    END IF;
    IF pg_catalog.jsonb_typeof(v_receipt->'quiescence_evidence') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_receipt->'quiescence_evidence')) IS DISTINCT FROM 4::bigint OR
       pg_catalog.jsonb_typeof(v_receipt->'quiescence_evidence'->'roles') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_receipt->'quiescence_evidence'->'roles') IS DISTINCT FROM 1 OR
       v_receipt->'quiescence_evidence'->>'restored_before_commit' IS DISTINCT FROM 'true' OR
       v_receipt->'quiescence_evidence'->>'observed_pre_namespace_sha256' IS NULL OR NOT (v_receipt->'quiescence_evidence'->>'observed_pre_namespace_sha256' ~ '^[0-9a-f]{64}$') OR
       v_receipt->'quiescence_evidence'->>'observed_post_namespace_sha256' IS NULL OR NOT (v_receipt->'quiescence_evidence'->>'observed_post_namespace_sha256' ~ '^[0-9a-f]{64}$') THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority quiescence evidence differs';
    END IF;
    v_role_evidence := v_receipt->'quiescence_evidence'->'roles'->0;
    v_at_rest := v_role_evidence->'observed_pre_state';
    v_temporary := v_at_rest || '{"login":false,"connection_limit":0}'::jsonb;
    IF pg_catalog.jsonb_typeof(v_role_evidence) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_role_evidence)) IS DISTINCT FROM 7::bigint OR
       v_role_evidence->>'principal' IS DISTINCT FROM 'harpy_migrator' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_at_rest)) IS DISTINCT FROM 11::bigint OR
       (v_at_rest-'password_state'::text) IS DISTINCT FROM '{"login":true,"inherit":false,"superuser":false,"createdb":false,"createrole":false,"replication":false,"bypassrls":false,"connection_limit":-1,"valid_until":"infinity","membership_count":1}'::jsonb OR
       v_at_rest->>'password_state' IS NULL OR v_at_rest->>'password_state' NOT IN ('null','scram_sha_256') OR
       v_role_evidence->'observed_temporary_state' IS DISTINCT FROM v_temporary OR
       v_role_evidence->'observed_post_state' IS DISTINCT FROM v_at_rest OR
       pg_catalog.jsonb_typeof(v_role_evidence->'terminated_session_count') IS DISTINCT FROM 'number' OR
       v_role_evidence->>'terminated_session_count' !~ '^[0-9]+$' OR
       (v_role_evidence->>'terminated_session_count')::numeric > 1000000 OR
       v_role_evidence->>'remaining_session_count' IS DISTINCT FROM '0' OR
       v_role_evidence->>'password_verifier_unchanged' IS DISTINCT FROM 'true' THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority quiesced role evidence differs';
    END IF;
    IF ((v_receipt->'authority_owner_role')-'owned_object_count'::text) IS DISTINCT FROM '{"login":false,"inherit":false,"superuser":false,"createdb":false,"createrole":false,"replication":false,"bypassrls":false,"connection_limit":-1,"password_state":"null","valid_until":"infinity","membership_count":0}'::jsonb OR
       v_receipt->'authority_owner_role'->>'owned_object_count' IS NULL OR NOT (v_receipt->'authority_owner_role'->>'owned_object_count' ~ '^[1-9][0-9]*$') OR
       (v_receipt->'authority_owner_role'->>'owned_object_count')::integer IS DISTINCT FROM v_inventory.object_count THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority owner receipt state differs';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
        JOIN pg_catalog.pg_auth_members AS membership ON membership.member=role.oid
        JOIN pg_catalog.pg_roles AS granted ON granted.oid=membership.roleid
        JOIN pg_catalog.pg_roles AS grantor ON grantor.oid=membership.grantor
        WHERE role.rolname='harpy_migrator' AND role.rolcanlogin AND NOT role.rolinherit
          AND NOT role.rolsuper AND NOT role.rolcreatedb AND NOT role.rolcreaterole
          AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=-1
          AND (role.rolvaliduntil IS NULL OR
               role.rolvaliduntil='infinity'::timestamptz)
          AND granted.rolname='harpy_owner'
          AND grantor.rolname=v_receipt->>'executor_session_user'
          AND NOT membership.admin_option AND NOT membership.inherit_option AND membership.set_option
          AND (SELECT pg_catalog.count(*) FROM pg_catalog.pg_auth_members AS all_membership
               WHERE all_membership.member=role.oid) = 1
          AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS child WHERE child.roleid=role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority migrator post-state differs';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
        WHERE role.rolname='harpy_cutover_authority_owner' AND NOT role.rolcanlogin
          AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
          AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls
          AND role.rolconnlimit=-1 AND role.rolvaliduntil IS NOT DISTINCT FROM 'infinity'::timestamptz
          AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
              WHERE membership.roleid=role.oid OR membership.member=role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority owner state differs';
    END IF;
    SELECT pg_catalog.count(DISTINCT pg_catalog.jsonb_build_array(item->>'kind',item->>'schema_name',
        item->>'object_name',item->>'identity_arguments',item->>'object_oid')) INTO v_count
    FROM pg_catalog.jsonb_array_elements(v_receipt->'objects') AS item;
    IF v_count IS DISTINCT FROM v_inventory.object_count::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority object inventory duplicates';
    END IF;
    SELECT pg_catalog.count(DISTINCT pg_catalog.jsonb_build_array(item->>'kind',item->>'schema_name',
        item->>'object_name',item->>'identity_arguments',item->>'object_oid')) INTO v_count
    FROM pg_catalog.jsonb_array_elements(v_receipt->'dependencies') AS item;
    IF v_count IS DISTINCT FROM v_inventory.dependency_count::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority dependency inventory duplicates';
    END IF;
    FOR v_item,v_protected IN
        SELECT value,true FROM pg_catalog.jsonb_array_elements(v_receipt->'objects')
        UNION ALL SELECT value,false FROM pg_catalog.jsonb_array_elements(v_receipt->'dependencies')
    LOOP
        IF pg_catalog.jsonb_typeof(v_item) IS DISTINCT FROM 'object' OR
           (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_item))
             IS DISTINCT FROM (CASE WHEN v_protected THEN 9::bigint ELSE 8::bigint END) OR
           pg_catalog.jsonb_typeof(v_item->'object_oid') IS DISTINCT FROM 'number' OR
           v_item->>'object_oid' IS NULL OR NOT (v_item->>'object_oid' ~ '^[1-9][0-9]*$') OR
           pg_catalog.jsonb_typeof(v_item->'kind') IS DISTINCT FROM 'string' OR
           pg_catalog.jsonb_typeof(v_item->'schema_name') IS DISTINCT FROM 'string' OR
           pg_catalog.jsonb_typeof(v_item->'object_name') IS DISTINCT FROM 'string' OR
           pg_catalog.jsonb_typeof(v_item->'identity_arguments') IS DISTINCT FROM 'string' OR
           pg_catalog.jsonb_typeof(v_item->'owner') IS DISTINCT FROM 'string' OR
           pg_catalog.jsonb_typeof(v_item->'definition_sha256') IS DISTINCT FROM 'string' OR
           pg_catalog.jsonb_typeof(v_item->'acl_sha256') IS DISTINCT FROM 'string' OR
           v_item->>'kind' NOT IN ('schema','table','function') OR
           (NOT v_protected AND v_item->>'kind'='function') OR
           (v_item->>'kind' IN ('schema','table') AND v_item->>'identity_arguments' IS DISTINCT FROM '') OR
           (v_item->>'kind'='schema' AND v_item->>'object_name' IS DISTINCT FROM v_item->>'schema_name') THEN
            RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority catalog item shape differs';
        END IF;
        v_oid := (v_item->>'object_oid')::oid;
        SELECT pg_catalog.count(*),pg_catalog.min(located.owner) INTO v_count,v_owner FROM (
            SELECT namespace.oid,pg_catalog.pg_get_userbyid(namespace.nspowner) AS owner
            FROM pg_catalog.pg_namespace AS namespace WHERE v_item->>'kind'='schema'
              AND namespace.nspname=v_item->>'schema_name' AND namespace.oid=v_oid
            UNION ALL SELECT relation.oid,pg_catalog.pg_get_userbyid(relation.relowner)
            FROM pg_catalog.pg_class AS relation JOIN pg_catalog.pg_namespace AS namespace
              ON namespace.oid=relation.relnamespace WHERE v_item->>'kind'='table'
              AND namespace.nspname=v_item->>'schema_name' AND relation.relname=v_item->>'object_name'
              AND relation.relkind IN ('r','p') AND relation.oid=v_oid
            UNION ALL SELECT procedure_row.oid,pg_catalog.pg_get_userbyid(procedure_row.proowner)
            FROM pg_catalog.pg_proc AS procedure_row JOIN pg_catalog.pg_namespace AS namespace
              ON namespace.oid=procedure_row.pronamespace WHERE v_item->>'kind'='function'
              AND namespace.nspname=v_item->>'schema_name' AND procedure_row.proname=v_item->>'object_name'
              AND pg_catalog.replace(pg_catalog.oidvectortypes(procedure_row.proargtypes),' ','')=v_item->>'identity_arguments'
              AND procedure_row.oid=v_oid
        ) AS located;
        SELECT cutover_authority.catalog_definition_sha256_v1(v_item->>'kind',v_oid),
               cutover_authority.catalog_acl_sha256_v1(v_item->>'kind',v_oid)
        INTO v_definition,v_acl;
        IF v_count IS DISTINCT FROM 1 OR v_owner IS DISTINCT FROM v_item->>'owner' OR
           v_definition IS DISTINCT FROM v_item->>'definition_sha256' OR
           v_acl IS DISTINCT FROM v_item->>'acl_sha256' THEN
            RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority catalog fingerprint differs';
        END IF;
    END LOOP;
    SELECT pg_catalog.count(*) INTO v_count FROM (
        SELECT namespace.oid FROM pg_catalog.pg_namespace AS namespace
        WHERE namespace.nspname='cutover_authority' AND pg_catalog.pg_get_userbyid(namespace.nspowner)='harpy_cutover_authority_owner'
        UNION ALL SELECT relation.oid FROM pg_catalog.pg_class AS relation JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid=relation.relnamespace
        WHERE namespace.nspname='cutover_authority' AND relation.relkind IN ('r','p') AND pg_catalog.pg_get_userbyid(relation.relowner)='harpy_cutover_authority_owner'
        UNION ALL SELECT procedure_row.oid FROM pg_catalog.pg_proc AS procedure_row JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid=procedure_row.pronamespace
        WHERE namespace.nspname='cutover_authority' AND pg_catalog.pg_get_userbyid(procedure_row.proowner)='harpy_cutover_authority_owner'
    ) AS live_object;
    IF v_count IS DISTINCT FROM v_inventory.object_count::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='authority live object set differs';
    END IF;
END;
$_$;


ALTER FUNCTION cutover_authority.assert_adopted_catalog_v1(p_receipt_sha256 text) OWNER TO harpy_owner;

--
-- Name: assert_completed_evidence_v1(uuid, uuid, bytea); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.assert_completed_evidence_v1(p_operation_id uuid, p_run_id uuid, p_terminal_evidence_document bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_terminal jsonb;
    v_invalid boolean;
BEGIN
    IF SESSION_USER NOT IN ('harpy_cluster_admin','harpy_cutover_finalizer') OR
       p_operation_id IS NULL OR p_run_id IS NULL OR p_terminal_evidence_document IS NULL OR
       pg_catalog.octet_length(p_terminal_evidence_document) NOT BETWEEN 2 AND 16777216 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover completion evidence input is invalid';
    END IF;
    v_terminal:=pg_catalog.convert_from(p_terminal_evidence_document,'UTF8')::jsonb;
    SELECT operation.* INTO STRICT v_operation FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    IF v_terminal->>'terminal_state' IS DISTINCT FROM 'completed' OR
       v_terminal->>'operation_id' IS DISTINCT FROM p_operation_id::text OR
       v_terminal->>'run_id' IS DISTINCT FROM p_run_id::text THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover completion evidence identity differs';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.cutover_initial_copy_receipts AS receipt
        WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id
          AND receipt.manifest_sha256=v_terminal->'initial_copy'->>'manifest_sha256'
          AND receipt.manifest_sha256=v_operation.lease_manifest_sha256
          AND receipt.snapshot_name=v_terminal->'initial_copy'->>'snapshot_name'
          AND receipt.snapshot_lsn=(v_terminal->'initial_copy'->>'snapshot_lsn')::pg_lsn
          AND receipt.relation_count=(v_terminal->'initial_copy'->>'relation_count')::integer
          AND receipt.partition_count=(v_terminal->'initial_copy'->>'partition_count')::integer
          AND receipt.row_count=(v_terminal->'initial_copy'->>'row_count')::bigint
          AND receipt.root_sha256=v_terminal->'initial_copy'->>'root_sha256') OR
       (SELECT pg_catalog.count(*) FROM platform.cutover_operation_relations AS relation
          WHERE relation.operation_id=p_operation_id AND relation.run_id=p_run_id)
            IS DISTINCT FROM (v_terminal->'initial_copy'->>'relation_count')::bigint OR
       (SELECT pg_catalog.count(*) FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key
          WHERE checkpoint_key.operation_id=p_operation_id AND checkpoint_key.run_id=p_run_id)
            IS DISTINCT FROM (v_terminal->'initial_copy'->>'partition_count')::bigint OR
       NOT EXISTS (SELECT 1 FROM platform.cutover_operation_relations AS relation
          WHERE relation.operation_id=p_operation_id AND relation.run_id=p_run_id
          HAVING pg_catalog.min(relation.ordinal)=1
             AND pg_catalog.max(relation.ordinal)=pg_catalog.count(*)
             AND pg_catalog.count(*)=(v_terminal->'initial_copy'->>'relation_count')::bigint) OR
       EXISTS ((SELECT relation.ordinal FROM platform.cutover_operation_relations AS relation
          WHERE relation.operation_id=p_operation_id AND relation.run_id=p_run_id)
          EXCEPT (SELECT DISTINCT (item->>'relation_ordinal')::smallint
             FROM pg_catalog.jsonb_array_elements(v_terminal->'checkpoints') AS item)) OR
       EXISTS ((SELECT DISTINCT (item->>'relation_ordinal')::smallint
             FROM pg_catalog.jsonb_array_elements(v_terminal->'checkpoints') AS item)
          EXCEPT (SELECT relation.ordinal FROM platform.cutover_operation_relations AS relation
             WHERE relation.operation_id=p_operation_id AND relation.run_id=p_run_id)) OR
       EXISTS ((SELECT checkpoint_key.relation_ordinal,checkpoint_key.checkpoint_key
          FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key
          WHERE checkpoint_key.operation_id=p_operation_id AND checkpoint_key.run_id=p_run_id)
          EXCEPT (SELECT (item->>'relation_ordinal')::smallint,item->>'checkpoint_key'
             FROM pg_catalog.jsonb_array_elements(v_terminal->'checkpoints') AS item)) OR
       EXISTS ((SELECT (item->>'relation_ordinal')::smallint,item->>'checkpoint_key'
             FROM pg_catalog.jsonb_array_elements(v_terminal->'checkpoints') AS item)
          EXCEPT (SELECT checkpoint_key.relation_ordinal,checkpoint_key.checkpoint_key
             FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key
             WHERE checkpoint_key.operation_id=p_operation_id AND checkpoint_key.run_id=p_run_id)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover completion checkpoint set differs';
    END IF;
    WITH checkpoint_evidence AS (
        SELECT (item->>'relation_ordinal')::smallint AS relation_ordinal,item->>'checkpoint_key' AS checkpoint_key,
            (item->>'applied_lsn')::pg_lsn AS applied_lsn,(item->>'applied_rows')::bigint AS applied_rows,
            (item->>'batch_count')::integer AS batch_count,item->>'batch_root_sha256' AS batch_root_sha256
        FROM pg_catalog.jsonb_array_elements(v_terminal->'checkpoints') AS item
    ), batch_leaf AS (
        SELECT batch.relation_ordinal,batch.checkpoint_key,batch.batch_ordinal,
          pg_catalog.octet_length(batch.batch_ordinal::text)::text||':'||batch.batch_ordinal::text||
          pg_catalog.octet_length(batch.source_xid::text)::text||':'||batch.source_xid::text||
          pg_catalog.octet_length(batch.source_commit_lsn::text)::text||':'||batch.source_commit_lsn::text||
          '64:'||batch.batch_sha256||pg_catalog.octet_length(batch.applied_count::text)::text||':'||batch.applied_count::text||
          '64:'||batch.key_state_sha256||'64:'||batch.state_sha256 AS leaf,
          batch.applied_count,batch.source_commit_lsn
        FROM platform.cutover_batch_receipts AS batch
        WHERE batch.operation_id=p_operation_id AND batch.run_id=p_run_id
    ), batch_summary AS (
        SELECT leaf.relation_ordinal,leaf.checkpoint_key,pg_catalog.count(*) AS batch_count,
          pg_catalog.sum(leaf.applied_count) AS applied_rows,pg_catalog.max(leaf.source_commit_lsn) AS applied_lsn,
          pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to('cutover-batch-root.v1'||pg_catalog.chr(10)||
            pg_catalog.string_agg(pg_catalog.octet_length(leaf.leaf)::text||':'||leaf.leaf,'' ORDER BY leaf.batch_ordinal),'UTF8')),'hex') AS batch_root_sha256
        FROM batch_leaf AS leaf GROUP BY leaf.relation_ordinal,leaf.checkpoint_key
    ) SELECT EXISTS (SELECT 1 FROM checkpoint_evidence AS terminal
        LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint ON checkpoint.operation_id=p_operation_id
          AND checkpoint.run_id=p_run_id AND checkpoint.relation_ordinal=terminal.relation_ordinal AND checkpoint.checkpoint_key=terminal.checkpoint_key
        LEFT JOIN batch_summary AS batch ON batch.relation_ordinal=terminal.relation_ordinal AND batch.checkpoint_key=terminal.checkpoint_key
        WHERE checkpoint.operation_id IS NULL OR checkpoint.state IS DISTINCT FROM 'complete' OR checkpoint.blocked_reason IS NOT NULL
          OR checkpoint.manifest_sha256 IS DISTINCT FROM v_operation.lease_manifest_sha256
          OR checkpoint.snapshot_name IS DISTINCT FROM v_terminal->'initial_copy'->>'snapshot_name'
          OR checkpoint.snapshot_lsn IS DISTINCT FROM (v_terminal->'initial_copy'->>'snapshot_lsn')::pg_lsn
          OR checkpoint.final_lsn IS DISTINCT FROM (v_terminal->>'final_lsn')::pg_lsn
          OR checkpoint.applied_lsn IS DISTINCT FROM terminal.applied_lsn OR checkpoint.applied_lsn<(v_terminal->>'final_lsn')::pg_lsn
          OR checkpoint.received_lsn<checkpoint.applied_lsn OR checkpoint.applied_rows IS DISTINCT FROM terminal.applied_rows
          OR checkpoint.attempt IS DISTINCT FROM terminal.batch_count OR batch.batch_count IS DISTINCT FROM terminal.batch_count::bigint
          OR batch.applied_rows IS DISTINCT FROM terminal.applied_rows OR batch.applied_lsn IS DISTINCT FROM terminal.applied_lsn
          OR batch.batch_root_sha256 IS DISTINCT FROM terminal.batch_root_sha256)
       OR EXISTS (SELECT 1 FROM platform.cutover_batch_receipts AS batch
          JOIN platform.cutover_copy_checkpoints AS checkpoint USING (operation_id,run_id,relation_ordinal,checkpoint_key)
          WHERE batch.operation_id=p_operation_id AND batch.run_id=p_run_id AND batch.applied_count=0
            AND (batch.source_commit_lsn IS DISTINCT FROM checkpoint.final_lsn OR batch.batch_ordinal IS DISTINCT FROM
              (SELECT pg_catalog.max(candidate.batch_ordinal) FROM platform.cutover_batch_receipts AS candidate
               WHERE candidate.operation_id=batch.operation_id AND candidate.run_id=batch.run_id
                 AND candidate.relation_ordinal=batch.relation_ordinal AND candidate.checkpoint_key=batch.checkpoint_key)))
       OR EXISTS (SELECT 1 FROM platform.cutover_batch_receipts AS batch
          WHERE batch.operation_id=p_operation_id AND batch.run_id=p_run_id AND batch.applied_count=0
          GROUP BY batch.relation_ordinal,batch.checkpoint_key HAVING pg_catalog.count(*)>1) INTO v_invalid;
    IF v_invalid THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover completion batch evidence differs';
    END IF;
    WITH change_leaf AS (
        SELECT receipt.source_xid,receipt.source_commit_lsn,receipt.relation_ordinal,receipt.change_ordinal,receipt.checkpoint_key,
          pg_catalog.octet_length(receipt.relation_ordinal::text)::text||':'||receipt.relation_ordinal::text||
          pg_catalog.octet_length(receipt.change_ordinal::text)::text||':'||receipt.change_ordinal::text||
          pg_catalog.octet_length(receipt.checkpoint_key)::text||':'||receipt.checkpoint_key||
          pg_catalog.octet_length(receipt.mutation_kind)::text||':'||receipt.mutation_kind||'64:'||receipt.mutation_sha256 AS leaf
        FROM platform.applied_change_receipts AS receipt WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id
    ), change_group AS (
        SELECT leaf.source_xid,pg_catalog.min(leaf.source_commit_lsn) AS source_commit_lsn,
          pg_catalog.count(*) AS change_count,pg_catalog.count(DISTINCT leaf.source_commit_lsn) AS commit_count,
          pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to('cutover-journal-changes-root.v1'||pg_catalog.chr(10)||
            pg_catalog.string_agg(pg_catalog.octet_length(leaf.leaf)::text||':'||leaf.leaf,'' ORDER BY leaf.relation_ordinal,leaf.change_ordinal,leaf.checkpoint_key),'UTF8')),'hex') AS changes_sha256
        FROM change_leaf AS leaf GROUP BY leaf.source_xid
    ), coverage_leaf AS (
        SELECT change.source_xid,change.source_commit_lsn,change.change_count,change.commit_count,
          pg_catalog.octet_length(change.source_xid::text)::text||':'||change.source_xid::text||
          pg_catalog.octet_length(change.source_commit_lsn::text)::text||':'||change.source_commit_lsn::text||
          pg_catalog.octet_length(change.change_count::text)::text||':'||change.change_count::text||'64:'||change.changes_sha256 AS leaf
        FROM change_group AS change
    ), coverage AS (
        SELECT pg_catalog.count(*) AS transaction_count,COALESCE(pg_catalog.sum(leaf.change_count),0) AS change_count,
          pg_catalog.max(leaf.commit_count) AS max_commit_count,
          pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to('cutover-journal-coverage-root.v1'||pg_catalog.chr(10)||
            COALESCE(pg_catalog.string_agg(pg_catalog.octet_length(leaf.leaf)::text||':'||leaf.leaf,'' ORDER BY leaf.source_xid),''),'UTF8')),'hex') AS root_sha256
        FROM coverage_leaf AS leaf
    ), delta_batch_group AS (
        SELECT batch.source_xid,pg_catalog.min(batch.source_commit_lsn) AS min_lsn,
          pg_catalog.max(batch.source_commit_lsn) AS max_lsn,pg_catalog.sum(batch.applied_count) AS applied_count
        FROM platform.cutover_batch_receipts AS batch WHERE batch.operation_id=p_operation_id AND batch.run_id=p_run_id
          AND EXISTS (SELECT 1 FROM platform.cutover_change_journal AS journal
            WHERE journal.operation_id=p_operation_id AND journal.run_id=p_run_id AND journal.source_xid=batch.source_xid)
        GROUP BY batch.source_xid
    ) SELECT EXISTS (SELECT 1 FROM platform.cutover_change_journal AS journal
          WHERE journal.operation_id=p_operation_id AND journal.run_id=p_run_id AND
            (journal.scope_kind IS DISTINCT FROM v_operation.scope_kind OR journal.scope_id IS DISTINCT FROM v_operation.scope_id
             OR journal.domain IS DISTINCT FROM v_operation.domain OR journal.cutover_generation IS DISTINCT FROM v_operation.cutover_generation))
       OR EXISTS ((SELECT journal.source_xid FROM platform.cutover_change_journal AS journal WHERE journal.operation_id=p_operation_id AND journal.run_id=p_run_id)
          EXCEPT (SELECT receipt.source_xid FROM platform.applied_change_receipts AS receipt WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id))
       OR EXISTS ((SELECT receipt.source_xid FROM platform.applied_change_receipts AS receipt WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id)
          EXCEPT (SELECT journal.source_xid FROM platform.cutover_change_journal AS journal WHERE journal.operation_id=p_operation_id AND journal.run_id=p_run_id))
       OR EXISTS (SELECT 1 FROM platform.applied_change_receipts AS receipt WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id
          AND (receipt.manifest_sha256 IS DISTINCT FROM v_operation.lease_manifest_sha256 OR receipt.source_commit_lsn>(v_terminal->>'final_lsn')::pg_lsn))
       OR EXISTS (SELECT 1 FROM platform.cutover_batch_receipts AS batch
          WHERE batch.operation_id=p_operation_id AND batch.run_id=p_run_id AND batch.applied_count>0
            AND NOT EXISTS (SELECT 1 FROM platform.cutover_change_journal AS journal
              WHERE journal.operation_id=p_operation_id AND journal.run_id=p_run_id AND journal.source_xid=batch.source_xid))
       OR EXISTS (SELECT 1 FROM coverage_leaf AS applied FULL JOIN delta_batch_group AS batch USING (source_xid)
          WHERE applied.change_count IS DISTINCT FROM batch.applied_count OR applied.commit_count IS DISTINCT FROM 1::bigint
             OR applied.source_commit_lsn IS DISTINCT FROM batch.min_lsn OR batch.min_lsn IS DISTINCT FROM batch.max_lsn)
       OR NOT EXISTS (SELECT 1 FROM coverage WHERE transaction_count=(v_terminal->>'journal_transaction_count')::bigint
          AND change_count=(v_terminal->>'applied_change_count')::bigint AND COALESCE(max_commit_count,1)=1
          AND root_sha256=v_terminal->>'journal_coverage_root_sha256') INTO v_invalid;
    IF v_invalid THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover journal coverage differs';
    END IF;
END;
$$;


ALTER FUNCTION cutover_authority.assert_completed_evidence_v1(p_operation_id uuid, p_run_id uuid, p_terminal_evidence_document bytea) OWNER TO harpy_owner;

--
-- Name: assert_tenant_completion_v1(uuid, uuid); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.assert_tenant_completion_v1(p_operation_id uuid, p_run_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_catalog platform.tenant_migration_requirement_catalogs%ROWTYPE;
    v_catalog_document jsonb;
    v_requirements jsonb;
    v_targets jsonb;
    v_live_targets jsonb;
    v_release_run_id uuid;
    v_database_origin text;
BEGIN
    IF SESSION_USER NOT IN ('harpy_cluster_admin','harpy_cutover_finalizer') OR
       p_operation_id IS NULL OR p_run_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover tenant completion input is invalid';
    END IF;
    SELECT operation.* INTO STRICT v_operation FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id AND operation.state='quiescing';
    SELECT release_row.migration_run_id,release_row.database_origin INTO STRICT v_release_run_id,v_database_origin
    FROM platform.release_generations AS release_row JOIN platform.schema_contracts AS contract_row
      ON contract_row.component='core' AND contract_row.verified_run_id=release_row.migration_run_id
     AND contract_row.database_generation=release_row.database_generation
     AND contract_row.minimum_runtime_generation=release_row.minimum_runtime_generation
     AND contract_row.migration_manifest_sha256=release_row.migration_manifest_sha256
     AND contract_row.extension_manifest_sha256=release_row.extension_manifest_sha256 AND contract_row.status='ready'
    WHERE release_row.release_id=v_operation.release_id AND release_row.environment_id=v_operation.environment_id;
    SELECT catalog.* INTO STRICT v_catalog FROM platform.tenant_migration_requirement_catalogs AS catalog
    WHERE catalog.migration_run_id=v_release_run_id AND catalog.release_id=v_operation.release_id
      AND catalog.environment_id=v_operation.environment_id AND catalog.database_origin=v_database_origin;
    v_catalog_document:=pg_catalog.convert_from(v_catalog.canonical_document,'UTF8')::jsonb;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordinal',requirement.ordinal,
      'owner',requirement.owner,'logical_version',requirement.logical_version,'database_origin',requirement.database_origin,
      'selected_path',requirement.selected_path,'selected_sha256',requirement.selected_sha256) ORDER BY requirement.ordinal),'[]'::jsonb)
    INTO v_requirements FROM platform.tenant_migration_requirements AS requirement WHERE requirement.migration_run_id=v_release_run_id;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordinal',target.ordinal,
      'tenant_id',target.tenant_id::text,'schema_name',target.schema_name) ORDER BY target.ordinal),'[]'::jsonb)
    INTO v_targets FROM platform.tenant_migration_requirement_targets AS target WHERE target.migration_run_id=v_release_run_id;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordinal',live.ordinal,
      'tenant_id',live.tenant_id,'schema_name',live.schema_name) ORDER BY live.ordinal),'[]'::jsonb)
    INTO v_live_targets FROM (SELECT pg_catalog.row_number() OVER (ORDER BY tenant.id) AS ordinal,
      tenant.id::text AS tenant_id,tenant.schema_name FROM platform.tenants AS tenant WHERE tenant.deleted_at IS NULL) AS live;
    IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_catalog_document)) IS DISTINCT FROM 8::bigint OR
       (v_catalog_document ?& ARRAY['contract_version','migration_run_id','release_id','environment_id','database_origin','migration_manifest_sha256','requirements','targets']) IS DISTINCT FROM true OR
       v_catalog_document->>'contract_version' IS DISTINCT FROM 'tenant-migration-requirement-catalog.v2' OR
       v_catalog_document->>'migration_run_id' IS DISTINCT FROM v_release_run_id::text OR
       v_catalog_document->>'release_id' IS DISTINCT FROM v_operation.release_id::text OR
       v_catalog_document->>'environment_id' IS DISTINCT FROM v_operation.environment_id::text OR
       v_catalog_document->>'database_origin' IS DISTINCT FROM v_database_origin OR
       v_catalog_document->>'migration_manifest_sha256' IS DISTINCT FROM v_catalog.migration_manifest_sha256 OR
       v_catalog_document->'requirements' IS DISTINCT FROM v_requirements OR v_catalog_document->'targets' IS DISTINCT FROM v_targets OR
       v_targets IS DISTINCT FROM v_live_targets OR pg_catalog.jsonb_array_length(v_requirements) IS DISTINCT FROM v_catalog.requirement_count OR
       pg_catalog.jsonb_array_length(v_targets) IS DISTINCT FROM v_catalog.target_count OR
       EXISTS (SELECT 1 FROM platform.tenant_migration_requirement_targets AS target
          CROSS JOIN platform.tenant_migration_requirements AS requirement
          WHERE target.migration_run_id=v_release_run_id AND requirement.migration_run_id=v_release_run_id
            AND NOT EXISTS (SELECT 1 FROM platform.tenant_migration_checkpoints AS checkpoint
              WHERE checkpoint.tenant_id=target.tenant_id AND checkpoint.owner=requirement.owner
                AND checkpoint.logical_version=requirement.logical_version AND checkpoint.database_origin=requirement.database_origin
                AND checkpoint.selected_path=requirement.selected_path AND checkpoint.selected_sha256=requirement.selected_sha256
                AND checkpoint.state='succeeded')) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover tenant completion authority differs';
    END IF;
END;
$$;


ALTER FUNCTION cutover_authority.assert_tenant_completion_v1(p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: assert_terminal_evidence_v1(uuid, uuid, text, bytea); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.assert_terminal_evidence_v1(p_operation_id uuid, p_run_id uuid, p_terminal_state text, p_terminal_evidence_document bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_terminal jsonb;
BEGIN
    IF SESSION_USER NOT IN ('harpy_cluster_admin','harpy_cutover_finalizer') OR
       p_operation_id IS NULL OR p_run_id IS NULL OR p_terminal_state NOT IN ('completed','failed','cancelled') OR
       p_terminal_evidence_document IS NULL OR pg_catalog.octet_length(p_terminal_evidence_document) NOT BETWEEN 2 AND 16777216 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover terminal evidence input is invalid';
    END IF;
    v_terminal:=pg_catalog.convert_from(p_terminal_evidence_document,'UTF8')::jsonb;
    SELECT operation.* INTO STRICT v_operation FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    IF pg_catalog.jsonb_typeof(v_terminal) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_terminal)) IS DISTINCT FROM
         (CASE WHEN p_terminal_state='completed' THEN 14::bigint ELSE 9::bigint END) OR
       (v_terminal ?& ARRAY['contract_version','operation_id','run_id','lease_manifest_sha256','plan_sha256','transform_manifest_sha256','terminal_state']) IS DISTINCT FROM true OR
       pg_catalog.jsonb_typeof(v_terminal->'contract_version') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_terminal->'operation_id') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_terminal->'run_id') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_terminal->'lease_manifest_sha256') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_terminal->'plan_sha256') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_terminal->'transform_manifest_sha256') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_terminal->'terminal_state') IS DISTINCT FROM 'string' OR
       v_terminal->>'contract_version' IS DISTINCT FROM 'cutover-terminal-evidence.v1' OR
       v_terminal->>'operation_id' IS DISTINCT FROM p_operation_id::text OR
       v_terminal->>'run_id' IS DISTINCT FROM p_run_id::text OR
       v_terminal->>'lease_manifest_sha256' IS DISTINCT FROM v_operation.lease_manifest_sha256 OR
       v_terminal->>'plan_sha256' IS DISTINCT FROM v_operation.plan_sha256 OR
       v_terminal->>'transform_manifest_sha256' IS DISTINCT FROM v_operation.transform_manifest_sha256 OR
       v_terminal->>'terminal_state' IS DISTINCT FROM p_terminal_state OR
       (p_terminal_state='completed' AND v_operation.state IS DISTINCT FROM 'quiescing') OR
       (p_terminal_state IN ('failed','cancelled') AND v_operation.state NOT IN ('planned','copying','shadow','quiescing','blocked')) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover terminal evidence identity differs';
    END IF;
    IF p_terminal_state IN ('failed','cancelled') THEN
        IF (v_terminal ?& ARRAY['outcome_code','outcome_evidence_sha256']) IS DISTINCT FROM true OR
           pg_catalog.jsonb_typeof(v_terminal->'outcome_code') IS DISTINCT FROM 'string' OR
           pg_catalog.jsonb_typeof(v_terminal->'outcome_evidence_sha256') IS DISTINCT FROM 'string' OR
           v_terminal->>'outcome_evidence_sha256'!~'^[0-9a-f]{64}$' OR
           (p_terminal_state='failed' AND NOT (v_terminal->>'outcome_code'=ANY
             (ARRAY['source_failed','target_failed','verification_failed','lease_expired']::text[]))) OR
           (p_terminal_state='cancelled' AND NOT (v_terminal->>'outcome_code'=ANY
             (ARRAY['operator_cancelled','superseded']::text[]))) THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover abort evidence differs';
        END IF;
        RETURN;
    END IF;
    IF (v_terminal ?& ARRAY['final_lsn','initial_copy','checkpoint_count','checkpoints','journal_transaction_count','applied_change_count','journal_coverage_root_sha256']) IS DISTINCT FROM true OR
       pg_catalog.jsonb_typeof(v_terminal->'final_lsn') IS DISTINCT FROM 'string' OR
       (v_terminal->>'final_lsn')::pg_lsn::text IS DISTINCT FROM v_terminal->>'final_lsn' OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_terminal->'initial_copy')) IS DISTINCT FROM 7::bigint OR
       (v_terminal->'initial_copy' ?& ARRAY['manifest_sha256','snapshot_name','snapshot_lsn','relation_count','partition_count','row_count','root_sha256']) IS DISTINCT FROM true OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy'->'manifest_sha256') IS DISTINCT FROM 'string' OR
       v_terminal->'initial_copy'->>'manifest_sha256' IS DISTINCT FROM v_operation.lease_manifest_sha256 OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy'->'snapshot_name') IS DISTINCT FROM 'string' OR
       v_terminal->'initial_copy'->>'snapshot_name'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy'->'snapshot_lsn') IS DISTINCT FROM 'string' OR
       (v_terminal->'initial_copy'->>'snapshot_lsn')::pg_lsn::text IS DISTINCT FROM v_terminal->'initial_copy'->>'snapshot_lsn' OR
       (v_terminal->'initial_copy'->>'snapshot_lsn')::pg_lsn>(v_terminal->>'final_lsn')::pg_lsn OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy'->'relation_count') IS DISTINCT FROM 'number' OR
       v_terminal->'initial_copy'->>'relation_count'!~'^[1-9][0-9]*$' OR
       (v_terminal->'initial_copy'->>'relation_count')::integer NOT BETWEEN 1 AND 4096 OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy'->'partition_count') IS DISTINCT FROM 'number' OR
       v_terminal->'initial_copy'->>'partition_count'!~'^[1-9][0-9]*$' OR
       (v_terminal->'initial_copy'->>'partition_count')::integer NOT BETWEEN
         (v_terminal->'initial_copy'->>'relation_count')::integer AND 10000 OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy'->'row_count') IS DISTINCT FROM 'number' OR
       v_terminal->'initial_copy'->>'row_count'!~'^[0-9]+$' OR
       (v_terminal->'initial_copy'->>'row_count')::numeric>9007199254740991 OR
       pg_catalog.jsonb_typeof(v_terminal->'initial_copy'->'root_sha256') IS DISTINCT FROM 'string' OR
       v_terminal->'initial_copy'->>'root_sha256'!~'^[0-9a-f]{64}$' OR
       pg_catalog.jsonb_typeof(v_terminal->'checkpoint_count') IS DISTINCT FROM 'number' OR
       v_terminal->>'checkpoint_count'!~'^[1-9][0-9]*$' OR
       (v_terminal->>'checkpoint_count')::integer NOT BETWEEN 1 AND 10000 OR
       pg_catalog.jsonb_typeof(v_terminal->'checkpoints') IS DISTINCT FROM 'array' OR
       (v_terminal->>'checkpoint_count')::integer IS DISTINCT FROM pg_catalog.jsonb_array_length(v_terminal->'checkpoints') OR
       (v_terminal->>'checkpoint_count')::integer IS DISTINCT FROM (v_terminal->'initial_copy'->>'partition_count')::integer OR
       pg_catalog.jsonb_typeof(v_terminal->'journal_transaction_count') IS DISTINCT FROM 'number' OR
       v_terminal->>'journal_transaction_count'!~'^[0-9]+$' OR
       (v_terminal->>'journal_transaction_count')::numeric>9007199254740991 OR
       pg_catalog.jsonb_typeof(v_terminal->'applied_change_count') IS DISTINCT FROM 'number' OR
       v_terminal->>'applied_change_count'!~'^[0-9]+$' OR
       (v_terminal->>'applied_change_count')::numeric>9007199254740991 OR
       ((v_terminal->>'journal_transaction_count')::numeric=0) IS DISTINCT FROM
         ((v_terminal->>'applied_change_count')::numeric=0) OR
       pg_catalog.jsonb_typeof(v_terminal->'journal_coverage_root_sha256') IS DISTINCT FROM 'string' OR
       v_terminal->>'journal_coverage_root_sha256'!~'^[0-9a-f]{64}$' OR
       EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(v_terminal->'checkpoints') AS item
          WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'object'
             OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(item)) IS DISTINCT FROM 6::bigint
             OR (item ?& ARRAY['relation_ordinal','checkpoint_key','applied_lsn','applied_rows','batch_count','batch_root_sha256']) IS DISTINCT FROM true
             OR pg_catalog.jsonb_typeof(item->'relation_ordinal') IS DISTINCT FROM 'number'
             OR item->>'relation_ordinal'!~'^[1-9][0-9]*$' OR (item->>'relation_ordinal')::integer NOT BETWEEN 1 AND 4096
             OR pg_catalog.jsonb_typeof(item->'checkpoint_key') IS DISTINCT FROM 'string'
             OR pg_catalog.octet_length(item->>'checkpoint_key') NOT BETWEEN 1 AND 512 OR item->>'checkpoint_key'~'[[:cntrl:]]'
             OR pg_catalog.jsonb_typeof(item->'applied_lsn') IS DISTINCT FROM 'string'
             OR (item->>'applied_lsn')::pg_lsn::text IS DISTINCT FROM item->>'applied_lsn'
             OR (item->>'applied_lsn')::pg_lsn<(v_terminal->>'final_lsn')::pg_lsn
             OR pg_catalog.jsonb_typeof(item->'applied_rows') IS DISTINCT FROM 'number'
             OR item->>'applied_rows'!~'^[0-9]+$' OR (item->>'applied_rows')::numeric>9007199254740991
             OR pg_catalog.jsonb_typeof(item->'batch_count') IS DISTINCT FROM 'number'
             OR item->>'batch_count'!~'^[1-9][0-9]*$' OR (item->>'batch_count')::numeric>2147483647
             OR pg_catalog.jsonb_typeof(item->'batch_root_sha256') IS DISTINCT FROM 'string'
             OR item->>'batch_root_sha256'!~'^[0-9a-f]{64}$') OR
       EXISTS (SELECT 1 FROM (SELECT item->>'relation_ordinal' AS relation_ordinal,item->>'checkpoint_key' AS checkpoint_key,
          pg_catalog.lag(item->>'relation_ordinal') OVER (ORDER BY item_ordinal) AS prior_relation_ordinal,
          pg_catalog.lag(item->>'checkpoint_key') OVER (ORDER BY item_ordinal) AS prior_checkpoint_key,item_ordinal
          FROM pg_catalog.jsonb_array_elements(v_terminal->'checkpoints') WITH ORDINALITY AS value(item,item_ordinal)) AS ordered
          WHERE ordered.item_ordinal>1 AND ((ordered.relation_ordinal)::integer<(ordered.prior_relation_ordinal)::integer
             OR ((ordered.relation_ordinal)::integer=(ordered.prior_relation_ordinal)::integer
                AND ordered.checkpoint_key<=ordered.prior_checkpoint_key))) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover completion evidence shape differs';
    END IF;
    PERFORM cutover_authority.assert_completed_evidence_v1(p_operation_id,p_run_id,p_terminal_evidence_document);
    PERFORM cutover_authority.assert_tenant_completion_v1(p_operation_id,p_run_id);
END;
$_$;


ALTER FUNCTION cutover_authority.assert_terminal_evidence_v1(p_operation_id uuid, p_run_id uuid, p_terminal_state text, p_terminal_evidence_document bytea) OWNER TO harpy_owner;

--
-- Name: authorize_finalization_v1(uuid, uuid, uuid, text, bytea, text, bytea, text, bytea, text, bytea, text, bytea, text, text, bytea); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.authorize_finalization_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_finalizer jsonb;
    v_state_sha256 text;
    v_finalizer_expires_at timestamptz;
    v_authorizer_valid_until timestamptz;
BEGIN
    IF SESSION_USER <> 'harpy_cluster_admin' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='cutover finalization authorizer denied';
    END IF;
    PERFORM cutover_authority.validate_finalization_envelope_v1(
        p_operation_id,p_run_id,p_finalizer_lease_id,p_finalizer_lease_sha256,p_finalizer_lease_document,
        p_adoption_lease_sha256,p_adoption_lease_document,p_seal_receipt_sha256,p_seal_receipt_document,
        p_cleanup_receipt_sha256,p_cleanup_receipt_document,p_authority_receipt_sha256,p_authority_receipt_document,
        p_terminal_state,p_terminal_evidence_sha256,p_terminal_evidence_document);
    PERFORM 1 FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM cutover_authority.finalization_receipts AS receipt
        WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover operation is already finalized';
    END IF;
    IF EXISTS (SELECT 1 FROM cutover_authority.finalization_authorizations AS authorization_row
        WHERE authorization_row.operation_id=p_operation_id AND authorization_row.run_id=p_run_id
          AND authorization_row.finalizer_lease_id<>p_finalizer_lease_id
          AND authorization_row.finalizer_expires_at>pg_catalog.clock_timestamp()) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover finalization authorization attempt is active';
    END IF;
    v_finalizer:=pg_catalog.convert_from(p_finalizer_lease_document,'UTF8')::jsonb;
    v_finalizer_expires_at:=(v_finalizer->>'expires_at')::timestamptz;
    SELECT role.rolvaliduntil INTO STRICT v_authorizer_valid_until FROM pg_catalog.pg_roles AS role
    WHERE role.rolname='harpy_cluster_admin' AND role.rolcanlogin AND NOT role.rolinherit
      AND NOT role.rolsuper AND role.rolcreatedb AND role.rolcreaterole AND NOT role.rolreplication
      AND NOT role.rolbypassrls AND role.rolconnlimit=1 AND role.rolvaliduntil>pg_catalog.clock_timestamp()
      AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
          WHERE membership.roleid=role.oid OR membership.member=role.oid);
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
        WHERE role.rolname='harpy_cutover_finalizer' AND role.rolcanlogin AND NOT role.rolinherit
          AND NOT role.rolsuper AND NOT role.rolcreatedb AND NOT role.rolcreaterole
          AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=1
          AND role.rolvaliduntil IS NOT DISTINCT FROM v_finalizer_expires_at
          AND role.rolvaliduntil>pg_catalog.clock_timestamp()
          AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
              WHERE membership.roleid=role.oid OR membership.member=role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover finalizer role lease is not active';
    END IF;
    v_state_sha256:=cutover_authority.finalization_state_sha256_v1(p_operation_id,p_run_id);
    IF v_state_sha256 IS DISTINCT FROM v_finalizer->>'finalization_state_sha256' OR
       v_finalizer_expires_at<=pg_catalog.clock_timestamp() OR
       v_finalizer_expires_at>v_authorizer_valid_until THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover finalization authorization state changed';
    END IF;
    INSERT INTO cutover_authority.finalization_authorizations (
        operation_id,run_id,finalizer_lease_id,finalizer_lease_sha256,finalizer_lease_document,
        adoption_lease_sha256,adoption_lease_document,seal_receipt_sha256,seal_receipt_document,
        cleanup_receipt_sha256,cleanup_receipt_document,authority_receipt_sha256,authority_receipt_document,
        terminal_state,terminal_evidence_sha256,terminal_evidence_document,finalization_state_sha256,
        finalizer_expires_at,authorizer_valid_until)
    VALUES (p_operation_id,p_run_id,p_finalizer_lease_id,p_finalizer_lease_sha256,p_finalizer_lease_document,
        p_adoption_lease_sha256,p_adoption_lease_document,p_seal_receipt_sha256,p_seal_receipt_document,
        p_cleanup_receipt_sha256,p_cleanup_receipt_document,p_authority_receipt_sha256,p_authority_receipt_document,
        p_terminal_state,p_terminal_evidence_sha256,p_terminal_evidence_document,v_state_sha256,
        v_finalizer_expires_at,v_authorizer_valid_until)
    ON CONFLICT DO NOTHING;
    IF NOT FOUND AND NOT EXISTS (SELECT 1 FROM cutover_authority.finalization_authorizations AS authorization_row
        WHERE authorization_row.operation_id=p_operation_id AND authorization_row.run_id=p_run_id
          AND authorization_row.finalizer_lease_id=p_finalizer_lease_id
          AND authorization_row.finalizer_lease_sha256=p_finalizer_lease_sha256
          AND authorization_row.finalizer_lease_document=p_finalizer_lease_document
          AND authorization_row.adoption_lease_sha256=p_adoption_lease_sha256
          AND authorization_row.adoption_lease_document=p_adoption_lease_document
          AND authorization_row.seal_receipt_sha256=p_seal_receipt_sha256
          AND authorization_row.seal_receipt_document=p_seal_receipt_document
          AND authorization_row.cleanup_receipt_sha256=p_cleanup_receipt_sha256
          AND authorization_row.cleanup_receipt_document=p_cleanup_receipt_document
          AND authorization_row.authority_receipt_sha256=p_authority_receipt_sha256
          AND authorization_row.authority_receipt_document=p_authority_receipt_document
          AND authorization_row.terminal_state=p_terminal_state
          AND authorization_row.terminal_evidence_sha256=p_terminal_evidence_sha256
          AND authorization_row.terminal_evidence_document=p_terminal_evidence_document
          AND authorization_row.finalization_state_sha256=v_state_sha256
          AND authorization_row.finalizer_expires_at=v_finalizer_expires_at
          AND authorization_row.authorizer_valid_until=v_authorizer_valid_until) THEN
        RAISE EXCEPTION USING ERRCODE='22000', MESSAGE='cutover finalization authorization replay differs';
    END IF;
END;
$$;


ALTER FUNCTION cutover_authority.authorize_finalization_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) OWNER TO harpy_owner;

--
-- Name: catalog_acl_sha256_v1(text, oid); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.catalog_acl_sha256_v1(p_kind text, p_object_oid oid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_located_count integer;
BEGIN
    IF p_kind IS NULL OR p_kind NOT IN ('schema','table','function') OR
       p_object_oid IS NULL OR p_object_oid = 0 THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'catalog ACL identity is invalid';
    END IF;
    SELECT pg_catalog.count(*) INTO v_located_count FROM (
        SELECT namespace.oid FROM pg_catalog.pg_namespace AS namespace
        WHERE p_kind = 'schema' AND namespace.oid = p_object_oid
        UNION ALL
        SELECT relation.oid FROM pg_catalog.pg_class AS relation
        WHERE p_kind = 'table' AND relation.oid = p_object_oid
          AND relation.relkind IN ('r','p')
        UNION ALL
        SELECT procedure_row.oid FROM pg_catalog.pg_proc AS procedure_row
        WHERE p_kind = 'function' AND procedure_row.oid = p_object_oid
    ) AS located;
    IF v_located_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'catalog ACL object is absent';
    END IF;
RETURN (SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object(
        'namespace', COALESCE((SELECT pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'grantor', pg_catalog.pg_get_userbyid(entry.grantor),
                'grantee', CASE WHEN entry.grantee = 0 THEN 'PUBLIC'
                    ELSE pg_catalog.pg_get_userbyid(entry.grantee) END,
                'privilege', entry.privilege_type,
                'grantable', entry.is_grantable)
            ORDER BY CASE WHEN entry.grantee = 0 THEN 'PUBLIC'
                         ELSE pg_catalog.pg_get_userbyid(entry.grantee) END,
                     pg_catalog.pg_get_userbyid(entry.grantor),
                     entry.privilege_type, entry.is_grantable)
            FROM pg_catalog.pg_namespace AS namespace
            CROSS JOIN pg_catalog.aclexplode(COALESCE(namespace.nspacl,
                pg_catalog.acldefault('n', namespace.nspowner))) AS entry
            WHERE p_kind = 'schema' AND namespace.oid = p_object_oid), '[]'::jsonb),
        'relation', COALESCE((SELECT pg_catalog.jsonb_build_object(
            'table', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'grantor', pg_catalog.pg_get_userbyid(entry.grantor),
                    'grantee', CASE WHEN entry.grantee = 0 THEN 'PUBLIC'
                        ELSE pg_catalog.pg_get_userbyid(entry.grantee) END,
                    'privilege', entry.privilege_type, 'grantable', entry.is_grantable)
                ORDER BY CASE WHEN entry.grantee = 0 THEN 'PUBLIC'
                             ELSE pg_catalog.pg_get_userbyid(entry.grantee) END,
                         pg_catalog.pg_get_userbyid(entry.grantor),
                         entry.privilege_type, entry.is_grantable)
                FROM pg_catalog.aclexplode(COALESCE(relation.relacl,
                    pg_catalog.acldefault('r'::"char", relation.relowner))) AS entry), '[]'::jsonb),
            'columns', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'number', attribute.attnum, 'name', attribute.attname,
                    'acl', COALESCE((SELECT pg_catalog.jsonb_agg(
                        pg_catalog.jsonb_build_object(
                            'grantor', pg_catalog.pg_get_userbyid(column_entry.grantor),
                            'grantee', CASE WHEN column_entry.grantee = 0 THEN 'PUBLIC'
                                ELSE pg_catalog.pg_get_userbyid(column_entry.grantee) END,
                            'privilege', column_entry.privilege_type,
                            'grantable', column_entry.is_grantable)
                        ORDER BY CASE WHEN column_entry.grantee = 0 THEN 'PUBLIC'
                                     ELSE pg_catalog.pg_get_userbyid(column_entry.grantee) END,
                            pg_catalog.pg_get_userbyid(column_entry.grantor),
                            column_entry.privilege_type, column_entry.is_grantable)
                        FROM pg_catalog.aclexplode(attribute.attacl) AS column_entry), '[]'::jsonb))
                ORDER BY attribute.attnum) FROM pg_catalog.pg_attribute AS attribute
                WHERE attribute.attrelid = relation.oid AND attribute.attnum > 0
                  AND NOT attribute.attisdropped), '[]'::jsonb))
            FROM pg_catalog.pg_class AS relation
            WHERE p_kind = 'table' AND relation.oid = p_object_oid), '{}'::jsonb),
        'routine', COALESCE((SELECT pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'grantor', pg_catalog.pg_get_userbyid(entry.grantor),
                'grantee', CASE WHEN entry.grantee = 0 THEN 'PUBLIC'
                    ELSE pg_catalog.pg_get_userbyid(entry.grantee) END,
                'privilege', entry.privilege_type,
                'grantable', entry.is_grantable)
            ORDER BY CASE WHEN entry.grantee = 0 THEN 'PUBLIC'
                         ELSE pg_catalog.pg_get_userbyid(entry.grantee) END,
                     pg_catalog.pg_get_userbyid(entry.grantor),
                     entry.privilege_type, entry.is_grantable)
            FROM pg_catalog.pg_proc AS procedure_row
            CROSS JOIN pg_catalog.aclexplode(COALESCE(procedure_row.proacl,
                pg_catalog.acldefault('f', procedure_row.proowner))) AS entry
            WHERE p_kind = 'function' AND procedure_row.oid = p_object_oid), '[]'::jsonb)
    )::text, 'UTF8')), 'hex'));
END;
$$;


ALTER FUNCTION cutover_authority.catalog_acl_sha256_v1(p_kind text, p_object_oid oid) OWNER TO harpy_owner;

--
-- Name: catalog_definition_sha256_v1(text, oid); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.catalog_definition_sha256_v1(p_kind text, p_object_oid oid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_located_count integer;
BEGIN
    IF p_kind IS NULL OR p_kind NOT IN ('schema','table','function') OR
       p_object_oid IS NULL OR p_object_oid = 0 THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'catalog definition identity is invalid';
    END IF;
    SELECT pg_catalog.count(*) INTO v_located_count FROM (
        SELECT namespace.oid FROM pg_catalog.pg_namespace AS namespace
        WHERE p_kind = 'schema' AND namespace.oid = p_object_oid
        UNION ALL
        SELECT relation.oid FROM pg_catalog.pg_class AS relation
        WHERE p_kind = 'table' AND relation.oid = p_object_oid
          AND relation.relkind IN ('r','p')
        UNION ALL
        SELECT procedure_row.oid FROM pg_catalog.pg_proc AS procedure_row
        WHERE p_kind = 'function' AND procedure_row.oid = p_object_oid
    ) AS located;
    IF v_located_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'catalog definition object is absent';
    END IF;
RETURN (SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
    pg_catalog.jsonb_build_object(
        'namespace', (SELECT pg_catalog.jsonb_build_object('name', namespace.nspname)
            FROM pg_catalog.pg_namespace AS namespace
            WHERE p_kind = 'schema' AND namespace.oid = p_object_oid),
        'relation', (SELECT pg_catalog.jsonb_build_object(
            'schema', namespace.nspname, 'name', relation.relname,
            'kind', relation.relkind, 'persistence', relation.relpersistence,
            'replica_identity', relation.relreplident,
            'access_method', access_method.amname, 'tablespace', tablespace.spcname,
            'options', COALESCE((SELECT pg_catalog.jsonb_agg(option_row ORDER BY option_row)
                FROM pg_catalog.unnest(relation.reloptions) AS option_row), '[]'::jsonb),
            'is_partition', relation.relispartition,
            'partition_key', pg_catalog.pg_get_partkeydef(relation.oid),
            'partition_bound', pg_catalog.pg_get_expr(relation.relpartbound, relation.oid),
            'row_security', relation.relrowsecurity,
            'force_row_security', relation.relforcerowsecurity,
            'columns', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'number', attribute.attnum, 'name', attribute.attname,
                    'type', pg_catalog.format_type(attribute.atttypid, attribute.atttypmod),
                    'not_null', attribute.attnotnull, 'identity', attribute.attidentity,
                    'generated', attribute.attgenerated, 'storage', attribute.attstorage,
                    'compression', attribute.attcompression,
                    'default', pg_catalog.pg_get_expr(attribute_default.adbin, attribute_default.adrelid),
                    'collation', CASE WHEN collation_row.oid IS NULL THEN NULL ELSE
                        pg_catalog.jsonb_build_object(
                            'schema', collation_namespace.nspname, 'name', collation_row.collname,
                            'provider', collation_row.collprovider,
                            'deterministic', collation_row.collisdeterministic,
                            'collate', collation_row.collcollate, 'ctype', collation_row.collctype,
                            'locale', collation_row.colllocale,
                            'icu_rules', collation_row.collicurules,
                            'version', collation_row.collversion) END) ORDER BY attribute.attnum)
                FROM pg_catalog.pg_attribute AS attribute
                LEFT JOIN pg_catalog.pg_attrdef AS attribute_default
                  ON attribute_default.adrelid = attribute.attrelid
                 AND attribute_default.adnum = attribute.attnum
                LEFT JOIN pg_catalog.pg_collation AS collation_row
                  ON collation_row.oid = attribute.attcollation
                LEFT JOIN pg_catalog.pg_namespace AS collation_namespace
                  ON collation_namespace.oid = collation_row.collnamespace
                WHERE attribute.attrelid = relation.oid AND attribute.attnum > 0
                  AND NOT attribute.attisdropped), '[]'::jsonb),
            'constraints', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'name', constraint_row.conname, 'type', constraint_row.contype,
                    'deferrable', constraint_row.condeferrable,
                    'deferred', constraint_row.condeferred,
                    'validated', constraint_row.convalidated,
                    'definition', pg_catalog.pg_get_constraintdef(constraint_row.oid, false))
                ORDER BY constraint_row.conname)
                FROM pg_catalog.pg_constraint AS constraint_row
                WHERE constraint_row.conrelid = relation.oid), '[]'::jsonb),
            'indexes', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'name', index_relation.relname,
                    'definition', pg_catalog.pg_get_indexdef(index_row.indexrelid),
                    'unique', index_row.indisunique, 'primary', index_row.indisprimary,
                    'exclusion', index_row.indisexclusion, 'immediate', index_row.indimmediate,
                    'clustered', index_row.indisclustered, 'valid', index_row.indisvalid,
                    'check_xmin', index_row.indcheckxmin, 'ready', index_row.indisready,
                    'live', index_row.indislive, 'replica_identity', index_row.indisreplident)
                ORDER BY index_relation.relname, pg_catalog.pg_get_indexdef(index_row.indexrelid))
                FROM pg_catalog.pg_index AS index_row
                JOIN pg_catalog.pg_class AS index_relation
                  ON index_relation.oid = index_row.indexrelid
                WHERE index_row.indrelid = relation.oid), '[]'::jsonb),
            'triggers', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object(
                    'name', trigger_row.tgname, 'enabled', trigger_row.tgenabled,
                    'definition', pg_catalog.pg_get_triggerdef(trigger_row.oid, false),
                    'function_schema', trigger_function_namespace.nspname,
                    'function_name', trigger_function.proname,
                    'function_identity_arguments',
                        pg_catalog.pg_get_function_identity_arguments(trigger_function.oid),
                    'function_owner', pg_catalog.pg_get_userbyid(trigger_function.proowner),
                    'function_definition', pg_catalog.pg_get_functiondef(trigger_function.oid),
                    'function_acl', cutover_authority.catalog_acl_sha256_v1(
                        'function', trigger_function.oid)) ORDER BY trigger_row.tgname)
                FROM pg_catalog.pg_trigger AS trigger_row
                JOIN pg_catalog.pg_proc AS trigger_function
                  ON trigger_function.oid = trigger_row.tgfoid
                JOIN pg_catalog.pg_namespace AS trigger_function_namespace
                  ON trigger_function_namespace.oid = trigger_function.pronamespace
                WHERE trigger_row.tgrelid = relation.oid AND NOT trigger_row.tgisinternal), '[]'::jsonb),
            'rules', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object('name', rule_row.rulename,
                    'enabled', rule_row.ev_enabled,
                    'definition', pg_catalog.pg_get_ruledef(rule_row.oid, false))
                ORDER BY rule_row.rulename)
                FROM pg_catalog.pg_rewrite AS rule_row
                WHERE rule_row.ev_class = relation.oid AND rule_row.rulename <> '_RETURN'), '[]'::jsonb),
            'policies', COALESCE((SELECT pg_catalog.jsonb_agg(
                pg_catalog.jsonb_build_object('name', policy.polname, 'command', policy.polcmd,
                    'permissive', policy.polpermissive,
                    'roles', COALESCE((SELECT pg_catalog.jsonb_agg(
                        pg_catalog.pg_get_userbyid(role_oid) ORDER BY pg_catalog.pg_get_userbyid(role_oid))
                        FROM pg_catalog.unnest(policy.polroles) AS role_oid), '[]'::jsonb),
                    'qual', pg_catalog.pg_get_expr(policy.polqual, policy.polrelid),
                    'with_check', pg_catalog.pg_get_expr(policy.polwithcheck, policy.polrelid))
                ORDER BY policy.polname) FROM pg_catalog.pg_policy AS policy
                WHERE policy.polrelid = relation.oid), '[]'::jsonb))
            FROM pg_catalog.pg_class AS relation
            JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = relation.relnamespace
            LEFT JOIN pg_catalog.pg_am AS access_method ON access_method.oid = relation.relam
            LEFT JOIN pg_catalog.pg_tablespace AS tablespace ON tablespace.oid = relation.reltablespace
            WHERE p_kind = 'table' AND relation.oid = p_object_oid),
        'routine', (SELECT pg_catalog.jsonb_build_object(
            'schema', namespace.nspname, 'name', procedure_row.proname,
            'identity_arguments', pg_catalog.pg_get_function_identity_arguments(procedure_row.oid),
            'result', pg_catalog.pg_get_function_result(procedure_row.oid),
            'language', language.lanname, 'kind', procedure_row.prokind,
            'volatile', procedure_row.provolatile, 'parallel', procedure_row.proparallel,
            'security_definer', procedure_row.prosecdef, 'strict', procedure_row.proisstrict,
            'leakproof', procedure_row.proleakproof,
            'config', COALESCE((SELECT pg_catalog.jsonb_agg(config_row ORDER BY config_row)
                FROM pg_catalog.unnest(procedure_row.proconfig) AS config_row), '[]'::jsonb),
            'definition', pg_catalog.pg_get_functiondef(procedure_row.oid))
            FROM pg_catalog.pg_proc AS procedure_row
            JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure_row.pronamespace
            JOIN pg_catalog.pg_language AS language ON language.oid = procedure_row.prolang
            WHERE p_kind = 'function' AND procedure_row.oid = p_object_oid)
    )::text, 'UTF8')), 'hex'));
END;
$$;


ALTER FUNCTION cutover_authority.catalog_definition_sha256_v1(p_kind text, p_object_oid oid) OWNER TO harpy_owner;

--
-- Name: consume_finalization_authorization_v1(uuid, uuid, uuid, text, bytea, text, bytea, text, bytea, text, bytea, text, bytea, text, text, bytea); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.consume_finalization_authorization_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) RETURNS TABLE(already_finalized boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_authorization cutover_authority.finalization_authorizations%ROWTYPE;
    v_receipt cutover_authority.finalization_receipts%ROWTYPE;
    v_finalizer jsonb;
BEGIN
    IF SESSION_USER <> 'harpy_cutover_finalizer' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='cutover finalization consumer denied';
    END IF;
    SELECT authorization_row.* INTO STRICT v_authorization
    FROM cutover_authority.finalization_authorizations AS authorization_row
    WHERE authorization_row.operation_id=p_operation_id AND authorization_row.run_id=p_run_id
      AND authorization_row.finalizer_lease_id=p_finalizer_lease_id FOR UPDATE;
    IF v_authorization.finalizer_lease_id IS DISTINCT FROM p_finalizer_lease_id OR
       v_authorization.finalizer_lease_sha256 IS DISTINCT FROM p_finalizer_lease_sha256 OR
       v_authorization.finalizer_lease_document IS DISTINCT FROM p_finalizer_lease_document OR
       v_authorization.adoption_lease_sha256 IS DISTINCT FROM p_adoption_lease_sha256 OR
       v_authorization.adoption_lease_document IS DISTINCT FROM p_adoption_lease_document OR
       v_authorization.seal_receipt_sha256 IS DISTINCT FROM p_seal_receipt_sha256 OR
       v_authorization.seal_receipt_document IS DISTINCT FROM p_seal_receipt_document OR
       v_authorization.cleanup_receipt_sha256 IS DISTINCT FROM p_cleanup_receipt_sha256 OR
       v_authorization.cleanup_receipt_document IS DISTINCT FROM p_cleanup_receipt_document OR
       v_authorization.authority_receipt_sha256 IS DISTINCT FROM p_authority_receipt_sha256 OR
       v_authorization.authority_receipt_document IS DISTINCT FROM p_authority_receipt_document OR
       v_authorization.terminal_state IS DISTINCT FROM p_terminal_state OR
       v_authorization.terminal_evidence_sha256 IS DISTINCT FROM p_terminal_evidence_sha256 OR
       v_authorization.terminal_evidence_document IS DISTINCT FROM p_terminal_evidence_document OR
       pg_catalog.encode(pg_catalog.sha256(p_finalizer_lease_document),'hex') IS DISTINCT FROM p_finalizer_lease_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_adoption_lease_document),'hex') IS DISTINCT FROM p_adoption_lease_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_seal_receipt_document),'hex') IS DISTINCT FROM p_seal_receipt_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_cleanup_receipt_document),'hex') IS DISTINCT FROM p_cleanup_receipt_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_authority_receipt_document),'hex') IS DISTINCT FROM p_authority_receipt_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_terminal_evidence_document),'hex') IS DISTINCT FROM p_terminal_evidence_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22000', MESSAGE='cutover finalization authorization differs';
    END IF;
    SELECT receipt.* INTO v_receipt FROM cutover_authority.finalization_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id;
    IF FOUND THEN
        IF v_receipt.finalizer_lease_id IS DISTINCT FROM p_finalizer_lease_id OR
           v_receipt.finalizer_lease_sha256 IS DISTINCT FROM p_finalizer_lease_sha256 OR
           v_receipt.finalizer_lease_document IS DISTINCT FROM p_finalizer_lease_document OR
           v_receipt.adoption_lease_sha256 IS DISTINCT FROM p_adoption_lease_sha256 OR
           v_receipt.adoption_lease_document IS DISTINCT FROM p_adoption_lease_document OR
           v_receipt.seal_receipt_sha256 IS DISTINCT FROM p_seal_receipt_sha256 OR
           v_receipt.seal_receipt_document IS DISTINCT FROM p_seal_receipt_document OR
           v_receipt.cleanup_receipt_sha256 IS DISTINCT FROM p_cleanup_receipt_sha256 OR
           v_receipt.cleanup_receipt_document IS DISTINCT FROM p_cleanup_receipt_document OR
           v_receipt.authority_receipt_sha256 IS DISTINCT FROM p_authority_receipt_sha256 OR
           v_receipt.authority_receipt_document IS DISTINCT FROM p_authority_receipt_document OR
           v_receipt.terminal_state IS DISTINCT FROM p_terminal_state OR
           v_receipt.terminal_evidence_sha256 IS DISTINCT FROM p_terminal_evidence_sha256 OR
           v_receipt.terminal_evidence_document IS DISTINCT FROM p_terminal_evidence_document OR
           v_receipt.finalization_state_sha256 IS DISTINCT FROM v_authorization.finalization_state_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='22000', MESSAGE='cutover finalization receipt replay differs';
        END IF;
        RETURN QUERY SELECT true;
        RETURN;
    END IF;
    v_finalizer:=pg_catalog.convert_from(p_finalizer_lease_document,'UTF8')::jsonb;
    IF v_authorization.finalizer_expires_at<=pg_catalog.clock_timestamp() OR
       v_authorization.authorizer_valid_until<=pg_catalog.clock_timestamp() OR
       v_finalizer->>'finalization_state_sha256' IS DISTINCT FROM v_authorization.finalization_state_sha256 OR
       (v_finalizer->>'expires_at')::timestamptz IS DISTINCT FROM v_authorization.finalizer_expires_at OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
          WHERE role.rolname='harpy_cutover_finalizer' AND role.rolcanlogin
            AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
            AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls
            AND role.rolconnlimit=1 AND role.rolvaliduntil IS NOT DISTINCT FROM v_authorization.finalizer_expires_at
            AND role.rolvaliduntil>pg_catalog.clock_timestamp()
            AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
                WHERE membership.roleid=role.oid OR membership.member=role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover finalizer role lease is not active';
    END IF;
    RETURN QUERY SELECT false;
END;
$$;


ALTER FUNCTION cutover_authority.consume_finalization_authorization_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) OWNER TO harpy_owner;

--
-- Name: finalization_state_sha256_v1(uuid, uuid); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.finalization_state_sha256_v1(p_operation_id uuid, p_run_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    SET bytea_output TO 'hex'
    SET "IntervalStyle" TO 'iso_8601'
    AS $$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_release_run_id uuid;
BEGIN
    IF p_operation_id IS NULL OR p_run_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='finalization state identity is invalid';
    END IF;
    LOCK TABLE platform.cutover_operations,
        platform.cutover_operation_relations,
        platform.cutover_operation_checkpoint_keys,
        platform.cutover_operation_columns,
        platform.cutover_operation_procedures,
        platform.cutover_initial_copy_receipts,
        platform.cutover_batch_receipts,
        platform.cutover_copy_checkpoints,
        platform.applied_change_receipts,
        platform.cutover_change_journal,
        platform.cutover_credential_receipts,
        platform.tenant_migration_requirement_catalogs,
        platform.tenant_migration_requirements,
        platform.tenant_migration_requirement_targets,
        platform.tenant_migration_checkpoints,
        platform.tenants,
        platform.release_generations,
        platform.schema_contracts IN SHARE MODE;
    SELECT operation.* INTO STRICT v_operation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    SELECT release_row.migration_run_id INTO STRICT v_release_run_id
    FROM platform.release_generations AS release_row
    WHERE release_row.release_id=v_operation.release_id
      AND release_row.environment_id=v_operation.environment_id;
    RETURN (SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.jsonb_build_object(
            'operation',pg_catalog.to_jsonb(v_operation),
            'relations',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(relation)
                ORDER BY relation.ordinal) FROM platform.cutover_operation_relations AS relation
                WHERE relation.operation_id=p_operation_id AND relation.run_id=p_run_id),'[]'::jsonb),
            'checkpoint_keys',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(checkpoint_key)
                ORDER BY checkpoint_key.relation_ordinal,checkpoint_key.ordinal)
                FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key
                WHERE checkpoint_key.operation_id=p_operation_id AND checkpoint_key.run_id=p_run_id),'[]'::jsonb),
            'columns',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(column_row)
                ORDER BY column_row.relation_ordinal,column_row.ordinal)
                FROM platform.cutover_operation_columns AS column_row
                WHERE column_row.operation_id=p_operation_id AND column_row.run_id=p_run_id),'[]'::jsonb),
            'procedures',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(procedure_row)
                ORDER BY procedure_row.ordinal) FROM platform.cutover_operation_procedures AS procedure_row
                WHERE procedure_row.operation_id=p_operation_id AND procedure_row.run_id=p_run_id),'[]'::jsonb),
            'initial_copy_receipt',(SELECT pg_catalog.to_jsonb(receipt)
                FROM platform.cutover_initial_copy_receipts AS receipt
                WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id),
            'copy_checkpoints',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(checkpoint)
                ORDER BY checkpoint.relation_ordinal,checkpoint.checkpoint_key)
                FROM platform.cutover_copy_checkpoints AS checkpoint
                WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id),'[]'::jsonb),
            'batch_receipts',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(batch)
                ORDER BY batch.relation_ordinal,batch.checkpoint_key,batch.batch_ordinal)
                FROM platform.cutover_batch_receipts AS batch
                WHERE batch.operation_id=p_operation_id AND batch.run_id=p_run_id),'[]'::jsonb),
            'applied_changes',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(receipt)
                ORDER BY receipt.source_xid,receipt.relation_ordinal,receipt.change_ordinal)
                FROM platform.applied_change_receipts AS receipt
                WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id),'[]'::jsonb),
            'change_journal',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(journal)
                ORDER BY journal.source_xid,journal.domain)
                FROM platform.cutover_change_journal AS journal
                WHERE journal.operation_id=p_operation_id AND journal.run_id=p_run_id),'[]'::jsonb),
            'credential_receipts',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(receipt)
                ORDER BY receipt.receipt_kind,receipt.receipt_id)
                FROM platform.cutover_credential_receipts AS receipt
                WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id),'[]'::jsonb),
            'release',(SELECT pg_catalog.to_jsonb(release_row) FROM platform.release_generations AS release_row
                WHERE release_row.migration_run_id=v_release_run_id),
            'schema_contract',(SELECT pg_catalog.to_jsonb(contract_row) FROM platform.schema_contracts AS contract_row
                WHERE contract_row.component='core'),
            'tenant_catalog',(SELECT pg_catalog.to_jsonb(catalog) FROM platform.tenant_migration_requirement_catalogs AS catalog
                WHERE catalog.migration_run_id=v_release_run_id),
            'tenant_requirements',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(requirement)
                ORDER BY requirement.ordinal) FROM platform.tenant_migration_requirements AS requirement
                WHERE requirement.migration_run_id=v_release_run_id),'[]'::jsonb),
            'tenant_targets',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(target)
                ORDER BY target.ordinal) FROM platform.tenant_migration_requirement_targets AS target
                WHERE target.migration_run_id=v_release_run_id),'[]'::jsonb),
            'active_tenants',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'tenant_id',tenant.id::text,'schema_name',tenant.schema_name) ORDER BY tenant.id)
                FROM platform.tenants AS tenant WHERE tenant.deleted_at IS NULL),'[]'::jsonb),
            'tenant_checkpoints',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(checkpoint)
                ORDER BY checkpoint.tenant_id,checkpoint.owner,checkpoint.logical_version)
                FROM platform.tenant_migration_checkpoints AS checkpoint
                WHERE EXISTS (SELECT 1 FROM platform.tenant_migration_requirement_targets AS target
                    WHERE target.migration_run_id=v_release_run_id AND target.tenant_id=checkpoint.tenant_id)
                  AND EXISTS (SELECT 1 FROM platform.tenant_migration_requirements AS requirement
                    WHERE requirement.migration_run_id=v_release_run_id
                      AND requirement.owner=checkpoint.owner
                      AND requirement.logical_version=checkpoint.logical_version)),'[]'::jsonb)
        )::text,'UTF8')),'hex'));
END;
$$;


ALTER FUNCTION cutover_authority.finalization_state_sha256_v1(p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: finalize_operation_v1(uuid, uuid, uuid, text, bytea, text, bytea, text, bytea, text, bytea, text, bytea, text, text, bytea); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.finalize_operation_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) RETURNS TABLE(terminal_state text, terminal_evidence_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_already_finalized boolean;
    v_authorization cutover_authority.finalization_authorizations%ROWTYPE;
    v_operation platform.cutover_operations%ROWTYPE;
    v_finalizer jsonb;
    v_state_sha256 text;
    v_catalog_sha256 text;
    v_catalog_document bytea;
    v_requirement_count integer;
    v_target_count integer;
    v_updated_state text;
BEGIN
    IF SESSION_USER <> 'harpy_cutover_finalizer' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='cutover finalizer denied';
    END IF;
    SELECT result.already_finalized INTO STRICT v_already_finalized
    FROM cutover_authority.consume_finalization_authorization_v1(
        p_operation_id,p_run_id,p_finalizer_lease_id,p_finalizer_lease_sha256,p_finalizer_lease_document,
        p_adoption_lease_sha256,p_adoption_lease_document,p_seal_receipt_sha256,p_seal_receipt_document,
        p_cleanup_receipt_sha256,p_cleanup_receipt_document,p_authority_receipt_sha256,p_authority_receipt_document,
        p_terminal_state,p_terminal_evidence_sha256,p_terminal_evidence_document) AS result;
    IF v_already_finalized THEN
        RETURN QUERY SELECT receipt.terminal_state,receipt.terminal_evidence_sha256
        FROM cutover_authority.finalization_receipts AS receipt
        WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id
          AND receipt.finalizer_lease_id=p_finalizer_lease_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover finalized operation differs';
        END IF;
        RETURN;
    END IF;
    PERFORM cutover_authority.validate_finalization_envelope_v1(
        p_operation_id,p_run_id,p_finalizer_lease_id,p_finalizer_lease_sha256,p_finalizer_lease_document,
        p_adoption_lease_sha256,p_adoption_lease_document,p_seal_receipt_sha256,p_seal_receipt_document,
        p_cleanup_receipt_sha256,p_cleanup_receipt_document,p_authority_receipt_sha256,p_authority_receipt_document,
        p_terminal_state,p_terminal_evidence_sha256,p_terminal_evidence_document);
    SELECT authorization_row.* INTO STRICT v_authorization
    FROM cutover_authority.finalization_authorizations AS authorization_row
    WHERE authorization_row.operation_id=p_operation_id AND authorization_row.run_id=p_run_id
      AND authorization_row.finalizer_lease_id=p_finalizer_lease_id FOR UPDATE;
    SELECT operation.* INTO STRICT v_operation FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    IF p_terminal_state='completed' THEN
        SELECT catalog.catalog_sha256,catalog.canonical_document,catalog.requirement_count,catalog.target_count
        INTO STRICT v_catalog_sha256,v_catalog_document,v_requirement_count,v_target_count
        FROM platform.release_generations AS release_row
        JOIN platform.tenant_migration_requirement_catalogs AS catalog
          ON catalog.migration_run_id=release_row.migration_run_id
         AND catalog.release_id=release_row.release_id
         AND catalog.environment_id=release_row.environment_id
         AND catalog.database_origin=release_row.database_origin
        WHERE release_row.release_id=v_operation.release_id
          AND release_row.environment_id=v_operation.environment_id;
    END IF;
    v_finalizer:=pg_catalog.convert_from(p_finalizer_lease_document,'UTF8')::jsonb;
    v_state_sha256:=cutover_authority.finalization_state_sha256_v1(p_operation_id,p_run_id);
    IF v_state_sha256 IS DISTINCT FROM v_authorization.finalization_state_sha256 OR
       v_state_sha256 IS DISTINCT FROM v_finalizer->>'finalization_state_sha256' OR
       v_authorization.finalizer_expires_at<=pg_catalog.clock_timestamp() OR
       v_authorization.authorizer_valid_until<=pg_catalog.clock_timestamp() OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
          WHERE role.rolname='harpy_cutover_finalizer' AND role.rolcanlogin AND NOT role.rolinherit
            AND NOT role.rolsuper AND NOT role.rolcreatedb AND NOT role.rolcreaterole
            AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=1
            AND role.rolvaliduntil IS NOT DISTINCT FROM v_authorization.finalizer_expires_at
            AND role.rolvaliduntil>pg_catalog.clock_timestamp() AND NOT EXISTS
              (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
               WHERE membership.roleid=role.oid OR membership.member=role.oid)) OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
          WHERE role.rolname='harpy_cluster_admin' AND role.rolcanlogin AND NOT role.rolinherit
            AND NOT role.rolsuper AND role.rolcreatedb AND role.rolcreaterole
            AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=1
            AND role.rolvaliduntil IS NOT DISTINCT FROM v_authorization.authorizer_valid_until
            AND role.rolvaliduntil>pg_catalog.clock_timestamp() AND NOT EXISTS
              (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
               WHERE membership.roleid=role.oid OR membership.member=role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover finalization state or role lease changed';
    END IF;
    INSERT INTO cutover_authority.finalization_receipts (
        operation_id,run_id,finalizer_lease_id,finalizer_lease_sha256,finalizer_lease_document,
        adoption_lease_sha256,adoption_lease_document,seal_receipt_sha256,seal_receipt_document,
        cleanup_receipt_sha256,cleanup_receipt_document,authority_receipt_sha256,authority_receipt_document,
        terminal_state,terminal_evidence_sha256,terminal_evidence_document,finalization_state_sha256,
        tenant_requirement_catalog_sha256,tenant_requirement_catalog_document,
        tenant_requirement_count,tenant_target_count)
    VALUES (p_operation_id,p_run_id,p_finalizer_lease_id,p_finalizer_lease_sha256,p_finalizer_lease_document,
        p_adoption_lease_sha256,p_adoption_lease_document,p_seal_receipt_sha256,p_seal_receipt_document,
        p_cleanup_receipt_sha256,p_cleanup_receipt_document,p_authority_receipt_sha256,p_authority_receipt_document,
        p_terminal_state,p_terminal_evidence_sha256,p_terminal_evidence_document,v_state_sha256,
        v_catalog_sha256,v_catalog_document,v_requirement_count,v_target_count);
    UPDATE platform.cutover_operations AS operation
    SET state=p_terminal_state,blocked_reason=NULL,updated_at=pg_catalog.clock_timestamp()
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id AND
      ((p_terminal_state='completed' AND operation.state='quiescing') OR
       (p_terminal_state IN ('failed','cancelled') AND operation.state IN ('planned','copying','shadow','quiescing','blocked')))
    RETURNING operation.state INTO STRICT v_updated_state;
    RETURN QUERY SELECT v_updated_state,p_terminal_evidence_sha256;
END;
$$;


ALTER FUNCTION cutover_authority.finalize_operation_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) OWNER TO harpy_owner;

--
-- Name: observe_finalizer_authority_v1(uuid, uuid); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.observe_finalizer_authority_v1(p_operation_id uuid, p_run_id uuid) RETURNS TABLE(finalization_state_sha256 text, finalization_procedure_oid oid, finalization_procedure_signature text, database_name text, database_origin text, system_identifier text, database_oid oid, operation_state text, completed_eligible boolean, abort_eligible boolean, completed_tenant_catalog_sha256 text, completed_tenant_requirement_count integer, finalizer_valid_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_finalizer_role pg_catalog.pg_roles%ROWTYPE;
    v_state_sha256 text;
    v_database_origin text;
    v_system_identifier text;
    v_database_oid oid;
    v_catalog_sha256 text;
    v_requirement_count integer;
    v_authority_receipt_sha256 text;
BEGIN
    IF SESSION_USER <> 'harpy_cluster_admin' OR p_operation_id IS NULL OR p_run_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='cutover finalizer authority observer denied';
    END IF;
    SELECT inventory.receipt_sha256 INTO STRICT v_authority_receipt_sha256
    FROM cutover_authority.authority_adoption_inventory AS inventory
    ORDER BY inventory.catalog_generation DESC LIMIT 1;
    PERFORM cutover_authority.assert_adopted_catalog_v1(v_authority_receipt_sha256);
    SELECT role.* INTO STRICT v_finalizer_role FROM pg_catalog.pg_roles AS role
    WHERE role.rolname='harpy_cutover_finalizer' AND role.rolcanlogin AND NOT role.rolinherit
      AND NOT role.rolsuper AND NOT role.rolcreatedb AND NOT role.rolcreaterole
      AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=1
      AND role.rolvaliduntil>pg_catalog.clock_timestamp()
      AND role.rolvaliduntil<=pg_catalog.clock_timestamp()+interval '120 seconds'
      AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
          WHERE membership.roleid=role.oid OR membership.member=role.oid);
    v_state_sha256:=cutover_authority.finalization_state_sha256_v1(p_operation_id,p_run_id);
    SELECT operation.* INTO STRICT v_operation FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    SELECT release_row.database_origin,control.system_identifier::text,database_row.oid,
           catalog.catalog_sha256,catalog.requirement_count
    INTO STRICT v_database_origin,v_system_identifier,v_database_oid,
         v_catalog_sha256,v_requirement_count
    FROM platform.release_generations AS release_row
    CROSS JOIN pg_catalog.pg_control_system() AS control
    CROSS JOIN pg_catalog.pg_database AS database_row
    LEFT JOIN platform.tenant_migration_requirement_catalogs AS catalog
      ON catalog.migration_run_id=release_row.migration_run_id
     AND catalog.release_id=release_row.release_id
     AND catalog.environment_id=release_row.environment_id
     AND catalog.database_origin=release_row.database_origin
    WHERE release_row.release_id=v_operation.release_id
      AND release_row.environment_id=v_operation.environment_id
      AND database_row.datname=pg_catalog.current_database();
    RETURN QUERY SELECT v_state_sha256,
        'cutover_authority.finalize_operation_v1(uuid,uuid,uuid,text,bytea,text,bytea,text,bytea,text,bytea,text,bytea,text,text,bytea)'::regprocedure::oid,
        'cutover_authority.finalize_operation_v1(uuid,uuid,uuid,text,bytea,text,bytea,text,bytea,text,bytea,text,bytea,text,text,bytea)'::text,
        pg_catalog.current_database()::text,v_database_origin,v_system_identifier,v_database_oid,
        v_operation.state,
        v_operation.state='quiescing' AND v_catalog_sha256 IS NOT NULL AND v_requirement_count IS NOT NULL,
        v_operation.state IN ('planned','copying','shadow','quiescing','blocked'),
        v_catalog_sha256,v_requirement_count,v_finalizer_role.rolvaliduntil;
END;
$$;


ALTER FUNCTION cutover_authority.observe_finalizer_authority_v1(p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: record_credential_receipts_v1(uuid, uuid, text, bytea, text, bytea); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.record_credential_receipts_v1(p_operation_id uuid, p_run_id uuid, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_seal jsonb;
    v_cleanup jsonb;
    v_target jsonb;
    v_authority_receipt_sha256 text;
    v_seal_receipt_id uuid;
    v_cleanup_receipt_id uuid;
    v_seal_issued_at timestamptz;
    v_cleanup_issued_at timestamptz;
    v_invalid boolean;
BEGIN
    IF SESSION_USER <> 'harpy_cluster_admin' OR p_operation_id IS NULL OR p_run_id IS NULL OR
       p_seal_receipt_sha256 IS NULL OR p_seal_receipt_sha256!~'^[0-9a-f]{64}$' OR
       p_cleanup_receipt_sha256 IS NULL OR p_cleanup_receipt_sha256!~'^[0-9a-f]{64}$' OR
       p_seal_receipt_document IS NULL OR pg_catalog.octet_length(p_seal_receipt_document) NOT BETWEEN 2 AND 65536 OR
       p_cleanup_receipt_document IS NULL OR pg_catalog.octet_length(p_cleanup_receipt_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.encode(pg_catalog.sha256(p_seal_receipt_document),'hex') IS DISTINCT FROM p_seal_receipt_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_cleanup_receipt_document),'hex') IS DISTINCT FROM p_cleanup_receipt_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover credential receipt input is invalid';
    END IF;
    SELECT inventory.receipt_sha256 INTO STRICT v_authority_receipt_sha256
    FROM cutover_authority.authority_adoption_inventory AS inventory
    ORDER BY inventory.catalog_generation DESC LIMIT 1;
    PERFORM cutover_authority.assert_adopted_catalog_v1(v_authority_receipt_sha256);
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
        WHERE role.rolname='harpy_cluster_admin' AND role.rolcanlogin AND NOT role.rolinherit
          AND NOT role.rolsuper AND role.rolcreatedb AND role.rolcreaterole AND NOT role.rolreplication
          AND NOT role.rolbypassrls AND role.rolconnlimit=1 AND role.rolvaliduntil>pg_catalog.clock_timestamp()
          AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
              WHERE membership.roleid=role.oid OR membership.member=role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover credential recorder role lease is invalid';
    END IF;
    SELECT operation.* INTO STRICT v_operation FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.state IN ('planned','copying','shadow','quiescing','blocked');
    SELECT pg_catalog.jsonb_build_object('database_name',pg_catalog.current_database(),
      'database_origin',release_row.database_origin,'system_identifier',control.system_identifier::text,
      'database_oid',database_row.oid::bigint) INTO STRICT v_target
    FROM platform.release_generations AS release_row CROSS JOIN pg_catalog.pg_control_system() AS control
    CROSS JOIN pg_catalog.pg_database AS database_row WHERE release_row.release_id=v_operation.release_id
      AND release_row.environment_id=v_operation.environment_id AND database_row.datname=pg_catalog.current_database();
    IF v_operation.target_system_identifier::text IS DISTINCT FROM v_target->>'system_identifier' OR
       v_operation.target_database_oid::oid IS DISTINCT FROM (v_target->>'database_oid')::oid THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover credential receipt target differs';
    END IF;
    v_seal:=pg_catalog.convert_from(p_seal_receipt_document,'UTF8')::jsonb;
    v_cleanup:=pg_catalog.convert_from(p_cleanup_receipt_document,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_seal) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_seal)) IS DISTINCT FROM 4::bigint OR
       (v_seal ?& ARRAY['contract_version','kind','payload','signature']) IS DISTINCT FROM true OR
       pg_catalog.jsonb_typeof(v_seal->'payload') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_seal->'payload')) IS DISTINCT FROM 13::bigint OR
       (v_seal->'payload' ?& ARRAY['receipt_id','lease_id','lease_manifest_sha256','environment_id','operation_id','run_id','issued_at','source','target','credentials','source_sessions','target_sessions','result']) IS DISTINCT FROM true OR
       v_seal->>'contract_version' IS DISTINCT FROM 'cutover-session-seal-receipt.v1' OR
       v_seal->>'kind' IS DISTINCT FROM 'cutover_session_seal' OR v_seal->'payload'->>'result' IS DISTINCT FROM 'sealed' OR
       v_seal->'payload'->>'lease_id' IS DISTINCT FROM v_operation.lease_id::text OR
       v_seal->'payload'->>'lease_manifest_sha256' IS DISTINCT FROM v_operation.lease_manifest_sha256 OR
       v_seal->'payload'->>'environment_id' IS DISTINCT FROM v_operation.environment_id::text OR
       v_seal->'payload'->>'operation_id' IS DISTINCT FROM p_operation_id::text OR
       v_seal->'payload'->>'run_id' IS DISTINCT FROM p_run_id::text OR
       v_seal->'payload'->'source' IS DISTINCT FROM v_target OR v_seal->'payload'->'target' IS DISTINCT FROM v_target OR
       v_seal->'payload'->'credentials' IS DISTINCT FROM
         '[{"principal":"harpy_cutover_decoder","can_login":false,"password_state":null,"replication":false,"connection_limit":0},{"principal":"harpy_adopter","can_login":false,"password_state":null,"replication":false,"connection_limit":0}]'::jsonb OR
       pg_catalog.jsonb_typeof(v_seal->'payload'->'source_sessions') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_seal->'payload'->'source_sessions') NOT BETWEEN 2 AND 32 OR
       pg_catalog.jsonb_typeof(v_seal->'payload'->'target_sessions') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_seal->'payload'->'target_sessions') NOT BETWEEN 1 AND 32 OR
       v_seal->'payload'->>'receipt_id' IS NULL OR
       (v_seal->'payload'->>'receipt_id')::uuid::text IS DISTINCT FROM v_seal->'payload'->>'receipt_id' OR
       v_seal->'payload'->>'issued_at' IS NULL OR v_seal->'payload'->>'issued_at'!~'(Z|[+]00:00)$' OR
       pg_catalog.jsonb_typeof(v_seal->'signature') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_seal->'signature')) IS DISTINCT FROM 3::bigint OR
       (v_seal->'signature' ?& ARRAY['algorithm','key_id','value']) IS DISTINCT FROM true OR
       v_seal->'signature'->>'algorithm' IS DISTINCT FROM 'Ed25519' OR
       pg_catalog.jsonb_typeof(v_seal->'signature'->'key_id') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_seal->'signature'->'value') IS DISTINCT FROM 'string' OR
       v_seal->'signature'->>'key_id'!~'^[a-z0-9][a-z0-9._-]{0,63}$' OR
       v_seal->'signature'->>'value'!~'^[A-Za-z0-9_-]{86}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover session seal receipt differs';
    END IF;
    v_seal_receipt_id:=(v_seal->'payload'->>'receipt_id')::uuid;
    v_seal_issued_at:=(v_seal->'payload'->>'issued_at')::timestamptz;
    IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(v_seal->'payload'->'source_sessions') AS session_row
          WHERE (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(session_row)) IS DISTINCT FROM 4::bigint
             OR (session_row ?& ARRAY['pid','backend_start','session_user','application_name']) IS DISTINCT FROM true
             OR pg_catalog.jsonb_typeof(session_row->'pid') IS DISTINCT FROM 'number' OR session_row->>'pid'!~'^[1-9][0-9]*$'
             OR pg_catalog.jsonb_typeof(session_row->'backend_start') IS DISTINCT FROM 'string'
             OR session_row->>'backend_start'!~'(Z|[+]00:00)$' OR (session_row->>'backend_start')::timestamptz>v_seal_issued_at
             OR session_row->>'session_user' IS DISTINCT FROM 'harpy_cutover_decoder'
             OR session_row->>'application_name' IS DISTINCT FROM 'harpy-cutover/'||p_run_id::text) OR
       EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(v_seal->'payload'->'target_sessions') AS session_row
          WHERE (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(session_row)) IS DISTINCT FROM 4::bigint
             OR (session_row ?& ARRAY['pid','backend_start','session_user','application_name']) IS DISTINCT FROM true
             OR pg_catalog.jsonb_typeof(session_row->'pid') IS DISTINCT FROM 'number' OR session_row->>'pid'!~'^[1-9][0-9]*$'
             OR pg_catalog.jsonb_typeof(session_row->'backend_start') IS DISTINCT FROM 'string'
             OR session_row->>'backend_start'!~'(Z|[+]00:00)$' OR (session_row->>'backend_start')::timestamptz>v_seal_issued_at
             OR session_row->>'session_user' IS DISTINCT FROM 'harpy_adopter'
             OR session_row->>'application_name' IS DISTINCT FROM 'harpy-cutover/'||p_run_id::text) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover sealed session set differs';
    END IF;
    SELECT pg_catalog.count(*) IS DISTINCT FROM pg_catalog.count(DISTINCT session_row.pid) INTO v_invalid
    FROM (SELECT (value->>'pid')::bigint AS pid FROM pg_catalog.jsonb_array_elements(v_seal->'payload'->'source_sessions') AS value
          UNION ALL SELECT (value->>'pid')::bigint FROM pg_catalog.jsonb_array_elements(v_seal->'payload'->'target_sessions') AS value) AS session_row;
    IF v_invalid THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover sealed session pid duplicates'; END IF;
    IF pg_catalog.jsonb_typeof(v_cleanup) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_cleanup)) IS DISTINCT FROM 4::bigint OR
       (v_cleanup ?& ARRAY['contract_version','kind','payload','signature']) IS DISTINCT FROM true OR
       pg_catalog.jsonb_typeof(v_cleanup->'payload') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_cleanup->'payload')) IS DISTINCT FROM 10::bigint OR
       (v_cleanup->'payload' ?& ARRAY['receipt_id','lease_id','lease_manifest_sha256','seal_receipt_sha256','environment_id','operation_id','run_id','issued_at','principals','result']) IS DISTINCT FROM true OR
       v_cleanup->>'contract_version' IS DISTINCT FROM 'cutover-credential-cleanup-receipt.v1' OR
       v_cleanup->>'kind' IS DISTINCT FROM 'cutover_credential_cleanup' OR v_cleanup->'payload'->>'result' IS DISTINCT FROM 'succeeded' OR
       v_cleanup->'payload'->>'lease_id' IS DISTINCT FROM v_operation.lease_id::text OR
       v_cleanup->'payload'->>'lease_manifest_sha256' IS DISTINCT FROM v_operation.lease_manifest_sha256 OR
       v_cleanup->'payload'->>'seal_receipt_sha256' IS DISTINCT FROM p_seal_receipt_sha256 OR
       v_cleanup->'payload'->>'environment_id' IS DISTINCT FROM v_operation.environment_id::text OR
       v_cleanup->'payload'->>'operation_id' IS DISTINCT FROM p_operation_id::text OR
       v_cleanup->'payload'->>'run_id' IS DISTINCT FROM p_run_id::text OR
       v_cleanup->'payload'->>'receipt_id' IS NULL OR
       (v_cleanup->'payload'->>'receipt_id')::uuid::text IS DISTINCT FROM v_cleanup->'payload'->>'receipt_id' OR
       v_cleanup->'payload'->>'issued_at' IS NULL OR v_cleanup->'payload'->>'issued_at'!~'(Z|[+]00:00)$' OR
       pg_catalog.jsonb_typeof(v_cleanup->'payload'->'principals') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_cleanup->'payload'->'principals') IS DISTINCT FROM 2 OR
       ((v_cleanup->'payload'->'principals'->0)-'cleaned_at'::text) IS DISTINCT FROM
         '{"principal":"harpy_cutover_decoder","can_login":false,"password_state":null,"replication":false,"connection_limit":0,"active_sessions":0,"membership_count":0,"dynamic_grants_revoked":true}'::jsonb OR
       ((v_cleanup->'payload'->'principals'->1)-'cleaned_at'::text) IS DISTINCT FROM
         '{"principal":"harpy_adopter","can_login":false,"password_state":null,"replication":false,"connection_limit":0,"active_sessions":0,"membership_count":0,"dynamic_grants_revoked":true}'::jsonb OR
       pg_catalog.jsonb_typeof(v_cleanup->'signature') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_cleanup->'signature')) IS DISTINCT FROM 3::bigint OR
       (v_cleanup->'signature' ?& ARRAY['algorithm','key_id','value']) IS DISTINCT FROM true OR
       v_cleanup->'signature'->>'algorithm' IS DISTINCT FROM 'Ed25519' OR
       pg_catalog.jsonb_typeof(v_cleanup->'signature'->'key_id') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_cleanup->'signature'->'value') IS DISTINCT FROM 'string' OR
       v_cleanup->'signature'->>'key_id'!~'^[a-z0-9][a-z0-9._-]{0,63}$' OR
       v_cleanup->'signature'->>'value'!~'^[A-Za-z0-9_-]{86}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover credential cleanup receipt differs';
    END IF;
    v_cleanup_receipt_id:=(v_cleanup->'payload'->>'receipt_id')::uuid;
    v_cleanup_issued_at:=(v_cleanup->'payload'->>'issued_at')::timestamptz;
    IF v_cleanup_receipt_id=v_seal_receipt_id OR v_cleanup_issued_at<v_seal_issued_at OR
       EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(v_cleanup->'payload'->'principals') AS principal
          WHERE pg_catalog.jsonb_typeof(principal->'cleaned_at') IS DISTINCT FROM 'string'
             OR principal->>'cleaned_at'!~'(Z|[+]00:00)$' OR
             (principal->>'cleaned_at')::timestamptz NOT BETWEEN v_seal_issued_at AND v_cleanup_issued_at) OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role WHERE role.rolname IN ('harpy_cutover_decoder','harpy_adopter')
          AND NOT role.rolcanlogin AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
          AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=0
          AND role.rolvaliduntil IS NOT DISTINCT FROM 'infinity'::timestamptz
          AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
             WHERE membership.roleid=role.oid OR membership.member=role.oid)
          HAVING pg_catalog.count(*)=2) OR
       EXISTS (SELECT 1 FROM pg_catalog.pg_stat_activity AS activity
          WHERE activity.usename IN ('harpy_cutover_decoder','harpy_adopter')) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover live credential cleanup state differs';
    END IF;
    INSERT INTO platform.cutover_credential_receipts (receipt_id,operation_id,run_id,lease_id,receipt_kind,
      contract_version,lease_manifest_sha256,seal_receipt_sha256,receipt_sha256,canonical_document,issued_at,verified_at)
    VALUES (v_seal_receipt_id,p_operation_id,p_run_id,v_operation.lease_id,'session_seal',
      'cutover-session-seal-receipt.v1',v_operation.lease_manifest_sha256,NULL,p_seal_receipt_sha256,v_seal,v_seal_issued_at,pg_catalog.clock_timestamp())
    ON CONFLICT DO NOTHING;
    IF NOT FOUND AND NOT EXISTS (SELECT 1 FROM platform.cutover_credential_receipts AS receipt
       WHERE receipt.receipt_id=v_seal_receipt_id AND receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id
         AND receipt.lease_id=v_operation.lease_id AND receipt.receipt_kind='session_seal'
         AND receipt.contract_version='cutover-session-seal-receipt.v1' AND receipt.lease_manifest_sha256=v_operation.lease_manifest_sha256
         AND receipt.seal_receipt_sha256 IS NULL AND receipt.receipt_sha256=p_seal_receipt_sha256
         AND receipt.canonical_document=v_seal AND receipt.issued_at=v_seal_issued_at) THEN
        RAISE EXCEPTION USING ERRCODE='22000', MESSAGE='cutover session seal receipt replay differs';
    END IF;
    INSERT INTO platform.cutover_credential_receipts (receipt_id,operation_id,run_id,lease_id,receipt_kind,
      contract_version,lease_manifest_sha256,seal_receipt_sha256,receipt_sha256,canonical_document,issued_at,verified_at)
    VALUES (v_cleanup_receipt_id,p_operation_id,p_run_id,v_operation.lease_id,'credential_cleanup',
      'cutover-credential-cleanup-receipt.v1',v_operation.lease_manifest_sha256,p_seal_receipt_sha256,p_cleanup_receipt_sha256,v_cleanup,v_cleanup_issued_at,pg_catalog.clock_timestamp())
    ON CONFLICT DO NOTHING;
    IF NOT FOUND AND NOT EXISTS (SELECT 1 FROM platform.cutover_credential_receipts AS receipt
       WHERE receipt.receipt_id=v_cleanup_receipt_id AND receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id
         AND receipt.lease_id=v_operation.lease_id AND receipt.receipt_kind='credential_cleanup'
         AND receipt.contract_version='cutover-credential-cleanup-receipt.v1' AND receipt.lease_manifest_sha256=v_operation.lease_manifest_sha256
         AND receipt.seal_receipt_sha256=p_seal_receipt_sha256 AND receipt.receipt_sha256=p_cleanup_receipt_sha256
         AND receipt.canonical_document=v_cleanup AND receipt.issued_at=v_cleanup_issued_at) THEN
        RAISE EXCEPTION USING ERRCODE='22000', MESSAGE='cutover credential cleanup receipt replay differs';
    END IF;
END;
$_$;


ALTER FUNCTION cutover_authority.record_credential_receipts_v1(p_operation_id uuid, p_run_id uuid, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea) OWNER TO harpy_owner;

--
-- Name: record_full_rollout_completion_v1(uuid, uuid, uuid, text, text, text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.record_full_rollout_completion_v1(p_receipt_id uuid, p_environment_id uuid, p_tenant_id uuid, p_evidence_sha256 text, p_shadow_read_sha256 text, p_logical_delta_sha256 text, p_reconcile_sha256 text, p_production_snapshot_sha256 text, p_v1_removal_sha256 text, p_backup_restore_sha256 text, p_frontend_contract_sha256 text, p_rollback_window_closure_sha256 text, p_last_legacy_hit_at timestamp with time zone, p_rollback_window_closed_at timestamp with time zone, p_recorded_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_domain_count integer;
    v_group_count integer;
    v_member_count integer;
    v_persisted_sha256 text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cluster_admin' OR
       p_receipt_id IS NULL OR p_environment_id IS NULL OR p_tenant_id IS NULL OR
       p_environment_id=p_tenant_id OR
       p_environment_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_tenant_id='00000000-0000-0000-0000-000000000000'::uuid OR
       NOT pg_catalog.isfinite(p_last_legacy_hit_at) OR
       NOT pg_catalog.isfinite(p_rollback_window_closed_at) OR
       NOT pg_catalog.isfinite(p_recorded_at) OR
       p_last_legacy_hit_at > p_recorded_at - interval '30 days' OR
       p_rollback_window_closed_at > p_recorded_at OR
       p_rollback_window_closed_at < p_last_legacy_hit_at OR
       p_recorded_at < pg_catalog.transaction_timestamp() - interval '5 minutes' OR
       p_recorded_at > pg_catalog.clock_timestamp() + interval '5 seconds' OR EXISTS (
        SELECT 1 FROM pg_catalog.unnest(ARRAY[
            p_evidence_sha256,p_shadow_read_sha256,p_logical_delta_sha256,
            p_reconcile_sha256,p_production_snapshot_sha256,p_v1_removal_sha256,
            p_backup_restore_sha256,p_frontend_contract_sha256,
            p_rollback_window_closure_sha256
        ]) AS supplied(value) WHERE supplied.value !~ '^[0-9a-f]{64}$'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P57F0',
            MESSAGE='full rollout completion input denied';
    END IF;
    PERFORM 1
    FROM platform.domain_cutovers AS domain_row
    WHERE (domain_row.scope_kind='global' AND
           domain_row.scope_id=p_environment_id AND domain_row.domain='billing')
       OR (domain_row.scope_kind='tenant' AND
           domain_row.scope_id=p_tenant_id AND domain_row.domain IN (
               'iam','system_resource_layout','billing','workflow',
               'analytics','catalog','work','documents','notifications'
           ))
    ORDER BY domain_row.scope_kind,domain_row.domain
    FOR SHARE;
    GET DIAGNOSTICS v_domain_count = ROW_COUNT;
    IF v_domain_count IS DISTINCT FROM 10 OR EXISTS (
        SELECT 1 FROM platform.domain_cutovers AS domain_row
        WHERE ((domain_row.scope_kind='global' AND
                domain_row.scope_id=p_environment_id AND domain_row.domain='billing')
           OR (domain_row.scope_kind='tenant' AND
               domain_row.scope_id=p_tenant_id AND domain_row.domain IN (
                   'iam','system_resource_layout','billing','workflow',
                   'analytics','catalog','work','documents','notifications'
               )))
          AND (domain_row.state IS DISTINCT FROM 'v2' OR
               domain_row.writer IS DISTINCT FROM 'v2' OR
               domain_row.approved_by IS NULL OR
               domain_row.approved_by=domain_row.requested_by OR
               domain_row.acceptance_digest IS NULL OR
               domain_row.changed_at > p_recorded_at)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P57F1',
            MESSAGE='full rollout domain authority differs';
    END IF;
    PERFORM 1
    FROM platform.cutover_groups AS cutover_group
    WHERE cutover_group.scope_kind='tenant'
      AND cutover_group.scope_id=p_tenant_id
      AND cutover_group.group_id IN ('billing','iam_system_resources')
    ORDER BY cutover_group.group_id
    FOR SHARE;
    GET DIAGNOSTICS v_group_count = ROW_COUNT;
    IF v_group_count IS DISTINCT FROM 2 OR EXISTS (
        SELECT 1 FROM platform.cutover_groups AS cutover_group
        WHERE cutover_group.scope_kind='tenant'
          AND cutover_group.scope_id=p_tenant_id
          AND cutover_group.group_id IN ('billing','iam_system_resources')
          AND (cutover_group.state IS DISTINCT FROM 'v2' OR
               cutover_group.writer IS DISTINCT FROM 'v2' OR
               cutover_group.approved_by IS NULL OR
               cutover_group.approved_by=cutover_group.requested_by OR
               cutover_group.acceptance_digest IS NULL OR
               cutover_group.changed_at > p_recorded_at)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P57F2',
            MESSAGE='full rollout group authority differs';
    END IF;
    PERFORM 1
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind='tenant' AND member.scope_id=p_tenant_id
      AND member.group_id IN ('billing','iam_system_resources')
    ORDER BY member.group_id,member.ordinal
    FOR SHARE;
    GET DIAGNOSTICS v_member_count = ROW_COUNT;
    IF v_member_count IS DISTINCT FROM 3 OR
       (SELECT pg_catalog.jsonb_agg(member.domain ORDER BY member.ordinal)
        FROM platform.cutover_group_members AS member
        WHERE member.scope_kind='tenant' AND member.scope_id=p_tenant_id
          AND member.group_id='billing') IS DISTINCT FROM
          '["billing"]'::jsonb OR
       (SELECT pg_catalog.jsonb_agg(member.domain ORDER BY member.ordinal)
        FROM platform.cutover_group_members AS member
        WHERE member.scope_kind='tenant' AND member.scope_id=p_tenant_id
          AND member.group_id='iam_system_resources') IS DISTINCT FROM
          '["iam","system_resource_layout"]'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='P57F3',
            MESSAGE='full rollout group members differ';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.contract_retirements AS retirement
        WHERE retirement.state IS DISTINCT FROM 'retired' OR
              retirement.remaining_scope_count IS DISTINCT FROM 0 OR
              retirement.zero_hit_since IS NULL OR
              retirement.zero_hit_since > p_recorded_at - interval '30 days' OR
              retirement.last_hit_at > p_recorded_at - interval '30 days'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P57F4',
            MESSAGE='full rollout legacy retirement is incomplete';
    END IF;
    INSERT INTO cutover_authority.full_rollout_completion_receipts (
        receipt_id,environment_id,tenant_id,evidence_sha256,
        shadow_read_sha256,logical_delta_sha256,reconcile_sha256,
        production_snapshot_sha256,v1_removal_sha256,backup_restore_sha256,
        frontend_contract_sha256,rollback_window_closure_sha256,
        legacy_route_hits,v1_writers,v1_consumers,v1_queue_messages,v1_credentials,
        last_legacy_hit_at,rollback_window_closed_at,recorded_at,recorded_by
    ) VALUES (
        p_receipt_id,p_environment_id,p_tenant_id,
        pg_catalog.decode(p_evidence_sha256,'hex'),
        pg_catalog.decode(p_shadow_read_sha256,'hex'),
        pg_catalog.decode(p_logical_delta_sha256,'hex'),
        pg_catalog.decode(p_reconcile_sha256,'hex'),
        pg_catalog.decode(p_production_snapshot_sha256,'hex'),
        pg_catalog.decode(p_v1_removal_sha256,'hex'),
        pg_catalog.decode(p_backup_restore_sha256,'hex'),
        pg_catalog.decode(p_frontend_contract_sha256,'hex'),
        pg_catalog.decode(p_rollback_window_closure_sha256,'hex'),
        0,0,0,0,0,p_last_legacy_hit_at,p_rollback_window_closed_at,
        p_recorded_at,SESSION_USER
    ) ON CONFLICT (receipt_id) DO NOTHING;
    SELECT pg_catalog.encode(receipt.evidence_sha256,'hex')
    INTO v_persisted_sha256
    FROM cutover_authority.full_rollout_completion_receipts AS receipt
    WHERE receipt.receipt_id=p_receipt_id
      AND receipt.environment_id=p_environment_id AND receipt.tenant_id=p_tenant_id
      AND receipt.evidence_sha256=pg_catalog.decode(p_evidence_sha256,'hex')
      AND ARRAY[receipt.shadow_read_sha256,receipt.logical_delta_sha256,
                receipt.reconcile_sha256,receipt.production_snapshot_sha256,
                receipt.v1_removal_sha256,receipt.backup_restore_sha256,
                receipt.frontend_contract_sha256,
                receipt.rollback_window_closure_sha256] =
          ARRAY[pg_catalog.decode(p_shadow_read_sha256,'hex'),
                pg_catalog.decode(p_logical_delta_sha256,'hex'),
                pg_catalog.decode(p_reconcile_sha256,'hex'),
                pg_catalog.decode(p_production_snapshot_sha256,'hex'),
                pg_catalog.decode(p_v1_removal_sha256,'hex'),
                pg_catalog.decode(p_backup_restore_sha256,'hex'),
                pg_catalog.decode(p_frontend_contract_sha256,'hex'),
                pg_catalog.decode(p_rollback_window_closure_sha256,'hex')]
      AND receipt.last_legacy_hit_at=p_last_legacy_hit_at
      AND receipt.rollback_window_closed_at=p_rollback_window_closed_at
      AND receipt.recorded_at=p_recorded_at;
    IF v_persisted_sha256 IS DISTINCT FROM p_evidence_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P57F5',
            MESSAGE='full rollout completion replay differs';
    END IF;
    RETURN v_persisted_sha256;
END;
$_$;


ALTER FUNCTION cutover_authority.record_full_rollout_completion_v1(p_receipt_id uuid, p_environment_id uuid, p_tenant_id uuid, p_evidence_sha256 text, p_shadow_read_sha256 text, p_logical_delta_sha256 text, p_reconcile_sha256 text, p_production_snapshot_sha256 text, p_v1_removal_sha256 text, p_backup_restore_sha256 text, p_frontend_contract_sha256 text, p_rollback_window_closure_sha256 text, p_last_legacy_hit_at timestamp with time zone, p_rollback_window_closed_at timestamp with time zone, p_recorded_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: validate_finalization_envelope_v1(uuid, uuid, uuid, text, bytea, text, bytea, text, bytea, text, bytea, text, bytea, text, text, bytea); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.validate_finalization_envelope_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_cluster pg_catalog.pg_roles%ROWTYPE;
    v_finalizer jsonb;
    v_adoption jsonb;
    v_seal jsonb;
    v_cleanup jsonb;
    v_live_relations jsonb;
    v_target jsonb;
    v_state_sha256 text;
    v_live_oid oid; v_system_identifier text;
    v_database_oid oid;
    v_database_origin text;
BEGIN
    IF SESSION_USER NOT IN ('harpy_cluster_admin','harpy_cutover_finalizer') OR
       p_operation_id IS NULL OR p_run_id IS NULL OR p_finalizer_lease_id IS NULL OR
       p_terminal_state NOT IN ('completed','failed','cancelled') OR
       p_finalizer_lease_sha256 IS NULL OR p_finalizer_lease_sha256!~'^[0-9a-f]{64}$' OR
       p_adoption_lease_sha256 IS NULL OR p_adoption_lease_sha256!~'^[0-9a-f]{64}$' OR
       p_seal_receipt_sha256 IS NULL OR p_seal_receipt_sha256!~'^[0-9a-f]{64}$' OR
       p_cleanup_receipt_sha256 IS NULL OR p_cleanup_receipt_sha256!~'^[0-9a-f]{64}$' OR
       p_authority_receipt_sha256 IS NULL OR p_authority_receipt_sha256!~'^[0-9a-f]{64}$' OR
       p_terminal_evidence_sha256 IS NULL OR p_terminal_evidence_sha256!~'^[0-9a-f]{64}$' OR
       p_finalizer_lease_document IS NULL OR pg_catalog.octet_length(p_finalizer_lease_document) NOT BETWEEN 2 AND 65536 OR
       p_adoption_lease_document IS NULL OR pg_catalog.octet_length(p_adoption_lease_document) NOT BETWEEN 2 AND 16777216 OR
       p_seal_receipt_document IS NULL OR pg_catalog.octet_length(p_seal_receipt_document) NOT BETWEEN 2 AND 65536 OR
       p_cleanup_receipt_document IS NULL OR pg_catalog.octet_length(p_cleanup_receipt_document) NOT BETWEEN 2 AND 65536 OR
       p_authority_receipt_document IS NULL OR pg_catalog.octet_length(p_authority_receipt_document) NOT BETWEEN 2 AND 16777216 OR
       p_terminal_evidence_document IS NULL OR pg_catalog.octet_length(p_terminal_evidence_document) NOT BETWEEN 2 AND 16777216 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover finalization envelope input is invalid';
    END IF;
    IF pg_catalog.encode(pg_catalog.sha256(p_finalizer_lease_document),'hex') IS DISTINCT FROM p_finalizer_lease_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_adoption_lease_document),'hex') IS DISTINCT FROM p_adoption_lease_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_seal_receipt_document),'hex') IS DISTINCT FROM p_seal_receipt_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_cleanup_receipt_document),'hex') IS DISTINCT FROM p_cleanup_receipt_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_authority_receipt_document),'hex') IS DISTINCT FROM p_authority_receipt_sha256 OR
       pg_catalog.encode(pg_catalog.sha256(p_terminal_evidence_document),'hex') IS DISTINCT FROM p_terminal_evidence_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22000', MESSAGE='cutover finalization envelope digest differs';
    END IF;
    v_finalizer:=pg_catalog.convert_from(p_finalizer_lease_document,'UTF8')::jsonb; v_adoption:=pg_catalog.convert_from(p_adoption_lease_document,'UTF8')::jsonb;
    v_seal:=pg_catalog.convert_from(p_seal_receipt_document,'UTF8')::jsonb; v_cleanup:=pg_catalog.convert_from(p_cleanup_receipt_document,'UTF8')::jsonb;
    v_state_sha256:=cutover_authority.finalization_state_sha256_v1(p_operation_id,p_run_id);
    SELECT operation.* INTO STRICT v_operation FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    SELECT role.* INTO STRICT v_cluster FROM pg_catalog.pg_roles AS role
    WHERE role.rolname='harpy_cluster_admin' AND role.rolcanlogin AND NOT role.rolinherit
      AND NOT role.rolsuper AND role.rolcreatedb AND role.rolcreaterole AND NOT role.rolreplication
      AND NOT role.rolbypassrls AND role.rolconnlimit=1 AND role.rolvaliduntil>pg_catalog.clock_timestamp()
      AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
          WHERE membership.roleid=role.oid OR membership.member=role.oid);
    SELECT release_row.database_origin,control.system_identifier::text,database_row.oid
    INTO STRICT v_database_origin,v_system_identifier,v_database_oid
    FROM platform.release_generations AS release_row CROSS JOIN pg_catalog.pg_control_system() AS control
    CROSS JOIN pg_catalog.pg_database AS database_row
    WHERE release_row.release_id=v_operation.release_id AND release_row.environment_id=v_operation.environment_id
      AND database_row.datname=pg_catalog.current_database();
    v_target:=pg_catalog.jsonb_build_object('database_name',pg_catalog.current_database(),
        'database_origin',v_database_origin,'system_identifier',v_system_identifier,
        'database_oid',v_database_oid::bigint);
    v_live_oid:='cutover_authority.finalize_operation_v1(uuid,uuid,uuid,text,bytea,text,bytea,text,bytea,text,bytea,text,bytea,text,text,bytea)'::regprocedure::oid;
    IF pg_catalog.jsonb_typeof(v_finalizer) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_finalizer)) IS DISTINCT FROM 22::bigint OR
       (v_finalizer ?& ARRAY['contract_version','lease_id','release_id','environment_id','operation_id','run_id','issued_at','not_before','expires_at','max_duration_seconds','role_lease','target','adoption_lease_sha256','cleanup_receipt_sha256','authority_adoption_receipt_sha256','finalization_state_sha256','tenant_requirement_catalog_sha256','tenant_requirement_count','finalization_procedure_oid','finalization_procedure_signature','terminal_state','terminal_evidence_sha256']) IS DISTINCT FROM true OR
       v_finalizer->>'contract_version' IS DISTINCT FROM 'cutover-finalizer-lease.v1' OR
       (v_finalizer->>'lease_id')::uuid IS DISTINCT FROM p_finalizer_lease_id OR
       (v_finalizer->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (v_finalizer->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       (v_finalizer->>'release_id')::uuid IS DISTINCT FROM v_operation.release_id OR
       (v_finalizer->>'environment_id')::uuid IS DISTINCT FROM v_operation.environment_id OR
       v_finalizer->>'adoption_lease_sha256' IS DISTINCT FROM p_adoption_lease_sha256 OR
       v_finalizer->>'cleanup_receipt_sha256' IS DISTINCT FROM p_cleanup_receipt_sha256 OR
       v_finalizer->>'authority_adoption_receipt_sha256' IS DISTINCT FROM p_authority_receipt_sha256 OR
       v_finalizer->>'finalization_state_sha256' IS DISTINCT FROM v_state_sha256 OR
       v_finalizer->>'terminal_state' IS DISTINCT FROM p_terminal_state OR
       v_finalizer->>'terminal_evidence_sha256' IS DISTINCT FROM p_terminal_evidence_sha256 OR
       v_finalizer->'role_lease' IS DISTINCT FROM '{"principal":"harpy_cutover_finalizer","login":true,"replication":false,"connection_limit":1,"password_state":"leased_secret"}'::jsonb OR
       v_finalizer->'target' IS DISTINCT FROM v_target OR
       (v_finalizer->>'finalization_procedure_oid')::oid IS DISTINCT FROM v_live_oid OR
       v_finalizer->>'finalization_procedure_signature' IS DISTINCT FROM 'cutover_authority.finalize_operation_v1(uuid,uuid,uuid,text,bytea,text,bytea,text,bytea,text,bytea,text,bytea,text,text,bytea)' OR
       v_finalizer->>'max_duration_seconds' IS DISTINCT FROM '120' OR
       (v_finalizer->>'issued_at')::timestamptz>(v_finalizer->>'not_before')::timestamptz OR
       (v_finalizer->>'not_before')::timestamptz>pg_catalog.clock_timestamp() OR
       (v_finalizer->>'expires_at')::timestamptz<=pg_catalog.clock_timestamp() OR
       (v_finalizer->>'expires_at')::timestamptz-(v_finalizer->>'issued_at')::timestamptz>interval '120 seconds' OR
       (v_finalizer->>'expires_at')::timestamptz-(v_finalizer->>'not_before')::timestamptz>interval '120 seconds' OR
       (v_finalizer->>'expires_at')::timestamptz>v_cluster.rolvaliduntil OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
          WHERE role.rolname='harpy_cutover_finalizer' AND role.rolcanlogin AND NOT role.rolinherit
            AND NOT role.rolsuper AND NOT role.rolcreatedb AND NOT role.rolcreaterole
            AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=1
            AND role.rolvaliduntil IS NOT DISTINCT FROM (v_finalizer->>'expires_at')::timestamptz
            AND role.rolvaliduntil>pg_catalog.clock_timestamp() AND NOT EXISTS
              (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
               WHERE membership.roleid=role.oid OR membership.member=role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover finalizer lease differs';
    END IF;
    IF (p_terminal_state='completed' AND NOT EXISTS (SELECT 1
        FROM platform.release_generations AS release_row
        JOIN platform.tenant_migration_requirement_catalogs AS catalog
          ON catalog.migration_run_id=release_row.migration_run_id AND catalog.release_id=release_row.release_id
         AND catalog.environment_id=release_row.environment_id AND catalog.database_origin=release_row.database_origin
        WHERE release_row.release_id=v_operation.release_id AND release_row.environment_id=v_operation.environment_id
          AND catalog.catalog_sha256=v_finalizer->>'tenant_requirement_catalog_sha256'
          AND catalog.requirement_count=(v_finalizer->>'tenant_requirement_count')::integer)) OR
       (p_terminal_state IN ('failed','cancelled') AND
        (v_finalizer->'tenant_requirement_catalog_sha256' IS DISTINCT FROM 'null'::jsonb OR
         v_finalizer->'tenant_requirement_count' IS DISTINCT FROM 'null'::jsonb)) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover tenant authority lease differs';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordinal',relation.ordinal,
        'source',pg_catalog.jsonb_build_object('schema_oid',relation.source_schema_oid,'relation_oid',relation.source_relation_oid,'schema_name',relation.source_schema_name,'relation_name',relation.source_relation_name),
        'target',pg_catalog.jsonb_build_object('schema_oid',relation.target_schema_oid,'relation_oid',relation.target_relation_oid,'schema_name',relation.target_schema_name,'relation_name',relation.target_relation_name),
        'replica_identity',relation.replica_identity,'columns',(SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordinal',column_row.ordinal,'source_attnum',column_row.source_attnum,'target_attnum',column_row.target_attnum,'transform_id',column_row.transform_id,'primary_key',column_row.primary_key) ORDER BY column_row.ordinal) FROM platform.cutover_operation_columns AS column_row WHERE column_row.operation_id=p_operation_id AND column_row.run_id=p_run_id AND column_row.relation_ordinal=relation.ordinal),
        'procedure_contract_id',procedure_row.procedure_contract_id,'apply_procedure_oid',procedure_row.procedure_oid,'apply_procedure_signature',procedure_row.procedure_signature,
        'expected_checkpoint_keys',(SELECT pg_catalog.jsonb_agg(checkpoint_key.checkpoint_key ORDER BY checkpoint_key.ordinal) FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key WHERE checkpoint_key.operation_id=p_operation_id AND checkpoint_key.run_id=p_run_id AND checkpoint_key.relation_ordinal=relation.ordinal)) ORDER BY relation.ordinal),'[]'::jsonb)
    INTO v_live_relations FROM platform.cutover_operation_relations AS relation
    JOIN platform.cutover_operation_procedures AS procedure_row ON procedure_row.operation_id=relation.operation_id AND procedure_row.run_id=relation.run_id AND procedure_row.relation_ordinal=relation.ordinal AND procedure_row.procedure_kind='apply'
    WHERE relation.operation_id=p_operation_id AND relation.run_id=p_run_id;
    IF pg_catalog.jsonb_typeof(v_adoption) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_adoption)) IS DISTINCT FROM 24::bigint OR
       (v_adoption ?& ARRAY['contract_version','lease_id','release_id','environment_id','operation_id','run_id','issued_at','not_before','expires_at','max_duration_seconds','scope_kind','scope_id','group_id','domains','plan_sha256','transform_manifest_sha256','source','target','publication_name','slot_name','source_connection_limit','target_connection_limit','role_leases','relations']) IS DISTINCT FROM true OR
       v_adoption->>'contract_version' IS DISTINCT FROM 'cutover-credential-lease.v1' OR
       (v_adoption->>'lease_id')::uuid IS DISTINCT FROM v_operation.lease_id OR
       (v_adoption->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (v_adoption->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       (v_adoption->>'release_id')::uuid IS DISTINCT FROM v_operation.release_id OR
       (v_adoption->>'environment_id')::uuid IS DISTINCT FROM v_operation.environment_id OR
       v_adoption->>'scope_kind' IS DISTINCT FROM v_operation.scope_kind OR
       (v_adoption->>'scope_id')::uuid IS DISTINCT FROM v_operation.scope_id OR
       v_adoption->>'group_id' IS DISTINCT FROM v_operation.group_id OR
       (v_adoption->'domains' ? v_operation.domain) IS DISTINCT FROM true OR
       v_adoption->>'plan_sha256' IS DISTINCT FROM v_operation.plan_sha256 OR
       v_adoption->>'transform_manifest_sha256' IS DISTINCT FROM v_operation.transform_manifest_sha256 OR
       v_adoption->'source' IS DISTINCT FROM v_target OR v_adoption->'target' IS DISTINCT FROM v_target OR
       v_adoption->>'publication_name' IS DISTINCT FROM v_operation.publication_name OR
       v_adoption->>'slot_name' IS DISTINCT FROM v_operation.slot_name OR
       (v_adoption->>'expires_at')::timestamptz IS DISTINCT FROM v_operation.lease_expires_at OR
       v_adoption->'relations' IS DISTINCT FROM v_live_relations OR
       p_adoption_lease_sha256 IS DISTINCT FROM v_operation.lease_manifest_sha256 OR
       EXISTS (SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key
          WHERE checkpoint_key.operation_id=p_operation_id AND checkpoint_key.run_id=p_run_id
          GROUP BY checkpoint_key.relation_ordinal HAVING pg_catalog.min(checkpoint_key.ordinal)<>1
            OR pg_catalog.max(checkpoint_key.ordinal)<>pg_catalog.count(*)
            OR pg_catalog.count(DISTINCT checkpoint_key.ordinal)<>pg_catalog.count(*)) OR
       (SELECT pg_catalog.count(*) FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key
          WHERE checkpoint_key.operation_id=p_operation_id AND checkpoint_key.run_id=p_run_id)>10000 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover adoption projection differs';
    END IF;
    IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_seal)) IS DISTINCT FROM 4::bigint OR
       (v_seal ?& ARRAY['contract_version','kind','payload','signature']) IS DISTINCT FROM true OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_seal->'payload')) IS DISTINCT FROM 13::bigint OR
       (v_seal->'payload' ?& ARRAY['receipt_id','lease_id','lease_manifest_sha256','environment_id','operation_id','run_id','issued_at','source','target','credentials','source_sessions','target_sessions','result']) IS DISTINCT FROM true OR
       v_seal->>'contract_version' IS DISTINCT FROM 'cutover-session-seal-receipt.v1' OR v_seal->>'kind' IS DISTINCT FROM 'cutover_session_seal' OR
       v_seal->'payload'->>'lease_id' IS DISTINCT FROM v_operation.lease_id::text OR v_seal->'payload'->>'operation_id' IS DISTINCT FROM p_operation_id::text OR
       v_seal->'payload'->>'run_id' IS DISTINCT FROM p_run_id::text OR v_seal->'payload'->>'environment_id' IS DISTINCT FROM v_operation.environment_id::text OR
       v_seal->'payload'->>'lease_manifest_sha256' IS DISTINCT FROM p_adoption_lease_sha256 OR v_seal->'payload'->'source' IS DISTINCT FROM v_target OR
       v_seal->'payload'->'target' IS DISTINCT FROM v_target OR v_seal->'payload'->>'result' IS DISTINCT FROM 'sealed' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_cleanup)) IS DISTINCT FROM 4::bigint OR
       (v_cleanup ?& ARRAY['contract_version','kind','payload','signature']) IS DISTINCT FROM true OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_cleanup->'payload')) IS DISTINCT FROM 10::bigint OR
       (v_cleanup->'payload' ?& ARRAY['receipt_id','lease_id','lease_manifest_sha256','seal_receipt_sha256','environment_id','operation_id','run_id','issued_at','principals','result']) IS DISTINCT FROM true OR
       v_cleanup->>'contract_version' IS DISTINCT FROM 'cutover-credential-cleanup-receipt.v1' OR v_cleanup->>'kind' IS DISTINCT FROM 'cutover_credential_cleanup' OR
       v_cleanup->'payload'->>'lease_id' IS DISTINCT FROM v_operation.lease_id::text OR v_cleanup->'payload'->>'operation_id' IS DISTINCT FROM p_operation_id::text OR
       v_cleanup->'payload'->>'run_id' IS DISTINCT FROM p_run_id::text OR v_cleanup->'payload'->>'environment_id' IS DISTINCT FROM v_operation.environment_id::text OR
       v_cleanup->'payload'->>'lease_manifest_sha256' IS DISTINCT FROM p_adoption_lease_sha256 OR v_cleanup->'payload'->>'seal_receipt_sha256' IS DISTINCT FROM p_seal_receipt_sha256 OR
       v_cleanup->'payload'->>'result' IS DISTINCT FROM 'succeeded' OR
       NOT EXISTS (SELECT 1 FROM platform.cutover_credential_receipts AS receipt WHERE receipt.receipt_id=(v_seal->'payload'->>'receipt_id')::uuid AND receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id AND receipt.lease_id=v_operation.lease_id AND receipt.receipt_kind='session_seal' AND receipt.lease_manifest_sha256=p_adoption_lease_sha256 AND receipt.receipt_sha256=p_seal_receipt_sha256 AND receipt.canonical_document IS NOT DISTINCT FROM v_seal) OR
       NOT EXISTS (SELECT 1 FROM platform.cutover_credential_receipts AS receipt WHERE receipt.receipt_id=(v_cleanup->'payload'->>'receipt_id')::uuid AND receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id AND receipt.lease_id=v_operation.lease_id AND receipt.receipt_kind='credential_cleanup' AND receipt.lease_manifest_sha256=p_adoption_lease_sha256 AND receipt.seal_receipt_sha256=p_seal_receipt_sha256 AND receipt.receipt_sha256=p_cleanup_receipt_sha256 AND receipt.canonical_document IS NOT DISTINCT FROM v_cleanup) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover cleanup evidence differs';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role WHERE role.rolname IN ('harpy_cutover_decoder','harpy_adopter')
        AND NOT role.rolcanlogin AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
        AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls AND role.rolconnlimit=0
        AND role.rolvaliduntil IS NOT DISTINCT FROM 'infinity'::timestamptz
        AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership WHERE membership.roleid=role.oid OR membership.member=role.oid)
        HAVING pg_catalog.count(*)=2) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover cleanup role state differs';
    END IF;
    PERFORM cutover_authority.assert_adopted_catalog_v1(p_authority_receipt_sha256);
    IF NOT EXISTS (SELECT 1 FROM cutover_authority.authority_adoption_inventory AS inventory
        WHERE inventory.receipt_sha256=p_authority_receipt_sha256 AND inventory.receipt_document=p_authority_receipt_document) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='cutover authority receipt bytes differ';
    END IF;
    PERFORM cutover_authority.assert_terminal_evidence_v1(p_operation_id,p_run_id,p_terminal_state,p_terminal_evidence_document);
END;
$_$;


ALTER FUNCTION cutover_authority.validate_finalization_envelope_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_finalizer_lease_sha256 text, p_finalizer_lease_document bytea, p_adoption_lease_sha256 text, p_adoption_lease_document bytea, p_seal_receipt_sha256 text, p_seal_receipt_document bytea, p_cleanup_receipt_sha256 text, p_cleanup_receipt_document bytea, p_authority_receipt_sha256 text, p_authority_receipt_document bytea, p_terminal_state text, p_terminal_evidence_sha256 text, p_terminal_evidence_document bytea) OWNER TO harpy_owner;

--
-- Name: verify_finalization_receipt_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: cutover_authority; Owner: harpy_owner
--

CREATE FUNCTION cutover_authority.verify_finalization_receipt_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_terminal_state text, p_terminal_evidence_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_receipt cutover_authority.finalization_receipts%ROWTYPE;
    v_authorization cutover_authority.finalization_authorizations%ROWTYPE;
    v_finalizer jsonb;
    v_catalog jsonb;
    v_current_generation integer;
    v_current_receipt_sha256 text;
    v_bound_generation integer;
    v_inventory_count bigint;
    v_valid_chain_count bigint;
BEGIN
    IF SESSION_USER <> 'harpy_cutover_finalizer' OR p_operation_id IS NULL OR
       p_run_id IS NULL OR p_finalizer_lease_id IS NULL OR
       p_terminal_state NOT IN ('completed','failed','cancelled') OR
       p_terminal_evidence_sha256 IS NULL OR p_terminal_evidence_sha256!~'^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='cutover finalization receipt verifier denied';
    END IF;
    SELECT receipt.* INTO STRICT v_receipt FROM cutover_authority.finalization_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id AND receipt.run_id=p_run_id
      AND receipt.finalizer_lease_id=p_finalizer_lease_id
      AND receipt.terminal_state=p_terminal_state
      AND receipt.terminal_evidence_sha256=p_terminal_evidence_sha256;
    SELECT authorization_row.* INTO STRICT v_authorization
    FROM cutover_authority.finalization_authorizations AS authorization_row
    WHERE authorization_row.operation_id=p_operation_id AND authorization_row.run_id=p_run_id
      AND authorization_row.finalizer_lease_id=p_finalizer_lease_id;
    IF v_receipt.finalizer_lease_id IS DISTINCT FROM v_authorization.finalizer_lease_id OR
       v_receipt.finalizer_lease_sha256 IS DISTINCT FROM v_authorization.finalizer_lease_sha256 OR
       v_receipt.finalizer_lease_document IS DISTINCT FROM v_authorization.finalizer_lease_document OR
       v_receipt.adoption_lease_sha256 IS DISTINCT FROM v_authorization.adoption_lease_sha256 OR
       v_receipt.adoption_lease_document IS DISTINCT FROM v_authorization.adoption_lease_document OR
       v_receipt.seal_receipt_sha256 IS DISTINCT FROM v_authorization.seal_receipt_sha256 OR
       v_receipt.seal_receipt_document IS DISTINCT FROM v_authorization.seal_receipt_document OR
       v_receipt.cleanup_receipt_sha256 IS DISTINCT FROM v_authorization.cleanup_receipt_sha256 OR
       v_receipt.cleanup_receipt_document IS DISTINCT FROM v_authorization.cleanup_receipt_document OR
       v_receipt.authority_receipt_sha256 IS DISTINCT FROM v_authorization.authority_receipt_sha256 OR
       v_receipt.authority_receipt_document IS DISTINCT FROM v_authorization.authority_receipt_document OR
       v_receipt.terminal_state IS DISTINCT FROM v_authorization.terminal_state OR
       v_receipt.terminal_evidence_sha256 IS DISTINCT FROM v_authorization.terminal_evidence_sha256 OR
       v_receipt.terminal_evidence_document IS DISTINCT FROM v_authorization.terminal_evidence_document OR
       v_receipt.finalization_state_sha256 IS DISTINCT FROM v_authorization.finalization_state_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover protected finalization receipt differs';
    END IF;
    v_finalizer:=pg_catalog.convert_from(v_receipt.finalizer_lease_document,'UTF8')::jsonb;
    IF p_terminal_state='completed' THEN
        v_catalog:=pg_catalog.convert_from(v_receipt.tenant_requirement_catalog_document,'UTF8')::jsonb;
        IF v_finalizer->>'tenant_requirement_catalog_sha256' IS DISTINCT FROM v_receipt.tenant_requirement_catalog_sha256 OR
            (v_finalizer->>'tenant_requirement_count')::integer IS DISTINCT FROM v_receipt.tenant_requirement_count OR
            pg_catalog.encode(pg_catalog.sha256(v_receipt.tenant_requirement_catalog_document),'hex')
              IS DISTINCT FROM v_receipt.tenant_requirement_catalog_sha256 OR
            pg_catalog.jsonb_typeof(v_catalog) IS DISTINCT FROM 'object' OR
            v_catalog->>'contract_version' IS DISTINCT FROM 'tenant-migration-requirement-catalog.v2' OR
            pg_catalog.jsonb_typeof(v_catalog->'requirements') IS DISTINCT FROM 'array' OR
            pg_catalog.jsonb_array_length(v_catalog->'requirements') IS DISTINCT FROM v_receipt.tenant_requirement_count OR
            pg_catalog.jsonb_typeof(v_catalog->'targets') IS DISTINCT FROM 'array' OR
            pg_catalog.jsonb_array_length(v_catalog->'targets') IS DISTINCT FROM v_receipt.tenant_target_count THEN
            RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover tenant finalization receipt differs';
        END IF;
    ELSIF v_receipt.tenant_requirement_catalog_sha256 IS NOT NULL OR
          v_receipt.tenant_requirement_catalog_document IS NOT NULL OR
          v_receipt.tenant_requirement_count IS NOT NULL OR v_receipt.tenant_target_count IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover abort finalization receipt differs';
    END IF;
    SELECT inventory.catalog_generation,inventory.receipt_sha256
    INTO STRICT v_current_generation,v_current_receipt_sha256
    FROM cutover_authority.authority_adoption_inventory AS inventory
    ORDER BY inventory.catalog_generation DESC LIMIT 1;
    PERFORM cutover_authority.assert_adopted_catalog_v1(v_current_receipt_sha256);
    SELECT inventory.catalog_generation INTO v_bound_generation
    FROM cutover_authority.authority_adoption_inventory AS inventory
    WHERE inventory.receipt_sha256=v_receipt.authority_receipt_sha256
      AND inventory.receipt_document=v_receipt.authority_receipt_document
      AND pg_catalog.encode(pg_catalog.sha256(inventory.receipt_document),'hex')=
          inventory.receipt_sha256;
    WITH decoded AS (
        SELECT inventory.*,
            pg_catalog.convert_from(inventory.receipt_document,'UTF8')::jsonb AS payload
        FROM cutover_authority.authority_adoption_inventory AS inventory
    ), linked AS (
        SELECT current_row.*,previous.receipt_sha256 AS prior_sha256,
            previous.catalog_contract_sha256 AS prior_contract_sha256,
            previous.receipt_id AS prior_receipt_id,
            previous.environment_id AS prior_environment_id,
            previous.catalog_generation AS prior_generation,
            previous.catalog_instance_sha256 AS prior_instance_sha256,
            previous.payload AS prior_payload
        FROM decoded AS current_row LEFT JOIN decoded AS previous
          ON previous.catalog_generation=current_row.catalog_generation-1
    )
    SELECT pg_catalog.count(*),pg_catalog.count(*) FILTER (WHERE
        pg_catalog.encode(pg_catalog.sha256(receipt_document),'hex')=receipt_sha256 AND
        payload->>'contract_version'='cutover-authority-adoption-receipt.v1' AND
        payload->>'result'='succeeded' AND
        (payload->>'catalog_generation')::integer=catalog_generation AND
        payload->>'receipt_id'=receipt_id::text AND
        payload->>'operation_id'=operation_id::text AND
        payload->>'operation_sha256'=operation_sha256 AND
        payload->>'release_id'=release_id::text AND
        payload->>'environment_id'=environment_id::text AND
        payload->'target'->>'database_name'=pg_catalog.current_database() AND
        payload->'target'->>'database_origin'=database_origin AND
        payload->'target'->>'system_identifier'=system_identifier::text AND
        payload->'target'->>'database_oid'=database_oid::text AND
        (payload->>'adopted_at')::timestamptz=adopted_at AND
        payload->>'post_catalog_contract_sha256'=catalog_contract_sha256 AND
        payload->>'catalog_instance_sha256'=catalog_instance_sha256 AND
        payload->>'dependency_contract_sha256'=dependency_contract_sha256 AND
        payload->>'dependency_instance_sha256'=dependency_instance_sha256 AND
        pg_catalog.jsonb_array_length(payload->'objects')=object_count AND
        pg_catalog.jsonb_array_length(payload->'dependencies')=dependency_count AND
        CASE WHEN catalog_generation=1 THEN
            payload->>'mode'='initial_adoption' AND
            (payload->>'previous_catalog_generation')::integer=0 AND
            payload->>'pre_catalog_contract_sha256'=
                'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' AND
            payload->'previous_authority_receipt_sha256'='null'::jsonb AND
            payload->'previous_catalog_checkpoint'='null'::jsonb
        ELSE payload->>'mode'='catalog_upgrade' AND
            (payload->>'previous_catalog_generation')::integer=catalog_generation-1 AND
            payload->>'previous_authority_receipt_sha256'=prior_sha256 AND
            payload->>'pre_catalog_contract_sha256'=prior_contract_sha256 AND
            (payload->>'adopted_at')::timestamptz>
                (prior_payload->>'adopted_at')::timestamptz AND
            pg_catalog.jsonb_array_length(payload->'objects')>
                pg_catalog.jsonb_array_length(prior_payload->'objects') AND
            NOT EXISTS (SELECT 1
                FROM pg_catalog.jsonb_array_elements(prior_payload->'objects')
                    WITH ORDINALITY AS prior_item(value,ordinal)
                LEFT JOIN pg_catalog.jsonb_array_elements(payload->'objects')
                    WITH ORDINALITY AS current_item(value,ordinal) USING (ordinal)
                WHERE current_item.value IS DISTINCT FROM prior_item.value) AND
            payload->'previous_catalog_checkpoint'=pg_catalog.jsonb_build_object(
                'receipt_sha256',prior_sha256,'receipt_id',prior_receipt_id,
                'environment_id',prior_environment_id,'target',prior_payload->'target',
                'catalog_generation',prior_generation,'adopted_at',prior_payload->>'adopted_at',
                'catalog_contract_sha256',prior_contract_sha256,
                'catalog_instance_sha256',prior_instance_sha256,
                'objects',prior_payload->'objects') END
    ) INTO v_inventory_count,v_valid_chain_count FROM linked;
    IF v_bound_generation IS NULL OR v_bound_generation>v_current_generation OR
       v_inventory_count IS DISTINCT FROM v_current_generation::bigint OR
       v_valid_chain_count IS DISTINCT FROM v_inventory_count THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='cutover authority receipt chain differs';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION cutover_authority.verify_finalization_receipt_v1(p_operation_id uuid, p_run_id uuid, p_finalizer_lease_id uuid, p_terminal_state text, p_terminal_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: analytics_assert_tenant_authority_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_assert_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_mode text;
    v_state text;
    v_writer text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.uuid_extract_version(p_authority_id) IS DISTINCT FROM 7 OR
       p_tenant_id IS NULL OR p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics authority assertion input is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        v_mode := 'runtime_v2'; v_state := 'v2'; v_writer := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        v_mode := 'adopter_shadow'; v_state := 'shadow'; v_writer := 'v1';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics authority assertion session is invalid';
    END IF;
    PERFORM 1
    FROM platform.analytics_tenant_authorities AS authority_row
    JOIN platform.tenants AS tenant ON tenant.id = authority_row.tenant_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = authority_row.scope_kind
     AND group_row.scope_id = authority_row.scope_id
     AND group_row.group_id = authority_row.authority_group_id
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = authority_row.scope_kind
     AND member_row.scope_id = authority_row.scope_id
     AND member_row.group_id = authority_row.authority_group_id
     AND member_row.domain = authority_row.authority_domain
     AND member_row.ordinal = 1
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = authority_row.scope_kind
     AND domain_row.scope_id = authority_row.scope_id
     AND domain_row.domain = authority_row.authority_domain
    WHERE authority_row.authority_id = p_authority_id
      AND authority_row.tenant_id = p_tenant_id
      AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND authority_row.scope_kind = 'tenant' AND authority_row.scope_id = p_tenant_id
      AND authority_row.authority_group_id = 'analytics'
      AND authority_row.authority_domain = 'analytics'
      AND authority_row.authority_mode = v_mode
      AND authority_row.authority_group_generation = group_row.generation
      AND authority_row.authority_domain_generation = domain_row.generation
      AND group_row.state = v_state AND group_row.writer = v_writer
      AND domain_row.state = v_state AND domain_row.writer = v_writer
    FOR SHARE OF authority_row, tenant, group_row, member_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics tenant authority is not current';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_assert_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_finalize_authority_successor_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_finalize_authority_successor_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_authority_id uuid;
    v_tenant_id uuid;
    v_created_at timestamptz;
    v_generation bigint;
    v_run_hash text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_cutover_finalizer' OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_run_id) IS DISTINCT FROM 7 OR
       p_acceptance_digest IS NULL OR
       p_acceptance_digest !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics successor authority input is invalid';
    END IF;
    SELECT tenant.id, group_row.generation, group_row.changed_at
    INTO v_tenant_id, v_generation, v_created_at
    FROM platform.cutover_operations AS operation
    JOIN platform.tenants AS tenant
      ON operation.scope_kind = 'tenant' AND tenant.id = operation.scope_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = operation.scope_kind
     AND group_row.scope_id = operation.scope_id
     AND group_row.group_id = operation.group_id
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.ordinal = 1 AND member_row.domain = 'analytics'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id
      AND operation.state = 'completed'
      AND operation.group_id = 'analytics' AND operation.domain = 'analytics'
      AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND group_row.state = 'v2' AND group_row.writer = 'v2'
      AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
      AND group_row.generation = operation.cutover_generation + 1
      AND domain_row.generation = operation.cutover_generation + 1
      AND group_row.acceptance_digest = p_acceptance_digest
      AND domain_row.acceptance_digest = p_acceptance_digest
      AND group_row.requested_by = domain_row.requested_by
      AND group_row.approved_by = domain_row.approved_by
      AND group_row.approved_by IS NOT NULL
      AND group_row.reason = domain_row.reason
      AND group_row.change_reference = domain_row.change_reference
      AND group_row.changed_at = domain_row.changed_at
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS extra
          WHERE extra.scope_kind = operation.scope_kind
            AND extra.scope_id = operation.scope_id
            AND extra.group_id = operation.group_id
            AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
      )
    FOR SHARE OF operation, tenant, group_row, member_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics successor authority evidence differs';
    END IF;
    v_run_hash := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(p_run_id::text, 'UTF8')
    ), 'hex');
    v_authority_id := (
        pg_catalog.substring(p_operation_id::text, 1, 19) || '8' ||
        pg_catalog.substring(v_run_hash, 1, 3) || '-' ||
        pg_catalog.substring(v_run_hash, 4, 12)
    )::uuid;
    INSERT INTO platform.analytics_tenant_authorities (
        authority_id, tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation,
        authority_domain, authority_domain_generation, authority_mode, created_at
    ) VALUES (
        v_authority_id, v_tenant_id, 'tenant', v_tenant_id,
        'analytics', v_generation, 'analytics', v_generation,
        'runtime_v2', v_created_at
    ) ON CONFLICT DO NOTHING;
    PERFORM 1 FROM platform.analytics_tenant_authorities AS authority_row
    WHERE authority_row.authority_id = v_authority_id
      AND authority_row.tenant_id = v_tenant_id
      AND authority_row.authority_group_generation = v_generation
      AND authority_row.authority_domain_generation = v_generation
      AND authority_row.authority_mode = 'runtime_v2'
      AND authority_row.created_at IS NOT DISTINCT FROM v_created_at;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics successor authority replay differs';
    END IF;
    RETURN v_authority_id;
END;
$_$;


ALTER FUNCTION platform.analytics_finalize_authority_successor_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) OWNER TO harpy_owner;

--
-- Name: analytics_guard_tenant_authority_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_guard_tenant_authority_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_mode text;
    v_state text;
    v_writer text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics tenant authority mutation is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        v_mode := 'runtime_v2'; v_state := 'v2'; v_writer := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        v_mode := 'adopter_shadow'; v_state := 'shadow'; v_writer := 'v1';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics tenant authority session is invalid';
    END IF;
    IF NEW.authority_mode IS DISTINCT FROM v_mode THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics tenant authority mode is invalid';
    END IF;
    PERFORM 1
    FROM platform.tenants AS tenant
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'tenant' AND group_row.scope_id = tenant.id
     AND group_row.group_id = 'analytics'
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.ordinal = 1 AND member_row.domain = 'analytics'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE tenant.id = NEW.tenant_id AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND NEW.scope_kind = 'tenant' AND NEW.scope_id = tenant.id
      AND NEW.authority_group_id = group_row.group_id
      AND NEW.authority_domain = domain_row.domain
      AND NEW.authority_group_generation = group_row.generation
      AND NEW.authority_domain_generation = domain_row.generation
      AND group_row.state = v_state AND group_row.writer = v_writer
      AND domain_row.state = v_state AND domain_row.writer = v_writer
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS extra
          WHERE extra.scope_kind = 'tenant' AND extra.scope_id = tenant.id
            AND extra.group_id = 'analytics'
            AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
      )
    FOR SHARE OF tenant, group_row, member_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics tenant authority binding is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.analytics_guard_tenant_authority_v1() OWNER TO harpy_owner;

--
-- Name: analytics_guard_tenant_authority_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_guard_tenant_authority_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_mode text;
    v_state text;
    v_writer text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics tenant authority mutation is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        v_mode := 'runtime_v2'; v_state := 'v2'; v_writer := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        v_mode := 'adopter_shadow'; v_state := 'shadow'; v_writer := 'v1';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_cutover_finalizer' THEN
        v_mode := 'runtime_v2'; v_state := 'v2'; v_writer := 'v2';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics tenant authority session is invalid';
    END IF;
    IF NEW.authority_mode IS DISTINCT FROM v_mode THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics tenant authority mode is invalid';
    END IF;
    PERFORM 1
    FROM platform.tenants AS tenant
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'tenant' AND group_row.scope_id = tenant.id
     AND group_row.group_id = 'analytics'
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.ordinal = 1 AND member_row.domain = 'analytics'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE tenant.id = NEW.tenant_id AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND NEW.scope_kind = 'tenant' AND NEW.scope_id = tenant.id
      AND NEW.authority_group_id = group_row.group_id
      AND NEW.authority_domain = domain_row.domain
      AND NEW.authority_group_generation = group_row.generation
      AND NEW.authority_domain_generation = domain_row.generation
      AND group_row.state = v_state AND group_row.writer = v_writer
      AND domain_row.state = v_state AND domain_row.writer = v_writer
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS extra
          WHERE extra.scope_kind = 'tenant' AND extra.scope_id = tenant.id
            AND extra.group_id = 'analytics'
            AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
      )
    FOR SHARE OF tenant, group_row, member_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics tenant authority binding is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.analytics_guard_tenant_authority_v2() OWNER TO harpy_owner;

--
-- Name: analytics_legacy_public_ack_consumers_v1(text, text, text, text, uuid, uuid, bytea, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_legacy_public_ack_consumers_v1(p_tenant_identity text, p_method text, p_path text, p_slug text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_public_id bytea, p_release_id uuid, p_inventory_sha256 bytea, p_acked_at timestamp with time zone) RETURNS TABLE(legacy_tenant_identity text, method text, path text, slug text, tenant_id uuid, legacy_endpoint_id uuid, public_id bytea, release_id uuid, state text, hit_count bigint, last_hit_at timestamp with time zone, consumers_acked_at timestamp with time zone, remove_after timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cluster_admin' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.octet_length(p_inventory_sha256) IS DISTINCT FROM 32 OR
       p_acked_at IS NULL OR NOT pg_catalog.isfinite(p_acked_at) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics consumer acknowledgement authority is invalid';
    END IF;
    RETURN QUERY
    UPDATE platform.analytics_legacy_public_routes AS route
       SET consumers_acked_at = p_acked_at,
           consumer_inventory_sha256 = p_inventory_sha256
    WHERE route.legacy_tenant_identity = p_tenant_identity
      AND route.method = p_method AND route.path = p_path AND route.slug = p_slug
      AND route.tenant_id = p_tenant_id
      AND route.legacy_endpoint_id = p_legacy_endpoint_id
      AND route.public_id IS NOT DISTINCT FROM p_public_id
      AND route.release_id = p_release_id AND route.state = 'active'
      AND (route.consumers_acked_at IS NULL OR (
          route.consumers_acked_at IS NOT DISTINCT FROM p_acked_at
          AND route.consumer_inventory_sha256 IS NOT DISTINCT FROM p_inventory_sha256
      ))
    RETURNING route.legacy_tenant_identity, route.method, route.path, route.slug,
              route.tenant_id, route.legacy_endpoint_id, route.public_id,
              route.release_id, route.state, route.hit_count, route.last_hit_at,
              route.consumers_acked_at, route.remove_after;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6103',
            MESSAGE = 'analytics consumer acknowledgement conflicts';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_legacy_public_ack_consumers_v1(p_tenant_identity text, p_method text, p_path text, p_slug text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_public_id bytea, p_release_id uuid, p_inventory_sha256 bytea, p_acked_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_legacy_public_record_hit_v1(text, text, text, text, uuid, uuid, bytea, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_legacy_public_record_hit_v1(p_tenant_identity text, p_method text, p_path text, p_slug text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_public_id bytea, p_release_id uuid, p_hit_at timestamp with time zone) RETURNS TABLE(legacy_tenant_identity text, method text, path text, slug text, tenant_id uuid, legacy_endpoint_id uuid, public_id bytea, release_id uuid, state text, hit_count bigint, last_hit_at timestamp with time zone, consumers_acked_at timestamp with time zone, remove_after timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_hit_at IS NULL OR NOT pg_catalog.isfinite(p_hit_at) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics legacy hit authority is invalid';
    END IF;
    RETURN QUERY
    UPDATE platform.analytics_legacy_public_routes AS route
       SET hit_count = route.hit_count + 1, last_hit_at = p_hit_at
    WHERE route.legacy_tenant_identity = p_tenant_identity
      AND route.method = p_method AND route.path = p_path AND route.slug = p_slug
      AND route.tenant_id = p_tenant_id
      AND route.legacy_endpoint_id = p_legacy_endpoint_id
      AND route.public_id IS NOT DISTINCT FROM p_public_id
      AND route.release_id = p_release_id AND route.state = 'active'
      AND EXISTS (
          SELECT 1 FROM platform.analytics_publications AS publication
          WHERE publication.public_id = route.public_id
            AND publication.tenant_id = route.tenant_id
            AND publication.release_id = route.release_id
            AND publication.state = 'active'
      )
    RETURNING route.legacy_tenant_identity, route.method, route.path, route.slug,
              route.tenant_id, route.legacy_endpoint_id, route.public_id,
              route.release_id, route.state, route.hit_count, route.last_hit_at,
              route.consumers_acked_at, route.remove_after;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'analytics legacy hit mapping was not found';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_legacy_public_record_hit_v1(p_tenant_identity text, p_method text, p_path text, p_slug text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_public_id bytea, p_release_id uuid, p_hit_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_legacy_public_resolve_v1(text, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_legacy_public_resolve_v1(p_tenant_identity text, p_method text, p_path text, p_slug text) RETURNS TABLE(legacy_tenant_identity text, method text, path text, slug text, tenant_id uuid, legacy_endpoint_id uuid, public_id bytea, release_id uuid, state text, hit_count bigint, last_hit_at timestamp with time zone, consumers_acked_at timestamp with time zone, remove_after timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics legacy resolver authority is invalid';
    END IF;
    RETURN QUERY
    SELECT route.legacy_tenant_identity, route.method, route.path, route.slug,
           route.tenant_id, route.legacy_endpoint_id, route.public_id,
           route.release_id, route.state, route.hit_count, route.last_hit_at,
           route.consumers_acked_at, route.remove_after
    FROM platform.analytics_legacy_public_routes AS route
    JOIN platform.analytics_publications AS publication
      ON publication.public_id = route.public_id
     AND publication.tenant_id = route.tenant_id
     AND publication.release_id = route.release_id
    WHERE route.legacy_tenant_identity = p_tenant_identity
      AND route.method = p_method AND route.path = p_path AND route.slug = p_slug
      AND route.state = 'active' AND publication.state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'analytics legacy mapping was not found';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_legacy_public_resolve_v1(p_tenant_identity text, p_method text, p_path text, p_slug text) OWNER TO harpy_owner;

--
-- Name: analytics_legacy_public_retire_v1(text, text, text, text, uuid, uuid, bytea, uuid, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_legacy_public_retire_v1(p_tenant_identity text, p_method text, p_path text, p_slug text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_public_id bytea, p_release_id uuid, p_evidence_sha256 bytea, p_observed_at timestamp with time zone, p_retired_at timestamp with time zone) RETURNS TABLE(legacy_tenant_identity text, method text, path text, slug text, tenant_id uuid, legacy_endpoint_id uuid, public_id bytea, release_id uuid, state text, hit_count bigint, last_hit_at timestamp with time zone, consumers_acked_at timestamp with time zone, remove_after timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cluster_admin' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.octet_length(p_evidence_sha256) IS DISTINCT FROM 32 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) OR
       p_retired_at IS NULL OR NOT pg_catalog.isfinite(p_retired_at) OR
       p_observed_at > p_retired_at OR
       p_retired_at - p_observed_at > INTERVAL '5 minutes' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics legacy retirement authority is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.tenants AS tenant
        LEFT JOIN platform.domain_cutovers AS cutover
          ON cutover.scope_kind = 'tenant' AND cutover.scope_id = tenant.id
         AND cutover.domain = 'analytics'
        WHERE tenant.deleted_at IS NULL
          AND (cutover.scope_id IS NULL OR cutover.state <> 'v2' OR cutover.writer <> 'v2')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6104',
            MESSAGE = 'analytics legacy retirement awaits tenant cutover';
    END IF;
    RETURN QUERY
    UPDATE platform.analytics_legacy_public_routes AS route
       SET state = 'retired', retirement_evidence_sha256 = p_evidence_sha256,
           retirement_observed_at = p_observed_at, retired_at = p_retired_at
    WHERE route.legacy_tenant_identity = p_tenant_identity
      AND route.method = p_method AND route.path = p_path AND route.slug = p_slug
      AND route.tenant_id = p_tenant_id
      AND route.legacy_endpoint_id = p_legacy_endpoint_id
      AND route.public_id IS NOT DISTINCT FROM p_public_id
      AND route.release_id = p_release_id AND route.state = 'active'
      AND route.consumers_acked_at IS NOT NULL
      AND route.consumer_inventory_sha256 IS NOT NULL
      AND route.remove_after <= p_retired_at
      AND (route.last_hit_at IS NULL
           OR route.last_hit_at <= p_retired_at - INTERVAL '30 days')
    RETURNING route.legacy_tenant_identity, route.method, route.path, route.slug,
              route.tenant_id, route.legacy_endpoint_id, route.public_id,
              route.release_id, route.state, route.hit_count, route.last_hit_at,
              route.consumers_acked_at, route.remove_after;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6104',
            MESSAGE = 'analytics legacy retirement gate is closed';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_legacy_public_retire_v1(p_tenant_identity text, p_method text, p_path text, p_slug text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_public_id bytea, p_release_id uuid, p_evidence_sha256 bytea, p_observed_at timestamp with time zone, p_retired_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_public_activate_v1(uuid, bytea, uuid, text, uuid, text, bigint, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_public_activate_v1(p_tenant_id uuid, p_public_id bytea, p_release_id uuid, p_resource_kind text, p_resource_version_id uuid, p_audience text, p_generation bigint, p_capability_sha256 bytea, p_capability_expires_at timestamp with time zone, p_activated_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_public_id) IS DISTINCT FROM 16 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_resource_version_id) IS DISTINCT FROM 7 OR
       p_resource_kind NOT IN ('query','dashboard') OR
       p_audience NOT IN ('public','capability') OR p_generation < 1 OR
       p_activated_at IS NULL OR NOT pg_catalog.isfinite(p_activated_at) OR
       (p_audience = 'public' AND
        (p_capability_sha256 IS NOT NULL OR p_capability_expires_at IS NOT NULL)) OR
       (p_audience = 'capability' AND
        (pg_catalog.octet_length(p_capability_sha256) IS DISTINCT FROM 32 OR
         p_capability_expires_at IS NULL OR
         NOT pg_catalog.isfinite(p_capability_expires_at) OR
         p_capability_expires_at <= p_activated_at OR
         p_capability_expires_at - p_activated_at > interval '30 days')) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics public activation input is invalid';
    END IF;
    PERFORM 1
    FROM platform.analytics_resolve_current_tenant_authority_v1(p_tenant_id);
    INSERT INTO platform.analytics_publications (
        public_id,tenant_id,release_id,resource_kind,resource_version_id,
        audience,state,generation,capability_sha256,capability_expires_at,activated_at
    ) VALUES (
        p_public_id,p_tenant_id,p_release_id,p_resource_kind,p_resource_version_id,
        p_audience,'active',p_generation,p_capability_sha256,
        p_capability_expires_at,p_activated_at
    );
END;
$$;


ALTER FUNCTION platform.analytics_public_activate_v1(p_tenant_id uuid, p_public_id bytea, p_release_id uuid, p_resource_kind text, p_resource_version_id uuid, p_audience text, p_generation bigint, p_capability_sha256 bytea, p_capability_expires_at timestamp with time zone, p_activated_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_public_admit_v1(uuid, uuid, bigint, inet, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_public_admit_v1(p_tenant_id uuid, p_release_id uuid, p_generation bigint, p_client_ip inet, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_window timestamptz; v_release_count integer; v_tenant_count bigint;
    v_lease_id uuid;
BEGIN
    IF p_tenant_id IS NULL OR pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_generation < 1 OR p_client_ip IS NULL OR p_occurred_at IS NULL OR
       NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics public admission is invalid';
    END IF;
    PERFORM 1 FROM platform.analytics_publications AS publication
    WHERE publication.tenant_id = p_tenant_id AND publication.release_id = p_release_id
      AND publication.generation = p_generation AND publication.state = 'active' FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102', MESSAGE = 'analytics public route was not found';
    END IF;
    v_window := pg_catalog.date_trunc('minute', p_occurred_at);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:public-limit:' || p_tenant_id::text || ':' || v_window::text, 6110));
    DELETE FROM platform.analytics_public_concurrency_leases WHERE expires_at <= p_occurred_at;
    SELECT pg_catalog.count(*)::integer INTO v_release_count
    FROM platform.analytics_public_concurrency_leases
    WHERE release_id = p_release_id AND generation = p_generation;
    IF v_release_count >= 10 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6105', MESSAGE = 'analytics public concurrency limit reached';
    END IF;
    SELECT COALESCE(pg_catalog.sum(request_count), 0) INTO v_tenant_count
    FROM platform.analytics_public_rate_windows
    WHERE tenant_id = p_tenant_id AND window_started_at = v_window;
    IF v_tenant_count >= 600 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6105', MESSAGE = 'analytics tenant public rate limit reached';
    END IF;
    INSERT INTO platform.analytics_public_rate_windows (
        tenant_id, release_id, generation, client_ip, window_started_at, request_count
    ) VALUES (p_tenant_id, p_release_id, p_generation, p_client_ip, v_window, 1)
    ON CONFLICT (tenant_id, release_id, generation, client_ip, window_started_at)
    DO UPDATE SET request_count = platform.analytics_public_rate_windows.request_count + 1
    WHERE platform.analytics_public_rate_windows.request_count < 60;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6105', MESSAGE = 'analytics public client rate limit reached';
    END IF;
    v_lease_id := pg_catalog.uuidv7();
    INSERT INTO platform.analytics_public_concurrency_leases VALUES (
        v_lease_id, p_tenant_id, p_release_id, p_generation, p_occurred_at + interval '30 seconds');
    RETURN v_lease_id;
END;
$$;


ALTER FUNCTION platform.analytics_public_admit_v1(p_tenant_id uuid, p_release_id uuid, p_generation bigint, p_client_ip inet, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_public_release_v1(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_public_release_v1(p_lease_id uuid, p_tenant_id uuid, p_release_id uuid, p_generation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF pg_catalog.uuid_extract_version(p_lease_id) IS DISTINCT FROM 7 OR
       p_tenant_id IS NULL OR pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_generation < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics public lease is invalid';
    END IF;
    DELETE FROM platform.analytics_public_concurrency_leases
    WHERE lease_id = p_lease_id AND tenant_id = p_tenant_id
      AND release_id = p_release_id AND generation = p_generation;
END;
$$;


ALTER FUNCTION platform.analytics_public_release_v1(p_lease_id uuid, p_tenant_id uuid, p_release_id uuid, p_generation bigint) OWNER TO harpy_owner;

--
-- Name: analytics_public_repair_v1(uuid, bytea, uuid, text, uuid, text, text, bigint, bytea, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_public_repair_v1(p_tenant_id uuid, p_public_id bytea, p_release_id uuid, p_resource_kind text, p_resource_version_id uuid, p_audience text, p_state text, p_generation bigint, p_capability_sha256 bytea, p_capability_expires_at timestamp with time zone, p_activated_at timestamp with time zone, p_revoked_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_public_id) IS DISTINCT FROM 16 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_resource_version_id) IS DISTINCT FROM 7 OR
       p_resource_kind NOT IN ('query','dashboard') OR
       p_audience NOT IN ('public','capability') OR
       p_state NOT IN ('active','revoked') OR p_generation < 1 OR
       p_activated_at IS NULL OR NOT pg_catalog.isfinite(p_activated_at) OR
       (p_state = 'active' AND p_revoked_at IS NOT NULL) OR
       (p_state = 'revoked' AND
        (p_revoked_at IS NULL OR NOT pg_catalog.isfinite(p_revoked_at) OR
         p_revoked_at < p_activated_at)) OR
       (p_audience = 'public' AND
        (p_capability_sha256 IS NOT NULL OR p_capability_expires_at IS NOT NULL)) OR
       (p_audience = 'capability' AND
        (pg_catalog.octet_length(p_capability_sha256) IS DISTINCT FROM 32 OR
         p_capability_expires_at IS NULL OR
         NOT pg_catalog.isfinite(p_capability_expires_at) OR
         p_capability_expires_at <= p_activated_at)) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics public repair input is invalid';
    END IF;
    PERFORM 1
    FROM platform.analytics_resolve_current_tenant_authority_v1(p_tenant_id);
    INSERT INTO platform.analytics_publications (
        public_id,tenant_id,release_id,resource_kind,resource_version_id,
        audience,state,generation,capability_sha256,capability_expires_at,
        activated_at,revoked_at
    ) VALUES (
        p_public_id,p_tenant_id,p_release_id,p_resource_kind,
        p_resource_version_id,p_audience,p_state,p_generation,
        p_capability_sha256,p_capability_expires_at,p_activated_at,p_revoked_at
    )
    ON CONFLICT (public_id) DO UPDATE
    SET state=EXCLUDED.state,generation=EXCLUDED.generation,
        capability_sha256=EXCLUDED.capability_sha256,
        capability_expires_at=EXCLUDED.capability_expires_at,
        activated_at=EXCLUDED.activated_at,revoked_at=EXCLUDED.revoked_at
    WHERE platform.analytics_publications.tenant_id=EXCLUDED.tenant_id
      AND platform.analytics_publications.release_id=EXCLUDED.release_id
      AND platform.analytics_publications.resource_kind=EXCLUDED.resource_kind
      AND platform.analytics_publications.resource_version_id=EXCLUDED.resource_version_id
      AND platform.analytics_publications.audience=EXCLUDED.audience
      AND platform.analytics_publications.generation <= EXCLUDED.generation;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics public repair identity conflicts';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_public_repair_v1(p_tenant_id uuid, p_public_id bytea, p_release_id uuid, p_resource_kind text, p_resource_version_id uuid, p_audience text, p_state text, p_generation bigint, p_capability_sha256 bytea, p_capability_expires_at timestamp with time zone, p_activated_at timestamp with time zone, p_revoked_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_public_resolve_v1(bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_public_resolve_v1(p_public_id bytea) RETURNS TABLE(public_id bytea, tenant_id uuid, release_id uuid, resource_kind text, resource_version_id uuid, audience text, state text, generation bigint, capability_sha256 bytea, capability_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF pg_catalog.octet_length(p_public_id) IS DISTINCT FROM 16 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics public identity is invalid';
    END IF;
    RETURN QUERY SELECT publication.public_id, publication.tenant_id,
        publication.release_id, publication.resource_kind,
        publication.resource_version_id, publication.audience,
        publication.state, publication.generation, publication.capability_sha256,
        publication.capability_expires_at
    FROM platform.analytics_publications AS publication
    WHERE publication.public_id = p_public_id AND publication.state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102', MESSAGE = 'analytics public route was not found';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_public_resolve_v1(p_public_id bytea) OWNER TO harpy_owner;

--
-- Name: analytics_public_retention_release_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_public_retention_release_v1(p_tenant_id uuid, p_release_id uuid, p_cutoff timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_cutoff IS NULL OR NOT pg_catalog.isfinite(p_cutoff) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics public retention input is invalid';
    END IF;
    PERFORM 1 FROM platform.analytics_resolve_current_tenant_authority_v1(p_tenant_id);
    IF EXISTS (
        SELECT 1 FROM platform.analytics_legacy_public_routes AS legacy
        WHERE legacy.tenant_id = p_tenant_id AND legacy.release_id = p_release_id
    ) OR EXISTS (
        SELECT 1 FROM platform.analytics_publications AS pointer
        WHERE pointer.tenant_id = p_tenant_id AND pointer.release_id = p_release_id
          AND (pointer.state <> 'revoked' OR pointer.revoked_at > p_cutoff)
    ) THEN
        RETURN false;
    END IF;
    DELETE FROM platform.analytics_public_rate_windows
    WHERE tenant_id = p_tenant_id AND release_id = p_release_id;
    DELETE FROM platform.analytics_public_concurrency_leases
    WHERE tenant_id = p_tenant_id AND release_id = p_release_id;
    DELETE FROM platform.analytics_publications
    WHERE tenant_id = p_tenant_id AND release_id = p_release_id
      AND state = 'revoked' AND revoked_at <= p_cutoff;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.analytics_public_retention_release_v1(p_tenant_id uuid, p_release_id uuid, p_cutoff timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_public_revoke_v1(uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_public_revoke_v1(p_tenant_id uuid, p_release_id uuid, p_generation bigint, p_revoked_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_generation < 1 OR p_revoked_at IS NULL OR
       NOT pg_catalog.isfinite(p_revoked_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics public revoke input is invalid';
    END IF;
    PERFORM 1
    FROM platform.analytics_resolve_current_tenant_authority_v1(p_tenant_id);
    UPDATE platform.analytics_publications
    SET state='revoked',generation=generation+1,revoked_at=p_revoked_at
    WHERE tenant_id=p_tenant_id AND release_id=p_release_id
      AND generation=p_generation AND state='active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics public pointer changed';
    END IF;
END;
$$;


ALTER FUNCTION platform.analytics_public_revoke_v1(p_tenant_id uuid, p_release_id uuid, p_generation bigint, p_revoked_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_reconcile_current_tenant_authorities_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_reconcile_current_tenant_authorities_v1() RETURNS TABLE(reconciled_count integer, remaining_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_reconciled integer;
    v_remaining integer;
BEGIN
    v_reconciled := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'analytics authority reconciliation is denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:analytics:tenant-authority-reconcile:v1', 0));
    FOR v_tenant_id, v_group_generation, v_domain_generation IN
        SELECT tenant.id, group_row.generation, domain_row.generation
        FROM platform.tenants AS tenant
        JOIN platform.cutover_groups AS group_row
          ON group_row.scope_kind = 'tenant' AND group_row.scope_id = tenant.id
         AND group_row.group_id = 'analytics'
        JOIN platform.cutover_group_members AS member_row
          ON member_row.scope_kind = group_row.scope_kind AND member_row.scope_id = group_row.scope_id
         AND member_row.group_id = group_row.group_id AND member_row.ordinal = 1
         AND member_row.domain = 'analytics'
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind = member_row.scope_kind AND domain_row.scope_id = member_row.scope_id
         AND domain_row.domain = member_row.domain
        WHERE tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
          AND group_row.state = 'v2' AND group_row.writer = 'v2'
          AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
          AND NOT EXISTS (
              SELECT 1 FROM platform.cutover_group_members AS extra
              WHERE extra.scope_kind = 'tenant' AND extra.scope_id = tenant.id
                AND extra.group_id = 'analytics'
                AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.analytics_tenant_authorities AS authority_row
              WHERE authority_row.tenant_id = tenant.id
                AND authority_row.authority_group_generation = group_row.generation
                AND authority_row.authority_domain_generation = domain_row.generation
                AND authority_row.authority_mode = 'runtime_v2'
          )
        ORDER BY tenant.id
    LOOP
        BEGIN
            PERFORM platform.analytics_register_tenant_authority_v1(
                pg_catalog.uuidv7(), v_tenant_id,
                v_group_generation, v_domain_generation,
                pg_catalog.transaction_timestamp()
            );
            v_reconciled := v_reconciled + 1;
        EXCEPTION WHEN SQLSTATE 'P6101' THEN
            IF NOT EXISTS (
                SELECT 1
                FROM platform.analytics_tenant_authorities AS authority_row
                JOIN platform.tenants AS tenant ON tenant.id = authority_row.tenant_id
                JOIN platform.cutover_groups AS group_row
                  ON group_row.scope_kind = authority_row.scope_kind AND group_row.scope_id = authority_row.scope_id
                 AND group_row.group_id = authority_row.authority_group_id
                JOIN platform.cutover_group_members AS member_row
                  ON member_row.scope_kind = authority_row.scope_kind AND member_row.scope_id = authority_row.scope_id
                 AND member_row.group_id = authority_row.authority_group_id AND member_row.ordinal = 1
                 AND member_row.domain = authority_row.authority_domain
                JOIN platform.domain_cutovers AS domain_row
                  ON domain_row.scope_kind = authority_row.scope_kind AND domain_row.scope_id = authority_row.scope_id
                 AND domain_row.domain = authority_row.authority_domain
                WHERE authority_row.tenant_id = v_tenant_id
                  AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
                  AND authority_row.scope_kind = 'tenant' AND authority_row.scope_id = v_tenant_id
                  AND authority_row.authority_group_id = 'analytics' AND authority_row.authority_domain = 'analytics'
                  AND authority_row.authority_group_generation = v_group_generation
                  AND authority_row.authority_domain_generation = v_domain_generation
                  AND authority_row.authority_mode = 'runtime_v2'
                  AND group_row.generation = v_group_generation AND domain_row.generation = v_domain_generation
                  AND group_row.state = 'v2' AND group_row.writer = 'v2'
                  AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
                  AND NOT EXISTS (
                      SELECT 1 FROM platform.cutover_group_members AS extra
                      WHERE extra.scope_kind = 'tenant' AND extra.scope_id = v_tenant_id
                        AND extra.group_id = 'analytics'
                        AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
                  )
            ) THEN
                RAISE;
            END IF;
        END;
    END LOOP;
    SELECT pg_catalog.count(*)::integer INTO v_remaining
    FROM platform.tenants AS tenant
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'tenant' AND group_row.scope_id = tenant.id
     AND group_row.group_id = 'analytics'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = 'tenant' AND domain_row.scope_id = tenant.id
     AND domain_row.domain = 'analytics'
    WHERE tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND group_row.state = 'v2' AND group_row.writer = 'v2'
      AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
      AND (
        NOT EXISTS (
            SELECT 1 FROM platform.cutover_group_members AS only_member
            WHERE only_member.scope_kind = 'tenant' AND only_member.scope_id = tenant.id
              AND only_member.group_id = 'analytics' AND only_member.ordinal = 1
              AND only_member.domain = 'analytics'
              AND NOT EXISTS (
                  SELECT 1 FROM platform.cutover_group_members AS extra
                  WHERE extra.scope_kind = 'tenant' AND extra.scope_id = tenant.id
                    AND extra.group_id = 'analytics'
                    AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
              )
        )
        OR NOT EXISTS (
            SELECT 1 FROM platform.analytics_tenant_authorities AS authority_row
            WHERE authority_row.tenant_id = tenant.id
              AND authority_row.authority_group_generation = group_row.generation
              AND authority_row.authority_domain_generation = domain_row.generation
              AND authority_row.authority_mode = 'runtime_v2'
        )
      );
    IF v_remaining IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101', MESSAGE = 'analytics authority reconciliation is incomplete';
    END IF;
    RETURN QUERY SELECT v_reconciled, v_remaining;
END;
$$;


ALTER FUNCTION platform.analytics_reconcile_current_tenant_authorities_v1() OWNER TO harpy_owner;

--
-- Name: analytics_reconcile_current_tenant_authorities_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_reconcile_current_tenant_authorities_v2() RETURNS TABLE(reconciled_count integer, remaining_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_reconciled integer;
    v_remaining integer;
BEGIN
    v_reconciled := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR platform.tenancy_authority_reconcile_scope_assert_v1('analytics')
            IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics authority reconciliation is denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:analytics:tenant-authority-reconcile:v1', 0));
    FOR v_tenant_id, v_group_generation, v_domain_generation IN
        SELECT tenant.id, group_row.generation, domain_row.generation
        FROM platform.tenants AS tenant
        JOIN platform.cutover_groups AS group_row
          ON group_row.scope_kind = 'tenant'
         AND group_row.scope_id = tenant.id
         AND group_row.group_id = 'analytics'
        JOIN platform.cutover_group_members AS member_row
          ON member_row.scope_kind = group_row.scope_kind
         AND member_row.scope_id = group_row.scope_id
         AND member_row.group_id = group_row.group_id
         AND member_row.ordinal = 1
         AND member_row.domain = 'analytics'
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind = member_row.scope_kind
         AND domain_row.scope_id = member_row.scope_id
         AND domain_row.domain = member_row.domain
        WHERE tenant.deleted_at IS NULL
          AND tenant.status IN ('ACTIVE', 'TRIAL')
          AND group_row.state = 'v2' AND group_row.writer = 'v2'
          AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
          AND NOT EXISTS (
              SELECT 1 FROM platform.cutover_group_members AS extra
              WHERE extra.scope_kind = 'tenant'
                AND extra.scope_id = tenant.id
                AND extra.group_id = 'analytics'
                AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.analytics_tenant_authorities AS authority_row
              WHERE authority_row.tenant_id = tenant.id
                AND authority_row.authority_group_generation =
                    group_row.generation
                AND authority_row.authority_domain_generation =
                    domain_row.generation
                AND authority_row.authority_mode = 'runtime_v2'
          )
        ORDER BY tenant.id
    LOOP
        BEGIN
            PERFORM platform.analytics_register_tenant_authority_v1(
                pg_catalog.uuidv7(), v_tenant_id,
                v_group_generation, v_domain_generation,
                pg_catalog.transaction_timestamp()
            );
            v_reconciled := v_reconciled + 1;
        EXCEPTION WHEN SQLSTATE 'P6101' THEN
            IF NOT EXISTS (
                SELECT 1
                FROM platform.analytics_tenant_authorities AS authority_row
                JOIN platform.tenants AS tenant
                  ON tenant.id = authority_row.tenant_id
                JOIN platform.cutover_groups AS group_row
                  ON group_row.scope_kind = authority_row.scope_kind
                 AND group_row.scope_id = authority_row.scope_id
                 AND group_row.group_id = authority_row.authority_group_id
                JOIN platform.cutover_group_members AS member_row
                  ON member_row.scope_kind = authority_row.scope_kind
                 AND member_row.scope_id = authority_row.scope_id
                 AND member_row.group_id = authority_row.authority_group_id
                 AND member_row.ordinal = 1
                 AND member_row.domain = authority_row.authority_domain
                JOIN platform.domain_cutovers AS domain_row
                  ON domain_row.scope_kind = authority_row.scope_kind
                 AND domain_row.scope_id = authority_row.scope_id
                 AND domain_row.domain = authority_row.authority_domain
                WHERE authority_row.tenant_id = v_tenant_id
                  AND tenant.deleted_at IS NULL
                  AND tenant.status IN ('ACTIVE', 'TRIAL')
                  AND authority_row.scope_kind = 'tenant'
                  AND authority_row.scope_id = v_tenant_id
                  AND authority_row.authority_group_id = 'analytics'
                  AND authority_row.authority_domain = 'analytics'
                  AND authority_row.authority_group_generation =
                      v_group_generation
                  AND authority_row.authority_domain_generation =
                      v_domain_generation
                  AND authority_row.authority_mode = 'runtime_v2'
                  AND group_row.generation = v_group_generation
                  AND domain_row.generation = v_domain_generation
                  AND group_row.state = 'v2' AND group_row.writer = 'v2'
                  AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
                  AND NOT EXISTS (
                      SELECT 1
                      FROM platform.cutover_group_members AS extra
                      WHERE extra.scope_kind = 'tenant'
                        AND extra.scope_id = v_tenant_id
                        AND extra.group_id = 'analytics'
                        AND NOT (
                            extra.ordinal = 1 AND extra.domain = 'analytics'
                        )
                  )
            ) THEN
                RAISE;
            END IF;
        END;
    END LOOP;
    SELECT pg_catalog.count(*)::integer INTO v_remaining
    FROM platform.tenants AS tenant
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'tenant'
     AND group_row.scope_id = tenant.id
     AND group_row.group_id = 'analytics'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = 'tenant'
     AND domain_row.scope_id = tenant.id
     AND domain_row.domain = 'analytics'
    WHERE tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND group_row.state = 'v2' AND group_row.writer = 'v2'
      AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
      AND (
        NOT EXISTS (
            SELECT 1 FROM platform.cutover_group_members AS only_member
            WHERE only_member.scope_kind = 'tenant'
              AND only_member.scope_id = tenant.id
              AND only_member.group_id = 'analytics'
              AND only_member.ordinal = 1
              AND only_member.domain = 'analytics'
              AND NOT EXISTS (
                  SELECT 1 FROM platform.cutover_group_members AS extra
                  WHERE extra.scope_kind = 'tenant'
                    AND extra.scope_id = tenant.id
                    AND extra.group_id = 'analytics'
                    AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
              )
        )
        OR NOT EXISTS (
            SELECT 1
            FROM platform.analytics_tenant_authorities AS authority_row
            WHERE authority_row.tenant_id = tenant.id
              AND authority_row.authority_group_generation =
                  group_row.generation
              AND authority_row.authority_domain_generation =
                  domain_row.generation
              AND authority_row.authority_mode = 'runtime_v2'
        )
      );
    IF v_remaining IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics authority reconciliation is incomplete';
    END IF;
    RETURN QUERY SELECT v_reconciled, v_remaining;
END;
$$;


ALTER FUNCTION platform.analytics_reconcile_current_tenant_authorities_v2() OWNER TO harpy_owner;

--
-- Name: analytics_register_tenant_authority_v1(uuid, uuid, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_register_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid, p_group_generation bigint, p_domain_generation bigint, p_created_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_mode text;
    v_state text;
    v_writer text;
    v_inserted boolean;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.uuid_extract_version(p_authority_id) IS DISTINCT FROM 7 OR
       p_tenant_id IS NULL OR p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_group_generation IS NULL OR p_group_generation < 1 OR
       p_domain_generation IS NULL OR p_domain_generation < 1 OR
       p_created_at IS NULL OR NOT pg_catalog.isfinite(p_created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics authority registration input is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        v_mode := 'runtime_v2'; v_state := 'v2'; v_writer := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        v_mode := 'adopter_shadow'; v_state := 'shadow'; v_writer := 'v1';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics authority registration session is invalid';
    END IF;
    PERFORM 1
    FROM platform.tenants AS tenant
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'tenant' AND group_row.scope_id = tenant.id
     AND group_row.group_id = 'analytics'
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.ordinal = 1 AND member_row.domain = 'analytics'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE tenant.id = p_tenant_id AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND group_row.generation = p_group_generation
      AND domain_row.generation = p_domain_generation
      AND group_row.state = v_state AND group_row.writer = v_writer
      AND domain_row.state = v_state AND domain_row.writer = v_writer
    FOR SHARE OF tenant, group_row, member_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics authority registration is not current';
    END IF;
    INSERT INTO platform.analytics_tenant_authorities (
        authority_id, tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation,
        authority_domain, authority_domain_generation, authority_mode, created_at
    ) VALUES (
        p_authority_id, p_tenant_id, 'tenant', p_tenant_id,
        'analytics', p_group_generation, 'analytics', p_domain_generation,
        v_mode, p_created_at
    ) ON CONFLICT DO NOTHING RETURNING true INTO v_inserted;
    IF NOT COALESCE(v_inserted, false) AND NOT EXISTS (
        SELECT 1 FROM platform.analytics_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = p_authority_id
          AND authority_row.tenant_id = p_tenant_id
          AND authority_row.authority_group_generation = p_group_generation
          AND authority_row.authority_domain_generation = p_domain_generation
          AND authority_row.authority_mode = v_mode
          AND authority_row.created_at IS NOT DISTINCT FROM p_created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101',
            MESSAGE = 'analytics authority registration replay differs';
    END IF;
    PERFORM platform.analytics_assert_tenant_authority_v1(p_authority_id, p_tenant_id);
    RETURN p_authority_id;
END;
$$;


ALTER FUNCTION platform.analytics_register_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid, p_group_generation bigint, p_domain_generation bigint, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_resolve_current_tenant_authority_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_resolve_current_tenant_authority_v1(p_tenant_id uuid) RETURNS TABLE(authority_id uuid, authority_group_generation bigint, authority_domain_generation bigint, authority_mode text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_authority_id uuid;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_mode text;
    v_state text;
    v_writer text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_tenant_id IS NULL OR
       p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'analytics authority resolver input is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        v_mode := 'runtime_v2'; v_state := 'v2'; v_writer := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        v_mode := 'adopter_shadow'; v_state := 'shadow'; v_writer := 'v1';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'analytics authority resolver session is invalid';
    END IF;
    BEGIN
        SELECT authority_row.authority_id, group_row.generation, domain_row.generation
        INTO STRICT v_authority_id, v_group_generation, v_domain_generation
        FROM platform.analytics_tenant_authorities AS authority_row
        JOIN platform.tenants AS tenant ON tenant.id = authority_row.tenant_id
        JOIN platform.cutover_groups AS group_row
          ON group_row.scope_kind = authority_row.scope_kind AND group_row.scope_id = authority_row.scope_id
         AND group_row.group_id = authority_row.authority_group_id
        JOIN platform.cutover_group_members AS member_row
          ON member_row.scope_kind = authority_row.scope_kind AND member_row.scope_id = authority_row.scope_id
         AND member_row.group_id = authority_row.authority_group_id AND member_row.domain = authority_row.authority_domain
         AND member_row.ordinal = 1
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind = authority_row.scope_kind AND domain_row.scope_id = authority_row.scope_id
         AND domain_row.domain = authority_row.authority_domain
        WHERE authority_row.tenant_id = p_tenant_id
          AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
          AND authority_row.scope_kind = 'tenant' AND authority_row.scope_id = p_tenant_id
          AND authority_row.authority_group_id = 'analytics' AND authority_row.authority_domain = 'analytics'
          AND authority_row.authority_mode = v_mode
          AND authority_row.authority_group_generation = group_row.generation
          AND authority_row.authority_domain_generation = domain_row.generation
          AND group_row.state = v_state AND group_row.writer = v_writer
          AND domain_row.state = v_state AND domain_row.writer = v_writer
          AND NOT EXISTS (
              SELECT 1 FROM platform.cutover_group_members AS extra
              WHERE extra.scope_kind = 'tenant' AND extra.scope_id = p_tenant_id
                AND extra.group_id = 'analytics'
                AND NOT (extra.ordinal = 1 AND extra.domain = 'analytics')
          );
    EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING ERRCODE = 'P6101', MESSAGE = 'analytics tenant authority is not current';
    END;
    RETURN QUERY SELECT v_authority_id, v_group_generation, v_domain_generation, v_mode;
END;
$$;


ALTER FUNCTION platform.analytics_resolve_current_tenant_authority_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_public_bridge_v1(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.analytics_v1_adoption_public_bridge_v1(p_action text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_target jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_pointer jsonb;
    v_route jsonb;
    v_snapshot jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_action NOT IN ('count','inspect','project') OR p_tenant_id IS NULL OR
       (p_action<>'count' AND p_legacy_endpoint_id IS NULL) OR
       (p_action='project' AND p_target IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption public bridge denied';
    END IF;
    IF p_action='count' THEN
      SELECT pg_catalog.jsonb_build_object(
        'publication_count',(SELECT pg_catalog.count(*)
          FROM platform.analytics_publications WHERE tenant_id=p_tenant_id),
        'route_count',(SELECT pg_catalog.count(*)
          FROM platform.analytics_legacy_public_routes WHERE tenant_id=p_tenant_id)
      ) INTO v_snapshot;
      RETURN v_snapshot;
    END IF;
    IF p_action='project' THEN
      v_pointer:=p_target->'public_pointer';
      v_route:=p_target->'legacy_route';
      IF (v_pointer->>'tenant_id')::uuid IS DISTINCT FROM p_tenant_id OR
         (v_route->>'tenant_id')::uuid IS DISTINCT FROM p_tenant_id OR
         (v_route->>'legacy_endpoint_id')::uuid
           IS DISTINCT FROM p_legacy_endpoint_id OR
         v_pointer->>'public_id'!~'^[0-9a-f]{32}$' OR
         v_route->>'public_id' IS DISTINCT FROM v_pointer->>'public_id' OR
         (v_route->>'release_id')::uuid IS DISTINCT FROM
           (v_pointer->>'release_id')::uuid OR
         v_pointer->>'state'<>'active' OR v_route->>'state'<>'active' OR
         (v_route->>'hit_count')::bigint<>0 OR
         v_route->'last_hit_at'<>'null'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='22023',
          MESSAGE='Analytics V1 adoption public bridge input invalid';
      END IF;
      INSERT INTO platform.analytics_publications(
        public_id,tenant_id,release_id,resource_kind,resource_version_id,audience,
        state,generation,capability_sha256,capability_expires_at,activated_at,revoked_at
      ) VALUES (
        pg_catalog.decode(v_pointer->>'public_id','hex'),p_tenant_id,
        (v_pointer->>'release_id')::uuid,v_pointer->>'resource_kind',
        (v_pointer->>'resource_version_id')::uuid,v_pointer->>'audience','active',
        (v_pointer->>'generation')::bigint,NULL,NULL,
        (v_pointer->>'activated_at')::timestamptz,NULL
      ) ON CONFLICT DO NOTHING;
      INSERT INTO platform.analytics_legacy_public_routes(
        legacy_tenant_identity,method,path,slug,tenant_id,legacy_endpoint_id,
        public_id,release_id,state,hit_count,last_hit_at,consumers_acked_at,
        remove_after,consumer_inventory_sha256,retirement_evidence_sha256,
        retirement_observed_at,retired_at
      ) VALUES (
        v_route->>'legacy_tenant_identity',v_route->>'method',v_route->>'path',
        v_route->>'slug',p_tenant_id,p_legacy_endpoint_id,
        pg_catalog.decode(v_route->>'public_id','hex'),
        (v_route->>'release_id')::uuid,'active',0,NULL,
        (v_route->>'consumers_acked_at')::timestamptz,
        (v_route->>'remove_after')::timestamptz,
        pg_catalog.decode(v_route->>'consumer_inventory_sha256','hex'),NULL,NULL,NULL
      ) ON CONFLICT DO NOTHING;
    END IF;
    SELECT pg_catalog.jsonb_build_object(
      'publication_exists',publication.public_id IS NOT NULL,
      'publication_public_id',pg_catalog.encode(publication.public_id,'hex'),
      'publication_release_id',publication.release_id,
      'publication_resource_version_id',publication.resource_version_id,
      'publication_audience',publication.audience,
      'publication_state',publication.state,
      'route_exists',route.legacy_endpoint_id IS NOT NULL,
      'route_public_id',pg_catalog.encode(route.public_id,'hex'),
      'route_release_id',route.release_id,'route_state',route.state,
      'hit_count',route.hit_count,'last_hit_at',route.last_hit_at,
      'consumers_acked_at',route.consumers_acked_at,
      'remove_after',route.remove_after,
      'consumer_inventory_sha256',
        pg_catalog.encode(route.consumer_inventory_sha256,'hex'),
      'legacy_tenant_identity',route.legacy_tenant_identity,
      'method',route.method,'path',route.path,'slug',route.slug
    ) INTO v_snapshot
    FROM (SELECT 1 AS marker) AS seed
    LEFT JOIN platform.analytics_legacy_public_routes AS route
      ON route.tenant_id=p_tenant_id
     AND route.legacy_endpoint_id=p_legacy_endpoint_id
    LEFT JOIN platform.analytics_publications AS publication
      ON publication.public_id=route.public_id
     AND publication.tenant_id=route.tenant_id
     AND publication.release_id=route.release_id;
    RETURN v_snapshot;
END;
$_$;


ALTER FUNCTION platform.analytics_v1_adoption_public_bridge_v1(p_action text, p_tenant_id uuid, p_legacy_endpoint_id uuid, p_target jsonb) OWNER TO harpy_owner;

