--
-- Name: billing_add_campaign_discount_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_add_campaign_discount_v1(p_authority_id uuid, p_campaign_version_id uuid, p_discount_version_id uuid, p_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    INSERT INTO platform.billing_campaign_discounts (
        authority_id, campaign_version_id, discount_version_id, created_at
    ) VALUES (
