ALTER FUNCTION platform.billing_add_campaign_discount_v1(p_authority_id uuid, p_campaign_version_id uuid, p_discount_version_id uuid, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_add_discount_offering_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_add_discount_offering_v1(p_authority_id uuid, p_discount_version_id uuid, p_offering_version_id uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    INSERT INTO platform.billing_discount_offerings (
        authority_id, discount_version_id, offering_version_id, created_at
    )
    SELECT p_authority_id, p_discount_version_id,
           p_offering_version_id, p_occurred_at
    FROM platform.billing_discount_versions AS discount_version
    JOIN platform.billing_offering_versions AS offering_version
      ON offering_version.authority_id = discount_version.authority_id
     AND offering_version.id = p_offering_version_id
    WHERE discount_version.authority_id = p_authority_id
      AND discount_version.id = p_discount_version_id
      AND NOT discount_version.all_offerings;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'billing discount offering binding is invalid';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_add_discount_offering_v1(p_authority_id uuid, p_discount_version_id uuid, p_offering_version_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_add_offering_grant_v1(uuid, uuid, text, text, boolean, bigint, boolean, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_add_offering_grant_v1(p_authority_id uuid, p_offering_version_id uuid, p_entitlement_key text, p_value_type text, p_boolean_value boolean, p_integer_value bigint, p_unlimited boolean, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    INSERT INTO platform.billing_offering_entitlements (
        authority_id, offering_version_id, entitlement_definition_id,
        value_type, definition_allows_unlimited, boolean_value,
        integer_value, unlimited, created_at
    )
    SELECT p_authority_id, p_offering_version_id, definition.id,
           definition.value_type, definition.unlimited_allowed,
           p_boolean_value, p_integer_value, p_unlimited, p_occurred_at
    FROM platform.billing_entitlement_definitions AS definition
    JOIN platform.billing_offering_versions AS offering_version
      ON offering_version.authority_id = definition.authority_id
     AND offering_version.id = p_offering_version_id
    WHERE definition.authority_id = p_authority_id
      AND definition.entitlement_key = p_entitlement_key
      AND definition.value_type = p_value_type;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'billing entitlement definition is missing';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_add_offering_grant_v1(p_authority_id uuid, p_offering_version_id uuid, p_entitlement_key text, p_value_type text, p_boolean_value boolean, p_integer_value bigint, p_unlimited boolean, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_add_offering_price_v1(uuid, uuid, uuid, text, bigint, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_add_offering_price_v1(p_authority_id uuid, p_offering_version_id uuid, p_price_id uuid, p_cadence text, p_minor_units bigint, p_currency text, p_currency_registry_version bigint, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    selected_start timestamptz;
    selected_end timestamptz;
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    SELECT effective_start, effective_end INTO selected_start, selected_end
    FROM platform.billing_offering_versions
    WHERE authority_id = p_authority_id AND id = p_offering_version_id
      AND publication_state = 'published'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'billing offering version is missing';
    END IF;
    INSERT INTO platform.billing_price_versions (
        id, authority_id, offering_version_id, cadence, minor_units,
        currency, currency_registry_version, currency_eligible,
        effective_start, effective_end, money_policy_version, published_at
    ) VALUES (
        p_price_id, p_authority_id, p_offering_version_id, p_cadence,
        p_minor_units, p_currency::character(3), p_currency_registry_version,
        true, selected_start, selected_end, 'fc_money_v1', p_occurred_at
    );
END;
$$;


ALTER FUNCTION platform.billing_add_offering_price_v1(p_authority_id uuid, p_offering_version_id uuid, p_price_id uuid, p_cadence text, p_minor_units bigint, p_currency text, p_currency_registry_version bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_adoption_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_adoption_v1(p_operation_id uuid, p_run_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_record jsonb;
    v_count bigint;
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
    FOR UPDATE;
    IF v_run.state IN ('applied', 'verified', 'rollback_rehearsed') THEN
        RETURN v_run.applied_count;
    END IF;
    IF v_run.state <> 'planned' OR NOT v_run.eligible THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing V1 adoption run is not applicable';
    END IF;
    IF v_run.scope_kind = 'global' THEN
        PERFORM platform.billing_apply_v1_provider_account_v1(
            p_operation_id, p_run_id,
            pg_catalog.to_jsonb(v_run.plan_document->>'manual_provider_account_id')
        );
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'offerings'
            )
        LOOP
            PERFORM platform.billing_apply_v1_offering_v1(
                p_operation_id, p_run_id, v_record
            );
        END LOOP;
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'discounts'
            )
        LOOP
            PERFORM platform.billing_apply_v1_discount_v1(
                p_operation_id, p_run_id, v_record
            );
        END LOOP;
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'campaigns'
            )
        LOOP
            PERFORM platform.billing_apply_v1_campaign_v1(
                p_operation_id, p_run_id, v_record
            );
        END LOOP;
    ELSE
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'base_assignments'
            )
        LOOP
            PERFORM platform.billing_apply_v1_base_assignment_v1(
                p_operation_id, p_run_id, v_record
            );
        END LOOP;
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'subscriptions'
            )
        LOOP
            PERFORM platform.billing_apply_v1_subscription_v1(
                p_operation_id, p_run_id, v_record
            );
        END LOOP;
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'redemptions'
            )
        LOOP
            PERFORM platform.billing_apply_v1_redemption_v1(
                p_operation_id, p_run_id, v_record
            );
        END LOOP;
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'usage_openings'
            )
        LOOP
            PERFORM platform.billing_apply_v1_opening_v1(
                p_operation_id, p_run_id, 'usage_opening', v_record
            );
        END LOOP;
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'gauge_openings'
            )
        LOOP
            PERFORM platform.billing_apply_v1_opening_v1(
                p_operation_id, p_run_id, 'gauge_opening', v_record
            );
        END LOOP;
        FOR v_record IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_run.plan_document->'legacy_events'
            )
        LOOP
            PERFORM platform.billing_apply_v1_event_v1(
                p_operation_id, p_run_id, v_record
            );
        END LOOP;
    END IF;
    SELECT pg_catalog.count(*) INTO v_count
    FROM platform.billing_v1_adoption_mappings AS mapping
    WHERE mapping.operation_id = p_operation_id AND mapping.run_id = p_run_id;
    UPDATE platform.billing_v1_adoption_runs SET
        state = 'applied', applied_count = v_count,
        applied_at = v_now, updated_at = v_now
    WHERE operation_id = p_operation_id AND run_id = p_run_id;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_adoption_v1(p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_base_assignment_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_base_assignment_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_id uuid;
    v_sha bytea;
BEGIN
    v_id := (p_record->>'id')::uuid;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'tenant' AND run.state = 'planned' AND run.eligible;
    IF (p_record->>'tenant_id')::uuid IS DISTINCT FROM v_run.scope_id THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 base assignment tenant is invalid';
    END IF;
    INSERT INTO platform.billing_tenant_base_offerings (
        id, authority_id, tenant_id, offering_version_id,
        effective_start, effective_end, source_operation_id, created_at
    ) VALUES (
        v_id, v_run.authority_id, v_run.scope_id,
        (p_record->>'offering_version_id')::uuid,
        (p_record->>'effective_start')::timestamptz, NULL,
        (p_record->>'source_operation_id')::uuid, v_run.snapshot_at
    );
    v_sha := platform.billing_v1_adoption_tenant_fingerprint_v1(
        'base_assignment', v_id
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'base_assignments', v_run.scope_id::text,
        'base_assignment', v_id, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_base_assignment_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_campaign_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_campaign_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_discount jsonb;
    v_metadata jsonb;
    v_sha bytea;
BEGIN
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'global' AND run.state = 'planned' AND run.eligible;
    v_metadata := pg_catalog.jsonb_build_object(
        'name', p_record->>'name', 'description', p_record->>'description',
        'banner_text', p_record->>'banner_text',
        'auto_apply', (p_record->>'auto_apply')::boolean
    );
    INSERT INTO platform.billing_campaigns (
        id, authority_id, campaign_key, lifecycle, created_at, retired_at, revision,
        legacy_created_by
    ) VALUES (
        (p_record->>'id')::uuid, v_run.authority_id, p_record->>'key',
        CASE WHEN p_record->>'retired_at' IS NULL THEN 'active' ELSE 'retired' END,
        (p_record->>'created_at')::timestamptz,
        NULLIF(p_record->>'retired_at', '')::timestamptz, 1,
        (p_record->>'created_by')::uuid
    );
    INSERT INTO platform.billing_campaign_versions (
        id, authority_id, campaign_id, version, priority,
        expected_discount_count, starts_at, ends_at,
        presentation_metadata, presentation_sha256, publication_state,
        publication_operation_id, published_at, presentation_name,
        presentation_description, presentation_banner_text, auto_apply, available
    ) VALUES (
        (p_record->>'version_id')::uuid, v_run.authority_id,
        (p_record->>'id')::uuid, 1, (p_record->>'priority')::integer,
        pg_catalog.jsonb_array_length(p_record->'discount_version_ids'),
        (p_record->>'starts_at')::timestamptz,
        NULLIF(p_record->>'ends_at', '')::timestamptz,
        v_metadata, pg_catalog.sha256(pg_catalog.convert_to(v_metadata::text, 'UTF8')),
        'published', (p_record->>'publication_operation_id')::uuid,
        (p_record->>'updated_at')::timestamptz, p_record->>'name',
        p_record->>'description', p_record->>'banner_text',
        (p_record->>'auto_apply')::boolean, (p_record->>'is_active')::boolean
    );
    FOR v_discount IN
        SELECT value
        FROM pg_catalog.jsonb_array_elements(p_record->'discount_version_ids')
    LOOP
        INSERT INTO platform.billing_campaign_discounts (
            authority_id, campaign_version_id, discount_version_id, created_at
        ) VALUES (
            v_run.authority_id, (p_record->>'version_id')::uuid,
            (v_discount #>> '{}')::uuid, (p_record->>'created_at')::timestamptz
        );
    END LOOP;
    v_sha := platform.billing_v1_adoption_catalog_fingerprint_v1(
        'campaign', (p_record->>'id')::uuid
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'campaigns', p_record->>'source_id',
        'campaign', (p_record->>'id')::uuid, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_campaign_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_discount_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_discount_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_offering jsonb;
    v_registry bigint;
    v_sha bytea;
BEGIN
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'global' AND run.state = 'planned' AND run.eligible;
    IF p_record->>'discount_kind' = 'fixed' THEN
        SELECT exponent.registry_version INTO STRICT v_registry
        FROM platform.billing_currency_exponents AS exponent
        WHERE exponent.authority_id = v_run.authority_id
          AND exponent.code = (p_record->>'currency')::character(3)
          AND exponent.financial_money_eligible
        ORDER BY exponent.registry_version DESC LIMIT 1;
    END IF;
    INSERT INTO platform.billing_discounts (
        id, authority_id, normalized_code, lifecycle, created_at, revoked_at, revision,
        legacy_created_by
    ) VALUES (
        (p_record->>'id')::uuid, v_run.authority_id,
        p_record->>'normalized_code',
        CASE WHEN p_record->>'revoked_at' IS NULL THEN 'active' ELSE 'revoked' END,
        (p_record->>'created_at')::timestamptz,
        NULLIF(p_record->>'revoked_at', '')::timestamptz, 1,
        (p_record->>'created_by')::uuid
    );
    INSERT INTO platform.billing_discount_versions (
        id, authority_id, discount_id, version, discount_kind,
        fixed_minor_units, currency, currency_registry_version,
        currency_eligible, basis_points, duration, repeating_cycles,
        priority, global_use_limit, per_tenant_use_limit, all_offerings,
        expected_offering_count, publication_operation_id,
        valid_start, valid_end, published_at,
        presentation_name, presentation_description, available
    ) VALUES (
        (p_record->>'version_id')::uuid, v_run.authority_id,
        (p_record->>'id')::uuid, 1, p_record->>'discount_kind',
        NULLIF(p_record->>'fixed_minor_units', '')::bigint,
        NULLIF(p_record->>'currency', '')::character(3), v_registry,
        CASE WHEN p_record->>'discount_kind' = 'fixed' THEN true ELSE NULL END,
        NULLIF(p_record->>'basis_points', '')::integer,
        p_record->>'duration', NULLIF(p_record->>'repeating_cycles', '')::bigint,
        (p_record->>'priority')::integer,
        NULLIF(p_record->>'global_use_limit', '')::bigint,
        NULLIF(p_record->>'per_tenant_use_limit', '')::bigint,
        (p_record->>'all_offerings')::boolean,
        pg_catalog.jsonb_array_length(p_record->'offering_version_ids'),
        (p_record->>'publication_operation_id')::uuid,
        (p_record->>'valid_start')::timestamptz,
        NULLIF(p_record->>'valid_end', '')::timestamptz,
        (p_record->>'updated_at')::timestamptz,
        p_record->>'name', p_record->>'description',
        (p_record->>'is_active')::boolean
    );
    FOR v_offering IN
        SELECT value
        FROM pg_catalog.jsonb_array_elements(p_record->'offering_version_ids')
    LOOP
        INSERT INTO platform.billing_discount_offerings (
            authority_id, discount_version_id, offering_version_id, created_at
        ) VALUES (
            v_run.authority_id, (p_record->>'version_id')::uuid,
            (v_offering #>> '{}')::uuid, (p_record->>'created_at')::timestamptz
        );
    END LOOP;
    v_sha := platform.billing_v1_adoption_catalog_fingerprint_v1(
        'discount', (p_record->>'id')::uuid
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'coupons', p_record->>'source_id',
        'discount', (p_record->>'id')::uuid, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_discount_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_event_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_event_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_id uuid;
    v_sha bytea;
BEGIN
    IF p_operation_id IS NULL OR p_run_id IS NULL OR p_record IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 event input is invalid';
    END IF;
    v_id := (p_record->>'id')::uuid;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'tenant' AND run.state = 'planned' AND run.eligible;
    IF (p_record->>'tenant_id')::uuid IS DISTINCT FROM v_run.scope_id THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 event tenant is invalid';
    END IF;
    INSERT INTO platform.billing_v1_event_archive (
        id, authority_id, tenant_id, source_event_id, subscription_id,
        source_subscription_id, event_type, amount_cents, currency,
        description, metadata, created_at, source_sha256,
        adoption_operation_id, adoption_run_id, archived_at
    ) VALUES (
        v_id, v_run.authority_id, v_run.scope_id,
        (p_record->>'source_id')::uuid,
        NULLIF(p_record->>'subscription_id', '')::uuid,
        NULLIF(p_record->>'source_subscription_id', '')::uuid,
        p_record->>'event_type', (p_record->>'amount_cents')::bigint,
        p_record->>'currency', p_record->>'description',
        CASE WHEN p_record ? 'metadata' THEN p_record->'metadata' ELSE NULL END,
        (p_record->>'created_at')::timestamptz,
        pg_catalog.decode(p_record->>'source_sha256', 'hex'),
        p_operation_id, p_run_id, v_run.snapshot_at
    );
    v_sha := platform.billing_v1_adoption_tenant_fingerprint_v1(
        'legacy_event', v_id
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'billing_events', p_record->>'source_id',
        'legacy_event', v_id, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_event_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_offering_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_offering_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_price jsonb;
    v_grant jsonb;
    v_definition platform.billing_entitlement_definitions%ROWTYPE;
    v_registry bigint;
    v_metadata jsonb;
    v_sha bytea;
    v_retired_at timestamptz;
BEGIN
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'global' AND run.state = 'planned' AND run.eligible;
    v_retired_at := NULLIF(p_record->>'retired_at', '')::timestamptz;
    v_metadata := pg_catalog.jsonb_build_object(
        'name', p_record->>'name', 'description', p_record->>'description',
        'sort_order', (p_record->>'sort_order')::integer,
        'highlight_label', p_record->>'highlight_label',
        'color', p_record->>'color',
        'billing_interval', p_record->>'billing_interval'
    );
    INSERT INTO platform.billing_offerings (
        id, authority_id, offering_key, lifecycle, created_at, retired_at, revision
    ) VALUES (
        (p_record->>'id')::uuid, v_run.authority_id, p_record->>'key',
		'active', (p_record->>'created_at')::timestamptz, NULL, 1
    );
    INSERT INTO platform.billing_offering_versions (
		id, authority_id, offering_id, version, is_base, is_public, available,
        trial_days, grace_days, expected_price_count, expected_grant_count,
        effective_start, effective_end, presentation_metadata,
        presentation_sha256, publication_state, publication_operation_id, published_at
    ) VALUES (
        (p_record->>'version_id')::uuid, v_run.authority_id,
        (p_record->>'id')::uuid, 1, (p_record->>'is_base')::boolean,
		(p_record->>'is_public')::boolean, (p_record->>'available')::boolean,
		(p_record->>'trial_days')::integer, 0,
        pg_catalog.jsonb_array_length(p_record->'prices'),
        pg_catalog.jsonb_array_length(p_record->'grants'),
        (p_record->>'created_at')::timestamptz,
		v_retired_at,
        v_metadata, pg_catalog.sha256(pg_catalog.convert_to(v_metadata::text, 'UTF8')),
        'published', (p_record->>'publication_operation_id')::uuid,
        (p_record->>'updated_at')::timestamptz
    );
    FOR v_price IN SELECT value FROM pg_catalog.jsonb_array_elements(p_record->'prices') LOOP
        SELECT exponent.registry_version INTO STRICT v_registry
        FROM platform.billing_currency_exponents AS exponent
        WHERE exponent.authority_id = v_run.authority_id
          AND exponent.code = (v_price->>'currency')::character(3)
          AND exponent.financial_money_eligible
        ORDER BY exponent.registry_version DESC LIMIT 1;
        INSERT INTO platform.billing_price_versions (
            id, authority_id, offering_version_id, cadence, minor_units,
            currency, currency_registry_version, currency_eligible,
            effective_start, effective_end, money_policy_version, published_at
        ) VALUES (
            (v_price->>'id')::uuid, v_run.authority_id,
            (p_record->>'version_id')::uuid, v_price->>'cadence',
            (v_price->>'minor_units')::bigint, (v_price->>'currency')::character(3),
            v_registry, true, (p_record->>'created_at')::timestamptz,
			v_retired_at,
            'fc_money_v1', (p_record->>'updated_at')::timestamptz
        );
    END LOOP;
    FOR v_grant IN SELECT value FROM pg_catalog.jsonb_array_elements(p_record->'grants') LOOP
        SELECT definition.* INTO STRICT v_definition
        FROM platform.billing_entitlement_definitions AS definition
        WHERE definition.authority_id = v_run.authority_id
          AND definition.entitlement_key = v_grant->>'entitlement_key';
        INSERT INTO platform.billing_offering_entitlements (
            authority_id, offering_version_id, entitlement_definition_id,
            value_type, definition_allows_unlimited, boolean_value,
            integer_value, unlimited, created_at
        ) VALUES (
            v_run.authority_id, (p_record->>'version_id')::uuid, v_definition.id,
            v_grant->>'value_type', v_definition.unlimited_allowed,
            NULLIF(v_grant->>'boolean_value', '')::boolean,
            NULLIF(v_grant->>'integer_value', '')::bigint,
            (v_grant->>'unlimited')::boolean, (p_record->>'updated_at')::timestamptz
        );
    END LOOP;
    IF v_retired_at IS NOT NULL THEN
        UPDATE platform.billing_offerings
        SET lifecycle = 'retired', retired_at = v_retired_at, revision = 2
        WHERE authority_id = v_run.authority_id
          AND id = (p_record->>'id')::uuid
          AND lifecycle = 'active' AND revision = 1;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing adopted offering retirement failed';
        END IF;
    END IF;
    v_sha := platform.billing_v1_adoption_catalog_fingerprint_v1(
        'offering', (p_record->>'id')::uuid
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'plans', p_record->>'source_id',
        'offering', (p_record->>'id')::uuid, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_offering_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_opening_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_opening_v1(p_operation_id uuid, p_run_id uuid, p_record_kind text, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_definition platform.billing_entitlement_definitions%ROWTYPE;
    v_period_id uuid;
    v_entry_id uuid;
    v_value bigint;
    v_period_start timestamptz;
    v_period_end timestamptz;
    v_evidence text;
    v_source_key text;
    v_category text;
    v_meter_kind text;
    v_reset_policy text;
    v_owner_fact_id uuid;
    v_sha bytea;
BEGIN
    v_period_id := (p_record->>'meter_period_id')::uuid;
    v_entry_id := NULLIF(p_record->>'entry_id', '')::uuid;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'tenant' AND run.state = 'planned' AND run.eligible;
    IF (p_record->>'tenant_id')::uuid IS DISTINCT FROM v_run.scope_id
       OR p_record_kind NOT IN ('usage_opening', 'gauge_opening') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 opening scope is invalid';
    END IF;
    IF p_record_kind = 'usage_opening' THEN
        v_value := (p_record->>'count')::bigint;
        v_period_start := (p_record->>'period_start')::timestamptz;
        v_period_end := (p_record->>'period_end')::timestamptz;
        v_evidence := p_record->>'flush_evidence_sha256';
        v_source_key := p_record->>'source_id';
        v_category := 'submission_usage';
        v_meter_kind := 'counter';
        v_reset_policy := 'calendar_month_utc';
    ELSE
        v_value := (p_record->>'value')::bigint;
        v_period_start := (p_record->>'measured_at')::timestamptz;
        v_period_end := '9999-12-31 23:59:59.999999+00'::timestamptz;
        v_evidence := p_record->>'evidence_sha256';
        v_owner_fact_id := (p_record->>'owner_fact_id')::uuid;
        v_source_key := p_record->>'owner_fact_id';
        v_category := 'gauge_openings';
        v_meter_kind := 'gauge';
        v_reset_policy := 'never';
    END IF;
    SELECT definition.* INTO STRICT v_definition
    FROM platform.billing_entitlement_definitions AS definition
    WHERE definition.entitlement_key = p_record->>'entitlement_key';
    INSERT INTO platform.billing_meter_periods (
        id, authority_id, tenant_id, entitlement_definition_id,
        entitlement_key, meter_kind, reset_policy, period_start,
        period_end, state, closed_at, revision
    ) VALUES (
        v_period_id, v_run.authority_id, v_run.scope_id, v_definition.id,
        p_record->>'entitlement_key', v_meter_kind, v_reset_policy,
        v_period_start, v_period_end, 'open', NULL, 1
    );
    INSERT INTO platform.billing_usage_totals (
        authority_id, tenant_id, meter_period_id, entitlement_key,
        meter_kind, committed_total, reserved_total, gauge_total,
        revision, updated_at
    ) VALUES (
        v_run.authority_id, v_run.scope_id, v_period_id,
        p_record->>'entitlement_key', v_meter_kind,
        CASE WHEN v_meter_kind = 'counter' THEN v_value ELSE 0 END,
        0, CASE WHEN v_meter_kind = 'gauge' THEN v_value ELSE 0 END,
        1, v_run.snapshot_at
    );
    IF v_value > 0 THEN
        INSERT INTO platform.billing_usage_entries (
            id, authority_id, tenant_id, decision_id, entitlement_key,
            meter_period_id, reservation_id, entry_kind, amount_delta,
            committed_after, reserved_after, gauge_after,
            source_operation_id, owner_fact_id, evidence_sha256,
            occurred_at, created_at
        ) VALUES (
            v_entry_id, v_run.authority_id, v_run.scope_id, NULL,
            p_record->>'entitlement_key', v_period_id, NULL, 'opening', v_value,
            CASE WHEN v_meter_kind = 'counter' THEN v_value ELSE 0 END,
            0, CASE WHEN v_meter_kind = 'gauge' THEN v_value ELSE 0 END,
            NULL, NULL, pg_catalog.decode(v_evidence, 'hex'),
            v_period_start, v_run.snapshot_at
        );
    END IF;
    INSERT INTO platform.billing_v1_adoption_opening_evidence (
        operation_id, run_id, scope_kind, scope_id, authority_id,
        evidence_kind, source_key, tenant_id, entitlement_key,
        meter_period_id, entry_id, owner_fact_id, period_start,
        period_end, opening_value, evidence_sha256, recorded_at
    ) VALUES (
        p_operation_id, p_run_id, v_run.scope_kind, v_run.scope_id,
        v_run.authority_id,
        CASE p_record_kind WHEN 'usage_opening' THEN 'submission_usage'
            ELSE 'owner_gauge' END,
        v_source_key, v_run.scope_id, p_record->>'entitlement_key',
        v_period_id, v_entry_id, v_owner_fact_id, v_period_start,
        v_period_end, v_value, pg_catalog.decode(v_evidence, 'hex'),
        v_run.snapshot_at
    );
    v_sha := platform.billing_v1_adoption_tenant_fingerprint_v1(
        p_record_kind, v_period_id
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, v_category, v_source_key,
        p_record_kind, v_period_id, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_opening_v1(p_operation_id uuid, p_run_id uuid, p_record_kind text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_provider_account_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_provider_account_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_id uuid;
    v_sha bytea;
BEGIN
    v_id := (p_record #>> '{}')::uuid;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'global' AND run.state = 'planned' AND run.eligible;
    INSERT INTO platform.billing_provider_accounts (
        id, authority_id, provider_key, provider_account_key, lifecycle,
        supports_checkout, supports_webhooks, supports_proration,
        supports_refunds, created_at, disabled_at, revision
    ) VALUES (
        v_id, v_run.authority_id, 'manual', 'default', 'active',
        false, false, false, false, v_run.snapshot_at, NULL, 1
    );
    v_sha := platform.billing_v1_adoption_catalog_fingerprint_v1(
        'provider_account', v_id
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'provider_accounts', 'manual/default',
        'provider_account', v_id, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_provider_account_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_redemption_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_redemption_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_registry bigint;
    v_id uuid;
    v_sha bytea;
BEGIN
    v_id := (p_record->>'id')::uuid;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'tenant' AND run.state = 'planned' AND run.eligible;
    IF (p_record->>'tenant_id')::uuid IS DISTINCT FROM v_run.scope_id THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 redemption tenant is invalid';
    END IF;
    IF p_record->>'applied_kind' = 'fixed' THEN
        SELECT exponent.registry_version INTO STRICT v_registry
        FROM platform.billing_currency_exponents AS exponent
        WHERE exponent.code = (p_record->>'applied_currency')::character(3)
          AND exponent.financial_money_eligible
        ORDER BY exponent.registry_version DESC LIMIT 1;
    END IF;
    INSERT INTO platform.billing_discount_redemptions (
        id, authority_id, tenant_id, subscription_id, discount_version_id,
        offering_version_id, price_version_id, source_operation_id,
        applied_kind, applied_fixed_minor_units, applied_currency,
        applied_currency_registry_version, applied_basis_points,
        applied_priority, applied_duration, applied_repeating_cycles,
        policy_sha256, redeemed_at, relationship_ended_at
    ) VALUES (
        v_id, v_run.authority_id, v_run.scope_id,
        (p_record->>'subscription_id')::uuid,
        (p_record->>'discount_version_id')::uuid,
        (p_record->>'offering_version_id')::uuid,
        (p_record->>'price_version_id')::uuid,
        (p_record->>'source_operation_id')::uuid,
        p_record->>'applied_kind',
        NULLIF(p_record->>'applied_fixed_minor_units', '')::bigint,
        NULLIF(p_record->>'applied_currency', '')::character(3), v_registry,
        NULLIF(p_record->>'applied_basis_points', '')::integer,
        (p_record->>'applied_priority')::integer,
        p_record->>'applied_duration',
        NULLIF(p_record->>'applied_repeating_cycles', '')::bigint,
        pg_catalog.decode(p_record->>'policy_sha256', 'hex'),
        (p_record->>'redeemed_at')::timestamptz,
        NULLIF(p_record->>'relationship_ended_at', '')::timestamptz
    );
    v_sha := platform.billing_v1_adoption_tenant_fingerprint_v1(
        'redemption', v_id
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'subscription_coupons',
        p_record->>'source_id', 'redemption', v_id, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_redemption_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_apply_v1_subscription_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_apply_v1_subscription_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_id uuid;
    v_created timestamptz;
    v_sha bytea;
BEGIN
    v_id := (p_record->>'id')::uuid;
    v_created := (p_record->>'created_at')::timestamptz;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.scope_kind = 'tenant' AND run.state = 'planned' AND run.eligible;
    IF (p_record->>'tenant_id')::uuid IS DISTINCT FROM v_run.scope_id THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 subscription tenant is invalid';
    END IF;
    INSERT INTO platform.billing_subscriptions (
        id, authority_id, tenant_id, provider_account_id,
        offering_version_id, price_version_id, state,
        period_start, period_end, trial_ends_at, grace_ends_at,
        cancel_at_period_end, cancel_at, created_at, updated_at, revision
    ) VALUES (
        v_id, v_run.authority_id, v_run.scope_id,
        (p_record->>'provider_account_id')::uuid,
        (p_record->>'offering_version_id')::uuid,
        (p_record->>'price_version_id')::uuid, p_record->>'state',
        (p_record->>'period_start')::timestamptz,
        (p_record->>'period_end')::timestamptz,
        NULLIF(p_record->>'trial_ends_at', '')::timestamptz,
        NULLIF(p_record->>'grace_ends_at', '')::timestamptz,
        (p_record->>'cancel_at_period_end')::boolean,
        NULLIF(p_record->>'cancel_at', '')::timestamptz,
        v_created, v_created, 1
    );
    INSERT INTO platform.billing_v1_subscription_wire_archive (
        subscription_id, authority_id, tenant_id, source_subscription_id,
        source_updated_at, trial_started_at, cancelled_at, cancellation_reason,
        adoption_operation_id, adoption_run_id, archived_at
    ) VALUES (
        v_id, v_run.authority_id, v_run.scope_id,
        (p_record->>'source_id')::uuid,
        (p_record->>'updated_at')::timestamptz,
        NULLIF(p_record->>'trial_started_at', '')::timestamptz,
        NULLIF(p_record->>'cancelled_at', '')::timestamptz,
        p_record->>'cancellation_reason', p_operation_id, p_run_id,
        v_run.snapshot_at
    );
    v_sha := platform.billing_v1_adoption_tenant_fingerprint_v1(
        'subscription', v_id
    );
    PERFORM platform.billing_record_v1_adoption_mapping_v1(
        p_operation_id, p_run_id, 'subscriptions', p_record->>'source_id',
        'subscription', v_id, v_sha, v_run.snapshot_at
    );
END;
$$;


ALTER FUNCTION platform.billing_apply_v1_subscription_v1(p_operation_id uuid, p_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: billing_assert_global_authority_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_assert_global_authority_v1(p_authority_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    expected_writer text;
    expected_state text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global authority owner is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        expected_writer := 'v2'; expected_state := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        expected_writer := 'v1'; expected_state := 'shadow';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global authority session is invalid';
    END IF;
    PERFORM 1
    FROM platform.billing_global_authorities AS authority_row
    JOIN platform.environment_identity AS environment
      ON environment.environment_id = authority_row.scope_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = authority_row.scope_kind
     AND group_row.scope_id = authority_row.scope_id
     AND group_row.group_id = authority_row.authority_group_id
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = authority_row.scope_kind
     AND domain_row.scope_id = authority_row.scope_id
     AND domain_row.domain = authority_row.authority_domain
    WHERE authority_row.authority_id = p_authority_id
      AND authority_row.authority_group_generation = group_row.generation
      AND authority_row.authority_domain_generation = domain_row.generation
      AND group_row.writer = expected_writer
      AND domain_row.writer = expected_writer
      AND group_row.state = expected_state
      AND domain_row.state = expected_state
    FOR SHARE OF authority_row, group_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing global authority is not current';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_assert_global_authority_v1(p_authority_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_assert_promotion_association_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_assert_promotion_association_v1(p_authority_id uuid, p_operation_id uuid, p_discount_id uuid, p_old_discount_version_id uuid, p_new_discount_version_id uuid, p_campaign_id uuid, p_campaign_version_id_one uuid, p_campaign_version_id_two uuid, p_campaign_operation_id_one uuid, p_campaign_operation_id_two uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT pg_catalog.isfinite(p_occurred_at)
       OR pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR pg_catalog.uuid_extract_version(p_discount_id) <> 7
       OR pg_catalog.uuid_extract_version(p_new_discount_version_id) <> 7
       OR (p_old_discount_version_id IS NOT NULL
           AND pg_catalog.uuid_extract_version(p_old_discount_version_id) <> 7)
       OR (p_campaign_id IS NOT NULL
           AND pg_catalog.uuid_extract_version(p_campaign_id) <> 7)
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.unnest(ARRAY[
               p_campaign_version_id_one, p_campaign_version_id_two,
               p_campaign_operation_id_one, p_campaign_operation_id_two
           ]) AS selected(identifier)
           WHERE pg_catalog.uuid_extract_version(selected.identifier) <> 7
       ) OR (
           SELECT pg_catalog.count(DISTINCT selected.identifier)
           FROM pg_catalog.unnest(ARRAY[
               p_campaign_version_id_one, p_campaign_version_id_two,
               p_campaign_operation_id_one, p_campaign_operation_id_two,
               p_operation_id, p_discount_id, p_new_discount_version_id
           ]) AS selected(identifier)
       ) <> 7 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing promotion association identity is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.billing_catalog_operations AS operation
        JOIN platform.billing_discount_versions AS version_row
          ON version_row.authority_id = operation.authority_id
         AND version_row.id = operation.result_version_id
         AND version_row.discount_id = operation.aggregate_id
        WHERE operation.operation_id = p_operation_id
          AND operation.authority_id = p_authority_id
          AND operation.aggregate_kind = 'discount'
          AND operation.aggregate_id = p_discount_id
          AND operation.result_version_id = p_new_discount_version_id
    ) OR (
        p_old_discount_version_id IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM platform.billing_discount_versions AS version_row
            WHERE version_row.authority_id = p_authority_id
              AND version_row.id = p_old_discount_version_id
              AND version_row.discount_id = p_discount_id
        )
    ) OR (
        p_campaign_id IS NOT NULL AND NOT EXISTS (
            SELECT 1
            FROM platform.billing_campaigns AS campaign
            WHERE campaign.authority_id = p_authority_id
              AND campaign.id = p_campaign_id
              AND campaign.lifecycle = 'active'
        )
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.unnest(ARRAY[
            p_campaign_version_id_one, p_campaign_version_id_two
        ]) AS selected(identifier)
        JOIN platform.billing_campaign_versions AS existing
          ON existing.id = selected.identifier
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.unnest(ARRAY[
            p_campaign_operation_id_one, p_campaign_operation_id_two
        ]) AS selected(identifier)
        JOIN platform.billing_catalog_operations AS existing
          ON existing.operation_id = selected.identifier
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'billing promotion association authority is invalid';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_assert_promotion_association_v1(p_authority_id uuid, p_operation_id uuid, p_discount_id uuid, p_old_discount_version_id uuid, p_new_discount_version_id uuid, p_campaign_id uuid, p_campaign_version_id_one uuid, p_campaign_version_id_two uuid, p_campaign_operation_id_one uuid, p_campaign_operation_id_two uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_assert_retained_tenant_authority_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_assert_retained_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    expected_writer text;
    expected_state text;
BEGIN
    IF p_authority_id IS NULL OR p_tenant_id IS NULL
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing retained tenant authority input is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        expected_writer := 'v2'; expected_state := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        expected_writer := 'v1'; expected_state := 'shadow';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing retained tenant authority session is invalid';
    END IF;
    PERFORM 1
    FROM platform.billing_tenant_authorities AS authority_row
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = authority_row.scope_kind
     AND group_row.scope_id = authority_row.scope_id
     AND group_row.group_id = authority_row.authority_group_id
    JOIN platform.domain_cutovers AS billing_row
      ON billing_row.scope_kind = authority_row.scope_kind
     AND billing_row.scope_id = authority_row.scope_id
     AND billing_row.domain = authority_row.billing_domain
    WHERE authority_row.authority_id = p_authority_id
      AND authority_row.tenant_id = p_tenant_id
      AND authority_row.authority_group_generation = group_row.generation
      AND authority_row.billing_generation = billing_row.generation
      AND group_row.writer = expected_writer AND group_row.state = expected_state
      AND billing_row.writer = expected_writer AND billing_row.state = expected_state
    FOR SHARE OF authority_row, group_row, billing_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing retained tenant authority is not current';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_assert_retained_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_assert_tenant_authority_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_assert_tenant_authority_v1(p_authority_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    expected_writer text;
    expected_state text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant authority owner is invalid';
    END IF;
    IF SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime' THEN
        expected_writer := 'v2'; expected_state := 'v2';
    ELSIF SESSION_USER IS NOT DISTINCT FROM 'harpy_adopter' THEN
        expected_writer := 'v1'; expected_state := 'shadow';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant authority session is invalid';
    END IF;
    PERFORM 1
    FROM platform.billing_tenant_authorities AS authority_row
    JOIN platform.tenants AS tenant ON tenant.id = authority_row.tenant_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = authority_row.scope_kind
     AND group_row.scope_id = authority_row.scope_id
     AND group_row.group_id = authority_row.authority_group_id
    JOIN platform.domain_cutovers AS billing_row
      ON billing_row.scope_kind = authority_row.scope_kind
     AND billing_row.scope_id = authority_row.scope_id
     AND billing_row.domain = authority_row.billing_domain
    WHERE authority_row.authority_id = p_authority_id
      AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND authority_row.authority_group_generation = group_row.generation
      AND authority_row.billing_generation = billing_row.generation
      AND group_row.writer = expected_writer
      AND billing_row.writer = expected_writer
      AND group_row.state = expected_state
      AND billing_row.state = expected_state
    FOR SHARE OF authority_row, tenant, group_row, billing_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing tenant authority is not current';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_assert_tenant_authority_v1(p_authority_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_assert_v1_adoption_ready_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_assert_v1_adoption_ready_v1(p_operation_id uuid, p_run_id uuid, p_observed_source_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_rehearsal platform.billing_v1_adoption_rollback_rehearsals%ROWTYPE;
    v_target bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR p_observed_source_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 readiness assertion is denied';
    END IF;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.state = 'rollback_rehearsed'
      AND run.money_difference = 0 AND run.period_difference = 0
      AND run.coupon_difference = 0 AND run.usage_difference = 0;
    SELECT rehearsal.* INTO STRICT v_rehearsal
    FROM platform.billing_v1_adoption_rollback_rehearsals AS rehearsal
    WHERE rehearsal.operation_id = p_operation_id AND rehearsal.run_id = p_run_id
      AND rehearsal.zero_difference
      AND rehearsal.observed_source_sha256 =
          pg_catalog.decode(p_observed_source_sha256, 'hex')
      AND rehearsal.reverse_sha256 = rehearsal.observed_source_sha256;
    SELECT pg_catalog.sha256(pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
        record_kind || ':' || source_key || ':' ||
        pg_catalog.encode(current_sha, 'hex'), '|'
        ORDER BY record_kind, source_key
    ) FILTER (WHERE current_sha IS NOT NULL), ''), 'UTF8'))
    INTO v_target
    FROM (
        SELECT mapping.record_kind, mapping.source_key,
            platform.billing_v1_adoption_fingerprint_v1(
                mapping.record_kind, mapping.target_id
            ) AS current_sha
        FROM platform.billing_v1_adoption_mappings AS mapping
        WHERE mapping.operation_id = p_operation_id AND mapping.run_id = p_run_id
    ) AS current_rows;
    IF v_run.source_sha256 IS DISTINCT FROM
            pg_catalog.decode(p_observed_source_sha256, 'hex')
       OR v_run.target_sha256 IS DISTINCT FROM v_target
       OR v_rehearsal.target_sha256 IS DISTINCT FROM v_target THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing V1 adoption readiness evidence drifted';
    END IF;
END;
$_$;


ALTER FUNCTION platform.billing_assert_v1_adoption_ready_v1(p_operation_id uuid, p_run_id uuid, p_observed_source_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_commit_restored_license_v1(uuid, uuid, text, uuid, uuid, uuid, uuid, bigint, text, bigint, text, bigint, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, jsonb, jsonb, bytea, bytea, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_commit_restored_license_v1(p_operation_id uuid, p_restore_receipt_id uuid, p_restore_receipt_sha256 text, p_license_binding_id uuid, p_license_id uuid, p_licensee_organization_id uuid, p_environment_id uuid, p_previous_sequence bigint, p_previous_sha256 text, p_next_sequence bigint, p_next_sha256 text, p_expected_revision bigint, p_delivery_kind text, p_issuer text, p_key_id text, p_status text, p_issued_at timestamp with time zone, p_not_before timestamp with time zone, p_refresh_after timestamp with time zone, p_grant_valid_until timestamp with time zone, p_grace_until timestamp with time zone, p_commercial_expires_at timestamp with time zone, p_release_channel text, p_features jsonb, p_limits jsonb, p_canonical_payload bytea, p_signed_document bytea, p_projection jsonb) RETURNS TABLE(operation_id uuid, restore_receipt_id uuid, license_binding_id uuid, previous_sequence bigint, previous_sha256 text, accepted_sequence bigint, accepted_sha256 text, authority_revision bigint, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_receipt platform.billing_license_restore_receipts%ROWTYPE;
    v_head platform.billing_license_heads%ROWTYPE;
    v_snapshot_id uuid;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR p_restore_receipt_id IS NULL OR p_license_binding_id IS NULL
       OR p_restore_receipt_sha256 !~ '^[0-9a-f]{64}$'
       OR p_previous_sequence < 1 OR p_next_sequence <= p_previous_sequence
       OR p_previous_sha256 !~ '^[0-9a-f]{64}$'
       OR p_next_sha256 !~ '^[0-9a-f]{64}$'
       OR p_expected_revision < 1
       OR p_next_sha256 IS DISTINCT FROM pg_catalog.encode(
            pg_catalog.sha256(p_canonical_payload), 'hex')
       OR p_delivery_kind NOT IN ('connected', 'airgap', 'development')
       OR p_status NOT IN ('active', 'suspended', 'revoked', 'expired')
       OR pg_catalog.octet_length(p_issuer) NOT BETWEEN 1 AND 256
       OR p_key_id !~ '^[a-z0-9][a-z0-9._-]{0,63}$'
       OR p_release_channel !~ '^[a-z0-9][a-z0-9._-]{0,63}$'
       OR pg_catalog.jsonb_typeof(p_features) <> 'object'
       OR pg_catalog.jsonb_typeof(p_limits) <> 'object'
       OR pg_catalog.octet_length(p_signed_document) NOT BETWEEN 2 AND 65536 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'restored license commit is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'billing-restored-license|' || p_operation_id::text, 0
    ));
    SELECT receipt.* INTO v_receipt
    FROM platform.billing_license_restore_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt.restore_receipt_id IS DISTINCT FROM p_restore_receipt_id
           OR v_receipt.restore_receipt_sha256 IS DISTINCT FROM
                p_restore_receipt_sha256
           OR v_receipt.license_binding_id IS DISTINCT FROM p_license_binding_id
           OR v_receipt.license_id IS DISTINCT FROM p_license_id
           OR v_receipt.licensee_organization_id IS DISTINCT FROM
                p_licensee_organization_id
           OR v_receipt.environment_id IS DISTINCT FROM p_environment_id
           OR v_receipt.previous_sequence IS DISTINCT FROM p_previous_sequence
           OR v_receipt.previous_sha256 IS DISTINCT FROM p_previous_sha256
           OR v_receipt.accepted_sequence IS DISTINCT FROM p_next_sequence
           OR v_receipt.accepted_sha256 IS DISTINCT FROM p_next_sha256
           OR v_receipt.expected_revision IS DISTINCT FROM p_expected_revision THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'restored license operation was reused';
        END IF;
        RETURN QUERY SELECT p_operation_id, p_restore_receipt_id,
            p_license_binding_id, p_previous_sequence, p_previous_sha256,
            p_next_sequence, p_next_sha256,
            v_receipt.authority_revision, true;
        RETURN;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_license_id::text || '|' || p_environment_id::text, 0
    ));
    SELECT head.* INTO v_head
    FROM platform.billing_license_heads AS head
    WHERE head.license_id = p_license_id
      AND head.environment_id = p_environment_id
    FOR UPDATE;
    IF NOT FOUND OR v_head.sequence IS DISTINCT FROM p_previous_sequence
       OR v_head.payload_sha256 IS DISTINCT FROM p_previous_sha256
       OR v_head.revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'restored license head compare-and-swap failed';
    END IF;
    INSERT INTO platform.billing_license_snapshots (
        license_id, licensee_organization_id, environment_id, delivery_kind,
        issuer, key_id, sequence, payload_sha256, status,
        issued_at, not_before, refresh_after, grant_valid_until,
        grace_until, commercial_expires_at, release_channel,
        features, limits, canonical_payload, signed_document, accepted_at
    ) VALUES (
        p_license_id, p_licensee_organization_id, p_environment_id,
        p_delivery_kind, p_issuer, p_key_id, p_next_sequence, p_next_sha256,
        p_status, p_issued_at, p_not_before, p_refresh_after,
        p_grant_valid_until, p_grace_until, p_commercial_expires_at,
        p_release_channel, p_features, p_limits,
        p_canonical_payload, p_signed_document, v_now
    ) RETURNING snapshot_id INTO v_snapshot_id;
    PERFORM platform.billing_license_projection_insert_v1(
        v_snapshot_id, p_projection, v_now
    );
    UPDATE platform.billing_license_heads
    SET snapshot_id = v_snapshot_id, sequence = p_next_sequence,
        payload_sha256 = p_next_sha256, revision = revision + 1,
        accepted_at = v_now
    WHERE license_id = p_license_id AND environment_id = p_environment_id;
    INSERT INTO platform.billing_license_restore_receipts (
        operation_id, restore_receipt_id, restore_receipt_sha256,
        license_binding_id, license_id, licensee_organization_id,
        environment_id, previous_sequence, previous_sha256,
        snapshot_id, accepted_sequence, accepted_sha256,
        expected_revision, authority_revision, created_at
    ) VALUES (
        p_operation_id, p_restore_receipt_id, p_restore_receipt_sha256,
        p_license_binding_id, p_license_id, p_licensee_organization_id,
        p_environment_id, p_previous_sequence, p_previous_sha256,
        v_snapshot_id, p_next_sequence, p_next_sha256,
        p_expected_revision, p_expected_revision + 1, v_now
    );
    RETURN QUERY SELECT p_operation_id, p_restore_receipt_id,
        p_license_binding_id, p_previous_sequence, p_previous_sha256,
        p_next_sequence, p_next_sha256, p_expected_revision + 1, false;
END;
$_$;


