--
-- Name: billing_convert_v1_storage_megabytes_v1(bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_convert_v1_storage_megabytes_v1(p_megabytes bigint) RETURNS TABLE(is_unlimited boolean, storage_bytes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_megabytes IS NULL OR p_megabytes < -1
       OR p_megabytes > 8583068847 THEN
        RAISE EXCEPTION USING ERRCODE = '22003',
            MESSAGE = 'billing V1 storage limit is outside canonical bounds';
    END IF;
    IF p_megabytes IS NOT DISTINCT FROM -1 THEN
        RETURN QUERY SELECT true, NULL::bigint;
        RETURN;
    END IF;
    RETURN QUERY SELECT false, p_megabytes * 1048576;
END;
$$;


