CREATE FUNCTION platform.billing_create_discount_version_v2(p_authority_id uuid, p_operation_id uuid, p_discount_id uuid, p_version_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_expected_revision bigint, p_code text, p_name text, p_description text, p_available boolean, p_discount_kind text, p_fixed_minor_units bigint, p_currency text, p_currency_registry_version bigint, p_basis_points integer, p_duration text, p_repeating_cycles bigint, p_priority integer, p_global_use_limit bigint, p_per_tenant_use_limit bigint, p_all_offerings boolean, p_expected_offering_count smallint, p_valid_start timestamp with time zone, p_valid_end timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS TABLE(result_discount_id uuid, result_version_id uuid, result_previous_version_id uuid, result_revision bigint, result_version bigint, result_lifecycle text, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored platform.billing_catalog_operations%ROWTYPE;
    previous platform.billing_discount_versions%ROWTYPE;
    updated_revision bigint;
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_authority_id::text || '|' || p_actor_id::text || '|' || p_idempotency_key, 0
    ));
    SELECT operation.* INTO stored
    FROM platform.billing_catalog_operations AS operation
    WHERE operation.authority_id = p_authority_id
      AND operation.actor_id = p_actor_id
      AND operation.idempotency_key = p_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF stored.request_sha256 IS DISTINCT FROM p_request_sha256
           OR stored.aggregate_kind IS DISTINCT FROM 'discount'
           OR stored.operation_kind IS DISTINCT FROM 'create_version' THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'billing catalog idempotency key was reused';
        END IF;
        RETURN QUERY SELECT stored.aggregate_id, stored.result_version_id,
            NULL::uuid, stored.result_revision, stored.result_version,
            stored.result_lifecycle, true;
        RETURN;
    END IF;
    SELECT version_row.* INTO STRICT previous
    FROM platform.billing_discount_versions AS version_row
    WHERE version_row.authority_id = p_authority_id
      AND version_row.discount_id = p_discount_id
    ORDER BY version_row.version DESC, version_row.id ASC
    LIMIT 1
    FOR SHARE;
    UPDATE platform.billing_discounts
    SET revision = revision + 1
    WHERE authority_id = p_authority_id AND id = p_discount_id
      AND normalized_code = p_code
      AND lifecycle = 'active' AND revision = p_expected_revision
    RETURNING revision INTO STRICT updated_revision;
    INSERT INTO platform.billing_discount_versions (
        id, authority_id, discount_id, version, discount_kind,
        fixed_minor_units, currency, currency_registry_version,
        currency_eligible, basis_points, duration, repeating_cycles,
        priority, global_use_limit, per_tenant_use_limit,
        all_offerings, expected_offering_count, publication_operation_id,
        valid_start, valid_end, published_at,
        presentation_name, presentation_description, available
    ) VALUES (
        p_version_id, p_authority_id, p_discount_id, updated_revision,
        p_discount_kind, p_fixed_minor_units, p_currency::character(3),
        p_currency_registry_version,
        CASE WHEN p_discount_kind = 'fixed' THEN true ELSE NULL END,
        p_basis_points, p_duration, p_repeating_cycles, p_priority,
        p_global_use_limit, p_per_tenant_use_limit,
        p_all_offerings, p_expected_offering_count, p_operation_id,
        p_valid_start, p_valid_end, p_occurred_at,
        p_name, p_description, COALESCE(p_available, previous.available)
    );
    INSERT INTO platform.billing_catalog_operations (
        operation_id, authority_id, actor_id, idempotency_key, request_sha256,
        aggregate_kind, aggregate_id, operation_kind, result_version_id,
        result_revision, result_version, result_lifecycle, reason, occurred_at
    ) VALUES (
        p_operation_id, p_authority_id, p_actor_id, p_idempotency_key,
        p_request_sha256, 'discount', p_discount_id, 'create_version',
        p_version_id, updated_revision, updated_revision,
        'active', NULL, p_occurred_at
    );
    RETURN QUERY SELECT p_discount_id, p_version_id, previous.id,
        updated_revision, updated_revision, 'active'::text, false;
END;
$$;


