CREATE FUNCTION platform.billing_create_offering_v2(p_authority_id uuid, p_operation_id uuid, p_offering_id uuid, p_version_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_offering_key text, p_name text, p_description text, p_sort_order integer, p_highlight_label text, p_color text, p_billing_interval text, p_is_public boolean, p_is_base boolean, p_trial_days integer, p_grace_days integer, p_expected_price_count smallint, p_expected_grant_count smallint, p_effective_start timestamp with time zone, p_effective_end timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS TABLE(result_offering_id uuid, result_version_id uuid, result_revision bigint, result_version bigint, result_lifecycle text, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored_request_sha256 bytea;
    stored_aggregate_id uuid;
    stored_version_id uuid;
    stored_revision bigint;
    stored_version bigint;
