        'name', p_name, 'description', p_description,
        'sort_order', p_sort_order, 'highlight_label', p_highlight_label,
        'color', p_color, 'billing_interval', p_billing_interval
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_authority_id::text || '|' || p_actor_id::text || '|' || p_idempotency_key, 0
    ));
    SELECT operation.request_sha256, operation.aggregate_id,
           operation.result_version_id, operation.result_revision,
           operation.result_version, operation.result_lifecycle
      INTO stored_request_sha256, stored_aggregate_id, stored_version_id,
           stored_revision, stored_version, stored_lifecycle
    FROM platform.billing_catalog_operations AS operation
    WHERE operation.authority_id = p_authority_id
      AND operation.actor_id = p_actor_id
      AND operation.idempotency_key = p_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF stored_request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'billing catalog idempotency key was reused';
        END IF;
        RETURN QUERY SELECT stored_aggregate_id, stored_version_id,
            stored_revision, stored_version, stored_lifecycle, true;
        RETURN;
    END IF;
    UPDATE platform.billing_offerings
    SET revision = revision + 1
    WHERE authority_id = p_authority_id AND id = p_offering_id
      AND lifecycle = 'active' AND revision = p_expected_revision
    RETURNING revision INTO updated_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'billing offering revision is stale';
    END IF;
    INSERT INTO platform.billing_offering_versions (
        id, authority_id, offering_id, version, is_base, is_public, available,
        trial_days, grace_days, expected_price_count, expected_grant_count,
        effective_start, effective_end, presentation_metadata,
        presentation_sha256, publication_state, publication_operation_id, published_at
    ) VALUES (
        p_version_id, p_authority_id, p_offering_id, updated_revision,
        p_is_base, p_is_public, p_available, p_trial_days, p_grace_days,
        p_expected_price_count, p_expected_grant_count,
        p_effective_start, p_effective_end, v_metadata,
        pg_catalog.sha256(pg_catalog.convert_to(v_metadata::text, 'UTF8')),
        'published', p_operation_id, p_occurred_at
    );
    INSERT INTO platform.billing_catalog_operations (
        operation_id, authority_id, actor_id, idempotency_key, request_sha256,
        aggregate_kind, aggregate_id, operation_kind, result_version_id,
        result_revision, result_version, result_lifecycle, reason, occurred_at
    ) VALUES (
        p_operation_id, p_authority_id, p_actor_id, p_idempotency_key,
        p_request_sha256, 'offering', p_offering_id, 'create_version',
        p_version_id, updated_revision, updated_revision,
        'active', NULL, p_occurred_at
    );
    RETURN QUERY SELECT p_offering_id, p_version_id, updated_revision,
        updated_revision, 'active'::text, false;
END;
$$;


ALTER FUNCTION platform.billing_create_offering_version_v3(p_authority_id uuid, p_operation_id uuid, p_offering_id uuid, p_version_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_expected_revision bigint, p_name text, p_description text, p_sort_order integer, p_highlight_label text, p_color text, p_billing_interval text, p_is_public boolean, p_available boolean, p_is_base boolean, p_trial_days integer, p_grace_days integer, p_expected_price_count smallint, p_expected_grant_count smallint, p_effective_start timestamp with time zone, p_effective_end timestamp with time zone, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_create_provider_command_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_create_provider_command_v1(p_authority_id uuid, p_tenant_id uuid, p_command_id uuid, p_finalizer_job_id uuid, p_actor_id uuid, p_provider_object_mapping_id uuid, p_subscription_id uuid, p_command_kind text, p_effect_key text, p_request_sha256 bytea, p_requested_at timestamp with time zone) RETURNS TABLE(command_id uuid, finalizer_job_id uuid, tenant_id uuid, actor_id uuid, provider_account_id uuid, provider_object_mapping_id uuid, subscription_id uuid, provider_key text, command_kind text, effect_key text, request_sha256 bytea, state text, requested_at timestamp with time zone, revision bigint, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored platform.billing_provider_commands%ROWTYPE;
    resolved_provider_id uuid;
    resolved_provider_key text;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    IF NOT EXISTS (
        SELECT 1
        FROM platform.billing_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = p_authority_id
          AND authority_row.tenant_id = p_tenant_id
    ) OR pg_catalog.uuid_extract_version(p_command_id) <> 7
       OR pg_catalog.uuid_extract_version(p_finalizer_job_id) <> 7
       OR p_command_id = p_finalizer_job_id
       OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_subscription_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_command_kind NOT IN ('checkout','change','cancel','refund','reconcile')
       OR pg_catalog.octet_length(p_effect_key) NOT BETWEEN 1 AND 256
       OR p_effect_key IS DISTINCT FROM pg_catalog.btrim(p_effect_key)
       OR pg_catalog.octet_length(p_request_sha256) <> 32
       OR NOT pg_catalog.isfinite(p_requested_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing provider command input is invalid';
    END IF;

    SELECT subscription.provider_account_id, account.provider_key
      INTO resolved_provider_id, resolved_provider_key
    FROM platform.billing_subscriptions AS subscription
    JOIN platform.billing_provider_accounts AS account
      ON account.id = subscription.provider_account_id
    WHERE subscription.tenant_id = p_tenant_id
      AND subscription.id = p_subscription_id
      AND account.lifecycle = 'active'
    FOR SHARE OF subscription, account;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5731',
            MESSAGE = 'billing provider command target is invalid';
    END IF;
    IF p_provider_object_mapping_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM platform.billing_provider_objects AS mapping
        WHERE mapping.tenant_id = p_tenant_id
          AND mapping.id = p_provider_object_mapping_id
          AND mapping.provider_account_id = resolved_provider_id
          AND mapping.retired_at IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5731',
            MESSAGE = 'billing provider command mapping is invalid';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'billing:provider-command:' || resolved_provider_id::text ||
        ':' || p_effect_key, 0
    ));
    SELECT * INTO stored
    FROM platform.billing_provider_commands AS command_row
    WHERE command_row.provider_account_id = resolved_provider_id
      AND command_row.effect_key = p_effect_key
    FOR UPDATE;
    IF FOUND THEN
        IF stored.tenant_id IS DISTINCT FROM p_tenant_id
           OR stored.actor_id IS DISTINCT FROM p_actor_id
           OR stored.provider_object_mapping_id IS DISTINCT FROM
              p_provider_object_mapping_id
           OR stored.subscription_id IS DISTINCT FROM p_subscription_id
           OR stored.command_kind IS DISTINCT FROM p_command_kind
           OR stored.request_sha256 IS DISTINCT FROM p_request_sha256
           OR stored.finalizer_job_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P5730',
                MESSAGE = 'billing provider command key was reused';
        END IF;
        RETURN QUERY SELECT stored.id, stored.finalizer_job_id, stored.tenant_id,
            stored.actor_id, stored.provider_account_id,
            stored.provider_object_mapping_id, stored.subscription_id,
            resolved_provider_key, stored.command_kind, stored.effect_key,
            stored.request_sha256, stored.state, stored.requested_at,
            stored.revision, true;
        RETURN;
    END IF;

    INSERT INTO platform.billing_provider_commands (
        id, authority_id, tenant_id, provider_account_id,
        provider_object_mapping_id, subscription_id, command_kind,
        effect_key, request_sha256, state, provider_receipt_reference,
        last_error_code, attempts, requested_at, completed_at, revision,
        actor_id, active_job_id, finalizer_job_id
    ) VALUES (
        p_command_id, p_authority_id, p_tenant_id, resolved_provider_id,
        p_provider_object_mapping_id, p_subscription_id, p_command_kind,
        p_effect_key, p_request_sha256, 'queued', NULL, NULL, 0,
        p_requested_at, NULL, 1, p_actor_id, p_command_id, p_finalizer_job_id
    );
    RETURN QUERY SELECT p_command_id, p_finalizer_job_id, p_tenant_id,
        p_actor_id, resolved_provider_id, p_provider_object_mapping_id,
        p_subscription_id, resolved_provider_key, p_command_kind, p_effect_key,
        p_request_sha256, 'queued'::text, p_requested_at, 1::bigint, false;
END;
$$;


ALTER FUNCTION platform.billing_create_provider_command_v1(p_authority_id uuid, p_tenant_id uuid, p_command_id uuid, p_finalizer_job_id uuid, p_actor_id uuid, p_provider_object_mapping_id uuid, p_subscription_id uuid, p_command_kind text, p_effect_key text, p_request_sha256 bytea, p_requested_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_discount_eligibility_snapshot_read_v1(uuid, uuid, text, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_discount_eligibility_snapshot_read_v1(p_tenant_authority_id uuid, p_tenant_id uuid, p_code text, p_offering_version_id uuid, p_at timestamp with time zone, p_global_authority_id uuid) RETURNS SETOF record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
WITH runtime_guard AS MATERIALIZED (
    SELECT 1
    WHERE SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime'
      AND CURRENT_USER IS NOT DISTINCT FROM 'harpy_owner'
      AND p_tenant_authority_id IS NOT DISTINCT FROM
          platform.billing_resolve_current_tenant_authority_v1(p_tenant_id)
      AND p_global_authority_id IS NOT DISTINCT FROM
          platform.billing_resolve_current_global_authority_v1('billing'::text)
), current_candidates AS MATERIALIZED (
    SELECT subscription.*, pg_catalog.count(*) OVER () AS candidate_count
    FROM runtime_guard
    CROSS JOIN platform.billing_subscriptions AS subscription
    WHERE subscription.authority_id = p_tenant_authority_id
      AND subscription.tenant_id = p_tenant_id
      AND subscription.state IN ('trialing', 'active', 'past_due')
), current_subscription AS MATERIALIZED (
    SELECT * FROM current_candidates ORDER BY updated_at DESC, id LIMIT 1
), candidate AS MATERIALIZED (
    SELECT current_subscription.candidate_count,
           discount_row.id AS discount_id, discount_row.revision,
           version_row.id AS discount_version_id, version_row.version,
           current_subscription.id AS subscription_id,
           current_subscription.offering_version_id,
           current_subscription.price_version_id,
           price.currency::text AS subscription_currency,
           discount_row.normalized_code, version_row.discount_kind,
           version_row.fixed_minor_units, version_row.currency::text,
           version_row.currency_registry_version, version_row.basis_points,
           version_row.duration, version_row.repeating_cycles,
           version_row.priority, version_row.global_use_limit,
           version_row.per_tenant_use_limit, version_row.all_offerings,
           version_row.expected_offering_count,
           version_row.valid_start, version_row.valid_end,
           version_row.available
    FROM current_subscription
    JOIN platform.billing_price_versions AS price
      ON price.id = current_subscription.price_version_id
     AND price.offering_version_id = current_subscription.offering_version_id
    JOIN platform.billing_discounts AS discount_row
      ON discount_row.authority_id = p_global_authority_id
     AND discount_row.normalized_code = p_code
     AND discount_row.lifecycle = 'active'
    JOIN LATERAL (
        SELECT version_row.*
        FROM platform.billing_discount_versions AS version_row
        WHERE version_row.discount_id = discount_row.id
          AND version_row.valid_start <= p_at
          AND (version_row.valid_end IS NULL OR p_at < version_row.valid_end)
        ORDER BY version_row.version DESC, version_row.id
        LIMIT 1
    ) AS version_row ON true
    WHERE p_offering_version_id IS NULL
       OR current_subscription.offering_version_id = p_offering_version_id
)
SELECT p_tenant_id, candidate.candidate_count,
       candidate.discount_id, candidate.revision,
       candidate.discount_version_id, candidate.version,
       candidate.subscription_id, candidate.offering_version_id,
       candidate.price_version_id, candidate.subscription_currency,
       candidate.normalized_code, candidate.discount_kind,
       candidate.fixed_minor_units, candidate.currency,
       candidate.currency_registry_version, candidate.basis_points,
       candidate.duration, candidate.repeating_cycles, candidate.priority,
       candidate.global_use_limit, candidate.per_tenant_use_limit,
       candidate.all_offerings, candidate.expected_offering_count,
       candidate.valid_start, candidate.valid_end, candidate.available,
       (SELECT pg_catalog.count(*)
        FROM platform.billing_discount_redemptions AS redemption
        WHERE redemption.discount_version_id = candidate.discount_version_id),
       (SELECT pg_catalog.count(*)
        FROM platform.billing_discount_redemptions AS redemption
        WHERE redemption.discount_version_id = candidate.discount_version_id
          AND redemption.tenant_id = p_tenant_id),
       (candidate.all_offerings OR EXISTS (
          SELECT 1 FROM platform.billing_discount_offerings AS allowed
          WHERE allowed.discount_version_id = candidate.discount_version_id
            AND allowed.offering_version_id = candidate.offering_version_id
       )),
       EXISTS (
          SELECT 1 FROM platform.billing_discount_redemptions AS redemption
          WHERE redemption.subscription_id = candidate.subscription_id
            AND redemption.discount_version_id = candidate.discount_version_id
       )
FROM candidate;
END;
$$;


ALTER FUNCTION platform.billing_discount_eligibility_snapshot_read_v1(p_tenant_authority_id uuid, p_tenant_id uuid, p_code text, p_offering_version_id uuid, p_at timestamp with time zone, p_global_authority_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_discount_offerings_snapshot_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_discount_offerings_snapshot_read_v1(p_authority_id uuid, p_discount_version_id uuid) RETURNS SETOF uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
SELECT offering_version_id
FROM platform.billing_discount_offerings
WHERE authority_id = p_authority_id
  AND discount_version_id = p_discount_version_id
  AND SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime'
  AND CURRENT_USER IS NOT DISTINCT FROM 'harpy_owner'
  AND p_authority_id IS NOT DISTINCT FROM
      platform.billing_resolve_current_global_authority_v1('billing'::text)
ORDER BY offering_version_id;
END;
$$;


ALTER FUNCTION platform.billing_discount_offerings_snapshot_read_v1(p_authority_id uuid, p_discount_version_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_effective_subscription_price_snapshot_read_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_effective_subscription_price_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid, p_subscription_id uuid, p_at timestamp with time zone) RETURNS TABLE(effective_minor_units bigint, effective_currency text, effective_registry_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_price_version_id uuid;
    v_applied_kind text;
    v_applied_currency text;
    v_applied_registry bigint;
    v_applied_fixed bigint;
    v_applied_basis_points integer;
    v_quotient bigint;
    v_remainder bigint;
    v_discount bigint;
BEGIN
    IF p_authority_id IS NULL OR p_tenant_id IS NULL
       OR p_subscription_id IS NULL OR p_at IS NULL
       OR SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_authority_id IS DISTINCT FROM
          platform.billing_resolve_current_tenant_authority_v1(p_tenant_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing effective snapshot price authority is invalid';
    END IF;
    SELECT subscription.state, subscription.price_version_id,
           price.minor_units, pg_catalog.btrim(price.currency::text),
           price.currency_registry_version
    INTO STRICT v_state, v_price_version_id, effective_minor_units,
        effective_currency, effective_registry_version
    FROM platform.billing_subscriptions AS subscription
    JOIN platform.billing_price_versions AS price
      ON price.id = subscription.price_version_id
     AND price.offering_version_id = subscription.offering_version_id
    WHERE subscription.authority_id = p_authority_id
      AND subscription.tenant_id = p_tenant_id
      AND subscription.id = p_subscription_id;
    IF v_state = 'trialing' THEN
        effective_minor_units := 0;
        RETURN NEXT;
        RETURN;
    END IF;
    FOR v_applied_kind, v_applied_currency, v_applied_registry,
        v_applied_fixed, v_applied_basis_points IN
        SELECT redemption.applied_kind,
               pg_catalog.btrim(redemption.applied_currency::text),
               redemption.applied_currency_registry_version,
               redemption.applied_fixed_minor_units,
               redemption.applied_basis_points
        FROM platform.billing_discount_redemptions AS redemption
        WHERE redemption.authority_id = p_authority_id
          AND redemption.tenant_id = p_tenant_id
          AND redemption.subscription_id = p_subscription_id
          AND redemption.price_version_id = v_price_version_id
          AND redemption.redeemed_at <= p_at
          AND (redemption.relationship_ended_at IS NULL
               OR redemption.relationship_ended_at > p_at)
        ORDER BY redemption.applied_priority, redemption.discount_version_id
    LOOP
        IF v_applied_kind = 'fixed' THEN
            IF v_applied_currency IS DISTINCT FROM effective_currency
               OR v_applied_registry IS DISTINCT FROM effective_registry_version THEN
                RAISE EXCEPTION USING ERRCODE = '23514',
                    MESSAGE = 'billing discount currency invariant failed';
            END IF;
            v_discount := v_applied_fixed;
        ELSE
            SELECT pg_catalog.floor(effective_minor_units::numeric
                       * v_applied_basis_points::numeric / 10000)::bigint,
                   pg_catalog.mod(effective_minor_units::numeric
                       * v_applied_basis_points::numeric, 10000)::bigint
            INTO v_quotient, v_remainder;
            IF v_remainder > 5000
               OR (v_remainder = 5000 AND pg_catalog.mod(v_quotient, 2) = 1) THEN
                v_quotient := v_quotient + 1;
            END IF;
            v_discount := v_quotient;
        END IF;
        effective_minor_units := GREATEST(
            0, effective_minor_units - v_discount
        );
    END LOOP;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.billing_effective_subscription_price_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid, p_subscription_id uuid, p_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_effective_subscription_price_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_effective_subscription_price_v1(p_authority_id uuid, p_tenant_id uuid, p_subscription_id uuid, p_at timestamp with time zone) RETURNS TABLE(effective_minor_units bigint, effective_currency text, effective_registry_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_price_version_id uuid;
    v_applied_kind text;
    v_applied_currency text;
    v_applied_registry bigint;
    v_applied_fixed bigint;
    v_applied_basis_points integer;
    v_quotient bigint;
    v_remainder bigint;
    v_discount bigint;
BEGIN
    IF p_authority_id IS NULL OR p_tenant_id IS NULL
       OR p_subscription_id IS NULL OR p_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing effective price input is invalid';
    END IF;
    PERFORM platform.billing_assert_retained_tenant_authority_v1(
        p_authority_id, p_tenant_id
    );
    SELECT subscription.state, subscription.price_version_id,
           price.minor_units, pg_catalog.btrim(price.currency::text),
           price.currency_registry_version
    INTO STRICT v_state, v_price_version_id, effective_minor_units,
        effective_currency, effective_registry_version
    FROM platform.billing_subscriptions AS subscription
    JOIN platform.billing_price_versions AS price
      ON price.id = subscription.price_version_id
     AND price.offering_version_id = subscription.offering_version_id
    WHERE subscription.authority_id = p_authority_id
      AND subscription.tenant_id = p_tenant_id
      AND subscription.id = p_subscription_id;
    IF v_state = 'trialing' THEN
        effective_minor_units := 0;
        RETURN NEXT;
        RETURN;
    END IF;
    FOR v_applied_kind, v_applied_currency, v_applied_registry,
        v_applied_fixed, v_applied_basis_points IN
        SELECT redemption.applied_kind,
               pg_catalog.btrim(redemption.applied_currency::text),
               redemption.applied_currency_registry_version,
               redemption.applied_fixed_minor_units,
               redemption.applied_basis_points
        FROM platform.billing_discount_redemptions AS redemption
        WHERE redemption.authority_id = p_authority_id
          AND redemption.tenant_id = p_tenant_id
          AND redemption.subscription_id = p_subscription_id
          AND redemption.price_version_id = v_price_version_id
          AND redemption.redeemed_at <= p_at
          AND (redemption.relationship_ended_at IS NULL
               OR redemption.relationship_ended_at > p_at)
        ORDER BY redemption.applied_priority,
                 redemption.discount_version_id
    LOOP
        IF v_applied_kind = 'fixed' THEN
            IF v_applied_currency IS DISTINCT FROM effective_currency
               OR v_applied_registry
                    IS DISTINCT FROM effective_registry_version THEN
                RAISE EXCEPTION USING ERRCODE = '23514',
                    MESSAGE = 'billing discount currency invariant failed';
            END IF;
            v_discount := v_applied_fixed;
        ELSE
            SELECT pg_catalog.floor(
                       effective_minor_units::numeric
                       * v_applied_basis_points::numeric / 10000
                   )::bigint,
                   pg_catalog.mod(
                       effective_minor_units::numeric
                       * v_applied_basis_points::numeric, 10000
                   )::bigint
            INTO v_quotient, v_remainder;
            IF v_remainder > 5000
               OR (v_remainder = 5000 AND pg_catalog.mod(v_quotient, 2) = 1) THEN
                v_quotient := v_quotient + 1;
            END IF;
            v_discount := v_quotient;
        END IF;
        IF v_discount >= effective_minor_units THEN
            effective_minor_units := 0;
        ELSE
            effective_minor_units := effective_minor_units - v_discount;
        END IF;
    END LOOP;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.billing_effective_subscription_price_v1(p_authority_id uuid, p_tenant_id uuid, p_subscription_id uuid, p_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_execute_retention_cycle_v1(uuid, uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_execute_retention_cycle_v1(p_authority_id uuid, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_successor_job_id uuid, p_payload_reference text, p_payload_sha256 text) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_payload_reference text, successor_payload_sha256 text, successor_dedupe_key text, successor_priority integer, raw_bodies_redacted bigint, raw_records_purged bigint, entitlement_records_purged bigint, financial_records_purged bigint, legal_hold_blocked bigint, checkpoint_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    stored platform.billing_retention_receipts%ROWTYPE;
    now_at timestamptz;
    next_at timestamptz;
    next_key text;
    raw_body_count bigint;
    raw_record_count bigint;
    entitlement_count bigint;
    invoice_count bigint;
    subscription_count bigint;
    hold_count bigint;
    checkpoint_value bigint;
    raw_remaining boolean;
    entitlement_remaining boolean;
    invoice_remaining boolean;
    subscription_remaining boolean;
    receipt_digest bytea;
BEGIN
    now_at := pg_catalog.clock_timestamp();
    raw_body_count := 0;
    raw_record_count := 0;
    entitlement_count := 0;
    invoice_count := 0;
    subscription_count := 0;
    hold_count := 0;
    raw_remaining := false;
    entitlement_remaining := false;
    invoice_remaining := false;
    subscription_remaining := false;
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = p_authority_id
          AND authority_row.tenant_id = p_tenant_id
    ) OR pg_catalog.uuid_extract_version(p_job_id) <> 7
       OR pg_catalog.uuid_extract_version(p_attempt_id) <> 7
       OR pg_catalog.uuid_extract_version(p_successor_job_id) <> 7
       OR pg_catalog.octet_length(p_payload_reference) NOT BETWEEN 1 AND 2048
       OR p_payload_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing retention cycle identity is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'billing:retention:' || p_tenant_id::text, 0
    ));
    SELECT * INTO stored
    FROM platform.billing_retention_receipts AS receipt
    WHERE receipt.job_id = p_job_id
    FOR SHARE;
    IF FOUND THEN
        IF stored.authority_id IS DISTINCT FROM p_authority_id
           OR stored.tenant_id IS DISTINCT FROM p_tenant_id
           OR stored.payload_reference IS DISTINCT FROM p_payload_reference
           OR stored.payload_sha256 IS DISTINCT FROM
              pg_catalog.decode(p_payload_sha256, 'hex') THEN
            RAISE EXCEPTION USING ERRCODE = 'P5730',
                MESSAGE = 'billing retention job identity was reused';
        END IF;
        RETURN QUERY SELECT stored.successor_job_id, stored.successor_run_at,
            stored.payload_reference, pg_catalog.encode(stored.payload_sha256, 'hex'),
            stored.successor_dedupe_key, 0,
            stored.raw_bodies_redacted, stored.raw_records_purged,
            stored.entitlement_purged, stored.financial_purged,
            stored.legal_hold_blocked, stored.checkpoint_revision;
        RETURN;
    END IF;

    PERFORM 1 FROM platform.billing_legal_holds AS legal_hold
    WHERE legal_hold.tenant_id = p_tenant_id AND legal_hold.state = 'active'
    FOR SHARE;
    IF FOUND THEN
        hold_count := 1;
    ELSE
        INSERT INTO platform.billing_retention_contexts (
            backend_pid, transaction_id, authority_id, tenant_id, job_id, opened_at
        ) VALUES (
            pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
            p_authority_id, p_tenant_id, p_job_id, now_at
        );
        SELECT result.raw_bodies_redacted, result.raw_records_purged,
               result.has_remaining
          INTO raw_body_count, raw_record_count, raw_remaining
        FROM platform.billing_purge_raw_retention_v1(
            p_authority_id, p_tenant_id, now_at, 500
        ) AS result;
        SELECT result.records_purged, result.has_remaining
          INTO entitlement_count, entitlement_remaining
        FROM platform.billing_purge_entitlement_retention_v1(
            p_authority_id, p_tenant_id, now_at, 500
        ) AS result;
        SELECT result.records_purged, result.has_remaining
          INTO invoice_count, invoice_remaining
        FROM platform.billing_purge_invoice_retention_v1(
            p_authority_id, p_tenant_id, now_at, 100
        ) AS result;
        SELECT result.records_purged, result.has_remaining
          INTO subscription_count, subscription_remaining
        FROM platform.billing_purge_subscription_retention_v1(
            p_authority_id, p_tenant_id, now_at, 100
        ) AS result;
        DELETE FROM platform.billing_retention_contexts AS retention_context
        WHERE retention_context.backend_pid = pg_catalog.pg_backend_pid()
          AND retention_context.transaction_id = pg_catalog.pg_current_xact_id();
    END IF;

    INSERT INTO platform.billing_retention_checkpoints (
        authority_id, tenant_id, revision, cycle_count, last_job_id,
        last_attempt_id, raw_cutoff, entitlement_cutoff, financial_cutoff,
        last_completed_at
    ) VALUES (
        p_authority_id, p_tenant_id, 1, 1, p_job_id, p_attempt_id,
        now_at - INTERVAL '400 days', now_at - INTERVAL '7 years',
        now_at - INTERVAL '10 years', now_at
    ) ON CONFLICT (tenant_id) DO UPDATE SET
        revision = billing_retention_checkpoints.revision + 1,
        cycle_count = billing_retention_checkpoints.cycle_count + 1,
        last_job_id = EXCLUDED.last_job_id,
        last_attempt_id = EXCLUDED.last_attempt_id,
        raw_cutoff = EXCLUDED.raw_cutoff,
        entitlement_cutoff = EXCLUDED.entitlement_cutoff,
        financial_cutoff = EXCLUDED.financial_cutoff,
        last_completed_at = EXCLUDED.last_completed_at
    RETURNING billing_retention_checkpoints.revision INTO checkpoint_value;

    IF hold_count = 0 AND (
        raw_remaining OR entitlement_remaining
        OR invoice_remaining OR subscription_remaining
    ) THEN
        next_at := now_at + INTERVAL '1 minute';
    ELSE
        next_at := (
            pg_catalog.date_trunc('day', now_at AT TIME ZONE 'UTC')
            + INTERVAL '1 day 3 hours'
        ) AT TIME ZONE 'UTC';
    END IF;
    next_key := 'billing:retention:' || p_successor_job_id::text;
    receipt_digest := pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.jsonb_build_array(
            p_job_id, p_tenant_id, p_successor_job_id, next_at,
            raw_body_count, raw_record_count, entitlement_count,
            invoice_count + subscription_count, hold_count, checkpoint_value
        )::text, 'UTF8'
    ));
    INSERT INTO platform.billing_retention_receipts (
        job_id, authority_id, tenant_id, attempt_id, payload_reference,
        payload_sha256, successor_job_id, successor_run_at,
        successor_dedupe_key, raw_bodies_redacted, raw_records_purged,
        entitlement_purged, financial_purged, legal_hold_blocked,
        checkpoint_revision, receipt_sha256, completed_at
    ) VALUES (
        p_job_id, p_authority_id, p_tenant_id, p_attempt_id,
        p_payload_reference, pg_catalog.decode(p_payload_sha256, 'hex'),
        p_successor_job_id, next_at, next_key, raw_body_count, raw_record_count,
        entitlement_count, invoice_count + subscription_count, hold_count,
        checkpoint_value, receipt_digest, now_at
    );
    RETURN QUERY SELECT p_successor_job_id, next_at, p_payload_reference,
        p_payload_sha256, next_key, 0, raw_body_count, raw_record_count,
        entitlement_count, invoice_count + subscription_count,
        hold_count, checkpoint_value;
END;
$_$;


ALTER FUNCTION platform.billing_execute_retention_cycle_v1(p_authority_id uuid, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_successor_job_id uuid, p_payload_reference text, p_payload_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_finalize_authority_successor_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_finalize_authority_successor_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_group_generation bigint;
    v_requested_by uuid;
    v_approved_by uuid;
    v_reason text;
    v_change_reference text;
    v_changed_at timestamptz;
    v_members jsonb;
    v_authority_id uuid;
    v_locked_count integer;
    v_run_hash text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cutover_finalizer'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_operation_id IS NULL OR p_run_id IS NULL
       OR pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_run_id) IS DISTINCT FROM 7
       OR p_acceptance_digest !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721', MESSAGE = 'billing finalized authority successor is denied';
    END IF;
    SELECT operation.* INTO STRICT v_operation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id
      AND operation.run_id = p_run_id
      AND operation.state = 'completed'
      AND operation.domain = 'billing'
      AND (
          (operation.scope_kind = 'global' AND operation.group_id = 'billing')
          OR (
              operation.scope_kind = 'tenant'
              AND operation.group_id = 'billing'
          )
      )
    FOR SHARE;
    SELECT group_row.generation, group_row.requested_by,
           group_row.approved_by, group_row.reason,
           group_row.change_reference, group_row.changed_at
    INTO STRICT v_group_generation, v_requested_by, v_approved_by,
        v_reason, v_change_reference, v_changed_at
    FROM platform.cutover_groups AS group_row
    WHERE group_row.scope_kind = v_operation.scope_kind
      AND group_row.scope_id = v_operation.scope_id
      AND group_row.group_id = v_operation.group_id
      AND group_row.state = 'v2' AND group_row.writer = 'v2'
      AND group_row.generation = v_operation.cutover_generation + 1
      AND group_row.acceptance_digest = p_acceptance_digest
      AND group_row.approved_by IS NOT NULL
      AND group_row.approved_by <> group_row.requested_by
    FOR SHARE;
    SELECT pg_catalog.jsonb_agg(member.domain ORDER BY member.ordinal)
    INTO v_members
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind = v_operation.scope_kind
      AND member.scope_id = v_operation.scope_id
      AND member.group_id = v_operation.group_id;
    IF (
        v_operation.scope_kind = 'global'
        AND v_members IS DISTINCT FROM '["billing"]'::jsonb
    ) OR (
        v_operation.scope_kind = 'tenant'
        AND v_members IS DISTINCT FROM '["billing"]'::jsonb
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721', MESSAGE = 'billing finalized authority members differ';
    END IF;
    PERFORM 1
    FROM platform.cutover_group_members AS member
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member.scope_kind
     AND domain_row.scope_id = member.scope_id
     AND domain_row.domain = member.domain
    WHERE member.scope_kind = v_operation.scope_kind
      AND member.scope_id = v_operation.scope_id
      AND member.group_id = v_operation.group_id
      AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
      AND domain_row.generation = v_group_generation
      AND domain_row.acceptance_digest = p_acceptance_digest
      AND domain_row.requested_by = v_requested_by
      AND domain_row.approved_by = v_approved_by
      AND domain_row.reason = v_reason
      AND domain_row.change_reference = v_change_reference
      AND domain_row.changed_at = v_changed_at
    ORDER BY member.ordinal
    FOR SHARE OF member, domain_row;
    GET DIAGNOSTICS v_locked_count = ROW_COUNT;
    IF (v_operation.scope_kind = 'global' AND v_locked_count IS DISTINCT FROM 1)
       OR (v_operation.scope_kind = 'tenant' AND v_locked_count IS DISTINCT FROM 1)
    THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721', MESSAGE = 'billing finalized authority domains differ';
    END IF;
    v_run_hash := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(p_run_id::text, 'UTF8')), 'hex');
    v_authority_id := (pg_catalog.substring(p_operation_id::text, 1, 19) ||
        '8' || pg_catalog.substring(v_run_hash, 1, 3) || '-' ||
        pg_catalog.substring(v_run_hash, 4, 12))::uuid;
    IF v_operation.scope_kind = 'global' THEN
        PERFORM 1
        FROM platform.billing_global_authorities AS authority
        WHERE authority.authority_id = v_authority_id
          AND authority.scope_id = v_operation.scope_id
          AND authority.authority_group_generation = v_group_generation
          AND authority.authority_domain_generation = v_group_generation;
    ELSE
        PERFORM 1
        FROM platform.billing_tenant_authorities AS authority
        WHERE authority.authority_id = v_authority_id
          AND authority.tenant_id = v_operation.scope_id
          AND authority.authority_group_generation = v_group_generation
          AND authority.billing_generation = v_group_generation;
    END IF;
    IF FOUND THEN
        RETURN v_authority_id;
    END IF;
    BEGIN
        IF v_operation.scope_kind = 'global' THEN
            INSERT INTO platform.billing_global_authorities (
                authority_id, scope_kind, scope_id, authority_group_id,
                authority_group_generation, authority_domain,
                authority_domain_generation, created_at
            ) VALUES (
                v_authority_id, 'global', v_operation.scope_id, 'billing',
                v_group_generation, 'billing', v_group_generation,
                pg_catalog.transaction_timestamp()
            );
        ELSE
            INSERT INTO platform.billing_tenant_authorities (
                authority_id, tenant_id, scope_kind, scope_id,
                authority_group_id, authority_group_generation,
                billing_domain, billing_generation, created_at
            ) VALUES (
                v_authority_id, v_operation.scope_id, 'tenant',
                v_operation.scope_id, 'billing', v_group_generation,
                'billing', v_group_generation,
                pg_catalog.transaction_timestamp()
            );
        END IF;
    EXCEPTION WHEN SQLSTATE '23505' THEN
        IF v_operation.scope_kind = 'global' THEN
            SELECT authority.authority_id INTO STRICT v_authority_id
            FROM platform.billing_global_authorities AS authority
            WHERE authority.authority_id = v_authority_id
              AND authority.scope_id = v_operation.scope_id
              AND authority.authority_group_generation = v_group_generation
              AND authority.authority_domain_generation = v_group_generation;
        ELSE
            SELECT authority.authority_id INTO STRICT v_authority_id
            FROM platform.billing_tenant_authorities AS authority
            WHERE authority.authority_id = v_authority_id
              AND authority.tenant_id = v_operation.scope_id
              AND authority.authority_group_generation = v_group_generation
              AND authority.billing_generation = v_group_generation;
        END IF;
    END;
    RETURN v_authority_id;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
    RAISE EXCEPTION USING ERRCODE = 'P5721', MESSAGE = 'billing finalized authority evidence differs';
END;
$_$;


ALTER FUNCTION platform.billing_finalize_authority_successor_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) OWNER TO harpy_owner;

--
-- Name: billing_finalize_provider_command_v1(uuid, uuid, uuid, bigint, integer, text, text, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_finalize_provider_command_v1(p_tenant_id uuid, p_finalizer_job_id uuid, p_finalizer_attempt_id uuid, p_finalizer_lease_generation bigint, p_finalizer_payload_revision integer, p_finalizer_payload_reference text, p_finalizer_payload_sha256 text, p_command_id uuid, p_next_finalizer_job_id uuid, p_reconciliation_job_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(decision text, command_id uuid, actor_id uuid, provider_key text, active_job_id uuid, finalizer_job_id uuid, request_sha256 text, state text, revision bigint, occurred_at timestamp with time zone, provider_reference text, error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored platform.billing_provider_commands%ROWTYPE;
    authority_row platform.billing_tenant_authorities%ROWTYPE;
    provider_value text;
    expected_kind text;
    active_reference text;
    active_effect_key text;
    active_state text;
    active_attempts integer;
    active_effect_started boolean;
    receipt_status text;
    receipt_reference text;
    active_error text;
    next_state text;
    next_decision text;
    next_error text;
BEGIN
    SELECT command_row.* INTO stored
    FROM platform.billing_provider_commands AS command_row
    JOIN platform.billing_tenant_authorities AS authority
      ON authority.authority_id = command_row.authority_id
     AND authority.tenant_id = command_row.tenant_id
    JOIN platform.billing_provider_accounts AS account
      ON account.id = command_row.provider_account_id
    WHERE command_row.tenant_id = p_tenant_id
      AND command_row.id = p_command_id
    FOR UPDATE OF command_row;
    IF NOT FOUND OR stored.actor_id IS NULL OR stored.active_job_id IS NULL
       OR stored.finalizer_job_id IS DISTINCT FROM p_finalizer_job_id
       OR pg_catalog.uuid_extract_version(p_next_finalizer_job_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_reconciliation_job_id)
          IS DISTINCT FROM 7
       OR p_next_finalizer_job_id IN (p_finalizer_job_id, p_reconciliation_job_id)
       OR p_next_finalizer_job_id = stored.active_job_id
       OR p_reconciliation_job_id IN (p_finalizer_job_id, stored.active_job_id)
       OR NOT pg_catalog.isfinite(p_observed_at)
       OR p_observed_at < stored.requested_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5731',
            MESSAGE = 'billing provider finalizer target is invalid';
    END IF;
    SELECT authority.* INTO authority_row FROM platform.billing_tenant_authorities AS authority
    WHERE authority.authority_id = stored.authority_id;
    SELECT account.provider_key INTO provider_value FROM platform.billing_provider_accounts AS account
    WHERE account.id = stored.provider_account_id;
    IF stored.state IN ('succeeded','failed') THEN
        RETURN QUERY SELECT 'replay'::text, stored.id, stored.actor_id,
            provider_value, stored.active_job_id, stored.finalizer_job_id,
            pg_catalog.encode(stored.request_sha256, 'hex'), stored.state,
            stored.revision, stored.completed_at,
            stored.provider_receipt_reference, stored.last_error_code;
        RETURN;
    END IF;

    IF stored.state = 'reconcile_required' THEN
        expected_kind := 'billing.provider.reconcile';
        active_reference := pg_catalog.concat(
            'billing-provider-reconciliation/', provider_value, '/', stored.id::text
        );
        active_effect_key := pg_catalog.concat(
            'billing:provider:reconcile:',
            pg_catalog.encode(pg_catalog.sha256(
                pg_catalog.convert_to(provider_value, 'UTF8') || '\x00'::bytea ||
                pg_catalog.convert_to(stored.id::text, 'UTF8')
            ), 'hex')
        );
    ELSE
        expected_kind := 'billing.provider.command';
        active_reference := pg_catalog.concat(
            'billing-provider-command/', provider_value, '/', stored.id::text
        );
        active_effect_key := pg_catalog.concat(
            'billing:provider:command:', provider_value, ':', stored.id::text
        );
    END IF;
    SELECT evidence.job_state, evidence.job_attempts,
           evidence.effect_started, evidence.receipt_status,
           evidence.provider_reference, evidence.error_code
      INTO active_state, active_attempts, active_effect_started,
           receipt_status, receipt_reference, active_error
    FROM platform.platform_async_external_effect_evidence_v1(
        p_tenant_id, 'tenant', p_tenant_id,
        authority_row.authority_group_id,
        authority_row.authority_group_generation,
        authority_row.billing_domain, authority_row.billing_generation,
        p_finalizer_job_id, p_finalizer_attempt_id,
        p_finalizer_lease_generation, 'billing.provider.finalize',
        p_finalizer_payload_revision, p_finalizer_payload_reference,
        p_finalizer_payload_sha256,
        pg_catalog.concat('billing:provider:finalize:', p_command_id::text),
        stored.active_job_id, expected_kind, 1, active_reference,
        pg_catalog.encode(stored.request_sha256, 'hex'),
        active_effect_key, active_effect_key, provider_value,
        CASE expected_kind WHEN 'billing.provider.command'
            THEN 'command' ELSE 'reconcile' END,
        stored.id
    ) AS evidence;
    IF active_state IN ('queued','running') THEN
        UPDATE platform.billing_provider_commands AS command_row
           SET finalizer_job_id = p_next_finalizer_job_id,
               revision = command_row.revision + 1
        WHERE command_row.id = stored.id
        RETURNING command_row.* INTO stored;
        RETURN QUERY SELECT 'pending'::text, stored.id, stored.actor_id,
            provider_value, stored.active_job_id, stored.finalizer_job_id,
            pg_catalog.encode(stored.request_sha256, 'hex'), stored.state,
            stored.revision, p_observed_at, stored.provider_receipt_reference,
            stored.last_error_code;
        RETURN;
    END IF;

    IF receipt_status = 'succeeded' THEN
        next_state := 'succeeded';
        next_decision := 'succeeded';
        next_error := NULL;
    ELSIF receipt_status = 'failed' OR NOT active_effect_started THEN
        next_state := 'failed';
        next_decision := 'failed';
        receipt_reference := NULL;
        next_error := COALESCE(
            active_error, 'PROVIDER_COMMAND_FAILED'
        );
    ELSIF stored.state = 'reconcile_required' THEN
        next_state := 'reconcile_required';
        next_decision := 'reconcile_unknown';
        receipt_reference := NULL;
        next_error := 'JOB_OUTCOME_UNKNOWN';
    ELSE
        next_state := 'reconcile_required';
        next_decision := 'reconcile';
        receipt_reference := NULL;
        next_error := 'JOB_OUTCOME_UNKNOWN';
    END IF;

    UPDATE platform.billing_provider_commands AS command_row
       SET state = next_state,
           active_job_id = CASE WHEN next_decision = 'reconcile'
               THEN p_reconciliation_job_id ELSE command_row.active_job_id END,
           finalizer_job_id = CASE WHEN next_decision = 'reconcile'
               THEN p_next_finalizer_job_id ELSE command_row.finalizer_job_id END,
           provider_receipt_reference = receipt_reference,
           last_error_code = next_error,
           attempts = LEAST(
               25, CASE WHEN command_row.state = 'reconcile_required'
                   THEN command_row.attempts + active_attempts
                   ELSE active_attempts END
           ),
           completed_at = p_observed_at,
           revision = command_row.revision + 1
    WHERE command_row.id = stored.id
    RETURNING command_row.* INTO stored;

    RETURN QUERY SELECT next_decision, stored.id, stored.actor_id,
        provider_value, stored.active_job_id, stored.finalizer_job_id,
        pg_catalog.encode(stored.request_sha256, 'hex'), stored.state,
        stored.revision, stored.completed_at,
        stored.provider_receipt_reference, stored.last_error_code;
END;
$$;


ALTER FUNCTION platform.billing_finalize_provider_command_v1(p_tenant_id uuid, p_finalizer_job_id uuid, p_finalizer_attempt_id uuid, p_finalizer_lease_generation bigint, p_finalizer_payload_revision integer, p_finalizer_payload_reference text, p_finalizer_payload_sha256 text, p_command_id uuid, p_next_finalizer_job_id uuid, p_reconciliation_job_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_guard_base_assignment_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_base_assignment_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing base offering assignment is immutable';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'billing:base-offering:' || NEW.tenant_id::text, 0
        )
    );
    IF EXISTS (
        SELECT 1
        FROM platform.billing_tenant_base_offerings AS assignment
        WHERE assignment.tenant_id = NEW.tenant_id
          AND assignment.effective_start <
              COALESCE(NEW.effective_end, 'infinity'::timestamptz)
          AND NEW.effective_start <
              COALESCE(assignment.effective_end, 'infinity'::timestamptz)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23P01',
            CONSTRAINT = 'billing_tenant_base_offerings_no_overlap',
            MESSAGE = 'billing base offering assignments cannot overlap';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_base_assignment_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_campaign_children_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_campaign_children_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    selected_discount_count bigint;
BEGIN
    SELECT pg_catalog.count(*) INTO selected_discount_count
    FROM platform.billing_campaign_discounts
    WHERE authority_id = NEW.authority_id
      AND campaign_version_id = NEW.id;
    IF selected_discount_count IS DISTINCT FROM NEW.expected_discount_count::bigint THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'billing campaign publication children are incomplete';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_campaign_children_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_campaign_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_campaign_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.lifecycle IS DISTINCT FROM 'active'
           OR NEW.revision IS DISTINCT FROM 1
           OR NEW.retired_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'billing campaign initial state is invalid';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing campaign cannot be deleted';
    END IF;
    IF OLD.lifecycle IS DISTINCT FROM 'active'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
       OR NEW.campaign_key IS DISTINCT FROM OLD.campaign_key
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.revision IS DISTINCT FROM OLD.revision + 1
       OR NOT (
           (NEW.lifecycle = 'active' AND NEW.retired_at IS NULL)
           OR (NEW.lifecycle = 'retired' AND NEW.retired_at >= OLD.created_at)
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing campaign transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_campaign_v1() OWNER TO harpy_owner;

