--
-- Name: billing_guard_discount_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_discount_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.lifecycle <> 'active' OR NEW.revision <> 1 OR NEW.revoked_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'billing discount initial state is invalid';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       OR OLD.lifecycle <> 'active'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
       OR NEW.normalized_code IS DISTINCT FROM OLD.normalized_code
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.revision IS DISTINCT FROM OLD.revision + 1
       OR NOT (
           (NEW.lifecycle = 'active' AND NEW.revoked_at IS NULL)
           OR (NEW.lifecycle = 'revoked' AND NEW.revoked_at >= OLD.created_at)
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing discount transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_discount_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_global_binding_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_global_binding_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR SESSION_USER NOT IN (
           'harpy_v2_runtime', 'harpy_adopter', 'harpy_migrator'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global binding session is invalid';
    END IF;
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing global authority binding is immutable';
    END IF;
    PERFORM 1
    FROM platform.environment_identity AS environment
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'global'
     AND group_row.scope_id = environment.environment_id
     AND group_row.group_id = 'billing'
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.domain = 'billing'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE NEW.scope_id = environment.environment_id
      AND NEW.authority_group_generation = group_row.generation
      AND NEW.authority_domain_generation = domain_row.generation
      AND group_row.state = domain_row.state
      AND group_row.writer = domain_row.writer
    FOR SHARE OF group_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing global authority binding is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_global_binding_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_global_binding_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_global_binding_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR SESSION_USER NOT IN (
           'harpy_v2_runtime', 'harpy_adopter', 'harpy_migrator',
           'harpy_cutover_finalizer'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global binding session is invalid';
    END IF;
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing global authority binding is immutable';
    END IF;
    PERFORM 1
    FROM platform.environment_identity AS environment
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'global'
     AND group_row.scope_id = environment.environment_id
     AND group_row.group_id = 'billing'
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.ordinal = 1 AND member_row.domain = 'billing'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE NEW.scope_kind = 'global'
      AND NEW.scope_id = environment.environment_id
      AND NEW.authority_group_id = 'billing'
      AND NEW.authority_domain = 'billing'
      AND NEW.authority_group_generation = group_row.generation
      AND NEW.authority_domain_generation = domain_row.generation
      AND group_row.state = domain_row.state
      AND group_row.writer = domain_row.writer
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS extra
          WHERE extra.scope_kind = group_row.scope_kind
            AND extra.scope_id = group_row.scope_id
            AND extra.group_id = group_row.group_id
            AND NOT (extra.ordinal = 1 AND extra.domain = 'billing')
      )
    FOR SHARE OF group_row, member_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing global authority binding is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_global_binding_v2() OWNER TO harpy_owner;

--
-- Name: billing_guard_global_row_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_global_row_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    selected_authority uuid;
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        selected_authority := OLD.authority_id;
    ELSE
        selected_authority := NEW.authority_id;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'UPDATE'
       AND NEW.authority_id IS DISTINCT FROM OLD.authority_id THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing global authority identity is immutable';
    END IF;
    PERFORM platform.billing_assert_global_authority_v1(selected_authority);
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_global_row_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_immutable_retention_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_immutable_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    previous_row jsonb;
    selected_authority uuid;
    selected_tenant uuid;
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        RETURN NEW;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        previous_row := pg_catalog.to_jsonb(OLD);
        selected_authority := (previous_row ->> 'authority_id')::uuid;
        selected_tenant := (previous_row ->> 'tenant_id')::uuid;
        IF platform.billing_retention_delete_allowed_v1(
            selected_authority, selected_tenant
        ) THEN
            RETURN OLD;
        END IF;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'billing immutable retention change is forbidden';
END;
$$;


ALTER FUNCTION platform.billing_guard_immutable_retention_v1() OWNER TO harpy_owner;

