--
-- Name: billing_guard_invoice_line_retention_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_invoice_line_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE selected_tenant uuid; selected_invoice uuid;
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       AND platform.billing_retention_delete_allowed_v1(
           OLD.authority_id, OLD.tenant_id
       ) THEN
        RETURN OLD;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        selected_tenant := OLD.tenant_id; selected_invoice := OLD.invoice_id;
    ELSE
        selected_tenant := NEW.tenant_id; selected_invoice := NEW.invoice_id;
    END IF;
    PERFORM 1 FROM platform.billing_invoices
    WHERE tenant_id = selected_tenant AND id = selected_invoice AND state = 'draft'
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing finalized invoice lines cannot change';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_invoice_line_retention_v1() OWNER TO harpy_owner;

