    IF NEW.state IS NOT DISTINCT FROM 'finalized' THEN
        SELECT pg_catalog.count(*),
               COALESCE(pg_catalog.sum(gross_minor_units), 0)::bigint,
               COALESCE(pg_catalog.sum(discount_minor_units), 0)::bigint,
               COALESCE(pg_catalog.sum(tax_minor_units), 0)::bigint,
               COALESCE(pg_catalog.sum(debit_adjustment_minor_units), 0)::bigint,
               COALESCE(pg_catalog.sum(credit_adjustment_minor_units), 0)::bigint,
               COALESCE(pg_catalog.sum(line_total_minor_units), 0)::bigint
        INTO selected_line_count, selected_gross, selected_discount,
             selected_tax, selected_debit, selected_credit, selected_total
        FROM platform.billing_invoice_lines
        WHERE tenant_id = NEW.tenant_id AND invoice_id = NEW.id;
        IF selected_line_count = 0 OR selected_gross <> NEW.gross_minor_units
           OR selected_discount <> NEW.discount_minor_units
           OR selected_tax <> NEW.tax_minor_units
           OR selected_debit <> NEW.debit_adjustment_minor_units
           OR selected_credit <> NEW.credit_adjustment_minor_units
           OR selected_total <> NEW.invoice_total_minor_units THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'billing invoice lines do not match final snapshot';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_invoice_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_legal_hold_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_legal_hold_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.state IS DISTINCT FROM 'active' OR NEW.revision IS DISTINCT FROM 1 THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'billing legal hold must begin active';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       OR OLD.state IS DISTINCT FROM 'active'
       OR NEW.state IS DISTINCT FROM 'released'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.placed_by IS DISTINCT FROM OLD.placed_by
       OR NEW.place_operation_id IS DISTINCT FROM OLD.place_operation_id
       OR NEW.place_idempotency_key IS DISTINCT FROM OLD.place_idempotency_key
       OR NEW.place_request_sha256 IS DISTINCT FROM OLD.place_request_sha256
       OR NEW.reason IS DISTINCT FROM OLD.reason
       OR NEW.ticket_reference IS DISTINCT FROM OLD.ticket_reference
       OR NEW.placed_at IS DISTINCT FROM OLD.placed_at
       OR NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing legal hold lifecycle is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_legal_hold_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_license_head_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_license_head_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license head cannot be deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
    IF NEW.license_id IS DISTINCT FROM OLD.license_id
       OR NEW.environment_id IS DISTINCT FROM OLD.environment_id
       OR NEW.sequence <= OLD.sequence
       OR NEW.revision <> OLD.revision + 1
       OR NEW.snapshot_id IS NOT DISTINCT FROM OLD.snapshot_id
       OR NEW.payload_sha256 IS NOT DISTINCT FROM OLD.payload_sha256
       OR NEW.accepted_at < OLD.accepted_at THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license head must advance monotonically';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_license_head_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_license_refresh_attempt_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_license_refresh_attempt_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh attempt cannot be deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
    IF OLD.state <> 'running' OR NEW.state = 'running'
       OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
       OR NEW.attempt IS DISTINCT FROM OLD.attempt
       OR NEW.lease_token IS DISTINCT FROM OLD.lease_token
       OR NEW.claimed_at IS DISTINCT FROM OLD.claimed_at
       OR NEW.lease_until IS DISTINCT FROM OLD.lease_until THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh attempt transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


