--
-- Name: billing_guard_license_refresh_operation_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_license_refresh_operation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh operation cannot be deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
    IF NEW.operation_id IS DISTINCT FROM OLD.operation_id
       OR NEW.license_id IS DISTINCT FROM OLD.license_id
       OR NEW.licensee_organization_id IS DISTINCT FROM OLD.licensee_organization_id
       OR NEW.environment_id IS DISTINCT FROM OLD.environment_id
       OR NEW.delivery_kind IS DISTINCT FROM OLD.delivery_kind
       OR NEW.nonce IS DISTINCT FROM OLD.nonce
       OR NEW.component_versions IS DISTINCT FROM OLD.component_versions
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.current_attempt < OLD.current_attempt
       OR NEW.current_attempt > OLD.current_attempt + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh operation identity is immutable';
    END IF;
    IF NOT (
        (OLD.state = 'pending' AND NEW.state = 'running')
        OR (OLD.state = 'running' AND NEW.state IN ('pending', 'succeeded', 'fenced'))
        OR (OLD.state = 'succeeded' AND NEW.state = 'running')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_license_refresh_operation_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_offering_children_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_offering_children_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    selected_price_count bigint;
    selected_grant_count bigint;
BEGIN
    SELECT pg_catalog.count(*) INTO selected_price_count
    FROM platform.billing_price_versions
    WHERE authority_id = NEW.authority_id
      AND offering_version_id = NEW.id;
    SELECT pg_catalog.count(*) INTO selected_grant_count
    FROM platform.billing_offering_entitlements
    WHERE authority_id = NEW.authority_id
      AND offering_version_id = NEW.id;
    IF selected_price_count IS DISTINCT FROM NEW.expected_price_count::bigint
       OR selected_grant_count IS DISTINCT FROM NEW.expected_grant_count::bigint THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'billing offering publication children are incomplete';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_offering_children_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_offering_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_offering_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.lifecycle <> 'active' OR NEW.revision <> 1 OR NEW.retired_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'billing offering initial state is invalid';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       OR OLD.lifecycle <> 'active'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
       OR NEW.offering_key IS DISTINCT FROM OLD.offering_key
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.revision IS DISTINCT FROM OLD.revision + 1
       OR NOT (
           (NEW.lifecycle = 'active' AND NEW.retired_at IS NULL)
           OR (NEW.lifecycle = 'retired' AND NEW.retired_at >= OLD.created_at)
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing offering transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


