--
-- Name: billing_guard_provider_command_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_provider_command_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF OLD.actor_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.provider_account_id IS DISTINCT FROM OLD.provider_account_id
       OR NEW.provider_object_mapping_id IS DISTINCT FROM
          OLD.provider_object_mapping_id
       OR NEW.subscription_id IS DISTINCT FROM OLD.subscription_id
       OR NEW.command_kind IS DISTINCT FROM OLD.command_kind
       OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
       OR NEW.request_sha256 IS DISTINCT FROM OLD.request_sha256
       OR NEW.requested_at IS DISTINCT FROM OLD.requested_at
       OR NEW.actor_id IS DISTINCT FROM OLD.actor_id
       OR NEW.revision <> OLD.revision + 1
       OR (OLD.state IN ('succeeded','failed'))
       OR NOT (
           (OLD.state IN ('queued','running') AND NEW.state = OLD.state
            AND NEW.active_job_id IS NOT DISTINCT FROM OLD.active_job_id
            AND NEW.finalizer_job_id IS DISTINCT FROM OLD.finalizer_job_id)
           OR (OLD.state IN ('queued','running')
               AND NEW.state = 'reconcile_required'
               AND NEW.active_job_id IS DISTINCT FROM OLD.active_job_id
               AND NEW.finalizer_job_id IS DISTINCT FROM OLD.finalizer_job_id)
           OR (OLD.state IN ('queued','running','reconcile_required')
               AND NEW.state IN ('succeeded','failed')
               AND NEW.active_job_id IS NOT DISTINCT FROM OLD.active_job_id
               AND NEW.finalizer_job_id IS NOT DISTINCT FROM OLD.finalizer_job_id)
           OR (OLD.state = 'reconcile_required'
               AND NEW.state = 'reconcile_required'
               AND NEW.active_job_id IS NOT DISTINCT FROM OLD.active_job_id)
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing provider command transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_provider_command_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_provider_event_retention_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_provider_event_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        RETURN NEW;
    END IF;
    IF NOT platform.billing_retention_delete_allowed_v1(
        OLD.authority_id, OLD.tenant_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing provider event is immutable';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        RETURN OLD;
    END IF;
    IF OLD.webhook_receipt_id IS NOT NULL
       AND NEW.webhook_receipt_id IS NULL
       AND (pg_catalog.to_jsonb(NEW) - 'webhook_receipt_id') =
           (pg_catalog.to_jsonb(OLD) - 'webhook_receipt_id') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'billing provider event retention update is forbidden';
END;
$$;


ALTER FUNCTION platform.billing_guard_provider_event_retention_v1() OWNER TO harpy_owner;

