--
-- Name: billing_guard_settlement_retention_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_settlement_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       AND platform.billing_retention_delete_allowed_v1(
           OLD.authority_id, OLD.tenant_id
       ) THEN
        RETURN OLD;
    END IF;
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing settlement fact is immutable';
    END IF;
    PERFORM 1 FROM platform.billing_invoices
    WHERE tenant_id = NEW.tenant_id AND id = NEW.invoice_id AND state = 'finalized'
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing settlement requires a finalized invoice';
    END IF;
    RETURN NEW;
END;
$$;


