--
-- Name: billing_guard_tenant_binding_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_tenant_binding_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR SESSION_USER NOT IN (
           'harpy_v2_runtime', 'harpy_adopter', 'harpy_migrator'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant binding session is invalid';
    END IF;
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing tenant authority binding is immutable';
    END IF;
    PERFORM 1
    FROM platform.tenants AS tenant
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'tenant'
     AND group_row.scope_id = tenant.id
     AND group_row.group_id = 'billing'
    JOIN platform.domain_cutovers AS billing_row
      ON billing_row.scope_kind = group_row.scope_kind
     AND billing_row.scope_id = group_row.scope_id
     AND billing_row.domain = 'billing'
    WHERE tenant.id = NEW.tenant_id
      AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND NEW.authority_group_generation = group_row.generation
      AND NEW.billing_generation = billing_row.generation
      AND group_row.state = billing_row.state
      AND group_row.writer = billing_row.writer
      AND EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS member_row
          WHERE member_row.scope_kind = group_row.scope_kind
            AND member_row.scope_id = group_row.scope_id
            AND member_row.group_id = group_row.group_id
            AND member_row.domain = 'billing'
          HAVING pg_catalog.count(*) = 1
      )
    FOR SHARE OF tenant, group_row, billing_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing tenant authority binding is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_tenant_binding_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_tenant_binding_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_tenant_binding_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR SESSION_USER NOT IN ('harpy_v2_runtime', 'harpy_adopter',
           'harpy_migrator', 'harpy_cutover_finalizer') THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'billing tenant binding session is invalid';
    END IF;
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'billing tenant authority binding is immutable';
    END IF;
    PERFORM 1
    FROM platform.tenants AS tenant
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'tenant' AND group_row.scope_id = tenant.id
     AND group_row.group_id = 'billing'
    JOIN platform.cutover_group_members AS billing_member
      ON billing_member.scope_kind = group_row.scope_kind
     AND billing_member.scope_id = group_row.scope_id
     AND billing_member.group_id = group_row.group_id
     AND billing_member.ordinal = 1 AND billing_member.domain = 'billing'
    JOIN platform.domain_cutovers AS billing_row
      ON billing_row.scope_kind = group_row.scope_kind
     AND billing_row.scope_id = group_row.scope_id
     AND billing_row.domain = billing_member.domain
    WHERE tenant.id = NEW.tenant_id AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL')
      AND NEW.scope_kind = 'tenant' AND NEW.scope_id = tenant.id
      AND NEW.authority_group_id = 'billing'
      AND NEW.billing_domain = 'billing'
      AND NEW.authority_group_generation = group_row.generation
      AND NEW.billing_generation = billing_row.generation
      AND group_row.state = billing_row.state
      AND group_row.writer = billing_row.writer
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS extra
          WHERE extra.scope_kind = group_row.scope_kind
            AND extra.scope_id = group_row.scope_id
            AND extra.group_id = group_row.group_id
            AND NOT (extra.ordinal = 1 AND extra.domain = 'billing')
      )
    FOR SHARE OF tenant, group_row, billing_member, billing_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721', MESSAGE = 'billing tenant authority binding is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_tenant_binding_v2() OWNER TO harpy_owner;

--
-- Name: billing_guard_tenant_row_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_tenant_row_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    selected_authority uuid;
    selected_tenant uuid;
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        selected_authority := OLD.authority_id;
        selected_tenant := OLD.tenant_id;
    ELSE
        selected_authority := NEW.authority_id;
        selected_tenant := NEW.tenant_id;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'UPDATE' AND (
        NEW.authority_id IS DISTINCT FROM OLD.authority_id
        OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing tenant authority identity is immutable';
    END IF;
    PERFORM platform.billing_assert_tenant_authority_v1(selected_authority);
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = selected_authority
          AND authority_row.tenant_id = selected_tenant
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'billing tenant authority identity does not match tenant';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_tenant_row_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_usage_reservation_retention_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_usage_reservation_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    transition_allowed boolean;
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.state IS DISTINCT FROM 'reserved'
           OR NEW.revision IS DISTINCT FROM 1
           OR NEW.resolved_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'billing usage reservation must begin reserved';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       AND OLD.state IN ('committed', 'released')
       AND platform.billing_retention_delete_allowed_v1(
           OLD.authority_id, OLD.tenant_id
       ) THEN
        RETURN OLD;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.entitlement_key IS DISTINCT FROM OLD.entitlement_key
       OR NEW.meter_period_id IS DISTINCT FROM OLD.meter_period_id
       OR NEW.source_operation_id IS DISTINCT FROM OLD.source_operation_id
       OR NEW.amount IS DISTINCT FROM OLD.amount
       OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing usage reservation identity is immutable';
    END IF;
    transition_allowed :=
        (OLD.state = 'reserved' AND NEW.state = 'reserved'
            AND OLD.effect_started_at IS NULL
            AND NEW.effect_started_at IS NOT NULL
            AND NEW.effect_receipt_id IS NOT NULL)
        OR (OLD.state = 'reserved'
            AND NEW.state IN ('committed', 'released', 'reconcile_required'))
        OR (OLD.state = 'reconcile_required'
            AND NEW.state IN ('committed', 'released'));
    IF NOT transition_allowed THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing usage reservation transition is forbidden';
    END IF;
    IF OLD.effect_started_at IS NOT NULL
       AND NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing usage effect start is immutable';
    END IF;
    IF OLD.effect_receipt_id IS NOT NULL
       AND NEW.effect_receipt_id IS DISTINCT FROM OLD.effect_receipt_id THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing usage effect receipt is immutable';
    END IF;
    IF OLD.resolution_receipt_id IS NOT NULL
       AND NEW.resolution_receipt_id IS DISTINCT FROM OLD.resolution_receipt_id THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing usage resolution receipt is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_usage_reservation_retention_v1() OWNER TO harpy_owner;

