--
-- Name: billing_guard_v1_adoption_plan_chunk_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_v1_adoption_plan_chunk_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP <> 'INSERT' OR
       SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       NOT EXISTS (
           SELECT 1 FROM platform.cutover_operations AS operation
           WHERE operation.operation_id = NEW.operation_id
             AND operation.run_id = NEW.run_id
             AND operation.scope_kind = NEW.scope_kind
             AND operation.scope_id = NEW.scope_id
             AND operation.state IN ('copying', 'shadow', 'quiescing')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption plan chunk mutation denied';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_v1_adoption_plan_chunk_v1() OWNER TO harpy_owner;

--
-- Name: billing_guard_v1_adoption_row_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_guard_v1_adoption_row_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    selected_scope_kind text;
    selected_scope_id uuid;
    selected_authority_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption principal is invalid';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        selected_scope_kind := OLD.scope_kind;
        selected_scope_id := OLD.scope_id;
        selected_authority_id := OLD.authority_id;
    ELSE
        selected_scope_kind := NEW.scope_kind;
        selected_scope_id := NEW.scope_id;
        selected_authority_id := NEW.authority_id;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'UPDATE' AND (
        NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
        OR NEW.scope_id IS DISTINCT FROM OLD.scope_id
        OR NEW.authority_id IS DISTINCT FROM OLD.authority_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing V1 adoption scope is immutable';
    END IF;
    IF selected_scope_kind IS NOT DISTINCT FROM 'global' THEN
        PERFORM platform.billing_assert_global_authority_v1(
            selected_authority_id
        );
        PERFORM 1
        FROM platform.billing_global_authorities AS authority_row
        WHERE authority_row.authority_id = selected_authority_id
          AND authority_row.scope_id = selected_scope_id;
    ELSIF selected_scope_kind IS NOT DISTINCT FROM 'tenant' THEN
        PERFORM platform.billing_assert_tenant_authority_v1(
            selected_authority_id
        );
        PERFORM 1
        FROM platform.billing_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = selected_authority_id
          AND authority_row.tenant_id = selected_scope_id;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption scope kind is invalid';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'billing V1 adoption authority does not match scope';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_guard_v1_adoption_row_v1() OWNER TO harpy_owner;

--
-- Name: billing_installation_assign_v1(uuid, uuid, uuid, uuid, uuid, text, uuid, bigint, text, timestamp with time zone, bigint, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_installation_assign_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_authority_id uuid, p_assignment_id uuid, p_deployment_mode text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.billing_installation_base_assignments%ROWTYPE;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_deployment_mode NOT IN ('onpremise','saas')
       OR p_offering_revision < 1
       OR p_offering_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR NOT pg_catalog.isfinite(p_offering_effective_at)
       OR (p_deployment_mode='onpremise' AND
           (p_source_sequence < 1 OR p_source_sha256 !~ '^[0-9a-f]{64}$'))
       OR (p_deployment_mode='saas' AND
           (p_source_sequence IS NOT NULL OR p_source_sha256 IS NOT NULL)) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='billing installation assignment input is invalid';
    END IF;
    SELECT * INTO v_existing
    FROM platform.billing_installation_base_assignments AS fact
    WHERE fact.operation_id=p_operation_id;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_existing.authority_id IS DISTINCT FROM p_authority_id
           OR v_existing.assignment_id IS DISTINCT FROM p_assignment_id
           OR v_existing.deployment_mode IS DISTINCT FROM p_deployment_mode
           OR v_existing.offering_version_id IS DISTINCT FROM p_offering_version_id
           OR v_existing.offering_revision IS DISTINCT FROM p_offering_revision
           OR v_existing.offering_sha256 IS DISTINCT FROM p_offering_sha256
           OR v_existing.offering_effective_at IS DISTINCT FROM p_offering_effective_at
           OR v_existing.source_sequence IS DISTINCT FROM p_source_sequence
           OR v_existing.source_sha256 IS DISTINCT FROM p_source_sha256
           OR v_existing.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='billing installation assignment replay conflicts';
        END IF;
        RETURN true;
    END IF;
    IF p_deployment_mode='onpremise' THEN
        PERFORM 1 FROM platform.billing_license_offering_publications AS publication
        WHERE publication.environment_id=p_environment_id
          AND publication.offering_version_id=p_offering_version_id
          AND publication.revision=p_offering_revision
          AND publication.offering_sha256=p_offering_sha256
          AND publication.effective_at=p_offering_effective_at
          AND publication.snapshot_sequence=p_source_sequence
          AND publication.snapshot_sha256=p_source_sha256 FOR SHARE;
    ELSE
        PERFORM 1 FROM platform.billing_saas_control_offering_publications AS publication
        WHERE publication.offering_key='saas_platform_control_base_v1'
          AND publication.offering_version_id=p_offering_version_id
          AND publication.revision=p_offering_revision
          AND publication.offering_sha256=p_offering_sha256
          AND publication.effective_at=p_offering_effective_at FOR SHARE;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='billing installation offering pin is unavailable';
    END IF;
    PERFORM platform.billing_register_tenant_authority_v1(
        p_authority_id,p_tenant_id,1,1,v_now
    );
    INSERT INTO platform.billing_tenant_base_offerings (
        id,authority_id,tenant_id,offering_version_id,effective_start,
        effective_end,source_operation_id,created_at
    ) VALUES (
        p_assignment_id,p_authority_id,p_tenant_id,p_offering_version_id,
        p_offering_effective_at,NULL,p_operation_id,v_now
    );
    INSERT INTO platform.billing_installation_base_assignments (
        operation_id,environment_id,tenant_id,authority_id,assignment_id,
        deployment_mode,offering_version_id,offering_revision,offering_sha256,
        offering_effective_at,source_sequence,source_sha256,manifest_sha256,assigned_at
    ) VALUES (
        p_operation_id,p_environment_id,p_tenant_id,p_authority_id,p_assignment_id,
        p_deployment_mode,p_offering_version_id,p_offering_revision,p_offering_sha256,
        p_offering_effective_at,p_source_sequence,p_source_sha256,p_manifest_sha256,v_now
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.billing_installation_assign_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_authority_id uuid, p_assignment_id uuid, p_deployment_mode text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_installation_assign_v2(uuid, uuid, uuid, uuid, uuid, text, uuid, bigint, text, timestamp with time zone, bigint, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_installation_assign_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_authority_id uuid, p_assignment_id uuid, p_deployment_mode text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_manifest_sha256 text, p_binding_purpose text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.billing_installation_base_assignments%ROWTYPE;
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_group_generation bigint;
    v_billing_generation bigint;
    v_replayed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR NOT (
           (p_deployment_mode = 'onpremise'
            AND p_binding_purpose = 'onpremise_primary')
           OR (p_deployment_mode = 'saas'
               AND p_binding_purpose IN ('saas_control','saas_customer'))
       )
       OR p_offering_revision < 1
       OR p_offering_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR NOT pg_catalog.isfinite(p_offering_effective_at)
       OR (p_deployment_mode = 'onpremise' AND (
           p_source_sequence < 1 OR p_source_sha256 !~ '^[0-9a-f]{64}$'
       ))
       OR (p_deployment_mode = 'saas' AND (
           p_source_sequence IS NOT NULL OR p_source_sha256 IS NOT NULL
       )) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing installation assignment input is invalid';
    END IF;
    BEGIN
        SELECT group_row.generation, billing_row.generation
        INTO STRICT v_group_generation, v_billing_generation
        FROM platform.tenants AS tenant
        JOIN platform.cutover_groups AS group_row
          ON group_row.scope_kind = 'tenant'
         AND group_row.scope_id = tenant.id
         AND group_row.group_id = 'billing'
        JOIN platform.cutover_group_members AS billing_member
          ON billing_member.scope_kind = group_row.scope_kind
         AND billing_member.scope_id = group_row.scope_id
         AND billing_member.group_id = group_row.group_id
         AND billing_member.ordinal = 1 AND billing_member.domain = 'billing'
        JOIN platform.domain_cutovers AS billing_row
          ON billing_row.scope_kind = 'tenant'
         AND billing_row.scope_id = tenant.id AND billing_row.domain = 'billing'
        WHERE tenant.id = p_tenant_id AND tenant.deleted_at IS NULL
          AND tenant.status IN ('ACTIVE', 'TRIAL')
          AND group_row.state = 'v2' AND group_row.writer = 'v2'
          AND billing_row.state = 'v2' AND billing_row.writer = 'v2'
          AND NOT EXISTS (
              SELECT 1 FROM platform.cutover_group_members AS extra
              WHERE extra.scope_kind = 'tenant'
                AND extra.scope_id = p_tenant_id
                AND extra.group_id = 'billing'
                AND NOT (extra.ordinal = 1 AND extra.domain = 'billing')
          )
        FOR SHARE OF tenant, group_row, billing_member, billing_row;
    EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing installation current authority is unavailable';
    END;
    SELECT * INTO v_existing
    FROM platform.billing_installation_base_assignments AS fact
    WHERE fact.operation_id = p_operation_id;
    v_replayed := FOUND;
    IF v_replayed AND (
       v_existing.environment_id IS DISTINCT FROM p_environment_id
       OR v_existing.tenant_id IS DISTINCT FROM p_tenant_id
       OR v_existing.authority_id IS DISTINCT FROM p_authority_id
       OR v_existing.assignment_id IS DISTINCT FROM p_assignment_id
       OR v_existing.deployment_mode IS DISTINCT FROM p_deployment_mode
       OR v_existing.offering_version_id IS DISTINCT FROM p_offering_version_id
       OR v_existing.offering_revision IS DISTINCT FROM p_offering_revision
       OR v_existing.offering_sha256 IS DISTINCT FROM p_offering_sha256
       OR v_existing.offering_effective_at IS DISTINCT FROM p_offering_effective_at
       OR v_existing.source_sequence IS DISTINCT FROM p_source_sequence
       OR v_existing.source_sha256 IS DISTINCT FROM p_source_sha256
       OR v_existing.manifest_sha256 IS DISTINCT FROM p_manifest_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'billing installation assignment replay conflicts';
    END IF;
    IF p_binding_purpose = 'onpremise_primary' THEN
        PERFORM 1 FROM platform.billing_license_offering_publications AS publication
        WHERE publication.environment_id = p_environment_id
          AND publication.offering_version_id = p_offering_version_id
          AND publication.revision = p_offering_revision
          AND publication.offering_sha256 = p_offering_sha256
          AND publication.effective_at = p_offering_effective_at
          AND publication.snapshot_sequence = p_source_sequence
          AND publication.snapshot_sha256 = p_source_sha256 FOR SHARE;
    ELSIF p_binding_purpose = 'saas_control' THEN
        PERFORM 1 FROM platform.billing_saas_control_offering_publications AS publication
        WHERE publication.offering_key = 'saas_platform_control_base_v1'
          AND publication.offering_version_id = p_offering_version_id
          AND publication.revision = p_offering_revision
          AND publication.offering_sha256 = p_offering_sha256
          AND publication.effective_at = p_offering_effective_at FOR SHARE;
    ELSE
        PERFORM 1 FROM platform.billing_saas_free_base_publications AS publication
        WHERE publication.offering_key = 'saas_free_base_v1'
          AND publication.offering_version_id = p_offering_version_id
          AND publication.revision = p_offering_revision
          AND publication.offering_sha256 = p_offering_sha256
          AND publication.effective_at = p_offering_effective_at FOR SHARE;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing installation offering pin is unavailable';
    END IF;
    IF v_replayed THEN
        PERFORM platform.billing_assert_tenant_authority_v1(
            v_existing.authority_id
        );
        PERFORM 1 FROM platform.billing_tenant_base_offerings AS assignment
        WHERE assignment.id = v_existing.assignment_id
          AND assignment.authority_id = v_existing.authority_id
          AND assignment.tenant_id = v_existing.tenant_id
          AND assignment.offering_version_id = v_existing.offering_version_id
          AND assignment.effective_start = v_existing.offering_effective_at
          AND assignment.effective_end IS NULL
          AND assignment.source_operation_id = p_operation_id FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing installation base assignment is unavailable';
        END IF;
        RETURN true;
    END IF;
    PERFORM platform.billing_register_tenant_authority_v1(
        p_authority_id, p_tenant_id, v_group_generation,
        v_billing_generation, v_now
    );
    INSERT INTO platform.billing_tenant_base_offerings (
        id, authority_id, tenant_id, offering_version_id, effective_start,
        effective_end, source_operation_id, created_at
    ) VALUES (
        p_assignment_id, p_authority_id, p_tenant_id, p_offering_version_id,
        p_offering_effective_at, NULL, p_operation_id, v_now
    );
    INSERT INTO platform.billing_installation_base_assignments (
        operation_id, environment_id, tenant_id, authority_id, assignment_id,
        deployment_mode, offering_version_id, offering_revision, offering_sha256,
        offering_effective_at, source_sequence, source_sha256,
        manifest_sha256, assigned_at
    ) VALUES (
        p_operation_id, p_environment_id, p_tenant_id, p_authority_id,
        p_assignment_id, p_deployment_mode, p_offering_version_id,
        p_offering_revision, p_offering_sha256, p_offering_effective_at,
        p_source_sequence, p_source_sha256, p_manifest_sha256, v_now
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.billing_installation_assign_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_authority_id uuid, p_assignment_id uuid, p_deployment_mode text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_manifest_sha256 text, p_binding_purpose text) OWNER TO harpy_owner;

--
-- Name: billing_installation_assign_v3(uuid, uuid, uuid, uuid, uuid, text, uuid, bigint, text, timestamp with time zone, bigint, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_installation_assign_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_authority_id uuid, p_assignment_id uuid, p_deployment_mode text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_manifest_sha256 text, p_binding_purpose text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_context platform.billing_installation_assignment_contexts%ROWTYPE;
    v_operation_kind text;
    v_context_found boolean;
    v_replayed boolean;
BEGIN
    IF p_deployment_mode='onpremise'
       AND p_binding_purpose='onpremise_primary' THEN
        v_operation_kind := 'environment_initialize';
    ELSIF p_deployment_mode='saas'
          AND p_binding_purpose='saas_control' THEN
        v_operation_kind := 'environment_initialize';
    ELSIF p_deployment_mode='saas'
          AND p_binding_purpose='saas_customer' THEN
        v_operation_kind := 'saas_customer_tenant_provision';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing installation assignment profile is invalid';
    END IF;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_authority_id IS DISTINCT FROM
            platform.billing_installation_id_v1(
                p_operation_id,'tenant-authority')
       OR p_assignment_id IS DISTINCT FROM
            platform.billing_installation_id_v1(
                p_operation_id,'base-offering-assignment')
       OR platform.tenancy_activation_command_consume_v1(
           p_operation_id,'billing.assign_tenant_base_offering',
           p_environment_id,p_tenant_id,v_operation_kind,p_deployment_mode,
           p_binding_purpose,p_manifest_sha256,p_offering_version_id,
           p_offering_revision,p_offering_sha256,p_offering_effective_at,
           p_source_sequence,p_source_sha256
       ) IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing installation assignment capability is denied';
    END IF;
    SELECT * INTO v_context
    FROM platform.billing_installation_assignment_contexts AS context
    WHERE context.operation_id=p_operation_id FOR SHARE;
    v_context_found := FOUND;
    IF v_context_found AND ROW(
        v_context.deployment_mode,v_context.operation_kind,
        v_context.binding_purpose
    ) IS DISTINCT FROM ROW(
        p_deployment_mode,v_operation_kind,p_binding_purpose
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'billing installation assignment context conflicts';
    END IF;
    v_replayed := platform.billing_installation_assign_v2(
        p_operation_id,p_environment_id,p_tenant_id,p_authority_id,
        p_assignment_id,p_deployment_mode,p_offering_version_id,
        p_offering_revision,p_offering_sha256,p_offering_effective_at,
        p_source_sequence,p_source_sha256,p_manifest_sha256,p_binding_purpose
    );
    IF v_replayed IS DISTINCT FROM v_context_found THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing installation assignment replay differs';
    END IF;
    IF NOT v_context_found THEN
        INSERT INTO platform.billing_installation_assignment_contexts (
            operation_id,deployment_mode,operation_kind,binding_purpose,recorded_at
        ) VALUES (
            p_operation_id,p_deployment_mode,v_operation_kind,
            p_binding_purpose,pg_catalog.transaction_timestamp()
        );
    END IF;
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.billing_installation_assign_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_authority_id uuid, p_assignment_id uuid, p_deployment_mode text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_manifest_sha256 text, p_binding_purpose text) OWNER TO harpy_owner;

--
-- Name: billing_installation_id_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_installation_id_v1(p_operation_id uuid, p_label text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_bytes bytea;
BEGIN
    IF p_operation_id IS NULL OR p_label IS NULL
       OR p_label NOT IN ('tenant-authority','base-offering-assignment') THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing installation identifier label is invalid';
    END IF;
    v_bytes := pg_catalog.substring(pg_catalog.sha256(
        pg_catalog.convert_to('harpy:billing:installation:v1','UTF8')
        || pg_catalog.uuid_send(p_operation_id)
        || pg_catalog.decode('00','hex')
        || pg_catalog.convert_to(p_label,'UTF8')),1,16);
    v_bytes := pg_catalog.set_byte(v_bytes, 6,
        (pg_catalog.get_byte(v_bytes, 6) & 15) | 112);
    v_bytes := pg_catalog.set_byte(v_bytes, 8,
        (pg_catalog.get_byte(v_bytes, 8) & 63) | 128);
    RETURN pg_catalog.encode(v_bytes,'hex')::uuid;
END;
$$;


ALTER FUNCTION platform.billing_installation_id_v1(p_operation_id uuid, p_label text) OWNER TO harpy_owner;

--
-- Name: billing_installation_offering_read_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_installation_offering_read_v1(p_environment_id uuid, p_deployment_mode text) RETURNS TABLE(offering_version_id uuid, revision bigint, offering_sha256 text, effective_at timestamp with time zone, source_sequence bigint, source_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_count bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_environment_id IS NULL
       OR p_deployment_mode NOT IN ('onpremise','saas') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='billing installation offering read denied';
    END IF;
    IF p_deployment_mode='onpremise' THEN
        RETURN QUERY
        SELECT publication.offering_version_id,publication.revision,
            publication.offering_sha256,publication.effective_at,
            publication.snapshot_sequence,publication.snapshot_sha256
        FROM platform.billing_license_heads AS head
        JOIN platform.billing_license_offering_publications AS publication
          ON publication.license_id=head.license_id
         AND publication.environment_id=head.environment_id
         AND publication.snapshot_sequence=head.sequence
         AND publication.snapshot_sha256=head.payload_sha256
        WHERE head.environment_id=p_environment_id;
    ELSE
        RETURN QUERY
        SELECT publication.offering_version_id,publication.revision,
            publication.offering_sha256,publication.effective_at,
            NULL::bigint,NULL::text
        FROM platform.billing_saas_control_offering_publications AS publication
        WHERE publication.offering_key='saas_platform_control_base_v1';
    END IF;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='billing installation offering is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_installation_offering_read_v1(p_environment_id uuid, p_deployment_mode text) OWNER TO harpy_owner;

--
-- Name: billing_installation_open_usage_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_installation_open_usage_v1(p_operation_id uuid, p_tenant_id uuid, p_manifest_sha256 text) RETURNS TABLE(meter_count integer, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_assignment platform.billing_installation_base_assignments%ROWTYPE;
    v_opening platform.billing_installation_usage_openings%ROWTYPE;
    v_count integer;
    v_total_count integer;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='billing installation usage input is invalid';
    END IF;
    SELECT * INTO v_assignment
    FROM platform.billing_installation_base_assignments AS assignment
    WHERE assignment.operation_id=p_operation_id
      AND assignment.tenant_id=p_tenant_id
      AND assignment.manifest_sha256=p_manifest_sha256 FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='billing installation assignment is unavailable';
    END IF;
    SELECT * INTO v_opening
    FROM platform.billing_installation_usage_openings AS opening
    WHERE opening.operation_id=p_operation_id;
    IF FOUND THEN
        IF v_opening.tenant_id IS DISTINCT FROM p_tenant_id THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='billing installation usage replay conflicts';
        END IF;
        RETURN QUERY SELECT v_opening.meter_count,true;
        RETURN;
    END IF;
    INSERT INTO platform.billing_meter_periods (
        id,authority_id,tenant_id,entitlement_definition_id,entitlement_key,
        meter_kind,reset_policy,period_start,period_end,state,closed_at,revision
    ) SELECT pg_catalog.uuidv7(),v_assignment.authority_id,p_tenant_id,
        definition.id,definition.entitlement_key,definition.meter_kind,
        definition.reset_policy,v_assignment.offering_effective_at,
        CASE definition.reset_policy
          WHEN 'calendar_month_utc' THEN pg_catalog.date_trunc(
              'month',v_assignment.offering_effective_at AT TIME ZONE 'UTC'
          ) AT TIME ZONE 'UTC' + interval '1 month'
          WHEN 'billing_period' THEN v_assignment.offering_effective_at + interval '1 month'
          ELSE '9999-12-31T23:59:59Z'::timestamptz
        END,'open',NULL,1
      FROM platform.billing_offering_entitlements AS entitlement
      JOIN platform.billing_entitlement_definitions AS definition
        ON definition.id=entitlement.entitlement_definition_id
      WHERE entitlement.offering_version_id=v_assignment.offering_version_id
        AND definition.meter_kind IS NOT NULL
      ORDER BY definition.entitlement_key;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO platform.billing_usage_totals (
        authority_id,tenant_id,meter_period_id,entitlement_key,meter_kind,
        committed_total,reserved_total,gauge_total,revision,updated_at
    ) SELECT period.authority_id,period.tenant_id,period.id,
        period.entitlement_key,period.meter_kind,0,0,0,1,v_now
      FROM platform.billing_meter_periods AS period
      WHERE period.tenant_id=p_tenant_id
        AND period.period_start=v_assignment.offering_effective_at;
    GET DIAGNOSTICS v_total_count = ROW_COUNT;
    IF v_count IS DISTINCT FROM v_total_count OR v_count < 1 THEN
        RAISE EXCEPTION USING ERRCODE='23503',
            MESSAGE='billing installation usage opening is incomplete';
    END IF;
    INSERT INTO platform.billing_installation_usage_openings (
        operation_id,tenant_id,meter_count,opened_at
    ) VALUES (p_operation_id,p_tenant_id,v_count,v_now);
    RETURN QUERY SELECT v_count,false;
END;
$_$;


ALTER FUNCTION platform.billing_installation_open_usage_v1(p_operation_id uuid, p_tenant_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_installation_open_usage_v2(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_installation_open_usage_v2(p_operation_id uuid, p_tenant_id uuid, p_manifest_sha256 text) RETURNS TABLE(meter_count integer, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR platform.tenancy_activation_step_consume_v1(
           p_operation_id, 'billing.open_tenant_usage'
       ) IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing installation usage opening is denied';
    END IF;
    RETURN QUERY
    SELECT opening.meter_count, opening.replay
    FROM platform.billing_installation_open_usage_v1(
        p_operation_id, p_tenant_id, p_manifest_sha256
    ) AS opening;
END;
$$;


ALTER FUNCTION platform.billing_installation_open_usage_v2(p_operation_id uuid, p_tenant_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_license_clock_read_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_clock_read_v1() RETURNS TABLE(database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing license clock read denied';
    END IF;
    RETURN QUERY SELECT pg_catalog.clock_timestamp();
END;
$$;


ALTER FUNCTION platform.billing_license_clock_read_v1() OWNER TO harpy_owner;

--
-- Name: billing_license_offering_document_valid_v1(uuid, uuid, bigint, timestamp with time zone, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_offering_document_valid_v1(p_snapshot_id uuid, p_offering_version_id uuid, p_revision bigint, p_effective_at timestamp with time zone, p_document jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_snapshot platform.billing_license_snapshots%ROWTYPE;
BEGIN
    SELECT snapshot.* INTO v_snapshot
    FROM platform.billing_license_snapshots AS snapshot
    WHERE snapshot.snapshot_id = p_snapshot_id;
    IF NOT FOUND
       OR pg_catalog.jsonb_typeof(p_document) <> 'object'
       OR (SELECT pg_catalog.count(*)
           FROM pg_catalog.jsonb_object_keys(p_document)) <> 13
       OR p_document ->> 'schema' <>
            'harpy-license-derived-offering.v1'
       OR p_document ->> 'offering_version_id' <>
            p_offering_version_id::text
       OR (p_document ->> 'revision')::bigint <> p_revision
       OR (p_document ->> 'effective_at')::timestamptz <> p_effective_at
       OR p_document ->> 'license_id' <> v_snapshot.license_id::text
       OR p_document ->> 'licensee_organization_id' <>
            v_snapshot.licensee_organization_id::text
       OR p_document ->> 'environment_id' <> v_snapshot.environment_id::text
       OR p_document ->> 'issuer' <> v_snapshot.issuer
       OR (p_document ->> 'snapshot_sequence')::bigint <> v_snapshot.sequence
       OR p_document ->> 'snapshot_sha256' <> v_snapshot.payload_sha256
       OR p_document ->> 'release_channel' <> v_snapshot.release_channel
       OR pg_catalog.jsonb_typeof(p_document -> 'booleans') <> 'array'
       OR pg_catalog.jsonb_array_length(p_document -> 'booleans') <> 5
       OR pg_catalog.jsonb_typeof(p_document -> 'limits') <> 'array'
       OR pg_catalog.jsonb_array_length(p_document -> 'limits') <> 5 THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.billing_license_snapshot_projections AS projection
        WHERE projection.snapshot_id = p_snapshot_id
          AND projection.value_type = 'boolean'
          AND NOT EXISTS (
              SELECT 1
              FROM pg_catalog.jsonb_to_recordset(
                  p_document -> 'booleans'
              ) AS grant_row(key text, value boolean)
              WHERE grant_row.key = projection.entitlement_key
                AND grant_row.value = projection.boolean_value
          )
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_to_recordset(
            p_document -> 'booleans'
        ) AS grant_row(key text, value boolean)
        WHERE NOT EXISTS (
            SELECT 1
            FROM platform.billing_license_snapshot_projections AS projection
            WHERE projection.snapshot_id = p_snapshot_id
              AND projection.value_type = 'boolean'
              AND projection.entitlement_key = grant_row.key
              AND projection.boolean_value = grant_row.value
        )
    ) THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.billing_license_snapshot_projections AS projection
        WHERE projection.snapshot_id = p_snapshot_id
          AND projection.value_type = 'integer'
          AND NOT EXISTS (
              SELECT 1
              FROM pg_catalog.jsonb_to_recordset(
                  p_document -> 'limits'
              ) AS grant_row(key text, value bigint, unlimited boolean)
              WHERE grant_row.key = projection.entitlement_key
                AND grant_row.unlimited = projection.unlimited
                AND grant_row.value = COALESCE(projection.integer_value, 0)
          )
    ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_to_recordset(
            p_document -> 'limits'
        ) AS grant_row(key text, value bigint, unlimited boolean)
        WHERE NOT EXISTS (
            SELECT 1
            FROM platform.billing_license_snapshot_projections AS projection
            WHERE projection.snapshot_id = p_snapshot_id
              AND projection.value_type = 'integer'
              AND projection.entitlement_key = grant_row.key
              AND projection.unlimited = grant_row.unlimited
              AND COALESCE(projection.integer_value, 0) = grant_row.value
        )
    ) THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.billing_license_offering_document_valid_v1(p_snapshot_id uuid, p_offering_version_id uuid, p_revision bigint, p_effective_at timestamp with time zone, p_document jsonb) OWNER TO harpy_owner;

--
-- Name: billing_license_offering_insert_v1(uuid, uuid, uuid, uuid, bigint, timestamp with time zone, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_offering_insert_v1(p_authority_id uuid, p_operation_id uuid, p_offering_id uuid, p_offering_version_id uuid, p_revision bigint, p_effective_at timestamp with time zone, p_snapshot_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_snapshot platform.billing_license_snapshots%ROWTYPE;
    v_metadata jsonb;
    v_count integer;
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    SELECT snapshot.* INTO v_snapshot
    FROM platform.billing_license_snapshots AS snapshot
    WHERE snapshot.snapshot_id = p_snapshot_id;
    IF NOT FOUND OR p_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing license offering input is invalid';
    END IF;
    v_metadata := pg_catalog.jsonb_build_object(
        'name', 'Harpy License',
        'description', 'License-derived on-premise base offering',
        'sort_order', 0,
        'highlight_label', '',
        'color', '',
        'billing_interval', 'monthly'
    );
    INSERT INTO platform.billing_offerings (
        id, authority_id, offering_key, lifecycle,
        created_at, retired_at, revision
    ) VALUES (
        p_offering_id, p_authority_id,
        'license.' || v_snapshot.license_id::text || '.'
            || v_snapshot.environment_id::text,
        'active', p_effective_at, NULL, p_revision
    );
    INSERT INTO platform.billing_offering_versions (
        id, authority_id, offering_id, version,
        is_base, is_public, available, trial_days, grace_days,
        expected_price_count, expected_grant_count,
        effective_start, effective_end, presentation_metadata,
        presentation_sha256, publication_state,
        publication_operation_id, published_at
    ) VALUES (
        p_offering_version_id, p_authority_id, p_offering_id, p_revision,
        true, false, false, 0, 0, 1, 10,
        p_effective_at, NULL, v_metadata,
        pg_catalog.sha256(pg_catalog.convert_to(v_metadata::text, 'UTF8')),
        'published', p_operation_id, p_effective_at
    );
    INSERT INTO platform.billing_price_versions (
        id, authority_id, offering_version_id, cadence,
        minor_units, currency, currency_registry_version,
        currency_eligible, effective_start, effective_end,
        money_policy_version, published_at
    ) VALUES (
        pg_catalog.gen_random_uuid(), p_authority_id,
        p_offering_version_id, 'one_time', 0, 'USD', 1,
        true, p_effective_at, NULL, 'fc_money_v1', p_effective_at
    );
    INSERT INTO platform.billing_offering_entitlements (
        authority_id, offering_version_id, entitlement_definition_id,
        value_type, definition_allows_unlimited, boolean_value,
        integer_value, unlimited, created_at
    )
    SELECT p_authority_id, p_offering_version_id, definition.id,
           definition.value_type, definition.unlimited_allowed,
           projection.boolean_value, projection.integer_value,
           projection.unlimited, p_effective_at
    FROM platform.billing_license_snapshot_projections AS projection
    JOIN platform.billing_entitlement_definitions AS definition
      ON definition.entitlement_key = projection.entitlement_key
     AND definition.value_type = projection.value_type
     AND (NOT projection.unlimited OR definition.unlimited_allowed)
    WHERE projection.snapshot_id = p_snapshot_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 10 THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'billing license offering grants are incomplete';
    END IF;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.billing_license_offering_insert_v1(p_authority_id uuid, p_operation_id uuid, p_offering_id uuid, p_offering_version_id uuid, p_revision bigint, p_effective_at timestamp with time zone, p_snapshot_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_license_projection_insert_v1(uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_projection_insert_v1(p_snapshot_id uuid, p_projection jsonb, p_created_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_keys text;
    v_count integer;
BEGIN
    IF pg_catalog.jsonb_typeof(p_projection) <> 'array'
       OR pg_catalog.jsonb_array_length(p_projection) <> 10
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(p_projection) AS item
           WHERE pg_catalog.jsonb_typeof(item) <> 'object'
              OR (SELECT pg_catalog.count(*)
                  FROM pg_catalog.jsonb_object_keys(item)) <> 5
              OR NOT item ? 'entitlement_key'
              OR NOT item ? 'value_type'
              OR NOT item ? 'boolean_value'
              OR NOT item ? 'integer_value'
              OR NOT item ? 'unlimited'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing license projection shape is invalid';
    END IF;
    SELECT pg_catalog.string_agg(
        grant_row.entitlement_key, ',' ORDER BY grant_row.entitlement_key
    )
    INTO v_keys
    FROM pg_catalog.jsonb_to_recordset(p_projection) AS grant_row(
        entitlement_key text, value_type text, boolean_value boolean,
        integer_value bigint, unlimited boolean
    );
    IF v_keys IS DISTINCT FROM
        'analytics.active_dashboards,analytics.dashboard_builder.enabled,' ||
        'api.access,api.active_endpoints,api.builder.enabled,documents.storage_bytes,' ||
        'iam.active_users,' ||
        'workflow.active_definitions,workflow.builder.enabled,workflow.enabled' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing license projection keys are invalid';
    END IF;
    INSERT INTO platform.billing_license_snapshot_projections (
        snapshot_id, entitlement_key, value_type, boolean_value,
        integer_value, unlimited, created_at
    )
    SELECT p_snapshot_id, grant_row.entitlement_key,
           grant_row.value_type, grant_row.boolean_value,
           grant_row.integer_value, grant_row.unlimited, p_created_at
    FROM pg_catalog.jsonb_to_recordset(p_projection) AS grant_row(
        entitlement_key text, value_type text, boolean_value boolean,
        integer_value bigint, unlimited boolean
    )
    JOIN platform.billing_entitlement_definitions AS definition
      ON definition.entitlement_key = grant_row.entitlement_key
     AND definition.value_type = grant_row.value_type
     AND (NOT grant_row.unlimited OR definition.unlimited_allowed);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 10 THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'billing license projection definitions are incomplete';
    END IF;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.billing_license_projection_insert_v1(p_snapshot_id uuid, p_projection jsonb, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_license_refresh_claim_v1(uuid, uuid, uuid, uuid, text, jsonb, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_refresh_claim_v1(p_operation_id uuid, p_license_id uuid, p_licensee_organization_id uuid, p_environment_id uuid, p_delivery_kind text, p_component_versions jsonb, p_lease_seconds integer) RETURNS TABLE(operation_id uuid, lease_token uuid, license_id uuid, licensee_organization_id uuid, environment_id uuid, delivery_kind text, nonce bytea, head_found boolean, head_sequence bigint, head_sha256 text, database_now timestamp with time zone, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.billing_license_refresh_operations%ROWTYPE;
    v_head platform.billing_license_heads%ROWTYPE;
    v_attempt integer;
    v_lease uuid;
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_until timestamptz;
BEGIN
    v_lease := pg_catalog.gen_random_uuid();
    IF pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR p_license_id IS NULL
       OR p_licensee_organization_id IS NULL
       OR p_environment_id IS NULL
       OR p_delivery_kind NOT IN ('connected', 'airgap', 'development')
       OR p_lease_seconds NOT BETWEEN 5 AND 300
       OR pg_catalog.jsonb_typeof(p_component_versions) <> 'array'
       OR pg_catalog.jsonb_array_length(p_component_versions) NOT BETWEEN 1 AND 64
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(p_component_versions) AS item
           WHERE pg_catalog.jsonb_typeof(item) <> 'object'
              OR (SELECT pg_catalog.count(*)
                  FROM pg_catalog.jsonb_object_keys(item)) <> 2
              OR NOT item ? 'component' OR NOT item ? 'version'
              OR pg_catalog.octet_length(item ->> 'component') NOT BETWEEN 1 AND 64
              OR pg_catalog.octet_length(item ->> 'version') NOT BETWEEN 1 AND 64
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing license refresh claim is invalid';
    END IF;
    INSERT INTO platform.billing_license_refresh_operations (
        operation_id, license_id, licensee_organization_id, environment_id,
        delivery_kind, nonce, component_versions, state, current_attempt,
        lease_token, lease_until, created_at, updated_at, completed_at
    ) VALUES (
        p_operation_id, p_license_id, p_licensee_organization_id,
        p_environment_id, p_delivery_kind,
        pg_catalog.uuid_send(pg_catalog.gen_random_uuid())
            || pg_catalog.uuid_send(pg_catalog.gen_random_uuid()),
        p_component_versions, 'pending', 0, NULL, NULL, v_now, v_now, NULL
    ) ON CONFLICT ON CONSTRAINT billing_license_refresh_operations_pkey
      DO NOTHING;
    SELECT operation.* INTO v_operation
    FROM platform.billing_license_refresh_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF v_operation.license_id IS DISTINCT FROM p_license_id
       OR v_operation.licensee_organization_id IS DISTINCT FROM
            p_licensee_organization_id
       OR v_operation.environment_id IS DISTINCT FROM p_environment_id
       OR v_operation.delivery_kind IS DISTINCT FROM p_delivery_kind
       OR v_operation.component_versions IS DISTINCT FROM p_component_versions THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'billing license refresh operation was reused';
    END IF;
    IF v_operation.state = 'fenced' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh operation is fenced';
    END IF;
    IF v_operation.state = 'running' AND v_operation.lease_until > v_now THEN
        RAISE EXCEPTION USING ERRCODE = '55P03',
            MESSAGE = 'billing license refresh lease is active';
    END IF;
    IF v_operation.state = 'running' THEN
        UPDATE platform.billing_license_refresh_attempts
        SET state = 'lease_expired', finished_at = v_now,
            failure_kind = 'lease_expired'
        WHERE billing_license_refresh_attempts.operation_id = p_operation_id
          AND attempt = v_operation.current_attempt AND state = 'running';
        UPDATE platform.billing_license_refresh_operations
        SET state = 'pending', lease_token = NULL, lease_until = NULL,
            updated_at = v_now
        WHERE billing_license_refresh_operations.operation_id = p_operation_id;
    END IF;
    v_attempt := v_operation.current_attempt + 1;
    v_until := v_now + pg_catalog.make_interval(secs => p_lease_seconds);
    UPDATE platform.billing_license_refresh_operations
    SET state = 'running', current_attempt = v_attempt,
        lease_token = v_lease, lease_until = v_until,
        updated_at = v_now, completed_at = NULL
    WHERE billing_license_refresh_operations.operation_id = p_operation_id
      AND state IN ('pending', 'succeeded');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'billing license refresh claim raced';
    END IF;
    INSERT INTO platform.billing_license_refresh_attempts (
        operation_id, attempt, lease_token, state,
        claimed_at, lease_until, finished_at, failure_kind
    ) VALUES (
        p_operation_id, v_attempt, v_lease, 'running',
        v_now, v_until, NULL, NULL
    );
    SELECT head.* INTO v_head
    FROM platform.billing_license_heads AS head
    WHERE head.license_id = p_license_id
      AND head.environment_id = p_environment_id;
    RETURN QUERY SELECT p_operation_id, v_lease, p_license_id,
        p_licensee_organization_id, p_environment_id, p_delivery_kind,
        v_operation.nonce, FOUND, COALESCE(v_head.sequence, 0),
        COALESCE(v_head.payload_sha256, ''), v_now, v_until;
END;
$$;


ALTER FUNCTION platform.billing_license_refresh_claim_v1(p_operation_id uuid, p_license_id uuid, p_licensee_organization_id uuid, p_environment_id uuid, p_delivery_kind text, p_component_versions jsonb, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: billing_license_refresh_failure_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_refresh_failure_v1(p_operation_id uuid, p_lease_token uuid, p_failure_kind text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.billing_license_refresh_operations%ROWTYPE;
    v_attempt_state text;
    v_operation_state text;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_failure_kind NOT IN (
        'source_unavailable', 'verification_failed',
        'sequence_conflict', 'sequence_rollback'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing license refresh failure kind is invalid';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.billing_license_refresh_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_operation.state <> 'running'
       OR v_operation.lease_token IS DISTINCT FROM p_lease_token THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'billing license refresh failure lease is stale';
    END IF;
    v_attempt_state := CASE p_failure_kind
        WHEN 'source_unavailable' THEN 'source_failed'
        WHEN 'verification_failed' THEN 'verification_failed'
        WHEN 'sequence_conflict' THEN 'sequence_conflict'
        ELSE 'sequence_rollback'
    END;
    v_operation_state := CASE
        WHEN p_failure_kind IN ('source_unavailable', 'verification_failed')
            THEN 'pending'
        ELSE 'fenced'
    END;
    UPDATE platform.billing_license_refresh_attempts
    SET state = v_attempt_state, finished_at = v_now,
        failure_kind = p_failure_kind
    WHERE operation_id = p_operation_id
      AND attempt = v_operation.current_attempt
      AND lease_token = p_lease_token AND state = 'running';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'billing license refresh failure attempt is stale';
    END IF;
    UPDATE platform.billing_license_refresh_operations
    SET state = v_operation_state, lease_token = NULL, lease_until = NULL,
        updated_at = v_now,
        completed_at = CASE WHEN v_operation_state = 'fenced'
            THEN v_now ELSE NULL END
    WHERE operation_id = p_operation_id;
    RETURN v_operation_state;
END;
$$;


ALTER FUNCTION platform.billing_license_refresh_failure_v1(p_operation_id uuid, p_lease_token uuid, p_failure_kind text) OWNER TO harpy_owner;

--
-- Name: billing_license_refresh_target_acquire_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_refresh_target_acquire_v1() RETURNS TABLE(target_found boolean, ready boolean, operation_id uuid, license_id uuid, licensee_organization_id uuid, environment_id uuid, delivery_kind text, target_revision bigint, retry_at timestamp with time zone, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_head platform.billing_license_heads%ROWTYPE;
    v_snapshot platform.billing_license_snapshots%ROWTYPE;
    v_target platform.billing_license_refresh_targets%ROWTYPE;
    v_operation_state text;
    v_count integer;
    v_ready boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR pg_catalog.current_setting('application_name', true)
            <> 'harpy-v2:core-worker' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing license refresh target denied';
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM platform.tenancy_deployment_policy AS policy
          JOIN platform.tenancy_tenant_bindings AS binding
            ON binding.environment_id = policy.environment_id
           AND binding.purpose = 'onpremise_primary'
         WHERE policy.singleton
           AND policy.deployment_mode = 'onpremise'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing license refresh requires onpremise primary';
    END IF;
    SELECT pg_catalog.count(*) INTO v_count
      FROM platform.billing_license_heads AS head
      JOIN platform.billing_license_snapshots AS snapshot
        ON snapshot.snapshot_id = head.snapshot_id
      JOIN platform.tenancy_deployment_policy AS policy
        ON policy.environment_id = head.environment_id
       AND policy.singleton
       AND policy.deployment_mode = 'onpremise'
      JOIN platform.tenancy_tenant_bindings AS binding
        ON binding.environment_id = policy.environment_id
       AND binding.purpose = 'onpremise_primary';
    IF v_count = 0 THEN
        RETURN QUERY SELECT false, false,
            '00000000-0000-0000-0000-000000000000'::uuid,
            '00000000-0000-0000-0000-000000000000'::uuid,
            '00000000-0000-0000-0000-000000000000'::uuid,
            '00000000-0000-0000-0000-000000000000'::uuid,
            ''::text, 0::bigint, v_now + interval '30 seconds', v_now;
        RETURN;
    END IF;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh target is ambiguous';
    END IF;
    SELECT head.* INTO v_head
      FROM platform.billing_license_heads AS head
      JOIN platform.tenancy_deployment_policy AS policy
        ON policy.environment_id = head.environment_id
       AND policy.singleton
       AND policy.deployment_mode = 'onpremise'
      JOIN platform.tenancy_tenant_bindings AS binding
        ON binding.environment_id = policy.environment_id
       AND binding.purpose = 'onpremise_primary'
     FOR SHARE OF head;
    SELECT snapshot.* INTO v_snapshot
      FROM platform.billing_license_snapshots AS snapshot
     WHERE snapshot.snapshot_id = v_head.snapshot_id
     FOR SHARE;
    INSERT INTO platform.billing_license_refresh_targets (
        license_id, environment_id, licensee_organization_id, delivery_kind,
        observed_sequence, observed_sha256, operation_id,
        next_attempt_at, lease_until, revision, updated_at
    ) VALUES (
        v_head.license_id, v_head.environment_id,
        v_snapshot.licensee_organization_id, v_snapshot.delivery_kind,
        v_head.sequence, v_head.payload_sha256, pg_catalog.uuidv7(),
        v_snapshot.refresh_after, NULL, 1, v_now
    ) ON CONFLICT ON CONSTRAINT billing_license_refresh_targets_pkey
      DO NOTHING;
    SELECT * INTO v_target
      FROM platform.billing_license_refresh_targets AS target
     WHERE target.license_id = v_head.license_id
       AND target.environment_id = v_head.environment_id
     FOR UPDATE;
    IF v_target.observed_sequence IS DISTINCT FROM v_head.sequence
       OR v_target.observed_sha256 IS DISTINCT FROM v_head.payload_sha256 THEN
        UPDATE platform.billing_license_refresh_targets AS refresh_target
           SET licensee_organization_id = v_snapshot.licensee_organization_id,
               delivery_kind = v_snapshot.delivery_kind,
               observed_sequence = v_head.sequence,
               observed_sha256 = v_head.payload_sha256,
               operation_id = pg_catalog.uuidv7(),
               next_attempt_at = v_snapshot.refresh_after,
               lease_until = NULL,
               revision = refresh_target.revision + 1, updated_at = v_now
         WHERE refresh_target.license_id = v_head.license_id
           AND refresh_target.environment_id = v_head.environment_id
         RETURNING refresh_target.* INTO v_target;
    END IF;
    SELECT operation.state INTO v_operation_state
      FROM platform.billing_license_refresh_operations AS operation
     WHERE operation.operation_id = v_target.operation_id;
    IF v_operation_state = 'fenced' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing license refresh target is fenced';
    END IF;
    IF v_operation_state = 'succeeded'
       AND v_target.next_attempt_at <= v_now THEN
        UPDATE platform.billing_license_refresh_targets AS refresh_target
           SET operation_id = pg_catalog.uuidv7(), lease_until = NULL,
               revision = refresh_target.revision + 1, updated_at = v_now
         WHERE refresh_target.license_id = v_target.license_id
           AND refresh_target.environment_id = v_target.environment_id
         RETURNING refresh_target.* INTO v_target;
    END IF;
    v_ready := v_target.next_attempt_at <= v_now
        AND (v_target.lease_until IS NULL OR v_target.lease_until <= v_now);
    IF v_ready THEN
        UPDATE platform.billing_license_refresh_targets AS refresh_target
           SET lease_until = v_now + interval '60 seconds',
               next_attempt_at = v_now + interval '5 minutes',
               revision = refresh_target.revision + 1, updated_at = v_now
         WHERE refresh_target.license_id = v_target.license_id
           AND refresh_target.environment_id = v_target.environment_id
         RETURNING refresh_target.* INTO v_target;
    END IF;
    RETURN QUERY SELECT true, v_ready, v_target.operation_id,
        v_target.license_id, v_target.licensee_organization_id,
        v_target.environment_id, v_target.delivery_kind, v_target.revision,
        CASE WHEN v_ready THEN v_target.lease_until
             ELSE GREATEST(v_target.next_attempt_at,
                 COALESCE(v_target.lease_until, v_target.next_attempt_at))
        END, v_now;
END;
$$;


ALTER FUNCTION platform.billing_license_refresh_target_acquire_v1() OWNER TO harpy_owner;

--
-- Name: billing_license_restore_binding_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_restore_binding_v1(p_environment_id uuid) RETURNS TABLE(license_id uuid, licensee_organization_id uuid, environment_id uuid, delivery_kind text, issuer text, sequence bigint, payload_sha256 text, authority_revision bigint, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR pg_catalog.current_setting('application_name', true)
            <> 'harpy-v2:core-operator-license-reconcile'
       OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing restored license binding denied';
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM platform.tenancy_deployment_policy AS policy
          JOIN platform.tenancy_tenant_bindings AS binding
            ON binding.environment_id = policy.environment_id
           AND binding.purpose = 'onpremise_primary'
         WHERE policy.singleton
           AND policy.environment_id = p_environment_id
           AND policy.deployment_mode = 'onpremise'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing restored license requires onpremise primary';
    END IF;
    SELECT pg_catalog.count(*) INTO v_count
      FROM platform.billing_license_heads AS head
      JOIN platform.tenancy_deployment_policy AS policy
        ON policy.environment_id = head.environment_id
       AND policy.singleton
       AND policy.deployment_mode = 'onpremise'
     WHERE head.environment_id = p_environment_id;
    IF v_count = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'billing restored license binding is unavailable';
    END IF;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing restored license binding is ambiguous';
    END IF;
    RETURN QUERY
    SELECT head.license_id, snapshot.licensee_organization_id,
        head.environment_id, snapshot.delivery_kind, snapshot.issuer,
        head.sequence, head.payload_sha256, head.revision,
        pg_catalog.clock_timestamp()
      FROM platform.billing_license_heads AS head
      JOIN platform.billing_license_snapshots AS snapshot
        ON snapshot.snapshot_id = head.snapshot_id
      JOIN platform.tenancy_deployment_policy AS policy
        ON policy.environment_id = head.environment_id
       AND policy.singleton
       AND policy.deployment_mode = 'onpremise'
     WHERE head.environment_id = p_environment_id;
END;
$$;


ALTER FUNCTION platform.billing_license_restore_binding_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_license_runtime_entitlements_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_runtime_entitlements_v1(p_environment_id uuid) RETURNS TABLE(license_id uuid, environment_id uuid, snapshot_sequence bigint, payload_sha256 text, runtime_state text, entitlement_key text, value_type text, boolean_value boolean, integer_value bigint, unlimited boolean, release_channel text, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    RETURN QUERY
    WITH authority AS (
        SELECT snapshot.snapshot_id, snapshot.license_id,
               snapshot.environment_id, snapshot.sequence,
               snapshot.payload_sha256,
               CASE
                   WHEN snapshot.status <> 'active'
                     OR v_now > snapshot.grace_until THEN 'build_off'
                   WHEN v_now > snapshot.grant_valid_until THEN 'grace'
                   ELSE 'valid'
               END AS state
        FROM platform.billing_license_heads AS head
        JOIN platform.billing_license_snapshots AS snapshot
          ON snapshot.snapshot_id = head.snapshot_id
        WHERE head.environment_id = p_environment_id
    )
    SELECT authority.license_id, authority.environment_id,
           authority.sequence, authority.payload_sha256, authority.state,
           projection.entitlement_key, projection.value_type,
           CASE
               WHEN authority.state = 'build_off'
                AND projection.value_type = 'boolean'
                AND projection.entitlement_key NOT IN (
                    'workflow.enabled', 'api.access'
                ) THEN false
               ELSE projection.boolean_value
           END,
           CASE
               WHEN authority.state = 'build_off'
                AND projection.value_type = 'integer' THEN 0
               ELSE projection.integer_value
           END,
           CASE
               WHEN authority.state = 'build_off'
                AND projection.value_type = 'integer' THEN false
               ELSE projection.unlimited
           END,
           snapshot.release_channel, v_now
    FROM authority
    JOIN platform.billing_license_snapshots AS snapshot
      ON snapshot.snapshot_id = authority.snapshot_id
    JOIN platform.billing_license_snapshot_projections AS projection
      ON projection.snapshot_id = authority.snapshot_id
    ORDER BY projection.entitlement_key;
END;
$$;


ALTER FUNCTION platform.billing_license_runtime_entitlements_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_license_snapshot_accept_v1(uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, bigint, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text, jsonb, jsonb, bytea, bytea, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_license_snapshot_accept_v1(p_operation_id uuid, p_lease_token uuid, p_license_id uuid, p_licensee_organization_id uuid, p_environment_id uuid, p_delivery_kind text, p_issuer text, p_key_id text, p_payload_sha256 text, p_status text, p_sequence bigint, p_issued_at timestamp with time zone, p_not_before timestamp with time zone, p_refresh_after timestamp with time zone, p_grant_valid_until timestamp with time zone, p_grace_until timestamp with time zone, p_commercial_expires_at timestamp with time zone, p_release_channel text, p_features jsonb, p_limits jsonb, p_canonical_payload bytea, p_signed_document bytea, p_projection jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.billing_license_refresh_operations%ROWTYPE;
    v_head platform.billing_license_heads%ROWTYPE;
    v_head_found boolean;
    v_snapshot_id uuid;
    v_outcome text;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_sequence < 1 OR p_payload_sha256 !~ '^[0-9a-f]{64}$'
       OR p_payload_sha256 IS DISTINCT FROM pg_catalog.encode(
            pg_catalog.sha256(p_canonical_payload), 'hex')
       OR pg_catalog.octet_length(p_signed_document) NOT BETWEEN 2 AND 65536
       OR p_delivery_kind NOT IN ('connected', 'airgap', 'development')
       OR p_status NOT IN ('active', 'suspended', 'revoked', 'expired')
       OR pg_catalog.octet_length(p_issuer) NOT BETWEEN 1 AND 256
       OR p_issuer <> pg_catalog.btrim(p_issuer)
       OR p_issuer ~ '[[:cntrl:]]'
       OR p_key_id !~ '^[a-z0-9][a-z0-9._-]{0,63}$'
       OR p_release_channel !~ '^[a-z0-9][a-z0-9._-]{0,63}$'
       OR pg_catalog.jsonb_typeof(p_features) <> 'object'
       OR pg_catalog.jsonb_typeof(p_limits) <> 'object'
       OR NOT pg_catalog.isfinite(p_issued_at)
       OR NOT pg_catalog.isfinite(p_not_before)
       OR NOT pg_catalog.isfinite(p_grant_valid_until)
       OR NOT pg_catalog.isfinite(p_grace_until) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing license snapshot acceptance is invalid';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.billing_license_refresh_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_operation.state <> 'running'
       OR v_operation.lease_token IS DISTINCT FROM p_lease_token
       OR v_operation.lease_until <= v_now
       OR v_operation.license_id IS DISTINCT FROM p_license_id
       OR v_operation.licensee_organization_id IS DISTINCT FROM
            p_licensee_organization_id
       OR v_operation.environment_id IS DISTINCT FROM p_environment_id
       OR v_operation.delivery_kind IS DISTINCT FROM p_delivery_kind THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'billing license snapshot acceptance lease is stale';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_license_id::text || '|' || p_environment_id::text, 0
    ));
    SELECT head.* INTO v_head
    FROM platform.billing_license_heads AS head
    WHERE head.license_id = p_license_id
      AND head.environment_id = p_environment_id
    FOR UPDATE;
    v_head_found := FOUND;
    v_outcome := CASE
        WHEN NOT v_head_found THEN 'accepted'
        WHEN p_sequence < v_head.sequence THEN 'sequence_rollback'
        WHEN p_sequence = v_head.sequence
             AND p_payload_sha256 <> v_head.payload_sha256
            THEN 'sequence_conflict'
        WHEN p_sequence = v_head.sequence THEN 'noop'
        ELSE 'accepted'
    END;
    IF v_outcome <> 'accepted' THEN
        INSERT INTO platform.billing_license_verification_receipts (
            operation_id, attempt, license_id, environment_id,
            sequence, payload_sha256, outcome, verified_at
        ) VALUES (
            p_operation_id, v_operation.current_attempt, p_license_id,
            p_environment_id, p_sequence, p_payload_sha256, v_outcome, v_now
        );
        UPDATE platform.billing_license_refresh_attempts
        SET state = v_outcome, finished_at = v_now,
            failure_kind = CASE WHEN v_outcome = 'noop'
                THEN NULL ELSE v_outcome END
        WHERE operation_id = p_operation_id
          AND attempt = v_operation.current_attempt
          AND lease_token = p_lease_token AND state = 'running';
        UPDATE platform.billing_license_refresh_operations
        SET state = CASE WHEN v_outcome = 'noop'
                THEN 'succeeded' ELSE 'fenced' END,
            lease_token = NULL, lease_until = NULL,
            updated_at = v_now, completed_at = v_now
        WHERE operation_id = p_operation_id;
        RETURN v_outcome;
    END IF;
    INSERT INTO platform.billing_license_snapshots (
        license_id, licensee_organization_id, environment_id, delivery_kind,
        issuer, key_id, sequence, payload_sha256, status,
        issued_at, not_before, refresh_after, grant_valid_until,
        grace_until, commercial_expires_at, release_channel,
        features, limits, canonical_payload, signed_document, accepted_at
    ) VALUES (
        p_license_id, p_licensee_organization_id, p_environment_id,
        p_delivery_kind, p_issuer, p_key_id, p_sequence, p_payload_sha256,
        p_status, p_issued_at, p_not_before, p_refresh_after,
        p_grant_valid_until, p_grace_until, p_commercial_expires_at,
        p_release_channel, p_features, p_limits,
        p_canonical_payload, p_signed_document, v_now
    ) RETURNING snapshot_id INTO v_snapshot_id;
    PERFORM platform.billing_license_projection_insert_v1(
        v_snapshot_id, p_projection, v_now
    );
    IF v_head_found THEN
        UPDATE platform.billing_license_heads
        SET snapshot_id = v_snapshot_id, sequence = p_sequence,
            payload_sha256 = p_payload_sha256, revision = revision + 1,
            accepted_at = v_now
        WHERE license_id = p_license_id AND environment_id = p_environment_id;
    ELSE
        INSERT INTO platform.billing_license_heads (
            license_id, environment_id, snapshot_id, sequence,
            payload_sha256, revision, accepted_at
        ) VALUES (
            p_license_id, p_environment_id, v_snapshot_id, p_sequence,
            p_payload_sha256, 1, v_now
        );
    END IF;
    INSERT INTO platform.billing_license_verification_receipts (
        operation_id, attempt, license_id, environment_id,
        sequence, payload_sha256, outcome, verified_at
    ) VALUES (
        p_operation_id, v_operation.current_attempt, p_license_id,
        p_environment_id, p_sequence, p_payload_sha256, 'accepted', v_now
    );
    UPDATE platform.billing_license_refresh_attempts
    SET state = 'succeeded', finished_at = v_now
    WHERE operation_id = p_operation_id
      AND attempt = v_operation.current_attempt
      AND lease_token = p_lease_token AND state = 'running';
    UPDATE platform.billing_license_refresh_operations
    SET state = 'succeeded', lease_token = NULL, lease_until = NULL,
        updated_at = v_now, completed_at = v_now
    WHERE operation_id = p_operation_id;
    RETURN 'accepted';
END;
$_$;


ALTER FUNCTION platform.billing_license_snapshot_accept_v1(p_operation_id uuid, p_lease_token uuid, p_license_id uuid, p_licensee_organization_id uuid, p_environment_id uuid, p_delivery_kind text, p_issuer text, p_key_id text, p_payload_sha256 text, p_status text, p_sequence bigint, p_issued_at timestamp with time zone, p_not_before timestamp with time zone, p_refresh_after timestamp with time zone, p_grant_valid_until timestamp with time zone, p_grace_until timestamp with time zone, p_commercial_expires_at timestamp with time zone, p_release_channel text, p_features jsonb, p_limits jsonb, p_canonical_payload bytea, p_signed_document bytea, p_projection jsonb) OWNER TO harpy_owner;

--
-- Name: billing_maintain_revenue_projection_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_maintain_revenue_projection_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        PERFORM platform.billing_refresh_revenue_projection_v1(OLD.id);
        RETURN OLD;
    END IF;
    PERFORM platform.billing_refresh_revenue_projection_v1(NEW.id);
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.billing_maintain_revenue_projection_v1() OWNER TO harpy_owner;

--
-- Name: billing_metered_resource_feature_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_metered_resource_feature_v1(p_authority_id uuid, p_tenant_id uuid, p_entitlement_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_assignment platform.billing_installation_base_assignments%ROWTYPE;
    v_enabled boolean;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    IF p_entitlement_key NOT IN (
        'api.builder.enabled','analytics.dashboard_builder.enabled'
    ) OR NOT EXISTS (
        SELECT 1
        FROM platform.billing_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = p_authority_id
          AND authority_row.tenant_id = p_tenant_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing metered resource feature input is invalid';
    END IF;

    SELECT assignment.*
    INTO STRICT v_assignment
    FROM platform.billing_installation_base_assignments AS assignment
    WHERE assignment.authority_id = p_authority_id
      AND assignment.tenant_id = p_tenant_id;

    IF v_assignment.deployment_mode = 'onpremise' THEN
        SELECT runtime.boolean_value
        INTO STRICT v_enabled
        FROM platform.billing_license_runtime_entitlements_v1(
            v_assignment.environment_id
        ) AS runtime
        WHERE runtime.entitlement_key = p_entitlement_key
          AND runtime.value_type = 'boolean'
          AND runtime.boolean_value IS NOT NULL;
        RETURN v_enabled;
    END IF;
    IF v_assignment.deployment_mode <> 'saas' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing deployment mode is unavailable';
    END IF;

    SELECT CASE
               WHEN override_row.id IS NOT NULL THEN override_row.boolean_value
               WHEN purchased.entitlement_definition_id IS NOT NULL
                   THEN purchased.boolean_value
               ELSE base_grant.boolean_value
           END
    INTO STRICT v_enabled
    FROM platform.billing_entitlement_definitions AS definition
    JOIN LATERAL (
        SELECT base_assignment.offering_version_id
        FROM platform.billing_tenant_base_offerings AS base_assignment
        WHERE base_assignment.authority_id = p_authority_id
          AND base_assignment.tenant_id = p_tenant_id
          AND base_assignment.effective_start <= pg_catalog.statement_timestamp()
          AND (
              base_assignment.effective_end IS NULL
              OR base_assignment.effective_end > pg_catalog.statement_timestamp()
          )
        ORDER BY base_assignment.effective_start DESC
        LIMIT 1
    ) AS active_base ON true
    LEFT JOIN platform.billing_offering_entitlements AS base_grant
      ON base_grant.offering_version_id = active_base.offering_version_id
     AND base_grant.entitlement_definition_id = definition.id
    LEFT JOIN LATERAL (
        SELECT subscription.id, subscription.offering_version_id
        FROM platform.billing_subscriptions AS subscription
        WHERE subscription.authority_id = p_authority_id
          AND subscription.tenant_id = p_tenant_id
          AND (
              (subscription.state = 'trialing'
               AND pg_catalog.statement_timestamp() < subscription.trial_ends_at)
              OR (subscription.state = 'active'
               AND pg_catalog.statement_timestamp() < subscription.period_end)
              OR (subscription.state = 'past_due'
               AND pg_catalog.statement_timestamp() < subscription.grace_ends_at)
          )
        LIMIT 1
    ) AS active_subscription ON true
    LEFT JOIN platform.billing_offering_entitlements AS purchased
      ON purchased.offering_version_id = active_subscription.offering_version_id
     AND purchased.entitlement_definition_id = definition.id
    LEFT JOIN LATERAL (
        SELECT candidate.*
        FROM platform.billing_subscription_overrides AS candidate
        WHERE candidate.authority_id = p_authority_id
          AND candidate.tenant_id = p_tenant_id
          AND candidate.subscription_id = active_subscription.id
          AND candidate.entitlement_definition_id = definition.id
          AND candidate.effective_start <= pg_catalog.statement_timestamp()
          AND (
              candidate.effective_end IS NULL
              OR candidate.effective_end > pg_catalog.statement_timestamp()
          )
        ORDER BY candidate.effective_start DESC
        LIMIT 1
    ) AS override_row ON true
    WHERE definition.entitlement_key = p_entitlement_key
      AND definition.value_type = 'boolean'
      AND (
          override_row.id IS NOT NULL
          OR purchased.entitlement_definition_id IS NOT NULL
          OR base_grant.entitlement_definition_id IS NOT NULL
      );

    IF v_enabled IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing metered resource feature is unavailable';
    END IF;
    RETURN v_enabled;
EXCEPTION
    WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing metered resource feature is unavailable';
END;
$$;


ALTER FUNCTION platform.billing_metered_resource_feature_v1(p_authority_id uuid, p_tenant_id uuid, p_entitlement_key text) OWNER TO harpy_owner;

--
-- Name: billing_metered_resource_inspect_v1(uuid, uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_metered_resource_inspect_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_mutation_kind text, p_idempotency_key text, p_owner_fact_id uuid) RETURNS TABLE(receipt_found boolean, operation_id uuid, owner_fact_id uuid, request_sha256 bytea, feature_enabled boolean, allowed boolean, gauge_delta bigint, current_amount bigint, limit_amount bigint, unlimited boolean, recorded_at timestamp with time zone, projection_found boolean, counted_state text, projection_revision bigint, projection_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_receipt platform.billing_metered_resource_receipts%ROWTYPE;
    v_projection platform.billing_metered_resources%ROWTYPE;
    v_receipt_found boolean;
    v_projection_found boolean;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    IF p_tenant_id IS NULL OR p_actor_id IS NULL
       OR p_resource_kind NOT IN ('api_endpoint','analytics_dashboard')
       OR p_mutation_kind NOT IN (
           'create','update','publish','revalidate','delete','restore'
       )
       OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
       OR pg_catalog.uuid_extract_version(p_owner_fact_id) IS DISTINCT FROM 7
       OR NOT EXISTS (
           SELECT 1
           FROM platform.billing_tenant_authorities AS authority_row
           WHERE authority_row.authority_id = p_authority_id
             AND authority_row.tenant_id = p_tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing metered resource inspection input is invalid';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_tenant_id::text || '|receipt|' || p_actor_id::text || '|'
        || p_resource_kind || '|' || p_mutation_kind || '|' || p_idempotency_key,
        0
    ));
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_tenant_id::text || '|resource|' || p_resource_kind || '|'
        || p_owner_fact_id::text,
        0
    ));

    SELECT receipt_row.*
    INTO v_receipt
    FROM platform.billing_metered_resource_receipts AS receipt_row
    WHERE receipt_row.tenant_id = p_tenant_id
      AND receipt_row.actor_id = p_actor_id
      AND receipt_row.resource_kind = p_resource_kind
      AND receipt_row.mutation_kind = p_mutation_kind
      AND receipt_row.idempotency_key = p_idempotency_key
    FOR UPDATE;
    v_receipt_found := FOUND;

    SELECT projection_row.*
    INTO v_projection
    FROM platform.billing_metered_resources AS projection_row
    WHERE projection_row.tenant_id = p_tenant_id
      AND projection_row.resource_kind = p_resource_kind
      AND projection_row.owner_fact_id = p_owner_fact_id
    FOR UPDATE;
    v_projection_found := FOUND;

    RETURN QUERY SELECT
        v_receipt_found,
        CASE WHEN v_receipt_found THEN v_receipt.operation_id END,
        CASE WHEN v_receipt_found THEN v_receipt.owner_fact_id END,
        CASE WHEN v_receipt_found THEN v_receipt.request_sha256 END,
        CASE WHEN v_receipt_found THEN v_receipt.feature_enabled ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.allowed ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.gauge_delta ELSE 0 END,
        CASE WHEN v_receipt_found THEN v_receipt.current_amount ELSE 0 END,
        CASE WHEN v_receipt_found THEN v_receipt.limit_amount ELSE 0 END,
        CASE WHEN v_receipt_found THEN v_receipt.unlimited ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.recorded_at END,
        v_projection_found,
        CASE WHEN v_projection_found THEN v_projection.counted_state END,
        CASE WHEN v_projection_found THEN v_projection.revision ELSE 0 END,
        CASE WHEN v_projection_found THEN v_projection.updated_at END;
END;
$_$;


ALTER FUNCTION platform.billing_metered_resource_inspect_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_mutation_kind text, p_idempotency_key text, p_owner_fact_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_metered_resource_reconcile_inspect_v1(uuid, uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_metered_resource_reconcile_inspect_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_idempotency_key text, p_owner_fact_id uuid) RETURNS TABLE(receipt_found boolean, operation_id uuid, request_sha256 bytea, evidence_sha256 bytea, evidence_exists boolean, evidence_active boolean, included_in_opening boolean, changed boolean, gauge_delta bigint, current_amount bigint, limit_amount bigint, unlimited boolean, recorded_at timestamp with time zone, projection_found boolean, counted_state text, projection_revision bigint, projection_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_receipt platform.billing_metered_resource_reconcile_receipts%ROWTYPE;
    v_projection platform.billing_metered_resources%ROWTYPE;
    v_receipt_found boolean;
    v_projection_found boolean;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    IF p_tenant_id IS NULL OR p_actor_id IS NULL
       OR p_resource_kind NOT IN ('api_endpoint','analytics_dashboard')
       OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
       OR pg_catalog.uuid_extract_version(p_owner_fact_id) IS DISTINCT FROM 7
       OR NOT EXISTS (
           SELECT 1 FROM platform.billing_tenant_authorities AS authority_row
           WHERE authority_row.authority_id=p_authority_id
             AND authority_row.tenant_id=p_tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing metered resource reconciliation input is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_tenant_id::text || '|reconcile|' || p_actor_id::text || '|'
        || p_resource_kind || '|' || p_idempotency_key, 0
    ));
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_tenant_id::text || '|resource|' || p_resource_kind || '|'
        || p_owner_fact_id::text, 0
    ));

    SELECT receipt_row.* INTO v_receipt
    FROM platform.billing_metered_resource_reconcile_receipts AS receipt_row
    WHERE receipt_row.tenant_id=p_tenant_id
      AND receipt_row.actor_id=p_actor_id
      AND receipt_row.resource_kind=p_resource_kind
      AND receipt_row.idempotency_key=p_idempotency_key
    FOR UPDATE;
    v_receipt_found := FOUND;

    SELECT projection_row.* INTO v_projection
    FROM platform.billing_metered_resources AS projection_row
    WHERE projection_row.tenant_id=p_tenant_id
      AND projection_row.resource_kind=p_resource_kind
      AND projection_row.owner_fact_id=p_owner_fact_id
    FOR UPDATE;
    v_projection_found := FOUND;

    RETURN QUERY SELECT v_receipt_found,
        CASE WHEN v_receipt_found THEN v_receipt.operation_id END,
        CASE WHEN v_receipt_found THEN v_receipt.request_sha256 END,
        CASE WHEN v_receipt_found THEN v_receipt.evidence_sha256 END,
        CASE WHEN v_receipt_found THEN v_receipt.evidence_exists ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.evidence_active ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.included_in_opening ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.changed ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.gauge_delta ELSE 0 END,
        CASE WHEN v_receipt_found THEN v_receipt.current_amount ELSE 0 END,
        CASE WHEN v_receipt_found THEN v_receipt.limit_amount ELSE 0 END,
        CASE WHEN v_receipt_found THEN v_receipt.unlimited ELSE false END,
        CASE WHEN v_receipt_found THEN v_receipt.recorded_at END,
        v_projection_found,
        CASE WHEN v_projection_found THEN v_projection.counted_state END,
        CASE WHEN v_projection_found THEN v_projection.revision ELSE 0 END,
        CASE WHEN v_projection_found THEN v_projection.updated_at END;
END;
$_$;


ALTER FUNCTION platform.billing_metered_resource_reconcile_inspect_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_idempotency_key text, p_owner_fact_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_metered_resource_reconcile_record_v1(uuid, uuid, uuid, text, uuid, uuid, text, bytea, bytea, boolean, boolean, boolean, boolean, bigint, bigint, bigint, boolean, uuid, uuid, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_metered_resource_reconcile_record_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_operation_id uuid, p_owner_fact_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_evidence_sha256 bytea, p_evidence_exists boolean, p_evidence_active boolean, p_included_in_opening boolean, p_changed boolean, p_gauge_delta bigint, p_current_amount bigint, p_limit_amount bigint, p_unlimited boolean, p_usage_decision_id uuid, p_usage_entry_id uuid, p_before_revision bigint, p_recorded_at timestamp with time zone, p_measured_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_gauge_key text;
    v_want_state text;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    v_want_state := CASE
        WHEN p_evidence_active THEN 'active'
        ELSE 'released'
    END;
    v_gauge_key := CASE p_resource_kind
        WHEN 'api_endpoint' THEN 'api.active_endpoints'
        WHEN 'analytics_dashboard' THEN 'analytics.active_dashboards'
    END;
    IF v_gauge_key IS NULL OR p_actor_id IS NULL
       OR pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_owner_fact_id) IS DISTINCT FROM 7
       OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
       OR pg_catalog.octet_length(p_request_sha256) <> 32
       OR pg_catalog.octet_length(p_evidence_sha256) <> 32
       OR (NOT p_evidence_exists AND p_evidence_active)
       OR (p_included_in_opening
           AND (NOT p_evidence_exists OR NOT p_evidence_active))
       OR p_gauge_delta NOT BETWEEN -1 AND 1
       OR (NOT p_changed AND p_gauge_delta <> 0)
       OR p_current_amount < 0 OR p_limit_amount < 0
       OR (p_unlimited AND p_limit_amount <> 0)
       OR p_before_revision < 0
       OR NOT pg_catalog.isfinite(p_recorded_at)
       OR NOT pg_catalog.isfinite(p_measured_at)
       OR NOT EXISTS (
           SELECT 1 FROM platform.billing_tenant_authorities AS authority_row
           WHERE authority_row.authority_id=p_authority_id
             AND authority_row.tenant_id=p_tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing metered resource reconciliation record is invalid';
    END IF;

    IF p_gauge_delta = 1 AND NOT platform.billing_metered_resource_feature_v1(
        p_authority_id,p_tenant_id,
        CASE p_resource_kind
            WHEN 'api_endpoint' THEN 'api.builder.enabled'
            ELSE 'analytics.dashboard_builder.enabled'
        END
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing metered resource builder is unavailable';
    END IF;

    IF p_gauge_delta <> 0 THEN
        IF p_usage_decision_id IS NULL OR p_usage_entry_id IS NULL
           OR NOT EXISTS (
               SELECT 1
               FROM platform.billing_entitlement_decisions AS decision_row
               JOIN platform.billing_usage_entries AS entry_row
                 ON entry_row.decision_id=decision_row.id
               WHERE decision_row.id=p_usage_decision_id
                 AND decision_row.authority_id=p_authority_id
                 AND decision_row.tenant_id=p_tenant_id
                 AND decision_row.actor_id=p_actor_id
                 AND decision_row.entitlement_key=v_gauge_key
                 AND decision_row.source_operation_id=p_operation_id
                 AND decision_row.requested_amount=p_gauge_delta
                 AND decision_row.current_amount=p_current_amount
                 AND decision_row.unlimited=p_unlimited
                 AND (
                     (p_unlimited AND decision_row.limit_amount IS NULL)
                     OR (NOT p_unlimited
                         AND decision_row.limit_amount=p_limit_amount)
                 )
                 AND decision_row.allowed
                 AND entry_row.id=p_usage_entry_id
                 AND entry_row.authority_id=p_authority_id
                 AND entry_row.tenant_id=p_tenant_id
                 AND entry_row.entitlement_key=v_gauge_key
                 AND entry_row.owner_fact_id=p_operation_id
                 AND entry_row.entry_kind='gauge_delta'
                 AND entry_row.amount_delta=p_gauge_delta
                 AND entry_row.gauge_after=p_current_amount+p_gauge_delta
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing reconciliation usage evidence is unavailable';
        END IF;
    ELSIF p_usage_decision_id IS NOT NULL OR p_usage_entry_id IS NOT NULL
          OR p_current_amount <> 0 OR p_limit_amount <> 0 OR p_unlimited THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing reconciliation usage evidence is unexpected';
    END IF;

    IF NOT p_changed THEN
        IF p_before_revision <> 0 OR NOT EXISTS (
            SELECT 1 FROM platform.billing_metered_resources AS projection_row
            WHERE projection_row.authority_id=p_authority_id
              AND projection_row.tenant_id=p_tenant_id
              AND projection_row.resource_kind=p_resource_kind
              AND projection_row.owner_fact_id=p_owner_fact_id
              AND projection_row.counted_state=v_want_state
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing reconciliation projection is unavailable';
        END IF;
    ELSIF p_before_revision = 0 THEN
        IF p_gauge_delta <> 0
           OR (p_evidence_active AND NOT p_included_in_opening) THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'billing reconciliation adoption evidence is invalid';
        END IF;
        INSERT INTO platform.billing_metered_resources (
            authority_id,tenant_id,resource_kind,owner_fact_id,counted_state,
            origin_kind,opening_evidence_sha256,opening_measured_at,
            last_operation_id,revision,created_at,updated_at
        ) VALUES (
            p_authority_id,p_tenant_id,p_resource_kind,p_owner_fact_id,
            v_want_state,'adopted',p_evidence_sha256,p_measured_at,
            p_operation_id,1,p_recorded_at,p_recorded_at
        );
    ELSE
        IF (p_evidence_active AND p_gauge_delta <> 1)
           OR (NOT p_evidence_active AND p_gauge_delta <> -1) THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'billing reconciliation gauge direction is invalid';
        END IF;
        UPDATE platform.billing_metered_resources AS projection_row
        SET counted_state=v_want_state,last_operation_id=p_operation_id,
            revision=projection_row.revision+1,updated_at=p_recorded_at
        WHERE projection_row.authority_id=p_authority_id
          AND projection_row.tenant_id=p_tenant_id
          AND projection_row.resource_kind=p_resource_kind
          AND projection_row.owner_fact_id=p_owner_fact_id
          AND projection_row.counted_state<>v_want_state
          AND projection_row.revision=p_before_revision;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing reconciliation projection revision conflicts';
        END IF;
    END IF;

    INSERT INTO platform.billing_metered_resource_reconcile_receipts (
        operation_id,authority_id,tenant_id,actor_id,resource_kind,owner_fact_id,
        idempotency_key,request_sha256,evidence_sha256,evidence_exists,
        evidence_active,included_in_opening,changed,gauge_delta,current_amount,
        limit_amount,unlimited,usage_decision_id,usage_entry_id,measured_at,
        recorded_at
    ) VALUES (
        p_operation_id,p_authority_id,p_tenant_id,p_actor_id,p_resource_kind,
        p_owner_fact_id,p_idempotency_key,p_request_sha256,p_evidence_sha256,
        p_evidence_exists,p_evidence_active,p_included_in_opening,p_changed,
        p_gauge_delta,p_current_amount,p_limit_amount,p_unlimited,
        p_usage_decision_id,p_usage_entry_id,p_measured_at,p_recorded_at
    );
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.billing_metered_resource_reconcile_record_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_operation_id uuid, p_owner_fact_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_evidence_sha256 bytea, p_evidence_exists boolean, p_evidence_active boolean, p_included_in_opening boolean, p_changed boolean, p_gauge_delta bigint, p_current_amount bigint, p_limit_amount bigint, p_unlimited boolean, p_usage_decision_id uuid, p_usage_entry_id uuid, p_before_revision bigint, p_recorded_at timestamp with time zone, p_measured_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_metered_resource_record_v1(uuid, uuid, uuid, text, text, uuid, uuid, text, bytea, boolean, boolean, bigint, bigint, bigint, boolean, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_metered_resource_record_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_mutation_kind text, p_operation_id uuid, p_owner_fact_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_feature_enabled boolean, p_allowed boolean, p_gauge_delta bigint, p_current_amount bigint, p_limit_amount bigint, p_unlimited boolean, p_usage_decision_id uuid, p_usage_entry_id uuid, p_before_revision bigint, p_recorded_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_gauge_key text;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    v_gauge_key := CASE p_resource_kind
        WHEN 'api_endpoint' THEN 'api.active_endpoints'
        WHEN 'analytics_dashboard' THEN 'analytics.active_dashboards'
    END;
    IF v_gauge_key IS NULL OR p_mutation_kind NOT IN (
           'create','update','publish','revalidate','delete','restore'
       )
       OR pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_owner_fact_id) IS DISTINCT FROM 7
       OR p_actor_id IS NULL
       OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
       OR pg_catalog.octet_length(p_request_sha256) <> 32
       OR p_current_amount < 0 OR p_limit_amount < 0
       OR (p_unlimited AND p_limit_amount <> 0)
       OR p_before_revision < 0 OR NOT pg_catalog.isfinite(p_recorded_at)
       OR NOT EXISTS (
           SELECT 1 FROM platform.billing_tenant_authorities AS authority_row
           WHERE authority_row.authority_id = p_authority_id
             AND authority_row.tenant_id = p_tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing metered resource record input is invalid';
    END IF;

    IF p_gauge_delta <> 0 OR (
        p_mutation_kind IN ('create','restore')
        AND p_feature_enabled AND NOT p_allowed
    ) THEN
        IF p_usage_decision_id IS NULL OR NOT EXISTS (
            SELECT 1
            FROM platform.billing_entitlement_decisions AS decision_row
            WHERE decision_row.id = p_usage_decision_id
              AND decision_row.authority_id = p_authority_id
              AND decision_row.tenant_id = p_tenant_id
              AND decision_row.actor_id = p_actor_id
              AND decision_row.entitlement_key = v_gauge_key
              AND decision_row.source_operation_id = p_operation_id
              AND decision_row.requested_amount = CASE
                  WHEN p_gauge_delta <> 0 THEN p_gauge_delta ELSE 1
              END
              AND decision_row.current_amount = p_current_amount
              AND decision_row.unlimited = p_unlimited
              AND (
                  (p_unlimited AND decision_row.limit_amount IS NULL)
                  OR (NOT p_unlimited
                      AND decision_row.limit_amount = p_limit_amount)
              )
              AND decision_row.allowed = p_allowed
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing usage decision evidence is unavailable';
        END IF;
    ELSIF p_usage_decision_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing usage decision evidence is unexpected';
    END IF;

    IF p_gauge_delta <> 0 THEN
        IF p_usage_entry_id IS NULL OR NOT EXISTS (
            SELECT 1
            FROM platform.billing_usage_entries AS entry_row
            WHERE entry_row.id = p_usage_entry_id
              AND entry_row.authority_id = p_authority_id
              AND entry_row.tenant_id = p_tenant_id
              AND entry_row.decision_id = p_usage_decision_id
              AND entry_row.entitlement_key = v_gauge_key
              AND entry_row.owner_fact_id = p_operation_id
              AND entry_row.entry_kind = 'gauge_delta'
              AND entry_row.amount_delta = p_gauge_delta
              AND entry_row.gauge_after = p_current_amount + p_gauge_delta
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing usage entry evidence is unavailable';
        END IF;
    ELSIF p_usage_entry_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing usage entry evidence is unexpected';
    END IF;

    IF p_mutation_kind = 'create' AND p_allowed THEN
        IF p_before_revision <> 0 OR p_gauge_delta <> 1 THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'billing metered resource create transition is invalid';
        END IF;
        INSERT INTO platform.billing_metered_resources (
            authority_id,tenant_id,resource_kind,owner_fact_id,counted_state,
            origin_kind,opening_evidence_sha256,opening_measured_at,
            last_operation_id,revision,created_at,updated_at
        ) VALUES (
            p_authority_id,p_tenant_id,p_resource_kind,p_owner_fact_id,'active',
            'runtime',NULL,NULL,p_operation_id,1,p_recorded_at,p_recorded_at
        );
    ELSIF p_mutation_kind = 'restore' AND p_allowed THEN
        UPDATE platform.billing_metered_resources AS projection_row
        SET counted_state='active',last_operation_id=p_operation_id,
            revision=projection_row.revision+1,updated_at=p_recorded_at
        WHERE projection_row.authority_id=p_authority_id
          AND projection_row.tenant_id=p_tenant_id
          AND projection_row.resource_kind=p_resource_kind
          AND projection_row.owner_fact_id=p_owner_fact_id
          AND projection_row.counted_state='released'
          AND projection_row.revision=p_before_revision;
        IF NOT FOUND OR p_gauge_delta <> 1 THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing metered resource restore revision conflicts';
        END IF;
    ELSIF p_mutation_kind = 'delete' AND p_gauge_delta = -1 THEN
        UPDATE platform.billing_metered_resources AS projection_row
        SET counted_state='released',last_operation_id=p_operation_id,
            revision=projection_row.revision+1,updated_at=p_recorded_at
        WHERE projection_row.authority_id=p_authority_id
          AND projection_row.tenant_id=p_tenant_id
          AND projection_row.resource_kind=p_resource_kind
          AND projection_row.owner_fact_id=p_owner_fact_id
          AND projection_row.counted_state='active'
          AND projection_row.revision=p_before_revision;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing metered resource delete revision conflicts';
        END IF;
    ELSIF p_mutation_kind = 'delete' THEN
        IF p_gauge_delta <> 0 OR NOT EXISTS (
            SELECT 1 FROM platform.billing_metered_resources AS projection_row
            WHERE projection_row.authority_id=p_authority_id
              AND projection_row.tenant_id=p_tenant_id
              AND projection_row.resource_kind=p_resource_kind
              AND projection_row.owner_fact_id=p_owner_fact_id
              AND projection_row.counted_state='released'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing metered resource release state is unavailable';
        END IF;
    END IF;

    INSERT INTO platform.billing_metered_resource_receipts (
        operation_id,authority_id,tenant_id,actor_id,resource_kind,mutation_kind,
        owner_fact_id,idempotency_key,request_sha256,feature_enabled,allowed,
        gauge_delta,current_amount,limit_amount,unlimited,usage_decision_id,
        usage_entry_id,recorded_at
    ) VALUES (
        p_operation_id,p_authority_id,p_tenant_id,p_actor_id,p_resource_kind,
        p_mutation_kind,p_owner_fact_id,p_idempotency_key,p_request_sha256,
        p_feature_enabled,p_allowed,p_gauge_delta,p_current_amount,p_limit_amount,
        p_unlimited,p_usage_decision_id,p_usage_entry_id,p_recorded_at
    );
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.billing_metered_resource_record_v1(p_authority_id uuid, p_tenant_id uuid, p_actor_id uuid, p_resource_kind text, p_mutation_kind text, p_operation_id uuid, p_owner_fact_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_feature_enabled boolean, p_allowed boolean, p_gauge_delta bigint, p_current_amount bigint, p_limit_amount bigint, p_unlimited boolean, p_usage_decision_id uuid, p_usage_entry_id uuid, p_before_revision bigint, p_recorded_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_place_legal_hold_v1(uuid, uuid, uuid, uuid, uuid, text, bytea, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_place_legal_hold_v1(p_authority_id uuid, p_tenant_id uuid, p_hold_id uuid, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_reason text, p_ticket_reference text, p_occurred_at timestamp with time zone) RETURNS TABLE(hold_id uuid, tenant_id uuid, state text, placed_by uuid, place_operation_id uuid, reason text, ticket_reference text, placed_at timestamp with time zone, released_by uuid, release_operation_id uuid, release_reason text, released_at timestamp with time zone, revision bigint, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored platform.billing_legal_holds%ROWTYPE;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = p_authority_id
          AND authority_row.tenant_id = p_tenant_id
    ) OR pg_catalog.uuid_extract_version(p_hold_id) <> 7
       OR pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128
       OR pg_catalog.octet_length(p_request_sha256) <> 32
       OR pg_catalog.octet_length(p_reason) NOT BETWEEN 1 AND 2048
       OR pg_catalog.octet_length(p_ticket_reference) NOT BETWEEN 1 AND 256
       OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing legal hold place input is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'billing:legal-hold:' || p_tenant_id::text, 0
    ));
    SELECT * INTO stored
    FROM platform.billing_legal_holds AS legal_hold
    WHERE legal_hold.tenant_id = p_tenant_id
      AND legal_hold.place_idempotency_key = p_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF stored.place_request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5730',
                MESSAGE = 'billing legal hold place key was reused';
        END IF;
        RETURN QUERY SELECT stored.id, stored.tenant_id, stored.state,
            stored.placed_by, stored.place_operation_id, stored.reason,
            stored.ticket_reference, stored.placed_at, stored.released_by,
            stored.release_operation_id, stored.release_reason,
            stored.released_at, stored.revision, true;
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.billing_legal_holds AS legal_hold
        WHERE legal_hold.tenant_id = p_tenant_id AND legal_hold.state = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5730',
            MESSAGE = 'billing tenant already has an active legal hold';
    END IF;
    INSERT INTO platform.billing_legal_holds (
        id, authority_id, tenant_id, state, placed_by, place_operation_id,
        place_idempotency_key, place_request_sha256, reason, ticket_reference,
        placed_at, released_by, release_operation_id, release_idempotency_key,
        release_request_sha256, release_reason, released_at, revision
    ) VALUES (
        p_hold_id, p_authority_id, p_tenant_id, 'active', p_actor_id,
        p_operation_id, p_idempotency_key, p_request_sha256, p_reason,
        p_ticket_reference, p_occurred_at, NULL, NULL, NULL, NULL, NULL, NULL, 1
    );
    RETURN QUERY SELECT p_hold_id, p_tenant_id, 'active'::text, p_actor_id,
        p_operation_id, p_reason, p_ticket_reference, p_occurred_at,
        NULL::uuid, NULL::uuid, NULL::text, NULL::timestamptz, 1::bigint, false;
END;
$$;


ALTER FUNCTION platform.billing_place_legal_hold_v1(p_authority_id uuid, p_tenant_id uuid, p_hold_id uuid, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_reason text, p_ticket_reference text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_platform_license_refresh_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_platform_license_refresh_read_v1(p_environment_id uuid, p_operation_id uuid) RETURNS TABLE(operation_id uuid, operation_state text, snapshot_sequence bigint, snapshot_sha256 text, failure_code text, created_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_request platform.billing_platform_license_refresh_requests%ROWTYPE;
    v_operation platform.billing_license_refresh_operations%ROWTYPE;
    v_attempt_state text;
    v_attempt_failure text;
    v_attempt_finished timestamptz;
    v_receipt_sequence bigint;
    v_receipt_sha256 text;
    v_receipt_outcome text;
    v_state text;
    v_failure text;
    v_completed timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing platform license refresh read denied';
    END IF;
    IF p_environment_id IS NULL
       OR pg_catalog.uuid_extract_version(p_environment_id) <> 7
       OR p_operation_id IS NULL
       OR pg_catalog.uuid_extract_version(p_operation_id) <> 7 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing platform license refresh read is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.tenancy_deployment_policy AS policy
        WHERE policy.singleton
          AND policy.environment_id = p_environment_id
          AND policy.deployment_mode = 'onpremise'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing platform license refresh read requires onpremise';
    END IF;
    SELECT request.* INTO v_request
    FROM platform.billing_platform_license_refresh_requests AS request
    WHERE request.operation_id = p_operation_id
      AND request.environment_id = p_environment_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'billing platform license refresh operation was not found';
    END IF;
    SELECT refresh.* INTO v_operation
    FROM platform.billing_license_refresh_operations AS refresh
    WHERE refresh.operation_id = p_operation_id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT p_operation_id, 'pending'::text,
            NULL::bigint, NULL::text, NULL::text,
            v_request.created_at, NULL::timestamptz;
        RETURN;
    END IF;
    SELECT attempt.state, attempt.failure_kind, attempt.finished_at
    INTO v_attempt_state, v_attempt_failure, v_attempt_finished
    FROM platform.billing_license_refresh_attempts AS attempt
    WHERE attempt.operation_id = p_operation_id
    ORDER BY attempt.attempt DESC
    LIMIT 1;
    SELECT receipt.sequence, receipt.payload_sha256, receipt.outcome
    INTO v_receipt_sequence, v_receipt_sha256, v_receipt_outcome
    FROM platform.billing_license_verification_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id
    ORDER BY receipt.attempt DESC
    LIMIT 1;
    IF v_operation.state = 'succeeded' THEN
        v_state := 'accepted';
        v_completed := v_operation.completed_at;
    ELSIF v_operation.state = 'fenced' THEN
        v_state := 'fenced';
        v_failure := COALESCE(v_attempt_failure, v_receipt_outcome);
        v_completed := v_operation.completed_at;
    ELSIF v_operation.state = 'running'
          AND v_operation.lease_until > v_now THEN
        v_state := 'leased';
    ELSIF v_operation.state = 'running' THEN
        v_state := 'failed';
        v_failure := 'outcome_unknown';
        v_completed := v_operation.lease_until;
    ELSIF v_operation.state = 'pending'
          AND v_attempt_failure IS NOT NULL THEN
        v_state := 'failed';
        v_failure := CASE
            WHEN v_attempt_failure = 'lease_expired' THEN 'outcome_unknown'
            ELSE v_attempt_failure
        END;
        v_completed := v_attempt_finished;
    ELSE
        v_state := 'pending';
    END IF;
    RETURN QUERY SELECT p_operation_id, v_state,
        v_receipt_sequence, v_receipt_sha256, v_failure,
        v_request.created_at, v_completed;
END;
$$;


ALTER FUNCTION platform.billing_platform_license_refresh_read_v1(p_environment_id uuid, p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_platform_license_refresh_request_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_platform_license_refresh_request_v1(p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 text) RETURNS TABLE(operation_id uuid, replayed boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_existing platform.billing_platform_license_refresh_requests%ROWTYPE;
    v_head platform.billing_license_heads%ROWTYPE;
    v_snapshot platform.billing_license_snapshots%ROWTYPE;
    v_target platform.billing_license_refresh_targets%ROWTYPE;
    v_operation_id uuid;
    v_operation_state text;
    v_count integer;
    v_target_created boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing platform license refresh denied';
    END IF;
    IF p_environment_id IS NULL
       OR pg_catalog.uuid_extract_version(p_environment_id) <> 7
       OR p_tenant_id IS NULL
       OR p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_actor_id IS NULL
       OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$'
       OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing platform license refresh request is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.tenancy_deployment_policy AS policy
        JOIN platform.tenancy_tenant_bindings AS binding
          ON binding.environment_id = policy.environment_id
         AND binding.tenant_id = p_tenant_id
         AND binding.purpose = 'onpremise_primary'
        WHERE policy.singleton
          AND policy.environment_id = p_environment_id
          AND policy.deployment_mode = 'onpremise'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing platform license refresh requires onpremise primary';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_environment_id::text, 0)
    );
    SELECT request.* INTO v_existing
    FROM platform.billing_platform_license_refresh_requests AS request
    WHERE request.environment_id = p_environment_id
      AND request.actor_id = p_actor_id
      AND request.idempotency_key = p_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF v_existing.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'billing platform license idempotency key was reused';
        END IF;
        RETURN QUERY SELECT v_existing.operation_id, true, v_existing.created_at;
        RETURN;
    END IF;
    SELECT pg_catalog.count(*) INTO v_count
    FROM platform.billing_license_heads AS head
    JOIN platform.billing_license_snapshots AS snapshot
      ON snapshot.snapshot_id = head.snapshot_id
    WHERE head.environment_id = p_environment_id;
    IF v_count = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'billing platform license was not found';
    ELSIF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing platform license authority is ambiguous';
    END IF;
    SELECT head.* INTO v_head
    FROM platform.billing_license_heads AS head
    WHERE head.environment_id = p_environment_id
    FOR SHARE;
    SELECT snapshot.* INTO v_snapshot
    FROM platform.billing_license_snapshots AS snapshot
    WHERE snapshot.snapshot_id = v_head.snapshot_id
    FOR SHARE;
    v_operation_id := pg_catalog.uuidv7();
    INSERT INTO platform.billing_license_refresh_targets (
        license_id, environment_id, licensee_organization_id, delivery_kind,
        observed_sequence, observed_sha256, operation_id,
        next_attempt_at, lease_until, revision, updated_at
    ) VALUES (
        v_head.license_id, v_head.environment_id,
        v_snapshot.licensee_organization_id, v_snapshot.delivery_kind,
        v_head.sequence, v_head.payload_sha256, v_operation_id,
        v_now, NULL, 1, v_now
    ) ON CONFLICT ON CONSTRAINT billing_license_refresh_targets_pkey
      DO NOTHING;
    v_target_created := FOUND;
    SELECT target.* INTO v_target
    FROM platform.billing_license_refresh_targets AS target
    WHERE target.license_id = v_head.license_id
      AND target.environment_id = v_head.environment_id
    FOR UPDATE;
    SELECT refresh.state INTO v_operation_state
    FROM platform.billing_license_refresh_operations AS refresh
    WHERE refresh.operation_id = v_target.operation_id;
    IF NOT v_target_created AND (
        v_target.lease_until > v_now
        OR v_operation_state IN ('pending', 'running')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55P03',
            MESSAGE = 'billing platform license refresh is in progress';
    END IF;
    IF NOT v_target_created AND v_operation_state = 'fenced' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing platform license refresh target is fenced';
    END IF;
    IF NOT v_target_created THEN
        UPDATE platform.billing_license_refresh_targets AS target
        SET licensee_organization_id = v_snapshot.licensee_organization_id,
            delivery_kind = v_snapshot.delivery_kind,
            observed_sequence = v_head.sequence,
            observed_sha256 = v_head.payload_sha256,
            operation_id = v_operation_id,
            next_attempt_at = v_now,
            lease_until = NULL,
            revision = target.revision + 1,
            updated_at = v_now
        WHERE target.license_id = v_head.license_id
          AND target.environment_id = v_head.environment_id;
    END IF;
    INSERT INTO platform.billing_platform_license_refresh_requests (
        operation_id, license_id, environment_id, tenant_id, actor_id,
        idempotency_key, request_sha256, created_at
    ) VALUES (
        v_operation_id, v_head.license_id, p_environment_id, p_tenant_id,
        p_actor_id, p_idempotency_key, p_request_sha256, v_now
    );
    RETURN QUERY SELECT v_operation_id, false, v_now;
END;
$_$;


ALTER FUNCTION platform.billing_platform_license_refresh_request_v1(p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_publish_license_derived_offering_v1(uuid, uuid, uuid, uuid, text, text, text, bigint, text, uuid, bigint, text, timestamp with time zone, text, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_publish_license_derived_offering_v1(p_operation_id uuid, p_environment_id uuid, p_license_id uuid, p_licensee_organization_id uuid, p_deployment_mode text, p_delivery_kind text, p_issuer text, p_sequence bigint, p_snapshot_sha256 text, p_offering_version_id uuid, p_revision bigint, p_offering_sha256 text, p_effective_at timestamp with time zone, p_manifest_sha256 text, p_offering_document bytea) RETURNS TABLE(operation_id uuid, offering_version_id uuid, revision bigint, offering_sha256 text, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_publication platform.billing_license_offering_publications%ROWTYPE;
    v_snapshot platform.billing_license_snapshots%ROWTYPE;
    v_authority_id uuid;
    v_offering_id uuid;
    v_document jsonb;
    v_manifest text;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    v_offering_id := pg_catalog.gen_random_uuid();
    v_manifest :=
        '3a0e120dd180d30f0e9c4ccb20c5338554c5f9e6db8349bff5335d813a421e99';
    IF pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR pg_catalog.uuid_extract_version(p_environment_id) <> 7
       OR pg_catalog.uuid_extract_version(p_offering_version_id) <> 7
       OR p_license_id IS NULL OR p_licensee_organization_id IS NULL
       OR p_deployment_mode <> 'onpremise'
       OR p_delivery_kind NOT IN ('connected', 'airgap', 'development')
       OR pg_catalog.octet_length(p_issuer) NOT BETWEEN 1 AND 256
       OR p_sequence < 1 OR p_revision < 1
       OR p_snapshot_sha256 !~ '^[0-9a-f]{64}$'
       OR p_offering_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 <> v_manifest
       OR p_offering_sha256 IS DISTINCT FROM pg_catalog.encode(
            pg_catalog.sha256(p_offering_document), 'hex')
       OR NOT pg_catalog.isfinite(p_effective_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing license offering publication is invalid';
    END IF;
    v_document := pg_catalog.convert_from(
        p_offering_document, 'UTF8'
    )::jsonb;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'billing-license-offering|' || p_operation_id::text, 0
    ));
    SELECT publication.* INTO v_publication
    FROM platform.billing_license_offering_publications AS publication
    WHERE publication.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_publication.environment_id IS DISTINCT FROM p_environment_id
           OR v_publication.license_id IS DISTINCT FROM p_license_id
           OR v_publication.licensee_organization_id IS DISTINCT FROM
                p_licensee_organization_id
           OR v_publication.delivery_kind IS DISTINCT FROM p_delivery_kind
           OR v_publication.issuer IS DISTINCT FROM p_issuer
           OR v_publication.snapshot_sequence IS DISTINCT FROM p_sequence
           OR v_publication.snapshot_sha256 IS DISTINCT FROM p_snapshot_sha256
           OR v_publication.offering_version_id IS DISTINCT FROM
                p_offering_version_id
           OR v_publication.revision IS DISTINCT FROM p_revision
           OR v_publication.offering_sha256 IS DISTINCT FROM p_offering_sha256
           OR v_publication.offering_document IS DISTINCT FROM p_offering_document
           OR v_publication.effective_at IS DISTINCT FROM p_effective_at
           OR v_publication.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'billing license offering operation was reused';
        END IF;
        RETURN QUERY SELECT p_operation_id, p_offering_version_id,
            p_revision, p_offering_sha256, true;
        RETURN;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_license_id::text || '|' || p_environment_id::text, 0
    ));
    SELECT snapshot.* INTO v_snapshot
    FROM platform.billing_license_heads AS head
    JOIN platform.billing_license_snapshots AS snapshot
      ON snapshot.snapshot_id = head.snapshot_id
    WHERE head.license_id = p_license_id
      AND head.environment_id = p_environment_id
      AND head.sequence = p_sequence
      AND head.payload_sha256 = p_snapshot_sha256
      AND snapshot.licensee_organization_id = p_licensee_organization_id
      AND snapshot.delivery_kind = p_delivery_kind
      AND snapshot.issuer = p_issuer
    FOR SHARE OF head, snapshot;
    IF NOT FOUND OR NOT platform.billing_license_offering_document_valid_v1(
        v_snapshot.snapshot_id, p_offering_version_id,
        p_revision, p_effective_at, v_document
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'verified license offering snapshot is unavailable';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.billing_license_offering_publications AS publication
        WHERE publication.license_id = p_license_id
          AND publication.environment_id = p_environment_id
          AND publication.snapshot_sequence = p_sequence
          AND publication.snapshot_sha256 = p_snapshot_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'license snapshot already published another offering';
    END IF;
    SELECT authority.authority_id INTO STRICT v_authority_id
    FROM platform.billing_global_authorities AS authority
    WHERE authority.scope_id = p_environment_id
      AND authority.scope_kind = 'global'
      AND authority.authority_group_id = 'billing'
      AND authority.authority_domain = 'billing';
    PERFORM platform.billing_license_offering_insert_v1(
        v_authority_id, p_operation_id, v_offering_id,
        p_offering_version_id, p_revision, p_effective_at,
        v_snapshot.snapshot_id
    );
    INSERT INTO platform.billing_license_offering_publications (
        operation_id, authority_id, license_id, licensee_organization_id,
        environment_id, delivery_kind, issuer, snapshot_id,
        snapshot_sequence, snapshot_sha256, offering_id,
        offering_version_id, revision, offering_sha256,
        offering_document, effective_at, manifest_sha256, created_at
    ) VALUES (
        p_operation_id, v_authority_id, p_license_id,
        p_licensee_organization_id, p_environment_id, p_delivery_kind,
        p_issuer, v_snapshot.snapshot_id, p_sequence, p_snapshot_sha256,
        v_offering_id, p_offering_version_id, p_revision,
        p_offering_sha256, p_offering_document, p_effective_at,
        p_manifest_sha256, v_now
    );
    RETURN QUERY SELECT p_operation_id, p_offering_version_id,
        p_revision, p_offering_sha256, false;
END;
$_$;


ALTER FUNCTION platform.billing_publish_license_derived_offering_v1(p_operation_id uuid, p_environment_id uuid, p_license_id uuid, p_licensee_organization_id uuid, p_deployment_mode text, p_delivery_kind text, p_issuer text, p_sequence bigint, p_snapshot_sha256 text, p_offering_version_id uuid, p_revision bigint, p_offering_sha256 text, p_effective_at timestamp with time zone, p_manifest_sha256 text, p_offering_document bytea) OWNER TO harpy_owner;

--
-- Name: billing_purge_entitlement_retention_v1(uuid, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_purge_entitlement_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) RETURNS TABLE(records_purged bigint, has_remaining boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    decision_count bigint;
    total_count bigint;
    period_count bigint;
BEGIN
    decision_count := 0;
    total_count := 0;
    period_count := 0;
    IF NOT platform.billing_retention_delete_allowed_v1(
        p_authority_id, p_tenant_id
    ) OR p_limit NOT BETWEEN 1 AND 1000 OR NOT pg_catalog.isfinite(p_now) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing entitlement retention context is invalid';
    END IF;
    WITH candidates AS (
        SELECT decision.id
        FROM platform.billing_entitlement_decisions AS decision
        WHERE decision.tenant_id = p_tenant_id
          AND decision.retain_until <= p_now
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_reservations AS reservation
              WHERE reservation.tenant_id = p_tenant_id
                AND reservation.decision_id = decision.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_entries AS entry
              WHERE entry.tenant_id = p_tenant_id
                AND entry.decision_id = decision.id
          )
        ORDER BY decision.retain_until, decision.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ), removed AS (
        DELETE FROM platform.billing_entitlement_decisions AS decision
        USING candidates
        WHERE decision.tenant_id = p_tenant_id AND decision.id = candidates.id
        RETURNING 1
    ) SELECT pg_catalog.count(*) INTO decision_count FROM removed;

    WITH candidates AS (
        SELECT total.meter_period_id
        FROM platform.billing_usage_totals AS total
        JOIN platform.billing_meter_periods AS period
          ON period.tenant_id = total.tenant_id
         AND period.id = total.meter_period_id
        WHERE total.tenant_id = p_tenant_id AND period.state = 'closed'
          AND period.closed_at <= p_now - INTERVAL '7 years'
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_reservations AS reservation
              WHERE reservation.tenant_id = p_tenant_id
                AND reservation.meter_period_id = total.meter_period_id
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_entries AS entry
              WHERE entry.tenant_id = p_tenant_id
                AND entry.meter_period_id = total.meter_period_id
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_entitlement_decisions AS decision
              WHERE decision.tenant_id = p_tenant_id
                AND decision.meter_period_id = total.meter_period_id
          )
        ORDER BY period.closed_at, total.meter_period_id
        FOR UPDATE OF total SKIP LOCKED LIMIT p_limit
    ), removed AS (
        DELETE FROM platform.billing_usage_totals AS total
        USING candidates
        WHERE total.tenant_id = p_tenant_id
          AND total.meter_period_id = candidates.meter_period_id
        RETURNING 1
    ) SELECT pg_catalog.count(*) INTO total_count FROM removed;

    WITH candidates AS (
        SELECT period.id
        FROM platform.billing_meter_periods AS period
        WHERE period.tenant_id = p_tenant_id AND period.state = 'closed'
          AND period.closed_at <= p_now - INTERVAL '7 years'
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_totals AS total
              WHERE total.tenant_id = p_tenant_id
                AND total.meter_period_id = period.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_reservations AS reservation
              WHERE reservation.tenant_id = p_tenant_id
                AND reservation.meter_period_id = period.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_entries AS entry
              WHERE entry.tenant_id = p_tenant_id
                AND entry.meter_period_id = period.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_entitlement_decisions AS decision
              WHERE decision.tenant_id = p_tenant_id
                AND decision.meter_period_id = period.id
          )
        ORDER BY period.closed_at, period.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ), removed AS (
        DELETE FROM platform.billing_meter_periods AS period
        USING candidates
        WHERE period.tenant_id = p_tenant_id AND period.id = candidates.id
        RETURNING 1
    ) SELECT pg_catalog.count(*) INTO period_count FROM removed;

    RETURN QUERY SELECT decision_count + total_count + period_count,
        decision_count = p_limit OR total_count = p_limit
        OR period_count = p_limit;
END;
$$;


ALTER FUNCTION platform.billing_purge_entitlement_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: billing_purge_invoice_retention_v1(uuid, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_purge_invoice_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) RETURNS TABLE(records_purged bigint, has_remaining boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    candidate_ids text;
    removed_count bigint;
    statement_count bigint;
    cutoff timestamptz;
BEGIN
    removed_count := 0;
    statement_count := 0;
    cutoff := p_now - INTERVAL '10 years';
    IF NOT platform.billing_retention_delete_allowed_v1(
        p_authority_id, p_tenant_id
    ) OR p_limit NOT BETWEEN 1 AND 1000 OR NOT pg_catalog.isfinite(p_now) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing invoice retention context is invalid';
    END IF;
    SELECT pg_catalog.string_agg(candidate.id::text, ',') INTO candidate_ids
    FROM (
        SELECT invoice.id
        FROM platform.billing_invoices AS invoice
        WHERE invoice.tenant_id = p_tenant_id AND invoice.state = 'finalized'
          AND invoice.finalized_at <= cutoff
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_settlements AS settlement
              WHERE settlement.tenant_id = p_tenant_id
                AND settlement.invoice_id = invoice.id
                AND settlement.occurred_at > cutoff
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_adjustments AS adjustment
              WHERE adjustment.tenant_id = p_tenant_id
                AND adjustment.invoice_id = invoice.id
                AND adjustment.created_at > cutoff
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.billing_provider_objects AS object_row
              JOIN platform.billing_webhook_receipts AS receipt
                ON receipt.tenant_id = object_row.tenant_id
               AND receipt.provider_object_mapping_id = object_row.id
              WHERE object_row.tenant_id = p_tenant_id
                AND object_row.invoice_id = invoice.id
                AND (receipt.retain_until > p_now OR receipt.processor_state IN (
                    'received', 'processing'
                ))
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.billing_provider_objects AS object_row
              JOIN platform.billing_provider_events AS event_row
                ON event_row.tenant_id = object_row.tenant_id
               AND event_row.provider_object_mapping_id = object_row.id
              WHERE object_row.tenant_id = p_tenant_id
                AND object_row.invoice_id = invoice.id
                AND event_row.occurred_at > cutoff
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.billing_provider_objects AS object_row
              JOIN platform.billing_provider_events AS event_row
                ON event_row.tenant_id = object_row.tenant_id
               AND event_row.provider_object_mapping_id = object_row.id
              JOIN platform.billing_subscription_boundary_evidence AS evidence
                ON evidence.tenant_id = event_row.tenant_id
               AND evidence.provider_event_id = event_row.id
              WHERE object_row.tenant_id = p_tenant_id
                AND object_row.invoice_id = invoice.id
                AND evidence.recorded_at > cutoff
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.billing_provider_objects AS object_row
              JOIN platform.billing_provider_commands AS command_row
                ON command_row.tenant_id = object_row.tenant_id
               AND command_row.provider_object_mapping_id = object_row.id
              WHERE object_row.tenant_id = p_tenant_id
                AND object_row.invoice_id = invoice.id
                AND (command_row.completed_at IS NULL
                    OR command_row.completed_at > cutoff)
          )
        ORDER BY invoice.finalized_at, invoice.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ) AS candidate;
    IF candidate_ids IS NULL THEN
        RETURN QUERY SELECT 0::bigint, false;
        RETURN;
    END IF;

    DELETE FROM platform.billing_subscription_boundary_evidence AS evidence
    USING platform.billing_provider_events AS event_row,
          platform.billing_provider_objects AS object_row
    WHERE evidence.tenant_id = p_tenant_id
      AND evidence.provider_event_id = event_row.id
      AND event_row.tenant_id = p_tenant_id
      AND event_row.provider_object_mapping_id = object_row.id
      AND object_row.tenant_id = p_tenant_id
      AND object_row.invoice_id = ANY(
          pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
      );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_provider_events AS event_row
    USING platform.billing_provider_objects AS object_row
    WHERE event_row.tenant_id = p_tenant_id
      AND event_row.provider_object_mapping_id = object_row.id
      AND object_row.tenant_id = p_tenant_id
      AND object_row.invoice_id = ANY(
          pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
      );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_webhook_receipts AS receipt
    USING platform.billing_provider_objects AS object_row
    WHERE receipt.tenant_id = p_tenant_id
      AND receipt.provider_object_mapping_id = object_row.id
      AND object_row.tenant_id = p_tenant_id
      AND object_row.invoice_id = ANY(
          pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
      );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_provider_commands AS command_row
    USING platform.billing_provider_objects AS object_row
    WHERE command_row.tenant_id = p_tenant_id
      AND command_row.provider_object_mapping_id = object_row.id
      AND object_row.tenant_id = p_tenant_id
      AND object_row.invoice_id = ANY(
          pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
      )
      AND command_row.state IN ('succeeded', 'failed', 'reconcile_required')
      AND command_row.completed_at <= cutoff;
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_provider_objects AS object_row
    WHERE object_row.tenant_id = p_tenant_id
      AND object_row.invoice_id = ANY(
          pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
      );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_adjustments
    WHERE tenant_id = p_tenant_id AND invoice_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_invoice_finalizations
    WHERE tenant_id = p_tenant_id AND invoice_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_settlements
    WHERE tenant_id = p_tenant_id AND invoice_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_invoice_lines
    WHERE tenant_id = p_tenant_id AND invoice_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_invoices
    WHERE tenant_id = p_tenant_id AND id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    RETURN QUERY SELECT removed_count,
        pg_catalog.cardinality(
            pg_catalog.string_to_array(candidate_ids, ',')
        ) = p_limit;
END;
$$;


ALTER FUNCTION platform.billing_purge_invoice_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: billing_purge_raw_retention_v1(uuid, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_purge_raw_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) RETURNS TABLE(raw_bodies_redacted bigint, raw_records_purged bigint, has_remaining boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    body_count bigint;
    entry_count bigint;
    reservation_count bigint;
    receipt_count bigint;
BEGIN
    body_count := 0;
    entry_count := 0;
    reservation_count := 0;
    receipt_count := 0;
    IF NOT platform.billing_retention_delete_allowed_v1(
        p_authority_id, p_tenant_id
    ) OR p_limit NOT BETWEEN 1 AND 1000 OR NOT pg_catalog.isfinite(p_now) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing raw retention context is invalid';
    END IF;
    WITH candidates AS (
        SELECT receipt.id
        FROM platform.billing_webhook_receipts AS receipt
        WHERE receipt.tenant_id = p_tenant_id
          AND receipt.raw_body_expires_at <= p_now
          AND receipt.encrypted_body IS NOT NULL
        ORDER BY receipt.raw_body_expires_at, receipt.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ), changed AS (
        UPDATE platform.billing_webhook_receipts AS receipt
           SET encrypted_body = NULL, wrapped_dek = NULL,
               algorithm = NULL, nonce = NULL, revision = receipt.revision + 1
          FROM candidates
         WHERE receipt.tenant_id = p_tenant_id AND receipt.id = candidates.id
         RETURNING 1
    ) SELECT pg_catalog.count(*) INTO body_count FROM changed;

    WITH candidates AS (
        SELECT entry.id
        FROM platform.billing_usage_entries AS entry
        WHERE entry.tenant_id = p_tenant_id
          AND entry.occurred_at <= p_now - INTERVAL '400 days'
        ORDER BY entry.occurred_at, entry.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ), removed AS (
        DELETE FROM platform.billing_usage_entries AS entry
        USING candidates
        WHERE entry.tenant_id = p_tenant_id AND entry.id = candidates.id
        RETURNING 1
    ) SELECT pg_catalog.count(*) INTO entry_count FROM removed;

    WITH candidates AS (
        SELECT reservation.id
        FROM platform.billing_usage_reservations AS reservation
        WHERE reservation.tenant_id = p_tenant_id
          AND reservation.state IN ('committed', 'released')
          AND reservation.resolved_at <= p_now - INTERVAL '400 days'
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_usage_entries AS entry
              WHERE entry.tenant_id = p_tenant_id
                AND entry.reservation_id = reservation.id
          )
        ORDER BY reservation.resolved_at, reservation.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ), removed AS (
        DELETE FROM platform.billing_usage_reservations AS reservation
        USING candidates
        WHERE reservation.tenant_id = p_tenant_id
          AND reservation.id = candidates.id
        RETURNING 1
    ) SELECT pg_catalog.count(*) INTO reservation_count FROM removed;

    WITH candidates AS (
        SELECT receipt.id
        FROM platform.billing_webhook_receipts AS receipt
        WHERE receipt.tenant_id = p_tenant_id
          AND receipt.retain_until <= p_now
          AND receipt.processor_state IN (
              'applied', 'reconcile_required', 'rejected'
          )
        ORDER BY receipt.retain_until, receipt.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ), removed AS (
        DELETE FROM platform.billing_webhook_receipts AS receipt
        USING candidates
        WHERE receipt.tenant_id = p_tenant_id AND receipt.id = candidates.id
        RETURNING 1
    ) SELECT pg_catalog.count(*) INTO receipt_count FROM removed;

    RETURN QUERY SELECT body_count,
        entry_count + reservation_count + receipt_count,
        body_count = p_limit OR entry_count = p_limit
        OR reservation_count = p_limit OR receipt_count = p_limit;
END;
$$;


ALTER FUNCTION platform.billing_purge_raw_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: billing_purge_subscription_retention_v1(uuid, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_purge_subscription_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) RETURNS TABLE(records_purged bigint, has_remaining boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    candidate_ids text;
    removed_count bigint;
    statement_count bigint;
    redemption_count bigint;
    candidate_count integer;
    cutoff timestamptz;
BEGIN
    removed_count := 0;
    statement_count := 0;
    redemption_count := 0;
    candidate_count := 0;
    cutoff := p_now - INTERVAL '10 years';
    IF NOT platform.billing_retention_delete_allowed_v1(
        p_authority_id, p_tenant_id
    ) OR p_limit NOT BETWEEN 1 AND 1000 OR NOT pg_catalog.isfinite(p_now) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing subscription retention context is invalid';
    END IF;
    WITH candidates AS (
        SELECT redemption.id
        FROM platform.billing_discount_redemptions AS redemption
        WHERE redemption.tenant_id = p_tenant_id
          AND redemption.relationship_ended_at <= cutoff
        ORDER BY redemption.relationship_ended_at, redemption.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ), removed AS (
        DELETE FROM platform.billing_discount_redemptions AS redemption
        USING candidates
        WHERE redemption.tenant_id = p_tenant_id
          AND redemption.id = candidates.id
        RETURNING 1
    ) SELECT pg_catalog.count(*) INTO redemption_count FROM removed;
    removed_count := redemption_count;

    SELECT pg_catalog.string_agg(candidate.id::text, ',') INTO candidate_ids
    FROM (
        SELECT subscription.id
        FROM platform.billing_subscriptions AS subscription
        WHERE subscription.tenant_id = p_tenant_id
          AND subscription.state IN ('cancelled', 'expired')
          AND subscription.updated_at <= cutoff
          AND platform.billing_subscription_retention_eligible_v1(
              p_tenant_id, subscription.id, cutoff, p_now
          )
        ORDER BY subscription.updated_at, subscription.id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    ) AS candidate;
    candidate_count := COALESCE(pg_catalog.cardinality(
        pg_catalog.string_to_array(candidate_ids, ',')
    ), 0);
    IF candidate_ids IS NULL THEN
        RETURN QUERY SELECT removed_count, redemption_count = p_limit;
        RETURN;
    END IF;

    DELETE FROM platform.billing_subscription_boundary_evidence
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_provider_events AS event_row
    USING platform.billing_provider_objects AS object_row
    WHERE event_row.tenant_id = p_tenant_id
      AND event_row.provider_object_mapping_id = object_row.id
      AND object_row.tenant_id = p_tenant_id
      AND object_row.subscription_id = ANY(
          pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
      );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_webhook_receipts AS receipt
    USING platform.billing_provider_objects AS object_row
    WHERE receipt.tenant_id = p_tenant_id
      AND receipt.provider_object_mapping_id = object_row.id
      AND object_row.tenant_id = p_tenant_id
      AND object_row.subscription_id = ANY(
          pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
      );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_provider_commands AS command_row
    WHERE command_row.tenant_id = p_tenant_id
      AND (command_row.subscription_id = ANY(
              pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
          )
        OR command_row.provider_object_mapping_id IN (
            SELECT object_row.id FROM platform.billing_provider_objects AS object_row
            WHERE object_row.tenant_id = p_tenant_id
              AND object_row.subscription_id = ANY(
                  pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
              )
        ));
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_provider_objects
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    DELETE FROM platform.billing_subscription_audit
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_subscription_boundary_jobs
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_subscription_changes
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_subscription_overrides
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_trial_claims
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_subscription_operations
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_discount_redemptions
    WHERE tenant_id = p_tenant_id AND subscription_id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;
    DELETE FROM platform.billing_subscriptions
    WHERE tenant_id = p_tenant_id AND id = ANY(
        pg_catalog.string_to_array(candidate_ids, ',')::uuid[]
    );
    GET DIAGNOSTICS statement_count = ROW_COUNT;
    removed_count := removed_count + statement_count;

    RETURN QUERY SELECT removed_count,
        redemption_count = p_limit OR candidate_count = p_limit;
END;
$$;


ALTER FUNCTION platform.billing_purge_subscription_retention_v1(p_authority_id uuid, p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: billing_rebuild_revenue_projection_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_rebuild_revenue_projection_v1(p_rebuild_id uuid, p_actor_id uuid, p_authority_id uuid, p_rebuilt_at timestamp with time zone) RETURNS TABLE(source_count bigint, projected_count bigint, source_revision_ceiling bigint, source_sha256 bytea, projection_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    group_generation bigint;
    billing_generation bigint;
    before_sha bytea;
    before_count bigint;
    before_revision bigint;
    source_count_value bigint;
    source_revision_value bigint;
    source_sha_value bytea;
    projection_count_value bigint;
    projection_revision_value bigint;
    projection_sha_value bytea;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR pg_catalog.uuid_extract_version(p_rebuild_id) <> 7
       OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_rebuilt_at IS DISTINCT FROM
          pg_catalog.date_trunc('microseconds', p_rebuilt_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing revenue rebuild input is invalid';
    END IF;

    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    SELECT authority.authority_group_generation,
           authority.authority_domain_generation
    INTO group_generation, billing_generation
    FROM platform.billing_global_authorities AS authority
    WHERE authority.authority_id = p_authority_id
    FOR SHARE;

    IF group_generation IS NULL OR billing_generation IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing revenue rebuild authority is unavailable';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:v2:billing:revenue-rebuild', 0
    ));

    SELECT digest.row_count, digest.revision_ceiling,
           digest.canonical_sha256
    INTO before_count, before_revision, before_sha
    FROM platform.billing_revenue_projection_digest_v1(p_authority_id) AS digest;

    SELECT digest.row_count, digest.revision_ceiling,
           digest.canonical_sha256
    INTO source_count_value, source_revision_value, source_sha_value
    FROM platform.billing_revenue_source_digest_v1(p_authority_id) AS digest;

    DELETE FROM platform.billing_revenue_projection;

    PERFORM platform.billing_refresh_revenue_projection_v1(source.id)
    FROM (
        SELECT subscription.id
        FROM platform.billing_subscriptions AS subscription
        JOIN platform.billing_price_versions AS price
          ON price.id = subscription.price_version_id
         AND price.offering_version_id = subscription.offering_version_id
        WHERE subscription.state IN ('active', 'past_due')
          AND price.cadence IN ('monthly', 'yearly')
        ORDER BY subscription.id
    ) AS source;

    SELECT digest.row_count, digest.revision_ceiling,
           digest.canonical_sha256
    INTO projection_count_value, projection_revision_value,
         projection_sha_value
    FROM platform.billing_revenue_projection_digest_v1(p_authority_id) AS digest;

    IF source_count_value IS DISTINCT FROM projection_count_value
       OR source_revision_value IS DISTINCT FROM projection_revision_value
       OR source_sha_value IS DISTINCT FROM projection_sha_value THEN
        RAISE EXCEPTION USING ERRCODE = 'P5790',
            MESSAGE = 'billing revenue projection rebuild differs from source';
    END IF;

    INSERT INTO platform.billing_revenue_rebuilds (
        id, authority_id, actor_id, authority_group_generation,
        billing_generation, source_count, projected_count,
        source_revision_ceiling, before_sha256, source_sha256,
        after_sha256, rebuilt_at
    ) VALUES (
        p_rebuild_id, p_authority_id, p_actor_id, group_generation,
        billing_generation, source_count_value, projection_count_value,
        source_revision_value, before_sha, source_sha_value,
        projection_sha_value, p_rebuilt_at
    );

    RETURN QUERY SELECT
        source_count_value, projection_count_value,
        source_revision_value, source_sha_value, projection_sha_value;
END;
$$;


ALTER FUNCTION platform.billing_rebuild_revenue_projection_v1(p_rebuild_id uuid, p_actor_id uuid, p_authority_id uuid, p_rebuilt_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_reconcile_current_global_authority_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_reconcile_current_global_authority_v1() RETURNS TABLE(reconciled_count integer, remaining_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_group_generation bigint;
    v_domain_generation bigint;
BEGIN
    reconciled_count := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global authority reconciliation is denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'harpy:billing:global-authority-reconcile:v1', 0
        )
    );
    SELECT group_row.generation, domain_row.generation
    INTO STRICT v_group_generation, v_domain_generation
    FROM platform.environment_identity AS environment
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'global'
     AND group_row.scope_id = environment.environment_id
     AND group_row.group_id = 'billing'
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.ordinal = 1 AND member_row.domain = 'billing'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE group_row.state = 'v2' AND group_row.writer = 'v2'
      AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS extra
          WHERE extra.scope_kind = group_row.scope_kind
            AND extra.scope_id = group_row.scope_id
            AND extra.group_id = group_row.group_id
            AND NOT (extra.ordinal = 1 AND extra.domain = 'billing')
      )
    FOR SHARE OF group_row, member_row, domain_row;
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_global_authorities AS authority
        WHERE authority.authority_group_generation = v_group_generation
          AND authority.authority_domain_generation = v_domain_generation
    ) THEN
        BEGIN
            PERFORM platform.billing_register_global_authority_v1(
                pg_catalog.uuidv7(), v_group_generation, v_domain_generation,
                pg_catalog.transaction_timestamp()
            );
            reconciled_count := 1;
        EXCEPTION WHEN SQLSTATE '23505' THEN
            IF NOT EXISTS (
                SELECT 1 FROM platform.billing_global_authorities AS authority
                WHERE authority.authority_group_generation = v_group_generation
                  AND authority.authority_domain_generation = v_domain_generation
            ) THEN
                RAISE;
            END IF;
        END;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_global_authorities AS authority
        WHERE authority.authority_group_generation = v_group_generation
          AND authority.authority_domain_generation = v_domain_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing global authority reconciliation is incomplete';
    END IF;
    RETURN QUERY SELECT reconciled_count, 0;
END;
$$;


ALTER FUNCTION platform.billing_reconcile_current_global_authority_v1() OWNER TO harpy_owner;

--
-- Name: billing_reconcile_current_global_authority_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_reconcile_current_global_authority_v2() RETURNS TABLE(reconciled_count integer, remaining_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_group_generation bigint;
    v_domain_generation bigint;
BEGIN
    reconciled_count := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR platform.tenancy_authority_reconcile_scope_assert_v1(
           'billing'
       ) IS DISTINCT FROM TRUE THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global authority reconciliation is denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'harpy:billing:global-authority-reconcile:v2', 0
        )
    );
    SELECT group_row.generation, domain_row.generation
    INTO STRICT v_group_generation, v_domain_generation
    FROM platform.environment_identity AS environment
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'global'
     AND group_row.scope_id = environment.environment_id
     AND group_row.group_id = 'billing'
    JOIN platform.cutover_group_members AS member_row
      ON member_row.scope_kind = group_row.scope_kind
     AND member_row.scope_id = group_row.scope_id
     AND member_row.group_id = group_row.group_id
     AND member_row.ordinal = 1 AND member_row.domain = 'billing'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = member_row.scope_kind
     AND domain_row.scope_id = member_row.scope_id
     AND domain_row.domain = member_row.domain
    WHERE group_row.state = 'v2' AND group_row.writer = 'v2'
      AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS extra
          WHERE extra.scope_kind = group_row.scope_kind
            AND extra.scope_id = group_row.scope_id
            AND extra.group_id = group_row.group_id
            AND NOT (extra.ordinal = 1 AND extra.domain = 'billing')
      )
    FOR SHARE OF group_row, member_row, domain_row;
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_global_authorities AS authority
        WHERE authority.authority_group_generation = v_group_generation
          AND authority.authority_domain_generation = v_domain_generation
    ) THEN
        BEGIN
            PERFORM platform.billing_register_global_authority_v1(
                pg_catalog.uuidv7(), v_group_generation, v_domain_generation,
                pg_catalog.transaction_timestamp()
            );
            reconciled_count := 1;
        EXCEPTION WHEN SQLSTATE '23505' THEN
            IF NOT EXISTS (
                SELECT 1 FROM platform.billing_global_authorities AS authority
                WHERE authority.authority_group_generation = v_group_generation
                  AND authority.authority_domain_generation = v_domain_generation
            ) THEN
                RAISE;
            END IF;
        END;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_global_authorities AS authority
        WHERE authority.authority_group_generation = v_group_generation
          AND authority.authority_domain_generation = v_domain_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing global authority reconciliation is incomplete';
    END IF;
    RETURN QUERY SELECT reconciled_count, 0;
END;
$$;


