--
-- Name: billing_record_v1_adoption_mapping_v1(uuid, uuid, text, text, text, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_record_v1_adoption_mapping_v1(p_operation_id uuid, p_run_id uuid, p_category text, p_source_key text, p_record_kind text, p_target_id uuid, p_record_sha256 bytea, p_recorded_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
BEGIN
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id
      AND run.run_id = p_run_id
      AND run.state = 'planned'
      AND run.eligible
    FOR SHARE;
    IF p_category IS NULL OR p_source_key IS NULL
       OR p_record_kind IS NULL OR p_target_id IS NULL
       OR pg_catalog.octet_length(p_record_sha256) <> 32
       OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption mapping is invalid';
    END IF;
    INSERT INTO platform.billing_v1_adoption_mappings (
        operation_id, run_id, scope_kind, scope_id, authority_id,
        category, source_key, record_kind, target_id,
        record_sha256, created_at
    ) VALUES (
        p_operation_id, p_run_id, v_run.scope_kind, v_run.scope_id,
        v_run.authority_id, p_category, p_source_key, p_record_kind,
        p_target_id, p_record_sha256, p_recorded_at
    );
END;
$$;


ALTER FUNCTION platform.billing_record_v1_adoption_mapping_v1(p_operation_id uuid, p_run_id uuid, p_category text, p_source_key text, p_record_kind text, p_target_id uuid, p_record_sha256 bytea, p_recorded_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_refresh_revenue_projection_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_refresh_revenue_projection_v1(p_subscription_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    current_authority uuid;
BEGIN
    SELECT authority.authority_id
    INTO current_authority
    FROM platform.billing_global_authorities AS authority
    JOIN platform.environment_identity AS identity
      ON identity.environment_id = authority.scope_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = authority.scope_kind
     AND group_row.scope_id = authority.scope_id
     AND group_row.group_id = authority.authority_group_id
     AND group_row.generation = authority.authority_group_generation
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = authority.scope_kind
     AND domain_row.scope_id = authority.scope_id
     AND domain_row.domain = authority.authority_domain
     AND domain_row.generation = authority.authority_domain_generation
    WHERE authority.scope_kind = 'global'
      AND authority.authority_group_id = 'billing'
      AND authority.authority_domain = 'billing'
    FOR SHARE OF authority, group_row, domain_row;

    IF current_authority IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing revenue global authority is not current';
    END IF;
    PERFORM platform.billing_assert_global_authority_v1(current_authority);

    DELETE FROM platform.billing_revenue_projection AS projection
    WHERE projection.subscription_id = p_subscription_id
      AND NOT EXISTS (
        SELECT 1
        FROM platform.billing_subscriptions AS subscription
        JOIN platform.billing_price_versions AS price
          ON price.id = subscription.price_version_id
         AND price.offering_version_id = subscription.offering_version_id
        WHERE subscription.id = p_subscription_id
          AND subscription.state IN ('active', 'past_due')
          AND price.cadence IN ('monthly', 'yearly')
      );

    INSERT INTO platform.billing_revenue_projection (
        id, authority_id, subscription_id, subscription_revision,
        offering_version_id, price_version_id, price_source_sha256,
        state, cadence, currency, currency_registry_version,
        source_minor_units, monthly_minor_units, annual_minor_units,
        refreshed_at
    )
    SELECT
        platform.billing_revenue_projection_id_v1(subscription.id),
        current_authority, subscription.id, subscription.revision,
        subscription.offering_version_id, subscription.price_version_id,
        pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.concat_ws(
            pg_catalog.chr(31), price.id::text,
            subscription.offering_version_id::text, price.cadence,
            price.minor_units::text, price.currency::text,
            price.currency_registry_version::text, price.money_policy_version
        ), 'UTF8')),
        subscription.state, price.cadence, price.currency,
        price.currency_registry_version, price.minor_units,
        platform.billing_revenue_monthly_v1(
            price.minor_units, price.cadence
        ),
        CASE WHEN price.cadence = 'monthly'
            THEN price.minor_units * 12
            ELSE price.minor_units
        END,
        pg_catalog.clock_timestamp()
    FROM platform.billing_subscriptions AS subscription
    JOIN platform.billing_price_versions AS price
      ON price.id = subscription.price_version_id
     AND price.offering_version_id = subscription.offering_version_id
    WHERE subscription.id = p_subscription_id
      AND subscription.state IN ('active', 'past_due')
      AND price.cadence IN ('monthly', 'yearly')
    ON CONFLICT (subscription_id) DO UPDATE SET
        authority_id = EXCLUDED.authority_id,
        subscription_revision = EXCLUDED.subscription_revision,
        offering_version_id = EXCLUDED.offering_version_id,
        price_version_id = EXCLUDED.price_version_id,
        price_source_sha256 = EXCLUDED.price_source_sha256,
        state = EXCLUDED.state,
        cadence = EXCLUDED.cadence,
        currency = EXCLUDED.currency,
        currency_registry_version = EXCLUDED.currency_registry_version,
        source_minor_units = EXCLUDED.source_minor_units,
        monthly_minor_units = EXCLUDED.monthly_minor_units,
        annual_minor_units = EXCLUDED.annual_minor_units,
        refreshed_at = EXCLUDED.refreshed_at;
END;
$$;


ALTER FUNCTION platform.billing_refresh_revenue_projection_v1(p_subscription_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_register_global_authority_v1(uuid, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_register_global_authority_v1(p_authority_id uuid, p_group_generation bigint, p_billing_generation bigint, p_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    environment_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global registration session is invalid';
    END IF;
    SELECT identity.environment_id INTO environment_id
    FROM platform.environment_identity AS identity
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = 'global'
     AND group_row.scope_id = identity.environment_id
     AND group_row.group_id = 'billing'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = group_row.scope_kind
     AND domain_row.scope_id = group_row.scope_id
     AND domain_row.domain = 'billing'
    WHERE group_row.state = 'v2' AND group_row.writer = 'v2'
      AND domain_row.state = 'v2' AND domain_row.writer = 'v2'
      AND group_row.generation = p_group_generation
      AND domain_row.generation = p_billing_generation
    FOR SHARE OF group_row, domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing global registration authority is not ready';
    END IF;
    INSERT INTO platform.billing_global_authorities (
        authority_id, scope_kind, scope_id, authority_group_id,
        authority_group_generation, authority_domain,
        authority_domain_generation, created_at
    ) VALUES (
        p_authority_id, 'global', environment_id, 'billing',
        p_group_generation, 'billing', p_billing_generation, p_created_at
    );
END;
$$;


ALTER FUNCTION platform.billing_register_global_authority_v1(p_authority_id uuid, p_group_generation bigint, p_billing_generation bigint, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_register_tenant_authority_v1(uuid, uuid, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_register_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid, p_group_generation bigint, p_billing_generation bigint, p_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant registration session is invalid';
    END IF;
    PERFORM 1
    FROM platform.cutover_groups AS group_row
    JOIN platform.domain_cutovers AS billing_row
      ON billing_row.scope_kind = group_row.scope_kind
     AND billing_row.scope_id = group_row.scope_id
     AND billing_row.domain = 'billing'
    WHERE group_row.scope_kind = 'tenant'
      AND group_row.scope_id = p_tenant_id
      AND group_row.group_id = 'billing'
      AND group_row.state = 'v2' AND group_row.writer = 'v2'
      AND billing_row.state = 'v2' AND billing_row.writer = 'v2'
      AND group_row.generation = p_group_generation
      AND billing_row.generation = p_billing_generation
    FOR SHARE OF group_row, billing_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing tenant registration authority is not ready';
    END IF;
    INSERT INTO platform.billing_tenant_authorities (
        authority_id, tenant_id, scope_kind, scope_id, authority_group_id,
        authority_group_generation, billing_domain, billing_generation,
        created_at
    ) VALUES (
        p_authority_id, p_tenant_id, 'tenant', p_tenant_id, 'billing',
        p_group_generation, 'billing', p_billing_generation, p_created_at
    );
END;
$$;


ALTER FUNCTION platform.billing_register_tenant_authority_v1(p_authority_id uuid, p_tenant_id uuid, p_group_generation bigint, p_billing_generation bigint, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_register_v1_adoption_v1(uuid, uuid, uuid, bytea, text, bytea, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_register_v1_adoption_v1(p_operation_id uuid, p_run_id uuid, p_authority_id uuid, p_plan_bytes bytea, p_plan_sha256 text, p_cutover_evidence_bytes bytea, p_cutover_envelope_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_plan jsonb;
    v_evidence jsonb;
    v_scope_kind text;
    v_scope_id uuid;
    v_source_sha256 text;
    v_eligible boolean;
    v_issue_count integer;
    v_existing bytea;
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_operation_id IS NULL OR p_run_id IS NULL
       OR p_authority_id IS NULL
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
       OR p_cutover_envelope_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(p_plan_bytes) NOT BETWEEN 2 AND 67108864
       OR pg_catalog.octet_length(p_cutover_evidence_bytes) NOT BETWEEN 2 AND 16384
       OR pg_catalog.encode(pg_catalog.sha256(p_plan_bytes), 'hex')
            IS DISTINCT FROM p_plan_sha256
       OR pg_catalog.encode(pg_catalog.sha256(p_cutover_evidence_bytes), 'hex')
            IS DISTINCT FROM p_cutover_envelope_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption registration is denied';
    END IF;
    v_plan := pg_catalog.convert_from(p_plan_bytes, 'UTF8')::jsonb;
    v_evidence := pg_catalog.convert_from(p_cutover_evidence_bytes, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_plan) IS DISTINCT FROM 'object'
       OR (SELECT pg_catalog.array_agg(key ORDER BY key)
           FROM pg_catalog.jsonb_object_keys(v_plan) AS key)
          IS DISTINCT FROM ARRAY[
              'base_assignments', 'campaigns', 'categories',
              'contract_version', 'discounts', 'eligible',
              'gauge_openings', 'issues', 'legacy_events',
              'manual_provider_account_id',
              'offerings', 'redemptions', 'scope_id', 'scope_kind',
              'snapshot_at', 'source_sha256', 'source_timezone',
              'subscriptions', 'usage_openings'
          ]::text[]
       OR v_plan->>'contract_version'
            IS DISTINCT FROM 'harpy/billing-v1-adoption-plan/v1'
       OR v_plan->>'source_timezone' IS DISTINCT FROM 'UTC'
       OR v_plan->>'source_sha256' !~ '^[0-9a-f]{64}$'
       OR pg_catalog.jsonb_typeof(v_plan->'categories') IS DISTINCT FROM 'array'
       OR pg_catalog.jsonb_typeof(v_plan->'issues') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption plan contract is invalid';
    END IF;
    v_scope_kind := v_plan->>'scope_kind';
    v_scope_id := (v_plan->>'scope_id')::uuid;
    v_source_sha256 := v_plan->>'source_sha256';
    v_eligible := (v_plan->>'eligible')::boolean;
    v_issue_count := pg_catalog.jsonb_array_length(v_plan->'issues');
    IF pg_catalog.jsonb_typeof(v_evidence) IS DISTINCT FROM 'object'
       OR (SELECT pg_catalog.array_agg(key ORDER BY key)
           FROM pg_catalog.jsonb_object_keys(v_evidence) AS key)
          IS DISTINCT FROM ARRAY[
              'batch_sha256', 'contract_version', 'evidence_generation',
              'lease_id', 'lease_manifest_sha256', 'operation_id',
              'plan_sha256', 'run_id', 'scope_id', 'scope_kind',
              'session_seal_receipt_id', 'session_seal_sha256'
          ]::text[]
       OR v_evidence->>'contract_version' IS DISTINCT FROM
            'harpy/billing-v1-cutover-evidence/v1'
       OR (v_evidence->>'operation_id')::uuid IS DISTINCT FROM p_operation_id
       OR (v_evidence->>'run_id')::uuid IS DISTINCT FROM p_run_id
       OR v_evidence->>'scope_kind' IS DISTINCT FROM v_scope_kind
       OR (v_evidence->>'scope_id')::uuid IS DISTINCT FROM v_scope_id
       OR v_evidence->>'plan_sha256' IS DISTINCT FROM p_plan_sha256
       OR (v_evidence->>'evidence_generation')::bigint < 1
       OR v_evidence->>'lease_manifest_sha256' !~ '^[0-9a-f]{64}$'
       OR v_evidence->>'batch_sha256' !~ '^[0-9a-f]{64}$'
       OR v_evidence->>'session_seal_sha256' !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing V1 verified cutover envelope is invalid';
    END IF;
    IF v_scope_kind NOT IN ('global', 'tenant')
       OR v_scope_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR v_eligible IS DISTINCT FROM (v_issue_count = 0)
       OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(v_plan->'categories') AS value
           WHERE (SELECT pg_catalog.array_agg(key ORDER BY key)
                  FROM pg_catalog.jsonb_object_keys(value) AS key)
                 IS DISTINCT FROM
                    ARRAY['category','root_sha256','row_count']::text[]
              OR value->>'root_sha256' !~ '^[0-9a-f]{64}$'
              OR (value->>'row_count')::bigint < 0
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption plan evidence is invalid';
    END IF;
    SELECT plan_sha256 INTO v_existing
    FROM platform.billing_v1_adoption_runs
    WHERE operation_id = p_operation_id AND run_id = p_run_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing IS DISTINCT FROM pg_catalog.decode(p_plan_sha256, 'hex') THEN
            RAISE EXCEPTION USING ERRCODE = '22000',
                MESSAGE = 'billing V1 adoption operation identity was reused';
        END IF;
        RETURN (
            SELECT state FROM platform.billing_v1_adoption_runs
            WHERE operation_id = p_operation_id AND run_id = p_run_id
        );
    END IF;
    INSERT INTO platform.billing_v1_adoption_runs (
        operation_id, run_id, scope_kind, scope_id, authority_id,
        cutover_lease_id, cutover_evidence_generation,
        cutover_lease_sha256, cutover_batch_sha256,
        cutover_session_seal_receipt_id, cutover_session_seal_sha256,
        cutover_envelope_sha256,
        contract_version, plan_sha256, source_sha256, plan_bytes,
        plan_document, state, eligible, issue_count, snapshot_at,
        source_timezone, created_at, updated_at
    ) VALUES (
        p_operation_id, p_run_id, v_scope_kind, v_scope_id, p_authority_id,
        (v_evidence->>'lease_id')::uuid,
        (v_evidence->>'evidence_generation')::bigint,
        pg_catalog.decode(v_evidence->>'lease_manifest_sha256', 'hex'),
        pg_catalog.decode(v_evidence->>'batch_sha256', 'hex'),
        (v_evidence->>'session_seal_receipt_id')::uuid,
        pg_catalog.decode(v_evidence->>'session_seal_sha256', 'hex'),
        pg_catalog.decode(p_cutover_envelope_sha256, 'hex'),
        v_plan->>'contract_version', pg_catalog.decode(p_plan_sha256, 'hex'),
        pg_catalog.decode(v_source_sha256, 'hex'), p_plan_bytes, v_plan,
        CASE WHEN v_eligible THEN 'planned' ELSE 'blocked' END,
        v_eligible, v_issue_count, (v_plan->>'snapshot_at')::timestamptz,
        'UTC', v_now, v_now
    );
    INSERT INTO platform.billing_v1_adoption_categories (
        operation_id, run_id, scope_kind, scope_id, authority_id,
        category, source_count, source_sha256, updated_at
    )
    SELECT p_operation_id, p_run_id, v_scope_kind, v_scope_id,
        p_authority_id, value->>'category', (value->>'row_count')::bigint,
        pg_catalog.decode(value->>'root_sha256', 'hex'), v_now
    FROM pg_catalog.jsonb_array_elements(v_plan->'categories') AS value;
    RETURN CASE WHEN v_eligible THEN 'planned' ELSE 'blocked' END;
END;
$_$;


ALTER FUNCTION platform.billing_register_v1_adoption_v1(p_operation_id uuid, p_run_id uuid, p_authority_id uuid, p_plan_bytes bytea, p_plan_sha256 text, p_cutover_evidence_bytes bytea, p_cutover_envelope_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_rehearse_v1_adoption_rollback_v1(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_rehearse_v1_adoption_rollback_v1(p_operation_id uuid, p_run_id uuid, p_receipt_id uuid, p_observed_source_sha256 text, p_rehearsed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, source_sha256 text, reverse_sha256 text, rehearsed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_target bytea;
    v_existing platform.billing_v1_adoption_rollback_rehearsals%ROWTYPE;
BEGIN
    IF p_observed_source_sha256 !~ '^[0-9a-f]{64}$'
       OR p_rehearsed_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 rollback observation is invalid';
    END IF;
    SELECT rehearsal.* INTO v_existing
    FROM platform.billing_v1_adoption_rollback_rehearsals AS rehearsal
    WHERE rehearsal.operation_id = p_operation_id AND rehearsal.run_id = p_run_id;
    IF FOUND THEN
        IF v_existing.receipt_id IS DISTINCT FROM p_receipt_id
           OR v_existing.observed_source_sha256 IS DISTINCT FROM
                pg_catalog.decode(p_observed_source_sha256, 'hex') THEN
            RAISE EXCEPTION USING ERRCODE = '22000',
                MESSAGE = 'billing V1 rollback receipt identity was reused';
        END IF;
        RETURN QUERY SELECT v_existing.receipt_id,
            pg_catalog.encode(v_existing.observed_source_sha256, 'hex'),
            pg_catalog.encode(v_existing.reverse_sha256, 'hex'),
            v_existing.rehearsed_at;
        RETURN;
    END IF;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
      AND run.state = 'verified'
      AND run.money_difference = 0 AND run.period_difference = 0
      AND run.coupon_difference = 0 AND run.usage_difference = 0
    FOR UPDATE;
    IF v_run.source_sha256 IS DISTINCT FROM
       pg_catalog.decode(p_observed_source_sha256, 'hex') THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing V1 source changed before rollback rehearsal';
    END IF;
    SELECT pg_catalog.sha256(pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
        record_kind || ':' || source_key || ':' ||
        pg_catalog.encode(current_sha, 'hex'), '|'
        ORDER BY record_kind, source_key
    ) FILTER (WHERE current_sha IS NOT NULL), ''), 'UTF8'))
    INTO v_target
    FROM (
        SELECT mapping.record_kind, mapping.source_key,
            platform.billing_v1_adoption_fingerprint_v1(
                mapping.record_kind, mapping.target_id
            ) AS current_sha
        FROM platform.billing_v1_adoption_mappings AS mapping
        WHERE mapping.operation_id = p_operation_id AND mapping.run_id = p_run_id
    ) AS current_rows;
    IF v_target IS DISTINCT FROM v_run.target_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'billing V2 target changed before rollback rehearsal';
    END IF;
    INSERT INTO platform.billing_v1_adoption_rollback_rehearsals (
        receipt_id, operation_id, run_id, scope_kind, scope_id, authority_id,
        observed_source_sha256, reverse_sha256, target_sha256,
        zero_difference, rehearsed_at
    ) VALUES (
        p_receipt_id, p_operation_id, p_run_id, v_run.scope_kind,
        v_run.scope_id, v_run.authority_id,
        pg_catalog.decode(p_observed_source_sha256, 'hex'),
        pg_catalog.decode(p_observed_source_sha256, 'hex'),
        v_target, true, p_rehearsed_at
    );
    UPDATE platform.billing_v1_adoption_runs SET
        state = 'rollback_rehearsed', rehearsed_at = p_rehearsed_at,
        updated_at = p_rehearsed_at
    WHERE operation_id = p_operation_id AND run_id = p_run_id;
    RETURN QUERY SELECT p_receipt_id, p_observed_source_sha256,
        p_observed_source_sha256, p_rehearsed_at;
END;
$_$;


ALTER FUNCTION platform.billing_rehearse_v1_adoption_rollback_v1(p_operation_id uuid, p_run_id uuid, p_receipt_id uuid, p_observed_source_sha256 text, p_rehearsed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_release_legal_hold_v1(uuid, uuid, uuid, uuid, uuid, text, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_release_legal_hold_v1(p_authority_id uuid, p_tenant_id uuid, p_hold_id uuid, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_reason text, p_occurred_at timestamp with time zone) RETURNS TABLE(hold_id uuid, tenant_id uuid, state text, placed_by uuid, place_operation_id uuid, reason text, ticket_reference text, placed_at timestamp with time zone, released_by uuid, release_operation_id uuid, release_reason text, released_at timestamp with time zone, revision bigint, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored platform.billing_legal_holds%ROWTYPE;
BEGIN
    PERFORM platform.billing_assert_tenant_authority_v1(p_authority_id);
    IF NOT EXISTS (
        SELECT 1 FROM platform.billing_tenant_authorities AS authority_row
        WHERE authority_row.authority_id = p_authority_id
          AND authority_row.tenant_id = p_tenant_id
    ) OR pg_catalog.uuid_extract_version(p_hold_id) <> 7
       OR pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128
       OR pg_catalog.octet_length(p_request_sha256) <> 32
       OR pg_catalog.octet_length(p_reason) NOT BETWEEN 1 AND 2048
       OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing legal hold release input is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'billing:legal-hold:' || p_tenant_id::text, 0
    ));
    SELECT * INTO stored
    FROM platform.billing_legal_holds AS legal_hold
    WHERE legal_hold.tenant_id = p_tenant_id AND legal_hold.id = p_hold_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5731',
            MESSAGE = 'billing legal hold does not exist';
    END IF;
    IF stored.state IS NOT DISTINCT FROM 'released' THEN
        IF stored.release_idempotency_key IS DISTINCT FROM p_idempotency_key
           OR stored.release_request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5730',
                MESSAGE = 'billing legal hold release key was reused';
        END IF;
        RETURN QUERY SELECT stored.id, stored.tenant_id, stored.state,
            stored.placed_by, stored.place_operation_id, stored.reason,
            stored.ticket_reference, stored.placed_at, stored.released_by,
            stored.release_operation_id, stored.release_reason,
            stored.released_at, stored.revision, true;
        RETURN;
    END IF;
    UPDATE platform.billing_legal_holds AS legal_hold
       SET state = 'released', released_by = p_actor_id,
           release_operation_id = p_operation_id,
           release_idempotency_key = p_idempotency_key,
           release_request_sha256 = p_request_sha256,
           release_reason = p_reason, released_at = p_occurred_at,
           revision = legal_hold.revision + 1
     WHERE legal_hold.tenant_id = p_tenant_id AND legal_hold.id = p_hold_id
     RETURNING * INTO stored;
    RETURN QUERY SELECT stored.id, stored.tenant_id, stored.state,
        stored.placed_by, stored.place_operation_id, stored.reason,
        stored.ticket_reference, stored.placed_at, stored.released_by,
        stored.release_operation_id, stored.release_reason,
        stored.released_at, stored.revision, false;
END;
$$;


ALTER FUNCTION platform.billing_release_legal_hold_v1(p_authority_id uuid, p_tenant_id uuid, p_hold_id uuid, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_reason text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_replace_discount_campaign_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_replace_discount_campaign_v1(p_authority_id uuid, p_operation_id uuid, p_discount_id uuid, p_old_discount_version_id uuid, p_new_discount_version_id uuid, p_campaign_id uuid, p_campaign_version_id_one uuid, p_campaign_version_id_two uuid, p_campaign_operation_id_one uuid, p_campaign_operation_id_two uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_previous_campaign_id uuid;
    v_campaign_id uuid;
    v_current_id uuid;
    v_current_version bigint;
    v_current_priority integer;
    v_current_starts_at timestamptz;
    v_current_ends_at timestamptz;
    v_current_metadata jsonb;
    v_current_sha256 bytea;
    v_current_name text;
    v_current_description text;
    v_current_banner text;
    v_current_auto_apply boolean;
    v_current_available boolean;
    v_revision bigint;
    v_count smallint;
    v_position integer;
    v_version_id uuid;
    v_operation_id uuid;
BEGIN
    v_position := 0;
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    PERFORM platform.billing_assert_promotion_association_v1(
        p_authority_id, p_operation_id, p_discount_id,
        p_old_discount_version_id, p_new_discount_version_id,
        p_campaign_id, p_campaign_version_id_one, p_campaign_version_id_two,
        p_campaign_operation_id_one, p_campaign_operation_id_two, p_occurred_at
    );
    IF p_new_discount_version_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing promotion association input is invalid';
    END IF;

    IF p_old_discount_version_id IS NOT NULL THEN
        SELECT CASE WHEN pg_catalog.count(DISTINCT version_row.campaign_id) = 1
                    THEN pg_catalog.min(version_row.campaign_id::text)::uuid END
          INTO v_previous_campaign_id
        FROM platform.billing_campaign_discounts AS binding
        JOIN platform.billing_campaign_versions AS version_row
          ON version_row.authority_id = binding.authority_id
         AND version_row.id = binding.campaign_version_id
        WHERE binding.authority_id = p_authority_id
          AND binding.discount_version_id = p_old_discount_version_id
          AND NOT EXISTS (
              SELECT 1
              FROM platform.billing_campaign_versions AS successor
              WHERE successor.authority_id = version_row.authority_id
                AND successor.superseded_version_id = version_row.id
          );
        IF (
            SELECT pg_catalog.count(DISTINCT version_row.campaign_id)
            FROM platform.billing_campaign_discounts AS binding
            JOIN platform.billing_campaign_versions AS version_row
              ON version_row.authority_id = binding.authority_id
             AND version_row.id = binding.campaign_version_id
            WHERE binding.authority_id = p_authority_id
              AND binding.discount_version_id = p_old_discount_version_id
              AND NOT EXISTS (
                  SELECT 1 FROM platform.billing_campaign_versions AS successor
                  WHERE successor.authority_id = version_row.authority_id
                    AND successor.superseded_version_id = version_row.id
              )
        ) > 1 THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'billing discount has ambiguous campaign association';
        END IF;
    END IF;

    FOR v_campaign_id IN
        SELECT DISTINCT value
        FROM pg_catalog.unnest(ARRAY[
            v_previous_campaign_id, p_campaign_id
        ]) AS selected(value)
        WHERE value IS NOT NULL
        ORDER BY value
    LOOP
        v_position := v_position + 1;
        v_version_id := CASE v_position WHEN 1 THEN p_campaign_version_id_one
            ELSE p_campaign_version_id_two END;
        v_operation_id := CASE v_position WHEN 1 THEN p_campaign_operation_id_one
            ELSE p_campaign_operation_id_two END;
        SELECT version_row.id, version_row.version, version_row.priority,
               version_row.starts_at, version_row.ends_at,
               version_row.presentation_metadata, version_row.presentation_sha256,
               version_row.presentation_name, version_row.presentation_description,
               version_row.presentation_banner_text, version_row.auto_apply,
               version_row.available
          INTO STRICT v_current_id, v_current_version, v_current_priority,
               v_current_starts_at, v_current_ends_at, v_current_metadata,
               v_current_sha256, v_current_name, v_current_description,
               v_current_banner, v_current_auto_apply, v_current_available
        FROM platform.billing_campaign_versions AS version_row
        WHERE version_row.authority_id = p_authority_id
          AND version_row.campaign_id = v_campaign_id
          AND NOT EXISTS (
              SELECT 1 FROM platform.billing_campaign_versions AS successor
              WHERE successor.authority_id = version_row.authority_id
                AND successor.superseded_version_id = version_row.id
          )
        ORDER BY version_row.version DESC, version_row.id ASC
        LIMIT 1
        FOR SHARE;

        SELECT (
            pg_catalog.count(*) FILTER (
                WHERE discount_version.discount_id <> p_discount_id
            ) + CASE WHEN v_campaign_id = p_campaign_id THEN 1 ELSE 0 END
        )::smallint
          INTO v_count
        FROM platform.billing_campaign_discounts AS binding
        JOIN platform.billing_discount_versions AS discount_version
          ON discount_version.authority_id = binding.authority_id
         AND discount_version.id = binding.discount_version_id
        WHERE binding.authority_id = p_authority_id
          AND binding.campaign_version_id = v_current_id;

        UPDATE platform.billing_campaigns
        SET revision = revision + 1
        WHERE authority_id = p_authority_id AND id = v_campaign_id
          AND lifecycle = 'active' AND revision = v_current_version
        RETURNING revision INTO STRICT v_revision;

        INSERT INTO platform.billing_campaign_versions (
            id, authority_id, campaign_id, version, priority,
            expected_discount_count, starts_at, ends_at,
            presentation_metadata, presentation_sha256, publication_state,
            publication_operation_id, published_at, presentation_name,
            presentation_description, presentation_banner_text, auto_apply,
            available, superseded_version_id
        ) VALUES (
            v_version_id, p_authority_id, v_campaign_id, v_revision,
            v_current_priority, v_count, v_current_starts_at, v_current_ends_at,
            v_current_metadata, v_current_sha256,
            'published', v_operation_id, p_occurred_at,
            v_current_name, v_current_description,
            v_current_banner, v_current_auto_apply,
            v_current_available, v_current_id
        );

        INSERT INTO platform.billing_campaign_discounts (
            authority_id, campaign_version_id, discount_version_id, created_at
        )
        SELECT p_authority_id, v_version_id, binding.discount_version_id,
               p_occurred_at
        FROM platform.billing_campaign_discounts AS binding
        JOIN platform.billing_discount_versions AS discount_version
          ON discount_version.authority_id = binding.authority_id
         AND discount_version.id = binding.discount_version_id
        WHERE binding.authority_id = p_authority_id
          AND binding.campaign_version_id = v_current_id
          AND discount_version.discount_id <> p_discount_id;
        IF v_campaign_id = p_campaign_id THEN
            INSERT INTO platform.billing_campaign_discounts (
                authority_id, campaign_version_id, discount_version_id, created_at
            ) VALUES (
                p_authority_id, v_version_id,
                p_new_discount_version_id, p_occurred_at
            );
        END IF;
    END LOOP;

    IF v_previous_campaign_id IS DISTINCT FROM p_campaign_id THEN
        INSERT INTO platform.billing_promotion_association_receipts (
            operation_id, authority_id, discount_id,
            previous_campaign_id, campaign_id, occurred_at
        ) VALUES (
            p_operation_id, p_authority_id, p_discount_id,
            v_previous_campaign_id, p_campaign_id, p_occurred_at
        );
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_replace_discount_campaign_v1(p_authority_id uuid, p_operation_id uuid, p_discount_id uuid, p_old_discount_version_id uuid, p_new_discount_version_id uuid, p_campaign_id uuid, p_campaign_version_id_one uuid, p_campaign_version_id_two uuid, p_campaign_operation_id_one uuid, p_campaign_operation_id_two uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_resolve_current_global_authority_v1(text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_resolve_current_global_authority_v1(p_authority_group_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_authority_id uuid;
BEGIN
    IF p_authority_group_id IS DISTINCT FROM 'billing'
       OR SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global authority resolver session is invalid';
    END IF;
    SELECT authority.authority_id INTO STRICT v_authority_id
    FROM platform.billing_global_authorities AS authority
    JOIN platform.environment_identity AS identity
      ON identity.environment_id = authority.scope_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = authority.scope_kind
     AND group_row.scope_id = authority.scope_id
     AND group_row.group_id = authority.authority_group_id
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = authority.scope_kind
     AND domain_row.scope_id = authority.scope_id
     AND domain_row.domain = authority.authority_domain
    WHERE authority.scope_kind = 'global'
      AND authority.authority_group_id = p_authority_group_id
      AND authority.authority_domain = 'billing'
      AND authority.authority_group_generation = group_row.generation
      AND authority.authority_domain_generation = domain_row.generation
      AND group_row.writer = 'v2' AND group_row.state = 'v2'
      AND domain_row.writer = 'v2' AND domain_row.state = 'v2';
    RETURN v_authority_id;
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
        MESSAGE = 'billing global authority is not current';
END;
$$;


ALTER FUNCTION platform.billing_resolve_current_global_authority_v1(p_authority_group_id text) OWNER TO harpy_owner;

--
-- Name: billing_resolve_current_tenant_authority_receipt_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_resolve_current_tenant_authority_receipt_v1(p_tenant_id uuid) RETURNS TABLE(authority_id uuid, authority_group_id text, authority_group_generation bigint, billing_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_authority_id uuid;
BEGIN
    v_authority_id :=
        platform.billing_resolve_current_tenant_authority_v1(p_tenant_id);

    RETURN QUERY
    SELECT authority.authority_id,
           authority.authority_group_id,
           authority.authority_group_generation,
           authority.billing_generation
    FROM platform.billing_tenant_authorities AS authority
    WHERE authority.authority_id = v_authority_id
      AND authority.tenant_id = p_tenant_id
      AND authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.authority_group_id = 'billing'
      AND authority.billing_domain = 'billing'
    FOR SHARE OF authority;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant authority receipt is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_resolve_current_tenant_authority_receipt_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_resolve_current_tenant_authority_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_resolve_current_tenant_authority_v1(p_tenant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_authority_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR
       p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant authority resolver input is invalid';
    END IF;
    BEGIN
        SELECT authority.authority_id INTO STRICT v_authority_id
        FROM platform.billing_tenant_authorities AS authority
        JOIN platform.tenants AS tenant ON tenant.id = authority.tenant_id
        JOIN platform.cutover_groups AS group_row
          ON group_row.scope_kind = authority.scope_kind
         AND group_row.scope_id = authority.scope_id
         AND group_row.group_id = authority.authority_group_id
        JOIN platform.domain_cutovers AS billing_row
          ON billing_row.scope_kind = authority.scope_kind
         AND billing_row.scope_id = authority.scope_id
         AND billing_row.domain = authority.billing_domain
        JOIN platform.cutover_group_members AS billing_member
          ON billing_member.scope_kind = authority.scope_kind
         AND billing_member.scope_id = authority.scope_id
         AND billing_member.group_id = authority.authority_group_id
         AND billing_member.domain = 'billing' AND billing_member.ordinal = 1
        WHERE authority.tenant_id = p_tenant_id
          AND authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
          AND authority.authority_group_id = 'billing'
          AND authority.billing_domain = 'billing'
          AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE', 'TRIAL')
          AND group_row.state = 'v2' AND group_row.writer = 'v2'
          AND billing_row.state = 'v2' AND billing_row.writer = 'v2'
          AND authority.authority_group_generation = group_row.generation
          AND authority.billing_generation = billing_row.generation
          AND NOT EXISTS (
              SELECT 1 FROM platform.cutover_group_members AS extra
              WHERE extra.scope_kind = 'tenant' AND extra.scope_id = p_tenant_id
                AND extra.group_id = 'billing'
                AND NOT (extra.ordinal = 1 AND extra.domain = 'billing')
          );
    EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant authority is not current';
    END;
    RETURN v_authority_id;
END;
$$;


ALTER FUNCTION platform.billing_resolve_current_tenant_authority_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_restored_license_receipt_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_restored_license_receipt_read_v1(p_operation_id uuid, p_environment_id uuid) RETURNS TABLE(found boolean, operation_id uuid, restore_receipt_id uuid, restore_receipt_sha256 text, license_binding_id uuid, license_id uuid, licensee_organization_id uuid, environment_id uuid, previous_sequence bigint, previous_sha256 text, accepted_sequence bigint, accepted_sha256 text, authority_revision bigint, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_receipt platform.billing_license_restore_receipts%ROWTYPE;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR pg_catalog.current_setting('application_name', true)
            <> 'harpy-v2:core-operator-license-reconcile'
       OR p_operation_id IS NULL
       OR pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing restored license receipt read denied';
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM platform.tenancy_deployment_policy AS policy
          JOIN platform.tenancy_tenant_bindings AS binding
            ON binding.environment_id = policy.environment_id
           AND binding.purpose = 'onpremise_primary'
         WHERE policy.singleton
           AND policy.environment_id = p_environment_id
           AND policy.deployment_mode = 'onpremise'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing restored license receipt requires onpremise primary';
    END IF;
    SELECT receipt.* INTO v_receipt
      FROM platform.billing_license_restore_receipts AS receipt
     WHERE receipt.operation_id = p_operation_id;
    IF NOT FOUND THEN
        RETURN QUERY SELECT false,
            '00000000-0000-0000-0000-000000000000'::uuid,
            '00000000-0000-0000-0000-000000000000'::uuid,
            ''::text, '00000000-0000-0000-0000-000000000000'::uuid,
            '00000000-0000-0000-0000-000000000000'::uuid,
            '00000000-0000-0000-0000-000000000000'::uuid,
            p_environment_id, 0::bigint, ''::text,
            0::bigint, ''::text, 0::bigint, v_now;
        RETURN;
    END IF;
    IF v_receipt.environment_id IS DISTINCT FROM p_environment_id THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'restored license operation environment changed';
    END IF;
    RETURN QUERY SELECT true, v_receipt.operation_id,
        v_receipt.restore_receipt_id, v_receipt.restore_receipt_sha256,
        v_receipt.license_binding_id, v_receipt.license_id,
        v_receipt.licensee_organization_id, v_receipt.environment_id,
        v_receipt.previous_sequence, v_receipt.previous_sha256,
        v_receipt.accepted_sequence, v_receipt.accepted_sha256,
        v_receipt.authority_revision, v_now;
END;
$$;


ALTER FUNCTION platform.billing_restored_license_receipt_read_v1(p_operation_id uuid, p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_retention_delete_allowed_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_retention_delete_allowed_v1(selected_authority uuid, selected_tenant uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime'
       AND selected_authority IS NOT NULL
       AND selected_tenant IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM platform.billing_retention_contexts AS retention_context
           WHERE retention_context.backend_pid = pg_catalog.pg_backend_pid()
             AND retention_context.transaction_id =
                 pg_catalog.pg_current_xact_id_if_assigned()
             AND retention_context.authority_id = selected_authority
             AND retention_context.tenant_id = selected_tenant
       );
END;
$$;


ALTER FUNCTION platform.billing_retention_delete_allowed_v1(selected_authority uuid, selected_tenant uuid) OWNER TO harpy_owner;

--
-- Name: billing_retire_campaign_v1(uuid, uuid, uuid, uuid, text, bytea, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_retire_campaign_v1(p_authority_id uuid, p_operation_id uuid, p_campaign_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_expected_revision bigint, p_reason text, p_occurred_at timestamp with time zone) RETURNS TABLE(result_campaign_id uuid, result_revision bigint, result_lifecycle text, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored_request_sha256 bytea;
    stored_aggregate_id uuid;
    stored_revision bigint;
    stored_lifecycle text;
    stored_aggregate_kind text;
    stored_operation_kind text;
    updated_revision bigint;
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_authority_id::text || '|' || p_actor_id::text || '|' || p_idempotency_key, 0
    ));
    SELECT request_sha256, aggregate_id,
           billing_catalog_operations.result_revision,
           billing_catalog_operations.result_lifecycle,
           aggregate_kind, operation_kind
      INTO stored_request_sha256, stored_aggregate_id, stored_revision,
           stored_lifecycle, stored_aggregate_kind, stored_operation_kind
    FROM platform.billing_catalog_operations
    WHERE authority_id = p_authority_id AND actor_id = p_actor_id
      AND idempotency_key = p_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF stored_request_sha256 IS DISTINCT FROM p_request_sha256
           OR stored_aggregate_kind IS DISTINCT FROM 'campaign'
           OR stored_operation_kind IS DISTINCT FROM 'retire' THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'billing catalog idempotency key was reused';
        END IF;
        RETURN QUERY SELECT stored_aggregate_id, stored_revision,
            stored_lifecycle, true;
        RETURN;
    END IF;
    UPDATE platform.billing_campaigns
    SET lifecycle = 'retired', retired_at = p_occurred_at,
        revision = revision + 1
    WHERE authority_id = p_authority_id AND id = p_campaign_id
      AND lifecycle = 'active' AND revision = p_expected_revision
    RETURNING revision INTO updated_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'billing campaign revision is stale';
    END IF;
    INSERT INTO platform.billing_catalog_operations (
        operation_id, authority_id, actor_id, idempotency_key, request_sha256,
        aggregate_kind, aggregate_id, operation_kind, result_version_id,
        result_revision, result_version, result_lifecycle, reason, occurred_at
    ) VALUES (
        p_operation_id, p_authority_id, p_actor_id, p_idempotency_key,
        p_request_sha256, 'campaign', p_campaign_id, 'retire', NULL,
        updated_revision, NULL, 'retired', p_reason, p_occurred_at
    );
    RETURN QUERY SELECT p_campaign_id, updated_revision, 'retired'::text, false;
END;
$$;


ALTER FUNCTION platform.billing_retire_campaign_v1(p_authority_id uuid, p_operation_id uuid, p_campaign_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_expected_revision bigint, p_reason text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_retire_discount_v1(uuid, uuid, uuid, uuid, text, bytea, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_retire_discount_v1(p_authority_id uuid, p_operation_id uuid, p_discount_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_expected_revision bigint, p_reason text, p_occurred_at timestamp with time zone) RETURNS TABLE(result_discount_id uuid, result_version_id uuid, result_revision bigint, result_version bigint, result_lifecycle text, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    stored_request_sha256 bytea;
    stored_aggregate_id uuid;
    stored_revision bigint;
    stored_lifecycle text;
    updated_revision bigint;
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_authority_id::text || '|' || p_actor_id::text || '|' || p_idempotency_key, 0
    ));
    SELECT request_sha256, aggregate_id,
           billing_catalog_operations.result_revision,
           billing_catalog_operations.result_lifecycle
      INTO stored_request_sha256, stored_aggregate_id,
           stored_revision, stored_lifecycle
    FROM platform.billing_catalog_operations
    WHERE authority_id = p_authority_id AND actor_id = p_actor_id
      AND idempotency_key = p_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF stored_request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'billing catalog idempotency key was reused';
        END IF;
        RETURN QUERY SELECT stored_aggregate_id, NULL::uuid,
            stored_revision, NULL::bigint, stored_lifecycle, true;
        RETURN;
    END IF;
    UPDATE platform.billing_discounts
    SET lifecycle = 'revoked', revoked_at = p_occurred_at,
        revision = revision + 1
    WHERE authority_id = p_authority_id AND id = p_discount_id
      AND lifecycle = 'active' AND revision = p_expected_revision
    RETURNING revision INTO updated_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'billing discount revision is stale';
    END IF;
    INSERT INTO platform.billing_catalog_operations (
        operation_id, authority_id, actor_id, idempotency_key, request_sha256,
        aggregate_kind, aggregate_id, operation_kind, result_version_id,
        result_revision, result_version, result_lifecycle, reason, occurred_at
    ) VALUES (
        p_operation_id, p_authority_id, p_actor_id, p_idempotency_key,
        p_request_sha256, 'discount', p_discount_id, 'retire', NULL,
        updated_revision, NULL, 'retired', p_reason, p_occurred_at
    );
    RETURN QUERY SELECT p_discount_id, NULL::uuid, updated_revision,
        NULL::bigint, 'retired'::text, false;
END;
$$;


ALTER FUNCTION platform.billing_retire_discount_v1(p_authority_id uuid, p_operation_id uuid, p_discount_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_expected_revision bigint, p_reason text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

