--
-- Name: billing_revenue_monthly_v1(bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_revenue_monthly_v1(p_minor_units bigint, p_cadence text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    quotient bigint;
    remainder bigint;
BEGIN
    IF p_minor_units IS NULL OR p_cadence IS NULL OR p_minor_units < 0
       OR p_cadence NOT IN ('monthly', 'yearly') THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing revenue normalization input is invalid';
    END IF;
    IF p_cadence = 'monthly' THEN
        RETURN p_minor_units;
    END IF;
    quotient := p_minor_units / 12;
    remainder := p_minor_units % 12;
    IF remainder > 6 OR (remainder = 6 AND quotient % 2 = 1) THEN
        quotient := quotient + 1;
    END IF;
    RETURN quotient;
END;
$$;


ALTER FUNCTION platform.billing_revenue_monthly_v1(p_minor_units bigint, p_cadence text) OWNER TO harpy_owner;

--
-- Name: billing_revenue_projection_digest_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_revenue_projection_digest_v1(p_authority_id uuid) RETURNS TABLE(row_count bigint, revision_ceiling bigint, canonical_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    RETURN QUERY
    SELECT
        pg_catalog.count(*)::bigint,
        COALESCE(
            pg_catalog.max(subscription_revision), 0::bigint
        ),
        pg_catalog.sha256(pg_catalog.convert_to(
            COALESCE(pg_catalog.string_agg(
                pg_catalog.concat_ws(
                    pg_catalog.chr(31), id::text,
                    subscription_id::text,
                    subscription_revision::text,
                    offering_version_id::text,
                    price_version_id::text,
                    pg_catalog.encode(price_source_sha256, 'hex'),
                    state, cadence, currency::text,
                    currency_registry_version::text,
                    source_minor_units::text,
                    monthly_minor_units::text,
                    annual_minor_units::text
                ),
                pg_catalog.chr(30) ORDER BY subscription_id
            ), ''), 'UTF8'
        ))
    FROM platform.billing_revenue_projection AS projection
    WHERE projection.authority_id = p_authority_id;
END;
$$;


ALTER FUNCTION platform.billing_revenue_projection_digest_v1(p_authority_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_revenue_projection_id_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_revenue_projection_id_v1(p_subscription_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    value text;
BEGIN
	IF p_subscription_id IS NULL THEN
		RAISE EXCEPTION USING ERRCODE = '22023',
			MESSAGE = 'billing revenue projection identity is invalid';
	END IF;
    value := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'billing-revenue-v1:' || p_subscription_id::text, 'UTF8'
    )), 'hex');
    RETURN (
        pg_catalog.substr(value, 1, 8) || '-' ||
        pg_catalog.substr(value, 9, 4) || '-5' ||
        pg_catalog.substr(value, 14, 3) || '-8' ||
        pg_catalog.substr(value, 18, 3) || '-' ||
        pg_catalog.substr(value, 21, 12)
    )::uuid;
END;
$$;


ALTER FUNCTION platform.billing_revenue_projection_id_v1(p_subscription_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_revenue_source_digest_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_revenue_source_digest_v1(p_authority_id uuid) RETURNS TABLE(row_count bigint, revision_ceiling bigint, canonical_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    RETURN QUERY
    WITH source_rows AS (
        SELECT
            subscription.id AS subscription_id,
            subscription.revision AS subscription_revision,
            pg_catalog.concat_ws(
                pg_catalog.chr(31),
                platform.billing_revenue_projection_id_v1(
                    subscription.id
                )::text,
                subscription.id::text,
                subscription.revision::text,
                subscription.offering_version_id::text,
                subscription.price_version_id::text,
                pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                    pg_catalog.concat_ws(
                        pg_catalog.chr(31), price.id::text,
                        subscription.offering_version_id::text,
                        price.cadence, price.minor_units::text,
                        price.currency::text,
                        price.currency_registry_version::text,
                        price.money_policy_version
                    ), 'UTF8'
                )), 'hex'),
                subscription.state, price.cadence,
                price.currency::text,
                price.currency_registry_version::text,
                price.minor_units::text,
                platform.billing_revenue_monthly_v1(
                    price.minor_units, price.cadence
                )::text,
                CASE WHEN price.cadence = 'monthly'
                    THEN (price.minor_units * 12)::text
                    ELSE price.minor_units::text
                END
            ) AS canonical_row
        FROM platform.billing_subscriptions AS subscription
        JOIN platform.billing_price_versions AS price
          ON price.id = subscription.price_version_id
         AND price.offering_version_id = subscription.offering_version_id
        WHERE subscription.state IN ('active', 'past_due')
          AND price.cadence IN ('monthly', 'yearly')
    )
    SELECT
        pg_catalog.count(*)::bigint,
        COALESCE(
            pg_catalog.max(subscription_revision), 0::bigint
        ),
        pg_catalog.sha256(pg_catalog.convert_to(
            COALESCE(pg_catalog.string_agg(
                canonical_row, pg_catalog.chr(30)
                ORDER BY subscription_id
            ), ''), 'UTF8'
        ))
    FROM source_rows;
END;
$$;


ALTER FUNCTION platform.billing_revenue_source_digest_v1(p_authority_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_saas_free_base_read_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_saas_free_base_read_v1() RETURNS TABLE(offering_version_id uuid, revision bigint, offering_sha256 text, effective_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='SaaS free base read denied';
    END IF;
    RETURN QUERY SELECT publication.offering_version_id,publication.revision,
        publication.offering_sha256,publication.effective_at
    FROM platform.billing_saas_free_base_publications AS publication
    WHERE publication.offering_key='saas_free_base_v1';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='SaaS free base publication is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.billing_saas_free_base_read_v1() OWNER TO harpy_owner;

--
-- Name: billing_select_active_campaign_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_select_active_campaign_v1(p_authority_id uuid, p_instant timestamp with time zone) RETURNS TABLE(campaign_id uuid, campaign_key text, campaign_version_id uuid, campaign_version bigint, campaign_priority integer, starts_at timestamp with time zone, ends_at timestamp with time zone, presentation_metadata jsonb, presentation_sha256 bytea, discount_version_id uuid, discount_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_instant IS NULL OR NOT pg_catalog.isfinite(p_instant) THEN
        RAISE EXCEPTION USING ERRCODE = '22007',
            MESSAGE = 'billing campaign selection instant is invalid';
    END IF;
    PERFORM platform.billing_assert_global_authority_v1(p_authority_id);
    RETURN QUERY
    WITH selected AS MATERIALIZED (
        SELECT root.id, root.campaign_key, version_row.id AS version_id,
               version_row.version, version_row.priority, version_row.starts_at,
               version_row.ends_at, version_row.presentation_metadata,
               version_row.presentation_sha256
        FROM platform.billing_campaigns AS root
        JOIN platform.billing_campaign_versions AS version_row
          ON version_row.authority_id = root.authority_id
         AND version_row.campaign_id = root.id
        WHERE root.authority_id = p_authority_id
          AND root.lifecycle = 'active'
          AND version_row.publication_state = 'published'
          AND version_row.available
          AND version_row.starts_at <= p_instant
          AND (version_row.ends_at IS NULL OR p_instant < version_row.ends_at)
          AND NOT EXISTS (
              SELECT 1
              FROM platform.billing_campaign_versions AS successor
              WHERE successor.authority_id = version_row.authority_id
                AND successor.superseded_version_id = version_row.id
          )
        ORDER BY root.created_at DESC, root.id ASC
        LIMIT 1
    )
    SELECT selected.id, selected.campaign_key, selected.version_id,
           selected.version, selected.priority, selected.starts_at,
           selected.ends_at, selected.presentation_metadata,
           selected.presentation_sha256, eligible.id, eligible.priority
    FROM selected
    LEFT JOIN LATERAL (
        SELECT discount_version.id, discount_version.priority
        FROM platform.billing_campaign_discounts AS binding
        JOIN platform.billing_discount_versions AS discount_version
          ON discount_version.authority_id = binding.authority_id
         AND discount_version.id = binding.discount_version_id
        JOIN platform.billing_discounts AS discount_root
          ON discount_root.authority_id = discount_version.authority_id
         AND discount_root.id = discount_version.discount_id
        WHERE binding.authority_id = p_authority_id
          AND binding.campaign_version_id = selected.version_id
          AND discount_root.lifecycle = 'active'
          AND discount_version.available
          AND discount_version.valid_start <= p_instant
          AND (discount_version.valid_end IS NULL
               OR p_instant < discount_version.valid_end)
        ORDER BY discount_version.priority ASC, discount_version.id ASC
    ) AS eligible ON true
    ORDER BY eligible.priority ASC, eligible.id ASC NULLS LAST;
END;
$$;


ALTER FUNCTION platform.billing_select_active_campaign_v1(p_authority_id uuid, p_instant timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_subscription_retention_eligible_v1(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_subscription_retention_eligible_v1(p_tenant_id uuid, p_subscription_id uuid, p_cutoff timestamp with time zone, p_now timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN NOT EXISTS (
        SELECT 1 FROM platform.billing_invoices AS invoice
        WHERE invoice.tenant_id = p_tenant_id
          AND invoice.subscription_id = p_subscription_id
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_entitlement_decisions AS decision
        WHERE decision.tenant_id = p_tenant_id
          AND decision.subscription_id = p_subscription_id
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_discount_redemptions AS redemption
        WHERE redemption.tenant_id = p_tenant_id
          AND redemption.subscription_id = p_subscription_id
          AND (redemption.relationship_ended_at IS NULL
              OR redemption.relationship_ended_at > p_cutoff)
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_subscription_changes AS change_row
        WHERE change_row.tenant_id = p_tenant_id
          AND change_row.subscription_id = p_subscription_id
          AND (change_row.resolved_at IS NULL OR change_row.resolved_at > p_cutoff)
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_subscription_overrides AS override_row
        WHERE override_row.tenant_id = p_tenant_id
          AND override_row.subscription_id = p_subscription_id
          AND (override_row.effective_end IS NULL
              OR override_row.effective_end > p_cutoff)
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_subscription_operations AS operation_row
        WHERE operation_row.tenant_id = p_tenant_id
          AND operation_row.subscription_id = p_subscription_id
          AND operation_row.completed_at > p_cutoff
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_subscription_audit AS audit_row
        WHERE audit_row.tenant_id = p_tenant_id
          AND audit_row.subscription_id = p_subscription_id
          AND audit_row.occurred_at > p_cutoff
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_subscription_boundary_jobs AS job_row
        WHERE job_row.tenant_id = p_tenant_id
          AND job_row.subscription_id = p_subscription_id
          AND job_row.run_at > p_cutoff
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_subscription_boundary_evidence AS evidence
        WHERE evidence.tenant_id = p_tenant_id
          AND evidence.subscription_id = p_subscription_id
          AND evidence.recorded_at > p_cutoff
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_trial_claims AS trial_claim
        WHERE trial_claim.tenant_id = p_tenant_id
          AND trial_claim.subscription_id = p_subscription_id
          AND trial_claim.claimed_at > p_cutoff
    ) AND NOT EXISTS (
        SELECT 1
        FROM platform.billing_provider_objects AS object_row
        JOIN platform.billing_provider_events AS event_row
          ON event_row.tenant_id = object_row.tenant_id
         AND event_row.provider_object_mapping_id = object_row.id
        WHERE object_row.tenant_id = p_tenant_id
          AND object_row.subscription_id = p_subscription_id
          AND event_row.occurred_at > p_cutoff
    ) AND NOT EXISTS (
        SELECT 1
        FROM platform.billing_provider_objects AS object_row
        JOIN platform.billing_webhook_receipts AS receipt
          ON receipt.tenant_id = object_row.tenant_id
         AND receipt.provider_object_mapping_id = object_row.id
        WHERE object_row.tenant_id = p_tenant_id
          AND object_row.subscription_id = p_subscription_id
          AND (receipt.retain_until > p_now
              OR receipt.processor_state IN ('received', 'processing'))
    ) AND NOT EXISTS (
        SELECT 1 FROM platform.billing_provider_commands AS command_row
        WHERE command_row.tenant_id = p_tenant_id
          AND command_row.subscription_id = p_subscription_id
          AND (command_row.completed_at IS NULL
              OR command_row.completed_at > p_cutoff)
    ) AND NOT EXISTS (
        SELECT 1
        FROM platform.billing_provider_objects AS object_row
        JOIN platform.billing_provider_commands AS command_row
          ON command_row.tenant_id = object_row.tenant_id
         AND command_row.provider_object_mapping_id = object_row.id
        WHERE object_row.tenant_id = p_tenant_id
          AND object_row.subscription_id = p_subscription_id
          AND (command_row.completed_at IS NULL
              OR command_row.completed_at > p_cutoff)
    );
END;
$$;


ALTER FUNCTION platform.billing_subscription_retention_eligible_v1(p_tenant_id uuid, p_subscription_id uuid, p_cutoff timestamp with time zone, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: billing_subscription_snapshot_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_subscription_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid) RETURNS SETOF record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
WITH runtime_guard AS MATERIALIZED (
    SELECT 1
    WHERE SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime'
      AND CURRENT_USER IS NOT DISTINCT FROM 'harpy_owner'
      AND p_authority_id IS NOT DISTINCT FROM
          platform.billing_resolve_current_tenant_authority_v1(p_tenant_id)
), global_authority AS MATERIALIZED (
    SELECT authority.authority_id, authority.scope_id
    FROM platform.billing_global_authorities AS authority
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind = authority.scope_kind
     AND group_row.scope_id = authority.scope_id
     AND group_row.group_id = authority.authority_group_id
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind = authority.scope_kind
     AND domain_row.scope_id = authority.scope_id
     AND domain_row.domain = authority.authority_domain
    WHERE authority.scope_kind = 'global'
      AND authority.scope_id = (
          SELECT identity.environment_id FROM platform.environment_identity AS identity
      )
      AND authority.authority_group_id = 'billing'
      AND authority.authority_domain = 'billing'
      AND authority.authority_group_generation = group_row.generation
      AND authority.authority_domain_generation = domain_row.generation
      AND group_row.writer = 'v2' AND group_row.state = 'v2'
      AND domain_row.writer = 'v2' AND domain_row.state = 'v2'
), candidates AS MATERIALIZED (
    SELECT subscription.*, pg_catalog.count(*) OVER () AS candidate_count
    FROM runtime_guard
    CROSS JOIN platform.billing_subscriptions AS subscription
    WHERE subscription.authority_id = p_authority_id
      AND subscription.tenant_id = p_tenant_id
      AND subscription.state IN ('trialing', 'active', 'past_due')
), chosen AS (
    SELECT * FROM candidates ORDER BY updated_at DESC, id ASC LIMIT 1
)
SELECT chosen.candidate_count, chosen.id,
       COALESCE(subscription_alias.legacy_id, chosen.id),
       chosen.tenant_id,
       COALESCE(offering_alias.legacy_id, root.id),
       chosen.provider_account_id, chosen.offering_version_id,
       chosen.price_version_id, provider.provider_key, chosen.state,
       chosen.period_start, chosen.period_end, chosen.trial_ends_at,
       chosen.grace_ends_at, chosen.cancel_at_period_end, chosen.cancel_at,
       COALESCE(wire.trial_started_at,
           CASE WHEN chosen.state = 'trialing' THEN chosen.period_start END),
       wire.cancelled_at, wire.cancellation_reason,
       effective.effective_minor_units, effective.effective_currency,
       effective.effective_registry_version,
       chosen.revision, chosen.created_at,
       CASE WHEN wire.source_updated_at IS NULL
                 OR chosen.updated_at >= wire.source_updated_at
            THEN chosen.updated_at ELSE wire.source_updated_at END,
       price.id IS NOT NULL,
       root.id IS NOT NULL AND version_row.id IS NOT NULL
         AND version_row.publication_state = 'published',
       CASE WHEN root.id IS NULL OR version_row.id IS NULL THEN NULL ELSE
         pg_catalog.jsonb_build_object(
           'ID', root.id, 'Key', root.offering_key, 'Revision', root.revision,
           'VersionID', version_row.id, 'Version', version_row.version,
           'State', root.lifecycle, 'Public', version_row.is_public,
           'Name', COALESCE(version_row.presentation_metadata ->> 'name', ''),
           'Description', COALESCE(version_row.presentation_metadata ->> 'description', ''),
           'SortOrder', COALESCE((version_row.presentation_metadata ->> 'sort_order')::integer, 0),
           'HighlightLabel', COALESCE(version_row.presentation_metadata ->> 'highlight_label', ''),
           'Color', COALESCE(version_row.presentation_metadata ->> 'color', ''),
           'BillingInterval', COALESCE(
               version_row.presentation_metadata ->> 'billing_interval', 'monthly'),
           'Base', version_row.is_base, 'TrialDays', version_row.trial_days,
           'GraceDays', version_row.grace_days,
           'ExpectedPriceCount', version_row.expected_price_count,
           'ExpectedGrantCount', version_row.expected_grant_count,
           'EffectiveStart', version_row.effective_start,
           'EffectiveEnd', version_row.effective_end,
           'CreatedAt', root.created_at, 'UpdatedAt', version_row.published_at,
           'Prices', COALESCE((
             SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'ID', child.id, 'Cadence', child.cadence,
               'MinorUnits', child.minor_units,
               'Currency', pg_catalog.btrim(child.currency::text),
               'CurrencyRegistryVersion', child.currency_registry_version
             ) ORDER BY child.cadence, child.currency, child.id)
             FROM platform.billing_price_versions AS child
             WHERE child.authority_id = global_authority.authority_id
               AND child.offering_version_id = version_row.id
           ), '[]'::jsonb),
           'Entitlements', COALESCE((
             SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'Key', definition.entitlement_key, 'Kind', grant_row.value_type,
               'Boolean', grant_row.boolean_value, 'Integer', grant_row.integer_value,
               'Unlimited', grant_row.unlimited
             ) ORDER BY definition.entitlement_key, definition.id)
             FROM platform.billing_offering_entitlements AS grant_row
             JOIN platform.billing_entitlement_definitions AS definition
               ON definition.authority_id = grant_row.authority_id
              AND definition.id = grant_row.entitlement_definition_id
             WHERE grant_row.authority_id = global_authority.authority_id
               AND grant_row.offering_version_id = version_row.id
           ), '[]'::jsonb)
         ) END
FROM chosen
JOIN platform.billing_effective_subscription_price_snapshot_read_v1(
  chosen.authority_id, chosen.tenant_id, chosen.id, CURRENT_TIMESTAMP
) AS effective ON true
LEFT JOIN global_authority ON true
LEFT JOIN platform.billing_offering_versions AS version_row
  ON version_row.authority_id = global_authority.authority_id
 AND version_row.id = chosen.offering_version_id
LEFT JOIN platform.billing_offerings AS root
  ON root.authority_id = global_authority.authority_id
 AND root.id = version_row.offering_id
LEFT JOIN platform.billing_v1_subscription_wire_archive AS wire
  ON wire.authority_id = chosen.authority_id
 AND wire.tenant_id = chosen.tenant_id AND wire.subscription_id = chosen.id
LEFT JOIN platform.billing_legacy_identity_alias_v1 AS subscription_alias
  ON subscription_alias.authority_id = chosen.authority_id
 AND subscription_alias.scope_kind = 'tenant'
 AND subscription_alias.scope_id = chosen.tenant_id
 AND subscription_alias.record_kind = 'subscription'
 AND subscription_alias.canonical_id = chosen.id
LEFT JOIN platform.billing_legacy_identity_alias_v1 AS offering_alias
  ON offering_alias.authority_id = global_authority.authority_id
 AND offering_alias.scope_kind = 'global'
 AND offering_alias.scope_id = global_authority.scope_id
 AND offering_alias.record_kind = 'offering'
 AND offering_alias.canonical_id = root.id
LEFT JOIN platform.billing_provider_accounts AS provider
  ON provider.id = chosen.provider_account_id
LEFT JOIN platform.billing_price_versions AS price
  ON price.authority_id = global_authority.authority_id
 AND price.id = chosen.price_version_id
 AND price.offering_version_id = chosen.offering_version_id;
END;
$$;


ALTER FUNCTION platform.billing_subscription_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_usage_context_snapshot_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_usage_context_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid) RETURNS SETOF record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
WITH runtime_guard AS MATERIALIZED (
    SELECT 1
    WHERE SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime'
      AND CURRENT_USER IS NOT DISTINCT FROM 'harpy_owner'
      AND p_authority_id IS NOT DISTINCT FROM
          platform.billing_resolve_current_tenant_authority_v1(p_tenant_id)
), base_candidates AS MATERIALIZED (
    SELECT assignment.offering_version_id
    FROM runtime_guard
    CROSS JOIN platform.billing_tenant_base_offerings AS assignment
    WHERE assignment.authority_id = p_authority_id
      AND assignment.tenant_id = p_tenant_id
      AND assignment.effective_start <= pg_catalog.transaction_timestamp()
      AND (assignment.effective_end IS NULL
           OR assignment.effective_end > pg_catalog.transaction_timestamp())
), subscription_candidates AS MATERIALIZED (
    SELECT subscription.id, subscription.offering_version_id
    FROM runtime_guard
    CROSS JOIN platform.billing_subscriptions AS subscription
    WHERE subscription.authority_id = p_authority_id
      AND subscription.tenant_id = p_tenant_id
      AND subscription.period_start <= pg_catalog.transaction_timestamp()
      AND (
          (subscription.state = 'trialing'
            AND pg_catalog.transaction_timestamp() < subscription.trial_ends_at)
          OR (subscription.state = 'active'
            AND pg_catalog.transaction_timestamp() < subscription.period_end)
          OR (subscription.state = 'past_due'
            AND pg_catalog.transaction_timestamp() < subscription.grace_ends_at)
      )
)
SELECT
    (SELECT pg_catalog.count(*) FROM base_candidates),
    (SELECT offering_version_id::text FROM base_candidates
     ORDER BY offering_version_id LIMIT 1),
    (SELECT pg_catalog.count(*) FROM subscription_candidates),
    (SELECT id::text FROM subscription_candidates ORDER BY id LIMIT 1),
    (SELECT offering_version_id::text FROM subscription_candidates
     ORDER BY id LIMIT 1);
END;
$$;


ALTER FUNCTION platform.billing_usage_context_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_usage_snapshot_read_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_usage_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid, p_base_offering_version_id uuid, p_subscription_id uuid, p_subscription_offering_version_id uuid) RETURNS SETOF record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
WITH runtime_guard AS MATERIALIZED (
    SELECT 1
    WHERE SESSION_USER IS NOT DISTINCT FROM 'harpy_v2_runtime'
      AND CURRENT_USER IS NOT DISTINCT FROM 'harpy_owner'
      AND p_authority_id IS NOT DISTINCT FROM
          platform.billing_resolve_current_tenant_authority_v1(p_tenant_id)
), periods AS MATERIALIZED (
    SELECT period.*, total.committed_total, total.reserved_total,
           total.gauge_total, total.revision AS total_revision,
           total.updated_at,
           pg_catalog.count(*) OVER (
               PARTITION BY period.entitlement_key
           ) AS period_count
    FROM runtime_guard
    CROSS JOIN platform.billing_meter_periods AS period
    JOIN platform.billing_usage_totals AS total
      ON total.authority_id = period.authority_id
     AND total.tenant_id = period.tenant_id
     AND total.meter_period_id = period.id
    WHERE period.authority_id = p_authority_id
      AND period.tenant_id = p_tenant_id
      AND period.state = 'open'
      AND period.period_start <= pg_catalog.transaction_timestamp()
      AND period.period_end > pg_catalog.transaction_timestamp()
)
SELECT period.period_count,
       COALESCE(override_row.override_count, 0::bigint),
       period.id, period.entitlement_key, definition.value_type,
       definition.meter_kind, definition.reset_policy,
       definition.enforcement, definition.unlimited_allowed,
       period.period_start, period.period_end, period.revision,
       period.committed_total, period.reserved_total, period.gauge_total,
       period.total_revision, period.updated_at,
       CASE
         WHEN override_row.id IS NOT NULL THEN override_row.integer_value
         WHEN purchased.entitlement_definition_id IS NOT NULL
           THEN purchased.integer_value
         ELSE base_grant.integer_value
       END,
       CASE
         WHEN override_row.id IS NOT NULL THEN override_row.unlimited
         WHEN purchased.entitlement_definition_id IS NOT NULL
           THEN purchased.unlimited
         ELSE base_grant.unlimited
       END,
       (override_row.id IS NOT NULL
        OR purchased.entitlement_definition_id IS NOT NULL
        OR base_grant.entitlement_definition_id IS NOT NULL)
FROM periods AS period
JOIN platform.billing_entitlement_definitions AS definition
  ON definition.id = period.entitlement_definition_id
 AND definition.entitlement_key = period.entitlement_key
 AND definition.value_type = 'integer'
 AND definition.meter_kind = period.meter_kind
LEFT JOIN platform.billing_offering_entitlements AS base_grant
  ON base_grant.offering_version_id = p_base_offering_version_id
 AND base_grant.entitlement_definition_id = definition.id
LEFT JOIN platform.billing_offering_entitlements AS purchased
  ON purchased.offering_version_id = p_subscription_offering_version_id
 AND purchased.entitlement_definition_id = definition.id
LEFT JOIN LATERAL (
    SELECT candidate.*, pg_catalog.count(*) OVER () AS override_count
    FROM platform.billing_subscription_overrides AS candidate
    WHERE p_subscription_id IS NOT NULL
      AND candidate.authority_id = p_authority_id
      AND candidate.tenant_id = p_tenant_id
      AND candidate.subscription_id = p_subscription_id
      AND candidate.entitlement_definition_id = definition.id
      AND candidate.effective_start <= pg_catalog.transaction_timestamp()
      AND (candidate.effective_end IS NULL
           OR candidate.effective_end > pg_catalog.transaction_timestamp())
    ORDER BY candidate.effective_start DESC, candidate.id
    LIMIT 1
) AS override_row ON true
ORDER BY period.entitlement_key COLLATE "C", period.id;
END;
$$;


ALTER FUNCTION platform.billing_usage_snapshot_read_v1(p_authority_id uuid, p_tenant_id uuid, p_base_offering_version_id uuid, p_subscription_id uuid, p_subscription_offering_version_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_batch_assert_v1(jsonb, uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_expected_scope text, p_expected_checkpoint text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_change_count integer;
    v_group text;
BEGIN
    v_change_count := pg_catalog.jsonb_array_length(p_batch->'changes');
    v_group := CASE p_expected_scope
        WHEN 'global' THEN 'billing' ELSE 'billing' END;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption evidence principal denied';
    END IF;
    IF p_expected_scope NOT IN ('global', 'tenant') OR
       p_scope_kind IS DISTINCT FROM p_expected_scope OR
       p_checkpoint_key IS DISTINCT FROM p_expected_checkpoint OR
       p_relation_ordinal IS DISTINCT FROM 1::smallint OR
       p_scope_id IS NULL OR p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_checkpoint_state NOT IN ('initial_copy','delta','complete') OR
       p_snapshot_name IS NULL OR p_snapshot_name = '' OR
       p_snapshot_lsn > p_commit_lsn OR p_commit_lsn > p_received_lsn OR
       (p_checkpoint_state = 'complete') IS DISTINCT FROM
           (p_final_lsn IS NOT NULL) OR
       (p_final_lsn IS NOT NULL AND p_commit_lsn < p_final_lsn) OR
       (v_change_count = 0 AND (
           p_checkpoint_state <> 'complete' OR
           p_final_lsn IS DISTINCT FROM p_commit_lsn
       )) OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_operations AS operation
           WHERE operation.operation_id = p_operation_id
             AND operation.run_id = p_run_id
             AND operation.scope_kind = p_scope_kind
             AND operation.scope_id = p_scope_id
             AND operation.group_id = v_group
             AND operation.domain = 'billing'
             AND operation.state IN ('copying','shadow','quiescing')
       ) OR NOT EXISTS (
           SELECT 1
           FROM platform.cutover_groups AS group_row
           JOIN platform.domain_cutovers AS billing_row
             ON billing_row.scope_kind = group_row.scope_kind
            AND billing_row.scope_id = group_row.scope_id
            AND billing_row.domain = 'billing'
           WHERE group_row.scope_kind = p_scope_kind
             AND group_row.scope_id = p_scope_id
             AND group_row.group_id = v_group
             AND group_row.state IN ('shadow','quiescing')
             AND billing_row.state IN ('shadow','quiescing')
       ) OR (p_expected_scope = 'global' AND NOT EXISTS (
           SELECT 1 FROM platform.environment_identity AS identity
           WHERE identity.environment_id = p_scope_id
       )) OR (p_expected_scope = 'tenant' AND (
           NOT EXISTS (
               SELECT 1 FROM platform.tenants AS tenant
               WHERE tenant.id = p_scope_id AND tenant.deleted_at IS NULL
           ) OR (SELECT pg_catalog.string_agg(member.domain, ',' ORDER BY member.ordinal)
               FROM platform.cutover_group_members AS member
               WHERE member.scope_kind = 'tenant'
                 AND member.scope_id = p_scope_id
                 AND member.group_id = 'billing')
              IS DISTINCT FROM 'billing'
       )) OR (p_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (p_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       p_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (p_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (p_batch->>'relation_ordinal')::smallint IS DISTINCT FROM
           p_relation_ordinal OR
       p_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key OR
       p_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       p_batch->'last_key' IS DISTINCT FROM p_last_key OR
       p_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM
           p_snapshot_name OR
       (p_batch->'source_position'->>'snapshot_lsn')::pg_lsn IS DISTINCT FROM
           p_snapshot_lsn OR
       (p_batch->'source_position'->>'received_lsn')::pg_lsn IS DISTINCT FROM
           p_received_lsn OR
       (p_batch->'source_position'->>'commit_lsn')::pg_lsn IS DISTINCT FROM
           p_commit_lsn OR
       (p_batch->'source_position'->>'final_lsn')::pg_lsn IS DISTINCT FROM
           p_final_lsn OR
       (p_batch->'source_position'->>'source_xid')::xid8 IS DISTINCT FROM
           p_source_xid OR
       (p_batch->'source_position'->>'batch_ordinal')::integer IS DISTINCT FROM
           p_batch_ordinal THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption batch evidence differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.billing_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_expected_scope text, p_expected_checkpoint text) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_batch_decode_v1(bytea, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_actual_bytes bigint;
    v_change_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption batch principal denied';
    END IF;
    v_actual_bytes := pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_bytes OR
       v_actual_bytes NOT BETWEEN 2 AND 8388608 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes), 'hex')
           IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption batch digest is invalid';
    END IF;
    v_batch := pg_catalog.convert_from(p_change_batch_bytes, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_batch) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch) AS key)
       IS DISTINCT FROM ARRAY[
           'changes','checkpoint_key','checkpoint_state','last_key',
           'operation_id','relation_ordinal','run_id','scope_id',
           'scope_kind','source_position'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'source_position') AS key)
       IS DISTINCT FROM ARRAY[
           'batch_ordinal','commit_lsn','final_lsn','received_lsn',
           'snapshot_lsn','snapshot_name','source_xid'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_batch->'changes') > 1000 OR
       pg_catalog.jsonb_typeof(v_batch->'last_key') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'last_key') AS key)
       IS DISTINCT FROM ARRAY[
           'session_seal_receipt_id','session_seal_sha256'
       ]::text[] OR
       v_batch->'last_key'->>'session_seal_sha256' !~ '^[0-9a-f]{64}$' OR
       (v_batch->'last_key'->>'session_seal_receipt_id')::uuid =
           '00000000-0000-0000-0000-000000000000'::uuid THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption batch envelope is invalid';
    END IF;
    v_change_count := pg_catalog.jsonb_array_length(v_batch->'changes');
    IF (SELECT pg_catalog.count(DISTINCT change.value->'key')
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes') AS change(value))
       IS DISTINCT FROM v_change_count::bigint OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes')
             WITH ORDINALITY AS change(value, position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(change.value) AS key)
              IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
           OR (change.value->>'ordinal')::integer IS DISTINCT FROM
                change.position::integer
           OR change.value->>'kind' IS DISTINCT FROM 'insert'
           OR change.value->'before' <> 'null'::jsonb
           OR NOT platform.billing_v1_adoption_chunk_valid_v1(
                change.value->'key', change.value->'after'
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption batch change is invalid';
    END IF;
    RETURN v_batch;
END;
$_$;


ALTER FUNCTION platform.billing_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_catalog_fingerprint_v1(text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_catalog_fingerprint_v1(p_record_kind text, p_target_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF p_record_kind IS NOT DISTINCT FROM 'offering' THEN
        SELECT pg_catalog.jsonb_build_object(
            'root', pg_catalog.to_jsonb(root_row),
            'version', pg_catalog.to_jsonb(version_row),
            'prices', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.to_jsonb(price_row) ORDER BY price_row.id
                )
                FROM platform.billing_price_versions AS price_row
                WHERE price_row.offering_version_id = version_row.id
            ), '[]'::jsonb),
            'grants', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.to_jsonb(grant_row)
                    ORDER BY grant_row.entitlement_definition_id
                )
                FROM platform.billing_offering_entitlements AS grant_row
                WHERE grant_row.offering_version_id = version_row.id
            ), '[]'::jsonb)
        ) INTO v_document
        FROM platform.billing_offerings AS root_row
        JOIN platform.billing_offering_versions AS version_row
          ON version_row.authority_id = root_row.authority_id
         AND version_row.offering_id = root_row.id
         AND version_row.version = 1
        WHERE root_row.id = p_target_id;
    ELSIF p_record_kind IS NOT DISTINCT FROM 'discount' THEN
        SELECT pg_catalog.jsonb_build_object(
            'root', pg_catalog.to_jsonb(root_row),
            'version', pg_catalog.to_jsonb(version_row),
            'offerings', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.to_jsonb(binding)
                    ORDER BY binding.offering_version_id
                )
                FROM platform.billing_discount_offerings AS binding
                WHERE binding.discount_version_id = version_row.id
            ), '[]'::jsonb)
        ) INTO v_document
        FROM platform.billing_discounts AS root_row
        JOIN platform.billing_discount_versions AS version_row
          ON version_row.authority_id = root_row.authority_id
         AND version_row.discount_id = root_row.id
         AND version_row.version = 1
        WHERE root_row.id = p_target_id;
    ELSIF p_record_kind IS NOT DISTINCT FROM 'campaign' THEN
        SELECT pg_catalog.jsonb_build_object(
            'root', pg_catalog.to_jsonb(root_row),
            'version', pg_catalog.to_jsonb(version_row),
            'discounts', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.to_jsonb(binding)
                    ORDER BY binding.discount_version_id
                )
                FROM platform.billing_campaign_discounts AS binding
                WHERE binding.campaign_version_id = version_row.id
            ), '[]'::jsonb)
        ) INTO v_document
        FROM platform.billing_campaigns AS root_row
        JOIN platform.billing_campaign_versions AS version_row
          ON version_row.authority_id = root_row.authority_id
         AND version_row.campaign_id = root_row.id
         AND version_row.version = 1
        WHERE root_row.id = p_target_id;
    ELSIF p_record_kind IS NOT DISTINCT FROM 'provider_account' THEN
        SELECT pg_catalog.to_jsonb(account)
        INTO v_document
        FROM platform.billing_provider_accounts AS account
        WHERE account.id = p_target_id;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 catalog fingerprint kind is invalid';
    END IF;
    IF v_document IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN pg_catalog.sha256(
        pg_catalog.convert_to(v_document::text, 'UTF8')
    );
END;
$$;


ALTER FUNCTION platform.billing_v1_adoption_catalog_fingerprint_v1(p_record_kind text, p_target_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_chunk_valid_v1(jsonb, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_chunk_valid_v1(p_key jsonb, p_after jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_bytes bytea;
BEGIN
    IF pg_catalog.jsonb_typeof(p_key) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_key) AS key)
       IS DISTINCT FROM ARRAY['chunk_ordinal']::text[] OR
       pg_catalog.jsonb_typeof(p_after) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_after) AS key)
       IS DISTINCT FROM ARRAY[
           'chunk_base64', 'chunk_count', 'chunk_ordinal', 'chunk_sha256'
       ]::text[] OR
       (p_after->>'chunk_ordinal')::integer IS DISTINCT FROM
           (p_key->>'chunk_ordinal')::integer OR
       (p_after->>'chunk_count')::integer NOT BETWEEN 1 AND 65536 OR
       (p_after->>'chunk_ordinal')::integer NOT BETWEEN 1 AND
           (p_after->>'chunk_count')::integer OR
       p_after->>'chunk_sha256' !~ '^[0-9a-f]{64}$' THEN
        RETURN false;
    END IF;
    v_bytes := pg_catalog.decode(p_after->>'chunk_base64', 'base64');
    RETURN pg_catalog.octet_length(v_bytes) BETWEEN 1 AND 6291456 AND
        pg_catalog.encode(pg_catalog.sha256(v_bytes), 'hex') =
            p_after->>'chunk_sha256';
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.billing_v1_adoption_chunk_valid_v1(p_key jsonb, p_after jsonb) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_fingerprint_v1(text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_fingerprint_v1(p_record_kind text, p_target_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_record_kind IN ('offering', 'campaign', 'discount', 'provider_account') THEN
        RETURN platform.billing_v1_adoption_catalog_fingerprint_v1(p_record_kind, p_target_id);
    END IF;
    RETURN platform.billing_v1_adoption_tenant_fingerprint_v1(p_record_kind, p_target_id);
END;
$$;


ALTER FUNCTION platform.billing_v1_adoption_fingerprint_v1(p_record_kind text, p_target_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_global_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_global_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_asserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global V1 adoption composite principal denied';
    END IF;
    v_batch := platform.billing_v1_adoption_batch_decode_v1(
        p_change_batch_bytes, p_batch_sha256, p_batch_bytes
    );
    v_asserted := platform.billing_v1_adoption_batch_assert_v1(
        v_batch, p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_name,
        p_snapshot_lsn, p_received_lsn, p_commit_lsn, p_final_lsn,
        p_source_xid, p_batch_ordinal, p_checkpoint_state, p_last_key,
        'global', 'catalog'
    );
    IF NOT v_asserted THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'billing global V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id, prepared.procedure_oid,
        prepared.procedure_signature, prepared.already_applied,
        prepared.applied_count, prepared.key_state_sha256,
        prepared.state_sha256
    INTO STRICT v_contract_id, v_procedure_oid, v_procedure_signature,
        v_already_applied, v_applied_count, v_key_sha, v_state_sha
    FROM platform.cutover_prepare_batch_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_batch_ordinal,
        p_commit_lsn, p_source_xid, p_batch_sha256,
        p_lease_manifest_sha256
    ) AS prepared;
    IF v_contract_id IS DISTINCT FROM 'billing.v1_adoption.global.v1' OR
       v_procedure_oid IS DISTINCT FROM
           'platform.billing_v1_adoption_global_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM
           'platform.billing_v1_adoption_global_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing global V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
        RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count, result.key_state_sha256, result.state_sha256
    INTO STRICT v_applied_count, v_key_sha, v_state_sha
    FROM platform.billing_v1_adoption_global_apply_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_lsn,
        p_received_lsn, p_commit_lsn, p_source_xid, p_batch_ordinal,
        v_batch, p_batch_sha256
    ) AS result;
    IF v_applied_count IS DISTINCT FROM
           pg_catalog.jsonb_array_length(v_batch->'changes') OR
       v_key_sha !~ '^[0-9a-f]{64}$' OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'billing global V1 adoption owner result differs';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key,
        p_snapshot_name, p_snapshot_lsn, p_received_lsn, p_commit_lsn,
        p_final_lsn, p_source_xid, p_batch_ordinal, p_checkpoint_state,
        p_last_key, p_batch_sha256, p_batch_bytes, v_applied_count,
        v_key_sha, v_state_sha
    );
    RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
END;
$_$;


ALTER FUNCTION platform.billing_v1_adoption_global_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_global_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_global_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_applied bigint;
    v_key_sha text;
    v_state_sha text;
    v_plan bytea;
    v_source_sha text;
    v_lease_manifest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'global' OR
       p_checkpoint_key IS DISTINCT FROM 'catalog' OR
       p_relation_ordinal IS DISTINCT FROM 1::smallint THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing global V1 adoption owner apply denied';
    END IF;
    SELECT operation.lease_manifest_sha256 INTO STRICT v_lease_manifest
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id
      AND operation.scope_kind = 'global' AND operation.scope_id = p_scope_id
      AND operation.group_id = 'billing' AND operation.domain = 'billing';
    SELECT staged.applied_count, staged.key_state_sha256,
        staged.state_sha256, staged.plan_bytes
    INTO STRICT v_applied, v_key_sha, v_state_sha, v_plan
    FROM platform.billing_v1_adoption_stage_plan_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_commit_lsn, p_source_xid,
        p_batch_ordinal, p_batch, p_batch_sha256, v_lease_manifest
    ) AS staged;
    IF v_plan IS NOT NULL THEN
        v_source_sha := platform.billing_v1_adoption_register_apply_v1(
            p_operation_id, p_run_id, p_scope_kind, p_scope_id, v_plan,
            p_batch->'last_key', p_batch_sha256, p_batch_ordinal,
            v_lease_manifest
        );
    END IF;
    IF p_batch->>'checkpoint_state' = 'complete' THEN
        IF v_plan IS NULL OR v_source_sha IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing global V1 adoption plan is incomplete';
        END IF;
        v_state_sha := platform.billing_v1_adoption_verify_rollback_v1(
            p_operation_id, p_run_id, v_source_sha
        );
    END IF;
    RETURN QUERY SELECT v_applied, v_key_sha, v_state_sha;
END;
$$;


ALTER FUNCTION platform.billing_v1_adoption_global_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_register_apply_v1(uuid, uuid, text, uuid, bytea, jsonb, text, integer, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_register_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_plan_bytes bytea, p_last_key jsonb, p_batch_sha256 text, p_batch_ordinal integer, p_lease_manifest_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_plan jsonb;
    v_evidence jsonb;
    v_evidence_bytes bytea;
    v_evidence_sha text;
    v_plan_sha text;
    v_authority_id uuid;
    v_lease_id uuid;
    v_expected_plan_sha text;
    v_cutover_generation bigint;
    v_state text;
    v_applied bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       p_lease_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption registration principal denied';
    END IF;
    SELECT operation.lease_id, operation.plan_sha256,
        operation.cutover_generation
    INTO STRICT v_lease_id, v_expected_plan_sha, v_cutover_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id
      AND operation.run_id = p_run_id
      AND operation.scope_kind = p_scope_kind
      AND operation.scope_id = p_scope_id
      AND operation.domain = 'billing'
      AND operation.lease_manifest_sha256 = p_lease_manifest_sha256
      AND operation.state IN ('copying','shadow','quiescing')
    FOR SHARE;
    v_plan_sha := pg_catalog.encode(pg_catalog.sha256(p_plan_bytes), 'hex');
    v_plan := pg_catalog.convert_from(p_plan_bytes, 'UTF8')::jsonb;
    IF v_plan_sha IS DISTINCT FROM v_expected_plan_sha OR
       v_plan->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (v_plan->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       v_plan->>'contract_version' IS DISTINCT FROM
           'harpy/billing-v1-adoption-plan/v1' OR
       (v_plan->>'eligible')::boolean IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 adoption compiled plan differs';
    END IF;
    SELECT run.* INTO v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_run.scope_kind IS DISTINCT FROM p_scope_kind OR
           v_run.scope_id IS DISTINCT FROM p_scope_id OR
           v_run.cutover_lease_id IS DISTINCT FROM v_lease_id OR
           v_run.cutover_lease_sha256 IS DISTINCT FROM
               pg_catalog.decode(p_lease_manifest_sha256, 'hex') OR
           v_run.plan_sha256 IS DISTINCT FROM pg_catalog.decode(v_plan_sha, 'hex') THEN
            RAISE EXCEPTION USING ERRCODE = '22000',
                MESSAGE = 'billing V1 adoption registered run differs';
        END IF;
        v_applied := platform.billing_apply_v1_adoption_v1(
            p_operation_id, p_run_id
        );
        RETURN pg_catalog.encode(v_run.source_sha256, 'hex');
    END IF;
    IF p_scope_kind = 'global' THEN
        SELECT authority.authority_id INTO STRICT v_authority_id
        FROM platform.billing_global_authorities AS authority
        JOIN platform.cutover_groups AS group_row
          ON group_row.scope_kind = authority.scope_kind
         AND group_row.scope_id = authority.scope_id
         AND group_row.group_id = authority.authority_group_id
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind = authority.scope_kind
         AND domain_row.scope_id = authority.scope_id
         AND domain_row.domain = authority.authority_domain
        WHERE authority.scope_id = p_scope_id
          AND authority.authority_group_generation = group_row.generation
          AND authority.authority_domain_generation = domain_row.generation
          AND domain_row.generation = v_cutover_generation;
    ELSE
        SELECT authority.authority_id INTO STRICT v_authority_id
        FROM platform.billing_tenant_authorities AS authority
        JOIN platform.cutover_groups AS group_row
          ON group_row.scope_kind = authority.scope_kind
         AND group_row.scope_id = authority.scope_id
         AND group_row.group_id = authority.authority_group_id
        JOIN platform.domain_cutovers AS billing_row
          ON billing_row.scope_kind = authority.scope_kind
         AND billing_row.scope_id = authority.scope_id
         AND billing_row.domain = authority.billing_domain
        WHERE authority.tenant_id = p_scope_id
          AND authority.authority_group_generation = group_row.generation
          AND authority.billing_generation = billing_row.generation
          AND billing_row.generation = v_cutover_generation;
    END IF;
    v_evidence := pg_catalog.jsonb_build_object(
        'batch_sha256', p_batch_sha256,
        'contract_version', 'harpy/billing-v1-cutover-evidence/v1',
        'evidence_generation', p_batch_ordinal,
        'lease_id', v_lease_id,
        'lease_manifest_sha256', p_lease_manifest_sha256,
        'operation_id', p_operation_id,
        'plan_sha256', v_plan_sha,
        'run_id', p_run_id,
        'scope_id', p_scope_id,
        'scope_kind', p_scope_kind,
        'session_seal_receipt_id',
            (p_last_key->>'session_seal_receipt_id')::uuid,
        'session_seal_sha256', p_last_key->>'session_seal_sha256'
    );
    v_evidence_bytes := pg_catalog.convert_to(v_evidence::text, 'UTF8');
    v_evidence_sha := pg_catalog.encode(
        pg_catalog.sha256(v_evidence_bytes), 'hex'
    );
    v_state := platform.billing_register_v1_adoption_v1(
        p_operation_id, p_run_id, v_authority_id, p_plan_bytes, v_plan_sha,
        v_evidence_bytes, v_evidence_sha
    );
    IF v_state IS DISTINCT FROM 'planned' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing V1 adoption registration was not planned';
    END IF;
    v_applied := platform.billing_apply_v1_adoption_v1(
        p_operation_id, p_run_id
    );
    IF v_applied < 0 THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'billing V1 adoption apply count is invalid';
    END IF;
    RETURN v_plan->>'source_sha256';
END;
$_$;


ALTER FUNCTION platform.billing_v1_adoption_register_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_plan_bytes bytea, p_last_key jsonb, p_batch_sha256 text, p_batch_ordinal integer, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_stage_plan_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, xid8, integer, jsonb, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_stage_plan_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_batch jsonb, p_batch_sha256 text, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text, plan_bytes bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_change jsonb;
    v_after jsonb;
    v_chunk bytea;
    v_applied bigint;
    v_count bigint;
    v_expected integer;
    v_min integer;
    v_max integer;
    v_distinct_counts bigint;
    v_digest text;
    v_plan bytea;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    v_applied := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       p_lease_manifest_sha256 !~ '^[0-9a-f]{64}$' OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_operations AS operation
           WHERE operation.operation_id = p_operation_id
             AND operation.run_id = p_run_id
             AND operation.scope_kind = p_scope_kind
             AND operation.scope_id = p_scope_id
             AND operation.lease_manifest_sha256 = p_lease_manifest_sha256
             AND operation.state IN ('copying','shadow','quiescing')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption plan staging denied';
    END IF;
    FOR v_change IN
        SELECT value
        FROM pg_catalog.jsonb_array_elements(p_batch->'changes')
             WITH ORDINALITY AS item(value, position)
        ORDER BY position
    LOOP
        v_after := v_change->'after';
        v_chunk := pg_catalog.decode(v_after->>'chunk_base64', 'base64');
        INSERT INTO platform.billing_v1_adoption_plan_chunks (
            operation_id, run_id, scope_kind, scope_id,
            chunk_ordinal, chunk_count, chunk_sha256, chunk_bytes,
            source_xid, commit_lsn, batch_ordinal, change_ordinal, created_at
        ) VALUES (
            p_operation_id, p_run_id, p_scope_kind, p_scope_id,
            (v_after->>'chunk_ordinal')::integer,
            (v_after->>'chunk_count')::integer,
            pg_catalog.decode(v_after->>'chunk_sha256', 'hex'), v_chunk,
            p_source_xid, p_commit_lsn, p_batch_ordinal,
            (v_change->>'ordinal')::integer, v_now
        );
        v_applied := v_applied + 1;
        INSERT INTO platform.applied_change_receipts (
            receipt_id, operation_id, run_id, manifest_sha256,
            source_xid, source_commit_lsn, relation_ordinal, change_ordinal,
            checkpoint_key, mutation_kind, mutation_sha256, applied_at
        ) VALUES (
            pg_catalog.gen_random_uuid(), p_operation_id, p_run_id,
            p_lease_manifest_sha256, p_source_xid, p_commit_lsn,
            p_relation_ordinal,
            (((p_batch_ordinal - 1)::bigint * 1000) +
                (v_change->>'ordinal')::integer)::integer,
            p_checkpoint_key, 'insert',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                p_batch_sha256 || ':' || (v_change->>'ordinal'), 'UTF8'
            )), 'hex'), v_now
        );
    END LOOP;
    SELECT pg_catalog.count(*), pg_catalog.min(chunk.chunk_count),
        pg_catalog.min(chunk.chunk_ordinal), pg_catalog.max(chunk.chunk_ordinal),
        pg_catalog.count(DISTINCT chunk.chunk_count)
    INTO v_count, v_expected, v_min, v_max, v_distinct_counts
    FROM platform.billing_v1_adoption_plan_chunks AS chunk
    WHERE chunk.operation_id = p_operation_id AND chunk.run_id = p_run_id
      AND chunk.scope_kind = p_scope_kind AND chunk.scope_id = p_scope_id;
    IF v_count > 0 AND v_distinct_counts IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'billing V1 adoption chunk cardinality differs';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(
            chunk.chunk_ordinal::text || ':' ||
            pg_catalog.encode(chunk.chunk_sha256, 'hex'),
            ',' ORDER BY chunk.chunk_ordinal
        ), ''), 'UTF8'
    )), 'hex')
    INTO v_digest
    FROM platform.billing_v1_adoption_plan_chunks AS chunk
    WHERE chunk.operation_id = p_operation_id AND chunk.run_id = p_run_id;
    IF v_count = v_expected AND v_min = 1 AND v_max = v_expected THEN
        SELECT pg_catalog.decode(pg_catalog.string_agg(
            pg_catalog.encode(chunk.chunk_bytes, 'hex'),
            '' ORDER BY chunk.chunk_ordinal
        ), 'hex')
        INTO v_plan
        FROM platform.billing_v1_adoption_plan_chunks AS chunk
        WHERE chunk.operation_id = p_operation_id AND chunk.run_id = p_run_id;
    END IF;
    RETURN QUERY SELECT v_applied, v_digest, v_digest, v_plan;
END;
$_$;


ALTER FUNCTION platform.billing_v1_adoption_stage_plan_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_batch jsonb, p_batch_sha256 text, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_tenant_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_tenant_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_asserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant V1 adoption composite principal denied';
    END IF;
    v_batch := platform.billing_v1_adoption_batch_decode_v1(
        p_change_batch_bytes, p_batch_sha256, p_batch_bytes
    );
    v_asserted := platform.billing_v1_adoption_batch_assert_v1(
        v_batch, p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_name,
        p_snapshot_lsn, p_received_lsn, p_commit_lsn, p_final_lsn,
        p_source_xid, p_batch_ordinal, p_checkpoint_state, p_last_key,
        'tenant', 'billing'
    );
    IF NOT v_asserted THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'billing tenant V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id, prepared.procedure_oid,
        prepared.procedure_signature, prepared.already_applied,
        prepared.applied_count, prepared.key_state_sha256,
        prepared.state_sha256
    INTO STRICT v_contract_id, v_procedure_oid, v_procedure_signature,
        v_already_applied, v_applied_count, v_key_sha, v_state_sha
    FROM platform.cutover_prepare_batch_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_batch_ordinal,
        p_commit_lsn, p_source_xid, p_batch_sha256,
        p_lease_manifest_sha256
    ) AS prepared;
    IF v_contract_id IS DISTINCT FROM 'billing.v1_adoption.tenant.v1' OR
       v_procedure_oid IS DISTINCT FROM
           'platform.billing_v1_adoption_tenant_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM
           'platform.billing_v1_adoption_tenant_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing tenant V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
        RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count, result.key_state_sha256, result.state_sha256
    INTO STRICT v_applied_count, v_key_sha, v_state_sha
    FROM platform.billing_v1_adoption_tenant_apply_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_lsn,
        p_received_lsn, p_commit_lsn, p_source_xid, p_batch_ordinal,
        v_batch, p_batch_sha256
    ) AS result;
    IF v_applied_count IS DISTINCT FROM
           pg_catalog.jsonb_array_length(v_batch->'changes') OR
       v_key_sha !~ '^[0-9a-f]{64}$' OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'billing tenant V1 adoption owner result differs';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key,
        p_snapshot_name, p_snapshot_lsn, p_received_lsn, p_commit_lsn,
        p_final_lsn, p_source_xid, p_batch_ordinal, p_checkpoint_state,
        p_last_key, p_batch_sha256, p_batch_bytes, v_applied_count,
        v_key_sha, v_state_sha
    );
    RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
END;
$_$;


ALTER FUNCTION platform.billing_v1_adoption_tenant_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_tenant_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_tenant_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_applied bigint;
    v_key_sha text;
    v_state_sha text;
    v_plan bytea;
    v_source_sha text;
    v_lease_manifest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR
       p_checkpoint_key IS DISTINCT FROM 'billing' OR
       p_relation_ordinal IS DISTINCT FROM 1::smallint THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing tenant V1 adoption owner apply denied';
    END IF;
    SELECT operation.lease_manifest_sha256 INTO STRICT v_lease_manifest
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id
      AND operation.scope_kind = 'tenant' AND operation.scope_id = p_scope_id
      AND operation.group_id = 'billing' AND operation.domain = 'billing';
    SELECT staged.applied_count, staged.key_state_sha256,
        staged.state_sha256, staged.plan_bytes
    INTO STRICT v_applied, v_key_sha, v_state_sha, v_plan
    FROM platform.billing_v1_adoption_stage_plan_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_commit_lsn, p_source_xid,
        p_batch_ordinal, p_batch, p_batch_sha256, v_lease_manifest
    ) AS staged;
    IF v_plan IS NOT NULL THEN
        v_source_sha := platform.billing_v1_adoption_register_apply_v1(
            p_operation_id, p_run_id, p_scope_kind, p_scope_id, v_plan,
            p_batch->'last_key', p_batch_sha256, p_batch_ordinal,
            v_lease_manifest
        );
    END IF;
    IF p_batch->>'checkpoint_state' = 'complete' THEN
        IF v_plan IS NULL OR v_source_sha IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'billing tenant V1 adoption plan is incomplete';
        END IF;
        v_state_sha := platform.billing_v1_adoption_verify_rollback_v1(
            p_operation_id, p_run_id, v_source_sha
        );
    END IF;
    RETURN QUERY SELECT v_applied, v_key_sha, v_state_sha;
END;
$$;


ALTER FUNCTION platform.billing_v1_adoption_tenant_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_tenant_fingerprint_v1(text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_tenant_fingerprint_v1(p_record_kind text, p_target_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF p_record_kind IS NOT DISTINCT FROM 'base_assignment' THEN
        SELECT pg_catalog.to_jsonb(row_value) INTO v_document
        FROM platform.billing_tenant_base_offerings AS row_value
        WHERE row_value.id = p_target_id;
    ELSIF p_record_kind IS NOT DISTINCT FROM 'subscription' THEN
        SELECT pg_catalog.jsonb_build_object(
            'subscription', pg_catalog.to_jsonb(row_value),
            'legacy_wire', pg_catalog.to_jsonb(wire_row)
        ) INTO v_document
        FROM platform.billing_subscriptions AS row_value
        LEFT JOIN platform.billing_v1_subscription_wire_archive AS wire_row
          ON wire_row.subscription_id = row_value.id
        WHERE row_value.id = p_target_id;
    ELSIF p_record_kind IS NOT DISTINCT FROM 'redemption' THEN
        SELECT pg_catalog.to_jsonb(row_value) INTO v_document
        FROM platform.billing_discount_redemptions AS row_value
        WHERE row_value.id = p_target_id;
    ELSIF p_record_kind IN ('usage_opening', 'gauge_opening') THEN
        SELECT pg_catalog.jsonb_build_object(
            'period', pg_catalog.to_jsonb(period_row),
            'total', pg_catalog.to_jsonb(total_row),
            'entries', COALESCE((
                SELECT pg_catalog.jsonb_agg(
                    pg_catalog.to_jsonb(entry_row) ORDER BY entry_row.id
                )
                FROM platform.billing_usage_entries AS entry_row
                WHERE entry_row.meter_period_id = period_row.id
                  AND entry_row.entry_kind = 'opening'
            ), '[]'::jsonb),
            'evidence', pg_catalog.to_jsonb(evidence_row)
        ) INTO v_document
        FROM platform.billing_meter_periods AS period_row
        JOIN platform.billing_usage_totals AS total_row
          ON total_row.meter_period_id = period_row.id
        JOIN platform.billing_v1_adoption_opening_evidence AS evidence_row
          ON evidence_row.meter_period_id = period_row.id
        WHERE period_row.id = p_target_id
          AND evidence_row.evidence_kind = CASE p_record_kind
              WHEN 'usage_opening' THEN 'submission_usage'
              ELSE 'owner_gauge'
          END;
    ELSIF p_record_kind IS NOT DISTINCT FROM 'legacy_event' THEN
        SELECT pg_catalog.to_jsonb(row_value) INTO v_document
        FROM platform.billing_v1_event_archive AS row_value
        WHERE row_value.id = p_target_id;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'billing V1 tenant fingerprint kind is invalid';
    END IF;
    IF v_document IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN pg_catalog.sha256(
        pg_catalog.convert_to(v_document::text, 'UTF8')
    );
END;
$$;


ALTER FUNCTION platform.billing_v1_adoption_tenant_fingerprint_v1(p_record_kind text, p_target_id uuid) OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_verify_rollback_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_adoption_verify_rollback_v1(p_operation_id uuid, p_run_id uuid, p_source_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_source_count bigint;
    v_target_count bigint;
    v_source_sha text;
    v_target_sha text;
    v_money bigint;
    v_period bigint;
    v_coupon bigint;
    v_usage bigint;
    v_receipt_id uuid;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_source_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'billing V1 adoption verification principal denied';
    END IF;
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
    FOR UPDATE;
    IF v_run.state = 'rollback_rehearsed' THEN
        IF v_run.source_sha256 IS DISTINCT FROM
               pg_catalog.decode(p_source_sha256, 'hex') OR
           v_run.baseline_sha256 IS DISTINCT FROM v_run.target_sha256 OR
           v_run.money_difference <> 0 OR v_run.period_difference <> 0 OR
           v_run.coupon_difference <> 0 OR v_run.usage_difference <> 0 THEN
            RAISE EXCEPTION USING ERRCODE = '22000',
                MESSAGE = 'billing V1 adoption completed evidence differs';
        END IF;
        RETURN pg_catalog.encode(v_run.target_sha256, 'hex');
    END IF;
    SELECT * INTO STRICT v_source_count, v_target_count,
        v_source_sha, v_target_sha, v_money, v_period, v_coupon, v_usage
    FROM platform.billing_verify_v1_adoption_v1(p_operation_id, p_run_id);
    IF v_source_count IS DISTINCT FROM v_target_count OR
       v_source_sha IS DISTINCT FROM v_target_sha OR
       v_money <> 0 OR v_period <> 0 OR v_coupon <> 0 OR v_usage <> 0 THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'billing V1 adoption reconciliation is not zero-diff',
            DETAIL = pg_catalog.format(
                'source=%s target=%s digest_equal=%s money=%s period=%s coupon=%s usage=%s',
                v_source_count, v_target_count, v_source_sha = v_target_sha,
                v_money, v_period, v_coupon, v_usage
            );
    END IF;
    v_receipt_id := pg_catalog.gen_random_uuid();
    v_now := pg_catalog.clock_timestamp();
    PERFORM * FROM platform.billing_rehearse_v1_adoption_rollback_v1(
        p_operation_id, p_run_id, v_receipt_id, p_source_sha256, v_now
    );
    PERFORM platform.billing_assert_v1_adoption_ready_v1(
        p_operation_id, p_run_id, p_source_sha256
    );
    RETURN v_target_sha;
END;
$_$;


ALTER FUNCTION platform.billing_v1_adoption_verify_rollback_v1(p_operation_id uuid, p_run_id uuid, p_source_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_base_adoption_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_base_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract text;
    v_oid oid;
    v_signature text;
    v_replayed boolean;
    v_count bigint;
    v_key_sha text;
    v_state_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_batch_bytes IS DISTINCT FROM pg_catalog.octet_length(p_change_batch_bytes)
       OR p_batch_bytes NOT BETWEEN 1 AND 8388608
       OR pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes),'hex')
            IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 Billing base adoption composite denied';
    END IF;
    v_batch := pg_catalog.convert_from(p_change_batch_bytes,'UTF8')::jsonb;
    IF (v_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id
       OR (v_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id
       OR v_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind
       OR (v_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id
       OR (v_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal
       OR v_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key
       OR v_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state
       OR v_batch->'last_key' IS DISTINCT FROM p_last_key
       OR v_batch#>>'{source_position,snapshot_name}' IS DISTINCT FROM p_snapshot_name
       OR (v_batch#>>'{source_position,snapshot_lsn}')::pg_lsn IS DISTINCT FROM p_snapshot_lsn
       OR (v_batch#>>'{source_position,received_lsn}')::pg_lsn IS DISTINCT FROM p_received_lsn
       OR (v_batch#>>'{source_position,commit_lsn}')::pg_lsn IS DISTINCT FROM p_commit_lsn
       OR (v_batch#>>'{source_position,final_lsn}')::pg_lsn IS DISTINCT FROM p_final_lsn
       OR (v_batch#>>'{source_position,source_xid}')::xid8 IS DISTINCT FROM p_source_xid
       OR (v_batch#>>'{source_position,batch_ordinal}')::integer IS DISTINCT FROM p_batch_ordinal THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 Billing base adoption batch evidence differs';
    END IF;
    SELECT prepared.procedure_contract_id,prepared.procedure_oid,
        prepared.procedure_signature,prepared.already_applied,
        prepared.applied_count,prepared.key_state_sha256,prepared.state_sha256
      INTO STRICT v_contract,v_oid,v_signature,v_replayed,
        v_count,v_key_sha,v_state_sha
      FROM platform.cutover_prepare_batch_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
        p_checkpoint_key,p_batch_ordinal,p_commit_lsn,p_source_xid,
        p_batch_sha256,p_lease_manifest_sha256) AS prepared;
    IF v_contract IS DISTINCT FROM 'billing.v1_base_adoption.v1'
       OR v_oid IS DISTINCT FROM
            'platform.billing_v1_base_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid
       OR v_signature IS DISTINCT FROM
            'platform.billing_v1_base_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 Billing base adoption procedure binding differs';
    END IF;
    IF v_replayed THEN
        RETURN QUERY SELECT v_count,v_key_sha,v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count,result.key_state_sha256,result.state_sha256
      INTO STRICT v_count,v_key_sha,v_state_sha
      FROM platform.billing_v1_base_adoption_apply_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
        p_checkpoint_key,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
        p_source_xid,p_batch_ordinal,v_batch,p_batch_sha256) AS result;
    IF v_count<0 OR v_key_sha !~ '^[0-9a-f]{64}$'
       OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='V1 Billing base adoption result is invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id,p_run_id,p_relation_ordinal,p_checkpoint_key,p_snapshot_name,
        p_snapshot_lsn,p_received_lsn,p_commit_lsn,p_final_lsn,p_source_xid,
        p_batch_ordinal,p_checkpoint_state,p_last_key,p_batch_sha256,p_batch_bytes,
        v_count,v_key_sha,v_state_sha);
    RETURN QUERY SELECT v_count,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION platform.billing_v1_base_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_base_adoption_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_base_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_after jsonb;
    v_plan jsonb;
    v_assignment jsonb;
    v_plan_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            IS DISTINCT FROM 'harpy-cutover/'||p_run_id::text
       OR p_scope_kind IS DISTINCT FROM 'global' OR p_scope_id IS NULL
       OR p_operation_id IS NULL OR p_run_id IS NULL
       OR p_relation_ordinal<1 OR p_checkpoint_key=''
       OR p_snapshot_lsn>p_commit_lsn OR p_received_lsn<p_commit_lsn
       OR p_batch_ordinal NOT BETWEEN 1 AND 2147483
       OR p_batch_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.jsonb_typeof(p_change_batch->'changes')<>'array'
       OR pg_catalog.jsonb_array_length(p_change_batch->'changes')<>1 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 Billing base adoption apply denied';
    END IF;
    v_after := p_change_batch#>'{changes,0,after}';
    IF p_change_batch#>>'{changes,0,kind}' IS DISTINCT FROM 'insert'
       OR p_change_batch#>'{changes,0,before}' IS DISTINCT FROM 'null'::jsonb
       OR pg_catalog.jsonb_typeof(v_after)<>'object'
       OR (SELECT pg_catalog.array_agg(key ORDER BY key)
             FROM pg_catalog.jsonb_object_keys(v_after) AS key)
          IS DISTINCT FROM ARRAY['authority_ids','contract_version','inventory',
              'operation_id','plan']::text[]
       OR v_after->>'contract_version' IS DISTINCT FROM
            'platform-v1-environment-adoption.v1'
       OR (v_after->>'operation_id')::uuid IS DISTINCT FROM p_operation_id THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 Billing base adoption document differs';
    END IF;
    v_plan := v_after->'plan';
    v_plan_sha := v_plan->>'plan_sha256';
    IF pg_catalog.jsonb_typeof(v_plan->'base_assignments')<>'array'
       OR pg_catalog.jsonb_array_length(v_plan->'base_assignments')<1 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 Billing base assignments are invalid';
    END IF;
    PERFORM 1 FROM platform.platform_cutover_v1_adoption_plans AS recorded
     WHERE recorded.operation_id=p_operation_id
       AND recorded.environment_id=p_scope_id AND recorded.decision='ready'
       AND recorded.plan_sha256=v_plan_sha
       AND recorded.plan_document=v_plan FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 Billing base adoption plan is not recorded';
    END IF;
    FOR v_assignment IN
        SELECT value FROM pg_catalog.jsonb_array_elements(
            v_plan->'base_assignments')
    LOOP
        PERFORM platform.billing_v1_base_adoption_assert_v1(
            p_operation_id,p_scope_id,(v_assignment->>'tenant_id')::uuid,
            v_assignment->>'kind',v_assignment#>>'{offering,key}',
            (v_assignment#>>'{offering,version_id}')::uuid,
            (v_assignment#>>'{offering,revision}')::bigint,
            v_assignment#>>'{offering,sha256}',
            (v_assignment#>>'{offering,effective_at}')::timestamptz,
            (v_assignment#>>'{offering,source_sequence}')::bigint,
            v_assignment#>>'{offering,source_sha256}',
            v_assignment->>'subscription_evidence_sha256',v_plan_sha);
    END LOOP;
    applied_count := pg_catalog.jsonb_array_length(
        v_plan->'base_assignments')::bigint;
    key_state_sha256 := v_plan_sha;
    state_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'billing:'||v_plan_sha||':'||applied_count::text,'UTF8')),'hex');
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.billing_v1_base_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_v1_base_adoption_assert_v1(uuid, uuid, uuid, text, text, uuid, bigint, text, timestamp with time zone, bigint, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_v1_base_adoption_assert_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_evidence_kind text, p_offering_key text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_subscription_sha256 text, p_plan_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.billing_v1_base_adoption_receipts%ROWTYPE;
    v_assignment_id uuid;
    v_assignment_count integer;
    v_purpose text;
    v_source_sequence bigint;
    v_source_sha256 text;
    v_subscription_sha256 text;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    v_source_sequence := NULLIF(p_source_sequence,0);
    v_source_sha256 := NULLIF(p_source_sha256,'');
    v_subscription_sha256 := NULLIF(p_subscription_sha256,'');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            !~ '^harpy-cutover/[0-9a-f-]{36}$'
       OR p_operation_id IS NULL OR p_environment_id IS NULL OR p_tenant_id IS NULL
       OR p_evidence_kind NOT IN ('license_derived','saas_control','saas_free','saas_paid')
       OR p_offering_key !~ '^[a-z][a-z0-9._-]{0,126}[a-z0-9]$'
       OR p_offering_version_id IS NULL OR p_offering_revision<1
       OR p_offering_sha256 !~ '^[0-9a-f]{64}$'
       OR NOT pg_catalog.isfinite(p_offering_effective_at)
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 Billing base adoption denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('v1-billing-base|'||p_tenant_id::text,0));
    SELECT * INTO v_existing FROM platform.billing_v1_base_adoption_receipts
     WHERE tenant_id=p_tenant_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.operation_id IS DISTINCT FROM p_operation_id
           OR v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.evidence_kind IS DISTINCT FROM p_evidence_kind
           OR v_existing.offering_key IS DISTINCT FROM p_offering_key
           OR v_existing.offering_version_id IS DISTINCT FROM p_offering_version_id
           OR v_existing.offering_revision IS DISTINCT FROM p_offering_revision
           OR v_existing.offering_sha256 IS DISTINCT FROM p_offering_sha256
           OR v_existing.offering_effective_at IS DISTINCT FROM p_offering_effective_at
           OR v_existing.source_sequence IS DISTINCT FROM v_source_sequence
           OR v_existing.source_sha256 IS DISTINCT FROM v_source_sha256
           OR v_existing.subscription_evidence_sha256 IS DISTINCT FROM v_subscription_sha256
           OR v_existing.plan_sha256 IS DISTINCT FROM p_plan_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='V1 Billing base adoption replay conflicts';
        END IF;
        RETURN true;
    END IF;
    SELECT binding.purpose INTO v_purpose
      FROM platform.tenancy_tenant_bindings AS binding
     WHERE binding.environment_id=p_environment_id AND binding.tenant_id=p_tenant_id
     FOR SHARE;
    IF (p_evidence_kind='license_derived' AND v_purpose<>'onpremise_primary')
       OR (p_evidence_kind='saas_control' AND v_purpose<>'saas_control')
       OR (p_evidence_kind IN ('saas_free','saas_paid') AND v_purpose<>'saas_customer') THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 Billing evidence conflicts with tenant purpose';
    END IF;
    PERFORM 1 FROM platform.billing_tenant_base_offerings AS base
     WHERE base.tenant_id=p_tenant_id AND base.effective_end IS NULL
     FOR SHARE;
    GET DIAGNOSTICS v_assignment_count = ROW_COUNT;
    IF v_assignment_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 Billing base assignment inventory is ambiguous';
    END IF;
    SELECT base.id INTO v_assignment_id
      FROM platform.billing_tenant_base_offerings AS base
      JOIN platform.billing_offering_versions AS version ON version.id=base.offering_version_id
      JOIN platform.billing_offerings AS offering ON offering.id=version.offering_id
     WHERE base.tenant_id=p_tenant_id AND base.effective_end IS NULL
       AND base.offering_version_id=p_offering_version_id
       AND version.version=p_offering_revision
       AND offering.offering_key=p_offering_key AND offering.lifecycle='active'
     FOR SHARE OF base,version,offering;
    IF v_assignment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='exact V2 base assignment is unavailable';
    END IF;
    IF p_evidence_kind='license_derived' THEN
        PERFORM 1 FROM platform.billing_license_offering_publications AS publication
         WHERE publication.environment_id=p_environment_id
           AND publication.offering_version_id=p_offering_version_id
           AND publication.revision=p_offering_revision
           AND publication.offering_sha256=p_offering_sha256
           AND publication.effective_at=p_offering_effective_at
           AND publication.snapshot_sequence=v_source_sequence
           AND publication.snapshot_sha256=v_source_sha256 FOR SHARE;
    ELSIF p_evidence_kind='saas_control' THEN
        PERFORM 1 FROM platform.billing_saas_control_offering_publications AS publication
         WHERE publication.offering_key='saas_platform_control_base_v1'
           AND p_offering_key='saas_platform_control_base_v1'
           AND publication.offering_version_id=p_offering_version_id
           AND publication.revision=p_offering_revision
           AND publication.offering_sha256=p_offering_sha256
           AND publication.effective_at=p_offering_effective_at FOR SHARE;
    ELSIF p_evidence_kind='saas_free' THEN
        PERFORM 1 FROM platform.billing_saas_free_base_publications AS publication
         WHERE publication.offering_key='saas_free_base_v1'
           AND p_offering_key='saas_free_base_v1'
           AND publication.offering_version_id=p_offering_version_id
           AND publication.revision=p_offering_revision
           AND publication.offering_sha256=p_offering_sha256
           AND publication.effective_at=p_offering_effective_at
           AND NOT EXISTS (SELECT 1 FROM platform.billing_subscriptions AS subscription
                            WHERE subscription.tenant_id=p_tenant_id) FOR SHARE;
    ELSE
        PERFORM 1 FROM platform.billing_subscriptions AS subscription
         WHERE subscription.tenant_id=p_tenant_id
           AND subscription.offering_version_id=p_offering_version_id
           AND subscription.state IN ('trialing','active','past_due')
           AND v_subscription_sha256 ~ '^[0-9a-f]{64}$' FOR SHARE;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 Billing evidence is not verified';
    END IF;
    INSERT INTO platform.billing_v1_base_adoption_receipts(
        operation_id,environment_id,tenant_id,assignment_id,evidence_kind,
        offering_key,offering_version_id,offering_revision,offering_sha256,
        offering_effective_at,source_sequence,source_sha256,
        subscription_evidence_sha256,plan_sha256,
        adopted_at,recorded_by
    ) VALUES (p_operation_id,p_environment_id,p_tenant_id,v_assignment_id,p_evidence_kind,
        p_offering_key,p_offering_version_id,p_offering_revision,p_offering_sha256,
        p_offering_effective_at,v_source_sequence,v_source_sha256,
        v_subscription_sha256,p_plan_sha256,
        v_now,SESSION_USER);
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.billing_v1_base_adoption_assert_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_evidence_kind text, p_offering_key text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_source_sequence bigint, p_source_sha256 text, p_subscription_sha256 text, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: billing_verify_v1_adoption_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.billing_verify_v1_adoption_v1(p_operation_id uuid, p_run_id uuid) RETURNS TABLE(source_count bigint, target_count bigint, source_sha256 text, target_sha256 text, money_difference bigint, period_difference bigint, coupon_difference bigint, usage_difference bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.billing_v1_adoption_runs%ROWTYPE;
    v_baseline bytea;
    v_target bytea;
    v_source_count bigint;
    v_target_count bigint;
    v_money bigint;
    v_period bigint;
    v_coupon bigint;
    v_usage bigint;
    v_now timestamptz;
BEGIN
    v_money := 0; v_period := 0; v_coupon := 0; v_usage := 0;
    v_now := pg_catalog.clock_timestamp();
    SELECT run.* INTO STRICT v_run
    FROM platform.billing_v1_adoption_runs AS run
    WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
    FOR UPDATE;
    IF v_run.state NOT IN ('applied', 'verified', 'rollback_rehearsed') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'billing V1 adoption run is not verifiable';
    END IF; SELECT COALESCE(pg_catalog.sum(category.source_count), 0)
    INTO v_source_count
    FROM platform.billing_v1_adoption_categories AS category
    WHERE category.operation_id = p_operation_id AND category.run_id = p_run_id;
    SELECT pg_catalog.sha256(pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
               mapping.record_kind || ':' || mapping.source_key || ':' ||
               pg_catalog.encode(mapping.record_sha256, 'hex'), '|'
               ORDER BY mapping.record_kind, mapping.source_key
           ), ''), 'UTF8'))
    INTO v_baseline
    FROM platform.billing_v1_adoption_mappings AS mapping
    WHERE mapping.operation_id = p_operation_id AND mapping.run_id = p_run_id;
    SELECT pg_catalog.count(current_sha),
           pg_catalog.sha256(pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
               record_kind || ':' || source_key || ':' ||
               pg_catalog.encode(current_sha, 'hex'), '|'
               ORDER BY record_kind, source_key
           ) FILTER (WHERE current_sha IS NOT NULL), ''), 'UTF8'))
    INTO v_target_count, v_target
    FROM (
        SELECT mapping.record_kind, mapping.source_key,
            platform.billing_v1_adoption_fingerprint_v1(
                mapping.record_kind, mapping.target_id
            ) AS current_sha
        FROM platform.billing_v1_adoption_mappings AS mapping
        WHERE mapping.operation_id = p_operation_id AND mapping.run_id = p_run_id
    ) AS current_rows;
    IF v_run.scope_kind = 'global' THEN
        SELECT COALESCE(pg_catalog.sum(pg_catalog.abs(
            (discount->>'source_used_count')::bigint - (
                SELECT pg_catalog.count(*)
                FROM platform.billing_discount_redemptions AS redemption
                WHERE redemption.discount_version_id =
                    (discount->>'version_id')::uuid
            )
        )), 0) INTO v_coupon
        FROM pg_catalog.jsonb_array_elements(
            v_run.plan_document->'discounts'
        ) AS discount;
    ELSE
        SELECT COALESCE(pg_catalog.sum(pg_catalog.abs(
            (subscription->>'effective_minor_units')::bigint -
            COALESCE(effective.effective_minor_units, -1)
        )), 0) INTO v_money
        FROM pg_catalog.jsonb_array_elements(
            v_run.plan_document->'subscriptions'
        ) AS subscription
        LEFT JOIN platform.billing_effective_subscription_price_v1(
            v_run.authority_id, v_run.scope_id,
            (subscription->>'id')::uuid, v_run.snapshot_at
        ) AS effective ON true;
        SELECT pg_catalog.count(*) INTO v_period
        FROM pg_catalog.jsonb_array_elements(
            v_run.plan_document->'subscriptions'
        ) AS expected
        LEFT JOIN platform.billing_subscriptions AS actual
          ON actual.id = (expected->>'id')::uuid
        WHERE actual.id IS NULL OR actual.state IS DISTINCT FROM expected->>'state'
           OR actual.period_start IS DISTINCT FROM (expected->>'period_start')::timestamptz
           OR actual.period_end IS DISTINCT FROM (expected->>'period_end')::timestamptz
           OR actual.trial_ends_at IS DISTINCT FROM
                NULLIF(expected->>'trial_ends_at', '')::timestamptz
           OR actual.grace_ends_at IS DISTINCT FROM
                NULLIF(expected->>'grace_ends_at', '')::timestamptz
           OR actual.cancel_at IS DISTINCT FROM
                NULLIF(expected->>'cancel_at', '')::timestamptz;
        SELECT pg_catalog.count(*) INTO v_coupon
        FROM pg_catalog.jsonb_array_elements(
            v_run.plan_document->'redemptions'
        ) AS expected
        LEFT JOIN platform.billing_discount_redemptions AS actual
          ON actual.id = (expected->>'id')::uuid
        WHERE actual.id IS NULL
           OR actual.policy_sha256 IS DISTINCT FROM
                pg_catalog.decode(expected->>'policy_sha256', 'hex')
           OR actual.applied_kind IS DISTINCT FROM expected->>'applied_kind'
           OR actual.applied_fixed_minor_units IS DISTINCT FROM
                NULLIF(expected->>'applied_fixed_minor_units', '')::bigint
           OR actual.applied_basis_points IS DISTINCT FROM
                NULLIF(expected->>'applied_basis_points', '')::integer;
        SELECT COALESCE(pg_catalog.sum(pg_catalog.abs(
            (expected->>'opening_value')::bigint - COALESCE(
                CASE expected->>'record_kind'
                    WHEN 'usage_opening' THEN totals.committed_total
                    ELSE totals.gauge_total END, -1
            )
        )), 0) INTO v_usage
        FROM (
            SELECT value || '{"record_kind":"usage_opening"}'::jsonb ||
                pg_catalog.jsonb_build_object('opening_value', value->'count') AS expected
            FROM pg_catalog.jsonb_array_elements(v_run.plan_document->'usage_openings')
            UNION ALL
            SELECT value || '{"record_kind":"gauge_opening"}'::jsonb ||
                pg_catalog.jsonb_build_object('opening_value', value->'value')
            FROM pg_catalog.jsonb_array_elements(v_run.plan_document->'gauge_openings')
        ) AS expected
        LEFT JOIN platform.billing_usage_totals AS totals
          ON totals.meter_period_id = (expected->>'meter_period_id')::uuid;
    END IF; UPDATE platform.billing_v1_adoption_categories AS category SET
        target_count = (SELECT pg_catalog.count(current_sha)
            FROM (SELECT platform.billing_v1_adoption_fingerprint_v1(
                    mapping.record_kind, mapping.target_id) AS current_sha
                  FROM platform.billing_v1_adoption_mappings AS mapping
                  WHERE mapping.operation_id = p_operation_id
                    AND mapping.run_id = p_run_id
                    AND mapping.category = category.category) AS rows),
        baseline_sha256 = (SELECT pg_catalog.sha256(pg_catalog.convert_to(
            COALESCE(pg_catalog.string_agg(mapping.record_kind || ':' ||
                mapping.source_key || ':' || pg_catalog.encode(
                    mapping.record_sha256, 'hex'), '|' ORDER BY
                mapping.record_kind, mapping.source_key), ''), 'UTF8'))
            FROM platform.billing_v1_adoption_mappings AS mapping
            WHERE mapping.operation_id = p_operation_id AND mapping.run_id = p_run_id
              AND mapping.category = category.category),
        target_sha256 = (SELECT pg_catalog.sha256(pg_catalog.convert_to(
            COALESCE(pg_catalog.string_agg(mapping.record_kind || ':' ||
                mapping.source_key || ':' || pg_catalog.encode(
                    platform.billing_v1_adoption_fingerprint_v1(
                        mapping.record_kind, mapping.target_id), 'hex'), '|'
                    ORDER BY mapping.record_kind, mapping.source_key), ''), 'UTF8'))
            FROM platform.billing_v1_adoption_mappings AS mapping
            WHERE mapping.operation_id = p_operation_id AND mapping.run_id = p_run_id
              AND mapping.category = category.category), updated_at = v_now
    WHERE category.operation_id = p_operation_id AND category.run_id = p_run_id;
    UPDATE platform.billing_v1_adoption_runs SET
        state = CASE WHEN v_source_count = v_target_count AND v_baseline = v_target
            AND v_money = 0 AND v_period = 0 AND v_coupon = 0 AND v_usage = 0
            THEN 'verified' ELSE 'blocked' END,
        baseline_sha256 = v_baseline, target_sha256 = v_target,
        money_difference = v_money, period_difference = v_period,
        coupon_difference = v_coupon, usage_difference = v_usage,
        verified_at = v_now, updated_at = v_now
    WHERE operation_id = p_operation_id AND run_id = p_run_id;
    RETURN QUERY SELECT v_source_count, v_target_count,
        pg_catalog.encode(v_baseline, 'hex'), pg_catalog.encode(v_target, 'hex'),
        v_money, v_period, v_coupon, v_usage;
END;
$$;


ALTER FUNCTION platform.billing_verify_v1_adoption_v1(p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: catalog_adoption_registry_blocker_v1(uuid, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.catalog_adoption_registry_blocker_v1(p_package_id uuid, p_slug text, p_version text, p_manifest_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_package_id uuid;
    v_manifest_sha256 text;
BEGIN
    IF SESSION_USER NOT IN ('harpy_v2_runtime','harpy_adopter') OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog adoption registry authority denied';
    END IF;
    SELECT package.package_id INTO v_package_id
    FROM platform.catalog_packages AS package
    WHERE package.slug=p_slug
      AND (p_package_id IS NULL OR package.package_id=p_package_id);
    IF NOT FOUND THEN
        RETURN 'UNKNOWN_PACKAGE';
    END IF;
    SELECT version.manifest_sha256 INTO v_manifest_sha256
    FROM platform.catalog_package_versions AS version
    WHERE version.package_id=v_package_id AND version.version=p_version;
    IF NOT FOUND THEN
        RETURN 'UNKNOWN_VERSION';
    END IF;
    IF p_manifest_sha256 IS NOT NULL AND
       p_manifest_sha256 IS DISTINCT FROM v_manifest_sha256 THEN
        RETURN 'MANIFEST_HASH_MISMATCH';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.catalog_adoption_registry_blocker_v1(p_package_id uuid, p_slug text, p_version text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: catalog_assert_tenant_authority_v1(uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.catalog_assert_tenant_authority_v1(expected_tenant uuid, expected_generation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    matched boolean;
BEGIN
    SELECT true INTO matched
    FROM platform.domain_cutovers
    WHERE scope_kind = 'tenant'
      AND scope_id = expected_tenant
      AND domain = 'catalog'
      AND state = 'v2'
      AND writer = 'v2'
      AND generation = expected_generation
    FOR SHARE;
    IF matched IS DISTINCT FROM true OR session_user <> 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'catalog authority is not current';
    END IF;
END;
$$;


ALTER FUNCTION platform.catalog_assert_tenant_authority_v1(expected_tenant uuid, expected_generation bigint) OWNER TO harpy_owner;

--
-- Name: catalog_reject_registry_mutation_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.catalog_reject_registry_mutation_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'catalog registry is immutable';
END;
$$;


ALTER FUNCTION platform.catalog_reject_registry_mutation_v1() OWNER TO harpy_owner;

--
-- Name: contract_retirement_admit_v1(jsonb, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.contract_retirement_admit_v1(p_contract_keys jsonb, p_owner_module text, p_domain text) RETURNS TABLE(retired_contract_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_input_count bigint;
    v_distinct_count bigint;
    v_found_count bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_contract_keys IS NULL OR p_owner_module IS NULL OR p_domain IS NULL OR
       p_owner_module OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_]{0,62}$' OR
       NOT (p_domain OPERATOR(pg_catalog.=) ANY (
           ARRAY['analytics','billing','catalog','documents','iam',
                 'notifications','system_resource_layout','work','workflow']::text[]
       )) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement admission input is invalid';
    END IF;
    IF pg_catalog.jsonb_typeof(p_contract_keys) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement admission input is invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(p_contract_keys) OPERATOR(pg_catalog.<) 1 OR
       pg_catalog.jsonb_array_length(p_contract_keys) OPERATOR(pg_catalog.>) 256 OR
       EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_contract_keys) AS item(value)
           WHERE pg_catalog.jsonb_typeof(item.value) IS DISTINCT FROM 'string'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement admission input is invalid';
    END IF;
    SELECT pg_catalog.count(*), pg_catalog.count(DISTINCT key_value)
    INTO STRICT v_input_count, v_distinct_count
    FROM pg_catalog.jsonb_array_elements_text(p_contract_keys) AS key_row(key_value)
    WHERE key_value OPERATOR(pg_catalog.~) '^rq[.]alias[.][0-9a-f]{64}$';
    IF v_input_count IS DISTINCT FROM
           pg_catalog.jsonb_array_length(p_contract_keys)::pg_catalog.int8 OR
       v_distinct_count IS DISTINCT FROM v_input_count THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement admission keys are invalid';
    END IF;
    PERFORM retirement.contract_key
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
        SELECT key_value
        FROM pg_catalog.jsonb_array_elements_text(p_contract_keys) AS key_row(key_value)
    )
    ORDER BY retirement.contract_key COLLATE "C";
    SELECT pg_catalog.count(*) INTO STRICT v_found_count
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
        SELECT key_value
        FROM pg_catalog.jsonb_array_elements_text(p_contract_keys) AS key_row(key_value)
    );
    IF v_found_count IS DISTINCT FROM v_input_count THEN
        RAISE EXCEPTION USING ERRCODE = 'P5501',
            MESSAGE = 'contract retirement key is missing';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND (retirement.owner_module IS DISTINCT FROM p_owner_module OR
               retirement.domain IS DISTINCT FROM p_domain)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5502',
            MESSAGE = 'contract retirement identity differs';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND retirement.state OPERATOR(pg_catalog.=) 'retired'
    ) THEN
        RETURN QUERY
        SELECT retirement.contract_key
        FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND retirement.state OPERATOR(pg_catalog.=) 'retired'
        ORDER BY retirement.contract_key COLLATE "C";
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND (retirement.state IS DISTINCT FROM 'active' OR
               retirement.remaining_scope_count OPERATOR(pg_catalog.<=) 0)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5506',
            MESSAGE = 'contract retirement release admission is denied';
    END IF;
    RETURN;
END;
$_$;


ALTER FUNCTION platform.contract_retirement_admit_v1(p_contract_keys jsonb, p_owner_module text, p_domain text) OWNER TO harpy_owner;

--
-- Name: contract_retirement_finalize_v1(text, text, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.contract_retirement_finalize_v1(p_contract_key text, p_owner_module text, p_domain text, p_expected_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_retirement platform.contract_retirements%ROWTYPE;
    v_now timestamptz;
    v_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator' OR
       p_contract_key IS NULL OR p_owner_module IS NULL OR p_domain IS NULL OR
       p_contract_key OPERATOR(pg_catalog.!~) '^rq[.]alias[.][0-9a-f]{64}$' OR
       p_owner_module OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_]{0,62}$' OR
       NOT (p_domain OPERATOR(pg_catalog.=) ANY (
           ARRAY['analytics','billing','catalog','documents','iam',
                 'notifications','system_resource_layout','work','workflow']::text[]
       )) OR
       p_expected_revision IS NULL OR p_expected_revision OPERATOR(pg_catalog.<) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement finalization input is invalid';
    END IF;
    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) p_contract_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5501',
            MESSAGE = 'contract retirement key is missing';
    END IF;
    IF v_retirement.owner_module IS DISTINCT FROM p_owner_module OR
       v_retirement.domain IS DISTINCT FROM p_domain THEN
        RAISE EXCEPTION USING ERRCODE = 'P5502',
            MESSAGE = 'contract retirement identity differs';
    END IF;
    IF v_retirement.state OPERATOR(pg_catalog.=) 'retired' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5503',
            MESSAGE = 'retired contract key is terminal';
    END IF;
    IF v_retirement.revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = 'P5505',
            MESSAGE = 'contract retirement revision differs';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF v_retirement.state IS DISTINCT FROM 'eligible' OR
       v_retirement.remaining_scope_count IS DISTINCT FROM 0 OR
       v_retirement.zero_hit_since IS NULL OR
       v_retirement.eligible_at IS NULL OR
       v_now OPERATOR(pg_catalog.<) (
           v_retirement.zero_hit_since OPERATOR(pg_catalog.+) INTERVAL '30 days'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5506',
            MESSAGE = 'contract retirement is not eligible';
    END IF;
    IF v_retirement.revision OPERATOR(pg_catalog.=) 9223372036854775807 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5504',
            MESSAGE = 'contract retirement counter overflow';
    END IF;
    UPDATE platform.contract_retirements AS retirement
    SET state = 'retired', retired_at = v_now,
        revision = retirement.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) p_contract_key
    RETURNING retirement.revision INTO STRICT v_revision;
    RETURN v_revision;
END;
$_$;


ALTER FUNCTION platform.contract_retirement_finalize_v1(p_contract_key text, p_owner_module text, p_domain text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: contract_retirement_guard_update(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.contract_retirement_guard_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF OLD.state OPERATOR(pg_catalog.=) 'retired' OR
       NEW.contract_key IS DISTINCT FROM OLD.contract_key OR
       NEW.owner_module IS DISTINCT FROM OLD.owner_module OR
       NEW.domain IS DISTINCT FROM OLD.domain OR
       NEW.revision IS DISTINCT FROM OLD.revision OPERATOR(pg_catalog.+) 1 OR
       NEW.updated_at OPERATOR(pg_catalog.<) OLD.updated_at OR
       NEW.updated_at OPERATOR(pg_catalog.>) pg_catalog.clock_timestamp() OR
       NEW.hit_count OPERATOR(pg_catalog.<) OLD.hit_count OR
       (OLD.last_hit_at IS NOT NULL AND
        NEW.last_hit_at OPERATOR(pg_catalog.<) OLD.last_hit_at) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'contract retirement monotonic update rejected';
    END IF;
    IF NEW.hit_count IS DISTINCT FROM OLD.hit_count THEN
        IF NEW.hit_count IS DISTINCT FROM OLD.hit_count OPERATOR(pg_catalog.+) 1 OR
           NEW.last_hit_at IS DISTINCT FROM NEW.updated_at OR
           NEW.state IS DISTINCT FROM 'active' OR
           NEW.remaining_scope_count IS DISTINCT FROM OLD.remaining_scope_count OR
           NEW.zero_hit_since IS NOT NULL OR NEW.eligible_at IS NOT NULL OR
           NEW.retired_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'contract retirement hit update rejected';
        END IF;
    ELSIF NEW.last_hit_at IS DISTINCT FROM OLD.last_hit_at THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'contract retirement last hit update rejected';
    END IF;
    IF NEW.state OPERATOR(pg_catalog.=) 'active' THEN
        IF NEW.eligible_at IS NOT NULL OR NEW.retired_at IS NOT NULL OR
           (NEW.remaining_scope_count OPERATOR(pg_catalog.>) 0 AND
            NEW.zero_hit_since IS NOT NULL) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'contract retirement active state rejected';
        END IF;
    ELSIF NEW.state OPERATOR(pg_catalog.=) 'eligible' THEN
        IF NEW.remaining_scope_count IS DISTINCT FROM 0 OR
           NEW.zero_hit_since IS NULL OR NEW.eligible_at IS NULL OR
           NEW.retired_at IS NOT NULL OR
           NEW.eligible_at OPERATOR(pg_catalog.<) (
               NEW.zero_hit_since OPERATOR(pg_catalog.+) INTERVAL '30 days'
           ) OR
           (OLD.state IS DISTINCT FROM 'eligible' AND
            NEW.eligible_at IS DISTINCT FROM NEW.updated_at) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'contract retirement eligible state rejected';
        END IF;
    ELSIF NEW.state OPERATOR(pg_catalog.=) 'retired' THEN
        IF OLD.state IS DISTINCT FROM 'eligible' OR
           NEW.remaining_scope_count IS DISTINCT FROM 0 OR
           NEW.zero_hit_since IS NULL OR NEW.eligible_at IS NULL OR
           NEW.retired_at IS NULL OR
           NEW.retired_at IS DISTINCT FROM NEW.updated_at OR
           NEW.retired_at OPERATOR(pg_catalog.<) NEW.eligible_at OR
           NEW.retired_at OPERATOR(pg_catalog.<) (
               NEW.zero_hit_since OPERATOR(pg_catalog.+) INTERVAL '30 days'
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'contract retirement terminal state rejected';
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'contract retirement state rejected';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.contract_retirement_guard_update() OWNER TO harpy_owner;

--
-- Name: contract_retirement_hit_v1(jsonb, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.contract_retirement_hit_v1(p_contract_keys jsonb, p_owner_module text, p_domain text) RETURNS TABLE(retired_contract_key text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_input_count bigint;
    v_distinct_count bigint;
    v_found_count bigint;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_contract_keys IS NULL OR p_owner_module IS NULL OR p_domain IS NULL OR
       p_owner_module OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_]{0,62}$' OR
       NOT (p_domain OPERATOR(pg_catalog.=) ANY (
           ARRAY['analytics','billing','catalog','documents','iam',
                 'notifications','system_resource_layout','work','workflow']::text[]
       )) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement hit input is invalid';
    END IF;
    IF pg_catalog.jsonb_typeof(p_contract_keys) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement hit input is invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(p_contract_keys) OPERATOR(pg_catalog.<) 1 OR
       pg_catalog.jsonb_array_length(p_contract_keys) OPERATOR(pg_catalog.>) 256 OR
       EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_contract_keys) AS item(value)
           WHERE pg_catalog.jsonb_typeof(item.value) IS DISTINCT FROM 'string'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement hit input is invalid';
    END IF;
    SELECT pg_catalog.count(*), pg_catalog.count(DISTINCT key_value)
    INTO STRICT v_input_count, v_distinct_count
    FROM pg_catalog.jsonb_array_elements_text(p_contract_keys) AS key_row(key_value)
    WHERE key_value OPERATOR(pg_catalog.~) '^rq[.]alias[.][0-9a-f]{64}$';
    IF v_input_count IS DISTINCT FROM
           pg_catalog.jsonb_array_length(p_contract_keys)::pg_catalog.int8 OR
       v_distinct_count IS DISTINCT FROM v_input_count THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement hit keys are invalid';
    END IF;
    PERFORM retirement.contract_key
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
        SELECT key_value
        FROM pg_catalog.jsonb_array_elements_text(p_contract_keys) AS key_row(key_value)
    )
    ORDER BY retirement.contract_key COLLATE "C"
    FOR UPDATE;
    SELECT pg_catalog.count(*) INTO STRICT v_found_count
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
        SELECT key_value
        FROM pg_catalog.jsonb_array_elements_text(p_contract_keys) AS key_row(key_value)
    );
    IF v_found_count IS DISTINCT FROM v_input_count THEN
        RAISE EXCEPTION USING ERRCODE = 'P5501',
            MESSAGE = 'contract retirement key is missing';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND (retirement.owner_module IS DISTINCT FROM p_owner_module OR
               retirement.domain IS DISTINCT FROM p_domain)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5502',
            MESSAGE = 'contract retirement identity differs';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND retirement.state OPERATOR(pg_catalog.=) 'retired'
    ) THEN
        RETURN QUERY
        SELECT retirement.contract_key
        FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND retirement.state OPERATOR(pg_catalog.=) 'retired'
        ORDER BY retirement.contract_key COLLATE "C";
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
            SELECT key_value FROM pg_catalog.jsonb_array_elements_text(p_contract_keys)
                AS key_row(key_value)
        ) AND (
            retirement.hit_count OPERATOR(pg_catalog.=) 9223372036854775807 OR
            retirement.revision OPERATOR(pg_catalog.=) 9223372036854775807
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5504',
            MESSAGE = 'contract retirement counter overflow';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    UPDATE platform.contract_retirements AS retirement
    SET hit_count = retirement.hit_count OPERATOR(pg_catalog.+) 1,
        revision = retirement.revision OPERATOR(pg_catalog.+) 1,
        last_hit_at = v_now, updated_at = v_now, state = 'active',
        zero_hit_since = NULL, eligible_at = NULL, retired_at = NULL
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) ANY (
        SELECT key_value
        FROM pg_catalog.jsonb_array_elements_text(p_contract_keys) AS key_row(key_value)
    );
    RETURN;
END;
$_$;


ALTER FUNCTION platform.contract_retirement_hit_v1(p_contract_keys jsonb, p_owner_module text, p_domain text) OWNER TO harpy_owner;

