ALTER FUNCTION platform.contract_retirement_mark_eligible_v1(p_contract_key text, p_owner_module text, p_domain text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: contract_retirement_provision_v1(text, text, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.contract_retirement_provision_v1(p_contract_key text, p_owner_module text, p_domain text, p_remaining_scope_count bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_retirement platform.contract_retirements%ROWTYPE;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator' OR
       p_contract_key IS NULL OR p_owner_module IS NULL OR p_domain IS NULL OR
       p_contract_key OPERATOR(pg_catalog.!~) '^rq[.]alias[.][0-9a-f]{64}$' OR
       p_owner_module OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_]{0,62}$' OR
       NOT (p_domain OPERATOR(pg_catalog.=) ANY (
           ARRAY['analytics','billing','catalog','documents','iam',
                 'notifications','system_resource_layout','work','workflow']::text[]
       )) OR p_remaining_scope_count IS NULL OR
       p_remaining_scope_count OPERATOR(pg_catalog.<) 0 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement provision input is invalid';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    INSERT INTO platform.contract_retirements AS retirement (
        contract_key, owner_module, domain, state, remaining_scope_count,
        hit_count, last_hit_at, zero_hit_since, eligible_at, retired_at,
        revision, updated_at
    ) VALUES (
        p_contract_key, p_owner_module, p_domain, 'active',
        p_remaining_scope_count, 0, NULL,
        CASE WHEN p_remaining_scope_count OPERATOR(pg_catalog.=) 0
            THEN v_now ELSE NULL END,
        NULL, NULL, 1, v_now
    ) ON CONFLICT (contract_key) DO NOTHING
    RETURNING retirement.* INTO v_retirement;
    IF NOT FOUND THEN
        SELECT retirement.* INTO v_retirement
        FROM platform.contract_retirements AS retirement
        WHERE retirement.contract_key OPERATOR(pg_catalog.=) p_contract_key
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = 'P5501',
                MESSAGE = 'contract retirement key is missing';
        END IF;
    END IF;
    IF v_retirement.owner_module IS DISTINCT FROM p_owner_module OR
       v_retirement.domain IS DISTINCT FROM p_domain THEN
        RAISE EXCEPTION USING ERRCODE = 'P5502',
            MESSAGE = 'contract retirement identity differs';
    END IF;
    IF v_retirement.state OPERATOR(pg_catalog.=) 'retired' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5503',
            MESSAGE = 'retired contract key cannot be provisioned';
    END IF;
    IF v_retirement.remaining_scope_count IS DISTINCT FROM p_remaining_scope_count THEN
        RAISE EXCEPTION USING ERRCODE = 'P5505',
            MESSAGE = 'contract retirement reconciliation is required';
    END IF;
    RETURN v_retirement.revision;
END;
$_$;


ALTER FUNCTION platform.contract_retirement_provision_v1(p_contract_key text, p_owner_module text, p_domain text, p_remaining_scope_count bigint) OWNER TO harpy_owner;

--
-- Name: contract_retirement_reconcile_v1(text, text, text, bigint, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.contract_retirement_reconcile_v1(p_contract_key text, p_owner_module text, p_domain text, p_remaining_scope_count bigint, p_expected_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_retirement platform.contract_retirements%ROWTYPE;
    v_now timestamptz;
    v_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator' OR
       p_contract_key IS NULL OR p_owner_module IS NULL OR p_domain IS NULL OR
       p_contract_key OPERATOR(pg_catalog.!~) '^rq[.]alias[.][0-9a-f]{64}$' OR
       p_owner_module OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_]{0,62}$' OR
       NOT (p_domain OPERATOR(pg_catalog.=) ANY (
           ARRAY['analytics','billing','catalog','documents','iam',
                 'notifications','system_resource_layout','work','workflow']::text[]
       )) OR
       p_remaining_scope_count IS NULL OR
       p_remaining_scope_count OPERATOR(pg_catalog.<) 0 OR
       p_expected_revision IS NULL OR p_expected_revision OPERATOR(pg_catalog.<) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'contract retirement reconcile input is invalid';
    END IF;
    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) p_contract_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5501',
            MESSAGE = 'contract retirement key is missing';
    END IF;
    IF v_retirement.owner_module IS DISTINCT FROM p_owner_module OR
       v_retirement.domain IS DISTINCT FROM p_domain THEN
        RAISE EXCEPTION USING ERRCODE = 'P5502',
            MESSAGE = 'contract retirement identity differs';
    END IF;
    IF v_retirement.state OPERATOR(pg_catalog.=) 'retired' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5503',
            MESSAGE = 'retired contract key cannot be reconciled';
    END IF;
    IF v_retirement.revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = 'P5505',
            MESSAGE = 'contract retirement revision differs';
    END IF;
    IF v_retirement.revision OPERATOR(pg_catalog.=) 9223372036854775807 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5504',
            MESSAGE = 'contract retirement counter overflow';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    UPDATE platform.contract_retirements AS retirement
    SET remaining_scope_count = p_remaining_scope_count,
        state = CASE
            WHEN p_remaining_scope_count OPERATOR(pg_catalog.>) 0 THEN 'active'
            WHEN retirement.state OPERATOR(pg_catalog.=) 'eligible' THEN 'eligible'
            ELSE 'active'
        END,
        zero_hit_since = CASE
            WHEN p_remaining_scope_count OPERATOR(pg_catalog.>) 0 THEN NULL
            ELSE COALESCE(retirement.zero_hit_since, v_now)
        END,
        eligible_at = CASE
            WHEN p_remaining_scope_count OPERATOR(pg_catalog.=) 0 AND
                 retirement.state OPERATOR(pg_catalog.=) 'eligible'
                THEN retirement.eligible_at
            ELSE NULL
        END,
        revision = retirement.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now
    WHERE retirement.contract_key OPERATOR(pg_catalog.=) p_contract_key
    RETURNING retirement.revision INTO STRICT v_revision;
    RETURN v_revision;
END;
$_$;


ALTER FUNCTION platform.contract_retirement_reconcile_v1(p_contract_key text, p_owner_module text, p_domain text, p_remaining_scope_count bigint, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: cutover_ensure_tenancy_authority_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_ensure_tenancy_authority_v1(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenancy cutover tenant is required';
    END IF;
    INSERT INTO platform.domain_cutovers (
        scope_kind, scope_id, domain, state, writer, generation,
        requested_by, approved_by, reason, change_reference,
        acceptance_digest, changed_at
    )
    SELECT domain.scope_kind, domain.scope_id, seed.domain,
           domain.state, domain.writer, domain.generation,
           domain.requested_by, domain.approved_by, domain.reason,
           domain.change_reference, domain.acceptance_digest,
           domain.changed_at
    FROM platform.domain_cutovers AS domain
    CROSS JOIN pg_catalog.unnest(ARRAY['tenancy']) AS seed(domain)
    WHERE domain.scope_kind = 'tenant'
      AND domain.scope_id = p_tenant_id
      AND domain.domain = 'workflow'
      AND NOT EXISTS (
          SELECT 1 FROM platform.domain_cutovers AS existing
          WHERE existing.scope_kind = domain.scope_kind
            AND existing.scope_id = domain.scope_id
            AND existing.domain = seed.domain
      );
    INSERT INTO platform.cutover_groups (
        scope_kind, scope_id, group_id, state, writer, generation,
        requested_by, approved_by, reason, change_reference,
        acceptance_digest, changed_at
    )
    SELECT domain.scope_kind, domain.scope_id, domain.domain,
           domain.state, domain.writer, domain.generation,
           domain.requested_by, domain.approved_by, domain.reason,
           domain.change_reference, domain.acceptance_digest,
           domain.changed_at
    FROM platform.domain_cutovers AS domain
    WHERE domain.scope_kind = 'tenant'
      AND domain.scope_id = p_tenant_id
      AND domain.domain = 'tenancy'
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_groups AS authority
          WHERE authority.scope_kind = domain.scope_kind
            AND authority.scope_id = domain.scope_id
            AND authority.group_id = domain.domain
      );
    INSERT INTO platform.cutover_group_members (
        scope_kind, scope_id, group_id, ordinal, domain
    )
    SELECT authority.scope_kind, authority.scope_id,
           authority.group_id, 1, authority.group_id
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.group_id = 'tenancy'
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members AS member
          WHERE member.scope_kind = authority.scope_kind
            AND member.scope_id = authority.scope_id
            AND member.group_id = authority.group_id
            AND member.domain = authority.group_id
      );
END;
$$;


ALTER FUNCTION platform.cutover_ensure_tenancy_authority_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: cutover_finalize_successor_group_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_finalize_successor_group_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE; v_group platform.cutover_groups%ROWTYPE;
    v_members jsonb; v_expected jsonb; v_changed_at timestamptz;
    v_count integer; v_authority_id uuid;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR SESSION_USER IS DISTINCT FROM 'harpy_cutover_finalizer'
       OR p_acceptance_digest !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='P5734', MESSAGE='cutover successor group authority is denied';
    END IF;
    SELECT operation.* INTO STRICT v_operation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.state='completed' AND (
        (operation.scope_kind='tenant' AND operation.group_id IN ('analytics','billing','workflow')
         AND operation.domain IN ('analytics','billing','workflow')) OR
        (operation.scope_kind='global' AND operation.group_id='billing' AND operation.domain='billing'))
    FOR SHARE;
    IF v_operation.group_id='billing' THEN
        IF v_operation.domain IS DISTINCT FROM 'billing' THEN
            RAISE EXCEPTION USING ERRCODE='P5735',
                MESSAGE='billing successor operation differs';
        END IF;
        v_expected:='["billing"]'::jsonb;
    ELSE
        IF v_operation.group_id IS DISTINCT FROM v_operation.domain THEN
            RAISE EXCEPTION USING ERRCODE='P5735',
                MESSAGE='singleton successor operation differs';
        END IF;
        v_expected:=pg_catalog.jsonb_build_array(v_operation.domain);
    END IF;
    SELECT group_row.* INTO STRICT v_group
    FROM platform.cutover_groups AS group_row
    WHERE group_row.scope_kind=v_operation.scope_kind
      AND group_row.scope_id=v_operation.scope_id
      AND group_row.group_id=v_operation.group_id
      AND group_row.state='quiescing' AND group_row.writer='none'
      AND group_row.generation=v_operation.cutover_generation
      AND group_row.approved_by IS NOT NULL
      AND group_row.approved_by IS DISTINCT FROM group_row.requested_by
    FOR UPDATE;
    SELECT pg_catalog.jsonb_agg(member.domain ORDER BY member.ordinal)
    INTO v_members FROM platform.cutover_group_members AS member
    WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
      AND member.group_id=v_group.group_id;
    IF v_members IS DISTINCT FROM v_expected THEN
        RAISE EXCEPTION USING ERRCODE='P5736',
            MESSAGE='cutover successor group members differ';
    END IF;
    v_changed_at:=pg_catalog.clock_timestamp();
    PERFORM 1 FROM platform.cutover_group_members AS member
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=member.scope_kind AND domain_row.scope_id=member.scope_id
     AND domain_row.domain=member.domain
    JOIN platform.async_v1_adoption_runs AS adoption
      ON adoption.scope_kind=member.scope_kind AND adoption.scope_id=member.scope_id
     AND adoption.group_id=member.group_id AND adoption.domain=member.domain
     AND adoption.source_generation=v_group.generation
     AND adoption.target_generation=v_group.generation+1
     AND adoption.source_group_generation=v_group.generation
     AND adoption.target_group_generation=v_group.generation+1
    JOIN platform.async_v1_zero_inventory_receipts AS zero_receipt
      ON zero_receipt.run_id=adoption.run_id
    WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
      AND member.group_id=v_group.group_id
      AND domain_row.state='quiescing' AND domain_row.writer='none'
      AND domain_row.generation=v_group.generation
      AND domain_row.requested_by=v_group.requested_by
      AND domain_row.approved_by IS NOT DISTINCT FROM v_group.approved_by
      AND domain_row.reason=v_group.reason
      AND domain_row.change_reference=v_group.change_reference
      AND adoption.state='accepted' AND adoption.item_count=0
      AND adoption.accepted_at<=v_changed_at
      AND adoption.acceptance_sha256=p_acceptance_digest
      AND zero_receipt.inventory_sha256=adoption.inventory_sha256
      AND zero_receipt.queue_count=0 AND zero_receipt.timer_count=0
      AND zero_receipt.future_count=0 AND zero_receipt.running_count=0
    ORDER BY member.ordinal
    FOR UPDATE OF domain_row FOR SHARE OF adoption,zero_receipt;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count IS DISTINCT FROM pg_catalog.jsonb_array_length(v_expected) THEN
        RAISE EXCEPTION USING ERRCODE='P5737',
            MESSAGE='cutover successor zero inventory differs';
    END IF;
    WITH targets AS (
        SELECT 'group'::text AS target_kind,NULL::text AS domain,
            v_group.requested_by AS requested_by,v_group.approved_by AS approved_by,
            v_group.reason AS reason,v_group.change_reference AS change_reference
        UNION ALL
        SELECT 'domain',domain_row.domain,domain_row.requested_by,
            domain_row.approved_by,domain_row.reason,domain_row.change_reference
        FROM platform.cutover_group_members AS member
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind=member.scope_kind
         AND domain_row.scope_id=member.scope_id AND domain_row.domain=member.domain
        WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
          AND member.group_id=v_group.group_id
    )
    INSERT INTO platform.cutover_transition_events (
        event_id,request_event_id,target_kind,event_kind,scope_kind,scope_id,
        group_id,domain,previous_state,new_state,previous_writer,new_writer,
        previous_generation,new_generation,actor_id,requested_by,approved_by,
        reason,change_reference,acceptance_digest,occurred_at
    )
    SELECT pg_catalog.uuidv7(),request.event_id,target.target_kind,'switch',
        v_group.scope_kind,v_group.scope_id,v_group.group_id,target.domain,
        'quiescing','v2','none','v2',v_group.generation,v_group.generation+1,
        target.approved_by,target.requested_by,target.approved_by,target.reason,
        target.change_reference,p_acceptance_digest,v_changed_at
    FROM targets AS target
    JOIN LATERAL (
        SELECT event.event_id FROM platform.cutover_transition_events AS event
        WHERE event.target_kind=target.target_kind AND event.event_kind='request'
          AND event.scope_kind=v_group.scope_kind AND event.scope_id=v_group.scope_id
          AND event.group_id=v_group.group_id
          AND event.domain IS NOT DISTINCT FROM target.domain
          AND event.new_state='quiescing' AND event.new_generation=v_group.generation
          AND event.requested_by=target.requested_by
          AND event.change_reference=target.change_reference
        ORDER BY event.occurred_at DESC,event.event_id DESC LIMIT 1
    ) AS request ON true;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count IS DISTINCT FROM pg_catalog.jsonb_array_length(v_expected)+1 THEN
        RAISE EXCEPTION USING ERRCODE='P5738',
            MESSAGE='cutover successor transition evidence differs';
    END IF;
    UPDATE platform.domain_cutovers AS domain_row
    SET state='v2',writer='v2',generation=domain_row.generation+1,
        acceptance_digest=p_acceptance_digest,changed_at=v_changed_at
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
      AND member.group_id=v_group.group_id
      AND domain_row.scope_kind=member.scope_kind
      AND domain_row.scope_id=member.scope_id AND domain_row.domain=member.domain
      AND domain_row.state='quiescing' AND domain_row.writer='none'
      AND domain_row.generation=v_group.generation;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count IS DISTINCT FROM pg_catalog.jsonb_array_length(v_expected) THEN
        RAISE EXCEPTION USING ERRCODE='P5739',
            MESSAGE='cutover successor domain switch lost its lock';
    END IF;
    UPDATE platform.cutover_groups AS group_row
    SET state='v2',writer='v2',generation=group_row.generation+1,
        acceptance_digest=p_acceptance_digest,changed_at=v_changed_at
    WHERE group_row.scope_kind=v_group.scope_kind AND group_row.scope_id=v_group.scope_id
      AND group_row.group_id=v_group.group_id AND group_row.state='quiescing'
      AND group_row.writer='none' AND group_row.generation=v_group.generation;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P5739',
            MESSAGE='cutover successor group switch lost its lock';
    END IF;
    IF v_group.group_id='analytics' THEN
        SELECT platform.analytics_finalize_authority_successor_v1(
            p_operation_id,p_run_id,p_acceptance_digest) INTO STRICT v_authority_id;
    ELSIF v_group.group_id='workflow' THEN
        SELECT platform.workflow_finalize_authority_successor_v1(
            p_operation_id,p_run_id,p_acceptance_digest) INTO STRICT v_authority_id;
    ELSE
        SELECT platform.billing_finalize_authority_successor_v1(
            p_operation_id,p_run_id,p_acceptance_digest) INTO STRICT v_authority_id;
    END IF;
    RETURN v_authority_id;
END;
$_$;


ALTER FUNCTION platform.cutover_finalize_successor_group_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) OWNER TO harpy_owner;

--
-- Name: cutover_initialize_tenant_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_initialize_tenant_v1(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_reference text;
    v_existing integer;
BEGIN
    v_reference := 'installation:' || p_operation_id::text;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_owner_user_id IS NULL OR p_operation_id = p_owner_user_id
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant cutover initialization denied';
    END IF;
    SELECT pg_catalog.count(*) INTO v_existing
    FROM (
        SELECT 1 FROM platform.domain_cutovers
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
        UNION ALL
        SELECT 1 FROM platform.cutover_groups
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
        UNION ALL
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
    ) AS existing;
    IF v_existing > 0 THEN
        IF (SELECT pg_catalog.count(*) FROM platform.domain_cutovers
            WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
              AND state = 'v2' AND writer = 'v2' AND generation = 1
              AND requested_by = p_operation_id AND approved_by = p_owner_user_id
              AND acceptance_digest = p_manifest_sha256
              AND change_reference = v_reference) IS DISTINCT FROM 9
           OR (SELECT pg_catalog.count(*) FROM platform.cutover_groups
               WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
                 AND group_id IN (
                    'billing','iam_system_resources','notifications'
                 )
                 AND state = 'v2' AND writer = 'v2' AND generation = 1
                 AND requested_by = p_operation_id AND approved_by = p_owner_user_id
                 AND acceptance_digest = p_manifest_sha256
                 AND change_reference = v_reference) IS DISTINCT FROM 3
           OR (SELECT pg_catalog.count(*) FROM platform.cutover_groups
               WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) IS DISTINCT FROM 3
           OR (SELECT pg_catalog.count(*) FROM platform.cutover_group_members
               WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) IS DISTINCT FROM 4
           OR (SELECT pg_catalog.count(*) FROM platform.cutover_group_members
               WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
                 AND (group_id,ordinal,domain) IN (
                    ('billing',1,'billing'),
                    ('iam_system_resources',1,'iam'),
                    ('iam_system_resources',2,'system_resource_layout'),
                    ('notifications',1,'notifications')
                 )) IS DISTINCT FROM 4 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'tenant cutover initialization replay conflicts';
        END IF;
        RETURN;
    END IF;
    INSERT INTO platform.domain_cutovers (
        scope_kind, scope_id, domain, state, writer, generation,
        requested_by, approved_by, reason, change_reference, acceptance_digest
    ) SELECT 'tenant', p_tenant_id, domain, 'v2', 'v2', 1,
        p_operation_id, p_owner_user_id, 'fresh V2 tenant activation',
        v_reference, p_manifest_sha256
      FROM pg_catalog.unnest(ARRAY[
        'analytics','billing','catalog','documents','iam','notifications',
        'system_resource_layout','work','workflow'
      ]) AS entry(domain);
    INSERT INTO platform.cutover_groups (
        scope_kind, scope_id, group_id, state, writer, generation,
        requested_by, approved_by, reason, change_reference, acceptance_digest
    ) SELECT 'tenant', p_tenant_id, group_id, 'v2', 'v2', 1,
        p_operation_id, p_owner_user_id, 'fresh V2 tenant activation',
        v_reference, p_manifest_sha256
      FROM pg_catalog.unnest(ARRAY[
        'billing','iam_system_resources','notifications'
      ]) AS entry(group_id);
    INSERT INTO platform.cutover_group_members (
        scope_kind, scope_id, group_id, ordinal, domain
    ) VALUES
        ('tenant',p_tenant_id,'billing',1,'billing'),
        ('tenant',p_tenant_id,'iam_system_resources',1,'iam'),
        ('tenant',p_tenant_id,'iam_system_resources',2,'system_resource_layout'),
        ('tenant',p_tenant_id,'notifications',1,'notifications');
END;
$_$;


ALTER FUNCTION platform.cutover_initialize_tenant_v1(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: cutover_initialize_tenant_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_initialize_tenant_v2(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_reference text;
BEGIN
    v_reference := 'installation:' || p_operation_id::text;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_owner_user_id IS NULL OR p_operation_id = p_owner_user_id
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant cutover initialization v2 denied';
    END IF;
    IF (SELECT pg_catalog.count(*) FROM platform.domain_cutovers
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) <> 9
       OR (SELECT pg_catalog.count(*) FROM platform.domain_cutovers
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
             AND domain IN (
                 'analytics','billing','catalog','documents','iam',
                 'notifications','system_resource_layout','work','workflow'
             )
             AND state = 'v2' AND writer = 'v2' AND generation = 1
             AND requested_by = p_operation_id
             AND approved_by = p_owner_user_id
             AND acceptance_digest = p_manifest_sha256
             AND change_reference = v_reference) <> 9 THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'tenant cutover initialization v2 domain conflict';
    END IF;
    INSERT INTO platform.cutover_groups (
        scope_kind, scope_id, group_id, state, writer, generation,
        requested_by, approved_by, reason, change_reference,
        acceptance_digest, changed_at
    )
    SELECT domain.scope_kind, domain.scope_id, domain.domain,
           domain.state, domain.writer, domain.generation,
           domain.requested_by, domain.approved_by, domain.reason,
           domain.change_reference, domain.acceptance_digest,
           domain.changed_at
    FROM platform.domain_cutovers AS domain
    WHERE domain.scope_kind = 'tenant' AND domain.scope_id = p_tenant_id
      AND domain.domain IN (
          'analytics', 'catalog', 'documents',
          'notifications', 'work', 'workflow'
      )
    ON CONFLICT (scope_kind, scope_id, group_id) DO NOTHING;
    INSERT INTO platform.cutover_group_members (
        scope_kind, scope_id, group_id, ordinal, domain
    )
    SELECT authority.scope_kind, authority.scope_id,
           authority.group_id, 1, authority.group_id
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.group_id IN (
          'analytics', 'catalog', 'documents',
          'notifications', 'work', 'workflow'
      )
    ON CONFLICT (scope_kind, scope_id, group_id, ordinal) DO NOTHING;
    IF (SELECT pg_catalog.count(*) FROM platform.cutover_groups
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) <> 8
       OR (SELECT pg_catalog.count(*) FROM platform.cutover_groups
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
             AND group_id IN (
                 'analytics','billing','catalog','documents',
                 'iam_system_resources','notifications','work','workflow'
             )
             AND state = 'v2' AND writer = 'v2' AND generation = 1
             AND requested_by = p_operation_id
             AND approved_by = p_owner_user_id
             AND acceptance_digest = p_manifest_sha256
             AND change_reference = v_reference) <> 8
       OR (SELECT pg_catalog.count(*) FROM platform.cutover_group_members
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) <> 9
       OR (SELECT pg_catalog.count(*) FROM platform.cutover_group_members
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
             AND (group_id,ordinal,domain) IN (
                 ('analytics',1,'analytics'),
                 ('billing',1,'billing'),
                 ('catalog',1,'catalog'),('documents',1,'documents'),
                 ('iam_system_resources',1,'iam'),
                 ('iam_system_resources',2,'system_resource_layout'),
                 ('notifications',1,'notifications'),('work',1,'work'),
                 ('workflow',1,'workflow')
             )) <> 9 THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'tenant cutover initialization v2 authority conflict';
    END IF;
END;
$_$;


ALTER FUNCTION platform.cutover_initialize_tenant_v2(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: cutover_initialize_tenant_v3(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_initialize_tenant_v3(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text, p_operation_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    PERFORM platform.cutover_initialize_tenant_v5(
        p_operation_id, p_tenant_id, p_owner_user_id,
        p_manifest_sha256, p_operation_kind
    );
END;
$$;


ALTER FUNCTION platform.cutover_initialize_tenant_v3(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text, p_operation_kind text) OWNER TO harpy_owner;

--
-- Name: cutover_initialize_tenant_v4(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_initialize_tenant_v4(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text, p_operation_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_application text;
    v_reference text;
    v_existing integer;
BEGIN
    v_application := pg_catalog.current_setting('application_name', true);
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR NOT (
           (p_operation_kind = 'environment_initialize'
            AND v_application = 'harpy-v2:core-operator-initialize')
           OR (p_operation_kind = 'saas_customer_tenant_provision'
               AND v_application = 'harpy-v2:core-worker')
       )
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_owner_user_id IS NULL OR p_operation_id = p_owner_user_id
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant cutover initialization v4 denied';
    END IF;
    IF p_operation_kind = 'environment_initialize' THEN
        PERFORM platform.cutover_initialize_tenant_v2(
            p_operation_id, p_tenant_id, p_owner_user_id, p_manifest_sha256
        );
        RETURN;
    END IF;
    v_reference := 'customer-activation:' || p_operation_id::text;
    SELECT pg_catalog.count(*) INTO v_existing
    FROM (
        SELECT 1 FROM platform.domain_cutovers
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
        UNION ALL
        SELECT 1 FROM platform.cutover_groups
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
        UNION ALL
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
    ) AS existing;
    IF v_existing = 0 THEN
        INSERT INTO platform.domain_cutovers (
            scope_kind, scope_id, domain, state, writer, generation,
            requested_by, approved_by, reason, change_reference,
            acceptance_digest
        )
        SELECT 'tenant', p_tenant_id, domain, 'v2', 'v2', 1,
            p_operation_id, p_owner_user_id, 'SaaS customer V2 activation',
            v_reference, p_manifest_sha256
        FROM pg_catalog.unnest(ARRAY[
            'analytics','billing','catalog','documents','iam',
            'notifications','system_resource_layout','work','workflow'
        ]) AS entry(domain);
        INSERT INTO platform.cutover_groups (
            scope_kind, scope_id, group_id, state, writer, generation,
            requested_by, approved_by, reason, change_reference,
            acceptance_digest
        )
        SELECT 'tenant', p_tenant_id, group_id, 'v2', 'v2', 1,
            p_operation_id, p_owner_user_id, 'SaaS customer V2 activation',
            v_reference, p_manifest_sha256
        FROM pg_catalog.unnest(ARRAY[
            'analytics','billing','catalog','documents',
            'iam_system_resources','notifications','work','workflow'
        ]) AS entry(group_id);
        INSERT INTO platform.cutover_group_members (
            scope_kind, scope_id, group_id, ordinal, domain
        ) VALUES
            ('tenant',p_tenant_id,'analytics',1,'analytics'),
            ('tenant',p_tenant_id,'billing',1,'billing'),
            ('tenant',p_tenant_id,'catalog',1,'catalog'),
            ('tenant',p_tenant_id,'documents',1,'documents'),
            ('tenant',p_tenant_id,'iam_system_resources',1,'iam'),
            ('tenant',p_tenant_id,'iam_system_resources',2,'system_resource_layout'),
            ('tenant',p_tenant_id,'notifications',1,'notifications'),
            ('tenant',p_tenant_id,'work',1,'work'),
            ('tenant',p_tenant_id,'workflow',1,'workflow');
    END IF;
    IF (SELECT pg_catalog.count(*) FROM platform.domain_cutovers
        WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
          AND domain IN (
              'analytics','billing','catalog','documents','iam',
              'notifications','system_resource_layout','work','workflow'
          )
          AND state = 'v2' AND writer = 'v2' AND generation = 1
          AND requested_by = p_operation_id AND approved_by = p_owner_user_id
          AND acceptance_digest = p_manifest_sha256
          AND change_reference = v_reference) <> 9
       OR (SELECT pg_catalog.count(*) FROM platform.domain_cutovers
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) <> 9
       OR (SELECT pg_catalog.count(*) FROM platform.cutover_groups
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
             AND group_id IN (
                 'analytics','billing','catalog','documents',
                 'iam_system_resources','notifications','work','workflow'
             )
             AND state = 'v2' AND writer = 'v2' AND generation = 1
             AND requested_by = p_operation_id AND approved_by = p_owner_user_id
             AND acceptance_digest = p_manifest_sha256
             AND change_reference = v_reference) <> 8
       OR (SELECT pg_catalog.count(*) FROM platform.cutover_groups
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) <> 8
       OR (SELECT pg_catalog.count(*) FROM platform.cutover_group_members
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id) <> 9
       OR (SELECT pg_catalog.count(*) FROM platform.cutover_group_members
           WHERE scope_kind = 'tenant' AND scope_id = p_tenant_id
             AND (group_id,ordinal,domain) IN (
                 ('analytics',1,'analytics'),
                 ('billing',1,'billing'),
                 ('catalog',1,'catalog'),('documents',1,'documents'),
                 ('iam_system_resources',1,'iam'),
                 ('iam_system_resources',2,'system_resource_layout'),
                 ('notifications',1,'notifications'),
                 ('work',1,'work'),('workflow',1,'workflow')
             )) <> 9 THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'tenant cutover initialization v4 authority conflict';
    END IF;
END;
$_$;


ALTER FUNCTION platform.cutover_initialize_tenant_v4(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text, p_operation_kind text) OWNER TO harpy_owner;

