CREATE FUNCTION platform.cutover_initialize_tenant_v5(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text, p_operation_kind text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
