    AS $$
BEGIN
    PERFORM platform.cutover_initialize_tenant_v4(
        p_operation_id, p_tenant_id, p_owner_user_id,
        p_manifest_sha256, p_operation_kind
    );
    PERFORM platform.cutover_ensure_tenancy_authority_v1(p_tenant_id);
END;
$$;


ALTER FUNCTION platform.cutover_initialize_tenant_v5(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text, p_operation_kind text) OWNER TO harpy_owner;

--
-- Name: cutover_prepare_batch_v1(uuid, uuid, text, uuid, smallint, text, integer, pg_lsn, xid8, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_prepare_batch_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_batch_ordinal integer, p_source_commit_lsn pg_lsn, p_source_xid xid8, p_batch_sha256 text, p_lease_manifest_sha256 text) RETURNS TABLE(procedure_contract_id text, procedure_oid bigint, procedure_signature text, already_applied boolean, applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_procedure platform.cutover_operation_procedures%ROWTYPE;
    v_receipt platform.cutover_batch_receipts%ROWTYPE;
    v_live_signature text;
BEGIN
    IF SESSION_USER <> 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'cutover batch prepare principal denied';
    END IF;
    SELECT operation.* INTO STRICT v_operation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id
    FOR UPDATE;
    IF v_operation.lease_manifest_sha256 IS DISTINCT FROM p_lease_manifest_sha256 OR
       v_operation.scope_kind IS DISTINCT FROM p_scope_kind OR
       v_operation.scope_id IS DISTINCT FROM p_scope_id OR
       v_operation.state NOT IN ('copying', 'shadow', 'quiescing') OR
       v_operation.lease_expires_at <= pg_catalog.clock_timestamp() OR
       NOT EXISTS (SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS checkpoint_key
           WHERE checkpoint_key.operation_id = p_operation_id
             AND checkpoint_key.run_id = p_run_id
             AND checkpoint_key.relation_ordinal = p_relation_ordinal
             AND checkpoint_key.checkpoint_key = p_checkpoint_key) OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
           WHERE role.rolname = 'harpy_adopter' AND NOT role.rolcanlogin
             AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
             AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls
             AND role.rolconnlimit = 0
             AND role.rolvaliduntil IS NOT DISTINCT FROM v_operation.lease_expires_at
             AND role.rolvaliduntil > pg_catalog.clock_timestamp()
             AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
                 WHERE membership.roleid = role.oid OR membership.member = role.oid)) OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
           WHERE role.rolname = 'harpy_cutover_decoder' AND NOT role.rolcanlogin
             AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
             AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls
             AND role.rolconnlimit = 0
             AND role.rolvaliduntil IS NOT DISTINCT FROM v_operation.lease_expires_at
             AND role.rolvaliduntil > pg_catalog.clock_timestamp()
             AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
                 WHERE membership.roleid = role.oid OR membership.member = role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'cutover operation is not apply-ready';
    END IF;

    SELECT procedure_row.* INTO STRICT v_procedure
    FROM platform.cutover_operation_procedures AS procedure_row
    WHERE procedure_row.operation_id = p_operation_id
      AND procedure_row.run_id = p_run_id
      AND procedure_row.relation_ordinal = p_relation_ordinal
      AND procedure_row.procedure_kind = 'apply';
    SELECT pg_catalog.format(
        '%I.%I(%s)', namespace.nspname, procedure_row.proname,
        pg_catalog.replace(pg_catalog.oidvectortypes(procedure_row.proargtypes), ' ', '')
    ) INTO STRICT v_live_signature
    FROM pg_catalog.pg_proc AS procedure_row
    JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid = procedure_row.pronamespace
    WHERE procedure_row.oid = v_procedure.procedure_oid::oid;
    IF v_live_signature <> v_procedure.procedure_signature THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'cutover apply procedure catalog differs';
    END IF;

    SELECT receipt.* INTO v_receipt
    FROM platform.cutover_batch_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id AND receipt.run_id = p_run_id
      AND receipt.relation_ordinal = p_relation_ordinal
      AND receipt.checkpoint_key = p_checkpoint_key
      AND receipt.batch_ordinal = p_batch_ordinal;
    IF FOUND AND (
        v_receipt.batch_sha256 <> p_batch_sha256 OR
        v_receipt.source_commit_lsn <> p_source_commit_lsn OR
        v_receipt.source_xid <> p_source_xid
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22000', MESSAGE = 'cutover batch idempotency tamper detected';
    END IF;

    RETURN QUERY SELECT
        v_procedure.procedure_contract_id,
        v_procedure.procedure_oid,
        v_procedure.procedure_signature,
        FOUND,
        CASE WHEN FOUND THEN v_receipt.applied_count ELSE NULL END,
        CASE WHEN FOUND THEN v_receipt.key_state_sha256 ELSE NULL END,
        CASE WHEN FOUND THEN v_receipt.state_sha256 ELSE NULL END;
END;
$$;


ALTER FUNCTION platform.cutover_prepare_batch_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_batch_ordinal integer, p_source_commit_lsn pg_lsn, p_source_xid xid8, p_batch_sha256 text, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: cutover_probe_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_probe_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_procedure platform.cutover_operation_procedures%ROWTYPE;
    v_receipt platform.cutover_batch_receipts%ROWTYPE;
    v_applied_count bigint;
    v_key_state_sha256 text;
    v_state_sha256 text;
    v_change_batch jsonb;
    v_actual_batch_bytes bigint;
    v_change_count integer;
BEGIN
    IF SESSION_USER <> 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'cutover composite principal denied';
    END IF;
    v_actual_batch_bytes := pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_batch_bytes OR
       v_actual_batch_bytes < 1 OR v_actual_batch_bytes > 8388608 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'cutover change batch size invalid';
    END IF;
    IF pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes), 'hex') IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22000', MESSAGE = 'cutover change batch digest differs';
    END IF;
    v_change_batch := pg_catalog.convert_from(p_change_batch_bytes, 'UTF8')::jsonb;
    v_change_count := pg_catalog.jsonb_array_length(v_change_batch->'changes');
    IF pg_catalog.octet_length(v_change_batch::text) > 8388608 OR
       (SELECT pg_catalog.array_agg(key ORDER BY key) FROM pg_catalog.jsonb_object_keys(v_change_batch) AS key)
         IS DISTINCT FROM ARRAY['changes','checkpoint_key','checkpoint_state','last_key','operation_id',
           'relation_ordinal','run_id','scope_id','scope_kind','source_position']::text[] OR
       pg_catalog.jsonb_typeof(v_change_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
          FROM pg_catalog.jsonb_object_keys(v_change_batch->'source_position') AS key)
         IS DISTINCT FROM ARRAY['batch_ordinal','commit_lsn','final_lsn','received_lsn',
           'snapshot_lsn','snapshot_name','source_xid']::text[] OR
       (pg_catalog.jsonb_typeof(v_change_batch->'last_key') IS DISTINCT FROM 'object' AND
         pg_catalog.jsonb_typeof(v_change_batch->'last_key') IS DISTINCT FROM 'null') OR
       v_change_batch->'last_key' = '{}'::jsonb OR
        pg_catalog.jsonb_typeof(v_change_batch->'changes') IS DISTINCT FROM 'array' OR
        v_change_count > 1000 OR p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
        (v_change_count = 0 AND (p_checkpoint_state IS DISTINCT FROM 'complete' OR
          p_final_lsn IS NULL OR p_commit_lsn IS DISTINCT FROM p_final_lsn)) OR
       (v_change_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (v_change_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       v_change_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (v_change_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (v_change_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal OR
       v_change_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key OR
       v_change_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       v_change_batch->'last_key' IS DISTINCT FROM p_last_key OR
       v_change_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM p_snapshot_name OR
       (v_change_batch->'source_position'->>'snapshot_lsn')::pg_lsn IS DISTINCT FROM p_snapshot_lsn OR
       (v_change_batch->'source_position'->>'received_lsn')::pg_lsn IS DISTINCT FROM p_received_lsn OR
       (v_change_batch->'source_position'->>'commit_lsn')::pg_lsn IS DISTINCT FROM p_commit_lsn OR
       (v_change_batch->'source_position'->>'final_lsn')::pg_lsn IS DISTINCT FROM p_final_lsn OR
       (v_change_batch->'source_position'->>'source_xid')::xid8 IS DISTINCT FROM p_source_xid OR
       (v_change_batch->'source_position'->>'batch_ordinal')::integer IS DISTINCT FROM p_batch_ordinal THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'cutover change batch evidence differs';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_change_batch->'changes')
          WITH ORDINALITY AS change(value, position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.array_agg(key ORDER BY key)
                 FROM pg_catalog.jsonb_object_keys(change.value) AS key)
                IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
           OR (change.value->>'ordinal')::integer IS DISTINCT FROM change.position::integer
           OR pg_catalog.jsonb_typeof(change.value->'kind') IS DISTINCT FROM 'string'
           OR change.value->>'kind' NOT IN ('insert','update','delete')
           OR pg_catalog.jsonb_typeof(change.value->'key') IS DISTINCT FROM 'object'
           OR change.value->'key' = '{}'::jsonb
           OR (change.value->>'kind' = 'insert' AND (change.value->'before' <> 'null'::jsonb OR
                pg_catalog.jsonb_typeof(change.value->'after') IS DISTINCT FROM 'object' OR change.value->'after' = '{}'::jsonb))
           OR (change.value->>'kind' = 'update' AND (pg_catalog.jsonb_typeof(change.value->'before') IS DISTINCT FROM 'object' OR
                change.value->'before' = '{}'::jsonb OR pg_catalog.jsonb_typeof(change.value->'after') IS DISTINCT FROM 'object' OR change.value->'after' = '{}'::jsonb))
           OR (change.value->>'kind' = 'delete' AND (pg_catalog.jsonb_typeof(change.value->'before') IS DISTINCT FROM 'object' OR
                change.value->'before' = '{}'::jsonb OR change.value->'after' <> 'null'::jsonb))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'cutover change batch shape differs';
    END IF;
    SELECT operation.* INTO STRICT v_operation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id
    FOR UPDATE;
    IF v_operation.lease_manifest_sha256 IS DISTINCT FROM p_lease_manifest_sha256 OR
       v_operation.scope_kind IS DISTINCT FROM p_scope_kind OR
       v_operation.scope_id IS DISTINCT FROM p_scope_id OR
       v_operation.state NOT IN ('copying', 'shadow', 'quiescing') OR
       v_operation.lease_expires_at <= pg_catalog.clock_timestamp() OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
           WHERE role.rolname = 'harpy_adopter' AND NOT role.rolcanlogin
             AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
             AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls
             AND role.rolconnlimit = 0
              AND role.rolvaliduntil IS NOT DISTINCT FROM v_operation.lease_expires_at
              AND role.rolvaliduntil > pg_catalog.clock_timestamp()
              AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
                  WHERE membership.roleid = role.oid OR membership.member = role.oid)) OR
       NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles AS role
           WHERE role.rolname = 'harpy_cutover_decoder' AND NOT role.rolcanlogin
             AND NOT role.rolinherit AND NOT role.rolsuper AND NOT role.rolcreatedb
             AND NOT role.rolcreaterole AND NOT role.rolreplication AND NOT role.rolbypassrls
             AND role.rolconnlimit = 0
             AND role.rolvaliduntil IS NOT DISTINCT FROM v_operation.lease_expires_at
             AND role.rolvaliduntil > pg_catalog.clock_timestamp()
             AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership
                 WHERE membership.roleid = role.oid OR membership.member = role.oid)) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'cutover operation is not apply-ready';
    END IF;
    SELECT procedure_row.* INTO STRICT v_procedure
    FROM platform.cutover_operation_procedures AS procedure_row
    WHERE procedure_row.operation_id = p_operation_id
      AND procedure_row.run_id = p_run_id
      AND procedure_row.relation_ordinal = p_relation_ordinal
      AND procedure_row.procedure_kind = 'apply';
    IF v_procedure.procedure_contract_id <> 'platform.cutover_probe.v1' OR
       v_procedure.procedure_oid <> 'platform.cutover_probe_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure.procedure_signature <> 'platform.cutover_probe_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'cutover composite procedure binding differs';
    END IF;
    SELECT receipt.* INTO v_receipt
    FROM platform.cutover_batch_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id AND receipt.run_id = p_run_id
      AND receipt.relation_ordinal = p_relation_ordinal
      AND receipt.checkpoint_key = p_checkpoint_key
      AND receipt.batch_ordinal = p_batch_ordinal;
    IF FOUND THEN
        IF v_receipt.batch_sha256 <> p_batch_sha256 OR
           v_receipt.source_commit_lsn <> p_commit_lsn OR
           v_receipt.source_xid <> p_source_xid THEN
            RAISE EXCEPTION USING ERRCODE = '22000', MESSAGE = 'cutover composite idempotency tamper detected';
        END IF;
        RETURN QUERY SELECT v_receipt.applied_count,
            v_receipt.key_state_sha256, v_receipt.state_sha256;
        RETURN;
    END IF;
    SELECT result.applied_count, result.key_state_sha256, result.state_sha256
    INTO STRICT v_applied_count, v_key_state_sha256, v_state_sha256
    FROM platform.cutover_probe_apply_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id, p_relation_ordinal,
        p_checkpoint_key, p_snapshot_lsn, p_received_lsn, p_commit_lsn,
        p_source_xid, p_batch_ordinal, v_change_batch, p_batch_sha256
    ) AS result;
    IF v_applied_count < 0 OR v_key_state_sha256 !~ '^[0-9a-f]{64}$' OR
       v_state_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22000', MESSAGE = 'cutover owner result invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key,
        p_snapshot_name, p_snapshot_lsn, p_received_lsn, p_commit_lsn,
        p_final_lsn, p_source_xid, p_batch_ordinal, p_checkpoint_state,
        p_last_key, p_batch_sha256, p_batch_bytes, v_applied_count,
        v_key_state_sha256, v_state_sha256
    );
    RETURN QUERY SELECT v_applied_count, v_key_state_sha256, v_state_sha256;
END;
$_$;


ALTER FUNCTION platform.cutover_probe_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: cutover_probe_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_probe_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing text;
    v_count bigint;
    v_manifest_sha256 text;
BEGIN
    IF SESSION_USER <> 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'cutover probe apply principal denied';
    END IF;
    IF p_operation_id IS NULL OR p_run_id IS NULL OR p_scope_kind IS NULL OR
       p_scope_id IS NULL OR p_relation_ordinal IS NULL OR p_checkpoint_key IS NULL OR
       p_scope_kind NOT IN ('global', 'tenant') OR p_received_lsn < p_commit_lsn OR
       p_snapshot_lsn > p_commit_lsn OR p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.octet_length(p_change_batch::text) > 8388608 OR
       pg_catalog.jsonb_typeof(p_change_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(p_change_batch->'changes') > 1000 OR
       (pg_catalog.jsonb_array_length(p_change_batch->'changes') = 0 AND
         (p_change_batch->>'checkpoint_state' IS DISTINCT FROM 'complete' OR
          p_change_batch->'source_position'->>'final_lsn' IS NULL OR
          (p_change_batch->'source_position'->>'final_lsn')::pg_lsn IS DISTINCT FROM p_commit_lsn)) OR
       EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements(p_change_batch->'changes') AS change(value)
           WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
              OR pg_catalog.jsonb_typeof(change.value->'kind') IS DISTINCT FROM 'string'
              OR change.value->>'kind' NOT IN ('insert','update','delete')
       ) OR
       p_change_batch->>'operation_id' IS DISTINCT FROM p_operation_id::text OR
       p_change_batch->>'run_id' IS DISTINCT FROM p_run_id::text OR
       p_change_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       p_change_batch->>'scope_id' IS DISTINCT FROM p_scope_id::text OR
       (p_change_batch->>'relation_ordinal')::integer IS DISTINCT FROM p_relation_ordinal OR
       p_change_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'cutover probe apply binding differs';
    END IF;

    INSERT INTO platform.cutover_contract_probe_rows (
        operation_id, run_id, relation_ordinal, checkpoint_key,
        batch_ordinal, batch_sha256, canonical_payload
    ) VALUES (
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key,
        p_batch_ordinal, p_batch_sha256, p_change_batch
    ) ON CONFLICT DO NOTHING;

    SELECT row.batch_sha256 INTO v_existing
    FROM platform.cutover_contract_probe_rows AS row
    WHERE row.operation_id = p_operation_id AND row.run_id = p_run_id
      AND row.relation_ordinal = p_relation_ordinal
      AND row.checkpoint_key = p_checkpoint_key AND row.batch_ordinal = p_batch_ordinal;
    IF v_existing IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22000', MESSAGE = 'cutover probe batch tamper detected';
    END IF;

    v_count := pg_catalog.jsonb_array_length(p_change_batch->'changes');
    SELECT operation.lease_manifest_sha256 INTO STRICT v_manifest_sha256
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id;
    INSERT INTO platform.applied_change_receipts (
        receipt_id, operation_id, run_id, manifest_sha256, source_xid,
        source_commit_lsn, relation_ordinal, change_ordinal, checkpoint_key,
        mutation_kind, mutation_sha256, applied_at
    ) SELECT pg_catalog.gen_random_uuid(), p_operation_id, p_run_id, v_manifest_sha256,
        p_source_xid, p_commit_lsn, p_relation_ordinal,
        (((p_batch_ordinal - 1)::bigint * 1000) + change.position)::integer,
        p_checkpoint_key, change.value->>'kind',
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            p_batch_sha256 || ':' || change.position::text, 'UTF8')), 'hex'),
        pg_catalog.clock_timestamp()
    FROM pg_catalog.jsonb_array_elements(p_change_batch->'changes')
        WITH ORDINALITY AS change(value, position)
    ;
    RETURN QUERY SELECT
        v_count,
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            COALESCE((p_change_batch->'last_key')::text, 'null'), 'UTF8'
        )), 'hex'),
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            p_change_batch::text || ':' || v_count::text, 'UTF8'
        )), 'hex');
END;
$_$;


ALTER FUNCTION platform.cutover_probe_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: cutover_record_batch_v1(uuid, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, text, bigint, bigint, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_record_batch_v1(p_operation_id uuid, p_run_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_batch_sha256 text, p_applied_bytes bigint, p_applied_count bigint, p_key_state_sha256 text, p_state_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_manifest_sha256 text;
BEGIN
    IF SESSION_USER <> 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'cutover batch receipt principal denied';
    END IF;
    IF p_applied_count < 0 OR p_applied_bytes < 1 OR p_batch_ordinal < 1 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       p_key_state_sha256 !~ '^[0-9a-f]{64}$' OR
       p_state_sha256 !~ '^[0-9a-f]{64}$' OR
       p_checkpoint_state NOT IN ('initial_copy', 'delta', 'complete') OR
       p_snapshot_lsn > p_commit_lsn OR p_commit_lsn > p_received_lsn OR
       (p_checkpoint_state = 'complete') <> (p_final_lsn IS NOT NULL) OR
       (p_final_lsn IS NOT NULL AND p_commit_lsn < p_final_lsn) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'cutover batch receipt input invalid';
    END IF;
    SELECT operation.lease_manifest_sha256 INTO STRICT v_manifest_sha256
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id
    FOR UPDATE;

    INSERT INTO platform.cutover_batch_receipts (
        operation_id, run_id, relation_ordinal, checkpoint_key, batch_ordinal,
        source_xid, source_commit_lsn, batch_sha256, applied_count,
        key_state_sha256, state_sha256
    ) VALUES (
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key, p_batch_ordinal,
        p_source_xid, p_commit_lsn, p_batch_sha256, p_applied_count,
        p_key_state_sha256, p_state_sha256
    );

    INSERT INTO platform.cutover_copy_checkpoints (
        operation_id, run_id, relation_ordinal, checkpoint_key, manifest_sha256,
        snapshot_name, snapshot_lsn, last_key, received_lsn, applied_lsn, final_lsn,
        applied_rows, applied_bytes, attempt, state, blocked_reason
    ) VALUES (
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key, v_manifest_sha256,
        p_snapshot_name, p_snapshot_lsn, p_last_key, p_received_lsn, p_commit_lsn, p_final_lsn,
        p_applied_count, p_applied_bytes, 1, p_checkpoint_state, NULL
    ) ON CONFLICT (operation_id, run_id, relation_ordinal, checkpoint_key) DO UPDATE
    SET last_key = EXCLUDED.last_key,
        received_lsn = EXCLUDED.received_lsn,
        applied_lsn = EXCLUDED.applied_lsn,
        final_lsn = EXCLUDED.final_lsn,
        applied_rows = platform.cutover_copy_checkpoints.applied_rows + EXCLUDED.applied_rows,
        applied_bytes = platform.cutover_copy_checkpoints.applied_bytes + EXCLUDED.applied_bytes,
        attempt = platform.cutover_copy_checkpoints.attempt + 1,
        state = EXCLUDED.state,
        blocked_reason = NULL,
        updated_at = pg_catalog.clock_timestamp()
    WHERE platform.cutover_copy_checkpoints.manifest_sha256 = EXCLUDED.manifest_sha256
      AND platform.cutover_copy_checkpoints.snapshot_name = EXCLUDED.snapshot_name
      AND platform.cutover_copy_checkpoints.snapshot_lsn = EXCLUDED.snapshot_lsn
      AND platform.cutover_copy_checkpoints.applied_lsn <= EXCLUDED.applied_lsn
      AND platform.cutover_copy_checkpoints.received_lsn <= EXCLUDED.received_lsn;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '22000', MESSAGE = 'cutover checkpoint regression detected';
    END IF;
END;
$_$;


ALTER FUNCTION platform.cutover_record_batch_v1(p_operation_id uuid, p_run_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_batch_sha256 text, p_applied_bytes bigint, p_applied_count bigint, p_key_state_sha256 text, p_state_sha256 text) OWNER TO harpy_owner;

--
-- Name: cutover_reject_delete(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_reject_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING
        ERRCODE = '55000',
        MESSAGE = pg_catalog.format(
            'delete is forbidden for immutable cutover relation %I.%I',
            TG_TABLE_SCHEMA,
            TG_TABLE_NAME
        );
    RETURN OLD;
END;
$$;


ALTER FUNCTION platform.cutover_reject_delete() OWNER TO harpy_owner;

--
-- Name: cutover_reject_mutation(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING
        ERRCODE = '55000',
        MESSAGE = pg_catalog.format(
            '%s is forbidden for append-only cutover relation %I.%I',
            TG_OP,
            TG_TABLE_SCHEMA,
            TG_TABLE_NAME
        );
    RETURN OLD;
END;
$$;


ALTER FUNCTION platform.cutover_reject_mutation() OWNER TO harpy_owner;

--
-- Name: cutover_require_domain_transition_event(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_require_domain_transition_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM platform.cutover_transition_events AS event
        WHERE event.event_xid = pg_catalog.pg_current_xact_id()
          AND event.target_kind = 'domain'
          AND event.scope_kind = NEW.scope_kind
          AND event.scope_id = NEW.scope_id
          AND event.domain = NEW.domain
          AND event.previous_state = OLD.state
          AND event.new_state = NEW.state
          AND event.previous_writer = OLD.writer
          AND event.new_writer = NEW.writer
          AND event.previous_generation = OLD.generation
          AND event.new_generation = NEW.generation
          AND event.requested_by = NEW.requested_by
          AND event.approved_by IS NOT DISTINCT FROM NEW.approved_by
          AND event.reason = NEW.reason
          AND event.change_reference = NEW.change_reference
          AND event.acceptance_digest IS NOT DISTINCT FROM NEW.acceptance_digest
          AND event.occurred_at = NEW.changed_at
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'domain cutover update requires matching immutable transition evidence';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM platform.cutover_group_members AS member
        JOIN platform.cutover_groups AS cutover_group
          ON cutover_group.scope_kind = member.scope_kind
         AND cutover_group.scope_id = member.scope_id
         AND cutover_group.group_id = member.group_id
        WHERE member.scope_kind = NEW.scope_kind
          AND member.scope_id = NEW.scope_id
          AND member.domain = NEW.domain
          AND cutover_group.state = NEW.state
          AND cutover_group.writer = NEW.writer
          AND cutover_group.generation = NEW.generation
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'domain cutover update must remain synchronized with its cutover group';
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.cutover_require_domain_transition_event() OWNER TO harpy_owner;

--
-- Name: cutover_require_group_transition_event(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_require_group_transition_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM platform.cutover_transition_events AS event
        WHERE event.event_xid = pg_catalog.pg_current_xact_id()
          AND event.target_kind = 'group'
          AND event.scope_kind = NEW.scope_kind
          AND event.scope_id = NEW.scope_id
          AND event.group_id = NEW.group_id
          AND event.previous_state = OLD.state
          AND event.new_state = NEW.state
          AND event.previous_writer = OLD.writer
          AND event.new_writer = NEW.writer
          AND event.previous_generation = OLD.generation
          AND event.new_generation = NEW.generation
          AND event.requested_by = NEW.requested_by
          AND event.approved_by IS NOT DISTINCT FROM NEW.approved_by
          AND event.reason = NEW.reason
          AND event.change_reference = NEW.change_reference
          AND event.acceptance_digest IS NOT DISTINCT FROM NEW.acceptance_digest
          AND event.occurred_at = NEW.changed_at
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'cutover group update requires matching immutable transition evidence';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM platform.cutover_group_members AS member
        WHERE member.scope_kind = NEW.scope_kind
          AND member.scope_id = NEW.scope_id
          AND member.group_id = NEW.group_id
    ) OR EXISTS (
        SELECT 1
        FROM platform.cutover_group_members AS member
        JOIN platform.domain_cutovers AS domain_cutover
          ON domain_cutover.scope_kind = member.scope_kind
         AND domain_cutover.scope_id = member.scope_id
         AND domain_cutover.domain = member.domain
        WHERE member.scope_kind = NEW.scope_kind
          AND member.scope_id = NEW.scope_id
          AND member.group_id = NEW.group_id
          AND (
              domain_cutover.state <> NEW.state OR
              domain_cutover.writer <> NEW.writer OR
              domain_cutover.generation <> NEW.generation
          )
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'cutover group update must atomically synchronize every member domain';
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.cutover_require_group_transition_event() OWNER TO harpy_owner;

--
-- Name: cutover_runtime_lock_domain_v1(text, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_runtime_lock_domain_v1(p_scope_kind text, p_scope_id uuid, p_domain text) RETURNS TABLE(state text, writer text, generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Cutover runtime domain lock denied';
    END IF;
    RETURN QUERY SELECT domain_row.state, domain_row.writer, domain_row.generation
    FROM platform.domain_cutovers AS domain_row
    WHERE domain_row.scope_kind = p_scope_kind
      AND domain_row.scope_id = p_scope_id
      AND domain_row.domain = p_domain
    ORDER BY domain_row.scope_kind COLLATE "C", domain_row.scope_id,
        domain_row.domain COLLATE "C"
    FOR SHARE;
END;
$$;


ALTER FUNCTION platform.cutover_runtime_lock_domain_v1(p_scope_kind text, p_scope_id uuid, p_domain text) OWNER TO harpy_owner;

--
-- Name: cutover_runtime_lock_group_members_v1(text, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_runtime_lock_group_members_v1(p_scope_kind text, p_scope_id uuid, p_group_id text) RETURNS TABLE(domain text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Cutover runtime group member lock denied';
    END IF;
    RETURN QUERY SELECT member.domain
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind = p_scope_kind
      AND member.scope_id = p_scope_id
      AND member.group_id = p_group_id
    ORDER BY member.domain COLLATE "C"
    FOR SHARE;
END;
$$;


ALTER FUNCTION platform.cutover_runtime_lock_group_members_v1(p_scope_kind text, p_scope_id uuid, p_group_id text) OWNER TO harpy_owner;

--
-- Name: cutover_runtime_lock_group_v1(text, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_runtime_lock_group_v1(p_scope_kind text, p_scope_id uuid, p_group_id text) RETURNS TABLE(state text, writer text, generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
