--
-- Name: cutover_successor_finalize_transition_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_successor_finalize_transition_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_receipt cutover_authority.finalization_receipts%ROWTYPE;
    v_verified boolean;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR TG_TABLE_SCHEMA IS DISTINCT FROM 'platform'
       OR TG_TABLE_NAME IS DISTINCT FROM 'cutover_operations' THEN
        RAISE EXCEPTION USING ERRCODE='P5740',
            MESSAGE='cutover successor finalizer trigger target differs';
    END IF;
    IF OLD.state IS DISTINCT FROM 'quiescing' OR NEW.state IS DISTINCT FROM 'completed'
       OR NEW.group_id NOT IN ('analytics','billing','workflow') THEN
        RETURN NEW;
    END IF;
    IF NEW.scope_kind NOT IN ('global','tenant')
       OR (NEW.scope_kind='global'
           AND (NEW.group_id<>'billing' OR NEW.domain<>'billing'))
       OR (NEW.scope_kind='tenant' AND NEW.group_id='billing')
       OR NEW.operation_id IS DISTINCT FROM OLD.operation_id
       OR NEW.run_id IS DISTINCT FROM OLD.run_id
       OR NEW.scope_id IS DISTINCT FROM OLD.scope_id
       OR NEW.group_id IS DISTINCT FROM OLD.group_id
       OR NEW.domain IS DISTINCT FROM OLD.domain
       OR NEW.cutover_generation IS DISTINCT FROM OLD.cutover_generation THEN
        RAISE EXCEPTION USING ERRCODE='P5741',
            MESSAGE='cutover successor completed transition differs';
    END IF;
    SELECT receipt.* INTO STRICT v_receipt
    FROM cutover_authority.finalization_receipts AS receipt
    WHERE receipt.operation_id=NEW.operation_id AND receipt.run_id=NEW.run_id
      AND receipt.terminal_state='completed';
    SELECT cutover_authority.verify_finalization_receipt_v1(
        NEW.operation_id,NEW.run_id,v_receipt.finalizer_lease_id,
        'completed',v_receipt.terminal_evidence_sha256) INTO STRICT v_verified;
    IF NOT v_verified THEN
        RAISE EXCEPTION USING ERRCODE='P5742',
            MESSAGE='cutover successor protected receipt differs';
    END IF;
    PERFORM platform.cutover_finalize_successor_group_v1(
        NEW.operation_id,NEW.run_id,v_receipt.terminal_evidence_sha256);
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.cutover_successor_finalize_transition_v1() OWNER TO harpy_owner;

--
-- Name: cutover_sync_singleton_authority_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.cutover_sync_singleton_authority_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.scope_kind <> 'tenant'
       OR NEW.domain NOT IN (
           'analytics', 'catalog', 'documents', 'work', 'workflow'
       ) THEN
        RETURN NEW;
    END IF;
    INSERT INTO platform.cutover_groups (
        scope_kind, scope_id, group_id, state, writer, generation,
        requested_by, approved_by, reason, change_reference,
        acceptance_digest, changed_at
    ) VALUES (
        NEW.scope_kind, NEW.scope_id, NEW.domain,
        NEW.state, NEW.writer, NEW.generation,
        NEW.requested_by, NEW.approved_by, NEW.reason,
        NEW.change_reference, NEW.acceptance_digest, NEW.changed_at
    )
    ON CONFLICT (scope_kind, scope_id, group_id) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM platform.cutover_groups AS authority
        WHERE authority.scope_kind = NEW.scope_kind
          AND authority.scope_id = NEW.scope_id
          AND authority.group_id = NEW.domain
          AND authority.state IS NOT DISTINCT FROM NEW.state
          AND authority.writer IS NOT DISTINCT FROM NEW.writer
          AND authority.generation IS NOT DISTINCT FROM NEW.generation
          AND authority.requested_by IS NOT DISTINCT FROM NEW.requested_by
          AND authority.approved_by IS NOT DISTINCT FROM NEW.approved_by
          AND authority.reason IS NOT DISTINCT FROM NEW.reason
          AND authority.change_reference IS NOT DISTINCT FROM NEW.change_reference
          AND authority.acceptance_digest IS NOT DISTINCT FROM NEW.acceptance_digest
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'tenant singleton cutover group conflicts';
    END IF;
    INSERT INTO platform.cutover_group_members (
        scope_kind, scope_id, group_id, ordinal, domain
    ) VALUES (
        NEW.scope_kind, NEW.scope_id, NEW.domain, 1, NEW.domain
    )
    ON CONFLICT (scope_kind, scope_id, group_id, ordinal) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members AS member
        WHERE member.scope_kind = NEW.scope_kind
          AND member.scope_id = NEW.scope_id
          AND member.group_id = NEW.domain
          AND member.ordinal = 1
          AND member.domain = NEW.domain
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'tenant singleton cutover member conflicts';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.cutover_sync_singleton_authority_v1() OWNER TO harpy_owner;

--
-- Name: iam_assert_current_tenant_authority_v1(uuid, bigint, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_assert_current_tenant_authority_v1(p_tenant_id uuid, p_group_generation bigint, p_cutover_generation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_group_state text;
    v_group_writer text;
    v_group_generation bigint;
    v_domain_state text;
    v_domain_writer text;
    v_domain_generation bigint;
    v_layout_state text;
    v_layout_writer text;
    v_layout_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_group_generation IS NULL OR
       p_cutover_generation IS NULL OR
       p_group_generation OPERATOR(pg_catalog.<) 1 OR
       p_cutover_generation OPERATOR(pg_catalog.<) 1 OR
       p_group_generation IS DISTINCT FROM p_cutover_generation THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM tenant authority input is invalid';
    END IF;

    SELECT authority.state, authority.writer, authority.generation
    INTO v_group_state, v_group_writer, v_group_generation
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind OPERATOR(pg_catalog.=) 'tenant'
      AND authority.scope_id OPERATOR(pg_catalog.=) p_tenant_id
      AND authority.group_id OPERATOR(pg_catalog.=) 'iam_system_resources';
    IF NOT FOUND OR v_group_state IS DISTINCT FROM 'v2' OR
       v_group_writer IS DISTINCT FROM 'v2' OR
       v_group_generation IS DISTINCT FROM p_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5701',
            MESSAGE = 'IAM cutover group authority is not current V2';
    END IF;

    SELECT authority.state, authority.writer, authority.generation
    INTO v_domain_state, v_domain_writer, v_domain_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind OPERATOR(pg_catalog.=) 'tenant'
      AND authority.scope_id OPERATOR(pg_catalog.=) p_tenant_id
      AND authority.domain OPERATOR(pg_catalog.=) 'iam';
    IF NOT FOUND OR v_domain_state IS DISTINCT FROM 'v2' OR
       v_domain_writer IS DISTINCT FROM 'v2' OR
       v_domain_generation IS DISTINCT FROM p_cutover_generation OR
       v_domain_generation IS DISTINCT FROM v_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5702',
            MESSAGE = 'IAM domain authority is not current V2';
    END IF;

    SELECT authority.state, authority.writer, authority.generation
    INTO v_layout_state, v_layout_writer, v_layout_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind OPERATOR(pg_catalog.=) 'tenant'
      AND authority.scope_id OPERATOR(pg_catalog.=) p_tenant_id
      AND authority.domain OPERATOR(pg_catalog.=) 'system_resource_layout';
    IF NOT FOUND OR v_layout_state IS DISTINCT FROM 'v2' OR
       v_layout_writer IS DISTINCT FROM 'v2' OR
       v_layout_generation IS DISTINCT FROM v_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5703',
            MESSAGE = 'IAM layout domain authority is not current V2';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members AS member
        WHERE member.scope_kind OPERATOR(pg_catalog.=) 'tenant'
          AND member.scope_id OPERATOR(pg_catalog.=) p_tenant_id
          AND member.group_id OPERATOR(pg_catalog.=) 'iam_system_resources'
          AND member.ordinal OPERATOR(pg_catalog.=) 1
          AND member.domain OPERATOR(pg_catalog.=) 'iam'
    ) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members AS member
        WHERE member.scope_kind OPERATOR(pg_catalog.=) 'tenant'
          AND member.scope_id OPERATOR(pg_catalog.=) p_tenant_id
          AND member.group_id OPERATOR(pg_catalog.=) 'iam_system_resources'
          AND member.ordinal OPERATOR(pg_catalog.=) 2
          AND member.domain OPERATOR(pg_catalog.=) 'system_resource_layout'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5704',
            MESSAGE = 'IAM system-resource group membership is invalid';
    END IF;
END;
$$;


ALTER FUNCTION platform.iam_assert_current_tenant_authority_v1(p_tenant_id uuid, p_group_generation bigint, p_cutover_generation bigint) OWNER TO harpy_owner;

--
-- Name: iam_auth_throttle_blocked_v2(text, uuid, text, text, text, bytea, bigint, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_auth_throttle_blocked_v2(p_scope_kind text, p_tenant_id uuid, p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_group_generation bigint, p_cutover_generation bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_scope_id uuid; v_epoch bigint;
    v_window integer; v_after integer; v_seconds integer;
    v_blocked_until timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind NOT IN ('tenant','environment') OR
       p_purpose NOT IN ('login','refresh') OR
       NOT platform.iam_hmac_key_id_valid_v1(p_key_id) OR
       pg_catalog.octet_length(p_bucket_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM throttle admission input is invalid';
    END IF;
    v_window := 300; v_seconds := 900;
    v_after := CASE p_dimension WHEN 'identifier' THEN 5 WHEN 'selector' THEN 5
        WHEN 'identifier_ip' THEN 10 WHEN 'tenant_slug' THEN 30
        WHEN 'ip' THEN 100 END;
    IF v_after IS NULL OR NOT platform.iam_auth_throttle_policy_v1(
        p_scope_kind,p_purpose,p_dimension,1,v_window,v_after,v_seconds
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM throttle admission policy is invalid';
    END IF;
    IF p_scope_kind = 'tenant' THEN
        IF p_tenant_id IS NULL OR p_group_generation IS NULL OR
           p_cutover_generation IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501',
                MESSAGE = 'IAM tenant throttle authority is invalid';
        END IF;
        PERFORM platform.iam_assert_current_tenant_authority_v1(
            p_tenant_id,p_group_generation,p_cutover_generation
        );
        v_scope_id := p_tenant_id; v_epoch := p_group_generation;
    ELSE
        IF p_tenant_id IS NOT NULL OR p_group_generation IS NOT NULL OR
           p_cutover_generation IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501',
                MESSAGE = 'IAM environment throttle authority is invalid';
        END IF;
        SELECT identity.environment_id INTO STRICT v_scope_id
        FROM platform.environment_identity AS identity;
        v_epoch := 0;
    END IF;
    SELECT bucket.blocked_until INTO v_blocked_until
    FROM platform.iam_auth_throttle_buckets AS bucket
    WHERE bucket.bucket_scope_kind = p_scope_kind
      AND bucket.scope_id = v_scope_id AND bucket.purpose = p_purpose
      AND bucket.dimension = p_dimension AND bucket.key_id = p_key_id
      AND bucket.bucket_hmac = p_bucket_hmac
      AND (p_scope_kind = 'environment' OR bucket.authority_epoch <= v_epoch)
    ORDER BY bucket.authority_epoch DESC LIMIT 1;
    RETURN v_blocked_until IS NOT NULL AND
        v_blocked_until > pg_catalog.clock_timestamp();
END;
$$;


ALTER FUNCTION platform.iam_auth_throttle_blocked_v2(p_scope_kind text, p_tenant_id uuid, p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_group_generation bigint, p_cutover_generation bigint) OWNER TO harpy_owner;

--
-- Name: iam_auth_throttle_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_auth_throttle_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'iam_auth_throttle_buckets' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM throttle session authority is invalid';
    END IF;
    IF TG_OP OPERATOR(pg_catalog.=) 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM throttle deletion is forbidden';
    END IF;

    IF NEW.bucket_scope_kind OPERATOR(pg_catalog.=) 'tenant' THEN
        PERFORM platform.iam_assert_current_tenant_authority_v1(
            NEW.tenant_id,
            NEW.authority_group_generation,
            NEW.cutover_generation
        );
    ELSE
        PERFORM 1
        FROM platform.environment_identity AS environment
        WHERE environment.environment_id
            OPERATOR(pg_catalog.=) NEW.environment_id
          AND NEW.scope_id OPERATOR(pg_catalog.=) NEW.environment_id
        FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = 'P5721',
                MESSAGE = 'IAM throttle environment identity is missing';
        END IF;
    END IF;
    IF TG_OP OPERATOR(pg_catalog.=) 'INSERT' THEN
        RETURN NEW;
    END IF;

    IF NEW.bucket_scope_kind IS DISTINCT FROM OLD.bucket_scope_kind OR
       NEW.scope_id IS DISTINCT FROM OLD.scope_id OR
       NEW.purpose IS DISTINCT FROM OLD.purpose OR
       NEW.dimension IS DISTINCT FROM OLD.dimension OR
       NEW.key_id IS DISTINCT FROM OLD.key_id OR
       NEW.bucket_hmac IS DISTINCT FROM OLD.bucket_hmac OR
       NEW.authority_epoch IS DISTINCT FROM OLD.authority_epoch OR
       NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
       NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR
       NEW.authority_scope_kind IS DISTINCT FROM OLD.authority_scope_kind OR
       NEW.authority_scope_id IS DISTINCT FROM OLD.authority_scope_id OR
       NEW.authority_group_id IS DISTINCT FROM OLD.authority_group_id OR
       NEW.authority_group_generation IS DISTINCT FROM
           OLD.authority_group_generation OR
       NEW.authority_domain IS DISTINCT FROM OLD.authority_domain OR
       NEW.cutover_generation IS DISTINCT FROM OLD.cutover_generation THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM throttle identity is immutable';
    END IF;

    IF NEW.revision IS DISTINCT FROM
           OLD.revision OPERATOR(pg_catalog.+) 1 OR
       NEW.last_attempt_at OPERATOR(pg_catalog.<=) OLD.last_attempt_at OR
       NEW.retain_until OPERATOR(pg_catalog.<) OLD.retain_until OR
       NEW.policy_version OPERATOR(pg_catalog.<) OLD.policy_version THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM throttle state must advance monotonically';
    END IF;

    IF OLD.blocked_until IS NOT NULL AND
       OLD.blocked_until OPERATOR(pg_catalog.>) NEW.last_attempt_at AND
       (
           NEW.blocked_until IS NULL OR
           NEW.blocked_until OPERATOR(pg_catalog.<) OLD.blocked_until
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM throttle active block cannot shrink';
    END IF;

    IF NEW.window_start IS NOT DISTINCT FROM OLD.window_start AND
       NEW.window_end IS NOT DISTINCT FROM OLD.window_end THEN
        IF NEW.policy_version IS DISTINCT FROM OLD.policy_version OR
           NEW.attempt_count IS DISTINCT FROM
               OLD.attempt_count OPERATOR(pg_catalog.+) 1 OR
           (
               OLD.blocked_until IS NOT NULL AND
               (
                   NEW.blocked_until IS NULL OR
                   NEW.blocked_until OPERATOR(pg_catalog.<) OLD.blocked_until
               )
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'IAM throttle active window update is invalid';
        END IF;
    ELSIF NEW.window_start OPERATOR(pg_catalog.<=) OLD.window_start OR
          (
              NEW.policy_version OPERATOR(pg_catalog.=) OLD.policy_version AND
              NEW.window_start OPERATOR(pg_catalog.<) OLD.window_end
          ) OR
          NEW.attempt_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM throttle window reset is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_auth_throttle_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_auth_throttle_policy_v1(text, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_auth_throttle_policy_v1(p_scope_kind text, p_purpose text, p_dimension text, p_policy_version integer, p_window_seconds integer, p_block_after integer, p_block_seconds integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
SELECT
    p_policy_version IS NOT DISTINCT FROM 1 AND
    p_window_seconds IS NOT DISTINCT FROM CASE
        WHEN p_purpose OPERATOR(pg_catalog.=) ANY (
            ARRAY['login','refresh','reauth']::text[]
        ) THEN 300
        WHEN p_purpose OPERATOR(pg_catalog.=) ANY (
            ARRAY['password_reset','email_verification',
                  'portal_setup','invitation']::text[]
        ) THEN 900
    END AND
    p_block_seconds IS NOT DISTINCT FROM CASE
        WHEN p_purpose OPERATOR(pg_catalog.=) ANY (
            ARRAY['login','refresh','reauth']::text[]
        ) THEN 900
        WHEN p_purpose OPERATOR(pg_catalog.=) ANY (
            ARRAY['password_reset','email_verification',
                  'portal_setup','invitation']::text[]
        ) THEN 3600
    END AND
    p_block_after IS NOT DISTINCT FROM CASE
        WHEN p_purpose OPERATOR(pg_catalog.=) ANY (
                 ARRAY['login','refresh','reauth']::text[]
             ) AND p_dimension OPERATOR(pg_catalog.=) ANY (
                 ARRAY['identifier','selector']::text[]
             ) THEN 5
        WHEN p_purpose OPERATOR(pg_catalog.=) ANY (
                 ARRAY['password_reset','email_verification',
                       'portal_setup','invitation']::text[]
             ) AND p_dimension OPERATOR(pg_catalog.=) 'identifier' THEN 3
        WHEN p_dimension OPERATOR(pg_catalog.=) 'identifier_ip' THEN 10
        WHEN p_dimension OPERATOR(pg_catalog.=) 'tenant_slug' THEN 30
        WHEN p_dimension OPERATOR(pg_catalog.=) 'ip' THEN 100
    END AND
    (
        p_scope_kind OPERATOR(pg_catalog.=) 'tenant' AND
        (
            p_purpose OPERATOR(pg_catalog.=) 'login' AND
            p_dimension OPERATOR(pg_catalog.=) ANY (
                ARRAY['identifier','ip','identifier_ip']::text[]
            ) OR
            p_purpose OPERATOR(pg_catalog.=) 'refresh' AND
            p_dimension OPERATOR(pg_catalog.=) ANY (
                ARRAY['selector','ip']::text[]
            ) OR
            p_purpose OPERATOR(pg_catalog.=) 'reauth' AND
            p_dimension OPERATOR(pg_catalog.=) ANY (
                ARRAY['identifier','ip','identifier_ip']::text[]
            ) OR
            p_purpose OPERATOR(pg_catalog.=) ANY (
                ARRAY['password_reset','email_verification',
                      'portal_setup','invitation']::text[]
            ) AND p_dimension OPERATOR(pg_catalog.=) ANY (
                ARRAY['identifier','ip','identifier_ip']::text[]
            )
        ) OR
        p_scope_kind OPERATOR(pg_catalog.=) 'environment' AND
        (
            p_purpose OPERATOR(pg_catalog.=) 'login' AND
            p_dimension OPERATOR(pg_catalog.=) ANY (
                ARRAY['tenant_slug','identifier','ip','identifier_ip']::text[]
            ) OR
            p_purpose OPERATOR(pg_catalog.=) 'refresh' AND
            p_dimension OPERATOR(pg_catalog.=) ANY (
                ARRAY['selector','ip']::text[]
            ) OR
            p_purpose OPERATOR(pg_catalog.=) ANY (
                ARRAY['password_reset','email_verification',
                      'portal_setup','invitation']::text[]
            ) AND p_dimension OPERATOR(pg_catalog.=) ANY (
                ARRAY['tenant_slug','identifier','ip','identifier_ip']::text[]
            )
        )
    );
$$;


ALTER FUNCTION platform.iam_auth_throttle_policy_v1(p_scope_kind text, p_purpose text, p_dimension text, p_policy_version integer, p_window_seconds integer, p_block_after integer, p_block_seconds integer) OWNER TO harpy_owner;

--
-- Name: iam_auth_throttle_record_failure_v2(text, uuid, text, text, text, bytea, bigint, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_auth_throttle_record_failure_v2(p_scope_kind text, p_tenant_id uuid, p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_group_generation bigint, p_cutover_generation bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_scope_id uuid;
    v_epoch bigint;
    v_row platform.iam_auth_throttle_buckets%ROWTYPE;
    v_found boolean;
    v_now timestamptz;
    v_window integer;
    v_after integer;
    v_seconds integer;
    v_start timestamptz;
    v_end timestamptz;
    v_count integer;
    v_blocked timestamptz;
    v_revision bigint;
    v_retain timestamptz;
BEGIN
	 v_window := 300;
	 v_seconds := 900;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind NOT IN ('tenant','environment') OR
       p_purpose NOT IN ('login','refresh') OR
       NOT platform.iam_hmac_key_id_valid_v1(p_key_id) OR
       pg_catalog.octet_length(p_bucket_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM throttle failure input is invalid';
    END IF;
    v_after := CASE p_dimension WHEN 'identifier' THEN 5 WHEN 'selector' THEN 5
        WHEN 'identifier_ip' THEN 10 WHEN 'tenant_slug' THEN 30
        WHEN 'ip' THEN 100 END;
    IF v_after IS NULL OR NOT platform.iam_auth_throttle_policy_v1(
        p_scope_kind,p_purpose,p_dimension,1,v_window,v_after,v_seconds
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM throttle failure policy is invalid';
    END IF;
    IF p_scope_kind = 'tenant' THEN
        IF p_tenant_id IS NULL OR p_group_generation IS NULL OR p_cutover_generation IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM tenant throttle authority is invalid';
        END IF;
        PERFORM platform.iam_assert_current_tenant_authority_v1(
            p_tenant_id,p_group_generation,p_cutover_generation
        );
        v_scope_id := p_tenant_id; v_epoch := p_group_generation;
    ELSE
        IF p_tenant_id IS NOT NULL OR p_group_generation IS NOT NULL OR p_cutover_generation IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM environment throttle authority is invalid';
        END IF;
        SELECT environment_id INTO STRICT v_scope_id FROM platform.environment_identity FOR SHARE;
        v_epoch := 0;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:iam-throttle:v2:' || p_scope_kind || ':' || v_scope_id::text || ':' ||
        p_purpose || ':' || p_dimension || ':' || p_key_id || ':' ||
        pg_catalog.encode(p_bucket_hmac,'hex'),0
    ));
    SELECT bucket.* INTO v_row FROM platform.iam_auth_throttle_buckets AS bucket
    WHERE bucket.bucket_scope_kind = p_scope_kind AND bucket.scope_id = v_scope_id
      AND bucket.authority_epoch = v_epoch AND bucket.purpose = p_purpose
      AND bucket.dimension = p_dimension AND bucket.key_id = p_key_id
      AND bucket.bucket_hmac = p_bucket_hmac FOR UPDATE;
    v_found := FOUND; v_now := pg_catalog.clock_timestamp();
    IF NOT v_found AND p_scope_kind = 'tenant' THEN
        SELECT bucket.* INTO v_row FROM platform.iam_auth_throttle_buckets AS bucket
        WHERE bucket.bucket_scope_kind = 'tenant' AND bucket.scope_id = v_scope_id
          AND bucket.authority_epoch < v_epoch AND bucket.purpose = p_purpose
          AND bucket.dimension = p_dimension AND bucket.key_id = p_key_id
          AND bucket.bucket_hmac = p_bucket_hmac
        ORDER BY bucket.authority_epoch DESC LIMIT 1 FOR SHARE;
    END IF;
    IF FOUND AND v_now <= v_row.last_attempt_at THEN
        v_now := v_row.last_attempt_at + INTERVAL '1 microsecond';
    END IF;
    IF FOUND AND v_now < v_row.window_end AND v_row.policy_version = 1 THEN
        IF v_row.attempt_count = 2147483647 THEN
            RAISE EXCEPTION USING ERRCODE = '22003', MESSAGE = 'IAM throttle counter overflow';
        END IF;
        v_start := v_row.window_start; v_end := v_row.window_end;
        v_count := v_row.attempt_count + 1; v_blocked := v_row.blocked_until;
    ELSE
        v_start := v_now; v_end := v_now + pg_catalog.make_interval(secs => v_window);
        v_count := 1;
        IF FOUND AND v_row.blocked_until > v_now THEN v_blocked := v_row.blocked_until; END IF;
    END IF;
    IF v_count >= v_after AND (v_blocked IS NULL OR
       v_blocked < v_now + pg_catalog.make_interval(secs => v_seconds)) THEN
        v_blocked := v_now + pg_catalog.make_interval(secs => v_seconds);
    END IF;
    v_revision := CASE WHEN v_found THEN v_row.revision + 1 ELSE 1 END;
    v_retain := v_end + INTERVAL '24 hours';
    IF v_blocked IS NOT NULL THEN v_retain := GREATEST(v_retain,v_blocked + INTERVAL '24 hours'); END IF;
    IF v_found THEN v_retain := GREATEST(v_retain,v_row.retain_until); END IF;
    IF v_found THEN
        UPDATE platform.iam_auth_throttle_buckets SET policy_version=1,
            window_start=v_start,window_end=v_end,attempt_count=v_count,
            blocked_until=v_blocked,last_attempt_at=v_now,revision=v_revision,
            retain_until=v_retain
        WHERE bucket_scope_kind=p_scope_kind AND scope_id=v_scope_id
          AND authority_epoch=v_epoch AND purpose=p_purpose AND dimension=p_dimension
          AND key_id=p_key_id AND bucket_hmac=p_bucket_hmac;
    ELSE
        INSERT INTO platform.iam_auth_throttle_buckets(
            bucket_scope_kind,scope_id,authority_epoch,purpose,dimension,key_id,bucket_hmac,
            environment_id,tenant_id,authority_scope_kind,authority_scope_id,
            authority_group_id,authority_group_generation,authority_domain,cutover_generation,
            policy_version,window_start,window_end,attempt_count,blocked_until,
            last_attempt_at,revision,retain_until
        ) VALUES (
            p_scope_kind,v_scope_id,v_epoch,p_purpose,p_dimension,p_key_id,p_bucket_hmac,
            CASE WHEN p_scope_kind='environment' THEN v_scope_id END,p_tenant_id,
            CASE WHEN p_scope_kind='tenant' THEN 'tenant' END,p_tenant_id,
            CASE WHEN p_scope_kind='tenant' THEN 'iam_system_resources' END,p_group_generation,
            CASE WHEN p_scope_kind='tenant' THEN 'iam' END,p_cutover_generation,
            1,v_start,v_end,v_count,v_blocked,v_now,1,v_retain
        );
    END IF;
    RETURN v_blocked IS NOT NULL AND v_blocked > v_now;
END;
$$;


ALTER FUNCTION platform.iam_auth_throttle_record_failure_v2(p_scope_kind text, p_tenant_id uuid, p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_group_generation bigint, p_cutover_generation bigint) OWNER TO harpy_owner;

--
-- Name: iam_environment_throttle_record_attempt_v1(text, text, text, bytea, integer, integer, integer, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_environment_throttle_record_attempt_v1(p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_policy_version integer, p_window_seconds integer, p_block_after integer, p_block_seconds integer) RETURNS TABLE(result_attempt_count integer, result_blocked_until timestamp with time zone, result_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_environment_id uuid;
    v_row platform.iam_auth_throttle_buckets%ROWTYPE;
    v_found boolean;
    v_now timestamptz;
    v_window_start timestamptz;
    v_window_end timestamptz;
    v_attempt_count integer;
    v_blocked_until timestamptz;
    v_revision bigint;
    v_retain_until timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_purpose IS NULL OR NOT (p_purpose OPERATOR(pg_catalog.=) ANY (
           ARRAY['login','refresh','password_reset','email_verification',
                 'portal_setup','invitation','reauth']::text[]
       )) OR p_dimension IS NULL OR
       NOT (p_dimension OPERATOR(pg_catalog.=) ANY (
           ARRAY['tenant_slug','identifier','ip','identifier_ip','selector']::text[]
       )) OR p_key_id IS NULL OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       p_key_id OPERATOR(pg_catalog.!~) '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       p_bucket_hmac IS NULL OR pg_catalog.octet_length(p_bucket_hmac) <> 32 OR
       NOT platform.iam_auth_throttle_policy_v1(
           'environment', p_purpose, p_dimension, p_policy_version,
           p_window_seconds, p_block_after, p_block_seconds
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM environment throttle input is invalid';
    END IF;

    SELECT environment.environment_id INTO v_environment_id
    FROM platform.environment_identity AS environment
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'IAM throttle environment identity is missing';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:iam-throttle:environment:' || v_environment_id::text || ':' ||
        COALESCE(p_purpose, '') || ':' || COALESCE(p_dimension, '') || ':' ||
        COALESCE(p_key_id, '') || ':' ||
        COALESCE(pg_catalog.encode(p_bucket_hmac, 'hex'), ''), 0
    ));

    SELECT bucket.* INTO v_row
    FROM platform.iam_auth_throttle_buckets AS bucket
    WHERE bucket.bucket_scope_kind OPERATOR(pg_catalog.=) 'environment'
      AND bucket.scope_id OPERATOR(pg_catalog.=) v_environment_id
      AND bucket.authority_epoch OPERATOR(pg_catalog.=) 0
      AND bucket.purpose OPERATOR(pg_catalog.=) p_purpose
      AND bucket.dimension OPERATOR(pg_catalog.=) p_dimension
      AND bucket.key_id OPERATOR(pg_catalog.=) p_key_id
      AND bucket.bucket_hmac OPERATOR(pg_catalog.=) p_bucket_hmac
    FOR UPDATE;
    v_found := FOUND;
    v_now := pg_catalog.clock_timestamp();

    IF NOT v_found THEN
        v_window_start := v_now;
        v_window_end := v_now OPERATOR(pg_catalog.+)
            pg_catalog.make_interval(secs => p_window_seconds);
        v_attempt_count := 1;
        v_revision := 1;
        IF p_block_after OPERATOR(pg_catalog.=) 1 THEN
            v_blocked_until := v_now OPERATOR(pg_catalog.+)
                pg_catalog.make_interval(secs => p_block_seconds);
        END IF;
    ELSE
        IF p_policy_version OPERATOR(pg_catalog.<) v_row.policy_version OR
           v_row.revision OPERATOR(pg_catalog.=) 9223372036854775807 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5723',
                MESSAGE = 'IAM environment throttle revision is stale';
        END IF;
        IF v_now OPERATOR(pg_catalog.<=) v_row.last_attempt_at THEN
            v_now := v_row.last_attempt_at OPERATOR(pg_catalog.+)
                INTERVAL '1 microsecond';
        END IF;
        IF v_now OPERATOR(pg_catalog.>=) v_row.window_end OR
           p_policy_version OPERATOR(pg_catalog.>) v_row.policy_version THEN
            v_window_start := v_now;
            v_window_end := v_now OPERATOR(pg_catalog.+)
                pg_catalog.make_interval(secs => p_window_seconds);
            v_attempt_count := 1;
            IF v_row.blocked_until IS NOT NULL AND
               v_row.blocked_until OPERATOR(pg_catalog.>) v_now THEN
                v_blocked_until := v_row.blocked_until;
            END IF;
            IF p_block_after OPERATOR(pg_catalog.=) 1 AND
               (
                   v_blocked_until IS NULL OR
                   v_blocked_until OPERATOR(pg_catalog.<) (
                       v_now OPERATOR(pg_catalog.+)
                       pg_catalog.make_interval(secs => p_block_seconds)
                   )
               ) THEN
                v_blocked_until := v_now OPERATOR(pg_catalog.+)
                    pg_catalog.make_interval(secs => p_block_seconds);
            END IF;
        ELSE
            IF v_row.attempt_count OPERATOR(pg_catalog.=) 2147483647 THEN
                RAISE EXCEPTION USING ERRCODE = '22003',
                    MESSAGE = 'IAM environment throttle counter overflow';
            END IF;
            v_window_start := v_row.window_start;
            v_window_end := v_row.window_end;
            v_attempt_count := v_row.attempt_count OPERATOR(pg_catalog.+) 1;
            v_blocked_until := v_row.blocked_until;
            IF v_attempt_count OPERATOR(pg_catalog.>=) p_block_after AND
               (
                   v_blocked_until IS NULL OR
                   v_blocked_until OPERATOR(pg_catalog.<) (
                       v_now OPERATOR(pg_catalog.+)
                       pg_catalog.make_interval(secs => p_block_seconds)
                   )
               ) THEN
                v_blocked_until := v_now OPERATOR(pg_catalog.+)
                    pg_catalog.make_interval(secs => p_block_seconds);
            END IF;
        END IF;
        v_revision := v_row.revision OPERATOR(pg_catalog.+) 1;
    END IF;

    v_retain_until := v_window_end OPERATOR(pg_catalog.+) INTERVAL '24 hours';
    IF v_blocked_until IS NOT NULL AND
       v_retain_until OPERATOR(pg_catalog.<) (
           v_blocked_until OPERATOR(pg_catalog.+) INTERVAL '24 hours'
       ) THEN
        v_retain_until := v_blocked_until OPERATOR(pg_catalog.+) INTERVAL '24 hours';
    END IF;
    IF v_found AND v_retain_until OPERATOR(pg_catalog.<) v_row.retain_until THEN
        v_retain_until := v_row.retain_until;
    END IF;

    IF v_found THEN
        UPDATE platform.iam_auth_throttle_buckets AS bucket
        SET policy_version = p_policy_version,
            window_start = v_window_start, window_end = v_window_end,
            attempt_count = v_attempt_count, blocked_until = v_blocked_until,
            last_attempt_at = v_now, revision = v_revision,
            retain_until = v_retain_until
        WHERE bucket.bucket_scope_kind OPERATOR(pg_catalog.=) 'environment'
          AND bucket.scope_id OPERATOR(pg_catalog.=) v_environment_id
          AND bucket.authority_epoch OPERATOR(pg_catalog.=) 0
          AND bucket.purpose OPERATOR(pg_catalog.=) p_purpose
          AND bucket.dimension OPERATOR(pg_catalog.=) p_dimension
          AND bucket.key_id OPERATOR(pg_catalog.=) p_key_id
          AND bucket.bucket_hmac OPERATOR(pg_catalog.=) p_bucket_hmac;
    ELSE
        INSERT INTO platform.iam_auth_throttle_buckets (
            bucket_scope_kind, scope_id, authority_epoch,
            purpose, dimension, key_id, bucket_hmac,
            environment_id, tenant_id, authority_scope_kind, authority_scope_id,
            authority_group_id, authority_group_generation, authority_domain,
            cutover_generation, policy_version, window_start, window_end,
            attempt_count, blocked_until, last_attempt_at, revision, retain_until
        ) VALUES (
            'environment', v_environment_id, 0, p_purpose, p_dimension,
            p_key_id, p_bucket_hmac, v_environment_id, NULL, NULL, NULL,
            NULL, NULL, NULL, NULL, p_policy_version, v_window_start, v_window_end,
            v_attempt_count, v_blocked_until, v_now, v_revision, v_retain_until
        );
    END IF;
    result_attempt_count := v_attempt_count;
    result_blocked_until := v_blocked_until;
    result_revision := v_revision;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.iam_environment_throttle_record_attempt_v1(p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_policy_version integer, p_window_seconds integer, p_block_after integer, p_block_seconds integer) OWNER TO harpy_owner;

--
-- Name: iam_hmac_key_id_valid_v1(text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_hmac_key_id_valid_v1(p_value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
SELECT p_value IS NOT NULL AND p_value OPERATOR(pg_catalog.~)
    '^(([A-Za-z0-9_-]{4}){4,16}|([A-Za-z0-9_-]{4}){4,15}[A-Za-z0-9_-][AQgw]|([A-Za-z0-9_-]{4}){4,15}[A-Za-z0-9_-]{2}[AEIMQUYcgkosw048])$'
$_$;


ALTER FUNCTION platform.iam_hmac_key_id_valid_v1(p_value text) OWNER TO harpy_owner;

--
-- Name: iam_identity_directory_tombstone_v1(uuid, bigint, bigint, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_identity_directory_tombstone_v1(p_tenant_id uuid, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_source_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_user_id IS NULL OR
       p_source_revision IS NULL OR p_source_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM identity directory tombstone input is invalid';
    END IF;
    PERFORM platform.iam_assert_current_tenant_authority_v1(
        p_tenant_id, p_group_generation, p_iam_generation
    );
    IF EXISTS (
        SELECT 1 FROM platform.iam_login_directory AS directory
        WHERE directory.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
          AND directory.user_id OPERATOR(pg_catalog.=) p_user_id
          AND directory.source_revision OPERATOR(pg_catalog.>) p_source_revision
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM identity directory tombstone revision is stale';
    END IF;
    UPDATE platform.iam_login_directory AS directory
    SET state = 'tombstoned', source_revision = p_source_revision,
        projected_at = v_now, tombstoned_at = v_now
    WHERE directory.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
      AND directory.user_id OPERATOR(pg_catalog.=) p_user_id
      AND directory.state OPERATOR(pg_catalog.=) 'active';
    RETURN p_source_revision;
END;
$$;


ALTER FUNCTION platform.iam_identity_directory_tombstone_v1(p_tenant_id uuid, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_source_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_directory_upsert_v1(uuid, bigint, bigint, uuid, uuid, text, bytea, bigint, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_identity_directory_upsert_v1(p_tenant_id uuid, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_identifier_id uuid, p_lookup_key_id text, p_identifier_hmac bytea, p_source_revision bigint, p_source_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_row platform.iam_login_directory%ROWTYPE;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_user_id IS NULL OR p_identifier_id IS NULL OR
       p_lookup_key_id IS NULL OR pg_catalog.octet_length(p_lookup_key_id) NOT BETWEEN 1 AND 128 OR
       p_lookup_key_id OPERATOR(pg_catalog.!~) '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       p_identifier_hmac IS NULL OR pg_catalog.octet_length(p_identifier_hmac) <> 32 OR
       p_source_revision IS NULL OR p_source_revision < 1 OR
       p_source_sha256 IS NULL OR pg_catalog.octet_length(p_source_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM identity directory upsert input is invalid';
    END IF;
    PERFORM platform.iam_assert_current_tenant_authority_v1(
        p_tenant_id, p_group_generation, p_iam_generation
    );
    SELECT directory.* INTO v_row
    FROM platform.iam_login_directory AS directory
    WHERE directory.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
      AND directory.identifier_kind OPERATOR(pg_catalog.=) 'email_v1'
      AND directory.lookup_key_id OPERATOR(pg_catalog.=) p_lookup_key_id
      AND directory.identifier_hmac OPERATOR(pg_catalog.=) p_identifier_hmac
    FOR UPDATE;
    IF FOUND THEN
        IF v_row.user_id IS DISTINCT FROM p_user_id OR
           v_row.source_identifier_id IS DISTINCT FROM p_identifier_id OR
           v_row.source_revision OPERATOR(pg_catalog.>) p_source_revision THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM identity directory ownership or revision conflicts';
        END IF;
        UPDATE platform.iam_login_directory AS directory
        SET source_revision = p_source_revision, state = 'active',
            source_sha256 = p_source_sha256, projected_at = v_now,
            tombstoned_at = NULL
        WHERE directory.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
          AND directory.identifier_kind OPERATOR(pg_catalog.=) 'email_v1'
          AND directory.lookup_key_id OPERATOR(pg_catalog.=) p_lookup_key_id
          AND directory.identifier_hmac OPERATOR(pg_catalog.=) p_identifier_hmac;
    ELSE
        INSERT INTO platform.iam_login_directory (
            tenant_id, identifier_kind, lookup_key_id, identifier_hmac,
            user_id, source_identifier_id, source_revision, state,
            source_sha256, projected_at
        ) VALUES (
            p_tenant_id, 'email_v1', p_lookup_key_id, p_identifier_hmac,
            p_user_id, p_identifier_id, p_source_revision, 'active',
            p_source_sha256, v_now
        );
    END IF;
    RETURN p_source_revision;
END;
$_$;


ALTER FUNCTION platform.iam_identity_directory_upsert_v1(p_tenant_id uuid, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_identifier_id uuid, p_lookup_key_id text, p_identifier_hmac bytea, p_source_revision bigint, p_source_sha256 bytea) OWNER TO harpy_owner;

