--
-- Name: iam_initial_admin_setup_stage_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_initial_admin_setup_stage_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='initial admin setup stage mutation is forbidden';
END;
$$;


ALTER FUNCTION platform.iam_initial_admin_setup_stage_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_initial_admin_setup_stage_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_initial_admin_setup_stage_read_v1(p_operation_id uuid, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_stage jsonb;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_operation_id IS NULL OR p_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='initial admin setup stage read is denied';
    END IF;
    SELECT pg_catalog.to_jsonb(stage) INTO STRICT v_stage
    FROM platform.iam_initial_admin_setup_stages AS stage
    WHERE stage.operation_id=p_operation_id
      AND stage.tenant_id=p_tenant_id
    FOR SHARE;
    RETURN v_stage;
END;
$$;


ALTER FUNCTION platform.iam_initial_admin_setup_stage_read_v1(p_operation_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_initial_admin_setup_stage_v1(uuid, uuid, uuid, uuid, text, uuid, bytea, text, bytea, bytea, uuid, text, text, bytea, bytea, bytea, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_initial_admin_setup_stage_v1(p_operation_id uuid, p_tenant_id uuid, p_user_id uuid, p_identifier_id uuid, p_normalized_email text, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_artifact_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea, p_created_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.iam_initial_admin_setup_stages%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_user_id IS NULL OR p_identifier_id IS NULL
       OR p_normalized_email IS DISTINCT FROM pg_catalog.lower(p_normalized_email)
       OR pg_catalog.octet_length(p_normalized_email) NOT BETWEEN 3 AND 254
       OR p_token_id IS NULL OR pg_catalog.octet_length(p_selector) <> 16
       OR p_hash_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$'
       OR pg_catalog.octet_length(p_secret_hmac) <> 32
       OR pg_catalog.octet_length(p_binding_sha256) <> 32
       OR p_artifact_id IS NULL
       OR p_artifact_ref IS DISTINCT FROM
          'iam-lifecycle-delivery://tenant/' || p_tenant_id::text ||
          '/artifact/' || p_artifact_id::text
       OR pg_catalog.octet_length(p_nonce) <> 12
       OR pg_catalog.octet_length(p_ciphertext) <> 66
       OR pg_catalog.octet_length(p_authentication_tag) <> 16
       OR pg_catalog.octet_length(p_aad_sha256) <> 32
       OR pg_catalog.octet_length(p_ciphertext_sha256) <> 32
       OR NOT pg_catalog.isfinite(p_created_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='initial admin setup stage is invalid';
    END IF;
    SELECT * INTO v_existing
    FROM platform.iam_initial_admin_setup_stages AS stage
    WHERE stage.operation_id=p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF ROW(v_existing.tenant_id,v_existing.user_id,
            v_existing.identifier_id,v_existing.normalized_email)
           IS DISTINCT FROM ROW(p_tenant_id,p_user_id,p_identifier_id,
            p_normalized_email) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='initial admin setup stage conflicts';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.iam_initial_admin_setup_stages (
        operation_id,tenant_id,user_id,identifier_id,normalized_email,
        token_id,selector,hash_key_id,secret_hmac,binding_sha256,
        artifact_id,artifact_ref,kms_key_id,nonce,ciphertext,
        authentication_tag,aad_sha256,ciphertext_sha256,created_at
    ) VALUES (
        p_operation_id,p_tenant_id,p_user_id,p_identifier_id,p_normalized_email,
        p_token_id,p_selector,p_hash_key_id,p_secret_hmac,p_binding_sha256,
        p_artifact_id,p_artifact_ref,p_kms_key_id,p_nonce,p_ciphertext,
        p_authentication_tag,p_aad_sha256,p_ciphertext_sha256,p_created_at
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.iam_initial_admin_setup_stage_v1(p_operation_id uuid, p_tenant_id uuid, p_user_id uuid, p_identifier_id uuid, p_normalized_email text, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_artifact_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_installation_activation_assert_v2(uuid, uuid, uuid, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_installation_activation_assert_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN SESSION_USER = 'harpy_v2_runtime'
       AND CURRENT_USER = 'harpy_owner'
       AND (
         platform.tenancy_activation_step_context_assert_v1(
            p_operation_id, 'iam.initialize_tenant_identity',
            p_environment_id, p_tenant_id, p_schema_name,
            'environment_initialize'
         )
         OR platform.tenancy_activation_step_context_assert_v1(
            p_operation_id, 'iam.initialize_tenant_identity',
            p_environment_id, p_tenant_id, p_schema_name,
            'saas_customer_tenant_provision'
         )
       );
END;
$$;


ALTER FUNCTION platform.iam_installation_activation_assert_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name) OWNER TO harpy_owner;

--
-- Name: iam_installation_identity_directory_upsert_v1(uuid, uuid, uuid, name, bigint, bigint, uuid, uuid, text, bytea, bigint, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_installation_identity_directory_upsert_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_identifier_id uuid, p_lookup_key_id text, p_identifier_hmac bytea, p_source_revision bigint, p_source_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT platform.iam_installation_activation_assert_v2(
        p_operation_id, p_environment_id, p_tenant_id, p_schema_name
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM installation directory capability required';
    END IF;
    RETURN platform.iam_identity_directory_upsert_v2(
        p_tenant_id, p_group_generation, p_iam_generation,
        p_user_id, p_identifier_id, p_lookup_key_id,
        p_identifier_hmac, p_source_revision, p_source_sha256
    );
END;
$$;


ALTER FUNCTION platform.iam_installation_identity_directory_upsert_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_identifier_id uuid, p_lookup_key_id text, p_identifier_hmac bytea, p_source_revision bigint, p_source_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_installation_instance_owner_bind_v1(uuid, uuid, uuid, name, uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_installation_instance_owner_bind_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_user_id uuid, p_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_owner_binding_id uuid, p_authorization_version bigint, p_request_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.iam_platform_mutation_receipts%ROWTYPE;
    v_permission_id uuid;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_schema_name IS NULL OR p_user_id IS NULL
       OR p_subject_id IS NULL OR p_owner_role_id IS NULL
       OR p_role_permission_id IS NULL OR p_owner_binding_id IS NULL
       OR p_authorization_version < 1
       OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='installation Instance Owner binding denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('iam-installation-owner|'||p_environment_id::text,0));
    SELECT * INTO v_existing
    FROM platform.iam_platform_mutation_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.mutation_kind IS DISTINCT FROM 'initial_owner'
           OR v_existing.request_sha256 IS DISTINCT FROM
                pg_catalog.decode(p_request_sha256,'hex')
           OR v_existing.actor_user_id IS DISTINCT FROM p_user_id
           OR v_existing.target_user_id IS DISTINCT FROM p_user_id
           OR v_existing.subject_id IS DISTINCT FROM p_subject_id
           OR v_existing.role_id IS DISTINCT FROM p_owner_role_id
           OR v_existing.subject_role_binding_id IS DISTINCT FROM p_owner_binding_id
           OR v_existing.role_permission_binding_id IS DISTINCT FROM p_role_permission_id
           OR v_existing.target_authorization_version IS DISTINCT FROM
                p_authorization_version THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='installation Instance Owner replay conflicts';
        END IF;
        RETURN true;
    END IF;
    PERFORM 1
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.tenants AS tenant ON tenant.id=operation.tenant_id
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id=operation.environment_id
     AND binding.tenant_id=operation.tenant_id
    JOIN platform.platformauthority_installation_owner_bindings AS authority
      ON authority.operation_id=operation.operation_id
     AND authority.environment_id=operation.environment_id
     AND authority.tenant_id=operation.tenant_id
     AND authority.instance_owner_binding_id=p_owner_binding_id
    WHERE operation.operation_id=p_operation_id
      AND operation.environment_id=p_environment_id
      AND operation.tenant_id=p_tenant_id
      AND operation.schema_name=p_schema_name
      AND operation.first_user_id=p_user_id
      AND operation.instance_owner_binding_id=p_owner_binding_id
      AND operation.operation_kind='environment_initialize'
      AND operation.state IN ('finalizing','succeeded')
      AND tenant.schema_name=p_schema_name AND tenant.owner_id=p_user_id
      AND tenant.status='ACTIVE' AND tenant.deleted_at IS NULL
      AND binding.purpose IN ('onpremise_primary','saas_control')
    FOR SHARE OF operation,tenant,binding,authority;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='installation Instance Owner activation evidence is unavailable';
    END IF;
    PERFORM 1 FROM platform.iam_login_directory AS directory
    WHERE directory.tenant_id=p_tenant_id AND directory.user_id=p_user_id
      AND directory.state='active' FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='installation Instance Owner has no active login mapping';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.iam_platform_owner_policies)
       OR EXISTS (SELECT 1 FROM platform.iam_platform_subjects
                  WHERE environment_id=p_environment_id) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='platform owner authority exists without installation receipt';
    END IF;
    SELECT permission.id INTO STRICT v_permission_id
    FROM platform.iam_platform_permissions AS permission
    WHERE permission.permission_key='environment_all'
      AND permission.match_kind='environment_all' AND permission.state='active'
    FOR SHARE;
    INSERT INTO platform.iam_platform_subjects(
        id,environment_id,primary_tenant_id,user_id,state,revision,created_at,updated_at
    ) VALUES (p_subject_id,p_environment_id,p_tenant_id,p_user_id,'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_roles(
        id,environment_id,role_kind,role_key,state,revision,created_at,updated_at
    ) VALUES (p_owner_role_id,p_environment_id,'instance_owner','instance_owner',
        'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_role_permissions(
        id,environment_id,role_id,permission_id,state,revision,created_at,updated_at
    ) VALUES (p_role_permission_id,p_environment_id,p_owner_role_id,v_permission_id,
        'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_subject_roles(
        id,environment_id,subject_id,role_id,state,revision,created_at,updated_at
    ) VALUES (p_owner_binding_id,p_environment_id,p_subject_id,p_owner_role_id,
        'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_owner_policies(
        environment_id,owner_binding_id,revision,created_at,updated_at
    ) VALUES (p_environment_id,p_owner_binding_id,1,v_now,v_now);
    INSERT INTO platform.iam_platform_authorization_clocks(
        environment_id,authorization_clock,revision,created_at,updated_at
    ) VALUES (p_environment_id,1,1,v_now,v_now);
    INSERT INTO platform.iam_platform_mutation_receipts VALUES (
        p_operation_id,p_environment_id,'initial_owner',
        pg_catalog.decode(p_request_sha256,'hex'),p_user_id,p_user_id,p_subject_id,
        p_owner_role_id,p_owner_binding_id,p_role_permission_id,v_permission_id,
        p_authorization_version,1,v_now
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.iam_installation_instance_owner_bind_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_user_id uuid, p_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_owner_binding_id uuid, p_authorization_version bigint, p_request_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_installation_instance_owner_bind_v2(uuid, uuid, uuid, name, uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_installation_instance_owner_bind_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_user_id uuid, p_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_owner_binding_id uuid, p_authorization_version bigint, p_request_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET application_name TO 'harpy-v2:core-operator-initialize'
    AS $$
DECLARE
    v_replayed boolean;
BEGIN
    IF NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id, 'platformauthority.bind_owner', p_environment_id,
        p_tenant_id, p_schema_name, 'environment_initialize'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM installation Instance Owner capability required';
    END IF;
    v_replayed := platform.iam_installation_instance_owner_bind_v1(
        p_operation_id,p_environment_id,p_tenant_id,p_schema_name,
        p_user_id,p_subject_id,p_owner_role_id,p_role_permission_id,
        p_owner_binding_id,p_authorization_version,p_request_sha256
    );
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id, 'platformauthority.bind_owner'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM installation Instance Owner capability conflicts';
    END IF;
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.iam_installation_instance_owner_bind_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_user_id uuid, p_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_owner_binding_id uuid, p_authorization_version bigint, p_request_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_installation_instance_owner_input_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_installation_instance_owner_input_v1(p_environment_id uuid) RETURNS TABLE(operation_id uuid, tenant_id uuid, schema_name name, user_id uuid, owner_binding_id uuid, request_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='installation Instance Owner input denied';
    END IF;
    RETURN QUERY
    SELECT operation.operation_id,operation.tenant_id,operation.schema_name::name,
        operation.first_user_id,operation.instance_owner_binding_id,
        operation.step_plan_sha256
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.platformauthority_installation_owner_bindings AS authority
      ON authority.operation_id=operation.operation_id
     AND authority.environment_id=operation.environment_id
     AND authority.tenant_id=operation.tenant_id
     AND authority.instance_owner_binding_id=operation.instance_owner_binding_id
    WHERE operation.environment_id=p_environment_id
      AND operation.operation_kind='environment_initialize'
      AND operation.state='succeeded';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='completed installation Instance Owner input is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.iam_installation_instance_owner_input_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_installation_instance_owner_verify_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_installation_instance_owner_verify_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_initial_user_id uuid, p_initial_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_initial_owner_binding_id uuid, p_authorization_version bigint, p_request_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_initial_user_id IS NULL
       OR p_initial_subject_id IS NULL OR p_owner_role_id IS NULL
       OR p_role_permission_id IS NULL OR p_initial_owner_binding_id IS NULL
       OR p_authorization_version < 1
       OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='installation Instance Owner verification denied';
    END IF;

    PERFORM 1
    FROM platform.iam_platform_mutation_receipts AS receipt
    JOIN platform.iam_platform_subjects AS initial_subject
      ON initial_subject.environment_id=receipt.environment_id
     AND initial_subject.id=receipt.subject_id
    JOIN platform.iam_platform_subject_roles AS initial_binding
      ON initial_binding.environment_id=receipt.environment_id
     AND initial_binding.id=receipt.subject_role_binding_id
    JOIN platform.iam_platform_roles AS owner_role
      ON owner_role.environment_id=receipt.environment_id
     AND owner_role.id=receipt.role_id
    JOIN platform.iam_platform_role_permissions AS owner_permission
      ON owner_permission.environment_id=receipt.environment_id
     AND owner_permission.id=receipt.role_permission_binding_id
    JOIN platform.iam_platform_permissions AS permission
      ON permission.id=receipt.permission_id
    JOIN platform.iam_platform_owner_policies AS policy
      ON policy.environment_id=receipt.environment_id
    JOIN platform.iam_platform_subject_roles AS current_binding
      ON current_binding.environment_id=policy.environment_id
     AND current_binding.id=policy.owner_binding_id
    JOIN platform.iam_platform_subjects AS current_subject
      ON current_subject.environment_id=current_binding.environment_id
     AND current_subject.id=current_binding.subject_id
    JOIN platform.iam_platform_authorization_clocks AS clock_state
      ON clock_state.environment_id=policy.environment_id
    WHERE receipt.operation_id=p_operation_id
      AND receipt.environment_id=p_environment_id
      AND receipt.mutation_kind='initial_owner'
      AND receipt.request_sha256=pg_catalog.decode(p_request_sha256,'hex')
      AND receipt.actor_user_id=p_initial_user_id
      AND receipt.target_user_id=p_initial_user_id
      AND receipt.subject_id=p_initial_subject_id
      AND receipt.role_id=p_owner_role_id
      AND receipt.subject_role_binding_id=p_initial_owner_binding_id
      AND receipt.role_permission_binding_id=p_role_permission_id
      AND receipt.target_authorization_version=p_authorization_version
      AND receipt.platform_clock=1
      AND initial_subject.primary_tenant_id=p_tenant_id
      AND initial_subject.user_id=p_initial_user_id
      AND initial_binding.subject_id=p_initial_subject_id
      AND initial_binding.role_id=p_owner_role_id
      AND owner_role.role_kind='instance_owner'
      AND owner_role.role_key='instance_owner'
      AND owner_role.state='active'
      AND owner_permission.role_id=p_owner_role_id
      AND owner_permission.permission_id=receipt.permission_id
      AND owner_permission.state='active'
      AND permission.permission_key='environment_all'
      AND permission.match_kind='environment_all'
      AND permission.deployment_mode='both'
      AND NOT permission.delegable
      AND NOT permission.step_up_required
      AND permission.owner_only
      AND permission.state='active'
      AND current_binding.role_id=p_owner_role_id
      AND current_binding.state='active'
      AND current_subject.primary_tenant_id=p_tenant_id
      AND current_subject.state='active'
      AND clock_state.authorization_clock>=receipt.platform_clock
      AND (
          (policy.owner_binding_id=p_initial_owner_binding_id
           AND initial_binding.state='active')
          OR
          (policy.owner_binding_id<>p_initial_owner_binding_id
           AND initial_binding.state='revoked')
      )
      AND NOT EXISTS (
          SELECT 1
          FROM platform.iam_platform_mutation_receipts AS duplicate_receipt
          WHERE duplicate_receipt.environment_id=p_environment_id
            AND duplicate_receipt.mutation_kind='initial_owner'
            AND duplicate_receipt.operation_id<>p_operation_id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM platform.iam_platform_subject_roles AS unexpected_binding
          JOIN platform.iam_platform_roles AS unexpected_role
            ON unexpected_role.environment_id=unexpected_binding.environment_id
           AND unexpected_role.id=unexpected_binding.role_id
          WHERE unexpected_binding.environment_id=p_environment_id
            AND unexpected_binding.state='active'
            AND unexpected_role.role_kind='instance_owner'
            AND unexpected_binding.id<>policy.owner_binding_id
      );
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='installation Instance Owner authority is inconsistent';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.iam_installation_instance_owner_verify_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_initial_user_id uuid, p_initial_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_initial_owner_binding_id uuid, p_authorization_version bigint, p_request_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_installation_security_epoch_initialize_v2(uuid, uuid, uuid, name, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_installation_security_epoch_initialize_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_now timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_now IS NULL OR NOT pg_catalog.isfinite(p_now)
       OR NOT platform.iam_installation_activation_assert_v2(
            p_operation_id, p_environment_id, p_tenant_id, p_schema_name
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM installation security epoch capability required';
    END IF;
    INSERT INTO platform.iam_security_epochs (
        environment_id, security_epoch, generation, created_at, rotated_at
    ) VALUES (
        p_environment_id,
        pg_catalog.sha256(
            pg_catalog.uuid_send(pg_catalog.gen_random_uuid()) ||
            pg_catalog.uuid_send(pg_catalog.gen_random_uuid())
        ),
        1, p_now, p_now
    ) ON CONFLICT (environment_id) DO NOTHING;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.iam_installation_security_epoch_initialize_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_login_directory_upsert_v2(uuid, bigint, bigint, uuid, uuid, text, text, bytea, bigint, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_login_directory_upsert_v2(p_tenant_id uuid, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_identifier_id uuid, p_identifier_kind text, p_lookup_key_id text, p_identifier_hmac bytea, p_source_revision bigint, p_source_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_row platform.iam_login_directory%ROWTYPE;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_user_id IS NULL OR p_identifier_id IS NULL OR
       p_identifier_kind NOT IN ('email_v1', 'portal_v1') OR
       pg_catalog.octet_length(p_lookup_key_id) NOT BETWEEN 1 AND 128 OR
       p_lookup_key_id OPERATOR(pg_catalog.!~) '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_identifier_hmac) <> 32 OR
       p_source_revision < 1 OR pg_catalog.octet_length(p_source_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM login directory projection is denied';
    END IF;
    PERFORM platform.iam_assert_current_tenant_authority_v1(
        p_tenant_id, p_group_generation, p_iam_generation
    );
    SELECT directory.* INTO v_row
    FROM platform.iam_login_directory AS directory
    WHERE directory.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
      AND directory.identifier_kind OPERATOR(pg_catalog.=) p_identifier_kind
      AND directory.lookup_key_id OPERATOR(pg_catalog.=) p_lookup_key_id
      AND directory.identifier_hmac OPERATOR(pg_catalog.=) p_identifier_hmac
    FOR UPDATE;
    IF FOUND THEN
        IF v_row.user_id IS DISTINCT FROM p_user_id OR
           v_row.source_identifier_id IS DISTINCT FROM p_identifier_id OR
           v_row.source_revision OPERATOR(pg_catalog.>) p_source_revision THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM login directory projection conflicts';
        END IF;
        UPDATE platform.iam_login_directory AS directory
        SET source_revision = p_source_revision, state = 'active',
            source_sha256 = p_source_sha256, projected_at = v_now,
            tombstoned_at = NULL
        WHERE directory.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
          AND directory.identifier_kind OPERATOR(pg_catalog.=) p_identifier_kind
          AND directory.lookup_key_id OPERATOR(pg_catalog.=) p_lookup_key_id
          AND directory.identifier_hmac OPERATOR(pg_catalog.=) p_identifier_hmac;
    ELSE
        INSERT INTO platform.iam_login_directory (
            tenant_id, identifier_kind, lookup_key_id, identifier_hmac,
            user_id, source_identifier_id, source_revision, state,
            source_sha256, projected_at
        ) VALUES (
            p_tenant_id, p_identifier_kind, p_lookup_key_id, p_identifier_hmac,
            p_user_id, p_identifier_id, p_source_revision, 'active',
            p_source_sha256, v_now
        );
    END IF;
    RETURN p_source_revision;
END;
$_$;


ALTER FUNCTION platform.iam_login_directory_upsert_v2(p_tenant_id uuid, p_group_generation bigint, p_iam_generation bigint, p_user_id uuid, p_identifier_id uuid, p_identifier_kind text, p_lookup_key_id text, p_identifier_hmac bytea, p_source_revision bigint, p_source_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_apply_v1(uuid, uuid, uuid, text, text, bigint, bytea, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_maintenance_directory_apply_v1(p_tenant_id uuid, p_identifier_id uuid, p_user_id uuid, p_kind text, p_state text, p_source_revision bigint, p_source_sha256 bytea, p_key_evidence jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_entry jsonb;
    v_key_id text;
    v_hmac bytea;
    v_rows bigint;
    v_step bigint;
BEGIN
    v_rows := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_identifier_id IS NULL OR p_user_id IS NULL OR
       p_kind NOT IN ('email_v1', 'portal_v1') OR
       p_state NOT IN ('pending', 'verified', 'active', 'tombstoned', 'retired') OR
       p_source_revision < 1 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM maintenance directory input is invalid';
    END IF;
    IF p_key_evidence IS NULL OR
       pg_catalog.jsonb_typeof(p_key_evidence) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM maintenance directory evidence is invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(p_key_evidence) > 65 OR
       (p_state = 'active' AND
        pg_catalog.jsonb_array_length(p_key_evidence) < 1) OR
       (p_state <> 'active' AND
        pg_catalog.jsonb_array_length(p_key_evidence) <> 0) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM maintenance directory evidence is invalid';
    END IF;
    IF p_state = 'active' THEN
        IF EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_key_evidence) AS item(value)
            WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
               OR item.value <> pg_catalog.jsonb_build_object(
                    'key_id', item.value ->> 'key_id',
                    'hmac', item.value ->> 'hmac'
                  )
               OR NOT platform.iam_hmac_key_id_valid_v1(
                    item.value ->> 'key_id'
                  )
               OR item.value ->> 'hmac' !~ '^[0-9a-f]{64}$'
        ) OR (
            SELECT pg_catalog.count(DISTINCT item.value ->> 'key_id')
            FROM pg_catalog.jsonb_array_elements(p_key_evidence) AS item(value)
        ) <> pg_catalog.jsonb_array_length(p_key_evidence) THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'IAM maintenance directory evidence is invalid';
        END IF;
        FOR v_entry IN
            SELECT item.value
            FROM pg_catalog.jsonb_array_elements(p_key_evidence) AS item(value)
            ORDER BY item.value ->> 'key_id'
        LOOP
            v_key_id := v_entry ->> 'key_id';
            v_hmac := pg_catalog.decode(v_entry ->> 'hmac', 'hex');
            UPDATE platform.iam_login_directory AS directory
            SET identifier_kind = p_kind, identifier_hmac = v_hmac,
                user_id = p_user_id, source_revision = p_source_revision,
                state = 'active', source_sha256 = p_source_sha256,
                projected_at = v_now, tombstoned_at = NULL
            WHERE directory.tenant_id = p_tenant_id
              AND directory.lookup_key_id = v_key_id
              AND directory.source_identifier_id = p_identifier_id;
            GET DIAGNOSTICS v_step = ROW_COUNT;
            IF v_step = 0 THEN
                INSERT INTO platform.iam_login_directory (
                    tenant_id, identifier_kind, lookup_key_id, identifier_hmac,
                    user_id, source_identifier_id, source_revision, state,
                    source_sha256, projected_at, tombstoned_at
                ) VALUES (
                    p_tenant_id, p_kind, v_key_id, v_hmac, p_user_id,
                    p_identifier_id, p_source_revision, 'active',
                    p_source_sha256, v_now, NULL
                );
                v_step := 1;
            END IF;
            v_rows := v_rows + v_step;
        END LOOP;
        UPDATE platform.iam_login_directory AS directory
        SET state = 'tombstoned', source_revision = p_source_revision,
            source_sha256 = p_source_sha256, projected_at = v_now,
            tombstoned_at = COALESCE(directory.tombstoned_at, v_now)
        WHERE directory.tenant_id = p_tenant_id
          AND directory.source_identifier_id = p_identifier_id
          AND NOT EXISTS (
              SELECT 1
              FROM pg_catalog.jsonb_array_elements(p_key_evidence) AS item(value)
              WHERE item.value ->> 'key_id' = directory.lookup_key_id
          );
        GET DIAGNOSTICS v_step = ROW_COUNT;
        v_rows := v_rows + v_step;
    ELSE
        UPDATE platform.iam_login_directory AS directory
        SET state = 'tombstoned', source_revision = p_source_revision,
            source_sha256 = p_source_sha256, projected_at = v_now,
            tombstoned_at = COALESCE(directory.tombstoned_at, v_now)
        WHERE directory.tenant_id = p_tenant_id
          AND directory.source_identifier_id = p_identifier_id
          AND directory.source_revision <= p_source_revision;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
    END IF;
    RETURN v_rows;
END;
$_$;


ALTER FUNCTION platform.iam_maintenance_directory_apply_v1(p_tenant_id uuid, p_identifier_id uuid, p_user_id uuid, p_kind text, p_state text, p_source_revision bigint, p_source_sha256 bytea, p_key_evidence jsonb) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_purge_v1(uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_maintenance_directory_purge_v1(p_tenant_id uuid, p_identifier_id uuid, p_source_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_rows bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_identifier_id IS NULL OR
       p_source_revision IS NULL OR p_source_revision < 1 OR
       NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM maintenance directory purge input is invalid';
    END IF;
    DELETE FROM platform.iam_login_directory AS directory
    WHERE directory.tenant_id = p_tenant_id
      AND directory.source_identifier_id = p_identifier_id
      AND directory.state = 'tombstoned'
      AND directory.tombstoned_at <=
          pg_catalog.transaction_timestamp() - pg_catalog.make_interval(days => 30)
      AND directory.source_revision <= p_source_revision;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN v_rows;
END;
$$;


ALTER FUNCTION platform.iam_maintenance_directory_purge_v1(p_tenant_id uuid, p_identifier_id uuid, p_source_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_snapshot_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_maintenance_directory_snapshot_v1(p_tenant_id uuid) RETURNS TABLE(source_identifier_id uuid, lookup_key_id text, identifier_hmac bytea, user_id uuid, source_revision bigint, identifier_kind text, state text, source_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM maintenance directory snapshot input is invalid';
    END IF;
    RETURN QUERY
    SELECT directory.source_identifier_id, directory.lookup_key_id,
           directory.identifier_hmac, directory.user_id,
           directory.source_revision, directory.identifier_kind,
           directory.state, directory.source_sha256
    FROM platform.iam_login_directory AS directory
    WHERE directory.tenant_id = p_tenant_id
    ORDER BY directory.source_identifier_id, directory.lookup_key_id;
END;
$$;


ALTER FUNCTION platform.iam_maintenance_directory_snapshot_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_ack_v1(uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint, bytea, bytea, bytea, bytea, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_owner_transfer_ack_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint, p_registry_binding_id uuid, p_scope_id uuid, p_registry_sequence bigint, p_generation bigint, p_proposal_sha256 bytea, p_previous_head_sha256 bytea, p_state_sha256 bytea, p_ack_sha256 bytea, p_ack_issued_at timestamp with time zone, p_ack_registry_kid text) RETURNS TABLE(operation_id uuid, registry_binding_id uuid, scope_id uuid, generation bigint, previous_head_sha256 bytea, state_sha256 bytea, proposal_sha256 bytea, status text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_environment_id uuid; v_owner_subject_id uuid; v_clock bigint;
    v_status text; v_operation_environment uuid; v_operation_actor uuid;
    v_operation_request bytea; v_operation_registry uuid; v_operation_scope uuid;
    v_operation_generation bigint; v_operation_proposal bytea;
    v_operation_previous bytea; v_operation_state bytea; v_operation_ack bytea;
    v_operation_sequence bigint; v_operation_ack_kid text; v_operation_expires_at timestamptz;
    v_head_generation bigint; v_head_sha bytea; v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_operation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_actor_id IS NULL OR p_registry_binding_id IS NULL OR p_scope_id IS NULL OR
       p_registry_sequence < 1 OR p_generation < 2 OR
       pg_catalog.octet_length(p_proposal_sha256) <> 32 OR
       pg_catalog.octet_length(p_previous_head_sha256) <> 32 OR
       pg_catalog.octet_length(p_state_sha256) <> 32 OR
       pg_catalog.octet_length(p_ack_sha256) <> 32 OR p_ack_issued_at > v_now OR
       p_ack_registry_kid !~ '^[a-z0-9][a-z0-9._-]{0,127}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Owner transfer acknowledgement is invalid';
    END IF;
    SELECT context.environment_id, context.owner_subject_id, context.platform_clock
    INTO v_environment_id, v_owner_subject_id, v_clock
    FROM platform.iam_platform_owner_context_lock_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock
    ) AS context;
    IF v_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Current actor is not the Instance Owner';
    END IF;
    SELECT operation.status,operation.environment_id,operation.actor_user_id,
           operation.request_sha256,operation.registry_binding_id,operation.scope_id,
           operation.generation,operation.proposal_sha256,operation.previous_head_sha256,
           operation.state_sha256,operation.ack_sha256,operation.registry_sequence,
           operation.ack_registry_kid,operation.proposal_expires_at
    INTO v_status,v_operation_environment,v_operation_actor,v_operation_request,
         v_operation_registry,v_operation_scope,v_operation_generation,v_operation_proposal,
         v_operation_previous,v_operation_state,v_operation_ack,v_operation_sequence,
         v_operation_ack_kid,v_operation_expires_at
    FROM platform.iam_platform_owner_transfer_operations AS operation
    WHERE operation.operation_id = p_operation_id FOR UPDATE;
    IF v_status = 'ack_verified' THEN
        IF v_operation_request <> p_request_sha256 OR v_operation_ack <> p_ack_sha256 OR
           v_operation_sequence <> p_registry_sequence OR v_operation_ack_kid <> p_ack_registry_kid THEN
            RAISE EXCEPTION USING ERRCODE = 'P1401', MESSAGE = 'Owner transfer acknowledgement conflicts';
        END IF;
        RETURN QUERY SELECT p_operation_id,v_operation_registry,v_operation_scope,
            v_operation_generation,v_operation_previous,v_operation_state,
            v_operation_proposal,v_status,true;
        RETURN;
    END IF;
    SELECT head.generation, head.state_sha256 INTO v_head_generation, v_head_sha
    FROM platform.iam_protected_authority_heads AS head
    WHERE head.environment_id = v_environment_id FOR UPDATE;
    IF v_status IS NULL OR v_status <> 'prepared' OR
       v_operation_environment <> v_environment_id OR v_operation_actor <> p_actor_id OR
       v_operation_request <> p_request_sha256 OR v_operation_registry <> p_registry_binding_id OR
       v_operation_scope <> p_scope_id OR p_scope_id <> v_environment_id OR
       v_operation_generation <> p_generation OR v_operation_proposal <> p_proposal_sha256 OR
       v_operation_previous <> p_previous_head_sha256 OR v_operation_state <> p_state_sha256 OR
       p_ack_issued_at > v_operation_expires_at OR
       v_head_generation <> p_generation - 1 OR v_head_sha <> p_previous_head_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer acknowledgement CAS failed';
    END IF;
    UPDATE platform.iam_platform_owner_transfer_operations AS operation
    SET status = 'ack_verified', registry_sequence = p_registry_sequence,
        ack_sha256 = p_ack_sha256, ack_registry_kid = p_ack_registry_kid,
        ack_issued_at = p_ack_issued_at, revision = operation.revision + 1, updated_at = v_now
    WHERE operation.operation_id = p_operation_id AND operation.status = 'prepared';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer acknowledgement changed';
    END IF;
    RETURN QUERY SELECT p_operation_id,v_operation_registry,v_operation_scope,
        v_operation_generation,v_operation_previous,v_operation_state,
        v_operation_proposal,'ack_verified'::text,false;
END;
$_$;


ALTER FUNCTION platform.iam_owner_transfer_ack_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint, p_registry_binding_id uuid, p_scope_id uuid, p_registry_sequence bigint, p_generation bigint, p_proposal_sha256 bytea, p_previous_head_sha256 bytea, p_state_sha256 bytea, p_ack_sha256 bytea, p_ack_issued_at timestamp with time zone, p_ack_registry_kid text) OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_commit_v1(uuid, uuid, bytea, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_owner_transfer_commit_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint) RETURNS TABLE(operation_id uuid, predecessor_user_id uuid, successor_user_id uuid, predecessor_token_version bigint, predecessor_authorization_version bigint, successor_token_version bigint, successor_authorization_version bigint, predecessor_expected_revision bigint, successor_expected_revision bigint, owner_policy_revision bigint, platform_clock bigint, head_generation bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_environment_id uuid; v_owner_subject_id uuid; v_clock bigint;
    v_successor_user_id uuid; v_successor_subject_plan uuid; v_successor_binding_plan uuid;
    v_successor_subject_id uuid; v_successor_binding_id uuid; v_owner_role_id uuid;
    v_predecessor_binding_id uuid; v_policy_revision bigint; v_generation bigint;
    v_previous_head bytea; v_state_sha bytea; v_ack_sha bytea;
    v_actor_token bigint; v_actor_auth bigint; v_successor_token bigint; v_successor_auth bigint;
    v_actor_revision bigint; v_successor_revision bigint;
    v_status text; v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_operation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_actor_id IS NULL OR p_expected_platform_clock < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Owner transfer commit is invalid';
    END IF;
    SELECT operation.status, operation.successor_user_id,
           operation.successor_subject_id, operation.successor_binding_id,
           operation.actor_expected_token_version, operation.actor_expected_authorization_version,
           operation.successor_expected_token_version, operation.successor_expected_authorization_version,
           operation.actor_expected_revision, operation.successor_expected_revision,
           operation.generation, operation.previous_head_sha256,
           operation.state_sha256, operation.ack_sha256,
           operation.owner_policy_revision, operation.platform_clock
    INTO v_status, v_successor_user_id, v_successor_subject_plan, v_successor_binding_plan,
         v_actor_token, v_actor_auth, v_successor_token, v_successor_auth,
         v_actor_revision, v_successor_revision,
         v_generation, v_previous_head, v_state_sha, v_ack_sha, v_policy_revision, v_clock
    FROM platform.iam_platform_owner_transfer_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.actor_user_id = p_actor_id
      AND operation.request_sha256 = p_request_sha256 FOR UPDATE;
    IF v_status = 'completed' THEN
        RETURN QUERY SELECT p_operation_id,p_actor_id,v_successor_user_id,
            v_actor_token + 1,v_actor_auth + 1,v_successor_token + 1,v_successor_auth + 1,
            v_actor_revision,v_successor_revision,
            v_policy_revision,v_clock,v_generation,true;
        RETURN;
    END IF;
    IF v_status <> 'ack_verified' THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer ack is not current';
    END IF;
    SELECT context.environment_id, context.owner_subject_id, context.platform_clock
    INTO v_environment_id, v_owner_subject_id, v_clock
    FROM platform.iam_platform_owner_context_lock_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock
    ) AS context;
    SELECT policy.owner_binding_id, policy.revision, binding.role_id
    INTO v_predecessor_binding_id, v_policy_revision, v_owner_role_id
    FROM platform.iam_platform_owner_policies AS policy
    JOIN platform.iam_platform_subject_roles AS binding
      ON binding.environment_id = policy.environment_id AND binding.id = policy.owner_binding_id
    WHERE policy.environment_id = v_environment_id FOR UPDATE OF policy, binding;
    IF v_environment_id IS NULL OR v_policy_revision IS NULL OR
       v_generation IS NULL OR v_clock <> p_expected_platform_clock THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer authority changed';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.iam_platform_owner_transfer_operations AS operation
        WHERE operation.operation_id = p_operation_id AND operation.environment_id = v_environment_id
          AND operation.expected_owner_policy_revision = v_policy_revision
          AND operation.expected_platform_clock = p_expected_platform_clock) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer policy changed';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.iam_protected_authority_heads AS head
        WHERE head.environment_id = v_environment_id AND head.generation = v_generation - 1
          AND head.state_sha256 = v_previous_head FOR UPDATE) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer head changed';
    END IF;
    INSERT INTO platform.iam_platform_subjects (
        id,environment_id,primary_tenant_id,user_id,state,revision,created_at,updated_at,retired_at
    ) VALUES (v_successor_subject_plan,v_environment_id,p_tenant_id,v_successor_user_id,
        'active',1,v_now,v_now,NULL) ON CONFLICT DO NOTHING;
    SELECT subject.id INTO v_successor_subject_id
    FROM platform.iam_platform_subjects AS subject
    WHERE subject.environment_id = v_environment_id AND subject.primary_tenant_id = p_tenant_id
      AND subject.user_id = v_successor_user_id AND subject.state = 'active' FOR SHARE;
    IF v_successor_subject_id <> v_successor_subject_plan THEN
        RAISE EXCEPTION USING ERRCODE = 'P1401', MESSAGE = 'Owner successor subject conflicts';
    END IF;
    INSERT INTO platform.iam_platform_subject_roles (
        id,environment_id,subject_id,role_id,state,revision,created_at,updated_at,revoked_at
    ) VALUES (v_successor_binding_plan,v_environment_id,v_successor_subject_id,
        v_owner_role_id,'active',1,v_now,v_now,NULL);
    v_successor_binding_id := v_successor_binding_plan;
    UPDATE platform.iam_platform_owner_policies
    SET owner_binding_id = v_successor_binding_id, revision = revision + 1, updated_at = v_now
    WHERE environment_id = v_environment_id AND owner_binding_id = v_predecessor_binding_id
      AND revision = v_policy_revision RETURNING revision INTO v_policy_revision;
    IF v_policy_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer policy CAS failed';
    END IF;
    UPDATE platform.iam_platform_subject_roles
    SET state = 'revoked', revision = revision + 1, updated_at = v_now, revoked_at = v_now
    WHERE environment_id = v_environment_id AND id = v_predecessor_binding_id AND state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner predecessor changed';
    END IF;
    UPDATE platform.iam_platform_authorization_clocks
    SET authorization_clock = authorization_clock + 1, revision = revision + 1, updated_at = v_now
    WHERE environment_id = v_environment_id AND authorization_clock = p_expected_platform_clock
    RETURNING authorization_clock INTO v_clock;
    UPDATE platform.iam_protected_authority_heads
    SET generation = v_generation, state_sha256 = v_state_sha, ack_sha256 = v_ack_sha,
        revision = revision + 1, updated_at = v_now
    WHERE environment_id = v_environment_id AND generation = v_generation - 1
      AND state_sha256 = v_previous_head;
    IF NOT FOUND OR v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer commit CAS failed';
    END IF;
    UPDATE platform.iam_platform_owner_transfer_operations AS operation
    SET status = 'completed', predecessor_token_version = v_actor_token + 1,
        predecessor_authorization_version = v_actor_auth + 1,
        successor_token_version = v_successor_token + 1,
        successor_authorization_version = v_successor_auth + 1,
        owner_policy_revision = v_policy_revision, platform_clock = v_clock,
        revision = operation.revision + 1, updated_at = v_now, completed_at = v_now
    WHERE operation.operation_id = p_operation_id AND operation.status = 'ack_verified';
    RETURN QUERY SELECT p_operation_id,p_actor_id,v_successor_user_id,
        v_actor_token + 1,v_actor_auth + 1,v_successor_token + 1,v_successor_auth + 1,
        v_actor_revision,v_successor_revision,
        v_policy_revision,v_clock,v_generation,false;
END;
$$;


ALTER FUNCTION platform.iam_owner_transfer_commit_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_compensate_apply_v1(uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint, bytea, bytea, bytea, bytea, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_owner_transfer_compensate_apply_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint, p_registry_binding_id uuid, p_scope_id uuid, p_registry_sequence bigint, p_generation bigint, p_proposal_sha256 bytea, p_previous_head_sha256 bytea, p_state_sha256 bytea, p_ack_sha256 bytea, p_ack_issued_at timestamp with time zone, p_ack_registry_kid text) RETURNS TABLE(operation_id uuid, original_operation_id uuid, generation bigint, state_sha256 bytea, ack_sha256 bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_environment_id uuid; v_owner_subject_id uuid; v_clock bigint;
    v_original_operation_id uuid; v_original_generation bigint;
    v_original_previous_head bytea; v_compensates_ack bytea; v_status text;
    v_proposal_expires_at timestamptz; v_head_generation bigint; v_head_sha bytea;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_operation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_actor_id IS NULL OR p_registry_binding_id IS NULL OR p_scope_id IS NULL OR
       p_registry_sequence < 1 OR p_generation < 3 OR
       pg_catalog.octet_length(p_proposal_sha256) <> 32 OR
       pg_catalog.octet_length(p_previous_head_sha256) <> 32 OR
       pg_catalog.octet_length(p_state_sha256) <> 32 OR
       pg_catalog.octet_length(p_ack_sha256) <> 32 OR p_ack_issued_at > v_now OR
       p_ack_registry_kid !~ '^[a-z0-9][a-z0-9._-]{0,127}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Owner compensation acknowledgement is invalid';
    END IF;
    SELECT context.environment_id, context.owner_subject_id, context.platform_clock
    INTO v_environment_id, v_owner_subject_id, v_clock
    FROM platform.iam_platform_owner_context_lock_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock
    ) AS context;
    SELECT compensation.original_operation_id, compensation.status,
           compensation.compensates_ack_sha256, compensation.proposal_expires_at
    INTO v_original_operation_id, v_status, v_compensates_ack, v_proposal_expires_at
    FROM platform.iam_platform_owner_transfer_compensations AS compensation
    WHERE compensation.operation_id = p_operation_id AND compensation.environment_id = v_environment_id
      AND compensation.request_sha256 = p_request_sha256 AND compensation.actor_user_id = p_actor_id
      AND compensation.registry_binding_id = p_registry_binding_id
      AND compensation.scope_kind = 'environment' AND compensation.scope_id = p_scope_id
      AND compensation.generation = p_generation
      AND compensation.proposal_sha256 = p_proposal_sha256
      AND compensation.previous_head_sha256 = p_previous_head_sha256
      AND compensation.state_sha256 = p_state_sha256 FOR UPDATE;
    IF v_status = 'completed' THEN
        IF NOT EXISTS (SELECT 1 FROM platform.iam_platform_owner_transfer_compensations AS compensation
            WHERE compensation.operation_id = p_operation_id AND compensation.ack_sha256 = p_ack_sha256
              AND compensation.registry_sequence = p_registry_sequence
              AND compensation.ack_registry_kid = p_ack_registry_kid) THEN
            RAISE EXCEPTION USING ERRCODE = 'P1401', MESSAGE = 'Owner compensation ack conflicts';
        END IF;
        RETURN QUERY SELECT p_operation_id,v_original_operation_id,p_generation,
            p_state_sha256,p_ack_sha256,true;
        RETURN;
    END IF;
    SELECT operation.generation, operation.previous_head_sha256
    INTO v_original_generation, v_original_previous_head
    FROM platform.iam_platform_owner_transfer_operations AS operation
    WHERE operation.operation_id = v_original_operation_id AND operation.status = 'ack_verified'
      AND operation.ack_sha256 = v_compensates_ack FOR UPDATE;
    SELECT head.generation, head.state_sha256 INTO v_head_generation, v_head_sha
    FROM platform.iam_protected_authority_heads AS head
    WHERE head.environment_id = v_environment_id FOR UPDATE;
    IF v_environment_id IS NULL OR v_status <> 'prepared' OR p_scope_id <> v_environment_id OR
       p_ack_issued_at > v_proposal_expires_at OR v_original_generation IS NULL OR
       p_generation <> v_original_generation + 1 OR
       v_head_generation <> v_original_generation - 1 OR
       v_head_sha <> v_original_previous_head THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner compensation ABA guard failed';
    END IF;
    UPDATE platform.iam_protected_authority_heads AS head
    SET generation = p_generation, state_sha256 = p_state_sha256, ack_sha256 = p_ack_sha256,
        revision = head.revision + 1, updated_at = v_now
    WHERE head.environment_id = v_environment_id AND head.generation = v_original_generation - 1
      AND head.state_sha256 = v_original_previous_head;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner compensation head changed';
    END IF;
    UPDATE platform.iam_platform_owner_transfer_compensations AS compensation
    SET status = 'completed', registry_sequence = p_registry_sequence,
        ack_sha256 = p_ack_sha256, ack_registry_kid = p_ack_registry_kid,
        ack_issued_at = p_ack_issued_at, revision = compensation.revision + 1,
        updated_at = v_now, completed_at = v_now
    WHERE compensation.operation_id = p_operation_id AND compensation.status = 'prepared';
    UPDATE platform.iam_platform_owner_transfer_operations AS operation
    SET status = 'compensated', revision = operation.revision + 1,
        updated_at = v_now, completed_at = v_now
    WHERE operation.operation_id = v_original_operation_id AND operation.status = 'ack_verified';
    RETURN QUERY SELECT p_operation_id,v_original_operation_id,p_generation,
        p_state_sha256,p_ack_sha256,false;
END;
$_$;


ALTER FUNCTION platform.iam_owner_transfer_compensate_apply_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint, p_registry_binding_id uuid, p_scope_id uuid, p_registry_sequence bigint, p_generation bigint, p_proposal_sha256 bytea, p_previous_head_sha256 bytea, p_state_sha256 bytea, p_ack_sha256 bytea, p_ack_issued_at timestamp with time zone, p_ack_registry_kid text) OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_compensate_prepare_v1(uuid, uuid, bytea, uuid, bigint, uuid, bytea, bigint, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_owner_transfer_compensate_prepare_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint, p_original_operation_id uuid, p_original_ack_sha256 bytea, p_expected_original_generation bigint, p_proposal_sha256 bytea, p_proposal_signer_kid text, p_proposal_signature_sha256 bytea, p_proposal_expires_at timestamp with time zone) RETURNS TABLE(operation_id uuid, registry_binding_id uuid, scope_id uuid, generation bigint, previous_head_sha256 bytea, state_sha256 bytea, proposal_sha256 bytea, status text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_environment_id uuid; v_owner_subject_id uuid; v_clock bigint;
    v_registry_binding_id uuid; v_original_generation bigint;
    v_original_previous_head bytea; v_original_state bytea; v_original_status text;
    v_head_generation bigint; v_head_sha bytea; v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_operation_id IS NULL OR p_operation_id = p_original_operation_id OR
       pg_catalog.octet_length(p_request_sha256) <> 32 OR p_actor_id IS NULL OR
       pg_catalog.octet_length(p_original_ack_sha256) <> 32 OR
       p_expected_original_generation < 2 OR pg_catalog.octet_length(p_proposal_sha256) <> 32 OR
       p_proposal_signer_kid !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_proposal_signature_sha256) <> 32 OR
       p_proposal_expires_at < v_now OR p_proposal_expires_at > v_now + INTERVAL '7 days' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Owner transfer compensation is invalid';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.iam_platform_owner_transfer_compensations AS compensation
               WHERE compensation.operation_id = p_operation_id) THEN
        IF NOT EXISTS (SELECT 1 FROM platform.iam_platform_owner_transfer_compensations AS compensation
            WHERE compensation.operation_id = p_operation_id
              AND compensation.original_operation_id = p_original_operation_id
              AND compensation.request_sha256 = p_request_sha256
              AND compensation.proposal_sha256 = p_proposal_sha256
              AND compensation.status = 'prepared') THEN
            RAISE EXCEPTION USING ERRCODE = 'P1401', MESSAGE = 'Owner compensation idempotency conflict';
        END IF;
        RETURN QUERY SELECT compensation.operation_id, compensation.registry_binding_id,
            compensation.scope_id, compensation.generation, compensation.previous_head_sha256,
            compensation.state_sha256, compensation.proposal_sha256, compensation.status, true
        FROM platform.iam_platform_owner_transfer_compensations AS compensation
        WHERE compensation.operation_id = p_operation_id;
        RETURN;
    END IF;
    SELECT context.environment_id, context.owner_subject_id, context.platform_clock
    INTO v_environment_id, v_owner_subject_id, v_clock
    FROM platform.iam_platform_owner_context_lock_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock
    ) AS context;
    SELECT operation.registry_binding_id, operation.generation,
           operation.previous_head_sha256, operation.state_sha256, operation.status
    INTO v_registry_binding_id, v_original_generation,
         v_original_previous_head, v_original_state, v_original_status
    FROM platform.iam_platform_owner_transfer_operations AS operation
    WHERE operation.operation_id = p_original_operation_id
      AND operation.environment_id = v_environment_id
      AND operation.actor_user_id = p_actor_id
      AND operation.ack_sha256 = p_original_ack_sha256 FOR UPDATE;
    SELECT head.generation, head.state_sha256 INTO v_head_generation, v_head_sha
    FROM platform.iam_protected_authority_heads AS head
    WHERE head.environment_id = v_environment_id FOR UPDATE;
    IF v_environment_id IS NULL OR v_original_status <> 'ack_verified' OR
       v_original_generation <> p_expected_original_generation OR
       v_head_generation <> v_original_generation - 1 OR
       v_head_sha <> v_original_previous_head THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner compensation CAS failed';
    END IF;
    INSERT INTO platform.iam_platform_owner_transfer_compensations (
        operation_id,original_operation_id,environment_id,request_sha256,actor_user_id,
        expected_platform_clock,registry_binding_id,scope_kind,scope_id,generation,
        previous_head_sha256,state_sha256,proposal_sha256,proposal_signer_kid,
        proposal_signature_sha256,proposal_expires_at,compensates_ack_sha256,
        status,revision,created_at,updated_at
    ) VALUES (p_operation_id,p_original_operation_id,v_environment_id,p_request_sha256,p_actor_id,
        p_expected_platform_clock,v_registry_binding_id,'environment',v_environment_id,
        v_original_generation + 1,v_original_state,v_original_previous_head,p_proposal_sha256,
        p_proposal_signer_kid,p_proposal_signature_sha256,p_proposal_expires_at,
        p_original_ack_sha256,'prepared',1,v_now,v_now);
    RETURN QUERY SELECT p_operation_id,v_registry_binding_id,v_environment_id,
        v_original_generation + 1,v_original_state,v_original_previous_head,
        p_proposal_sha256,'prepared'::text,false;
END;
$_$;


ALTER FUNCTION platform.iam_owner_transfer_compensate_prepare_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_platform_clock bigint, p_original_operation_id uuid, p_original_ack_sha256 bytea, p_expected_original_generation bigint, p_proposal_sha256 bytea, p_proposal_signer_kid text, p_proposal_signature_sha256 bytea, p_proposal_expires_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_compensation_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_owner_transfer_compensation_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Owner transfer compensation deletion is forbidden';
    ELSIF TG_OP = 'INSERT' AND (NEW.status <> 'prepared' OR NEW.revision <> 1) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Owner transfer compensation origin is invalid';
    ELSIF TG_OP = 'UPDATE' AND (
        NEW.operation_id IS DISTINCT FROM OLD.operation_id OR
        NEW.original_operation_id IS DISTINCT FROM OLD.original_operation_id OR
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.request_sha256 IS DISTINCT FROM OLD.request_sha256 OR
        NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id OR
        NEW.expected_platform_clock IS DISTINCT FROM OLD.expected_platform_clock OR
        NEW.registry_binding_id IS DISTINCT FROM OLD.registry_binding_id OR
        NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR NEW.scope_id IS DISTINCT FROM OLD.scope_id OR
        NEW.generation IS DISTINCT FROM OLD.generation OR
        NEW.previous_head_sha256 IS DISTINCT FROM OLD.previous_head_sha256 OR
        NEW.state_sha256 IS DISTINCT FROM OLD.state_sha256 OR
        NEW.proposal_sha256 IS DISTINCT FROM OLD.proposal_sha256 OR
        NEW.proposal_signer_kid IS DISTINCT FROM OLD.proposal_signer_kid OR
        NEW.proposal_signature_sha256 IS DISTINCT FROM OLD.proposal_signature_sha256 OR
        NEW.proposal_expires_at IS DISTINCT FROM OLD.proposal_expires_at OR
        NEW.compensates_ack_sha256 IS DISTINCT FROM OLD.compensates_ack_sha256 OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.revision IS DISTINCT FROM OLD.revision + 1 OR
        OLD.status <> 'prepared' OR NEW.status <> 'completed'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer compensation transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_owner_transfer_compensation_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_operation_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_owner_transfer_operation_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Owner transfer operation deletion is forbidden';
    ELSIF TG_OP = 'INSERT' AND (NEW.status <> 'prepared' OR NEW.revision <> 1) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Owner transfer operation origin is invalid';
    ELSIF TG_OP = 'UPDATE' AND (
        NEW.operation_id IS DISTINCT FROM OLD.operation_id OR
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.request_sha256 IS DISTINCT FROM OLD.request_sha256 OR
        NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id OR
        NEW.successor_user_id IS DISTINCT FROM OLD.successor_user_id OR
        NEW.actor_expected_revision IS DISTINCT FROM OLD.actor_expected_revision OR
        NEW.actor_expected_token_version IS DISTINCT FROM OLD.actor_expected_token_version OR
        NEW.actor_expected_authorization_version IS DISTINCT FROM OLD.actor_expected_authorization_version OR
        NEW.successor_expected_revision IS DISTINCT FROM OLD.successor_expected_revision OR
        NEW.successor_expected_token_version IS DISTINCT FROM OLD.successor_expected_token_version OR
        NEW.successor_expected_authorization_version IS DISTINCT FROM OLD.successor_expected_authorization_version OR
        NEW.successor_subject_id IS DISTINCT FROM OLD.successor_subject_id OR
        NEW.successor_binding_id IS DISTINCT FROM OLD.successor_binding_id OR
        NEW.expected_owner_policy_revision IS DISTINCT FROM OLD.expected_owner_policy_revision OR
        NEW.expected_platform_clock IS DISTINCT FROM OLD.expected_platform_clock OR
        NEW.registry_binding_id IS DISTINCT FROM OLD.registry_binding_id OR
        NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR NEW.scope_id IS DISTINCT FROM OLD.scope_id OR
        NEW.generation IS DISTINCT FROM OLD.generation OR
        NEW.previous_head_sha256 IS DISTINCT FROM OLD.previous_head_sha256 OR
        NEW.state_sha256 IS DISTINCT FROM OLD.state_sha256 OR
        NEW.proposal_sha256 IS DISTINCT FROM OLD.proposal_sha256 OR
        NEW.proposal_signer_kid IS DISTINCT FROM OLD.proposal_signer_kid OR
        NEW.proposal_signature_sha256 IS DISTINCT FROM OLD.proposal_signature_sha256 OR
        NEW.proposal_expires_at IS DISTINCT FROM OLD.proposal_expires_at OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.revision IS DISTINCT FROM OLD.revision + 1 OR
        NOT ((OLD.status = 'prepared' AND NEW.status = 'ack_verified') OR
             (OLD.status = 'ack_verified' AND NEW.status IN ('completed','compensated')))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer operation transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_owner_transfer_operation_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_prepare_v1(uuid, uuid, bytea, uuid, bigint, bigint, bigint, uuid, bigint, bigint, bigint, bigint, uuid, uuid, uuid, bigint, bigint, bytea, bytea, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_owner_transfer_prepare_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_actor_revision bigint, p_actor_token_version bigint, p_actor_authorization_version bigint, p_successor_id uuid, p_successor_revision bigint, p_successor_token_version bigint, p_successor_authorization_version bigint, p_expected_platform_clock bigint, p_successor_subject_id uuid, p_successor_binding_id uuid, p_registry_binding_id uuid, p_expected_policy_revision bigint, p_expected_head_generation bigint, p_expected_head_sha256 bytea, p_state_sha256 bytea, p_proposal_sha256 bytea, p_proposal_signer_kid text, p_proposal_signature_sha256 bytea, p_proposal_expires_at timestamp with time zone) RETURNS TABLE(operation_id uuid, registry_binding_id uuid, scope_id uuid, generation bigint, previous_head_sha256 bytea, state_sha256 bytea, proposal_sha256 bytea, status text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_environment_id uuid; v_owner_subject_id uuid; v_clock bigint;
    v_policy_revision bigint; v_head_generation bigint; v_head_sha bytea;
    v_existing_subject_id uuid; v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_operation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_actor_id IS NULL OR p_successor_id IS NULL OR p_actor_id = p_successor_id OR
       p_actor_revision < 1 OR p_actor_token_version < 1 OR p_actor_authorization_version < 1 OR
       p_successor_revision < 1 OR p_successor_token_version < 1 OR
       p_successor_authorization_version < 1 OR p_successor_subject_id IS NULL OR
       p_successor_binding_id IS NULL OR p_registry_binding_id IS NULL OR
       p_expected_policy_revision < 1 OR p_expected_head_generation < 1 OR
       pg_catalog.octet_length(p_expected_head_sha256) <> 32 OR
       pg_catalog.octet_length(p_state_sha256) <> 32 OR p_state_sha256 = p_expected_head_sha256 OR
       pg_catalog.octet_length(p_proposal_sha256) <> 32 OR
       p_proposal_signer_kid !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_proposal_signature_sha256) <> 32 OR
       p_proposal_expires_at < v_now OR p_proposal_expires_at > v_now + INTERVAL '7 days' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Owner transfer proposal is invalid';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.iam_platform_owner_transfer_operations AS operation
               WHERE operation.operation_id = p_operation_id) THEN
        IF NOT EXISTS (SELECT 1 FROM platform.iam_platform_owner_transfer_operations AS operation
            WHERE operation.operation_id = p_operation_id AND operation.request_sha256 = p_request_sha256
              AND operation.actor_user_id = p_actor_id AND operation.successor_user_id = p_successor_id
              AND operation.proposal_sha256 = p_proposal_sha256 AND operation.status = 'prepared') THEN
            RAISE EXCEPTION USING ERRCODE = 'P1401', MESSAGE = 'Owner transfer idempotency conflict';
        END IF;
        RETURN QUERY SELECT operation.operation_id, operation.registry_binding_id,
            operation.scope_id, operation.generation, operation.previous_head_sha256,
            operation.state_sha256, operation.proposal_sha256, operation.status, true
        FROM platform.iam_platform_owner_transfer_operations AS operation
        WHERE operation.operation_id = p_operation_id;
        RETURN;
    END IF;
    SELECT context.environment_id, context.owner_subject_id, context.platform_clock
    INTO v_environment_id, v_owner_subject_id, v_clock
    FROM platform.iam_platform_owner_context_lock_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock
    ) AS context;
    IF v_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Current actor is not the Instance Owner';
    END IF;
    SELECT policy.revision INTO v_policy_revision
    FROM platform.iam_platform_owner_policies AS policy
    WHERE policy.environment_id = v_environment_id FOR UPDATE;
    SELECT head.generation, head.state_sha256 INTO v_head_generation, v_head_sha
    FROM platform.iam_protected_authority_heads AS head
    WHERE head.environment_id = v_environment_id AND head.registry_binding_id = p_registry_binding_id
      AND head.scope_kind = 'environment' AND head.scope_id = v_environment_id FOR UPDATE;
    SELECT subject.id INTO v_existing_subject_id
    FROM platform.iam_platform_subjects AS subject
    WHERE subject.environment_id = v_environment_id AND subject.primary_tenant_id = p_tenant_id
      AND subject.user_id = p_successor_id AND subject.state = 'active' FOR SHARE;
    IF v_policy_revision <> p_expected_policy_revision OR v_head_generation <> p_expected_head_generation OR
       v_head_sha <> p_expected_head_sha256 OR
       (v_existing_subject_id IS NOT NULL AND v_existing_subject_id <> p_successor_subject_id) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer authority head is stale';
    END IF;
    INSERT INTO platform.iam_platform_owner_transfer_operations (
        operation_id,environment_id,request_sha256,actor_user_id,successor_user_id,
        actor_expected_revision,actor_expected_token_version,actor_expected_authorization_version,
        successor_expected_revision,successor_expected_token_version,successor_expected_authorization_version,
        successor_subject_id,successor_binding_id,expected_owner_policy_revision,expected_platform_clock,
        registry_binding_id,scope_kind,scope_id,generation,previous_head_sha256,state_sha256,
        proposal_sha256,proposal_signer_kid,proposal_signature_sha256,proposal_expires_at,
        status,revision,created_at,updated_at
    ) VALUES (p_operation_id,v_environment_id,p_request_sha256,p_actor_id,p_successor_id,
        p_actor_revision,p_actor_token_version,p_actor_authorization_version,
        p_successor_revision,p_successor_token_version,p_successor_authorization_version,
        p_successor_subject_id,p_successor_binding_id,p_expected_policy_revision,p_expected_platform_clock,
        p_registry_binding_id,'environment',v_environment_id,p_expected_head_generation + 1,
        p_expected_head_sha256,p_state_sha256,p_proposal_sha256,p_proposal_signer_kid,
        p_proposal_signature_sha256,p_proposal_expires_at,'prepared',1,v_now,v_now);
    RETURN QUERY SELECT p_operation_id,p_registry_binding_id,v_environment_id,
        p_expected_head_generation + 1,p_expected_head_sha256,p_state_sha256,
        p_proposal_sha256,'prepared'::text,false;
END;
$_$;


ALTER FUNCTION platform.iam_owner_transfer_prepare_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_actor_revision bigint, p_actor_token_version bigint, p_actor_authorization_version bigint, p_successor_id uuid, p_successor_revision bigint, p_successor_token_version bigint, p_successor_authorization_version bigint, p_expected_platform_clock bigint, p_successor_subject_id uuid, p_successor_binding_id uuid, p_registry_binding_id uuid, p_expected_policy_revision bigint, p_expected_head_generation bigint, p_expected_head_sha256 bytea, p_state_sha256 bytea, p_proposal_sha256 bytea, p_proposal_signer_kid text, p_proposal_signature_sha256 bytea, p_proposal_expires_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_platform_authorize_decide_v1(uuid, uuid, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_authorize_decide_v1(p_tenant_id uuid, p_user_id uuid, p_expected_platform_clock bigint, p_capability text) RETURNS TABLE(allowed boolean, deployment_mode text, subject_id uuid, platform_clock bigint, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_environment_id uuid;
    v_mode text;
    v_purpose text;
    v_subject_id uuid;
    v_clock bigint;
    v_permission_id uuid;
    v_allowed boolean := false;
BEGIN
    SELECT context.environment_id, context.deployment_mode,
           context.tenant_purpose, context.subject_id, context.platform_clock
    INTO v_environment_id, v_mode, v_purpose, v_subject_id, v_clock
    FROM platform.iam_platform_session_context_read_v1(
        p_tenant_id, p_user_id
    ) AS context;
    IF v_environment_id IS NULL OR v_purpose = 'saas_customer' OR
       v_clock <> p_expected_platform_clock THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'Platform authorization context is stale or unavailable';
    END IF;
    SELECT permission.id INTO v_permission_id
    FROM platform.iam_platform_permissions AS permission
    WHERE permission.permission_key = p_capability
      AND permission.match_kind = 'exact' AND permission.state = 'active'
      AND permission.deployment_mode IN ('both', v_mode);
    IF v_subject_id IS NOT NULL AND v_permission_id IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1
            FROM platform.iam_platform_subject_roles AS subject_binding
            JOIN platform.iam_platform_roles AS role
              ON role.environment_id = subject_binding.environment_id
             AND role.id = subject_binding.role_id AND role.state = 'active'
            JOIN platform.iam_platform_role_permissions AS role_permission
              ON role_permission.environment_id = role.environment_id
             AND role_permission.role_id = role.id AND role_permission.state = 'active'
            JOIN platform.iam_platform_permissions AS granted
              ON granted.id = role_permission.permission_id AND granted.state = 'active'
            LEFT JOIN platform.iam_platform_owner_policies AS owner_policy
              ON owner_policy.environment_id = subject_binding.environment_id
             AND owner_policy.owner_binding_id = subject_binding.id
            WHERE subject_binding.environment_id = v_environment_id
              AND subject_binding.subject_id = v_subject_id
              AND subject_binding.state = 'active'
              AND ((role.role_kind = 'instance_owner'
                    AND owner_policy.owner_binding_id IS NOT NULL
                    AND granted.match_kind = 'environment_all')
                OR (role.role_kind = 'platform_operator'
                    AND granted.id = v_permission_id
                    AND granted.match_kind = 'exact' AND granted.delegable))
        ) INTO v_allowed;
    END IF;
    allowed := v_allowed;
    deployment_mode := v_mode;
    subject_id := v_subject_id;
    platform_clock := v_clock;
    reason := CASE WHEN v_allowed THEN 'granted' ELSE 'not_granted' END;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.iam_platform_authorize_decide_v1(p_tenant_id uuid, p_user_id uuid, p_expected_platform_clock bigint, p_capability text) OWNER TO harpy_owner;

--
-- Name: iam_platform_clock_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_clock_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform authorization clock deletion is forbidden';
    ELSIF TG_OP = 'INSERT' AND
          (NEW.authorization_clock IS DISTINCT FROM 1 OR NEW.revision IS DISTINCT FROM 1) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform authorization clock origin is invalid';
    ELSIF TG_OP = 'UPDATE' AND (
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR
        NEW.authorization_clock IS DISTINCT FROM OLD.authorization_clock + 1 OR
        NEW.revision IS DISTINCT FROM OLD.revision + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform authorization clock step is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_platform_clock_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_current_owner_projection_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_current_owner_projection_v1(p_expected_environment_id uuid) RETURNS TABLE(environment_id uuid, owner_binding_id uuid, owner_policy_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT policy.environment_id,policy.owner_binding_id,policy.revision
      FROM platform.iam_platform_owner_policies AS policy
      JOIN platform.iam_platform_subject_roles AS binding
        ON binding.environment_id = policy.environment_id
       AND binding.id = policy.owner_binding_id
       AND binding.state = 'active'
      JOIN platform.iam_platform_roles AS role
        ON role.environment_id = binding.environment_id
       AND role.id = binding.role_id
       AND role.role_kind = 'instance_owner'
       AND role.state = 'active'
      JOIN platform.iam_platform_subjects AS subject
        ON subject.environment_id = binding.environment_id
       AND subject.id = binding.subject_id
       AND subject.state = 'active'
     WHERE policy.environment_id = p_expected_environment_id;
END;
$$;


ALTER FUNCTION platform.iam_platform_current_owner_projection_v1(p_expected_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_platform_current_owner_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_current_owner_v1(p_tenant_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM platform.iam_platform_owner_policies AS policy
        JOIN platform.iam_platform_subject_roles AS owner_binding
          ON owner_binding.environment_id = policy.environment_id
         AND owner_binding.id = policy.owner_binding_id AND owner_binding.state = 'active'
        JOIN platform.iam_platform_subjects AS subject
          ON subject.environment_id = owner_binding.environment_id
         AND subject.id = owner_binding.subject_id AND subject.state = 'active'
        WHERE subject.primary_tenant_id = p_tenant_id AND subject.user_id = p_user_id
    );
END;
$$;


ALTER FUNCTION platform.iam_platform_current_owner_v1(p_tenant_id uuid, p_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_platform_operator_grant_apply_v1(uuid, uuid, bytea, uuid, uuid, bigint, bigint, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_operator_grant_apply_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_target_user_id uuid, p_target_authorization_version bigint, p_expected_platform_clock bigint, p_subject_id uuid, p_role_id uuid, p_subject_role_binding_id uuid, p_role_permission_binding_id uuid, p_capability text) RETURNS TABLE(target_user_id uuid, subject_id uuid, role_id uuid, subject_role_binding_id uuid, role_permission_binding_id uuid, target_authorization_version bigint, platform_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_environment_id uuid;
    v_mode text;
    v_owner_subject_id uuid;
    v_prior_clock bigint;
    v_permission_id uuid;
    v_subject_id uuid;
    v_role_id uuid;
    v_subject_role_id uuid;
    v_role_permission_id uuid;
    v_clock bigint;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF EXISTS (SELECT 1 FROM platform.iam_platform_mutation_receipts AS receipt
               WHERE receipt.operation_id = p_operation_id) THEN
        IF NOT EXISTS (
            SELECT 1 FROM platform.iam_platform_mutation_receipts AS receipt
            JOIN platform.iam_platform_permissions AS permission
              ON permission.id = receipt.permission_id
            JOIN platform.iam_platform_subjects AS subject
              ON subject.environment_id = receipt.environment_id
             AND subject.id = receipt.subject_id
            WHERE receipt.operation_id = p_operation_id
              AND receipt.mutation_kind = 'operator_grant'
              AND receipt.request_sha256 = p_request_sha256
              AND receipt.actor_user_id = p_actor_id
              AND receipt.target_user_id = p_target_user_id
              AND receipt.target_authorization_version = p_target_authorization_version
              AND permission.permission_key = p_capability
              AND subject.primary_tenant_id = p_tenant_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P1401',
                MESSAGE = 'Platform operator grant idempotency conflict';
        END IF;
        RETURN QUERY SELECT receipt.target_user_id, receipt.subject_id,
            receipt.role_id, receipt.subject_role_binding_id,
            receipt.role_permission_binding_id,
            receipt.target_authorization_version, receipt.platform_clock, true
        FROM platform.iam_platform_mutation_receipts AS receipt
        WHERE receipt.operation_id = p_operation_id;
        RETURN;
    END IF;

    SELECT context.environment_id, context.deployment_mode,
           context.owner_subject_id, context.platform_clock
    INTO v_environment_id, v_mode, v_owner_subject_id, v_prior_clock
    FROM platform.iam_platform_owner_context_lock_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock
    ) AS context;
    IF v_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Current actor is not the Instance Owner';
    END IF;
    SELECT permission.id INTO v_permission_id
    FROM platform.iam_platform_permissions AS permission
    WHERE permission.permission_key = p_capability AND permission.match_kind = 'exact'
      AND permission.state = 'active' AND permission.delegable
      AND NOT permission.owner_only
      AND permission.deployment_mode IN ('both', v_mode) FOR SHARE;
    IF v_permission_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Platform capability cannot be delegated';
    END IF;

    INSERT INTO platform.iam_platform_subjects (
        id, environment_id, primary_tenant_id, user_id, state, revision,
        created_at, updated_at, retired_at
    ) VALUES (p_subject_id, v_environment_id, p_tenant_id, p_target_user_id,
        'active', 1, v_now, v_now, NULL) ON CONFLICT DO NOTHING;
    SELECT subject.id INTO v_subject_id FROM platform.iam_platform_subjects AS subject
    WHERE subject.environment_id = v_environment_id
      AND subject.primary_tenant_id = p_tenant_id
      AND subject.user_id = p_target_user_id AND subject.state = 'active' FOR SHARE;

    INSERT INTO platform.iam_platform_roles (
        id, environment_id, role_kind, role_key, state, revision,
        created_at, updated_at, retired_at
    ) VALUES (p_role_id, v_environment_id, 'platform_operator',
        'platform_operator.' || p_target_user_id::text,
        'active', 1, v_now, v_now, NULL) ON CONFLICT DO NOTHING;
    SELECT role.id INTO v_role_id FROM platform.iam_platform_roles AS role
    WHERE role.environment_id = v_environment_id
      AND role.role_key = 'platform_operator.' || p_target_user_id::text
      AND role.role_kind = 'platform_operator' AND role.state = 'active' FOR SHARE;
    IF v_subject_id IS NULL OR v_role_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P1401',
            MESSAGE = 'Platform operator identity plan conflicts with stored authority';
    END IF;

    SELECT binding.id INTO v_subject_role_id
    FROM platform.iam_platform_subject_roles AS binding
    WHERE binding.environment_id = v_environment_id
      AND binding.subject_id = v_subject_id AND binding.role_id = v_role_id
      AND binding.state = 'active' FOR SHARE;
    IF v_subject_role_id IS NULL THEN
        INSERT INTO platform.iam_platform_subject_roles (
            id, environment_id, subject_id, role_id, state, revision,
            created_at, updated_at, revoked_at
        ) VALUES (p_subject_role_binding_id, v_environment_id, v_subject_id,
            v_role_id, 'active', 1, v_now, v_now, NULL)
        RETURNING id INTO v_subject_role_id;
    END IF;
    IF EXISTS (SELECT 1 FROM platform.iam_platform_role_permissions AS binding
        WHERE binding.environment_id = v_environment_id AND binding.role_id = v_role_id
          AND binding.permission_id = v_permission_id AND binding.state = 'active') THEN
        RAISE EXCEPTION USING ERRCODE = 'P1401',
            MESSAGE = 'Platform capability is already delegated';
    END IF;
    INSERT INTO platform.iam_platform_role_permissions (
        id, environment_id, role_id, permission_id, state, revision,
        created_at, updated_at, revoked_at
    ) VALUES (p_role_permission_binding_id, v_environment_id, v_role_id,
        v_permission_id, 'active', 1, v_now, v_now, NULL)
    RETURNING id INTO v_role_permission_id;

    UPDATE platform.iam_platform_authorization_clocks
    SET authorization_clock = authorization_clock + 1, revision = revision + 1,
        updated_at = v_now
    WHERE environment_id = v_environment_id
      AND authorization_clock = p_expected_platform_clock
    RETURNING authorization_clock INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'Platform operator grant authority changed';
    END IF;
    INSERT INTO platform.iam_platform_mutation_receipts VALUES (
        p_operation_id, v_environment_id, 'operator_grant', p_request_sha256,
        p_actor_id, p_target_user_id, v_subject_id, v_role_id, v_subject_role_id,
        v_role_permission_id, v_permission_id, p_target_authorization_version,
        v_clock, v_now
    );
    RETURN QUERY SELECT p_target_user_id, v_subject_id, v_role_id,
        v_subject_role_id, v_role_permission_id,
        p_target_authorization_version, v_clock, false;
END;
$$;


ALTER FUNCTION platform.iam_platform_operator_grant_apply_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_target_user_id uuid, p_target_authorization_version bigint, p_expected_platform_clock bigint, p_subject_id uuid, p_role_id uuid, p_subject_role_binding_id uuid, p_role_permission_binding_id uuid, p_capability text) OWNER TO harpy_owner;

--
-- Name: iam_platform_operator_revoke_apply_v1(uuid, uuid, bytea, uuid, uuid, bigint, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_operator_revoke_apply_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_target_user_id uuid, p_target_authorization_version bigint, p_expected_platform_clock bigint, p_capability text) RETURNS TABLE(target_user_id uuid, subject_id uuid, role_id uuid, subject_role_binding_id uuid, role_permission_binding_id uuid, target_authorization_version bigint, platform_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_environment_id uuid;
    v_mode text;
    v_owner_subject_id uuid;
    v_prior_clock bigint;
    v_permission_id uuid;
    v_subject_id uuid;
    v_role_id uuid;
    v_subject_role_id uuid;
    v_role_permission_id uuid;
    v_clock bigint;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF EXISTS (SELECT 1 FROM platform.iam_platform_mutation_receipts AS receipt
               WHERE receipt.operation_id = p_operation_id) THEN
        IF NOT EXISTS (
            SELECT 1 FROM platform.iam_platform_mutation_receipts AS receipt
            JOIN platform.iam_platform_permissions AS permission
              ON permission.id = receipt.permission_id
            JOIN platform.iam_platform_subjects AS subject
              ON subject.environment_id = receipt.environment_id
             AND subject.id = receipt.subject_id
            WHERE receipt.operation_id = p_operation_id
              AND receipt.mutation_kind = 'operator_revoke'
              AND receipt.request_sha256 = p_request_sha256
              AND receipt.actor_user_id = p_actor_id
              AND receipt.target_user_id = p_target_user_id
              AND receipt.target_authorization_version = p_target_authorization_version
              AND permission.permission_key = p_capability
              AND subject.primary_tenant_id = p_tenant_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P1401',
                MESSAGE = 'Platform operator revoke idempotency conflict';
        END IF;
        RETURN QUERY SELECT receipt.target_user_id, receipt.subject_id,
            receipt.role_id, receipt.subject_role_binding_id,
            receipt.role_permission_binding_id,
            receipt.target_authorization_version, receipt.platform_clock, true
        FROM platform.iam_platform_mutation_receipts AS receipt
        WHERE receipt.operation_id = p_operation_id;
        RETURN;
    END IF;

    SELECT context.environment_id, context.deployment_mode,
           context.owner_subject_id, context.platform_clock
    INTO v_environment_id, v_mode, v_owner_subject_id, v_prior_clock
    FROM platform.iam_platform_owner_context_lock_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock
    ) AS context;
    IF v_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Current actor is not the Instance Owner';
    END IF;
    SELECT permission.id INTO v_permission_id
    FROM platform.iam_platform_permissions AS permission
    WHERE permission.permission_key = p_capability AND permission.match_kind = 'exact'
      AND permission.state = 'active' AND permission.delegable
      AND NOT permission.owner_only
      AND permission.deployment_mode IN ('both', v_mode) FOR SHARE;
    IF v_permission_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Platform capability cannot be revoked';
    END IF;

    SELECT subject.id, role.id, subject_binding.id, permission_binding.id
    INTO v_subject_id, v_role_id, v_subject_role_id, v_role_permission_id
    FROM platform.iam_platform_subjects AS subject
    JOIN platform.iam_platform_subject_roles AS subject_binding
      ON subject_binding.environment_id = subject.environment_id
     AND subject_binding.subject_id = subject.id AND subject_binding.state = 'active'
    JOIN platform.iam_platform_roles AS role
      ON role.environment_id = subject_binding.environment_id
     AND role.id = subject_binding.role_id
     AND role.role_kind = 'platform_operator' AND role.state = 'active'
    JOIN platform.iam_platform_role_permissions AS permission_binding
      ON permission_binding.environment_id = role.environment_id
     AND permission_binding.role_id = role.id
     AND permission_binding.permission_id = v_permission_id
     AND permission_binding.state = 'active'
    WHERE subject.environment_id = v_environment_id
      AND subject.primary_tenant_id = p_tenant_id
      AND subject.user_id = p_target_user_id AND subject.state = 'active'
    FOR UPDATE OF permission_binding
    FOR SHARE OF subject, subject_binding, role;
    IF v_role_permission_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P1404',
            MESSAGE = 'Platform capability delegation was not found';
    END IF;
    UPDATE platform.iam_platform_role_permissions
    SET state = 'revoked', revision = revision + 1,
        updated_at = v_now, revoked_at = v_now
    WHERE environment_id = v_environment_id
      AND id = v_role_permission_id AND state = 'active';
    UPDATE platform.iam_platform_authorization_clocks
    SET authorization_clock = authorization_clock + 1, revision = revision + 1,
        updated_at = v_now
    WHERE environment_id = v_environment_id
      AND authorization_clock = p_expected_platform_clock
    RETURNING authorization_clock INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'Platform operator revoke authority changed';
    END IF;
    INSERT INTO platform.iam_platform_mutation_receipts VALUES (
        p_operation_id, v_environment_id, 'operator_revoke', p_request_sha256,
        p_actor_id, p_target_user_id, v_subject_id, v_role_id, v_subject_role_id,
        v_role_permission_id, v_permission_id, p_target_authorization_version,
        v_clock, v_now
    );
    RETURN QUERY SELECT p_target_user_id, v_subject_id, v_role_id,
        v_subject_role_id, v_role_permission_id,
        p_target_authorization_version, v_clock, false;
END;
$$;


ALTER FUNCTION platform.iam_platform_operator_revoke_apply_v1(p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_target_user_id uuid, p_target_authorization_version bigint, p_expected_platform_clock bigint, p_capability text) OWNER TO harpy_owner;

--
-- Name: iam_platform_owner_context_lock_v1(uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_owner_context_lock_v1(p_tenant_id uuid, p_user_id uuid, p_expected_platform_clock bigint) RETURNS TABLE(environment_id uuid, deployment_mode text, owner_subject_id uuid, platform_clock bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT policy.environment_id, deployment.deployment_mode,
           subject.id, clock.authorization_clock
    FROM platform.tenancy_tenant_bindings AS tenant_binding
    JOIN platform.tenancy_deployment_policy AS deployment
      ON deployment.environment_id = tenant_binding.environment_id
    JOIN platform.iam_platform_owner_policies AS policy
      ON policy.environment_id = deployment.environment_id
    JOIN platform.iam_platform_subject_roles AS owner_binding
      ON owner_binding.environment_id = policy.environment_id
     AND owner_binding.id = policy.owner_binding_id AND owner_binding.state = 'active'
    JOIN platform.iam_platform_roles AS owner_role
      ON owner_role.environment_id = owner_binding.environment_id
     AND owner_role.id = owner_binding.role_id
     AND owner_role.role_kind = 'instance_owner' AND owner_role.state = 'active'
    JOIN platform.iam_platform_subjects AS subject
      ON subject.environment_id = owner_binding.environment_id
     AND subject.id = owner_binding.subject_id AND subject.state = 'active'
     AND subject.primary_tenant_id = p_tenant_id AND subject.user_id = p_user_id
    JOIN platform.iam_platform_authorization_clocks AS clock
      ON clock.environment_id = policy.environment_id
    WHERE tenant_binding.tenant_id = p_tenant_id
      AND tenant_binding.purpose IN ('onpremise_primary', 'saas_control')
      AND clock.authorization_clock = p_expected_platform_clock
    FOR UPDATE OF clock
    FOR SHARE OF tenant_binding, deployment, policy, owner_binding, owner_role, subject;
END;
$$;


ALTER FUNCTION platform.iam_platform_owner_context_lock_v1(p_tenant_id uuid, p_user_id uuid, p_expected_platform_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_platform_owner_policy_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_owner_policy_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE binding_kind text; binding_state text; subject_state text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Instance Owner policy deletion is forbidden';
    END IF;
    SELECT role.role_kind, binding.state, subject.state
    INTO binding_kind, binding_state, subject_state
    FROM platform.iam_platform_subject_roles AS binding
    JOIN platform.iam_platform_roles AS role
      ON role.environment_id = binding.environment_id AND role.id = binding.role_id
    JOIN platform.iam_platform_subjects AS subject
      ON subject.environment_id = binding.environment_id AND subject.id = binding.subject_id
    WHERE binding.environment_id = NEW.environment_id AND binding.id = NEW.owner_binding_id
    FOR SHARE OF binding, role, subject;
    IF binding_kind IS DISTINCT FROM 'instance_owner' OR
       binding_state IS DISTINCT FROM 'active' OR subject_state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Instance Owner binding is invalid';
    END IF;
    IF TG_OP = 'INSERT' AND NEW.revision IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Instance Owner policy revision is invalid';
    ELSIF TG_OP = 'UPDATE' AND (
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.owner_binding_id IS NOT DISTINCT FROM OLD.owner_binding_id OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR
        NEW.revision IS DISTINCT FROM OLD.revision + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Instance Owner transfer CAS is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_platform_owner_policy_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_permission_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_permission_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE exact_key text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform permission deletion is forbidden';
    END IF;
    IF NEW.match_kind = 'exact' THEN
        SELECT resource.resource_key || '.' || action.action_key INTO exact_key
        FROM platform.iam_platform_resources AS resource
        JOIN platform.iam_platform_actions AS action ON action.id = NEW.action_id
        WHERE resource.id = NEW.resource_id AND resource.state = 'active'
          AND action.state = 'active' FOR SHARE OF resource, action;
        IF exact_key IS DISTINCT FROM NEW.permission_key THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'Platform permission key does not match its exact catalog pair';
        END IF;
    ELSIF NEW.permission_key IS DISTINCT FROM 'environment_all' OR
          NEW.delegable OR NOT NEW.owner_only OR NEW.deployment_mode <> 'both' THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'Reserved environment permission shape is invalid';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.id IS DISTINCT FROM OLD.id OR NEW.permission_key IS DISTINCT FROM OLD.permission_key OR
        NEW.match_kind IS DISTINCT FROM OLD.match_kind OR NEW.resource_id IS DISTINCT FROM OLD.resource_id OR
        NEW.action_id IS DISTINCT FROM OLD.action_id OR
        NEW.deployment_mode IS DISTINCT FROM OLD.deployment_mode OR
        NEW.delegable IS DISTINCT FROM OLD.delegable OR
        NEW.step_up_required IS DISTINCT FROM OLD.step_up_required OR
        NEW.owner_only IS DISTINCT FROM OLD.owner_only OR NEW.created_at IS DISTINCT FROM OLD.created_at OR
        OLD.state IS DISTINCT FROM 'active' OR NEW.state IS DISTINCT FROM 'retired' OR
        NEW.revision IS DISTINCT FROM OLD.revision + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform permission transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_platform_permission_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_receipt_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_receipt_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform IAM receipt is immutable';
END;
$$;


ALTER FUNCTION platform.iam_platform_receipt_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_role_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_role_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND OLD.role_kind = 'instance_owner') THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Reserved platform role mutation is forbidden';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.id IS DISTINCT FROM OLD.id OR NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.role_kind IS DISTINCT FROM OLD.role_kind OR NEW.role_key IS DISTINCT FROM OLD.role_key OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR OLD.state IS DISTINCT FROM 'active' OR
        NEW.state IS DISTINCT FROM 'retired' OR NEW.revision IS DISTINCT FROM OLD.revision + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform role transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_platform_role_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_role_permission_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_role_permission_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE role_kind text; permission_match text; permission_delegable boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform role permission deletion is forbidden';
    END IF;
    SELECT role.role_kind, permission.match_kind, permission.delegable
    INTO role_kind, permission_match, permission_delegable
    FROM platform.iam_platform_roles AS role
    JOIN platform.iam_platform_permissions AS permission ON permission.id = NEW.permission_id
    WHERE role.environment_id = NEW.environment_id AND role.id = NEW.role_id
      AND role.state = 'active' AND permission.state = 'active'
    FOR SHARE OF role, permission;
    IF (role_kind = 'instance_owner' AND permission_match <> 'environment_all') OR
       (role_kind = 'platform_operator' AND
        (permission_match <> 'exact' OR permission_delegable IS DISTINCT FROM true)) OR
       role_kind IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform role permission is reserved';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.id IS DISTINCT FROM OLD.id OR NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.role_id IS DISTINCT FROM OLD.role_id OR NEW.permission_id IS DISTINCT FROM OLD.permission_id OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR OLD.state IS DISTINCT FROM 'active' OR
        NEW.state IS DISTINCT FROM 'revoked' OR NEW.revision IS DISTINCT FROM OLD.revision + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform role permission transition is invalid';
    END IF;
    IF TG_OP = 'UPDATE' AND role_kind = 'instance_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Owner environment authority is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_platform_role_permission_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_session_context_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_session_context_read_v1(p_tenant_id uuid, p_user_id uuid) RETURNS TABLE(environment_id uuid, deployment_mode text, tenant_purpose text, subject_id uuid, platform_clock bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT binding.environment_id, deployment.deployment_mode, binding.purpose,
           CASE WHEN binding.purpose = 'saas_customer' THEN NULL ELSE subject.id END,
           CASE WHEN binding.purpose = 'saas_customer' THEN 0
                ELSE clock.authorization_clock END
    FROM platform.tenancy_tenant_bindings AS binding
    JOIN platform.tenancy_deployment_policy AS deployment
      ON deployment.environment_id = binding.environment_id
    LEFT JOIN platform.iam_platform_authorization_clocks AS clock
      ON clock.environment_id = binding.environment_id
    LEFT JOIN platform.iam_platform_subjects AS subject
      ON subject.environment_id = binding.environment_id
     AND subject.primary_tenant_id = p_tenant_id
     AND subject.user_id = p_user_id AND subject.state = 'active'
    WHERE binding.tenant_id = p_tenant_id
      AND (binding.purpose = 'saas_customer' OR clock.authorization_clock > 0);
END;
$$;


ALTER FUNCTION platform.iam_platform_session_context_read_v1(p_tenant_id uuid, p_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_platform_subject_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_subject_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE binding_purpose text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform subject deletion is forbidden';
    END IF;
    SELECT binding.purpose INTO binding_purpose
    FROM platform.tenancy_tenant_bindings AS binding
    WHERE binding.environment_id = NEW.environment_id
      AND binding.tenant_id = NEW.primary_tenant_id
    FOR SHARE;
    IF binding_purpose NOT IN ('onpremise_primary', 'saas_control') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Platform subject must belong to the immutable primary tenant';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.id IS DISTINCT FROM OLD.id OR
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.primary_tenant_id IS DISTINCT FROM OLD.primary_tenant_id OR
        NEW.user_id IS DISTINCT FROM OLD.user_id OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR
        OLD.state IS DISTINCT FROM 'active' OR NEW.state IS DISTINCT FROM 'retired' OR
        NEW.revision IS DISTINCT FROM OLD.revision + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform subject transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_platform_subject_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_subject_role_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_platform_subject_role_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE role_kind text; current_owner uuid;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform subject role deletion is forbidden';
    END IF;
    SELECT role.role_kind INTO role_kind FROM platform.iam_platform_roles AS role
    WHERE role.environment_id = NEW.environment_id AND role.id = NEW.role_id
      AND role.state = 'active' FOR SHARE;
    IF role_kind IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform role is not active';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        SELECT policy.owner_binding_id INTO current_owner
        FROM platform.iam_platform_owner_policies AS policy
        WHERE policy.environment_id = OLD.environment_id FOR SHARE;
        IF OLD.id = current_owner OR
           NEW.id IS DISTINCT FROM OLD.id OR NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
           NEW.subject_id IS DISTINCT FROM OLD.subject_id OR NEW.role_id IS DISTINCT FROM OLD.role_id OR
           NEW.created_at IS DISTINCT FROM OLD.created_at OR OLD.state IS DISTINCT FROM 'active' OR
           NEW.state IS DISTINCT FROM 'revoked' OR NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
            RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Platform subject role transition is invalid';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_platform_subject_role_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_post_restore_admission_v1(boolean); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_admission_v1(p_probe boolean) RETURNS TABLE(state text, environment_id uuid, restore_operation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
IF p_probe IS DISTINCT FROM true THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='post-restore admission probe is invalid';
END IF;
RETURN QUERY
WITH current_restore AS (
	SELECT event.operation_id,lineage.environment_id,lineage.current_database_system_id
	  FROM platform.platformops_database_lineages AS lineage
	  JOIN platform.platformops_database_lineage_events AS event
	    ON event.environment_id=lineage.environment_id
	   AND event.database_system_id=lineage.current_database_system_id
	   AND event.event_kind='restored'
	 ORDER BY event.generation DESC LIMIT 1
), restored_admission AS (
	SELECT COALESCE(reconciliation.state,'fenced') AS state,
	       restore.environment_id,restore.operation_id
	  FROM current_restore AS restore
	  LEFT JOIN platform.iam_post_restore_reconciliations AS reconciliation
	    ON reconciliation.restore_operation_id=restore.operation_id
	   AND reconciliation.environment_id=restore.environment_id
	   AND reconciliation.new_database_system_id=restore.current_database_system_id
)
SELECT admission.state,admission.environment_id,admission.operation_id
  FROM restored_admission AS admission
UNION ALL
SELECT reconciliation.state,reconciliation.environment_id,reconciliation.restore_operation_id
 FROM (SELECT candidate.* FROM platform.iam_post_restore_reconciliations AS candidate
		 ORDER BY candidate.created_at DESC LIMIT 1) AS reconciliation
 WHERE NOT EXISTS (SELECT 1 FROM current_restore)
;
END;
$$;


ALTER FUNCTION platform.iam_post_restore_admission_v1(p_probe boolean) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_binding_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_binding_v1(p_environment_id uuid, p_restore_operation_id uuid) RETURNS TABLE(tenant_id uuid, owner_user_id uuid, anchor_id uuid, new_database_system_id uuid, security_epoch bytea, tenant_slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
SELECT reconciliation.tenant_id,reconciliation.owner_user_id,reconciliation.anchor_id,
       reconciliation.new_database_system_id,reconciliation.security_epoch,tenant.slug::text
FROM platform.iam_post_restore_reconciliations AS reconciliation
	JOIN platform.tenants AS tenant ON tenant.id=reconciliation.tenant_id
WHERE reconciliation.environment_id=p_environment_id
  AND reconciliation.restore_operation_id=p_restore_operation_id
  AND reconciliation.state='identity_reactivation_required';
END;
$$;


ALTER FUNCTION platform.iam_post_restore_binding_v1(p_environment_id uuid, p_restore_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_challenge_context_v1(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_challenge_context_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_origin text, p_occurred_at timestamp with time zone) RETURNS TABLE(tenant_id uuid, owner_user_id uuid, anchor_id uuid, challenge text, credential_id bytea, public_key_cose bytea, rp_id text, sign_count bigint, context_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY SELECT challenge.tenant_id,challenge.owner_user_id,challenge.anchor_id,
        challenge.challenge,anchor.credential_id,anchor.public_key_cose,
		challenge.rp_id,anchor.sign_count,challenge.context_sha256
      FROM platform.iam_post_restore_challenges AS challenge
      JOIN platform.iam_post_restore_reconciliations AS reconciliation
        ON reconciliation.restore_operation_id=challenge.restore_operation_id
      JOIN platform.iam_recovery_anchors AS anchor ON anchor.anchor_id=challenge.anchor_id
     WHERE challenge.operation_id=p_operation_id
       AND challenge.environment_id=p_environment_id
       AND challenge.restore_operation_id=p_restore_operation_id
       AND challenge.origin=p_origin AND challenge.state='pending'
       AND challenge.expires_at>p_occurred_at
       AND reconciliation.state='identity_reactivation_required'
       AND anchor.state='active' AND anchor.user_verification='required'
       AND NOT anchor.backup_eligible AND NOT anchor.backup_state;
END;
$$;


ALTER FUNCTION platform.iam_post_restore_challenge_context_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_origin text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_challenge_v1(uuid, uuid, uuid, text, bytea, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_challenge_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_challenge text, p_context_sha256 bytea, p_rp_id text, p_origin text, p_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS TABLE(operation_id uuid, tenant_id uuid, owner_user_id uuid, anchor_id uuid, challenge text, credential_id bytea, public_key_cose bytea, rp_id text, sign_count bigint, expires_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_reconcile platform.iam_post_restore_reconciliations%ROWTYPE;
v_existing platform.iam_post_restore_challenges%ROWTYPE;
v_replayed boolean := false;
BEGIN
    IF p_operation_id IS NULL OR p_environment_id IS NULL OR p_restore_operation_id IS NULL OR
       p_challenge !~ '^[A-Za-z0-9_-]{43}$' OR pg_catalog.octet_length(p_context_sha256)<>32 OR
       pg_catalog.octet_length(p_rp_id) NOT BETWEEN 1 AND 253 OR
       pg_catalog.octet_length(p_origin) NOT BETWEEN 1 AND 512 OR
       p_expires_at<=p_occurred_at OR p_expires_at>p_occurred_at+INTERVAL '5 minutes' THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='post-restore challenge input is invalid';
    END IF;
    SELECT * INTO v_reconcile FROM platform.iam_post_restore_reconciliations
     WHERE restore_operation_id=p_restore_operation_id FOR UPDATE;
    IF NOT FOUND OR v_reconcile.environment_id<>p_environment_id OR
       v_reconcile.state<>'identity_reactivation_required' THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='post-restore reactivation is unavailable';
    END IF;
    UPDATE platform.iam_post_restore_challenges SET state='expired',terminal_at=p_occurred_at
     WHERE restore_operation_id=p_restore_operation_id AND state='pending'
       AND expires_at<=p_occurred_at;
	UPDATE platform.iam_post_restore_challenges SET state='failed',terminal_at=p_occurred_at
	 WHERE restore_operation_id=p_restore_operation_id AND state='pending'
	   AND operation_id<>p_operation_id;
    SELECT * INTO v_existing FROM platform.iam_post_restore_challenges
     WHERE operation_id=p_operation_id FOR SHARE;
    IF FOUND THEN
        v_replayed := true;
        IF v_existing.restore_operation_id<>p_restore_operation_id OR
           v_existing.environment_id<>p_environment_id OR v_existing.challenge<>p_challenge OR
           v_existing.context_sha256<>p_context_sha256 OR v_existing.rp_id<>p_rp_id OR
           v_existing.origin<>p_origin OR v_existing.expires_at<>p_expires_at THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='post-restore challenge replay conflicts';
        END IF;
    ELSE
        INSERT INTO platform.iam_post_restore_challenges(
            operation_id,restore_operation_id,environment_id,tenant_id,owner_user_id,
            anchor_id,challenge,context_sha256,rp_id,origin,state,created_at,expires_at
        ) VALUES (p_operation_id,p_restore_operation_id,p_environment_id,
            v_reconcile.tenant_id,v_reconcile.owner_user_id,v_reconcile.anchor_id,
            p_challenge,p_context_sha256,p_rp_id,p_origin,'pending',p_occurred_at,p_expires_at);
        SELECT * INTO v_existing FROM platform.iam_post_restore_challenges
         WHERE operation_id=p_operation_id;
    END IF;
    RETURN QUERY SELECT v_existing.operation_id,v_existing.tenant_id,v_existing.owner_user_id,
        v_existing.anchor_id,v_existing.challenge,anchor.credential_id,anchor.public_key_cose,
        v_existing.rp_id,anchor.sign_count,v_existing.expires_at,v_replayed
      FROM platform.iam_recovery_anchors AS anchor
     WHERE anchor.anchor_id=v_existing.anchor_id AND anchor.state='active'
       AND anchor.user_verification='required' AND NOT anchor.backup_eligible
       AND NOT anchor.backup_state;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='post-restore recovery anchor is unavailable';
    END IF;
END;
$_$;


ALTER FUNCTION platform.iam_post_restore_challenge_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_challenge text, p_context_sha256 bytea, p_rp_id text, p_origin text, p_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_observe_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_observe_v1(p_environment_id uuid, p_restore_operation_id uuid) RETURNS TABLE(state text, receipt_sha256 text, reactivated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_reconciliation platform.iam_post_restore_reconciliations%ROWTYPE;
    v_admission_environment_id uuid;
    v_admission_restore_operation_id uuid;
    v_admission_state text;
    v_receipt_sha256 bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_reactivation_observer'
       OR pg_catalog.current_setting('application_name') IS DISTINCT FROM
          'harpy-v2:core-operator-post-restore-reactivation-observer'
       OR p_environment_id IS NULL OR p_restore_operation_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='post-restore reactivation observation denied';
    END IF;
    SELECT * INTO v_reconciliation
    FROM platform.iam_post_restore_reconciliations
    WHERE environment_id=p_environment_id
      AND restore_operation_id=p_restore_operation_id;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1
        FROM platform.platformops_database_lineages AS lineage
        JOIN platform.platformops_database_lineage_events AS event
          ON event.environment_id=lineage.environment_id
         AND event.database_system_id=lineage.current_database_system_id
         AND event.event_kind='restored'
        WHERE lineage.environment_id=p_environment_id
          AND lineage.current_database_system_id=
              v_reconciliation.new_database_system_id
          AND event.operation_id=p_restore_operation_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='post-restore reactivation identity differs';
    END IF;
    SELECT admission.environment_id,admission.restore_operation_id,
           admission.state
    INTO v_admission_environment_id,v_admission_restore_operation_id,
         v_admission_state
    FROM platform.iam_post_restore_admission_v1(true) AS admission;
    IF NOT FOUND OR v_admission_environment_id<>p_environment_id
       OR v_admission_restore_operation_id<>p_restore_operation_id
       OR v_admission_state<>v_reconciliation.state
       OR v_reconciliation.state='fenced' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='post-restore reactivation admission differs';
    END IF;
    IF v_reconciliation.state='identity_reactivation_required' THEN
        RETURN QUERY SELECT 'pending'::text,NULL::text,NULL::timestamptz;
        RETURN;
    END IF;
    SELECT receipt.receipt_sha256 INTO v_receipt_sha256
    FROM platform.iam_post_restore_reactivation_receipts AS receipt
    WHERE receipt.restore_operation_id=p_restore_operation_id
      AND receipt.environment_id=p_environment_id;
    IF NOT FOUND OR v_reconciliation.state<>'reactivated'
       OR v_reconciliation.reactivated_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='post-restore reactivation receipt differs';
    END IF;
    RETURN QUERY SELECT 'reactivated'::text,
        pg_catalog.encode(v_receipt_sha256,'hex'),
        v_reconciliation.reactivated_at;
END;
$$;


ALTER FUNCTION platform.iam_post_restore_observe_v1(p_environment_id uuid, p_restore_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_reactivation_apply_v1(uuid, uuid, uuid, uuid, uuid, uuid, bytea, bytea, bytea, bigint, uuid, bigint, text, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_reactivation_apply_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_assertion_sha256 bytea, p_password_credential_sha256 bytea, p_receipt_sha256 bytea, p_sign_count bigint, p_identifier_id uuid, p_identifier_revision bigint, p_directory_key_id text, p_directory_hmac bytea, p_source_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_owner_user_id IS NULL OR
       p_identifier_id IS NULL OR p_identifier_revision<1 OR
       p_directory_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_directory_hmac)<>32 OR
       pg_catalog.octet_length(p_source_sha256)<>32 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='post-restore directory projection is denied';
    END IF;
    DELETE FROM platform.iam_login_directory
    WHERE tenant_id=p_tenant_id;
    INSERT INTO platform.iam_login_directory(
        tenant_id,identifier_kind,lookup_key_id,identifier_hmac,user_id,
        source_identifier_id,source_revision,state,source_sha256,projected_at
    ) VALUES (
        p_tenant_id,'email_v1',p_directory_key_id,p_directory_hmac,
        p_owner_user_id,p_identifier_id,p_identifier_revision,'active',
        p_source_sha256,p_occurred_at
    );
    RETURN platform.iam_post_restore_reactivation_complete_v1(
        p_operation_id,p_environment_id,p_restore_operation_id,p_tenant_id,
        p_owner_user_id,p_anchor_id,p_assertion_sha256,
        p_password_credential_sha256,p_receipt_sha256,p_sign_count,p_occurred_at
    );
END;
$_$;


ALTER FUNCTION platform.iam_post_restore_reactivation_apply_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_assertion_sha256 bytea, p_password_credential_sha256 bytea, p_receipt_sha256 bytea, p_sign_count bigint, p_identifier_id uuid, p_identifier_revision bigint, p_directory_key_id text, p_directory_hmac bytea, p_source_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_reactivation_complete_v1(uuid, uuid, uuid, uuid, uuid, uuid, bytea, bytea, bytea, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_reactivation_complete_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_assertion_sha256 bytea, p_password_credential_sha256 bytea, p_receipt_sha256 bytea, p_sign_count bigint, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_challenge platform.iam_post_restore_challenges%ROWTYPE;
v_existing platform.iam_post_restore_reactivation_receipts%ROWTYPE;
v_old_sign_count bigint;
BEGIN
    IF pg_catalog.octet_length(p_assertion_sha256)<>32 OR
       pg_catalog.octet_length(p_password_credential_sha256)<>32 OR
       pg_catalog.octet_length(p_receipt_sha256)<>32 OR p_sign_count<0 THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='post-restore reactivation result is invalid';
    END IF;
    SELECT * INTO v_existing FROM platform.iam_post_restore_reactivation_receipts
     WHERE restore_operation_id=p_restore_operation_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.operation_id<>p_operation_id OR v_existing.environment_id<>p_environment_id OR
           v_existing.tenant_id<>p_tenant_id OR v_existing.owner_user_id<>p_owner_user_id OR
           v_existing.anchor_id<>p_anchor_id OR v_existing.assertion_sha256<>p_assertion_sha256 OR
           v_existing.password_credential_sha256<>p_password_credential_sha256 OR
           v_existing.receipt_sha256<>p_receipt_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='post-restore reactivation replay conflicts';
        END IF;
        RETURN false;
    END IF;
    SELECT * INTO v_challenge FROM platform.iam_post_restore_challenges
     WHERE operation_id=p_operation_id AND environment_id=p_environment_id
       AND restore_operation_id=p_restore_operation_id FOR UPDATE;
    IF NOT FOUND OR v_challenge.state<>'pending' OR v_challenge.expires_at<=p_occurred_at OR
       v_challenge.tenant_id<>p_tenant_id OR v_challenge.owner_user_id<>p_owner_user_id OR
       v_challenge.anchor_id<>p_anchor_id THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='post-restore challenge is unavailable';
    END IF;
    SELECT sign_count INTO v_old_sign_count FROM platform.iam_recovery_anchors
     WHERE anchor_id=p_anchor_id AND state='active' FOR UPDATE;
    IF NOT FOUND OR (v_old_sign_count>0 AND p_sign_count<=v_old_sign_count) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='post-restore assertion counter is invalid';
    END IF;
    UPDATE platform.iam_recovery_anchors SET sign_count=p_sign_count,
        revision=revision+1,updated_at=p_occurred_at WHERE anchor_id=p_anchor_id;
    UPDATE platform.iam_post_restore_challenges SET state='consumed',terminal_at=p_occurred_at
     WHERE operation_id=p_operation_id;
    UPDATE platform.iam_post_restore_reconciliations
       SET state='reactivated',updated_at=p_occurred_at,reactivated_at=p_occurred_at
     WHERE restore_operation_id=p_restore_operation_id
       AND state='identity_reactivation_required';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='post-restore reconcile state is invalid';
    END IF;
    INSERT INTO platform.iam_post_restore_reactivation_receipts(
        restore_operation_id,operation_id,environment_id,tenant_id,owner_user_id,
        anchor_id,assertion_sha256,password_credential_sha256,receipt_sha256,created_at
    ) VALUES (p_restore_operation_id,p_operation_id,p_environment_id,p_tenant_id,
        p_owner_user_id,p_anchor_id,p_assertion_sha256,p_password_credential_sha256,
        p_receipt_sha256,p_occurred_at);
    RETURN true;
END;
$$;


ALTER FUNCTION platform.iam_post_restore_reactivation_complete_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_assertion_sha256 bytea, p_password_credential_sha256 bytea, p_receipt_sha256 bytea, p_sign_count bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_reactivation_fail_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_reactivation_fail_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_attempts smallint;
BEGIN
    UPDATE platform.iam_post_restore_challenges
       SET attempt_count=attempt_count+1,
           state=CASE WHEN attempt_count+1>=5 THEN 'failed' ELSE state END,
           terminal_at=CASE WHEN attempt_count+1>=5 THEN p_occurred_at ELSE terminal_at END
     WHERE operation_id=p_operation_id AND environment_id=p_environment_id
       AND restore_operation_id=p_restore_operation_id AND state='pending'
       AND expires_at>p_occurred_at
     RETURNING attempt_count INTO v_attempts;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.iam_post_restore_reactivation_fail_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_reconcile_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, bytea, bytea, bytea, bigint, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_post_restore_reconcile_v1(p_restore_operation_id uuid, p_environment_id uuid, p_recovery_set_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_new_database_system_id uuid, p_security_epoch bytea, p_restore_receipt_sha256 bytea, p_protected_head_sha256 bytea, p_custody_generation bigint, p_custody_result_sha256 bytea, p_receipt jsonb, p_occurred_at timestamp with time zone) RETURNS TABLE(state text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_existing platform.iam_post_restore_reconciliations%ROWTYPE;
v_epoch bytea;
BEGIN
    IF p_restore_operation_id IS NULL OR p_environment_id IS NULL OR
       p_recovery_set_id IS NULL OR p_tenant_id IS NULL OR p_owner_user_id IS NULL OR
       p_anchor_id IS NULL OR p_new_database_system_id IS NULL OR
       pg_catalog.octet_length(p_security_epoch)<>32 OR
       pg_catalog.octet_length(p_restore_receipt_sha256)<>32 OR
       pg_catalog.octet_length(p_protected_head_sha256)<>32 OR
       p_custody_generation<1 OR pg_catalog.octet_length(p_custody_result_sha256)<>32 OR
       pg_catalog.jsonb_typeof(p_receipt)<>'object' THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='post-restore reconcile input is invalid';
    END IF;
    SELECT * INTO v_existing FROM platform.iam_post_restore_reconciliations
     WHERE restore_operation_id=p_restore_operation_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.environment_id<>p_environment_id OR
           v_existing.recovery_set_id<>p_recovery_set_id OR
           v_existing.tenant_id<>p_tenant_id OR v_existing.owner_user_id<>p_owner_user_id OR
           v_existing.anchor_id<>p_anchor_id OR
           v_existing.new_database_system_id<>p_new_database_system_id OR
           v_existing.security_epoch<>p_security_epoch OR
           v_existing.restore_receipt_sha256<>p_restore_receipt_sha256 OR
           v_existing.protected_head_sha256<>p_protected_head_sha256 OR
           v_existing.custody_generation<>p_custody_generation OR
           v_existing.custody_result_sha256<>p_custody_result_sha256 OR
           v_existing.receipt<>p_receipt THEN
            UPDATE platform.iam_post_restore_reconciliations SET state='fenced',updated_at=p_occurred_at
             WHERE restore_operation_id=p_restore_operation_id;
		    RETURN QUERY SELECT 'fenced'::text,false;
		    RETURN;
        END IF;
        RETURN QUERY SELECT v_existing.state,true;
        RETURN;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.iam_recovery_anchors AS anchor
         WHERE anchor.anchor_id=p_anchor_id AND anchor.environment_id=p_environment_id
           AND anchor.tenant_id=p_tenant_id AND anchor.owner_user_id=p_owner_user_id
           AND anchor.state='active' AND anchor.user_verification='required'
           AND NOT anchor.backup_eligible AND NOT anchor.backup_state
           AND anchor.protected_state_sha256=p_protected_head_sha256
    ) OR NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_owner_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='post-restore protected owner binding is invalid';
    END IF;
    SELECT security_epoch INTO v_epoch FROM platform.iam_security_epochs
     WHERE environment_id=p_environment_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='IAM security epoch is missing';
    END IF;
    IF v_epoch<>p_security_epoch THEN
        UPDATE platform.iam_security_epochs SET security_epoch=p_security_epoch,
            generation=generation+1,rotated_at=p_occurred_at
         WHERE environment_id=p_environment_id;
    END IF;
    DELETE FROM platform.iam_refresh_locators WHERE tenant_id=p_tenant_id;
    INSERT INTO platform.iam_post_restore_reconciliations(
        restore_operation_id,environment_id,recovery_set_id,tenant_id,owner_user_id,anchor_id,
        new_database_system_id,security_epoch,restore_receipt_sha256,protected_head_sha256,
        custody_generation,custody_result_sha256,receipt,state,created_at,updated_at
    ) VALUES (p_restore_operation_id,p_environment_id,p_recovery_set_id,p_tenant_id,
        p_owner_user_id,p_anchor_id,p_new_database_system_id,p_security_epoch,
        p_restore_receipt_sha256,p_protected_head_sha256,p_custody_generation,
        p_custody_result_sha256,p_receipt,'identity_reactivation_required',p_occurred_at,p_occurred_at);
    RETURN QUERY SELECT 'identity_reactivation_required'::text,false;
END;
$$;


ALTER FUNCTION platform.iam_post_restore_reconcile_v1(p_restore_operation_id uuid, p_environment_id uuid, p_recovery_set_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_new_database_system_id uuid, p_security_epoch bytea, p_restore_receipt_sha256 bytea, p_protected_head_sha256 bytea, p_custody_generation bigint, p_custody_result_sha256 bytea, p_receipt jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_protected_authority_head_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_protected_authority_head_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Protected authority head deletion is forbidden';
    ELSIF TG_OP = 'INSERT' AND NEW.revision <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Protected authority head origin is invalid';
    ELSIF TG_OP = 'UPDATE' AND (
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.registry_binding_id IS DISTINCT FROM OLD.registry_binding_id OR
        NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR NEW.scope_id IS DISTINCT FROM OLD.scope_id OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.generation <= OLD.generation OR
        NEW.revision IS DISTINCT FROM OLD.revision + 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Protected authority head CAS is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_protected_authority_head_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_protected_authority_head_initialize_v1(uuid, uuid, bigint, bytea, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_protected_authority_head_initialize_v1(p_environment_id uuid, p_registry_binding_id uuid, p_generation bigint, p_state_sha256 bytea, p_ack_sha256 bytea) RETURNS TABLE(generation bigint, state_sha256 bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_environment_id IS NULL OR p_registry_binding_id IS NULL OR p_generation < 1 OR
       pg_catalog.octet_length(p_state_sha256) <> 32 OR
       pg_catalog.octet_length(p_ack_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Protected authority head is invalid';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.iam_protected_authority_heads AS head
               WHERE head.environment_id = p_environment_id) THEN
        IF NOT EXISTS (SELECT 1 FROM platform.iam_protected_authority_heads AS head
            WHERE head.environment_id = p_environment_id
              AND head.registry_binding_id = p_registry_binding_id
              AND head.scope_kind = 'environment' AND head.scope_id = p_environment_id
              AND head.generation = p_generation AND head.state_sha256 = p_state_sha256
              AND head.ack_sha256 = p_ack_sha256) THEN
            RAISE EXCEPTION USING ERRCODE = 'P1401', MESSAGE = 'Protected authority head conflicts';
        END IF;
        RETURN QUERY SELECT p_generation, p_state_sha256, true;
        RETURN;
    END IF;
    INSERT INTO platform.iam_protected_authority_heads (
        environment_id, registry_binding_id, scope_kind, scope_id, generation,
        state_sha256, ack_sha256, revision, created_at, updated_at
    ) VALUES (p_environment_id, p_registry_binding_id, 'environment', p_environment_id,
        p_generation, p_state_sha256, p_ack_sha256, 1, v_now, v_now);
    RETURN QUERY SELECT p_generation, p_state_sha256, false;
END;
$$;


ALTER FUNCTION platform.iam_protected_authority_head_initialize_v1(p_environment_id uuid, p_registry_binding_id uuid, p_generation bigint, p_state_sha256 bytea, p_ack_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_authority_context_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_authority_context_v1(p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid) RETURNS TABLE(environment_id uuid, deployment_mode text, owner_binding_id uuid, owner_binding_generation bigint, registry_binding_id uuid, head_generation bigint, head_state_sha256 bytea, head_ack_sha256 bytea, proposal_signer_generation bigint, proposal_signer_kid text, recovery_trust_bundle_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current owner is required';
    END IF;
    RETURN QUERY
    SELECT policy.environment_id,deployment.deployment_mode,policy.owner_binding_id,
        policy.revision,head.registry_binding_id,head.generation,head.state_sha256,
        head.ack_sha256,binding.signer_generation,binding.signer_kid,
        binding.recovery_trust_bundle_sha256
      FROM platform.tenancy_tenant_bindings AS tenant
      JOIN platform.tenancy_deployment_policy AS deployment
        ON deployment.environment_id=tenant.environment_id
      JOIN platform.iam_platform_owner_policies AS policy
        ON policy.environment_id=deployment.environment_id
      JOIN platform.iam_protected_authority_heads AS head
        ON head.environment_id=policy.environment_id
      JOIN platform.platformauthority_bindings AS binding
        ON binding.binding_id=head.registry_binding_id
       AND binding.environment_id=policy.environment_id
       AND binding.deployment_mode=deployment.deployment_mode
       AND binding.signer_status='active'
     WHERE tenant.tenant_id=p_tenant_id AND tenant.environment_id=p_environment_id
       AND tenant.purpose='onpremise_primary' AND deployment.deployment_mode='onpremise';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor authority is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_authority_context_v1(p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_commit_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_commit_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_occurred_at timestamp with time zone) RETURNS TABLE(operation_id uuid, anchor_id uuid, kind text, authority_generation bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_operation platform.iam_recovery_anchor_operations%ROWTYPE;
v_authority platform.platformauthority_operations%ROWTYPE;
v_head platform.iam_protected_authority_heads%ROWTYPE;
v_ack bytea;
v_clock bigint;
BEGIN
    IF p_operation_id IS NULL OR p_tenant_id IS NULL OR p_actor_user_id IS NULL OR
       p_occurred_at IS NULL OR
       NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='recovery anchor commit is invalid';
    END IF;
    SELECT * INTO v_operation FROM platform.iam_recovery_anchor_operations AS operation
     WHERE operation.operation_id=p_operation_id AND operation.tenant_id=p_tenant_id
       AND operation.actor_user_id=p_actor_user_id FOR UPDATE;
    IF v_operation.state='completed' THEN
        RETURN QUERY SELECT v_operation.operation_id,v_operation.anchor_id,v_operation.kind,
            v_operation.authority_generation,true;
        RETURN;
    END IF;
    SELECT * INTO v_authority FROM platform.platformauthority_operations AS authority
     WHERE authority.operation_id=p_operation_id FOR SHARE;
    SELECT * INTO v_head FROM platform.iam_protected_authority_heads AS head
     WHERE head.environment_id=v_operation.environment_id FOR UPDATE;
    IF v_operation.state<>'proposal_signed' OR v_authority.status<>'completed' OR
       v_authority.purpose<>'recovery_anchor_change' OR
       v_authority.binding_id<>v_operation.registry_binding_id OR
       v_authority.scope_kind<>'environment' OR
       v_authority.scope_id<>v_operation.environment_id OR
       v_authority.generation<>v_operation.authority_generation OR
       v_authority.state_sha256<>pg_catalog.encode(v_operation.protected_state_sha256,'hex') OR
       v_authority.proposal_sha256<>pg_catalog.encode(v_operation.proposal_sha256,'hex') OR
       v_authority.previous_head_sha256<>pg_catalog.encode(v_head.ack_sha256,'hex') OR
       v_head.registry_binding_id<>v_operation.registry_binding_id OR
       v_head.generation+1<>v_operation.authority_generation OR
       v_authority.ack_sha256 IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor authority is not complete';
    END IF;
    v_ack:=pg_catalog.decode(v_authority.ack_sha256,'hex');
    IF pg_catalog.octet_length(v_ack)<>32 THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor ack is invalid';
    END IF;
    IF v_operation.kind='anchor_register' THEN
        UPDATE platform.iam_recovery_anchors
           SET state='active',authority_generation=v_operation.authority_generation,
               protected_state_sha256=v_operation.protected_state_sha256,
               authority_ack_sha256=v_ack,revision=revision+1,updated_at=p_occurred_at
         WHERE anchor_id=v_operation.anchor_id AND environment_id=v_operation.environment_id
           AND state='pending';
    ELSE
        IF (SELECT COUNT(*) FROM platform.iam_recovery_anchors AS anchor
             WHERE anchor.environment_id=v_operation.environment_id AND anchor.state='active')<=1 THEN
            RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='last recovery anchor cannot be deleted';
        END IF;
        UPDATE platform.iam_recovery_anchors
           SET state='deleted',authority_generation=v_operation.authority_generation,
               protected_state_sha256=v_operation.protected_state_sha256,
               authority_ack_sha256=v_ack,revision=revision+1,updated_at=p_occurred_at,
               deleted_at=p_occurred_at
         WHERE anchor_id=v_operation.anchor_id AND environment_id=v_operation.environment_id
           AND state='active';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor state changed';
    END IF;
    UPDATE platform.iam_protected_authority_heads
       SET generation=v_operation.authority_generation,
           state_sha256=v_operation.protected_state_sha256,ack_sha256=v_ack,
           revision=revision+1,updated_at=p_occurred_at
     WHERE environment_id=v_operation.environment_id
       AND generation=v_operation.authority_generation-1
       AND ack_sha256=pg_catalog.decode(v_authority.previous_head_sha256,'hex');
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor head changed'; END IF;
    UPDATE platform.iam_platform_authorization_clocks
       SET authorization_clock=authorization_clock+1,revision=revision+1,updated_at=p_occurred_at
     WHERE environment_id=v_operation.environment_id
     RETURNING authorization_clock INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor clock changed';
    END IF;
    PERFORM platform.platformops_stale_recovery_sets_for_authority_v1(
        v_operation.environment_id,v_operation.authority_generation,
        v_operation.protected_state_sha256,p_occurred_at);
    IF NOT platform.platformops_complete_anchor_operation_v1(
        p_operation_id,v_ack,p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery operation completion conflicts';
    END IF;
    UPDATE platform.iam_recovery_anchor_operations
       SET state='completed',completed_at=p_occurred_at,updated_at=p_occurred_at
     WHERE operation_id=p_operation_id AND state='proposal_signed';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor operation changed'; END IF;
    RETURN QUERY SELECT v_operation.operation_id,v_operation.anchor_id,v_operation.kind,
        v_operation.authority_generation,false;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_commit_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_finalize_authority_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_finalize_authority_v1(p_operation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_operation platform.iam_recovery_anchor_operations%ROWTYPE;
BEGIN
    IF p_operation_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='recovery anchor authority finalization is invalid';
    END IF;
    SELECT * INTO v_operation
      FROM platform.iam_recovery_anchor_operations AS operation
     WHERE operation.operation_id=p_operation_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='recovery anchor operation is missing';
    END IF;
    IF v_operation.state='completed' THEN
        RETURN true;
    END IF;
    PERFORM result.operation_id
      FROM platform.iam_recovery_anchor_commit_v1(
        v_operation.operation_id,v_operation.tenant_id,
        v_operation.actor_user_id,pg_catalog.clock_timestamp()
      ) AS result;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_finalize_authority_v1(p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='recovery anchor deletion is forbidden';
    ELSIF TG_OP='INSERT' AND (NEW.state<>'pending' OR NEW.revision<>1) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='recovery anchor origin is invalid';
    ELSIF TG_OP='UPDATE' AND (
        NEW.anchor_id IS DISTINCT FROM OLD.anchor_id OR
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR
        NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id OR
        NEW.generation IS DISTINCT FROM OLD.generation OR
        NEW.credential_id IS DISTINCT FROM OLD.credential_id OR
        NEW.public_key_cose IS DISTINCT FROM OLD.public_key_cose OR
        NEW.aaguid IS DISTINCT FROM OLD.aaguid OR
        NEW.attestation_format IS DISTINCT FROM OLD.attestation_format OR
        NEW.attestation_type IS DISTINCT FROM OLD.attestation_type OR
        NEW.rp_id IS DISTINCT FROM OLD.rp_id OR
        NEW.allowed_origins IS DISTINCT FROM OLD.allowed_origins OR
        NEW.allowed_origins_sha256 IS DISTINCT FROM OLD.allowed_origins_sha256 OR
        NEW.user_verification IS DISTINCT FROM OLD.user_verification OR
        NEW.backup_eligible IS DISTINCT FROM OLD.backup_eligible OR
        NEW.backup_state IS DISTINCT FROM OLD.backup_state OR
        NEW.sign_count IS DISTINCT FROM OLD.sign_count OR
        NEW.counter_policy IS DISTINCT FROM OLD.counter_policy OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.revision<>OLD.revision+1 OR
        NOT ((OLD.state='pending' AND NEW.state='active') OR
             (OLD.state='active' AND NEW.state IN ('stale','deleted')))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_list_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_list_v1(p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid) RETURNS TABLE(anchor_id uuid, generation bigint, credential_id bytea, rp_id text, user_verification text, backup_eligible boolean, backup_state boolean, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current owner is required';
    END IF;
    RETURN QUERY SELECT anchor.anchor_id,anchor.generation,anchor.credential_id,
        anchor.rp_id,anchor.user_verification,anchor.backup_eligible,
        anchor.backup_state,anchor.state
      FROM platform.iam_recovery_anchors AS anchor
     WHERE anchor.environment_id=p_environment_id AND anchor.tenant_id=p_tenant_id
     ORDER BY anchor.generation,anchor.anchor_id;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_list_v1(p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_operation_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_operation_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='recovery anchor operation deletion is forbidden';
    ELSIF TG_OP='INSERT' AND NOT (
        (NEW.kind='anchor_register' AND NEW.state='options_issued') OR
        (NEW.kind='anchor_delete' AND NEW.state='authority_pending')) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='recovery anchor operation origin is invalid';
    ELSIF TG_OP='UPDATE' AND (
        NEW.operation_id IS DISTINCT FROM OLD.operation_id OR
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR
        NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id OR
        NEW.kind IS DISTINCT FROM OLD.kind OR NEW.anchor_id IS DISTINCT FROM OLD.anchor_id OR
        NEW.options_idempotency_key IS DISTINCT FROM OLD.options_idempotency_key OR
        NEW.options_request_sha256 IS DISTINCT FROM OLD.options_request_sha256 OR
        NEW.challenge IS DISTINCT FROM OLD.challenge OR
        NEW.challenge_expires_at IS DISTINCT FROM OLD.challenge_expires_at OR
        NEW.rp_id IS DISTINCT FROM OLD.rp_id OR NEW.allowed_origins IS DISTINCT FROM OLD.allowed_origins OR
        NEW.allowed_origins_sha256 IS DISTINCT FROM OLD.allowed_origins_sha256 OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR NOT (
            (OLD.state='options_issued' AND NEW.state='authority_pending') OR
            (OLD.state='authority_pending' AND NEW.state='proposal_signed') OR
            (OLD.state='proposal_signed' AND NEW.state='completed'))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor operation transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_operation_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_options_v1(uuid, uuid, uuid, uuid, uuid, text, bytea, text, text, jsonb, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_options_v1(p_operation_id uuid, p_anchor_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_challenge text, p_rp_id text, p_allowed_origins jsonb, p_allowed_origins_sha256 bytea, p_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS TABLE(operation_id uuid, anchor_id uuid, challenge text, rp_id text, allowed_origins jsonb, expires_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_existing platform.iam_recovery_anchor_operations%ROWTYPE;
BEGIN
    IF p_operation_id IS NULL OR p_anchor_id IS NULL OR p_environment_id IS NULL OR
       p_tenant_id IS NULL OR p_actor_user_id IS NULL OR
       p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       pg_catalog.octet_length(p_request_sha256)<>32 OR
       p_challenge !~ '^[A-Za-z0-9_-]{43}$' OR
       pg_catalog.octet_length(p_rp_id) NOT BETWEEN 1 AND 253 OR
       pg_catalog.jsonb_typeof(p_allowed_origins)<>'array' OR
       pg_catalog.jsonb_array_length(p_allowed_origins)<1 OR
       pg_catalog.octet_length(p_allowed_origins_sha256)<>32 OR
       p_expires_at<=p_occurred_at OR
       NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='recovery anchor options are invalid';
    END IF;
    SELECT * INTO v_existing FROM platform.iam_recovery_anchor_operations
     WHERE operation_id=p_operation_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.environment_id<>p_environment_id OR v_existing.tenant_id<>p_tenant_id OR
           v_existing.actor_user_id<>p_actor_user_id OR v_existing.kind<>'anchor_register' OR
           v_existing.anchor_id<>p_anchor_id OR
           v_existing.options_idempotency_key<>p_idempotency_key OR
           v_existing.options_request_sha256<>p_request_sha256 OR
           v_existing.rp_id<>p_rp_id OR
           v_existing.allowed_origins_sha256<>p_allowed_origins_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='recovery anchor options conflict';
        END IF;
        RETURN QUERY SELECT v_existing.operation_id,v_existing.anchor_id,
            v_existing.challenge,v_existing.rp_id,v_existing.allowed_origins,
            v_existing.challenge_expires_at,true;
        RETURN;
    END IF;
    INSERT INTO platform.iam_recovery_anchor_operations(
        operation_id,environment_id,tenant_id,actor_user_id,kind,anchor_id,
        options_idempotency_key,options_request_sha256,challenge,challenge_expires_at,
        rp_id,allowed_origins,allowed_origins_sha256,state,created_at,updated_at
    ) VALUES (p_operation_id,p_environment_id,p_tenant_id,p_actor_user_id,
        'anchor_register',p_anchor_id,p_idempotency_key,p_request_sha256,p_challenge,
        p_expires_at,p_rp_id,p_allowed_origins,p_allowed_origins_sha256,
        'options_issued',p_occurred_at,p_occurred_at);
    IF NOT platform.platformops_record_anchor_operation_v1(
        p_operation_id,p_environment_id,p_actor_user_id,p_idempotency_key,
        p_request_sha256,'anchor_register',p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery operation projection conflicts';
    END IF;
    RETURN QUERY SELECT p_operation_id,p_anchor_id,p_challenge,p_rp_id,
        p_allowed_origins,p_expires_at,false;
END;
$_$;


ALTER FUNCTION platform.iam_recovery_anchor_options_v1(p_operation_id uuid, p_anchor_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_challenge text, p_rp_id text, p_allowed_origins jsonb, p_allowed_origins_sha256 bytea, p_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_record_proposal_v1(uuid, uuid, uuid, uuid, bigint, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_record_proposal_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_registry_binding_id uuid, p_authority_generation bigint, p_protected_state_sha256 bytea, p_proposal_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_operation platform.iam_recovery_anchor_operations%ROWTYPE;
v_head platform.iam_protected_authority_heads%ROWTYPE;
BEGIN
    IF p_operation_id IS NULL OR p_tenant_id IS NULL OR p_actor_user_id IS NULL OR
       p_registry_binding_id IS NULL OR p_authority_generation<2 OR
       pg_catalog.octet_length(p_protected_state_sha256)<>32 OR
       pg_catalog.octet_length(p_proposal_sha256)<>32 OR p_occurred_at IS NULL OR
       NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='recovery anchor proposal is invalid';
    END IF;
    SELECT * INTO v_operation FROM platform.iam_recovery_anchor_operations AS operation
     WHERE operation.operation_id=p_operation_id AND operation.tenant_id=p_tenant_id
       AND operation.actor_user_id=p_actor_user_id FOR UPDATE;
    IF v_operation.state='proposal_signed' THEN
        RETURN v_operation.registry_binding_id=p_registry_binding_id AND
            v_operation.authority_generation=p_authority_generation AND
            v_operation.protected_state_sha256=p_protected_state_sha256 AND
            v_operation.proposal_sha256=p_proposal_sha256;
    END IF;
    SELECT * INTO v_head FROM platform.iam_protected_authority_heads AS head
     WHERE head.environment_id=v_operation.environment_id FOR SHARE;
    IF v_operation.state<>'authority_pending' OR v_head.registry_binding_id<>p_registry_binding_id OR
       p_authority_generation<>v_head.generation+1 OR NOT EXISTS(
        SELECT 1 FROM platform.platformauthority_operations AS authority
         WHERE authority.operation_id=p_operation_id AND authority.purpose='recovery_anchor_change'
           AND authority.binding_id=p_registry_binding_id AND authority.scope_kind='environment'
           AND authority.scope_id=v_operation.environment_id
           AND authority.generation=p_authority_generation
           AND authority.previous_head_sha256=pg_catalog.encode(v_head.ack_sha256,'hex')
           AND authority.state_sha256=pg_catalog.encode(p_protected_state_sha256,'hex')
           AND authority.proposal_sha256=pg_catalog.encode(p_proposal_sha256,'hex')
           AND authority.status='proposal_signed') THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor proposal conflicts';
    END IF;
    UPDATE platform.iam_recovery_anchor_operations
       SET registry_binding_id=p_registry_binding_id,authority_generation=p_authority_generation,
           protected_state_sha256=p_protected_state_sha256,proposal_sha256=p_proposal_sha256,
           state='proposal_signed',updated_at=p_occurred_at
     WHERE operation_id=p_operation_id AND state='authority_pending';
    IF NOT FOUND OR NOT platform.platformops_mark_anchor_handoff_v1(p_operation_id,p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor handoff conflicts';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_record_proposal_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_registry_binding_id uuid, p_authority_generation bigint, p_protected_state_sha256 bytea, p_proposal_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_registration_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_registration_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid) RETURNS TABLE(operation_id uuid, anchor_id uuid, challenge text, rp_id text, allowed_origins jsonb, allowed_origins_sha256 bytea, expires_at timestamp with time zone, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current owner is required';
    END IF;
    RETURN QUERY SELECT operation.operation_id,operation.anchor_id,operation.challenge,
        operation.rp_id,operation.allowed_origins,operation.allowed_origins_sha256,
        operation.challenge_expires_at,operation.state
      FROM platform.iam_recovery_anchor_operations AS operation
     WHERE operation.operation_id=p_operation_id AND operation.tenant_id=p_tenant_id
       AND operation.actor_user_id=p_actor_user_id AND operation.kind='anchor_register';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='recovery anchor operation is missing';
    END IF;
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_registration_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_set_sha256_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_set_sha256_v1(p_environment_id uuid, p_excluded_anchor_id uuid DEFAULT NULL::uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN (
SELECT pg_catalog.sha256(pg_catalog.convert_to(
    'harpy/recovery-anchor-set/v1' || COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'anchor_id',anchor.anchor_id,'generation',anchor.generation,
            'owner_user_id',anchor.owner_user_id,
            'credential_id',pg_catalog.encode(anchor.credential_id,'base64'),
            'public_key_cose',pg_catalog.encode(anchor.public_key_cose,'base64'),
            'aaguid',anchor.aaguid,'rp_id',anchor.rp_id,
            'allowed_origins_sha256',pg_catalog.encode(anchor.allowed_origins_sha256,'hex'),
            'user_verification',anchor.user_verification,
            'backup_eligible',anchor.backup_eligible,'backup_state',anchor.backup_state,
            'sign_count',anchor.sign_count,'counter_policy',anchor.counter_policy
        ) ORDER BY anchor.generation
    ),'[]'::jsonb)::text,'UTF8'))
FROM platform.iam_recovery_anchors AS anchor
WHERE anchor.environment_id=p_environment_id
  AND anchor.state IN ('pending','active')
  AND anchor.anchor_id IS DISTINCT FROM p_excluded_anchor_id
);
END;
$$;


ALTER FUNCTION platform.iam_recovery_anchor_set_sha256_v1(p_environment_id uuid, p_excluded_anchor_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_stage_delete_v1(uuid, uuid, uuid, uuid, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_stage_delete_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_anchor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(anchor_id uuid, anchor_set_sha256 bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_existing platform.iam_recovery_anchor_operations%ROWTYPE; v_set bytea;
BEGIN
    IF p_operation_id IS NULL OR p_environment_id IS NULL OR p_tenant_id IS NULL OR
       p_actor_user_id IS NULL OR p_anchor_id IS NULL OR
       p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       pg_catalog.octet_length(p_request_sha256)<>32 OR p_occurred_at IS NULL OR
       NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='recovery anchor deletion is invalid';
    END IF;
    SELECT * INTO v_existing FROM platform.iam_recovery_anchor_operations AS operation
     WHERE operation.operation_id=p_operation_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.environment_id<>p_environment_id OR v_existing.tenant_id<>p_tenant_id OR
           v_existing.actor_user_id<>p_actor_user_id OR v_existing.kind<>'anchor_delete' OR
           v_existing.anchor_id<>p_anchor_id OR
           v_existing.options_idempotency_key<>p_idempotency_key OR
           v_existing.options_request_sha256<>p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='recovery anchor deletion conflicts';
        END IF;
        RETURN QUERY SELECT p_anchor_id,v_existing.anchor_set_sha256,true;
        RETURN;
    END IF;
    IF NOT EXISTS(SELECT 1 FROM platform.iam_recovery_anchors AS anchor
        WHERE anchor.anchor_id=p_anchor_id AND anchor.environment_id=p_environment_id
          AND anchor.tenant_id=p_tenant_id AND anchor.state='active' FOR UPDATE) OR
       (SELECT COUNT(*) FROM platform.iam_recovery_anchors AS anchor
         WHERE anchor.environment_id=p_environment_id AND anchor.state='active')<=1 THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='last recovery anchor cannot be deleted';
    END IF;
    v_set:=platform.iam_recovery_anchor_set_sha256_v1(p_environment_id,p_anchor_id);
    INSERT INTO platform.iam_recovery_anchor_operations(
        operation_id,environment_id,tenant_id,actor_user_id,kind,anchor_id,
        options_idempotency_key,options_request_sha256,anchor_set_sha256,state,created_at,updated_at
    ) VALUES(p_operation_id,p_environment_id,p_tenant_id,p_actor_user_id,'anchor_delete',p_anchor_id,
        p_idempotency_key,p_request_sha256,v_set,'authority_pending',p_occurred_at,p_occurred_at);
    IF NOT platform.platformops_record_anchor_operation_v1(
        p_operation_id,p_environment_id,p_actor_user_id,p_idempotency_key,
        p_request_sha256,'anchor_delete',p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery operation projection conflicts';
    END IF;
    RETURN QUERY SELECT p_anchor_id,v_set,false;
END;
$_$;


ALTER FUNCTION platform.iam_recovery_anchor_stage_delete_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_anchor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_recovery_anchor_stage_registration_v1(uuid, uuid, uuid, uuid, text, bytea, bytea, bytea, uuid, text, text, text, jsonb, bytea, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_anchor_stage_registration_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_credential_id bytea, p_public_key_cose bytea, p_aaguid uuid, p_attestation_format text, p_attestation_type text, p_rp_id text, p_allowed_origins jsonb, p_allowed_origins_sha256 bytea, p_sign_count bigint, p_occurred_at timestamp with time zone) RETURNS TABLE(anchor_id uuid, anchor_set_sha256 bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_operation platform.iam_recovery_anchor_operations%ROWTYPE;
v_anchor platform.iam_recovery_anchors%ROWTYPE;
v_generation bigint;
v_set bytea;
BEGIN
    IF p_operation_id IS NULL OR p_environment_id IS NULL OR p_tenant_id IS NULL OR
       p_actor_user_id IS NULL OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       pg_catalog.octet_length(p_request_sha256)<>32 OR
       pg_catalog.octet_length(p_credential_id) NOT BETWEEN 1 AND 1024 OR
       pg_catalog.octet_length(p_public_key_cose) NOT BETWEEN 1 AND 4096 OR
       p_aaguid IS NULL OR p_aaguid='00000000-0000-0000-0000-000000000000'::uuid OR
       p_attestation_format IN ('','none') OR p_attestation_type IN ('','none') OR
       pg_catalog.octet_length(p_rp_id) NOT BETWEEN 1 AND 253 OR
       pg_catalog.jsonb_typeof(p_allowed_origins)<>'array' OR
       pg_catalog.jsonb_array_length(p_allowed_origins)<1 OR
       pg_catalog.octet_length(p_allowed_origins_sha256)<>32 OR p_sign_count<0 OR
       p_occurred_at IS NULL OR
       NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='recovery anchor registration is invalid';
    END IF;
    SELECT * INTO v_operation FROM platform.iam_recovery_anchor_operations AS operation
     WHERE operation.operation_id=p_operation_id FOR UPDATE;
    IF NOT FOUND OR v_operation.environment_id<>p_environment_id OR
       v_operation.tenant_id<>p_tenant_id OR v_operation.actor_user_id<>p_actor_user_id OR
       v_operation.kind<>'anchor_register' THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor challenge is unavailable';
    END IF;
    IF v_operation.state<>'options_issued' THEN
        SELECT * INTO v_anchor FROM platform.iam_recovery_anchors AS anchor
         WHERE anchor.anchor_id=v_operation.anchor_id;
        IF v_operation.register_idempotency_key<>p_idempotency_key OR
           v_operation.register_request_sha256<>p_request_sha256 OR
           v_anchor.credential_id<>p_credential_id OR v_anchor.public_key_cose<>p_public_key_cose OR
           v_anchor.aaguid<>p_aaguid OR v_anchor.attestation_format<>p_attestation_format OR
           v_anchor.attestation_type<>p_attestation_type OR v_anchor.rp_id<>p_rp_id OR
           v_anchor.allowed_origins_sha256<>p_allowed_origins_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='recovery anchor replay conflicts';
        END IF;
        RETURN QUERY SELECT v_anchor.anchor_id,v_operation.anchor_set_sha256,true;
        RETURN;
    END IF;
    IF v_operation.challenge_expires_at<=p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor challenge expired';
    END IF;
    SELECT COALESCE(MAX(anchor.generation),0)+1 INTO v_generation
      FROM platform.iam_recovery_anchors AS anchor
     WHERE anchor.environment_id=p_environment_id;
    INSERT INTO platform.iam_recovery_anchors(
        anchor_id,environment_id,tenant_id,owner_user_id,generation,credential_id,
        public_key_cose,aaguid,attestation_format,attestation_type,rp_id,allowed_origins,
        allowed_origins_sha256,user_verification,backup_eligible,backup_state,sign_count,
        counter_policy,state,revision,created_at,updated_at
    ) VALUES(v_operation.anchor_id,p_environment_id,p_tenant_id,p_actor_user_id,v_generation,
        p_credential_id,p_public_key_cose,p_aaguid,p_attestation_format,p_attestation_type,
        p_rp_id,p_allowed_origins,p_allowed_origins_sha256,'required',false,false,p_sign_count,
        'adr0062','pending',1,p_occurred_at,p_occurred_at);
    v_set:=platform.iam_recovery_anchor_set_sha256_v1(p_environment_id,NULL);
    UPDATE platform.iam_recovery_anchor_operations
       SET register_idempotency_key=p_idempotency_key,register_request_sha256=p_request_sha256,
           anchor_set_sha256=v_set,state='authority_pending',updated_at=p_occurred_at
     WHERE operation_id=p_operation_id AND state='options_issued';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery anchor changed'; END IF;
    RETURN QUERY SELECT v_operation.anchor_id,v_set,false;
END;
$_$;


ALTER FUNCTION platform.iam_recovery_anchor_stage_registration_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_credential_id bytea, p_public_key_cose bytea, p_aaguid uuid, p_attestation_format text, p_attestation_type text, p_rp_id text, p_allowed_origins jsonb, p_allowed_origins_sha256 bytea, p_sign_count bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_recovery_owner_anchor_evidence_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_recovery_owner_anchor_evidence_v1(p_environment_id uuid) RETURNS TABLE(environment_id uuid, tenant_id uuid, owner_user_id uuid, owner_binding_id uuid, owner_binding_generation bigint, anchor_id uuid, anchor_generation bigint, credential_id bytea, public_key_cose bytea, aaguid uuid, attestation_format text, attestation_type text, rp_id text, allowed_origins jsonb, allowed_origins_sha256 bytea, user_verification text, backup_eligible boolean, backup_state boolean, sign_count bigint, counter_policy text, protected_head_generation bigint, protected_state_sha256 bytea, protected_ack_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery owner evidence denied';
    END IF;
    RETURN QUERY
    SELECT anchor.environment_id,anchor.tenant_id,anchor.owner_user_id,
           policy.owner_binding_id,policy.revision,anchor.anchor_id,
           anchor.generation,anchor.credential_id,anchor.public_key_cose,
           anchor.aaguid,anchor.attestation_format,anchor.attestation_type,
           anchor.rp_id,anchor.allowed_origins,anchor.allowed_origins_sha256,
           anchor.user_verification,anchor.backup_eligible,
           anchor.backup_state,anchor.sign_count,anchor.counter_policy,
           head.generation,head.state_sha256,head.ack_sha256
    FROM platform.iam_recovery_anchors AS anchor
    JOIN platform.iam_platform_owner_policies AS policy
      ON policy.environment_id=anchor.environment_id
     AND policy.revision>0
    JOIN platform.iam_protected_authority_heads AS head
      ON head.environment_id=anchor.environment_id
     AND head.generation=anchor.authority_generation
     AND head.state_sha256=anchor.protected_state_sha256
     AND head.ack_sha256=anchor.authority_ack_sha256
    WHERE anchor.environment_id=p_environment_id
      AND anchor.state='active' AND anchor.user_verification='required'
      AND NOT anchor.backup_eligible AND NOT anchor.backup_state
    ORDER BY anchor.generation,anchor.anchor_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='current recovery owner evidence is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.iam_recovery_owner_anchor_evidence_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_refresh_locator_advance_v1(bytea, uuid, bigint, bigint, bigint, bigint, bytea, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_refresh_locator_advance_v1(p_selector bytea, p_tenant_id uuid, p_group_generation bigint, p_cutover_generation bigint, p_expected_source_revision bigint, p_source_revision bigint, p_source_sha256 bytea, p_source_token_state text, p_projected_at timestamp with time zone, p_retain_until timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_count bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_expected_source_revision IS NULL OR p_source_revision IS NULL OR
       p_source_revision OPERATOR(pg_catalog.<=) p_expected_source_revision THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh locator advance input is invalid';
    END IF;
    PERFORM platform.iam_assert_current_tenant_authority_v1(
        p_tenant_id, p_group_generation, p_cutover_generation
    );

    UPDATE platform.iam_refresh_locators AS locator
    SET source_revision = p_source_revision,
        source_sha256 = p_source_sha256,
        source_token_state = p_source_token_state,
        projected_at = p_projected_at,
        retain_until = p_retain_until
    WHERE locator.selector OPERATOR(pg_catalog.=) p_selector
      AND locator.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
      AND locator.authority_group_generation
          OPERATOR(pg_catalog.=) p_group_generation
      AND locator.cutover_generation
          OPERATOR(pg_catalog.=) p_cutover_generation
      AND locator.source_revision
          OPERATOR(pg_catalog.=) p_expected_source_revision;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE = 'P5711',
            MESSAGE = 'IAM refresh locator revision is stale or missing';
    END IF;
    RETURN p_source_revision;
END;
$$;


ALTER FUNCTION platform.iam_refresh_locator_advance_v1(p_selector bytea, p_tenant_id uuid, p_group_generation bigint, p_cutover_generation bigint, p_expected_source_revision bigint, p_source_revision bigint, p_source_sha256 bytea, p_source_token_state text, p_projected_at timestamp with time zone, p_retain_until timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_refresh_locator_create_v1(bytea, uuid, uuid, uuid, bigint, bigint, bigint, bytea, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_refresh_locator_create_v1(p_selector bytea, p_tenant_id uuid, p_token_id uuid, p_family_id uuid, p_group_generation bigint, p_cutover_generation bigint, p_source_revision bigint, p_source_sha256 bytea, p_source_token_state text, p_issued_at timestamp with time zone, p_projected_at timestamp with time zone, p_family_absolute_expires_at timestamp with time zone, p_retain_until timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh locator create session is invalid';
    END IF;
    PERFORM platform.iam_assert_current_tenant_authority_v1(
        p_tenant_id, p_group_generation, p_cutover_generation
    );

    INSERT INTO platform.iam_refresh_locators (
        selector, tenant_id, token_id, family_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation, authority_domain,
        cutover_generation, source_revision, source_sha256,
        source_token_state, issued_at, projected_at,
        family_absolute_expires_at, retain_until
    ) VALUES (
        p_selector, p_tenant_id, p_token_id, p_family_id, 'tenant', p_tenant_id,
        'iam_system_resources', p_group_generation, 'iam',
        p_cutover_generation, p_source_revision, p_source_sha256,
        p_source_token_state, p_issued_at, p_projected_at,
        p_family_absolute_expires_at, p_retain_until
    );
END;
$$;


ALTER FUNCTION platform.iam_refresh_locator_create_v1(p_selector bytea, p_tenant_id uuid, p_token_id uuid, p_family_id uuid, p_group_generation bigint, p_cutover_generation bigint, p_source_revision bigint, p_source_sha256 bytea, p_source_token_state text, p_issued_at timestamp with time zone, p_projected_at timestamp with time zone, p_family_absolute_expires_at timestamp with time zone, p_retain_until timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_refresh_locator_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_refresh_locator_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'iam_refresh_locators' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh locator session authority is invalid';
    END IF;
    IF TG_OP OPERATOR(pg_catalog.=) 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM refresh locator deletion is forbidden';
    END IF;

    PERFORM platform.iam_assert_current_tenant_authority_v1(
        NEW.tenant_id,
        NEW.authority_group_generation,
        NEW.cutover_generation
    );
    IF TG_OP OPERATOR(pg_catalog.=) 'INSERT' THEN
        RETURN NEW;
    END IF;

    IF NEW.selector IS DISTINCT FROM OLD.selector OR
       NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR
       NEW.token_id IS DISTINCT FROM OLD.token_id OR
       NEW.family_id IS DISTINCT FROM OLD.family_id OR
       NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR
       NEW.scope_id IS DISTINCT FROM OLD.scope_id OR
       NEW.authority_group_id IS DISTINCT FROM OLD.authority_group_id OR
       NEW.authority_group_generation IS DISTINCT FROM
           OLD.authority_group_generation OR
       NEW.authority_domain IS DISTINCT FROM OLD.authority_domain OR
       NEW.cutover_generation IS DISTINCT FROM OLD.cutover_generation OR
       NEW.issued_at IS DISTINCT FROM OLD.issued_at OR
       NEW.family_absolute_expires_at IS DISTINCT FROM
           OLD.family_absolute_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM refresh locator identity is immutable';
    END IF;

    IF NEW.source_revision OPERATOR(pg_catalog.<=) OLD.source_revision OR
       NEW.source_sha256 IS NOT DISTINCT FROM OLD.source_sha256 OR
       NEW.projected_at OPERATOR(pg_catalog.<) OLD.projected_at OR
       NEW.retain_until OPERATOR(pg_catalog.<) OLD.retain_until OR
       (
           OLD.source_token_state IS DISTINCT FROM 'active' AND
           NEW.source_token_state IS DISTINCT FROM OLD.source_token_state
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM refresh locator projection must advance monotonically';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_refresh_locator_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_resolve_login_target_v1(uuid, text, text, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_resolve_login_target_v1(p_tenant_id uuid, p_identifier_kind text, p_key_id text, p_identifier_hmac bytea) RETURNS TABLE(tenant_id uuid, source_revision bigint, source_sha256 bytea, group_generation bigint, iam_generation bigint, layout_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_identifier_kind IS NULL OR NOT (
           p_identifier_kind OPERATOR(pg_catalog.=) ANY (
               ARRAY['email_v1','portal_v1']::text[]
           )
       ) OR NOT platform.iam_hmac_key_id_valid_v1(p_key_id) OR
       p_identifier_hmac IS NULL OR
       pg_catalog.octet_length(p_identifier_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM login target input is invalid';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:iam-login-target:' || p_tenant_id::text || ':' ||
        p_identifier_kind || ':' || p_key_id || ':' ||
        pg_catalog.encode(p_identifier_hmac, 'hex'), 0
    ));
    SELECT target.group_generation, target.iam_generation,
           target.layout_generation
    INTO group_generation, iam_generation, layout_generation
    FROM platform.iam_resolve_tenant_target_v1(p_tenant_id) AS target;

    BEGIN
        SELECT directory.tenant_id, directory.source_revision,
               directory.source_sha256
        INTO STRICT tenant_id, source_revision, source_sha256
        FROM platform.iam_login_directory AS directory
        WHERE directory.tenant_id OPERATOR(pg_catalog.=) p_tenant_id
          AND directory.identifier_kind OPERATOR(pg_catalog.=) p_identifier_kind
          AND directory.lookup_key_id OPERATOR(pg_catalog.=) p_key_id
          AND directory.identifier_hmac OPERATOR(pg_catalog.=) p_identifier_hmac
          AND directory.state OPERATOR(pg_catalog.=) 'active'
          AND directory.tombstoned_at IS NULL
        FOR SHARE;
    EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING ERRCODE = 'P5731',
            MESSAGE = 'IAM login target is not exact and active';
    END;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.iam_resolve_login_target_v1(p_tenant_id uuid, p_identifier_kind text, p_key_id text, p_identifier_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_resolve_login_target_v2(uuid, text, text, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_resolve_login_target_v2(p_tenant_id uuid, p_identifier_kind text, p_key_id text, p_identifier_hmac bytea) RETURNS TABLE(tenant_id uuid, source_user_id uuid, source_identifier_id uuid, source_identifier_kind text, source_revision bigint, source_sha256 bytea, group_generation bigint, iam_generation bigint, layout_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_source_revision bigint;
    v_source_sha256 bytea;
BEGIN
    SELECT target.tenant_id, target.source_revision, target.source_sha256,
           target.group_generation, target.iam_generation,
           target.layout_generation
    INTO STRICT v_tenant_id, v_source_revision, v_source_sha256,
        group_generation, iam_generation, layout_generation
    FROM platform.iam_resolve_login_target_v1(
        p_tenant_id, p_identifier_kind, p_key_id, p_identifier_hmac
    ) AS target;

    SELECT directory.tenant_id, directory.user_id,
           directory.source_identifier_id, directory.identifier_kind,
           directory.source_revision, directory.source_sha256
    INTO STRICT tenant_id, source_user_id, source_identifier_id,
        source_identifier_kind, source_revision, source_sha256
    FROM platform.iam_login_directory AS directory
    WHERE directory.tenant_id OPERATOR(pg_catalog.=) v_tenant_id
      AND directory.identifier_kind OPERATOR(pg_catalog.=) p_identifier_kind
      AND directory.lookup_key_id OPERATOR(pg_catalog.=) p_key_id
      AND directory.identifier_hmac OPERATOR(pg_catalog.=) p_identifier_hmac
      AND directory.source_revision OPERATOR(pg_catalog.=) v_source_revision
      AND directory.source_sha256 OPERATOR(pg_catalog.=) v_source_sha256
      AND directory.state OPERATOR(pg_catalog.=) 'active'
      AND directory.tombstoned_at IS NULL
    FOR SHARE;
    RETURN NEXT;
END;
$$;


