       NOT platform.iam_hmac_key_id_valid_v1(p_key_id) OR
       pg_catalog.octet_length(p_identifier_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM login target V7 input is invalid';
    END IF;
    RETURN QUERY SELECT target.tenant_id, target.source_user_id,
        target.source_identifier_id, target.source_identifier_kind,
        target.source_revision, target.source_sha256,
        target.group_generation, target.iam_generation,
        target.layout_generation
    FROM platform.iam_resolve_login_target_v2(
        p_tenant_id, p_identifier_kind, p_key_id, p_identifier_hmac
    ) AS target;
END;
$$;


ALTER FUNCTION platform.iam_resolve_login_target_v7(p_tenant_id uuid, p_identifier_kind text, p_key_id text, p_identifier_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_resolve_refresh_target_v1(bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_resolve_refresh_target_v1(p_selector bytea) RETURNS TABLE(tenant_id uuid, source_revision bigint, source_sha256 bytea, group_generation bigint, iam_generation bigint, layout_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_probe_tenant_id uuid;
    v_locked_group_generation bigint;
    v_locked_iam_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_selector IS NULL OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh target input is invalid';
    END IF;

    SELECT locator.tenant_id INTO v_probe_tenant_id
    FROM platform.iam_refresh_locators AS locator
    WHERE locator.selector OPERATOR(pg_catalog.=) p_selector
      AND locator.retain_until OPERATOR(pg_catalog.>) pg_catalog.clock_timestamp();
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5732',
            MESSAGE = 'IAM refresh target is not retained';
    END IF;

    SELECT target.group_generation, target.iam_generation,
           target.layout_generation
    INTO group_generation, iam_generation, layout_generation
    FROM platform.iam_resolve_tenant_target_v1(v_probe_tenant_id) AS target;

    SELECT locator.tenant_id, locator.source_revision, locator.source_sha256,
           locator.authority_group_generation, locator.cutover_generation
    INTO tenant_id, source_revision, source_sha256,
         v_locked_group_generation, v_locked_iam_generation
    FROM platform.iam_refresh_locators AS locator
    WHERE locator.selector OPERATOR(pg_catalog.=) p_selector
      AND locator.retain_until OPERATOR(pg_catalog.>) pg_catalog.clock_timestamp()
    FOR SHARE;
    IF NOT FOUND OR tenant_id IS DISTINCT FROM v_probe_tenant_id OR
       v_locked_group_generation IS DISTINCT FROM group_generation OR
       v_locked_iam_generation IS DISTINCT FROM iam_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5732',
            MESSAGE = 'IAM refresh target authority is stale or changed';
    END IF;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.iam_resolve_refresh_target_v1(p_selector bytea) OWNER TO harpy_owner;

--
-- Name: iam_resolve_refresh_target_v2(bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_resolve_refresh_target_v2(p_selector bytea) RETURNS TABLE(tenant_id uuid, source_token_id uuid, source_family_id uuid, source_selector bytea, source_revision bigint, source_sha256 bytea, group_generation bigint, iam_generation bigint, layout_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_probe_tenant_id uuid;
    v_group_generation bigint;
    v_iam_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_selector IS NULL OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh target input is invalid';
    END IF;
    SELECT locator.tenant_id INTO v_probe_tenant_id
    FROM platform.iam_refresh_locators AS locator
    WHERE locator.selector OPERATOR(pg_catalog.=) p_selector
      AND locator.retain_until OPERATOR(pg_catalog.>) pg_catalog.clock_timestamp();
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5732',
            MESSAGE = 'IAM refresh target is not retained';
    END IF;
    SELECT target.group_generation, target.iam_generation,
           target.layout_generation
    INTO group_generation, iam_generation, layout_generation
    FROM platform.iam_resolve_tenant_target_v1(v_probe_tenant_id) AS target;
    SELECT locator.tenant_id, locator.token_id, locator.family_id,
           locator.selector, locator.source_revision, locator.source_sha256,
           locator.authority_group_generation, locator.cutover_generation
    INTO tenant_id, source_token_id, source_family_id, source_selector,
        source_revision, source_sha256, v_group_generation, v_iam_generation
    FROM platform.iam_refresh_locators AS locator
    WHERE locator.selector OPERATOR(pg_catalog.=) p_selector
      AND locator.retain_until OPERATOR(pg_catalog.>) pg_catalog.clock_timestamp()
    FOR UPDATE;
    IF NOT FOUND OR tenant_id IS DISTINCT FROM v_probe_tenant_id OR
       v_group_generation IS DISTINCT FROM group_generation OR
       v_iam_generation IS DISTINCT FROM iam_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5732',
            MESSAGE = 'IAM refresh target authority is stale or changed';
    END IF;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.iam_resolve_refresh_target_v2(p_selector bytea) OWNER TO harpy_owner;

--
-- Name: iam_resolve_tenant_target_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_resolve_tenant_target_v1(p_tenant_id uuid) RETURNS TABLE(tenant_id uuid, group_generation bigint, iam_generation bigint, layout_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM tenant target input is invalid';
    END IF;

    SELECT authority.generation INTO v_generation
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind OPERATOR(pg_catalog.=) 'tenant'
      AND authority.scope_id OPERATOR(pg_catalog.=) p_tenant_id
      AND authority.group_id OPERATOR(pg_catalog.=) 'iam_system_resources'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5701',
            MESSAGE = 'IAM tenant target authority is missing';
    END IF;
    PERFORM platform.iam_assert_current_tenant_authority_v1(
        p_tenant_id, v_generation, v_generation
    );

    tenant_id := p_tenant_id;
    group_generation := v_generation;
    iam_generation := v_generation;
    layout_generation := v_generation;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.iam_resolve_tenant_target_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_security_epoch_for_tenant_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_security_epoch_for_tenant_v1(p_tenant_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_epoch bytea;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM tenant security epoch read is denied';
    END IF;
    SELECT epoch.security_epoch INTO STRICT v_epoch
    FROM platform.tenancy_tenant_bindings AS binding
    JOIN platform.iam_security_epochs AS epoch
      ON epoch.environment_id=binding.environment_id
    WHERE binding.tenant_id=p_tenant_id;
    IF pg_catalog.octet_length(v_epoch) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM tenant security epoch is unavailable';
    END IF;
    RETURN v_epoch;
END;
$$;


ALTER FUNCTION platform.iam_security_epoch_for_tenant_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_security_epoch_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_security_epoch_guard_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM security epoch removal is forbidden';
    END IF;
    IF TG_OP = 'INSERT' AND (
        NEW.generation IS DISTINCT FROM 1 OR
        NEW.rotated_at IS DISTINCT FROM NEW.created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM initial security epoch is invalid';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
        NEW.created_at IS DISTINCT FROM OLD.created_at OR
        NEW.generation IS DISTINCT FROM OLD.generation + 1 OR
        NEW.security_epoch IS NOT DISTINCT FROM OLD.security_epoch OR
        NEW.rotated_at <= OLD.rotated_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM security epoch rotation is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_security_epoch_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_security_epoch_initialize_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_security_epoch_initialize_v1(p_environment_id uuid, p_now timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_environment_id IS NULL OR p_now IS NULL
       OR NOT pg_catalog.isfinite(p_now) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM security epoch initialization denied';
    END IF;
    INSERT INTO platform.iam_security_epochs (
        environment_id, security_epoch, generation, created_at, rotated_at
    ) VALUES (
        p_environment_id,
        pg_catalog.sha256(
            pg_catalog.uuid_send(pg_catalog.gen_random_uuid()) ||
            pg_catalog.uuid_send(pg_catalog.gen_random_uuid())
        ),
        1, p_now, p_now
    ) ON CONFLICT (environment_id) DO NOTHING;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.iam_security_epoch_initialize_v1(p_environment_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_snapshot_domain_generations_v1(uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_snapshot_domain_generations_v1(p_tenant_id uuid, p_first_domain text, p_second_domain text) RETURNS TABLE(result_domain text, result_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR
       p_first_domain IS NULL OR p_second_domain IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM snapshot authority caller is invalid';
    END IF;
    IF p_first_domain !~ '^[a-z][a-z0-9_]{0,62}$' OR
       p_second_domain !~ '^[a-z][a-z0-9_]{0,62}$' OR
       p_first_domain = p_second_domain THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM snapshot authority domains are invalid';
    END IF;
    RETURN QUERY
    SELECT authority.domain, authority.generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.domain IN (p_first_domain,p_second_domain)
      AND authority.state = 'v2' AND authority.writer = 'v2'
    ORDER BY authority.domain;
    IF (SELECT pg_catalog.count(*) FROM platform.domain_cutovers AS authority
        WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
          AND authority.domain IN (p_first_domain,p_second_domain)
          AND authority.state = 'v2' AND authority.writer = 'v2') <> 2 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM snapshot authority is unavailable';
    END IF;
END;
$_$;


ALTER FUNCTION platform.iam_snapshot_domain_generations_v1(p_tenant_id uuid, p_first_domain text, p_second_domain text) OWNER TO harpy_owner;

--
-- Name: iam_system_resources_apply_finalized_switch_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_system_resources_apply_finalized_switch_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_group platform.cutover_groups%ROWTYPE;
    v_members jsonb;
    v_locked_count integer;
    v_changed_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cutover_finalizer' OR
       p_acceptance_digest IS NULL OR
       p_acceptance_digest !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='P5670',
            MESSAGE='IAM system-resource finalized switch authority denied';
    END IF;

    SELECT operation.* INTO STRICT v_operation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
    FOR UPDATE;
    IF v_operation.state IS DISTINCT FROM 'completed' OR
       v_operation.scope_kind IS DISTINCT FROM 'tenant' OR
       v_operation.group_id IS DISTINCT FROM 'iam_system_resources' OR
       v_operation.domain IS DISTINCT FROM 'iam' THEN
        RAISE EXCEPTION USING ERRCODE='P5671',
            MESSAGE='IAM system-resource finalized operation differs';
    END IF;

    SELECT cutover_group.* INTO STRICT v_group
    FROM platform.cutover_groups AS cutover_group
    WHERE cutover_group.scope_kind=v_operation.scope_kind
      AND cutover_group.scope_id=v_operation.scope_id
      AND cutover_group.group_id=v_operation.group_id
    FOR UPDATE;
    IF v_group.state IS DISTINCT FROM 'quiescing' OR
       v_group.writer IS DISTINCT FROM 'none' OR
       v_group.generation IS DISTINCT FROM v_operation.cutover_generation OR
       v_group.approved_by IS NULL OR
       v_group.approved_by IS NOT DISTINCT FROM v_group.requested_by THEN
        RAISE EXCEPTION USING ERRCODE='P5672',
            MESSAGE='IAM system-resource quiescing group differs';
    END IF;

    SELECT pg_catalog.jsonb_agg(member.domain ORDER BY member.ordinal)
    INTO v_members
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
      AND member.group_id=v_group.group_id;
    IF v_members IS DISTINCT FROM '["iam","system_resource_layout"]'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='P5673',
            MESSAGE='IAM system-resource exact members differ';
    END IF;

    PERFORM 1
    FROM platform.cutover_group_members AS member
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=member.scope_kind AND domain_row.scope_id=member.scope_id
     AND domain_row.domain=member.domain
    WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
      AND member.group_id=v_group.group_id
    ORDER BY member.ordinal
    FOR UPDATE OF domain_row;
    GET DIAGNOSTICS v_locked_count = ROW_COUNT;
    IF v_locked_count IS DISTINCT FROM 2 OR EXISTS (
        SELECT 1 FROM platform.cutover_group_members AS member
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind=member.scope_kind AND domain_row.scope_id=member.scope_id
         AND domain_row.domain=member.domain
        WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
          AND member.group_id=v_group.group_id AND
          (domain_row.state IS DISTINCT FROM v_group.state OR
           domain_row.writer IS DISTINCT FROM v_group.writer OR
           domain_row.generation IS DISTINCT FROM v_group.generation OR
           domain_row.requested_by IS DISTINCT FROM v_group.requested_by OR
           domain_row.approved_by IS DISTINCT FROM v_group.approved_by OR
           domain_row.reason IS DISTINCT FROM v_group.reason OR
           domain_row.change_reference IS DISTINCT FROM v_group.change_reference)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P5673',
            MESSAGE='IAM system-resource member authority differs';
    END IF;

    v_changed_at:=pg_catalog.clock_timestamp();
    PERFORM 1
    FROM platform.cutover_group_members AS member
    JOIN platform.async_v1_adoption_runs AS adoption
      ON adoption.scope_kind=member.scope_kind AND adoption.scope_id=member.scope_id
     AND adoption.group_id=member.group_id AND adoption.domain=member.domain
     AND adoption.source_generation=v_group.generation
     AND adoption.target_generation=v_group.generation+1
     AND adoption.source_group_generation=v_group.generation
     AND adoption.target_group_generation=v_group.generation+1
    JOIN platform.async_v1_zero_inventory_receipts AS zero_receipt
      ON zero_receipt.run_id=adoption.run_id
    WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
      AND member.group_id=v_group.group_id AND adoption.state='accepted'
      AND adoption.item_count=0 AND adoption.accepted_at<=v_changed_at
      AND adoption.acceptance_sha256=p_acceptance_digest
      AND zero_receipt.inventory_sha256=adoption.inventory_sha256
      AND zero_receipt.queue_count=0 AND zero_receipt.timer_count=0
      AND zero_receipt.future_count=0 AND zero_receipt.running_count=0
    ORDER BY member.ordinal
    FOR SHARE OF adoption,zero_receipt;
    GET DIAGNOSTICS v_locked_count = ROW_COUNT;
    IF v_locked_count IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING ERRCODE='P5674',
            MESSAGE='IAM system-resource switch requires two accepted zero inventories';
    END IF;

    WITH targets AS (
        SELECT 'group'::text AS target_kind,NULL::text AS domain,
            v_group.requested_by AS requested_by,v_group.approved_by AS approved_by,
            v_group.reason AS reason,v_group.change_reference AS change_reference
        UNION ALL
        SELECT 'domain',domain_row.domain,domain_row.requested_by,domain_row.approved_by,
            domain_row.reason,domain_row.change_reference
        FROM platform.cutover_group_members AS member
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind=member.scope_kind AND domain_row.scope_id=member.scope_id
         AND domain_row.domain=member.domain
        WHERE member.scope_kind=v_group.scope_kind AND member.scope_id=v_group.scope_id
          AND member.group_id=v_group.group_id
    )
    INSERT INTO platform.cutover_transition_events (
        event_id,request_event_id,target_kind,event_kind,scope_kind,scope_id,
        group_id,domain,previous_state,new_state,previous_writer,new_writer,
        previous_generation,new_generation,actor_id,requested_by,approved_by,
        reason,change_reference,acceptance_digest,occurred_at
    )
    SELECT pg_catalog.gen_random_uuid(),request.event_id,target.target_kind,'switch',
        v_group.scope_kind,v_group.scope_id,v_group.group_id,target.domain,
        'quiescing','v2','none','v2',v_group.generation,v_group.generation+1,
        target.approved_by,target.requested_by,target.approved_by,target.reason,
        target.change_reference,p_acceptance_digest,v_changed_at
    FROM targets AS target
    JOIN LATERAL (
        SELECT event.event_id FROM platform.cutover_transition_events AS event
        WHERE event.target_kind=target.target_kind AND event.event_kind='request'
          AND event.scope_kind=v_group.scope_kind AND event.scope_id=v_group.scope_id
          AND event.group_id=v_group.group_id
          AND event.domain IS NOT DISTINCT FROM target.domain
          AND event.new_state='quiescing' AND event.new_generation=v_group.generation
          AND event.requested_by=target.requested_by
          AND event.change_reference=target.change_reference
        ORDER BY event.occurred_at DESC,event.event_id DESC LIMIT 1
    ) AS request ON true;
    GET DIAGNOSTICS v_locked_count = ROW_COUNT;
    IF v_locked_count IS DISTINCT FROM 3 THEN
        RAISE EXCEPTION USING ERRCODE='P5675',
            MESSAGE='IAM system-resource switch request evidence differs';
    END IF;

    UPDATE platform.domain_cutovers AS domain_row
    SET state='v2',writer='v2',generation=domain_row.generation+1,
        acceptance_digest=p_acceptance_digest,changed_at=v_changed_at
    WHERE domain_row.scope_kind=v_group.scope_kind AND domain_row.scope_id=v_group.scope_id
      AND domain_row.domain IN ('iam','system_resource_layout')
      AND domain_row.state='quiescing'
      AND domain_row.writer='none' AND domain_row.generation=v_group.generation;
    GET DIAGNOSTICS v_locked_count = ROW_COUNT;
    IF v_locked_count IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING ERRCODE='P5676',
            MESSAGE='IAM system-resource domain switch lost its lock';
    END IF;
    UPDATE platform.cutover_groups AS cutover_group
    SET state='v2',writer='v2',generation=cutover_group.generation+1,
        acceptance_digest=p_acceptance_digest,changed_at=v_changed_at
    WHERE cutover_group.scope_kind=v_group.scope_kind AND cutover_group.scope_id=v_group.scope_id
      AND cutover_group.group_id=v_group.group_id AND cutover_group.state='quiescing'
      AND cutover_group.writer='none' AND cutover_group.generation=v_group.generation;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P5676',
            MESSAGE='IAM system-resource group switch lost its lock';
    END IF;
END;
$_$;


ALTER FUNCTION platform.iam_system_resources_apply_finalized_switch_v1(p_operation_id uuid, p_run_id uuid, p_acceptance_digest text) OWNER TO harpy_owner;

--
-- Name: iam_system_resources_finalize_transition_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_system_resources_finalize_transition_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_finalizer_lease_id uuid;
    v_terminal_evidence_sha256 text;
    v_verified boolean;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'cutover_operations' THEN
        RAISE EXCEPTION USING ERRCODE='P5677',
            MESSAGE='IAM system-resource finalizer trigger target differs';
    END IF;
    IF OLD.state IS DISTINCT FROM 'quiescing' OR
       NEW.state IS DISTINCT FROM 'completed' OR
       NEW.group_id IS DISTINCT FROM 'iam_system_resources' THEN
        RETURN NEW;
    END IF;
    IF NEW.scope_kind IS DISTINCT FROM 'tenant' OR NEW.domain IS DISTINCT FROM 'iam' OR
       NEW.operation_id IS DISTINCT FROM OLD.operation_id OR
       NEW.run_id IS DISTINCT FROM OLD.run_id OR
       NEW.scope_kind IS DISTINCT FROM OLD.scope_kind OR
       NEW.scope_id IS DISTINCT FROM OLD.scope_id OR
       NEW.group_id IS DISTINCT FROM OLD.group_id OR
       NEW.domain IS DISTINCT FROM OLD.domain OR
       NEW.cutover_generation IS DISTINCT FROM OLD.cutover_generation THEN
        RAISE EXCEPTION USING ERRCODE='P5678',
            MESSAGE='IAM system-resource completed transition differs';
    END IF;

    SELECT receipt.finalizer_lease_id,receipt.terminal_evidence_sha256
    INTO STRICT v_finalizer_lease_id,v_terminal_evidence_sha256
    FROM cutover_authority.finalization_receipts AS receipt
    WHERE receipt.operation_id=NEW.operation_id AND receipt.run_id=NEW.run_id
      AND receipt.terminal_state='completed';
    SELECT cutover_authority.verify_finalization_receipt_v1(
        NEW.operation_id,NEW.run_id,v_finalizer_lease_id,
        'completed',v_terminal_evidence_sha256
    ) INTO STRICT v_verified;
    IF NOT v_verified THEN
        RAISE EXCEPTION USING ERRCODE='P5679',
            MESSAGE='IAM system-resource protected finalization receipt differs';
    END IF;
    PERFORM platform.iam_system_resources_apply_finalized_switch_v1(
        NEW.operation_id,NEW.run_id,v_terminal_evidence_sha256
    );
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.iam_system_resources_finalize_transition_v1() OWNER TO harpy_owner;

--
-- Name: iam_tenant_throttle_record_attempt_v1(uuid, text, text, text, bytea, bigint, bigint, integer, integer, integer, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_tenant_throttle_record_attempt_v1(p_tenant_id uuid, p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_group_generation bigint, p_cutover_generation bigint, p_policy_version integer, p_window_seconds integer, p_block_after integer, p_block_seconds integer) RETURNS TABLE(result_attempt_count integer, result_blocked_until timestamp with time zone, result_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_row platform.iam_auth_throttle_buckets%ROWTYPE;
    v_found boolean; v_prior_found boolean;
    v_now timestamptz;
    v_window_start timestamptz; v_window_end timestamptz;
    v_attempt_count integer; v_blocked_until timestamptz;
    v_revision bigint; v_retain_until timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_purpose IS NULL OR
       NOT (p_purpose OPERATOR(pg_catalog.=) ANY (ARRAY['login','refresh',
           'password_reset','email_verification','portal_setup','invitation','reauth']::text[])) OR
       p_dimension IS NULL OR NOT (p_dimension OPERATOR(pg_catalog.=) ANY (
           ARRAY['tenant_slug','identifier','ip','identifier_ip','selector']::text[])) OR p_key_id IS NULL OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       p_key_id OPERATOR(pg_catalog.!~) '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       p_bucket_hmac IS NULL OR pg_catalog.octet_length(p_bucket_hmac) <> 32 OR
       NOT platform.iam_auth_throttle_policy_v1(
           'tenant', p_purpose, p_dimension, p_policy_version,
           p_window_seconds, p_block_after, p_block_seconds
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM tenant throttle input is invalid';
    END IF;
    PERFORM platform.iam_assert_current_tenant_authority_v1(
        p_tenant_id, p_group_generation, p_cutover_generation
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:iam-throttle:tenant:' || p_tenant_id::text || ':' ||
        COALESCE(p_purpose, '') || ':' || COALESCE(p_dimension, '') || ':' ||
        COALESCE(p_key_id, '') || ':' ||
        COALESCE(pg_catalog.encode(p_bucket_hmac, 'hex'), ''), 0
    ));
    SELECT bucket.* INTO v_row
    FROM platform.iam_auth_throttle_buckets AS bucket
    WHERE bucket.bucket_scope_kind OPERATOR(pg_catalog.=) 'tenant' AND bucket.scope_id OPERATOR(pg_catalog.=) p_tenant_id
      AND bucket.authority_epoch OPERATOR(pg_catalog.=) p_group_generation AND bucket.purpose OPERATOR(pg_catalog.=) p_purpose
      AND bucket.dimension OPERATOR(pg_catalog.=) p_dimension AND bucket.key_id OPERATOR(pg_catalog.=) p_key_id
      AND bucket.bucket_hmac OPERATOR(pg_catalog.=) p_bucket_hmac
    FOR UPDATE;
    v_found := FOUND;
    v_now := pg_catalog.clock_timestamp();
    IF NOT v_found THEN
        SELECT bucket.* INTO v_row
        FROM platform.iam_auth_throttle_buckets AS bucket
        WHERE bucket.bucket_scope_kind OPERATOR(pg_catalog.=) 'tenant' AND bucket.scope_id OPERATOR(pg_catalog.=) p_tenant_id
          AND bucket.authority_epoch OPERATOR(pg_catalog.<) p_group_generation AND bucket.purpose OPERATOR(pg_catalog.=) p_purpose
          AND bucket.dimension OPERATOR(pg_catalog.=) p_dimension AND bucket.key_id OPERATOR(pg_catalog.=) p_key_id
          AND bucket.bucket_hmac OPERATOR(pg_catalog.=) p_bucket_hmac
        ORDER BY bucket.authority_epoch DESC LIMIT 1 FOR SHARE;
        v_prior_found := FOUND;
        IF v_prior_found AND
           v_now OPERATOR(pg_catalog.<=) v_row.last_attempt_at THEN
            v_now := v_row.last_attempt_at OPERATOR(pg_catalog.+)
                INTERVAL '1 microsecond';
        END IF;
        IF v_prior_found AND
           p_policy_version OPERATOR(pg_catalog.<) v_row.policy_version THEN
            RAISE EXCEPTION USING ERRCODE = 'P5722', MESSAGE =
                'IAM tenant throttle prior policy is newer';
        END IF;
        IF v_prior_found AND
           p_policy_version OPERATOR(pg_catalog.=) v_row.policy_version AND
           v_now OPERATOR(pg_catalog.<) v_row.window_end THEN
            IF v_row.attempt_count OPERATOR(pg_catalog.=) 2147483647 THEN
                RAISE EXCEPTION USING ERRCODE = '22003', MESSAGE =
                    'IAM tenant throttle counter overflow';
            END IF;
            v_window_start := v_row.window_start;
            v_window_end := v_row.window_end;
            v_attempt_count := v_row.attempt_count OPERATOR(pg_catalog.+) 1;
            v_blocked_until := v_row.blocked_until;
        ELSE
            v_window_start := v_now;
            v_window_end := v_now OPERATOR(pg_catalog.+)
                pg_catalog.make_interval(secs => p_window_seconds);
            v_attempt_count := 1;
            IF v_prior_found AND v_row.blocked_until OPERATOR(pg_catalog.>) v_now THEN
                v_blocked_until := v_row.blocked_until;
            END IF;
        END IF;
        v_revision := 1;
        IF v_attempt_count OPERATOR(pg_catalog.>=) p_block_after AND (
           v_blocked_until IS NULL OR v_blocked_until OPERATOR(pg_catalog.<) (
               v_now OPERATOR(pg_catalog.+) pg_catalog.make_interval(secs => p_block_seconds))) THEN
            v_blocked_until := v_now OPERATOR(pg_catalog.+)
                pg_catalog.make_interval(secs => p_block_seconds);
        END IF;
    ELSE
        IF v_row.authority_group_generation IS DISTINCT FROM
               p_group_generation OR
           v_row.cutover_generation IS DISTINCT FROM p_cutover_generation OR
           p_policy_version OPERATOR(pg_catalog.<) v_row.policy_version OR
           v_row.revision OPERATOR(pg_catalog.=) 9223372036854775807 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5722', MESSAGE =
                'IAM tenant throttle authority or revision is stale';
        END IF;
        IF v_now OPERATOR(pg_catalog.<=) v_row.last_attempt_at THEN
            v_now := v_row.last_attempt_at OPERATOR(pg_catalog.+)
                INTERVAL '1 microsecond';
        END IF;
        IF v_now OPERATOR(pg_catalog.>=) v_row.window_end OR
           p_policy_version OPERATOR(pg_catalog.>) v_row.policy_version THEN
            v_window_start := v_now;
            v_window_end := v_now OPERATOR(pg_catalog.+)
                pg_catalog.make_interval(secs => p_window_seconds);
            v_attempt_count := 1;
            IF v_row.blocked_until IS NOT NULL AND
               v_row.blocked_until OPERATOR(pg_catalog.>) v_now THEN
                v_blocked_until := v_row.blocked_until;
            END IF;
            IF p_block_after OPERATOR(pg_catalog.=) 1 AND (
               v_blocked_until IS NULL OR v_blocked_until OPERATOR(pg_catalog.<) (
                   v_now OPERATOR(pg_catalog.+)
                   pg_catalog.make_interval(secs => p_block_seconds))) THEN
                v_blocked_until := v_now OPERATOR(pg_catalog.+)
                    pg_catalog.make_interval(secs => p_block_seconds);
            END IF;
        ELSE
            IF v_row.attempt_count OPERATOR(pg_catalog.=) 2147483647 THEN
                RAISE EXCEPTION USING ERRCODE = '22003', MESSAGE =
                    'IAM tenant throttle counter overflow';
            END IF;
            v_window_start := v_row.window_start;
            v_window_end := v_row.window_end;
            v_attempt_count := v_row.attempt_count OPERATOR(pg_catalog.+) 1;
            v_blocked_until := v_row.blocked_until;
            IF v_attempt_count OPERATOR(pg_catalog.>=) p_block_after AND (
               v_blocked_until IS NULL OR v_blocked_until OPERATOR(pg_catalog.<) (
                   v_now OPERATOR(pg_catalog.+)
                   pg_catalog.make_interval(secs => p_block_seconds))) THEN
                v_blocked_until := v_now OPERATOR(pg_catalog.+)
                    pg_catalog.make_interval(secs => p_block_seconds);
            END IF;
        END IF;
        v_revision := v_row.revision OPERATOR(pg_catalog.+) 1;
    END IF;
    v_retain_until := v_window_end OPERATOR(pg_catalog.+) INTERVAL '24 hours';
    IF v_blocked_until IS NOT NULL AND
       v_retain_until OPERATOR(pg_catalog.<) (
           v_blocked_until OPERATOR(pg_catalog.+) INTERVAL '24 hours'
       ) THEN
        v_retain_until := v_blocked_until OPERATOR(pg_catalog.+) INTERVAL '24 hours';
    END IF;
    IF v_found AND v_retain_until OPERATOR(pg_catalog.<) v_row.retain_until THEN
        v_retain_until := v_row.retain_until;
    END IF;
    IF v_found THEN
        UPDATE platform.iam_auth_throttle_buckets AS bucket
        SET policy_version = p_policy_version,
            window_start = v_window_start, window_end = v_window_end,
            attempt_count = v_attempt_count, blocked_until = v_blocked_until,
            last_attempt_at = v_now, revision = v_revision,
            retain_until = v_retain_until
        WHERE bucket.bucket_scope_kind OPERATOR(pg_catalog.=) 'tenant' AND bucket.scope_id OPERATOR(pg_catalog.=) p_tenant_id
          AND bucket.authority_epoch OPERATOR(pg_catalog.=) p_group_generation AND bucket.purpose OPERATOR(pg_catalog.=) p_purpose
          AND bucket.dimension OPERATOR(pg_catalog.=) p_dimension AND bucket.key_id OPERATOR(pg_catalog.=) p_key_id
          AND bucket.bucket_hmac OPERATOR(pg_catalog.=) p_bucket_hmac;
    ELSE
        INSERT INTO platform.iam_auth_throttle_buckets (
            bucket_scope_kind, scope_id, authority_epoch,
            purpose, dimension, key_id, bucket_hmac,
            environment_id, tenant_id, authority_scope_kind, authority_scope_id,
            authority_group_id, authority_group_generation, authority_domain,
            cutover_generation, policy_version, window_start, window_end,
            attempt_count, blocked_until, last_attempt_at, revision, retain_until
        ) VALUES (
            'tenant', p_tenant_id, p_group_generation,
            p_purpose, p_dimension, p_key_id, p_bucket_hmac,
            NULL, p_tenant_id, 'tenant', p_tenant_id, 'iam_system_resources',
            p_group_generation, 'iam', p_cutover_generation, p_policy_version,
            v_window_start, v_window_end, v_attempt_count, v_blocked_until,
            v_now, v_revision, v_retain_until
        );
    END IF;
    result_attempt_count := v_attempt_count;
    result_blocked_until := v_blocked_until;
    result_revision := v_revision;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.iam_tenant_throttle_record_attempt_v1(p_tenant_id uuid, p_purpose text, p_dimension text, p_key_id text, p_bucket_hmac bytea, p_group_generation bigint, p_cutover_generation bigint, p_policy_version integer, p_window_seconds integer, p_block_after integer, p_block_seconds integer) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_assertion_consume_v1(uuid, name, uuid, uuid, uuid, text, text, text, bytea, bytea, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_assertion_consume_v1(p_tenant_id uuid, p_scope_schema name, p_jti uuid, p_subject_id uuid, p_permission_id uuid, p_target_domain text, p_audience text, p_key_id text, p_permission_decision_sha256 bytea, p_target_binding_sha256 bytea, p_iam_group_generation bigint, p_iam_generation bigint, p_target_generation bigint, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_issued_at bigint, p_expires_at bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_iam_group_generation bigint;
    v_iam_generation bigint;
    v_target_generation bigint;
    v_retirement platform.contract_retirements%ROWTYPE;
    v_schema text;
    v_issued_at timestamptz;
    v_expires_at timestamptz;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v1_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_scope_schema IS NULL OR
       p_jti IS NULL OR p_subject_id IS NULL OR
       p_permission_id IS NULL OR p_target_domain IS NULL OR p_audience IS NULL OR
       p_key_id IS NULL OR p_permission_decision_sha256 IS NULL OR
       p_target_binding_sha256 IS NULL OR p_iam_group_generation < 1 OR
       p_iam_generation < 1 OR p_target_generation < 1 OR p_token_version < 1 OR
       p_authorization_version < 1 OR p_authorization_clock < 0 OR
       p_issued_at < 1 OR p_expires_at - p_issued_at <> 30 OR
       p_audience IS DISTINCT FROM
           'urn:harpy:v1-domain:' || p_target_domain OR
       p_key_id !~ '^[a-z][a-z0-9_-]{0,62}$' OR
       pg_catalog.octet_length(p_permission_decision_sha256) <> 32 OR
       pg_catalog.octet_length(p_target_binding_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor assertion consume input is invalid';
    END IF;

    SELECT authority.iam_group_generation, authority.iam_generation,
           authority.target_generation
    INTO STRICT v_iam_group_generation, v_iam_generation, v_target_generation
    FROM platform.iam_v1_actor_bridge_authority_v1(
        p_tenant_id, p_target_domain
    ) AS authority;
    IF v_iam_group_generation IS DISTINCT FROM p_iam_group_generation OR
       v_iam_generation IS DISTINCT FROM p_iam_generation OR
       v_target_generation IS DISTINCT FROM p_target_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5602',
            MESSAGE = 'IAM V1 actor assertion generation is stale';
    END IF;

    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    FOR SHARE;
    IF NOT FOUND OR v_retirement.owner_module IS DISTINCT FROM 'iam' OR
       v_retirement.domain IS DISTINCT FROM 'iam' OR
       v_retirement.state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'IAM V1 actor bridge contract is unavailable';
    END IF;

    v_issued_at := pg_catalog.to_timestamp(p_issued_at);
    v_expires_at := pg_catalog.to_timestamp(p_expires_at);
    v_now := pg_catalog.clock_timestamp();
    IF v_expires_at IS DISTINCT FROM v_issued_at + INTERVAL '30 seconds' OR
       v_now < v_issued_at - INTERVAL '2 seconds' OR v_now >= v_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5605',
            MESSAGE = 'IAM V1 actor assertion lifetime is invalid';
    END IF;

    SELECT tenant.schema_name::text INTO v_schema
    FROM platform.tenants AS tenant
    WHERE tenant.id = p_tenant_id AND tenant.deleted_at IS NULL
    FOR SHARE;
    IF NOT FOUND OR v_schema IS NULL OR
       v_schema IS DISTINCT FROM p_scope_schema::text OR
       v_schema !~ '^t_[a-z2-7]{26}$|^[a-z_][a-z0-9_]{0,62}$' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5601',
            MESSAGE = 'IAM V1 actor assertion tenant is unavailable';
    END IF;

    BEGIN
        INSERT INTO platform.iam_v1_actor_assertion_receipts (
            tenant_id, jti, subject_id, permission_id, target_domain, audience,
            key_id, permission_decision_sha256, target_binding_sha256,
            iam_group_generation, iam_generation, target_generation,
            token_version, authorization_version, authorization_clock,
            issued_at, expires_at, consumed_at
        ) VALUES (
            p_tenant_id, p_jti, p_subject_id, p_permission_id, p_target_domain,
            p_audience, p_key_id, p_permission_decision_sha256,
            p_target_binding_sha256, p_iam_group_generation, p_iam_generation,
            p_target_generation, p_token_version, p_authorization_version,
            p_authorization_clock, v_issued_at, v_expires_at, v_now
        );
    EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5604',
            MESSAGE = 'IAM V1 actor assertion replay is denied';
    END;
    RETURN v_now;
END;
$_$;


ALTER FUNCTION platform.iam_v1_actor_assertion_consume_v1(p_tenant_id uuid, p_scope_schema name, p_jti uuid, p_subject_id uuid, p_permission_id uuid, p_target_domain text, p_audience text, p_key_id text, p_permission_decision_sha256 bytea, p_target_binding_sha256 bytea, p_iam_group_generation bigint, p_iam_generation bigint, p_target_generation bigint, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_issued_at bigint, p_expires_at bigint) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_assertion_issue_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_assertion_issue_v1(p_tenant_id uuid, p_target_domain text) RETURNS TABLE(iam_group_generation bigint, iam_generation bigint, target_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 actor assertion issue authority is denied';
    END IF;
    RETURN QUERY
    SELECT authority.iam_group_generation, authority.iam_generation,
           authority.target_generation
    FROM platform.iam_v1_actor_bridge_authority_v1(
        p_tenant_id, p_target_domain
    ) AS authority;
END;
$$;


ALTER FUNCTION platform.iam_v1_actor_assertion_issue_v1(p_tenant_id uuid, p_target_domain text) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_assertion_purge_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_assertion_purge_v1(p_limit integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_deleted bigint;
    v_cutoff timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_limit IS NULL OR p_limit < 1 OR p_limit > 10000 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor assertion purge input is invalid';
    END IF;
    v_cutoff := pg_catalog.clock_timestamp() - INTERVAL '24 hours';
    WITH candidates AS MATERIALIZED (
        SELECT receipt.tenant_id, receipt.jti
        FROM platform.iam_v1_actor_assertion_receipts AS receipt
        WHERE receipt.accounted_at IS NOT NULL
          AND receipt.expires_at < v_cutoff
        ORDER BY receipt.expires_at, receipt.tenant_id, receipt.jti
        LIMIT p_limit
        FOR UPDATE SKIP LOCKED
    )
    DELETE FROM platform.iam_v1_actor_assertion_receipts AS receipt
    USING candidates
    WHERE receipt.tenant_id = candidates.tenant_id
      AND receipt.jti = candidates.jti;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    RETURN v_deleted;
END;
$$;


ALTER FUNCTION platform.iam_v1_actor_assertion_purge_v1(p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_assertion_reconcile_hits_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_assertion_reconcile_hits_v1(p_limit integer) RETURNS TABLE(accounted_count bigint, latest_hit_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_retirement platform.contract_retirements%ROWTYPE;
    v_count bigint;
    v_latest timestamptz;
    v_now timestamptz;
    v_receipt_tenant_id uuid;
    v_receipt_jti uuid;
    v_receipt_consumed_at timestamptz;
BEGIN
    IF SESSION_USER NOT IN ('harpy_v2_runtime','harpy_migrator') OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_limit IS NULL OR p_limit < 1 OR p_limit > 10000 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor assertion hit reconcile input is invalid';
    END IF;
    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    FOR UPDATE;
    IF NOT FOUND OR v_retirement.owner_module IS DISTINCT FROM 'iam' OR
       v_retirement.domain IS DISTINCT FROM 'iam' OR
       v_retirement.state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'IAM V1 actor bridge contract is unavailable';
    END IF;

    v_count := 0;
    v_latest := NULL;
    FOR v_receipt_tenant_id, v_receipt_jti, v_receipt_consumed_at IN
        SELECT receipt.tenant_id, receipt.jti, receipt.consumed_at
        FROM platform.iam_v1_actor_assertion_receipts AS receipt
        WHERE receipt.accounted_at IS NULL
        ORDER BY receipt.consumed_at, receipt.tenant_id, receipt.jti
        LIMIT p_limit
        FOR UPDATE
    LOOP
        IF v_retirement.hit_count = 9223372036854775807 OR
           v_retirement.revision = 9223372036854775807 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5504',
                MESSAGE = 'IAM V1 actor bridge counter overflow';
        END IF;
        v_now := pg_catalog.clock_timestamp();
        UPDATE platform.iam_v1_actor_assertion_receipts AS receipt
        SET accounted_at = v_now
        WHERE receipt.tenant_id = v_receipt_tenant_id
          AND receipt.jti = v_receipt_jti;
        UPDATE platform.contract_retirements AS retirement
        SET hit_count = retirement.hit_count + 1,
            last_hit_at = v_now,
            revision = retirement.revision + 1,
            updated_at = v_now
        WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1';
        v_retirement.hit_count := v_retirement.hit_count + 1;
        v_retirement.revision := v_retirement.revision + 1;
        v_count := v_count + 1;
        v_latest := CASE
            WHEN v_latest IS NULL OR v_latest < v_receipt_consumed_at
            THEN v_receipt_consumed_at ELSE v_latest
        END;
    END LOOP;
    RETURN QUERY SELECT v_count, v_latest;
END;
$$;


ALTER FUNCTION platform.iam_v1_actor_assertion_reconcile_hits_v1(p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_bridge_authority_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_bridge_authority_v1(p_tenant_id uuid, p_target_domain text) RETURNS TABLE(iam_group_generation bigint, iam_generation bigint, target_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_group platform.cutover_groups%ROWTYPE;
    v_iam platform.domain_cutovers%ROWTYPE;
    v_target platform.domain_cutovers%ROWTYPE;
    v_member_count bigint;
    v_exact_member_count bigint;
    v_retirement platform.contract_retirements%ROWTYPE;
BEGIN
    IF SESSION_USER NOT IN ('harpy_v1_runtime','harpy_v2_runtime') OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_target_domain IS NULL OR
       NOT (p_target_domain = ANY (ARRAY[
           'analytics','billing','catalog','documents',
           'notifications','work','workflow'
       ]::text[])) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor bridge authority input is invalid';
    END IF;

    SELECT authority_group.* INTO v_group
    FROM platform.cutover_groups AS authority_group
    JOIN platform.cutover_group_members AS member
      ON member.scope_kind = authority_group.scope_kind
     AND member.scope_id = authority_group.scope_id
     AND member.group_id = authority_group.group_id
    WHERE authority_group.scope_kind = 'tenant'
      AND authority_group.scope_id = p_tenant_id
      AND member.domain = 'iam'
    FOR SHARE OF authority_group, member;
    IF NOT FOUND OR v_group.group_id IS DISTINCT FROM 'iam_system_resources' OR
       v_group.state IS DISTINCT FROM 'v2' OR v_group.writer IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5601',
            MESSAGE = 'IAM V1 actor bridge IAM group is not V2';
    END IF;

    PERFORM member.ordinal
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind = 'tenant' AND member.scope_id = p_tenant_id
      AND member.group_id = 'iam_system_resources'
    ORDER BY member.ordinal
    FOR SHARE;
    SELECT pg_catalog.count(*),
           pg_catalog.count(*) FILTER (
               WHERE member.domain IN ('iam','system_resource_layout')
           )
    INTO v_member_count, v_exact_member_count
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind = 'tenant' AND member.scope_id = p_tenant_id
      AND member.group_id = 'iam_system_resources';
    IF v_member_count IS DISTINCT FROM 2 OR v_exact_member_count IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5601',
            MESSAGE = 'IAM V1 actor bridge IAM group membership differs';
    END IF;

    PERFORM authority.domain
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.domain IN ('iam', p_target_domain)
    ORDER BY authority.domain COLLATE "C"
    FOR SHARE;
    SELECT authority.* INTO v_iam
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.domain = 'iam';
    SELECT authority.* INTO v_target
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.domain = p_target_domain;
    IF v_iam.state IS DISTINCT FROM 'v2' OR v_iam.writer IS DISTINCT FROM 'v2' OR
       v_target.state NOT IN ('v1','shadow') OR v_target.writer IS DISTINCT FROM 'v1' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5602',
            MESSAGE = 'IAM V1 actor bridge domain authority differs';
    END IF;

    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1';
    IF NOT FOUND OR v_retirement.owner_module IS DISTINCT FROM 'iam' OR
       v_retirement.domain IS DISTINCT FROM 'iam' OR
       v_retirement.state IS DISTINCT FROM 'active' OR
       v_retirement.remaining_scope_count < 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'IAM V1 actor bridge contract is unavailable';
    END IF;

    RETURN QUERY SELECT v_group.generation, v_iam.generation, v_target.generation;
END;
$$;


ALTER FUNCTION platform.iam_v1_actor_bridge_authority_v1(p_tenant_id uuid, p_target_domain text) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_bridge_finalize_v1(bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_bridge_finalize_v1(p_expected_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_retirement platform.contract_retirements%ROWTYPE;
    v_revision bigint;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_expected_revision IS NULL OR p_expected_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor bridge finalization input is invalid';
    END IF;
    PERFORM authority.scope_id, authority.domain
    FROM platform.domain_cutovers AS authority
    JOIN platform.tenants AS tenant
      ON tenant.id = authority.scope_id AND tenant.deleted_at IS NULL
    WHERE authority.scope_kind = 'tenant' AND authority.domain IN (
        'analytics','billing','catalog','documents',
        'notifications','work','workflow'
    )
    ORDER BY authority.scope_id, authority.domain COLLATE "C"
    FOR SHARE OF authority;
    IF EXISTS (
        SELECT 1
        FROM platform.domain_cutovers AS authority
        JOIN platform.tenants AS tenant
          ON tenant.id = authority.scope_id AND tenant.deleted_at IS NULL
        WHERE authority.scope_kind = 'tenant' AND authority.domain IN (
            'analytics','billing','catalog','documents',
            'notifications','work','workflow'
        ) AND authority.state IN ('v1','shadow') AND authority.writer = 'v1'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5607',
            MESSAGE = 'IAM V1 actor bridge still has V1 targets';
    END IF;

    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND OR v_retirement.owner_module IS DISTINCT FROM 'iam' OR
       v_retirement.domain IS DISTINCT FROM 'iam' OR
       v_retirement.state IS DISTINCT FROM 'eligible' OR
       v_retirement.revision IS DISTINCT FROM p_expected_revision OR
       v_retirement.remaining_scope_count IS DISTINCT FROM 0 OR
       v_retirement.zero_hit_since IS NULL OR v_retirement.eligible_at IS NULL OR
       v_retirement.zero_hit_since + INTERVAL '30 days' > v_now OR
       EXISTS (
           SELECT 1 FROM platform.iam_v1_actor_assertion_receipts AS receipt
           WHERE receipt.accounted_at IS NULL OR
                 receipt.consumed_at >= v_retirement.zero_hit_since
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5607',
            MESSAGE = 'IAM V1 actor bridge cannot be finalized';
    END IF;
    IF v_retirement.revision = 9223372036854775807 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5504',
            MESSAGE = 'IAM V1 actor bridge counter overflow';
    END IF;
    UPDATE platform.contract_retirements AS retirement
    SET state = 'retired', retired_at = v_now,
        revision = retirement.revision + 1, updated_at = v_now
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    RETURNING retirement.revision INTO STRICT v_revision;
    RETURN v_revision;
END;
$$;


ALTER FUNCTION platform.iam_v1_actor_bridge_finalize_v1(p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_bridge_mark_eligible_v1(bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_bridge_mark_eligible_v1(p_expected_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_retirement platform.contract_retirements%ROWTYPE;
    v_revision bigint;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_expected_revision IS NULL OR p_expected_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor bridge eligibility input is invalid';
    END IF;
    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    FOR UPDATE;
    v_now := pg_catalog.clock_timestamp();
    IF NOT FOUND OR v_retirement.owner_module IS DISTINCT FROM 'iam' OR
       v_retirement.domain IS DISTINCT FROM 'iam' OR
       v_retirement.state IS DISTINCT FROM 'active' OR
       v_retirement.revision IS DISTINCT FROM p_expected_revision OR
       v_retirement.remaining_scope_count IS DISTINCT FROM 0 OR
       v_retirement.zero_hit_since IS NULL OR
       v_retirement.zero_hit_since + INTERVAL '30 days' > v_now OR
       EXISTS (
           SELECT 1 FROM platform.iam_v1_actor_assertion_receipts AS receipt
           WHERE receipt.accounted_at IS NULL OR
                 receipt.consumed_at >= v_retirement.zero_hit_since
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5607',
            MESSAGE = 'IAM V1 actor bridge is not eligible';
    END IF;
    IF v_retirement.revision = 9223372036854775807 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5504',
            MESSAGE = 'IAM V1 actor bridge counter overflow';
    END IF;
    UPDATE platform.contract_retirements AS retirement
    SET state = 'eligible', eligible_at = v_now,
        revision = retirement.revision + 1, updated_at = v_now
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    RETURNING retirement.revision INTO STRICT v_revision;
    RETURN v_revision;
END;
$$;


ALTER FUNCTION platform.iam_v1_actor_bridge_mark_eligible_v1(p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_bridge_reconcile_v1(bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_actor_bridge_reconcile_v1(p_expected_revision bigint) RETURNS TABLE(remaining_scope_count bigint, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_retirement platform.contract_retirements%ROWTYPE;
    v_remaining bigint;
    v_revision bigint;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_expected_revision IS NULL OR p_expected_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor bridge reconcile input is invalid';
    END IF;
    PERFORM authority.scope_id, authority.domain
    FROM platform.domain_cutovers AS authority
    JOIN platform.tenants AS tenant
      ON tenant.id = authority.scope_id AND tenant.deleted_at IS NULL
    WHERE authority.scope_kind = 'tenant' AND authority.domain IN (
        'analytics','billing','catalog','documents',
        'notifications','work','workflow'
    )
    ORDER BY authority.scope_id, authority.domain COLLATE "C"
    FOR SHARE OF authority;

    SELECT pg_catalog.count(*) INTO v_remaining
    FROM platform.domain_cutovers AS authority
    JOIN platform.tenants AS tenant
      ON tenant.id = authority.scope_id AND tenant.deleted_at IS NULL
    WHERE authority.scope_kind = 'tenant' AND authority.domain IN (
        'analytics','billing','catalog','documents',
        'notifications','work','workflow'
    ) AND authority.state IN ('v1','shadow') AND authority.writer = 'v1';

    SELECT retirement.* INTO v_retirement
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    FOR UPDATE;
    IF NOT FOUND OR v_retirement.owner_module IS DISTINCT FROM 'iam' OR
       v_retirement.domain IS DISTINCT FROM 'iam' OR
       v_retirement.state IS DISTINCT FROM 'active' OR
       v_retirement.revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = 'P5505',
            MESSAGE = 'IAM V1 actor bridge reconcile authority differs';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.iam_v1_actor_assertion_receipts
        WHERE accounted_at IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5606',
            MESSAGE = 'IAM V1 actor bridge hits are not reconciled';
    END IF;
    IF v_retirement.revision = 9223372036854775807 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5504',
            MESSAGE = 'IAM V1 actor bridge counter overflow';
    END IF;

    v_now := pg_catalog.clock_timestamp();
    UPDATE platform.contract_retirements AS retirement
    SET remaining_scope_count = v_remaining,
        zero_hit_since = CASE WHEN v_remaining = 0
            THEN COALESCE(retirement.zero_hit_since, v_now)
            ELSE NULL END,
        eligible_at = NULL,
        revision = retirement.revision + 1,
        updated_at = v_now
    WHERE retirement.contract_key = 'iam.v1_actor_assertion.v1'
    RETURNING retirement.revision INTO STRICT v_revision;
    RETURN QUERY SELECT v_remaining, v_revision;
END;
$$;


ALTER FUNCTION platform.iam_v1_actor_bridge_reconcile_v1(p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_v1_adopt_protected_authority_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_adopt_protected_authority_v1(p_operation_id uuid, p_environment_id uuid, p_primary_tenant_id uuid, p_user_id uuid, p_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_owner_binding_id uuid, p_authorization_version bigint, p_protected_mapping_sha256 text, p_plan_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.iam_v1_protected_authority_adoption_receipts%ROWTYPE;
    v_permission_id uuid;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            !~ '^harpy-cutover/[0-9a-f-]{36}$'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_primary_tenant_id IS NULL OR p_user_id IS NULL OR p_subject_id IS NULL
       OR p_owner_role_id IS NULL OR p_role_permission_id IS NULL
       OR p_owner_binding_id IS NULL
       OR p_authorization_version<1
       OR p_protected_mapping_sha256 !~ '^[0-9a-f]{64}$'
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 protected authority adoption denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('v1-iam-owner|'||p_environment_id::text,0));
    SELECT * INTO v_existing
      FROM platform.iam_v1_protected_authority_adoption_receipts
     WHERE environment_id=p_environment_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.operation_id IS DISTINCT FROM p_operation_id
           OR v_existing.primary_tenant_id IS DISTINCT FROM p_primary_tenant_id
           OR v_existing.user_id IS DISTINCT FROM p_user_id
           OR v_existing.authorization_version IS DISTINCT FROM p_authorization_version
           OR v_existing.subject_id IS DISTINCT FROM p_subject_id
           OR v_existing.owner_role_id IS DISTINCT FROM p_owner_role_id
           OR v_existing.owner_binding_id IS DISTINCT FROM p_owner_binding_id
           OR v_existing.protected_mapping_sha256 IS DISTINCT FROM
                pg_catalog.decode(p_protected_mapping_sha256,'hex')
           OR v_existing.plan_sha256 IS DISTINCT FROM pg_catalog.decode(p_plan_sha256,'hex') THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='V1 protected authority replay conflicts';
        END IF;
        RETURN true;
    END IF;
    PERFORM 1 FROM platform.tenants AS tenant
      JOIN platform.tenancy_tenant_bindings AS binding
        ON binding.tenant_id=tenant.id AND binding.environment_id=p_environment_id
     WHERE tenant.id=p_primary_tenant_id AND tenant.owner_id=p_user_id
       AND tenant.deleted_at IS NULL
       AND binding.purpose IN ('onpremise_primary','saas_control')
     FOR SHARE OF tenant,binding;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 primary tenant owner mapping is unavailable';
    END IF;
    PERFORM 1 FROM platform.iam_login_directory AS directory
     WHERE directory.tenant_id=p_primary_tenant_id AND directory.user_id=p_user_id
       AND directory.state='active' FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 protected account has no active canonical login mapping';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.iam_platform_owner_policies)
       OR EXISTS (SELECT 1 FROM platform.iam_platform_subjects
                  WHERE environment_id=p_environment_id) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='platform owner authority already exists without adoption receipt';
    END IF;
    SELECT permission.id INTO STRICT v_permission_id
      FROM platform.iam_platform_permissions AS permission
     WHERE permission.permission_key='environment_all'
       AND permission.match_kind='environment_all' AND permission.state='active'
     FOR SHARE;
    INSERT INTO platform.iam_platform_subjects(
        id,environment_id,primary_tenant_id,user_id,state,revision,created_at,updated_at
    ) VALUES (p_subject_id,p_environment_id,p_primary_tenant_id,p_user_id,
        'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_roles(
        id,environment_id,role_kind,role_key,state,revision,created_at,updated_at
    ) VALUES (p_owner_role_id,p_environment_id,'instance_owner','instance_owner',
        'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_role_permissions(
        id,environment_id,role_id,permission_id,state,revision,created_at,updated_at
    ) VALUES (p_role_permission_id,p_environment_id,p_owner_role_id,v_permission_id,
        'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_subject_roles(
        id,environment_id,subject_id,role_id,state,revision,created_at,updated_at
    ) VALUES (p_owner_binding_id,p_environment_id,p_subject_id,p_owner_role_id,
        'active',1,v_now,v_now);
    INSERT INTO platform.iam_platform_owner_policies(
        environment_id,owner_binding_id,revision,created_at,updated_at
    ) VALUES (p_environment_id,p_owner_binding_id,1,v_now,v_now);
    INSERT INTO platform.iam_platform_authorization_clocks(
        environment_id,authorization_clock,revision,created_at,updated_at
    ) VALUES (p_environment_id,1,1,v_now,v_now);
    INSERT INTO platform.iam_platform_mutation_receipts VALUES (
        p_operation_id,p_environment_id,'initial_owner',
        pg_catalog.decode(p_plan_sha256,'hex'),p_user_id,p_user_id,p_subject_id,
        p_owner_role_id,p_owner_binding_id,p_role_permission_id,v_permission_id,
        p_authorization_version,1,v_now
    );
    INSERT INTO platform.iam_v1_protected_authority_adoption_receipts(
        operation_id,environment_id,primary_tenant_id,user_id,authorization_version,subject_id,
        owner_role_id,owner_binding_id,protected_mapping_sha256,plan_sha256,
        adopted_at,recorded_by
    ) VALUES (p_operation_id,p_environment_id,p_primary_tenant_id,p_user_id,
        p_authorization_version,p_subject_id,
        p_owner_role_id,p_owner_binding_id,
        pg_catalog.decode(p_protected_mapping_sha256,'hex'),
        pg_catalog.decode(p_plan_sha256,'hex'),v_now,SESSION_USER);
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.iam_v1_adopt_protected_authority_v1(p_operation_id uuid, p_environment_id uuid, p_primary_tenant_id uuid, p_user_id uuid, p_subject_id uuid, p_owner_role_id uuid, p_role_permission_id uuid, p_owner_binding_id uuid, p_authorization_version bigint, p_protected_mapping_sha256 text, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_v1_protected_authority_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_protected_authority_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract text;
    v_oid oid;
    v_signature text;
    v_replayed boolean;
    v_count bigint;
    v_key_sha text;
    v_state_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_batch_bytes IS DISTINCT FROM pg_catalog.octet_length(p_change_batch_bytes)
       OR p_batch_bytes NOT BETWEEN 1 AND 8388608
       OR pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes),'hex')
            IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 protected authority composite denied';
    END IF;
    v_batch := pg_catalog.convert_from(p_change_batch_bytes,'UTF8')::jsonb;
    IF (v_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id
       OR (v_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id
       OR v_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind
       OR (v_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id
       OR (v_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal
       OR v_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key
       OR v_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state
       OR v_batch->'last_key' IS DISTINCT FROM p_last_key
       OR v_batch#>>'{source_position,snapshot_name}' IS DISTINCT FROM p_snapshot_name
       OR (v_batch#>>'{source_position,snapshot_lsn}')::pg_lsn IS DISTINCT FROM p_snapshot_lsn
       OR (v_batch#>>'{source_position,received_lsn}')::pg_lsn IS DISTINCT FROM p_received_lsn
       OR (v_batch#>>'{source_position,commit_lsn}')::pg_lsn IS DISTINCT FROM p_commit_lsn
       OR (v_batch#>>'{source_position,final_lsn}')::pg_lsn IS DISTINCT FROM p_final_lsn
       OR (v_batch#>>'{source_position,source_xid}')::xid8 IS DISTINCT FROM p_source_xid
       OR (v_batch#>>'{source_position,batch_ordinal}')::integer IS DISTINCT FROM p_batch_ordinal THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 protected authority batch evidence differs';
    END IF;
    SELECT prepared.procedure_contract_id,prepared.procedure_oid,
        prepared.procedure_signature,prepared.already_applied,
        prepared.applied_count,prepared.key_state_sha256,prepared.state_sha256
      INTO STRICT v_contract,v_oid,v_signature,v_replayed,
        v_count,v_key_sha,v_state_sha
      FROM platform.cutover_prepare_batch_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
        p_checkpoint_key,p_batch_ordinal,p_commit_lsn,p_source_xid,
        p_batch_sha256,p_lease_manifest_sha256) AS prepared;
    IF v_contract IS DISTINCT FROM 'iam.v1_protected_authority_adoption.v1'
       OR v_oid IS DISTINCT FROM
            'platform.iam_v1_protected_authority_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid
       OR v_signature IS DISTINCT FROM
            'platform.iam_v1_protected_authority_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 protected authority procedure binding differs';
    END IF;
    IF v_replayed THEN
        RETURN QUERY SELECT v_count,v_key_sha,v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count,result.key_state_sha256,result.state_sha256
      INTO STRICT v_count,v_key_sha,v_state_sha
      FROM platform.iam_v1_protected_authority_apply_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
        p_checkpoint_key,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
        p_source_xid,p_batch_ordinal,v_batch,p_batch_sha256) AS result;
    IF v_count<0 OR v_key_sha !~ '^[0-9a-f]{64}$'
       OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='V1 protected authority result is invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id,p_run_id,p_relation_ordinal,p_checkpoint_key,p_snapshot_name,
        p_snapshot_lsn,p_received_lsn,p_commit_lsn,p_final_lsn,p_source_xid,
        p_batch_ordinal,p_checkpoint_state,p_last_key,p_batch_sha256,p_batch_bytes,
        v_count,v_key_sha,v_state_sha);
    RETURN QUERY SELECT v_count,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION platform.iam_v1_protected_authority_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_v1_protected_authority_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.iam_v1_protected_authority_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_after jsonb;
    v_plan jsonb;
    v_authority jsonb;
    v_plan_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            IS DISTINCT FROM 'harpy-cutover/'||p_run_id::text
       OR p_scope_kind IS DISTINCT FROM 'global' OR p_scope_id IS NULL
       OR p_operation_id IS NULL OR p_run_id IS NULL
       OR p_relation_ordinal<1 OR p_checkpoint_key=''
       OR p_snapshot_lsn>p_commit_lsn OR p_received_lsn<p_commit_lsn
       OR p_batch_ordinal NOT BETWEEN 1 AND 2147483
       OR p_batch_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.jsonb_typeof(p_change_batch->'changes')<>'array'
       OR pg_catalog.jsonb_array_length(p_change_batch->'changes')<>1 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 protected authority apply denied';
    END IF;
    v_after := p_change_batch#>'{changes,0,after}';
    IF p_change_batch#>>'{changes,0,kind}' IS DISTINCT FROM 'insert'
       OR p_change_batch#>'{changes,0,before}' IS DISTINCT FROM 'null'::jsonb
       OR pg_catalog.jsonb_typeof(v_after)<>'object'
       OR (SELECT pg_catalog.array_agg(key ORDER BY key)
             FROM pg_catalog.jsonb_object_keys(v_after) AS key)
          IS DISTINCT FROM ARRAY['authority_ids','contract_version','inventory',
              'operation_id','plan']::text[]
       OR v_after->>'contract_version' IS DISTINCT FROM
            'platform-v1-environment-adoption.v1'
       OR (v_after->>'operation_id')::uuid IS DISTINCT FROM p_operation_id THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 protected authority document differs';
    END IF;
    v_plan := v_after->'plan';
    v_authority := v_after->'authority_ids';
    v_plan_sha := v_plan->>'plan_sha256';
    PERFORM 1 FROM platform.platform_cutover_v1_adoption_plans AS recorded
     WHERE recorded.operation_id=p_operation_id
       AND recorded.environment_id=p_scope_id AND recorded.decision='ready'
       AND recorded.primary_tenant_id=(v_plan->>'primary_tenant_id')::uuid
       AND recorded.owner_user_id=(v_plan->>'owner_user_id')::uuid
       AND recorded.plan_sha256=v_plan_sha
       AND recorded.plan_document=v_plan FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 protected authority plan is not recorded';
    END IF;
    PERFORM platform.iam_v1_adopt_protected_authority_v1(
        p_operation_id,p_scope_id,(v_plan->>'primary_tenant_id')::uuid,
        (v_plan->>'owner_user_id')::uuid,(v_authority->>'subject_id')::uuid,
        (v_authority->>'owner_role_id')::uuid,
        (v_authority->>'role_permission_id')::uuid,
        (v_authority->>'owner_binding_id')::uuid,
        (v_plan->>'owner_authorization_version')::bigint,
        v_plan->>'owner_mapping_sha256',v_plan_sha);
    applied_count := 1;
    key_state_sha256 := v_plan_sha;
    state_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'iam:'||v_plan_sha,'UTF8')),'hex');
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.iam_v1_protected_authority_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: notifications_retention_purge_platform_v1(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.notifications_retention_purge_platform_v1(p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
WITH terminal_tickets AS MATERIALIZED (
    SELECT ticket.id, ticket.tenant_id, ticket.user_id,
           ticket.authorization_version, ticket.origin,
           CASE WHEN ticket.consumed_at IS NULL THEN 'expired' ELSE 'consumed' END AS kind,
           COALESCE(ticket.consumed_at, ticket.expires_at) AS terminal_at
    FROM platform.notification_realtime_tickets AS ticket
    WHERE p_tenant_id IS NOT NULL AND pg_catalog.isfinite(p_now)
      AND p_limit BETWEEN 1 AND 500 AND ticket.tenant_id = p_tenant_id
      AND COALESCE(ticket.consumed_at, ticket.expires_at) <= p_now - interval '24 hours'
    ORDER BY COALESCE(ticket.consumed_at, ticket.expires_at), ticket.id
    FOR UPDATE SKIP LOCKED LIMIT p_limit
), inserted_audits AS (
    INSERT INTO platform.notification_realtime_ticket_audits (
        ticket_id, tenant_id, user_id, authorization_version, origin_digest,
        terminal_kind, terminal_at, retain_until
    ) SELECT id, tenant_id, user_id, authorization_version,
        pg_catalog.sha256(pg_catalog.convert_to(origin, 'UTF8')),
        kind, terminal_at, terminal_at + interval '90 days'
    FROM terminal_tickets ON CONFLICT (ticket_id) DO NOTHING RETURNING ticket_id
), removable_tickets AS (
    SELECT candidate.id FROM terminal_tickets AS candidate
    WHERE candidate.id IN (SELECT ticket_id FROM inserted_audits)
       OR EXISTS (
          SELECT 1 FROM platform.notification_realtime_ticket_audits AS audit
          WHERE audit.ticket_id = candidate.id
            AND audit.tenant_id = candidate.tenant_id
            AND audit.user_id = candidate.user_id
            AND audit.authorization_version = candidate.authorization_version
            AND audit.origin_digest = pg_catalog.sha256(
                pg_catalog.convert_to(candidate.origin, 'UTF8'))
            AND audit.terminal_kind = candidate.kind
            AND audit.terminal_at = candidate.terminal_at
       )
), deleted_tickets AS (
    DELETE FROM platform.notification_realtime_tickets AS ticket
    USING removable_tickets WHERE ticket.id = removable_tickets.id RETURNING ticket.id
), locator_candidates AS MATERIALIZED (
    SELECT provider_kind, provider_account_digest, external_message_digest
    FROM platform.notification_provider_locators
    WHERE tenant_id = p_tenant_id AND expires_at <= p_now
    ORDER BY expires_at, delivery_id FOR UPDATE SKIP LOCKED LIMIT p_limit
), deleted_locators AS (
    DELETE FROM platform.notification_provider_locators AS locator
    USING locator_candidates AS candidate
    WHERE locator.provider_kind = candidate.provider_kind
      AND locator.provider_account_digest = candidate.provider_account_digest
      AND locator.external_message_digest = candidate.external_message_digest
    RETURNING locator.delivery_id
), audit_candidates AS MATERIALIZED (
    SELECT ticket_id FROM platform.notification_realtime_ticket_audits
    WHERE tenant_id = p_tenant_id AND retain_until <= p_now
    ORDER BY retain_until, ticket_id FOR UPDATE SKIP LOCKED LIMIT p_limit
), deleted_audits AS (
    DELETE FROM platform.notification_realtime_ticket_audits AS audit
    USING audit_candidates AS candidate
    WHERE audit.ticket_id = candidate.ticket_id RETURNING audit.ticket_id
), legacy_candidates AS MATERIALIZED (
    SELECT id FROM platform.notification_legacy_connection_hits
    WHERE tenant_id = p_tenant_id AND occurred_at <= p_now - interval '90 days'
    ORDER BY occurred_at, id FOR UPDATE SKIP LOCKED LIMIT p_limit
), deleted_legacy AS (
    DELETE FROM platform.notification_legacy_connection_hits AS hit
    USING legacy_candidates AS candidate
    WHERE hit.id = candidate.id RETURNING hit.id
)
SELECT (SELECT pg_catalog.count(*) FROM deleted_tickets)
     + (SELECT pg_catalog.count(*) FROM deleted_locators)
     + (SELECT pg_catalog.count(*) FROM deleted_audits)
     + (SELECT pg_catalog.count(*) FROM deleted_legacy) INTO v_count;
RETURN v_count;
END;
$$;


ALTER FUNCTION platform.notifications_retention_purge_platform_v1(p_tenant_id uuid, p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: platform_async_accept_v1_adoption_v1(uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_accept_v1_adoption_v1(p_run_id uuid, p_zero_inventory_sha256 text, p_disposition_sha256 text, p_accepted_at timestamp with time zone, p_acceptance_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.async_v1_adoption_runs%ROWTYPE;
    v_zero_observed_at timestamptz;
    v_disposition_count bigint;
    v_disposition_sha256 text;
    v_binding_count bigint;
    v_adopted_count bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cluster_admin' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5660',
            MESSAGE = 'V1 async acceptance requires cluster authority';
    END IF;
    SELECT * INTO v_run FROM platform.async_v1_adoption_runs
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id FOR UPDATE;
    IF v_run.state OPERATOR(pg_catalog.=) 'accepted' AND
       v_run.acceptance_sha256 OPERATOR(pg_catalog.=) p_acceptance_sha256 THEN
        RETURN;
    END IF;
    IF NOT FOUND OR v_run.state IS DISTINCT FROM 'disposing' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5661',
            MESSAGE = 'V1 async adoption is not ready for acceptance';
    END IF;
    SELECT observed_at INTO v_zero_observed_at
    FROM platform.async_v1_zero_inventory_receipts
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id
      AND inventory_sha256 OPERATOR(pg_catalog.=) v_run.inventory_sha256
      AND receipt_sha256 OPERATOR(pg_catalog.=) p_zero_inventory_sha256
    FOR SHARE;
    IF NOT FOUND OR p_accepted_at < v_zero_observed_at OR
       p_accepted_at > pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE = 'P5662',
            MESSAGE = 'V1 zero inventory receipt is missing or stale';
    END IF;
    SELECT pg_catalog.count(*),
           pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
               COALESCE(pg_catalog.string_agg(
                   receipt_sha256, E'\n' ORDER BY receipt_sha256
               ), ''), 'UTF8'
           )), 'hex')
    INTO v_disposition_count, v_disposition_sha256
    FROM platform.async_v1_adoption_dispositions
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id;
    IF v_disposition_count IS DISTINCT FROM v_run.item_count OR
       v_disposition_sha256 IS DISTINCT FROM p_disposition_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5663',
            MESSAGE = 'V1 disposition count or checksum differs';
    END IF;
    SELECT pg_catalog.count(*) INTO v_binding_count
    FROM platform.async_v1_adoption_job_bindings
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id;
    SELECT pg_catalog.count(*) INTO v_adopted_count
    FROM platform.async_v1_adoption_dispositions
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id
      AND disposition OPERATOR(pg_catalog.=) 'adopted';
    IF v_binding_count IS DISTINCT FROM v_adopted_count OR EXISTS (
        SELECT 1
        FROM platform.async_v1_adoption_dispositions AS disposition
        JOIN platform.async_v1_adoption_items AS item USING (
            run_id, inventory_class, source_name, source_item_id
        )
        LEFT JOIN platform.async_v1_adoption_job_bindings AS binding USING (
            run_id, inventory_class, source_name, source_item_id
        )
        LEFT JOIN platform.jobs AS job ON job.id OPERATOR(pg_catalog.=) binding.job_id
        WHERE disposition.run_id OPERATOR(pg_catalog.=) p_run_id
          AND disposition.disposition OPERATOR(pg_catalog.=) 'adopted'
          AND (binding.job_id IS NULL OR job.id IS NULL OR
               disposition.target_job_id IS DISTINCT FROM binding.job_id OR
               job.writer_origin IS DISTINCT FROM 'v1' OR
               job.state IS DISTINCT FROM 'queued' OR
               job.cutover_generation IS DISTINCT FROM v_run.target_generation OR
               job.authority_group_generation IS DISTINCT FROM
                   v_run.target_group_generation OR
               job.payload_sha256 IS DISTINCT FROM item.target_payload_sha256 OR
               job.dedupe_key IS DISTINCT FROM item.idempotency_identity)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5664',
            MESSAGE = 'V1 adopted job binding is incomplete';
    END IF;
    UPDATE platform.async_v1_adoption_runs
    SET state = 'accepted', accepted_at = p_accepted_at,
        acceptance_sha256 = p_acceptance_sha256
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id;
END;
$$;


ALTER FUNCTION platform.platform_async_accept_v1_adoption_v1(p_run_id uuid, p_zero_inventory_sha256 text, p_disposition_sha256 text, p_accepted_at timestamp with time zone, p_acceptance_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_adopt_v1_inventory_item_v1(uuid, text, text, text, text, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_adopt_v1_inventory_item_v1(p_run_id uuid, p_inventory_class text, p_source_name text, p_source_item_id text, p_item_sha256 text, p_job_id uuid, p_disposed_at timestamp with time zone, p_receipt_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.async_v1_adoption_runs%ROWTYPE;
    v_item platform.async_v1_adoption_items%ROWTYPE;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5646',
            MESSAGE = 'V1 async item adoption requires adopter authority';
    END IF;
    SELECT * INTO v_run FROM platform.async_v1_adoption_runs
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id FOR UPDATE;
    SELECT * INTO v_item FROM platform.async_v1_adoption_items
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id
      AND inventory_class OPERATOR(pg_catalog.=) p_inventory_class
      AND source_name OPERATOR(pg_catalog.=) p_source_name
      AND source_item_id OPERATOR(pg_catalog.=) p_source_item_id
    FOR SHARE;
    IF v_run.state IS DISTINCT FROM 'disposing' OR NOT FOUND OR
       v_item.item_sha256 IS DISTINCT FROM p_item_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5647',
            MESSAGE = 'V1 async adoption item is not sealed';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.async_v1_adoption_dispositions
        WHERE run_id OPERATOR(pg_catalog.=) p_run_id
          AND inventory_class OPERATOR(pg_catalog.=) p_inventory_class
          AND source_name OPERATOR(pg_catalog.=) p_source_name
          AND source_item_id OPERATOR(pg_catalog.=) p_source_item_id
          AND disposition OPERATOR(pg_catalog.=) 'adopted'
          AND target_job_id OPERATOR(pg_catalog.=) p_job_id
          AND receipt_sha256 OPERATOR(pg_catalog.=) p_receipt_sha256
    ) THEN
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.async_v1_adoption_dispositions
        WHERE run_id OPERATOR(pg_catalog.=) p_run_id
          AND inventory_class OPERATOR(pg_catalog.=) p_inventory_class
          AND source_name OPERATOR(pg_catalog.=) p_source_name
          AND source_item_id OPERATOR(pg_catalog.=) p_source_item_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5648',
            MESSAGE = 'V1 async adoption disposition already differs';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    IF p_disposed_at < v_item.captured_at OR p_disposed_at > v_now THEN
        RAISE EXCEPTION USING ERRCODE = 'P5649',
            MESSAGE = 'V1 async adoption disposition time is invalid';
    END IF;
    INSERT INTO platform.async_v1_adoption_job_bindings (
        run_id, inventory_class, source_name, source_item_id, item_sha256, job_id
    ) VALUES (
        p_run_id, p_inventory_class, p_source_name, p_source_item_id,
        p_item_sha256, p_job_id
    );
    INSERT INTO platform.jobs (
        id, tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation,
        authority_domain, cutover_generation, writer_origin,
        kind, payload_revision, payload_ref, payload_sha256,
        dedupe_key, effect_class, effect_idempotency_key,
        priority, run_at, state, attempts, max_attempts,
        lease_generation, created_at, updated_at
    ) VALUES (
        p_job_id,
        CASE WHEN v_run.scope_kind = 'tenant' THEN v_run.scope_id ELSE NULL END,
        v_run.scope_kind, v_run.scope_id, v_run.group_id,
        v_run.target_group_generation, v_run.domain, v_run.target_generation, 'v1',
        v_item.target_kind, v_item.target_payload_revision,
        v_item.target_payload_ref, v_item.target_payload_sha256,
        v_item.idempotency_identity, v_item.target_effect_class,
        v_item.target_effect_idempotency_key, v_item.target_priority,
        v_item.target_run_at, 'queued', 0, v_item.target_max_attempts,
        0, v_now, v_now
    );
    INSERT INTO platform.async_v1_adoption_dispositions (
        run_id, inventory_class, source_name, source_item_id,
        item_sha256, idempotency_identity, disposition,
        target_job_id, disposed_at, receipt_sha256
    ) VALUES (
        p_run_id, p_inventory_class, p_source_name, p_source_item_id,
        p_item_sha256, v_item.idempotency_identity, 'adopted',
        p_job_id, p_disposed_at, p_receipt_sha256
    );
END;
$$;


ALTER FUNCTION platform.platform_async_adopt_v1_inventory_item_v1(p_run_id uuid, p_inventory_class text, p_source_name text, p_source_item_id text, p_item_sha256 text, p_job_id uuid, p_disposed_at timestamp with time zone, p_receipt_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_assert_cleanup_owner_(text, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_(p_scope_kind text, p_scope_id uuid, p_authority_group_id text, p_authority_domain text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR p_scope_id IS NULL OR
       p_authority_group_id !~ '^[a-z][a-z0-9_]{0,62}$' OR
       p_authority_domain IS DISTINCT FROM 'analytics' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export cleanup owner input is invalid';
    END IF;
    PERFORM 1 FROM platform.cutover_groups AS group_row
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=group_row.scope_kind
     AND domain_row.scope_id=group_row.scope_id
    JOIN platform.cutover_group_members AS member
      ON member.scope_kind=group_row.scope_kind
     AND member.scope_id=group_row.scope_id
     AND member.group_id=group_row.group_id
     AND member.domain=domain_row.domain
    WHERE group_row.scope_kind=p_scope_kind
      AND group_row.scope_id=p_scope_id
      AND group_row.group_id=p_authority_group_id
      AND group_row.state='v2' AND group_row.writer='v2'
      AND domain_row.domain=p_authority_domain
      AND domain_row.state='v2' AND domain_row.writer='v2';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export cleanup owner is not current';
    END IF;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_(p_scope_kind text, p_scope_id uuid, p_authority_group_id text, p_authority_domain text) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_candidate_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_candidate_v1() RETURNS TABLE(tenant_id uuid, tenant_schema name, export_id uuid, job_id uuid, attempt_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Analytics dashboard export candidate authority is invalid';
    END IF;
    RETURN QUERY
    SELECT job.tenant_id,tenant.schema_name::name,job.payload_ref::uuid,
           job.id,(job.attempts + 1)::bigint
    FROM platform.jobs AS job
    JOIN platform.tenants AS tenant ON tenant.id=job.tenant_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind=job.scope_kind
     AND group_row.scope_id=job.scope_id
     AND group_row.group_id=job.authority_group_id
     AND group_row.generation=job.authority_group_generation
     AND group_row.state='v2' AND group_row.writer='v2'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=job.scope_kind
     AND domain_row.scope_id=job.scope_id
     AND domain_row.domain=job.authority_domain
     AND domain_row.generation=job.cutover_generation
     AND domain_row.state='v2' AND domain_row.writer='v2'
    WHERE job.scope_kind='tenant' AND job.scope_id=job.tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3
      AND pg_catalog.pg_input_is_valid(job.payload_ref,'uuid')
      AND job.payload_ref=(job.payload_ref::uuid)::text
      AND pg_catalog.uuid_extract_version(job.payload_ref::uuid)=7
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(job.payload_ref,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||job.payload_ref
      AND job.effect_idempotency_key=job.dedupe_key
      AND job.state='queued' AND job.parked_at IS NULL
      AND job.effect_started_at IS NULL
      AND job.attempts<job.max_attempts
      AND job.run_at<=pg_catalog.clock_timestamp()
      AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE','TRIAL')
    ORDER BY job.priority DESC,job.run_at,job.id
    LIMIT 1;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_candidate_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_checkpoint_v1(uuid, uuid, uuid, uuid, bigint, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_checkpoint_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(lease_until timestamp with time zone, cancellation_requested boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export checkpoint authority is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.state IS DISTINCT FROM 'running' OR v_attempt.attempt_id IS NULL OR
       v_attempt.finished_at IS NOT NULL OR
       v_job.attempts IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_generation IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_until<=pg_catalog.clock_timestamp() OR
       p_observed_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export lease is stale';
    END IF;
    UPDATE platform.jobs SET lease_heartbeat_at=p_observed_at,
        lease_until=p_observed_at+interval '60 seconds',updated_at=p_observed_at
    WHERE id=p_job_id;
    lease_until:=p_observed_at+interval '60 seconds';
    cancellation_requested:=v_job.cancel_requested_at IS NOT NULL;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_checkpoint_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_claim_v1(uuid, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_claim_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid) RETURNS TABLE(claim_state text, attempt_id uuid, claimed_at timestamp with time zone, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_quota platform.artifact_quota_counters%ROWTYPE;
    v_started_at timestamptz;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export claim authority is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export candidate changed';
    END IF;
    IF v_job.state='running' AND v_job.attempts=p_attempt_generation AND
       v_job.lease_generation=p_attempt_generation AND
       v_job.lease_owner_id=p_lease_owner_id THEN
        SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
        WHERE attempt.job_id=p_job_id AND attempt.attempt=p_attempt_generation
          AND attempt.lease_generation=p_attempt_generation
          AND attempt.lease_owner_id=p_lease_owner_id
          AND attempt.finished_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export claim replay differs';
        END IF;
        claim_state:='claimed'; attempt_id:=v_attempt.attempt_id;
        claimed_at:=v_attempt.started_at; lease_until:=v_job.lease_until;
        RETURN NEXT; RETURN;
    END IF;
    IF v_job.state<>'queued' OR v_job.parked_at IS NOT NULL OR
       v_job.effect_started_at IS NOT NULL OR
       v_job.cancel_requested_at IS NOT NULL OR
       v_job.attempts+1<>p_attempt_generation OR
       v_job.attempts>=v_job.max_attempts OR
       v_job.run_at>pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export candidate changed';
    END IF;
    PERFORM 1 FROM platform.tenants AS tenant
    WHERE tenant.id=p_tenant_id AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE','TRIAL') FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export tenant is not claimable';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_group_generation,v_job.authority_domain,
        v_job.cutover_generation);
    SELECT quota.* INTO v_quota
    FROM platform.artifact_quota_counters AS quota
    WHERE quota.tenant_id=p_tenant_id FOR UPDATE;
    IF NOT FOUND OR v_quota.fenced THEN
        RAISE EXCEPTION USING ERRCODE='P6049',
            MESSAGE='Analytics dashboard export artifact quota is fenced';
    END IF;
    IF v_quota.used_ciphertext_bytes+v_quota.reserved_ciphertext_bytes+
       2147483648>21474836480 THEN
        claim_state:='quota_wait'; RETURN NEXT; RETURN;
    END IF;
    v_started_at:=GREATEST(
        pg_catalog.clock_timestamp(),v_job.updated_at+interval '1 microsecond');
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes+2147483648,
        revision=revision+1,updated_at=GREATEST(
            updated_at+interval '1 microsecond',v_started_at)
    WHERE tenant_id=p_tenant_id;
    UPDATE platform.jobs SET state='running',attempts=p_attempt_generation,
        lease_generation=p_attempt_generation,lease_owner_id=p_lease_owner_id,
        lease_heartbeat_at=v_started_at,
        lease_until=v_started_at+interval '60 seconds',updated_at=v_started_at
    WHERE id=p_job_id;
    attempt_id:=pg_catalog.uuidv7();
    INSERT INTO platform.job_attempts(
        attempt_id,job_id,scope_kind,scope_id,attempt,lease_generation,
        lease_owner_id,started_at
    ) VALUES (
        attempt_id,p_job_id,'tenant',p_tenant_id,p_attempt_generation,
        p_attempt_generation,p_lease_owner_id,v_started_at);
    claim_state:='claimed'; claimed_at:=v_started_at;
    lease_until:=v_started_at+interval '60 seconds';
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_claim_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_control_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_control_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_requested_at timestamp with time zone) RETURNS TABLE(control_state text, changed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_resolution platform.analytics_dashboard_export_unknown_resolutions%ROWTYPE;
    v_changed_at timestamptz;
    v_error_digest text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export control authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_requested_at) OR
       p_requested_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export control input is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    IF v_job.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export control evidence differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    IF v_job.state IN ('succeeded','dead','cancelled') THEN
        SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
        WHERE attempt.job_id=p_job_id AND attempt.scope_kind='tenant'
          AND attempt.scope_id=p_tenant_id AND attempt.attempt=v_job.attempts
          AND attempt.lease_generation=v_job.lease_generation FOR SHARE;
        IF v_job.completed_at IS NULL OR v_job.completed_at<>v_job.updated_at THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export terminal evidence differs';
        END IF;
        IF v_job.state='dead' AND v_job.last_error_class IS NULL AND
           v_job.last_error_code='JOB_OUTCOME_UNKNOWN' AND
           v_job.last_error_sha256 IS NULL THEN
            IF NOT COALESCE((
               v_attempt.attempt_id IS NOT NULL AND
               v_attempt.finished_at=v_job.completed_at AND
               v_attempt.outcome='dead' AND v_attempt.error_class IS NULL AND
               v_attempt.error_code='JOB_OUTCOME_UNKNOWN' AND
               v_attempt.redacted_error_sha256 IS NULL AND
               v_attempt.effect_started_at IS NOT NULL AND
               v_attempt.effect_receipt_id IS NULL),false) THEN
                RAISE EXCEPTION USING ERRCODE='P6048',
                    MESSAGE='Analytics dashboard export unknown evidence differs';
            END IF;
            SELECT resolution.* INTO v_resolution
            FROM platform.analytics_dashboard_export_unknown_resolutions AS resolution
            WHERE resolution.job_id=p_job_id FOR SHARE;
            IF FOUND AND (v_resolution.tenant_id<>p_tenant_id OR
               v_resolution.export_id<>p_export_id OR
               v_resolution.attempt_id<>v_attempt.attempt_id OR
               v_resolution.attempt_generation<>v_attempt.attempt OR
               v_resolution.lease_owner_id<>v_attempt.lease_owner_id OR
               v_resolution.effect_id<>v_attempt.effect_id OR
               v_resolution.request_sha256<>v_attempt.effect_request_sha256) THEN
                RAISE EXCEPTION USING ERRCODE='P6048',
                    MESSAGE='Analytics dashboard export resolution evidence differs';
            END IF;
            control_state:=CASE WHEN FOUND THEN 'unknown_resolved'
                ELSE 'outcome_unknown' END;
            changed_at:=COALESCE(v_resolution.resolved_at,v_job.completed_at);
            RETURN NEXT; RETURN;
        END IF;
        IF v_job.state='succeeded' AND NOT COALESCE((
           v_attempt.attempt_id IS NOT NULL AND
           v_job.last_error_class IS NULL AND v_job.last_error_code IS NULL AND
           v_job.last_error_sha256 IS NULL AND
           v_attempt.finished_at=v_job.completed_at AND
           v_attempt.outcome='succeeded' AND
           v_attempt.effect_receipt_id IS NOT NULL),false) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export success evidence differs';
        ELSIF v_job.state='dead' AND NOT COALESCE((
           v_attempt.attempt_id IS NOT NULL AND
           v_job.last_error_class IN ('transient','permanent','conflict') AND
           v_attempt.finished_at=v_job.completed_at AND
           v_attempt.outcome='dead' AND
           v_attempt.error_class=v_job.last_error_class AND
           v_attempt.error_code=v_job.last_error_code AND
            v_attempt.redacted_error_sha256=v_job.last_error_sha256 AND
           ((v_attempt.effect_started_at IS NULL AND
             v_attempt.effect_receipt_id IS NULL) OR
            (v_attempt.effect_started_at IS NOT NULL AND
             v_attempt.effect_receipt_id IS NOT NULL))),false) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export failure evidence differs';
        ELSIF v_job.state='cancelled' AND NOT COALESCE((
           v_job.last_error_class='cancelled' AND
           v_job.last_error_code='EXPORT_CANCELLED' AND
           v_job.last_error_sha256~'^[0-9a-f]{64}$' AND
           v_job.last_error_sha256<>pg_catalog.repeat('0',64) AND NOT EXISTS (
             SELECT 1 FROM platform.job_attempts AS active
             WHERE active.job_id=p_job_id AND active.finished_at IS NULL
           ) AND ((v_job.attempts=0 AND v_job.lease_generation=0 AND
                   v_attempt.attempt_id IS NULL AND NOT EXISTS (
                     SELECT 1 FROM platform.job_attempts AS unexpected
                     WHERE unexpected.job_id=p_job_id
                   )) OR (v_job.attempts>0 AND
                   v_attempt.attempt_id IS NOT NULL AND
                   v_attempt.finished_at IS NOT NULL AND (
                     (v_attempt.outcome IN ('requeued','lease_expired') AND
                      v_attempt.finished_at<v_job.completed_at) OR
                     (v_attempt.outcome='cancelled' AND
                      v_attempt.finished_at=v_job.completed_at AND
                      v_attempt.error_class=v_job.last_error_class AND
                      v_attempt.error_code=v_job.last_error_code AND
                      v_attempt.redacted_error_sha256=v_job.last_error_sha256)
                   )))),false) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export cancellation evidence differs';
        END IF;
        control_state:=v_job.state; changed_at:=v_job.completed_at;
        RETURN NEXT; RETURN;
    END IF;
    IF v_job.state='running' AND v_job.cancel_requested_at IS NOT NULL THEN
        control_state:='cancellation_requested';
        changed_at:=v_job.cancel_requested_at;
        RETURN NEXT; RETURN;
    END IF;
    v_changed_at:=GREATEST(pg_catalog.clock_timestamp(),p_requested_at,
        v_job.updated_at+interval '1 microsecond');
    IF v_job.state='queued' AND v_job.effect_started_at IS NULL THEN
        v_error_digest:=pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.convert_to('analytics.dashboard.export.cancel.v1','UTF8')||
            pg_catalog.uuid_send(p_job_id)||pg_catalog.uuid_send(p_export_id)),'hex');
        UPDATE platform.jobs SET state='cancelled',
            last_error_class='cancelled',last_error_code='EXPORT_CANCELLED',
            last_error_sha256=v_error_digest,
            retain_until=v_changed_at+interval '91 days',
            updated_at=v_changed_at,completed_at=v_changed_at
        WHERE id=p_job_id;
        control_state:='cancelled'; changed_at:=v_changed_at;
        RETURN NEXT; RETURN;
    END IF;
    IF v_job.state='running' THEN
        UPDATE platform.jobs SET cancel_requested_at=v_changed_at,
            updated_at=v_changed_at WHERE id=p_job_id;
        control_state:='cancellation_requested'; changed_at:=v_changed_at;
        RETURN NEXT; RETURN;
    END IF;
    RAISE EXCEPTION USING ERRCODE='P6048',
        MESSAGE='Analytics dashboard export control state is invalid';
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_control_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_requested_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_effect_receipt_v1(uuid, uuid, uuid, uuid, uuid, text, text, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_effect_receipt_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_receipt_id uuid, p_status text, p_error_class text, p_code text, p_provider_reference text, p_result_sha256 bytea, p_completed_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_receipt_id uuid;
    v_result_ref text;
    v_result_digest text;
    v_exact boolean;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       (p_receipt_id IS NOT NULL AND
        pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7) OR
       p_status NOT IN ('succeeded','failed') OR
       p_code !~ '^[A-Z][A-Z0-9_]{1,63}$' OR
       (p_provider_reference IS NOT NULL AND
        pg_catalog.octet_length(p_provider_reference) NOT BETWEEN 1 AND 512) OR
       NOT pg_catalog.isfinite(p_completed_at) OR
       (p_status='succeeded' AND (p_receipt_id IS NULL OR
        p_error_class IS NOT NULL OR
        pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
        p_result_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex'))) OR
       (p_status='failed' AND (
        p_error_class NOT IN ('transient','permanent','conflict','cancelled') OR
        p_result_sha256 IS NOT NULL)) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export effect receipt input is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id;
    IF v_job.id IS NULL OR v_attempt.attempt_id IS NULL OR
       v_attempt.effect_started_at IS NULL OR v_attempt.effect_id IS NULL OR
       v_attempt.effect_request_sha256 IS NULL OR
       p_completed_at<v_attempt.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export effect evidence is incomplete';
    END IF;
    v_receipt_id:=COALESCE(p_receipt_id,pg_catalog.uuidv7());
    v_result_ref:=CASE WHEN p_status='succeeded' THEN
        'analytics-dashboard-export/'||p_export_id::text||'/artifact' END;
    v_result_digest:=CASE WHEN p_status='succeeded' THEN
        pg_catalog.encode(p_result_sha256,'hex') END;
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,
        authority_group_id,authority_group_generation,authority_domain,
        cutover_generation,writer_origin,request_sha256,retention_class,
        effect_id,effect_kind,effect_revision,effect_key,provider,operation,
        correlation_id,causation_id,effect_status,effect_error_class,effect_code,
        provider_reference,effect_result_ref,effect_result_sha256,
        completed_at,retain_until
    ) VALUES (
        v_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
        v_job.authority_group_id,v_job.authority_group_generation,
        v_job.authority_domain,v_job.cutover_generation,'v2',
        v_attempt.effect_request_sha256,'external_effect',v_attempt.effect_id,
        'analytics.dashboard.export.render',1,v_job.effect_idempotency_key,
        'object-storage','put-object',v_attempt.effect_id::text,p_job_id,
        p_status,p_error_class,p_code,p_provider_reference,v_result_ref,
        v_result_digest,p_completed_at,p_completed_at+interval '91 days'
    ) ON CONFLICT DO NOTHING;
    SELECT receipt.receipt_id=v_receipt_id INTO v_exact
    FROM platform.idempotency_receipts AS receipt
    WHERE receipt.receipt_id=v_receipt_id AND receipt.record_kind='effect'
      AND receipt.scope_kind='tenant' AND receipt.scope_id=p_tenant_id
      AND receipt.authority_domain='analytics'
      AND receipt.effect_id=v_attempt.effect_id
      AND receipt.effect_kind='analytics.dashboard.export.render'
      AND receipt.effect_revision=1 AND receipt.effect_key=v_job.dedupe_key
      AND receipt.provider='object-storage' AND receipt.operation='put-object'
      AND receipt.request_sha256=v_attempt.effect_request_sha256
      AND receipt.effect_status=p_status
      AND receipt.effect_error_class IS NOT DISTINCT FROM p_error_class
      AND receipt.effect_code=p_code
      AND receipt.provider_reference IS NOT DISTINCT FROM p_provider_reference
      AND receipt.effect_result_ref IS NOT DISTINCT FROM v_result_ref
      AND receipt.effect_result_sha256 IS NOT DISTINCT FROM v_result_digest
      AND receipt.completed_at=p_completed_at;
    IF NOT COALESCE(v_exact,false) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export effect receipt replay differs';
    END IF;
    RETURN v_receipt_id;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_effect_receipt_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_receipt_id uuid, p_status text, p_error_class text, p_code text, p_provider_reference text, p_result_sha256 bytea, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_effect_start_v1(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_effect_start_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_started_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_request text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       NOT pg_catalog.isfinite(p_started_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export effect authority is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_attempt.effect_started_at IS NOT NULL THEN
        IF v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_job.effect_started_at=v_attempt.effect_started_at THEN
            RETURN v_attempt.effect_started_at;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export effect replay differs';
    END IF;
    IF v_job.state IS DISTINCT FROM 'running' OR v_attempt.attempt_id IS NULL OR
       v_attempt.finished_at IS NOT NULL OR v_job.cancel_requested_at IS NOT NULL OR
       v_job.effect_started_at IS NOT NULL OR
       v_job.attempts IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_generation IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_until<=pg_catalog.clock_timestamp() OR
       p_started_at<=v_job.updated_at OR p_started_at<v_attempt.started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export effect lease is stale';
    END IF;
    UPDATE platform.jobs SET effect_started_at=p_started_at,updated_at=p_started_at
    WHERE id=p_job_id;
    UPDATE platform.job_attempts SET effect_started_at=p_started_at,
        effect_id=p_effect_id,effect_request_sha256=v_request
    WHERE attempt_id=p_attempt_id;
    RETURN p_started_at;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_effect_start_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_started_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_expired_candidate_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_expired_candidate_v1() RETURNS TABLE(tenant_id uuid, tenant_schema name, export_id uuid, job_id uuid, attempt_id uuid, attempt_generation bigint, lease_owner_id uuid, effect_started boolean, effect_id uuid, effect_request_sha256 bytea, cancellation_requested boolean, lease_expired_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export expired candidate authority is invalid';
    END IF;
    RETURN QUERY
    SELECT job.tenant_id,tenant.schema_name::name,job.payload_ref::uuid,job.id,
        attempt.attempt_id,attempt.attempt::bigint,attempt.lease_owner_id,
        attempt.effect_started_at IS NOT NULL,attempt.effect_id,
        CASE WHEN attempt.effect_request_sha256 IS NULL THEN NULL::bytea
             ELSE pg_catalog.decode(attempt.effect_request_sha256,'hex') END,
        job.cancel_requested_at IS NOT NULL,job.lease_until
    FROM platform.jobs AS job
    JOIN platform.job_attempts AS attempt
      ON attempt.job_id=job.id AND attempt.scope_kind='tenant'
     AND attempt.scope_id=job.tenant_id AND attempt.attempt=job.attempts
     AND attempt.lease_generation=job.lease_generation
     AND attempt.lease_owner_id=job.lease_owner_id
    JOIN platform.tenants AS tenant ON tenant.id=job.tenant_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind=job.scope_kind
     AND group_row.scope_id=job.scope_id
     AND group_row.group_id=job.authority_group_id
     AND group_row.state='v2' AND group_row.writer='v2'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=job.scope_kind
     AND domain_row.scope_id=job.scope_id
     AND domain_row.domain=job.authority_domain
     AND domain_row.state='v2' AND domain_row.writer='v2'
    JOIN platform.cutover_group_members AS member
      ON member.scope_kind=job.scope_kind AND member.scope_id=job.scope_id
     AND member.group_id=job.authority_group_id
     AND member.domain=job.authority_domain
    WHERE job.scope_kind='tenant' AND job.scope_id=job.tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3
      AND pg_catalog.pg_input_is_valid(job.payload_ref,'uuid')
      AND job.payload_ref=(job.payload_ref::uuid)::text
      AND pg_catalog.uuid_extract_version(job.payload_ref::uuid)=7
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(job.payload_ref,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||job.payload_ref
      AND job.effect_idempotency_key=job.dedupe_key
      AND job.state='running' AND job.lease_until<=pg_catalog.clock_timestamp()
      AND attempt.finished_at IS NULL
      AND attempt.attempt BETWEEN 1 AND 3
      AND pg_catalog.uuid_extract_version(attempt.attempt_id)=7
      AND pg_catalog.uuid_extract_version(attempt.lease_owner_id)=7
      AND ((attempt.effect_started_at IS NULL AND attempt.effect_id IS NULL AND
            attempt.effect_request_sha256 IS NULL AND job.effect_started_at IS NULL) OR
           (attempt.effect_started_at IS NOT NULL AND
            pg_catalog.uuid_extract_version(attempt.effect_id)=7 AND
            attempt.effect_request_sha256~'^[0-9a-f]{64}$' AND
            attempt.effect_request_sha256<>pg_catalog.repeat('0',64) AND
            job.effect_started_at=attempt.effect_started_at))
      AND tenant.deleted_at IS NULL
    ORDER BY job.lease_until,job.id LIMIT 1;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_expired_candidate_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_expired_finalize_v1(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_expired_finalize_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_observed_at timestamp with time zone) RETURNS TABLE(final_state text, finalized_at timestamp with time zone, failure_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_request text;
    v_error_class text;
    v_error_code text;
    v_error_digest text;
    v_outcome text;
    v_job_state text;
    v_finalized_at timestamptz;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export expiry authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' OR NOT (
        p_effect_id IS NULL AND p_request_sha256 IS NULL OR
        pg_catalog.uuid_extract_version(p_effect_id)=7 AND
        pg_catalog.octet_length(p_request_sha256)=32 AND
        p_request_sha256<>pg_catalog.decode(pg_catalog.repeat('00',32),'hex')
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export expiry input is invalid';
    END IF;
    v_request:=CASE WHEN p_request_sha256 IS NOT NULL THEN
        pg_catalog.encode(p_request_sha256,'hex') END;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.id IS NULL OR v_attempt.attempt_id IS NULL OR
       v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export expiry evidence differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    IF v_attempt.finished_at IS NOT NULL THEN
        IF v_job.state='dead' AND v_job.last_error_class IS NULL AND
           v_job.last_error_code='JOB_OUTCOME_UNKNOWN' AND
           v_attempt.outcome='dead' AND v_attempt.error_class IS NULL AND
           v_attempt.error_code='JOB_OUTCOME_UNKNOWN' AND
           v_attempt.effect_started_at IS NOT NULL AND
           v_attempt.finished_at=v_job.completed_at THEN
            final_state:='outcome_unknown'; finalized_at:=v_job.completed_at;
            RETURN NEXT; RETURN;
        END IF;
        IF v_attempt.effect_started_at IS NULL AND
           v_attempt.finished_at=v_job.updated_at AND (
            v_job.state='queued' AND v_attempt.outcome='requeued' OR
            v_job.state='dead' AND v_attempt.outcome='dead' OR
            v_job.state='cancelled' AND v_attempt.outcome='cancelled') AND
           v_attempt.error_class=v_job.last_error_class AND
           v_attempt.error_code=v_job.last_error_code AND
           v_attempt.redacted_error_sha256=v_job.last_error_sha256 THEN
            final_state:=v_job.state; finalized_at:=v_attempt.finished_at;
            failure_sha256:=pg_catalog.decode(v_attempt.redacted_error_sha256,'hex');
            RETURN NEXT; RETURN;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export expiry replay differs';
    END IF;
    IF v_job.state IS DISTINCT FROM 'running' OR
       v_job.attempts<>p_attempt_generation OR
       v_job.lease_generation<>p_attempt_generation OR
       v_job.lease_owner_id<>p_lease_owner_id OR
       v_job.lease_until>pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export expiry lease is not expired';
    END IF;
    v_finalized_at:=GREATEST(pg_catalog.clock_timestamp(),p_observed_at,
        v_job.updated_at+interval '1 microsecond');
    IF v_attempt.effect_started_at IS NOT NULL THEN
        v_outcome:='dead'; v_job_state:='dead';
        UPDATE platform.job_attempts SET finished_at=v_finalized_at,
            outcome='dead',error_class=NULL,error_code='JOB_OUTCOME_UNKNOWN',
            redacted_error_sha256=NULL,effect_receipt_id=NULL
        WHERE attempt_id=p_attempt_id;
        UPDATE platform.jobs SET state='dead',lease_owner_id=NULL,
            lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=NULL,
            last_error_code='JOB_OUTCOME_UNKNOWN',last_error_sha256=NULL,
            retain_until=v_finalized_at+interval '366 days',
            updated_at=v_finalized_at,completed_at=v_finalized_at
        WHERE id=p_job_id;
        final_state:='outcome_unknown'; finalized_at:=v_finalized_at;
        RETURN NEXT; RETURN;
    END IF;
    IF v_job.cancel_requested_at IS NOT NULL THEN
        v_outcome:='cancelled'; v_job_state:='cancelled';
        v_error_class:='cancelled'; v_error_code:='EXPORT_CANCELLED';
    ELSIF p_attempt_generation<3 THEN
        v_outcome:='requeued'; v_job_state:='queued';
        v_error_class:='transient'; v_error_code:='JOB_LEASE_EXPIRED';
    ELSE
        v_outcome:='dead'; v_job_state:='dead';
        v_error_class:='transient'; v_error_code:='JOB_LEASE_EXPIRED';
    END IF;
    v_error_digest:=pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to('analytics.dashboard.export.expiry.v1','UTF8')||
        pg_catalog.uuid_send(p_job_id)||pg_catalog.uuid_send(p_attempt_id)||
        pg_catalog.int8send(p_attempt_generation)||
        pg_catalog.convert_to(v_error_code,'UTF8')),'hex');
    UPDATE platform.job_attempts SET finished_at=v_finalized_at,
        outcome=v_outcome,error_class=v_error_class,error_code=v_error_code,
        redacted_error_sha256=v_error_digest WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state=v_job_state,
        run_at=CASE WHEN v_job_state='queued' THEN
            v_finalized_at+interval '5 seconds' ELSE run_at END,
        lease_owner_id=NULL,lease_heartbeat_at=NULL,lease_until=NULL,
        last_error_class=v_error_class,last_error_code=v_error_code,
        last_error_sha256=v_error_digest,
        retain_until=CASE WHEN v_job_state='dead' THEN v_finalized_at+interval '366 days'
            WHEN v_job_state='cancelled' THEN v_finalized_at+interval '91 days' END,
        updated_at=v_finalized_at,
        completed_at=CASE WHEN v_job_state='queued' THEN NULL ELSE v_finalized_at END
    WHERE id=p_job_id;
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
        revision=revision+1,updated_at=GREATEST(
            updated_at+interval '1 microsecond',v_finalized_at)
    WHERE tenant_id=p_tenant_id AND reserved_ciphertext_bytes>=2147483648;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6049',
            MESSAGE='Analytics dashboard export expiry quota is inconsistent';
    END IF;
    final_state:=v_job_state; finalized_at:=v_finalized_at;
    failure_sha256:=pg_catalog.decode(v_error_digest,'hex'); RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_expired_finalize_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_finish_v1(uuid, uuid, uuid, uuid, bigint, uuid, text, text, bytea, boolean, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_finish_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_failure_class text, p_failure_code text, p_failure_sha256 bytea, p_retryable boolean, p_provider_reference text, p_finished_at timestamp with time zone) RETURNS TABLE(job_state text, effect_receipt_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_receipt_id uuid;
    v_outcome text;
    v_job_state text;
    v_retry_at timestamptz;
    v_digest text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export finish authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       p_failure_class NOT IN ('transient','permanent','conflict','cancelled') OR
       p_failure_code !~ '^[A-Z][A-Z0-9_]{1,63}$' OR
       pg_catalog.octet_length(p_failure_sha256) IS DISTINCT FROM 32 OR
       p_failure_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       (p_retryable AND p_failure_class NOT IN ('transient','conflict')) OR
       (p_failure_class='cancelled' AND p_retryable) OR
       (p_provider_reference IS NOT NULL AND
        pg_catalog.octet_length(p_provider_reference) NOT BETWEEN 1 AND 512) OR
       NOT pg_catalog.isfinite(p_finished_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export finish input is invalid';
    END IF;
    v_digest:=pg_catalog.encode(p_failure_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF p_failure_class='cancelled' AND v_job.cancel_requested_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export cancellation was not requested';
    END IF;
    IF p_failure_class='cancelled' AND
       v_attempt.effect_started_at IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export cancellation cleanup is required';
    END IF;
    IF p_failure_class='cancelled' THEN
        v_outcome:='cancelled'; v_job_state:='cancelled';
    ELSIF p_retryable AND p_attempt_generation<3 AND
          v_attempt.effect_started_at IS NULL THEN
        v_outcome:='requeued'; v_job_state:='queued';
    ELSE
        v_outcome:='dead'; v_job_state:='dead';
    END IF;
    IF v_attempt.finished_at IS NOT NULL THEN
        IF NOT COALESCE((v_job.state=v_job_state AND
           v_job.updated_at=p_finished_at AND v_job.lease_owner_id IS NULL AND
           v_job.lease_heartbeat_at IS NULL AND v_job.lease_until IS NULL AND
           v_job.last_error_class=p_failure_class AND
           v_job.last_error_code=p_failure_code AND
           v_job.last_error_sha256=v_digest AND
           v_job.effect_started_at IS NOT DISTINCT FROM
               v_attempt.effect_started_at AND
           ((v_job_state='queued' AND v_job.completed_at IS NULL AND
             v_job.retain_until IS NULL AND v_job.run_at>=p_finished_at AND
             v_job.run_at<=p_finished_at+interval '15 minutes') OR
            (v_job_state='dead' AND v_job.completed_at=p_finished_at AND
             v_job.retain_until=p_finished_at+interval '366 days') OR
            (v_job_state='cancelled' AND v_job.completed_at=p_finished_at AND
             v_job.retain_until=p_finished_at+interval '91 days')) AND
           v_attempt.outcome=v_outcome AND
           v_attempt.error_class=p_failure_class AND
           v_attempt.error_code=p_failure_code AND
           v_attempt.redacted_error_sha256=v_digest AND
           v_attempt.finished_at=p_finished_at),false) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export finish replay differs';
        END IF;
        IF v_attempt.effect_started_at IS NOT NULL THEN
            IF v_attempt.effect_receipt_id IS NULL THEN
                RAISE EXCEPTION USING ERRCODE='P6048',
                    MESSAGE='Analytics dashboard export finish receipt is missing';
            END IF;
            PERFORM platform.platform_async_analytics_dashboard_export_effect_receipt_v1(
                p_tenant_id,p_export_id,p_job_id,p_attempt_id,
                v_attempt.effect_receipt_id,'failed',p_failure_class,
                p_failure_code,p_provider_reference,NULL,p_finished_at);
        ELSIF v_attempt.effect_receipt_id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export finish receipt is unexpected';
        END IF;
        job_state:=v_job_state;
        effect_receipt_id:=v_attempt.effect_receipt_id;
        RETURN NEXT; RETURN;
    END IF;
    IF v_job.state IS DISTINCT FROM 'running' OR v_attempt.attempt_id IS NULL OR
       v_job.attempts IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_generation IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_until<=pg_catalog.clock_timestamp() OR
       p_finished_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export finish lease is stale';
    END IF;
    IF v_attempt.effect_started_at IS NOT NULL THEN
        v_receipt_id:=platform.platform_async_analytics_dashboard_export_effect_receipt_v1(
            p_tenant_id,p_export_id,p_job_id,p_attempt_id,NULL,'failed',
            p_failure_class,p_failure_code,p_provider_reference,NULL,p_finished_at);
    END IF;
    UPDATE platform.job_attempts SET finished_at=p_finished_at,
        outcome=v_outcome,error_class=p_failure_class,error_code=p_failure_code,
        redacted_error_sha256=v_digest,effect_receipt_id=v_receipt_id
    WHERE attempt_id=p_attempt_id;
    v_retry_at:=CASE WHEN v_job_state='queued' THEN p_finished_at+
        pg_catalog.random()*LEAST(
            interval '5 seconds'*pg_catalog.power(
                2::double precision,(p_attempt_generation-1)::double precision),
            interval '15 minutes') ELSE p_finished_at END;
    UPDATE platform.jobs SET state=v_job_state,
        run_at=CASE WHEN v_job_state='queued' THEN v_retry_at ELSE run_at END,
        lease_owner_id=NULL,lease_heartbeat_at=NULL,lease_until=NULL,
        last_error_class=p_failure_class,last_error_code=p_failure_code,
        last_error_sha256=v_digest,
        retain_until=CASE WHEN v_job_state='dead' THEN
            p_finished_at+interval '366 days' WHEN v_job_state='cancelled' THEN
            p_finished_at+interval '91 days' END,updated_at=p_finished_at,
        completed_at=CASE WHEN v_job_state='queued' THEN NULL ELSE p_finished_at END
    WHERE id=p_job_id;
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
        revision=revision+1,updated_at=GREATEST(
            updated_at+interval '1 microsecond',p_finished_at)
    WHERE tenant_id=p_tenant_id AND reserved_ciphertext_bytes>=2147483648;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6049',
            MESSAGE='Analytics dashboard export finish quota is inconsistent';
    END IF;
    job_state:=v_job_state; effect_receipt_id:=v_receipt_id;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_finish_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_failure_class text, p_failure_code text, p_failure_sha256 bytea, p_retryable boolean, p_provider_reference text, p_finished_at timestamp with time zone) OWNER TO harpy_owner;

SET default_tablespace = '';

SET default_table_access_method = heap;

