    updated_at timestamp with time zone CONSTRAINT analytics_dashboard_export_maintenance_unkn_updated_at_not_null NOT NULL,
    CONSTRAINT analytics_dashboard_export_maintenance_claim_lease_check CHECK (((claim_generation >= 0) AND (((cleanup_lease_owner_id IS NULL) AND (lease_heartbeat_at IS NULL) AND (lease_until IS NULL)) OR ((uuid_extract_version(cleanup_lease_owner_id) = 7) AND (claim_generation > 0) AND (lease_heartbeat_at IS NOT NULL) AND (lease_until IS NOT NULL) AND (lease_heartbeat_at < lease_until))))),
    CONSTRAINT analytics_dashboard_export_maintenance_claim_shape_check CHECK (((kind = ANY (ARRAY['analytics.dashboard.export.delete'::text, 'analytics.dashboard.export.expire'::text])) AND ((tenant_schema)::text ~ '^[a-z][a-z0-9_]{0,62}$'::text) AND (uuid_extract_version(export_id) = 7) AND (uuid_extract_version(job_id) = 7) AND (authority_group_id ~ '^[a-z][a-z0-9_]{0,62}$'::text) AND (authority_group_generation > 0) AND (cutover_generation > 0) AND (uuid_extract_version(attempt_id) = 7) AND ((attempt_number >= 1) AND (attempt_number <=
CASE kind
    WHEN 'analytics.dashboard.export.delete'::text THEN 3
    ELSE 8
END)) AND (lease_generation > 0) AND (uuid_extract_version(original_lease_owner_id) = 7) AND (uuid_extract_version(effect_id) = 5) AND (request_sha256 ~ '^[0-9a-f]{64}$'::text) AND (request_sha256 <> repeat('0'::text, 64)) AND isfinite(unknown_at))),
    CONSTRAINT analytics_dashboard_export_maintenance_claim_time_check CHECK ((isfinite(run_at) AND isfinite(created_at) AND isfinite(updated_at) AND (created_at <= updated_at)))
);


