    resolved_at timestamp with time zone CONSTRAINT analytics_dashboard_export_maintenance_unk_resolved_at_not_null NOT NULL,
    CONSTRAINT analytics_dashboard_export_maintenance_resolution_shape_check CHECK (((uuid_extract_version(resolution_receipt_id) = 7) AND (uuid_extract_version(effect_receipt_id) = 5) AND (effect_receipt_sha256 ~ '^[0-9a-f]{64}$'::text) AND (effect_receipt_sha256 <> repeat('0'::text, 64)) AND (resolution_sha256 ~ '^[0-9a-f]{64}$'::text) AND (resolution_sha256 <> repeat('0'::text, 64)) AND (kind = ANY (ARRAY['analytics.dashboard.export.delete'::text, 'analytics.dashboard.export.expire'::text])) AND ((tenant_schema)::text ~ '^[a-z][a-z0-9_]{0,62}$'::text) AND (uuid_extract_version(export_id) = 7) AND (uuid_extract_version(job_id) = 7) AND (authority_group_id ~ '^[a-z][a-z0-9_]{0,62}$'::text) AND (authority_group_generation > 0) AND (cutover_generation > 0) AND (uuid_extract_version(attempt_id) = 7) AND ((attempt_number >= 1) AND (attempt_number <=
CASE kind
    WHEN 'analytics.dashboard.export.delete'::text THEN 3
    ELSE 8
END)) AND (lease_generation > 0) AND (uuid_extract_version(original_lease_owner_id) = 7) AND (uuid_extract_version(effect_id) = 5) AND (request_sha256 ~ '^[0-9a-f]{64}$'::text) AND (request_sha256 <> repeat('0'::text, 64)) AND (original_attempt_outcome = 'dead'::text) AND (original_error_class IS NULL) AND (original_error_code = 'JOB_OUTCOME_UNKNOWN'::text) AND (original_error_sha256 IS NULL) AND (cleanup_generation > 0) AND (uuid_extract_version(cleanup_lease_owner_id) = 7) AND (((kind = 'analytics.dashboard.export.delete'::text) AND (terminal_state = 'deleted'::text) AND (provider_code = 'ANALYTICS_EXPORT_DELETED'::text)) OR ((kind = 'analytics.dashboard.export.expire'::text) AND (terminal_state = ANY (ARRAY['expired'::text, 'cancelled'::text, 'failed'::text, 'deleted'::text])) AND (provider_code = 'ANALYTICS_EXPORT_EXPIRY_COMPLETE'::text))) AND (provider_reference = (export_id)::text) AND (result_sha256 ~ '^[0-9a-f]{64}$'::text) AND (result_sha256 <> repeat('0'::text, 64)) AND isfinite(original_unknown_at) AND (original_attempt_finished_at = original_unknown_at) AND isfinite(resolved_at) AND (resolved_at > original_unknown_at)))
);


