--
-- Name: job_attempts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.job_attempts (
    attempt_id uuid NOT NULL,
    job_id uuid NOT NULL,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    attempt integer NOT NULL,
    lease_generation bigint NOT NULL,
    lease_owner_id uuid NOT NULL,
    started_at timestamp with time zone NOT NULL,
    finished_at timestamp with time zone,
    outcome text,
    error_class text,
    error_code text,
    redacted_error_sha256 text,
    effect_started_at timestamp with time zone,
    effect_id uuid,
    effect_request_sha256 text,
    effect_receipt_id uuid,
    CONSTRAINT job_attempts_attempt_check CHECK (((attempt >= 1) AND (attempt <= 25))),
    CONSTRAINT job_attempts_effect_identity_check CHECK ((((effect_started_at IS NULL) AND (effect_id IS NULL) AND (effect_request_sha256 IS NULL)) OR ((effect_started_at IS NOT NULL) AND (effect_id IS NOT NULL) AND (effect_request_sha256 IS NOT NULL)))),
    CONSTRAINT job_attempts_effect_request_sha256_check CHECK ((effect_request_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT job_attempts_error_check CHECK ((((outcome IS NULL) AND (error_class IS NULL) AND (error_code IS NULL) AND (redacted_error_sha256 IS NULL)) OR ((outcome = 'succeeded'::text) AND (error_class IS NULL) AND (error_code IS NULL) AND (redacted_error_sha256 IS NULL)) OR ((outcome = 'dead'::text) AND (error_class IS NULL) AND (error_code = 'JOB_OUTCOME_UNKNOWN'::text) AND (redacted_error_sha256 IS NULL) AND (effect_started_at IS NOT NULL) AND (effect_receipt_id IS NULL)) OR ((outcome = ANY (ARRAY['requeued'::text, 'dead'::text, 'cancelled'::text, 'lease_expired'::text])) AND (error_class IS NOT NULL) AND (error_code IS NOT NULL) AND (redacted_error_sha256 IS NOT NULL)))),
    CONSTRAINT job_attempts_error_class_check CHECK ((error_class = ANY (ARRAY['transient'::text, 'permanent'::text, 'conflict'::text, 'cancelled'::text]))),
    CONSTRAINT job_attempts_error_code_check CHECK ((error_code ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT job_attempts_lease_check CHECK ((lease_generation = attempt)),
    CONSTRAINT job_attempts_lease_generation_check CHECK ((lease_generation > 0)),
    CONSTRAINT job_attempts_outcome_check CHECK ((outcome = ANY (ARRAY['succeeded'::text, 'requeued'::text, 'dead'::text, 'cancelled'::text, 'lease_expired'::text]))),
    CONSTRAINT job_attempts_redacted_error_sha256_check CHECK ((redacted_error_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT job_attempts_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT job_attempts_terminal_check CHECK ((((finished_at IS NULL) AND (outcome IS NULL) AND (error_class IS NULL) AND (error_code IS NULL) AND (redacted_error_sha256 IS NULL) AND (effect_receipt_id IS NULL)) OR ((finished_at IS NOT NULL) AND (outcome IS NOT NULL)))),
    CONSTRAINT job_attempts_time_check CHECK ((((effect_started_at IS NULL) OR (started_at <= effect_started_at)) AND ((finished_at IS NULL) OR (started_at <= finished_at)) AND ((effect_started_at IS NULL) OR (finished_at IS NULL) OR (effect_started_at <= finished_at))))
);


ALTER TABLE platform.job_attempts OWNER TO harpy_owner;

--
-- Name: jobs; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.jobs (
    id uuid NOT NULL,
    tenant_id uuid,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    authority_group_id text NOT NULL,
    authority_group_generation bigint NOT NULL,
    authority_domain text NOT NULL,
    cutover_generation bigint NOT NULL,
    writer_origin text NOT NULL,
    kind text NOT NULL,
    payload_revision integer NOT NULL,
    payload_ref text,
    payload_sha256 text NOT NULL,
    payload_redacted_at timestamp with time zone,
    dedupe_key text NOT NULL,
    effect_class text NOT NULL,
    effect_idempotency_key text,
    priority integer NOT NULL,
    run_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    attempts integer NOT NULL,
    max_attempts integer NOT NULL,
    lease_owner_id uuid,
    lease_generation bigint NOT NULL,
    lease_heartbeat_at timestamp with time zone,
    lease_until timestamp with time zone,
    cancel_requested_at timestamp with time zone,
    parked_at timestamp with time zone,
    parked_code text,
    parked_current_group_generation bigint,
    parked_current_cutover_generation bigint,
    effect_started_at timestamp with time zone,
    last_error_class text,
    last_error_code text,
    last_error_sha256 text,
    retry_of_job_id uuid,
    retain_until timestamp with time zone,
    retention_release_revision bigint DEFAULT 0 NOT NULL,
    retention_release_sha256 text,
    retention_released_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT jobs_attempt_check CHECK (((attempts <= max_attempts) AND (lease_generation = attempts))),
    CONSTRAINT jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT jobs_authority_domain_check CHECK ((authority_domain ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT jobs_authority_group_generation_check CHECK ((authority_group_generation > 0)),
    CONSTRAINT jobs_authority_group_id_check CHECK ((authority_group_id ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT jobs_cutover_generation_check CHECK ((cutover_generation > 0)),
    CONSTRAINT jobs_dedupe_key_check CHECK (((octet_length(dedupe_key) >= 1) AND (octet_length(dedupe_key) <= 512))),
    CONSTRAINT jobs_effect_check CHECK (((effect_class = 'database_transactional'::text) OR (effect_idempotency_key IS NOT NULL))),
    CONSTRAINT jobs_effect_class_check CHECK ((effect_class = ANY (ARRAY['database_transactional'::text, 'external'::text]))),
    CONSTRAINT jobs_effect_idempotency_key_check CHECK (((octet_length(effect_idempotency_key) >= 1) AND (octet_length(effect_idempotency_key) <= 512))),
    CONSTRAINT jobs_error_check CHECK ((((state = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text])) AND (last_error_class IS NULL) AND (last_error_code IS NULL) AND (last_error_sha256 IS NULL)) OR ((state = 'dead'::text) AND (last_error_class IS NULL) AND (last_error_code = 'JOB_OUTCOME_UNKNOWN'::text) AND (last_error_sha256 IS NULL) AND (effect_started_at IS NOT NULL)) OR ((state = ANY (ARRAY['queued'::text, 'running'::text, 'dead'::text, 'cancelled'::text])) AND (last_error_class IS NOT NULL) AND (last_error_code IS NOT NULL) AND (last_error_sha256 IS NOT NULL)))),
    CONSTRAINT jobs_kind_check CHECK ((kind ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT jobs_last_error_class_check CHECK ((last_error_class = ANY (ARRAY['transient'::text, 'permanent'::text, 'conflict'::text, 'cancelled'::text]))),
    CONSTRAINT jobs_last_error_code_check CHECK ((last_error_code ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT jobs_last_error_sha256_check CHECK ((last_error_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT jobs_lease_check CHECK ((((state = 'running'::text) AND (attempts > 0) AND (lease_owner_id IS NOT NULL) AND (lease_heartbeat_at IS NOT NULL) AND (lease_until IS NOT NULL) AND (lease_heartbeat_at < lease_until)) OR ((state <> 'running'::text) AND (lease_owner_id IS NULL) AND (lease_heartbeat_at IS NULL) AND (lease_until IS NULL)))),
    CONSTRAINT jobs_lease_generation_check CHECK ((lease_generation >= 0)),
    CONSTRAINT jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 25))),
    CONSTRAINT jobs_outcome_check CHECK ((((state = ANY (ARRAY['queued'::text, 'running'::text])) AND (completed_at IS NULL)) OR ((state = ANY (ARRAY['succeeded'::text, 'dead'::text, 'cancelled'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT jobs_parked_check CHECK ((((parked_at IS NULL) AND (parked_code IS NULL) AND (parked_current_group_generation IS NULL) AND (parked_current_cutover_generation IS NULL)) OR ((state = ANY (ARRAY['queued'::text, 'cancelled'::text])) AND (parked_at IS NOT NULL) AND (parked_code IS NOT NULL) AND (parked_current_group_generation >= authority_group_generation) AND (parked_current_cutover_generation >= cutover_generation) AND ((parked_current_group_generation > authority_group_generation) OR (parked_current_cutover_generation > cutover_generation))))),
    CONSTRAINT jobs_parked_code_check CHECK ((parked_code ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT jobs_parked_current_cutover_generation_check CHECK ((parked_current_cutover_generation > 0)),
    CONSTRAINT jobs_parked_current_group_generation_check CHECK ((parked_current_group_generation > 0)),
    CONSTRAINT jobs_payload_check CHECK ((((payload_ref IS NOT NULL) AND ((octet_length(payload_ref) >= 1) AND (octet_length(payload_ref) <= 2048)) AND (payload_redacted_at IS NULL)) OR ((payload_ref IS NULL) AND (payload_redacted_at IS NOT NULL)))),
    CONSTRAINT jobs_payload_revision_check CHECK ((payload_revision > 0)),
    CONSTRAINT jobs_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT jobs_retention_check CHECK ((((state = ANY (ARRAY['queued'::text, 'running'::text])) AND (retain_until IS NULL) AND (retention_release_revision = 0) AND (retention_release_sha256 IS NULL) AND (retention_released_at IS NULL)) OR ((state = ANY (ARRAY['succeeded'::text, 'cancelled'::text])) AND (retain_until >= (completed_at + '90 days'::interval))) OR ((state = 'dead'::text) AND (retain_until >= (completed_at + '365 days'::interval))))),
    CONSTRAINT jobs_retention_release_check CHECK ((((retention_release_revision = 0) AND (retention_release_sha256 IS NULL) AND (retention_released_at IS NULL)) OR ((retention_release_revision > 0) AND (retention_release_sha256 IS NOT NULL) AND (retention_released_at IS NOT NULL)))),
    CONSTRAINT jobs_retention_release_revision_check CHECK ((retention_release_revision >= 0)),
    CONSTRAINT jobs_retention_release_sha256_check CHECK ((retention_release_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT jobs_scope_check CHECK ((((scope_kind = 'tenant'::text) AND (tenant_id IS NOT NULL) AND (tenant_id = scope_id)) OR ((scope_kind = 'global'::text) AND (tenant_id IS NULL)))),
    CONSTRAINT jobs_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT jobs_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'dead'::text, 'cancelled'::text]))),
    CONSTRAINT jobs_time_check CHECK (((created_at <= updated_at) AND ((payload_redacted_at IS NULL) OR (completed_at <= payload_redacted_at)) AND ((payload_redacted_at IS NULL) OR (state = ANY (ARRAY['succeeded'::text, 'dead'::text, 'cancelled'::text]))) AND ((cancel_requested_at IS NULL) OR (created_at <= cancel_requested_at)) AND ((parked_at IS NULL) OR (created_at <= parked_at)) AND ((effect_started_at IS NULL) OR (created_at <= effect_started_at)) AND ((completed_at IS NULL) OR (completed_at <= updated_at)) AND ((retention_released_at IS NULL) OR (completed_at <= retention_released_at)))),
    CONSTRAINT jobs_writer_origin_check CHECK ((writer_origin = ANY (ARRAY['v1'::text, 'v2'::text])))
);


ALTER TABLE platform.jobs OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_assert_re(platform.jobs, platform.job_attempts, platform.analytics_dashboard_export_maintenance_unknown_claims, platform.analytics_dashboard_export_maintenance_unknown_resolutions, uuid, bytea, uuid, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_assert_re(p_job platform.jobs, p_attempt platform.job_attempts, p_claim platform.analytics_dashboard_export_maintenance_unknown_claims, p_resolution platform.analytics_dashboard_export_maintenance_unknown_resolutions, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_resolution_receipt_id uuid, p_resolution_sha256 bytea, p_terminal_state text, p_resolved_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_receipt platform.idempotency_receipts%ROWTYPE;
    v_operation text;
    v_code text;
    v_result_ref text;
    v_expected_receipt_id uuid;
BEGIN
    v_operation:=CASE p_claim.kind WHEN 'analytics.dashboard.export.delete' THEN
        'delete' WHEN 'analytics.dashboard.export.expire' THEN 'expire' END;
    v_code:=CASE p_claim.kind WHEN 'analytics.dashboard.export.delete' THEN
        'ANALYTICS_EXPORT_DELETED' ELSE 'ANALYTICS_EXPORT_EXPIRY_COMPLETE' END;
    v_result_ref:='analytics-dashboard-export://'||v_operation||'/'||
        p_claim.export_id::text||'/'||p_terminal_state;
    v_expected_receipt_id:=
        platform.platform_async_analytics_export_maint_receipt_id_v1(
            p_attempt.effect_id,p_job.kind);
    SELECT receipt.* INTO v_receipt FROM platform.idempotency_receipts receipt
    WHERE receipt.receipt_id=p_effect_receipt_id FOR SHARE;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_claim.job_id IS NULL OR p_resolution.job_id IS NULL OR
       p_job.kind IS DISTINCT FROM p_claim.kind OR
       p_attempt.effect_id IS DISTINCT FROM p_claim.effect_id OR
       p_effect_receipt_id IS DISTINCT FROM v_expected_receipt_id OR
       p_resolution.effect_receipt_id IS DISTINCT FROM v_expected_receipt_id OR
       v_receipt.receipt_id IS DISTINCT FROM v_expected_receipt_id OR
       p_resolution.kind IS DISTINCT FROM p_claim.kind OR
       p_resolution.tenant_id IS DISTINCT FROM p_claim.tenant_id OR
       p_resolution.tenant_schema IS DISTINCT FROM p_claim.tenant_schema OR
       p_resolution.export_id IS DISTINCT FROM p_claim.export_id OR
       p_resolution.authority_group_id IS DISTINCT FROM p_claim.authority_group_id OR
       p_resolution.authority_group_generation IS DISTINCT FROM
           p_claim.authority_group_generation OR
       p_resolution.cutover_generation IS DISTINCT FROM p_claim.cutover_generation OR
       p_resolution.attempt_id IS DISTINCT FROM p_claim.attempt_id OR
       p_resolution.attempt_number IS DISTINCT FROM p_claim.attempt_number OR
       p_resolution.lease_generation IS DISTINCT FROM p_claim.lease_generation OR
       p_resolution.original_lease_owner_id IS DISTINCT FROM
           p_claim.original_lease_owner_id OR
       p_resolution.effect_id IS DISTINCT FROM p_claim.effect_id OR
       p_resolution.request_sha256 IS DISTINCT FROM p_claim.request_sha256 OR
       p_resolution.original_unknown_at IS DISTINCT FROM p_claim.unknown_at OR
       p_resolution.original_attempt_finished_at IS DISTINCT FROM p_claim.unknown_at OR
       p_resolution.original_attempt_outcome IS DISTINCT FROM 'dead' OR
       p_resolution.original_error_class IS NOT NULL OR
       p_resolution.original_error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       p_resolution.original_error_sha256 IS NOT NULL OR
       p_resolution.cleanup_generation IS DISTINCT FROM p_claim.claim_generation OR
       p_resolution.cleanup_lease_owner_id IS DISTINCT FROM
           p_claim.cleanup_lease_owner_id OR
       p_resolution.resolution_receipt_id IS DISTINCT FROM p_resolution_receipt_id OR
       p_resolution.effect_receipt_id IS DISTINCT FROM p_effect_receipt_id OR
       p_resolution.effect_receipt_sha256 IS DISTINCT FROM
           pg_catalog.encode(p_effect_receipt_sha256,'hex') OR
       p_resolution.resolution_sha256 IS DISTINCT FROM
           pg_catalog.encode(p_resolution_sha256,'hex') OR
       p_resolution.terminal_state IS DISTINCT FROM p_terminal_state OR
       p_resolution.provider_code IS DISTINCT FROM v_code OR
       p_resolution.result_reference IS DISTINCT FROM v_result_ref OR
       p_resolution.resolved_at IS DISTINCT FROM p_resolved_at OR
       p_job.id IS DISTINCT FROM p_claim.job_id OR p_job.state IS DISTINCT FROM 'succeeded' OR
       p_job.completed_at IS DISTINCT FROM p_resolved_at OR
       p_job.updated_at IS DISTINCT FROM p_resolved_at OR
       p_job.retain_until IS DISTINCT FROM p_resolved_at+interval '90 days' OR
       p_attempt.attempt_id IS DISTINCT FROM p_claim.attempt_id OR
       p_attempt.outcome IS DISTINCT FROM 'succeeded' OR
       p_attempt.effect_receipt_id IS DISTINCT FROM p_effect_receipt_id OR
       p_attempt.finished_at IS DISTINCT FROM p_resolved_at OR
       v_receipt.effect_id IS DISTINCT FROM p_claim.effect_id OR
       v_receipt.effect_kind IS DISTINCT FROM p_claim.kind OR
       v_receipt.request_sha256 IS DISTINCT FROM p_claim.request_sha256 OR
       v_receipt.effect_status IS DISTINCT FROM 'succeeded' OR
       v_receipt.effect_code IS DISTINCT FROM v_code OR
       v_receipt.effect_result_ref IS DISTINCT FROM v_result_ref OR
       v_receipt.completed_at IS DISTINCT FROM p_resolved_at OR
       platform.platform_async_analytics_dashboard_export_maintenance_receipt_sha256_v1(
           p_job,p_attempt,p_effect_receipt_id,p_terminal_state,p_resolved_at)
           IS DISTINCT FROM p_effect_receipt_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution replay differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_assert_re(p_job platform.jobs, p_attempt platform.job_attempts, p_claim platform.analytics_dashboard_export_maintenance_unknown_claims, p_resolution platform.analytics_dashboard_export_maintenance_unknown_resolutions, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_resolution_receipt_id uuid, p_resolution_sha256 bytea, p_terminal_state text, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_effect_ow(uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_effect_ow(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_effect_id uuid, p_observed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_max integer;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance effect owner is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 5 OR
       pg_catalog.isfinite(p_observed_at) IS DISTINCT FROM true OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export maintenance effect owner input is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs job
    WHERE job.id=p_job_id FOR UPDATE;
    v_max:=CASE v_job.kind WHEN 'analytics.dashboard.export.delete' THEN 3
        WHEN 'analytics.dashboard.export.expire' THEN 8 END;
    IF v_job.id IS NULL OR v_job.tenant_id IS DISTINCT FROM p_tenant_id OR
       v_job.scope_kind IS DISTINCT FROM 'tenant' OR
       v_job.scope_id IS DISTINCT FROM p_tenant_id OR v_max IS NULL OR
       v_job.authority_domain IS DISTINCT FROM 'analytics' OR
       v_job.writer_origin IS DISTINCT FROM 'v2' OR
       v_job.payload_revision IS DISTINCT FROM 1 OR
       v_job.effect_class IS DISTINCT FROM 'external' OR
       v_job.max_attempts IS DISTINCT FROM v_max OR
       v_job.payload_ref IS DISTINCT FROM p_export_id::text OR
       v_job.payload_sha256 IS DISTINCT FROM pg_catalog.encode(pg_catalog.sha256(
           pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex') OR
       v_job.dedupe_key IS DISTINCT FROM v_job.kind||':'||p_export_id::text OR
       v_job.effect_idempotency_key IS DISTINCT FROM v_job.dedupe_key THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance job evidence differs';
    END IF;
    IF v_job.state IS DISTINCT FROM 'running' OR v_job.completed_at IS NOT NULL OR
       v_job.attempts NOT BETWEEN 1 AND v_max OR v_job.lease_generation<1 OR
       pg_catalog.uuid_extract_version(v_job.lease_owner_id) IS DISTINCT FROM 7 OR
       v_job.lease_until<=p_observed_at OR v_job.effect_started_at IS NULL OR
       p_observed_at<v_job.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export maintenance effect lease is stale';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts attempt
    WHERE attempt.job_id=v_job.id AND attempt.scope_kind='tenant'
      AND attempt.scope_id=p_tenant_id AND attempt.attempt=v_job.attempts
      AND attempt.lease_generation=v_job.lease_generation FOR UPDATE;
    IF v_attempt.attempt_id IS NULL OR v_attempt.finished_at IS NOT NULL OR
       v_attempt.outcome IS NOT NULL OR
       v_attempt.lease_owner_id IS DISTINCT FROM v_job.lease_owner_id OR
       v_attempt.effect_started_at IS DISTINCT FROM v_job.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export maintenance attempt lease is stale';
    END IF;
    IF v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       pg_catalog.uuid_extract_version(v_attempt.effect_id) IS DISTINCT FROM 5 OR
       v_attempt.effect_request_sha256!~'^[0-9a-f]{64}$' OR
       v_attempt.effect_request_sha256=pg_catalog.repeat('0',64) OR
       v_attempt.effect_receipt_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance effect evidence differs';
    END IF;
    PERFORM 1 FROM platform.cutover_groups group_row
    JOIN platform.domain_cutovers domain_row
      ON domain_row.scope_kind=group_row.scope_kind
     AND domain_row.scope_id=group_row.scope_id
    JOIN platform.cutover_group_members member
      ON member.scope_kind=group_row.scope_kind AND member.scope_id=group_row.scope_id
     AND member.group_id=group_row.group_id AND member.domain=domain_row.domain
    JOIN platform.tenants tenant ON tenant.id=v_job.tenant_id
    WHERE group_row.scope_kind='tenant' AND group_row.scope_id=v_job.tenant_id
      AND group_row.group_id=v_job.authority_group_id
      AND group_row.generation=v_job.authority_group_generation
      AND group_row.state='v2' AND group_row.writer='v2'
      AND domain_row.domain='analytics'
      AND domain_row.generation=v_job.cutover_generation
      AND domain_row.state='v2' AND domain_row.writer='v2'
      AND tenant.deleted_at IS NULL
    FOR SHARE OF group_row,domain_row,member,tenant;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance effect owner is not current';
    END IF;
    RETURN v_job.kind;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_effect_ow(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_effect_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_insert_re(platform.jobs, platform.job_attempts, uuid, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_insert_re(p_job platform.jobs, p_attempt platform.job_attempts, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_terminal_state text, p_completed_at timestamp with time zone) RETURNS TABLE(provider_code text, result_reference text, result_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_operation text;
BEGIN
    v_operation:=CASE p_job.kind WHEN 'analytics.dashboard.export.delete' THEN
        'delete' WHEN 'analytics.dashboard.export.expire' THEN 'expire' END;
    provider_code:=CASE p_job.kind WHEN 'analytics.dashboard.export.delete' THEN
        'ANALYTICS_EXPORT_DELETED' WHEN 'analytics.dashboard.export.expire' THEN
        'ANALYTICS_EXPORT_EXPIRY_COMPLETE' END;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR v_operation IS NULL OR
       p_job.state IS DISTINCT FROM 'dead' OR
       p_job.last_error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       p_attempt.job_id IS DISTINCT FROM p_job.id OR
       p_attempt.outcome IS DISTINCT FROM 'dead' OR
       p_attempt.error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       p_attempt.effect_receipt_id IS NOT NULL OR
       p_effect_receipt_id IS DISTINCT FROM
          platform.platform_async_analytics_export_maint_receipt_id_v1(
              p_attempt.effect_id,p_job.kind) OR
       pg_catalog.octet_length(p_effect_receipt_sha256) IS DISTINCT FROM 32 OR
       p_effect_receipt_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       pg_catalog.isfinite(p_completed_at) IS DISTINCT FROM true OR
       p_completed_at<=p_job.completed_at OR
       p_completed_at>pg_catalog.clock_timestamp()+interval '5 seconds' OR
       (v_operation='delete' AND p_terminal_state IS DISTINCT FROM 'deleted') OR
       (v_operation='expire' AND p_terminal_state NOT IN
           ('expired','cancelled','failed','deleted')) OR
       platform.platform_async_analytics_dashboard_export_maintenance_receipt_sha256_v1(
           p_job,p_attempt,p_effect_receipt_id,p_terminal_state,p_completed_at)
           IS DISTINCT FROM p_effect_receipt_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance receipt evidence differs';
    END IF;
    result_reference:='analytics-dashboard-export://'||v_operation||'/'||
        p_job.payload_ref||'/'||p_terminal_state;
    result_sha256:=pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(result_reference,'UTF8')),'hex');
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,writer_origin,
        request_sha256,retention_class,effect_id,effect_kind,effect_revision,effect_key,
        provider,operation,correlation_id,causation_id,effect_status,effect_code,
        provider_reference,effect_result_ref,effect_result_sha256,completed_at,retain_until
    ) VALUES (p_effect_receipt_id,'effect',p_job.tenant_id,'tenant',p_job.tenant_id,
        p_job.authority_group_id,p_job.authority_group_generation,'analytics',
        p_job.cutover_generation,'v2',p_attempt.effect_request_sha256,'external_effect',
        p_attempt.effect_id,p_job.kind,1,p_job.effect_idempotency_key,
        'analytics.dashboard-export',v_operation,p_job.id::text,p_job.id,'succeeded',
        provider_code,p_job.payload_ref,result_reference,result_sha256,p_completed_at,
        p_completed_at+interval '90 days');
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_insert_re(p_job platform.jobs, p_attempt platform.job_attempts, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_terminal_state text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_receipt_s(platform.jobs, platform.job_attempts, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_receipt_s(p_job platform.jobs, p_attempt platform.job_attempts, p_effect_receipt_id uuid, p_terminal_state text, p_completed_at timestamp with time zone) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation text;
    v_code text;
    v_result_ref text;
    v_result_sha text;
    v_canonical bytea;
BEGIN
    v_operation:=CASE p_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'delete'
        WHEN 'analytics.dashboard.export.expire' THEN 'expire' END;
    v_code:=CASE p_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'ANALYTICS_EXPORT_DELETED'
        WHEN 'analytics.dashboard.export.expire' THEN
            'ANALYTICS_EXPORT_EXPIRY_COMPLETE' END;
    v_result_ref:='analytics-dashboard-export://'||v_operation||'/'||
        p_job.payload_ref||'/'||p_terminal_state;
    v_result_sha:=pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(v_result_ref,'UTF8')),'hex');
    SELECT pg_catalog.string_agg(pg_catalog.convert_to(field.value,'UTF8'),
        pg_catalog.decode('00','hex') ORDER BY field.ordinality)
    INTO v_canonical FROM pg_catalog.unnest(ARRAY[
        'analytics-dashboard-export-maintenance-effect-receipt-v1',
        'effect-receipt.v1',p_effect_receipt_id::text,p_attempt.effect_id::text,
        p_job.kind,'1',p_job.tenant_id::text,'tenant',p_job.scope_id::text,
        p_job.authority_group_id,p_job.authority_group_generation::text,
        'analytics',p_job.cutover_generation::text,'v2',
        'analytics.dashboard-export',v_operation,p_job.effect_idempotency_key,
        p_job.id::text,p_job.id::text,'succeeded',v_code,p_job.payload_ref,
        v_result_ref,v_result_sha,p_attempt.effect_request_sha256,
        (EXTRACT(EPOCH FROM p_completed_at)*1000000)::bigint::text
    ]) WITH ORDINALITY AS field(value,ordinality);
    RETURN pg_catalog.sha256(v_canonical);
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_receipt_s(p_job platform.jobs, p_attempt platform.job_attempts, p_effect_receipt_id uuid, p_terminal_state text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_unknown_c(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_c() RETURNS TABLE(kind text, tenant_id uuid, tenant_schema name, export_id uuid, authority_group_id text, authority_group_generation bigint, cutover_generation bigint, job_id uuid, attempt_id uuid, attempt_number integer, lease_generation bigint, original_lease_owner_id uuid, effect_id uuid, effect_request_sha256 bytea, unknown_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance candidate authority is invalid';
    END IF;
    RETURN QUERY
    SELECT job.kind,job.tenant_id,tenant.schema_name::name,job.payload_ref::uuid,
        job.authority_group_id,job.authority_group_generation,
        job.cutover_generation,job.id,attempt.attempt_id,attempt.attempt,
        attempt.lease_generation,attempt.lease_owner_id,attempt.effect_id,
        pg_catalog.decode(attempt.effect_request_sha256,'hex'),job.completed_at
    FROM platform.jobs AS job
    JOIN platform.job_attempts AS attempt
      ON attempt.job_id=job.id AND attempt.scope_kind='tenant'
     AND attempt.scope_id=job.tenant_id AND attempt.attempt=job.attempts
     AND attempt.lease_generation=job.lease_generation
    JOIN platform.tenants AS tenant ON tenant.id=job.tenant_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind=job.scope_kind AND group_row.scope_id=job.scope_id
     AND group_row.group_id=job.authority_group_id
     AND group_row.state='v2' AND group_row.writer='v2'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=job.scope_kind AND domain_row.scope_id=job.scope_id
     AND domain_row.domain=job.authority_domain
     AND domain_row.state='v2' AND domain_row.writer='v2'
    JOIN platform.cutover_group_members AS member
      ON member.scope_kind=job.scope_kind AND member.scope_id=job.scope_id
     AND member.group_id=job.authority_group_id
     AND member.domain=job.authority_domain
    WHERE job.scope_kind='tenant' AND job.scope_id=job.tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind IN ('analytics.dashboard.export.delete',
                       'analytics.dashboard.export.expire')
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=CASE job.kind
          WHEN 'analytics.dashboard.export.delete' THEN 3 ELSE 8 END
      AND pg_catalog.pg_input_is_valid(job.payload_ref,'uuid')
      AND job.payload_ref=(job.payload_ref::uuid)::text
      AND pg_catalog.uuid_extract_version(job.payload_ref::uuid)=7
      AND job.payload_sha256=pg_catalog.encode(pg_catalog.sha256(
          pg_catalog.convert_to(job.payload_ref,'UTF8')),'hex')
      AND job.dedupe_key=job.kind||':'||job.payload_ref
      AND job.effect_idempotency_key=job.dedupe_key
      AND job.state='dead' AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN'
      AND job.last_error_sha256 IS NULL AND job.completed_at IS NOT NULL
      AND job.updated_at=job.completed_at
      AND job.retain_until=job.completed_at+interval '365 days'
      AND job.lease_owner_id IS NULL AND job.lease_heartbeat_at IS NULL
      AND job.lease_until IS NULL
      AND attempt.attempt BETWEEN 1 AND job.max_attempts
      AND attempt.outcome='dead' AND attempt.error_class IS NULL
      AND attempt.error_code='JOB_OUTCOME_UNKNOWN'
      AND attempt.redacted_error_sha256 IS NULL
      AND attempt.finished_at=job.completed_at
      AND attempt.effect_started_at IS NOT NULL
      AND pg_catalog.uuid_extract_version(attempt.attempt_id)=7
      AND pg_catalog.uuid_extract_version(attempt.lease_owner_id)=7
      AND pg_catalog.uuid_extract_version(attempt.effect_id)=5
      AND attempt.effect_request_sha256~'^[0-9a-f]{64}$'
      AND attempt.effect_request_sha256<>pg_catalog.repeat('0',64)
      AND attempt.effect_receipt_id IS NULL AND tenant.deleted_at IS NULL
      AND tenant.schema_name::text~'^[a-z][a-z0-9_]{0,62}$'
      AND NOT EXISTS (
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.record_kind='effect' AND receipt.scope_kind=job.scope_kind
          AND receipt.scope_id=job.scope_id
          AND receipt.authority_group_id=job.authority_group_id
          AND receipt.authority_group_generation=job.authority_group_generation
          AND receipt.authority_domain=job.authority_domain
          AND receipt.cutover_generation=job.cutover_generation
          AND receipt.effect_key=job.effect_idempotency_key
          AND receipt.effect_id=attempt.effect_id
          AND receipt.request_sha256=attempt.effect_request_sha256
      )
      AND NOT EXISTS (
        SELECT 1
        FROM platform.analytics_dashboard_export_maintenance_unknown_resolutions resolution
        WHERE resolution.job_id=job.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM platform.analytics_dashboard_export_maintenance_unknown_claims claim
        WHERE claim.job_id=job.id AND (
            claim.lease_until>pg_catalog.clock_timestamp() OR
            claim.run_at>pg_catalog.clock_timestamp())
      )
    ORDER BY job.completed_at,job.id LIMIT 1;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_c() OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_unknown_c(text, uuid, name, uuid, text, bigint, bigint, uuid, uuid, integer, bigint, uuid, uuid, bytea, timestamp with time zone, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_c(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(claim_state text, cleanup_generation bigint, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_claim platform.analytics_dashboard_export_maintenance_unknown_claims%ROWTYPE;
    v_resolution platform.analytics_dashboard_export_maintenance_unknown_resolutions%ROWTYPE;
    v_schema name;
    v_request text;
    v_claimed_at timestamptz;
    v_max integer;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance claim authority is invalid';
    END IF;
    v_max:=CASE p_kind
        WHEN 'analytics.dashboard.export.delete' THEN 3
        WHEN 'analytics.dashboard.export.expire' THEN 8 END;
    IF v_max IS NULL OR p_tenant_id IS NULL OR
       p_tenant_schema::text!~'^[a-z][a-z0-9_]{0,62}$' OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_authority_group_id!~'^[a-z][a-z0-9_]{0,62}$' OR
       p_authority_group_generation<1 OR p_cutover_generation<1 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_number NOT BETWEEN 1 AND v_max OR p_lease_generation<1 OR
       pg_catalog.uuid_extract_version(p_original_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 5 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       NOT pg_catalog.isfinite(p_unknown_at) OR p_unknown_at>p_observed_at OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export maintenance claim input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id=p_authority_group_id
      AND job.authority_group_generation=p_authority_group_generation
      AND job.authority_domain='analytics'
      AND job.cutover_generation=p_cutover_generation AND job.writer_origin='v2'
      AND job.kind=p_kind AND job.payload_revision=1
      AND job.effect_class='external' AND job.max_attempts=v_max
      AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(pg_catalog.sha256(
          pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key=p_kind||':'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    IF v_job.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance job evidence differs';
    END IF;
    SELECT tenant.schema_name INTO v_schema FROM platform.tenants AS tenant
    WHERE tenant.id=p_tenant_id AND tenant.deleted_at IS NULL FOR SHARE;
    IF v_schema IS DISTINCT FROM p_tenant_schema THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export maintenance tenant schema changed';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
       AND attempt.attempt=p_attempt_number
       AND attempt.lease_generation=p_lease_generation
       AND attempt.lease_owner_id=p_original_lease_owner_id FOR SHARE;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    SELECT resolution.* INTO v_resolution
    FROM platform.analytics_dashboard_export_maintenance_unknown_resolutions resolution
    WHERE resolution.job_id=p_job_id FOR SHARE;
    IF FOUND THEN
        IF v_resolution.kind<>p_kind OR v_resolution.tenant_id<>p_tenant_id OR
           v_resolution.tenant_schema<>p_tenant_schema OR
           v_resolution.export_id<>p_export_id OR
           v_resolution.authority_group_id<>p_authority_group_id OR
           v_resolution.authority_group_generation<>p_authority_group_generation OR
           v_resolution.cutover_generation<>p_cutover_generation OR
           v_resolution.attempt_id<>p_attempt_id OR
           v_resolution.attempt_number<>p_attempt_number OR
           v_resolution.lease_generation<>p_lease_generation OR
           v_resolution.original_lease_owner_id<>p_original_lease_owner_id OR
           v_resolution.effect_id<>p_effect_id OR
           v_resolution.request_sha256<>v_request OR
           v_resolution.original_unknown_at<>p_unknown_at OR
           v_job.state<>'succeeded' OR v_attempt.outcome<>'succeeded' OR
           v_attempt.effect_receipt_id<>v_resolution.effect_receipt_id THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export maintenance resolution differs';
        END IF;
        claim_state:='resolved'; RETURN NEXT; RETURN;
    END IF;
    IF NOT COALESCE((v_job.state='dead' AND
       v_job.last_error_class IS NULL AND
       v_job.last_error_code='JOB_OUTCOME_UNKNOWN' AND
       v_job.last_error_sha256 IS NULL AND v_job.completed_at=p_unknown_at AND
       v_job.updated_at=v_job.completed_at AND
       v_job.retain_until=v_job.completed_at+interval '365 days' AND
       v_job.lease_owner_id IS NULL AND v_job.lease_heartbeat_at IS NULL AND
       v_job.lease_until IS NULL AND v_job.attempts=p_attempt_number AND
       v_job.lease_generation=p_lease_generation AND
       v_attempt.finished_at=v_job.completed_at AND
       v_attempt.outcome='dead' AND v_attempt.error_class IS NULL AND
       v_attempt.error_code='JOB_OUTCOME_UNKNOWN' AND
       v_attempt.redacted_error_sha256 IS NULL AND
       v_attempt.effect_started_at IS NOT NULL AND
       v_attempt.effect_id=p_effect_id AND
       v_attempt.effect_request_sha256=v_request AND
       v_attempt.effect_receipt_id IS NULL),false) OR EXISTS (
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.record_kind='effect' AND receipt.scope_kind=v_job.scope_kind
          AND receipt.scope_id=v_job.scope_id
          AND receipt.authority_group_id=v_job.authority_group_id
          AND receipt.authority_group_generation=v_job.authority_group_generation
          AND receipt.authority_domain=v_job.authority_domain
          AND receipt.cutover_generation=v_job.cutover_generation
          AND receipt.effect_key=v_job.effect_idempotency_key
          AND receipt.effect_id=p_effect_id AND receipt.request_sha256=v_request
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown evidence differs';
    END IF;
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_maintenance_unknown_claims AS claim
    WHERE claim.job_id=p_job_id FOR UPDATE;
    IF FOUND AND (v_claim.kind<>p_kind OR v_claim.tenant_id<>p_tenant_id OR
       v_claim.tenant_schema<>p_tenant_schema OR v_claim.export_id<>p_export_id OR
       v_claim.authority_group_id<>p_authority_group_id OR
       v_claim.authority_group_generation<>p_authority_group_generation OR
       v_claim.cutover_generation<>p_cutover_generation OR
       v_claim.attempt_id<>p_attempt_id OR
       v_claim.attempt_number<>p_attempt_number OR
       v_claim.lease_generation<>p_lease_generation OR
       v_claim.original_lease_owner_id<>p_original_lease_owner_id OR
       v_claim.effect_id<>p_effect_id OR v_claim.request_sha256<>v_request OR
       v_claim.unknown_at<>p_unknown_at) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance claim replay differs';
    END IF;
    IF FOUND AND v_claim.lease_until>pg_catalog.clock_timestamp() THEN
        IF v_claim.cleanup_lease_owner_id=p_cleanup_lease_owner_id THEN
            claim_state:='claimed'; cleanup_generation:=v_claim.claim_generation;
            lease_until:=v_claim.lease_until; RETURN NEXT; RETURN;
        END IF;
        claim_state:='busy'; RETURN NEXT; RETURN;
    END IF;
    IF FOUND AND v_claim.run_at>pg_catalog.clock_timestamp() THEN
        claim_state:='busy'; RETURN NEXT; RETURN;
    END IF;
    v_claimed_at:=GREATEST(pg_catalog.clock_timestamp(),p_observed_at,
        COALESCE(v_claim.updated_at,p_observed_at)+interval '1 microsecond');
    IF FOUND THEN
        UPDATE platform.analytics_dashboard_export_maintenance_unknown_claims
        SET claim_generation=claim_generation+1,
            cleanup_lease_owner_id=p_cleanup_lease_owner_id,
            lease_heartbeat_at=v_claimed_at,
            lease_until=v_claimed_at+interval '60 seconds',updated_at=v_claimed_at
        WHERE job_id=p_job_id RETURNING claim_generation INTO cleanup_generation;
    ELSE
        cleanup_generation:=1;
        INSERT INTO platform.analytics_dashboard_export_maintenance_unknown_claims(
            job_id,kind,tenant_id,tenant_schema,export_id,authority_group_id,
            authority_group_generation,cutover_generation,attempt_id,attempt_number,
            lease_generation,original_lease_owner_id,effect_id,request_sha256,
            unknown_at,claim_generation,cleanup_lease_owner_id,lease_heartbeat_at,
            lease_until,run_at,created_at,updated_at
        ) VALUES (p_job_id,p_kind,p_tenant_id,p_tenant_schema,p_export_id,
            v_job.authority_group_id,v_job.authority_group_generation,
            v_job.cutover_generation,p_attempt_id,p_attempt_number,p_lease_generation,
            p_original_lease_owner_id,p_effect_id,v_request,v_job.completed_at,1,
            p_cleanup_lease_owner_id,v_claimed_at,v_claimed_at+interval '60 seconds',
            v_claimed_at,v_claimed_at,v_claimed_at);
    END IF;
    claim_state:='claimed'; lease_until:=v_claimed_at+interval '60 seconds';
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_c(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_unknown_c(text, uuid, name, uuid, text, bigint, bigint, uuid, uuid, integer, bigint, uuid, uuid, bytea, timestamp with time zone, bigint, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_c(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_claim platform.analytics_dashboard_export_maintenance_unknown_claims%ROWTYPE;
    v_schema name;
    v_request text;
    v_checkpoint_at timestamptz;
    v_max integer;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance checkpoint authority is invalid';
    END IF;
    v_max:=CASE p_kind
        WHEN 'analytics.dashboard.export.delete' THEN 3
        WHEN 'analytics.dashboard.export.expire' THEN 8 END;
    IF v_max IS NULL OR p_tenant_id IS NULL OR
       p_tenant_schema::text!~'^[a-z][a-z0-9_]{0,62}$' OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_authority_group_id!~'^[a-z][a-z0-9_]{0,62}$' OR
       p_authority_group_generation<1 OR p_cutover_generation<1 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_number NOT BETWEEN 1 AND v_max OR p_lease_generation<1 OR
       pg_catalog.uuid_extract_version(p_original_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 5 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       NOT pg_catalog.isfinite(p_unknown_at) OR p_unknown_at>p_observed_at OR
       p_cleanup_generation<1 OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export maintenance checkpoint input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id=p_authority_group_id
      AND job.authority_group_generation=p_authority_group_generation
      AND job.authority_domain='analytics'
      AND job.cutover_generation=p_cutover_generation AND job.writer_origin='v2'
      AND job.kind=p_kind AND job.payload_revision=1
      AND job.effect_class='external' AND job.max_attempts=v_max
      AND job.payload_ref=p_export_id::text AND job.state='dead'
      AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN'
      AND job.completed_at=p_unknown_at FOR SHARE;
    IF v_job.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance checkpoint evidence differs';
    END IF;
    SELECT tenant.schema_name INTO v_schema FROM platform.tenants AS tenant
    WHERE tenant.id=p_tenant_id AND tenant.deleted_at IS NULL FOR SHARE;
    IF v_schema IS DISTINCT FROM p_tenant_schema THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export maintenance tenant schema changed';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_maintenance_unknown_claims AS claim
    WHERE claim.job_id=p_job_id AND claim.kind=p_kind
      AND claim.tenant_id=p_tenant_id AND claim.tenant_schema=p_tenant_schema
      AND claim.export_id=p_export_id AND claim.attempt_id=p_attempt_id
      AND claim.authority_group_id=p_authority_group_id
      AND claim.authority_group_generation=p_authority_group_generation
      AND claim.cutover_generation=p_cutover_generation
      AND claim.attempt_number=p_attempt_number
      AND claim.lease_generation=p_lease_generation
      AND claim.original_lease_owner_id=p_original_lease_owner_id
      AND claim.effect_id=p_effect_id AND claim.request_sha256=v_request
      AND claim.unknown_at=p_unknown_at FOR UPDATE;
    IF v_claim.job_id IS NULL OR
       v_claim.claim_generation<>p_cleanup_generation OR
       v_claim.cleanup_lease_owner_id<>p_cleanup_lease_owner_id OR
       v_claim.lease_until<=pg_catalog.clock_timestamp() OR EXISTS (
        SELECT 1
        FROM platform.analytics_dashboard_export_maintenance_unknown_resolutions resolution
        WHERE resolution.job_id=p_job_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export maintenance checkpoint lease is stale';
    END IF;
    v_checkpoint_at:=GREATEST(pg_catalog.clock_timestamp(),p_observed_at,
        v_claim.updated_at+interval '1 microsecond');
    UPDATE platform.analytics_dashboard_export_maintenance_unknown_claims
    SET lease_heartbeat_at=v_checkpoint_at,
        lease_until=v_checkpoint_at+interval '60 seconds',updated_at=v_checkpoint_at
    WHERE job_id=p_job_id;
    RETURN v_checkpoint_at+interval '60 seconds';
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_c(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_unknown_d(text, uuid, name, uuid, text, bigint, bigint, uuid, uuid, integer, bigint, uuid, uuid, bytea, timestamp with time zone, bigint, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_d(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_claim platform.analytics_dashboard_export_maintenance_unknown_claims%ROWTYPE;
    v_schema name;
    v_request text;
    v_deferred_at timestamptz;
    v_retry_at timestamptz;
    v_max integer;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance defer authority is invalid';
    END IF;
    v_max:=CASE p_kind
        WHEN 'analytics.dashboard.export.delete' THEN 3
        WHEN 'analytics.dashboard.export.expire' THEN 8 END;
    IF v_max IS NULL OR p_tenant_id IS NULL OR
       p_tenant_schema::text!~'^[a-z][a-z0-9_]{0,62}$' OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_authority_group_id!~'^[a-z][a-z0-9_]{0,62}$' OR
       p_authority_group_generation<1 OR p_cutover_generation<1 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_number NOT BETWEEN 1 AND v_max OR p_lease_generation<1 OR
       pg_catalog.uuid_extract_version(p_original_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 5 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       NOT pg_catalog.isfinite(p_unknown_at) OR p_unknown_at>p_observed_at OR
       p_cleanup_generation<1 OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export maintenance defer input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id=p_authority_group_id
      AND job.authority_group_generation=p_authority_group_generation
      AND job.authority_domain='analytics'
      AND job.cutover_generation=p_cutover_generation AND job.writer_origin='v2'
      AND job.kind=p_kind AND job.payload_revision=1
      AND job.effect_class='external' AND job.max_attempts=v_max
      AND job.payload_ref=p_export_id::text AND job.state='dead'
      AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN'
      AND job.completed_at=p_unknown_at FOR SHARE;
    IF v_job.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance defer evidence differs';
    END IF;
    SELECT tenant.schema_name INTO v_schema FROM platform.tenants AS tenant
    WHERE tenant.id=p_tenant_id AND tenant.deleted_at IS NULL FOR SHARE;
    IF v_schema IS DISTINCT FROM p_tenant_schema THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export maintenance tenant schema changed';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_maintenance_unknown_claims AS claim
    WHERE claim.job_id=p_job_id AND claim.kind=p_kind
      AND claim.tenant_id=p_tenant_id AND claim.tenant_schema=p_tenant_schema
      AND claim.export_id=p_export_id AND claim.attempt_id=p_attempt_id
      AND claim.authority_group_id=p_authority_group_id
      AND claim.authority_group_generation=p_authority_group_generation
      AND claim.cutover_generation=p_cutover_generation
      AND claim.attempt_number=p_attempt_number
      AND claim.lease_generation=p_lease_generation
      AND claim.original_lease_owner_id=p_original_lease_owner_id
      AND claim.effect_id=p_effect_id AND claim.request_sha256=v_request
      AND claim.unknown_at=p_unknown_at FOR UPDATE;
    IF v_claim.job_id IS NULL OR
       v_claim.claim_generation<>p_cleanup_generation OR
       v_claim.cleanup_lease_owner_id<>p_cleanup_lease_owner_id OR EXISTS (
        SELECT 1
        FROM platform.analytics_dashboard_export_maintenance_unknown_resolutions resolution
        WHERE resolution.job_id=p_job_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export maintenance defer lease is stale';
    END IF;
    IF v_claim.lease_until<=pg_catalog.clock_timestamp() AND
       v_claim.run_at>pg_catalog.clock_timestamp() THEN
        RETURN v_claim.run_at;
    END IF;
    IF v_claim.lease_until<=pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export maintenance defer lease expired';
    END IF;
    v_deferred_at:=GREATEST(pg_catalog.clock_timestamp(),p_observed_at,
        v_claim.updated_at+interval '1 microsecond');
    v_retry_at:=v_deferred_at+LEAST(
        interval '30 seconds'*pg_catalog.power(2::double precision,
            LEAST((p_cleanup_generation-1)::double precision,5::double precision)),
        interval '15 minutes');
    UPDATE platform.analytics_dashboard_export_maintenance_unknown_claims
    SET lease_until=v_deferred_at,run_at=v_retry_at,updated_at=v_deferred_at
    WHERE job_id=p_job_id;
    RETURN v_retry_at;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_d(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_maintenance_unknown_r(text, uuid, name, uuid, text, bigint, bigint, uuid, uuid, integer, bigint, uuid, uuid, bytea, timestamp with time zone, bigint, uuid, uuid, uuid, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_r(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_resolution_receipt_id uuid, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_terminal_state text, p_resolution_sha256 bytea, p_resolved_at timestamp with time zone) RETURNS TABLE(replayed boolean, effect_receipt_id uuid, job_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_claim platform.analytics_dashboard_export_maintenance_unknown_claims%ROWTYPE;
    v_resolution platform.analytics_dashboard_export_maintenance_unknown_resolutions%ROWTYPE;
    v_schema name;
    v_request text;
    v_receipt_digest text;
    v_resolution_digest text;
    v_code text;
    v_result_ref text;
    v_result_sha text;
    v_max integer;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance resolution authority is invalid';
    END IF;
    v_max:=CASE p_kind WHEN 'analytics.dashboard.export.delete' THEN 3
        WHEN 'analytics.dashboard.export.expire' THEN 8 END;
    IF v_max IS NULL OR p_tenant_id IS NULL OR
       (p_tenant_schema::text~'^[a-z][a-z0-9_]{0,62}$') IS DISTINCT FROM true OR
       (p_authority_group_id~'^[a-z][a-z0-9_]{0,62}$') IS DISTINCT FROM true OR
       COALESCE(p_authority_group_generation<1,true) OR
       COALESCE(p_cutover_generation<1,true) OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_number NOT BETWEEN 1 AND v_max OR COALESCE(p_lease_generation<1,true) OR
       pg_catalog.uuid_extract_version(p_original_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 5 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       pg_catalog.isfinite(p_unknown_at) IS DISTINCT FROM true OR
       COALESCE(p_cleanup_generation<1,true) OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_resolution_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_receipt_id) IS DISTINCT FROM 5 OR
       p_effect_receipt_id=p_effect_id OR
       pg_catalog.octet_length(p_effect_receipt_sha256) IS DISTINCT FROM 32 OR
       p_effect_receipt_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       pg_catalog.octet_length(p_resolution_sha256) IS DISTINCT FROM 32 OR
       p_resolution_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       pg_catalog.isfinite(p_resolved_at) IS DISTINCT FROM true OR
       p_unknown_at>=p_resolved_at OR
       p_resolved_at>pg_catalog.clock_timestamp()+interval '5 seconds' OR
       (CASE p_kind WHEN 'analytics.dashboard.export.delete' THEN
            p_terminal_state='deleted' ELSE p_terminal_state IN
            ('expired','cancelled','failed','deleted') END) IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export maintenance resolution input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    v_receipt_digest:=pg_catalog.encode(p_effect_receipt_sha256,'hex');
    v_resolution_digest:=pg_catalog.encode(p_resolution_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id AND job.scope_kind='tenant'
      AND job.scope_id=p_tenant_id AND job.authority_group_id=p_authority_group_id
      AND job.authority_group_generation=p_authority_group_generation
      AND job.authority_domain='analytics' AND job.cutover_generation=p_cutover_generation
      AND job.writer_origin='v2' AND job.kind=p_kind AND job.payload_revision=1
      AND job.effect_class='external' AND job.max_attempts=v_max
      AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(pg_catalog.sha256(
          pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key=p_kind||':'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    IF v_job.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution job differs';
    END IF;
    SELECT tenant.schema_name INTO v_schema FROM platform.tenants tenant
    WHERE tenant.id=p_tenant_id AND tenant.deleted_at IS NULL FOR SHARE;
    IF v_schema IS DISTINCT FROM p_tenant_schema THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export maintenance tenant schema changed';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,v_job.authority_domain);
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_number AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_original_lease_owner_id FOR SHARE;
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_maintenance_unknown_claims claim
    WHERE claim.job_id=p_job_id AND claim.kind=p_kind AND claim.tenant_id=p_tenant_id
      AND claim.tenant_schema=p_tenant_schema AND claim.export_id=p_export_id
      AND claim.authority_group_id=p_authority_group_id
      AND claim.authority_group_generation=p_authority_group_generation
      AND claim.cutover_generation=p_cutover_generation AND claim.attempt_id=p_attempt_id
      AND claim.attempt_number=p_attempt_number AND claim.lease_generation=p_lease_generation
      AND claim.original_lease_owner_id=p_original_lease_owner_id
      AND claim.effect_id=p_effect_id AND claim.request_sha256=v_request
      AND claim.unknown_at=p_unknown_at AND claim.claim_generation=p_cleanup_generation
      AND claim.cleanup_lease_owner_id=p_cleanup_lease_owner_id FOR UPDATE;
    SELECT resolution.* INTO v_resolution
    FROM platform.analytics_dashboard_export_maintenance_unknown_resolutions resolution
    WHERE resolution.job_id=p_job_id FOR SHARE;
    IF FOUND THEN
        PERFORM platform.platform_async_analytics_dashboard_export_maintenance_assert_replay_v1(
            v_job,v_attempt,v_claim,v_resolution,p_effect_receipt_id,
            p_effect_receipt_sha256,p_resolution_receipt_id,p_resolution_sha256,
            p_terminal_state,p_resolved_at);
        replayed:=true; effect_receipt_id:=p_effect_receipt_id;
        job_state:='succeeded'; RETURN NEXT; RETURN;
    END IF;
    IF v_claim.job_id IS NULL OR v_attempt.attempt_id IS NULL OR
       v_claim.lease_until<=pg_catalog.clock_timestamp() OR v_job.state<>'dead' OR
       v_job.last_error_class IS NOT NULL OR
       v_job.last_error_code<>'JOB_OUTCOME_UNKNOWN' OR
       v_job.last_error_sha256 IS NOT NULL OR v_job.completed_at<>p_unknown_at OR
       v_job.completed_at<>v_attempt.finished_at OR v_attempt.outcome<>'dead' OR
       v_attempt.error_class IS NOT NULL OR
       v_attempt.error_code<>'JOB_OUTCOME_UNKNOWN' OR
       v_attempt.redacted_error_sha256 IS NOT NULL OR v_attempt.effect_id<>p_effect_id OR
       v_attempt.effect_request_sha256<>v_request OR v_attempt.effect_started_at IS NULL OR
       v_attempt.effect_receipt_id IS NOT NULL OR EXISTS (
           SELECT 1 FROM platform.idempotency_receipts receipt
           WHERE receipt.receipt_id=p_effect_receipt_id OR
             (receipt.record_kind='effect' AND receipt.effect_id=p_effect_id AND
              receipt.effect_key=v_job.effect_idempotency_key)) OR
       platform.platform_async_analytics_dashboard_export_maintenance_receipt_sha256_v1(
           v_job,v_attempt,p_effect_receipt_id,p_terminal_state,p_resolved_at)
           <>p_effect_receipt_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution evidence differs';
    END IF;
    SELECT inserted.provider_code,inserted.result_reference,inserted.result_sha256
    INTO v_code,v_result_ref,v_result_sha
    FROM platform.platform_async_analytics_dashboard_export_maintenance_insert_receipt_v1(
        v_job,v_attempt,p_effect_receipt_id,p_effect_receipt_sha256,
        p_terminal_state,p_resolved_at) inserted;
    INSERT INTO platform.analytics_dashboard_export_maintenance_unknown_resolutions(
        resolution_receipt_id,effect_receipt_id,effect_receipt_sha256,resolution_sha256,
        kind,tenant_id,tenant_schema,export_id,authority_group_id,
        authority_group_generation,cutover_generation,job_id,attempt_id,attempt_number,
        lease_generation,original_lease_owner_id,effect_id,request_sha256,
        original_unknown_at,original_attempt_finished_at,original_attempt_outcome,
        original_error_class,original_error_code,original_error_sha256,
        cleanup_generation,cleanup_lease_owner_id,terminal_state,provider_code,
        provider_reference,result_reference,result_sha256,resolved_at
    ) VALUES (p_resolution_receipt_id,p_effect_receipt_id,v_receipt_digest,
        v_resolution_digest,p_kind,p_tenant_id,p_tenant_schema,p_export_id,
        v_job.authority_group_id,v_job.authority_group_generation,
        v_job.cutover_generation,p_job_id,p_attempt_id,p_attempt_number,
        p_lease_generation,p_original_lease_owner_id,p_effect_id,v_request,
        v_job.completed_at,v_attempt.finished_at,v_attempt.outcome,
        v_attempt.error_class,v_attempt.error_code,v_attempt.redacted_error_sha256,
        p_cleanup_generation,p_cleanup_lease_owner_id,p_terminal_state,v_code,
        p_export_id::text,v_result_ref,v_result_sha,p_resolved_at);
    UPDATE platform.job_attempts SET finished_at=p_resolved_at,outcome='succeeded',
        error_code=NULL,effect_receipt_id=p_effect_receipt_id
    WHERE attempt_id=p_attempt_id AND outcome='dead'
      AND error_code='JOB_OUTCOME_UNKNOWN'
      AND platform.job_attempts.effect_receipt_id IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P6048',
        MESSAGE='Analytics dashboard export maintenance attempt changed'; END IF;
    UPDATE platform.jobs SET state='succeeded',last_error_code=NULL,
        completed_at=p_resolved_at,updated_at=p_resolved_at,
        retain_until=p_resolved_at+interval '90 days'
    WHERE id=p_job_id AND state='dead' AND last_error_code='JOB_OUTCOME_UNKNOWN'
      AND completed_at=p_unknown_at;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P6048',
        MESSAGE='Analytics dashboard export maintenance job changed'; END IF;
    replayed:=false; effect_receipt_id:=p_effect_receipt_id; job_state:='succeeded';
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_maintenance_unknown_r(p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_resolution_receipt_id uuid, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_terminal_state text, p_resolution_sha256 bytea, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_spool_state_v1(uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_spool_state_v1(p_tenant_id uuid, p_export_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export spool state authority is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.tenant_id=p_tenant_id AND job.scope_kind='tenant'
      AND job.scope_id=p_tenant_id AND job.authority_domain='analytics'
      AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key;
    IF NOT FOUND OR v_job.attempts<>p_attempt_generation OR
       v_job.lease_generation<>p_attempt_generation THEN
        RETURN 'inactive';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=v_job.id AND attempt.scope_kind='tenant'
      AND attempt.scope_id=p_tenant_id AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id;
    IF NOT FOUND THEN RETURN 'inactive'; END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.analytics_dashboard_export_unknown_resolutions AS resolution
        WHERE resolution.tenant_id=p_tenant_id
          AND resolution.export_id=p_export_id AND resolution.job_id=v_job.id
          AND resolution.attempt_id=v_attempt.attempt_id
          AND resolution.attempt_generation=p_attempt_generation
          AND resolution.lease_owner_id=p_lease_owner_id
          AND resolution.effect_id=v_attempt.effect_id
          AND resolution.request_sha256=v_attempt.effect_request_sha256
    ) THEN
        RETURN 'inactive';
    END IF;
    IF v_job.state='running' AND v_attempt.finished_at IS NULL AND
       v_job.lease_owner_id=p_lease_owner_id AND
       v_job.lease_until>pg_catalog.clock_timestamp() THEN
        RETURN 'running';
    END IF;
    IF v_job.state='dead' AND v_job.last_error_class IS NULL AND
       v_job.last_error_code='JOB_OUTCOME_UNKNOWN' AND
       v_attempt.outcome='dead' AND v_attempt.error_class IS NULL AND
       v_attempt.error_code='JOB_OUTCOME_UNKNOWN' AND
       v_attempt.effect_started_at IS NOT NULL AND
       v_attempt.effect_receipt_id IS NULL THEN
        RETURN 'outcome_unknown';
    END IF;
    RETURN 'inactive';
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_spool_state_v1(p_tenant_id uuid, p_export_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_spool_tenant_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_spool_tenant_v1(p_export_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_tenant_id uuid;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export spool tenant authority is invalid';
    END IF;
    SELECT job.tenant_id INTO v_tenant_id FROM platform.jobs AS job
    WHERE job.scope_kind='tenant' AND job.scope_id=job.tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key
    ORDER BY job.tenant_id LIMIT 1;
    IF EXISTS (
        SELECT 1 FROM platform.jobs AS other
        WHERE other.scope_kind='tenant' AND other.scope_id=other.tenant_id
          AND other.authority_domain='analytics' AND other.writer_origin='v2'
          AND other.kind='analytics.dashboard.export.render'
          AND other.payload_revision=1 AND other.effect_class='external'
          AND other.max_attempts=3 AND other.payload_ref=p_export_id::text
          AND other.tenant_id IS DISTINCT FROM v_tenant_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export spool tenant is ambiguous';
    END IF;
    RETURN v_tenant_id;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_spool_tenant_v1(p_export_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_succeed_v1(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, uuid, bytea, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_succeed_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_effect_receipt_id uuid, p_effect_result_sha256 bytea, p_provider_reference text, p_ciphertext_bytes bigint, p_completed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_receipt_id uuid;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export success authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_effect_request_sha256) IS DISTINCT FROM 32 OR
       p_effect_request_sha256=
           pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       pg_catalog.uuid_extract_version(p_effect_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_effect_result_sha256) IS DISTINCT FROM 32 OR
       p_effect_result_sha256=
           pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       pg_catalog.octet_length(p_provider_reference) NOT BETWEEN 1 AND 512 OR
       p_ciphertext_bytes NOT BETWEEN 1 AND 2147483648 OR
       NOT pg_catalog.isfinite(p_completed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export success input is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_attempt.finished_at IS NOT NULL THEN
        IF NOT COALESCE((v_job.state='succeeded' AND
           v_job.completed_at=p_completed_at AND v_job.updated_at=p_completed_at AND
           v_job.lease_owner_id IS NULL AND v_job.lease_heartbeat_at IS NULL AND
           v_job.lease_until IS NULL AND v_job.last_error_class IS NULL AND
           v_job.last_error_code IS NULL AND v_job.last_error_sha256 IS NULL AND
           v_job.retain_until=p_completed_at+interval '91 days' AND
           v_attempt.outcome='succeeded' AND v_attempt.error_class IS NULL AND
           v_attempt.error_code IS NULL AND
           v_attempt.redacted_error_sha256 IS NULL AND
           v_attempt.effect_started_at IS NOT NULL AND
           v_job.effect_started_at=v_attempt.effect_started_at AND
           v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=
               pg_catalog.encode(p_effect_request_sha256,'hex') AND
           v_attempt.effect_receipt_id=p_effect_receipt_id AND
           v_attempt.finished_at=p_completed_at),false) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export success replay differs';
        END IF;
        PERFORM platform.platform_async_analytics_dashboard_export_effect_receipt_v1(
            p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_effect_receipt_id,
            'succeeded',NULL,'OBJECT_UPLOAD_SUCCEEDED',p_provider_reference,
            p_effect_result_sha256,p_completed_at);
        RETURN true;
    END IF;
    IF v_job.state IS DISTINCT FROM 'running' OR v_attempt.attempt_id IS NULL OR
       v_job.cancel_requested_at IS NOT NULL OR
       v_job.attempts IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_generation IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_until<=pg_catalog.clock_timestamp() OR
       v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM
           pg_catalog.encode(p_effect_request_sha256,'hex') OR
       v_attempt.effect_started_at IS NULL OR
       v_job.effect_started_at IS DISTINCT FROM v_attempt.effect_started_at OR
       p_completed_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export success lease is stale';
    END IF;
    v_receipt_id:=platform.platform_async_analytics_dashboard_export_effect_receipt_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_effect_receipt_id,
        'succeeded',NULL,'OBJECT_UPLOAD_SUCCEEDED',p_provider_reference,
        p_effect_result_sha256,p_completed_at);
    UPDATE platform.job_attempts SET finished_at=p_completed_at,
        outcome='succeeded',effect_receipt_id=v_receipt_id
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='succeeded',lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=NULL,
        last_error_code=NULL,last_error_sha256=NULL,
        retain_until=p_completed_at+interval '91 days',updated_at=p_completed_at,
        completed_at=p_completed_at WHERE id=p_job_id;
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
        used_ciphertext_bytes=used_ciphertext_bytes+p_ciphertext_bytes,
        revision=revision+1,updated_at=GREATEST(
            updated_at+interval '1 microsecond',p_completed_at)
    WHERE tenant_id=p_tenant_id AND reserved_ciphertext_bytes>=2147483648
      AND used_ciphertext_bytes+p_ciphertext_bytes<=21474836480;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6049',
            MESSAGE='Analytics dashboard export success quota is inconsistent';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_succeed_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_effect_receipt_id uuid, p_effect_result_sha256 bytea, p_provider_reference text, p_ciphertext_bytes bigint, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_candidate_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_candidate_v1() RETURNS TABLE(tenant_id uuid, tenant_schema name, export_id uuid, job_id uuid, attempt_id uuid, attempt_generation bigint, lease_owner_id uuid, effect_id uuid, effect_request_sha256 bytea, unknown_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown candidate authority is invalid';
    END IF;
    RETURN QUERY
    SELECT job.tenant_id,tenant.schema_name::name,job.payload_ref::uuid,job.id,
        attempt.attempt_id,attempt.attempt::bigint,attempt.lease_owner_id,
        attempt.effect_id,pg_catalog.decode(attempt.effect_request_sha256,'hex'),
        job.completed_at
    FROM platform.jobs AS job
    JOIN platform.job_attempts AS attempt
      ON attempt.job_id=job.id AND attempt.scope_kind='tenant'
     AND attempt.scope_id=job.tenant_id AND attempt.attempt=job.attempts
     AND attempt.lease_generation=job.lease_generation
    JOIN platform.tenants AS tenant ON tenant.id=job.tenant_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind=job.scope_kind
     AND group_row.scope_id=job.scope_id
     AND group_row.group_id=job.authority_group_id
     AND group_row.state='v2' AND group_row.writer='v2'
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=job.scope_kind
     AND domain_row.scope_id=job.scope_id
     AND domain_row.domain=job.authority_domain
     AND domain_row.state='v2' AND domain_row.writer='v2'
    JOIN platform.cutover_group_members AS member
      ON member.scope_kind=job.scope_kind AND member.scope_id=job.scope_id
     AND member.group_id=job.authority_group_id
     AND member.domain=job.authority_domain
    WHERE job.scope_kind='tenant' AND job.scope_id=job.tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3
      AND pg_catalog.pg_input_is_valid(job.payload_ref,'uuid')
      AND job.payload_ref=(job.payload_ref::uuid)::text
      AND pg_catalog.uuid_extract_version(job.payload_ref::uuid)=7
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(job.payload_ref,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||job.payload_ref
      AND job.effect_idempotency_key=job.dedupe_key
      AND job.state='dead' AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN'
      AND job.last_error_sha256 IS NULL AND job.completed_at IS NOT NULL
      AND attempt.attempt BETWEEN 1 AND 3 AND attempt.outcome='dead'
      AND attempt.error_class IS NULL
      AND attempt.error_code='JOB_OUTCOME_UNKNOWN'
      AND attempt.redacted_error_sha256 IS NULL
      AND attempt.finished_at=job.completed_at
      AND attempt.effect_started_at IS NOT NULL
      AND attempt.effect_id IS NOT NULL
      AND pg_catalog.uuid_extract_version(attempt.lease_owner_id)=7
      AND attempt.effect_request_sha256~'^[0-9a-f]{64}$'
      AND attempt.effect_request_sha256<>pg_catalog.repeat('0',64)
      AND attempt.effect_receipt_id IS NULL
      AND tenant.deleted_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM platform.analytics_dashboard_export_unknown_resolutions resolution
        WHERE resolution.job_id=job.id AND resolution.attempt_id=attempt.attempt_id
          AND resolution.effect_id=attempt.effect_id
      )
      AND NOT EXISTS (
        SELECT 1 FROM platform.analytics_dashboard_export_unknown_cleanup_claims claim
        WHERE claim.job_id=job.id AND (
            claim.lease_until>pg_catalog.clock_timestamp() OR
            claim.run_at>pg_catalog.clock_timestamp())
      )
    ORDER BY job.completed_at,job.id LIMIT 1;
END;
$_$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_candidate_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_cleanup_check(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, bigint, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_cleanup_check(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(lease_until timestamp with time zone, cancellation_requested boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_claim platform.analytics_dashboard_export_unknown_cleanup_claims%ROWTYPE;
    v_request text;
    v_checkpoint_at timestamptz;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export cleanup checkpoint authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_original_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       p_cleanup_generation<1 OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export cleanup checkpoint input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.state='dead' AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN' FOR SHARE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_original_lease_owner_id
      AND attempt.outcome='dead' AND attempt.error_class IS NULL
      AND attempt.error_code='JOB_OUTCOME_UNKNOWN'
      AND attempt.effect_id=p_effect_id
      AND attempt.effect_request_sha256=v_request
      AND attempt.effect_started_at IS NOT NULL
      AND attempt.effect_receipt_id IS NULL
      AND attempt.finished_at=v_job.completed_at FOR SHARE;
    IF v_job.id IS NULL OR v_attempt.attempt_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export cleanup checkpoint evidence differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_unknown_cleanup_claims AS claim
    WHERE claim.job_id=p_job_id AND claim.tenant_id=p_tenant_id
      AND claim.export_id=p_export_id AND claim.attempt_id=p_attempt_id
      AND claim.attempt_generation=p_attempt_generation
      AND claim.original_lease_owner_id=p_original_lease_owner_id
      AND claim.effect_id=p_effect_id AND claim.request_sha256=v_request
    FOR UPDATE;
    IF v_claim.job_id IS NULL OR
       v_claim.claim_generation<>p_cleanup_generation OR
       v_claim.lease_owner_id<>p_cleanup_lease_owner_id OR
       v_claim.lease_until<=pg_catalog.clock_timestamp() OR EXISTS (
        SELECT 1 FROM platform.analytics_dashboard_export_unknown_resolutions resolution
        WHERE resolution.job_id=p_job_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export cleanup checkpoint lease is stale';
    END IF;
    v_checkpoint_at:=GREATEST(pg_catalog.clock_timestamp(),p_observed_at,
        v_claim.updated_at+interval '1 microsecond');
    UPDATE platform.analytics_dashboard_export_unknown_cleanup_claims
    SET lease_heartbeat_at=v_checkpoint_at,
        lease_until=v_checkpoint_at+interval '60 seconds',updated_at=v_checkpoint_at
    WHERE job_id=p_job_id;
    lease_until:=v_checkpoint_at+interval '60 seconds';
    cancellation_requested:=v_job.cancel_requested_at IS NOT NULL;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_cleanup_check(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_cleanup_claim(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_cleanup_claim(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(claim_state text, cleanup_generation bigint, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_claim platform.analytics_dashboard_export_unknown_cleanup_claims%ROWTYPE;
    v_request text;
    v_claimed_at timestamptz;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export cleanup claim authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_original_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export cleanup claim input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_original_lease_owner_id FOR SHARE;
    IF v_job.state IS DISTINCT FROM 'dead' OR
       v_job.last_error_class IS NOT NULL OR
       v_job.last_error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       v_attempt.outcome IS DISTINCT FROM 'dead' OR
       v_attempt.error_class IS NOT NULL OR
       v_attempt.error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS NULL OR v_attempt.effect_receipt_id IS NOT NULL OR
       v_attempt.finished_at IS DISTINCT FROM v_job.completed_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export cleanup evidence differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    IF EXISTS (
        SELECT 1 FROM platform.analytics_dashboard_export_unknown_resolutions resolution
        WHERE resolution.job_id=p_job_id
    ) THEN
        claim_state:='resolved'; RETURN NEXT; RETURN;
    END IF;
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_unknown_cleanup_claims AS claim
    WHERE claim.job_id=p_job_id FOR UPDATE;
    IF FOUND AND (v_claim.tenant_id<>p_tenant_id OR
       v_claim.export_id<>p_export_id OR v_claim.attempt_id<>p_attempt_id OR
       v_claim.attempt_generation<>p_attempt_generation OR
       v_claim.original_lease_owner_id<>p_original_lease_owner_id OR
       v_claim.effect_id<>p_effect_id OR v_claim.request_sha256<>v_request) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export cleanup claim replay differs';
    END IF;
    IF FOUND AND v_claim.lease_until>pg_catalog.clock_timestamp() THEN
        IF v_claim.lease_owner_id=p_cleanup_lease_owner_id THEN
            claim_state:='claimed'; cleanup_generation:=v_claim.claim_generation;
            lease_until:=v_claim.lease_until; RETURN NEXT; RETURN;
        END IF;
        claim_state:='busy'; RETURN NEXT; RETURN;
    END IF;
    IF FOUND AND v_claim.run_at>pg_catalog.clock_timestamp() THEN
        claim_state:='busy'; RETURN NEXT; RETURN;
    END IF;
    v_claimed_at:=GREATEST(pg_catalog.clock_timestamp(),p_observed_at,
        COALESCE(v_claim.updated_at,p_observed_at)+interval '1 microsecond');
    IF FOUND THEN
        UPDATE platform.analytics_dashboard_export_unknown_cleanup_claims
        SET claim_generation=claim_generation+1,
            lease_owner_id=p_cleanup_lease_owner_id,
            lease_heartbeat_at=v_claimed_at,
            lease_until=v_claimed_at+interval '60 seconds',
            updated_at=v_claimed_at WHERE job_id=p_job_id
        RETURNING claim_generation INTO cleanup_generation;
    ELSE
        cleanup_generation:=1;
        INSERT INTO platform.analytics_dashboard_export_unknown_cleanup_claims(
            job_id,tenant_id,export_id,attempt_id,attempt_generation,
            original_lease_owner_id,effect_id,request_sha256,claim_generation,
            lease_owner_id,lease_heartbeat_at,lease_until,run_at,created_at,updated_at
        ) VALUES (p_job_id,p_tenant_id,p_export_id,p_attempt_id,p_attempt_generation,
            p_original_lease_owner_id,p_effect_id,v_request,cleanup_generation,
            p_cleanup_lease_owner_id,v_claimed_at,v_claimed_at+interval '60 seconds',
            v_claimed_at,v_claimed_at,v_claimed_at);
    END IF;
    claim_state:='claimed'; lease_until:=v_claimed_at+interval '60 seconds';
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_cleanup_claim(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_cleanup_defer(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, bigint, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_cleanup_defer(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_claim platform.analytics_dashboard_export_unknown_cleanup_claims%ROWTYPE;
    v_request text;
    v_deferred_at timestamptz;
    v_retry_at timestamptz;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export cleanup defer authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_original_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       p_cleanup_generation<1 OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export cleanup defer input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.state='dead' AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN' FOR SHARE;
    IF v_job.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export cleanup defer evidence differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_unknown_cleanup_claims AS claim
    WHERE claim.job_id=p_job_id AND claim.tenant_id=p_tenant_id
      AND claim.export_id=p_export_id AND claim.attempt_id=p_attempt_id
      AND claim.attempt_generation=p_attempt_generation
      AND claim.original_lease_owner_id=p_original_lease_owner_id
      AND claim.effect_id=p_effect_id AND claim.request_sha256=v_request
    FOR UPDATE;
    IF v_claim.job_id IS NULL OR
       v_claim.claim_generation<>p_cleanup_generation OR
       v_claim.lease_owner_id<>p_cleanup_lease_owner_id OR EXISTS (
        SELECT 1 FROM platform.analytics_dashboard_export_unknown_resolutions resolution
        WHERE resolution.job_id=p_job_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export cleanup defer lease is stale';
    END IF;
    IF v_claim.lease_until<=pg_catalog.clock_timestamp() AND
       v_claim.run_at>pg_catalog.clock_timestamp() THEN
        RETURN v_claim.run_at;
    END IF;
    IF v_claim.lease_until<=pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export cleanup defer lease expired';
    END IF;
    v_deferred_at:=GREATEST(pg_catalog.clock_timestamp(),p_observed_at,
        v_claim.updated_at+interval '1 microsecond');
    v_retry_at:=v_deferred_at+LEAST(
        interval '30 seconds'*pg_catalog.power(2::double precision,
            LEAST((p_cleanup_generation-1)::double precision,5::double precision)),
        interval '15 minutes');
    UPDATE platform.analytics_dashboard_export_unknown_cleanup_claims
    SET lease_until=v_deferred_at,run_at=v_retry_at,updated_at=v_deferred_at
    WHERE job_id=p_job_id;
    RETURN v_retry_at;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_cleanup_defer(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_evidence_v1(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_evidence_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_request text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown evidence authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export unknown evidence input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.state='dead' AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN'
      AND job.last_error_sha256 IS NULL FOR SHARE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id
      AND attempt.finished_at=v_job.completed_at AND attempt.outcome='dead'
      AND attempt.error_class IS NULL
      AND attempt.error_code='JOB_OUTCOME_UNKNOWN'
      AND attempt.redacted_error_sha256 IS NULL
      AND attempt.effect_id=p_effect_id
      AND attempt.effect_request_sha256=v_request
      AND attempt.effect_started_at IS NOT NULL
      AND attempt.effect_receipt_id IS NULL FOR SHARE;
    IF v_job.id IS NULL OR v_attempt.attempt_id IS NULL OR EXISTS (
        SELECT 1 FROM platform.analytics_dashboard_export_unknown_resolutions resolution
        WHERE resolution.job_id=p_job_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export unknown evidence differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    RETURN v_job.completed_at;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_evidence_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_resolve_v1(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_resolve_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_resolution_receipt_id uuid, p_resolution_kind text, p_resolution_sha256 bytea, p_resolved_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown resolution authority is invalid';
    END IF;
    RAISE EXCEPTION USING ERRCODE='P6047',
        MESSAGE='Analytics dashboard export cleanup lease is required';
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_resolve_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_resolution_receipt_id uuid, p_resolution_kind text, p_resolution_sha256 bytea, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_resolve_v2(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, bigint, uuid, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_resolve_v2(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_resolution_receipt_id uuid, p_resolution_kind text, p_resolution_sha256 bytea, p_resolved_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_claim platform.analytics_dashboard_export_unknown_cleanup_claims%ROWTYPE;
    v_resolution platform.analytics_dashboard_export_unknown_resolutions%ROWTYPE;
    v_request text;
    v_resolution_digest text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown resolution authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       p_cleanup_generation<1 OR
       pg_catalog.uuid_extract_version(p_cleanup_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_resolution_receipt_id) IS DISTINCT FROM 7 OR
       p_resolution_receipt_id IN (p_job_id,p_attempt_id,p_effect_id) OR
       p_resolution_kind NOT IN ('deleted','absent') OR
       pg_catalog.octet_length(p_resolution_sha256) IS DISTINCT FROM 32 OR
       p_resolution_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       NOT pg_catalog.isfinite(p_resolved_at) OR
       p_resolved_at>pg_catalog.clock_timestamp()+interval '5 seconds' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export unknown resolution input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    v_resolution_digest:=pg_catalog.encode(p_resolution_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR SHARE;
    IF v_job.id IS NULL OR v_attempt.attempt_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export unknown evidence is unavailable';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    IF NOT COALESCE((v_job.state='dead' AND
       v_job.last_error_class IS NULL AND
       v_job.last_error_code='JOB_OUTCOME_UNKNOWN' AND
       v_job.last_error_sha256 IS NULL AND v_job.completed_at IS NOT NULL AND
       v_job.updated_at=v_job.completed_at AND p_resolved_at>v_job.completed_at AND
       v_job.lease_owner_id IS NULL AND v_job.lease_heartbeat_at IS NULL AND
       v_job.lease_until IS NULL AND
       v_job.retain_until=v_job.completed_at+interval '366 days' AND
       v_attempt.finished_at=v_job.completed_at AND
       v_attempt.outcome='dead' AND v_attempt.error_class IS NULL AND
       v_attempt.error_code='JOB_OUTCOME_UNKNOWN' AND
       v_attempt.redacted_error_sha256 IS NULL AND
       v_attempt.effect_receipt_id IS NULL AND
       v_attempt.effect_id=p_effect_id AND
       v_attempt.effect_request_sha256=v_request AND
       v_attempt.effect_started_at IS NOT NULL AND
       v_job.effect_started_at=v_attempt.effect_started_at),false) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export is not exact unknown evidence';
    END IF;
    SELECT resolution.* INTO v_resolution
    FROM platform.analytics_dashboard_export_unknown_resolutions AS resolution
    WHERE resolution.job_id=p_job_id FOR SHARE;
    IF FOUND THEN
        IF v_resolution.resolution_receipt_id=p_resolution_receipt_id AND
           v_resolution.tenant_id=p_tenant_id AND
           v_resolution.export_id=p_export_id AND
           v_resolution.attempt_id=p_attempt_id AND
           v_resolution.attempt_generation=p_attempt_generation AND
           v_resolution.lease_owner_id=p_lease_owner_id AND
           v_resolution.effect_id=p_effect_id AND
           v_resolution.request_sha256=v_request AND
           v_resolution.cleanup_generation=p_cleanup_generation AND
           v_resolution.cleanup_lease_owner_id=p_cleanup_lease_owner_id AND
           v_resolution.resolution_kind=p_resolution_kind AND
           v_resolution.resolution_sha256=v_resolution_digest AND
           v_resolution.resolved_at=p_resolved_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export unknown resolution replay differs';
    END IF;
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_unknown_cleanup_claims AS claim
    WHERE claim.job_id=p_job_id AND claim.tenant_id=p_tenant_id
      AND claim.export_id=p_export_id AND claim.attempt_id=p_attempt_id
      AND claim.attempt_generation=p_attempt_generation
      AND claim.original_lease_owner_id=p_lease_owner_id
      AND claim.effect_id=p_effect_id AND claim.request_sha256=v_request
    FOR UPDATE;
    IF v_claim.job_id IS NULL OR
       v_claim.claim_generation<>p_cleanup_generation OR
       v_claim.lease_owner_id<>p_cleanup_lease_owner_id OR
       v_claim.lease_until<=pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export cleanup resolution lease is stale';
    END IF;
    INSERT INTO platform.analytics_dashboard_export_unknown_resolutions(
        resolution_receipt_id,tenant_id,export_id,job_id,attempt_id,
        attempt_generation,lease_owner_id,effect_id,request_sha256,
        cleanup_generation,cleanup_lease_owner_id,resolution_kind,
        resolution_sha256,resolved_at
    ) VALUES (
        p_resolution_receipt_id,p_tenant_id,p_export_id,p_job_id,p_attempt_id,
        p_attempt_generation,p_lease_owner_id,p_effect_id,v_request,
        p_cleanup_generation,p_cleanup_lease_owner_id,p_resolution_kind,
        v_resolution_digest,p_resolved_at
    );
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
        revision=revision+1,updated_at=GREATEST(
            updated_at+interval '1 microsecond',p_resolved_at)
    WHERE tenant_id=p_tenant_id AND reserved_ciphertext_bytes>=2147483648;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6049',
            MESSAGE='Analytics dashboard export unknown quota is inconsistent';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_resolve_v2(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_resolution_receipt_id uuid, p_resolution_kind text, p_resolution_sha256 bytea, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_dashboard_export_unknown_v1(uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_dashboard_export_unknown_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_request text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown authority is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_request_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export unknown input is invalid';
    END IF;
    v_request:=pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind='analytics.dashboard.export.render'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=3 AND job.payload_ref=p_export_id::text
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_export_id::text,'UTF8')),'hex')
      AND job.dedupe_key='analytics.dashboard.export.render:'||p_export_id::text
      AND job.effect_idempotency_key=job.dedupe_key FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_attempt_generation
      AND attempt.lease_generation=p_attempt_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_attempt.finished_at IS NOT NULL THEN
        IF COALESCE((v_job.state='dead' AND v_job.last_error_class IS NULL AND
           v_job.last_error_code='JOB_OUTCOME_UNKNOWN' AND
           v_job.last_error_sha256 IS NULL AND
           v_job.completed_at=p_observed_at AND v_job.updated_at=p_observed_at AND
           v_job.lease_owner_id IS NULL AND v_job.lease_heartbeat_at IS NULL AND
           v_job.lease_until IS NULL AND
           v_job.retain_until=p_observed_at+interval '366 days' AND
           v_attempt.outcome='dead' AND
           v_attempt.error_class IS NULL AND
           v_attempt.error_code='JOB_OUTCOME_UNKNOWN' AND
           v_attempt.redacted_error_sha256 IS NULL AND
           v_attempt.effect_receipt_id IS NULL AND
           v_attempt.effect_started_at IS NOT NULL AND
           v_job.effect_started_at=v_attempt.effect_started_at AND
           v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.finished_at=p_observed_at),false) THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export unknown replay differs';
    END IF;
    IF v_job.state IS DISTINCT FROM 'running' OR v_attempt.attempt_id IS NULL OR
       v_job.attempts IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_generation IS DISTINCT FROM p_attempt_generation OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_until<=pg_catalog.clock_timestamp() OR
       v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS NULL OR
       v_job.effect_started_at IS DISTINCT FROM v_attempt.effect_started_at OR
       p_observed_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export unknown lease is stale';
    END IF;
    UPDATE platform.job_attempts SET finished_at=p_observed_at,outcome='dead',
        error_class=NULL,error_code='JOB_OUTCOME_UNKNOWN',
        redacted_error_sha256=NULL,effect_receipt_id=NULL
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='dead',lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=NULL,
        last_error_code='JOB_OUTCOME_UNKNOWN',last_error_sha256=NULL,
        retain_until=p_observed_at+interval '366 days',updated_at=p_observed_at,
        completed_at=p_observed_at WHERE id=p_job_id;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_dashboard_export_unknown_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_export_maint_receipt_id_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_export_maint_receipt_id_v1(p_effect_id uuid, p_kind text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_code text;
    v_digest bytea;
    v_uuid bytea;
    v_hex text;
BEGIN
    v_code:=CASE p_kind WHEN 'analytics.dashboard.export.delete' THEN
        'ANALYTICS_EXPORT_DELETED' WHEN 'analytics.dashboard.export.expire' THEN
        'ANALYTICS_EXPORT_EXPIRY_COMPLETE' END;
    IF v_code IS NULL OR pg_catalog.uuid_extract_version(p_effect_id)<>5 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export receipt identity input is invalid';
    END IF;
    v_digest:=platform.platform_async_analytics_export_sha1_v1(
        pg_catalog.uuid_send('8e7a6d02-df6d-4327-b179-160296b50b8e'::uuid)||
        pg_catalog.convert_to(p_effect_id::text,'UTF8')||
        pg_catalog.decode('00','hex')||pg_catalog.convert_to(v_code,'UTF8'));
    v_uuid:=pg_catalog.substr(v_digest,1,16);
    v_uuid:=pg_catalog.set_byte(v_uuid,6,
        (pg_catalog.get_byte(v_uuid,6)&15)|80);
    v_uuid:=pg_catalog.set_byte(v_uuid,8,
        (pg_catalog.get_byte(v_uuid,8)&63)|128);
    v_hex:=pg_catalog.encode(v_uuid,'hex');
    RETURN (pg_catalog.substr(v_hex,1,8)||'-'||pg_catalog.substr(v_hex,9,4)||'-'||
        pg_catalog.substr(v_hex,13,4)||'-'||pg_catalog.substr(v_hex,17,4)||'-'||
        pg_catalog.substr(v_hex,21,12))::uuid;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_export_maint_receipt_id_v1(p_effect_id uuid, p_kind text) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_export_maintenance_effect_id_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_export_maintenance_effect_id_v1(p_attempt_id uuid, p_kind text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_namespace uuid;
    v_digest bytea;
    v_uuid bytea;
    v_hex text;
BEGIN
    v_namespace:=CASE p_kind
        WHEN 'analytics.dashboard.export.delete' THEN
            'bfce9d42-fd8b-453a-a54e-d6f35a886868'::uuid
        WHEN 'analytics.dashboard.export.expire' THEN
            '1bce05e3-fc4d-40a9-82e9-f125b12fa10a'::uuid END;
    IF pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       v_namespace IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export maintenance effect identity input is invalid';
    END IF;
    v_digest:=platform.platform_async_analytics_export_sha1_v1(
        pg_catalog.uuid_send(v_namespace)||pg_catalog.uuid_send(p_attempt_id));
    v_uuid:=pg_catalog.substr(v_digest,1,16);
    v_uuid:=pg_catalog.set_byte(v_uuid,6,
        (pg_catalog.get_byte(v_uuid,6)&15)|80);
    v_uuid:=pg_catalog.set_byte(v_uuid,8,
        (pg_catalog.get_byte(v_uuid,8)&63)|128);
    v_hex:=pg_catalog.encode(v_uuid,'hex');
    RETURN (pg_catalog.substr(v_hex,1,8)||'-'||pg_catalog.substr(v_hex,9,4)||'-'||
        pg_catalog.substr(v_hex,13,4)||'-'||pg_catalog.substr(v_hex,17,4)||'-'||
        pg_catalog.substr(v_hex,21,12))::uuid;
END;
$$;


