--

CREATE FUNCTION platform.platform_async_analytics_export_maintenance_receipt_id_v2(p_effect_id uuid, p_code text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_code text;
    v_digest bytea;
    v_uuid bytea;
    v_hex text;
BEGIN
    v_code:=CASE p_code
        WHEN 'ANALYTICS_EXPORT_DELETED' THEN p_code
        WHEN 'ANALYTICS_EXPORT_EXPIRY_COMPLETE' THEN p_code
        WHEN 'ANALYTICS_EXPORT_REJECTED' THEN p_code
        WHEN 'ANALYTICS_EXPORT_CONFLICT' THEN p_code
        WHEN 'ANALYTICS_EXPORT_UNAVAILABLE' THEN p_code
        WHEN 'ANALYTICS_EXPORT_RETRY' THEN p_code
        WHEN 'ANALYTICS_EXPORT_TERMINAL' THEN p_code END;
    IF pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 5 OR
       v_code IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export maintenance receipt identity input is invalid';
    END IF;
    v_digest:=platform.platform_async_analytics_export_sha1_v1(
        pg_catalog.uuid_send('8e7a6d02-df6d-4327-b179-160296b50b8e'::uuid)||
        pg_catalog.convert_to(p_effect_id::text,'UTF8')||
        pg_catalog.decode('00','hex')||pg_catalog.convert_to(v_code,'UTF8'));
    v_uuid:=pg_catalog.substr(v_digest,1,16);
    v_uuid:=pg_catalog.set_byte(v_uuid,6,
        (pg_catalog.get_byte(v_uuid,6)&15)|80);
    v_uuid:=pg_catalog.set_byte(v_uuid,8,
        (pg_catalog.get_byte(v_uuid,8)&63)|128);
    v_hex:=pg_catalog.encode(v_uuid,'hex');
    RETURN (pg_catalog.substr(v_hex,1,8)||'-'||pg_catalog.substr(v_hex,9,4)||'-'||
        pg_catalog.substr(v_hex,13,4)||'-'||pg_catalog.substr(v_hex,17,4)||'-'||
        pg_catalog.substr(v_hex,21,12))::uuid;
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_export_maintenance_receipt_id_v2(p_effect_id uuid, p_code text) OWNER TO harpy_owner;

--
-- Name: platform_async_analytics_export_sha1_v1(bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_analytics_export_sha1_v1(p_value bytea) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_h0 bigint:=1732584193;
    v_h1 bigint:=4023233417;
    v_h2 bigint:=2562383102;
    v_h3 bigint:=271733878;
    v_h4 bigint:=3285377520;
    v_a bigint;
    v_b bigint;
    v_c bigint;
    v_d bigint;
    v_e bigint;
    v_f bigint;
    v_k bigint;
    v_temp bigint;
    v_word bigint;
    v_words bigint[]:=pg_catalog.array_fill(0::bigint,ARRAY[80]);
    v_data bytea;
    v_length integer:=pg_catalog.octet_length(p_value);
    v_padded integer;
    v_block integer;
    v_round integer;
    v_mask constant bigint:=4294967295;
BEGIN
    IF v_length>4096 THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='SHA-1 input is too large';
    END IF;
    v_padded:=((v_length+72)/64)*64;
    v_data:=p_value||pg_catalog.decode('80','hex')||pg_catalog.decode(
        pg_catalog.repeat('00',v_padded-v_length-9),'hex')||
        pg_catalog.int8send(v_length::bigint*8);
    FOR v_block IN 0..(v_padded/64)-1 LOOP
        FOR v_round IN 0..15 LOOP
            v_words[v_round+1]:=
                (pg_catalog.get_byte(v_data,v_block*64+v_round*4)::bigint<<24)|
                (pg_catalog.get_byte(v_data,v_block*64+v_round*4+1)::bigint<<16)|
                (pg_catalog.get_byte(v_data,v_block*64+v_round*4+2)::bigint<<8)|
                 pg_catalog.get_byte(v_data,v_block*64+v_round*4+3)::bigint;
        END LOOP;
        FOR v_round IN 16..79 LOOP
            v_word:=v_words[v_round-2]#v_words[v_round-7]#
                v_words[v_round-13]#v_words[v_round-15];
            v_words[v_round+1]:=((v_word<<1)&v_mask)|(v_word>>31);
        END LOOP;
        v_a:=v_h0; v_b:=v_h1; v_c:=v_h2; v_d:=v_h3; v_e:=v_h4;
        FOR v_round IN 0..79 LOOP
            IF v_round<20 THEN
                v_f:=(v_b&v_c)|((v_b#v_mask)&v_d); v_k:=1518500249;
            ELSIF v_round<40 THEN
                v_f:=v_b#v_c#v_d; v_k:=1859775393;
            ELSIF v_round<60 THEN
                v_f:=(v_b&v_c)|(v_b&v_d)|(v_c&v_d); v_k:=2400959708;
            ELSE
                v_f:=v_b#v_c#v_d; v_k:=3395469782;
            END IF;
            v_temp:=((v_a<<5)&v_mask)|(v_a>>27);
            v_temp:=(v_temp+v_f+v_e+v_k+v_words[v_round+1])&v_mask;
            v_e:=v_d; v_d:=v_c;
            v_c:=(((v_b<<30)&v_mask)|(v_b>>2))&v_mask;
            v_b:=v_a; v_a:=v_temp;
        END LOOP;
        v_h0:=(v_h0+v_a)&v_mask; v_h1:=(v_h1+v_b)&v_mask;
        v_h2:=(v_h2+v_c)&v_mask; v_h3:=(v_h3+v_d)&v_mask;
        v_h4:=(v_h4+v_e)&v_mask;
    END LOOP;
    RETURN pg_catalog.decode(
        pg_catalog.lpad(pg_catalog.to_hex(v_h0),8,'0')||
        pg_catalog.lpad(pg_catalog.to_hex(v_h1),8,'0')||
        pg_catalog.lpad(pg_catalog.to_hex(v_h2),8,'0')||
        pg_catalog.lpad(pg_catalog.to_hex(v_h3),8,'0')||
        pg_catalog.lpad(pg_catalog.to_hex(v_h4),8,'0'),'hex');
END;
$$;


ALTER FUNCTION platform.platform_async_analytics_export_sha1_v1(p_value bytea) OWNER TO harpy_owner;

--
-- Name: idempotency_receipts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.idempotency_receipts (
    receipt_id uuid NOT NULL,
    record_kind text NOT NULL,
    tenant_id uuid,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    authority_group_id text NOT NULL,
    authority_group_generation bigint NOT NULL,
    authority_domain text NOT NULL,
    cutover_generation bigint NOT NULL,
    writer_origin text NOT NULL,
    request_sha256 text NOT NULL,
    retention_class text NOT NULL,
    principal_id uuid,
    operation_id text,
    idempotency_key text,
    authorization_version bigint,
    response_status integer,
    response_headers jsonb,
    response_body bytea,
    http_result_ref text,
    response_sha256 text,
    async_job_id uuid,
    effect_id uuid,
    effect_kind text,
    effect_revision bigint,
    effect_key text,
    provider text,
    operation text,
    correlation_id text,
    causation_id uuid,
    effect_status text,
    effect_error_class text,
    effect_code text,
    provider_reference text,
    effect_result_ref text,
    effect_result_sha256 text,
    completed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    retain_until timestamp with time zone NOT NULL,
    CONSTRAINT idempotency_receipts_authority_domain_check CHECK ((authority_domain ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT idempotency_receipts_authority_group_generation_check CHECK ((authority_group_generation > 0)),
    CONSTRAINT idempotency_receipts_authority_group_id_check CHECK ((authority_group_id ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT idempotency_receipts_authorization_version_check CHECK ((authorization_version > 0)),
    CONSTRAINT idempotency_receipts_correlation_id_check CHECK ((correlation_id ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,63}$'::text)),
    CONSTRAINT idempotency_receipts_cutover_generation_check CHECK ((cutover_generation > 0)),
    CONSTRAINT idempotency_receipts_effect_code_check CHECK ((effect_code ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT idempotency_receipts_effect_error_class_check CHECK ((effect_error_class = ANY (ARRAY['transient'::text, 'permanent'::text, 'conflict'::text, 'cancelled'::text]))),
    CONSTRAINT idempotency_receipts_effect_key_check CHECK (((octet_length(effect_key) >= 1) AND (octet_length(effect_key) <= 512))),
    CONSTRAINT idempotency_receipts_effect_kind_check CHECK ((effect_kind ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT idempotency_receipts_effect_result_ref_check CHECK (((octet_length(effect_result_ref) >= 1) AND (octet_length(effect_result_ref) <= 2048))),
    CONSTRAINT idempotency_receipts_effect_result_sha256_check CHECK ((effect_result_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT idempotency_receipts_effect_revision_check CHECK ((effect_revision > 0)),
    CONSTRAINT idempotency_receipts_effect_shape_check CHECK (((record_kind <> 'effect'::text) OR ((retention_class = ANY (ARRAY['external_effect'::text, 'workflow_effect'::text])) AND (principal_id IS NULL) AND (operation_id IS NULL) AND (idempotency_key IS NULL) AND (authorization_version IS NULL) AND (response_status IS NULL) AND (response_headers IS NULL) AND (response_body IS NULL) AND (http_result_ref IS NULL) AND (response_sha256 IS NULL) AND (async_job_id IS NULL) AND (effect_id IS NOT NULL) AND (effect_kind IS NOT NULL) AND (effect_revision IS NOT NULL) AND (effect_key IS NOT NULL) AND (provider IS NOT NULL) AND (operation IS NOT NULL) AND (correlation_id IS NOT NULL) AND (causation_id IS NOT NULL) AND (effect_status IS NOT NULL) AND (effect_code IS NOT NULL) AND (((effect_status = 'succeeded'::text) AND (effect_error_class IS NULL) AND (effect_result_ref IS NOT NULL) AND (effect_result_sha256 IS NOT NULL)) OR ((effect_status = 'failed'::text) AND (effect_error_class IS NOT NULL) AND (effect_result_ref IS NULL) AND (effect_result_sha256 IS NULL)))))),
    CONSTRAINT idempotency_receipts_effect_status_check CHECK ((effect_status = ANY (ARRAY['succeeded'::text, 'failed'::text]))),
    CONSTRAINT idempotency_receipts_http_result_ref_check CHECK (((octet_length(http_result_ref) >= 1) AND (octet_length(http_result_ref) <= 2048))),
    CONSTRAINT idempotency_receipts_http_shape_check CHECK (((record_kind <> 'http'::text) OR ((retention_class = ANY (ARRAY['interactive_write'::text, 'administrative_write'::text, 'async_handle'::text])) AND (tenant_id IS NOT NULL) AND (principal_id IS NOT NULL) AND (operation_id IS NOT NULL) AND (idempotency_key IS NOT NULL) AND (authorization_version IS NOT NULL) AND (response_status IS NOT NULL) AND (response_headers IS NOT NULL) AND (jsonb_typeof(response_headers) = 'object'::text) AND (octet_length((response_headers)::text) <= 16384) AND (response_sha256 IS NOT NULL) AND (((retention_class = 'async_handle'::text) AND (async_job_id IS NOT NULL)) OR ((retention_class <> 'async_handle'::text) AND (async_job_id IS NULL))) AND (effect_id IS NULL) AND (effect_kind IS NULL) AND (effect_revision IS NULL) AND (effect_key IS NULL) AND (provider IS NULL) AND (operation IS NULL) AND (correlation_id IS NULL) AND (causation_id IS NULL) AND (effect_status IS NULL) AND (effect_error_class IS NULL) AND (effect_code IS NULL) AND (provider_reference IS NULL) AND (effect_result_ref IS NULL) AND (effect_result_sha256 IS NULL) AND (((response_body IS NOT NULL) AND (http_result_ref IS NULL) AND (octet_length(response_body) <= 65536)) OR ((response_body IS NULL) AND (http_result_ref IS NOT NULL)))))),
    CONSTRAINT idempotency_receipts_idempotency_key_check CHECK (((octet_length(idempotency_key) >= 1) AND (octet_length(idempotency_key) <= 512))),
    CONSTRAINT idempotency_receipts_operation_check CHECK ((operation ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT idempotency_receipts_operation_id_check CHECK ((operation_id ~ '^[a-z][a-z0-9_.:-]{0,127}$'::text)),
    CONSTRAINT idempotency_receipts_provider_check CHECK ((provider ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT idempotency_receipts_provider_reference_check CHECK (((octet_length(provider_reference) >= 1) AND (octet_length(provider_reference) <= 512))),
    CONSTRAINT idempotency_receipts_record_kind_check CHECK ((record_kind = ANY (ARRAY['http'::text, 'effect'::text]))),
    CONSTRAINT idempotency_receipts_request_sha256_check CHECK ((request_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT idempotency_receipts_response_sha256_check CHECK ((response_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT idempotency_receipts_response_status_check CHECK (((response_status >= 100) AND (response_status <= 599))),
    CONSTRAINT idempotency_receipts_retention_class_check CHECK ((retention_class = ANY (ARRAY['interactive_write'::text, 'administrative_write'::text, 'async_handle'::text, 'external_effect'::text, 'workflow_effect'::text]))),
    CONSTRAINT idempotency_receipts_scope_check CHECK ((((scope_kind = 'tenant'::text) AND (tenant_id IS NOT NULL) AND (tenant_id = scope_id)) OR ((scope_kind = 'global'::text) AND (tenant_id IS NULL)))),
    CONSTRAINT idempotency_receipts_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT idempotency_receipts_time_check CHECK ((completed_at < retain_until)),
    CONSTRAINT idempotency_receipts_writer_origin_check CHECK ((writer_origin = ANY (ARRAY['v1'::text, 'v2'::text])))
);


ALTER TABLE platform.idempotency_receipts OWNER TO harpy_owner;

--
-- Name: platform_async_assert_analytics_dashboard_export_maintenance_re(platform.idempotency_receipts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_analytics_dashboard_export_maintenance_re(p_receipt platform.idempotency_receipts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_claim platform.analytics_dashboard_export_maintenance_unknown_claims%ROWTYPE;
    v_schema name;
    v_operation text;
    v_code text;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_receipt.effect_kind NOT IN ('analytics.dashboard.export.delete',
                                     'analytics.dashboard.export.expire') THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance receipt authority is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_receipt.causation_id AND job.tenant_id=p_receipt.tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=job.tenant_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind=p_receipt.effect_kind AND job.payload_revision=1
      AND job.effect_class='external' AND job.state='dead'
      AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN' FOR SHARE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=v_job.id AND attempt.attempt=v_job.attempts
      AND attempt.lease_generation=v_job.lease_generation
      AND attempt.outcome='dead' AND attempt.error_class IS NULL
      AND attempt.error_code='JOB_OUTCOME_UNKNOWN'
      AND attempt.effect_receipt_id IS NULL FOR SHARE;
    SELECT claim.* INTO v_claim
    FROM platform.analytics_dashboard_export_maintenance_unknown_claims AS claim
    WHERE claim.job_id=v_job.id AND claim.attempt_id=v_attempt.attempt_id
      AND claim.effect_id=v_attempt.effect_id
      AND claim.request_sha256=v_attempt.effect_request_sha256
      AND claim.claim_generation>0
      AND claim.cleanup_lease_owner_id IS NOT NULL
      AND claim.lease_until>pg_catalog.clock_timestamp() FOR SHARE;
    SELECT tenant.schema_name INTO v_schema FROM platform.tenants AS tenant
    WHERE tenant.id=v_job.tenant_id AND tenant.deleted_at IS NULL FOR SHARE;
    v_operation:=CASE v_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'delete'
        WHEN 'analytics.dashboard.export.expire' THEN 'expire' END;
    v_code:=CASE v_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'ANALYTICS_EXPORT_DELETED'
        WHEN 'analytics.dashboard.export.expire' THEN
            'ANALYTICS_EXPORT_EXPIRY_COMPLETE' END;
    IF v_job.id IS NULL OR v_attempt.attempt_id IS NULL OR v_claim.job_id IS NULL OR
       v_schema IS DISTINCT FROM v_claim.tenant_schema OR
       p_receipt.receipt_id IS DISTINCT FROM
          platform.platform_async_analytics_export_maint_receipt_id_v1(
              v_attempt.effect_id,v_job.kind) OR
       p_receipt.record_kind IS DISTINCT FROM 'effect' OR
       p_receipt.scope_kind IS DISTINCT FROM v_job.scope_kind OR
       p_receipt.scope_id IS DISTINCT FROM v_job.scope_id OR
       p_receipt.authority_group_id IS DISTINCT FROM v_job.authority_group_id OR
       p_receipt.authority_group_generation IS DISTINCT FROM
           v_job.authority_group_generation OR
       p_receipt.authority_domain IS DISTINCT FROM v_job.authority_domain OR
       p_receipt.cutover_generation IS DISTINCT FROM v_job.cutover_generation OR
       p_receipt.writer_origin IS DISTINCT FROM 'v2' OR
       p_receipt.request_sha256 IS DISTINCT FROM v_attempt.effect_request_sha256 OR
       p_receipt.retention_class IS DISTINCT FROM 'external_effect' OR
       p_receipt.effect_id IS DISTINCT FROM v_attempt.effect_id OR
       p_receipt.effect_revision IS DISTINCT FROM 1 OR
       p_receipt.effect_key IS DISTINCT FROM v_job.effect_idempotency_key OR
       p_receipt.provider IS DISTINCT FROM 'analytics.dashboard-export' OR
       p_receipt.operation IS DISTINCT FROM v_operation OR
       p_receipt.correlation_id IS DISTINCT FROM v_job.id::text OR
       p_receipt.effect_status IS DISTINCT FROM 'succeeded' OR
       p_receipt.effect_error_class IS NOT NULL OR
       p_receipt.effect_code IS DISTINCT FROM v_code OR
       p_receipt.provider_reference IS DISTINCT FROM v_job.payload_ref OR
       p_receipt.effect_result_ref IS NULL OR
       p_receipt.effect_result_ref IS DISTINCT FROM
          'analytics-dashboard-export://'||v_operation||'/'||v_job.payload_ref||'/'||
          pg_catalog.split_part(p_receipt.effect_result_ref,'/',5) OR
       p_receipt.effect_result_sha256 IS DISTINCT FROM pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(p_receipt.effect_result_ref,'UTF8')),
          'hex') OR p_receipt.completed_at<=v_job.completed_at OR
       p_receipt.retain_until IS DISTINCT FROM
          p_receipt.completed_at+interval '90 days' THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance receipt differs';
    END IF;
    IF (v_job.kind='analytics.dashboard.export.delete' AND
        p_receipt.effect_result_ref<> 'analytics-dashboard-export://delete/'||
            v_job.payload_ref||'/deleted') OR
       (v_job.kind='analytics.dashboard.export.expire' AND
        pg_catalog.split_part(p_receipt.effect_result_ref,'/',5) NOT IN
            ('expired','cancelled','failed','deleted')) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance receipt state differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
END;
$$;


ALTER FUNCTION platform.platform_async_assert_analytics_dashboard_export_maintenance_re(p_receipt platform.idempotency_receipts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_analytics_dashboard_export_receipt_replay(platform.idempotency_receipts, platform.jobs, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_analytics_dashboard_export_receipt_replay(p_receipt platform.idempotency_receipts, p_job platform.jobs, p_current_user name, p_session_user name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_existing platform.idempotency_receipts%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_operation text;
    v_success_code text;
    v_expected_class text;
    v_expected_effect uuid;
    v_expected_receipt uuid;
    v_result_state text;
    v_result_ref text;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_receipt.writer_origin IS DISTINCT FROM 'v2' OR
       p_receipt.effect_kind NOT IN ('analytics.dashboard.export.delete',
                                     'analytics.dashboard.export.expire') THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export receipt replay authority is invalid';
    END IF;
    SELECT receipt.* INTO v_existing FROM platform.idempotency_receipts AS receipt
    WHERE receipt.receipt_id=p_receipt.receipt_id FOR SHARE;
    IF NOT FOUND THEN RETURN false; END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=p_job.id
      AND attempt.effect_receipt_id=p_receipt.receipt_id
      AND attempt.effect_id=p_receipt.effect_id
      AND attempt.effect_request_sha256=p_receipt.request_sha256
    ORDER BY attempt.attempt DESC LIMIT 1 FOR SHARE;
    v_operation:=CASE p_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'delete'
        WHEN 'analytics.dashboard.export.expire' THEN 'expire' END;
    v_success_code:=CASE p_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'ANALYTICS_EXPORT_DELETED'
        WHEN 'analytics.dashboard.export.expire' THEN
            'ANALYTICS_EXPORT_EXPIRY_COMPLETE' END;
    v_expected_class:=CASE p_receipt.effect_code
        WHEN 'ANALYTICS_EXPORT_REJECTED' THEN 'permanent'
        WHEN 'ANALYTICS_EXPORT_CONFLICT' THEN 'conflict'
        WHEN 'ANALYTICS_EXPORT_UNAVAILABLE' THEN 'transient'
        WHEN 'ANALYTICS_EXPORT_RETRY' THEN 'transient'
        WHEN 'ANALYTICS_EXPORT_TERMINAL' THEN 'permanent' END;
    IF p_job.id IS NULL OR v_attempt.attempt_id IS NULL OR
       v_existing IS DISTINCT FROM p_receipt OR
       pg_catalog.uuid_extract_version(v_attempt.attempt_id) IS DISTINCT FROM 7 OR
       (p_receipt.effect_status='succeeded' AND
          p_receipt.effect_code IS DISTINCT FROM v_success_code) OR
       (p_receipt.effect_status='failed' AND v_expected_class IS NULL) OR
       p_receipt.effect_status NOT IN ('succeeded','failed') THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export receipt replay differs';
    END IF;
    v_expected_effect:=
        platform.platform_async_analytics_export_maintenance_effect_id_v1(
            v_attempt.attempt_id,p_job.kind);
    v_expected_receipt:=
        platform.platform_async_analytics_export_maintenance_receipt_id_v2(
            v_expected_effect,p_receipt.effect_code);
    IF p_receipt.receipt_id IS DISTINCT FROM v_expected_receipt OR
       p_receipt.record_kind IS DISTINCT FROM 'effect' OR
       p_receipt.tenant_id IS DISTINCT FROM p_job.tenant_id OR
       p_receipt.scope_kind IS DISTINCT FROM p_job.scope_kind OR
       p_receipt.scope_id IS DISTINCT FROM p_job.scope_id OR
       p_receipt.authority_group_id IS DISTINCT FROM p_job.authority_group_id OR
       p_receipt.authority_group_generation IS DISTINCT FROM
           p_job.authority_group_generation OR
       p_receipt.authority_domain IS DISTINCT FROM p_job.authority_domain OR
       p_receipt.cutover_generation IS DISTINCT FROM p_job.cutover_generation OR
       p_receipt.retention_class IS DISTINCT FROM 'external_effect' OR
       p_receipt.effect_id IS DISTINCT FROM v_expected_effect OR
       p_receipt.effect_kind IS DISTINCT FROM p_job.kind OR
       p_receipt.effect_revision IS DISTINCT FROM 1 OR
       p_receipt.effect_key IS DISTINCT FROM p_job.effect_idempotency_key OR
       p_receipt.provider IS DISTINCT FROM 'analytics.dashboard-export' OR
       p_receipt.operation IS DISTINCT FROM v_operation OR
       p_receipt.correlation_id IS DISTINCT FROM p_job.id::text OR
       p_receipt.causation_id IS DISTINCT FROM p_job.id OR
       p_receipt.provider_reference IS DISTINCT FROM p_job.payload_ref OR
       p_receipt.retain_until IS DISTINCT FROM
           p_receipt.completed_at+interval '90 days' OR
       v_attempt.finished_at IS NULL OR v_attempt.effect_started_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export receipt replay evidence differs';
    END IF;
    IF p_receipt.effect_status='failed' THEN
        IF v_attempt.outcome NOT IN ('requeued','dead') OR
           v_attempt.error_class IS DISTINCT FROM v_expected_class OR
           v_attempt.error_code IS DISTINCT FROM p_receipt.effect_code OR
           p_receipt.effect_error_class IS DISTINCT FROM v_expected_class OR
           p_receipt.effect_result_ref IS NOT NULL OR
           p_receipt.effect_result_sha256 IS NOT NULL OR
           (v_attempt.outcome='dead' AND p_job.state IS DISTINCT FROM 'dead') THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export failure receipt replay differs';
        END IF;
        RETURN true;
    END IF;
    v_result_state:=pg_catalog.split_part(p_receipt.effect_result_ref,'/',5);
    v_result_ref:='analytics-dashboard-export://'||v_operation||'/'||
        p_job.payload_ref||'/'||v_result_state;
    IF p_job.state IS DISTINCT FROM 'succeeded' OR
       p_job.completed_at IS NULL OR p_job.updated_at IS DISTINCT FROM p_job.completed_at OR
       p_job.lease_owner_id IS NOT NULL OR p_job.lease_until IS NOT NULL OR
       p_job.last_error_class IS NOT NULL OR p_job.last_error_code IS NOT NULL OR
       v_attempt.outcome IS DISTINCT FROM 'succeeded' OR
       v_attempt.finished_at IS DISTINCT FROM p_job.completed_at OR
       v_attempt.error_class IS NOT NULL OR v_attempt.error_code IS NOT NULL OR
       p_receipt.effect_error_class IS NOT NULL OR
       p_receipt.effect_result_ref IS DISTINCT FROM v_result_ref OR
       p_receipt.effect_result_sha256 IS DISTINCT FROM pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(v_result_ref,'UTF8')),'hex') OR
       (p_job.kind='analytics.dashboard.export.delete' AND
          v_result_state IS DISTINCT FROM 'deleted') OR
       (p_job.kind='analytics.dashboard.export.expire' AND
          v_result_state NOT IN ('expired','cancelled','failed','deleted')) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export success receipt replay differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platform_async_assert_analytics_dashboard_export_receipt_replay(p_receipt platform.idempotency_receipts, p_job platform.jobs, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_analytics_dashboard_export_running_receip(platform.idempotency_receipts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_analytics_dashboard_export_running_receip(p_receipt platform.idempotency_receipts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_operation text;
    v_success_code text;
    v_expected_class text;
    v_expected_effect uuid;
    v_expected_receipt uuid;
    v_result_state text;
    v_result_ref text;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_receipt.effect_kind NOT IN ('analytics.dashboard.export.delete',
                                     'analytics.dashboard.export.expire') OR
       p_receipt.writer_origin IS DISTINCT FROM 'v2' OR
       pg_catalog.uuid_extract_version(p_receipt.effect_id) IS DISTINCT FROM 5 OR
       pg_catalog.isfinite(p_receipt.completed_at) IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export running receipt authority is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_receipt.causation_id AND job.tenant_id=p_receipt.tenant_id
    FOR UPDATE;
    IF v_job.id IS NULL OR
       pg_catalog.pg_input_is_valid(v_job.payload_ref,'uuid') IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export running receipt job differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_maintenance_effect_owner_v1(
        v_job.tenant_id,v_job.payload_ref::uuid,v_job.id,p_receipt.effect_id,
        p_receipt.completed_at);
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=v_job.id AND attempt.scope_kind='tenant'
      AND attempt.scope_id=v_job.tenant_id AND attempt.attempt=v_job.attempts
      AND attempt.lease_generation=v_job.lease_generation FOR UPDATE;
    IF pg_catalog.uuid_extract_version(v_attempt.attempt_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export running receipt attempt differs';
    END IF;
    v_operation:=CASE v_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'delete'
        WHEN 'analytics.dashboard.export.expire' THEN 'expire' END;
    v_success_code:=CASE v_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 'ANALYTICS_EXPORT_DELETED'
        WHEN 'analytics.dashboard.export.expire' THEN
            'ANALYTICS_EXPORT_EXPIRY_COMPLETE' END;
    v_expected_class:=CASE p_receipt.effect_code
        WHEN 'ANALYTICS_EXPORT_REJECTED' THEN 'permanent'
        WHEN 'ANALYTICS_EXPORT_CONFLICT' THEN 'conflict'
        WHEN 'ANALYTICS_EXPORT_UNAVAILABLE' THEN 'transient'
        WHEN 'ANALYTICS_EXPORT_RETRY' THEN 'transient'
        WHEN 'ANALYTICS_EXPORT_TERMINAL' THEN 'permanent' END;
    IF (p_receipt.effect_status='succeeded' AND
            p_receipt.effect_code IS DISTINCT FROM v_success_code) OR
       (p_receipt.effect_status='failed' AND v_expected_class IS NULL) OR
       p_receipt.effect_status NOT IN ('succeeded','failed') THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export running receipt outcome differs';
    END IF;
    v_expected_effect:=
        platform.platform_async_analytics_export_maintenance_effect_id_v1(
            v_attempt.attempt_id,v_job.kind);
    v_expected_receipt:=
        platform.platform_async_analytics_export_maintenance_receipt_id_v2(
            v_expected_effect,p_receipt.effect_code);
    IF p_receipt.receipt_id IS DISTINCT FROM v_expected_receipt OR
       p_receipt.record_kind IS DISTINCT FROM 'effect' OR
       p_receipt.scope_kind IS DISTINCT FROM v_job.scope_kind OR
       p_receipt.scope_id IS DISTINCT FROM v_job.scope_id OR
       p_receipt.tenant_id IS DISTINCT FROM v_job.tenant_id OR
       p_receipt.authority_group_id IS DISTINCT FROM v_job.authority_group_id OR
       p_receipt.authority_group_generation IS DISTINCT FROM
           v_job.authority_group_generation OR
       p_receipt.authority_domain IS DISTINCT FROM v_job.authority_domain OR
       p_receipt.cutover_generation IS DISTINCT FROM v_job.cutover_generation OR
       p_receipt.request_sha256 IS DISTINCT FROM v_attempt.effect_request_sha256 OR
       p_receipt.retention_class IS DISTINCT FROM 'external_effect' OR
       p_receipt.effect_id IS DISTINCT FROM v_expected_effect OR
       p_receipt.effect_kind IS DISTINCT FROM v_job.kind OR
       p_receipt.effect_revision IS DISTINCT FROM 1 OR
       p_receipt.effect_key IS DISTINCT FROM v_job.effect_idempotency_key OR
       p_receipt.provider IS DISTINCT FROM 'analytics.dashboard-export' OR
       p_receipt.operation IS DISTINCT FROM v_operation OR
       p_receipt.correlation_id IS DISTINCT FROM v_job.id::text OR
       p_receipt.causation_id IS DISTINCT FROM v_job.id OR
       p_receipt.provider_reference IS DISTINCT FROM v_job.payload_ref OR
       p_receipt.retain_until IS DISTINCT FROM
           p_receipt.completed_at+interval '90 days' THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export running receipt evidence differs';
    END IF;
    IF p_receipt.effect_status='failed' THEN
        IF p_receipt.effect_error_class IS DISTINCT FROM v_expected_class OR
           p_receipt.effect_result_ref IS NOT NULL OR
           p_receipt.effect_result_sha256 IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export failure receipt differs';
        END IF;
        RETURN;
    END IF;
    v_result_state:=pg_catalog.split_part(p_receipt.effect_result_ref,'/',5);
    v_result_ref:='analytics-dashboard-export://'||v_operation||'/'||
        v_job.payload_ref||'/'||v_result_state;
    IF p_receipt.effect_error_class IS NOT NULL OR
       p_receipt.effect_result_ref IS DISTINCT FROM v_result_ref OR
       p_receipt.effect_result_sha256 IS DISTINCT FROM pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(v_result_ref,'UTF8')),'hex') OR
       (v_job.kind='analytics.dashboard.export.delete' AND
          v_result_state IS DISTINCT FROM 'deleted') OR
       (v_job.kind='analytics.dashboard.export.expire' AND
          v_result_state NOT IN ('expired','cancelled','failed','deleted')) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export success receipt differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_assert_analytics_dashboard_export_running_receip(p_receipt platform.idempotency_receipts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_current_authority_v1(text, uuid, text, bigint, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_current_authority_v1(p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_cutover_generation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_group_state text;
    v_group_writer text;
    v_group_generation bigint;
    v_domain_state text;
    v_domain_writer text;
    v_domain_generation bigint;
BEGIN
    IF p_scope_kind IS NULL OR p_scope_id IS NULL OR p_group_id IS NULL OR
       p_group_generation IS NULL OR p_domain IS NULL OR
       p_cutover_generation IS NULL OR
       NOT (p_scope_kind OPERATOR(pg_catalog.=) ANY (
           ARRAY['global','tenant']::text[]
       )) OR
       p_group_id OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_]{0,62}$' OR
       p_group_generation OPERATOR(pg_catalog.<) 1 OR
       p_domain OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_]{0,62}$' OR
       p_cutover_generation OPERATOR(pg_catalog.<) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async authority input is invalid';
    END IF;

    SELECT group_row.state, group_row.writer, group_row.generation
    INTO v_group_state, v_group_writer, v_group_generation
    FROM platform.cutover_groups AS group_row
    WHERE group_row.scope_kind OPERATOR(pg_catalog.=) p_scope_kind
      AND group_row.scope_id OPERATOR(pg_catalog.=) p_scope_id
      AND group_row.group_id OPERATOR(pg_catalog.=) p_group_id
    FOR SHARE;

    IF NOT FOUND OR v_group_state IS DISTINCT FROM 'v2' OR
       v_group_writer IS DISTINCT FROM 'v2' OR
       v_group_generation IS DISTINCT FROM p_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5601',
            MESSAGE = 'async group authority is stale';
    END IF;

    SELECT domain_row.state, domain_row.writer, domain_row.generation
    INTO v_domain_state, v_domain_writer, v_domain_generation
    FROM platform.domain_cutovers AS domain_row
    WHERE domain_row.scope_kind OPERATOR(pg_catalog.=) p_scope_kind
      AND domain_row.scope_id OPERATOR(pg_catalog.=) p_scope_id
      AND domain_row.domain OPERATOR(pg_catalog.=) p_domain
    FOR SHARE;

    IF NOT FOUND OR v_domain_state IS DISTINCT FROM 'v2' OR
       v_domain_writer IS DISTINCT FROM 'v2' OR
       v_domain_generation IS DISTINCT FROM p_cutover_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5602',
            MESSAGE = 'async domain authority is stale';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM platform.cutover_group_members AS member
        WHERE member.scope_kind OPERATOR(pg_catalog.=) p_scope_kind
          AND member.scope_id OPERATOR(pg_catalog.=) p_scope_id
          AND member.group_id OPERATOR(pg_catalog.=) p_group_id
          AND member.domain OPERATOR(pg_catalog.=) p_domain
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'async authority membership is missing';
    END IF;
END;
$_$;


ALTER FUNCTION platform.platform_async_assert_current_authority_v1(p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_cutover_generation bigint) OWNER TO harpy_owner;

--
-- Name: dead_letters; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.dead_letters (
    id uuid NOT NULL,
    root_id uuid NOT NULL,
    entry_sequence integer NOT NULL,
    record_kind text NOT NULL,
    tenant_id uuid,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    authority_group_id text NOT NULL,
    authority_group_generation bigint NOT NULL,
    authority_domain text NOT NULL,
    cutover_generation bigint NOT NULL,
    writer_origin text NOT NULL,
    source_kind text NOT NULL,
    source_id uuid NOT NULL,
    consumer_name text,
    consumer_version integer,
    source_contract text NOT NULL,
    source_version integer NOT NULL,
    source_sha256 text NOT NULL,
    reason_class text NOT NULL,
    reason_code text NOT NULL,
    redacted_error_sha256 text NOT NULL,
    payload_canonical bytea,
    payload_sha256 text NOT NULL,
    payload_redacted_at timestamp with time zone,
    redacted_envelope jsonb NOT NULL,
    action_reason text,
    action_ticket text,
    action_actor_id uuid,
    action_causation_id uuid,
    full_payload_expires_at timestamp with time zone NOT NULL,
    metadata_expires_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT dead_letters_action_text_check CHECK ((((action_reason IS NULL) AND (action_ticket IS NULL)) OR ((action_reason IS NOT NULL) AND (action_ticket IS NOT NULL) AND ((octet_length(action_reason) >= 1) AND (octet_length(action_reason) <= 2048)) AND ((octet_length(action_ticket) >= 1) AND (octet_length(action_ticket) <= 256))))),
    CONSTRAINT dead_letters_authority_domain_check CHECK ((authority_domain ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT dead_letters_authority_group_generation_check CHECK ((authority_group_generation > 0)),
    CONSTRAINT dead_letters_authority_group_id_check CHECK ((authority_group_id ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT dead_letters_consumer_name_check CHECK ((consumer_name ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT dead_letters_consumer_version_check CHECK ((consumer_version > 0)),
    CONSTRAINT dead_letters_cutover_generation_check CHECK ((cutover_generation > 0)),
    CONSTRAINT dead_letters_entry_sequence_check CHECK ((entry_sequence >= 0)),
    CONSTRAINT dead_letters_envelope_check CHECK (((jsonb_typeof(redacted_envelope) = 'object'::text) AND (octet_length((redacted_envelope)::text) <= 16384))),
    CONSTRAINT dead_letters_payload_canonical_check CHECK (((payload_canonical IS NULL) OR ((octet_length(payload_canonical) >= 2) AND (octet_length(payload_canonical) <= 131072)))),
    CONSTRAINT dead_letters_payload_hash_check CHECK (((payload_canonical IS NULL) OR ((jsonb_typeof((convert_from(payload_canonical, 'UTF8'::name))::jsonb) = 'object'::text) AND (payload_sha256 = encode(sha256(payload_canonical), 'hex'::text))))),
    CONSTRAINT dead_letters_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT dead_letters_reason_class_check CHECK ((reason_class = ANY (ARRAY['permanent'::text, 'unknown_version'::text, 'delivery_limit'::text, 'outcome_unknown'::text, 'stale_generation'::text, 'sequence_gap'::text]))),
    CONSTRAINT dead_letters_reason_code_check CHECK ((reason_code ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT dead_letters_record_kind_check CHECK ((record_kind = ANY (ARRAY['root'::text, 'retry_action'::text, 'repair_action'::text]))),
    CONSTRAINT dead_letters_redacted_error_sha256_check CHECK ((redacted_error_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT dead_letters_root_shape_check CHECK ((((record_kind = 'root'::text) AND (id = root_id) AND (entry_sequence = 0) AND (action_reason IS NULL) AND (action_ticket IS NULL) AND (action_actor_id IS NULL) AND (action_causation_id IS NULL) AND (((payload_canonical IS NOT NULL) AND (payload_redacted_at IS NULL)) OR ((payload_canonical IS NULL) AND (payload_redacted_at IS NOT NULL)))) OR ((record_kind = ANY (ARRAY['retry_action'::text, 'repair_action'::text])) AND (id <> root_id) AND (entry_sequence > 0) AND (payload_canonical IS NULL) AND (payload_redacted_at IS NULL) AND (action_reason IS NOT NULL) AND (action_ticket IS NOT NULL) AND (action_actor_id IS NOT NULL) AND (action_causation_id IS NOT NULL)))),
    CONSTRAINT dead_letters_scope_check CHECK ((((scope_kind = 'tenant'::text) AND (tenant_id IS NOT NULL) AND (tenant_id = scope_id)) OR ((scope_kind = 'global'::text) AND (tenant_id IS NULL)))),
    CONSTRAINT dead_letters_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT dead_letters_source_contract_check CHECK ((source_contract ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT dead_letters_source_kind_check CHECK ((source_kind = ANY (ARRAY['job'::text, 'event'::text]))),
    CONSTRAINT dead_letters_source_sha256_check CHECK ((source_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT dead_letters_source_shape_check CHECK ((((source_kind = 'job'::text) AND (consumer_name IS NULL) AND (consumer_version IS NULL)) OR ((source_kind = 'event'::text) AND (consumer_name IS NOT NULL) AND (consumer_version IS NOT NULL)))),
    CONSTRAINT dead_letters_source_version_check CHECK ((source_version > 0)),
    CONSTRAINT dead_letters_time_check CHECK (((full_payload_expires_at <= metadata_expires_at) AND (recorded_at < metadata_expires_at) AND ((record_kind <> 'root'::text) OR (recorded_at < full_payload_expires_at)) AND ((payload_redacted_at IS NULL) OR (full_payload_expires_at <= payload_redacted_at)))),
    CONSTRAINT dead_letters_writer_origin_check CHECK ((writer_origin = ANY (ARRAY['v1'::text, 'v2'::text])))
);


ALTER TABLE platform.dead_letters OWNER TO harpy_owner;

--
-- Name: platform_async_assert_cutover_dead_letter_v1(platform.dead_letters); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_cutover_dead_letter_v1(p_letter platform.dead_letters) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
BEGIN
    SELECT job.* INTO v_job FROM platform.jobs AS job
    JOIN platform.cutover_job_bindings AS binding ON binding.job_id=job.id
    WHERE job.id=p_letter.source_id FOR SHARE OF job,binding;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'cutover dead letter job is missing';
    END IF;
    PERFORM platform.platform_async_assert_job_row_authority_v1(v_job);
    IF p_letter.record_kind IS DISTINCT FROM 'root' OR
       p_letter.source_kind IS DISTINCT FROM 'job' OR
       p_letter.tenant_id IS DISTINCT FROM v_job.tenant_id OR
       p_letter.scope_kind IS DISTINCT FROM v_job.scope_kind OR
       p_letter.scope_id IS DISTINCT FROM v_job.scope_id OR
       p_letter.authority_group_id IS DISTINCT FROM v_job.authority_group_id OR
       p_letter.authority_group_generation IS DISTINCT FROM
           v_job.authority_group_generation OR
       p_letter.authority_domain IS DISTINCT FROM v_job.authority_domain OR
       p_letter.cutover_generation IS DISTINCT FROM v_job.cutover_generation OR
       p_letter.writer_origin IS DISTINCT FROM 'v2' OR
       p_letter.source_contract IS DISTINCT FROM v_job.kind OR
       p_letter.source_version IS DISTINCT FROM v_job.payload_revision OR
       p_letter.source_sha256 IS DISTINCT FROM v_job.payload_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'cutover dead letter differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_assert_cutover_dead_letter_v1(p_letter platform.dead_letters) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_cutover_effect_receipt_v1(platform.idempotency_receipts); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_cutover_effect_receipt_v1(p_receipt platform.idempotency_receipts) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
BEGIN
    SELECT job.* INTO v_job FROM platform.jobs AS job
    JOIN platform.cutover_job_bindings AS binding ON binding.job_id=job.id
    WHERE job.id=p_receipt.causation_id FOR SHARE OF job,binding;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'cutover effect receipt job is missing';
    END IF;
    PERFORM platform.platform_async_assert_job_row_authority_v1(v_job);
    IF p_receipt.record_kind IS DISTINCT FROM 'effect' OR
       p_receipt.tenant_id IS DISTINCT FROM v_job.tenant_id OR
       p_receipt.scope_kind IS DISTINCT FROM v_job.scope_kind OR
       p_receipt.scope_id IS DISTINCT FROM v_job.scope_id OR
       p_receipt.authority_group_id IS DISTINCT FROM v_job.authority_group_id OR
       p_receipt.authority_group_generation IS DISTINCT FROM
           v_job.authority_group_generation OR
       p_receipt.authority_domain IS DISTINCT FROM v_job.authority_domain OR
       p_receipt.cutover_generation IS DISTINCT FROM v_job.cutover_generation OR
       p_receipt.writer_origin IS DISTINCT FROM 'v2' OR
       p_receipt.effect_kind IS DISTINCT FROM v_job.kind OR
       p_receipt.effect_revision IS DISTINCT FROM v_job.payload_revision OR
       p_receipt.effect_key IS DISTINCT FROM v_job.effect_idempotency_key OR
       p_receipt.provider IS DISTINCT FROM 'documents.adoption' OR
       p_receipt.operation IS DISTINCT FROM 'copy' OR NOT EXISTS (
           SELECT 1 FROM platform.job_attempts AS attempt
           WHERE attempt.job_id=v_job.id AND attempt.finished_at IS NULL
             AND attempt.effect_id=p_receipt.effect_id
             AND attempt.effect_request_sha256=p_receipt.request_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'cutover effect receipt differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_assert_cutover_effect_receipt_v1(p_receipt platform.idempotency_receipts) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_cutover_shadow_authority_v1(text, uuid, text, bigint, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_cutover_shadow_authority_v1(p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_cutover_generation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_scope_kind IS DISTINCT FROM 'tenant' OR p_scope_id IS NULL OR
       p_group_id IS DISTINCT FROM 'documents' OR p_group_generation < 1 OR
       p_domain IS DISTINCT FROM 'documents' OR p_cutover_generation < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'cutover shadow authority input is invalid';
    END IF;
    PERFORM 1
    FROM platform.cutover_job_bindings AS binding
    JOIN platform.cutover_operations AS operation
      ON operation.operation_id=binding.operation_id
     AND operation.run_id=binding.cutover_run_id
    JOIN platform.cutover_groups AS group_row
      ON group_row.scope_kind=operation.scope_kind
     AND group_row.scope_id=operation.scope_id
     AND group_row.group_id=operation.group_id
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=operation.scope_kind
     AND domain_row.scope_id=operation.scope_id
     AND domain_row.domain=operation.domain
    JOIN platform.cutover_group_members AS member
      ON member.scope_kind=operation.scope_kind
     AND member.scope_id=operation.scope_id
     AND member.group_id=operation.group_id
     AND member.domain=operation.domain
    WHERE binding.tenant_id=p_scope_id
      AND binding.group_id=p_group_id
      AND binding.group_generation=p_group_generation
      AND binding.domain=p_domain
      AND binding.cutover_generation=p_cutover_generation
      AND operation.scope_kind=p_scope_kind
      AND operation.scope_id=p_scope_id
      AND operation.group_id=p_group_id
      AND operation.domain=p_domain
      AND operation.cutover_generation=p_cutover_generation
      AND operation.lease_manifest_sha256=binding.lease_manifest_sha256
      AND operation.state IN ('copying','shadow')
      AND operation.lease_expires_at>pg_catalog.clock_timestamp()
      AND group_row.state IN ('v1','shadow') AND group_row.writer='v1'
      AND group_row.generation=p_group_generation
      AND domain_row.state IN ('v1','shadow') AND domain_row.writer='v1'
      AND domain_row.generation=p_cutover_generation
    LIMIT 1
    FOR SHARE OF binding,operation,group_row,domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5601',
            MESSAGE = 'cutover shadow authority is stale';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_assert_cutover_shadow_authority_v1(p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_cutover_generation bigint) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_job_id_authority_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_job_id_authority_v1(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
BEGIN
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603', MESSAGE = 'job is missing';
    END IF;
    PERFORM platform.platform_async_assert_job_row_authority_v1(v_job);
END;
$$;


ALTER FUNCTION platform.platform_async_assert_job_id_authority_v1(p_job_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_job_row_authority_v1(platform.jobs); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_job_row_authority_v1(p_job platform.jobs) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_bound boolean;
BEGIN
    SELECT pg_catalog.count(*)=1 INTO v_bound
    FROM platform.cutover_job_bindings AS binding
    WHERE binding.job_id=p_job.id;
    IF v_bound THEN
        PERFORM platform.platform_async_assert_cutover_shadow_authority_v1(
            p_job.scope_kind,p_job.scope_id,p_job.authority_group_id,
            p_job.authority_group_generation,p_job.authority_domain,
            p_job.cutover_generation);
        IF p_job.scope_kind IS DISTINCT FROM 'tenant' OR
           p_job.tenant_id IS DISTINCT FROM p_job.scope_id OR
           p_job.writer_origin IS DISTINCT FROM 'v2' OR
           p_job.kind IS DISTINCT FROM 'documents.adoption.copy' OR
           p_job.payload_revision IS DISTINCT FROM 1 OR
           p_job.effect_class IS DISTINCT FROM 'external' OR
           p_job.payload_ref IS NULL OR p_job.effect_idempotency_key IS NULL OR
           NOT EXISTS (
               SELECT 1 FROM platform.cutover_job_bindings AS binding
               WHERE binding.job_id=p_job.id
                 AND binding.tenant_id=p_job.scope_id
                 AND binding.group_id=p_job.authority_group_id
                 AND binding.group_generation=p_job.authority_group_generation
                 AND binding.domain=p_job.authority_domain
                 AND binding.cutover_generation=p_job.cutover_generation
                 AND binding.job_kind=p_job.kind
                 AND binding.payload_revision=p_job.payload_revision
                 AND binding.payload_ref=p_job.payload_ref
                 AND binding.payload_sha256=p_job.payload_sha256
                 AND binding.effect_idempotency_key=p_job.effect_idempotency_key
           ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5603',
                MESSAGE = 'cutover shadow job binding differs';
        END IF;
        RETURN;
    END IF;
    IF p_job.kind='documents.adoption.copy' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'Documents adoption copy job is unbound';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        p_job.scope_kind,p_job.scope_id,p_job.authority_group_id,
        p_job.authority_group_generation,p_job.authority_domain,
        p_job.cutover_generation);
END;
$$;


ALTER FUNCTION platform.platform_async_assert_job_row_authority_v1(p_job platform.jobs) OWNER TO harpy_owner;

--
-- Name: platform_async_assert_worker_authority_v1(text, uuid, text, bigint, text, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_assert_worker_authority_v1(p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_cutover_generation bigint, p_mode text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_mode='v2' THEN
        PERFORM platform.platform_async_assert_current_authority_v1(
            p_scope_kind,p_scope_id,p_group_id,p_group_generation,
            p_domain,p_cutover_generation);
    ELSIF p_mode='cutover_shadow' THEN
        PERFORM platform.platform_async_assert_cutover_shadow_authority_v1(
            p_scope_kind,p_scope_id,p_group_id,p_group_generation,
            p_domain,p_cutover_generation);
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'job authority mode is invalid';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_assert_worker_authority_v1(p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_cutover_generation bigint, p_mode text) OWNER TO harpy_owner;

--
-- Name: platform_async_begin_v1_adoption_v1(uuid, text, uuid, text, text, bigint, bigint, bigint, bigint, text, text, smallint, smallint, smallint, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_begin_v1_adoption_v1(p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_domain text, p_group_id text, p_source_generation bigint, p_target_generation bigint, p_source_group_generation bigint, p_target_group_generation bigint, p_inventory_sha256 text, p_component_manifest_sha256 text, p_expected_enqueue_fences smallint, p_expected_scheduler_fences smallint, p_expected_consumer_fences smallint, p_item_count bigint, p_captured_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_group_state text;
    v_group_writer text;
    v_group_generation bigint;
    v_domain_state text;
    v_domain_writer text;
    v_domain_generation bigint;
    v_inserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5632',
            MESSAGE = 'V1 async adoption requires adopter authority';
    END IF;
    SELECT state, writer, generation
    INTO v_group_state, v_group_writer, v_group_generation
    FROM platform.cutover_groups
    WHERE scope_kind OPERATOR(pg_catalog.=) p_scope_kind
      AND scope_id OPERATOR(pg_catalog.=) p_scope_id
      AND group_id OPERATOR(pg_catalog.=) p_group_id
    FOR SHARE;
    IF NOT FOUND OR v_group_state IS DISTINCT FROM 'quiescing' OR
       v_group_writer IS DISTINCT FROM 'none' OR
       v_group_generation IS DISTINCT FROM p_source_group_generation OR
       p_target_group_generation IS DISTINCT FROM p_source_group_generation + 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5633',
            MESSAGE = 'V1 async adoption group is not quiesced';
    END IF;
    SELECT state, writer, generation
    INTO v_domain_state, v_domain_writer, v_domain_generation
    FROM platform.domain_cutovers
    WHERE scope_kind OPERATOR(pg_catalog.=) p_scope_kind
      AND scope_id OPERATOR(pg_catalog.=) p_scope_id
      AND domain OPERATOR(pg_catalog.=) p_domain
    FOR SHARE;
    IF NOT FOUND OR v_domain_state IS DISTINCT FROM 'quiescing' OR
       v_domain_writer IS DISTINCT FROM 'none' OR
       v_domain_generation IS DISTINCT FROM p_source_generation OR
       p_target_generation IS DISTINCT FROM p_source_generation + 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5634',
            MESSAGE = 'V1 async adoption domain is not quiesced';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind OPERATOR(pg_catalog.=) p_scope_kind
          AND scope_id OPERATOR(pg_catalog.=) p_scope_id
          AND group_id OPERATOR(pg_catalog.=) p_group_id
          AND domain OPERATOR(pg_catalog.=) p_domain
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5635',
            MESSAGE = 'V1 async adoption group membership is missing';
    END IF;
    INSERT INTO platform.async_v1_adoption_runs (
        run_id, scope_kind, scope_id, domain, group_id,
        source_generation, target_generation,
        source_group_generation, target_group_generation,
        inventory_contract_version, inventory_revision, inventory_sha256,
        component_manifest_sha256, expected_enqueue_fences,
        expected_scheduler_fences, expected_consumer_fences,
        item_count, state, captured_at
    ) VALUES (
        p_run_id, p_scope_kind, p_scope_id, p_domain, p_group_id,
        p_source_generation, p_target_generation,
        p_source_group_generation, p_target_group_generation,
        'async-adoption-inventory.v1', 1, p_inventory_sha256,
        p_component_manifest_sha256, p_expected_enqueue_fences,
        p_expected_scheduler_fences, p_expected_consumer_fences,
        p_item_count, 'inventory', p_captured_at
    ) ON CONFLICT DO NOTHING RETURNING true INTO v_inserted;
    IF NOT COALESCE(v_inserted, false) AND NOT EXISTS (
        SELECT 1 FROM platform.async_v1_adoption_runs AS run
        WHERE run.run_id OPERATOR(pg_catalog.=) p_run_id
          AND run.scope_kind OPERATOR(pg_catalog.=) p_scope_kind
          AND run.scope_id OPERATOR(pg_catalog.=) p_scope_id
          AND run.domain OPERATOR(pg_catalog.=) p_domain
          AND run.group_id OPERATOR(pg_catalog.=) p_group_id
          AND run.source_generation OPERATOR(pg_catalog.=) p_source_generation
          AND run.target_generation OPERATOR(pg_catalog.=) p_target_generation
          AND run.source_group_generation OPERATOR(pg_catalog.=) p_source_group_generation
          AND run.target_group_generation OPERATOR(pg_catalog.=) p_target_group_generation
          AND run.inventory_sha256 OPERATOR(pg_catalog.=) p_inventory_sha256
          AND run.component_manifest_sha256 OPERATOR(pg_catalog.=) p_component_manifest_sha256
          AND run.item_count OPERATOR(pg_catalog.=) p_item_count
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5636',
            MESSAGE = 'V1 async adoption run replay differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_begin_v1_adoption_v1(p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_domain text, p_group_id text, p_source_generation bigint, p_target_generation bigint, p_source_group_generation bigint, p_target_group_generation bigint, p_inventory_sha256 text, p_component_manifest_sha256 text, p_expected_enqueue_fences smallint, p_expected_scheduler_fences smallint, p_expected_consumer_fences smallint, p_item_count bigint, p_captured_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_cancel_v1_inventory_item_v1(uuid, text, text, text, text, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_cancel_v1_inventory_item_v1(p_run_id uuid, p_inventory_class text, p_source_name text, p_source_item_id text, p_item_sha256 text, p_reason_code text, p_reason text, p_ticket text, p_disposed_at timestamp with time zone, p_receipt_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run_state text;
    v_item platform.async_v1_adoption_items%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5650',
            MESSAGE = 'V1 async item cancellation requires adopter authority';
    END IF;
    SELECT state INTO v_run_state FROM platform.async_v1_adoption_runs
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id FOR UPDATE;
    SELECT * INTO v_item FROM platform.async_v1_adoption_items
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id
      AND inventory_class OPERATOR(pg_catalog.=) p_inventory_class
      AND source_name OPERATOR(pg_catalog.=) p_source_name
      AND source_item_id OPERATOR(pg_catalog.=) p_source_item_id
    FOR SHARE;
    IF v_run_state IS DISTINCT FROM 'disposing' OR NOT FOUND OR
       v_item.item_sha256 IS DISTINCT FROM p_item_sha256 OR
       p_reason_code IS NULL OR p_reason IS NULL OR p_ticket IS NULL OR
       p_disposed_at < v_item.captured_at OR
       p_disposed_at > pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE = 'P5651',
            MESSAGE = 'V1 async cancellation evidence is invalid';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.async_v1_adoption_dispositions
        WHERE run_id OPERATOR(pg_catalog.=) p_run_id
          AND inventory_class OPERATOR(pg_catalog.=) p_inventory_class
          AND source_name OPERATOR(pg_catalog.=) p_source_name
          AND source_item_id OPERATOR(pg_catalog.=) p_source_item_id
          AND disposition OPERATOR(pg_catalog.=) 'cancelled'
          AND reason_code OPERATOR(pg_catalog.=) p_reason_code
          AND reason OPERATOR(pg_catalog.=) p_reason
          AND ticket OPERATOR(pg_catalog.=) p_ticket
          AND receipt_sha256 OPERATOR(pg_catalog.=) p_receipt_sha256
    ) THEN
        RETURN;
    END IF;
    INSERT INTO platform.async_v1_adoption_dispositions (
        run_id, inventory_class, source_name, source_item_id,
        item_sha256, idempotency_identity, disposition,
        reason_code, reason, ticket, disposed_at, receipt_sha256
    ) VALUES (
        p_run_id, p_inventory_class, p_source_name, p_source_item_id,
        p_item_sha256, v_item.idempotency_identity, 'cancelled',
        p_reason_code, p_reason, p_ticket, p_disposed_at, p_receipt_sha256
    );
END;
$$;


ALTER FUNCTION platform.platform_async_cancel_v1_inventory_item_v1(p_run_id uuid, p_inventory_class text, p_source_name text, p_source_item_id text, p_item_sha256 text, p_reason_code text, p_reason text, p_ticket text, p_disposed_at timestamp with time zone, p_receipt_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_complete_event_gap_job_v1(platform.jobs, uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_complete_event_gap_job_v1(p_job platform.jobs, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_completed_at timestamptz;
    v_count bigint;
BEGIN
    v_completed_at := GREATEST(
        pg_catalog.clock_timestamp(),p_job.updated_at + interval '1 microsecond'
    );
    UPDATE platform.job_attempts AS attempt
    SET finished_at = v_completed_at,outcome = 'succeeded'
    WHERE attempt.attempt_id = p_attempt_id
      AND attempt.job_id = p_job.id
      AND attempt.lease_owner_id = p_lease_owner_id
      AND attempt.lease_generation = p_lease_generation
      AND attempt.finished_at IS NULL
      AND attempt.effect_started_at IS NULL
      AND attempt.effect_receipt_id IS NULL;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5695',
            MESSAGE = 'event gap attempt completion failed';
    END IF;

    UPDATE platform.jobs AS job
    SET state = 'succeeded',lease_owner_id = NULL,
        lease_heartbeat_at = NULL,lease_until = NULL,
        last_error_class = NULL,last_error_code = NULL,last_error_sha256 = NULL,
        retain_until = v_completed_at + interval '90 days',
        updated_at = v_completed_at,completed_at = v_completed_at
    WHERE job.id = p_job.id AND job.state = 'running'
      AND job.lease_owner_id = p_lease_owner_id
      AND job.lease_generation = p_lease_generation;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5696',
            MESSAGE = 'event gap job completion failed';
    END IF;
    RETURN v_completed_at;
END;
$$;


ALTER FUNCTION platform.platform_async_complete_event_gap_job_v1(p_job platform.jobs, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) OWNER TO harpy_owner;

--
-- Name: platform_async_cutover_shadow_operation_active_v1(uuid, uuid, text, uuid, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_cutover_shadow_operation_active_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_group_id text, p_domain text, p_cutover_generation bigint, p_manifest_sha256 text, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_active boolean;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM platform.cutover_operations AS operation
        WHERE operation.operation_id=p_operation_id
          AND operation.run_id=p_run_id
          AND operation.scope_kind=p_scope_kind
          AND operation.scope_id=p_scope_id
          AND operation.group_id=p_group_id
          AND operation.domain=p_domain
          AND operation.cutover_generation=p_cutover_generation
          AND operation.lease_manifest_sha256=p_manifest_sha256
          AND operation.state IN ('copying','shadow')
          AND operation.lease_expires_at>p_observed_at
    ) INTO v_active;
    RETURN v_active;
END;
$$;


ALTER FUNCTION platform.platform_async_cutover_shadow_operation_active_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_group_id text, p_domain text, p_cutover_generation bigint, p_manifest_sha256 text, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_dispose_stale_job_v1(uuid, text, uuid, uuid, uuid, uuid, text, uuid, text, bigint, text, bigint, text, text, bytea, text, text, text, uuid, uuid, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_dispose_stale_job_v1(p_job_id uuid, p_action text, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_result_gap_root_id uuid, p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_domain_generation bigint, p_result_payload_ref text, p_result_dedupe_key text, p_payload_canonical bytea, p_payload_sha256 text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid, p_source_run_at text, p_result_run_at text, p_occurred_at text) RETURNS TABLE(completed_at timestamp with time zone, action_id uuid, result_job_id uuid, result_root_id uuid, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_result platform.jobs%ROWTYPE;
    v_now timestamptz;
    v_recorded_at timestamptz;
    v_replay_root_id uuid;
    v_replay_payload_ref text;
    v_replay_dedupe_key text;
    v_replay_run_at text;
    v_payload_ref text;
    v_code text;
    v_error_sha256 text;
    v_is_gap boolean;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_job_id IS NULL OR p_root_id IS NULL OR p_action_id IS NULL OR
       p_action NOT IN ('adopt','cancel') OR
       NOT ((p_action = 'adopt' AND p_result_job_id IS NOT NULL) OR
            (p_action = 'cancel' AND p_result_job_id IS NULL AND
             p_result_gap_root_id IS NULL AND p_result_payload_ref IS NULL AND
             p_result_dedupe_key IS NULL AND p_result_run_at IS NULL)) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5687',
            MESSAGE = 'stale job disposition input is invalid';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        p_scope_kind,p_scope_id,p_group_id,p_group_generation,
        p_domain,p_domain_generation
    );
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id = p_job_id FOR UPDATE;
    IF NOT FOUND OR ROW(v_job.scope_kind,v_job.scope_id,
            v_job.authority_group_id,v_job.authority_domain)
        IS DISTINCT FROM ROW(p_scope_kind,p_scope_id,p_group_id,p_domain) OR
       p_group_generation < v_job.authority_group_generation OR
       p_domain_generation < v_job.cutover_generation OR
       (p_group_generation = v_job.authority_group_generation AND
        p_domain_generation = v_job.cutover_generation) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5688',
            MESSAGE = 'stale job disposition authority conflicts';
    END IF;
    IF p_source_run_at IS NULL OR p_source_run_at !~ 'Z$' OR
       p_source_run_at::timestamptz <> v_job.run_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5687',
            MESSAGE = 'stale job source schedule is invalid';
    END IF;
    v_code := CASE p_action WHEN 'adopt' THEN
        'JOB_AUTHORITY_STALE_ADOPTED' ELSE 'JOB_AUTHORITY_STALE_CANCELLED' END;
    v_error_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        v_code || E'\n' || p_reason || E'\n' || p_ticket,'UTF8')),'hex');
    IF v_job.state = 'cancelled' THEN
        SELECT replay.recorded_at,replay.result_root_id,
            replay.result_payload_ref,replay.result_dedupe_key,
            replay.result_run_at
        INTO STRICT v_recorded_at,v_replay_root_id,v_replay_payload_ref,
            v_replay_dedupe_key,v_replay_run_at
        FROM platform.platform_async_verify_stale_job_disposition_replay_v1(
            v_job,p_root_id,p_action_id,p_result_job_id,p_group_generation,
            p_domain_generation,p_action,p_reason,p_ticket,p_actor_id,
            p_causation_id
        ) AS replay;
        RETURN QUERY SELECT v_recorded_at,p_action_id,p_result_job_id,
            v_replay_root_id,false;
        RETURN;
    END IF;
    IF v_job.state <> 'queued' OR v_job.parked_at IS NULL OR
       v_job.parked_code <> 'JOB_AUTHORITY_STALE' OR
       v_job.effect_started_at IS NOT NULL OR v_job.payload_ref IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5689',
            MESSAGE = 'stale job is not dispositionable';
    END IF;
    IF p_action = 'adopt' AND (p_result_payload_ref IS NULL OR
       p_result_dedupe_key IS NULL OR p_result_run_at IS NULL OR
       p_result_run_at !~ 'Z$' OR p_result_run_at::timestamptz <>
           GREATEST(v_job.run_at,v_now)) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5687',
            MESSAGE = 'stale job adoption input is invalid';
    END IF;
    v_is_gap := v_job.kind = 'platform_async.event_gap_reconcile.' ||
        v_job.authority_domain AND v_job.payload_ref LIKE 'deadletter:event-gap:%';
    v_payload_ref := v_job.payload_ref;
    IF p_action = 'adopt' AND v_is_gap THEN
        IF p_result_gap_root_id IS NULL OR p_result_payload_ref IS DISTINCT FROM
            'deadletter:event-gap:' || p_result_gap_root_id::text THEN
            RAISE EXCEPTION USING ERRCODE = 'P5687',
                MESSAGE = 'stale event gap replacement identity is invalid';
        END IF;
        v_payload_ref := platform.platform_async_reissue_stale_event_gap_v1(
            v_job,p_result_gap_root_id,p_group_generation,p_domain_generation,v_now);
    ELSIF p_action = 'adopt' AND (p_result_gap_root_id IS NOT NULL OR
            p_result_payload_ref IS DISTINCT FROM v_job.payload_ref) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5687',
            MESSAGE = 'stale job replacement payload is invalid';
    END IF;
    PERFORM platform.platform_async_record_stale_job_disposition_v1(
        v_job,p_root_id,p_action_id,p_result_job_id,p_result_gap_root_id,
        p_result_payload_ref,p_result_dedupe_key,p_group_generation,
        p_domain_generation,p_action,p_payload_canonical,p_payload_sha256,
        p_reason,p_ticket,p_actor_id,p_causation_id,p_source_run_at,
        p_result_run_at,p_occurred_at,v_now
    );
    IF p_action = 'adopt' THEN
        INSERT INTO platform.jobs (
            id,tenant_id,scope_kind,scope_id,authority_group_id,
            authority_group_generation,authority_domain,cutover_generation,
            writer_origin,kind,payload_revision,payload_ref,payload_sha256,
            dedupe_key,effect_class,effect_idempotency_key,priority,run_at,
            state,attempts,max_attempts,lease_generation,retry_of_job_id,
            created_at,updated_at
        ) VALUES (
            p_result_job_id,v_job.tenant_id,v_job.scope_kind,v_job.scope_id,
            v_job.authority_group_id,p_group_generation,v_job.authority_domain,
            p_domain_generation,'v2',v_job.kind,v_job.payload_revision,
            v_payload_ref,v_job.payload_sha256,p_result_dedupe_key,
            v_job.effect_class,v_job.effect_idempotency_key,v_job.priority,
            p_result_run_at::timestamptz,'queued',0,v_job.max_attempts,0,
            v_job.id,v_now,v_now
        ) ON CONFLICT DO NOTHING;
        SELECT result.* INTO v_result FROM platform.jobs AS result
        WHERE ROW(result.id,result.tenant_id,result.scope_kind,result.scope_id,
            result.authority_group_id,result.authority_group_generation,
            result.authority_domain,result.cutover_generation,
            result.writer_origin,result.kind,result.payload_revision,
            result.payload_ref,result.payload_sha256,result.dedupe_key,
            result.effect_class,result.effect_idempotency_key,result.priority,
            result.run_at,result.max_attempts,result.retry_of_job_id,
            result.created_at,result.updated_at)
          IS NOT DISTINCT FROM ROW(p_result_job_id,v_job.tenant_id,
            v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
            p_group_generation,v_job.authority_domain,p_domain_generation,'v2',
            v_job.kind,v_job.payload_revision,v_payload_ref,v_job.payload_sha256,
            p_result_dedupe_key,v_job.effect_class,v_job.effect_idempotency_key,
            v_job.priority,p_result_run_at::timestamptz,v_job.max_attempts,
            v_job.id,v_now,v_now)
          AND result.state = 'queued' AND result.attempts = 0
          AND result.lease_generation = 0 AND result.lease_owner_id IS NULL
          AND result.parked_at IS NULL AND result.effect_started_at IS NULL
          AND result.last_error_code IS NULL AND result.completed_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = 'P5689',
                MESSAGE = 'stale job replacement conflicts';
        END IF;
    END IF;
    UPDATE platform.jobs SET state = 'cancelled',last_error_class = 'cancelled',
        last_error_code = v_code,last_error_sha256 = v_error_sha256,
        retain_until = v_now + interval '90 days',completed_at = v_now,
        updated_at = v_now WHERE id = v_job.id;
    RETURN QUERY SELECT v_now,p_action_id,p_result_job_id,
        p_result_gap_root_id,true;
END;
$_$;


ALTER FUNCTION platform.platform_async_dispose_stale_job_v1(p_job_id uuid, p_action text, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_result_gap_root_id uuid, p_scope_kind text, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_domain text, p_domain_generation bigint, p_result_payload_ref text, p_result_dedupe_key text, p_payload_canonical bytea, p_payload_sha256 text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid, p_source_run_at text, p_result_run_at text, p_occurred_at text) OWNER TO harpy_owner;

--
-- Name: platform_async_enqueue_documents_cutover_copy_v1(uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_enqueue_documents_cutover_copy_v1(p_operation_id uuid, p_cutover_run_id uuid, p_adoption_run_id uuid, p_source_version_id uuid, p_job_id uuid, p_enqueued_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.cutover_operations%ROWTYPE;
    v_group_generation bigint;
    v_payload_ref text;
    v_payload_sha256 text;
    v_effect_key text;
    v_document bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.uuid_extract_version(p_adoption_run_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_source_version_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       p_enqueued_at IS NULL OR p_enqueued_at>pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Documents cutover enqueue authority is invalid';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id
      AND operation.run_id=p_cutover_run_id
      AND operation.scope_kind='tenant'
      AND operation.group_id='documents' AND operation.domain='documents'
      AND operation.state IN ('copying','shadow')
      AND operation.lease_expires_at>pg_catalog.clock_timestamp()
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5601',
            MESSAGE = 'Documents cutover operation is stale';
    END IF;
    SELECT group_row.generation INTO v_group_generation
    FROM platform.cutover_groups AS group_row
    JOIN platform.domain_cutovers AS domain_row
      ON domain_row.scope_kind=group_row.scope_kind
     AND domain_row.scope_id=group_row.scope_id
     AND domain_row.domain='documents'
    JOIN platform.cutover_group_members AS member
      ON member.scope_kind=group_row.scope_kind
     AND member.scope_id=group_row.scope_id
     AND member.group_id=group_row.group_id
     AND member.domain=domain_row.domain
    WHERE group_row.scope_kind='tenant'
      AND group_row.scope_id=v_operation.scope_id
      AND group_row.group_id='documents'
      AND group_row.state IN ('v1','shadow') AND group_row.writer='v1'
      AND domain_row.state IN ('v1','shadow') AND domain_row.writer='v1'
      AND domain_row.generation=v_operation.cutover_generation
    FOR SHARE OF group_row,domain_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5602',
            MESSAGE = 'Documents shadow writer authority is stale';
    END IF;
    v_payload_ref := 'documents/v1/adoption-copy/'||v_operation.scope_id::text||
        '/'||p_adoption_run_id::text||'/'||p_source_version_id::text||'/'||
        v_operation.cutover_generation::text||'/'||v_operation.lease_manifest_sha256;
    v_document := pg_catalog.convert_to('{"run_id":"'||p_adoption_run_id::text||
        '","source_version_id":"'||p_source_version_id::text||
        '","cutover_generation":'||v_operation.cutover_generation::text||
        ',"manifest_sha256":"'||v_operation.lease_manifest_sha256||'"}','UTF8');
    v_payload_sha256 := pg_catalog.encode(pg_catalog.sha256(v_document),'hex');
    v_effect_key := 'documents:adoption-copy:'||p_adoption_run_id::text||':'||
        p_source_version_id::text;
    INSERT INTO platform.cutover_job_bindings (
        job_id,operation_id,cutover_run_id,tenant_id,group_id,group_generation,
        domain,cutover_generation,lease_manifest_sha256,adoption_run_id,
        source_version_id,job_kind,payload_revision,payload_ref,payload_sha256,
        effect_idempotency_key,enqueued_at
    ) VALUES (
        p_job_id,p_operation_id,p_cutover_run_id,v_operation.scope_id,
        'documents',v_group_generation,'documents',v_operation.cutover_generation,
        v_operation.lease_manifest_sha256,p_adoption_run_id,p_source_version_id,
        'documents.adoption.copy',1,v_payload_ref,v_payload_sha256,v_effect_key,
        p_enqueued_at
    ) ON CONFLICT DO NOTHING;
    INSERT INTO platform.jobs (
        id,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,
        writer_origin,kind,payload_revision,payload_ref,payload_sha256,dedupe_key,
        effect_class,effect_idempotency_key,priority,run_at,state,attempts,
        max_attempts,lease_generation
    ) VALUES (
        p_job_id,v_operation.scope_id,'tenant',v_operation.scope_id,'documents',
        v_group_generation,'documents',v_operation.cutover_generation,'v2',
        'documents.adoption.copy',1,v_payload_ref,v_payload_sha256,v_effect_key,
        'external',v_effect_key,100,p_enqueued_at,'queued',0,8,0
    ) ON CONFLICT DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM platform.cutover_job_bindings AS binding
        JOIN platform.jobs AS job ON job.id=binding.job_id
        WHERE binding.job_id=p_job_id AND binding.operation_id=p_operation_id
          AND binding.cutover_run_id=p_cutover_run_id
          AND binding.adoption_run_id=p_adoption_run_id
          AND binding.source_version_id=p_source_version_id
          AND binding.payload_ref=v_payload_ref
          AND binding.payload_sha256=v_payload_sha256
          AND binding.effect_idempotency_key=v_effect_key
          AND job.scope_id=v_operation.scope_id AND job.kind=binding.job_kind
          AND job.payload_ref=binding.payload_ref
          AND job.payload_sha256=binding.payload_sha256
          AND job.effect_idempotency_key=binding.effect_idempotency_key
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5603',
            MESSAGE = 'Documents cutover enqueue replay differs';
    END IF;
    RETURN p_job_id;
END;
$$;


ALTER FUNCTION platform.platform_async_enqueue_documents_cutover_copy_v1(p_operation_id uuid, p_cutover_run_id uuid, p_adoption_run_id uuid, p_source_version_id uuid, p_job_id uuid, p_enqueued_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_event_gap_job_ready_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_event_gap_job_ready_v1(p_job_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN (
SELECT CASE
    WHEN pg_catalog.left(
        job.kind, pg_catalog.length('platform_async.event_gap_reconcile.')
    ) <> 'platform_async.event_gap_reconcile.' THEN true
    WHEN job.kind IS DISTINCT FROM
        ('platform_async.event_gap_reconcile.' || job.authority_domain) THEN false
    ELSE EXISTS (
        SELECT 1
        FROM platform.dead_letters AS root
        JOIN platform.outbox AS event ON event.event_id = root.source_id
        CROSS JOIN LATERAL (
            SELECT pg_catalog.convert_from(root.payload_canonical, 'UTF8')::jsonb AS value
        ) AS gap
        WHERE root.id::text = pg_catalog.substr(
                job.payload_ref, pg_catalog.length('deadletter:event-gap:') + 1
            )
          AND job.payload_ref = 'deadletter:event-gap:' || root.id::text
          AND root.record_kind = 'root' AND root.source_kind = 'event'
          AND root.reason_class = 'sequence_gap'
          AND root.reason_code = 'EVENT_SEQUENCE_GAP'
          AND root.payload_canonical IS NOT NULL
          AND root.payload_redacted_at IS NULL
          AND ROW(root.tenant_id,root.scope_kind,root.scope_id,
              root.authority_group_id,root.authority_group_generation,
              root.authority_domain,root.cutover_generation,root.writer_origin,
              root.source_sha256)
              = ROW(job.tenant_id,job.scope_kind,job.scope_id,
                  job.authority_group_id,job.authority_group_generation,
                  job.authority_domain,job.cutover_generation,'v2',job.payload_sha256)
          AND gap.value->>'contract_version' = 'event-sequence-gap.v1'
          AND gap.value->>'consumer' = root.consumer_name
          AND (gap.value->>'consumer_version')::integer = root.consumer_version
          AND (gap.value->>'received_sequence')::bigint = event.event_sequence
          AND gap.value->'envelope'->>'event_id' = event.event_id::text
          AND gap.value->'envelope'->>'event_type' = event.event_type
          AND (gap.value->'envelope'->>'event_version')::integer = event.event_version
          AND gap.value->'envelope'->>'aggregate_type' = event.aggregate_type
          AND gap.value->'envelope'->>'aggregate_id' = event.aggregate_id::text
          AND (gap.value->'envelope'->>'event_sequence')::bigint = event.event_sequence
          AND gap.value->'envelope'->>'payload_sha256' = event.payload_sha256
          AND event.payload_canonical IS NOT NULL
          AND gap.value->'envelope'->'payload' =
              pg_catalog.convert_from(event.payload_canonical, 'UTF8')::jsonb
          AND (
              EXISTS (
                  SELECT 1
                  FROM platform.inbox AS receipt
                  WHERE receipt.record_kind = 'event_receipt'
                    AND receipt.consumer_name = root.consumer_name
                    AND receipt.consumer_version = root.consumer_version
                    AND receipt.scope_kind = root.scope_kind
                    AND receipt.scope_id = root.scope_id
                    AND receipt.event_id = root.source_id
              ) OR (
                  SELECT COALESCE(pg_catalog.max(mark.through_sequence), 0)
                  FROM platform.inbox AS mark
                  WHERE mark.consumer_name = root.consumer_name
                    AND mark.consumer_version = root.consumer_version
                    AND mark.scope_kind = root.scope_kind
                    AND mark.scope_id = root.scope_id
                    AND mark.aggregate_type = event.aggregate_type
                    AND mark.aggregate_id = event.aggregate_id
              ) = event.event_sequence - 1
          )
    )
END
FROM platform.jobs AS job
WHERE job.id = p_job_id
);
END;
$$;


ALTER FUNCTION platform.platform_async_event_gap_job_ready_v1(p_job_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_event_gap_job_ready_v2(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_event_gap_job_ready_v2(p_job_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_event platform.outbox%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5690',
            MESSAGE = 'event gap readiness authority is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job WHERE job.id = p_job_id;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    IF pg_catalog.left(v_job.kind,
            pg_catalog.length('platform_async.event_gap_reconcile.')) <>
            'platform_async.event_gap_reconcile.' THEN
        RETURN true;
    END IF;
    IF v_job.kind IS DISTINCT FROM
        ('platform_async.event_gap_reconcile.' || v_job.authority_domain) THEN
        RETURN false;
    END IF;
    IF platform.platform_async_event_gap_job_ready_v1(p_job_id) THEN
        RETURN true;
    END IF;
    SELECT event.* INTO v_event
    FROM platform.dead_letters AS root
    JOIN platform.outbox AS event ON event.event_id = root.source_id
    CROSS JOIN LATERAL (
        SELECT pg_catalog.convert_from(root.payload_canonical,'UTF8')::jsonb AS value
    ) AS gap
    WHERE v_job.payload_ref = 'deadletter:event-gap:' || root.id::text
      AND root.record_kind = 'root' AND root.source_kind = 'event'
      AND root.reason_class = 'sequence_gap'
      AND root.reason_code = 'EVENT_SEQUENCE_GAP'
      AND root.payload_canonical IS NOT NULL
      AND root.payload_redacted_at IS NULL
      AND ROW(root.tenant_id,root.scope_kind,root.scope_id,
          root.authority_group_id,root.authority_group_generation,
          root.authority_domain,root.cutover_generation,root.writer_origin,
          root.source_sha256)
          = ROW(v_job.tenant_id,v_job.scope_kind,v_job.scope_id,
              v_job.authority_group_id,v_job.authority_group_generation,
              v_job.authority_domain,v_job.cutover_generation,'v2',
              v_job.payload_sha256)
      AND gap.value->>'contract_version' = 'event-sequence-gap.v1'
      AND gap.value->>'consumer' = root.consumer_name
      AND (gap.value->>'consumer_version')::integer = root.consumer_version
      AND gap.value->'envelope'->>'event_id' = event.event_id::text
      AND (gap.value->'envelope'->>'event_sequence')::bigint = event.event_sequence
      AND gap.value->'envelope'->>'event_type' = event.event_type
      AND (gap.value->'envelope'->>'event_version')::integer = event.event_version
      AND gap.value->'envelope'->>'aggregate_type' = event.aggregate_type
      AND gap.value->'envelope'->>'aggregate_id' = event.aggregate_id::text
      AND gap.value->'envelope'->>'payload_sha256' = event.payload_sha256
      AND event.payload_canonical IS NOT NULL
      AND event.payload_redacted_at IS NULL
      AND gap.value->'envelope'->'payload' =
          pg_catalog.convert_from(event.payload_canonical,'UTF8')::jsonb;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    RETURN NOT platform.platform_async_outbox_authority_current_v1(v_event);
END;
$$;


ALTER FUNCTION platform.platform_async_event_gap_job_ready_v2(p_job_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_external_effect_evidence_v1(uuid, text, uuid, text, bigint, text, bigint, uuid, uuid, bigint, text, integer, text, text, text, uuid, text, integer, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_external_effect_evidence_v1(p_tenant_id uuid, p_scope_kind text, p_scope_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_authority_domain text, p_cutover_generation bigint, p_claim_job_id uuid, p_claim_attempt_id uuid, p_claim_lease_generation bigint, p_claim_kind text, p_claim_payload_revision integer, p_claim_payload_reference text, p_claim_payload_sha256 text, p_claim_dedupe_prefix text, p_job_id uuid, p_expected_kind text, p_expected_payload_revision integer, p_expected_payload_reference text, p_payload_sha256 text, p_expected_dedupe_key text, p_expected_effect_key text, p_provider text, p_operation text, p_causation_id uuid) RETURNS TABLE(job_state text, job_attempts integer, effect_started boolean, receipt_status text, provider_reference text, error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    job_row platform.jobs%ROWTYPE;
    attempt_row platform.job_attempts%ROWTYPE;
    receipt_row platform.idempotency_receipts%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR p_scope_kind NOT IN ('global','tenant')
       OR p_scope_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_authority_group_generation < 1 OR p_cutover_generation < 1
       OR p_claim_lease_generation < 1 OR p_claim_payload_revision < 1
       OR NOT (p_claim_kind OPERATOR(pg_catalog.~)
               '^[a-z][a-z0-9_.-]{2,127}$')
       OR pg_catalog.octet_length(p_claim_payload_reference) NOT BETWEEN 1 AND 2048
       OR NOT (p_claim_payload_sha256 OPERATOR(pg_catalog.~) '^[0-9a-f]{64}$')
       OR pg_catalog.octet_length(p_claim_dedupe_prefix) NOT BETWEEN 1 AND 512
       OR p_expected_payload_revision < 1
       OR NOT (p_expected_kind OPERATOR(pg_catalog.~)
               '^[a-z][a-z0-9_.-]{2,127}$')
       OR pg_catalog.octet_length(p_expected_payload_reference)
          NOT BETWEEN 1 AND 2048
       OR NOT (p_payload_sha256 OPERATOR(pg_catalog.~) '^[0-9a-f]{64}$')
       OR pg_catalog.octet_length(p_expected_dedupe_key) NOT BETWEEN 1 AND 512
       OR pg_catalog.octet_length(p_expected_effect_key) NOT BETWEEN 1 AND 512
       OR NOT (p_provider OPERATOR(pg_catalog.~) '^[a-z][a-z0-9_.-]{2,127}$')
       OR NOT (p_operation OPERATOR(pg_catalog.~) '^[a-z][a-z0-9_.-]{2,127}$')
       OR p_causation_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR (p_scope_kind = 'tenant' AND
           (p_tenant_id IS NULL OR p_tenant_id <> p_scope_id))
       OR (p_scope_kind = 'global' AND p_tenant_id IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'external effect evidence identity is invalid';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM platform.jobs AS claim_job
        JOIN platform.job_attempts AS claim_attempt
         ON claim_attempt.job_id = claim_job.id
         AND claim_attempt.attempt_id = p_claim_attempt_id
         AND claim_attempt.attempt = claim_job.attempts
         AND claim_attempt.lease_generation = p_claim_lease_generation
        WHERE claim_job.id = p_claim_job_id
          AND claim_job.tenant_id IS NOT DISTINCT FROM p_tenant_id
          AND claim_job.scope_kind = p_scope_kind
          AND claim_job.scope_id = p_scope_id
          AND claim_job.authority_group_id = p_authority_group_id
          AND claim_job.authority_group_generation =
              p_authority_group_generation
          AND claim_job.authority_domain = p_authority_domain
          AND claim_job.cutover_generation = p_cutover_generation
          AND claim_job.writer_origin = 'v2'
          AND claim_job.kind = p_claim_kind
          AND claim_job.payload_revision = p_claim_payload_revision
          AND claim_job.lease_generation = p_claim_lease_generation
          AND claim_job.effect_class = 'database_transactional'
          AND claim_job.state = 'running'
          AND claim_job.payload_ref = p_claim_payload_reference
          AND claim_job.payload_sha256 = p_claim_payload_sha256
          AND (claim_job.dedupe_key = p_claim_dedupe_prefix
               OR pg_catalog.left(claim_job.dedupe_key,
                  pg_catalog.char_length(p_claim_dedupe_prefix) + 1) =
                  pg_catalog.concat(p_claim_dedupe_prefix, ':'))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'database job claim evidence is invalid';
    END IF;

    SELECT * INTO job_row
    FROM platform.jobs AS job
    WHERE job.id = p_job_id
      AND job.tenant_id IS NOT DISTINCT FROM p_tenant_id
      AND job.scope_kind = p_scope_kind
      AND job.scope_id = p_scope_id
      AND job.authority_group_id = p_authority_group_id
      AND job.authority_group_generation = p_authority_group_generation
      AND job.authority_domain = p_authority_domain
      AND job.cutover_generation = p_cutover_generation
      AND job.writer_origin = 'v2'
      AND job.kind = p_expected_kind
      AND job.payload_revision = p_expected_payload_revision
      AND job.payload_ref = p_expected_payload_reference
      AND job.payload_sha256 = p_payload_sha256
      AND job.dedupe_key = p_expected_dedupe_key
      AND job.effect_class = 'external'
      AND job.effect_idempotency_key = p_expected_effect_key
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'external effect job authority is invalid';
    END IF;

    IF job_row.attempts > 0 THEN
        SELECT * INTO attempt_row
        FROM platform.job_attempts AS attempt
        WHERE attempt.job_id = job_row.id
          AND attempt.scope_kind = p_scope_kind
          AND attempt.scope_id = p_scope_id
          AND attempt.attempt = job_row.attempts
        FOR SHARE;
        IF attempt_row.attempt_id IS NULL OR
           (job_row.state NOT IN ('queued','running') AND attempt_row.outcome IS NULL) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5721',
                MESSAGE = 'external effect terminal attempt is invalid';
        END IF;
    ELSIF job_row.state NOT IN ('queued','running') THEN
        RAISE EXCEPTION USING ERRCODE = 'P5721',
            MESSAGE = 'external effect terminal job has no attempt';
    END IF;
    IF attempt_row.effect_receipt_id IS NOT NULL THEN
        SELECT * INTO receipt_row
        FROM platform.idempotency_receipts AS receipt
        WHERE receipt.receipt_id = attempt_row.effect_receipt_id
        FOR SHARE;
        IF receipt_row.receipt_id IS NULL OR receipt_row.record_kind <> 'effect'
           OR receipt_row.tenant_id IS DISTINCT FROM p_tenant_id
           OR receipt_row.scope_kind <> p_scope_kind
           OR receipt_row.scope_id <> p_scope_id
           OR receipt_row.authority_group_id <> p_authority_group_id
           OR receipt_row.authority_group_generation <>
              p_authority_group_generation
           OR receipt_row.authority_domain <> p_authority_domain
           OR receipt_row.cutover_generation <> p_cutover_generation
           OR receipt_row.writer_origin <> 'v2'
           OR receipt_row.request_sha256 <> attempt_row.effect_request_sha256
           OR receipt_row.effect_id <> attempt_row.effect_id
           OR receipt_row.effect_kind <> job_row.kind
           OR receipt_row.effect_revision <> 1
           OR receipt_row.effect_key <> job_row.effect_idempotency_key
           OR receipt_row.provider <> p_provider
           OR receipt_row.operation <> p_operation
           OR receipt_row.causation_id <> p_causation_id THEN
            RAISE EXCEPTION USING ERRCODE = 'P5721',
                MESSAGE = 'external effect receipt chain is invalid';
        END IF;
    END IF;
    RETURN QUERY SELECT job_row.state, job_row.attempts,
        job_row.effect_started_at IS NOT NULL, receipt_row.effect_status,
        receipt_row.provider_reference,
        COALESCE(receipt_row.effect_code, job_row.last_error_code);
END;
$_$;


ALTER FUNCTION platform.platform_async_external_effect_evidence_v1(p_tenant_id uuid, p_scope_kind text, p_scope_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_authority_domain text, p_cutover_generation bigint, p_claim_job_id uuid, p_claim_attempt_id uuid, p_claim_lease_generation bigint, p_claim_kind text, p_claim_payload_revision integer, p_claim_payload_reference text, p_claim_payload_sha256 text, p_claim_dedupe_prefix text, p_job_id uuid, p_expected_kind text, p_expected_payload_revision integer, p_expected_payload_reference text, p_payload_sha256 text, p_expected_dedupe_key text, p_expected_effect_key text, p_provider text, p_operation text, p_causation_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_finalize_stale_external_unknown_v1(uuid, uuid, bigint, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_finalize_stale_external_unknown_v1(p_job_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_attempt_id uuid, p_effect_started_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_job_id IS NULL OR p_lease_owner_id IS NULL OR
       p_lease_generation < 1 OR p_attempt_id IS NULL OR
       p_effect_started_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5678',
            MESSAGE = 'stale external finalization input is invalid';
    END IF;

    SELECT * INTO v_job FROM platform.jobs WHERE id = p_job_id;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    SELECT generation INTO v_group_generation
    FROM platform.cutover_groups
    WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
      AND group_id = v_job.authority_group_id
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    SELECT generation INTO v_domain_generation
    FROM platform.domain_cutovers
    WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
      AND domain = v_job.authority_domain
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
          AND group_id = v_job.authority_group_id
          AND domain = v_job.authority_domain
    ) THEN
        RETURN false;
    END IF;

    SELECT * INTO v_job FROM platform.jobs WHERE id = p_job_id FOR UPDATE;
    IF NOT FOUND OR v_job.state IS DISTINCT FROM 'running' OR
       v_job.effect_class IS DISTINCT FROM 'external' OR
       v_job.effect_started_at IS DISTINCT FROM p_effect_started_at OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_generation IS DISTINCT FROM p_lease_generation OR
       v_job.parked_at IS NOT NULL OR
       v_group_generation < v_job.authority_group_generation OR
       v_domain_generation < v_job.cutover_generation OR
       (v_group_generation = v_job.authority_group_generation AND
        v_domain_generation = v_job.cutover_generation) THEN
        RETURN false;
    END IF;

    SELECT * INTO v_attempt
    FROM platform.job_attempts
    WHERE attempt_id = p_attempt_id AND job_id = v_job.id
      AND attempt = v_job.attempts
      AND lease_generation = p_lease_generation
      AND lease_owner_id = p_lease_owner_id
    FOR UPDATE;
    IF NOT FOUND OR v_attempt.finished_at IS NOT NULL OR
       v_attempt.effect_started_at IS DISTINCT FROM p_effect_started_at OR
       v_attempt.effect_id IS NULL OR v_attempt.effect_request_sha256 IS NULL OR
       EXISTS (
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.record_kind = 'effect'
          AND receipt.scope_kind = v_job.scope_kind
          AND receipt.scope_id = v_job.scope_id
          AND receipt.authority_group_id = v_job.authority_group_id
          AND receipt.authority_group_generation = v_job.authority_group_generation
          AND receipt.authority_domain = v_job.authority_domain
          AND receipt.cutover_generation = v_job.cutover_generation
          AND receipt.effect_key = v_job.effect_idempotency_key
          AND receipt.effect_id = v_attempt.effect_id
          AND receipt.request_sha256 = v_attempt.effect_request_sha256
    ) THEN
        RETURN false;
    END IF;

    v_now := GREATEST(
        pg_catalog.clock_timestamp(),
        v_job.updated_at + interval '1 microsecond',
        v_attempt.effect_started_at
    );
    UPDATE platform.job_attempts
    SET finished_at = v_now, outcome = 'dead', error_class = NULL,
        error_code = 'JOB_OUTCOME_UNKNOWN', redacted_error_sha256 = NULL,
        effect_receipt_id = NULL
    WHERE attempt_id = v_attempt.attempt_id AND finished_at IS NULL;
    IF NOT FOUND THEN
        RETURN false;
    END IF;

    UPDATE platform.jobs
    SET state = 'dead', lease_owner_id = NULL, lease_heartbeat_at = NULL,
        lease_until = NULL, last_error_class = NULL,
        last_error_code = 'JOB_OUTCOME_UNKNOWN', last_error_sha256 = NULL,
        retain_until = v_now + interval '365 days',
        updated_at = v_now, completed_at = v_now
    WHERE id = v_job.id;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platform_async_finalize_stale_external_unknown_v1(p_job_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_attempt_id uuid, p_effect_started_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_guard_append_only_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_append_only_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP OPERATOR(pg_catalog.=) 'DELETE' AND
       CURRENT_USER OPERATOR(pg_catalog.=) 'harpy_owner' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION USING
        ERRCODE = '55000',
        MESSAGE = 'platform async record is append-only';
END;
$$;


ALTER FUNCTION platform.platform_async_guard_append_only_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_dead_letter_redaction_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_dead_letter_redaction_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    expected platform.dead_letters%ROWTYPE;
    redaction_time timestamptz;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'dead_letters' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5649',
            MESSAGE = 'dead-letter redaction trigger target is invalid';
    END IF;

    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       OLD.record_kind IS DISTINCT FROM 'root' OR
       NEW.record_kind IS DISTINCT FROM 'root' OR
       OLD.payload_canonical IS NULL OR
       OLD.payload_redacted_at IS NOT NULL OR
       NEW.payload_canonical IS NOT NULL OR
       NEW.payload_redacted_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'dead-letter record is immutable';
    END IF;

    redaction_time := pg_catalog.clock_timestamp();
    IF redaction_time < OLD.full_payload_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'dead-letter payload retention has not expired';
    END IF;

    NEW.payload_redacted_at := redaction_time;
    expected := OLD;
    expected.payload_canonical := NULL;
    expected.payload_redacted_at := redaction_time;
    IF NEW IS DISTINCT FROM expected THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'dead-letter redaction changed immutable evidence';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_guard_dead_letter_redaction_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_dead_letter_redaction_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_dead_letter_redaction_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    expected platform.dead_letters%ROWTYPE;
    redaction_time timestamptz;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'dead_letters' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5649',
            MESSAGE = 'dead-letter redaction trigger target is invalid';
    END IF;

    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       OLD.record_kind IS DISTINCT FROM 'root' OR
       NEW.record_kind IS DISTINCT FROM 'root' OR
       OLD.payload_canonical IS NULL OR
       OLD.payload_redacted_at IS NOT NULL OR
       NEW.payload_canonical IS NOT NULL OR
       NEW.payload_redacted_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'dead-letter record is immutable';
    END IF;

    IF platform.platform_async_has_live_event_gap_root_v1(OLD) OR
       platform.platform_async_has_live_stale_job_root_v1(OLD) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'live event gap evidence cannot be redacted';
    END IF;

    redaction_time := pg_catalog.clock_timestamp();
    IF redaction_time < OLD.full_payload_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'dead-letter payload retention has not expired';
    END IF;

    NEW.payload_redacted_at := redaction_time;
    expected := OLD;
    expected.payload_canonical := NULL;
    expected.payload_redacted_at := redaction_time;
    IF NEW IS DISTINCT FROM expected THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'dead-letter redaction changed immutable evidence';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_guard_dead_letter_redaction_v2() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_inbox_stream_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_inbox_stream_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_latest bigint;
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'inbox' OR
       SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5630',
            MESSAGE = 'async inbox stream authority is invalid';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        pg_catalog.concat_ws(E'\x1f',
            'platform_async_inbox_v1', NEW.consumer_name,
            NEW.consumer_version::text, NEW.scope_kind, NEW.scope_id::text,
            NEW.aggregate_type, NEW.aggregate_id::text
        ), 0
    ));

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'event_receipt' THEN
        IF EXISTS (
            SELECT 1 FROM platform.inbox AS duplicate
            WHERE duplicate.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
              AND duplicate.consumer_version OPERATOR(pg_catalog.=)
                  NEW.consumer_version
              AND duplicate.event_id OPERATOR(pg_catalog.=) NEW.event_id
        ) THEN
            RETURN NEW;
        END IF;

        SELECT pg_catalog.max(watermark.through_sequence)
        INTO v_latest
        FROM platform.inbox AS watermark
        WHERE watermark.record_kind OPERATOR(pg_catalog.=) 'watermark'
          AND watermark.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
          AND watermark.consumer_version OPERATOR(pg_catalog.=) NEW.consumer_version
          AND watermark.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
          AND watermark.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
          AND watermark.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
          AND watermark.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id;

        IF NEW.event_sequence IS DISTINCT FROM
           (COALESCE(v_latest, 0::bigint) OPERATOR(pg_catalog.+) 1) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5631',
                MESSAGE = 'async inbox event sequence is not contiguous';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'watermark' AND
       NEW.watermark_kind OPERATOR(pg_catalog.=) 'event' THEN
        IF EXISTS (
            SELECT 1 FROM platform.inbox AS duplicate
            WHERE duplicate.record_kind OPERATOR(pg_catalog.=) 'watermark'
              AND duplicate.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
              AND duplicate.consumer_version OPERATOR(pg_catalog.=)
                  NEW.consumer_version
              AND duplicate.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
              AND duplicate.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
              AND duplicate.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
              AND duplicate.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id
              AND duplicate.through_sequence OPERATOR(pg_catalog.=)
                  NEW.through_sequence
        ) THEN
            RETURN NEW;
        END IF;

        SELECT pg_catalog.max(watermark.through_sequence)
        INTO v_latest
        FROM platform.inbox AS watermark
        WHERE watermark.record_kind OPERATOR(pg_catalog.=) 'watermark'
          AND watermark.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
          AND watermark.consumer_version OPERATOR(pg_catalog.=) NEW.consumer_version
          AND watermark.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
          AND watermark.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
          AND watermark.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
          AND watermark.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id;

        IF NEW.through_sequence IS DISTINCT FROM
           (COALESCE(v_latest, 0::bigint) OPERATOR(pg_catalog.+) 1) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5632',
                MESSAGE = 'async inbox event watermark is not contiguous';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'watermark' AND
       NEW.watermark_kind OPERATOR(pg_catalog.=) 'bootstrap' THEN
        IF EXISTS (
            SELECT 1 FROM platform.inbox AS stream_row
            WHERE stream_row.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
              AND stream_row.consumer_version OPERATOR(pg_catalog.=)
                  NEW.consumer_version
              AND stream_row.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
              AND stream_row.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
              AND stream_row.aggregate_type OPERATOR(pg_catalog.=)
                  NEW.aggregate_type
              AND stream_row.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5633',
                MESSAGE = 'async inbox bootstrap requires an empty stream';
        END IF;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION USING ERRCODE = 'P5634',
        MESSAGE = 'async inbox stream record is invalid';
END;
$$;


ALTER FUNCTION platform.platform_async_guard_inbox_stream_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_job_attempt_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_job_attempt_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'job_attempts' OR
       NOT (TG_OP = ANY (ARRAY['INSERT','UPDATE']::text[])) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5620',
            MESSAGE = 'job attempt invocation is invalid';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF platform.platform_async_validate_job_attempt_v1(
            NULL::platform.job_attempts, NEW, CURRENT_USER, SESSION_USER
        ) IS NULL THEN NULL; END IF;
    ELSE
        IF platform.platform_async_validate_job_attempt_v1(
            OLD, NEW, CURRENT_USER, SESSION_USER
        ) IS NULL THEN NULL; END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_guard_job_attempt_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_job_attempt_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_job_attempt_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'job_attempts' OR
       NOT (TG_OP = ANY (ARRAY['INSERT','UPDATE']::text[])) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5620',
            MESSAGE = 'job attempt invocation is invalid';
    END IF;
    IF TG_OP = 'INSERT' THEN
        PERFORM platform.platform_async_validate_job_attempt_v1(
            NULL::platform.job_attempts, NEW, CURRENT_USER, SESSION_USER
        );
    ELSIF CURRENT_USER = 'harpy_owner' AND
          OLD.finished_at IS NULL AND NEW.finished_at IS NOT NULL AND
          OLD.effect_started_at IS NOT NULL AND NEW.outcome = 'dead' AND
          NEW.error_code = 'JOB_OUTCOME_UNKNOWN' THEN
        PERFORM platform.platform_async_validate_stale_external_attempt_unknown_v1(
            OLD, NEW, CURRENT_USER, SESSION_USER
        );
    ELSE
        PERFORM platform.platform_async_validate_job_attempt_v1(
            OLD, NEW, CURRENT_USER, SESSION_USER
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_guard_job_attempt_v2() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_job_attempt_v3(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_job_attempt_v3() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_authority_current boolean;
BEGIN
    IF TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'job_attempts' OR
       NOT (TG_OP = ANY (ARRAY['INSERT','UPDATE']::text[])) THEN
        RAISE EXCEPTION USING ERRCODE='P5620',
            MESSAGE='job attempt invocation is invalid';
    END IF;
    IF TG_OP='INSERT' THEN
        PERFORM platform.platform_async_validate_job_attempt_v1(
            NULL::platform.job_attempts,NEW,CURRENT_USER,SESSION_USER);
    ELSIF CURRENT_USER='harpy_owner' AND OLD.finished_at IS NULL AND
          NEW.finished_at IS NOT NULL AND OLD.effect_started_at IS NOT NULL AND
          NEW.outcome='dead' AND NEW.error_code='JOB_OUTCOME_UNKNOWN' THEN
        SELECT job.* INTO STRICT v_job FROM platform.jobs AS job
        WHERE job.id=NEW.job_id;
        v_authority_current := EXISTS (
            SELECT 1 FROM platform.cutover_groups AS authority
            WHERE authority.scope_kind=v_job.scope_kind
              AND authority.scope_id=v_job.scope_id
              AND authority.group_id=v_job.authority_group_id
              AND authority.generation=v_job.authority_group_generation
              AND authority.state='v2' AND authority.writer='v2'
        ) AND EXISTS (
            SELECT 1 FROM platform.domain_cutovers AS authority
            WHERE authority.scope_kind=v_job.scope_kind
              AND authority.scope_id=v_job.scope_id
              AND authority.domain=v_job.authority_domain
              AND authority.generation=v_job.cutover_generation
              AND authority.state='v2' AND authority.writer='v2');
        IF v_authority_current THEN
            PERFORM platform.platform_async_validate_job_attempt_v1(
                OLD,NEW,CURRENT_USER,SESSION_USER);
        ELSE
            PERFORM platform.platform_async_validate_stale_external_attempt_unknown_v1(
                OLD,NEW,CURRENT_USER,SESSION_USER);
        END IF;
    ELSE
        PERFORM platform.platform_async_validate_job_attempt_v1(
            OLD,NEW,CURRENT_USER,SESSION_USER);
    END IF;
    RETURN NEW;
END;
$$;


