          NEW.outcome='dead' AND NEW.error_code='JOB_OUTCOME_UNKNOWN' THEN
        SELECT job.kind INTO v_kind FROM platform.jobs AS job
        WHERE job.id=NEW.job_id;
        IF v_kind='analytics.dashboard.export.render' THEN
