    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR TG_TABLE_SCHEMA IS DISTINCT FROM 'platform'
       OR TG_TABLE_NAME IS DISTINCT FROM 'jobs' THEN
        RAISE EXCEPTION USING ERRCODE='P5610',
            MESSAGE='job transition invocation is invalid';
    END IF;
    PERFORM platform.platform_async_validate_job_transition_v2(
        OLD,NEW,CURRENT_USER,SESSION_USER);
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_guard_job_transition_v5() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_job_transition_v6(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_job_transition_v6() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'jobs' THEN
        RAISE EXCEPTION USING ERRCODE='P5610',
            MESSAGE='job transition invocation is invalid';
    END IF;
    IF CURRENT_USER='harpy_owner' AND OLD.parked_at IS NULL AND
       NEW.parked_at IS NOT NULL THEN
        NULL;
    ELSIF CURRENT_USER='harpy_owner' AND OLD.state='running' AND
       OLD.effect_started_at IS NOT NULL AND NEW.state='dead' AND
       NEW.last_error_code='JOB_OUTCOME_UNKNOWN' THEN
        IF OLD.kind='analytics.dashboard.export.render' THEN
            PERFORM platform.platform_async_validate_analytics_dashboard_export_unknown_job_v1(
                OLD,NEW,CURRENT_USER,SESSION_USER);
        ELSE
            PERFORM platform.platform_async_validate_stale_external_job_unknown_v1(
                OLD,NEW,CURRENT_USER,SESSION_USER);
        END IF;
    ELSE
        PERFORM platform.platform_async_validate_job_transition_v1(
            OLD,NEW,CURRENT_USER,SESSION_USER);
    END IF;
    RETURN NEW;
END;
$$;


