CREATE FUNCTION platform.platform_async_guard_job_transition_v8() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
