--
-- Name: platform_async_guard_outbox_park_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_outbox_park_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'outbox' OR
       SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' OR
       CURRENT_USER OPERATOR(pg_catalog.<>) 'harpy_owner' OR
       OLD.parked_at IS NOT NULL OR NEW.parked_at IS NULL OR
       NEW.parked_code IS DISTINCT FROM 'OUTBOX_AUTHORITY_STALE' OR
       NEW.parked_current_group_generation <
           OLD.authority_group_generation OR
       NEW.parked_current_cutover_generation < OLD.cutover_generation OR
       (NEW.parked_current_group_generation =
            OLD.authority_group_generation AND
        NEW.parked_current_cutover_generation = OLD.cutover_generation) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5650',
            MESSAGE = 'outbox stale park invocation is invalid';
    END IF;

    PERFORM platform.platform_async_assert_current_authority_v1(
        OLD.scope_kind, OLD.scope_id, OLD.authority_group_id,
        NEW.parked_current_group_generation, OLD.authority_domain,
        NEW.parked_current_cutover_generation
    );

    IF NEW.delivery_state IS DISTINCT FROM 'pending' OR
       NEW.lease_owner_id IS NOT NULL OR
       NEW.lease_heartbeat_at IS NOT NULL OR NEW.lease_until IS NOT NULL OR
       NOT (
           (OLD.delivery_state = 'pending' AND
            OLD.lease_owner_id IS NULL AND OLD.lease_heartbeat_at IS NULL AND
            OLD.lease_until IS NULL) OR
           (OLD.delivery_state = 'publishing' AND
            OLD.lease_until <= v_now)
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5651',
            MESSAGE = 'outbox stale park lease is not eligible';
    END IF;

    IF ROW(
        NEW.event_id, NEW.tenant_id, NEW.scope_kind, NEW.scope_id,
        NEW.authority_group_id, NEW.authority_group_generation,
        NEW.authority_domain, NEW.cutover_generation, NEW.writer_origin,
        NEW.envelope_contract_version, NEW.event_type, NEW.event_version,
        NEW.aggregate_type, NEW.aggregate_id, NEW.aggregate_version,
        NEW.event_sequence, NEW.occurred_at, NEW.actor_id,
        NEW.correlation_id, NEW.causation_id, NEW.idempotency_key,
        NEW.business_effect_idempotency_key, NEW.payload_canonical,
        NEW.payload_sha256, NEW.payload_schema_sha256, NEW.payload_redacted_at,
        NEW.delivery_attempts, NEW.lease_generation, NEW.next_attempt_at,
        NEW.confirmed_at, NEW.delivered_at, NEW.confirm_sha256,
        NEW.last_error_code, NEW.last_error_sha256, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.event_id, OLD.tenant_id, OLD.scope_kind, OLD.scope_id,
        OLD.authority_group_id, OLD.authority_group_generation,
        OLD.authority_domain, OLD.cutover_generation, OLD.writer_origin,
        OLD.envelope_contract_version, OLD.event_type, OLD.event_version,
        OLD.aggregate_type, OLD.aggregate_id, OLD.aggregate_version,
        OLD.event_sequence, OLD.occurred_at, OLD.actor_id,
        OLD.correlation_id, OLD.causation_id, OLD.idempotency_key,
        OLD.business_effect_idempotency_key, OLD.payload_canonical,
        OLD.payload_sha256, OLD.payload_schema_sha256, OLD.payload_redacted_at,
        OLD.delivery_attempts, OLD.lease_generation, OLD.next_attempt_at,
        OLD.confirmed_at, OLD.delivered_at, OLD.confirm_sha256,
        OLD.last_error_code, OLD.last_error_sha256, OLD.created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5652',
            MESSAGE = 'outbox stale park changed immutable state';
    END IF;

    NEW.parked_at := v_now;
    NEW.updated_at := v_now;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_guard_outbox_park_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_outbox_transition_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_outbox_transition_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'outbox' OR
       SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5620',
            MESSAGE = 'async outbox mutation authority is invalid';
    END IF;

    IF ROW(
        NEW.event_id, NEW.tenant_id, NEW.scope_kind, NEW.scope_id,
        NEW.authority_group_id, NEW.authority_group_generation,
        NEW.authority_domain, NEW.cutover_generation, NEW.writer_origin,
        NEW.envelope_contract_version, NEW.event_type, NEW.event_version,
        NEW.aggregate_type, NEW.aggregate_id, NEW.aggregate_version,
        NEW.event_sequence, NEW.occurred_at, NEW.actor_id,
        NEW.correlation_id, NEW.causation_id, NEW.idempotency_key,
        NEW.business_effect_idempotency_key, NEW.payload_sha256,
        NEW.payload_schema_sha256, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.event_id, OLD.tenant_id, OLD.scope_kind, OLD.scope_id,
        OLD.authority_group_id, OLD.authority_group_generation,
        OLD.authority_domain, OLD.cutover_generation, OLD.writer_origin,
        OLD.envelope_contract_version, OLD.event_type, OLD.event_version,
        OLD.aggregate_type, OLD.aggregate_id, OLD.aggregate_version,
        OLD.event_sequence, OLD.occurred_at, OLD.actor_id,
        OLD.correlation_id, OLD.causation_id, OLD.idempotency_key,
        OLD.business_effect_idempotency_key, OLD.payload_sha256,
        OLD.payload_schema_sha256, OLD.created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5621',
            MESSAGE = 'async outbox envelope is immutable';
    END IF;

    NEW.updated_at := v_now;

    IF CURRENT_USER OPERATOR(pg_catalog.=) 'harpy_owner' AND
       OLD.delivery_state OPERATOR(pg_catalog.=) 'delivered' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'delivered' AND
       OLD.payload_canonical IS NOT NULL AND NEW.payload_canonical IS NULL AND
       OLD.payload_redacted_at IS NULL AND
       OLD.delivered_at <=
           (v_now OPERATOR(pg_catalog.-) INTERVAL '30 days') AND
       ROW(NEW.delivery_attempts, NEW.lease_owner_id, NEW.lease_generation,
           NEW.lease_heartbeat_at, NEW.lease_until, NEW.next_attempt_at,
           NEW.confirmed_at, NEW.delivered_at, NEW.confirm_sha256,
           NEW.last_error_code, NEW.last_error_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.delivery_attempts, OLD.lease_owner_id, OLD.lease_generation,
           OLD.lease_heartbeat_at, OLD.lease_until, OLD.next_attempt_at,
           OLD.confirmed_at, OLD.delivered_at, OLD.confirm_sha256,
           OLD.last_error_code, OLD.last_error_sha256) THEN
        NEW.payload_redacted_at := v_now;
        RETURN NEW;
    END IF;

    PERFORM platform.platform_async_assert_current_authority_v1(
        OLD.scope_kind, OLD.scope_id,
        OLD.authority_group_id, OLD.authority_group_generation,
        OLD.authority_domain, OLD.cutover_generation
    );

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'pending' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_attempts OPERATOR(pg_catalog.=)
           (OLD.delivery_attempts OPERATOR(pg_catalog.+) 1) AND
       NEW.lease_generation OPERATOR(pg_catalog.=)
           (OLD.lease_generation OPERATOR(pg_catalog.+) 1) AND
       OLD.next_attempt_at <= v_now AND NEW.lease_owner_id IS NOT NULL AND
       ROW(NEW.payload_canonical, NEW.payload_redacted_at,
           NEW.next_attempt_at, NEW.confirmed_at, NEW.delivered_at,
           NEW.confirm_sha256, NEW.last_error_code, NEW.last_error_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.payload_canonical, OLD.payload_redacted_at,
           OLD.next_attempt_at, OLD.confirmed_at, OLD.delivered_at,
           OLD.confirm_sha256, OLD.last_error_code, OLD.last_error_sha256) THEN
        IF (OLD.event_sequence OPERATOR(pg_catalog.>) 1 AND NOT EXISTS (
            SELECT 1 FROM platform.outbox AS predecessor
            WHERE predecessor.scope_kind OPERATOR(pg_catalog.=) OLD.scope_kind
              AND predecessor.scope_id OPERATOR(pg_catalog.=) OLD.scope_id
              AND predecessor.aggregate_type OPERATOR(pg_catalog.=)
                  OLD.aggregate_type
              AND predecessor.aggregate_id OPERATOR(pg_catalog.=) OLD.aggregate_id
              AND predecessor.event_sequence OPERATOR(pg_catalog.=)
                  (OLD.event_sequence OPERATOR(pg_catalog.-) 1)
              AND predecessor.delivery_state OPERATOR(pg_catalog.=) 'delivered'
        )) OR EXISTS (
            SELECT 1 FROM platform.outbox AS prior
            WHERE prior.scope_kind OPERATOR(pg_catalog.=) OLD.scope_kind
              AND prior.scope_id OPERATOR(pg_catalog.=) OLD.scope_id
              AND prior.aggregate_type OPERATOR(pg_catalog.=) OLD.aggregate_type
              AND prior.aggregate_id OPERATOR(pg_catalog.=) OLD.aggregate_id
              AND prior.event_sequence OPERATOR(pg_catalog.<) OLD.event_sequence
              AND prior.delivery_state OPERATOR(pg_catalog.<>) 'delivered'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5623',
                MESSAGE = 'async outbox stream predecessor is not delivered';
        END IF;
        NEW.lease_heartbeat_at := v_now;
        NEW.lease_until := v_now OPERATOR(pg_catalog.+) INTERVAL '60 seconds';
        RETURN NEW;
    END IF;

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       OLD.lease_until > v_now AND
       NEW.lease_until > OLD.lease_until AND
       ROW(NEW.delivery_attempts, NEW.lease_owner_id, NEW.lease_generation,
           NEW.payload_canonical, NEW.payload_redacted_at,
           NEW.next_attempt_at, NEW.confirmed_at, NEW.delivered_at,
           NEW.confirm_sha256, NEW.last_error_code, NEW.last_error_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.delivery_attempts, OLD.lease_owner_id, OLD.lease_generation,
           OLD.payload_canonical, OLD.payload_redacted_at,
           OLD.next_attempt_at, OLD.confirmed_at, OLD.delivered_at,
           OLD.confirm_sha256, OLD.last_error_code, OLD.last_error_sha256) THEN
        NEW.lease_heartbeat_at := v_now;
        NEW.lease_until := v_now OPERATOR(pg_catalog.+) INTERVAL '60 seconds';
        RETURN NEW;
    END IF;

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'pending' AND
       NEW.delivery_attempts OPERATOR(pg_catalog.=) OLD.delivery_attempts AND
       NEW.lease_generation OPERATOR(pg_catalog.=) OLD.lease_generation AND
       NEW.lease_owner_id IS NULL AND NEW.lease_heartbeat_at IS NULL AND
       NEW.lease_until IS NULL AND NEW.next_attempt_at IS NOT NULL AND
       NEW.last_error_code IS NOT NULL AND NEW.last_error_sha256 IS NOT NULL AND
       ROW(NEW.payload_canonical, NEW.payload_redacted_at,
           NEW.confirmed_at, NEW.delivered_at, NEW.confirm_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.payload_canonical, OLD.payload_redacted_at,
           OLD.confirmed_at, OLD.delivered_at, OLD.confirm_sha256) THEN
        IF NEW.next_attempt_at < v_now THEN
            NEW.next_attempt_at := v_now;
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'delivered' AND
       OLD.lease_until > v_now AND
       NEW.delivery_attempts OPERATOR(pg_catalog.=) OLD.delivery_attempts AND
       NEW.lease_generation OPERATOR(pg_catalog.=) OLD.lease_generation AND
       NEW.lease_owner_id IS NULL AND NEW.lease_heartbeat_at IS NULL AND
       NEW.lease_until IS NULL AND NEW.confirm_sha256 IS NOT NULL AND
       NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at AND
       NEW.payload_canonical IS NOT DISTINCT FROM OLD.payload_canonical AND
       NEW.payload_redacted_at IS NOT DISTINCT FROM OLD.payload_redacted_at THEN
        NEW.confirmed_at := v_now;
        NEW.delivered_at := v_now;
        NEW.last_error_code := NULL;
        NEW.last_error_sha256 := NULL;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION USING ERRCODE = 'P5622',
        MESSAGE = 'async outbox transition is invalid';
END;
$$;


ALTER FUNCTION platform.platform_async_guard_outbox_transition_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_outbox_transition_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_outbox_transition_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'outbox' OR
       SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5620',
            MESSAGE = 'async outbox mutation authority is invalid';
    END IF;

    IF ROW(
        NEW.event_id, NEW.tenant_id, NEW.scope_kind, NEW.scope_id,
        NEW.authority_group_id, NEW.authority_group_generation,
        NEW.authority_domain, NEW.cutover_generation, NEW.writer_origin,
        NEW.envelope_contract_version, NEW.event_type, NEW.event_version,
        NEW.aggregate_type, NEW.aggregate_id, NEW.aggregate_version,
        NEW.event_sequence, NEW.occurred_at, NEW.actor_id,
        NEW.correlation_id, NEW.causation_id, NEW.idempotency_key,
        NEW.business_effect_idempotency_key, NEW.payload_sha256,
        NEW.payload_schema_sha256, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.event_id, OLD.tenant_id, OLD.scope_kind, OLD.scope_id,
        OLD.authority_group_id, OLD.authority_group_generation,
        OLD.authority_domain, OLD.cutover_generation, OLD.writer_origin,
        OLD.envelope_contract_version, OLD.event_type, OLD.event_version,
        OLD.aggregate_type, OLD.aggregate_id, OLD.aggregate_version,
        OLD.event_sequence, OLD.occurred_at, OLD.actor_id,
        OLD.correlation_id, OLD.causation_id, OLD.idempotency_key,
        OLD.business_effect_idempotency_key, OLD.payload_sha256,
        OLD.payload_schema_sha256, OLD.created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5621',
            MESSAGE = 'async outbox envelope is immutable';
    END IF;

    NEW.updated_at := v_now;

    IF CURRENT_USER OPERATOR(pg_catalog.=) 'harpy_owner' AND
       OLD.delivery_state OPERATOR(pg_catalog.=) 'delivered' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'delivered' AND
       OLD.payload_canonical IS NOT NULL AND NEW.payload_canonical IS NULL AND
       OLD.payload_redacted_at IS NULL AND
       OLD.delivered_at <=
           (v_now OPERATOR(pg_catalog.-) INTERVAL '30 days') AND
       NOT platform.platform_async_has_live_event_gap_v1(OLD) AND
       ROW(NEW.delivery_attempts, NEW.lease_owner_id, NEW.lease_generation,
           NEW.lease_heartbeat_at, NEW.lease_until, NEW.next_attempt_at,
           NEW.confirmed_at, NEW.delivered_at, NEW.confirm_sha256,
           NEW.last_error_code, NEW.last_error_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.delivery_attempts, OLD.lease_owner_id, OLD.lease_generation,
           OLD.lease_heartbeat_at, OLD.lease_until, OLD.next_attempt_at,
           OLD.confirmed_at, OLD.delivered_at, OLD.confirm_sha256,
           OLD.last_error_code, OLD.last_error_sha256) THEN
        NEW.payload_redacted_at := v_now;
        RETURN NEW;
    END IF;

    IF CURRENT_USER OPERATOR(pg_catalog.=) 'harpy_owner' AND
       platform.platform_async_is_gap_requeue_v1(OLD, NEW, v_now) THEN
        RETURN NEW;
    END IF;

    PERFORM platform.platform_async_assert_current_authority_v1(
        OLD.scope_kind, OLD.scope_id,
        OLD.authority_group_id, OLD.authority_group_generation,
        OLD.authority_domain, OLD.cutover_generation
    );

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'pending' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_attempts OPERATOR(pg_catalog.=)
           (OLD.delivery_attempts OPERATOR(pg_catalog.+) 1) AND
       NEW.lease_generation OPERATOR(pg_catalog.=)
           (OLD.lease_generation OPERATOR(pg_catalog.+) 1) AND
       OLD.next_attempt_at <= v_now AND NEW.lease_owner_id IS NOT NULL AND
       ROW(NEW.payload_canonical, NEW.payload_redacted_at,
           NEW.next_attempt_at, NEW.confirmed_at, NEW.delivered_at,
           NEW.confirm_sha256, NEW.last_error_code, NEW.last_error_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.payload_canonical, OLD.payload_redacted_at,
           OLD.next_attempt_at, OLD.confirmed_at, OLD.delivered_at,
           OLD.confirm_sha256, OLD.last_error_code, OLD.last_error_sha256) THEN
        IF (OLD.event_sequence OPERATOR(pg_catalog.>) 1 AND NOT EXISTS (
            SELECT 1 FROM platform.outbox AS predecessor
            WHERE predecessor.scope_kind OPERATOR(pg_catalog.=) OLD.scope_kind
              AND predecessor.scope_id OPERATOR(pg_catalog.=) OLD.scope_id
              AND predecessor.aggregate_type OPERATOR(pg_catalog.=)
                  OLD.aggregate_type
              AND predecessor.aggregate_id OPERATOR(pg_catalog.=) OLD.aggregate_id
              AND predecessor.event_sequence OPERATOR(pg_catalog.=)
                  (OLD.event_sequence OPERATOR(pg_catalog.-) 1)
              AND predecessor.delivery_state OPERATOR(pg_catalog.=) 'delivered'
        )) OR EXISTS (
            SELECT 1 FROM platform.outbox AS prior
            WHERE prior.scope_kind OPERATOR(pg_catalog.=) OLD.scope_kind
              AND prior.scope_id OPERATOR(pg_catalog.=) OLD.scope_id
              AND prior.aggregate_type OPERATOR(pg_catalog.=)
                  OLD.aggregate_type
              AND prior.aggregate_id OPERATOR(pg_catalog.=) OLD.aggregate_id
              AND prior.event_sequence OPERATOR(pg_catalog.<) OLD.event_sequence
              AND prior.delivery_state OPERATOR(pg_catalog.<>) 'delivered'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5623',
                MESSAGE = 'async outbox stream predecessor is not delivered';
        END IF;
        NEW.lease_heartbeat_at := v_now;
        NEW.lease_until := v_now OPERATOR(pg_catalog.+) INTERVAL '60 seconds';
        RETURN NEW;
    END IF;

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       OLD.lease_until > v_now AND
       NEW.lease_until > OLD.lease_until AND
       ROW(NEW.delivery_attempts, NEW.lease_owner_id, NEW.lease_generation,
           NEW.payload_canonical, NEW.payload_redacted_at,
           NEW.next_attempt_at, NEW.confirmed_at, NEW.delivered_at,
           NEW.confirm_sha256, NEW.last_error_code, NEW.last_error_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.delivery_attempts, OLD.lease_owner_id, OLD.lease_generation,
           OLD.payload_canonical, OLD.payload_redacted_at,
           OLD.next_attempt_at, OLD.confirmed_at, OLD.delivered_at,
           OLD.confirm_sha256, OLD.last_error_code, OLD.last_error_sha256) THEN
        NEW.lease_heartbeat_at := v_now;
        NEW.lease_until := v_now OPERATOR(pg_catalog.+) INTERVAL '60 seconds';
        RETURN NEW;
    END IF;

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'pending' AND
       NEW.delivery_attempts OPERATOR(pg_catalog.=) OLD.delivery_attempts AND
       NEW.lease_generation OPERATOR(pg_catalog.=) OLD.lease_generation AND
       NEW.lease_owner_id IS NULL AND NEW.lease_heartbeat_at IS NULL AND
       NEW.lease_until IS NULL AND NEW.next_attempt_at IS NOT NULL AND
       NEW.last_error_code IS NOT NULL AND NEW.last_error_sha256 IS NOT NULL AND
       ROW(NEW.payload_canonical, NEW.payload_redacted_at,
           NEW.confirmed_at, NEW.delivered_at, NEW.confirm_sha256)
       IS NOT DISTINCT FROM
       ROW(OLD.payload_canonical, OLD.payload_redacted_at,
           OLD.confirmed_at, OLD.delivered_at, OLD.confirm_sha256) THEN
        IF NEW.next_attempt_at < v_now THEN
            NEW.next_attempt_at := v_now;
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
       NEW.delivery_state OPERATOR(pg_catalog.=) 'delivered' AND
       OLD.lease_until > v_now AND
       NEW.delivery_attempts OPERATOR(pg_catalog.=) OLD.delivery_attempts AND
       NEW.lease_generation OPERATOR(pg_catalog.=) OLD.lease_generation AND
       NEW.lease_owner_id IS NULL AND NEW.lease_heartbeat_at IS NULL AND
       NEW.lease_until IS NULL AND NEW.confirm_sha256 IS NOT NULL AND
       NEW.next_attempt_at IS NOT DISTINCT FROM OLD.next_attempt_at AND
       NEW.payload_canonical IS NOT DISTINCT FROM OLD.payload_canonical AND
       NEW.payload_redacted_at IS NOT DISTINCT FROM OLD.payload_redacted_at THEN
        NEW.confirmed_at := v_now;
        NEW.delivered_at := v_now;
        NEW.last_error_code := NULL;
        NEW.last_error_sha256 := NULL;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION USING ERRCODE = 'P5622',
        MESSAGE = 'async outbox transition is invalid';
END;
$$;


ALTER FUNCTION platform.platform_async_guard_outbox_transition_v2() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_stale_job_park_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_stale_job_park_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_changed jsonb;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'jobs' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.state NOT IN ('queued', 'running') OR NEW.state <> 'queued' OR
       OLD.parked_at IS NOT NULL OR NEW.parked_at IS NULL OR
       OLD.effect_started_at IS NOT NULL OR
       NEW.parked_at <> NEW.updated_at OR NEW.updated_at <= OLD.updated_at OR
       NEW.parked_code <> 'JOB_AUTHORITY_STALE' OR
       NEW.parked_current_group_generation < OLD.authority_group_generation OR
       NEW.parked_current_cutover_generation < OLD.cutover_generation OR
       (NEW.parked_current_group_generation = OLD.authority_group_generation AND
        NEW.parked_current_cutover_generation = OLD.cutover_generation) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5636',
            MESSAGE = 'stale job park transition is invalid';
    END IF;

    PERFORM platform.platform_async_assert_current_authority_v1(
        OLD.scope_kind, OLD.scope_id, OLD.authority_group_id,
        NEW.parked_current_group_generation, OLD.authority_domain,
        NEW.parked_current_cutover_generation
    );

    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF NOT (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
        'state','lease_owner_id','lease_heartbeat_at','lease_until','parked_at',
        'parked_code','parked_current_group_generation',
        'parked_current_cutover_generation','updated_at'
    ]::text[])) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5637',
            MESSAGE = 'stale job park changed immutable state';
    END IF;

    IF (OLD.state = 'queued' AND NOT EXISTS (
        SELECT 1 FROM platform.dead_letters AS dead_letter
        WHERE dead_letter.record_kind = 'root'
          AND dead_letter.source_kind = 'job'
          AND dead_letter.source_id = OLD.id
          AND dead_letter.reason_class = 'stale_generation'
          AND dead_letter.reason_code = 'JOB_AUTHORITY_STALE'
          AND dead_letter.authority_group_generation =
              NEW.parked_current_group_generation
          AND dead_letter.cutover_generation =
              NEW.parked_current_cutover_generation
          AND dead_letter.recorded_at = NEW.updated_at
    )) OR (OLD.state = 'running' AND NOT EXISTS (
        SELECT 1 FROM platform.job_attempts AS attempt
        WHERE attempt.job_id = OLD.id AND attempt.attempt = OLD.attempts
          AND attempt.lease_generation = OLD.lease_generation
          AND attempt.lease_owner_id = OLD.lease_owner_id
          AND attempt.outcome = 'lease_expired'
          AND attempt.error_class = 'conflict'
          AND attempt.error_code = 'JOB_AUTHORITY_STALE'
          AND attempt.finished_at IS NOT NULL
    )) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5638',
            MESSAGE = 'stale job park lacks durable evidence';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_guard_stale_job_park_v2() OWNER TO harpy_owner;

--
-- Name: platform_async_guard_v1_adoption_run_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_guard_v1_adoption_run_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_changed jsonb;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'async_v1_adoption_runs' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5630',
            MESSAGE = 'V1 async adoption run mutation is forbidden';
    END IF;

    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;

    IF OLD.state OPERATOR(pg_catalog.=) 'inventory' AND
       NEW.state OPERATOR(pg_catalog.=) 'disposing' AND
       v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY['state']::text[]) THEN
        RETURN NEW;
    END IF;
    IF OLD.state OPERATOR(pg_catalog.=) 'disposing' AND
       NEW.state OPERATOR(pg_catalog.=) 'accepted' AND
       NEW.accepted_at IS NOT NULL AND NEW.acceptance_sha256 IS NOT NULL AND
       v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'state', 'accepted_at', 'acceptance_sha256'
       ]::text[]) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'P5631',
        MESSAGE = 'V1 async adoption run transition is invalid';
END;
$$;


ALTER FUNCTION platform.platform_async_guard_v1_adoption_run_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_has_live_event_gap_root_v1(platform.dead_letters); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_has_live_event_gap_root_v1(p_root platform.dead_letters) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN p_root.record_kind = 'root'
    AND p_root.source_kind = 'event'
    AND p_root.reason_class = 'sequence_gap'
    AND EXISTS (
        SELECT 1
        FROM platform.jobs AS job
        WHERE job.payload_ref = 'deadletter:event-gap:' || p_root.id::text
          AND job.payload_sha256 = p_root.payload_sha256
          AND job.kind = 'platform_async.event_gap_reconcile.' ||
              job.authority_domain
          AND job.state IN ('queued','running')
    );
END;
$$;


ALTER FUNCTION platform.platform_async_has_live_event_gap_root_v1(p_root platform.dead_letters) OWNER TO harpy_owner;

--
-- Name: outbox; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.outbox (
    event_id uuid NOT NULL,
    tenant_id uuid,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    authority_group_id text NOT NULL,
    authority_group_generation bigint NOT NULL,
    authority_domain text NOT NULL,
    cutover_generation bigint NOT NULL,
    writer_origin text NOT NULL,
    envelope_contract_version text NOT NULL,
    event_type text NOT NULL,
    event_version integer NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    aggregate_version bigint NOT NULL,
    event_sequence bigint NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    actor_id uuid NOT NULL,
    correlation_id text NOT NULL,
    causation_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    business_effect_idempotency_key text NOT NULL,
    payload_canonical bytea,
    payload_sha256 text NOT NULL,
    payload_schema_sha256 text NOT NULL,
    payload_redacted_at timestamp with time zone,
    delivery_state text NOT NULL,
    delivery_attempts integer NOT NULL,
    lease_owner_id uuid,
    lease_generation bigint NOT NULL,
    lease_heartbeat_at timestamp with time zone,
    lease_until timestamp with time zone,
    next_attempt_at timestamp with time zone NOT NULL,
    confirmed_at timestamp with time zone,
    delivered_at timestamp with time zone,
    confirm_sha256 text,
    last_error_code text,
    last_error_sha256 text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    parked_at timestamp with time zone,
    parked_code text,
    parked_current_group_generation bigint,
    parked_current_cutover_generation bigint,
    CONSTRAINT outbox_aggregate_type_check CHECK ((aggregate_type ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT outbox_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT outbox_attempt_check CHECK ((lease_generation = delivery_attempts)),
    CONSTRAINT outbox_authority_domain_check CHECK ((authority_domain ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT outbox_authority_group_generation_check CHECK ((authority_group_generation > 0)),
    CONSTRAINT outbox_authority_group_id_check CHECK ((authority_group_id ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT outbox_business_effect_idempotency_key_check CHECK (((octet_length(business_effect_idempotency_key) >= 1) AND (octet_length(business_effect_idempotency_key) <= 512))),
    CONSTRAINT outbox_confirm_sha256_check CHECK ((confirm_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT outbox_correlation_id_check CHECK ((correlation_id ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,63}$'::text)),
    CONSTRAINT outbox_cutover_generation_check CHECK ((cutover_generation > 0)),
    CONSTRAINT outbox_delivery_attempts_check CHECK ((delivery_attempts >= 0)),
    CONSTRAINT outbox_delivery_check CHECK ((((delivery_state = ANY (ARRAY['pending'::text, 'publishing'::text])) AND (confirmed_at IS NULL) AND (delivered_at IS NULL) AND (confirm_sha256 IS NULL)) OR ((delivery_state = 'delivered'::text) AND (confirmed_at IS NOT NULL) AND (delivered_at IS NOT NULL) AND (confirm_sha256 IS NOT NULL)))),
    CONSTRAINT outbox_delivery_state_check CHECK ((delivery_state = ANY (ARRAY['pending'::text, 'publishing'::text, 'delivered'::text]))),
    CONSTRAINT outbox_envelope_contract_version_check CHECK ((envelope_contract_version = 'integration-event.v1'::text)),
    CONSTRAINT outbox_error_check CHECK ((((last_error_code IS NULL) AND (last_error_sha256 IS NULL)) OR ((last_error_code IS NOT NULL) AND (last_error_sha256 IS NOT NULL)))),
    CONSTRAINT outbox_event_sequence_check CHECK ((event_sequence > 0)),
    CONSTRAINT outbox_event_type_check CHECK ((event_type ~ '^[a-z][a-z0-9_.-]{2,127}$'::text)),
    CONSTRAINT outbox_event_version_check CHECK ((event_version > 0)),
    CONSTRAINT outbox_idempotency_key_check CHECK (((octet_length(idempotency_key) >= 1) AND (octet_length(idempotency_key) <= 512))),
    CONSTRAINT outbox_last_error_code_check CHECK ((last_error_code ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT outbox_last_error_sha256_check CHECK ((last_error_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT outbox_lease_check CHECK ((((delivery_state = 'publishing'::text) AND (delivery_attempts > 0) AND (lease_owner_id IS NOT NULL) AND (lease_heartbeat_at IS NOT NULL) AND (lease_until IS NOT NULL) AND (lease_heartbeat_at < lease_until)) OR ((delivery_state <> 'publishing'::text) AND (lease_owner_id IS NULL) AND (lease_heartbeat_at IS NULL) AND (lease_until IS NULL)))),
    CONSTRAINT outbox_lease_generation_check CHECK ((lease_generation >= 0)),
    CONSTRAINT outbox_parked_check CHECK ((((parked_at IS NULL) AND (parked_code IS NULL) AND (parked_current_group_generation IS NULL) AND (parked_current_cutover_generation IS NULL)) OR ((delivery_state = 'pending'::text) AND (parked_at IS NOT NULL) AND (parked_code = 'OUTBOX_AUTHORITY_STALE'::text) AND (lease_owner_id IS NULL) AND (lease_heartbeat_at IS NULL) AND (lease_until IS NULL) AND (parked_current_group_generation >= authority_group_generation) AND (parked_current_cutover_generation >= cutover_generation) AND ((parked_current_group_generation > authority_group_generation) OR (parked_current_cutover_generation > cutover_generation))))),
    CONSTRAINT outbox_parked_code_check CHECK ((parked_code ~ '^[A-Z][A-Z0-9_]{1,63}$'::text)),
    CONSTRAINT outbox_parked_current_cutover_generation_check CHECK ((parked_current_cutover_generation > 0)),
    CONSTRAINT outbox_parked_current_group_generation_check CHECK ((parked_current_group_generation > 0)),
    CONSTRAINT outbox_payload_check CHECK ((((payload_canonical IS NOT NULL) AND ((octet_length(payload_canonical) >= 2) AND (octet_length(payload_canonical) <= 65536)) AND (jsonb_typeof((convert_from(payload_canonical, 'UTF8'::name))::jsonb) = 'object'::text) AND (payload_sha256 = encode(sha256(payload_canonical), 'hex'::text)) AND (payload_redacted_at IS NULL)) OR ((payload_canonical IS NULL) AND (payload_redacted_at IS NOT NULL) AND (delivery_state = 'delivered'::text)))),
    CONSTRAINT outbox_payload_schema_sha256_check CHECK ((payload_schema_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT outbox_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT outbox_scope_check CHECK ((((scope_kind = 'tenant'::text) AND (tenant_id IS NOT NULL) AND (tenant_id = scope_id)) OR ((scope_kind = 'global'::text) AND (tenant_id IS NULL)))),
    CONSTRAINT outbox_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT outbox_time_check CHECK (((occurred_at <= created_at) AND (created_at <= updated_at) AND ((payload_redacted_at IS NULL) OR ((delivered_at IS NOT NULL) AND (delivered_at <= payload_redacted_at))) AND ((confirmed_at IS NULL) OR (occurred_at <= confirmed_at)) AND ((delivered_at IS NULL) OR (confirmed_at <= delivered_at)))),
    CONSTRAINT outbox_writer_origin_check CHECK ((writer_origin = ANY (ARRAY['v1'::text, 'v2'::text])))
);


ALTER TABLE platform.outbox OWNER TO harpy_owner;

--
-- Name: platform_async_has_live_event_gap_v1(platform.outbox); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_has_live_event_gap_v1(p_event platform.outbox) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN EXISTS (
    SELECT 1
    FROM platform.dead_letters AS root
    WHERE root.source_id = p_event.event_id
      AND root.tenant_id = p_event.tenant_id
      AND root.scope_kind = p_event.scope_kind
      AND root.scope_id = p_event.scope_id
      AND platform.platform_async_has_live_event_gap_root_v1(root)
);
END;
$$;


ALTER FUNCTION platform.platform_async_has_live_event_gap_v1(p_event platform.outbox) OWNER TO harpy_owner;

--
-- Name: platform_async_has_live_stale_job_root_v1(platform.dead_letters); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_has_live_stale_job_root_v1(p_root platform.dead_letters) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN p_root.record_kind = 'root'
    AND p_root.source_kind = 'job'
    AND p_root.reason_class = 'stale_generation'
    AND EXISTS (
        SELECT 1
        FROM platform.jobs AS job
        WHERE job.id = p_root.source_id
          AND job.state IN ('queued','running')
          AND job.parked_at IS NOT NULL
          AND job.parked_code = 'JOB_AUTHORITY_STALE'
    );
END;
$$;


ALTER FUNCTION platform.platform_async_has_live_stale_job_root_v1(p_root platform.dead_letters) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_current_lease_v1(uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_current_lease_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       p_lease_generation NOT BETWEEN 1 AND 3 OR
       p_resource_kind NOT IN ('users','roles','organizations') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export lease authority is invalid';
    END IF;
    SELECT job.* INTO v_job
    FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.authority_group_id='iam_system_resources'
      AND job.kind='iam.system-resource.record-export'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.effect_idempotency_key='iam-system-export:'||p_export_id::text
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.record-export:'||p_export_id::text
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||
          p_export_id::text
      AND job.max_attempts=3
    FOR SHARE;
    IF NOT FOUND OR v_job.state IS DISTINCT FROM 'running' OR
       v_job.attempts IS DISTINCT FROM p_lease_generation::integer OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_generation IS DISTINCT FROM p_lease_generation OR
       v_job.lease_until<=pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export lease is stale';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_group_generation,v_job.authority_domain,
        v_job.cutover_generation
    );
    SELECT attempt.* INTO v_attempt
    FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id
    FOR SHARE;
    IF NOT FOUND OR v_attempt.finished_at IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export attempt is stale';
    END IF;
    RETURN v_job.cancel_requested_at IS NOT NULL;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_current_lease_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_effect_start_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_effect_start_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_started_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_cancelled boolean;
    v_request text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_receipt_id=p_effect_id OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_started_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export effect start is invalid';
    END IF;
    SELECT platform.platform_async_iam_export_current_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export cancellation was requested';
    END IF;
    IF EXISTS(
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.receipt_id=p_receipt_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export effect receipt already exists';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO STRICT v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id FOR UPDATE;
    SELECT attempt.* INTO STRICT v_attempt
    FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
    FOR UPDATE;
    IF v_attempt.effect_started_at IS NOT NULL THEN
        IF v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_started_at=p_started_at AND
           v_job.effect_started_at=p_started_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export effect start replay differs';
    END IF;
    IF p_effect_id IS DISTINCT FROM p_attempt_id OR
       p_started_at<v_attempt.started_at OR p_started_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export effect start lease is stale';
    END IF;
    UPDATE platform.job_attempts SET effect_started_at=p_started_at,
        effect_id=p_effect_id,effect_request_sha256=v_request
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET effect_started_at=p_started_at,
        updated_at=p_started_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_effect_start_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_started_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_finish_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_finish_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_failure_class text, p_failure_code text, p_failure_sha256 bytea, p_finished_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_cancelled boolean;
    v_digest text;
    v_job_state text;
    v_outcome text;
    v_receipt_id uuid;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_failure_class NOT IN ('transient','permanent','conflict','cancelled') OR
       p_failure_code !~ '^[A-Z][A-Z0-9_]{1,63}$' OR
       pg_catalog.octet_length(p_failure_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_finished_at) OR
       (p_failure_class='transient' AND p_lease_generation<>3) OR
       (p_failure_class='cancelled' AND
        p_failure_code<>'IAM_SYSTEM_EXPORT_CANCELLED') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export terminal failure is invalid';
    END IF;
    v_digest := pg_catalog.encode(p_failure_sha256,'hex');
    v_job_state := CASE WHEN p_failure_class='cancelled'
        THEN 'cancelled' ELSE 'dead' END;
    v_outcome := v_job_state;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.authority_group_id='iam_system_resources'
      AND job.kind='iam.system-resource.record-export'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.effect_idempotency_key='iam-system-export:'||p_export_id::text
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.record-export:'||p_export_id::text
      AND job.max_attempts=3
    FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.state=v_job_state AND v_attempt.outcome=v_outcome THEN
        IF v_attempt.error_class=p_failure_class AND
           v_attempt.error_code=p_failure_code AND
           v_attempt.redacted_error_sha256=v_digest AND
           v_attempt.finished_at=p_finished_at AND
           v_job.last_error_class=p_failure_class AND
           v_job.last_error_code=p_failure_code AND
           v_job.last_error_sha256=v_digest AND
           v_job.completed_at=p_finished_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export terminal replay differs';
    END IF;
    SELECT platform.platform_async_iam_export_current_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled IS DISTINCT FROM (p_failure_class='cancelled') OR
       p_finished_at<=v_job.updated_at OR p_finished_at<v_attempt.started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export terminal lease is stale';
    END IF;
    IF v_attempt.effect_started_at IS NOT NULL THEN
        v_receipt_id := pg_catalog.uuidv7();
        INSERT INTO platform.idempotency_receipts(
            receipt_id,record_kind,tenant_id,scope_kind,scope_id,
            authority_group_id,authority_group_generation,authority_domain,
            cutover_generation,writer_origin,request_sha256,retention_class,
            effect_id,effect_kind,effect_revision,effect_key,provider,operation,
            correlation_id,causation_id,effect_status,effect_error_class,
            effect_code,completed_at,retain_until
        ) VALUES(
            v_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
            v_job.authority_group_id,v_job.authority_group_generation,
            v_job.authority_domain,v_job.cutover_generation,'v2',
            v_attempt.effect_request_sha256,'external_effect',v_attempt.effect_id,
            'iam.system-export.artifact',1,v_job.effect_idempotency_key,
            'object-storage','put-object',v_attempt.effect_id::text,p_job_id,
            'failed',p_failure_class,p_failure_code,p_finished_at,
            p_finished_at+interval '91 days'
        );
    END IF;
    UPDATE platform.job_attempts SET finished_at=p_finished_at,
        outcome=v_outcome,error_class=p_failure_class,error_code=p_failure_code,
        redacted_error_sha256=v_digest,effect_receipt_id=v_receipt_id
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state=v_job_state,lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=p_failure_class,
        last_error_code=p_failure_code,last_error_sha256=v_digest,
        retain_until=p_finished_at+CASE WHEN v_job_state='dead'
            THEN interval '366 days' ELSE interval '91 days' END,
        updated_at=p_finished_at,completed_at=p_finished_at WHERE id=p_job_id;
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.platform_async_iam_export_finish_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_failure_class text, p_failure_code text, p_failure_sha256 bytea, p_finished_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_effect_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_effect_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_started_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_cancelled boolean;
    v_request text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_receipt_id OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_started_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export reconciliation effect is invalid';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export reconciliation cancellation was requested';
    END IF;
    IF EXISTS(
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.receipt_id=p_receipt_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation receipt already exists';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO STRICT v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id FOR UPDATE;
    SELECT attempt.* INTO STRICT v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id FOR UPDATE;
    IF v_attempt.effect_started_at IS NOT NULL THEN
        IF v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_started_at=p_started_at AND
           v_job.effect_started_at=p_started_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation effect replay differs';
    END IF;
    IF p_effect_id<>p_attempt_id OR p_started_at<v_attempt.started_at OR
       p_started_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export reconciliation effect lease is stale';
    END IF;
    UPDATE platform.job_attempts SET effect_started_at=p_started_at,
        effect_id=p_effect_id,effect_request_sha256=v_request
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET effect_started_at=p_started_at,
        updated_at=p_started_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_effect_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_started_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_enqueue_v1(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_enqueue_v1(p_tenant_id uuid, p_export_id uuid, p_original_job_id uuid, p_resource_kind text, p_enqueued_at timestamp with time zone) RETURNS TABLE(job_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_original platform.jobs%ROWTYPE;
    v_existing platform.jobs%ROWTYPE;
    v_job_id uuid;
    v_payload_ref text;
    v_payload_sha text;
    v_dedupe text;
    v_effect_key text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_original_job_id) IS DISTINCT FROM 7 OR
       p_resource_kind NOT IN ('users','roles','organizations') OR
       NOT pg_catalog.isfinite(p_enqueued_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export reconciliation enqueue authority is invalid';
    END IF;
    SELECT original.* INTO v_original FROM platform.jobs AS original
    WHERE original.id=p_original_job_id AND original.tenant_id=p_tenant_id
      AND original.scope_kind='tenant' AND original.scope_id=p_tenant_id
      AND original.authority_group_id='iam_system_resources'
      AND original.authority_domain='iam' AND original.writer_origin='v2'
      AND original.kind='iam.system-resource.record-export'
      AND original.payload_revision=1 AND original.effect_class='external'
      AND original.payload_ref='iam-system-record/'||p_resource_kind||'/'||
          p_export_id::text
      AND original.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.record-export:'||p_export_id::text
      AND original.effect_idempotency_key='iam-system-export:'||p_export_id::text
      AND original.max_attempts=3 AND original.state='dead'
      AND original.last_error_class IS NULL
      AND original.last_error_code='JOB_OUTCOME_UNKNOWN'
      AND original.last_error_sha256 IS NULL
      AND original.completed_at=p_enqueued_at
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export unknown source is unavailable';
    END IF;
    v_payload_ref := 'iam-system-record/'||p_resource_kind||'/'||p_export_id::text;
    v_payload_sha := pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(v_payload_ref,'UTF8')),'hex');
    v_dedupe := 'iam-system-transfer:iam.system-resource.export-reconcile:'||
        p_export_id::text;
    v_effect_key := 'iam-system-export-reconcile:'||p_export_id::text;
    SELECT candidate.* INTO v_existing FROM platform.jobs AS candidate
    WHERE candidate.scope_kind='tenant' AND candidate.scope_id=p_tenant_id
      AND candidate.authority_group_id='iam_system_resources'
      AND candidate.authority_domain='iam'
      AND candidate.kind='iam.system-resource.export-reconcile'
      AND candidate.dedupe_key=v_dedupe FOR SHARE;
    IF FOUND THEN
        IF v_existing.tenant_id=p_tenant_id AND
           v_existing.authority_group_generation=v_original.authority_group_generation AND
           v_existing.cutover_generation=v_original.cutover_generation AND
           v_existing.writer_origin='v2' AND v_existing.payload_revision=1 AND
           v_existing.payload_ref=v_payload_ref AND
           v_existing.payload_sha256=v_payload_sha AND
           v_existing.effect_class='external' AND
           v_existing.effect_idempotency_key=v_effect_key AND
           v_existing.max_attempts=8 AND v_existing.created_at=p_enqueued_at THEN
            RETURN QUERY SELECT v_existing.id,true;
            RETURN;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation replay differs';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        v_original.scope_kind,v_original.scope_id,v_original.authority_group_id,
        v_original.authority_group_generation,v_original.authority_domain,
        v_original.cutover_generation
    );
    v_job_id := pg_catalog.uuidv7();
    INSERT INTO platform.jobs(
        id,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,
        writer_origin,kind,payload_revision,payload_ref,payload_sha256,dedupe_key,
        effect_class,effect_idempotency_key,priority,run_at,state,attempts,
        max_attempts,lease_generation,created_at,updated_at
    ) VALUES(
        v_job_id,p_tenant_id,'tenant',p_tenant_id,'iam_system_resources',
        v_original.authority_group_generation,'iam',v_original.cutover_generation,
        'v2','iam.system-resource.export-reconcile',1,v_payload_ref,v_payload_sha,
        v_dedupe,'external',v_effect_key,90,p_enqueued_at,'queued',0,8,0,
        p_enqueued_at,p_enqueued_at
    );
    RETURN QUERY SELECT v_job_id,false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_enqueue_v1(p_tenant_id uuid, p_export_id uuid, p_original_job_id uuid, p_resource_kind text, p_enqueued_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_expired_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, timestamp with time zone, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_expired_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_effect_started_at timestamp with time zone, p_recovered_at timestamp with time zone, p_retry_at timestamp with time zone, p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_request text;
    v_failure text;
    v_class text;
    v_state text;
    v_outcome text;
    v_current boolean;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_lease_generation NOT BETWEEN 1 AND 8 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_receipt_id OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_effect_started_at) OR
       NOT pg_catalog.isfinite(p_recovered_at) OR
       p_recovered_at<p_effect_started_at OR
       (p_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN' AND (
           p_lease_generation=8 OR
           NOT pg_catalog.isfinite(p_retry_at) OR p_retry_at<p_recovered_at OR
           p_retry_at>p_recovered_at+LEAST(
               interval '5 seconds' * pg_catalog.power(
                   2::double precision,
                   (p_lease_generation-1)::double precision),
               interval '15 minutes'))) OR
       (p_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' AND
           p_retry_at IS NOT NULL) OR
       p_code NOT IN ('IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN',
           'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export expired reconciliation is invalid';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    v_failure := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(
            'iam.system-export.reconciliation-failure.v1','UTF8') ||
        pg_catalog.decode('00','hex') || pg_catalog.uuid_send(p_job_id) ||
        pg_catalog.uuid_send(p_effect_id) ||
        pg_catalog.int8send(pg_catalog.octet_length(
            pg_catalog.convert_to(p_code,'UTF8'))::bigint) ||
        pg_catalog.convert_to(p_code,'UTF8') ||
        pg_catalog.int8send(p_lease_generation)),'hex');
    v_class := CASE WHEN p_code=
        'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN'
        THEN 'transient' ELSE 'permanent' END;
    v_state := CASE WHEN v_class='transient' THEN 'queued' ELSE 'dead' END;
    v_outcome := CASE WHEN v_class='transient' THEN 'requeued' ELSE 'dead' END;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.export-reconcile:'||p_export_id::text
      AND job.effect_idempotency_key='iam-system-export-reconcile:'||p_export_id::text
      AND job.max_attempts=8 FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export expired reconciliation job is stale';
    END IF;
    SELECT EXISTS(
        SELECT 1 FROM platform.cutover_groups AS group_row
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind=group_row.scope_kind
         AND domain_row.scope_id=group_row.scope_id
        WHERE group_row.scope_kind=v_job.scope_kind
          AND group_row.scope_id=v_job.scope_id
          AND group_row.group_id=v_job.authority_group_id
          AND group_row.generation=v_job.authority_group_generation
          AND group_row.state='v2' AND group_row.writer='v2'
          AND domain_row.domain=v_job.authority_domain
          AND domain_row.generation=v_job.cutover_generation
          AND domain_row.state='v2' AND domain_row.writer='v2'
    ) INTO v_current;
    IF (p_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN' AND
        NOT v_current) OR
       (p_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' AND
        p_lease_generation<8 AND v_current) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export expired reconciliation disposition conflicts';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export expired reconciliation attempt is stale';
    END IF;
    IF v_job.state=v_state AND v_attempt.outcome=v_outcome THEN
        IF v_job.last_error_class=v_class AND v_job.last_error_code=p_code AND
           v_job.last_error_sha256=v_failure AND v_job.updated_at=p_recovered_at AND
           ((v_state='queued' AND v_job.run_at=p_retry_at AND
             v_job.completed_at IS NULL) OR
            (v_state='dead' AND v_job.completed_at=p_recovered_at)) AND
           v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_started_at=p_effect_started_at AND
           v_attempt.effect_receipt_id=p_receipt_id AND
           v_attempt.error_class=v_class AND v_attempt.error_code=p_code AND
           v_attempt.redacted_error_sha256=v_failure AND
           v_attempt.finished_at=p_recovered_at AND EXISTS(
               SELECT 1 FROM platform.idempotency_receipts AS receipt
               WHERE receipt.receipt_id=p_receipt_id AND receipt.effect_id=p_effect_id
                 AND receipt.request_sha256=v_request AND receipt.effect_status='failed'
                 AND receipt.effect_error_class=v_class AND receipt.effect_code=p_code
                 AND receipt.completed_at=p_recovered_at
           ) THEN RETURN true; END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export expired reconciliation replay differs';
    END IF;
    IF v_job.state<>'running' OR v_job.attempts<>p_lease_generation OR
       v_job.lease_generation<>p_lease_generation OR
       v_job.lease_owner_id<>p_lease_owner_id OR
       v_job.lease_until>p_recovered_at OR v_job.updated_at>=p_recovered_at OR
       v_attempt.finished_at IS NOT NULL OR
       v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS DISTINCT FROM p_effect_started_at OR
       v_attempt.effect_receipt_id IS NOT NULL OR EXISTS(
           SELECT 1 FROM platform.idempotency_receipts AS receipt
           WHERE receipt.receipt_id=p_receipt_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export expired reconciliation lease is stale';
    END IF;
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,writer_origin,
        request_sha256,retention_class,effect_id,effect_kind,effect_revision,
        effect_key,provider,operation,correlation_id,causation_id,effect_status,
        effect_error_class,effect_code,completed_at,retain_until
    ) VALUES(
        p_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
        v_job.authority_group_id,v_job.authority_group_generation,
        v_job.authority_domain,v_job.cutover_generation,'v2',v_request,
        'external_effect',p_effect_id,'iam.system-resource.export-reconcile',1,
        v_job.effect_idempotency_key,'object-storage','head-object',p_effect_id::text,
        p_job_id,'failed',v_class,p_code,p_recovered_at,
        p_recovered_at+CASE WHEN v_state='dead'
            THEN interval '366 days' ELSE interval '91 days' END
    );
    UPDATE platform.job_attempts SET finished_at=p_recovered_at,outcome=v_outcome,
        error_class=v_class,error_code=p_code,redacted_error_sha256=v_failure,
        effect_receipt_id=p_receipt_id WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state=v_state,run_at=COALESCE(p_retry_at,run_at),
        lease_owner_id=NULL,lease_heartbeat_at=NULL,lease_until=NULL,
        last_error_class=v_class,last_error_code=p_code,last_error_sha256=v_failure,
        retain_until=CASE WHEN v_state='dead'
            THEN p_recovered_at+interval '366 days' END,
        updated_at=p_recovered_at,
        completed_at=CASE WHEN v_state='dead' THEN p_recovered_at END
    WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_expired_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_effect_started_at timestamp with time zone, p_recovered_at timestamp with time zone, p_retry_at timestamp with time zone, p_code text) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_lease_v1(uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_lease_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_payload_ref text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       p_lease_generation NOT BETWEEN 1 AND 8 OR
       p_resource_kind NOT IN ('users','roles','organizations') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export reconciliation lease authority is invalid';
    END IF;
    v_payload_ref := 'iam-system-record/'||p_resource_kind||'/'||p_export_id::text;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_revision=1 AND job.payload_ref=v_payload_ref
      AND job.payload_sha256=pg_catalog.encode(
          pg_catalog.sha256(pg_catalog.convert_to(v_payload_ref,'UTF8')),'hex')
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.export-reconcile:'||p_export_id::text
      AND job.effect_class='external'
      AND job.effect_idempotency_key='iam-system-export-reconcile:'||p_export_id::text
      AND job.max_attempts=8 FOR SHARE;
    IF NOT FOUND OR v_job.state<>'running' OR
       v_job.attempts<>p_lease_generation::integer OR
       v_job.lease_generation<>p_lease_generation OR
       v_job.lease_owner_id<>p_lease_owner_id OR
       v_job.lease_until<=pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export reconciliation lease is stale';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_group_generation,v_job.authority_domain,
        v_job.cutover_generation
    );
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR SHARE;
    IF NOT FOUND OR v_attempt.finished_at IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export reconciliation attempt is stale';
    END IF;
    RETURN v_job.cancel_requested_at IS NOT NULL;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_lease_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_missing_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_missing_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_result_sha256 bytea, p_provider_reference text, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_cancelled boolean;
    v_request text;
    v_result text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_receipt_id OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_provider_reference) NOT BETWEEN 1 AND 512 OR
       NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export missing reconciliation is invalid';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    v_result := pg_catalog.encode(p_result_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.effect_idempotency_key='iam-system-export-reconcile:'||p_export_id::text
      AND job.max_attempts=8 FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.state='succeeded' AND v_attempt.outcome='succeeded' THEN
        IF v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_receipt_id=p_receipt_id AND
           v_attempt.finished_at=p_observed_at AND v_job.completed_at=p_observed_at AND
           EXISTS(SELECT 1 FROM platform.idempotency_receipts AS receipt
             WHERE receipt.receipt_id=p_receipt_id AND receipt.effect_id=p_effect_id
               AND receipt.request_sha256=v_request AND receipt.effect_status='succeeded'
               AND receipt.effect_code='OBJECT_ARTIFACT_MISSING'
               AND receipt.provider_reference=p_provider_reference
               AND receipt.effect_result_sha256=v_result
               AND receipt.completed_at=p_observed_at) THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export missing reconciliation replay differs';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export reconciliation cancellation was requested';
    END IF;
    IF v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS NULL OR p_observed_at<v_attempt.effect_started_at OR
       p_observed_at<v_job.updated_at OR EXISTS(
           SELECT 1 FROM platform.idempotency_receipts AS receipt
           WHERE receipt.receipt_id=p_receipt_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export missing reconciliation evidence conflicts';
    END IF;
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,writer_origin,
        request_sha256,retention_class,effect_id,effect_kind,effect_revision,
        effect_key,provider,operation,correlation_id,causation_id,effect_status,
        effect_code,provider_reference,effect_result_ref,effect_result_sha256,
        completed_at,retain_until
    ) VALUES(
        p_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
        v_job.authority_group_id,v_job.authority_group_generation,
        v_job.authority_domain,v_job.cutover_generation,'v2',v_request,
        'external_effect',p_effect_id,'iam.system-resource.export-reconcile',1,
        v_job.effect_idempotency_key,'object-storage','head-object',p_effect_id::text,
        p_job_id,'succeeded','OBJECT_ARTIFACT_MISSING',p_provider_reference,
        'iam-system-export/'||p_export_id::text||'/reconciliation',v_result,
        p_observed_at,p_observed_at+interval '91 days'
    );
    UPDATE platform.job_attempts SET finished_at=p_observed_at,
        outcome='succeeded',effect_receipt_id=p_receipt_id WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='succeeded',lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=NULL,
        last_error_code=NULL,last_error_sha256=NULL,
        retain_until=p_observed_at+interval '91 days',updated_at=p_observed_at,
        completed_at=p_observed_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_missing_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_result_sha256 bytea, p_provider_reference text, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_park_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_park_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_failure_sha256 bytea, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_request text;
    v_failure text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_lease_generation<>8 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_receipt_id OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_failure_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export reconciliation park is invalid';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    v_failure := pg_catalog.encode(p_failure_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.effect_idempotency_key='iam-system-export-reconcile:'||p_export_id::text
      AND job.max_attempts=8 FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.attempt=8 AND attempt.lease_generation=8
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.state='dead' AND v_attempt.outcome='dead' THEN
        IF v_job.last_error_class='permanent' AND
           v_job.last_error_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' AND
           v_job.last_error_sha256=v_failure AND v_job.completed_at=p_observed_at AND
           v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_receipt_id=p_receipt_id AND
           v_attempt.error_class='permanent' AND
           v_attempt.error_code=
               'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' AND
           v_attempt.redacted_error_sha256=v_failure AND
           v_attempt.finished_at=p_observed_at AND EXISTS(
               SELECT 1 FROM platform.idempotency_receipts AS receipt
               WHERE receipt.receipt_id=p_receipt_id AND receipt.effect_id=p_effect_id
                 AND receipt.request_sha256=v_request AND receipt.effect_status='failed'
                 AND receipt.effect_error_class='permanent'
                 AND receipt.effect_code=
                     'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED'
                 AND receipt.completed_at=p_observed_at
           ) THEN RETURN true; END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation park replay differs';
    END IF;
    PERFORM platform.platform_async_iam_export_reconcile_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    );
    IF v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS NULL OR p_observed_at<v_attempt.effect_started_at OR
       p_observed_at<v_job.updated_at OR EXISTS(
           SELECT 1 FROM platform.idempotency_receipts AS receipt
           WHERE receipt.receipt_id=p_receipt_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation park evidence conflicts';
    END IF;
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,writer_origin,
        request_sha256,retention_class,effect_id,effect_kind,effect_revision,
        effect_key,provider,operation,correlation_id,causation_id,effect_status,
        effect_error_class,effect_code,completed_at,retain_until
    ) VALUES(
        p_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
        v_job.authority_group_id,v_job.authority_group_generation,
        v_job.authority_domain,v_job.cutover_generation,'v2',v_request,
        'external_effect',p_effect_id,'iam.system-resource.export-reconcile',1,
        v_job.effect_idempotency_key,'object-storage','head-object',p_effect_id::text,
        p_job_id,'failed','permanent',
        'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED',p_observed_at,
        p_observed_at+interval '366 days'
    );
    UPDATE platform.job_attempts SET finished_at=p_observed_at,outcome='dead',
        error_class='permanent',
        error_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED',
        redacted_error_sha256=v_failure,effect_receipt_id=p_receipt_id
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='dead',lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class='permanent',
        last_error_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED',
        last_error_sha256=v_failure,retain_until=p_observed_at+interval '366 days',
        updated_at=p_observed_at,completed_at=p_observed_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_park_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_failure_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_retry_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_retry_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_failure_sha256 bytea, p_observed_at timestamp with time zone, p_retry_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_cancelled boolean;
    v_request text;
    v_failure text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_lease_generation NOT BETWEEN 1 AND 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_receipt_id OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_failure_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_observed_at) OR NOT pg_catalog.isfinite(p_retry_at) OR
       p_retry_at<p_observed_at OR p_retry_at>p_observed_at+interval '15 minutes' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export reconciliation retry is invalid';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    v_failure := pg_catalog.encode(p_failure_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.effect_idempotency_key='iam-system-export-reconcile:'||p_export_id::text
      AND job.max_attempts=8 FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.state='queued' AND v_attempt.outcome='requeued' THEN
        IF v_job.run_at=p_retry_at AND v_job.updated_at=p_observed_at AND
           v_job.last_error_class='transient' AND
           v_job.last_error_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN' AND
           v_job.last_error_sha256=v_failure AND
           v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_receipt_id=p_receipt_id AND
           v_attempt.error_class='transient' AND
           v_attempt.error_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN' AND
           v_attempt.redacted_error_sha256=v_failure AND
           v_attempt.finished_at=p_observed_at AND EXISTS(
               SELECT 1 FROM platform.idempotency_receipts AS receipt
               WHERE receipt.receipt_id=p_receipt_id AND receipt.effect_id=p_effect_id
                 AND receipt.request_sha256=v_request AND receipt.effect_status='failed'
                 AND receipt.effect_error_class='transient'
                 AND receipt.effect_code=
                     'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN'
                 AND receipt.completed_at=p_observed_at
           ) THEN RETURN true; END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation retry replay differs';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled OR v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS NULL OR p_observed_at<v_attempt.effect_started_at OR
       p_observed_at<v_job.updated_at OR EXISTS(
           SELECT 1 FROM platform.idempotency_receipts AS receipt
           WHERE receipt.receipt_id=p_receipt_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation retry evidence conflicts';
    END IF;
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,writer_origin,
        request_sha256,retention_class,effect_id,effect_kind,effect_revision,
        effect_key,provider,operation,correlation_id,causation_id,effect_status,
        effect_error_class,effect_code,completed_at,retain_until
    ) VALUES(
        p_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
        v_job.authority_group_id,v_job.authority_group_generation,
        v_job.authority_domain,v_job.cutover_generation,'v2',v_request,
        'external_effect',p_effect_id,'iam.system-resource.export-reconcile',1,
        v_job.effect_idempotency_key,'object-storage','head-object',p_effect_id::text,
        p_job_id,'failed','transient',
        'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN',p_observed_at,
        p_observed_at+interval '91 days'
    );
    UPDATE platform.job_attempts SET finished_at=p_observed_at,outcome='requeued',
        error_class='transient',
        error_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN',
        redacted_error_sha256=v_failure,effect_receipt_id=p_receipt_id
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='queued',run_at=p_retry_at,lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class='transient',
        last_error_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN',
        last_error_sha256=v_failure,updated_at=p_observed_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_retry_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_failure_sha256 bytea, p_observed_at timestamp with time zone, p_retry_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_reconcile_sealed_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, bytea, text, timestamp with time zone, uuid, uuid, uuid, bytea, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_reconcile_sealed_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_result_sha256 bytea, p_provider_reference text, p_observed_at timestamp with time zone, p_original_job_id uuid, p_original_effect_id uuid, p_original_receipt_id uuid, p_original_request_sha256 bytea, p_artifact_result_sha256 bytea, p_artifact_provider_reference text, p_artifact_sealed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_original platform.jobs%ROWTYPE;
    v_cancelled boolean;
    v_request text;
    v_result text;
    v_original_request text;
    v_artifact_result text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_original_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_original_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_receipt_id OR p_original_effect_id=p_original_receipt_id OR
       p_receipt_id=p_original_receipt_id OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_original_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_artifact_result_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_provider_reference) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_artifact_provider_reference) NOT BETWEEN 1 AND 512 OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       NOT pg_catalog.isfinite(p_artifact_sealed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export sealed reconciliation is invalid';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    v_result := pg_catalog.encode(p_result_sha256,'hex');
    v_original_request := pg_catalog.encode(p_original_request_sha256,'hex');
    v_artifact_result := pg_catalog.encode(p_artifact_result_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_revision=1
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.export-reconcile:'||p_export_id::text
      AND job.effect_class='external'
      AND job.effect_idempotency_key='iam-system-export-reconcile:'||p_export_id::text
      AND job.max_attempts=8 FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    SELECT original.* INTO v_original FROM platform.jobs AS original
    WHERE original.id=p_original_job_id AND original.tenant_id=p_tenant_id
      AND original.kind='iam.system-resource.record-export'
      AND original.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND original.effect_idempotency_key='iam-system-export:'||p_export_id::text
      AND original.state='dead' AND original.last_error_class IS NULL
      AND original.last_error_code='JOB_OUTCOME_UNKNOWN' FOR SHARE;
    IF v_job.state='succeeded' AND v_attempt.outcome='succeeded' THEN
        IF v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_receipt_id=p_receipt_id AND
           v_attempt.finished_at=p_observed_at AND v_job.completed_at=p_observed_at AND
           EXISTS(SELECT 1 FROM platform.idempotency_receipts AS receipt
             WHERE receipt.receipt_id=p_receipt_id AND receipt.effect_id=p_effect_id
               AND receipt.request_sha256=v_request AND receipt.effect_status='succeeded'
               AND receipt.effect_code='OBJECT_ARTIFACT_SEALED'
               AND receipt.provider_reference=p_provider_reference
               AND receipt.effect_result_sha256=v_result
               AND receipt.completed_at=p_observed_at) AND
           EXISTS(SELECT 1 FROM platform.idempotency_receipts AS receipt
             WHERE receipt.receipt_id=p_original_receipt_id
               AND receipt.effect_id=p_original_effect_id
               AND receipt.request_sha256=v_original_request
               AND receipt.effect_status='succeeded'
               AND receipt.effect_code='OBJECT_UPLOAD_RECONCILED'
               AND receipt.provider_reference=p_artifact_provider_reference
               AND receipt.effect_result_sha256=v_artifact_result
               AND receipt.completed_at=p_artifact_sealed_at) THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export sealed reconciliation replay differs';
    END IF;
    IF v_original.id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export original unknown job is unavailable';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export reconciliation cancellation was requested';
    END IF;
    IF v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS NULL OR p_observed_at<v_attempt.effect_started_at OR
       p_observed_at<v_job.updated_at OR
       p_artifact_sealed_at<v_original.effect_started_at-interval '1 second' OR
       EXISTS(SELECT 1 FROM platform.idempotency_receipts AS receipt
              WHERE receipt.receipt_id IN (p_receipt_id,p_original_receipt_id)) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export sealed reconciliation evidence conflicts';
    END IF;
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,writer_origin,
        request_sha256,retention_class,effect_id,effect_kind,effect_revision,
        effect_key,provider,operation,correlation_id,causation_id,effect_status,
        effect_code,provider_reference,effect_result_ref,effect_result_sha256,
        completed_at,retain_until
    ) VALUES
    (p_original_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
     v_original.authority_group_id,v_original.authority_group_generation,
     v_original.authority_domain,v_original.cutover_generation,'v2',v_original_request,
     'external_effect',p_original_effect_id,'iam.system-export.artifact',1,
     v_original.effect_idempotency_key,'object-storage','head-object',
     p_original_effect_id::text,p_original_job_id,'succeeded','OBJECT_UPLOAD_RECONCILED',
     p_artifact_provider_reference,'iam-system-export/'||p_export_id::text||'/artifact',
     v_artifact_result,p_artifact_sealed_at,p_observed_at+interval '91 days'),
    (p_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
     v_job.authority_group_id,v_job.authority_group_generation,v_job.authority_domain,
     v_job.cutover_generation,'v2',v_request,'external_effect',p_effect_id,
     'iam.system-resource.export-reconcile',1,v_job.effect_idempotency_key,
     'object-storage','head-object',p_effect_id::text,p_job_id,'succeeded',
     'OBJECT_ARTIFACT_SEALED',p_provider_reference,
     'iam-system-export/'||p_export_id::text||'/reconciliation',v_result,
     p_observed_at,p_observed_at+interval '91 days');
    UPDATE platform.job_attempts SET finished_at=p_observed_at,
        outcome='succeeded',effect_receipt_id=p_receipt_id WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='succeeded',lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=NULL,
        last_error_code=NULL,last_error_sha256=NULL,
        retain_until=p_observed_at+interval '91 days',updated_at=p_observed_at,
        completed_at=p_observed_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_reconcile_sealed_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_result_sha256 bytea, p_provider_reference text, p_observed_at timestamp with time zone, p_original_job_id uuid, p_original_effect_id uuid, p_original_receipt_id uuid, p_original_request_sha256 bytea, p_artifact_result_sha256 bytea, p_artifact_provider_reference text, p_artifact_sealed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_succeed_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_succeed_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_result_sha256 bytea, p_provider_reference text, p_completed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_cancelled boolean;
    v_request text;
    v_result text;
    v_receipt_exact boolean;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_provider_reference) NOT BETWEEN 1 AND 512 OR
       NOT pg_catalog.isfinite(p_completed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export success evidence is invalid';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    v_result := pg_catalog.encode(p_result_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.authority_group_id='iam_system_resources'
      AND job.kind='iam.system-resource.record-export'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.effect_idempotency_key='iam-system-export:'||p_export_id::text
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.record-export:'||p_export_id::text
      AND job.max_attempts=3
    FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.state='succeeded' AND v_attempt.outcome='succeeded' THEN
        SELECT receipt.receipt_id=p_receipt_id INTO v_receipt_exact
        FROM platform.idempotency_receipts AS receipt
        WHERE receipt.receipt_id=p_receipt_id AND receipt.record_kind='effect'
          AND receipt.scope_kind='tenant' AND receipt.scope_id=p_tenant_id
          AND receipt.effect_id=p_effect_id AND receipt.request_sha256=v_request
          AND receipt.effect_status='succeeded'
          AND receipt.effect_code='OBJECT_UPLOAD_SUCCEEDED'
          AND receipt.provider_reference=p_provider_reference
          AND receipt.effect_result_sha256=v_result
          AND receipt.completed_at=p_completed_at;
        IF COALESCE(v_receipt_exact,false) AND
           v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_receipt_id=p_receipt_id AND
           v_attempt.finished_at=p_completed_at AND
           v_job.completed_at=p_completed_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export success replay differs';
    END IF;
    SELECT platform.platform_async_iam_export_current_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export cancellation was requested';
    END IF;
    IF v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_started_at IS NULL OR
       p_completed_at<v_attempt.effect_started_at OR
       p_completed_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export success lease is stale';
    END IF;
    INSERT INTO platform.idempotency_receipts(
        receipt_id,record_kind,tenant_id,scope_kind,scope_id,
        authority_group_id,authority_group_generation,authority_domain,
        cutover_generation,writer_origin,request_sha256,retention_class,
        effect_id,effect_kind,effect_revision,effect_key,provider,operation,
        correlation_id,causation_id,effect_status,effect_code,provider_reference,
        effect_result_ref,effect_result_sha256,completed_at,retain_until
    ) VALUES(
        p_receipt_id,'effect',p_tenant_id,'tenant',p_tenant_id,
        v_job.authority_group_id,v_job.authority_group_generation,
        v_job.authority_domain,v_job.cutover_generation,'v2',v_request,
        'external_effect',p_effect_id,'iam.system-export.artifact',1,
        v_job.effect_idempotency_key,'object-storage','put-object',
        p_effect_id::text,p_job_id,'succeeded','OBJECT_UPLOAD_SUCCEEDED',
        p_provider_reference,'iam-system-export/'||p_export_id::text||'/artifact',
        v_result,p_completed_at,p_completed_at+interval '91 days'
    );
    UPDATE platform.job_attempts SET finished_at=p_completed_at,
        outcome='succeeded',effect_receipt_id=p_receipt_id
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='succeeded',lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=NULL,
        last_error_code=NULL,last_error_sha256=NULL,
        retain_until=p_completed_at+interval '91 days',updated_at=p_completed_at,
        completed_at=p_completed_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_succeed_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_receipt_id uuid, p_request_sha256 bytea, p_result_sha256 bytea, p_provider_reference text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_export_unknown_v1(uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_export_unknown_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_cancelled boolean;
    v_request text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_unknown_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export unknown evidence is invalid';
    END IF;
    v_request := pg_catalog.encode(p_request_sha256,'hex');
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.authority_group_id='iam_system_resources'
      AND job.kind='iam.system-resource.record-export'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||p_export_id::text
      AND job.effect_idempotency_key='iam-system-export:'||p_export_id::text
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.record-export:'||p_export_id::text
      AND job.max_attempts=3
    FOR UPDATE;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id FOR UPDATE;
    IF v_job.state='dead' AND
       v_job.last_error_code='JOB_OUTCOME_UNKNOWN' AND
       v_attempt.outcome='dead' AND
       v_attempt.error_code='JOB_OUTCOME_UNKNOWN' THEN
        IF v_attempt.error_class IS NULL AND
           v_attempt.redacted_error_sha256 IS NULL AND
           v_attempt.effect_id=p_effect_id AND
           v_attempt.effect_request_sha256=v_request AND
           v_attempt.effect_receipt_id IS NULL AND
           v_attempt.finished_at=p_unknown_at AND
           v_job.completed_at=p_unknown_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export unknown replay differs';
    END IF;
    SELECT platform.platform_async_iam_export_current_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_attempt.effect_started_at IS NULL OR
       v_attempt.effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.effect_request_sha256 IS DISTINCT FROM v_request OR
       v_attempt.effect_receipt_id IS NOT NULL OR
       p_unknown_at<v_attempt.effect_started_at OR
       p_unknown_at<=v_job.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export unknown lease is stale';
    END IF;
    UPDATE platform.job_attempts SET finished_at=p_unknown_at,outcome='dead',
        error_class=NULL,error_code='JOB_OUTCOME_UNKNOWN',
        redacted_error_sha256=NULL,effect_receipt_id=NULL
    WHERE attempt_id=p_attempt_id;
    UPDATE platform.jobs SET state='dead',lease_owner_id=NULL,
        lease_heartbeat_at=NULL,lease_until=NULL,last_error_class=NULL,
        last_error_code='JOB_OUTCOME_UNKNOWN',last_error_sha256=NULL,
        retain_until=p_unknown_at+interval '366 days',updated_at=p_unknown_at,
        completed_at=p_unknown_at WHERE id=p_job_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_export_unknown_v1(p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_import_cleanup_read_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_import_cleanup_read_v1(p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_resource_kind text) RETURNS TABLE(job_state text, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_resource_kind NOT IN ('users','roles','organizations') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM import cleanup job read authority is invalid';
    END IF;
    RETURN QUERY
    SELECT job.state::text,job.completed_at
    FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.authority_group_id='iam_system_resources'
      AND job.kind='iam.system-resource.record-import'
      AND job.payload_revision=1
      AND job.effect_class='database_transactional'
      AND job.effect_idempotency_key IS NULL
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.record-import:'||p_import_id::text
      AND (job.payload_ref='iam-system-record/'||p_resource_kind||'/'||
           p_import_id::text OR
           (job.payload_ref IS NULL AND job.payload_redacted_at IS NOT NULL))
      AND job.max_attempts=8;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import cleanup job was not found';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_import_cleanup_read_v1(p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_import_cleanup_tenant_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_import_cleanup_tenant_v1(p_after_tenant_id uuid) RETURNS TABLE(tenant_id uuid, tenant_schema name)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM import cleanup inventory authority is invalid';
    END IF;
    RETURN QUERY
    SELECT tenant.id,tenant.schema_name::name
    FROM platform.tenants AS tenant
    JOIN platform.domain_cutovers AS authority
      ON authority.scope_kind='tenant' AND authority.scope_id=tenant.id
     AND authority.domain='iam' AND authority.state='v2'
     AND authority.writer='v2'
    WHERE tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE','TRIAL')
      AND (p_after_tenant_id IS NULL OR tenant.id>p_after_tenant_id)
    ORDER BY tenant.id
    LIMIT 1;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_import_cleanup_tenant_v1(p_after_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_iam_import_current_lease_v1(uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_iam_import_current_lease_v1(p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_lease_owner_id IS NULL OR p_lease_generation NOT BETWEEN 1 AND 8 OR
       p_resource_kind NOT IN ('users','roles','organizations') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM import lease authority is invalid';
    END IF;
    SELECT job.* INTO v_job
    FROM platform.jobs AS job
    WHERE job.id=p_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.authority_group_id='iam_system_resources'
      AND job.kind='iam.system-resource.record-import'
      AND job.payload_revision=1
      AND job.effect_class='database_transactional'
      AND job.effect_idempotency_key IS NULL
      AND job.dedupe_key='iam-system-transfer:'||
          'iam.system-resource.record-import:'||p_import_id::text
      AND job.payload_ref='iam-system-record/'||p_resource_kind||'/'||
          p_import_id::text
      AND job.max_attempts=8
    FOR SHARE;
    IF NOT FOUND OR v_job.state IS DISTINCT FROM 'running' OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_generation IS DISTINCT FROM p_lease_generation OR
       v_job.lease_until<=pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import lease is stale';
    END IF;
    SELECT attempt.* INTO v_attempt
    FROM platform.job_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id AND attempt.job_id=p_job_id
      AND attempt.scope_kind='tenant' AND attempt.scope_id=p_tenant_id
      AND attempt.attempt=p_lease_generation
      AND attempt.lease_generation=p_lease_generation
      AND attempt.lease_owner_id=p_lease_owner_id
    FOR SHARE;
    IF NOT FOUND OR v_attempt.finished_at IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import attempt is stale';
    END IF;
    RETURN v_job.cancel_requested_at IS NOT NULL;
END;
$$;


ALTER FUNCTION platform.platform_async_iam_import_current_lease_v1(p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: platform_async_initial_admin_setup_enqueue_v1(uuid, uuid, uuid, text, name, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_initial_admin_setup_enqueue_v1(p_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid, p_artifact_ref text, p_schema_name name, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_digest text;
    v_effect_key text;
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_inserted integer;
    v_existing platform.jobs%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_artifact_id IS NULL OR p_schema_name IS NULL
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR p_artifact_ref IS DISTINCT FROM
          'iam-lifecycle-delivery://tenant/' || p_tenant_id::text ||
          '/artifact/' || p_artifact_id::text
       OR NOT platform.tenancy_activation_assert_v2(
           p_operation_id,p_tenant_id,p_schema_name
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='initial admin setup delivery enqueue denied';
    END IF;
    v_digest := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to('iam.lifecycle.delivery.v1','UTF8') ||
        '\x00'::bytea || pg_catalog.convert_to(p_artifact_ref,'UTF8')
    ), 'hex');
    v_effect_key := 'iam.lifecycle.delivery:' || p_artifact_ref;
    INSERT INTO platform.jobs (
        id,tenant_id,scope_kind,scope_id,authority_group_id,
        authority_group_generation,authority_domain,cutover_generation,
        writer_origin,kind,payload_revision,payload_ref,payload_sha256,
        dedupe_key,effect_class,effect_idempotency_key,priority,run_at,
        state,attempts,max_attempts,lease_generation,retry_of_job_id
    ) VALUES (
        p_artifact_id,p_tenant_id,'tenant',p_tenant_id,
        'iam_system_resources',1,'iam',1,'v2','iam.lifecycle.delivery',1,
        p_artifact_ref,v_digest,p_artifact_id::text,'external',v_effect_key,
        100,v_now,'queued',0,8,0,NULL
    ) ON CONFLICT (id) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted=1 THEN
        RETURN false;
    END IF;
    SELECT * INTO v_existing FROM platform.jobs AS job
    WHERE job.id=p_artifact_id FOR SHARE;
    IF NOT FOUND OR ROW(v_existing.tenant_id,v_existing.scope_kind,
        v_existing.scope_id,v_existing.authority_group_id,
        v_existing.authority_group_generation,v_existing.authority_domain,
        v_existing.cutover_generation,v_existing.writer_origin,
        v_existing.kind,v_existing.payload_revision,v_existing.payload_ref,
        v_existing.payload_sha256,v_existing.dedupe_key,
        v_existing.effect_class,v_existing.effect_idempotency_key)
       IS DISTINCT FROM ROW(p_tenant_id,'tenant',p_tenant_id,
        'iam_system_resources',1::bigint,'iam',1::bigint,'v2',
        'iam.lifecycle.delivery',1,p_artifact_ref,v_digest,
        p_artifact_id::text,'external',v_effect_key) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='initial admin setup delivery replay conflicts';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platform_async_initial_admin_setup_enqueue_v1(p_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid, p_artifact_ref text, p_schema_name name, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_initial_admin_setup_enqueue_v2(uuid, uuid, uuid, uuid, text, name, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_initial_admin_setup_enqueue_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_artifact_id uuid, p_artifact_ref text, p_schema_name name, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET application_name TO 'harpy-v2:core-operator-initialize'
    AS $$
DECLARE
    v_replayed boolean;
BEGIN
    IF NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id, 'activation.complete', p_environment_id,
        p_tenant_id, p_schema_name, 'saas_customer_tenant_provision'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'initial admin setup enqueue capability required';
    END IF;
    v_replayed := platform.platform_async_initial_admin_setup_enqueue_v1(
        p_operation_id, p_tenant_id, p_artifact_id, p_artifact_ref,
        p_schema_name, p_manifest_sha256
    );
    INSERT INTO platform.platform_async_installation_activation_receipts (
        operation_id, receipt_kind, environment_id, tenant_id, job_id,
        manifest_sha256
    ) VALUES (
        p_operation_id, 'initial_admin_setup', p_environment_id, p_tenant_id,
        p_artifact_id, p_manifest_sha256
    ) ON CONFLICT (operation_id, receipt_kind) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM platform.platform_async_installation_activation_receipts r
        WHERE r.operation_id = p_operation_id
          AND r.receipt_kind = 'initial_admin_setup'
          AND ROW(r.environment_id,r.tenant_id,r.job_id,r.manifest_sha256)
              = ROW(p_environment_id,p_tenant_id,p_artifact_id,p_manifest_sha256)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'initial admin setup activation receipt conflicts';
    END IF;
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.platform_async_initial_admin_setup_enqueue_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_artifact_id uuid, p_artifact_ref text, p_schema_name name, p_manifest_sha256 text) OWNER TO harpy_owner;

