--
-- Name: platform_async_installation_activation_event_v1(uuid, uuid, uuid, uuid, name, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_installation_activation_event_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_schema_name name, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_payload bytea;
    v_payload_sha256 text;
    v_payload_schema_sha256 text;
    v_occurred_at timestamptz := pg_catalog.statement_timestamp();
    v_inserted integer;
    v_existing platform.outbox%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_actor_id IS NULL OR p_schema_name IS NULL
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation activation event denied';
    END IF;
    IF NOT platform.tenancy_activation_assert_v1(
        p_operation_id, p_tenant_id, p_schema_name
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'installation activation event conflicts';
    END IF;
    v_payload := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
        'environment_id', p_environment_id::text,
        'manifest_sha256', p_manifest_sha256,
        'operation_id', p_operation_id::text,
        'tenant_id', p_tenant_id::text
    )::text, 'UTF8');
    v_payload_sha256 := pg_catalog.encode(pg_catalog.sha256(v_payload), 'hex');
    v_payload_schema_sha256 := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to('installation.activation.v1', 'UTF8')
    ), 'hex');
    INSERT INTO platform.outbox (
        event_id, tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation,
        authority_domain, cutover_generation, writer_origin,
        envelope_contract_version, event_type, event_version,
        aggregate_type, aggregate_id, aggregate_version, event_sequence,
        occurred_at, actor_id, correlation_id, causation_id,
        idempotency_key, business_effect_idempotency_key,
        payload_canonical, payload_sha256, payload_schema_sha256,
        delivery_state, delivery_attempts, lease_generation, next_attempt_at
    ) VALUES (
        p_operation_id, p_tenant_id, 'tenant', p_tenant_id,
        'iam_system_resources', 1, 'iam', 1, 'v2',
        'integration-event.v1', 'installation.activated', 1,
        'installation.environment', p_tenant_id, 1, 1,
        v_occurred_at, p_actor_id,
        'installation:' || p_operation_id::text, p_operation_id,
        'installation.activation:' || p_operation_id::text,
        'installation.activation:' || p_operation_id::text,
        v_payload, v_payload_sha256, v_payload_schema_sha256,
        'pending', 0, 0, v_occurred_at
    ) ON CONFLICT (event_id) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 1 THEN
        RETURN false;
    END IF;
    SELECT * INTO v_existing
    FROM platform.outbox AS event
    WHERE event.event_id = p_operation_id
    FOR SHARE;
    IF NOT FOUND OR ROW(v_existing.tenant_id, v_existing.scope_kind,
        v_existing.scope_id, v_existing.authority_group_id,
        v_existing.authority_group_generation, v_existing.authority_domain,
        v_existing.cutover_generation, v_existing.writer_origin,
        v_existing.envelope_contract_version, v_existing.event_type,
        v_existing.event_version, v_existing.aggregate_type,
        v_existing.aggregate_id, v_existing.aggregate_version,
        v_existing.event_sequence, v_existing.actor_id,
        v_existing.causation_id, v_existing.idempotency_key,
        v_existing.business_effect_idempotency_key,
        v_existing.payload_canonical, v_existing.payload_sha256,
        v_existing.payload_schema_sha256)
       IS DISTINCT FROM ROW(p_tenant_id, 'tenant', p_tenant_id,
        'iam_system_resources', 1::bigint, 'iam', 1::bigint, 'v2',
        'integration-event.v1', 'installation.activated', 1,
        'installation.environment', p_tenant_id, 1::bigint, 1::bigint,
        p_actor_id, p_operation_id,
        'installation.activation:' || p_operation_id::text,
        'installation.activation:' || p_operation_id::text,
        v_payload, v_payload_sha256, v_payload_schema_sha256) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'installation activation event replay conflicts';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platform_async_installation_activation_event_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_schema_name name, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_installation_activation_event_v2(uuid, uuid, uuid, uuid, name, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_installation_activation_event_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_schema_name name, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET application_name TO 'harpy-v2:core-operator-initialize'
    AS $$
DECLARE
    v_replayed boolean;
    v_authorized boolean;
BEGIN
    v_authorized :=
        platform.tenancy_activation_step_context_assert_v1(
            p_operation_id, 'activation.complete', p_environment_id,
            p_tenant_id, p_schema_name, 'environment_initialize'
        ) OR platform.tenancy_activation_step_context_assert_v1(
            p_operation_id, 'activation.complete', p_environment_id,
            p_tenant_id, p_schema_name, 'saas_customer_tenant_provision'
        );
    IF NOT v_authorized THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation activation event capability required';
    END IF;
    v_replayed := platform.platform_async_installation_activation_event_v1(
        p_operation_id, p_environment_id, p_tenant_id, p_actor_id,
        p_schema_name, p_manifest_sha256
    );
    INSERT INTO platform.platform_async_installation_activation_receipts (
        operation_id, receipt_kind, environment_id, tenant_id, event_id,
        manifest_sha256
    ) VALUES (
        p_operation_id, 'activation_event', p_environment_id, p_tenant_id,
        p_operation_id, p_manifest_sha256
    ) ON CONFLICT (operation_id, receipt_kind) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM platform.platform_async_installation_activation_receipts r
        WHERE r.operation_id = p_operation_id
          AND r.receipt_kind = 'activation_event'
          AND ROW(r.environment_id,r.tenant_id,r.event_id,r.manifest_sha256)
              = ROW(p_environment_id,p_tenant_id,p_operation_id,p_manifest_sha256)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'installation activation event receipt conflicts';
    END IF;
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.platform_async_installation_activation_event_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_schema_name name, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_installation_activation_evidence_assert_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_installation_activation_evidence_assert_v1(p_operation_id uuid, p_expected_artifact_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN SESSION_USER = 'harpy_v2_runtime'
       AND CURRENT_USER = 'harpy_owner'
       AND EXISTS (
        SELECT 1
        FROM platform.platform_async_installation_activation_receipts event
        JOIN platform.outbox outbox ON outbox.event_id = event.event_id
        LEFT JOIN platform.platform_async_installation_activation_receipts setup
          ON setup.operation_id = event.operation_id
         AND setup.receipt_kind = 'initial_admin_setup'
         AND ROW(setup.environment_id,setup.tenant_id,setup.manifest_sha256)
             = ROW(event.environment_id,event.tenant_id,event.manifest_sha256)
        LEFT JOIN platform.jobs job ON job.id = setup.job_id
        WHERE event.operation_id = p_operation_id
          AND event.receipt_kind = 'activation_event'
          AND ROW(outbox.tenant_id,outbox.scope_kind,outbox.scope_id,
              outbox.writer_origin,outbox.event_type,outbox.aggregate_type,
              outbox.aggregate_id,outbox.causation_id,outbox.idempotency_key,
              outbox.business_effect_idempotency_key)
          = ROW(event.tenant_id,'tenant',event.tenant_id,'v2',
              'installation.activated','installation.environment',
              event.tenant_id,event.operation_id,
              'installation.activation:' || event.operation_id::text,
              'installation.activation:' || event.operation_id::text)
          AND outbox.payload_canonical = pg_catalog.convert_to(
              pg_catalog.jsonb_build_object(
                'environment_id',event.environment_id::text,
                'manifest_sha256',event.manifest_sha256,
                'operation_id',event.operation_id::text,
                'tenant_id',event.tenant_id::text
              )::text,'UTF8'
          )
          AND (p_expected_artifact_id IS NULL OR (
              setup.job_id = p_expected_artifact_id
          AND ROW(job.tenant_id,job.scope_kind,job.scope_id,
              job.authority_group_id,job.authority_group_generation,
              job.authority_domain,job.cutover_generation,job.writer_origin,
              job.kind,job.payload_ref,job.dedupe_key,job.effect_class,
              job.effect_idempotency_key)
          = ROW(setup.tenant_id,'tenant',setup.tenant_id,
              'iam_system_resources',1::bigint,'iam',1::bigint,'v2',
              'iam.lifecycle.delivery',
              'iam-lifecycle-delivery://tenant/' || setup.tenant_id::text ||
                  '/artifact/' || setup.job_id::text,
              setup.job_id::text,'external',
              'iam.lifecycle.delivery:iam-lifecycle-delivery://tenant/' ||
                  setup.tenant_id::text || '/artifact/' || setup.job_id::text)
          ))
       );
END;
$$;


ALTER FUNCTION platform.platform_async_installation_activation_evidence_assert_v1(p_operation_id uuid, p_expected_artifact_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_is_gap_requeue_v1(platform.outbox, platform.outbox, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_is_gap_requeue_v1(p_old platform.outbox, p_new platform.outbox, p_now timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN (
SELECT
    p_old.delivery_state = 'delivered'
    AND p_new.delivery_state = 'pending'
    AND p_old.payload_canonical IS NOT NULL
    AND p_old.payload_redacted_at IS NULL
    AND p_new.payload_canonical IS NOT DISTINCT FROM p_old.payload_canonical
    AND p_new.payload_redacted_at IS NULL
    AND p_new.delivery_attempts = p_old.delivery_attempts
    AND p_new.lease_generation = p_old.lease_generation
    AND p_new.lease_owner_id IS NULL
    AND p_new.lease_heartbeat_at IS NULL
    AND p_new.lease_until IS NULL
    AND p_new.next_attempt_at <= p_now
    AND p_new.next_attempt_at >= p_old.updated_at
    AND p_new.confirmed_at IS NULL
    AND p_new.delivered_at IS NULL
    AND p_new.confirm_sha256 IS NULL
    AND p_new.last_error_code IS NULL
    AND p_new.last_error_sha256 IS NULL
    AND p_new.parked_at IS NOT DISTINCT FROM p_old.parked_at
    AND p_new.parked_code IS NOT DISTINCT FROM p_old.parked_code
    AND p_new.parked_current_group_generation
        IS NOT DISTINCT FROM p_old.parked_current_group_generation
    AND p_new.parked_current_cutover_generation
        IS NOT DISTINCT FROM p_old.parked_current_cutover_generation
    AND EXISTS (
        SELECT 1
        FROM platform.jobs AS job
        JOIN platform.dead_letters AS root
          ON job.payload_ref = 'deadletter:event-gap:' || root.id::text
        JOIN platform.dead_letters AS action
          ON action.id = job.id AND action.root_id = root.id
        WHERE job.state = 'running'
          AND job.kind = 'platform_async.event_gap_reconcile.' ||
              job.authority_domain
          AND job.effect_class = 'database_transactional'
          AND root.record_kind = 'root' AND root.source_kind = 'event'
          AND root.source_id = p_old.event_id
          AND root.reason_class = 'sequence_gap'
          AND action.record_kind = 'retry_action'
          AND action.source_id = p_old.event_id
          AND action.recorded_at = p_new.next_attempt_at
          AND platform.platform_async_event_gap_job_ready_v1(job.id)
    )
);
END;
$$;


ALTER FUNCTION platform.platform_async_is_gap_requeue_v1(p_old platform.outbox, p_new platform.outbox, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_outbox_authority_current_v1(platform.outbox); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_outbox_authority_current_v1(p_event platform.outbox) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_group_state text;
    v_group_writer text;
    v_group_generation bigint;
    v_domain_state text;
    v_domain_writer text;
    v_domain_generation bigint;
    v_member boolean;
BEGIN
    SELECT authority_group.state,authority_group.writer,
        authority_group.generation
    INTO v_group_state,v_group_writer,v_group_generation
    FROM platform.cutover_groups AS authority_group
    WHERE authority_group.scope_kind = p_event.scope_kind
      AND authority_group.scope_id = p_event.scope_id
      AND authority_group.group_id = p_event.authority_group_id
    FOR SHARE;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    SELECT authority_domain.state,authority_domain.writer,
        authority_domain.generation
    INTO v_domain_state,v_domain_writer,v_domain_generation
    FROM platform.domain_cutovers AS authority_domain
    WHERE authority_domain.scope_kind = p_event.scope_kind
      AND authority_domain.scope_id = p_event.scope_id
      AND authority_domain.domain = p_event.authority_domain
    FOR SHARE;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    SELECT true INTO v_member FROM platform.cutover_group_members AS member
    WHERE member.scope_kind = p_event.scope_kind
      AND member.scope_id = p_event.scope_id
      AND member.group_id = p_event.authority_group_id
      AND member.domain = p_event.authority_domain
    FOR SHARE;
    RETURN p_event.parked_at IS NULL AND p_event.writer_origin = 'v2'
        AND v_group_state = 'v2' AND v_group_writer = 'v2'
        AND v_group_generation = p_event.authority_group_generation
        AND v_domain_state = 'v2' AND v_domain_writer = 'v2'
        AND v_domain_generation = p_event.cutover_generation
        AND COALESCE(v_member,false);
END;
$$;


ALTER FUNCTION platform.platform_async_outbox_authority_current_v1(p_event platform.outbox) OWNER TO harpy_owner;

--
-- Name: platform_async_park_stale_outbox_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_park_stale_outbox_v1(p_event_id uuid, p_dead_letter_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_event platform.outbox%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_error_sha256 text;
BEGIN
    IF SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' OR
       p_event_id IS NULL OR p_dead_letter_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5653',
            MESSAGE = 'stale outbox park input is invalid';
    END IF;

    SELECT * INTO v_event
    FROM platform.outbox
    WHERE event_id OPERATOR(pg_catalog.=) p_event_id;
    IF NOT FOUND OR v_event.parked_at IS NOT NULL THEN
        RETURN false;
    END IF;

    SELECT generation INTO v_group_generation
    FROM platform.cutover_groups
    WHERE scope_kind OPERATOR(pg_catalog.=) v_event.scope_kind
      AND scope_id OPERATOR(pg_catalog.=) v_event.scope_id
      AND group_id OPERATOR(pg_catalog.=) v_event.authority_group_id
      AND state OPERATOR(pg_catalog.=) 'v2'
      AND writer OPERATOR(pg_catalog.=) 'v2'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5654',
            MESSAGE = 'current outbox group authority is unavailable';
    END IF;

    SELECT generation INTO v_domain_generation
    FROM platform.domain_cutovers
    WHERE scope_kind OPERATOR(pg_catalog.=) v_event.scope_kind
      AND scope_id OPERATOR(pg_catalog.=) v_event.scope_id
      AND domain OPERATOR(pg_catalog.=) v_event.authority_domain
      AND state OPERATOR(pg_catalog.=) 'v2'
      AND writer OPERATOR(pg_catalog.=) 'v2'
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind OPERATOR(pg_catalog.=) v_event.scope_kind
          AND scope_id OPERATOR(pg_catalog.=) v_event.scope_id
          AND group_id OPERATOR(pg_catalog.=) v_event.authority_group_id
          AND domain OPERATOR(pg_catalog.=) v_event.authority_domain
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5655',
            MESSAGE = 'current outbox domain authority is unavailable';
    END IF;

    SELECT * INTO v_event
    FROM platform.outbox
    WHERE event_id OPERATOR(pg_catalog.=) p_event_id
    FOR UPDATE;
    IF v_event.parked_at IS NOT NULL OR
       NOT (
           v_event.delivery_state OPERATOR(pg_catalog.=) 'pending' OR
           (v_event.delivery_state OPERATOR(pg_catalog.=) 'publishing' AND
            v_event.lease_until OPERATOR(pg_catalog.<=) v_now)
       ) THEN
        RETURN false;
    END IF;
    IF v_group_generation < v_event.authority_group_generation OR
       v_domain_generation < v_event.cutover_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5656',
            MESSAGE = 'outbox authority generation moved backwards';
    END IF;
    IF v_group_generation = v_event.authority_group_generation AND
       v_domain_generation = v_event.cutover_generation THEN
        RETURN false;
    END IF;

    UPDATE platform.outbox
    SET delivery_state = 'pending',
        lease_owner_id = NULL,
        lease_heartbeat_at = NULL,
        lease_until = NULL,
        parked_at = v_now,
        parked_code = 'OUTBOX_AUTHORITY_STALE',
        parked_current_group_generation = v_group_generation,
        parked_current_cutover_generation = v_domain_generation,
        updated_at = v_now
    WHERE event_id OPERATOR(pg_catalog.=) v_event.event_id;

    v_error_sha256 := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(
            'outbox-authority-stale.v1' || pg_catalog.chr(10) ||
            v_event.event_id::text || pg_catalog.chr(10) ||
            v_event.authority_group_generation::text || pg_catalog.chr(10) ||
            v_event.cutover_generation::text || pg_catalog.chr(10) ||
            v_group_generation::text || pg_catalog.chr(10) ||
            v_domain_generation::text,
            'UTF8'
        )
    ), 'hex');

    INSERT INTO platform.dead_letters (
        id, root_id, entry_sequence, record_kind,
        tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation,
        authority_domain, cutover_generation, writer_origin,
        source_kind, source_id, consumer_name, consumer_version,
        source_contract, source_version, source_sha256,
        reason_class, reason_code, redacted_error_sha256,
        payload_canonical, payload_sha256, redacted_envelope,
        full_payload_expires_at, metadata_expires_at, recorded_at
    ) VALUES (
        p_dead_letter_id, p_dead_letter_id, 0, 'root',
        v_event.tenant_id, v_event.scope_kind, v_event.scope_id,
        v_event.authority_group_id, v_group_generation,
        v_event.authority_domain, v_domain_generation, 'v2',
        'event', v_event.event_id, 'platform.outbox.publisher', 1,
        v_event.envelope_contract_version, v_event.event_version,
        v_event.payload_sha256,
        'stale_generation', 'OUTBOX_AUTHORITY_STALE', v_error_sha256,
        v_event.payload_canonical, v_event.payload_sha256,
        pg_catalog.jsonb_build_object(
            'contract', 'outbox-authority-stale.v1',
            'event_id', v_event.event_id,
            'event_type', v_event.event_type,
            'stored_group_generation', v_event.authority_group_generation,
            'stored_domain_generation', v_event.cutover_generation,
            'current_group_generation', v_group_generation,
            'current_domain_generation', v_domain_generation
        ),
        v_now + interval '30 days', v_now + interval '365 days', v_now
    );
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platform_async_park_stale_outbox_v1(p_event_id uuid, p_dead_letter_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_park_stale_work_v1(uuid, uuid, bigint, uuid, bytea, text, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_park_stale_work_v1(p_job_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_dead_letter_id uuid, p_payload_canonical bytea, p_payload_sha256 text, p_redacted_envelope jsonb, p_error_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' OR
       p_job_id IS NULL OR p_lease_owner_id IS NULL OR
       p_lease_generation OPERATOR(pg_catalog.<) 1 OR p_dead_letter_id IS NULL OR
       p_payload_canonical IS NULL OR p_payload_sha256 !~ '^[0-9a-f]{64}$' OR
       p_redacted_envelope IS NULL OR p_error_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5630',
            MESSAGE = 'stale async work park input is invalid';
    END IF;

    SELECT * INTO v_job
    FROM platform.jobs
    WHERE id OPERATOR(pg_catalog.=) p_job_id;
    IF NOT FOUND THEN
        RETURN false;
    END IF;

    SELECT generation INTO v_group_generation
    FROM platform.cutover_groups
    WHERE scope_kind OPERATOR(pg_catalog.=) v_job.scope_kind
      AND scope_id OPERATOR(pg_catalog.=) v_job.scope_id
      AND group_id OPERATOR(pg_catalog.=) v_job.authority_group_id
      AND state OPERATOR(pg_catalog.=) 'v2'
      AND writer OPERATOR(pg_catalog.=) 'v2'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5631',
            MESSAGE = 'current async group authority is unavailable';
    END IF;

    SELECT generation INTO v_domain_generation
    FROM platform.domain_cutovers
    WHERE scope_kind OPERATOR(pg_catalog.=) v_job.scope_kind
      AND scope_id OPERATOR(pg_catalog.=) v_job.scope_id
      AND domain OPERATOR(pg_catalog.=) v_job.authority_domain
      AND state OPERATOR(pg_catalog.=) 'v2'
      AND writer OPERATOR(pg_catalog.=) 'v2'
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind OPERATOR(pg_catalog.=) v_job.scope_kind
          AND scope_id OPERATOR(pg_catalog.=) v_job.scope_id
          AND group_id OPERATOR(pg_catalog.=) v_job.authority_group_id
          AND domain OPERATOR(pg_catalog.=) v_job.authority_domain
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5632',
            MESSAGE = 'current async domain authority is unavailable';
    END IF;

    SELECT * INTO v_job
    FROM platform.jobs
    WHERE id OPERATOR(pg_catalog.=) p_job_id
    FOR UPDATE;
    IF v_job.state OPERATOR(pg_catalog.<>) 'running' OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_generation IS DISTINCT FROM p_lease_generation OR
       v_job.lease_until IS NULL OR
       v_job.lease_until OPERATOR(pg_catalog.<=) v_now OR
       v_job.effect_started_at IS NOT NULL THEN
        RETURN false;
    END IF;
    IF v_job.payload_sha256 OPERATOR(pg_catalog.<>) p_payload_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5635',
            MESSAGE = 'stale async work payload digest differs';
    END IF;
    IF v_group_generation OPERATOR(pg_catalog.<) v_job.authority_group_generation OR
       v_domain_generation OPERATOR(pg_catalog.<) v_job.cutover_generation OR
       (v_group_generation OPERATOR(pg_catalog.=) v_job.authority_group_generation AND
        v_domain_generation OPERATOR(pg_catalog.=) v_job.cutover_generation) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5633',
            MESSAGE = 'async work authority is not stale';
    END IF;

    UPDATE platform.job_attempts
    SET finished_at = v_now,
        outcome = 'lease_expired',
        error_class = 'conflict',
        error_code = 'JOB_AUTHORITY_STALE',
        redacted_error_sha256 = p_error_sha256
    WHERE job_id OPERATOR(pg_catalog.=) v_job.id
      AND attempt OPERATOR(pg_catalog.=) v_job.attempts
      AND lease_generation OPERATOR(pg_catalog.=) p_lease_generation
      AND lease_owner_id OPERATOR(pg_catalog.=) p_lease_owner_id
      AND finished_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5634',
            MESSAGE = 'active async attempt is unavailable';
    END IF;

    UPDATE platform.jobs
    SET state = 'queued',
        lease_owner_id = NULL,
        lease_heartbeat_at = NULL,
        lease_until = NULL,
        parked_at = v_now,
        parked_code = 'JOB_AUTHORITY_STALE',
        parked_current_group_generation = v_group_generation,
        parked_current_cutover_generation = v_domain_generation,
        updated_at = v_now
    WHERE id OPERATOR(pg_catalog.=) v_job.id;

    INSERT INTO platform.dead_letters (
        id, root_id, entry_sequence, record_kind,
        tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation,
        authority_domain, cutover_generation, writer_origin,
        source_kind, source_id, source_contract, source_version, source_sha256,
        reason_class, reason_code, redacted_error_sha256,
        payload_canonical, payload_sha256, redacted_envelope,
        full_payload_expires_at, metadata_expires_at, recorded_at
    ) VALUES (
        p_dead_letter_id, p_dead_letter_id, 0, 'root',
        v_job.tenant_id, v_job.scope_kind, v_job.scope_id,
        v_job.authority_group_id, v_group_generation,
        v_job.authority_domain, v_domain_generation, 'v2',
        'job', v_job.id, v_job.kind, v_job.payload_revision, v_job.payload_sha256,
        'stale_generation', 'JOB_AUTHORITY_STALE', p_error_sha256,
        p_payload_canonical, p_payload_sha256, p_redacted_envelope,
        v_now + interval '30 days', v_now + interval '365 days', v_now
    );
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platform_async_park_stale_work_v1(p_job_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_dead_letter_id uuid, p_payload_canonical bytea, p_payload_sha256 text, p_redacted_envelope jsonb, p_error_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_park_stale_work_v2(uuid, text, uuid, bigint, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_park_stale_work_v2(p_job_id uuid, p_expected_state text, p_lease_owner_id uuid, p_lease_generation bigint, p_dead_letter_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_payload bytea;
    v_payload_sha256 text;
    v_error_sha256 text;
    v_redacted_envelope jsonb;
BEGIN
    IF SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' OR
       p_job_id IS NULL OR p_dead_letter_id IS NULL OR
       NOT ((p_expected_state = 'queued' AND p_lease_owner_id IS NULL AND
             p_lease_generation >= 0) OR
            (p_expected_state = 'running' AND p_lease_owner_id IS NOT NULL AND
             p_lease_generation >= 1)) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5630',
            MESSAGE = 'stale async work park input is invalid';
    END IF;

    SELECT * INTO v_job FROM platform.jobs WHERE id = p_job_id;
    IF NOT FOUND THEN
        RETURN false;
    END IF;

    SELECT generation INTO v_group_generation
    FROM platform.cutover_groups
    WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
      AND group_id = v_job.authority_group_id
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5631',
            MESSAGE = 'current async group authority is unavailable';
    END IF;

    SELECT generation INTO v_domain_generation
    FROM platform.domain_cutovers
    WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
      AND domain = v_job.authority_domain
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
          AND group_id = v_job.authority_group_id
          AND domain = v_job.authority_domain
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5632',
            MESSAGE = 'current async domain authority is unavailable';
    END IF;

    SELECT * INTO v_job FROM platform.jobs WHERE id = p_job_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    IF v_job.state IS DISTINCT FROM p_expected_state OR
       v_job.parked_at IS NOT NULL OR v_job.effect_started_at IS NOT NULL OR
       v_job.lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_job.lease_generation IS DISTINCT FROM p_lease_generation THEN
        RETURN false;
    END IF;
    IF v_group_generation < v_job.authority_group_generation OR
       v_domain_generation < v_job.cutover_generation OR
       (v_group_generation = v_job.authority_group_generation AND
        v_domain_generation = v_job.cutover_generation) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5633',
            MESSAGE = 'async work authority is not stale';
    END IF;

    v_payload := pg_catalog.convert_to(
        '{"contract_version":"harpy.job-stale-reference.v1","job_id":' ||
        pg_catalog.to_json(v_job.id::text)::text || ',"kind":' ||
        pg_catalog.to_json(v_job.kind)::text || ',"payload_reference":' ||
        pg_catalog.to_json(v_job.payload_ref)::text || ',"payload_revision":' ||
        v_job.payload_revision::text || ',"payload_sha256":' ||
        pg_catalog.to_json(v_job.payload_sha256)::text || '}', 'UTF8'
    );
    v_payload_sha256 := pg_catalog.encode(pg_catalog.sha256(v_payload), 'hex');
    v_error_sha256 := pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to('JOB_AUTHORITY_STALE', 'UTF8')), 'hex'
    );
    v_redacted_envelope := pg_catalog.jsonb_build_object(
        'contract_version', 'harpy.job-stale-reference.v1',
        'job_id', v_job.id, 'kind', v_job.kind,
        'payload_revision', v_job.payload_revision,
        'payload_sha256', v_job.payload_sha256
    );

    INSERT INTO platform.dead_letters (
        id, root_id, entry_sequence, record_kind, tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation, authority_domain,
        cutover_generation, writer_origin, source_kind, source_id, source_contract,
        source_version, source_sha256, reason_class, reason_code,
        redacted_error_sha256, payload_canonical, payload_sha256,
        redacted_envelope, full_payload_expires_at, metadata_expires_at, recorded_at
    ) VALUES (
        p_dead_letter_id, p_dead_letter_id, 0, 'root', v_job.tenant_id,
        v_job.scope_kind, v_job.scope_id, v_job.authority_group_id,
        v_group_generation, v_job.authority_domain, v_domain_generation, 'v2',
        'job', v_job.id, v_job.kind, v_job.payload_revision, v_job.payload_sha256,
        'stale_generation', 'JOB_AUTHORITY_STALE', v_error_sha256,
        v_payload, v_payload_sha256, v_redacted_envelope,
        v_now + interval '30 days', v_now + interval '365 days', v_now
    );

    IF v_job.state = 'running' THEN
        UPDATE platform.job_attempts
        SET finished_at = v_now, outcome = 'lease_expired',
            error_class = 'conflict', error_code = 'JOB_AUTHORITY_STALE',
            redacted_error_sha256 = v_error_sha256
        WHERE job_id = v_job.id AND attempt = v_job.attempts
          AND lease_generation = v_job.lease_generation
          AND lease_owner_id = v_job.lease_owner_id AND finished_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = 'P5634',
                MESSAGE = 'active async attempt is unavailable';
        END IF;
    END IF;

    UPDATE platform.jobs
    SET state = 'queued', lease_owner_id = NULL, lease_heartbeat_at = NULL,
        lease_until = NULL, parked_at = v_now, parked_code = 'JOB_AUTHORITY_STALE',
        parked_current_group_generation = v_group_generation,
        parked_current_cutover_generation = v_domain_generation, updated_at = v_now
    WHERE id = v_job.id;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platform_async_park_stale_work_v2(p_job_id uuid, p_expected_state text, p_lease_owner_id uuid, p_lease_generation bigint, p_dead_letter_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_async_purge_dead_letters_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_purge_dead_letters_v1(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'unsafe dead-letter purge v1 is retired; use v2';
END;
$$;


ALTER FUNCTION platform.platform_async_purge_dead_letters_v1(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_purge_dead_letters_v2(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_purge_dead_letters_v2(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_root_id uuid;
    v_root platform.dead_letters%ROWTYPE;
    v_count integer;
    v_changed integer;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    v_count := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'async retention session authority is invalid';
    END IF;
    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async purge batch size must be between 1 and 500';
    END IF;

    FOR v_root_id IN
        SELECT root.id
        FROM platform.dead_letters AS root
        WHERE root.record_kind = 'root'
          AND root.metadata_expires_at <= v_now
          AND root.payload_canonical IS NULL
          AND root.payload_redacted_at IS NOT NULL
          AND NOT platform.platform_async_has_live_event_gap_root_v1(root)
          AND NOT platform.platform_async_has_live_stale_job_root_v1(root)
        ORDER BY root.metadata_expires_at,root.id
        LIMIT p_batch_size
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
            'harpy:deadletter:' || v_root_id::text,0));
        SELECT root.* INTO v_root
        FROM platform.dead_letters AS root
        WHERE root.id = v_root_id AND root.record_kind = 'root'
          AND root.metadata_expires_at <= v_now
          AND root.payload_canonical IS NULL
          AND root.payload_redacted_at IS NOT NULL
        FOR UPDATE;
        IF NOT FOUND OR
           platform.platform_async_has_live_event_gap_root_v1(v_root) OR
           platform.platform_async_has_live_stale_job_root_v1(v_root) THEN
            CONTINUE;
        END IF;
        DELETE FROM platform.dead_letters AS action
        WHERE action.root_id = v_root_id AND action.id <> v_root_id;
        DELETE FROM platform.dead_letters AS root
        WHERE root.id = v_root_id AND root.root_id = root.id;
        GET DIAGNOSTICS v_changed = ROW_COUNT;
        v_count := v_count + v_changed;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platform_async_purge_dead_letters_v2(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_purge_idempotency_receipts_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_purge_idempotency_receipts_v1(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_count integer;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async purge batch size must be between 1 and 500';
    END IF;

    WITH candidates AS (
        SELECT receipt.receipt_id
        FROM platform.idempotency_receipts AS receipt
        WHERE receipt.retain_until <= v_now
          AND (
              receipt.retention_class <> 'async_handle' OR EXISTS (
                  SELECT 1
                  FROM platform.jobs AS job
                  WHERE job.scope_kind = receipt.scope_kind
                    AND job.scope_id = receipt.scope_id
                    AND job.id = receipt.async_job_id
                    AND job.state IN ('succeeded', 'dead', 'cancelled')
                    AND job.completed_at <= v_now - interval '24 hours'
              )
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.job_attempts AS attempt
              WHERE attempt.effect_receipt_id = receipt.receipt_id
          )
        ORDER BY receipt.retain_until, receipt.receipt_id
        FOR UPDATE SKIP LOCKED
        LIMIT p_batch_size
    )
    DELETE FROM platform.idempotency_receipts AS receipt
    USING candidates
    WHERE receipt.receipt_id = candidates.receipt_id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platform_async_purge_idempotency_receipts_v1(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_purge_inbox_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_purge_inbox_v1(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_count integer;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async purge batch size must be between 1 and 500';
    END IF;

    WITH candidates AS (
        SELECT inbox_row.id
        FROM platform.inbox AS inbox_row
        WHERE inbox_row.recorded_at <= v_now - interval '180 days'
          AND (
              inbox_row.record_kind = 'event_receipt' OR
              (inbox_row.record_kind = 'watermark' AND EXISTS (
                  SELECT 1
                  FROM platform.inbox AS newer
                  WHERE newer.record_kind = 'watermark'
                    AND newer.consumer_name = inbox_row.consumer_name
                    AND newer.consumer_version = inbox_row.consumer_version
                    AND newer.scope_kind = inbox_row.scope_kind
                    AND newer.scope_id = inbox_row.scope_id
                    AND newer.aggregate_type = inbox_row.aggregate_type
                    AND newer.aggregate_id = inbox_row.aggregate_id
                    AND newer.through_sequence > inbox_row.through_sequence
              ))
          )
        ORDER BY inbox_row.recorded_at, inbox_row.id
        FOR UPDATE SKIP LOCKED
        LIMIT p_batch_size
    )
    DELETE FROM platform.inbox AS inbox_row
    USING candidates
    WHERE inbox_row.id = candidates.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platform_async_purge_inbox_v1(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_purge_jobs_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_purge_jobs_v1(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_job_id uuid;
    v_deleted integer;
    v_count integer;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    v_count := 0;
    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async purge batch size must be between 1 and 500';
    END IF;

    FOR v_job_id IN
        SELECT job.id
        FROM platform.jobs AS job
        WHERE job.state IN ('succeeded', 'dead', 'cancelled')
          AND job.payload_ref IS NULL
          AND job.payload_redacted_at IS NOT NULL
          AND job.retain_until <= v_now
          AND job.retention_release_revision > 0
          AND job.retention_release_sha256 IS NOT NULL
          AND job.retention_released_at IS NOT NULL
          AND job.retention_released_at <= v_now
          AND NOT EXISTS (
              SELECT 1
              FROM platform.job_attempts AS attempt
              WHERE attempt.job_id = job.id
                AND attempt.finished_at IS NULL
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.idempotency_receipts AS receipt
              WHERE receipt.async_job_id = job.id
          )
          AND NOT EXISTS (
              SELECT 1
              FROM platform.jobs AS retry
              WHERE retry.retry_of_job_id = job.id
          )
        ORDER BY job.retain_until, job.id
        FOR UPDATE SKIP LOCKED
        LIMIT p_batch_size
    LOOP
        DELETE FROM platform.job_attempts AS attempt
        WHERE attempt.job_id = v_job_id;

        DELETE FROM platform.jobs AS job
        WHERE job.id = v_job_id;
        GET DIAGNOSTICS v_deleted = ROW_COUNT;
        v_count := v_count + v_deleted;
    END LOOP;

    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platform_async_purge_jobs_v1(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_reconcile_event_gap_v1(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_reconcile_event_gap_v1(p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) RETURNS TABLE(completed_at timestamp with time zone, requeued boolean, action_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_root platform.dead_letters%ROWTYPE;
    v_event platform.outbox%ROWTYPE;
    v_gap jsonb;
    v_now timestamptz;
    v_through bigint;
    v_duplicate boolean;
    v_action_kind text;
    v_action_reason text;
    v_count bigint;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5690',
            MESSAGE = 'event gap reconciliation authority is invalid';
    END IF;

    SELECT job.* INTO v_job
    FROM platform.jobs AS job
    WHERE job.id = p_job_id
      AND job.state = 'running'
      AND job.kind = 'platform_async.event_gap_reconcile.' ||
          job.authority_domain
      AND job.payload_revision = 1
      AND job.effect_class = 'database_transactional'
      AND job.effect_started_at IS NULL
      AND job.cancel_requested_at IS NULL
      AND job.lease_owner_id = p_lease_owner_id
      AND job.lease_generation = p_lease_generation
      AND job.lease_until > v_now
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5691',
            MESSAGE = 'event gap reconciliation job is invalid';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_group_generation,v_job.authority_domain,
        v_job.cutover_generation
    );

    SELECT root.* INTO v_root
    FROM platform.dead_letters AS root
    WHERE v_job.payload_ref = 'deadletter:event-gap:' || root.id::text
      AND root.record_kind = 'root' AND root.source_kind = 'event'
      AND root.reason_class = 'sequence_gap'
      AND root.reason_code = 'EVENT_SEQUENCE_GAP'
      AND root.payload_canonical IS NOT NULL
      AND root.payload_redacted_at IS NULL
      AND root.source_sha256 = v_job.payload_sha256
      AND ROW(root.tenant_id,root.scope_kind,root.scope_id,
          root.authority_group_id,root.authority_group_generation,
          root.authority_domain,root.cutover_generation,root.writer_origin)
          = ROW(v_job.tenant_id,v_job.scope_kind,v_job.scope_id,
              v_job.authority_group_id,v_job.authority_group_generation,
              v_job.authority_domain,v_job.cutover_generation,'v2')
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5694',
            MESSAGE = 'event gap evidence is missing or redacted';
    END IF;
    v_gap := pg_catalog.convert_from(v_root.payload_canonical, 'UTF8')::jsonb;

    SELECT event.* INTO v_event
    FROM platform.outbox AS event
    WHERE event.event_id = v_root.source_id
      AND event.payload_canonical IS NOT NULL
      AND event.payload_redacted_at IS NULL
      AND event.event_id::text = v_gap->'envelope'->>'event_id'
      AND event.event_sequence =
          (v_gap->'envelope'->>'event_sequence')::bigint
      AND event.payload_sha256 = v_gap->'envelope'->>'payload_sha256'
      AND pg_catalog.convert_from(event.payload_canonical, 'UTF8')::jsonb =
          v_gap->'envelope'->'payload'
    FOR UPDATE;
    IF NOT FOUND OR v_event.parked_at IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5693',
            MESSAGE = 'event gap source outbox is unavailable';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        pg_catalog.concat_ws(E'\x1f',
            'platform_async_inbox_v1',v_root.consumer_name,
            v_root.consumer_version::text,v_root.scope_kind,
            v_root.scope_id::text,v_event.aggregate_type,
            v_event.aggregate_id::text
        ), 0
    ));
    SELECT
        COALESCE(pg_catalog.max(mark.through_sequence), 0),
        COALESCE(pg_catalog.bool_or(
            mark.record_kind = 'event_receipt' AND
            mark.event_id = v_root.source_id
        ), false)
    INTO v_through,v_duplicate
    FROM platform.inbox AS mark
    WHERE mark.consumer_name = v_root.consumer_name
      AND mark.consumer_version = v_root.consumer_version
      AND mark.scope_kind = v_root.scope_kind
      AND mark.scope_id = v_root.scope_id
      AND mark.aggregate_type = v_event.aggregate_type
      AND mark.aggregate_id = v_event.aggregate_id;

    IF v_duplicate OR v_through >= v_event.event_sequence THEN
        v_action_kind := 'repair_action';
        v_action_reason := 'automatic sequence-gap reconciliation found durable inbox evidence';
    ELSIF v_through = v_event.event_sequence - 1 AND
          v_event.delivery_state IN ('pending','publishing') THEN
        v_action_kind := 'repair_action';
        v_action_reason := 'automatic sequence-gap replay was already pending';
    ELSIF v_through = v_event.event_sequence - 1 AND
          v_event.delivery_state = 'delivered' THEN
        PERFORM platform.platform_async_assert_current_authority_v1(
            v_event.scope_kind,v_event.scope_id,v_event.authority_group_id,
            v_event.authority_group_generation,v_event.authority_domain,
            v_event.cutover_generation
        );
        v_action_kind := 'retry_action';
        v_action_reason := 'automatic sequence-gap replay after contiguous watermark';
    ELSE
        RAISE EXCEPTION USING ERRCODE = 'P5692',
            MESSAGE = 'event gap predecessor watermark is not ready';
    END IF;

    PERFORM platform.platform_async_record_event_gap_action_v1(
        v_job,v_root,v_gap,v_action_kind,v_action_reason,v_now
    );

    requeued := v_action_kind = 'retry_action';
    IF requeued THEN
        UPDATE platform.outbox AS event
        SET delivery_state = 'pending',next_attempt_at = v_now,
            confirmed_at = NULL,delivered_at = NULL,confirm_sha256 = NULL,
            last_error_code = NULL,last_error_sha256 = NULL
        WHERE event.event_id = v_event.event_id;
        GET DIAGNOSTICS v_count = ROW_COUNT;
        IF v_count <> 1 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5693',
                MESSAGE = 'event gap source outbox was not reopened';
        END IF;
    END IF;

    completed_at := platform.platform_async_complete_event_gap_job_v1(
        v_job,p_attempt_id,p_lease_owner_id,p_lease_generation
    );
    action_id := v_job.id;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_reconcile_event_gap_v1(p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) OWNER TO harpy_owner;

--
-- Name: platform_async_reconcile_event_gap_v2(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_reconcile_event_gap_v2(p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) RETURNS TABLE(completed_at timestamp with time zone, requeued boolean, action_id uuid, disposition text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_root platform.dead_letters%ROWTYPE;
    v_event platform.outbox%ROWTYPE;
    v_gap jsonb;
    v_now timestamptz;
    v_error_sha256 text;
    v_count bigint;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5690',
            MESSAGE = 'event gap reconciliation authority is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id = p_job_id AND job.state = 'running'
      AND job.kind = 'platform_async.event_gap_reconcile.' || job.authority_domain
      AND job.payload_revision = 1
      AND job.effect_class = 'database_transactional'
      AND job.effect_started_at IS NULL AND job.cancel_requested_at IS NULL
      AND job.lease_owner_id = p_lease_owner_id
      AND job.lease_generation = p_lease_generation
      AND job.lease_until > v_now
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5691',
            MESSAGE = 'event gap reconciliation job is invalid';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_group_generation,v_job.authority_domain,
        v_job.cutover_generation
    );
    SELECT root.* INTO v_root FROM platform.dead_letters AS root
    WHERE v_job.payload_ref = 'deadletter:event-gap:' || root.id::text
      AND root.record_kind = 'root' AND root.source_kind = 'event'
      AND root.reason_class = 'sequence_gap'
      AND root.reason_code = 'EVENT_SEQUENCE_GAP'
      AND root.payload_canonical IS NOT NULL
      AND root.payload_redacted_at IS NULL
      AND root.source_sha256 = v_job.payload_sha256
      AND ROW(root.tenant_id,root.scope_kind,root.scope_id,
          root.authority_group_id,root.authority_group_generation,
          root.authority_domain,root.cutover_generation,root.writer_origin)
          = ROW(v_job.tenant_id,v_job.scope_kind,v_job.scope_id,
              v_job.authority_group_id,v_job.authority_group_generation,
              v_job.authority_domain,v_job.cutover_generation,'v2')
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5694',
            MESSAGE = 'event gap evidence is missing or redacted';
    END IF;
    v_gap := pg_catalog.convert_from(v_root.payload_canonical,'UTF8')::jsonb;
    SELECT event.* INTO v_event FROM platform.outbox AS event
    WHERE event.event_id = v_root.source_id
      AND event.payload_canonical IS NOT NULL
      AND event.payload_redacted_at IS NULL
      AND event.event_id::text = v_gap->'envelope'->>'event_id'
      AND event.event_sequence =
          (v_gap->'envelope'->>'event_sequence')::bigint
      AND event.payload_sha256 = v_gap->'envelope'->>'payload_sha256'
      AND pg_catalog.convert_from(event.payload_canonical,'UTF8')::jsonb =
          v_gap->'envelope'->'payload'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5693',
            MESSAGE = 'event gap source outbox is unavailable';
    END IF;
    IF platform.platform_async_outbox_authority_current_v1(v_event) THEN
        SELECT result.completed_at,result.requeued,result.action_id
        INTO completed_at,requeued,action_id
        FROM platform.platform_async_reconcile_event_gap_v1(
            p_job_id,p_attempt_id,p_lease_owner_id,p_lease_generation
        ) AS result;
        disposition := CASE WHEN requeued THEN 'requeued' ELSE 'already_applied' END;
        RETURN NEXT;
        RETURN;
    END IF;

    v_now := GREATEST(
        pg_catalog.clock_timestamp(),v_job.updated_at + interval '1 microsecond'
    );
    v_error_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'EVENT_GAP_SOURCE_AUTHORITY_STALE','UTF8')),'hex');
    PERFORM platform.platform_async_record_event_gap_action_v1(
        v_job,v_root,v_gap,'repair_action',
        'automatic sequence-gap reconciliation terminated because source authority is stale',
        v_now
    );
    UPDATE platform.job_attempts AS attempt
    SET finished_at = v_now,outcome = 'cancelled',error_class = 'cancelled',
        error_code = 'EVENT_GAP_SOURCE_AUTHORITY_STALE',
        redacted_error_sha256 = v_error_sha256
    WHERE attempt.attempt_id = p_attempt_id AND attempt.job_id = v_job.id
      AND attempt.attempt = v_job.attempts
      AND attempt.lease_owner_id = p_lease_owner_id
      AND attempt.lease_generation = p_lease_generation
      AND attempt.finished_at IS NULL AND attempt.effect_started_at IS NULL;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5695',
            MESSAGE = 'event gap source-stale attempt completion failed';
    END IF;
    UPDATE platform.jobs AS job
    SET state = 'cancelled',lease_owner_id = NULL,lease_heartbeat_at = NULL,
        lease_until = NULL,last_error_class = 'cancelled',
        last_error_code = 'EVENT_GAP_SOURCE_AUTHORITY_STALE',
        last_error_sha256 = v_error_sha256,
        retain_until = v_now + interval '90 days',updated_at = v_now,
        completed_at = v_now
    WHERE job.id = v_job.id AND job.state = 'running'
      AND job.lease_owner_id = p_lease_owner_id
      AND job.lease_generation = p_lease_generation;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5696',
            MESSAGE = 'event gap source-stale job completion failed';
    END IF;
    completed_at := v_now;
    requeued := false;
    action_id := v_job.id;
    disposition := 'source_authority_stale';
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_reconcile_event_gap_v2(p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) OWNER TO harpy_owner;

--
-- Name: platform_async_record_event_gap_action_v1(platform.jobs, platform.dead_letters, jsonb, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_record_event_gap_action_v1(p_job platform.jobs, p_root platform.dead_letters, p_gap jsonb, p_kind text, p_reason text, p_now timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_count bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_kind NOT IN ('retry_action','repair_action') OR
       p_job.payload_ref IS DISTINCT FROM
           'deadletter:event-gap:' || p_root.id::text OR
       p_root.reason_class IS DISTINCT FROM 'sequence_gap' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5697',
            MESSAGE = 'event gap action evidence is invalid';
    END IF;
    INSERT INTO platform.dead_letters (
        id,root_id,entry_sequence,record_kind,tenant_id,scope_kind,scope_id,
        authority_group_id,authority_group_generation,authority_domain,
        cutover_generation,writer_origin,source_kind,source_id,consumer_name,
        consumer_version,source_contract,source_version,source_sha256,
        reason_class,reason_code,redacted_error_sha256,payload_sha256,
        redacted_envelope,action_reason,action_ticket,action_actor_id,
        action_causation_id,full_payload_expires_at,metadata_expires_at,recorded_at
    ) SELECT
        p_job.id,p_root.id,pg_catalog.max(entry.entry_sequence) + 1,
        p_kind,p_root.tenant_id,p_root.scope_kind,p_root.scope_id,
        p_root.authority_group_id,p_root.authority_group_generation,
        p_root.authority_domain,p_root.cutover_generation,'v2',
        p_root.source_kind,p_root.source_id,p_root.consumer_name,
        p_root.consumer_version,p_root.source_contract,p_root.source_version,
        p_root.source_sha256,p_root.reason_class,p_root.reason_code,
        p_root.redacted_error_sha256,p_root.payload_sha256,
        p_root.redacted_envelope,p_reason,
        'event-gap-reconcile:' || p_job.id::text,
        (p_gap->'envelope'->>'actor_id')::uuid,p_job.id,
        p_root.full_payload_expires_at,p_root.metadata_expires_at,p_now
    FROM platform.dead_letters AS entry
    WHERE entry.root_id = p_root.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5697',
            MESSAGE = 'event gap action evidence was not recorded';
    END IF;
    RETURN p_job.id;
END;
$$;


ALTER FUNCTION platform.platform_async_record_event_gap_action_v1(p_job platform.jobs, p_root platform.dead_letters, p_gap jsonb, p_kind text, p_reason text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_record_stale_job_disposition_v1(platform.jobs, uuid, uuid, uuid, uuid, text, text, bigint, bigint, text, bytea, text, text, text, uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_record_stale_job_disposition_v1(p_job platform.jobs, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_result_root_id uuid, p_result_payload_ref text, p_result_dedupe_key text, p_group_generation bigint, p_domain_generation bigint, p_action text, p_payload_canonical bytea, p_payload_sha256 text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid, p_source_run_at text, p_result_run_at text, p_occurred_at text, p_now timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_envelope jsonb;
    v_error_sha256 text;
    v_root platform.dead_letters%ROWTYPE;
BEGIN
    v_envelope := platform.platform_async_validate_stale_job_disposition_v1(
        p_job,p_root_id,p_action_id,p_result_job_id,p_result_root_id,
        p_result_payload_ref,p_result_dedupe_key,p_group_generation,
        p_domain_generation,p_action,p_payload_canonical,p_payload_sha256,
        p_reason,p_ticket,p_actor_id,p_causation_id,p_source_run_at,
        p_result_run_at,p_occurred_at,p_now
    );
    v_error_sha256 := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to('JOB_AUTHORITY_STALE','UTF8')),'hex');
    INSERT INTO platform.dead_letters (
        id,root_id,entry_sequence,record_kind,tenant_id,scope_kind,scope_id,
        authority_group_id,authority_group_generation,authority_domain,
        cutover_generation,writer_origin,source_kind,source_id,source_contract,
        source_version,source_sha256,reason_class,reason_code,
        redacted_error_sha256,payload_canonical,payload_sha256,
        redacted_envelope,full_payload_expires_at,metadata_expires_at,recorded_at
    ) VALUES (
        p_root_id,p_root_id,0,'root',p_job.tenant_id,p_job.scope_kind,
        p_job.scope_id,p_job.authority_group_id,p_group_generation,
        p_job.authority_domain,p_domain_generation,'v2','job',p_job.id,
        p_job.kind,p_job.payload_revision,p_job.payload_sha256,
        'stale_generation','JOB_AUTHORITY_STALE',v_error_sha256,
        p_payload_canonical,p_payload_sha256,v_envelope,
        p_now + interval '30 days',p_now + interval '365 days',p_now
    ) ON CONFLICT (id) DO NOTHING;
    SELECT root.* INTO v_root FROM platform.dead_letters AS root
    WHERE ROW(root.id,root.root_id,root.entry_sequence,root.record_kind,
        root.tenant_id,root.scope_kind,root.scope_id,root.authority_group_id,
        root.authority_group_generation,root.authority_domain,
        root.cutover_generation,root.writer_origin,root.source_kind,
        root.source_id,root.consumer_name,root.consumer_version,
        root.source_contract,root.source_version,root.source_sha256,
        root.reason_class,root.reason_code,root.redacted_error_sha256,
        root.payload_canonical,root.payload_sha256,root.payload_redacted_at,
        root.redacted_envelope,root.action_reason,root.action_ticket,
        root.action_actor_id,root.action_causation_id)
      IS NOT DISTINCT FROM ROW(p_root_id,p_root_id,0,'root',p_job.tenant_id,
        p_job.scope_kind,p_job.scope_id,p_job.authority_group_id,
        p_group_generation,p_job.authority_domain,p_domain_generation,'v2',
        'job',p_job.id,NULL,NULL,p_job.kind,p_job.payload_revision,
        p_job.payload_sha256,'stale_generation','JOB_AUTHORITY_STALE',
        v_error_sha256,p_payload_canonical,p_payload_sha256,NULL,v_envelope,
        NULL,NULL,NULL,NULL)
      AND root.full_payload_expires_at = root.recorded_at + interval '30 days'
      AND root.metadata_expires_at = root.recorded_at + interval '365 days'
      AND root.recorded_at <= p_now;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5685',
            MESSAGE = 'stale job disposition root conflicts';
    END IF;
    INSERT INTO platform.dead_letters (
        id,root_id,entry_sequence,record_kind,tenant_id,scope_kind,scope_id,
        authority_group_id,authority_group_generation,authority_domain,
        cutover_generation,writer_origin,source_kind,source_id,source_contract,
        source_version,source_sha256,reason_class,reason_code,
        redacted_error_sha256,payload_sha256,redacted_envelope,
        action_reason,action_ticket,action_actor_id,action_causation_id,
        full_payload_expires_at,metadata_expires_at,recorded_at
    ) VALUES (
        p_action_id,p_root_id,1,'repair_action',v_root.tenant_id,
        v_root.scope_kind,v_root.scope_id,v_root.authority_group_id,
        v_root.authority_group_generation,v_root.authority_domain,
        v_root.cutover_generation,'v2','job',v_root.source_id,
        v_root.source_contract,v_root.source_version,v_root.source_sha256,
        v_root.reason_class,v_root.reason_code,v_root.redacted_error_sha256,
        v_root.payload_sha256,v_root.redacted_envelope,p_reason,p_ticket,
        p_actor_id,p_causation_id,v_root.full_payload_expires_at,
        v_root.metadata_expires_at,p_now
    ) ON CONFLICT (id) DO NOTHING;
    IF NOT EXISTS (SELECT 1 FROM platform.dead_letters AS action WHERE
        ROW(action.id,action.root_id,action.entry_sequence,action.record_kind,
        action.tenant_id,action.scope_kind,action.scope_id,
        action.authority_group_id,action.authority_group_generation,
        action.authority_domain,action.cutover_generation,action.writer_origin,
        action.source_kind,action.source_id,action.consumer_name,
        action.consumer_version,action.source_contract,action.source_version,
        action.source_sha256,action.reason_class,action.reason_code,
        action.redacted_error_sha256,action.payload_canonical,
        action.payload_sha256,action.payload_redacted_at,
        action.redacted_envelope,action.action_reason,action.action_ticket,
        action.action_actor_id,action.action_causation_id,
        action.full_payload_expires_at,action.metadata_expires_at)
      IS NOT DISTINCT FROM ROW(p_action_id,p_root_id,1,'repair_action',
        v_root.tenant_id,v_root.scope_kind,v_root.scope_id,
        v_root.authority_group_id,v_root.authority_group_generation,
        v_root.authority_domain,v_root.cutover_generation,'v2','job',
        v_root.source_id,NULL,NULL,v_root.source_contract,v_root.source_version,
        v_root.source_sha256,v_root.reason_class,v_root.reason_code,
        v_root.redacted_error_sha256,NULL,v_root.payload_sha256,NULL,
        v_root.redacted_envelope,p_reason,p_ticket,p_actor_id,p_causation_id,
        v_root.full_payload_expires_at,v_root.metadata_expires_at)
      AND action.recorded_at BETWEEN v_root.recorded_at AND p_now) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5686',
            MESSAGE = 'stale job disposition action conflicts';
    END IF;
    RETURN p_action_id;
END;
$$;


ALTER FUNCTION platform.platform_async_record_stale_job_disposition_v1(p_job platform.jobs, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_result_root_id uuid, p_result_payload_ref text, p_result_dedupe_key text, p_group_generation bigint, p_domain_generation bigint, p_action text, p_payload_canonical bytea, p_payload_sha256 text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid, p_source_run_at text, p_result_run_at text, p_occurred_at text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_record_terminal_job_dead_letter_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_record_terminal_job_dead_letter_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_attempt platform.job_attempts%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_root_digest text;
    v_root_id uuid;
    v_payload bytea;
    v_payload_sha256 text;
    v_error_sha256 text;
    v_reason_class text;
    v_redacted_envelope jsonb;
    v_inserted integer;
    v_existing platform.dead_letters%ROWTYPE;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'jobs' OR
       pg_catalog.pg_trigger_depth() IS DISTINCT FROM 1 OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.state IS NOT DISTINCT FROM 'dead' OR NEW.state IS DISTINCT FROM 'dead' OR
       NEW.completed_at IS NULL OR NEW.completed_at IS DISTINCT FROM NEW.updated_at OR
       NEW.payload_ref IS NULL OR NEW.last_error_code IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5680',
            MESSAGE = 'terminal job dead-letter invocation is invalid';
    END IF;

    SELECT attempt.* INTO v_attempt
    FROM platform.job_attempts AS attempt
    WHERE attempt.job_id = NEW.id AND attempt.attempt = NEW.attempts
    FOR SHARE;
    IF NOT FOUND OR v_attempt.finished_at IS NULL OR v_attempt.outcome <> 'dead' OR
       v_attempt.error_class IS DISTINCT FROM NEW.last_error_class OR
       v_attempt.error_code IS DISTINCT FROM NEW.last_error_code OR
       v_attempt.redacted_error_sha256 IS DISTINCT FROM NEW.last_error_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5681',
            MESSAGE = 'terminal job dead-letter lacks exact attempt evidence';
    END IF;

    SELECT authority.generation INTO v_group_generation
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind = NEW.scope_kind AND authority.scope_id = NEW.scope_id
      AND authority.group_id = NEW.authority_group_id
      AND authority.state = 'v2' AND authority.writer = 'v2'
    FOR SHARE;
    SELECT authority.generation INTO v_domain_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = NEW.scope_kind AND authority.scope_id = NEW.scope_id
      AND authority.domain = NEW.authority_domain
      AND authority.state = 'v2' AND authority.writer = 'v2'
    FOR SHARE;
    IF v_group_generation IS NULL OR v_domain_generation IS NULL OR
       v_group_generation < NEW.authority_group_generation OR
       v_domain_generation < NEW.cutover_generation OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_group_members AS member
           WHERE member.scope_kind = NEW.scope_kind AND member.scope_id = NEW.scope_id
             AND member.group_id = NEW.authority_group_id
             AND member.domain = NEW.authority_domain
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5682',
            MESSAGE = 'terminal job dead-letter authority is unavailable';
    END IF;

    v_reason_class := CASE
        WHEN NEW.last_error_code = 'JOB_OUTCOME_UNKNOWN' THEN 'outcome_unknown'
        WHEN NEW.last_error_class = 'permanent' THEN 'permanent'
        ELSE 'delivery_limit'
    END;
    v_error_sha256 := COALESCE(
        NEW.last_error_sha256,
        pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.convert_to(NEW.last_error_code, 'UTF8')
        ), 'hex')
    );
    v_payload := pg_catalog.convert_to(
        '{"attempt":' || NEW.attempts::text ||
        ',"contract_version":"harpy.job-terminal-reference.v1","job_id":' ||
        pg_catalog.to_json(NEW.id::text)::text || ',"kind":' ||
        pg_catalog.to_json(NEW.kind)::text || ',"payload_reference":' ||
        pg_catalog.to_json(NEW.payload_ref)::text || ',"payload_revision":' ||
        NEW.payload_revision::text || ',"payload_sha256":' ||
        pg_catalog.to_json(NEW.payload_sha256)::text || ',"reason_code":' ||
        pg_catalog.to_json(NEW.last_error_code)::text || '}', 'UTF8'
    );
    v_payload_sha256 := pg_catalog.encode(pg_catalog.sha256(v_payload), 'hex');
    v_redacted_envelope := pg_catalog.jsonb_build_object(
        'attempt', NEW.attempts,
        'contract_version', 'harpy.job-terminal-reference.v1',
        'job_id', NEW.id, 'kind', NEW.kind,
        'payload_revision', NEW.payload_revision,
        'payload_sha256', NEW.payload_sha256,
        'reason_code', NEW.last_error_code
    );
    v_root_digest := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy.job-terminal-dead-letter.v1' || pg_catalog.chr(10) ||
        'job_id=' || NEW.id::text || pg_catalog.chr(10) ||
        'attempt=' || NEW.attempts::text || pg_catalog.chr(10) ||
        'reason=' || NEW.last_error_code, 'UTF8'
    )), 'hex');
    v_root_id := (
        pg_catalog.substr(v_root_digest, 1, 8) || '-' ||
        pg_catalog.substr(v_root_digest, 9, 4) || '-8' ||
        pg_catalog.substr(v_root_digest, 14, 3) || '-' ||
        pg_catalog.substr('89ab', (
            (pg_catalog.get_byte(pg_catalog.decode(v_root_digest, 'hex'), 8) >> 4) & 3
        ) + 1, 1) ||
        pg_catalog.substr(v_root_digest, 18, 3) || '-' ||
        pg_catalog.substr(v_root_digest, 21, 12)
    )::uuid;

    INSERT INTO platform.dead_letters (
        id, root_id, entry_sequence, record_kind, tenant_id, scope_kind, scope_id,
        authority_group_id, authority_group_generation, authority_domain,
        cutover_generation, writer_origin, source_kind, source_id, source_contract,
        source_version, source_sha256, reason_class, reason_code,
        redacted_error_sha256, payload_canonical, payload_sha256,
        redacted_envelope, full_payload_expires_at, metadata_expires_at, recorded_at
    ) VALUES (
        v_root_id, v_root_id, 0, 'root', NEW.tenant_id, NEW.scope_kind, NEW.scope_id,
        NEW.authority_group_id, v_group_generation, NEW.authority_domain,
        v_domain_generation, 'v2', 'job', NEW.id, NEW.kind,
        NEW.payload_revision, NEW.payload_sha256, v_reason_class, NEW.last_error_code,
        v_error_sha256, v_payload, v_payload_sha256,
        v_redacted_envelope,
        NEW.completed_at + interval '30 days',
        NEW.completed_at + interval '365 days', NEW.completed_at
    ) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 1 THEN
        RETURN NEW;
    END IF;

    SELECT root.* INTO v_existing
    FROM platform.dead_letters AS root
    WHERE root.source_kind = 'job' AND root.source_id = NEW.id
      AND root.record_kind = 'root'
      AND root.reason_class IN ('permanent','delivery_limit','outcome_unknown')
    FOR SHARE;
    IF NOT FOUND OR v_existing.id IS DISTINCT FROM v_root_id OR
       v_existing.tenant_id IS DISTINCT FROM NEW.tenant_id OR
       v_existing.scope_kind IS DISTINCT FROM NEW.scope_kind OR
       v_existing.scope_id IS DISTINCT FROM NEW.scope_id OR
       v_existing.authority_group_id IS DISTINCT FROM NEW.authority_group_id OR
       v_existing.authority_group_generation IS DISTINCT FROM v_group_generation OR
       v_existing.authority_domain IS DISTINCT FROM NEW.authority_domain OR
       v_existing.cutover_generation IS DISTINCT FROM v_domain_generation OR
       v_existing.writer_origin IS DISTINCT FROM 'v2' OR
       v_existing.source_contract IS DISTINCT FROM NEW.kind OR
       v_existing.source_version IS DISTINCT FROM NEW.payload_revision OR
       v_existing.reason_class IS DISTINCT FROM v_reason_class OR
       v_existing.reason_code IS DISTINCT FROM NEW.last_error_code OR
       v_existing.source_sha256 IS DISTINCT FROM NEW.payload_sha256 OR
       v_existing.redacted_error_sha256 IS DISTINCT FROM v_error_sha256 OR
       v_existing.payload_canonical IS DISTINCT FROM v_payload OR
       v_existing.payload_sha256 IS DISTINCT FROM v_payload_sha256 OR
       v_existing.redacted_envelope IS DISTINCT FROM v_redacted_envelope OR
       v_existing.recorded_at IS DISTINCT FROM NEW.completed_at OR
       v_existing.full_payload_expires_at IS DISTINCT FROM
           NEW.completed_at + interval '30 days' OR
       v_existing.metadata_expires_at IS DISTINCT FROM
           NEW.completed_at + interval '365 days' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5683',
            MESSAGE = 'terminal job dead-letter evidence conflicts';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_record_terminal_job_dead_letter_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_record_terminal_job_dead_letter_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_record_terminal_job_dead_letter_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_attempt platform.job_attempts%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_root_digest text;
    v_root_id uuid;
    v_payload bytea;
    v_payload_sha256 text;
    v_error_sha256 text;
    v_reason_class text;
    v_redacted_envelope jsonb;
    v_inserted integer;
    v_existing platform.dead_letters%ROWTYPE;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR TG_TABLE_SCHEMA IS DISTINCT FROM 'platform'
       OR TG_TABLE_NAME IS DISTINCT FROM 'jobs'
       OR pg_catalog.pg_trigger_depth() IS DISTINCT FROM 1
       OR SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR OLD.state IS NOT DISTINCT FROM 'dead' OR NEW.state IS DISTINCT FROM 'dead'
       OR NEW.completed_at IS NULL OR NEW.completed_at IS DISTINCT FROM NEW.updated_at
       OR NEW.payload_ref IS NULL OR NEW.last_error_code IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P5680',
            MESSAGE='terminal job dead-letter invocation is invalid';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=NEW.id AND attempt.attempt=NEW.attempts FOR SHARE;
    IF NOT FOUND OR v_attempt.finished_at IS NULL OR v_attempt.outcome<>'dead'
       OR v_attempt.error_class IS DISTINCT FROM NEW.last_error_class
       OR v_attempt.error_code IS DISTINCT FROM NEW.last_error_code
       OR v_attempt.redacted_error_sha256 IS DISTINCT FROM NEW.last_error_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P5681',
            MESSAGE='terminal job dead-letter lacks exact attempt evidence';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.cutover_job_bindings AS binding
               WHERE binding.job_id=NEW.id) THEN
        PERFORM platform.platform_async_assert_job_row_authority_v1(NEW);
        v_group_generation:=NEW.authority_group_generation;
        v_domain_generation:=NEW.cutover_generation;
    ELSE
        SELECT authority.generation INTO v_group_generation
        FROM platform.cutover_groups AS authority
        WHERE authority.scope_kind=NEW.scope_kind AND authority.scope_id=NEW.scope_id
          AND authority.group_id=NEW.authority_group_id
          AND authority.state='v2' AND authority.writer='v2' FOR SHARE;
        SELECT authority.generation INTO v_domain_generation
        FROM platform.domain_cutovers AS authority
        WHERE authority.scope_kind=NEW.scope_kind AND authority.scope_id=NEW.scope_id
          AND authority.domain=NEW.authority_domain
          AND authority.state='v2' AND authority.writer='v2' FOR SHARE;
        IF v_group_generation IS NULL OR v_domain_generation IS NULL
           OR v_group_generation<NEW.authority_group_generation
           OR v_domain_generation<NEW.cutover_generation OR NOT EXISTS (
               SELECT 1 FROM platform.cutover_group_members AS member
               WHERE member.scope_kind=NEW.scope_kind AND member.scope_id=NEW.scope_id
                 AND member.group_id=NEW.authority_group_id
                 AND member.domain=NEW.authority_domain) THEN
            RAISE EXCEPTION USING ERRCODE='P5682',
                MESSAGE='terminal job dead-letter authority is unavailable';
        END IF;
    END IF;
    v_reason_class:=CASE WHEN NEW.last_error_code='JOB_OUTCOME_UNKNOWN'
        THEN 'outcome_unknown' WHEN NEW.last_error_class='permanent'
        THEN 'permanent' ELSE 'delivery_limit' END;
    v_error_sha256:=COALESCE(NEW.last_error_sha256,pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(NEW.last_error_code,'UTF8')),'hex'));
    v_payload:=pg_catalog.convert_to(
        '{"attempt":'||NEW.attempts::text||
        ',"contract_version":"harpy.job-terminal-reference.v1","job_id":'||
        pg_catalog.to_json(NEW.id::text)::text||',"kind":'||
        pg_catalog.to_json(NEW.kind)::text||',"payload_reference":'||
        pg_catalog.to_json(NEW.payload_ref)::text||',"payload_revision":'||
        NEW.payload_revision::text||',"payload_sha256":'||
        pg_catalog.to_json(NEW.payload_sha256)::text||',"reason_code":'||
        pg_catalog.to_json(NEW.last_error_code)::text||'}','UTF8');
    v_payload_sha256:=pg_catalog.encode(pg_catalog.sha256(v_payload),'hex');
    v_redacted_envelope:=pg_catalog.jsonb_build_object(
        'attempt',NEW.attempts,'contract_version','harpy.job-terminal-reference.v1',
        'job_id',NEW.id,'kind',NEW.kind,'payload_revision',NEW.payload_revision,
        'payload_sha256',NEW.payload_sha256,'reason_code',NEW.last_error_code);
    v_root_digest:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy.job-terminal-dead-letter.v1'||pg_catalog.chr(10)||
        'job_id='||NEW.id::text||pg_catalog.chr(10)||
        'attempt='||NEW.attempts::text||pg_catalog.chr(10)||
        'reason='||NEW.last_error_code,'UTF8')),'hex');
    v_root_id:=(pg_catalog.substr(v_root_digest,1,8)||'-'||
        pg_catalog.substr(v_root_digest,9,4)||'-8'||
        pg_catalog.substr(v_root_digest,14,3)||'-'||
        pg_catalog.substr('89ab',((pg_catalog.get_byte(
            pg_catalog.decode(v_root_digest,'hex'),8)>>4)&3)+1,1)||
        pg_catalog.substr(v_root_digest,18,3)||'-'||
        pg_catalog.substr(v_root_digest,21,12))::uuid;
    INSERT INTO platform.dead_letters (
        id,root_id,entry_sequence,record_kind,tenant_id,scope_kind,scope_id,
        authority_group_id,authority_group_generation,authority_domain,
        cutover_generation,writer_origin,source_kind,source_id,source_contract,
        source_version,source_sha256,reason_class,reason_code,redacted_error_sha256,
        payload_canonical,payload_sha256,redacted_envelope,full_payload_expires_at,
        metadata_expires_at,recorded_at
    ) VALUES (
        v_root_id,v_root_id,0,'root',NEW.tenant_id,NEW.scope_kind,NEW.scope_id,
        NEW.authority_group_id,v_group_generation,NEW.authority_domain,
        v_domain_generation,'v2','job',NEW.id,NEW.kind,NEW.payload_revision,
        NEW.payload_sha256,v_reason_class,NEW.last_error_code,v_error_sha256,
        v_payload,v_payload_sha256,v_redacted_envelope,
        NEW.completed_at+interval '30 days',NEW.completed_at+interval '365 days',
        NEW.completed_at) ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_inserted=ROW_COUNT;
    IF v_inserted=1 THEN RETURN NEW; END IF;
    SELECT root.* INTO v_existing FROM platform.dead_letters AS root
    WHERE root.source_kind='job' AND root.source_id=NEW.id
      AND root.record_kind='root'
      AND root.reason_class IN ('permanent','delivery_limit','outcome_unknown')
    FOR SHARE;
    IF NOT FOUND OR v_existing.id IS DISTINCT FROM v_root_id
       OR v_existing.tenant_id IS DISTINCT FROM NEW.tenant_id
       OR v_existing.scope_kind IS DISTINCT FROM NEW.scope_kind
       OR v_existing.scope_id IS DISTINCT FROM NEW.scope_id
       OR v_existing.authority_group_id IS DISTINCT FROM NEW.authority_group_id
       OR v_existing.authority_group_generation IS DISTINCT FROM v_group_generation
       OR v_existing.authority_domain IS DISTINCT FROM NEW.authority_domain
       OR v_existing.cutover_generation IS DISTINCT FROM v_domain_generation
       OR v_existing.writer_origin IS DISTINCT FROM 'v2'
       OR v_existing.source_contract IS DISTINCT FROM NEW.kind
       OR v_existing.source_version IS DISTINCT FROM NEW.payload_revision
       OR v_existing.reason_class IS DISTINCT FROM v_reason_class
       OR v_existing.reason_code IS DISTINCT FROM NEW.last_error_code
       OR v_existing.source_sha256 IS DISTINCT FROM NEW.payload_sha256
       OR v_existing.redacted_error_sha256 IS DISTINCT FROM v_error_sha256
       OR v_existing.payload_canonical IS DISTINCT FROM v_payload
       OR v_existing.payload_sha256 IS DISTINCT FROM v_payload_sha256
       OR v_existing.redacted_envelope IS DISTINCT FROM v_redacted_envelope
       OR v_existing.recorded_at IS DISTINCT FROM NEW.completed_at
       OR v_existing.full_payload_expires_at IS DISTINCT FROM
          NEW.completed_at+interval '30 days'
       OR v_existing.metadata_expires_at IS DISTINCT FROM
          NEW.completed_at+interval '365 days' THEN
        RAISE EXCEPTION USING ERRCODE='P5683',
            MESSAGE='terminal job dead-letter evidence conflicts';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_record_terminal_job_dead_letter_v2() OWNER TO harpy_owner;

--
-- Name: platform_async_record_v1_inventory_item_v1(uuid, text, text, text, text, text, integer, text, text, text, text, integer, text, text, timestamp with time zone, integer, integer, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_record_v1_inventory_item_v1(p_run_id uuid, p_inventory_class text, p_source_surface text, p_source_name text, p_source_item_id text, p_source_contract_version text, p_source_revision integer, p_source_payload_sha256 text, p_transform_version text, p_idempotency_identity text, p_target_kind text, p_target_payload_revision integer, p_target_payload_ref text, p_target_payload_sha256 text, p_target_run_at timestamp with time zone, p_target_priority integer, p_target_max_attempts integer, p_target_effect_class text, p_target_effect_idempotency_key text, p_captured_at timestamp with time zone, p_item_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_manifest_captured_at timestamptz;
    v_inserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5637',
            MESSAGE = 'V1 async inventory requires adopter authority';
    END IF;
    SELECT captured_at INTO v_manifest_captured_at
    FROM platform.async_v1_adoption_runs
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id
      AND state OPERATOR(pg_catalog.=) 'inventory'
    FOR UPDATE;
    IF NOT FOUND OR p_captured_at > v_manifest_captured_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5638',
            MESSAGE = 'V1 async inventory run is not open';
    END IF;
    IF (p_source_name OPERATOR(pg_catalog.=) 'workflow.cron.scheduler' AND NOT (
            p_inventory_class OPERATOR(pg_catalog.=) 'timer' AND
            p_source_surface OPERATOR(pg_catalog.=) 'scheduler' AND
            p_source_contract_version OPERATOR(pg_catalog.=)
                'v1.workflow-minute-scheduler.v1'
       )) OR
       (p_source_name OPERATOR(pg_catalog.=) 'schedule.events' AND NOT (
            p_inventory_class OPERATOR(pg_catalog.=) 'queue' AND
            p_source_surface OPERATOR(pg_catalog.=) 'queue' AND
            p_source_contract_version OPERATOR(pg_catalog.=) 'v1.queue-message.v1'
       )) OR
       (p_source_name OPERATOR(pg_catalog.=) 'workflow.delay' AND NOT (
            p_inventory_class OPERATOR(pg_catalog.=) 'timer' AND
            p_source_surface OPERATOR(pg_catalog.=) 'delayed_plugin' AND
            p_source_contract_version OPERATOR(pg_catalog.=)
                'v1.workflow-delayed-plugin.v1'
       )) OR
       (p_source_name OPERATOR(pg_catalog.=) 'workflow.webhook.retry' AND NOT (
            p_inventory_class OPERATOR(pg_catalog.=) 'timer' AND
            p_source_surface OPERATOR(pg_catalog.=) 'ttl_queue' AND
            p_source_contract_version OPERATOR(pg_catalog.=)
                'v1.workflow-webhook-ttl-not-delay.v1'
       )) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5639',
            MESSAGE = 'known V1 async source semantics differ';
    END IF;
    INSERT INTO platform.async_v1_adoption_items (
        run_id, inventory_class, source_surface, source_name, source_item_id,
        source_contract_version, source_revision, source_payload_sha256,
        transform_version, idempotency_identity, target_kind,
        target_payload_revision, target_payload_ref, target_payload_sha256,
        target_run_at, target_priority, target_max_attempts,
        target_effect_class, target_effect_idempotency_key,
        captured_at, item_sha256
    ) VALUES (
        p_run_id, p_inventory_class, p_source_surface, p_source_name, p_source_item_id,
        p_source_contract_version, p_source_revision, p_source_payload_sha256,
        p_transform_version, p_idempotency_identity, p_target_kind,
        p_target_payload_revision, p_target_payload_ref, p_target_payload_sha256,
        p_target_run_at, p_target_priority, p_target_max_attempts,
        p_target_effect_class, p_target_effect_idempotency_key,
        p_captured_at, p_item_sha256
    ) ON CONFLICT DO NOTHING RETURNING true INTO v_inserted;
    IF NOT COALESCE(v_inserted, false) AND NOT EXISTS (
        SELECT 1 FROM platform.async_v1_adoption_items
        WHERE run_id OPERATOR(pg_catalog.=) p_run_id
          AND inventory_class OPERATOR(pg_catalog.=) p_inventory_class
          AND source_name OPERATOR(pg_catalog.=) p_source_name
          AND source_item_id OPERATOR(pg_catalog.=) p_source_item_id
          AND item_sha256 OPERATOR(pg_catalog.=) p_item_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5640',
            MESSAGE = 'V1 async inventory item replay differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_record_v1_inventory_item_v1(p_run_id uuid, p_inventory_class text, p_source_surface text, p_source_name text, p_source_item_id text, p_source_contract_version text, p_source_revision integer, p_source_payload_sha256 text, p_transform_version text, p_idempotency_identity text, p_target_kind text, p_target_payload_revision integer, p_target_payload_ref text, p_target_payload_sha256 text, p_target_run_at timestamp with time zone, p_target_priority integer, p_target_max_attempts integer, p_target_effect_class text, p_target_effect_idempotency_key text, p_captured_at timestamp with time zone, p_item_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_record_v1_restart_fence_v1(uuid, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_record_v1_restart_fence_v1(p_run_id uuid, p_fence_kind text, p_component_name text, p_component_contract_version text, p_binary_sha256 text, p_config_sha256 text, p_restart_probe_sha256 text, p_fenced_at timestamp with time zone, p_restart_verified_at timestamp with time zone, p_receipt_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run_state text;
    v_captured_at timestamptz;
    v_inserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cluster_admin' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5652',
            MESSAGE = 'V1 async restart fence requires cluster authority';
    END IF;
    SELECT state, captured_at INTO v_run_state, v_captured_at
    FROM platform.async_v1_adoption_runs
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id FOR UPDATE;
    IF NOT FOUND OR v_run_state IS DISTINCT FROM 'disposing' OR
       p_fenced_at >= p_restart_verified_at OR
       p_restart_verified_at > v_captured_at OR
       p_restart_verified_at > pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE = 'P5653',
            MESSAGE = 'V1 async restart fence evidence is invalid';
    END IF;
    INSERT INTO platform.async_v1_restart_fence_receipts (
        run_id, fence_kind, component_name, component_contract_version,
        binary_sha256, config_sha256, restart_probe_sha256,
        fenced_at, restart_verified_at, receipt_sha256
    ) VALUES (
        p_run_id, p_fence_kind, p_component_name, p_component_contract_version,
        p_binary_sha256, p_config_sha256, p_restart_probe_sha256,
        p_fenced_at, p_restart_verified_at, p_receipt_sha256
    ) ON CONFLICT DO NOTHING RETURNING true INTO v_inserted;
    IF NOT COALESCE(v_inserted, false) AND NOT EXISTS (
        SELECT 1 FROM platform.async_v1_restart_fence_receipts
        WHERE run_id OPERATOR(pg_catalog.=) p_run_id
          AND fence_kind OPERATOR(pg_catalog.=) p_fence_kind
          AND component_name OPERATOR(pg_catalog.=) p_component_name
          AND receipt_sha256 OPERATOR(pg_catalog.=) p_receipt_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5654',
            MESSAGE = 'V1 async restart fence replay differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_record_v1_restart_fence_v1(p_run_id uuid, p_fence_kind text, p_component_name text, p_component_contract_version text, p_binary_sha256 text, p_config_sha256 text, p_restart_probe_sha256 text, p_fenced_at timestamp with time zone, p_restart_verified_at timestamp with time zone, p_receipt_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_record_v1_zero_inventory_v1(uuid, text, bigint, bigint, bigint, bigint, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_record_v1_zero_inventory_v1(p_run_id uuid, p_inventory_sha256 text, p_queue_count bigint, p_timer_count bigint, p_future_count bigint, p_running_count bigint, p_observed_at timestamp with time zone, p_receipt_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.async_v1_adoption_runs%ROWTYPE;
    v_enqueue_count bigint;
    v_scheduler_count bigint;
    v_consumer_count bigint;
    v_component_sha256 text;
    v_last_restart timestamptz;
    v_disposition_count bigint;
    v_inserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cluster_admin' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5655',
            MESSAGE = 'V1 zero inventory requires cluster authority';
    END IF;
    SELECT * INTO v_run FROM platform.async_v1_adoption_runs
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id FOR UPDATE;
    IF NOT FOUND OR v_run.state IS DISTINCT FROM 'disposing' OR
       v_run.inventory_sha256 IS DISTINCT FROM p_inventory_sha256 OR
       p_queue_count IS DISTINCT FROM 0 OR p_timer_count IS DISTINCT FROM 0 OR
       p_future_count IS DISTINCT FROM 0 OR p_running_count IS DISTINCT FROM 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5656',
            MESSAGE = 'V1 async inventory is not zero';
    END IF;
    SELECT pg_catalog.count(*) FILTER (WHERE fence_kind = 'enqueue'),
           pg_catalog.count(*) FILTER (WHERE fence_kind = 'scheduler'),
           pg_catalog.count(*) FILTER (WHERE fence_kind = 'consumer'),
           pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
               COALESCE(pg_catalog.string_agg(
                   receipt_sha256, E'\n' ORDER BY receipt_sha256
               ), ''), 'UTF8'
           )), 'hex'),
           pg_catalog.max(restart_verified_at)
    INTO v_enqueue_count, v_scheduler_count, v_consumer_count,
         v_component_sha256, v_last_restart
    FROM platform.async_v1_restart_fence_receipts
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id;
    IF v_enqueue_count IS DISTINCT FROM v_run.expected_enqueue_fences OR
       v_scheduler_count IS DISTINCT FROM v_run.expected_scheduler_fences OR
       v_consumer_count IS DISTINCT FROM v_run.expected_consumer_fences OR
       v_component_sha256 IS DISTINCT FROM v_run.component_manifest_sha256 OR
       v_last_restart IS NULL OR p_observed_at < v_last_restart OR
       p_observed_at < v_run.captured_at OR
       p_observed_at > pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE = 'P5657',
            MESSAGE = 'V1 enqueue scheduler or consumer restart fence is incomplete';
    END IF;
    SELECT pg_catalog.count(*) INTO v_disposition_count
    FROM platform.async_v1_adoption_dispositions
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id;
    IF v_disposition_count IS DISTINCT FROM v_run.item_count THEN
        RAISE EXCEPTION USING ERRCODE = 'P5658',
            MESSAGE = 'V1 async inventory has unresolved items';
    END IF;
    INSERT INTO platform.async_v1_zero_inventory_receipts (
        run_id, inventory_contract_version, inventory_sha256,
        queue_count, timer_count, future_count, running_count,
        observed_at, receipt_sha256
    ) VALUES (
        p_run_id, 'async-adoption-zero-inventory.v1', p_inventory_sha256,
        p_queue_count, p_timer_count, p_future_count, p_running_count,
        p_observed_at, p_receipt_sha256
    ) ON CONFLICT DO NOTHING RETURNING true INTO v_inserted;
    IF NOT COALESCE(v_inserted, false) AND NOT EXISTS (
        SELECT 1 FROM platform.async_v1_zero_inventory_receipts
        WHERE run_id OPERATOR(pg_catalog.=) p_run_id
          AND receipt_sha256 OPERATOR(pg_catalog.=) p_receipt_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5659',
            MESSAGE = 'V1 zero inventory replay differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_record_v1_zero_inventory_v1(p_run_id uuid, p_inventory_sha256 text, p_queue_count bigint, p_timer_count bigint, p_future_count bigint, p_running_count bigint, p_observed_at timestamp with time zone, p_receipt_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_redact_dead_letter_payloads_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_redact_dead_letter_payloads_v1(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'unsafe dead-letter redaction v1 is retired; use v2';
END;
$$;


ALTER FUNCTION platform.platform_async_redact_dead_letter_payloads_v1(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_redact_dead_letter_payloads_v2(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_redact_dead_letter_payloads_v2(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_count integer;
    v_changed integer;
    v_root_id uuid;
    v_root platform.dead_letters%ROWTYPE;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    v_count := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'async retention session authority is invalid';
    END IF;
    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async redaction batch size must be between 1 and 500';
    END IF;

    FOR v_root_id IN
        SELECT root.id
        FROM platform.dead_letters AS root
        WHERE root.record_kind = 'root'
          AND root.payload_canonical IS NOT NULL
          AND root.payload_redacted_at IS NULL
          AND root.full_payload_expires_at <= v_now
          AND NOT platform.platform_async_has_live_event_gap_root_v1(root)
          AND NOT platform.platform_async_has_live_stale_job_root_v1(root)
        ORDER BY root.full_payload_expires_at, root.id
        LIMIT p_batch_size
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
            'harpy:deadletter:' || v_root_id::text,0));
        SELECT root.* INTO v_root
        FROM platform.dead_letters AS root
        WHERE root.id = v_root_id
          AND root.record_kind = 'root'
          AND root.payload_canonical IS NOT NULL
          AND root.payload_redacted_at IS NULL
          AND root.full_payload_expires_at <= v_now
        FOR UPDATE;
        IF NOT FOUND OR
           platform.platform_async_has_live_event_gap_root_v1(v_root) OR
           platform.platform_async_has_live_stale_job_root_v1(v_root) THEN
            CONTINUE;
        END IF;
        UPDATE platform.dead_letters AS root
        SET payload_canonical = NULL,payload_redacted_at = v_now
        WHERE root.id = v_root_id;
        GET DIAGNOSTICS v_changed = ROW_COUNT;
        v_count := v_count + v_changed;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platform_async_redact_dead_letter_payloads_v2(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_redact_job_payloads_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_redact_job_payloads_v1(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_count integer;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async redaction batch size must be between 1 and 500';
    END IF;

    WITH candidates AS (
        SELECT job.id
        FROM platform.jobs AS job
        WHERE job.state IN ('succeeded', 'dead', 'cancelled')
          AND job.payload_ref IS NOT NULL
          AND job.payload_redacted_at IS NULL
          AND job.completed_at <= v_now - interval '30 days'
        ORDER BY job.completed_at, job.id
        FOR UPDATE SKIP LOCKED
        LIMIT p_batch_size
    )
    UPDATE platform.jobs AS job
    SET payload_ref = NULL,
        payload_redacted_at = v_now,
        updated_at = v_now
    FROM candidates
    WHERE job.id = candidates.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platform_async_redact_job_payloads_v1(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_redact_outbox_payloads_v1(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_redact_outbox_payloads_v1(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'unsafe outbox redaction v1 is retired; use v2';
END;
$$;


ALTER FUNCTION platform.platform_async_redact_outbox_payloads_v1(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_redact_outbox_payloads_v2(integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_redact_outbox_payloads_v2(p_batch_size integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_count integer;
    v_changed integer;
    v_event_id uuid;
    v_event platform.outbox%ROWTYPE;
BEGIN
    v_now := pg_catalog.clock_timestamp();
    v_count := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'async retention session authority is invalid';
    END IF;
    IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'async redaction batch size must be between 1 and 500';
    END IF;

    FOR v_event_id IN
        SELECT event.event_id
        FROM platform.outbox AS event
        WHERE event.delivery_state = 'delivered'
          AND event.payload_canonical IS NOT NULL
          AND event.payload_redacted_at IS NULL
          AND event.delivered_at <= v_now - interval '30 days'
          AND NOT platform.platform_async_has_live_event_gap_v1(event)
        ORDER BY event.delivered_at, event.event_id
        LIMIT p_batch_size
    LOOP
        SELECT event.* INTO v_event
        FROM platform.outbox AS event
        WHERE event.event_id = v_event_id
          AND event.delivery_state = 'delivered'
          AND event.payload_canonical IS NOT NULL
          AND event.payload_redacted_at IS NULL
          AND event.delivered_at <= v_now - interval '30 days'
        FOR UPDATE;
        IF NOT FOUND OR platform.platform_async_has_live_event_gap_v1(v_event) THEN
            CONTINUE;
        END IF;
        UPDATE platform.outbox AS event
        SET payload_canonical = NULL,payload_redacted_at = v_now,updated_at = v_now
        WHERE event.event_id = v_event_id;
        GET DIAGNOSTICS v_changed = ROW_COUNT;
        v_count := v_count + v_changed;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platform_async_redact_outbox_payloads_v2(p_batch_size integer) OWNER TO harpy_owner;

--
-- Name: platform_async_reissue_stale_event_gap_v1(platform.jobs, uuid, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_reissue_stale_event_gap_v1(p_job platform.jobs, p_root_id uuid, p_group_generation bigint, p_domain_generation bigint, p_now timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_old platform.dead_letters%ROWTYPE;
    v_new platform.dead_letters%ROWTYPE;
    v_prefix text;
BEGIN
    v_prefix := 'platform_async.event_gap_reconcile.';
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5680',
            MESSAGE = 'stale event gap reissue authority is invalid';
    END IF;
    IF pg_catalog.left(p_job.kind,pg_catalog.length(v_prefix)) <> v_prefix THEN
        RETURN p_job.payload_ref;
    END IF;
    IF p_job.kind IS DISTINCT FROM (v_prefix || p_job.authority_domain) OR
       p_root_id IS NULL OR p_job.payload_ref IS NULL OR
       pg_catalog.left(p_job.payload_ref,
           pg_catalog.length('deadletter:event-gap:')) <>
           'deadletter:event-gap:' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5681',
            MESSAGE = 'stale event gap source identity is invalid';
    END IF;

    SELECT root.* INTO v_old
    FROM platform.dead_letters AS root
    WHERE p_job.payload_ref = 'deadletter:event-gap:' || root.id::text
      AND root.record_kind = 'root' AND root.source_kind = 'event'
      AND root.reason_class = 'sequence_gap'
      AND root.reason_code = 'EVENT_SEQUENCE_GAP'
      AND root.payload_canonical IS NOT NULL
      AND root.payload_redacted_at IS NULL
      AND root.source_sha256 = p_job.payload_sha256
      AND ROW(root.tenant_id,root.scope_kind,root.scope_id,
          root.authority_group_id,root.authority_group_generation,
          root.authority_domain,root.cutover_generation,root.writer_origin)
          = ROW(p_job.tenant_id,p_job.scope_kind,p_job.scope_id,
              p_job.authority_group_id,p_job.authority_group_generation,
              p_job.authority_domain,p_job.cutover_generation,'v2')
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5682',
            MESSAGE = 'stale event gap evidence is unavailable';
    END IF;

    INSERT INTO platform.dead_letters (
        id,root_id,entry_sequence,record_kind,tenant_id,scope_kind,scope_id,
        authority_group_id,authority_group_generation,authority_domain,
        cutover_generation,writer_origin,source_kind,source_id,consumer_name,
        consumer_version,source_contract,source_version,source_sha256,
        reason_class,reason_code,redacted_error_sha256,payload_canonical,
        payload_sha256,redacted_envelope,full_payload_expires_at,
        metadata_expires_at,recorded_at
    ) VALUES (
        p_root_id,p_root_id,0,'root',v_old.tenant_id,v_old.scope_kind,
        v_old.scope_id,v_old.authority_group_id,p_group_generation,
        v_old.authority_domain,p_domain_generation,'v2',v_old.source_kind,
        v_old.source_id,v_old.consumer_name,v_old.consumer_version,
        v_old.source_contract,v_old.source_version,v_old.source_sha256,
        v_old.reason_class,v_old.reason_code,v_old.redacted_error_sha256,
        v_old.payload_canonical,v_old.payload_sha256,v_old.redacted_envelope,
        p_now + interval '30 days',p_now + interval '365 days',p_now
    ) ON CONFLICT (id) DO NOTHING;

    SELECT root.* INTO v_new
    FROM platform.dead_letters AS root
    WHERE ROW(root.id,root.root_id,root.entry_sequence,root.record_kind,
            root.tenant_id,root.scope_kind,root.scope_id,
            root.authority_group_id,root.authority_group_generation,
            root.authority_domain,root.cutover_generation,root.writer_origin,
            root.source_kind,root.source_id,root.consumer_name,
            root.consumer_version,root.source_contract,root.source_version,
            root.source_sha256,root.reason_class,root.reason_code,
            root.redacted_error_sha256,root.payload_canonical,
            root.payload_sha256,root.redacted_envelope,
            root.full_payload_expires_at,root.metadata_expires_at,
            root.recorded_at,root.payload_redacted_at)
          IS NOT DISTINCT FROM
          ROW(p_root_id,p_root_id,0,'root',v_old.tenant_id,v_old.scope_kind,
            v_old.scope_id,v_old.authority_group_id,p_group_generation,
            v_old.authority_domain,p_domain_generation,'v2',v_old.source_kind,
            v_old.source_id,v_old.consumer_name,v_old.consumer_version,
            v_old.source_contract,v_old.source_version,v_old.source_sha256,
            v_old.reason_class,v_old.reason_code,v_old.redacted_error_sha256,
            v_old.payload_canonical,v_old.payload_sha256,
            v_old.redacted_envelope,p_now + interval '30 days',
            p_now + interval '365 days',p_now,NULL);
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5683',
            MESSAGE = 'stale event gap replacement conflicts';
    END IF;
    RETURN 'deadletter:event-gap:' || p_root_id::text;
END;
$$;


ALTER FUNCTION platform.platform_async_reissue_stale_event_gap_v1(p_job platform.jobs, p_root_id uuid, p_group_generation bigint, p_domain_generation bigint, p_now timestamp with time zone) OWNER TO harpy_owner;

