--
-- Name: platform_async_release_job_retention_v1(uuid, uuid, text, bigint, text, bigint, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_release_job_retention_v1(p_job_id uuid, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_owner_domain text, p_cutover_generation bigint, p_expected_revision bigint, p_release_sha256 text, p_retain_until timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz;
    v_released boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_job_id IS NULL OR p_scope_id IS NULL OR
       p_expected_revision IS NULL OR p_expected_revision < 0 OR
       p_release_sha256 IS NULL OR
       p_release_sha256 !~ '^[0-9a-f]{64}$' OR
       p_retain_until IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'job retention release input is invalid';
    END IF;

    IF platform.platform_async_assert_current_authority_v1(
        'tenant', p_scope_id, p_group_id, p_group_generation,
        p_owner_domain, p_cutover_generation
    ) IS NULL THEN NULL; END IF;

    v_now := pg_catalog.clock_timestamp();
    UPDATE platform.jobs AS job
    SET retain_until = p_retain_until,
        retention_release_revision = p_expected_revision + 1,
        retention_release_sha256 = p_release_sha256,
        retention_released_at = v_now,
        updated_at = v_now
    WHERE job.id = p_job_id
      AND job.scope_kind = 'tenant'
      AND job.scope_id = p_scope_id
      AND job.tenant_id = p_scope_id
      AND job.authority_group_id = p_group_id
      AND job.authority_domain = p_owner_domain
      AND job.state IN ('succeeded', 'dead', 'cancelled')
      AND job.retention_release_revision = p_expected_revision
      AND job.retain_until IS NOT NULL
      AND job.retain_until <= v_now
      AND p_retain_until >= job.retain_until
      AND p_retain_until <= v_now
      AND NOT EXISTS (
          SELECT 1 FROM platform.idempotency_receipts AS dependency
          WHERE dependency.async_job_id = job.id
            AND dependency.retain_until > v_now
      )
      AND NOT EXISTS (
          SELECT 1 FROM platform.jobs AS retry
          WHERE retry.retry_of_job_id = job.id
      )
      AND NOT EXISTS (
          SELECT 1 FROM platform.job_attempts AS attempt
          WHERE attempt.job_id = job.id AND attempt.finished_at IS NULL
      )
      AND NOT EXISTS (
          SELECT 1
          FROM platform.job_attempts AS attempt
          JOIN platform.idempotency_receipts AS receipt
            ON receipt.receipt_id = attempt.effect_receipt_id
          WHERE attempt.job_id = job.id AND receipt.retain_until > v_now
      )
    RETURNING true INTO v_released;

    RETURN COALESCE(v_released, false);
END;
$_$;


ALTER FUNCTION platform.platform_async_release_job_retention_v1(p_job_id uuid, p_scope_id uuid, p_group_id text, p_group_generation bigint, p_owner_domain text, p_cutover_generation bigint, p_expected_revision bigint, p_release_sha256 text, p_retain_until timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_require_inbox_event_pair_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_require_inbox_event_pair_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.record_kind OPERATOR(pg_catalog.=) 'event_receipt' AND NOT EXISTS (
        SELECT 1 FROM platform.inbox AS pair
        WHERE pair.record_kind OPERATOR(pg_catalog.=) 'watermark'
          AND pair.watermark_kind OPERATOR(pg_catalog.=) 'event'
          AND pair.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
          AND pair.consumer_version OPERATOR(pg_catalog.=) NEW.consumer_version
          AND pair.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
          AND pair.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
          AND pair.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
          AND pair.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id
          AND pair.through_sequence OPERATOR(pg_catalog.=) NEW.event_sequence
          AND pair.causation_id OPERATOR(pg_catalog.=) NEW.event_id
          AND ROW(pair.tenant_id, pair.producer_group_id,
              pair.producer_group_generation, pair.producer_domain,
              pair.producer_generation, pair.writer_origin,
              pair.consumer_group_id, pair.consumer_group_generation,
              pair.consumer_domain, pair.consumer_generation)
          IS NOT DISTINCT FROM
              ROW(NEW.tenant_id, NEW.producer_group_id,
              NEW.producer_group_generation, NEW.producer_domain,
              NEW.producer_generation, NEW.writer_origin,
              NEW.consumer_group_id, NEW.consumer_group_generation,
              NEW.consumer_domain, NEW.consumer_generation)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5635',
            MESSAGE = 'async inbox event receipt lacks its watermark';
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'watermark' AND
       NEW.watermark_kind OPERATOR(pg_catalog.=) 'event' AND NOT EXISTS (
        SELECT 1 FROM platform.inbox AS pair
        WHERE pair.record_kind OPERATOR(pg_catalog.=) 'event_receipt'
          AND pair.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
          AND pair.consumer_version OPERATOR(pg_catalog.=) NEW.consumer_version
          AND pair.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
          AND pair.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
          AND pair.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
          AND pair.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id
          AND pair.event_sequence OPERATOR(pg_catalog.=) NEW.through_sequence
          AND pair.event_id OPERATOR(pg_catalog.=) NEW.causation_id
          AND ROW(pair.tenant_id, pair.producer_group_id,
              pair.producer_group_generation, pair.producer_domain,
              pair.producer_generation, pair.writer_origin,
              pair.consumer_group_id, pair.consumer_group_generation,
              pair.consumer_domain, pair.consumer_generation)
          IS NOT DISTINCT FROM
              ROW(NEW.tenant_id, NEW.producer_group_id,
              NEW.producer_group_generation, NEW.producer_domain,
              NEW.producer_generation, NEW.writer_origin,
              NEW.consumer_group_id, NEW.consumer_group_generation,
              NEW.consumer_domain, NEW.consumer_generation)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5636',
            MESSAGE = 'async inbox event watermark lacks its receipt';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_require_inbox_event_pair_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_route_analytics_dashboard_export_maintenance_rec(platform.idempotency_receipts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_route_analytics_dashboard_export_maintenance_rec(p_receipt platform.idempotency_receipts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_job platform.jobs%ROWTYPE;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_receipt.writer_origin IS DISTINCT FROM 'v2' OR
       p_receipt.effect_kind NOT IN ('analytics.dashboard.export.delete',
                                     'analytics.dashboard.export.expire') THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance receipt route is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=p_receipt.causation_id AND job.tenant_id=p_receipt.tenant_id
    FOR UPDATE;
    IF platform.platform_async_assert_analytics_dashboard_export_receipt_replay_v1(
        p_receipt,v_job,p_current_user,p_session_user) THEN RETURN; END IF;
    IF v_job.state='running' THEN
        PERFORM platform.platform_async_assert_analytics_dashboard_export_running_receipt_v1(
            p_receipt,p_current_user,p_session_user);
    ELSIF v_job.state='dead' AND
          v_job.last_error_code='JOB_OUTCOME_UNKNOWN' THEN
        PERFORM platform.platform_async_assert_analytics_dashboard_export_maintenance_receipt_v1(
            p_receipt,p_current_user,p_session_user);
    ELSE
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance receipt state is invalid';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_route_analytics_dashboard_export_maintenance_rec(p_receipt platform.idempotency_receipts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_run_retention_cycle_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_run_retention_cycle_v1() RETURNS TABLE(lock_acquired boolean, jobs_redacted integer, outbox_redacted integer, dead_letters_redacted integer, inbox_purged integer, idempotency_purged integer, jobs_purged integer, dead_letters_purged integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'async retention cycle requires the exact runtime authority';
    END IF;

    SELECT pg_catalog.pg_try_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'harpy.platform_async.retention-cycle.v1', 0
        )
    ) INTO lock_acquired;
    jobs_redacted := 0;
    outbox_redacted := 0;
    dead_letters_redacted := 0;
    inbox_purged := 0;
    idempotency_purged := 0;
    jobs_purged := 0;
    dead_letters_purged := 0;

    IF NOT lock_acquired THEN
        RETURN NEXT;
        RETURN;
    END IF;

    jobs_redacted := platform.platform_async_redact_job_payloads_v1(500);
    outbox_redacted := platform.platform_async_redact_outbox_payloads_v2(500);
    dead_letters_redacted :=
        platform.platform_async_redact_dead_letter_payloads_v2(500);
    inbox_purged := platform.platform_async_purge_inbox_v1(500);
    idempotency_purged :=
        platform.platform_async_purge_idempotency_receipts_v1(500);
    jobs_purged := platform.platform_async_purge_jobs_v1(500);
    dead_letters_purged :=
        platform.platform_async_purge_dead_letters_v2(500);
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_async_run_retention_cycle_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_seal_v1_inventory_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_seal_v1_inventory_v1(p_run_id uuid, p_inventory_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.async_v1_adoption_runs%ROWTYPE;
    v_item_count bigint;
    v_inventory_sha256 text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5641',
            MESSAGE = 'V1 async inventory seal requires adopter authority';
    END IF;
    SELECT * INTO v_run
    FROM platform.async_v1_adoption_runs
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id
    FOR UPDATE;
    IF NOT FOUND OR v_run.state NOT IN ('inventory', 'disposing') OR
       v_run.inventory_sha256 IS DISTINCT FROM p_inventory_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5642',
            MESSAGE = 'V1 async inventory seal identity differs';
    END IF;
    SELECT pg_catalog.count(*),
           pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
               COALESCE(pg_catalog.string_agg(item_sha256, E'\n' ORDER BY item_sha256), ''),
               'UTF8'
           )), 'hex')
    INTO v_item_count, v_inventory_sha256
    FROM platform.async_v1_adoption_items
    WHERE run_id OPERATOR(pg_catalog.=) p_run_id;
    IF v_item_count IS DISTINCT FROM v_run.item_count OR
       v_inventory_sha256 IS DISTINCT FROM v_run.inventory_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5643',
            MESSAGE = 'V1 async inventory count or checksum differs';
    END IF;
    IF v_run.state OPERATOR(pg_catalog.=) 'inventory' THEN
        UPDATE platform.async_v1_adoption_runs
        SET state = 'disposing'
        WHERE run_id OPERATOR(pg_catalog.=) p_run_id;
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_seal_v1_inventory_v1(p_run_id uuid, p_inventory_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_analytics_dashboard_export_maintenance_(platform.job_attempts, platform.job_attempts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_analytics_dashboard_export_maintenance_(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_changed jsonb;
    v_max integer;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_current_user NOT IN ('harpy_owner','harpy_runtime',
           'harpy_v2_runtime') OR
       OLD.finished_at IS NOT NULL OR NEW.finished_at IS NULL OR
       OLD.effect_started_at IS NULL OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       NEW.effect_id IS DISTINCT FROM OLD.effect_id OR
       NEW.effect_request_sha256 IS DISTINCT FROM OLD.effect_request_sha256 OR
       NEW.outcome IS DISTINCT FROM 'dead' OR NEW.error_class IS NOT NULL OR
       NEW.error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       NEW.redacted_error_sha256 IS NOT NULL OR
       NEW.effect_receipt_id IS NOT NULL OR
       NEW.finished_at<OLD.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown attempt is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=NEW.job_id AND job.tenant_id=NEW.scope_id
      AND job.scope_kind='tenant' AND job.scope_id=NEW.scope_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind IN ('analytics.dashboard.export.delete',
                       'analytics.dashboard.export.expire')
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.state='running' AND job.attempts=NEW.attempt
      AND job.lease_generation=NEW.lease_generation
      AND job.lease_owner_id=NEW.lease_owner_id
      AND job.effect_started_at=NEW.effect_started_at
      AND pg_catalog.pg_input_is_valid(job.payload_ref,'uuid')
      AND job.payload_ref=(job.payload_ref::uuid)::text
      AND pg_catalog.uuid_extract_version(job.payload_ref::uuid)=7
      AND job.payload_sha256=pg_catalog.encode(pg_catalog.sha256(
          pg_catalog.convert_to(job.payload_ref,'UTF8')),'hex')
      AND job.dedupe_key=job.kind||':'||job.payload_ref
      AND job.effect_idempotency_key=job.dedupe_key FOR SHARE;
    v_max:=CASE v_job.kind
        WHEN 'analytics.dashboard.export.delete' THEN 3
        WHEN 'analytics.dashboard.export.expire' THEN 8 END;
    IF v_job.id IS NULL OR v_job.max_attempts IS DISTINCT FROM v_max OR
       NEW.attempt NOT BETWEEN 1 AND v_max OR
       pg_catalog.uuid_extract_version(NEW.attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(NEW.job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(NEW.lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(NEW.effect_id) IS DISTINCT FROM 5 OR
       NEW.effect_request_sha256!~'^[0-9a-f]{64}$' OR
       NEW.effect_request_sha256=pg_catalog.repeat('0',64) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown evidence differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
    IF EXISTS (
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.record_kind='effect' AND receipt.scope_kind=v_job.scope_kind
          AND receipt.scope_id=v_job.scope_id
          AND receipt.authority_group_id=v_job.authority_group_id
          AND receipt.authority_group_generation=v_job.authority_group_generation
          AND receipt.authority_domain=v_job.authority_domain
          AND receipt.cutover_generation=v_job.cutover_generation
          AND receipt.effect_key=v_job.effect_idempotency_key
          AND receipt.effect_id=NEW.effect_id
          AND receipt.request_sha256=NEW.effect_request_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown has a receipt';
    END IF;
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING(key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF v_changed IS DISTINCT FROM pg_catalog.to_jsonb(
        ARRAY['error_code','finished_at','outcome']::text[]
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown changed evidence';
    END IF;
END;
$_$;


ALTER FUNCTION platform.platform_async_validate_analytics_dashboard_export_maintenance_(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_analytics_dashboard_export_maintenance_(platform.jobs, platform.jobs, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_analytics_dashboard_export_maintenance_(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_attempt platform.job_attempts%ROWTYPE;
    v_changed jsonb;
    v_max integer;
BEGIN
    v_max:=CASE OLD.kind
        WHEN 'analytics.dashboard.export.delete' THEN 3
        WHEN 'analytics.dashboard.export.expire' THEN 8 END;
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       p_current_user NOT IN ('harpy_owner','harpy_runtime',
           'harpy_v2_runtime') OR v_max IS NULL OR
       OLD.state IS DISTINCT FROM 'running' OR
       OLD.scope_kind IS DISTINCT FROM 'tenant' OR
       OLD.tenant_id IS DISTINCT FROM OLD.scope_id OR
       OLD.authority_domain IS DISTINCT FROM 'analytics' OR
       OLD.writer_origin IS DISTINCT FROM 'v2' OR
       OLD.payload_revision IS DISTINCT FROM 1 OR
       OLD.effect_class IS DISTINCT FROM 'external' OR
       OLD.max_attempts IS DISTINCT FROM v_max OR
       OLD.attempts NOT BETWEEN 1 AND v_max OR
       OLD.effect_started_at IS NULL OR NEW.state IS DISTINCT FROM 'dead' OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       NEW.lease_owner_id IS NOT NULL OR NEW.lease_heartbeat_at IS NOT NULL OR
       NEW.lease_until IS NOT NULL OR NEW.last_error_class IS NOT NULL OR
       NEW.last_error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       NEW.last_error_sha256 IS NOT NULL OR
       NEW.completed_at IS DISTINCT FROM NEW.updated_at OR
       NEW.updated_at<=OLD.updated_at OR
       NEW.retain_until IS DISTINCT FROM NEW.completed_at+interval '365 days' OR
       NOT pg_catalog.pg_input_is_valid(OLD.payload_ref,'uuid') OR
       OLD.payload_ref IS DISTINCT FROM (OLD.payload_ref::uuid)::text OR
       pg_catalog.uuid_extract_version(OLD.payload_ref::uuid) IS DISTINCT FROM 7 OR
       OLD.payload_sha256 IS DISTINCT FROM pg_catalog.encode(pg_catalog.sha256(
           pg_catalog.convert_to(OLD.payload_ref,'UTF8')),'hex') OR
       OLD.dedupe_key IS DISTINCT FROM OLD.kind||':'||OLD.payload_ref OR
       OLD.effect_idempotency_key IS DISTINCT FROM OLD.dedupe_key THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown job is invalid';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=OLD.id AND attempt.attempt=OLD.attempts
      AND attempt.lease_generation=OLD.lease_generation
      AND attempt.lease_owner_id=OLD.lease_owner_id FOR SHARE;
    IF v_attempt.attempt_id IS NULL OR
       pg_catalog.uuid_extract_version(v_attempt.attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(v_attempt.lease_owner_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(v_attempt.effect_id) IS DISTINCT FROM 5 OR
       v_attempt.finished_at IS DISTINCT FROM NEW.updated_at OR
       v_attempt.outcome IS DISTINCT FROM 'dead' OR
       v_attempt.error_class IS NOT NULL OR
       v_attempt.error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       v_attempt.redacted_error_sha256 IS NOT NULL OR
       v_attempt.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       v_attempt.effect_request_sha256!~'^[0-9a-f]{64}$' OR
       v_attempt.effect_request_sha256=pg_catalog.repeat('0',64) OR
       v_attempt.effect_receipt_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown attempt differs';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        OLD.scope_kind,OLD.scope_id,OLD.authority_group_id,OLD.authority_domain);
    IF EXISTS (
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.record_kind='effect' AND receipt.scope_kind=OLD.scope_kind
          AND receipt.scope_id=OLD.scope_id
          AND receipt.authority_group_id=OLD.authority_group_id
          AND receipt.authority_group_generation=OLD.authority_group_generation
          AND receipt.authority_domain=OLD.authority_domain
          AND receipt.cutover_generation=OLD.cutover_generation
          AND receipt.effect_key=OLD.effect_idempotency_key
          AND receipt.effect_id=v_attempt.effect_id
          AND receipt.request_sha256=v_attempt.effect_request_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown has a receipt';
    END IF;
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING(key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF v_changed IS DISTINCT FROM pg_catalog.to_jsonb(ARRAY[
        'completed_at','last_error_code','lease_heartbeat_at','lease_owner_id',
        'lease_until','retain_until','state','updated_at'
    ]::text[]) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance unknown changed evidence';
    END IF;
END;
$_$;


