--
-- Name: platform_async_validate_analytics_export_maint_resolve_attempt_(platform.job_attempts, platform.job_attempts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_analytics_export_maint_resolve_attempt_(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_receipt platform.idempotency_receipts%ROWTYPE;
    v_resolution platform.analytics_dashboard_export_maintenance_unknown_resolutions%ROWTYPE;
    v_changed jsonb;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.finished_at IS NULL OR OLD.outcome IS DISTINCT FROM 'dead' OR
       OLD.error_class IS NOT NULL OR
       OLD.error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       OLD.redacted_error_sha256 IS NOT NULL OR OLD.effect_started_at IS NULL OR
       OLD.effect_receipt_id IS NOT NULL OR
       NEW.finished_at<=OLD.finished_at OR NEW.outcome IS DISTINCT FROM 'succeeded' OR
       NEW.error_class IS NOT NULL OR NEW.error_code IS NOT NULL OR
       NEW.redacted_error_sha256 IS NOT NULL OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       NEW.effect_id IS DISTINCT FROM OLD.effect_id OR
       NEW.effect_request_sha256 IS DISTINCT FROM OLD.effect_request_sha256 OR
       pg_catalog.uuid_extract_version(NEW.effect_receipt_id) IS DISTINCT FROM 5 THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution attempt is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=OLD.job_id AND job.tenant_id=OLD.scope_id
      AND job.scope_kind='tenant' AND job.scope_id=OLD.scope_id
      AND job.authority_domain='analytics' AND job.writer_origin='v2'
      AND job.kind IN ('analytics.dashboard.export.delete',
                       'analytics.dashboard.export.expire')
      AND job.state='dead' AND job.last_error_class IS NULL
      AND job.last_error_code='JOB_OUTCOME_UNKNOWN'
      AND job.completed_at=OLD.finished_at AND job.attempts=OLD.attempt
      AND job.lease_generation=OLD.lease_generation FOR SHARE;
    SELECT receipt.* INTO v_receipt FROM platform.idempotency_receipts AS receipt
    WHERE receipt.receipt_id=NEW.effect_receipt_id
      AND receipt.record_kind='effect' AND receipt.tenant_id=v_job.tenant_id
      AND receipt.scope_kind=v_job.scope_kind AND receipt.scope_id=v_job.scope_id
      AND receipt.authority_group_id=v_job.authority_group_id
      AND receipt.authority_group_generation=v_job.authority_group_generation
      AND receipt.authority_domain=v_job.authority_domain
      AND receipt.cutover_generation=v_job.cutover_generation
      AND receipt.writer_origin='v2'
      AND receipt.request_sha256=OLD.effect_request_sha256
      AND receipt.effect_id=OLD.effect_id AND receipt.effect_kind=v_job.kind
      AND receipt.effect_revision=1 AND receipt.effect_key=v_job.effect_idempotency_key
      AND receipt.effect_status='succeeded' AND receipt.effect_error_class IS NULL
      AND receipt.causation_id=v_job.id AND receipt.completed_at=NEW.finished_at
    FOR SHARE;
    SELECT resolution.* INTO v_resolution
    FROM platform.analytics_dashboard_export_maintenance_unknown_resolutions AS resolution
    WHERE resolution.job_id=v_job.id AND resolution.attempt_id=OLD.attempt_id
      AND resolution.effect_receipt_id=NEW.effect_receipt_id
      AND resolution.effect_id=OLD.effect_id
      AND resolution.request_sha256=OLD.effect_request_sha256
      AND resolution.original_unknown_at=OLD.finished_at
      AND resolution.original_attempt_finished_at=OLD.finished_at
      AND resolution.original_attempt_outcome=OLD.outcome
      AND resolution.original_error_class IS NOT DISTINCT FROM OLD.error_class
      AND resolution.original_error_code=OLD.error_code
      AND resolution.original_error_sha256 IS NOT DISTINCT FROM
          OLD.redacted_error_sha256
      AND resolution.resolved_at=NEW.finished_at FOR SHARE;
    IF v_job.id IS NULL OR v_receipt.receipt_id IS NULL OR
       v_resolution.resolution_receipt_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution evidence differs';
    END IF;
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING(key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF v_changed IS DISTINCT FROM pg_catalog.to_jsonb(ARRAY[
        'effect_receipt_id','error_code','finished_at','outcome'
    ]::text[]) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution changed evidence';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        v_job.scope_kind,v_job.scope_id,v_job.authority_group_id,
        v_job.authority_domain);
END;
$$;


ALTER FUNCTION platform.platform_async_validate_analytics_export_maint_resolve_attempt_(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_analytics_export_maint_resolve_job_v1(platform.jobs, platform.jobs, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_analytics_export_maint_resolve_job_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_attempt platform.job_attempts%ROWTYPE;
    v_receipt platform.idempotency_receipts%ROWTYPE;
    v_resolution platform.analytics_dashboard_export_maintenance_unknown_resolutions%ROWTYPE;
    v_changed jsonb;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.kind NOT IN ('analytics.dashboard.export.delete',
                        'analytics.dashboard.export.expire') OR
       OLD.state IS DISTINCT FROM 'dead' OR OLD.last_error_class IS NOT NULL OR
       OLD.last_error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       OLD.last_error_sha256 IS NOT NULL OR OLD.completed_at IS NULL OR
       NEW.state IS DISTINCT FROM 'succeeded' OR
       NEW.last_error_class IS NOT NULL OR NEW.last_error_code IS NOT NULL OR
       NEW.last_error_sha256 IS NOT NULL OR
       NEW.completed_at IS DISTINCT FROM NEW.updated_at OR
       NEW.updated_at<=OLD.completed_at OR
       NEW.retain_until IS DISTINCT FROM NEW.completed_at+interval '90 days' OR
       NEW.lease_owner_id IS NOT NULL OR NEW.lease_heartbeat_at IS NOT NULL OR
       NEW.lease_until IS NOT NULL OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution job is invalid';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=OLD.id AND attempt.attempt=OLD.attempts
      AND attempt.lease_generation=OLD.lease_generation
      AND attempt.outcome='succeeded' AND attempt.error_class IS NULL
      AND attempt.error_code IS NULL AND attempt.redacted_error_sha256 IS NULL
      AND attempt.effect_started_at=OLD.effect_started_at
      AND attempt.effect_receipt_id IS NOT NULL
      AND attempt.finished_at=NEW.completed_at FOR SHARE;
    SELECT receipt.* INTO v_receipt FROM platform.idempotency_receipts AS receipt
    WHERE receipt.receipt_id=v_attempt.effect_receipt_id
      AND receipt.record_kind='effect' AND receipt.tenant_id=OLD.tenant_id
      AND receipt.scope_kind=OLD.scope_kind AND receipt.scope_id=OLD.scope_id
      AND receipt.authority_group_id=OLD.authority_group_id
      AND receipt.authority_group_generation=OLD.authority_group_generation
      AND receipt.authority_domain=OLD.authority_domain
      AND receipt.cutover_generation=OLD.cutover_generation
      AND receipt.request_sha256=v_attempt.effect_request_sha256
      AND receipt.effect_id=v_attempt.effect_id AND receipt.effect_kind=OLD.kind
      AND receipt.effect_revision=1 AND receipt.effect_key=OLD.effect_idempotency_key
      AND receipt.effect_status='succeeded' AND receipt.effect_error_class IS NULL
      AND receipt.causation_id=OLD.id AND receipt.completed_at=NEW.completed_at
    FOR SHARE;
    SELECT resolution.* INTO v_resolution
    FROM platform.analytics_dashboard_export_maintenance_unknown_resolutions AS resolution
    WHERE resolution.job_id=OLD.id AND resolution.attempt_id=v_attempt.attempt_id
      AND resolution.effect_receipt_id=v_attempt.effect_receipt_id
      AND resolution.kind=OLD.kind AND resolution.tenant_id=OLD.tenant_id
      AND resolution.export_id=OLD.payload_ref::uuid
      AND resolution.original_unknown_at=OLD.completed_at
      AND resolution.original_attempt_finished_at=OLD.completed_at
      AND resolution.original_attempt_outcome='dead'
      AND resolution.original_error_class IS NULL
      AND resolution.original_error_code='JOB_OUTCOME_UNKNOWN'
      AND resolution.original_error_sha256 IS NULL
      AND resolution.resolved_at=NEW.completed_at FOR SHARE;
    IF v_attempt.attempt_id IS NULL OR v_receipt.receipt_id IS NULL OR
       v_resolution.resolution_receipt_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution chain differs';
    END IF;
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING(key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF v_changed IS DISTINCT FROM pg_catalog.to_jsonb(ARRAY[
        'completed_at','last_error_code','retain_until','state','updated_at'
    ]::text[]) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance resolution changed evidence';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_assert_cleanup_owner_v1(
        OLD.scope_kind,OLD.scope_id,OLD.authority_group_id,OLD.authority_domain);
END;
$$;


ALTER FUNCTION platform.platform_async_validate_analytics_export_maint_resolve_job_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_dead_letter_chain_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_dead_letter_chain_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    root_row platform.dead_letters%ROWTYPE;
    expected_sequence bigint;
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'dead_letters' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5640',
            MESSAGE = 'dead-letter chain trigger target is invalid';
    END IF;

    IF (
        (NEW.source_kind OPERATOR(pg_catalog.=) 'job' AND
            NEW.consumer_name IS NULL AND NEW.consumer_version IS NULL) OR
        (NEW.source_kind OPERATOR(pg_catalog.=) 'event' AND
            NEW.consumer_name IS NOT NULL AND NEW.consumer_version IS NOT NULL)
    ) IS NOT TRUE THEN
        RAISE EXCEPTION USING ERRCODE = 'P5641',
            MESSAGE = 'dead-letter source consumer shape is invalid';
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'root' THEN
        IF NEW.id IS DISTINCT FROM NEW.root_id OR
           NEW.entry_sequence IS DISTINCT FROM 0 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5642',
                MESSAGE = 'dead-letter root identity is invalid';
        END IF;
        RETURN NEW;
    END IF;

    IF (NEW.record_kind IN ('retry_action', 'repair_action')) IS NOT TRUE OR
       NEW.writer_origin IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5642',
            MESSAGE = 'dead-letter action identity is invalid';
    END IF;

    SELECT root.*
    INTO root_row
    FROM platform.dead_letters AS root
    WHERE root.id OPERATOR(pg_catalog.=) NEW.root_id AND
          root.record_kind OPERATOR(pg_catalog.=) 'root'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5643',
            MESSAGE = 'dead-letter root is missing';
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'retry_action' AND (
        root_row.payload_canonical IS NULL OR
        root_row.payload_redacted_at IS NOT NULL OR
        pg_catalog.clock_timestamp() >= root_row.full_payload_expires_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5644',
            MESSAGE = 'dead-letter payload cannot be retried';
    END IF;

    SELECT pg_catalog.max(entry.entry_sequence)::bigint + 1
    INTO expected_sequence
    FROM platform.dead_letters AS entry
    WHERE entry.root_id OPERATOR(pg_catalog.=) NEW.root_id;
    IF NEW.entry_sequence::bigint IS DISTINCT FROM expected_sequence THEN
        RAISE EXCEPTION USING ERRCODE = 'P5645',
            MESSAGE = 'dead-letter action sequence is not contiguous';
    END IF;

    IF ROW(
        NEW.tenant_id, NEW.scope_kind, NEW.scope_id,
        NEW.authority_group_id, NEW.authority_group_generation,
        NEW.authority_domain, NEW.cutover_generation
    ) IS DISTINCT FROM ROW(
        root_row.tenant_id, root_row.scope_kind, root_row.scope_id,
        root_row.authority_group_id, root_row.authority_group_generation,
        root_row.authority_domain, root_row.cutover_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5646',
            MESSAGE = 'dead-letter action authority differs from root';
    END IF;

    IF ROW(
        NEW.source_kind, NEW.source_id, NEW.consumer_name, NEW.consumer_version,
        NEW.source_contract, NEW.source_version, NEW.source_sha256,
        NEW.reason_class, NEW.reason_code, NEW.redacted_error_sha256
    ) IS DISTINCT FROM ROW(
        root_row.source_kind, root_row.source_id,
        root_row.consumer_name, root_row.consumer_version,
        root_row.source_contract, root_row.source_version, root_row.source_sha256,
        root_row.reason_class, root_row.reason_code, root_row.redacted_error_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5647',
            MESSAGE = 'dead-letter action source differs from root';
    END IF;

    IF ROW(
        NEW.payload_sha256, NEW.redacted_envelope,
        NEW.full_payload_expires_at, NEW.metadata_expires_at
    ) IS DISTINCT FROM ROW(
        root_row.payload_sha256, root_row.redacted_envelope,
        root_row.full_payload_expires_at, root_row.metadata_expires_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5648',
            MESSAGE = 'dead-letter action evidence differs from root';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_dead_letter_chain_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_validate_dead_letter_chain_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_dead_letter_chain_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    root_row platform.dead_letters%ROWTYPE;
    expected_sequence bigint;
    live_gap_job boolean;
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'dead_letters' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5640',
            MESSAGE = 'dead-letter chain trigger target is invalid';
    END IF;

    IF (
        (NEW.source_kind = 'job' AND
            NEW.consumer_name IS NULL AND NEW.consumer_version IS NULL) OR
        (NEW.source_kind = 'event' AND
            NEW.consumer_name IS NOT NULL AND NEW.consumer_version IS NOT NULL)
    ) IS NOT TRUE THEN
        RAISE EXCEPTION USING ERRCODE = 'P5641',
            MESSAGE = 'dead-letter source consumer shape is invalid';
    END IF;

    IF NEW.record_kind = 'root' THEN
        IF NEW.id IS DISTINCT FROM NEW.root_id OR
           NEW.entry_sequence IS DISTINCT FROM 0 THEN
            RAISE EXCEPTION USING ERRCODE = 'P5642',
                MESSAGE = 'dead-letter root identity is invalid';
        END IF;
        RETURN NEW;
    END IF;

    IF (NEW.record_kind IN ('retry_action', 'repair_action')) IS NOT TRUE OR
       NEW.writer_origin IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5642',
            MESSAGE = 'dead-letter action identity is invalid';
    END IF;

    SELECT root.* INTO root_row
    FROM platform.dead_letters AS root
    WHERE root.id = NEW.root_id AND root.record_kind = 'root'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5643',
            MESSAGE = 'dead-letter root is missing';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM platform.jobs AS job
        WHERE job.payload_ref = 'deadletter:event-gap:' || root_row.id::text
          AND job.payload_sha256 = root_row.payload_sha256
          AND job.kind = 'platform_async.event_gap_reconcile.' ||
              job.authority_domain
          AND job.state = 'running'
    ) INTO live_gap_job;
    IF NEW.record_kind = 'retry_action' AND (
        root_row.payload_canonical IS NULL OR
        root_row.payload_redacted_at IS NOT NULL OR
        (pg_catalog.clock_timestamp() >= root_row.full_payload_expires_at AND
            NOT (root_row.reason_class = 'sequence_gap' AND live_gap_job))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5644',
            MESSAGE = 'dead-letter payload cannot be retried';
    END IF;

    SELECT pg_catalog.max(entry.entry_sequence)::bigint + 1
    INTO expected_sequence
    FROM platform.dead_letters AS entry
    WHERE entry.root_id = NEW.root_id;
    IF NEW.entry_sequence::bigint IS DISTINCT FROM expected_sequence THEN
        RAISE EXCEPTION USING ERRCODE = 'P5645',
            MESSAGE = 'dead-letter action sequence is not contiguous';
    END IF;

    IF ROW(
        NEW.tenant_id, NEW.scope_kind, NEW.scope_id,
        NEW.authority_group_id, NEW.authority_group_generation,
        NEW.authority_domain, NEW.cutover_generation
    ) IS DISTINCT FROM ROW(
        root_row.tenant_id, root_row.scope_kind, root_row.scope_id,
        root_row.authority_group_id, root_row.authority_group_generation,
        root_row.authority_domain, root_row.cutover_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5646',
            MESSAGE = 'dead-letter action authority differs from root';
    END IF;

    IF ROW(
        NEW.source_kind, NEW.source_id, NEW.consumer_name, NEW.consumer_version,
        NEW.source_contract, NEW.source_version, NEW.source_sha256,
        NEW.reason_class, NEW.reason_code, NEW.redacted_error_sha256
    ) IS DISTINCT FROM ROW(
        root_row.source_kind, root_row.source_id,
        root_row.consumer_name, root_row.consumer_version,
        root_row.source_contract, root_row.source_version, root_row.source_sha256,
        root_row.reason_class, root_row.reason_code, root_row.redacted_error_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5647',
            MESSAGE = 'dead-letter action source differs from root';
    END IF;

    IF ROW(
        NEW.payload_sha256, NEW.redacted_envelope,
        NEW.full_payload_expires_at, NEW.metadata_expires_at
    ) IS DISTINCT FROM ROW(
        root_row.payload_sha256, root_row.redacted_envelope,
        root_row.full_payload_expires_at, root_row.metadata_expires_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5648',
            MESSAGE = 'dead-letter action evidence differs from root';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_dead_letter_chain_v2() OWNER TO harpy_owner;

--
-- Name: platform_async_validate_iam_export_reconcile_expired_attempt_v1(platform.job_attempts, platform.job_attempts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_iam_export_reconcile_expired_attempt_v1(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_changed jsonb;
    v_current boolean;
    v_authority_exists boolean;
    v_failure text;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.finished_at IS NOT NULL OR NEW.finished_at IS NULL OR
       NEW.outcome<>'dead' OR NEW.error_class<>'permanent' OR
       NEW.error_code<>'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' OR
       NEW.redacted_error_sha256 IS NULL OR NEW.effect_receipt_id IS NULL OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       NEW.effect_id IS DISTINCT FROM OLD.effect_id OR
       NEW.effect_request_sha256 IS DISTINCT FROM OLD.effect_request_sha256 OR
       NEW.finished_at<OLD.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM expired reconciliation attempt is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=NEW.job_id AND job.scope_kind=NEW.scope_kind
      AND job.scope_id=NEW.scope_id AND job.tenant_id=NEW.scope_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.effect_class='external' AND job.state='running'
      AND job.attempts=NEW.attempt AND job.lease_generation=NEW.lease_generation
      AND job.lease_owner_id=NEW.lease_owner_id
      AND job.effect_started_at IS NOT NULL
      AND job.lease_until<=NEW.finished_at AND job.updated_at<NEW.finished_at
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM expired reconciliation attempt lease is stale';
    END IF;
    SELECT EXISTS(
        SELECT 1 FROM platform.cutover_groups AS group_row
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind=group_row.scope_kind
         AND domain_row.scope_id=group_row.scope_id
        WHERE group_row.scope_kind=v_job.scope_kind
          AND group_row.scope_id=v_job.scope_id
          AND group_row.group_id=v_job.authority_group_id
          AND group_row.generation=v_job.authority_group_generation
          AND group_row.state='v2' AND group_row.writer='v2'
          AND domain_row.domain=v_job.authority_domain
          AND domain_row.generation=v_job.cutover_generation
          AND domain_row.state='v2' AND domain_row.writer='v2'
    ),EXISTS(
        SELECT 1 FROM platform.cutover_group_members AS member
        WHERE member.scope_kind=v_job.scope_kind AND member.scope_id=v_job.scope_id
          AND member.group_id=v_job.authority_group_id
          AND member.domain=v_job.authority_domain
    ) INTO v_current,v_authority_exists;
    IF v_current THEN
        PERFORM platform.platform_async_validate_job_attempt_v1(
            OLD,NEW,p_current_user,p_session_user);
        RETURN;
    END IF;
    v_failure := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(
            'iam.system-export.reconciliation-failure.v1','UTF8')||
        pg_catalog.decode('00','hex')||pg_catalog.uuid_send(NEW.job_id)||
        pg_catalog.uuid_send(NEW.effect_id)||pg_catalog.int8send(
            pg_catalog.octet_length(pg_catalog.convert_to(NEW.error_code,'UTF8')))||
        pg_catalog.convert_to(NEW.error_code,'UTF8')||
        pg_catalog.int8send(NEW.lease_generation)),'hex');
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key) INTO v_changed
    FROM (
        SELECT old_field.key FROM pg_catalog.jsonb_each(
            pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING(key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF NOT v_authority_exists OR NEW.redacted_error_sha256<>v_failure OR
       v_changed IS DISTINCT FROM pg_catalog.to_jsonb(ARRAY[
           'effect_receipt_id','error_class','error_code','finished_at',
           'outcome','redacted_error_sha256'
       ]::text[]) OR NOT EXISTS(
           SELECT 1 FROM platform.idempotency_receipts AS receipt
           WHERE receipt.receipt_id=NEW.effect_receipt_id
             AND receipt.scope_kind=NEW.scope_kind AND receipt.scope_id=NEW.scope_id
             AND receipt.authority_group_id=v_job.authority_group_id
             AND receipt.authority_group_generation=v_job.authority_group_generation
             AND receipt.authority_domain=v_job.authority_domain
             AND receipt.cutover_generation=v_job.cutover_generation
             AND receipt.effect_key=v_job.effect_idempotency_key
             AND receipt.effect_id=NEW.effect_id
             AND receipt.request_sha256=NEW.effect_request_sha256
             AND receipt.effect_status='failed'
             AND receipt.effect_error_class='permanent'
             AND receipt.effect_code=NEW.error_code
             AND receipt.completed_at=NEW.finished_at
       ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM expired reconciliation attempt evidence differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_iam_export_reconcile_expired_attempt_v1(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_iam_export_reconcile_expired_job_v1(platform.jobs, platform.jobs, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_iam_export_reconcile_expired_job_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_attempt platform.job_attempts%ROWTYPE;
    v_changed jsonb;
    v_current boolean;
    v_authority_exists boolean;
    v_failure text;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.state<>'running' OR OLD.effect_class<>'external' OR
       OLD.kind<>'iam.system-resource.export-reconcile' OR
       OLD.authority_group_id<>'iam_system_resources' OR
       OLD.authority_domain<>'iam' OR OLD.writer_origin<>'v2' OR
       NEW.state<>'dead' OR NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       NEW.lease_owner_id IS NOT NULL OR NEW.lease_heartbeat_at IS NOT NULL OR
       NEW.lease_until IS NOT NULL OR NEW.last_error_class<>'permanent' OR
       NEW.last_error_code<>'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' OR
       NEW.last_error_sha256 IS NULL OR NEW.completed_at<>NEW.updated_at OR
       NEW.updated_at<=OLD.updated_at OR NEW.updated_at<OLD.lease_until OR
       NEW.retain_until<NEW.completed_at+interval '366 days' THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM expired reconciliation job is invalid';
    END IF;
    SELECT EXISTS(
        SELECT 1 FROM platform.cutover_groups AS group_row
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind=group_row.scope_kind
         AND domain_row.scope_id=group_row.scope_id
        WHERE group_row.scope_kind=OLD.scope_kind
          AND group_row.scope_id=OLD.scope_id
          AND group_row.group_id=OLD.authority_group_id
          AND group_row.generation=OLD.authority_group_generation
          AND group_row.state='v2' AND group_row.writer='v2'
          AND domain_row.domain=OLD.authority_domain
          AND domain_row.generation=OLD.cutover_generation
          AND domain_row.state='v2' AND domain_row.writer='v2'
    ),EXISTS(
        SELECT 1 FROM platform.cutover_group_members AS member
        WHERE member.scope_kind=OLD.scope_kind AND member.scope_id=OLD.scope_id
          AND member.group_id=OLD.authority_group_id
          AND member.domain=OLD.authority_domain
    ) INTO v_current,v_authority_exists;
    IF v_current THEN
        PERFORM platform.platform_async_validate_job_transition_v1(
            OLD,NEW,p_current_user,p_session_user);
        RETURN;
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=OLD.id AND attempt.attempt=OLD.attempts
      AND attempt.lease_generation=OLD.lease_generation
      AND attempt.lease_owner_id=OLD.lease_owner_id
      AND attempt.finished_at=NEW.updated_at AND attempt.outcome='dead'
      AND attempt.error_class='permanent'
      AND attempt.error_code=NEW.last_error_code
      AND attempt.redacted_error_sha256=NEW.last_error_sha256
      AND attempt.effect_started_at IS NOT NULL
      AND attempt.effect_receipt_id IS NOT NULL FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM expired reconciliation job attempt differs';
    END IF;
    v_failure := pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(
            'iam.system-export.reconciliation-failure.v1','UTF8')||
        pg_catalog.decode('00','hex')||pg_catalog.uuid_send(OLD.id)||
        pg_catalog.uuid_send(v_attempt.effect_id)||pg_catalog.int8send(
            pg_catalog.octet_length(pg_catalog.convert_to(NEW.last_error_code,'UTF8')))||
        pg_catalog.convert_to(NEW.last_error_code,'UTF8')||
        pg_catalog.int8send(OLD.lease_generation)),'hex');
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key) INTO v_changed
    FROM (
        SELECT old_field.key FROM pg_catalog.jsonb_each(
            pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING(key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF NOT v_authority_exists OR NEW.last_error_sha256<>v_failure OR
       v_changed IS DISTINCT FROM pg_catalog.to_jsonb(ARRAY[
           'completed_at','last_error_class','last_error_code','last_error_sha256',
           'lease_heartbeat_at','lease_owner_id','lease_until','retain_until',
           'state','updated_at'
       ]::text[]) OR NOT EXISTS(
           SELECT 1 FROM platform.idempotency_receipts AS receipt
           WHERE receipt.receipt_id=v_attempt.effect_receipt_id
             AND receipt.tenant_id=OLD.tenant_id
             AND receipt.scope_kind=OLD.scope_kind AND receipt.scope_id=OLD.scope_id
             AND receipt.authority_group_id=OLD.authority_group_id
             AND receipt.authority_group_generation=OLD.authority_group_generation
             AND receipt.authority_domain=OLD.authority_domain
             AND receipt.cutover_generation=OLD.cutover_generation
             AND receipt.effect_key=OLD.effect_idempotency_key
             AND receipt.effect_id=v_attempt.effect_id
             AND receipt.request_sha256=v_attempt.effect_request_sha256
             AND receipt.effect_status='failed'
             AND receipt.effect_error_class='permanent'
             AND receipt.effect_code=NEW.last_error_code
             AND receipt.completed_at=NEW.updated_at
       ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM expired reconciliation job evidence differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_iam_export_reconcile_expired_job_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_iam_export_reconcile_expired_receipt_v1(platform.idempotency_receipts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_iam_export_reconcile_expired_receipt_v1(new platform.idempotency_receipts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       NEW.record_kind<>'effect' OR NEW.scope_kind<>'tenant' OR
       NEW.tenant_id IS NULL OR NEW.scope_id<>NEW.tenant_id OR
       NEW.authority_group_id<>'iam_system_resources' OR
       NEW.authority_domain<>'iam' OR NEW.writer_origin<>'v2' OR
       NEW.retention_class<>'external_effect' OR
       NEW.effect_kind<>'iam.system-resource.export-reconcile' OR
       NEW.effect_revision<>1 OR NEW.provider<>'object-storage' OR
       NEW.operation<>'head-object' OR NEW.effect_status<>'failed' OR
       NEW.effect_error_class<>'permanent' OR
       NEW.effect_code<>'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' OR
       NEW.provider_reference IS NOT NULL OR NEW.effect_result_ref IS NOT NULL OR
       NEW.effect_result_sha256 IS NOT NULL OR
       NEW.retain_until<NEW.completed_at+interval '366 days' THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM expired reconciliation receipt is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.id=NEW.causation_id AND job.tenant_id=NEW.tenant_id
      AND job.scope_kind=NEW.scope_kind AND job.scope_id=NEW.scope_id
      AND job.authority_group_id=NEW.authority_group_id
      AND job.authority_group_generation=NEW.authority_group_generation
      AND job.authority_domain=NEW.authority_domain
      AND job.cutover_generation=NEW.cutover_generation
      AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.effect_class='external' AND job.effect_idempotency_key=NEW.effect_key
      AND job.state='running' AND job.lease_until<=NEW.completed_at
      AND job.updated_at<NEW.completed_at FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM expired reconciliation receipt job is stale';
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=v_job.id AND attempt.attempt=v_job.attempts
      AND attempt.lease_generation=v_job.lease_generation
      AND attempt.lease_owner_id=v_job.lease_owner_id
      AND attempt.effect_id=NEW.effect_id
      AND attempt.effect_request_sha256=NEW.request_sha256
      AND attempt.effect_started_at IS NOT NULL
      AND attempt.finished_at IS NULL AND attempt.effect_receipt_id IS NULL
    FOR SHARE;
    IF NOT FOUND OR NEW.correlation_id<>NEW.effect_id::text OR
       NEW.completed_at<v_attempt.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM expired reconciliation receipt attempt differs';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_iam_export_reconcile_expired_receipt_v1(new platform.idempotency_receipts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_inbox_insert_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_inbox_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'inbox' OR
       SESSION_USER OPERATOR(pg_catalog.<>) 'harpy_v2_runtime' OR
       NEW.consumer_writer_origin IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5606',
            MESSAGE = 'async inbox consumer authority is invalid';
    END IF;

    IF platform.platform_async_assert_current_authority_v1(
        NEW.scope_kind, NEW.scope_id,
        NEW.consumer_group_id, NEW.consumer_group_generation,
        NEW.consumer_domain, NEW.consumer_generation
    ) IS NULL THEN
        NULL;
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'event_receipt' AND
       NEW.event_id IS NOT NULL AND NEW.event_type IS NOT NULL AND
       NEW.event_version IS NOT NULL AND NEW.event_sequence IS NOT NULL AND
       NEW.through_sequence IS NULL AND NEW.watermark_kind IS NULL AND
       NEW.causation_id IS NULL AND NEW.state_sha256 IS NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM platform.outbox AS event_row
            WHERE event_row.event_id OPERATOR(pg_catalog.=) NEW.event_id
              AND event_row.tenant_id IS NOT DISTINCT FROM NEW.tenant_id
              AND event_row.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
              AND event_row.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
              AND event_row.authority_group_id OPERATOR(pg_catalog.=)
                  NEW.producer_group_id
              AND event_row.authority_group_generation OPERATOR(pg_catalog.=)
                  NEW.producer_group_generation
              AND event_row.authority_domain OPERATOR(pg_catalog.=)
                  NEW.producer_domain
              AND event_row.cutover_generation OPERATOR(pg_catalog.=)
                  NEW.producer_generation
              AND event_row.writer_origin OPERATOR(pg_catalog.=) NEW.writer_origin
              AND event_row.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
              AND event_row.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id
              AND event_row.event_type OPERATOR(pg_catalog.=) NEW.event_type
              AND event_row.event_version OPERATOR(pg_catalog.=) NEW.event_version
              AND event_row.event_sequence OPERATOR(pg_catalog.=) NEW.event_sequence
            FOR SHARE
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5609',
                MESSAGE = 'async event receipt producer is invalid';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'watermark' AND
       NEW.watermark_kind OPERATOR(pg_catalog.=) 'event' AND
       NEW.event_id IS NULL AND NEW.event_type IS NULL AND
       NEW.event_version IS NULL AND NEW.event_sequence IS NULL AND
       NEW.through_sequence IS NOT NULL AND NEW.causation_id IS NOT NULL AND
       NEW.state_sha256 IS NULL THEN
        IF NOT EXISTS (
            SELECT 1
            FROM platform.outbox AS event_row
            JOIN platform.inbox AS receipt
              ON receipt.record_kind OPERATOR(pg_catalog.=) 'event_receipt'
             AND receipt.consumer_name OPERATOR(pg_catalog.=) NEW.consumer_name
             AND receipt.consumer_version OPERATOR(pg_catalog.=) NEW.consumer_version
             AND receipt.event_id OPERATOR(pg_catalog.=) event_row.event_id
             AND receipt.event_type OPERATOR(pg_catalog.=) event_row.event_type
             AND receipt.event_version OPERATOR(pg_catalog.=) event_row.event_version
             AND receipt.event_sequence OPERATOR(pg_catalog.=) event_row.event_sequence
             AND receipt.tenant_id IS NOT DISTINCT FROM NEW.tenant_id
             AND receipt.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
             AND receipt.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
             AND receipt.producer_group_id OPERATOR(pg_catalog.=)
                 NEW.producer_group_id
             AND receipt.producer_group_generation OPERATOR(pg_catalog.=)
                 NEW.producer_group_generation
             AND receipt.producer_domain OPERATOR(pg_catalog.=) NEW.producer_domain
             AND receipt.producer_generation OPERATOR(pg_catalog.=)
                 NEW.producer_generation
             AND receipt.writer_origin OPERATOR(pg_catalog.=) NEW.writer_origin
             AND receipt.consumer_group_id OPERATOR(pg_catalog.=)
                 NEW.consumer_group_id
             AND receipt.consumer_group_generation OPERATOR(pg_catalog.=)
                 NEW.consumer_group_generation
             AND receipt.consumer_domain OPERATOR(pg_catalog.=) NEW.consumer_domain
             AND receipt.consumer_generation OPERATOR(pg_catalog.=)
                 NEW.consumer_generation
             AND receipt.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
             AND receipt.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id
            WHERE event_row.event_id OPERATOR(pg_catalog.=) NEW.causation_id
              AND event_row.tenant_id IS NOT DISTINCT FROM NEW.tenant_id
              AND event_row.scope_kind OPERATOR(pg_catalog.=) NEW.scope_kind
              AND event_row.scope_id OPERATOR(pg_catalog.=) NEW.scope_id
              AND event_row.authority_group_id OPERATOR(pg_catalog.=)
                  NEW.producer_group_id
              AND event_row.authority_group_generation OPERATOR(pg_catalog.=)
                  NEW.producer_group_generation
              AND event_row.authority_domain OPERATOR(pg_catalog.=)
                  NEW.producer_domain
              AND event_row.cutover_generation OPERATOR(pg_catalog.=)
                  NEW.producer_generation
              AND event_row.writer_origin OPERATOR(pg_catalog.=) NEW.writer_origin
              AND event_row.aggregate_type OPERATOR(pg_catalog.=) NEW.aggregate_type
              AND event_row.aggregate_id OPERATOR(pg_catalog.=) NEW.aggregate_id
              AND event_row.event_sequence OPERATOR(pg_catalog.=) NEW.through_sequence
            FOR SHARE OF event_row, receipt
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5611',
                MESSAGE = 'async event watermark producer is invalid';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.record_kind OPERATOR(pg_catalog.=) 'watermark' AND
       NEW.watermark_kind OPERATOR(pg_catalog.=) 'bootstrap' AND
       NEW.event_id IS NULL AND NEW.event_type IS NULL AND
       NEW.event_version IS NULL AND NEW.event_sequence IS NULL AND
       NEW.through_sequence IS NOT NULL AND NEW.causation_id IS NOT NULL AND
       NEW.state_sha256 IS NOT NULL THEN
        IF NEW.writer_origin IS DISTINCT FROM 'v2' THEN
            RAISE EXCEPTION USING ERRCODE = 'P5607',
                MESSAGE = 'async bootstrap producer origin is invalid';
        END IF;
        IF platform.platform_async_assert_current_authority_v1(
            NEW.scope_kind, NEW.scope_id,
            NEW.producer_group_id, NEW.producer_group_generation,
            NEW.producer_domain, NEW.producer_generation
        ) IS NULL THEN
            NULL;
        END IF;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION USING ERRCODE = 'P5608',
        MESSAGE = 'async inbox record shape is invalid';
END;
$$;


ALTER FUNCTION platform.platform_async_validate_inbox_insert_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_validate_job_attempt_v1(platform.job_attempts, platform.job_attempts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_job_attempt_v1(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_changed jsonb;
    v_receipt_status text;
    v_receipt_found boolean;
    v_effect_valid boolean;
    v_owner_stale boolean;
BEGIN
    v_receipt_found := false;
    v_effect_valid := false;
    v_owner_stale := false;
    IF pg_catalog.pg_trigger_depth() <> 1 OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5620',
            MESSAGE = 'job attempt invocation is invalid';
    END IF;

    SELECT job_row.* INTO v_job
    FROM platform.jobs AS job_row
    WHERE job_row.scope_kind = NEW.scope_kind
      AND job_row.scope_id = NEW.scope_id
      AND job_row.id = NEW.job_id
    FOR SHARE;
    IF NOT FOUND OR v_job.state IS DISTINCT FROM 'running' OR
       v_job.attempts IS DISTINCT FROM NEW.attempt OR
       v_job.lease_generation IS DISTINCT FROM NEW.lease_generation OR
       v_job.lease_owner_id IS DISTINCT FROM NEW.lease_owner_id THEN
        RAISE EXCEPTION USING ERRCODE = 'P5621',
            MESSAGE = 'job attempt lease is stale';
    END IF;

    IF OLD IS NULL THEN
        IF NEW.started_at IS DISTINCT FROM v_job.lease_heartbeat_at OR
           NEW.finished_at IS NOT NULL OR NEW.outcome IS NOT NULL OR
           NEW.error_class IS NOT NULL OR NEW.error_code IS NOT NULL OR
           NEW.redacted_error_sha256 IS NOT NULL OR
           NEW.effect_started_at IS NOT NULL OR NEW.effect_id IS NOT NULL OR
           NEW.effect_request_sha256 IS NOT NULL OR
           NEW.effect_receipt_id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P5622',
                MESSAGE = 'job attempt insert is invalid';
        END IF;
        IF platform.platform_async_assert_current_authority_v1(
            v_job.scope_kind, v_job.scope_id, v_job.authority_group_id,
            v_job.authority_group_generation, v_job.authority_domain,
            v_job.cutover_generation
        ) IS NULL THEN NULL; END IF;
        RETURN;
    END IF;

    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;

    IF OLD.finished_at IS NULL AND NEW.finished_at IS NULL AND
       OLD.effect_started_at IS NULL AND NEW.effect_started_at IS NOT NULL AND
       OLD.effect_id IS NULL AND NEW.effect_id IS NOT NULL AND
       OLD.effect_request_sha256 IS NULL AND
       NEW.effect_request_sha256 IS NOT NULL AND
       v_job.effect_class = 'external' AND
       v_job.cancel_requested_at IS NULL AND
       v_job.effect_started_at IS NOT NULL AND
       NEW.effect_started_at >= NEW.started_at AND
       NEW.effect_started_at >= v_job.effect_started_at AND
       (v_changed OPERATOR(pg_catalog.<@)
        pg_catalog.to_jsonb(ARRAY[
            'effect_started_at','effect_id','effect_request_sha256'
        ]::text[])) THEN
        IF platform.platform_async_assert_current_authority_v1(
            v_job.scope_kind, v_job.scope_id, v_job.authority_group_id,
            v_job.authority_group_generation, v_job.authority_domain,
            v_job.cutover_generation
        ) IS NULL THEN NULL; END IF;
        RETURN;
    END IF;

    IF OLD.finished_at IS NOT NULL OR NEW.finished_at IS NULL OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       (NEW.effect_started_at IS NOT NULL AND
        (v_job.effect_started_at IS NULL OR
         NEW.effect_started_at < v_job.effect_started_at)) OR
       NOT (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'finished_at','outcome','error_class','error_code',
           'redacted_error_sha256','effect_receipt_id'
       ]::text[])) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5623',
            MESSAGE = 'job attempt transition is forbidden';
    END IF;

    IF NEW.effect_receipt_id IS NOT NULL THEN
        SELECT receipt.effect_status INTO v_receipt_status
        FROM platform.idempotency_receipts AS receipt
        WHERE receipt.receipt_id = NEW.effect_receipt_id
          AND receipt.record_kind = 'effect'
          AND receipt.scope_kind = v_job.scope_kind
          AND receipt.scope_id = v_job.scope_id
          AND receipt.authority_group_id = v_job.authority_group_id
          AND receipt.authority_group_generation = v_job.authority_group_generation
          AND receipt.authority_domain = v_job.authority_domain
          AND receipt.cutover_generation = v_job.cutover_generation
          AND receipt.effect_key = v_job.effect_idempotency_key
          AND receipt.effect_id = NEW.effect_id
          AND receipt.request_sha256 = NEW.effect_request_sha256
          AND receipt.completed_at <= NEW.finished_at;
        v_receipt_found := FOUND;
    END IF;

    IF v_job.effect_class = 'database_transactional' THEN
        v_effect_valid := NEW.effect_started_at IS NULL AND
            NEW.effect_receipt_id IS NULL;
    ELSIF NEW.outcome = 'succeeded' THEN
        v_effect_valid := NEW.effect_started_at IS NOT NULL AND
            v_receipt_found AND v_receipt_status = 'succeeded';
    ELSIF NEW.outcome = 'dead' AND NEW.error_code = 'JOB_OUTCOME_UNKNOWN' THEN
        v_effect_valid := NEW.effect_started_at IS NOT NULL AND
            NEW.effect_receipt_id IS NULL;
    ELSIF NEW.outcome = 'lease_expired' THEN
        v_effect_valid :=
            (NEW.effect_started_at IS NULL AND NEW.effect_receipt_id IS NULL) OR
            (NEW.effect_started_at IS NOT NULL AND v_receipt_found);
    ELSE
        v_effect_valid :=
            (NEW.effect_started_at IS NULL AND NEW.effect_receipt_id IS NULL) OR
            (NEW.effect_started_at IS NOT NULL AND v_receipt_found AND
             v_receipt_status = 'failed');
    END IF;
    IF NOT v_effect_valid THEN
        RAISE EXCEPTION USING ERRCODE = 'P5624',
            MESSAGE = 'job attempt effect receipt is invalid';
    END IF;

    v_owner_stale := p_current_user = 'harpy_owner' AND
        NEW.outcome = 'lease_expired' AND NEW.error_class = 'conflict' AND
        NEW.error_code = 'JOB_AUTHORITY_STALE';
    IF NOT v_owner_stale THEN
        IF platform.platform_async_assert_current_authority_v1(
            v_job.scope_kind, v_job.scope_id, v_job.authority_group_id,
            v_job.authority_group_generation, v_job.authority_domain,
            v_job.cutover_generation
        ) IS NULL THEN NULL; END IF;
    END IF;
    RETURN;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_job_attempt_v1(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_job_attempt_v2(platform.job_attempts, platform.job_attempts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_job_attempt_v2(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_changed jsonb;
    v_receipt_status text;
    v_receipt_found boolean := false;
    v_effect_valid boolean := false;
    v_owner_stale boolean := false;
BEGIN
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='P5620',
            MESSAGE='job attempt invocation is invalid';
    END IF;
    SELECT job.* INTO v_job FROM platform.jobs AS job
    WHERE job.scope_kind=NEW.scope_kind AND job.scope_id=NEW.scope_id
      AND job.id=NEW.job_id FOR SHARE;
    IF NOT FOUND OR v_job.state IS DISTINCT FROM 'running' OR
       v_job.attempts IS DISTINCT FROM NEW.attempt OR
       v_job.lease_generation IS DISTINCT FROM NEW.lease_generation OR
       v_job.lease_owner_id IS DISTINCT FROM NEW.lease_owner_id THEN
        RAISE EXCEPTION USING ERRCODE='P5621', MESSAGE='job attempt lease is stale';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.cutover_job_bindings AS binding
                   WHERE binding.job_id=v_job.id) THEN
        PERFORM platform.platform_async_validate_job_attempt_v1(
            OLD,NEW,p_current_user,p_session_user);
        RETURN;
    END IF;
    IF OLD IS NULL THEN
        IF NEW.started_at IS DISTINCT FROM v_job.lease_heartbeat_at OR
           NEW.finished_at IS NOT NULL OR NEW.outcome IS NOT NULL OR
           NEW.error_class IS NOT NULL OR NEW.error_code IS NOT NULL OR
           NEW.redacted_error_sha256 IS NOT NULL OR
           NEW.effect_started_at IS NOT NULL OR NEW.effect_id IS NOT NULL OR
           NEW.effect_request_sha256 IS NOT NULL OR
           NEW.effect_receipt_id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='P5622',
                MESSAGE='job attempt insert is invalid';
        END IF;
        PERFORM platform.platform_async_assert_job_row_authority_v1(v_job);
        RETURN;
    END IF;
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key) INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF OLD.finished_at IS NULL AND NEW.finished_at IS NULL
       AND OLD.effect_started_at IS NULL AND NEW.effect_started_at IS NOT NULL
       AND OLD.effect_id IS NULL AND NEW.effect_id IS NOT NULL
       AND OLD.effect_request_sha256 IS NULL
       AND NEW.effect_request_sha256 IS NOT NULL
       AND v_job.effect_class='external' AND v_job.cancel_requested_at IS NULL
       AND v_job.effect_started_at IS NOT NULL
       AND NEW.effect_started_at>=NEW.started_at
       AND NEW.effect_started_at>=v_job.effect_started_at
       AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'effect_started_at','effect_id','effect_request_sha256']::text[]) THEN
        PERFORM platform.platform_async_assert_job_row_authority_v1(v_job);
        RETURN;
    END IF;
    IF OLD.finished_at IS NOT NULL OR NEW.finished_at IS NULL OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       (NEW.effect_started_at IS NOT NULL AND
        (v_job.effect_started_at IS NULL OR
         NEW.effect_started_at<v_job.effect_started_at)) OR
       NOT (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'finished_at','outcome','error_class','error_code',
           'redacted_error_sha256','effect_receipt_id']::text[])) THEN
        RAISE EXCEPTION USING ERRCODE='P5623',
            MESSAGE='job attempt transition is forbidden';
    END IF;
    IF NEW.effect_receipt_id IS NOT NULL THEN
        SELECT receipt.effect_status INTO v_receipt_status
        FROM platform.idempotency_receipts AS receipt
        WHERE receipt.receipt_id=NEW.effect_receipt_id
          AND receipt.record_kind='effect'
          AND receipt.scope_kind=v_job.scope_kind AND receipt.scope_id=v_job.scope_id
          AND receipt.authority_group_id=v_job.authority_group_id
          AND receipt.authority_group_generation=v_job.authority_group_generation
          AND receipt.authority_domain=v_job.authority_domain
          AND receipt.cutover_generation=v_job.cutover_generation
          AND receipt.effect_key=v_job.effect_idempotency_key
          AND receipt.effect_id=NEW.effect_id
          AND receipt.request_sha256=NEW.effect_request_sha256
          AND receipt.completed_at<=NEW.finished_at;
        v_receipt_found := FOUND;
    END IF;
    IF v_job.effect_class='database_transactional' THEN
        v_effect_valid := NEW.effect_started_at IS NULL
            AND NEW.effect_receipt_id IS NULL;
    ELSIF NEW.outcome='succeeded' THEN
        v_effect_valid := NEW.effect_started_at IS NOT NULL
            AND v_receipt_found AND v_receipt_status='succeeded';
    ELSIF NEW.outcome='dead' AND NEW.error_code='JOB_OUTCOME_UNKNOWN' THEN
        v_effect_valid := NEW.effect_started_at IS NOT NULL
            AND NEW.effect_receipt_id IS NULL;
    ELSIF NEW.outcome='lease_expired' THEN
        v_effect_valid := (NEW.effect_started_at IS NULL
            AND NEW.effect_receipt_id IS NULL) OR
            (NEW.effect_started_at IS NOT NULL AND v_receipt_found);
    ELSE
        v_effect_valid := (NEW.effect_started_at IS NULL
            AND NEW.effect_receipt_id IS NULL) OR
            (NEW.effect_started_at IS NOT NULL AND v_receipt_found
             AND v_receipt_status='failed');
    END IF;
    IF NOT v_effect_valid THEN
        RAISE EXCEPTION USING ERRCODE='P5624',
            MESSAGE='job attempt effect receipt is invalid';
    END IF;
    v_owner_stale := p_current_user='harpy_owner'
        AND NEW.outcome='lease_expired' AND NEW.error_class='conflict'
        AND NEW.error_code='JOB_AUTHORITY_STALE';
    IF NOT v_owner_stale THEN
        PERFORM platform.platform_async_assert_job_row_authority_v1(v_job);
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_job_attempt_v2(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_job_transition_v1(platform.jobs, platform.jobs, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_job_transition_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_changed jsonb;
    v_normal boolean;
    v_owner boolean;
BEGIN
    IF pg_catalog.pg_trigger_depth() <> 1 OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5610',
            MESSAGE = 'job transition invocation is invalid';
    END IF;
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    v_normal :=
        (OLD.state = 'queued' AND OLD.parked_at IS NULL AND
         NEW.state = 'running' AND NEW.attempts = OLD.attempts + 1 AND
         NEW.lease_generation = OLD.lease_generation + 1 AND
         NEW.lease_heartbeat_at > OLD.updated_at AND
         NEW.lease_until = NEW.lease_heartbeat_at + interval '60 seconds' AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','attempts','lease_generation','lease_owner_id',
             'lease_heartbeat_at','lease_until','updated_at'
         ]::text[]))) OR
        (OLD.state = 'running' AND NEW.state = 'running' AND
         NEW.lease_heartbeat_at > OLD.lease_heartbeat_at AND
         NEW.lease_until = NEW.lease_heartbeat_at + interval '60 seconds' AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'lease_heartbeat_at','lease_until','updated_at'
         ]::text[]))) OR
        (OLD.state = 'running' AND NEW.state = 'running' AND
         OLD.cancel_requested_at IS NULL AND NEW.cancel_requested_at IS NOT NULL AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'cancel_requested_at','updated_at'
         ]::text[]))) OR
        (OLD.state = 'running' AND NEW.state = 'running' AND
         OLD.effect_class = 'external' AND OLD.effect_started_at IS NULL AND
         OLD.cancel_requested_at IS NULL AND NEW.effect_started_at IS NOT NULL AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'effect_started_at','updated_at'
         ]::text[]))) OR
        (OLD.state = 'queued' AND OLD.parked_at IS NULL AND
         NEW.state = 'cancelled' AND NEW.completed_at = NEW.updated_at AND
         NEW.last_error_class = 'cancelled' AND
         NEW.retain_until >= NEW.completed_at + interval '90 days' AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at'
         ]::text[]))) OR
        (OLD.state = 'running' AND NEW.state = 'queued' AND
         NEW.last_error_class IN ('transient','conflict') AND
         NEW.run_at >= NEW.updated_at AND OLD.attempts < OLD.max_attempts AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'run_at','state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256','updated_at'
         ]::text[]))) OR
        (OLD.state = 'running' AND NEW.state = 'succeeded' AND
         NEW.completed_at = NEW.updated_at AND NEW.last_error_class IS NULL AND
         NEW.last_error_code IS NULL AND NEW.last_error_sha256 IS NULL AND
         NEW.retain_until >= NEW.completed_at + interval '90 days' AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at'
         ]::text[]))) OR
        (OLD.state = 'running' AND NEW.state = 'dead' AND
         NEW.completed_at = NEW.updated_at AND
         (NEW.last_error_class IN ('transient','permanent','conflict') OR
          (NEW.last_error_class IS NULL AND
           NEW.last_error_code = 'JOB_OUTCOME_UNKNOWN')) AND
         NEW.retain_until >= NEW.completed_at + interval '365 days' AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at'
         ]::text[]))) OR
        (OLD.state = 'running' AND NEW.state = 'cancelled' AND
         NEW.completed_at = NEW.updated_at AND NEW.last_error_class = 'cancelled' AND
         NEW.retain_until >= NEW.completed_at + interval '90 days' AND
         (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at'
         ]::text[])));
    IF v_normal THEN
        IF platform.platform_async_assert_current_authority_v1(
            OLD.scope_kind, OLD.scope_id, OLD.authority_group_id,
            OLD.authority_group_generation, OLD.authority_domain,
            OLD.cutover_generation
        ) IS NULL THEN NULL; END IF;
        IF OLD.state = 'running' AND NEW.state <> 'running' AND NOT EXISTS (
            SELECT 1 FROM platform.job_attempts AS attempt
            WHERE attempt.job_id = OLD.id AND attempt.attempt = OLD.attempts
              AND attempt.lease_generation = OLD.lease_generation
              AND attempt.lease_owner_id = OLD.lease_owner_id
              AND attempt.finished_at IS NOT NULL
              AND ((NEW.state = 'queued' AND
                    attempt.outcome IN ('requeued','lease_expired') AND
                    attempt.error_class IS NOT DISTINCT FROM NEW.last_error_class AND
                    attempt.error_code IS NOT DISTINCT FROM NEW.last_error_code AND
                    attempt.redacted_error_sha256 IS NOT DISTINCT FROM NEW.last_error_sha256) OR
                   (NEW.state = 'succeeded' AND attempt.outcome = 'succeeded') OR
                   (NEW.state = 'dead' AND attempt.outcome = 'dead' AND
                    attempt.error_class IS NOT DISTINCT FROM NEW.last_error_class AND
                    attempt.error_code IS NOT DISTINCT FROM NEW.last_error_code AND
                    attempt.redacted_error_sha256 IS NOT DISTINCT FROM NEW.last_error_sha256) OR
                   (NEW.state = 'cancelled' AND
                    (attempt.outcome = 'lease_expired' OR
                     (attempt.outcome = 'cancelled' AND
                      attempt.error_code IS NOT DISTINCT FROM NEW.last_error_code AND
                      attempt.redacted_error_sha256 IS NOT DISTINCT FROM NEW.last_error_sha256))))
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5612',
                MESSAGE = 'job transition lacks its terminal attempt';
        END IF;
        RETURN;
    END IF;
    v_owner := p_current_user = 'harpy_owner';
    IF v_owner AND OLD.state = 'running' AND NEW.state = 'queued' AND
       OLD.effect_started_at IS NULL AND NEW.parked_at = NEW.updated_at AND
       NEW.parked_code = 'JOB_AUTHORITY_STALE' AND
       NEW.parked_current_group_generation >= OLD.authority_group_generation AND
       NEW.parked_current_cutover_generation >= OLD.cutover_generation AND
       (NEW.parked_current_group_generation > OLD.authority_group_generation OR
        NEW.parked_current_cutover_generation > OLD.cutover_generation) AND
       (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'state','lease_owner_id','lease_heartbeat_at','lease_until','parked_at',
           'parked_code','parked_current_group_generation',
           'parked_current_cutover_generation','updated_at'
       ]::text[])) AND EXISTS (
           SELECT 1 FROM platform.job_attempts AS attempt
           WHERE attempt.job_id = OLD.id AND attempt.attempt = OLD.attempts
             AND attempt.lease_generation = OLD.lease_generation
             AND attempt.lease_owner_id = OLD.lease_owner_id
             AND attempt.outcome = 'lease_expired' AND attempt.finished_at IS NOT NULL
       ) THEN
        RETURN;
    END IF;
    IF v_owner AND OLD.state = 'queued' AND OLD.parked_at IS NOT NULL AND
       NEW.state = 'cancelled' AND NEW.completed_at = NEW.updated_at AND
       NEW.last_error_class = 'cancelled' AND
       NEW.retain_until >= NEW.completed_at + interval '90 days' AND
       (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'state','last_error_class','last_error_code','last_error_sha256',
           'retain_until','completed_at','updated_at'
       ]::text[])) THEN
        RETURN;
    END IF;
    IF v_owner AND OLD.state IN ('succeeded','dead','cancelled') AND
       NEW.state = OLD.state AND NEW.retention_release_revision =
           OLD.retention_release_revision + 1 AND
       NEW.retention_release_sha256 IS NOT NULL AND
       NEW.retention_released_at = NEW.updated_at AND
       NEW.retain_until >= OLD.retain_until AND
       (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'retain_until','retention_release_revision','retention_release_sha256',
           'retention_released_at','updated_at'
       ]::text[])) THEN
        RETURN;
    END IF;
    IF v_owner AND OLD.state IN ('succeeded','dead','cancelled') AND
       OLD.payload_ref IS NOT NULL AND OLD.payload_redacted_at IS NULL AND
       NEW.payload_ref IS NULL AND NEW.payload_redacted_at = NEW.updated_at AND
       NEW.updated_at >= OLD.completed_at + interval '30 days' AND
       (v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
           'payload_ref','payload_redacted_at','updated_at'
       ]::text[])) THEN
        RETURN;
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'P5613', MESSAGE = 'job transition is forbidden';
END;
$$;


ALTER FUNCTION platform.platform_async_validate_job_transition_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_job_transition_v2(platform.jobs, platform.jobs, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_job_transition_v2(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_changed jsonb;
    v_valid boolean;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM platform.cutover_job_bindings AS binding
                   WHERE binding.job_id=OLD.id) OR
       p_current_user='harpy_owner' THEN
        PERFORM platform.platform_async_validate_job_transition_v1(
            OLD,NEW,p_current_user,p_session_user);
        RETURN;
    END IF;
    IF pg_catalog.pg_trigger_depth()<>1 OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       NEW.updated_at<=OLD.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P5610',
            MESSAGE='cutover shadow job transition invocation is invalid';
    END IF;
    PERFORM platform.platform_async_assert_job_row_authority_v1(OLD);
    PERFORM platform.platform_async_assert_job_row_authority_v1(NEW);
    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key) INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    v_valid :=
        (OLD.state='queued' AND OLD.parked_at IS NULL AND NEW.state='running'
         AND NEW.attempts=OLD.attempts+1
         AND NEW.lease_generation=OLD.lease_generation+1
         AND NEW.lease_heartbeat_at>OLD.updated_at
         AND NEW.lease_until=NEW.lease_heartbeat_at+interval '60 seconds'
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','attempts','lease_generation','lease_owner_id',
             'lease_heartbeat_at','lease_until','updated_at']::text[])) OR
        (OLD.state='running' AND NEW.state='running'
         AND NEW.lease_heartbeat_at>OLD.lease_heartbeat_at
         AND NEW.lease_until=NEW.lease_heartbeat_at+interval '60 seconds'
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'lease_heartbeat_at','lease_until','updated_at']::text[])) OR
        (OLD.state='running' AND NEW.state='running'
         AND OLD.cancel_requested_at IS NULL AND NEW.cancel_requested_at IS NOT NULL
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'cancel_requested_at','updated_at']::text[])) OR
        (OLD.state='running' AND NEW.state='running'
         AND OLD.effect_class='external' AND OLD.effect_started_at IS NULL
         AND OLD.cancel_requested_at IS NULL AND NEW.effect_started_at IS NOT NULL
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'effect_started_at','updated_at']::text[])) OR
        (OLD.state='queued' AND OLD.parked_at IS NULL AND NEW.state='cancelled'
         AND NEW.completed_at=NEW.updated_at AND NEW.last_error_class='cancelled'
         AND NEW.retain_until>=NEW.completed_at+interval '90 days'
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at']::text[])) OR
        (OLD.state='running' AND NEW.state='queued'
         AND NEW.last_error_class IN ('transient','conflict')
         AND NEW.run_at>=NEW.updated_at AND OLD.attempts<OLD.max_attempts
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'run_at','state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256','updated_at']::text[])) OR
        (OLD.state='running' AND NEW.state='succeeded'
         AND NEW.completed_at=NEW.updated_at AND NEW.last_error_class IS NULL
         AND NEW.last_error_code IS NULL AND NEW.last_error_sha256 IS NULL
         AND NEW.retain_until>=NEW.completed_at+interval '90 days'
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at']::text[])) OR
        (OLD.state='running' AND NEW.state='dead' AND NEW.completed_at=NEW.updated_at
         AND (NEW.last_error_class IN ('transient','permanent','conflict') OR
              (NEW.last_error_class IS NULL
               AND NEW.last_error_code='JOB_OUTCOME_UNKNOWN'))
         AND NEW.retain_until>=NEW.completed_at+interval '365 days'
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at']::text[])) OR
        (OLD.state='running' AND NEW.state='cancelled'
         AND NEW.completed_at=NEW.updated_at AND NEW.last_error_class='cancelled'
         AND NEW.retain_until>=NEW.completed_at+interval '90 days'
         AND v_changed OPERATOR(pg_catalog.<@) pg_catalog.to_jsonb(ARRAY[
             'state','lease_owner_id','lease_heartbeat_at','lease_until',
             'last_error_class','last_error_code','last_error_sha256',
             'retain_until','completed_at','updated_at']::text[]));
    IF NOT v_valid THEN
        RAISE EXCEPTION USING ERRCODE='P5613',
            MESSAGE='cutover shadow job transition is forbidden';
    END IF;
    IF OLD.state='running' AND NEW.state<>'running' AND NOT EXISTS (
        SELECT 1 FROM platform.job_attempts AS attempt
        WHERE attempt.job_id=OLD.id AND attempt.attempt=OLD.attempts
          AND attempt.lease_generation=OLD.lease_generation
          AND attempt.lease_owner_id=OLD.lease_owner_id
          AND attempt.finished_at IS NOT NULL
          AND ((NEW.state='queued' AND attempt.outcome IN ('requeued','lease_expired')
                AND attempt.error_class IS NOT DISTINCT FROM NEW.last_error_class
                AND attempt.error_code IS NOT DISTINCT FROM NEW.last_error_code
                AND attempt.redacted_error_sha256 IS NOT DISTINCT FROM
                    NEW.last_error_sha256)
            OR (NEW.state='succeeded' AND attempt.outcome='succeeded')
            OR (NEW.state='dead' AND attempt.outcome='dead'
                AND attempt.error_class IS NOT DISTINCT FROM NEW.last_error_class
                AND attempt.error_code IS NOT DISTINCT FROM NEW.last_error_code
                AND attempt.redacted_error_sha256 IS NOT DISTINCT FROM
                    NEW.last_error_sha256)
            OR (NEW.state='cancelled' AND
                (attempt.outcome='lease_expired' OR
                 (attempt.outcome='cancelled'
                  AND attempt.error_code IS NOT DISTINCT FROM NEW.last_error_code
                  AND attempt.redacted_error_sha256 IS NOT DISTINCT FROM
                      NEW.last_error_sha256))))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P5612',
            MESSAGE='cutover shadow job transition lacks terminal attempt';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_job_transition_v2(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_owner_insert_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_owner_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       NOT (TG_TABLE_NAME OPERATOR(pg_catalog.=) ANY (
           ARRAY['jobs','outbox','idempotency_receipts','dead_letters']::text[]
       )) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5604',
            MESSAGE = 'async owner insert trigger target is invalid';
    END IF;

    IF NOT (
        (SESSION_USER OPERATOR(pg_catalog.=) 'harpy_v2_runtime' AND
            NEW.writer_origin OPERATOR(pg_catalog.=) 'v2') OR
        (SESSION_USER OPERATOR(pg_catalog.=) 'harpy_adopter' AND
            NEW.writer_origin OPERATOR(pg_catalog.=) 'v1')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5605',
            MESSAGE = 'async owner insert authority is invalid';
    END IF;

    IF platform.platform_async_assert_current_authority_v1(
        NEW.scope_kind,
        NEW.scope_id,
        NEW.authority_group_id,
        NEW.authority_group_generation,
        NEW.authority_domain,
        NEW.cutover_generation
    ) IS NULL THEN
        NULL;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_owner_insert_v1() OWNER TO harpy_owner;

--
-- Name: platform_async_validate_owner_insert_v10(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_owner_insert_v10() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_row jsonb:=pg_catalog.to_jsonb(NEW);
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'idempotency_receipts' THEN
        RAISE EXCEPTION USING ERRCODE='P5604',
            MESSAGE='async receipt insert trigger target is invalid';
    END IF;
    IF v_row->>'effect_kind' IN ('analytics.dashboard.export.delete',
                                 'analytics.dashboard.export.expire') THEN
        PERFORM platform.platform_async_route_analytics_dashboard_export_maintenance_receipt_v1(
            NEW,CURRENT_USER,SESSION_USER);
        RETURN NEW;
    END IF;
    IF SESSION_USER='harpy_v2_runtime' AND NEW.writer_origin='v2'
       AND EXISTS (SELECT 1 FROM platform.cutover_job_bindings AS binding
                   WHERE binding.job_id=(v_row->>'causation_id')::uuid) THEN
        PERFORM platform.platform_async_assert_cutover_effect_receipt_v1(NEW);
        RETURN NEW;
    END IF;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       NEW.writer_origin IS DISTINCT FROM 'v2' THEN
        RAISE EXCEPTION USING ERRCODE='P5605',
            MESSAGE='async owner insert authority is invalid';
    END IF;
    PERFORM platform.platform_async_assert_current_authority_v1(
        NEW.scope_kind,NEW.scope_id,NEW.authority_group_id,
        NEW.authority_group_generation,NEW.authority_domain,
        NEW.cutover_generation);
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_owner_insert_v10() OWNER TO harpy_owner;

--
-- Name: platform_async_validate_owner_insert_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_owner_insert_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
