ALTER FUNCTION platform.platform_async_validate_owner_insert_v9() OWNER TO harpy_owner;

--
-- Name: platform_async_validate_stale_external_attempt_unknown_v1(platform.job_attempts, platform.job_attempts, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_stale_external_attempt_unknown_v1(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.jobs%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_changed jsonb;
BEGIN
    IF pg_catalog.pg_trigger_depth() <> 1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.finished_at IS NOT NULL OR NEW.finished_at IS NULL OR
       OLD.effect_started_at IS NULL OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       NEW.effect_id IS DISTINCT FROM OLD.effect_id OR
       NEW.effect_request_sha256 IS DISTINCT FROM OLD.effect_request_sha256 OR
       NEW.outcome IS DISTINCT FROM 'dead' OR
       NEW.error_class IS NOT NULL OR
       NEW.error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       NEW.redacted_error_sha256 IS NOT NULL OR
       NEW.effect_receipt_id IS NOT NULL OR
       NEW.finished_at < OLD.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5670',
            MESSAGE = 'stale external attempt finalization is invalid';
    END IF;

    SELECT job.* INTO v_job
    FROM platform.jobs AS job
    WHERE job.id = NEW.job_id AND job.scope_kind = NEW.scope_kind
      AND job.scope_id = NEW.scope_id
    FOR SHARE;
    IF NOT FOUND OR v_job.state IS DISTINCT FROM 'running' OR
       v_job.effect_class IS DISTINCT FROM 'external' OR
       v_job.attempts IS DISTINCT FROM NEW.attempt OR
       v_job.lease_generation IS DISTINCT FROM NEW.lease_generation OR
       v_job.lease_owner_id IS DISTINCT FROM NEW.lease_owner_id OR
       v_job.effect_started_at IS DISTINCT FROM NEW.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5671',
            MESSAGE = 'stale external attempt does not match its job';
    END IF;

    SELECT generation INTO v_group_generation
    FROM platform.cutover_groups
    WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
      AND group_id = v_job.authority_group_id
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    SELECT generation INTO v_domain_generation
    FROM platform.domain_cutovers
    WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
      AND domain = v_job.authority_domain
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    IF v_group_generation IS NULL OR v_domain_generation IS NULL OR
       v_group_generation < v_job.authority_group_generation OR
       v_domain_generation < v_job.cutover_generation OR
       (v_group_generation = v_job.authority_group_generation AND
        v_domain_generation = v_job.cutover_generation) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind = v_job.scope_kind AND scope_id = v_job.scope_id
          AND group_id = v_job.authority_group_id
          AND domain = v_job.authority_domain
    ) OR EXISTS (
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.record_kind = 'effect'
          AND receipt.scope_kind = v_job.scope_kind
          AND receipt.scope_id = v_job.scope_id
          AND receipt.authority_group_id = v_job.authority_group_id
          AND receipt.authority_group_generation = v_job.authority_group_generation
          AND receipt.authority_domain = v_job.authority_domain
          AND receipt.cutover_generation = v_job.cutover_generation
          AND receipt.effect_key = v_job.effect_idempotency_key
          AND receipt.effect_id = NEW.effect_id
          AND receipt.request_sha256 = NEW.effect_request_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5672',
            MESSAGE = 'external attempt outcome is not unknown under stale authority';
    END IF;

    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF v_changed IS DISTINCT FROM pg_catalog.to_jsonb(
        ARRAY['error_code','finished_at','outcome']::text[]
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5673',
            MESSAGE = 'stale external attempt changed immutable state';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_stale_external_attempt_unknown_v1(old platform.job_attempts, new platform.job_attempts, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_stale_external_job_unknown_v1(platform.jobs, platform.jobs, name, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_stale_external_job_unknown_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_attempt platform.job_attempts%ROWTYPE;
    v_group_generation bigint;
    v_domain_generation bigint;
    v_changed jsonb;
BEGIN
    IF pg_catalog.pg_trigger_depth() <> 1 OR
       p_current_user IS DISTINCT FROM 'harpy_owner' OR
       p_session_user IS DISTINCT FROM 'harpy_v2_runtime' OR
       OLD.state IS DISTINCT FROM 'running' OR
       OLD.effect_class IS DISTINCT FROM 'external' OR
       OLD.effect_started_at IS NULL OR NEW.state IS DISTINCT FROM 'dead' OR
       NEW.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       NEW.lease_owner_id IS NOT NULL OR NEW.lease_heartbeat_at IS NOT NULL OR
       NEW.lease_until IS NOT NULL OR NEW.last_error_class IS NOT NULL OR
       NEW.last_error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       NEW.last_error_sha256 IS NOT NULL OR
       NEW.completed_at IS DISTINCT FROM NEW.updated_at OR
       NEW.updated_at <= OLD.updated_at OR
       NEW.retain_until < NEW.completed_at + interval '365 days' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5674',
            MESSAGE = 'stale external job finalization is invalid';
    END IF;

    SELECT attempt.* INTO v_attempt
    FROM platform.job_attempts AS attempt
    WHERE attempt.job_id = OLD.id AND attempt.attempt = OLD.attempts
      AND attempt.lease_generation = OLD.lease_generation
      AND attempt.lease_owner_id = OLD.lease_owner_id
    FOR SHARE;
    IF NOT FOUND OR v_attempt.finished_at IS DISTINCT FROM NEW.updated_at OR
       v_attempt.outcome IS DISTINCT FROM 'dead' OR
       v_attempt.error_class IS NOT NULL OR
       v_attempt.error_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
       v_attempt.redacted_error_sha256 IS NOT NULL OR
       v_attempt.effect_started_at IS DISTINCT FROM OLD.effect_started_at OR
       v_attempt.effect_receipt_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P5675',
            MESSAGE = 'stale external job lacks its terminal attempt';
    END IF;

    SELECT generation INTO v_group_generation
    FROM platform.cutover_groups
    WHERE scope_kind = OLD.scope_kind AND scope_id = OLD.scope_id
      AND group_id = OLD.authority_group_id
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    SELECT generation INTO v_domain_generation
    FROM platform.domain_cutovers
    WHERE scope_kind = OLD.scope_kind AND scope_id = OLD.scope_id
      AND domain = OLD.authority_domain
      AND state = 'v2' AND writer = 'v2'
    FOR SHARE;
    IF v_group_generation IS NULL OR v_domain_generation IS NULL OR
       v_group_generation < OLD.authority_group_generation OR
       v_domain_generation < OLD.cutover_generation OR
       (v_group_generation = OLD.authority_group_generation AND
        v_domain_generation = OLD.cutover_generation) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_group_members
        WHERE scope_kind = OLD.scope_kind AND scope_id = OLD.scope_id
          AND group_id = OLD.authority_group_id
          AND domain = OLD.authority_domain
    ) OR EXISTS (
        SELECT 1 FROM platform.idempotency_receipts AS receipt
        WHERE receipt.record_kind = 'effect'
          AND receipt.scope_kind = OLD.scope_kind
          AND receipt.scope_id = OLD.scope_id
          AND receipt.authority_group_id = OLD.authority_group_id
          AND receipt.authority_group_generation = OLD.authority_group_generation
          AND receipt.authority_domain = OLD.authority_domain
          AND receipt.cutover_generation = OLD.cutover_generation
          AND receipt.effect_key = OLD.effect_idempotency_key
          AND receipt.effect_id = v_attempt.effect_id
          AND receipt.request_sha256 = v_attempt.effect_request_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5676',
            MESSAGE = 'external job outcome is not unknown under stale authority';
    END IF;

    SELECT pg_catalog.jsonb_agg(changed.key ORDER BY changed.key)
    INTO v_changed
    FROM (
        SELECT old_field.key
        FROM pg_catalog.jsonb_each(pg_catalog.to_jsonb(OLD)) AS old_field
        JOIN pg_catalog.jsonb_each(pg_catalog.to_jsonb(NEW)) AS new_field USING (key)
        WHERE old_field.value IS DISTINCT FROM new_field.value
    ) AS changed;
    IF v_changed IS DISTINCT FROM pg_catalog.to_jsonb(ARRAY[
        'completed_at','last_error_code','lease_heartbeat_at','lease_owner_id',
        'lease_until','retain_until','state','updated_at'
    ]::text[]) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5677',
            MESSAGE = 'stale external job changed immutable state';
    END IF;
END;
$$;


ALTER FUNCTION platform.platform_async_validate_stale_external_job_unknown_v1(old platform.jobs, new platform.jobs, p_current_user name, p_session_user name) OWNER TO harpy_owner;

--
-- Name: platform_async_validate_stale_job_disposition_v1(platform.jobs, uuid, uuid, uuid, uuid, text, text, bigint, bigint, text, bytea, text, text, text, uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_validate_stale_job_disposition_v1(p_job platform.jobs, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_result_root_id uuid, p_result_payload_ref text, p_result_dedupe_key text, p_group_generation bigint, p_domain_generation bigint, p_action text, p_payload_canonical bytea, p_payload_sha256 text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid, p_source_run_at text, p_result_run_at text, p_occurred_at text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
    v_expected jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_root_id IS NULL OR p_action_id IS NULL OR
       p_root_id IN (p_action_id,p_job.id) OR p_action_id = p_job.id OR
       p_action NOT IN ('adopt','cancel') OR p_job.payload_ref IS NULL OR
       p_payload_canonical IS NULL OR
       pg_catalog.octet_length(p_payload_canonical) NOT BETWEEN 2 AND 65536 OR
       p_payload_sha256 !~ '^[0-9a-f]{64}$' OR
       p_payload_sha256 IS DISTINCT FROM pg_catalog.encode(
           pg_catalog.sha256(p_payload_canonical),'hex') OR
       p_reason IS NULL OR p_reason <> pg_catalog.btrim(p_reason) OR
       pg_catalog.octet_length(p_reason) NOT BETWEEN 1 AND 2048 OR
       p_ticket IS NULL OR p_ticket <> pg_catalog.btrim(p_ticket) OR
       pg_catalog.octet_length(p_ticket) NOT BETWEEN 1 AND 256 OR
       p_actor_id IS NULL OR p_causation_id IS NULL OR
       p_source_run_at IS NULL OR p_source_run_at !~ 'Z$' OR
       p_source_run_at::timestamptz <> p_job.run_at OR
       p_occurred_at IS NULL OR p_occurred_at !~ 'Z$' OR
       p_occurred_at::timestamptz <> p_now OR
       p_now IS DISTINCT FROM pg_catalog.transaction_timestamp() OR
       p_group_generation < p_job.authority_group_generation OR
       p_domain_generation < p_job.cutover_generation OR
       (p_group_generation = p_job.authority_group_generation AND
        p_domain_generation = p_job.cutover_generation) OR
       NOT ((p_action = 'adopt' AND p_result_job_id IS NOT NULL AND
             p_result_job_id <> p_job.id AND p_result_payload_ref IS NOT NULL AND
             p_result_job_id NOT IN (p_root_id,p_action_id) AND
             pg_catalog.octet_length(p_result_payload_ref) BETWEEN 1 AND 2048 AND
             p_result_dedupe_key IS NOT NULL AND
             pg_catalog.octet_length(p_result_dedupe_key) BETWEEN 1 AND 512 AND
             p_result_run_at IS NOT NULL AND p_result_run_at ~ 'Z$' AND
             p_result_run_at::timestamptz =
                 GREATEST(p_job.run_at,p_now)) OR
            (p_action = 'cancel' AND p_result_job_id IS NULL AND
             p_result_root_id IS NULL AND p_result_payload_ref IS NULL AND
             p_result_dedupe_key IS NULL AND p_result_run_at IS NULL)) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5684',
            MESSAGE = 'stale job disposition evidence input is invalid';
    END IF;
    BEGIN
        v_document := pg_catalog.convert_from(p_payload_canonical,'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE = 'P5684',
            MESSAGE = 'stale job disposition evidence payload is invalid';
    END;
    v_expected := pg_catalog.jsonb_build_object(
        'contract_version','stale-job-disposition.v1',
        'evidence_root_id',p_root_id,'disposition_id',p_action_id,
        'source_job_id',p_job.id,'decision',p_action,
        'result_job_id',p_result_job_id,
        'kind',p_job.kind,'effect_class',p_job.effect_class,
        'maximum_attempts',p_job.max_attempts,'priority',p_job.priority,
        'old_authority',pg_catalog.jsonb_build_object(
            'scope_kind',p_job.scope_kind,'scope_id',p_job.scope_id,
            'domain',p_job.authority_domain,
            'cutover_generation',p_job.cutover_generation,
            'writer_origin',p_job.writer_origin,
            'group_id',p_job.authority_group_id,
            'group_generation',p_job.authority_group_generation),
        'current_authority',pg_catalog.jsonb_build_object(
            'scope_kind',p_job.scope_kind,'scope_id',p_job.scope_id,
            'domain',p_job.authority_domain,
            'cutover_generation',p_domain_generation,'writer_origin','v2',
            'group_id',p_job.authority_group_id,
            'group_generation',p_group_generation),
        'source_payload',pg_catalog.jsonb_build_object(
            'revision',p_job.payload_revision,'sha256',p_job.payload_sha256,
            'reference',p_job.payload_ref,'dedupe_key',p_job.dedupe_key,
            'effect_idempotency_key',p_job.effect_idempotency_key),
        'result_payload',CASE WHEN p_action = 'adopt' THEN
            pg_catalog.jsonb_build_object(
                'revision',p_job.payload_revision,'sha256',p_job.payload_sha256,
                'reference',p_result_payload_ref,'dedupe_key',p_result_dedupe_key,
                'effect_idempotency_key',p_job.effect_idempotency_key)
            ELSE 'null'::jsonb END,
        'source_run_at',p_source_run_at,'result_run_at',p_result_run_at,
        'reason',p_reason,'ticket_reference',p_ticket,
        'actor_id',p_actor_id,'causation_id',p_causation_id,
        'occurred_at',p_occurred_at
    );
    IF v_document IS DISTINCT FROM v_expected THEN
        RAISE EXCEPTION USING ERRCODE = 'P5684',
            MESSAGE = 'stale job disposition evidence contract is invalid';
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'contract_version','stale-job-disposition.v1','source_job_id',p_job.id,
        'decision',p_action,'result_job_id',p_result_job_id,
        'result_root_id',p_result_root_id,'kind',p_job.kind,
        'effect_class',p_job.effect_class,'maximum_attempts',p_job.max_attempts,
        'priority',p_job.priority,'source_payload_reference',p_job.payload_ref,
        'source_payload_sha256',p_job.payload_sha256,
        'source_dedupe_key',p_job.dedupe_key,
        'effect_idempotency_key',p_job.effect_idempotency_key,
        'result_payload_reference',p_result_payload_ref,
        'result_dedupe_key',p_result_dedupe_key,
        'source_run_at',p_source_run_at,'result_run_at',p_result_run_at,
        'current_group_generation',p_group_generation,
        'current_domain_generation',p_domain_generation
    );
END;
$_$;


ALTER FUNCTION platform.platform_async_validate_stale_job_disposition_v1(p_job platform.jobs, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_result_root_id uuid, p_result_payload_ref text, p_result_dedupe_key text, p_group_generation bigint, p_domain_generation bigint, p_action text, p_payload_canonical bytea, p_payload_sha256 text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid, p_source_run_at text, p_result_run_at text, p_occurred_at text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_async_verify_stale_job_disposition_replay_v1(platform.jobs, uuid, uuid, uuid, bigint, bigint, text, text, text, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_async_verify_stale_job_disposition_replay_v1(p_job platform.jobs, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_group_generation bigint, p_domain_generation bigint, p_action text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid) RETURNS TABLE(recorded_at timestamp with time zone, result_root_id uuid, result_payload_ref text, result_dedupe_key text, result_run_at text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_root platform.dead_letters%ROWTYPE;
    v_envelope jsonb;
    v_result platform.jobs%ROWTYPE;
    v_result_root_text text;
    v_result_run_at text;
    v_code text;
    v_error_sha256 text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_job.state <> 'cancelled' OR p_root_id IS NULL OR p_action_id IS NULL OR
       p_action NOT IN ('adopt','cancel') OR
       NOT ((p_action = 'adopt' AND p_result_job_id IS NOT NULL) OR
            (p_action = 'cancel' AND p_result_job_id IS NULL)) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5689',
            MESSAGE = 'stale job disposition replay conflicts';
    END IF;
    SELECT root.* INTO v_root FROM platform.dead_letters AS root
    WHERE root.id = p_root_id AND root.root_id = root.id
      AND root.entry_sequence = 0 AND root.record_kind = 'root'
      AND root.source_kind = 'job' AND root.source_id = p_job.id
      AND ROW(root.tenant_id,root.scope_kind,root.scope_id,
          root.authority_group_id,root.authority_group_generation,
          root.authority_domain,root.cutover_generation,root.writer_origin,
          root.source_contract,root.source_version,root.source_sha256,
          root.reason_class,root.reason_code)
          IS NOT DISTINCT FROM ROW(p_job.tenant_id,p_job.scope_kind,p_job.scope_id,
          p_job.authority_group_id,p_group_generation,p_job.authority_domain,
          p_domain_generation,'v2',p_job.kind,p_job.payload_revision,
          p_job.payload_sha256,'stale_generation','JOB_AUTHORITY_STALE');
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM platform.dead_letters AS action
        WHERE action.id = p_action_id AND action.root_id = v_root.id
          AND action.entry_sequence = 1 AND action.record_kind = 'repair_action'
          AND action.action_reason = p_reason AND action.action_ticket = p_ticket
          AND action.action_actor_id = p_actor_id
          AND action.action_causation_id = p_causation_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5689',
            MESSAGE = 'stale job disposition replay evidence conflicts';
    END IF;
    v_envelope := v_root.redacted_envelope;
    IF NOT v_envelope @> pg_catalog.jsonb_build_object(
        'contract_version','stale-job-disposition.v1',
        'source_job_id',p_job.id,'decision',p_action,
        'result_job_id',p_result_job_id,'kind',p_job.kind,
        'effect_class',p_job.effect_class,
        'maximum_attempts',p_job.max_attempts,'priority',p_job.priority,
        'source_payload_sha256',p_job.payload_sha256,
        'source_dedupe_key',p_job.dedupe_key,
        'effect_idempotency_key',p_job.effect_idempotency_key,
        'current_group_generation',p_group_generation,
        'current_domain_generation',p_domain_generation
    ) OR v_envelope->>'source_run_at' IS NULL OR
        v_envelope->>'source_run_at' !~ 'Z$' OR
        (v_envelope->>'source_run_at')::timestamptz <> p_job.run_at OR
        (p_job.payload_ref IS NOT NULL AND
         v_envelope->>'source_payload_reference' <> p_job.payload_ref) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5689',
            MESSAGE = 'stale job disposition replay envelope conflicts';
    END IF;
    v_code := CASE p_action WHEN 'adopt' THEN
        'JOB_AUTHORITY_STALE_ADOPTED' ELSE 'JOB_AUTHORITY_STALE_CANCELLED' END;
    v_error_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        v_code || E'\n' || p_reason || E'\n' || p_ticket,'UTF8')),'hex');
    IF p_job.last_error_code IS DISTINCT FROM v_code OR
       p_job.last_error_sha256 IS DISTINCT FROM v_error_sha256 OR
       p_job.completed_at IS DISTINCT FROM v_root.recorded_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5689',
            MESSAGE = 'stale job disposition replay outcome conflicts';
    END IF;
    IF p_action = 'cancel' THEN
        RETURN QUERY SELECT v_root.recorded_at,NULL::uuid,NULL::text,
            NULL::text,NULL::text;
        RETURN;
    END IF;
    v_result_root_text := v_envelope->>'result_root_id';
    v_result_run_at := v_envelope->>'result_run_at';
    IF v_envelope->>'result_payload_reference' IS NULL OR
       v_envelope->>'result_dedupe_key' IS NULL OR
       v_result_run_at IS NULL OR v_result_run_at !~ 'Z$' OR
       (v_result_root_text IS NOT NULL AND v_result_root_text !~
           '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') THEN
        RAISE EXCEPTION USING ERRCODE = 'P5689',
            MESSAGE = 'stale job adoption replay envelope conflicts';
    END IF;
    SELECT result.* INTO v_result FROM platform.jobs AS result
    WHERE ROW(result.id,result.tenant_id,result.scope_kind,result.scope_id,
        result.authority_group_id,result.authority_group_generation,
        result.authority_domain,result.cutover_generation,result.writer_origin,
        result.kind,result.payload_revision,result.payload_sha256,
        result.dedupe_key,result.effect_class,result.effect_idempotency_key,
        result.priority,result.run_at,result.max_attempts,result.retry_of_job_id,
        result.created_at) IS NOT DISTINCT FROM ROW(p_result_job_id,p_job.tenant_id,
        p_job.scope_kind,p_job.scope_id,p_job.authority_group_id,
        p_group_generation,p_job.authority_domain,p_domain_generation,'v2',
        p_job.kind,p_job.payload_revision,p_job.payload_sha256,
        v_envelope->>'result_dedupe_key',p_job.effect_class,
        p_job.effect_idempotency_key,p_job.priority,
        v_result_run_at::timestamptz,p_job.max_attempts,p_job.id,
        v_root.recorded_at)
      AND (result.payload_ref = v_envelope->>'result_payload_reference' OR
           (result.payload_ref IS NULL AND result.payload_redacted_at IS NOT NULL));
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5689',
            MESSAGE = 'stale job adoption replay conflicts';
    END IF;
    RETURN QUERY SELECT v_root.recorded_at,v_result_root_text::uuid,
        v_envelope->>'result_payload_reference',
        v_envelope->>'result_dedupe_key',v_result_run_at;
END;
$_$;


ALTER FUNCTION platform.platform_async_verify_stale_job_disposition_replay_v1(p_job platform.jobs, p_root_id uuid, p_action_id uuid, p_result_job_id uuid, p_group_generation bigint, p_domain_generation bigint, p_action text, p_reason text, p_ticket text, p_actor_id uuid, p_causation_id uuid) OWNER TO harpy_owner;

--
-- Name: platform_cutover_complete_v1_adoption_v1(uuid, uuid, text, bigint, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_cutover_complete_v1_adoption_v1(p_operation_id uuid, p_environment_id uuid, p_frontend_sha256 text, p_legacy_boolean_hits bigint, p_module_migration_hits bigint, p_zero_hit_since timestamp with time zone, p_completed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_plan platform.platform_cutover_v1_adoption_plans%ROWTYPE;
    v_existing platform.platform_cutover_v1_adoption_completion_receipts%ROWTYPE;
    v_tenant_count integer;
    v_billing_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            !~ '^harpy-cutover/[0-9a-f-]{36}$'
       OR p_frontend_sha256 !~ '^[0-9a-f]{64}$'
       OR p_legacy_boolean_hits<>0 OR p_module_migration_hits<>0
       OR NOT pg_catalog.isfinite(p_zero_hit_since)
       OR NOT pg_catalog.isfinite(p_completed_at)
       OR p_zero_hit_since>p_completed_at-interval '30 days' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='V1 adoption completion denied';
    END IF;
    SELECT * INTO v_existing
      FROM platform.platform_cutover_v1_adoption_completion_receipts
     WHERE operation_id=p_operation_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.frontend_contract_sha256 IS DISTINCT FROM p_frontend_sha256
           OR v_existing.zero_hit_since IS DISTINCT FROM p_zero_hit_since
           OR v_existing.completed_at IS DISTINCT FROM p_completed_at THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='V1 adoption completion replay conflicts';
        END IF;
        RETURN true;
    END IF;
    SELECT * INTO v_plan FROM platform.platform_cutover_v1_adoption_plans
     WHERE operation_id=p_operation_id AND environment_id=p_environment_id
       AND decision='ready' FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='ready V1 adoption plan is missing';
    END IF;
    SELECT receipt.adopted_tenant_count INTO v_tenant_count
      FROM platform.tenancy_v1_adoption_receipts AS receipt
     WHERE receipt.operation_id=p_operation_id AND receipt.environment_id=p_environment_id
       AND receipt.primary_tenant_id=v_plan.primary_tenant_id
       AND pg_catalog.encode(receipt.plan_sha256,'hex')=v_plan.plan_sha256 FOR SHARE;
    IF v_tenant_count IS NULL OR NOT EXISTS (
        SELECT 1 FROM platform.iam_v1_protected_authority_adoption_receipts AS receipt
         WHERE receipt.operation_id=p_operation_id AND receipt.environment_id=p_environment_id
           AND receipt.primary_tenant_id=v_plan.primary_tenant_id
           AND receipt.user_id=v_plan.owner_user_id
           AND pg_catalog.encode(receipt.plan_sha256,'hex')=v_plan.plan_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 tenancy or IAM adoption evidence is incomplete';
    END IF;
    SELECT pg_catalog.count(*)::integer INTO v_billing_count
      FROM platform.billing_v1_base_adoption_receipts AS receipt
     WHERE receipt.operation_id=p_operation_id AND receipt.environment_id=p_environment_id
       AND receipt.plan_sha256=v_plan.plan_sha256;
    IF v_billing_count IS DISTINCT FROM v_tenant_count THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 Billing adoption evidence is incomplete';
    END IF;
    INSERT INTO platform.platform_cutover_v1_adoption_completion_receipts(
        operation_id,environment_id,plan_sha256,frontend_contract_sha256,
        legacy_boolean_hits,module_migration_hits,
        zero_hit_since,completed_at,recorded_by
    ) VALUES (p_operation_id,p_environment_id,v_plan.plan_sha256,p_frontend_sha256,
        0,0,p_zero_hit_since,p_completed_at,SESSION_USER);
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.platform_cutover_complete_v1_adoption_v1(p_operation_id uuid, p_environment_id uuid, p_frontend_sha256 text, p_legacy_boolean_hits bigint, p_module_migration_hits bigint, p_zero_hit_since timestamp with time zone, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_cutover_guard_v2_async_adoption_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_cutover_guard_v2_async_adoption_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run_id uuid;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       TG_TABLE_SCHEMA IS DISTINCT FROM 'platform' OR
       TG_TABLE_NAME IS DISTINCT FROM 'domain_cutovers' THEN
        RAISE EXCEPTION USING ERRCODE = 'P5665',
            MESSAGE = 'async V2 switch guard target is invalid';
    END IF;
    IF NOT (OLD.state IS DISTINCT FROM 'v2' AND
            NEW.state OPERATOR(pg_catalog.=) 'v2') THEN
        RETURN NEW;
    END IF;
    IF OLD.state IS DISTINCT FROM 'quiescing' OR OLD.writer IS DISTINCT FROM 'none' OR
       NEW.writer IS DISTINCT FROM 'v2' OR
       NEW.generation IS DISTINCT FROM OLD.generation + 1 OR
       NEW.acceptance_digest IS NULL OR NEW.changed_at <= OLD.changed_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P5666',
            MESSAGE = 'async V2 switch transition is invalid';
    END IF;
    SELECT run.run_id INTO v_run_id
    FROM platform.async_v1_adoption_runs AS run
    JOIN platform.async_v1_zero_inventory_receipts AS zero_receipt USING (run_id)
    WHERE run.scope_kind OPERATOR(pg_catalog.=) OLD.scope_kind
      AND run.scope_id OPERATOR(pg_catalog.=) OLD.scope_id
      AND run.domain OPERATOR(pg_catalog.=) OLD.domain
      AND run.source_generation OPERATOR(pg_catalog.=) OLD.generation
      AND run.target_generation OPERATOR(pg_catalog.=) NEW.generation
      AND run.state OPERATOR(pg_catalog.=) 'accepted'
      AND run.accepted_at <= NEW.changed_at
      AND run.acceptance_sha256 IS NOT NULL
      AND NEW.acceptance_digest OPERATOR(pg_catalog.=) run.acceptance_sha256
      AND zero_receipt.inventory_sha256 OPERATOR(pg_catalog.=) run.inventory_sha256
      AND zero_receipt.queue_count OPERATOR(pg_catalog.=) 0
      AND zero_receipt.timer_count OPERATOR(pg_catalog.=) 0
      AND zero_receipt.future_count OPERATOR(pg_catalog.=) 0
      AND zero_receipt.running_count OPERATOR(pg_catalog.=) 0
    FOR SHARE OF run, zero_receipt;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5667',
            MESSAGE = 'V2 switch requires accepted zero V1 async inventory';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_cutover_guard_v2_async_adoption_v1() OWNER TO harpy_owner;

--
-- Name: platform_cutover_record_v1_adoption_plan_v1(uuid, uuid, text, text, uuid, uuid, text, text, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_cutover_record_v1_adoption_plan_v1(p_operation_id uuid, p_environment_id uuid, p_deployment_mode text, p_decision text, p_primary_tenant_id uuid, p_owner_user_id uuid, p_inventory_sha256 text, p_plan_sha256 text, p_issue_codes jsonb, p_plan_document jsonb, p_recorded_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.platform_cutover_v1_adoption_plans%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            !~ '^harpy-cutover/[0-9a-f-]{36}$'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_deployment_mode NOT IN ('onpremise','saas')
       OR p_decision NOT IN ('ready','fenced')
       OR p_inventory_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.jsonb_typeof(p_issue_codes)<>'array'
       OR pg_catalog.jsonb_typeof(p_plan_document)<>'object'
       OR NOT pg_catalog.isfinite(p_recorded_at)
       OR (p_decision='ready' AND (p_primary_tenant_id IS NULL OR p_owner_user_id IS NULL
            OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
            OR pg_catalog.jsonb_array_length(p_issue_codes)<>0))
       OR (p_decision='fenced' AND pg_catalog.jsonb_array_length(p_issue_codes)=0) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='V1 adoption plan denied';
    END IF;
    SELECT * INTO v_existing FROM platform.platform_cutover_v1_adoption_plans
     WHERE operation_id=p_operation_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.deployment_mode IS DISTINCT FROM p_deployment_mode
           OR v_existing.decision IS DISTINCT FROM p_decision
           OR v_existing.primary_tenant_id IS DISTINCT FROM p_primary_tenant_id
           OR v_existing.owner_user_id IS DISTINCT FROM p_owner_user_id
           OR v_existing.inventory_sha256 IS DISTINCT FROM p_inventory_sha256
           OR v_existing.plan_sha256 IS DISTINCT FROM p_plan_sha256
           OR v_existing.issue_codes IS DISTINCT FROM p_issue_codes
           OR v_existing.plan_document IS DISTINCT FROM p_plan_document
           OR v_existing.recorded_at IS DISTINCT FROM p_recorded_at THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='V1 adoption plan replay conflicts';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.platform_cutover_v1_adoption_plans(
        operation_id,environment_id,deployment_mode,decision,primary_tenant_id,
        owner_user_id,inventory_sha256,plan_sha256,issue_codes,plan_document,
        recorded_at,recorded_by
    ) VALUES (p_operation_id,p_environment_id,p_deployment_mode,p_decision,
        p_primary_tenant_id,p_owner_user_id,p_inventory_sha256,p_plan_sha256,
        p_issue_codes,p_plan_document,p_recorded_at,SESSION_USER);
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.platform_cutover_record_v1_adoption_plan_v1(p_operation_id uuid, p_environment_id uuid, p_deployment_mode text, p_decision text, p_primary_tenant_id uuid, p_owner_user_id uuid, p_inventory_sha256 text, p_plan_sha256 text, p_issue_codes jsonb, p_plan_document jsonb, p_recorded_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platform_migrator_assert_schema_submission_v1(name, uuid, uuid, text, uuid, bigint, text, text, integer, bytea, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_assert_schema_submission_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_plan jsonb;
    v_allowed jsonb;
    v_operation text;
    v_previous text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS NULL
       OR p_scope_schema::text !~ '^[a-z][a-z0-9_]{0,62}$'
       OR pg_catalog.uuid_extract_version(p_tenant_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_resource_id) IS DISTINCT FROM 7
       OR p_resource_kind NOT IN ('form_storage', 'form_purge')
       OR p_resource_revision NOT BETWEEN 1 AND 9007199254740991
       OR p_plan_contract_version <> 'forms-schema-plan.v1'
       OR p_compiler_version <> '1.0.0'
       OR p_postgresql_major <> 18
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
       OR p_canonical_plan_bytes IS NULL
       OR pg_catalog.octet_length(p_canonical_plan_bytes) NOT BETWEEN 2 AND 1048576
       OR pg_catalog.jsonb_typeof(p_canonical_steps) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'schema submission identity is invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(p_canonical_steps) NOT BETWEEN 1 AND 2000
       OR pg_catalog.octet_length(p_canonical_steps::text) > 4194304
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_canonical_steps) AS encoded(value)
            WHERE pg_catalog.jsonb_typeof(encoded.value) <> 'string'
               OR encoded.value #>> '{}' !~ '^([0-9a-f]{2})+$'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'schema submission step transport is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.tenants AS tenant
        WHERE tenant.id = p_tenant_id
          AND tenant.schema_name = p_scope_schema::text
          AND tenant.deleted_at IS NULL
          AND tenant.status IN ('ACTIVE', 'TRIAL')
        FOR SHARE
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'schema submission TenantScope is invalid';
    END IF;
    PERFORM platform.billing_resolve_current_tenant_authority_v1(p_tenant_id);
    IF pg_catalog.encode(
        pg_catalog.sha256(p_canonical_plan_bytes), 'hex'
    ) IS DISTINCT FROM p_plan_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'schema submission plan digest differs';
    END IF;
    BEGIN
        v_plan := pg_catalog.convert_from(p_canonical_plan_bytes, 'UTF8')::jsonb;
    EXCEPTION
        WHEN character_not_in_repertoire OR invalid_text_representation THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'schema submission plan document is invalid';
    END;
    IF pg_catalog.jsonb_typeof(v_plan) <> 'object'
       OR (SELECT pg_catalog.count(*) FROM
            pg_catalog.jsonb_object_keys(v_plan)) <> 7
       OR NOT (v_plan ?& ARRAY[
            'contract_version', 'tenant_id', 'owner', 'resource', 'compiler',
            'allowed_operations', 'steps'
       ])
       OR v_plan->>'contract_version' IS DISTINCT FROM p_plan_contract_version
       OR v_plan->>'tenant_id' IS DISTINCT FROM p_tenant_id::text
       OR v_plan->>'owner' IS DISTINCT FROM 'forms'
       OR pg_catalog.jsonb_typeof(v_plan->'resource') <> 'object'
       OR pg_catalog.jsonb_typeof(v_plan->'compiler') <> 'object'
       OR pg_catalog.jsonb_typeof(v_plan->'allowed_operations') <> 'array'
       OR pg_catalog.jsonb_typeof(v_plan->'steps') <> 'array'
       OR v_plan::text ~*
            '"(sql|raw_sql|function_body|routine_body|client_identifier)"[[:space:]]*:'
       THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'schema submission plan shape differs';
    END IF;
    IF (SELECT pg_catalog.count(*) FROM
            pg_catalog.jsonb_object_keys(v_plan->'resource')) <> 3
       OR NOT ((v_plan->'resource') ?& ARRAY['kind', 'id', 'revision'])
       OR v_plan->'resource'->>'kind' IS DISTINCT FROM p_resource_kind
       OR v_plan->'resource'->>'id' IS DISTINCT FROM p_resource_id::text
       OR (v_plan->'resource'->>'revision')::bigint
            IS DISTINCT FROM p_resource_revision
       OR (SELECT pg_catalog.count(*) FROM
            pg_catalog.jsonb_object_keys(v_plan->'compiler')) <> 2
       OR NOT ((v_plan->'compiler') ?& ARRAY['version', 'postgresql_major'])
       OR v_plan->'compiler'->>'version' IS DISTINCT FROM p_compiler_version
       OR (v_plan->'compiler'->>'postgresql_major')::integer
            IS DISTINCT FROM p_postgresql_major
       OR pg_catalog.jsonb_array_length(v_plan->'steps')
            IS DISTINCT FROM pg_catalog.jsonb_array_length(p_canonical_steps)
       OR v_plan->'steps'->0->>'executor_kind' IS DISTINCT FROM 'migrator' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'schema submission resource contract differs';
    END IF;
    v_allowed := v_plan->'allowed_operations';
    IF pg_catalog.jsonb_array_length(v_allowed) NOT BETWEEN 1 AND 20 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'schema submission operation allowlist is invalid';
    END IF;
    FOR v_operation IN
        SELECT allowed.value
        FROM pg_catalog.jsonb_array_elements_text(v_allowed)
            WITH ORDINALITY AS allowed(value, ordinal)
        ORDER BY allowed.ordinal
    LOOP
        IF v_operation NOT IN (
            'activate_generation', 'add_constraint', 'add_field_column',
            'add_relation_table', 'backfill_field_batch', 'cleanup_invalid_index',
            'create_form_table', 'create_index', 'create_index_concurrently',
            'disable_old_writer', 'drop_constraint', 'drop_field_column',
            'drop_form_table', 'drop_index', 'drop_index_concurrently',
            'drop_relation_table', 'enable_dual_write', 'retain_generation',
            'validate_constraint', 'verify_storage'
        ) OR (v_previous IS NOT NULL AND v_previous >= v_operation) THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'schema submission operation allowlist differs';
        END IF;
        v_previous := v_operation;
    END LOOP;
    RETURN v_plan;
END;
$_$;


ALTER FUNCTION platform.platform_migrator_assert_schema_submission_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) OWNER TO harpy_owner;

--
-- Name: platform_migrator_assert_schema_submission_v2(name, uuid, uuid, text, uuid, bigint, text, text, integer, bytea, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_assert_schema_submission_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_plan jsonb;
    v_allowed jsonb;
    v_operation text;
    v_previous text;
    v_last integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS NULL
       OR p_scope_schema::text !~ '^[a-z][a-z0-9_]{0,62}$'
       OR pg_catalog.uuid_extract_version(p_tenant_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_resource_id) IS DISTINCT FROM 7
       OR p_resource_kind NOT IN ('form_storage','form_purge')
       OR p_resource_revision NOT BETWEEN 1 AND 9007199254740991
       OR p_plan_contract_version IS DISTINCT FROM 'forms-schema-plan.v2'
       OR p_compiler_version IS DISTINCT FROM '2.0.0'
       OR p_postgresql_major IS DISTINCT FROM 18
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(p_canonical_plan_bytes) NOT BETWEEN 2 AND 1048576
       OR pg_catalog.jsonb_typeof(p_canonical_steps) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission identity is invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(p_canonical_steps) NOT BETWEEN 1 AND 2000
       OR pg_catalog.octet_length(p_canonical_steps::text)>4194304
       OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_array_elements(p_canonical_steps) encoded(value)
            WHERE pg_catalog.jsonb_typeof(encoded.value)<>'string'
               OR encoded.value#>>'{}' !~ '^([0-9a-f]{2})+$'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission step transport is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.tenants tenant
        WHERE tenant.id=p_tenant_id AND tenant.schema_name=p_scope_schema::text
          AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE','TRIAL')
        FOR SHARE
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='schema V2 submission TenantScope is invalid';
    END IF;
    IF pg_catalog.encode(pg_catalog.sha256(p_canonical_plan_bytes),'hex')
            IS DISTINCT FROM p_plan_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission plan digest differs';
    END IF;
    BEGIN
        v_plan := pg_catalog.convert_from(p_canonical_plan_bytes,'UTF8')::jsonb;
    EXCEPTION WHEN character_not_in_repertoire OR invalid_text_representation THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission plan document is invalid';
    END;
    IF pg_catalog.jsonb_typeof(v_plan)<>'object'
       OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_plan))<>7
       OR NOT (v_plan ?& ARRAY['contract_version','tenant_id','owner','resource',
            'compiler','allowed_operations','steps'])
       OR v_plan->>'contract_version' IS DISTINCT FROM p_plan_contract_version
       OR v_plan->>'tenant_id' IS DISTINCT FROM p_tenant_id::text
       OR v_plan->>'owner' IS DISTINCT FROM 'forms'
       OR pg_catalog.jsonb_typeof(v_plan->'resource')<>'object'
       OR pg_catalog.jsonb_typeof(v_plan->'compiler')<>'object'
       OR pg_catalog.jsonb_typeof(v_plan->'allowed_operations')<>'array'
       OR pg_catalog.jsonb_typeof(v_plan->'steps')<>'array'
       OR v_plan::text ~*
            '"(sql|raw_sql|function_body|routine_body|client_identifier)"[[:space:]]*:' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission plan shape differs';
    END IF;
    v_last := pg_catalog.jsonb_array_length(v_plan->'steps')-1;
    IF (SELECT pg_catalog.count(*) FROM
            pg_catalog.jsonb_object_keys(v_plan->'resource'))<>3
       OR NOT ((v_plan->'resource') ?& ARRAY['kind','id','revision'])
       OR v_plan#>>'{resource,kind}' IS DISTINCT FROM p_resource_kind
       OR v_plan#>>'{resource,id}' IS DISTINCT FROM p_resource_id::text
       OR (v_plan#>>'{resource,revision}')::bigint IS DISTINCT FROM p_resource_revision
       OR (SELECT pg_catalog.count(*) FROM
            pg_catalog.jsonb_object_keys(v_plan->'compiler'))<>2
       OR NOT ((v_plan->'compiler') ?& ARRAY['version','postgresql_major'])
       OR v_plan#>>'{compiler,version}' IS DISTINCT FROM p_compiler_version
       OR (v_plan#>>'{compiler,postgresql_major}')::integer
            IS DISTINCT FROM p_postgresql_major
       OR pg_catalog.jsonb_array_length(v_plan->'steps')
            IS DISTINCT FROM pg_catalog.jsonb_array_length(p_canonical_steps)
       OR v_plan->'steps'->0->>'executor_kind' IS DISTINCT FROM 'migrator'
       OR (p_resource_kind='form_storage' AND
           v_plan->'steps'->v_last->>'operation_id' IS DISTINCT FROM 'verify_storage')
       OR (p_resource_kind='form_purge' AND
           v_plan->'steps'->v_last->>'operation_id' IS DISTINCT FROM 'drop_form_table')
       OR v_plan->'steps'->v_last->>'executor_kind' IS DISTINCT FROM 'migrator' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission resource contract differs';
    END IF;
    v_allowed := v_plan->'allowed_operations';
    IF pg_catalog.jsonb_array_length(v_allowed) NOT BETWEEN 1 AND 21 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission allowlist is invalid';
    END IF;
    FOR v_operation IN
        SELECT allowed.value FROM pg_catalog.jsonb_array_elements_text(v_allowed)
             WITH ORDINALITY allowed(value,ordinal) ORDER BY allowed.ordinal
    LOOP
        IF v_operation NOT IN (
            'activate_generation','add_constraint','add_field_column',
            'add_relation_table','backfill_field_batch','cleanup_invalid_index',
            'create_form_table','create_index','create_index_concurrently',
            'disable_old_writer','drop_constraint','drop_field_column',
            'drop_form_table','drop_index','drop_index_concurrently',
            'drop_relation_table','enable_dual_write','retain_generation',
            'set_field_not_null','validate_constraint','verify_storage'
        ) OR (v_previous IS NOT NULL AND v_previous>=v_operation) THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='schema V2 submission allowlist differs';
        END IF;
        v_previous := v_operation;
    END LOOP;
    RETURN v_plan;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='schema V2 submission typed value is invalid';
END;
$_$;


ALTER FUNCTION platform.platform_migrator_assert_schema_submission_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) OWNER TO harpy_owner;

--
-- Name: platform_migrator_guard_schema_submission_identity_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_guard_schema_submission_identity_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF ROW(
        NEW.canonical_plan_bytes,NEW.submission_authority_id,
        NEW.submission_authority_group_id,NEW.submission_group_generation,
        NEW.submission_billing_generation,NEW.submission_forms_generation
    ) IS DISTINCT FROM ROW(
        OLD.canonical_plan_bytes,OLD.submission_authority_id,
        OLD.submission_authority_group_id,OLD.submission_group_generation,
        OLD.submission_billing_generation,OLD.submission_forms_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='schema submission authority identity is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_guard_schema_submission_identity_v2() OWNER TO harpy_owner;

--
-- Name: platform_migrator_reject_mutation(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_reject_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING
        ERRCODE = '55000',
        MESSAGE = 'harpy immutable foundation evidence cannot be mutated';
END;
$$;


ALTER FUNCTION platform.platform_migrator_reject_mutation() OWNER TO harpy_owner;

--
-- Name: platform_migrator_replay_schema_submission_v1(uuid, text, uuid, bigint, text, text, jsonb, bytea, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_replay_schema_submission_v1(p_tenant_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_plan jsonb, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) RETURNS TABLE(job_id uuid, generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.schema_jobs%ROWTYPE;
    v_row platform.schema_job_steps%ROWTYPE;
    v_step jsonb;
    v_index integer;
    v_step_sha256 text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'schema submission replay role is invalid';
    END IF;
    SELECT candidate.* INTO v_job
    FROM platform.schema_jobs AS candidate
    WHERE candidate.tenant_id = p_tenant_id
      AND candidate.plan_sha256 = p_plan_sha256
    FOR SHARE;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF v_job.resource_kind IS DISTINCT FROM p_resource_kind
       OR v_job.resource_id IS DISTINCT FROM p_resource_id
       OR v_job.resource_revision IS DISTINCT FROM p_resource_revision
       OR v_job.plan_contract_version IS DISTINCT FROM p_plan_contract_version
       OR v_job.compiler_version IS DISTINCT FROM p_compiler_version
       OR v_job.canonical_plan IS DISTINCT FROM p_plan
       OR (
            v_job.canonical_plan_bytes IS NOT NULL
            AND v_job.canonical_plan_bytes IS DISTINCT FROM p_canonical_plan_bytes
       )
       OR v_job.step_count IS DISTINCT FROM pg_catalog.jsonb_array_length(p_canonical_steps)
       THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'schema submission replay evidence differs';
    END IF;
    FOR v_index IN 0..v_job.step_count - 1 LOOP
        v_step := platform.platform_migrator_validate_submission_step_v1(
            p_plan_sha256,
            p_resource_kind,
            pg_catalog.decode(p_canonical_steps->>v_index, 'hex'),
            v_index,
            p_plan->'allowed_operations'
        );
        SELECT candidate.* INTO v_row
        FROM platform.schema_job_steps AS candidate
        WHERE candidate.job_id = v_job.job_id
          AND candidate.ordinal = v_index;
        v_step_sha256 := pg_catalog.encode(
            pg_catalog.sha256(pg_catalog.decode(p_canonical_steps->>v_index, 'hex')), 'hex'
        );
        IF NOT FOUND
           OR v_row.plan_sha256 IS DISTINCT FROM p_plan_sha256
           OR v_row.operation_id IS DISTINCT FROM v_step->>'operation_id'
           OR v_row.transaction_class IS DISTINCT FROM v_step->>'transaction_class'
           OR v_row.executor_kind IS DISTINCT FROM v_step->>'executor_kind'
           OR v_row.identifier_mapping IS DISTINCT FROM v_step->'identifier_mapping'
           OR v_row.arguments IS DISTINCT FROM v_step->'arguments'
           OR v_row.step_sha256 IS DISTINCT FROM v_step_sha256
           OR (
                v_row.canonical_step_bytes IS NOT NULL
                AND v_row.canonical_step_bytes
                    IS DISTINCT FROM pg_catalog.decode(p_canonical_steps->>v_index, 'hex')
           )
           THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'schema submission replay step differs';
        END IF;
    END LOOP;
    job_id := v_job.job_id;
    generation := v_job.generation;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_migrator_replay_schema_submission_v1(p_tenant_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_plan jsonb, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) OWNER TO harpy_owner;

--
-- Name: platform_migrator_replay_schema_submission_v2(uuid, text, uuid, bigint, text, text, jsonb, bytea, text, jsonb, uuid, text, bigint, bigint, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_replay_schema_submission_v2(p_tenant_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_plan jsonb, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb, p_authority_id uuid, p_authority_group_id text, p_group_generation bigint, p_billing_generation bigint, p_forms_generation bigint) RETURNS TABLE(job_id uuid, generation bigint, job_state text, terminal boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_job platform.schema_jobs%ROWTYPE;
    v_row platform.schema_job_steps%ROWTYPE;
    v_step jsonb;
    v_index integer;
    v_step_bytes bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='schema V2 replay authority is invalid';
    END IF;
    SELECT candidate.* INTO v_job
    FROM platform.schema_jobs candidate
    WHERE candidate.tenant_id=p_tenant_id
      AND candidate.plan_sha256=p_plan_sha256
    FOR SHARE;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF v_job.resource_kind IS DISTINCT FROM p_resource_kind
       OR v_job.resource_id IS DISTINCT FROM p_resource_id
       OR v_job.resource_revision IS DISTINCT FROM p_resource_revision
       OR v_job.plan_contract_version IS DISTINCT FROM p_plan_contract_version
       OR v_job.compiler_version IS DISTINCT FROM p_compiler_version
       OR v_job.canonical_plan IS DISTINCT FROM p_plan
       OR v_job.canonical_plan_bytes IS DISTINCT FROM p_canonical_plan_bytes
       OR v_job.step_count IS DISTINCT FROM pg_catalog.jsonb_array_length(p_canonical_steps)
       OR v_job.submission_authority_id IS DISTINCT FROM p_authority_id
       OR v_job.submission_authority_group_id IS DISTINCT FROM p_authority_group_id
       OR v_job.submission_group_generation IS DISTINCT FROM p_group_generation
       OR v_job.submission_billing_generation IS DISTINCT FROM p_billing_generation
       OR v_job.submission_forms_generation IS DISTINCT FROM p_forms_generation THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='schema V2 submission replay evidence differs';
    END IF;
    FOR v_index IN 0..v_job.step_count-1 LOOP
        v_step_bytes := pg_catalog.decode(p_canonical_steps->>v_index,'hex');
        v_step := platform.platform_migrator_validate_submission_step_v2(
            p_plan_sha256,p_resource_kind,v_step_bytes,v_index,
            p_plan->'allowed_operations'
        );
        SELECT candidate.* INTO v_row
        FROM platform.schema_job_steps candidate
        WHERE candidate.job_id=v_job.job_id AND candidate.ordinal=v_index;
        IF NOT FOUND
           OR v_row.plan_sha256 IS DISTINCT FROM p_plan_sha256
           OR v_row.operation_id IS DISTINCT FROM v_step->>'operation_id'
           OR v_row.transaction_class IS DISTINCT FROM v_step->>'transaction_class'
           OR v_row.executor_kind IS DISTINCT FROM v_step->>'executor_kind'
           OR v_row.identifier_mapping IS DISTINCT FROM v_step->'identifier_mapping'
           OR v_row.arguments IS DISTINCT FROM v_step->'arguments'
           OR v_row.step_sha256 IS DISTINCT FROM pg_catalog.encode(
                pg_catalog.sha256(v_step_bytes),'hex')
           OR v_row.canonical_step_bytes IS DISTINCT FROM v_step_bytes THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='schema V2 submission replay step differs';
        END IF;
    END LOOP;
    job_id := v_job.job_id;
    generation := v_job.generation;
    job_state := v_job.state;
    terminal := v_job.state IN ('succeeded','failed','cancelled');
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_migrator_replay_schema_submission_v2(p_tenant_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_plan jsonb, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb, p_authority_id uuid, p_authority_group_id text, p_group_generation bigint, p_billing_generation bigint, p_forms_generation bigint) OWNER TO harpy_owner;

--
-- Name: platform_migrator_resolve_schema_result_v1(uuid, uuid, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_resolve_schema_result_v1(p_tenant_id uuid, p_job_id uuid, p_plan_sha256 text, p_minimum_generation bigint) RETURNS TABLE(job_id uuid, result_generation bigint, succeeded boolean, receipt_sha256 bytea, failure_code text, failure_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.schema_jobs%ROWTYPE;
    v_failure_digest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.uuid_extract_version(p_tenant_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
       OR p_minimum_generation IS NULL
       OR p_minimum_generation NOT BETWEEN 1 AND 9007199254740991 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'schema result identity is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.tenants AS tenant
        WHERE tenant.id = p_tenant_id
          AND tenant.deleted_at IS NULL
          AND tenant.status IN ('ACTIVE', 'TRIAL')
        FOR SHARE
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'schema result TenantScope is invalid';
    END IF;
    PERFORM platform.billing_resolve_current_tenant_authority_v1(p_tenant_id);
    SELECT candidate.* INTO v_job
    FROM platform.schema_jobs AS candidate
    WHERE candidate.tenant_id = p_tenant_id
      AND candidate.job_id = p_job_id
      AND candidate.plan_sha256 = p_plan_sha256
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'schema result binding differs';
    END IF;
    IF v_job.generation < p_minimum_generation
       OR v_job.state NOT IN ('succeeded', 'failed', 'cancelled') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'schema result is not terminal at required generation';
    END IF;
    job_id := v_job.job_id;
    result_generation := v_job.generation;
    succeeded := v_job.state = 'succeeded';
    IF succeeded THEN
        failure_code := NULL;
        failure_sha256 := NULL;
        receipt_sha256 := pg_catalog.sha256(pg_catalog.convert_to(
            pg_catalog.format(
                'harpy:v2:schema-result:v1|success|%s|%s|%s|%s',
                v_job.tenant_id, v_job.job_id, v_job.plan_sha256,
                v_job.generation
            ),
            'UTF8'
        ));
    ELSE
        failure_code := CASE v_job.state
            WHEN 'cancelled' THEN 'SCHEMA_JOB_CANCELLED'
            ELSE 'SCHEMA_JOB_FAILED'
        END;
        SELECT attempt.redacted_detail_sha256 INTO v_failure_digest
        FROM platform.schema_job_steps AS step
        JOIN platform.schema_job_step_attempts AS attempt
          ON attempt.job_id = step.job_id
         AND attempt.step_ordinal = step.ordinal
         AND attempt.attempt = step.attempt
         AND attempt.plan_sha256 = step.plan_sha256
         AND attempt.step_sha256 = step.step_sha256
        WHERE step.job_id = v_job.job_id
          AND step.ordinal = v_job.next_step_ordinal
          AND step.error_code = v_job.failure_code
          AND attempt.error_code = v_job.failure_code
          AND attempt.state IN ('failed', 'blocked', 'cancelled')
        FOR SHARE OF step, attempt;
        IF FOUND THEN
            failure_sha256 := pg_catalog.decode(v_failure_digest, 'hex');
        ELSIF v_job.state = 'cancelled' THEN
            failure_sha256 := pg_catalog.sha256(pg_catalog.convert_to(
                pg_catalog.format(
                    'harpy:v2:schema-result-cancelled:v1|%s|%s|%s|%s|%s',
                    v_job.tenant_id, v_job.job_id, v_job.plan_sha256,
                    v_job.generation, v_job.failure_code
                ),
                'UTF8'
            ));
        ELSE
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'schema terminal failure evidence differs';
        END IF;
        receipt_sha256 := pg_catalog.sha256(pg_catalog.convert_to(
            pg_catalog.format(
                'harpy:v2:schema-result:v1|failure|%s|%s|%s|%s|%s|%s',
                v_job.tenant_id, v_job.job_id, v_job.plan_sha256,
                v_job.generation, failure_code,
                pg_catalog.encode(failure_sha256, 'hex')
            ),
            'UTF8'
        ));
    END IF;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.platform_migrator_resolve_schema_result_v1(p_tenant_id uuid, p_job_id uuid, p_plan_sha256 text, p_minimum_generation bigint) OWNER TO harpy_owner;

--
-- Name: platform_migrator_schema_authority_current_v2(uuid, uuid, text, bigint, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_schema_authority_current_v2(p_tenant_id uuid, p_authority_id uuid, p_authority_group_id text, p_group_generation bigint, p_billing_generation bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.uuid_extract_version(p_tenant_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_authority_id) IS DISTINCT FROM 7
       OR p_authority_group_id IS DISTINCT FROM 'billing'
       OR p_group_generation NOT BETWEEN 1 AND 9007199254740991
       OR p_billing_generation NOT BETWEEN 1 AND 9007199254740991 THEN
        RETURN false;
    END IF;
    PERFORM 1
    FROM platform.billing_tenant_authorities authority
    JOIN platform.tenants tenant ON tenant.id=authority.tenant_id
    JOIN platform.cutover_groups group_row
      ON group_row.scope_kind=authority.scope_kind
     AND group_row.scope_id=authority.scope_id
     AND group_row.group_id=authority.authority_group_id
    JOIN platform.domain_cutovers billing_row
      ON billing_row.scope_kind=authority.scope_kind
     AND billing_row.scope_id=authority.scope_id
     AND billing_row.domain=authority.billing_domain
    JOIN platform.cutover_group_members billing_member
      ON billing_member.scope_kind=authority.scope_kind
     AND billing_member.scope_id=authority.scope_id
     AND billing_member.group_id=authority.authority_group_id
     AND billing_member.domain='billing' AND billing_member.ordinal=1
    WHERE authority.authority_id=p_authority_id
      AND authority.tenant_id=p_tenant_id
      AND authority.scope_kind='tenant' AND authority.scope_id=p_tenant_id
      AND authority.authority_group_id=p_authority_group_id
      AND authority.authority_group_generation=p_group_generation
      AND authority.billing_domain='billing'
      AND authority.billing_generation=p_billing_generation
      AND tenant.deleted_at IS NULL AND tenant.status IN ('ACTIVE','TRIAL')
      AND group_row.state='v2' AND group_row.writer='v2'
      AND group_row.generation=p_group_generation
      AND billing_row.state='v2' AND billing_row.writer='v2'
      AND billing_row.generation=p_billing_generation
      AND NOT EXISTS (
          SELECT 1 FROM platform.cutover_group_members extra
          WHERE extra.scope_kind='tenant' AND extra.scope_id=p_tenant_id
            AND extra.group_id='billing'
            AND NOT (extra.ordinal=1 AND extra.domain='billing')
      )
    FOR SHARE OF authority,tenant,group_row,billing_row,billing_member;
    RETURN FOUND;
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END;
$$;


ALTER FUNCTION platform.platform_migrator_schema_authority_current_v2(p_tenant_id uuid, p_authority_id uuid, p_authority_group_id text, p_group_generation bigint, p_billing_generation bigint) OWNER TO harpy_owner;

--
-- Name: platform_migrator_submit_schema_plan_v1(name, uuid, uuid, text, uuid, bigint, text, text, integer, bytea, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_submit_schema_plan_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) RETURNS TABLE(job_id uuid, generation bigint, plan_sha256 text, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_plan jsonb;
    v_step jsonb;
    v_ordinal integer;
    v_existing_job_id uuid;
    v_existing_generation bigint;
BEGIN
    v_plan := platform.platform_migrator_assert_schema_submission_v1(
        p_scope_schema,
        p_tenant_id,
        p_job_id,
        p_resource_kind,
        p_resource_id,
        p_resource_revision,
        p_plan_contract_version,
        p_compiler_version,
        p_postgresql_major,
        p_canonical_plan_bytes,
        p_plan_sha256,
        p_canonical_steps
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:v2:schema-revision:' || p_tenant_id::text || ':forms:' ||
        p_resource_kind || ':' || p_resource_id::text,
        0
    ));
    SELECT existing.job_id, existing.generation
    INTO v_existing_job_id, v_existing_generation
    FROM platform.platform_migrator_replay_schema_submission_v1(
        p_tenant_id,
        p_resource_kind,
        p_resource_id,
        p_resource_revision,
        p_plan_contract_version,
        p_compiler_version,
        v_plan,
        p_canonical_plan_bytes,
        p_plan_sha256,
        p_canonical_steps
    ) AS existing;
    IF FOUND THEN
        job_id := v_existing_job_id;
        generation := v_existing_generation;
        plan_sha256 := p_plan_sha256;
        replay := TRUE;
        RETURN NEXT;
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.schema_jobs AS existing
        WHERE existing.job_id = p_job_id
        FOR SHARE
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'schema submission job identity is already owned';
    END IF;
    INSERT INTO platform.schema_jobs (
        job_id,
        tenant_id,
        owner,
        resource_kind,
        resource_id,
        resource_revision,
        compiler_version,
        plan_contract_version,
        canonical_plan,
        canonical_plan_bytes,
        plan_sha256,
        step_count,
        available_at
    ) VALUES (
        p_job_id,
        p_tenant_id,
        'forms',
        p_resource_kind,
        p_resource_id,
        p_resource_revision,
        p_compiler_version,
        p_plan_contract_version,
        v_plan,
        p_canonical_plan_bytes,
        p_plan_sha256,
        pg_catalog.jsonb_array_length(p_canonical_steps),
        pg_catalog.statement_timestamp()
    );
    FOR v_ordinal IN 0..pg_catalog.jsonb_array_length(p_canonical_steps) - 1 LOOP
        v_step := platform.platform_migrator_validate_submission_step_v1(
            p_plan_sha256,
            p_resource_kind,
            pg_catalog.decode(p_canonical_steps->>v_ordinal, 'hex'),
            v_ordinal,
            v_plan->'allowed_operations'
        );
        IF v_plan->'steps'->v_ordinal IS DISTINCT FROM v_step THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'schema submission plan and step differ';
        END IF;
        INSERT INTO platform.schema_job_steps (
            job_id,
            ordinal,
            plan_sha256,
            operation_id,
            transaction_class,
            executor_kind,
            identifier_mapping,
            arguments,
            canonical_step_bytes,
            step_sha256,
            next_executor
        ) VALUES (
            p_job_id,
            v_ordinal,
            p_plan_sha256,
            v_step->>'operation_id',
            v_step->>'transaction_class',
            v_step->>'executor_kind',
            v_step->'identifier_mapping',
            v_step->'arguments',
            pg_catalog.decode(p_canonical_steps->>v_ordinal, 'hex'),
            pg_catalog.encode(
                pg_catalog.sha256(pg_catalog.decode(p_canonical_steps->>v_ordinal, 'hex')), 'hex'
            ),
            v_step->>'executor_kind'
        );
    END LOOP;
    job_id := p_job_id;
    generation := 1;
    plan_sha256 := p_plan_sha256;
    replay := FALSE;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_migrator_submit_schema_plan_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) OWNER TO harpy_owner;

--
-- Name: platform_migrator_submit_schema_plan_v2(name, uuid, uuid, text, uuid, bigint, text, text, integer, bytea, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_submit_schema_plan_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) RETURNS TABLE(job_id uuid, generation bigint, plan_sha256 text, replay boolean, job_state text, terminal boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_plan jsonb; v_step jsonb; v_ordinal integer;
    v_authority_id uuid; v_group_id text; v_group_generation bigint;
    v_billing_generation bigint; v_forms_generation bigint;
    v_existing_job_id uuid; v_existing_generation bigint;
    v_existing_state text; v_existing_terminal boolean;
    v_completion_job_id uuid;
BEGIN
    v_plan := platform.platform_migrator_assert_schema_submission_v2(
        p_scope_schema,p_tenant_id,p_job_id,p_resource_kind,p_resource_id,
        p_resource_revision,p_plan_contract_version,p_compiler_version,
        p_postgresql_major,p_canonical_plan_bytes,p_plan_sha256,p_canonical_steps
    );
    SELECT receipt.authority_id,receipt.authority_group_id,
           receipt.authority_group_generation,receipt.billing_generation,
           receipt.forms_generation
      INTO v_authority_id,v_group_id,v_group_generation,
           v_billing_generation,v_forms_generation
    FROM platform.billing_resolve_current_tenant_authority_receipt_v1(
        p_tenant_id
    ) receipt;
    IF NOT FOUND OR v_group_id IS DISTINCT FROM 'billing' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='schema V2 submission authority receipt is unavailable';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:v2:schema-revision:'||p_tenant_id::text||':'||
        p_resource_kind||':'||p_resource_id::text,0
    ));
    SELECT existing.job_id,existing.generation,existing.job_state,existing.terminal
      INTO v_existing_job_id,v_existing_generation,
           v_existing_state,v_existing_terminal
    FROM platform.platform_migrator_replay_schema_submission_v2(
        p_tenant_id,p_resource_kind,p_resource_id,p_resource_revision,
        p_plan_contract_version,p_compiler_version,v_plan,p_canonical_plan_bytes,
        p_plan_sha256,p_canonical_steps,v_authority_id,v_group_id,
        v_group_generation,v_billing_generation,v_forms_generation
    ) existing;
    IF FOUND THEN
        IF v_existing_terminal THEN
            v_completion_job_id :=
                platform.platform_async_enqueue_forms_schema_completion_v1(
                    v_existing_job_id,p_job_id,v_authority_id,v_group_id,
                    v_group_generation,v_billing_generation,v_forms_generation
                );
            IF pg_catalog.uuid_extract_version(v_completion_job_id)
                    IS DISTINCT FROM 7 THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='schema V2 terminal replay completion is invalid';
            END IF;
        END IF;
        job_id:=v_existing_job_id; generation:=v_existing_generation;
        plan_sha256:=p_plan_sha256; replay:=true;
        job_state:=v_existing_state; terminal:=v_existing_terminal;
        RETURN NEXT;
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.schema_jobs existing
        WHERE existing.job_id=p_job_id FOR SHARE
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='schema V2 submission job identity is already owned';
    END IF;
    INSERT INTO platform.schema_jobs (
        job_id,tenant_id,owner,resource_kind,resource_id,resource_revision,
        compiler_version,plan_contract_version,canonical_plan,
        canonical_plan_bytes,plan_sha256,step_count,available_at,
        submission_authority_id,submission_authority_group_id,
        submission_group_generation,submission_billing_generation,
        submission_forms_generation
    ) VALUES (
        p_job_id,p_tenant_id,'billing',p_resource_kind,p_resource_id,
        p_resource_revision,p_compiler_version,p_plan_contract_version,v_plan,
        p_canonical_plan_bytes,p_plan_sha256,
        pg_catalog.jsonb_array_length(p_canonical_steps),
        pg_catalog.statement_timestamp(),v_authority_id,v_group_id,
        v_group_generation,v_billing_generation,v_forms_generation
    );
    FOR v_ordinal IN 0..pg_catalog.jsonb_array_length(p_canonical_steps)-1 LOOP
        v_step := platform.platform_migrator_validate_submission_step_v2(
            p_plan_sha256,p_resource_kind,
            pg_catalog.decode(p_canonical_steps->>v_ordinal,'hex'),
            v_ordinal,v_plan->'allowed_operations'
        );
        IF v_plan->'steps'->v_ordinal IS DISTINCT FROM v_step THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='schema V2 submission plan and step differ';
        END IF;
        INSERT INTO platform.schema_job_steps (
            job_id,ordinal,plan_sha256,operation_id,transaction_class,
            executor_kind,identifier_mapping,arguments,canonical_step_bytes,
            step_sha256,next_executor
        ) VALUES (
            p_job_id,v_ordinal,p_plan_sha256,v_step->>'operation_id',
            v_step->>'transaction_class',v_step->>'executor_kind',
            v_step->'identifier_mapping',v_step->'arguments',
            pg_catalog.decode(p_canonical_steps->>v_ordinal,'hex'),
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.decode(
                p_canonical_steps->>v_ordinal,'hex')),'hex'),
            v_step->>'executor_kind'
        );
    END LOOP;
    job_id:=p_job_id; generation:=1; plan_sha256:=p_plan_sha256;
    replay:=false; job_state:='queued'; terminal:=false;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.platform_migrator_submit_schema_plan_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_revision bigint, p_plan_contract_version text, p_compiler_version text, p_postgresql_major integer, p_canonical_plan_bytes bytea, p_plan_sha256 text, p_canonical_steps jsonb) OWNER TO harpy_owner;

--
-- Name: platform_migrator_tenant_checkpoint_satisfies_v1(uuid, text, bigint, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_tenant_checkpoint_satisfies_v1(p_tenant_id uuid, p_owner text, p_logical_version bigint, p_database_origin text, p_selected_path text, p_selected_sha256 text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
SELECT EXISTS (
    SELECT 1
    FROM platform.tenant_migration_checkpoints AS checkpoint
    WHERE checkpoint.tenant_id = p_tenant_id
      AND checkpoint.owner = p_owner
      AND checkpoint.logical_version = p_logical_version
      AND checkpoint.state = 'succeeded'
      AND (
        (
          checkpoint.database_origin = p_database_origin
          AND checkpoint.selected_path = p_selected_path
          AND checkpoint.selected_sha256 = p_selected_sha256
        ) OR EXISTS (
          SELECT 1
          FROM platform.tenant_migration_supersessions AS supersession
          WHERE supersession.owner = p_owner
            AND supersession.scope = 'tenant'
            AND supersession.logical_version = p_logical_version
            AND supersession.database_origin = p_database_origin
            AND supersession.current_path = p_selected_path
            AND supersession.current_sha256 = p_selected_sha256
            AND checkpoint.database_origin = supersession.database_origin
            AND checkpoint.selected_path = supersession.superseded_path
            AND checkpoint.selected_sha256 = supersession.superseded_sha256
        )
      )
);
$$;


ALTER FUNCTION platform.platform_migrator_tenant_checkpoint_satisfies_v1(p_tenant_id uuid, p_owner text, p_logical_version bigint, p_database_origin text, p_selected_path text, p_selected_sha256 text) OWNER TO harpy_owner;

