CREATE FUNCTION platform.platform_migrator_tenant_checkpoint_satisfies_v2(p_tenant_id uuid, p_owner text, p_logical_version bigint, p_database_origin text, p_selected_path text, p_selected_sha256 text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
