            WHERE attempt.tenant_id = NEW.tenant_id
              AND attempt.owner = NEW.owner
              AND attempt.logical_version = NEW.logical_version
              AND attempt.attempt = NEW.attempt
              AND attempt.database_origin = NEW.database_origin
              AND attempt.selected_path = NEW.selected_path
              AND attempt.selected_sha256 = NEW.selected_sha256
              AND attempt.run_id = NEW.run_id
              AND attempt.state = NEW.state
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'checkpoint receipt is missing';
        END IF;
        SELECT attempt.started_at,attempt.finished_at,attempt.error_code
        INTO NEW.started_at,NEW.finished_at,NEW.error_code
        FROM platform.tenant_migration_checkpoint_attempts AS attempt
        WHERE attempt.tenant_id = NEW.tenant_id
          AND attempt.owner = NEW.owner
          AND attempt.logical_version = NEW.logical_version
          AND attempt.attempt = NEW.attempt;
    END IF;
    NEW.updated_at := pg_catalog.clock_timestamp();
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_checkpoint_transition_v4() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_checkpoint_transition_v5(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_checkpoint_transition_v5() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_identity_changed boolean;
    v_registered_supersession boolean;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'pending' OR NEW.attempt <> 1 OR
           NEW.started_at IS NOT NULL OR NEW.finished_at IS NOT NULL OR
           NEW.error_code IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'invalid initial checkpoint';
        END IF;
        NEW.updated_at := pg_catalog.clock_timestamp();
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'checkpoint deletion is forbidden';
    END IF;
    v_identity_changed :=
        ROW(NEW.tenant_id,NEW.owner,NEW.logical_version,NEW.database_origin,
            NEW.selected_path,NEW.selected_sha256)
        IS DISTINCT FROM
        ROW(OLD.tenant_id,OLD.owner,OLD.logical_version,OLD.database_origin,
            OLD.selected_path,OLD.selected_sha256);
    v_registered_supersession := v_identity_changed
        AND OLD.state = 'failed' AND NEW.state = 'running'
        AND NEW.attempt = OLD.attempt + 1 AND NEW.run_id <> OLD.run_id
        AND NEW.tenant_id = OLD.tenant_id AND NEW.owner = OLD.owner
        AND NEW.logical_version = OLD.logical_version
        AND EXISTS (
            SELECT 1
            FROM platform.tenant_migration_supersessions AS supersession
            WHERE supersession.owner = NEW.owner
              AND supersession.scope = 'tenant'
              AND supersession.logical_version = NEW.logical_version
              AND supersession.database_origin = NEW.database_origin
              AND supersession.database_origin = OLD.database_origin
              AND supersession.superseded_path = OLD.selected_path
              AND supersession.superseded_sha256 = OLD.selected_sha256
              AND supersession.current_path = NEW.selected_path
              AND supersession.current_sha256 = NEW.selected_sha256
              AND supersession.supersession_distance IN (1,2,3)
        );
    IF v_identity_changed AND NOT v_registered_supersession THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'checkpoint identity is immutable';
    END IF;
    IF NOT (
        (OLD.state = 'pending' AND NEW.state = 'running' AND
            NEW.attempt = OLD.attempt AND NEW.run_id = OLD.run_id) OR
        (OLD.state = 'failed' AND NEW.state = 'running' AND
            NEW.attempt = OLD.attempt + 1 AND NEW.run_id <> OLD.run_id) OR
        (OLD.state = 'running' AND NEW.state IN ('succeeded','failed','fenced') AND
            NEW.attempt = OLD.attempt AND NEW.run_id = OLD.run_id)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'invalid checkpoint transition';
    END IF;
    IF NEW.state = 'running' THEN
        NEW.started_at := pg_catalog.clock_timestamp();
        NEW.finished_at := NULL;
        NEW.error_code := NULL;
    ELSE
        IF NOT EXISTS (
            SELECT 1
            FROM platform.tenant_migration_checkpoint_attempts AS attempt
            WHERE attempt.tenant_id = NEW.tenant_id
              AND attempt.owner = NEW.owner
              AND attempt.logical_version = NEW.logical_version
              AND attempt.attempt = NEW.attempt
              AND attempt.database_origin = NEW.database_origin
              AND attempt.selected_path = NEW.selected_path
              AND attempt.selected_sha256 = NEW.selected_sha256
              AND attempt.run_id = NEW.run_id
              AND attempt.state = NEW.state
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'checkpoint receipt is missing';
        END IF;
        SELECT attempt.started_at,attempt.finished_at,attempt.error_code
        INTO NEW.started_at,NEW.finished_at,NEW.error_code
        FROM platform.tenant_migration_checkpoint_attempts AS attempt
        WHERE attempt.tenant_id = NEW.tenant_id
          AND attempt.owner = NEW.owner
          AND attempt.logical_version = NEW.logical_version
          AND attempt.attempt = NEW.attempt;
    END IF;
    NEW.updated_at := pg_catalog.clock_timestamp();
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_checkpoint_transition_v5() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_contract_transition(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_contract_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'schema contract deletion is forbidden';
    END IF;
    IF NEW.component IS DISTINCT FROM OLD.component THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'schema component is immutable';
    END IF;
    IF NEW.revision <> OLD.revision + 1
        OR NEW.database_generation < OLD.database_generation
        OR NEW.minimum_runtime_generation < OLD.minimum_runtime_generation
        OR NEW.verified_at <= OLD.verified_at
        OR NEW.verified_run_id = OLD.verified_run_id THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'invalid schema contract transition';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_contract_transition() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_release_generation_finalization(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_release_generation_finalization() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM platform.release_generations AS release_row
        JOIN platform.schema_contracts AS contract_row
          ON contract_row.component = 'core'
         AND contract_row.verified_run_id = release_row.migration_run_id
         AND contract_row.database_generation = release_row.database_generation
         AND contract_row.minimum_runtime_generation = release_row.minimum_runtime_generation
         AND contract_row.migration_manifest_sha256 = release_row.migration_manifest_sha256
         AND contract_row.extension_manifest_sha256 = release_row.extension_manifest_sha256
         AND contract_row.status = 'ready'
        WHERE release_row.migration_run_id = NEW.migration_run_id
          AND release_row.xmin::text = pg_catalog.pg_current_xact_id()::text
          AND contract_row.xmin::text = pg_catalog.pg_current_xact_id()::text
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'release generation is not the finalized active contract';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_release_generation_finalization() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_release_generation_insert(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_release_generation_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM platform.release_generations AS stored
        WHERE stored.migration_run_id = NEW.migration_run_id
          AND stored.release_id = NEW.release_id
          AND stored.environment_id = NEW.environment_id
          AND stored.database_origin = NEW.database_origin
          AND stored.database_generation = NEW.database_generation
          AND stored.minimum_runtime_generation = NEW.minimum_runtime_generation
          AND stored.runtime_generation = NEW.runtime_generation
          AND stored.minimum_database_generation = NEW.minimum_database_generation
          AND stored.migration_manifest_sha256 = NEW.migration_manifest_sha256
          AND stored.extension_manifest_sha256 = NEW.extension_manifest_sha256
          AND stored.postgres_image_digest = NEW.postgres_image_digest
          AND stored.bootstrap_receipt_run_id = NEW.bootstrap_receipt_run_id
          AND stored.extension_receipt_run_id = NEW.extension_receipt_run_id
          AND stored.cleanup_receipt_run_id = NEW.cleanup_receipt_run_id
    ) THEN
        RETURN NEW;
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.release_generations AS stored
        WHERE stored.migration_run_id = NEW.migration_run_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'release generation replay differs';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.release_generations AS stored
        WHERE stored.environment_id = NEW.environment_id
          AND stored.release_id = NEW.release_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'release generation release fork';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.release_generations AS stored
        WHERE stored.environment_id = NEW.environment_id
          AND stored.runtime_generation = NEW.runtime_generation
          AND stored.minimum_database_generation = NEW.minimum_database_generation
          AND stored.migration_manifest_sha256 = NEW.migration_manifest_sha256
          AND stored.extension_manifest_sha256 = NEW.extension_manifest_sha256
          AND stored.postgres_image_digest = NEW.postgres_image_digest
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'release generation binary tuple is duplicated';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.migration_runs AS run_row
        JOIN platform.environment_identity AS identity_row
          ON identity_row.singleton = TRUE
         AND identity_row.environment_id = run_row.environment_id
         AND identity_row.database_origin = run_row.database_origin
        JOIN platform.bootstrap_receipts AS bootstrap_row
          ON bootstrap_row.kind = NEW.bootstrap_receipt_kind
         AND bootstrap_row.run_id = NEW.bootstrap_receipt_run_id
        JOIN platform.bootstrap_receipts AS extension_row
          ON extension_row.kind = NEW.extension_receipt_kind
         AND extension_row.run_id = NEW.extension_receipt_run_id
        JOIN platform.bootstrap_receipts AS cleanup_row
          ON cleanup_row.kind = NEW.cleanup_receipt_kind
         AND cleanup_row.run_id = NEW.cleanup_receipt_run_id
        WHERE run_row.run_id = NEW.migration_run_id
          AND run_row.release_id = NEW.release_id
          AND run_row.environment_id = NEW.environment_id
          AND run_row.database_origin = NEW.database_origin
          AND run_row.command = 'up'
          AND run_row.state = 'succeeded'
          AND run_row.migration_manifest_sha256 = NEW.migration_manifest_sha256
          AND run_row.extension_manifest_sha256 = NEW.extension_manifest_sha256
          AND run_row.xmin::text = pg_catalog.pg_current_xact_id()::text
          AND bootstrap_row.release_id = NEW.release_id
          AND extension_row.release_id = NEW.release_id
          AND cleanup_row.release_id = NEW.release_id
          AND bootstrap_row.environment_id = NEW.environment_id
          AND extension_row.environment_id = NEW.environment_id
          AND cleanup_row.environment_id = NEW.environment_id
          AND bootstrap_row.database_origin = NEW.database_origin
          AND extension_row.database_origin = NEW.database_origin
          AND cleanup_row.database_origin = NEW.database_origin
          AND bootstrap_row.database_system_identifier = identity_row.database_system_identifier
          AND extension_row.database_system_identifier = identity_row.database_system_identifier
          AND cleanup_row.database_system_identifier = identity_row.database_system_identifier
          AND bootstrap_row.database_oid = identity_row.database_oid
          AND extension_row.database_oid = identity_row.database_oid
          AND cleanup_row.database_oid = identity_row.database_oid
          AND bootstrap_row.xmin::text = pg_catalog.pg_current_xact_id()::text
          AND extension_row.xmin::text = pg_catalog.pg_current_xact_id()::text
          AND cleanup_row.xmin::text = pg_catalog.pg_current_xact_id()::text
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'release generation is outside exact finalization';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.platform_migration_history AS history_row
        WHERE history_row.record_kind = 'migration'
          AND history_row.is_applied = TRUE
          AND history_row.version = (
              SELECT pg_catalog.max(latest_row.version)
              FROM platform.platform_migration_history AS latest_row
              WHERE latest_row.record_kind = 'migration'
                AND latest_row.is_applied = TRUE
          )
          AND history_row.target_database_generation = NEW.database_generation
          AND history_row.next_minimum_runtime_generation = NEW.minimum_runtime_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'release generation differs from migration history';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_release_generation_insert() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_run_transition(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_run_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'migration run deletion is forbidden';
    END IF;
    IF ROW(NEW.run_id, NEW.release_id, NEW.environment_id, NEW.database_origin,
           NEW.command, NEW.migration_manifest_sha256, NEW.extension_manifest_sha256,
           NEW.roles_manifest_sha256, NEW.privileges_manifest_sha256,
           NEW.ownership_manifest_sha256, NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.run_id, OLD.release_id, OLD.environment_id, OLD.database_origin,
           OLD.command, OLD.migration_manifest_sha256, OLD.extension_manifest_sha256,
           OLD.roles_manifest_sha256, OLD.privileges_manifest_sha256,
           OLD.ownership_manifest_sha256, OLD.created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'migration run identity is immutable';
    END IF;
    IF NOT ((OLD.state = 'planned' AND NEW.state IN ('running', 'fenced'))
        OR (OLD.state = 'running' AND NEW.state IN ('succeeded', 'failed', 'fenced'))) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'invalid migration run transition';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_run_transition() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_schema_attempt_insert(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_schema_attempt_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.recorded_at > pg_catalog.clock_timestamp() OR NOT EXISTS (
        SELECT 1
        FROM platform.schema_job_steps AS step
        JOIN platform.schema_jobs AS job ON job.job_id = step.job_id
        WHERE step.job_id = NEW.job_id
          AND step.ordinal = NEW.step_ordinal
          AND step.plan_sha256 = NEW.plan_sha256
          AND step.step_sha256 = NEW.step_sha256
          AND step.state = 'running'
          AND step.attempt = NEW.attempt
          AND step.executor_kind = NEW.executor_kind
          AND step.started_at = NEW.started_at
          AND job.next_step_ordinal = NEW.step_ordinal
          AND job.next_executor = NEW.executor_kind
          AND job.lease_id = NEW.lease_id
          AND job.lease_owner_id = NEW.lease_owner_id
          AND job.state IN ('leased', 'running')
          AND (
              (NEW.state = 'lease_expired' AND
                  job.lease_expires_at <= NEW.finished_at) OR
              (NEW.state <> 'lease_expired' AND job.state = 'running' AND
                  NEW.finished_at < job.lease_expires_at)
          )
          AND COALESCE((
              SELECT pg_catalog.max(previous.attempt)
              FROM platform.schema_job_step_attempts AS previous
              WHERE previous.job_id = NEW.job_id
                AND previous.step_ordinal = NEW.step_ordinal
          ), 0) = NEW.attempt - 1
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'schema attempt does not match active lease';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_schema_attempt_insert() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_schema_attempt_insert_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_schema_attempt_insert_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.recorded_at > pg_catalog.clock_timestamp() OR NOT EXISTS (
        SELECT 1
        FROM platform.schema_job_steps AS step
        JOIN platform.schema_jobs AS job ON job.job_id = step.job_id
        WHERE step.job_id = NEW.job_id
          AND step.ordinal = NEW.step_ordinal
          AND step.plan_sha256 = NEW.plan_sha256
          AND step.step_sha256 = NEW.step_sha256
          AND step.state = 'running'
          AND step.attempt = NEW.attempt
          AND step.executor_kind = NEW.executor_kind
          AND step.started_at = NEW.started_at
          AND job.next_step_ordinal = NEW.step_ordinal
          AND job.next_executor = NEW.executor_kind
          AND job.lease_id = NEW.lease_id
          AND job.lease_owner_id = NEW.lease_owner_id
          AND job.state IN ('leased', 'running')
          AND (
              (NEW.state = 'lease_expired' AND NEW.error_code = 'lease_expired' AND
                  job.lease_expires_at <= NEW.finished_at) OR
              (NEW.state = 'failed' AND NEW.attempt = 8 AND
                  NEW.error_code = 'attempt_limit_exhausted' AND
                  job.lease_expires_at <= NEW.finished_at) OR
              (NEW.state <> 'lease_expired' AND
                  NEW.error_code IS DISTINCT FROM 'attempt_limit_exhausted' AND
                  job.state = 'running' AND NEW.finished_at < job.lease_expires_at)
          )
          AND COALESCE((
              SELECT pg_catalog.max(previous.attempt)
              FROM platform.schema_job_step_attempts AS previous
              WHERE previous.job_id = NEW.job_id
                AND previous.step_ordinal = NEW.step_ordinal
          ), 0) = NEW.attempt - 1
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'schema attempt does not match active lease';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_schema_attempt_insert_v2() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_schema_job_alignment(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_schema_job_alignment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM platform.schema_jobs AS job
        WHERE job.job_id = NEW.job_id AND (
            (job.state IN ('queued', 'awaiting_runtime') AND EXISTS (
                SELECT 1 FROM platform.schema_job_steps AS current_step
                WHERE current_step.job_id = job.job_id
                  AND current_step.ordinal = job.next_step_ordinal
                  AND current_step.state IN ('pending', 'retryable', 'lease_expired')
                  AND current_step.executor_kind = job.next_executor
            )) OR
            (job.state IN ('leased', 'running') AND EXISTS (
                SELECT 1 FROM platform.schema_job_steps AS current_step
                WHERE current_step.job_id = job.job_id
                  AND current_step.ordinal = job.next_step_ordinal
                  AND current_step.state = 'running'
                  AND current_step.executor_kind = job.next_executor
            )) OR
            (job.state = 'lease_expired' AND EXISTS (
                SELECT 1 FROM platform.schema_job_steps AS current_step
                WHERE current_step.job_id = job.job_id
                  AND current_step.ordinal = job.next_step_ordinal
                  AND current_step.state = 'lease_expired'
                  AND current_step.executor_kind = job.next_executor
            )) OR
            (job.state = 'succeeded' AND NOT EXISTS (
                SELECT 1 FROM platform.schema_job_steps AS unfinished_step
                WHERE unfinished_step.job_id = job.job_id
                  AND unfinished_step.state NOT IN ('succeeded', 'skipped')
            )) OR
            (job.state = 'failed' AND EXISTS (
                SELECT 1 FROM platform.schema_job_steps AS current_step
                WHERE current_step.job_id = job.job_id
                  AND current_step.ordinal = job.next_step_ordinal
                  AND current_step.state IN ('failed', 'blocked')
            )) OR
            (job.state = 'cancelled' AND EXISTS (
                SELECT 1 FROM platform.schema_job_steps AS current_step
                WHERE current_step.job_id = job.job_id
                  AND current_step.ordinal = job.next_step_ordinal
                  AND current_step.state IN (
                      'pending', 'retryable', 'lease_expired', 'cancelled'
                  )
            ))
        )
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'schema job and current step are misaligned';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_schema_job_alignment() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_schema_job_plan(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_schema_job_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM platform.schema_jobs AS job
        WHERE job.job_id = NEW.job_id
          AND job.state = 'queued'
          AND job.next_executor = 'migrator'
          AND job.next_step_ordinal = 0
          AND job.generation = 1
          AND job.attempt = 0
          AND job.last_lease_expired_at IS NULL
          AND job.updated_at = job.created_at
          AND (
              SELECT pg_catalog.count(*)
              FROM platform.schema_job_steps AS step
              WHERE step.job_id = job.job_id
          ) = job.step_count
          AND (
              SELECT pg_catalog.min(step.ordinal)
              FROM platform.schema_job_steps AS step
              WHERE step.job_id = job.job_id
          ) = 0
          AND (
              SELECT pg_catalog.max(step.ordinal)
              FROM platform.schema_job_steps AS step
              WHERE step.job_id = job.job_id
          ) = job.step_count - 1
          AND EXISTS (
              SELECT 1 FROM platform.schema_job_steps AS first_step
              WHERE first_step.job_id = job.job_id AND first_step.ordinal = 0
                AND first_step.executor_kind = 'migrator'
          )
          AND NOT EXISTS (
              SELECT 1 FROM platform.schema_job_steps AS invalid_step
              WHERE invalid_step.job_id = job.job_id AND (
                  invalid_step.plan_sha256 <> job.plan_sha256 OR
                  invalid_step.state <> 'pending' OR
                  invalid_step.generation <> 1 OR invalid_step.attempt <> 0 OR
                  invalid_step.next_executor <> invalid_step.executor_kind OR
                  invalid_step.updated_at <> invalid_step.created_at
              )
          )
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'schema job plan must be complete and gapless';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_schema_job_plan() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_schema_job_revision(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_schema_job_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:v2:schema-revision:' || NEW.tenant_id::text || ':' ||
        NEW.owner || ':' || NEW.resource_kind || ':' || NEW.resource_id::text,
        0
    )) THEN
        RAISE EXCEPTION USING
            ERRCODE = '40001', MESSAGE = 'schema resource revision serialization conflict';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.schema_jobs AS previous
        WHERE previous.tenant_id = NEW.tenant_id
          AND previous.owner = NEW.owner
          AND previous.resource_kind = NEW.resource_kind
          AND previous.resource_id = NEW.resource_id
          AND previous.resource_revision >= NEW.resource_revision
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'schema resource revision is not monotonic';
    END IF;
