        NEW.arguments, NEW.step_sha256, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.job_id, OLD.ordinal, OLD.plan_sha256, OLD.operation_id,
        OLD.transaction_class, OLD.executor_kind, OLD.identifier_mapping,
        OLD.arguments, OLD.step_sha256, OLD.created_at
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'schema step identity is immutable';
    END IF;
    IF NEW.generation <> OLD.generation + 1 OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'schema step generation must advance exactly once';
    END IF;

    IF OLD.state IN ('pending', 'retryable', 'lease_expired') AND
       NEW.state = 'running' AND NEW.attempt = OLD.attempt + 1 AND
       NEW.next_executor = OLD.executor_kind AND
       ROW(
           NEW.checkpoint_record_id, NEW.processed_rows,
           NEW.checkpoint_canonical_bytes, NEW.checkpoint_page_sha256
       ) IS NOT DISTINCT FROM ROW(
           OLD.checkpoint_record_id, OLD.processed_rows,
           OLD.checkpoint_canonical_bytes, OLD.checkpoint_page_sha256
       ) AND EXISTS (
           SELECT 1 FROM platform.schema_jobs AS job
           WHERE job.job_id = OLD.job_id AND job.state = 'leased'
             AND job.next_step_ordinal = OLD.ordinal
             AND job.next_executor = OLD.executor_kind
       ) THEN
        RETURN NEW;
    END IF;

    IF OLD.state = 'running' AND NEW.state = 'running' AND
       OLD.operation_id = 'backfill_field_batch' AND
       NEW.attempt = OLD.attempt AND NEW.next_executor = OLD.executor_kind AND
       NEW.started_at = OLD.started_at AND NEW.finished_at IS NULL AND
       NEW.error_code IS NULL AND NEW.processed_rows > OLD.processed_rows AND
       NEW.processed_rows <= OLD.processed_rows + 1000 AND
       NEW.checkpoint_record_id IS NOT NULL AND
       (OLD.checkpoint_record_id IS NULL OR
        NEW.checkpoint_record_id > OLD.checkpoint_record_id) AND EXISTS (
           SELECT 1 FROM platform.schema_jobs AS job
           WHERE job.job_id = OLD.job_id AND job.state = 'running'
             AND job.next_step_ordinal = OLD.ordinal
             AND job.next_executor = OLD.executor_kind
             AND (
                (
                    job.plan_contract_version = 'forms-schema-plan.v1' AND
                    NEW.checkpoint_canonical_bytes IS NULL AND
                    NEW.checkpoint_page_sha256 IS NULL
                ) OR (
                    job.plan_contract_version = 'forms-schema-plan.v2' AND
                    NEW.checkpoint_canonical_bytes BETWEEN 1 AND 8388608 AND
                    NEW.checkpoint_page_sha256 ~ '^[0-9a-f]{64}$'
                )
             )
       ) THEN
        RETURN NEW;
    END IF;

    IF OLD.state = 'running' AND NEW.state IN (
        'succeeded', 'retryable', 'lease_expired', 'failed',
        'blocked', 'skipped', 'cancelled'
    ) AND NEW.attempt = OLD.attempt AND
       ROW(
           NEW.checkpoint_record_id, NEW.processed_rows,
           NEW.checkpoint_canonical_bytes, NEW.checkpoint_page_sha256
       ) IS NOT DISTINCT FROM ROW(
           OLD.checkpoint_record_id, OLD.processed_rows,
           OLD.checkpoint_canonical_bytes, OLD.checkpoint_page_sha256
       ) AND EXISTS (
        SELECT 1 FROM platform.schema_job_step_attempts AS receipt
        WHERE receipt.job_id = OLD.job_id
          AND receipt.step_ordinal = OLD.ordinal
          AND receipt.attempt = OLD.attempt
          AND receipt.plan_sha256 = OLD.plan_sha256
          AND receipt.step_sha256 = OLD.step_sha256
          AND receipt.state = NEW.state
          AND receipt.started_at = OLD.started_at
          AND receipt.finished_at = NEW.finished_at
    ) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION USING
        ERRCODE = '55000', MESSAGE = 'invalid schema step transition';
END;
$_$;


ALTER FUNCTION platform.platform_migrator_validate_schema_step_transition_v3() OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_submission_step_v1(text, text, bytea, integer, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_submission_step_v1(p_plan_sha256 text, p_resource_kind text, p_document bytea, p_expected_ordinal integer, p_allowed_operations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
    v_step jsonb;
    v_operation text;
    v_executor text;
    v_transaction_class text;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
       OR p_resource_kind NOT IN ('form_storage','form_purge')
       OR p_expected_ordinal NOT BETWEEN 0 AND 1999
       OR p_document IS NULL
       OR pg_catalog.octet_length(p_document) NOT BETWEEN 2 AND 1048576
       OR pg_catalog.encode(pg_catalog.sha256(p_document),'hex') IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema submission step input is invalid';
    END IF;
    BEGIN
        v_document := pg_catalog.convert_from(p_document,'UTF8')::jsonb;
    EXCEPTION WHEN character_not_in_repertoire OR invalid_text_representation THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema submission step document is invalid';
    END;
    IF pg_catalog.jsonb_typeof(v_document)<>'object'
       OR (SELECT pg_catalog.count(*) FROM
            pg_catalog.jsonb_object_keys(v_document))<>2
       OR NOT (v_document ? 'plan_sha256' AND v_document ? 'step')
       OR v_document->>'plan_sha256' IS DISTINCT FROM p_plan_sha256
       OR pg_catalog.jsonb_typeof(v_document->'step')<>'object' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema submission step envelope differs';
    END IF;
    v_step := v_document->'step';
    IF (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_step))<>6
       OR NOT (v_step ?& ARRAY['ordinal','operation_id','transaction_class',
            'executor_kind','identifier_mapping','arguments'])
       OR (v_step->>'ordinal')::integer IS DISTINCT FROM p_expected_ordinal
       OR pg_catalog.jsonb_typeof(v_step->'identifier_mapping')<>'object'
       OR v_step->'identifier_mapping'='{}'::jsonb
       OR pg_catalog.jsonb_typeof(v_step->'arguments')<>'object'
       OR pg_catalog.octet_length((v_step->'identifier_mapping')::text)
            NOT BETWEEN 2 AND 65536
       OR pg_catalog.octet_length((v_step->'arguments')::text)
            NOT BETWEEN 2 AND 262144
       OR v_step::text ~*
            '"(sql|raw_sql|function_body|routine_body|client_identifier)"[[:space:]]*:' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema submission step shape differs';
    END IF;
    v_operation := v_step->>'operation_id';
    v_executor := v_step->>'executor_kind';
    v_transaction_class := v_step->>'transaction_class';
    IF NOT EXISTS (SELECT 1 FROM
        pg_catalog.jsonb_array_elements_text(p_allowed_operations) AS allowed(value)
        WHERE allowed.value=v_operation) OR v_operation NOT IN (
        'activate_generation','add_constraint','add_field_column','add_relation_table',
        'backfill_field_batch','cleanup_invalid_index','create_form_table','create_index',
        'create_index_concurrently','disable_old_writer','drop_constraint',
        'drop_field_column','drop_form_table','drop_index','drop_index_concurrently',
        'drop_relation_table','enable_dual_write','retain_generation',
        'set_field_not_null','validate_constraint','verify_storage'
    ) OR (v_operation='drop_form_table' AND p_resource_kind<>'form_purge') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema submission step operation is invalid';
    END IF;
    IF (v_operation IN ('cleanup_invalid_index','create_index_concurrently',
            'drop_index_concurrently') AND (v_executor<>'migrator'
            OR v_transaction_class<>'concurrent_index'))
       OR (v_operation IN ('activate_generation','disable_old_writer',
            'enable_dual_write','retain_generation') AND
            (v_executor<>'forms_runtime' OR v_transaction_class<>'transactional'))
       OR (v_operation NOT IN ('cleanup_invalid_index','create_index_concurrently',
            'drop_index_concurrently','activate_generation','disable_old_writer',
            'enable_dual_write','retain_generation') AND
            (v_executor<>'migrator' OR v_transaction_class<>'transactional')) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema submission execution contract differs';
    END IF;
    RETURN v_step;
END;
$_$;


ALTER FUNCTION platform.platform_migrator_validate_submission_step_v1(p_plan_sha256 text, p_resource_kind text, p_document bytea, p_expected_ordinal integer, p_allowed_operations jsonb) OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_submission_step_v2(text, text, bytea, integer, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_submission_step_v2(p_plan_sha256 text, p_resource_kind text, p_document bytea, p_expected_ordinal integer, p_allowed_operations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_step jsonb;
BEGIN
    v_step := platform.platform_migrator_validate_submission_step_v1(
        p_plan_sha256,p_resource_kind,p_document,p_expected_ordinal,
        p_allowed_operations
    );
    IF pg_catalog.jsonb_typeof(v_step#>'{identifier_mapping,form}')<>'object'
       OR v_step#>>'{identifier_mapping,form,logical_id}' IS NULL
       OR v_step#>>'{identifier_mapping,form,physical_name}' IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='schema V2 submission mapping differs';
    END IF;
    RETURN v_step;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_submission_step_v2(p_plan_sha256 text, p_resource_kind text, p_document bytea, p_expected_ordinal integer, p_allowed_operations jsonb) OWNER TO harpy_owner;

--
-- Name: platform_migrator_validate_tenant_checkpoint_attempt(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_validate_tenant_checkpoint_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'tenant checkpoint attempt is append only';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM platform.tenant_migration_checkpoints AS checkpoint
        WHERE checkpoint.tenant_id = NEW.tenant_id
          AND checkpoint.owner = NEW.owner
          AND checkpoint.logical_version = NEW.logical_version
          AND checkpoint.database_origin = NEW.database_origin
          AND checkpoint.selected_path = NEW.selected_path
          AND checkpoint.selected_sha256 = NEW.selected_sha256
          AND checkpoint.run_id = NEW.run_id
          AND checkpoint.state = 'running'
          AND checkpoint.attempt = NEW.attempt
    ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000', MESSAGE = 'tenant checkpoint attempt is invalid';
    END IF;
    NEW.started_at := (
        SELECT checkpoint.started_at
        FROM platform.tenant_migration_checkpoints AS checkpoint
        WHERE checkpoint.tenant_id = NEW.tenant_id
          AND checkpoint.owner = NEW.owner
          AND checkpoint.logical_version = NEW.logical_version
    );
    NEW.finished_at := pg_catalog.clock_timestamp();
    NEW.recorded_at := NEW.finished_at;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platform_migrator_validate_tenant_checkpoint_attempt() OWNER TO harpy_owner;

--
-- Name: platform_migrator_verify_new_tenant_v1(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_verify_new_tenant_v1(p_release_id uuid, p_environment_id uuid, p_database_origin text, p_tenant_id uuid, p_migration_manifest_sha256 text) RETURNS TABLE(verified boolean, catalog_sha256 text, requirement_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_migration_run_id uuid;
    v_catalog_sha256 text;
    v_requirement_count integer;
BEGIN
    LOCK TABLE platform.release_generations,
        platform.tenant_migration_requirement_catalogs,
        platform.tenant_migration_requirements,
        platform.tenant_migration_checkpoints IN SHARE MODE;

    SELECT catalog.migration_run_id, catalog.catalog_sha256,
           catalog.requirement_count
    INTO v_migration_run_id, v_catalog_sha256, v_requirement_count
    FROM platform.tenant_migration_requirement_catalogs AS catalog
    JOIN platform.release_generations AS release_row
      ON release_row.migration_run_id = catalog.migration_run_id
     AND release_row.release_id = catalog.release_id
     AND release_row.environment_id = catalog.environment_id
     AND release_row.database_origin = catalog.database_origin
     AND release_row.migration_manifest_sha256 =
         catalog.migration_manifest_sha256
    WHERE catalog.release_id = p_release_id
      AND catalog.environment_id = p_environment_id
      AND catalog.database_origin = p_database_origin
      AND catalog.migration_manifest_sha256 = p_migration_manifest_sha256
      AND catalog.contract_version =
          'tenant-migration-requirement-catalog.v2';

    IF NOT FOUND OR v_requirement_count < 1 THEN
        RETURN QUERY SELECT false, NULL::text, 0;
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM platform.tenant_migration_requirements AS requirement
        WHERE requirement.migration_run_id = v_migration_run_id
          AND NOT EXISTS (
              SELECT 1
              FROM platform.tenant_migration_checkpoints AS checkpoint
              WHERE checkpoint.tenant_id = p_tenant_id
                AND checkpoint.owner = requirement.owner
                AND checkpoint.logical_version = requirement.logical_version
                AND checkpoint.database_origin = requirement.database_origin
                AND checkpoint.selected_path = requirement.selected_path
                AND checkpoint.selected_sha256 = requirement.selected_sha256
                AND checkpoint.state = 'succeeded'
          )
    ) OR (
        SELECT pg_catalog.count(*)
        FROM platform.tenant_migration_requirements AS requirement
        WHERE requirement.migration_run_id = v_migration_run_id
    ) IS DISTINCT FROM v_requirement_count::bigint THEN
        RETURN QUERY SELECT false, v_catalog_sha256, v_requirement_count;
        RETURN;
    END IF;

    RETURN QUERY SELECT true, v_catalog_sha256, v_requirement_count;
END;
$$;


ALTER FUNCTION platform.platform_migrator_verify_new_tenant_v1(p_release_id uuid, p_environment_id uuid, p_database_origin text, p_tenant_id uuid, p_migration_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platform_migrator_verify_tenant_requirement_catalog_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_verify_tenant_requirement_catalog_v2(p_migration_run_id uuid, p_release_id uuid, p_environment_id uuid, p_database_origin text) RETURNS TABLE(verified boolean, catalog_sha256 text, requirement_count integer, target_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_catalog_sha256 text;
    v_requirement_count integer;
    v_target_count integer;
    v_migration_sha256 text;
    v_document jsonb;
    v_requirements jsonb;
    v_targets jsonb;
    v_live_targets jsonb;
BEGIN
    LOCK TABLE platform.release_generations,
        platform.tenant_migration_requirement_catalogs,
        platform.tenant_migration_requirements,
        platform.tenant_migration_requirement_targets,
        platform.tenants,
        platform.tenant_migration_checkpoints IN SHARE MODE;

    SELECT catalog.catalog_sha256, catalog.requirement_count,
           catalog.target_count, catalog.migration_manifest_sha256,
           pg_catalog.convert_from(catalog.canonical_document, 'UTF8')::jsonb
    INTO v_catalog_sha256, v_requirement_count, v_target_count,
         v_migration_sha256, v_document
    FROM platform.tenant_migration_requirement_catalogs AS catalog
    JOIN platform.release_generations AS release_row
      ON release_row.migration_run_id = catalog.migration_run_id
     AND release_row.release_id = catalog.release_id
     AND release_row.environment_id = catalog.environment_id
     AND release_row.database_origin = catalog.database_origin
     AND release_row.migration_manifest_sha256 = catalog.migration_manifest_sha256
    WHERE catalog.migration_run_id = p_migration_run_id
      AND catalog.release_id = p_release_id
      AND catalog.environment_id = p_environment_id
      AND catalog.database_origin = p_database_origin
      AND catalog.contract_version = 'tenant-migration-requirement-catalog.v2';
    IF NOT FOUND THEN
        RETURN QUERY SELECT false, NULL::text, 0, 0;
        RETURN;
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal', requirement.ordinal, 'owner', requirement.owner,
        'logical_version', requirement.logical_version,
        'database_origin', requirement.database_origin,
        'selected_path', requirement.selected_path,
        'selected_sha256', requirement.selected_sha256
    ) ORDER BY requirement.ordinal), '[]'::jsonb)
    INTO v_requirements
    FROM platform.tenant_migration_requirements AS requirement
    WHERE requirement.migration_run_id = p_migration_run_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal', target.ordinal, 'tenant_id', target.tenant_id::text,
        'schema_name', target.schema_name
    ) ORDER BY target.ordinal), '[]'::jsonb)
    INTO v_targets
    FROM platform.tenant_migration_requirement_targets AS target
    WHERE target.migration_run_id = p_migration_run_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal', live_target.ordinal, 'tenant_id', live_target.tenant_id,
        'schema_name', live_target.schema_name
    ) ORDER BY live_target.ordinal), '[]'::jsonb)
    INTO v_live_targets
    FROM (SELECT pg_catalog.row_number() OVER (ORDER BY tenant.id) AS ordinal,
                 tenant.id::text AS tenant_id, tenant.schema_name
          FROM platform.tenants AS tenant
          WHERE tenant.deleted_at IS NULL) AS live_target;

    IF pg_catalog.jsonb_typeof(v_document) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(v_document)) IS DISTINCT FROM 8::bigint OR
       v_document->>'contract_version' IS DISTINCT FROM 'tenant-migration-requirement-catalog.v2' OR
       v_document->>'migration_run_id' IS DISTINCT FROM p_migration_run_id::text OR
       v_document->>'release_id' IS DISTINCT FROM p_release_id::text OR
       v_document->>'environment_id' IS DISTINCT FROM p_environment_id::text OR
       v_document->>'database_origin' IS DISTINCT FROM p_database_origin OR
       pg_catalog.jsonb_typeof(v_document->'contract_version') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_document->'migration_run_id') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_document->'release_id') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_document->'environment_id') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_document->'database_origin') IS DISTINCT FROM 'string' OR
       pg_catalog.jsonb_typeof(v_document->'migration_manifest_sha256') IS DISTINCT FROM 'string' OR
       v_document->>'migration_manifest_sha256' IS DISTINCT FROM v_migration_sha256 OR
       pg_catalog.jsonb_typeof(v_document->'requirements') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_typeof(v_document->'targets') IS DISTINCT FROM 'array' OR
       v_document->'requirements' IS DISTINCT FROM v_requirements OR
       v_document->'targets' IS DISTINCT FROM v_targets OR
       v_targets IS DISTINCT FROM v_live_targets OR
       pg_catalog.jsonb_array_length(v_requirements) IS DISTINCT FROM v_requirement_count OR
       pg_catalog.jsonb_array_length(v_targets) IS DISTINCT FROM v_target_count THEN
        RETURN QUERY SELECT false, v_catalog_sha256, v_requirement_count, v_target_count;
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM platform.tenant_migration_requirement_targets AS target
        CROSS JOIN platform.tenant_migration_requirements AS requirement
        WHERE target.migration_run_id = p_migration_run_id
          AND requirement.migration_run_id = p_migration_run_id
          AND NOT EXISTS (
              SELECT 1 FROM platform.tenant_migration_checkpoints AS checkpoint
              WHERE checkpoint.tenant_id = target.tenant_id
                AND checkpoint.owner = requirement.owner
                AND checkpoint.logical_version = requirement.logical_version
                AND checkpoint.database_origin = requirement.database_origin
                AND checkpoint.selected_path = requirement.selected_path
                AND checkpoint.selected_sha256 = requirement.selected_sha256
                AND checkpoint.state = 'succeeded'
          )
    ) THEN
        RETURN QUERY SELECT false, v_catalog_sha256, v_requirement_count, v_target_count;
        RETURN;
    END IF;

    RETURN QUERY SELECT true, v_catalog_sha256, v_requirement_count, v_target_count;
END;
$$;


ALTER FUNCTION platform.platform_migrator_verify_tenant_requirement_catalog_v2(p_migration_run_id uuid, p_release_id uuid, p_environment_id uuid, p_database_origin text) OWNER TO harpy_owner;

--
-- Name: platform_migrator_verify_tenant_requirement_catalog_v3(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_verify_tenant_requirement_catalog_v3(p_migration_run_id uuid, p_release_id uuid, p_environment_id uuid, p_database_origin text) RETURNS TABLE(verified boolean, catalog_sha256 text, requirement_count integer, target_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_catalog_sha256 text;
    v_requirement_count integer;
    v_target_count integer;
    v_migration_sha256 text;
    v_document jsonb;
    v_requirements jsonb;
    v_targets jsonb;
    v_live_targets jsonb;
BEGIN
    LOCK TABLE platform.release_generations,
        platform.tenant_migration_requirement_catalogs,
        platform.tenant_migration_requirements,
        platform.tenant_migration_requirement_targets,
        platform.tenant_migration_supersessions,
        platform.tenants,
        platform.tenant_migration_checkpoints IN SHARE MODE;

    SELECT catalog.catalog_sha256,catalog.requirement_count,
           catalog.target_count,catalog.migration_manifest_sha256,
           pg_catalog.convert_from(catalog.canonical_document,'UTF8')::jsonb
    INTO v_catalog_sha256,v_requirement_count,v_target_count,
         v_migration_sha256,v_document
    FROM platform.tenant_migration_requirement_catalogs AS catalog
    JOIN platform.release_generations AS release_row
      ON release_row.migration_run_id = catalog.migration_run_id
     AND release_row.release_id = catalog.release_id
     AND release_row.environment_id = catalog.environment_id
     AND release_row.database_origin = catalog.database_origin
     AND release_row.migration_manifest_sha256 =
         catalog.migration_manifest_sha256
    WHERE catalog.migration_run_id = p_migration_run_id
      AND catalog.release_id = p_release_id
      AND catalog.environment_id = p_environment_id
      AND catalog.database_origin = p_database_origin
      AND catalog.contract_version =
          'tenant-migration-requirement-catalog.v2';
    IF NOT FOUND THEN
        RETURN QUERY SELECT false,NULL::text,0,0;
        RETURN;
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal',requirement.ordinal,'owner',requirement.owner,
        'logical_version',requirement.logical_version,
        'database_origin',requirement.database_origin,
        'selected_path',requirement.selected_path,
        'selected_sha256',requirement.selected_sha256
    ) ORDER BY requirement.ordinal),'[]'::jsonb)
    INTO v_requirements
    FROM platform.tenant_migration_requirements AS requirement
    WHERE requirement.migration_run_id = p_migration_run_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal',target.ordinal,'tenant_id',target.tenant_id::text,
        'schema_name',target.schema_name
    ) ORDER BY target.ordinal),'[]'::jsonb)
    INTO v_targets
    FROM platform.tenant_migration_requirement_targets AS target
    WHERE target.migration_run_id = p_migration_run_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal',live_target.ordinal,'tenant_id',live_target.tenant_id,
        'schema_name',live_target.schema_name
    ) ORDER BY live_target.ordinal),'[]'::jsonb)
    INTO v_live_targets
    FROM (
        SELECT pg_catalog.row_number() OVER (ORDER BY tenant.id) AS ordinal,
               tenant.id::text AS tenant_id,tenant.schema_name
        FROM platform.tenants AS tenant WHERE tenant.deleted_at IS NULL
    ) AS live_target;

    IF pg_catalog.jsonb_typeof(v_document) IS DISTINCT FROM 'object'
       OR (SELECT pg_catalog.count(*) FROM
           pg_catalog.jsonb_object_keys(v_document)) IS DISTINCT FROM 8::bigint
       OR v_document->>'contract_version' IS DISTINCT FROM
          'tenant-migration-requirement-catalog.v2'
       OR v_document->>'migration_run_id' IS DISTINCT FROM
          p_migration_run_id::text
       OR v_document->>'release_id' IS DISTINCT FROM p_release_id::text
       OR v_document->>'environment_id' IS DISTINCT FROM p_environment_id::text
       OR v_document->>'database_origin' IS DISTINCT FROM p_database_origin
       OR pg_catalog.jsonb_typeof(v_document->'contract_version') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'migration_run_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'release_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'environment_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'database_origin') <> 'string'
       OR pg_catalog.jsonb_typeof(
          v_document->'migration_manifest_sha256') <> 'string'
       OR v_document->>'migration_manifest_sha256' IS DISTINCT FROM
          v_migration_sha256
       OR pg_catalog.jsonb_typeof(v_document->'requirements') <> 'array'
       OR pg_catalog.jsonb_typeof(v_document->'targets') <> 'array'
       OR v_document->'requirements' IS DISTINCT FROM v_requirements
       OR v_document->'targets' IS DISTINCT FROM v_targets
       OR v_targets IS DISTINCT FROM v_live_targets
       OR pg_catalog.jsonb_array_length(v_requirements) IS DISTINCT FROM
          v_requirement_count
       OR pg_catalog.jsonb_array_length(v_targets) IS DISTINCT FROM
          v_target_count THEN
        RETURN QUERY SELECT false,v_catalog_sha256,
            v_requirement_count,v_target_count;
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM platform.tenant_migration_requirement_targets AS target
        CROSS JOIN platform.tenant_migration_requirements AS requirement
        WHERE target.migration_run_id = p_migration_run_id
          AND requirement.migration_run_id = p_migration_run_id
          AND NOT platform.platform_migrator_tenant_checkpoint_satisfies_v1(
              target.tenant_id,requirement.owner,
              requirement.logical_version,requirement.database_origin,
              requirement.selected_path,requirement.selected_sha256
          )
    ) THEN
        RETURN QUERY SELECT false,v_catalog_sha256,
            v_requirement_count,v_target_count;
        RETURN;
    END IF;

    RETURN QUERY SELECT true,v_catalog_sha256,
        v_requirement_count,v_target_count;
END;
$$;


ALTER FUNCTION platform.platform_migrator_verify_tenant_requirement_catalog_v3(p_migration_run_id uuid, p_release_id uuid, p_environment_id uuid, p_database_origin text) OWNER TO harpy_owner;

--
-- Name: platform_migrator_verify_tenant_requirement_catalog_v4(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_migrator_verify_tenant_requirement_catalog_v4(p_migration_run_id uuid, p_release_id uuid, p_environment_id uuid, p_database_origin text) RETURNS TABLE(verified boolean, catalog_sha256 text, requirement_count integer, target_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_catalog_sha256 text;
    v_requirement_count integer;
    v_target_count integer;
    v_migration_sha256 text;
    v_document jsonb;
    v_requirements jsonb;
    v_targets jsonb;
    v_live_targets jsonb;
BEGIN
    LOCK TABLE platform.release_generations,
        platform.tenant_migration_requirement_catalogs,
        platform.tenant_migration_requirements,
        platform.tenant_migration_requirement_targets,
        platform.tenant_migration_supersessions,
        platform.tenants,
        platform.tenant_migration_checkpoints IN SHARE MODE;

    SELECT catalog.catalog_sha256,catalog.requirement_count,
           catalog.target_count,catalog.migration_manifest_sha256,
           pg_catalog.convert_from(catalog.canonical_document,'UTF8')::jsonb
    INTO v_catalog_sha256,v_requirement_count,v_target_count,
         v_migration_sha256,v_document
    FROM platform.tenant_migration_requirement_catalogs AS catalog
    JOIN platform.release_generations AS release_row
      ON release_row.migration_run_id = catalog.migration_run_id
     AND release_row.release_id = catalog.release_id
     AND release_row.environment_id = catalog.environment_id
     AND release_row.database_origin = catalog.database_origin
     AND release_row.migration_manifest_sha256 =
         catalog.migration_manifest_sha256
    WHERE catalog.migration_run_id = p_migration_run_id
      AND catalog.release_id = p_release_id
      AND catalog.environment_id = p_environment_id
      AND catalog.database_origin = p_database_origin
      AND catalog.contract_version =
          'tenant-migration-requirement-catalog.v2';
    IF NOT FOUND THEN
        RETURN QUERY SELECT false,NULL::text,0,0;
        RETURN;
    END IF;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal',requirement.ordinal,'owner',requirement.owner,
        'logical_version',requirement.logical_version,
        'database_origin',requirement.database_origin,
        'selected_path',requirement.selected_path,
        'selected_sha256',requirement.selected_sha256
    ) ORDER BY requirement.ordinal),'[]'::jsonb)
    INTO v_requirements
    FROM platform.tenant_migration_requirements AS requirement
    WHERE requirement.migration_run_id = p_migration_run_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal',target.ordinal,'tenant_id',target.tenant_id::text,
        'schema_name',target.schema_name
    ) ORDER BY target.ordinal),'[]'::jsonb)
    INTO v_targets
    FROM platform.tenant_migration_requirement_targets AS target
    WHERE target.migration_run_id = p_migration_run_id;

    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal',live_target.ordinal,'tenant_id',live_target.tenant_id,
        'schema_name',live_target.schema_name
    ) ORDER BY live_target.ordinal),'[]'::jsonb)
    INTO v_live_targets
    FROM (
        SELECT pg_catalog.row_number() OVER (ORDER BY tenant.id) AS ordinal,
               tenant.id::text AS tenant_id,tenant.schema_name
        FROM platform.tenants AS tenant WHERE tenant.deleted_at IS NULL
    ) AS live_target;

    IF pg_catalog.jsonb_typeof(v_document) IS DISTINCT FROM 'object'
       OR (SELECT pg_catalog.count(*) FROM
           pg_catalog.jsonb_object_keys(v_document)) IS DISTINCT FROM 8::bigint
       OR v_document->>'contract_version' IS DISTINCT FROM
          'tenant-migration-requirement-catalog.v2'
       OR v_document->>'migration_run_id' IS DISTINCT FROM
          p_migration_run_id::text
       OR v_document->>'release_id' IS DISTINCT FROM p_release_id::text
       OR v_document->>'environment_id' IS DISTINCT FROM p_environment_id::text
       OR v_document->>'database_origin' IS DISTINCT FROM p_database_origin
       OR pg_catalog.jsonb_typeof(v_document->'contract_version') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'migration_run_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'release_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'environment_id') <> 'string'
       OR pg_catalog.jsonb_typeof(v_document->'database_origin') <> 'string'
       OR pg_catalog.jsonb_typeof(
          v_document->'migration_manifest_sha256') <> 'string'
       OR v_document->>'migration_manifest_sha256' IS DISTINCT FROM
          v_migration_sha256
       OR pg_catalog.jsonb_typeof(v_document->'requirements') <> 'array'
       OR pg_catalog.jsonb_typeof(v_document->'targets') <> 'array'
       OR v_document->'requirements' IS DISTINCT FROM v_requirements
       OR v_document->'targets' IS DISTINCT FROM v_targets
       OR v_targets IS DISTINCT FROM v_live_targets
       OR pg_catalog.jsonb_array_length(v_requirements) IS DISTINCT FROM
          v_requirement_count
       OR pg_catalog.jsonb_array_length(v_targets) IS DISTINCT FROM
          v_target_count THEN
        RETURN QUERY SELECT false,v_catalog_sha256,
            v_requirement_count,v_target_count;
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM platform.tenant_migration_requirement_targets AS target
        CROSS JOIN platform.tenant_migration_requirements AS requirement
        WHERE target.migration_run_id = p_migration_run_id
          AND requirement.migration_run_id = p_migration_run_id
          AND NOT platform.platform_migrator_tenant_checkpoint_satisfies_v2(
              target.tenant_id,requirement.owner,
              requirement.logical_version,requirement.database_origin,
              requirement.selected_path,requirement.selected_sha256
          )
    ) THEN
        RETURN QUERY SELECT false,v_catalog_sha256,
            v_requirement_count,v_target_count;
        RETURN;
    END IF;

    RETURN QUERY SELECT true,v_catalog_sha256,
        v_requirement_count,v_target_count;
END;
$$;


ALTER FUNCTION platform.platform_migrator_verify_tenant_requirement_catalog_v4(p_migration_run_id uuid, p_release_id uuid, p_environment_id uuid, p_database_origin text) OWNER TO harpy_owner;

