--
-- Name: platform_v1_environment_completion_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platform_v1_environment_completion_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_after jsonb;
    v_plan_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            IS DISTINCT FROM 'harpy-cutover/'||p_run_id::text
       OR p_scope_kind IS DISTINCT FROM 'global' OR p_scope_id IS NULL
       OR p_operation_id IS NULL OR p_run_id IS NULL
       OR p_relation_ordinal<1 OR p_checkpoint_key=''
       OR p_snapshot_lsn>p_commit_lsn OR p_received_lsn<p_commit_lsn
       OR p_batch_ordinal NOT BETWEEN 1 AND 2147483
       OR p_batch_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.jsonb_typeof(p_change_batch->'changes')<>'array'
       OR pg_catalog.jsonb_array_length(p_change_batch->'changes')<>1 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 environment completion apply denied';
    END IF;
    v_after := p_change_batch#>'{changes,0,after}';
    IF p_change_batch#>>'{changes,0,kind}' IS DISTINCT FROM 'insert'
       OR p_change_batch#>'{changes,0,before}' IS DISTINCT FROM 'null'::jsonb
       OR pg_catalog.jsonb_typeof(v_after)<>'object'
       OR (SELECT pg_catalog.array_agg(key ORDER BY key)
             FROM pg_catalog.jsonb_object_keys(v_after) AS key)
          IS DISTINCT FROM ARRAY['completed_at','contract_version','environment_id',
              'frontend_contract_sha256','legacy_boolean_hits',
              'module_migration_hits','operation_id','plan_sha256',
              'zero_hit_since']::text[]
       OR v_after->>'contract_version' IS DISTINCT FROM
            'platform-v1-environment-completion.v1'
       OR (v_after->>'operation_id')::uuid IS DISTINCT FROM p_operation_id
       OR (v_after->>'environment_id')::uuid IS DISTINCT FROM p_scope_id THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 environment completion document differs';
    END IF;
    v_plan_sha := v_after->>'plan_sha256';
    IF v_plan_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 environment completion plan differs';
    END IF;
    PERFORM platform.platform_cutover_complete_v1_adoption_v1(
        p_operation_id,p_scope_id,v_after->>'frontend_contract_sha256',
        (v_after->>'legacy_boolean_hits')::bigint,
        (v_after->>'module_migration_hits')::bigint,
        (v_after->>'zero_hit_since')::timestamptz,
        (v_after->>'completed_at')::timestamptz);
    applied_count := 1;
    key_state_sha256 := v_plan_sha;
    state_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        v_plan_sha||':'||(v_after->>'completed_at'),'UTF8')),'hex');
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.platform_v1_environment_completion_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

