--
-- Name: platformauthority_commit_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_commit_v1(p_operation_id uuid, p_completed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.platformauthority_operations%ROWTYPE;
    v_count integer;
    v_signer_status text;
    v_signer_kid text;
    v_proposal_signer_kid text;
BEGIN
    SELECT * INTO v_operation FROM platform.platformauthority_operations
    WHERE operation_id = p_operation_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'protected authority operation is missing';
    END IF;
    IF v_operation.status = 'completed' THEN
        RETURN;
    END IF;
    SELECT signer_status, signer_kid INTO v_signer_status, v_signer_kid
    FROM platform.platformauthority_bindings
    WHERE binding_id = v_operation.binding_id FOR UPDATE;
    v_proposal_signer_kid := convert_from(v_operation.proposal_bytes, 'UTF8')::jsonb->>'signer_kid';
    IF NOT FOUND OR v_signer_status <> 'active' OR
       v_signer_kid IS DISTINCT FROM v_proposal_signer_kid THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority signer is fenced';
    END IF;
    IF v_operation.status <> 'ack_verified' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority ack is not verified';
    END IF;
    INSERT INTO platform.platformauthority_heads (
        binding_id, scope_kind, scope_id, generation, previous_head_sha256,
        state_sha256, proposal_sha256, ack_sha256, registry_sequence, updated_at
    ) VALUES (
        v_operation.binding_id, v_operation.scope_kind, v_operation.scope_id,
        v_operation.generation, v_operation.previous_head_sha256,
        v_operation.state_sha256, v_operation.proposal_sha256,
        v_operation.ack_sha256, v_operation.registry_sequence, p_completed_at
    ) ON CONFLICT (binding_id, scope_kind, scope_id) DO UPDATE SET
        generation = EXCLUDED.generation,
        previous_head_sha256 = EXCLUDED.previous_head_sha256,
        state_sha256 = EXCLUDED.state_sha256,
        proposal_sha256 = EXCLUDED.proposal_sha256,
        ack_sha256 = EXCLUDED.ack_sha256,
        registry_sequence = EXCLUDED.registry_sequence,
        updated_at = EXCLUDED.updated_at
    WHERE platform.platformauthority_heads.generation = EXCLUDED.generation - 1
      AND platform.platformauthority_heads.ack_sha256 = EXCLUDED.previous_head_sha256;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count <> 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'protected authority head CAS is stale';
    END IF;
    UPDATE platform.platformauthority_operations
    SET status = 'completed', completed_at = p_completed_at,
        revision = revision + 1, updated_at = p_completed_at
    WHERE operation_id = p_operation_id;
    INSERT INTO platform.platformauthority_receipts (
        operation_id, binding_id, scope_kind, scope_id, generation, state_sha256,
        proposal_sha256, ack_sha256, registry_sequence, completed_at
    ) VALUES (
        v_operation.operation_id, v_operation.binding_id, v_operation.scope_kind,
        v_operation.scope_id, v_operation.generation, v_operation.state_sha256,
        v_operation.proposal_sha256, v_operation.ack_sha256,
        v_operation.registry_sequence, p_completed_at
    );
END;
$$;


ALTER FUNCTION platform.platformauthority_commit_v1(p_operation_id uuid, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformauthority_delivery_await_import_v1(uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_delivery_await_import_v1(p_operation_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    UPDATE platform.platformauthority_delivery_jobs AS job
       SET state='awaiting_import',lease_owner_id=NULL,lease_until=NULL,
           last_error_code=NULL,updated_at=v_now
     WHERE job.operation_id=p_operation_id AND job.state='running'
       AND job.lease_owner_id=p_lease_owner_id
       AND job.lease_generation=p_lease_generation AND job.lease_until>v_now
       AND EXISTS (
           SELECT 1 FROM platform.platformauthority_operations AS authority
            WHERE authority.operation_id=job.operation_id
              AND authority.status<>'completed'
       );
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='protected authority delivery lease is stale';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformauthority_delivery_await_import_v1(p_operation_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) OWNER TO harpy_owner;

--
-- Name: platformauthority_delivery_claim_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_delivery_claim_v1(p_lease_owner_id uuid) RETURNS TABLE(operation_id uuid, lease_generation bigint, attempt integer, max_attempts integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_operation_id uuid;
BEGIN
    IF p_lease_owner_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='protected authority delivery owner is invalid';
    END IF;
    INSERT INTO platform.platformauthority_delivery_jobs (
        operation_id,state,next_attempt_at,created_at,updated_at
    )
    SELECT authority.operation_id,'queued',v_now,v_now,v_now
      FROM platform.platformauthority_operations AS authority
     WHERE authority.purpose NOT IN (
        'initial_environment_authority','initial_tenant_authority'
     )
    ON CONFLICT ON CONSTRAINT platformauthority_delivery_jobs_pkey DO NOTHING;

    UPDATE platform.platformauthority_delivery_jobs AS job
       SET state=CASE WHEN job.attempts>=job.max_attempts THEN 'dead' ELSE 'queued' END,
           lease_owner_id=NULL,lease_until=NULL,
           next_attempt_at=CASE WHEN job.attempts>=job.max_attempts
               THEN job.next_attempt_at ELSE v_now END,
           last_error_code='LEASE_EXPIRED',updated_at=v_now
     WHERE job.state='running' AND job.lease_until<=v_now;

    SELECT job.operation_id INTO v_operation_id
      FROM platform.platformauthority_delivery_jobs AS job
      JOIN platform.platformauthority_operations AS authority
        ON authority.operation_id=job.operation_id
     WHERE (job.state='queued' AND job.next_attempt_at<=v_now)
        OR (job.state='awaiting_import' AND authority.status='completed')
     ORDER BY job.next_attempt_at,job.operation_id
     FOR UPDATE OF job SKIP LOCKED
     LIMIT 1;
    IF v_operation_id IS NULL THEN RETURN; END IF;

    RETURN QUERY
    UPDATE platform.platformauthority_delivery_jobs AS job
       SET state='running',attempts=job.attempts+1,
           lease_generation=job.lease_generation+1,
           lease_owner_id=p_lease_owner_id,lease_until=v_now+interval '60 seconds',
           last_error_code=NULL,updated_at=v_now
     WHERE job.operation_id=v_operation_id
     RETURNING job.operation_id,job.lease_generation,job.attempts,job.max_attempts;
END;
$$;


ALTER FUNCTION platform.platformauthority_delivery_claim_v1(p_lease_owner_id uuid) OWNER TO harpy_owner;

--
-- Name: platformauthority_delivery_retry_v1(uuid, uuid, bigint, text, boolean); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_delivery_retry_v1(p_operation_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_error_code text, p_permanent boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.platformauthority_delivery_jobs%ROWTYPE;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_error_code !~ '^[A-Z][A-Z0-9_]{0,127}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='protected authority delivery error code is invalid';
    END IF;
    SELECT * INTO v_job FROM platform.platformauthority_delivery_jobs AS job
     WHERE job.operation_id=p_operation_id FOR UPDATE;
    IF NOT FOUND OR v_job.state<>'running' OR
       v_job.lease_owner_id<>p_lease_owner_id OR
       v_job.lease_generation<>p_lease_generation OR v_job.lease_until<=v_now THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='protected authority delivery lease is stale';
    END IF;
    UPDATE platform.platformauthority_delivery_jobs
       SET state=CASE WHEN p_permanent OR attempts>=max_attempts
           THEN 'dead' ELSE 'queued' END,
           lease_owner_id=NULL,lease_until=NULL,last_error_code=p_error_code,
           next_attempt_at=CASE WHEN p_permanent OR attempts>=max_attempts
               THEN next_attempt_at
               ELSE v_now+pg_catalog.make_interval(
                   secs=>LEAST(300,1 << (attempts-1))) END,
           updated_at=v_now
     WHERE operation_id=p_operation_id;
END;
$_$;


ALTER FUNCTION platform.platformauthority_delivery_retry_v1(p_operation_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_error_code text, p_permanent boolean) OWNER TO harpy_owner;

--
-- Name: platformauthority_delivery_succeed_v1(uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_delivery_succeed_v1(p_operation_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    UPDATE platform.platformauthority_delivery_jobs AS job
       SET state='succeeded',lease_owner_id=NULL,lease_until=NULL,
           last_error_code=NULL,completed_at=v_now,updated_at=v_now
     WHERE job.operation_id=p_operation_id AND job.state='running'
       AND job.lease_owner_id=p_lease_owner_id
       AND job.lease_generation=p_lease_generation AND job.lease_until>v_now
       AND EXISTS (
           SELECT 1 FROM platform.platformauthority_operations AS authority
            WHERE authority.operation_id=job.operation_id
              AND authority.status='completed'
       );
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='protected authority delivery lease is stale';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformauthority_delivery_succeed_v1(p_operation_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) OWNER TO harpy_owner;

--
-- Name: platformauthority_development_binding_input_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_development_binding_input_v1(p_environment_id uuid) RETURNS TABLE(operation_id uuid, registry_binding_id uuid, finalization_receipt_sha256 text, recovery_trust_bundle_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'development authority binding input denied';
    END IF;
    RETURN QUERY
    SELECT operation.operation_id, owner_binding.registry_binding_id,
        receipt.receipt_sha256, operation.recovery_trust_bundle_sha256
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.platformauthority_installation_owner_bindings AS owner_binding
      ON owner_binding.operation_id = operation.operation_id
     AND owner_binding.environment_id = operation.environment_id
     AND owner_binding.registry_binding_id = operation.registry_binding_id
    JOIN platform.tenancy_onboarding_receipts AS receipt
      ON receipt.operation_id = operation.operation_id
     AND receipt.receipt_kind = 'activation_completed'
    JOIN platform.platformops_installation_recovery_identities AS recovery
      ON recovery.operation_id = operation.operation_id
     AND recovery.environment_id = operation.environment_id
     AND recovery.trust_bundle_sha256 = operation.recovery_trust_bundle_sha256
    WHERE operation.environment_id = p_environment_id
      AND operation.operation_kind = 'environment_initialize'
      AND operation.deployment_mode = 'onpremise'
      AND operation.state = 'succeeded';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'completed development authority binding input is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformauthority_development_binding_input_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: platformauthority_fence_signer_v1(uuid, bigint, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_fence_signer_v1(p_binding_id uuid, p_expected_generation bigint, p_expected_kid text, p_evidence_sha256 text, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_binding platform.platformauthority_bindings%ROWTYPE;
BEGIN
    SELECT * INTO v_binding FROM platform.platformauthority_bindings
    WHERE binding_id = p_binding_id FOR UPDATE;
    IF v_binding.signer_status = 'rekey_required' AND
       v_binding.signer_generation = p_expected_generation AND v_binding.signer_kid = p_expected_kid THEN
        RETURN;
    END IF;
    IF NOT FOUND OR v_binding.signer_status <> 'active' OR
       v_binding.signer_generation <> p_expected_generation OR v_binding.signer_kid <> p_expected_kid THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'protected authority signer fence is stale';
    END IF;
    UPDATE platform.platformauthority_bindings SET signer_status = 'rekey_required'
    WHERE binding_id = p_binding_id;
    INSERT INTO platform.platformauthority_signer_events (
        binding_id, signer_generation, signer_kid, signer_public_key_sha256,
        event_kind, evidence_sha256, occurred_at
    ) VALUES (p_binding_id, v_binding.signer_generation, v_binding.signer_kid,
        v_binding.signer_public_key_sha256, 'revoked', p_evidence_sha256, p_now);
END;
$$;


ALTER FUNCTION platform.platformauthority_fence_signer_v1(p_binding_id uuid, p_expected_generation bigint, p_expected_kid text, p_evidence_sha256 text, p_now timestamp with time zone) OWNER TO harpy_owner;

