--
-- Name: platformauthority_guard_binding_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_guard_binding_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' OR ROW(NEW.binding_id, NEW.environment_id, NEW.deployment_mode,
        NEW.registry_kind, NEW.license_binding_id, NEW.finalization_receipt_sha256,
        NEW.proof_sha256, NEW.proof_bytes, NEW.created_at)
        IS DISTINCT FROM ROW(OLD.binding_id, OLD.environment_id, OLD.deployment_mode,
        OLD.registry_kind, OLD.license_binding_id, OLD.finalization_receipt_sha256,
        OLD.proof_sha256, OLD.proof_bytes, OLD.created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority binding identity is immutable';
    END IF;
    IF NOT (
        (OLD.signer_status = 'active' AND NEW.signer_status = 'rekey_required'
            AND NEW.signer_generation = OLD.signer_generation
            AND NEW.signer_kid = OLD.signer_kid
            AND NEW.signer_public_key_sha256 = OLD.signer_public_key_sha256
            AND NEW.recovery_trust_bundle_sha256 IS NOT DISTINCT FROM
                OLD.recovery_trust_bundle_sha256)
        OR (NEW.signer_status = 'active' AND NEW.signer_generation = OLD.signer_generation + 1
            AND NEW.signer_kid <> OLD.signer_kid
            AND NEW.signer_public_key_sha256 <> OLD.signer_public_key_sha256
            AND ((NEW.deployment_mode = 'onpremise' AND
                    NEW.recovery_trust_bundle_sha256 <> OLD.recovery_trust_bundle_sha256)
                OR (NEW.deployment_mode = 'saas' AND
                    NEW.recovery_trust_bundle_sha256 IS NULL)))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority signer transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformauthority_guard_binding_v2() OWNER TO harpy_owner;

--
-- Name: platformauthority_guard_head_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_guard_head_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority head delete is forbidden';
    END IF;
    IF ROW(NEW.binding_id, NEW.scope_kind, NEW.scope_id) IS DISTINCT FROM
       ROW(OLD.binding_id, OLD.scope_kind, OLD.scope_id) OR
       NEW.generation <> OLD.generation + 1 OR
       NEW.previous_head_sha256 IS DISTINCT FROM OLD.ack_sha256 OR
       NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'protected authority head CAS is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformauthority_guard_head_v1() OWNER TO harpy_owner;

--
-- Name: platformauthority_guard_operation_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_guard_operation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority operation delete is forbidden';
    END IF;
    IF ROW(NEW.operation_id, NEW.binding_id, NEW.purpose, NEW.scope_kind, NEW.scope_id,
        NEW.generation, NEW.previous_head_sha256, NEW.state_sha256, NEW.state_bytes,
        NEW.proposal_sha256, NEW.proposal_bytes, NEW.compensates_ack_sha256,
        NEW.issued_at, NEW.expires_at, NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.operation_id, OLD.binding_id, OLD.purpose, OLD.scope_kind, OLD.scope_id,
        OLD.generation, OLD.previous_head_sha256, OLD.state_sha256, OLD.state_bytes,
        OLD.proposal_sha256, OLD.proposal_bytes, OLD.compensates_ack_sha256,
        OLD.issued_at, OLD.expires_at, OLD.created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority plan is immutable';
    END IF;
    IF NEW.revision <> OLD.revision + 1 OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'protected authority revision is stale';
    END IF;
    IF NOT ((OLD.status = 'proposal_signed' AND NEW.status = 'ack_verified') OR
            (OLD.status = 'ack_verified' AND NEW.status = 'completed')) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformauthority_guard_operation_v1() OWNER TO harpy_owner;

--
-- Name: platformauthority_installation_head_pin_v1(uuid, uuid, uuid, name, uuid, text, uuid, bigint, text, text, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_installation_head_pin_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_authority_operation platform.platformauthority_operations%ROWTYPE;
    v_head platform.platformauthority_heads%ROWTYPE;
    v_existing platform.platformauthority_installation_head_pins%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_schema_name IS NULL
       OR p_registry_binding_id IS NULL OR p_scope_kind IS DISTINCT FROM 'environment'
       OR p_scope_id IS DISTINCT FROM p_environment_id OR p_generation < 1
       OR ((p_generation = 1) IS DISTINCT FROM (p_previous_head_sha256 IS NULL))
       OR (p_previous_head_sha256 IS NOT NULL
            AND p_previous_head_sha256 !~ '^[0-9a-f]{64}$')
       OR p_state_sha256 !~ '^[0-9a-f]{64}$'
       OR p_proposal_sha256 !~ '^[0-9a-f]{64}$'
       OR p_ack_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation authority head pin denied';
    END IF;
    IF NOT platform.tenancy_activation_assert_v1(
        p_operation_id, p_tenant_id, p_schema_name
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'installation authority activation conflicts';
    END IF;
    SELECT * INTO v_authority_operation
    FROM platform.platformauthority_operations AS authority_operation
    WHERE authority_operation.ack_sha256 = p_ack_sha256
    FOR UPDATE;
    IF NOT FOUND
       OR v_authority_operation.binding_id IS DISTINCT FROM p_registry_binding_id
       OR v_authority_operation.purpose IS DISTINCT FROM 'initial_environment_authority'
       OR v_authority_operation.scope_kind IS DISTINCT FROM p_scope_kind
       OR v_authority_operation.scope_id IS DISTINCT FROM p_scope_id
       OR v_authority_operation.generation IS DISTINCT FROM p_generation
       OR v_authority_operation.previous_head_sha256
            IS DISTINCT FROM p_previous_head_sha256
       OR v_authority_operation.state_sha256 IS DISTINCT FROM p_state_sha256
       OR v_authority_operation.proposal_sha256 IS DISTINCT FROM p_proposal_sha256
       OR v_authority_operation.status NOT IN ('ack_verified', 'completed') THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'verified protected authority operation conflicts';
    END IF;
    IF v_authority_operation.status = 'ack_verified' THEN
        PERFORM platform.platformauthority_commit_v1(
            v_authority_operation.operation_id,
            pg_catalog.statement_timestamp()
        );
    END IF;
    SELECT * INTO v_head
    FROM platform.platformauthority_heads AS head
    WHERE head.binding_id = p_registry_binding_id
      AND head.scope_kind = p_scope_kind
      AND head.scope_id = p_scope_id
    FOR SHARE;
    IF NOT FOUND OR ROW(v_head.generation, v_head.previous_head_sha256,
        v_head.state_sha256, v_head.proposal_sha256, v_head.ack_sha256)
       IS DISTINCT FROM ROW(p_generation, p_previous_head_sha256,
        p_state_sha256, p_proposal_sha256, p_ack_sha256) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'protected authority head conflicts';
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformauthority_installation_head_pins AS pin
    WHERE pin.operation_id = p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF ROW(v_existing.registry_binding_id, v_existing.scope_kind,
            v_existing.scope_id, v_existing.generation,
            v_existing.previous_head_sha256, v_existing.state_sha256,
            v_existing.proposal_sha256, v_existing.ack_sha256,
            v_existing.manifest_sha256)
           IS DISTINCT FROM ROW(p_registry_binding_id, p_scope_kind,
            p_scope_id, p_generation, p_previous_head_sha256,
            p_state_sha256, p_proposal_sha256, p_ack_sha256,
            p_manifest_sha256) THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'installation authority head replay conflicts';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.platformauthority_installation_head_pins (
        operation_id, registry_binding_id, scope_kind, scope_id,
        generation, previous_head_sha256, state_sha256,
        proposal_sha256, ack_sha256, manifest_sha256, pinned_at
    ) VALUES (
        p_operation_id, p_registry_binding_id, p_scope_kind, p_scope_id,
        p_generation, p_previous_head_sha256, p_state_sha256,
        p_proposal_sha256, p_ack_sha256, p_manifest_sha256,
        pg_catalog.statement_timestamp()
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.platformauthority_installation_head_pin_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformauthority_installation_head_pin_v2(uuid, uuid, uuid, name, uuid, text, uuid, bigint, text, text, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_installation_head_pin_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_authority_operation platform.platformauthority_operations%ROWTYPE;
    v_head platform.platformauthority_heads%ROWTYPE;
    v_existing platform.platformauthority_installation_head_pins%ROWTYPE;
    v_purpose text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_schema_name IS NULL
       OR p_registry_binding_id IS NULL
       OR p_scope_kind NOT IN ('environment', 'tenant')
       OR (p_scope_kind = 'environment'
           AND p_scope_id IS DISTINCT FROM p_environment_id)
       OR (p_scope_kind = 'tenant'
           AND p_scope_id IS DISTINCT FROM p_tenant_id)
       OR p_generation < 1
       OR ((p_generation = 1) IS DISTINCT FROM (p_previous_head_sha256 IS NULL))
       OR (p_previous_head_sha256 IS NOT NULL
           AND p_previous_head_sha256 !~ '^[0-9a-f]{64}$')
       OR p_state_sha256 !~ '^[0-9a-f]{64}$'
       OR p_proposal_sha256 !~ '^[0-9a-f]{64}$'
       OR p_ack_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation authority head pin denied';
    END IF;
    IF NOT platform.tenancy_activation_assert_v2(
        p_operation_id, p_tenant_id, p_schema_name
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'installation authority activation conflicts';
    END IF;
    v_purpose := CASE p_scope_kind
        WHEN 'environment' THEN 'initial_environment_authority'
        ELSE 'initial_tenant_authority'
    END;
    SELECT * INTO v_authority_operation
    FROM platform.platformauthority_operations AS authority_operation
    WHERE authority_operation.ack_sha256 = p_ack_sha256
    FOR UPDATE;
    IF NOT FOUND
       OR v_authority_operation.binding_id IS DISTINCT FROM p_registry_binding_id
       OR v_authority_operation.purpose IS DISTINCT FROM v_purpose
       OR v_authority_operation.scope_kind IS DISTINCT FROM p_scope_kind
       OR v_authority_operation.scope_id IS DISTINCT FROM p_scope_id
       OR v_authority_operation.generation IS DISTINCT FROM p_generation
       OR v_authority_operation.previous_head_sha256
            IS DISTINCT FROM p_previous_head_sha256
       OR v_authority_operation.state_sha256 IS DISTINCT FROM p_state_sha256
       OR v_authority_operation.proposal_sha256 IS DISTINCT FROM p_proposal_sha256
       OR v_authority_operation.status NOT IN ('ack_verified', 'completed') THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'verified protected authority operation conflicts';
    END IF;
    IF v_authority_operation.status = 'ack_verified' THEN
        PERFORM platform.platformauthority_commit_v1(
            v_authority_operation.operation_id,
            pg_catalog.statement_timestamp()
        );
    END IF;
    SELECT * INTO v_head
    FROM platform.platformauthority_heads AS head
    WHERE head.binding_id = p_registry_binding_id
      AND head.scope_kind = p_scope_kind AND head.scope_id = p_scope_id
    FOR SHARE;
    IF NOT FOUND OR ROW(v_head.generation, v_head.previous_head_sha256,
        v_head.state_sha256, v_head.proposal_sha256, v_head.ack_sha256)
       IS DISTINCT FROM ROW(p_generation, p_previous_head_sha256,
        p_state_sha256, p_proposal_sha256, p_ack_sha256) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'protected authority head conflicts';
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformauthority_installation_head_pins AS pin
    WHERE pin.operation_id = p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF ROW(v_existing.registry_binding_id, v_existing.scope_kind,
            v_existing.scope_id, v_existing.generation,
            v_existing.previous_head_sha256, v_existing.state_sha256,
            v_existing.proposal_sha256, v_existing.ack_sha256,
            v_existing.manifest_sha256)
           IS DISTINCT FROM ROW(p_registry_binding_id, p_scope_kind,
            p_scope_id, p_generation, p_previous_head_sha256,
            p_state_sha256, p_proposal_sha256, p_ack_sha256,
            p_manifest_sha256) THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'installation authority head replay conflicts';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.platformauthority_installation_head_pins (
        operation_id, registry_binding_id, scope_kind, scope_id,
        generation, previous_head_sha256, state_sha256,
        proposal_sha256, ack_sha256, manifest_sha256, pinned_at
    ) VALUES (
        p_operation_id, p_registry_binding_id, p_scope_kind, p_scope_id,
        p_generation, p_previous_head_sha256, p_state_sha256,
        p_proposal_sha256, p_ack_sha256, p_manifest_sha256,
        pg_catalog.statement_timestamp()
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.platformauthority_installation_head_pin_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformauthority_installation_head_pin_v3(uuid, uuid, uuid, name, uuid, text, uuid, bigint, text, text, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_installation_head_pin_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_authority_operation platform.platformauthority_operations%ROWTYPE;
    v_head platform.platformauthority_heads%ROWTYPE;
    v_existing platform.platformauthority_installation_head_pins%ROWTYPE;
    v_operation_kind text;
    v_purpose text;
    v_replayed boolean := false;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_schema_name IS NULL
       OR p_registry_binding_id IS NULL OR p_scope_kind IS NULL
       OR p_scope_id IS NULL
       OR p_scope_kind NOT IN ('environment', 'tenant')
       OR (p_scope_kind = 'environment'
           AND p_scope_id IS DISTINCT FROM p_environment_id)
       OR (p_scope_kind = 'tenant'
           AND p_scope_id IS DISTINCT FROM p_tenant_id)
       OR p_generation IS NULL OR p_generation < 1
       OR ((p_generation = 1) IS DISTINCT FROM
           (p_previous_head_sha256 IS NULL))
       OR (p_previous_head_sha256 IS NOT NULL
           AND p_previous_head_sha256 !~ '^[0-9a-f]{64}$')
       OR p_state_sha256 IS NULL
       OR p_state_sha256 !~ '^[0-9a-f]{64}$'
       OR p_proposal_sha256 IS NULL
       OR p_proposal_sha256 !~ '^[0-9a-f]{64}$'
       OR p_ack_sha256 IS NULL
       OR p_ack_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 IS NULL
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation authority head pin denied';
    END IF;
    v_operation_kind := CASE p_scope_kind
        WHEN 'environment' THEN 'environment_initialize'
        ELSE 'saas_customer_tenant_provision'
    END;
    v_purpose := CASE p_scope_kind
        WHEN 'environment' THEN 'initial_environment_authority'
        ELSE 'initial_tenant_authority'
    END;
    IF NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id,
        'platformauthority.pin_protected_authority_head',
        p_environment_id, p_tenant_id, p_schema_name,
        v_operation_kind
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation authority head capability required';
    END IF;
    SELECT * INTO v_authority_operation
    FROM platform.platformauthority_operations AS authority_operation
    WHERE authority_operation.ack_sha256 = p_ack_sha256
    FOR UPDATE;
    IF NOT FOUND
       OR v_authority_operation.binding_id
            IS DISTINCT FROM p_registry_binding_id
       OR v_authority_operation.purpose IS DISTINCT FROM v_purpose
       OR v_authority_operation.scope_kind IS DISTINCT FROM p_scope_kind
       OR v_authority_operation.scope_id IS DISTINCT FROM p_scope_id
       OR v_authority_operation.generation IS DISTINCT FROM p_generation
       OR v_authority_operation.previous_head_sha256
            IS DISTINCT FROM p_previous_head_sha256
       OR v_authority_operation.state_sha256 IS DISTINCT FROM p_state_sha256
       OR v_authority_operation.proposal_sha256
            IS DISTINCT FROM p_proposal_sha256
       OR v_authority_operation.status NOT IN ('ack_verified', 'completed') THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'verified protected authority operation conflicts';
    END IF;
    IF v_authority_operation.status = 'ack_verified' THEN
        PERFORM platform.platformauthority_commit_v1(
            v_authority_operation.operation_id,
            pg_catalog.statement_timestamp()
        );
    END IF;
    SELECT * INTO v_head
    FROM platform.platformauthority_heads AS head
    WHERE head.binding_id = p_registry_binding_id
      AND head.scope_kind = p_scope_kind AND head.scope_id = p_scope_id
    FOR SHARE;
    IF NOT FOUND OR ROW(v_head.generation, v_head.previous_head_sha256,
        v_head.state_sha256, v_head.proposal_sha256, v_head.ack_sha256)
       IS DISTINCT FROM ROW(p_generation, p_previous_head_sha256,
        p_state_sha256, p_proposal_sha256, p_ack_sha256) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'protected authority head conflicts';
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformauthority_installation_head_pins AS pin
    WHERE pin.operation_id = p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF ROW(v_existing.registry_binding_id, v_existing.scope_kind,
            v_existing.scope_id, v_existing.generation,
            v_existing.previous_head_sha256, v_existing.state_sha256,
            v_existing.proposal_sha256, v_existing.ack_sha256,
            v_existing.manifest_sha256)
           IS DISTINCT FROM ROW(p_registry_binding_id, p_scope_kind,
            p_scope_id, p_generation, p_previous_head_sha256,
            p_state_sha256, p_proposal_sha256, p_ack_sha256,
            p_manifest_sha256) THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'installation authority head replay conflicts';
        END IF;
        v_replayed := true;
    ELSE
        INSERT INTO platform.platformauthority_installation_head_pins (
            operation_id, registry_binding_id, scope_kind, scope_id,
            generation, previous_head_sha256, state_sha256,
            proposal_sha256, ack_sha256, manifest_sha256, pinned_at
        ) VALUES (
            p_operation_id, p_registry_binding_id, p_scope_kind, p_scope_id,
            p_generation, p_previous_head_sha256, p_state_sha256,
            p_proposal_sha256, p_ack_sha256, p_manifest_sha256,
            pg_catalog.statement_timestamp()
        );
    END IF;
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id,
        'platformauthority.pin_protected_authority_head'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation authority head capability consume failed';
    END IF;
    RETURN v_replayed;
END;
$_$;


ALTER FUNCTION platform.platformauthority_installation_head_pin_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformauthority_installation_owner_bind_v1(uuid, uuid, uuid, name, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_installation_owner_bind_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_instance_owner_binding_id uuid, p_protected_admin_binding_id uuid, p_registry_binding_id uuid, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.platformauthority_installation_owner_bindings%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_schema_name IS NULL
       OR p_instance_owner_binding_id IS NULL OR p_protected_admin_binding_id IS NULL
       OR p_registry_binding_id IS NULL
       OR p_deployment_mode NOT IN ('onpremise', 'saas')
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation owner binding denied';
    END IF;
    IF NOT platform.tenancy_activation_assert_v1(
        p_operation_id, p_tenant_id, p_schema_name
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'installation owner activation conflicts';
    END IF;
    PERFORM 1
    FROM platform.platformauthority_bindings AS binding
    WHERE binding.binding_id = p_registry_binding_id
      AND binding.environment_id = p_environment_id
      AND binding.deployment_mode = p_deployment_mode
      AND binding.signer_status = 'active'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'protected authority binding is not active';
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformauthority_installation_owner_bindings AS owner_binding
    WHERE owner_binding.operation_id = p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF ROW(v_existing.environment_id, v_existing.tenant_id,
            v_existing.instance_owner_binding_id,
            v_existing.protected_admin_binding_id,
            v_existing.registry_binding_id, v_existing.manifest_sha256)
           IS DISTINCT FROM ROW(p_environment_id, p_tenant_id,
            p_instance_owner_binding_id, p_protected_admin_binding_id,
            p_registry_binding_id, p_manifest_sha256) THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'installation owner binding replay conflicts';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.platformauthority_installation_owner_bindings (
        operation_id, environment_id, tenant_id, instance_owner_binding_id,
        protected_admin_binding_id, registry_binding_id,
        manifest_sha256, created_at
    ) VALUES (
        p_operation_id, p_environment_id, p_tenant_id,
        p_instance_owner_binding_id, p_protected_admin_binding_id,
        p_registry_binding_id, p_manifest_sha256,
        pg_catalog.statement_timestamp()
    );
    RETURN false;
END;
$_$;


