--

CREATE FUNCTION platform.platformauthority_installation_owner_bind_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_instance_owner_binding_id uuid, p_protected_admin_binding_id uuid, p_registry_binding_id uuid, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.platformauthority_installation_owner_bindings%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_schema_name IS NULL
