            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'protected authority binding is not active';
        END IF;
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformauthority_installation_owner_bindings AS owner_binding
    WHERE owner_binding.operation_id = p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF ROW(v_existing.environment_id, v_existing.tenant_id,
            v_existing.instance_owner_binding_id,
            v_existing.protected_admin_binding_id,
            v_existing.registry_binding_id, v_existing.manifest_sha256)
           IS DISTINCT FROM ROW(p_environment_id, p_tenant_id,
            p_instance_owner_binding_id, p_protected_admin_binding_id,
            p_registry_binding_id, p_manifest_sha256) THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'installation owner binding replay conflicts';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.platformauthority_installation_owner_bindings (
        operation_id, environment_id, tenant_id, instance_owner_binding_id,
        protected_admin_binding_id, registry_binding_id,
        manifest_sha256, created_at
    ) VALUES (
        p_operation_id, p_environment_id, p_tenant_id,
        p_instance_owner_binding_id, p_protected_admin_binding_id,
        p_registry_binding_id, p_manifest_sha256,
        pg_catalog.statement_timestamp()
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.platformauthority_installation_owner_bind_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_instance_owner_binding_id uuid, p_protected_admin_binding_id uuid, p_registry_binding_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformauthority_installation_owner_bind_v3(uuid, uuid, uuid, name, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_installation_owner_bind_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_instance_owner_binding_id uuid, p_protected_admin_binding_id uuid, p_registry_binding_id uuid, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id, 'platformauthority.bind_owner',
        p_environment_id, p_tenant_id, p_schema_name,
        'environment_initialize'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation owner capability required';
    END IF;
    RETURN platform.platformauthority_installation_owner_bind_v2(
        p_operation_id, p_environment_id, p_tenant_id, p_schema_name,
        p_deployment_mode, p_instance_owner_binding_id,
        p_protected_admin_binding_id, p_registry_binding_id,
        p_manifest_sha256
    );
END;
$$;


ALTER FUNCTION platform.platformauthority_installation_owner_bind_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_instance_owner_binding_id uuid, p_protected_admin_binding_id uuid, p_registry_binding_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformauthority_prepare_v1(uuid, uuid, text, text, uuid, bigint, text, text, bytea, text, bytea, text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_prepare_v1(p_operation_id uuid, p_binding_id uuid, p_purpose text, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_state_bytes bytea, p_proposal_sha256 text, p_proposal_bytes bytea, p_compensates_ack_sha256 text, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_generation bigint;
    v_ack_sha256 text;
    v_exact boolean;
BEGIN
    PERFORM 1 FROM platform.platformauthority_bindings WHERE binding_id = p_binding_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'protected authority binding is missing';
    END IF;
    SELECT generation, ack_sha256 INTO v_generation, v_ack_sha256
    FROM platform.platformauthority_heads
    WHERE binding_id = p_binding_id AND scope_kind = p_scope_kind AND scope_id = p_scope_id
    FOR UPDATE;
    IF (v_generation IS NULL AND (p_generation <> 1 OR p_previous_head_sha256 IS NOT NULL)) OR
       (v_generation IS NOT NULL AND (p_generation <> v_generation + 1 OR
            p_previous_head_sha256 IS DISTINCT FROM v_ack_sha256)) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'protected authority head is stale';
    END IF;
    INSERT INTO platform.platformauthority_operations (
        operation_id, binding_id, purpose, scope_kind, scope_id, generation,
        previous_head_sha256, state_sha256, state_bytes, proposal_sha256,
        proposal_bytes, compensates_ack_sha256, status, issued_at, expires_at,
        created_at, updated_at
    ) VALUES (
        p_operation_id, p_binding_id, p_purpose, p_scope_kind, p_scope_id, p_generation,
        p_previous_head_sha256, p_state_sha256, p_state_bytes, p_proposal_sha256,
        p_proposal_bytes, p_compensates_ack_sha256, 'proposal_signed', p_issued_at,
        p_expires_at, p_now, p_now
    ) ON CONFLICT (operation_id) DO NOTHING;
    IF FOUND THEN
        RETURN;
    END IF;
    SELECT ROW(binding_id, purpose, scope_kind, scope_id, generation,
        previous_head_sha256, state_sha256, state_bytes, proposal_sha256,
        proposal_bytes, compensates_ack_sha256, issued_at, expires_at)
        IS NOT DISTINCT FROM
        ROW(p_binding_id, p_purpose, p_scope_kind, p_scope_id, p_generation,
        p_previous_head_sha256, p_state_sha256, p_state_bytes, p_proposal_sha256,
        p_proposal_bytes, p_compensates_ack_sha256, p_issued_at, p_expires_at)
    INTO v_exact FROM platform.platformauthority_operations
    WHERE operation_id = p_operation_id;
    IF NOT COALESCE(v_exact, false) THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'protected authority operation conflicts';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformauthority_prepare_v1(p_operation_id uuid, p_binding_id uuid, p_purpose text, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_state_bytes bytea, p_proposal_sha256 text, p_proposal_bytes bytea, p_compensates_ack_sha256 text, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformauthority_prepare_v2(uuid, uuid, text, text, uuid, bigint, text, text, bytea, text, bytea, text, timestamp with time zone, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_prepare_v2(p_operation_id uuid, p_binding_id uuid, p_purpose text, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_state_bytes bytea, p_proposal_sha256 text, p_proposal_bytes bytea, p_compensates_ack_sha256 text, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone, p_signer_kid text, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_kid text;
    v_status text;
BEGIN
    SELECT signer_kid, signer_status INTO v_kid, v_status
    FROM platform.platformauthority_bindings WHERE binding_id = p_binding_id FOR UPDATE;
    IF NOT FOUND OR v_status <> 'active' OR v_kid <> p_signer_kid THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority signer is fenced';
    END IF;
    PERFORM platform.platformauthority_prepare_v1(
        p_operation_id, p_binding_id, p_purpose, p_scope_kind, p_scope_id,
        p_generation, p_previous_head_sha256, p_state_sha256, p_state_bytes,
        p_proposal_sha256, p_proposal_bytes, p_compensates_ack_sha256,
        p_issued_at, p_expires_at, p_now
    );
END;
$$;


ALTER FUNCTION platform.platformauthority_prepare_v2(p_operation_id uuid, p_binding_id uuid, p_purpose text, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_state_bytes bytea, p_proposal_sha256 text, p_proposal_bytes bytea, p_compensates_ack_sha256 text, p_issued_at timestamp with time zone, p_expires_at timestamp with time zone, p_signer_kid text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformauthority_record_ack_v1(uuid, uuid, text, uuid, bigint, text, text, text, text, bytea, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_record_ack_v1(p_operation_id uuid, p_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_ack_bytes bytea, p_registry_sequence bigint, p_verified_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.platformauthority_operations%ROWTYPE;
BEGIN
    SELECT * INTO v_operation FROM platform.platformauthority_operations
    WHERE operation_id = p_operation_id FOR UPDATE;
    IF NOT FOUND OR ROW(v_operation.binding_id, v_operation.scope_kind,
        v_operation.scope_id, v_operation.generation, v_operation.previous_head_sha256,
        v_operation.state_sha256, v_operation.proposal_sha256)
        IS DISTINCT FROM ROW(p_binding_id, p_scope_kind, p_scope_id, p_generation,
        p_previous_head_sha256, p_state_sha256, p_proposal_sha256) THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'protected authority ack mismatches proposal';
    END IF;
    IF v_operation.status IN ('ack_verified', 'completed') THEN
        IF ROW(v_operation.ack_sha256, v_operation.ack_bytes, v_operation.registry_sequence)
            IS DISTINCT FROM ROW(p_ack_sha256, p_ack_bytes, p_registry_sequence) THEN
            RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'protected authority ack replay conflicts';
        END IF;
        RETURN;
    END IF;
    UPDATE platform.platformauthority_operations
    SET status = 'ack_verified', ack_sha256 = p_ack_sha256, ack_bytes = p_ack_bytes,
        registry_sequence = p_registry_sequence, ack_verified_at = p_verified_at,
        revision = revision + 1, updated_at = p_verified_at
    WHERE operation_id = p_operation_id;
END;
$$;


ALTER FUNCTION platform.platformauthority_record_ack_v1(p_operation_id uuid, p_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_ack_bytes bytea, p_registry_sequence bigint, p_verified_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformauthority_recovery_head_evidence_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_recovery_head_evidence_v1(p_environment_id uuid) RETURNS TABLE(binding_id uuid, environment_id uuid, deployment_mode text, registry_kind text, license_binding_id uuid, finalization_receipt_sha256 text, recovery_trust_bundle_sha256 text, signer_generation bigint, signer_kid text, signer_public_key_sha256 text, binding_proof_sha256 text, binding_proof_bytes bytea, operation_id uuid, purpose text, scope_kind text, scope_id uuid, generation bigint, previous_head_sha256 text, state_sha256 text, state_bytes bytea, proposal_sha256 text, proposal_bytes bytea, ack_sha256 text, ack_bytes bytea, registry_sequence bigint, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='protected authority recovery evidence denied';
    END IF;
    RETURN QUERY
    SELECT binding.binding_id,binding.environment_id,binding.deployment_mode,
           binding.registry_kind,binding.license_binding_id,
           binding.finalization_receipt_sha256,
           binding.recovery_trust_bundle_sha256,binding.signer_generation,
           binding.signer_kid,binding.signer_public_key_sha256,
           binding.proof_sha256,binding.proof_bytes,operation.operation_id,
           operation.purpose,operation.scope_kind,operation.scope_id,
           operation.generation,operation.previous_head_sha256,
           operation.state_sha256,operation.state_bytes,
           operation.proposal_sha256,operation.proposal_bytes,
           operation.ack_sha256,operation.ack_bytes,
           operation.registry_sequence,operation.completed_at
    FROM platform.platformauthority_bindings AS binding
    JOIN platform.platformauthority_heads AS head
      ON head.binding_id=binding.binding_id
     AND head.scope_kind='environment' AND head.scope_id=binding.environment_id
    JOIN platform.platformauthority_operations AS operation
      ON operation.binding_id=head.binding_id
     AND operation.scope_kind=head.scope_kind
     AND operation.scope_id=head.scope_id
     AND operation.generation=head.generation
     AND operation.state_sha256=head.state_sha256
     AND operation.proposal_sha256=head.proposal_sha256
     AND operation.ack_sha256=head.ack_sha256
     AND operation.registry_sequence=head.registry_sequence
     AND operation.status='completed'
    WHERE binding.environment_id=p_environment_id
      AND binding.deployment_mode='onpremise'
      AND binding.registry_kind = 'development'
      AND binding.signer_status='active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='current protected authority evidence is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformauthority_recovery_head_evidence_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: platformauthority_reject_mutation_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_reject_mutation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'protected authority evidence is append only';
END;
$$;


