--
-- Name: platformauthority_rotate_signer_v1(uuid, uuid, bigint, text, bigint, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_rotate_signer_v1(p_operation_id uuid, p_binding_id uuid, p_expected_generation bigint, p_expected_kid text, p_new_generation bigint, p_new_kid text, p_new_public_key_sha256 text, p_new_recovery_trust_bundle_sha256 text, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_binding platform.platformauthority_bindings%ROWTYPE;
    v_operation platform.platformauthority_operations%ROWTYPE;
    v_head_ack text;
BEGIN
    SELECT * INTO v_binding FROM platform.platformauthority_bindings
    WHERE binding_id = p_binding_id FOR UPDATE;
    IF v_binding.signer_generation = p_new_generation AND v_binding.signer_kid = p_new_kid
       AND v_binding.signer_public_key_sha256 = p_new_public_key_sha256
       AND v_binding.recovery_trust_bundle_sha256 IS NOT DISTINCT FROM
           p_new_recovery_trust_bundle_sha256
       AND v_binding.signer_status = 'active' THEN
        RETURN;
    END IF;
    IF NOT FOUND OR v_binding.signer_generation <> p_expected_generation OR
       v_binding.signer_kid <> p_expected_kid OR p_new_generation <> p_expected_generation + 1 OR
       p_new_kid = p_expected_kid OR v_binding.signer_status <> 'active' THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'protected authority signer rotation is stale';
    END IF;
    IF (v_binding.deployment_mode = 'onpremise' AND
            (p_new_recovery_trust_bundle_sha256 IS NULL OR
             p_new_recovery_trust_bundle_sha256 = v_binding.recovery_trust_bundle_sha256)) OR
       (v_binding.deployment_mode = 'saas' AND p_new_recovery_trust_bundle_sha256 IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'signer rotation trust bundle conflicts';
    END IF;
    SELECT * INTO v_operation FROM platform.platformauthority_operations
    WHERE operation_id = p_operation_id AND binding_id = p_binding_id FOR UPDATE;
    SELECT ack_sha256 INTO v_head_ack FROM platform.platformauthority_heads
    WHERE binding_id = p_binding_id AND scope_kind = v_operation.scope_kind
      AND scope_id = v_operation.scope_id FOR UPDATE;
    IF v_operation.operation_id IS NULL OR v_head_ack IS NULL OR
       v_operation.status <> 'completed' OR v_operation.purpose <> 'proposal_signer_rotation'
       OR v_operation.ack_sha256 IS DISTINCT FROM v_head_ack THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'signer rotation ack is not current';
    END IF;
    UPDATE platform.platformauthority_bindings
    SET signer_generation = p_new_generation, signer_kid = p_new_kid,
        signer_public_key_sha256 = p_new_public_key_sha256,
        recovery_trust_bundle_sha256 = p_new_recovery_trust_bundle_sha256,
        signer_status = 'active'
    WHERE binding_id = p_binding_id;
    INSERT INTO platform.platformauthority_signer_events (
        binding_id, signer_generation, signer_kid, signer_public_key_sha256,
        event_kind, evidence_sha256, occurred_at
    ) VALUES
        (p_binding_id, v_binding.signer_generation, v_binding.signer_kid,
            v_binding.signer_public_key_sha256, 'retired', v_operation.ack_sha256, p_now),
        (p_binding_id, p_new_generation, p_new_kid, p_new_public_key_sha256,
            'activated', v_operation.ack_sha256, p_now);
END;
$$;


ALTER FUNCTION platform.platformauthority_rotate_signer_v1(p_operation_id uuid, p_binding_id uuid, p_expected_generation bigint, p_expected_kid text, p_new_generation bigint, p_new_kid text, p_new_public_key_sha256 text, p_new_recovery_trust_bundle_sha256 text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformauthority_saas_binding_read_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformauthority_saas_binding_read_v1(p_environment_id uuid) RETURNS TABLE(binding_id uuid, environment_id uuid, deployment_mode text, registry_kind text, license_binding_id uuid, finalization_receipt_sha256 text, recovery_trust_bundle_sha256 text, signer_generation bigint, signer_kid text, signer_public_key_sha256 text, signer_status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='SaaS authority binding read is denied';
    END IF;
    RETURN QUERY
    SELECT binding.binding_id,binding.environment_id,
        binding.deployment_mode,binding.registry_kind,
        binding.license_binding_id,binding.finalization_receipt_sha256,
        binding.recovery_trust_bundle_sha256,binding.signer_generation,
        binding.signer_kid,binding.signer_public_key_sha256,
        binding.signer_status
    FROM platform.platformauthority_bindings AS binding
    WHERE binding.environment_id=p_environment_id
      AND binding.deployment_mode='saas'
      AND binding.registry_kind='saas_provider'
      AND binding.signer_status='active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='active SaaS authority binding is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformauthority_saas_binding_read_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_ack_recovery_kit_v1(uuid, uuid, uuid, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_ack_recovery_kit_v1(p_operation_id uuid, p_actor_user_id uuid, p_session_id uuid, p_artifact_sha256 bytea, p_ack_proof bytea, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.platformops_recovery_control_operations%ROWTYPE;
    v_tenant_id uuid;
BEGIN
    SELECT * INTO v_operation
      FROM platform.platformops_recovery_control_operations AS operation
     WHERE operation.operation_id=p_operation_id FOR UPDATE;
    SELECT identity.tenant_id INTO v_tenant_id
      FROM platform.platformops_installation_recovery_identities AS identity
     WHERE identity.environment_id=v_operation.environment_id
       AND identity.identity_state='active' FOR SHARE;
    IF NOT FOUND OR v_operation.actor_user_id IS DISTINCT FROM p_actor_user_id OR
       v_operation.claimed_session_id IS DISTINCT FROM p_session_id OR
       v_operation.state<>'kit_ready' OR v_operation.kit_claim_state<>'downloaded' OR
       v_operation.expires_at<=p_occurred_at OR
       v_operation.artifact_sha256 IS DISTINCT FROM p_artifact_sha256 OR
       pg_catalog.sha256(p_ack_proof) IS DISTINCT FROM v_operation.ack_verifier_sha256 OR
       NOT platform.iam_platform_current_owner_v1(v_tenant_id,p_actor_user_id) THEN
        RETURN false;
    END IF;
    UPDATE platform.platformops_recovery_control_operations
       SET state='completed',kit_claim_state='acknowledged',artifact_bytes=NULL,
           ack_verifier_sha256=NULL,
           completed_at=p_occurred_at,updated_at=p_occurred_at
     WHERE operation_id=p_operation_id;
    UPDATE platform.platformops_recovery_protections
       SET state='protected',generation=generation+1,
           active_kit_sha256=p_artifact_sha256,current_operation_id=NULL,
           updated_at=p_occurred_at
     WHERE environment_id=v_operation.environment_id
       AND current_operation_id=p_operation_id;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_ack_recovery_kit_v1(p_operation_id uuid, p_actor_user_id uuid, p_session_id uuid, p_artifact_sha256 bytea, p_ack_proof bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_advance_recovery_set_v1(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_advance_recovery_set_v1(p_recovery_set_id uuid, p_expected_state text, p_next_state text, p_failure_code text, p_updated_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE platform.platformops_recovery_sets
       SET state = p_next_state,
           failure_code = CASE WHEN p_next_state = 'failed' THEN p_failure_code ELSE NULL END,
           updated_at = p_updated_at
     WHERE recovery_set_id = p_recovery_set_id
       AND state = p_expected_state
       AND p_next_state IN ('holding','snapshotting','copying','verifying','failed')
       AND (p_next_state <> 'failed' OR length(p_failure_code) BETWEEN 1 AND 128)
    ;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_advance_recovery_set_v1(p_recovery_set_id uuid, p_expected_state text, p_next_state text, p_failure_code text, p_updated_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_advance_restore_v1(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_advance_restore_v1(p_operation_id uuid, p_expected_state text, p_next_state text, p_updated_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE platform.platformops_restore_operations
       SET state = p_next_state, updated_at = p_updated_at
     WHERE operation_id = p_operation_id AND state = p_expected_state
       AND p_next_state IN ('draining','restoring','verifying','switched','failed','fenced')
    ;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_advance_restore_v1(p_operation_id uuid, p_expected_state text, p_next_state text, p_updated_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_attest_documents_hold_v1(uuid, uuid, uuid, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_attest_documents_hold_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_hold_sha256 text, p_inventory_count bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_hold_sha256 !~ '^[0-9a-f]{64}$' OR p_inventory_count<0 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='documents hold attestation denied';
    END IF;
    UPDATE platform.platformops_recovery_execution_attempts AS attempt
    SET documents_hold_sha256=p_hold_sha256,
        documents_inventory_count=p_inventory_count,
        heartbeat_at=v_now,lease_expires_at=v_now+interval '2 minutes'
    FROM platform.platformops_recovery_sets AS recovery
    WHERE attempt.attempt_id=p_attempt_id
      AND attempt.recovery_set_id=p_recovery_set_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active' AND attempt.lease_expires_at>v_now
      AND recovery.recovery_set_id=attempt.recovery_set_id
      AND recovery.state IN ('copying','verifying')
      AND (attempt.documents_hold_sha256 IS NULL
           OR (attempt.documents_hold_sha256=p_hold_sha256
               AND attempt.documents_inventory_count=p_inventory_count));
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_attest_documents_hold_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_hold_sha256 text, p_inventory_count bigint) OWNER TO harpy_owner;

--
-- Name: platformops_claim_next_recovery_set_v2(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_next_recovery_set_v2(p_attempt_id uuid, p_lease_token uuid) RETURNS TABLE(attempt_id uuid, lease_token uuid, attempt_generation bigint, recovery_state text, recovery_set_id uuid, operation_id uuid, environment_id uuid, sequence bigint, primary_binding_id uuid, tenant_set_sha256 text, owner_binding_id uuid, owner_binding_generation bigint, database_lineage_id uuid, database_system_id uuid, recovery_signing_generation bigint, recovery_trust_bundle_sha256 text, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_set_id uuid;
    v_generation bigint;
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR pg_catalog.substring(p_attempt_id::text,15,1)<>'7'
       OR pg_catalog.substring(p_lease_token::text,15,1)<>'7' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery execution claim denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('platformops:recovery-executor',0)
    );
    IF EXISTS (
        SELECT 1
        FROM platform.platformops_recovery_execution_attempts AS existing
        WHERE existing.attempt_id=p_attempt_id
          AND (existing.lease_token<>p_lease_token
               OR existing.lifecycle_state<>'active'
               OR existing.lease_expires_at<=v_now)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='recovery execution claim conflicts';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.platformops_recovery_execution_attempts AS existing
        WHERE existing.attempt_id=p_attempt_id
          AND existing.lease_token=p_lease_token
          AND existing.lifecycle_state='active'
          AND existing.lease_expires_at>v_now
    ) THEN
        RETURN QUERY
        SELECT execution.attempt_id,execution.lease_token,execution.generation,
               recovery.state,recovery.recovery_set_id,recovery.operation_id,
               recovery.environment_id,recovery.sequence,recovery.primary_binding_id,
               recovery.tenant_set_sha256,recovery.owner_binding_id,
               recovery.owner_binding_generation,recovery.database_lineage_id,
               lineage.current_database_system_id,
               recovery.recovery_signing_generation,
               recovery.recovery_trust_bundle_sha256,v_now
        FROM platform.platformops_recovery_execution_attempts AS execution
        JOIN platform.platformops_recovery_sets AS recovery
          ON recovery.recovery_set_id=execution.recovery_set_id
        JOIN platform.platformops_database_lineages AS lineage
          ON lineage.environment_id=recovery.environment_id
        WHERE execution.attempt_id=p_attempt_id;
        RETURN;
    END IF;
    SELECT recovery.recovery_set_id INTO v_set_id
    FROM platform.platformops_recovery_sets AS recovery
    LEFT JOIN platform.platformops_recovery_execution_attempts AS active
      ON active.recovery_set_id=recovery.recovery_set_id
     AND active.lifecycle_state='active'
    WHERE recovery.state='requested'
       OR (recovery.state IN ('holding','snapshotting','copying','verifying')
           AND active.lease_expires_at<=v_now)
    ORDER BY (recovery.state='requested') DESC,
             recovery.sequence,recovery.recovery_set_id
    LIMIT 1 FOR UPDATE OF recovery SKIP LOCKED;
    IF NOT FOUND THEN RETURN; END IF;
    UPDATE platform.platformops_recovery_execution_attempts AS execution
    SET lifecycle_state='superseded',completed_at=v_now
    WHERE execution.recovery_set_id=v_set_id
      AND execution.lifecycle_state='active'
      AND execution.lease_expires_at<=v_now;
    SELECT COALESCE(pg_catalog.max(execution.generation),0)+1
    INTO v_generation
    FROM platform.platformops_recovery_execution_attempts AS execution
    WHERE execution.recovery_set_id=v_set_id;
    UPDATE platform.platformops_recovery_sets AS recovery
    SET state=CASE WHEN recovery.state='requested' THEN 'holding'
                   ELSE recovery.state END,
        updated_at=v_now
    WHERE recovery.recovery_set_id=v_set_id;
    INSERT INTO platform.platformops_recovery_execution_attempts(
        attempt_id,recovery_set_id,generation,lease_token,lifecycle_state,
        claimed_recovery_state,lease_expires_at,heartbeat_at,started_at
    )
    SELECT p_attempt_id,recovery.recovery_set_id,v_generation,p_lease_token,
           'active',recovery.state,v_now+interval '2 minutes',v_now,v_now
    FROM platform.platformops_recovery_sets AS recovery
    WHERE recovery.recovery_set_id=v_set_id;
    RETURN QUERY
    SELECT execution.attempt_id,execution.lease_token,execution.generation,
           recovery.state,recovery.recovery_set_id,recovery.operation_id,
           recovery.environment_id,recovery.sequence,recovery.primary_binding_id,
           recovery.tenant_set_sha256,recovery.owner_binding_id,
           recovery.owner_binding_generation,recovery.database_lineage_id,
           lineage.current_database_system_id,
           recovery.recovery_signing_generation,
           recovery.recovery_trust_bundle_sha256,v_now
    FROM platform.platformops_recovery_execution_attempts AS execution
    JOIN platform.platformops_recovery_sets AS recovery
      ON recovery.recovery_set_id=execution.recovery_set_id
    JOIN platform.platformops_database_lineages AS lineage
      ON lineage.environment_id=recovery.environment_id
    WHERE execution.attempt_id=p_attempt_id;
END;
$$;


ALTER FUNCTION platform.platformops_claim_next_recovery_set_v2(p_attempt_id uuid, p_lease_token uuid) OWNER TO harpy_owner;

--
-- Name: platformops_claim_next_recovery_set_v3(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_next_recovery_set_v3(p_attempt_id uuid, p_lease_token uuid) RETURNS TABLE(attempt_id uuid, lease_token uuid, attempt_generation bigint, recovery_state text, recovery_set_id uuid, operation_id uuid, environment_id uuid, sequence bigint, primary_binding_id uuid, tenant_set_sha256 text, owner_binding_id uuid, owner_binding_generation bigint, database_lineage_id uuid, database_system_id uuid, recovery_signing_generation bigint, recovery_trust_bundle_sha256 text, component_inventory jsonb, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
WITH claimed AS MATERIALIZED (
    SELECT * FROM platform.platformops_claim_next_recovery_set_v2(
        p_attempt_id,p_lease_token
    )
)
SELECT claimed.attempt_id,claimed.lease_token,claimed.attempt_generation,
       claimed.recovery_state,claimed.recovery_set_id,claimed.operation_id,
       claimed.environment_id,claimed.sequence,claimed.primary_binding_id,
       claimed.tenant_set_sha256,claimed.owner_binding_id,
       claimed.owner_binding_generation,claimed.database_lineage_id,
       claimed.database_system_id,claimed.recovery_signing_generation,
       claimed.recovery_trust_bundle_sha256,
       COALESCE((
           SELECT pg_catalog.jsonb_object_agg(
               component.component_kind,
               pg_catalog.jsonb_build_object(
                   'object_key',component.object_key,
                   'object_version_id',component.object_version_id,
                   'ciphertext_sha256',component.ciphertext_sha256,
                   'ciphertext_bytes',component.ciphertext_bytes
               )
           )
           FROM platform.platformops_recovery_components AS component
           WHERE component.recovery_set_id=claimed.recovery_set_id
       ),'{}'::jsonb),
       claimed.database_now
FROM claimed;
END;
$$;


ALTER FUNCTION platform.platformops_claim_next_recovery_set_v3(p_attempt_id uuid, p_lease_token uuid) OWNER TO harpy_owner;

--
-- Name: platformops_claim_recovery_kit_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_recovery_kit_v1(p_operation_id uuid, p_actor_user_id uuid, p_session_id uuid, p_occurred_at timestamp with time zone) RETURNS TABLE(artifact_bytes bytea, artifact_sha256 text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.platformops_recovery_control_operations%ROWTYPE;
    v_tenant_id uuid;
BEGIN
    SELECT * INTO v_operation
      FROM platform.platformops_recovery_control_operations AS operation
     WHERE operation.operation_id=p_operation_id FOR UPDATE;
    SELECT identity.tenant_id INTO v_tenant_id
      FROM platform.platformops_installation_recovery_identities AS identity
     WHERE identity.environment_id=v_operation.environment_id
       AND identity.identity_state='active' FOR SHARE;
    IF NOT FOUND OR p_actor_user_id IS DISTINCT FROM v_operation.actor_user_id OR
       p_session_id IS NULL OR v_operation.state<>'kit_ready' OR
       v_operation.kit_claim_state NOT IN ('ready','downloaded') OR
       v_operation.expires_at<=p_occurred_at OR
       (v_operation.claimed_session_id IS NOT NULL AND
        v_operation.claimed_session_id IS DISTINCT FROM p_session_id) OR
       NOT platform.iam_platform_current_owner_v1(v_tenant_id,p_actor_user_id) THEN
        RETURN;
    END IF;
    UPDATE platform.platformops_recovery_control_operations
       SET claimed_session_id=p_session_id,kit_claim_state='downloaded',
           updated_at=p_occurred_at WHERE operation_id=p_operation_id;
    RETURN QUERY SELECT v_operation.artifact_bytes,
        pg_catalog.encode(v_operation.artifact_sha256,'hex'),v_operation.expires_at;
END;
$$;


ALTER FUNCTION platform.platformops_claim_recovery_kit_v1(p_operation_id uuid, p_actor_user_id uuid, p_session_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_claim_recovery_manifest_v1(uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_recovery_manifest_v1(p_recovery_set_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid, p_claimed_at timestamp with time zone) RETURNS TABLE(artifact_sha256 text, artifact_bytes bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION 'current owner is required' USING ERRCODE = '42501';
    END IF;
    INSERT INTO platform.platformops_recovery_artifact_claims(
        artifact_kind, artifact_id, tenant_id, actor_user_id, session_id,
        artifact_sha256, claimed_at
    )
    SELECT 'recovery_manifest', r.recovery_set_id, p_tenant_id,
           p_actor_user_id, p_session_id, r.manifest_sha256, p_claimed_at
      FROM platform.platformops_recovery_sets r
      JOIN platform.tenancy_tenant_bindings b
        ON b.environment_id = r.environment_id AND b.tenant_id = p_tenant_id
     WHERE r.recovery_set_id = p_recovery_set_id
       AND r.state = 'protected' AND r.manifest_bytes IS NOT NULL
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    RETURN QUERY
    SELECT r.manifest_sha256, r.manifest_bytes
      FROM platform.platformops_recovery_sets r
     WHERE r.recovery_set_id = p_recovery_set_id;
END;
$$;


ALTER FUNCTION platform.platformops_claim_recovery_manifest_v1(p_recovery_set_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid, p_claimed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_claim_recovery_manifest_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_recovery_manifest_v2(p_recovery_set_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid) RETURNS TABLE(artifact_sha256 text, artifact_bytes bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_runtime'
       OR NOT platform.iam_platform_current_owner_v1(
           p_tenant_id,p_actor_user_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery manifest claim denied';
    END IF;
    INSERT INTO platform.platformops_recovery_artifact_claims(
        artifact_kind,artifact_id,tenant_id,actor_user_id,session_id,
        artifact_sha256,claimed_at
    )
    SELECT 'recovery_manifest',recovery.recovery_set_id,p_tenant_id,
           p_actor_user_id,p_session_id,recovery.manifest_sha256,v_now
    FROM platform.platformops_recovery_sets AS recovery
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id=recovery.environment_id
     AND binding.tenant_id=p_tenant_id
    WHERE recovery.recovery_set_id=p_recovery_set_id
      AND recovery.state='protected' AND recovery.manifest_bytes IS NOT NULL
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN RETURN; END IF;
    RETURN QUERY
    SELECT recovery.manifest_sha256,recovery.manifest_bytes
    FROM platform.platformops_recovery_sets AS recovery
    WHERE recovery.recovery_set_id=p_recovery_set_id;
END;
$$;


ALTER FUNCTION platform.platformops_claim_recovery_manifest_v2(p_recovery_set_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_claim_recovery_set_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_recovery_set_v1(p_recovery_set_id uuid, p_claimed_at timestamp with time zone) RETURNS TABLE(recovery_set_id uuid, environment_id uuid, sequence bigint, primary_binding_id uuid, tenant_set_sha256 text, owner_binding_id uuid, owner_binding_generation bigint, database_lineage_id uuid, recovery_signing_generation bigint, recovery_trust_bundle_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE platform.platformops_recovery_sets r
       SET state = 'holding', updated_at = p_claimed_at
     WHERE r.recovery_set_id = p_recovery_set_id AND r.state = 'requested'
    RETURNING r.recovery_set_id, r.environment_id, r.sequence,
              r.primary_binding_id, r.tenant_set_sha256, r.owner_binding_id,
              r.owner_binding_generation, r.database_lineage_id,
              r.recovery_signing_generation, r.recovery_trust_bundle_sha256
    ;
END;
$$;


ALTER FUNCTION platform.platformops_claim_recovery_set_v1(p_recovery_set_id uuid, p_claimed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_claim_restore_execution_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_restore_execution_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) RETURNS TABLE(attempt_id uuid, lease_token uuid, attempt_generation bigint, restore_state text, operation_id uuid, recovery_set_id uuid, environment_id uuid, target_disposition text, plan_sha256 text, plan_bytes bytea, safety_recovery_set_id uuid, safety_recovery_set_sha256 text, waiver_reason text, probe_sha256 text, destructive_confirmed boolean, manifest_sha256 text, manifest_bytes bytea, previous_database_system_id uuid, component_inventory jsonb, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_generation bigint;
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_components jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR pg_catalog.substring(p_attempt_id::text,15,1)<>'7'
       OR pg_catalog.substring(p_lease_token::text,15,1)<>'7'
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore execution claim denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'platformops:restore-executor:'||p_operation_id::text,0
        )
    );
    IF EXISTS (
        SELECT 1 FROM platform.platformops_restore_execution_attempts
        WHERE attempt_id=p_attempt_id
          AND (operation_id<>p_operation_id OR lease_token<>p_lease_token
               OR plan_sha256<>p_plan_sha256
               OR lifecycle_state<>'active' OR lease_expires_at<=v_now)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='restore execution claim conflicts';
    END IF;
    PERFORM 1 FROM platform.platformops_restore_operations AS restore
    JOIN platform.platformops_recovery_sets AS recovery
      ON recovery.recovery_set_id=restore.recovery_set_id
    WHERE restore.operation_id=p_operation_id
      AND restore.plan_sha256=p_plan_sha256
      AND restore.state IN (
          'plan_ready','draining','restoring','verifying','switched'
      )
      AND recovery.state='protected'
      AND recovery.manifest_sha256 IS NOT NULL
      AND recovery.manifest_bytes IS NOT NULL
    FOR UPDATE OF restore;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='restore operation is not claimable';
    END IF;
    SELECT pg_catalog.jsonb_object_agg(
        component.component_kind,
        pg_catalog.jsonb_build_object(
            'object_key',component.object_key,
            'object_version_id',component.object_version_id,
            'ciphertext_sha256',component.ciphertext_sha256,
            'ciphertext_bytes',component.ciphertext_bytes
        )
    ) INTO v_components
    FROM platform.platformops_recovery_components AS component
    JOIN platform.platformops_restore_operations AS restore
      ON restore.recovery_set_id=component.recovery_set_id
    WHERE restore.operation_id=p_operation_id;
    IF pg_catalog.jsonb_object_length(v_components)<>5
       OR NOT v_components ?& ARRAY[
           'database_archive','documents_inventory','key_custody',
           'owner_anchor','protected_authority'
       ] THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='restore component inventory is incomplete';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.platformops_restore_execution_attempts
        WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
          AND lifecycle_state='active' AND lease_expires_at>v_now
    ) THEN
        UPDATE platform.platformops_restore_execution_attempts
        SET lifecycle_state='superseded',completed_at=v_now
        WHERE operation_id=p_operation_id AND lifecycle_state='active'
          AND lease_expires_at<=v_now;
        IF EXISTS (
            SELECT 1 FROM platform.platformops_restore_execution_attempts
            WHERE operation_id=p_operation_id AND lifecycle_state='active'
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55P03',
                MESSAGE='restore execution is leased';
        END IF;
        SELECT COALESCE(pg_catalog.max(generation),0)+1 INTO v_generation
        FROM platform.platformops_restore_execution_attempts
        WHERE operation_id=p_operation_id;
        INSERT INTO platform.platformops_restore_execution_attempts(
            attempt_id,operation_id,generation,lease_token,lifecycle_state,
            claimed_restore_state,plan_sha256,lease_expires_at,
            heartbeat_at,started_at
        )
        SELECT p_attempt_id,p_operation_id,v_generation,p_lease_token,'active',
               state,p_plan_sha256,v_now+interval '2 minutes',v_now,v_now
        FROM platform.platformops_restore_operations
        WHERE operation_id=p_operation_id;
    END IF;
    RETURN QUERY
    SELECT attempt.attempt_id,attempt.lease_token,attempt.generation,
           restore.state,restore.operation_id,restore.recovery_set_id,
           restore.environment_id,restore.target_disposition,
           restore.plan_sha256,restore.plan_bytes,
           restore.safety_recovery_set_id,restore.safety_recovery_set_sha256,
           restore.waiver_reason,restore.probe_sha256,
           restore.destructive_confirmed,recovery.manifest_sha256,
           recovery.manifest_bytes,recovery.database_system_id,
           v_components,v_now
    FROM platform.platformops_restore_execution_attempts AS attempt
    JOIN platform.platformops_restore_operations AS restore
      ON restore.operation_id=attempt.operation_id
    JOIN platform.platformops_recovery_sets AS recovery
      ON recovery.recovery_set_id=restore.recovery_set_id
    WHERE attempt.attempt_id=p_attempt_id;
END;
$_$;


ALTER FUNCTION platform.platformops_claim_restore_execution_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_claim_restore_execution_v3(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_restore_execution_v3(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) RETURNS TABLE(attempt_id uuid, lease_token uuid, attempt_generation bigint, restore_state text, operation_id uuid, recovery_set_id uuid, environment_id uuid, target_disposition text, plan_sha256 text, plan_bytes bytea, safety_recovery_set_id uuid, safety_recovery_set_sha256 text, waiver_reason text, probe_sha256 text, destructive_confirmed boolean, manifest_sha256 text, manifest_bytes bytea, previous_database_system_id uuid, component_inventory jsonb, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    WITH claimed AS MATERIALIZED (
        SELECT * FROM platform.platformops_claim_restore_execution_v2(
            p_operation_id,p_attempt_id,p_lease_token,p_plan_sha256
        )
    )
    SELECT claimed.*
    FROM claimed
    WHERE pg_catalog.convert_from(claimed.manifest_bytes,'UTF8')::jsonb
          #> '{payload,components}'
          IS NOT DISTINCT FROM claimed.component_inventory;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore manifest component binding denied';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformops_claim_restore_execution_v3(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_claim_restore_execution_v4(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_restore_execution_v4(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) RETURNS TABLE(attempt_id uuid, lease_token uuid, attempt_generation bigint, restore_state text, operation_id uuid, recovery_set_id uuid, environment_id uuid, target_disposition text, plan_sha256 text, plan_bytes bytea, safety_recovery_set_id uuid, safety_recovery_set_sha256 text, waiver_reason text, probe_sha256 text, destructive_confirmed boolean, manifest_sha256 text, manifest_bytes bytea, previous_database_system_id uuid, component_inventory jsonb, control_database_locator_sha256 text, scratch_database_locator_sha256 text, drain_ack_sha256 text, switch_ack_sha256 text, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
WITH claimed AS MATERIALIZED (
    SELECT * FROM platform.platformops_claim_restore_execution_v3(
        p_operation_id,p_attempt_id,p_lease_token,p_plan_sha256
    )
)
SELECT claimed.attempt_id,claimed.lease_token,claimed.attempt_generation,
       claimed.restore_state,claimed.operation_id,claimed.recovery_set_id,
       claimed.environment_id,claimed.target_disposition,
       claimed.plan_sha256,claimed.plan_bytes,
       claimed.safety_recovery_set_id,claimed.safety_recovery_set_sha256,
       claimed.waiver_reason,claimed.probe_sha256,
       claimed.destructive_confirmed,claimed.manifest_sha256,
       claimed.manifest_bytes,claimed.previous_database_system_id,
       claimed.component_inventory,
       COALESCE(attempt.control_database_locator_sha256,''),
       COALESCE(attempt.scratch_database_locator_sha256,''),
       COALESCE(attempt.drain_ack_sha256,''),
       COALESCE(attempt.switch_ack_sha256,''),claimed.database_now
FROM claimed
JOIN platform.platformops_restore_execution_attempts AS attempt
  ON attempt.attempt_id=claimed.attempt_id
 AND attempt.lease_token=claimed.lease_token;
END;
$$;


ALTER FUNCTION platform.platformops_claim_restore_execution_v4(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_claim_restore_execution_v5(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_restore_execution_v5(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) RETURNS TABLE(attempt_id uuid, lease_token uuid, attempt_generation bigint, restore_state text, operation_id uuid, recovery_set_id uuid, environment_id uuid, target_disposition text, plan_sha256 text, plan_bytes bytea, safety_recovery_set_id uuid, safety_recovery_set_sha256 text, waiver_reason text, probe_sha256 text, destructive_confirmed boolean, manifest_sha256 text, manifest_bytes bytea, previous_database_system_id uuid, component_inventory jsonb, control_database_locator_sha256 text, scratch_database_locator_sha256 text, drain_ack_sha256 text, switch_ack_sha256 text, archive_readback_sha256 text, new_database_system_id uuid, object_merkle_sha256 text, locator_remap_sha256 text, safety_evidence_sha256 text, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_claim_attempt_id uuid;
    v_claim_lease_token uuid;
    v_claim_attempt_generation bigint;
    v_claim_restore_state text;
    v_claim_operation_id uuid;
    v_claim_recovery_set_id uuid;
    v_claim_environment_id uuid;
    v_claim_target_disposition text;
    v_claim_plan_sha256 text;
    v_claim_plan_bytes bytea;
    v_claim_safety_recovery_set_id uuid;
    v_claim_safety_recovery_set_sha256 text;
    v_claim_waiver_reason text;
    v_claim_probe_sha256 text;
    v_claim_destructive_confirmed boolean;
    v_claim_manifest_sha256 text;
    v_claim_manifest_bytes bytea;
    v_claim_previous_database_system_id uuid;
    v_claim_component_inventory jsonb;
    v_claim_database_now timestamptz;
BEGIN
    SELECT claimed.attempt_id,claimed.lease_token,
           claimed.attempt_generation,claimed.restore_state,
           claimed.operation_id,claimed.recovery_set_id,
           claimed.environment_id,claimed.target_disposition,
           claimed.plan_sha256,claimed.plan_bytes,
           claimed.safety_recovery_set_id,
           claimed.safety_recovery_set_sha256,claimed.waiver_reason,
           claimed.probe_sha256,claimed.destructive_confirmed,
           claimed.manifest_sha256,claimed.manifest_bytes,
           claimed.previous_database_system_id,
           claimed.component_inventory,claimed.database_now
    INTO v_claim_attempt_id,v_claim_lease_token,
         v_claim_attempt_generation,v_claim_restore_state,
         v_claim_operation_id,v_claim_recovery_set_id,
         v_claim_environment_id,v_claim_target_disposition,
         v_claim_plan_sha256,v_claim_plan_bytes,
         v_claim_safety_recovery_set_id,
         v_claim_safety_recovery_set_sha256,v_claim_waiver_reason,
         v_claim_probe_sha256,v_claim_destructive_confirmed,
         v_claim_manifest_sha256,v_claim_manifest_bytes,
         v_claim_previous_database_system_id,
         v_claim_component_inventory,v_claim_database_now
    FROM platform.platformops_claim_restore_execution_v4(
        p_operation_id,p_attempt_id,p_lease_token,p_plan_sha256
    ) AS claimed;
    IF NOT FOUND THEN RETURN; END IF;
    UPDATE platform.platformops_restore_execution_attempts AS current_attempt
    SET drain_ack_sha256=prior.drain_ack_sha256,
        archive_readback_sha256=prior.archive_readback_sha256,
        restored_database_system_id=prior.restored_database_system_id,
        object_merkle_sha256=prior.object_merkle_sha256,
        locator_remap_sha256=prior.locator_remap_sha256,
        safety_evidence_sha256=prior.safety_evidence_sha256,
        control_database_locator_sha256=prior.control_database_locator_sha256,
        scratch_database_locator_sha256=prior.scratch_database_locator_sha256,
        switch_ack_sha256=prior.switch_ack_sha256
    FROM (
        SELECT previous_attempt.*
        FROM platform.platformops_restore_execution_attempts AS previous_attempt
        WHERE previous_attempt.operation_id=p_operation_id
          AND previous_attempt.generation<v_claim_attempt_generation
          AND previous_attempt.plan_sha256=p_plan_sha256
        ORDER BY previous_attempt.generation DESC
        LIMIT 1
    ) AS prior
    WHERE current_attempt.attempt_id=p_attempt_id
      AND current_attempt.operation_id=p_operation_id
      AND current_attempt.lease_token=p_lease_token
      AND current_attempt.lifecycle_state='active'
      AND current_attempt.drain_ack_sha256 IS NULL
      AND current_attempt.archive_readback_sha256 IS NULL
      AND current_attempt.restored_database_system_id IS NULL
      AND current_attempt.object_merkle_sha256 IS NULL
      AND current_attempt.locator_remap_sha256 IS NULL
      AND current_attempt.safety_evidence_sha256 IS NULL
      AND current_attempt.control_database_locator_sha256 IS NULL
      AND current_attempt.scratch_database_locator_sha256 IS NULL
      AND current_attempt.switch_ack_sha256 IS NULL;
    RETURN QUERY
    SELECT v_claim_attempt_id,v_claim_lease_token,
           v_claim_attempt_generation,v_claim_restore_state,
           v_claim_operation_id,v_claim_recovery_set_id,
           v_claim_environment_id,v_claim_target_disposition,
           v_claim_plan_sha256,v_claim_plan_bytes,
           v_claim_safety_recovery_set_id,
           v_claim_safety_recovery_set_sha256,v_claim_waiver_reason,
           v_claim_probe_sha256,v_claim_destructive_confirmed,
           v_claim_manifest_sha256,v_claim_manifest_bytes,
           v_claim_previous_database_system_id,v_claim_component_inventory,
           COALESCE(attempt.control_database_locator_sha256,''),
           COALESCE(attempt.scratch_database_locator_sha256,''),
           COALESCE(attempt.drain_ack_sha256,''),
           COALESCE(attempt.switch_ack_sha256,''),
           COALESCE(attempt.archive_readback_sha256,''),
           attempt.restored_database_system_id,
           COALESCE(attempt.object_merkle_sha256,''),
           COALESCE(attempt.locator_remap_sha256,''),
           COALESCE(attempt.safety_evidence_sha256,''),
           v_claim_database_now
    FROM platform.platformops_restore_execution_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id
      AND attempt.operation_id=p_operation_id
      AND attempt.lease_token=p_lease_token;
END;
$$;


ALTER FUNCTION platform.platformops_claim_restore_execution_v5(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_claim_restore_plan_v1(uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_restore_plan_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid, p_claimed_at timestamp with time zone) RETURNS TABLE(artifact_sha256 text, artifact_bytes bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id) THEN
        RAISE EXCEPTION 'current owner is required' USING ERRCODE = '42501';
    END IF;
    INSERT INTO platform.platformops_recovery_artifact_claims(
        artifact_kind, artifact_id, tenant_id, actor_user_id, session_id,
        artifact_sha256, claimed_at
    )
    SELECT 'restore_plan', r.operation_id, p_tenant_id,
           p_actor_user_id, p_session_id, r.plan_sha256, p_claimed_at
      FROM platform.platformops_restore_operations r
      JOIN platform.tenancy_tenant_bindings b
        ON b.environment_id = r.environment_id AND b.tenant_id = p_tenant_id
     WHERE r.operation_id = p_operation_id AND r.state = 'plan_ready'
       AND r.requested_by_actor_id = p_actor_user_id
       AND r.requested_by_session_id = p_session_id
       AND r.created_at + interval '15 minutes' > p_claimed_at
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    RETURN QUERY
    SELECT r.plan_sha256, r.plan_bytes
      FROM platform.platformops_restore_operations r
     WHERE r.operation_id = p_operation_id;
END;
$$;


ALTER FUNCTION platform.platformops_claim_restore_plan_v1(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid, p_claimed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_claim_restore_plan_v2(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_restore_plan_v2(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid) RETURNS TABLE(artifact_sha256 text, artifact_bytes bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_runtime'
       OR NOT platform.iam_platform_current_owner_v1(
           p_tenant_id,p_actor_user_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore plan claim denied';
    END IF;
    INSERT INTO platform.platformops_recovery_artifact_claims(
        artifact_kind,artifact_id,tenant_id,actor_user_id,session_id,
        artifact_sha256,claimed_at
    )
    SELECT 'restore_plan',restore.operation_id,p_tenant_id,
           p_actor_user_id,p_session_id,restore.plan_sha256,v_now
    FROM platform.platformops_restore_operations AS restore
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id=restore.environment_id
     AND binding.tenant_id=p_tenant_id
    WHERE restore.operation_id=p_operation_id AND restore.state='plan_ready'
      AND restore.requested_by_actor_id=p_actor_user_id
      AND restore.requested_by_session_id=p_session_id
      AND restore.created_at+interval '15 minutes'>v_now
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN RETURN; END IF;
    RETURN QUERY
    SELECT restore.plan_sha256,restore.plan_bytes
    FROM platform.platformops_restore_operations AS restore
    WHERE restore.operation_id=p_operation_id;
END;
$$;


ALTER FUNCTION platform.platformops_claim_restore_plan_v2(p_operation_id uuid, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_claim_restore_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_claim_restore_v1(p_operation_id uuid, p_claimed_at timestamp with time zone) RETURNS TABLE(operation_id uuid, recovery_set_id uuid, environment_id uuid, target_disposition text, plan_sha256 text, plan_bytes bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE platform.platformops_restore_operations r
       SET state = 'draining', updated_at = p_claimed_at
     WHERE r.operation_id = p_operation_id AND r.state = 'plan_ready'
    RETURNING r.operation_id, r.recovery_set_id, r.environment_id,
              r.target_disposition, r.plan_sha256, r.plan_bytes
    ;
END;
$$;


ALTER FUNCTION platform.platformops_claim_restore_v1(p_operation_id uuid, p_claimed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_commit_database_lineage_restore_v1(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_commit_database_lineage_restore_v1(p_operation_id uuid, p_expected_database_system_id uuid, p_new_database_system_id uuid, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_restore platform.platformops_restore_operations%ROWTYPE;
    v_generation bigint;
BEGIN
    SELECT * INTO v_restore
      FROM platform.platformops_restore_operations AS restore
     WHERE restore.operation_id = p_operation_id
       AND restore.state = 'completed'
       AND restore.new_database_system_id = p_new_database_system_id
     FOR SHARE;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    UPDATE platform.platformops_database_lineages
       SET current_database_system_id = p_new_database_system_id,
           generation = generation + 1,updated_at = p_occurred_at
     WHERE environment_id = v_restore.environment_id
       AND current_database_system_id = p_expected_database_system_id
       AND p_new_database_system_id <> p_expected_database_system_id
    RETURNING generation INTO v_generation;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    INSERT INTO platform.platformops_database_lineage_events(
        operation_id,environment_id,previous_database_system_id,
        database_system_id,generation,event_kind,occurred_at
    ) VALUES (
        p_operation_id,v_restore.environment_id,p_expected_database_system_id,
        p_new_database_system_id,v_generation,'restored',p_occurred_at
    );
    RETURN true;
END;
$$;


ALTER FUNCTION platform.platformops_commit_database_lineage_restore_v1(p_operation_id uuid, p_expected_database_system_id uuid, p_new_database_system_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_complete_anchor_operation_v1(uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_anchor_operation_v1(p_operation_id uuid, p_ack_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF pg_catalog.octet_length(p_ack_sha256)<>32 THEN RETURN false; END IF;
    UPDATE platform.platformops_recovery_control_operations
       SET state='completed',completed_at=COALESCE(completed_at,p_occurred_at),
           updated_at=p_occurred_at
     WHERE operation_id=p_operation_id
       AND operation_kind IN ('anchor_register','anchor_delete')
       AND state IN ('accepted','handoff_ready','completed');
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_complete_anchor_operation_v1(p_operation_id uuid, p_ack_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_complete_recovery_disable_v1(uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_recovery_disable_v1(p_operation_id uuid, p_handoff_receipt_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_environment_id uuid;
BEGIN
    IF pg_catalog.octet_length(p_handoff_receipt_sha256)<>32 THEN RETURN false; END IF;
    UPDATE platform.platformops_recovery_control_operations
       SET state='completed',completed_at=p_occurred_at,updated_at=p_occurred_at
     WHERE operation_id=p_operation_id AND operation_kind='disable' AND state='accepted'
    RETURNING environment_id INTO v_environment_id;
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_recovery_protections
       SET state='unprotected',active_kit_sha256=NULL,current_operation_id=NULL,
           updated_at=p_occurred_at
     WHERE environment_id=v_environment_id AND current_operation_id=p_operation_id;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_complete_recovery_disable_v1(p_operation_id uuid, p_handoff_receipt_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_complete_recovery_execution_v1(uuid, uuid, uuid, text, bytea, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_recovery_execution_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_manifest_sha256 text, p_manifest_bytes bytea, p_database_system_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_attempt_state text;
    v_attempt_phase text;
    v_attempt_lease timestamptz;
    v_documents_hold_sha256 text;
    v_recovery_state text;
    v_stored_manifest_sha256 text;
    v_stored_manifest_bytes bytea;
    v_stored_database_system_id uuid;
    v_environment_id uuid;
    v_operation_id uuid;
    v_sequence bigint;
    v_signing_generation bigint;
    v_primary_binding_id uuid;
    v_tenant_set_sha256 text;
    v_owner_binding_id uuid;
    v_owner_binding_generation bigint;
    v_database_lineage_id uuid;
    v_trust_bundle_sha256 text;
    v_manifest jsonb;
    v_kinds text;
    v_database_sha text;
    v_key_custody_sha text;
    v_owner_anchor_sha text;
    v_authority_sha text;
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.statement_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_recovery_set_id IS NULL OR p_attempt_id IS NULL
       OR p_lease_token IS NULL OR p_database_system_id IS NULL
       OR p_manifest_sha256 IS NULL OR p_manifest_bytes IS NULL
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(p_manifest_bytes) NOT BETWEEN 1 AND 2097152
       OR p_manifest_sha256 <> pg_catalog.encode(
           pg_catalog.sha256(p_manifest_bytes),'hex'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery completion denied';
    END IF;
    SELECT attempt.lifecycle_state,attempt.claimed_recovery_state,
           attempt.lease_expires_at,attempt.documents_hold_sha256
    INTO v_attempt_state,v_attempt_phase,v_attempt_lease,
         v_documents_hold_sha256
    FROM platform.platformops_recovery_execution_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id
      AND attempt.recovery_set_id=p_recovery_set_id
      AND attempt.lease_token=p_lease_token
    FOR UPDATE;
    IF NOT FOUND THEN RETURN false; END IF;
    SELECT recovery.state,recovery.manifest_sha256,recovery.manifest_bytes,
           recovery.database_system_id,recovery.environment_id,
           recovery.operation_id,recovery.sequence,
           recovery.recovery_signing_generation,recovery.primary_binding_id,
           recovery.tenant_set_sha256,recovery.owner_binding_id,
           recovery.owner_binding_generation,recovery.database_lineage_id,
           recovery.recovery_trust_bundle_sha256
    INTO v_recovery_state,v_stored_manifest_sha256,v_stored_manifest_bytes,
         v_stored_database_system_id,v_environment_id,v_operation_id,v_sequence,
         v_signing_generation,v_primary_binding_id,v_tenant_set_sha256,
         v_owner_binding_id,v_owner_binding_generation,v_database_lineage_id,
         v_trust_bundle_sha256
    FROM platform.platformops_recovery_sets AS recovery
    WHERE recovery.recovery_set_id=p_recovery_set_id
    FOR UPDATE;
    IF NOT FOUND THEN RETURN false; END IF;
    IF v_attempt_state='completed' AND v_recovery_state='protected' THEN
        RETURN (v_stored_manifest_sha256,v_stored_manifest_bytes,
                v_stored_database_system_id)
            IS NOT DISTINCT FROM
               (p_manifest_sha256,p_manifest_bytes,p_database_system_id);
    END IF;
    IF v_attempt_state<>'active' OR v_attempt_lease<=v_now
       OR v_attempt_phase<>'verifying'
       OR v_documents_hold_sha256 IS NULL
       OR v_recovery_state<>'verifying' THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.string_agg(component_kind,',' ORDER BY component_kind),
           pg_catalog.max(ciphertext_sha256)
               FILTER (WHERE component_kind='database_archive'),
           pg_catalog.max(ciphertext_sha256)
               FILTER (WHERE component_kind='key_custody'),
           pg_catalog.max(ciphertext_sha256)
               FILTER (WHERE component_kind='owner_anchor'),
           pg_catalog.max(ciphertext_sha256)
               FILTER (WHERE component_kind='protected_authority')
    INTO v_kinds,v_database_sha,v_key_custody_sha,v_owner_anchor_sha,v_authority_sha
    FROM platform.platformops_recovery_components
    WHERE recovery_set_id=p_recovery_set_id;
    IF v_kinds IS DISTINCT FROM
       'database_archive,documents_inventory,key_custody,owner_anchor,protected_authority' THEN
        RETURN false;
    END IF;
    v_manifest := pg_catalog.convert_from(p_manifest_bytes,'UTF8')::jsonb;
    IF v_manifest->>'schema' IS DISTINCT FROM 'harpy-recovery-artifact.v1'
       OR v_manifest->>'purpose' IS DISTINCT FROM 'recovery_manifest'
       OR v_manifest->>'environment_id' IS DISTINCT FROM v_environment_id::text
       OR v_manifest->>'operation_id' IS DISTINCT FROM v_operation_id::text
       OR v_manifest->>'artifact_id' IS DISTINCT FROM p_recovery_set_id::text
       OR (v_manifest->>'artifact_sequence')::bigint IS DISTINCT FROM v_sequence
       OR (v_manifest->>'key_generation')::bigint IS DISTINCT FROM
          v_signing_generation
       OR v_manifest->>'algorithm' IS DISTINCT FROM 'Ed25519'
       OR v_manifest->>'payload_sha256' IS NULL
       OR v_manifest->>'payload_sha256' !~ '^[0-9a-f]{64}$'
       OR v_manifest->>'signature' IS NULL
       OR pg_catalog.octet_length(v_manifest->>'signature') < 1
       OR v_manifest->>'issued_at' IS NULL
       OR v_manifest->>'expires_at' IS NULL
       OR (v_manifest->>'issued_at')::timestamptz > v_now
       OR (v_manifest->>'expires_at')::timestamptz <= v_now
       OR v_manifest#>>'{payload,schema}' IS DISTINCT FROM
          'environment-recovery-set-payload.v1'
       OR v_manifest#>>'{payload,portability}' IS DISTINCT FROM 'same_environment'
       OR v_manifest#>>'{payload,identity,environment_id}' IS DISTINCT FROM
          v_environment_id::text
       OR v_manifest#>>'{payload,identity,deployment_mode}' IS DISTINCT FROM 'onpremise'
       OR v_manifest#>>'{payload,identity,primary_binding_id}' IS DISTINCT FROM
          v_primary_binding_id::text
       OR v_manifest#>>'{payload,identity,tenant_set_sha256}' IS DISTINCT FROM
          v_tenant_set_sha256
       OR v_manifest#>>'{payload,identity,owner_binding_id}' IS DISTINCT FROM
          v_owner_binding_id::text
       OR (v_manifest#>>'{payload,identity,owner_binding_generation}')::bigint IS DISTINCT FROM
          v_owner_binding_generation
       OR v_manifest#>>'{payload,identity,database_lineage_id}' IS DISTINCT FROM
          v_database_lineage_id::text
       OR v_manifest#>>'{payload,database_system_id}' IS DISTINCT FROM
          p_database_system_id::text
       OR v_manifest#>>'{payload,database_archive_sha256}' IS DISTINCT FROM v_database_sha
       OR v_manifest#>>'{payload,documents_merkle_sha256}' IS DISTINCT FROM
          v_documents_hold_sha256
       OR v_manifest#>>'{payload,key_custody_sha256}' IS DISTINCT FROM v_key_custody_sha
       OR v_manifest#>>'{payload,owner_anchor_sha256}' IS DISTINCT FROM v_owner_anchor_sha
       OR v_manifest#>>'{payload,protected_head_ack_sha256}' IS DISTINCT FROM v_authority_sha
       OR v_manifest#>>'{payload,recovery_trust_bundle_sha256}' IS DISTINCT FROM
          v_trust_bundle_sha256
       OR (v_manifest#>>'{payload,recovery_signing_generation}')::bigint IS DISTINCT FROM
          v_signing_generation THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery manifest evidence denied';
    END IF;
    UPDATE platform.platformops_recovery_sets
    SET state='protected',manifest_sha256=p_manifest_sha256,
        manifest_bytes=p_manifest_bytes,database_system_id=p_database_system_id,
        protected_at=v_now,updated_at=v_now
    WHERE recovery_set_id=p_recovery_set_id AND state='verifying';
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_recovery_execution_attempts
    SET lifecycle_state='completed',heartbeat_at=v_now,
        lease_expires_at=v_now,completed_at=v_now
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_complete_recovery_execution_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_manifest_sha256 text, p_manifest_bytes bytea, p_database_system_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_complete_recovery_execution_v2(uuid, uuid, uuid, text, bytea, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_recovery_execution_v2(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_manifest_sha256 text, p_manifest_bytes bytea, p_database_system_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_inventory jsonb;
    v_manifest_inventory jsonb;
    v_result boolean;
BEGIN
    SELECT pg_catalog.jsonb_object_agg(
        component_kind,
        pg_catalog.jsonb_build_object(
            'object_key',object_key,
            'object_version_id',object_version_id,
            'ciphertext_sha256',ciphertext_sha256,
            'ciphertext_bytes',ciphertext_bytes
        )
    ) INTO v_inventory
    FROM platform.platformops_recovery_components
    WHERE recovery_set_id=p_recovery_set_id;
    v_manifest_inventory :=
        pg_catalog.convert_from(p_manifest_bytes,'UTF8')::jsonb
        #> '{payload,components}';
    IF pg_catalog.jsonb_typeof(v_manifest_inventory)<>'object'
       OR pg_catalog.jsonb_object_length(v_manifest_inventory)<>5
       OR v_manifest_inventory IS DISTINCT FROM v_inventory THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery manifest component binding denied';
    END IF;
    SELECT platform.platformops_complete_recovery_execution_v1(
        p_recovery_set_id,p_attempt_id,p_lease_token,p_manifest_sha256,
        p_manifest_bytes,p_database_system_id
    ) INTO v_result;
    RETURN v_result;
END;
$$;


ALTER FUNCTION platform.platformops_complete_recovery_execution_v2(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_manifest_sha256 text, p_manifest_bytes bytea, p_database_system_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_complete_recovery_set_v1(uuid, text, bytea, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_recovery_set_v1(p_recovery_set_id uuid, p_manifest_sha256 text, p_manifest_bytes bytea, p_database_system_id uuid, p_protected_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    UPDATE platform.platformops_recovery_sets
       SET state = 'protected', manifest_sha256 = p_manifest_sha256,
           manifest_bytes = p_manifest_bytes, database_system_id = p_database_system_id,
           protected_at = p_protected_at, updated_at = p_protected_at
     WHERE recovery_set_id = p_recovery_set_id AND state = 'verifying'
       AND p_manifest_sha256 ~ '^[0-9a-f]{64}$'
       AND octet_length(p_manifest_bytes) BETWEEN 1 AND 2097152
       AND (SELECT count(*) FROM platform.platformops_recovery_components c
             WHERE c.recovery_set_id = p_recovery_set_id) = 5
    ;
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_complete_recovery_set_v1(p_recovery_set_id uuid, p_manifest_sha256 text, p_manifest_bytes bytea, p_database_system_id uuid, p_protected_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_complete_restore_execution_v1(uuid, uuid, uuid, text, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_restore_execution_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_receipt_sha256 text, p_receipt_bytes bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_receipt jsonb;
    v_attempt platform.platformops_restore_execution_attempts%ROWTYPE;
    v_restore platform.platformops_restore_operations%ROWTYPE;
    v_recovery platform.platformops_recovery_sets%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_receipt_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(p_receipt_bytes) NOT BETWEEN 1 AND 2097152
       OR p_receipt_sha256<>pg_catalog.encode(
           pg_catalog.sha256(p_receipt_bytes),'hex'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore completion denied';
    END IF;
    SELECT * INTO v_attempt
    FROM platform.platformops_restore_execution_attempts
    WHERE attempt_id=p_attempt_id AND operation_id=p_operation_id
      AND lease_token=p_lease_token FOR UPDATE;
    SELECT * INTO v_restore FROM platform.platformops_restore_operations
    WHERE operation_id=p_operation_id FOR UPDATE;
    SELECT * INTO v_recovery FROM platform.platformops_recovery_sets
    WHERE recovery_set_id=v_restore.recovery_set_id;
    IF v_attempt.lifecycle_state='completed'
       AND v_restore.state='completed' THEN
        RETURN (v_restore.receipt_sha256,v_restore.receipt_bytes,
                v_restore.new_database_system_id)
            IS NOT DISTINCT FROM
               (p_receipt_sha256,p_receipt_bytes,
                v_attempt.restored_database_system_id);
    END IF;
    IF v_attempt.lifecycle_state<>'active'
       OR v_attempt.claimed_restore_state<>'switched'
       OR v_attempt.lease_expires_at<=v_now
       OR v_restore.state<>'switched' THEN RETURN false; END IF;
    v_receipt := pg_catalog.convert_from(p_receipt_bytes,'UTF8')::jsonb;
    IF v_receipt->>'schema' IS DISTINCT FROM 'harpy-recovery-artifact.v1'
       OR v_receipt->>'purpose' IS DISTINCT FROM 'restore_receipt'
       OR v_receipt->>'environment_id' IS DISTINCT FROM v_restore.environment_id::text
       OR v_receipt->>'operation_id' IS DISTINCT FROM p_operation_id::text
       OR v_receipt->>'artifact_id' IS DISTINCT FROM p_operation_id::text
       OR (v_receipt->>'artifact_sequence')::bigint IS DISTINCT FROM v_recovery.sequence
       OR (v_receipt->>'key_generation')::bigint IS DISTINCT FROM
          v_recovery.recovery_signing_generation
       OR v_receipt->>'algorithm' IS DISTINCT FROM 'Ed25519'
       OR v_receipt->>'payload_sha256' !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(v_receipt->>'signature')<1
       OR (v_receipt->>'issued_at')::timestamptz>v_now
       OR (v_receipt->>'expires_at')::timestamptz<=v_now
       OR v_receipt#>>'{payload,schema}' IS DISTINCT FROM
          'restore-receipt-payload.v1'
       OR v_receipt#>>'{payload,recovery_set_id}' IS DISTINCT FROM
          v_restore.recovery_set_id::text
       OR v_receipt#>>'{payload,manifest_sha256}' IS DISTINCT FROM
          v_recovery.manifest_sha256
       OR v_receipt#>>'{payload,identity,environment_id}' IS DISTINCT FROM
          v_restore.environment_id::text
       OR v_receipt#>>'{payload,new_database_system_id}' IS DISTINCT FROM
          v_attempt.restored_database_system_id::text
       OR v_receipt#>>'{payload,object_merkle_sha256}' IS DISTINCT FROM
          v_attempt.object_merkle_sha256
       OR v_receipt#>>'{payload,locator_remap_sha256}' IS DISTINCT FROM
          v_attempt.locator_remap_sha256
       OR v_receipt#>>'{payload,safety_evidence_sha256}' IS DISTINCT FROM
          v_attempt.safety_evidence_sha256
       OR (v_receipt#>>'{payload,seeded}')::boolean
       OR (v_receipt#>>'{payload,owner_changed}')::boolean
       OR (v_receipt#>>'{payload,tenant_replaced}')::boolean
       OR v_receipt#>>'{payload,switch_outcome}' IS DISTINCT FROM
          'switched_same_environment' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt evidence denied';
    END IF;
    UPDATE platform.platformops_restore_operations
    SET state='completed',receipt_sha256=p_receipt_sha256,
        receipt_bytes=p_receipt_bytes,
        new_database_system_id=v_attempt.restored_database_system_id,
        completed_at=v_now,updated_at=v_now
    WHERE operation_id=p_operation_id AND state='switched';
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET lifecycle_state='completed',heartbeat_at=v_now,
        lease_expires_at=v_now,completed_at=v_now
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_complete_restore_execution_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_receipt_sha256 text, p_receipt_bytes bytea) OWNER TO harpy_owner;

--
-- Name: platformops_complete_restore_execution_v2(uuid, uuid, uuid, text, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_restore_execution_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_receipt_sha256 text, p_receipt_bytes bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_receipt jsonb;
    v_attempt platform.platformops_restore_execution_attempts%ROWTYPE;
    v_restore platform.platformops_restore_operations%ROWTYPE;
    v_recovery platform.platformops_recovery_sets%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_receipt_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(p_receipt_bytes) NOT BETWEEN 1 AND 2097152
       OR p_receipt_sha256<>pg_catalog.encode(
           pg_catalog.sha256(p_receipt_bytes),'hex'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore completion v2 denied';
    END IF;
    SELECT * INTO v_attempt
    FROM platform.platformops_restore_execution_attempts
    WHERE attempt_id=p_attempt_id AND operation_id=p_operation_id
      AND lease_token=p_lease_token FOR UPDATE;
    SELECT * INTO v_restore
    FROM platform.platformops_restore_operations
    WHERE operation_id=p_operation_id FOR UPDATE;
    SELECT * INTO v_recovery
    FROM platform.platformops_recovery_sets
    WHERE recovery_set_id=v_restore.recovery_set_id;
    IF v_attempt.lifecycle_state='completed'
       AND v_restore.state='completed' THEN
        RETURN (v_restore.receipt_sha256,v_restore.receipt_bytes,
                v_restore.new_database_system_id)
            IS NOT DISTINCT FROM
               (p_receipt_sha256,p_receipt_bytes,
                v_attempt.restored_database_system_id);
    END IF;
    IF v_attempt.lifecycle_state<>'active'
       OR v_attempt.claimed_restore_state<>'switched'
       OR v_attempt.lease_expires_at<=v_now
       OR v_attempt.drain_ack_sha256 IS NULL
       OR v_attempt.switch_ack_sha256 IS NULL
       OR v_attempt.control_database_locator_sha256 IS NULL
       OR v_attempt.scratch_database_locator_sha256 IS NULL
       OR v_restore.state<>'switched' THEN
        RETURN false;
    END IF;
    v_receipt := pg_catalog.convert_from(p_receipt_bytes,'UTF8')::jsonb;
    IF v_receipt->>'schema' IS DISTINCT FROM
          'harpy-recovery-artifact.v1'
       OR v_receipt->>'purpose' IS DISTINCT FROM 'restore_receipt'
       OR v_receipt->>'environment_id' IS DISTINCT FROM
          v_restore.environment_id::text
       OR v_receipt->>'operation_id' IS DISTINCT FROM p_operation_id::text
       OR v_receipt->>'artifact_id' IS DISTINCT FROM p_operation_id::text
       OR (v_receipt->>'artifact_sequence')::bigint IS DISTINCT FROM
          v_recovery.sequence
       OR (v_receipt->>'key_generation')::bigint IS DISTINCT FROM
          v_recovery.recovery_signing_generation
       OR v_receipt->>'algorithm' IS DISTINCT FROM 'Ed25519'
       OR v_receipt->>'payload_sha256' !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(v_receipt->>'signature')<1
       OR (v_receipt->>'issued_at')::timestamptz>v_now
       OR (v_receipt->>'expires_at')::timestamptz<=v_now
       OR v_receipt#>>'{payload,schema}' IS DISTINCT FROM
          'restore-receipt-payload.v2'
       OR v_receipt#>>'{payload,operation_id}' IS DISTINCT FROM
          p_operation_id::text
       OR v_receipt#>>'{payload,recovery_set_id}' IS DISTINCT FROM
          v_restore.recovery_set_id::text
       OR v_receipt#>>'{payload,plan_sha256}' IS DISTINCT FROM
          v_restore.plan_sha256
       OR v_receipt#>>'{payload,manifest_sha256}' IS DISTINCT FROM
          v_recovery.manifest_sha256
       OR v_receipt#>>'{payload,identity,environment_id}' IS DISTINCT FROM
          v_restore.environment_id::text
       OR v_receipt#>>'{payload,previous_database_system_id}' IS DISTINCT FROM
          v_recovery.database_system_id::text
       OR v_receipt#>>'{payload,new_database_system_id}' IS DISTINCT FROM
          v_attempt.restored_database_system_id::text
       OR v_receipt#>>'{payload,previous_database_locator_sha256}'
          IS DISTINCT FROM v_attempt.control_database_locator_sha256
       OR v_receipt#>>'{payload,new_database_locator_sha256}'
          IS DISTINCT FROM v_attempt.scratch_database_locator_sha256
       OR v_receipt#>>'{payload,drain_ack_sha256}' IS DISTINCT FROM
          v_attempt.drain_ack_sha256
       OR v_receipt#>>'{payload,switch_ack_sha256}' IS DISTINCT FROM
          v_attempt.switch_ack_sha256
       OR v_receipt#>>'{payload,object_merkle_sha256}' IS DISTINCT FROM
          v_attempt.object_merkle_sha256
       OR v_receipt#>>'{payload,locator_remap_sha256}' IS DISTINCT FROM
          v_attempt.locator_remap_sha256
       OR v_receipt#>>'{payload,safety_evidence_sha256}' IS DISTINCT FROM
          v_attempt.safety_evidence_sha256
       OR (v_receipt#>>'{payload,seeded}')::boolean
       OR (v_receipt#>>'{payload,owner_changed}')::boolean
       OR (v_receipt#>>'{payload,tenant_replaced}')::boolean
       OR v_receipt#>>'{payload,switch_outcome}' IS DISTINCT FROM
          'switched_same_environment' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt v2 evidence denied';
    END IF;
    UPDATE platform.platformops_restore_operations
    SET state='completed',receipt_sha256=p_receipt_sha256,
        receipt_bytes=p_receipt_bytes,
        new_database_system_id=v_attempt.restored_database_system_id,
        completed_at=v_now,updated_at=v_now
    WHERE operation_id=p_operation_id AND state='switched';
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET lifecycle_state='completed',heartbeat_at=v_now,
        lease_expires_at=v_now,completed_at=v_now
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_complete_restore_execution_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_receipt_sha256 text, p_receipt_bytes bytea) OWNER TO harpy_owner;

--
-- Name: platformops_complete_restore_v1(uuid, text, bytea, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_complete_restore_v1(p_operation_id uuid, p_receipt_sha256 text, p_receipt_bytes bytea, p_new_database_system_id uuid, p_completed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    UPDATE platform.platformops_restore_operations
       SET state = 'completed', receipt_sha256 = p_receipt_sha256,
           receipt_bytes = p_receipt_bytes,
           new_database_system_id = p_new_database_system_id,
           completed_at = p_completed_at, updated_at = p_completed_at
     WHERE operation_id = p_operation_id AND state = 'switched'
       AND p_receipt_sha256 ~ '^[0-9a-f]{64}$'
       AND octet_length(p_receipt_bytes) BETWEEN 1 AND 2097152
    ;
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_complete_restore_v1(p_operation_id uuid, p_receipt_sha256 text, p_receipt_bytes bytea, p_new_database_system_id uuid, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_alert_rules; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.platformops_alert_rules (
    id uuid NOT NULL,
    environment_id uuid NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    enabled boolean NOT NULL,
    service_name text,
    condition text NOT NULL,
    cooldown_minutes integer NOT NULL,
    channels jsonb NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT platformops_alert_rules_channels_check CHECK (((jsonb_typeof(channels) = 'array'::text) AND (jsonb_array_length(channels) <= 8))),
    CONSTRAINT platformops_alert_rules_condition_check CHECK ((condition = ANY (ARRAY['unhealthy'::text, 'degraded'::text, 'any_change'::text]))),
    CONSTRAINT platformops_alert_rules_cooldown_minutes_check CHECK (((cooldown_minutes >= 1) AND (cooldown_minutes <= 10080))),
    CONSTRAINT platformops_alert_rules_description_check CHECK ((length(description) <= 1000)),
    CONSTRAINT platformops_alert_rules_name_check CHECK (((length(name) >= 1) AND (length(name) <= 120))),
    CONSTRAINT platformops_alert_rules_revision_check CHECK ((revision > 0)),
    CONSTRAINT platformops_alert_rules_service_name_check CHECK (((service_name IS NULL) OR ((length(service_name) >= 1) AND (length(service_name) <= 100))))
);


ALTER TABLE platform.platformops_alert_rules OWNER TO harpy_owner;

--
-- Name: platformops_create_alert_rule_v1(uuid, uuid, text, text, boolean, text, text, integer, jsonb, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_create_alert_rule_v1(p_id uuid, p_environment_id uuid, p_name text, p_description text, p_enabled boolean, p_service_name text, p_condition text, p_cooldown_minutes integer, p_channels jsonb, p_now timestamp with time zone) RETURNS SETOF platform.platformops_alert_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    INSERT INTO platform.platformops_alert_rules(
        id, environment_id, name, description, enabled, service_name,
        condition, cooldown_minutes, channels, created_at, updated_at
    ) VALUES (
        p_id, p_environment_id, btrim(p_name), p_description, p_enabled,
        nullif(btrim(p_service_name), ''), p_condition, p_cooldown_minutes,
        p_channels, p_now, p_now
    );
    RETURN QUERY SELECT * FROM platform.platformops_alert_rules WHERE id = p_id;
END;
$$;


ALTER FUNCTION platform.platformops_create_alert_rule_v1(p_id uuid, p_environment_id uuid, p_name text, p_description text, p_enabled boolean, p_service_name text, p_condition text, p_cooldown_minutes integer, p_channels jsonb, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_current_environment_identity_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_current_environment_identity_v1(p_expected_environment_id uuid) RETURNS TABLE(environment_id uuid, deployment_mode text, primary_binding_id uuid, tenant_set_sha256 text, owner_binding_id uuid, owner_binding_generation bigint, database_lineage_id uuid, database_system_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT identity.environment_id,identity.deployment_mode,
           target.tenant_id,pg_catalog.encode(target.tenant_set_sha256,'hex'),
           owner.owner_binding_id,owner.owner_policy_revision,
           lineage.lineage_id,lineage.current_database_system_id
      FROM platform.platformops_installation_recovery_identities AS identity
      JOIN platform.tenancy_get_primary_tenant_target_v2() AS target
        ON target.environment_id = identity.environment_id
       AND target.tenant_id = identity.tenant_id
       AND target.deployment_mode = identity.deployment_mode
       AND target.purpose = 'onpremise_primary'
      JOIN platform.iam_platform_current_owner_projection_v1(
          identity.environment_id
      ) AS owner ON owner.environment_id = identity.environment_id
      JOIN platform.platformops_database_lineages AS lineage
        ON lineage.environment_id = identity.environment_id
     WHERE identity.environment_id = p_expected_environment_id
       AND identity.deployment_mode = 'onpremise'
       AND identity.identity_state = 'active';
END;
$$;


ALTER FUNCTION platform.platformops_current_environment_identity_v1(p_expected_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_delete_alert_rule_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_delete_alert_rule_v1(p_id uuid, p_environment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    DELETE FROM platform.platformops_alert_rules
    WHERE id = p_id AND environment_id = p_environment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'alert rule was not found' USING ERRCODE = 'P0002'; END IF;
END;
$$;


ALTER FUNCTION platform.platformops_delete_alert_rule_v1(p_id uuid, p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_export_recovery_snapshot_v1(text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_export_recovery_snapshot_v1(p_process text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_process IS DISTINCT FROM
          'harpy-v2:core-database-backup-executor' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery snapshot export denied';
    END IF;
    RETURN pg_catalog.pg_export_snapshot();
END;
$$;


ALTER FUNCTION platform.platformops_export_recovery_snapshot_v1(p_process text) OWNER TO harpy_owner;

--
-- Name: platformops_fail_recovery_execution_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_fail_recovery_execution_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_failure_code !~ '^[a-z0-9_]{1,64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery execution failure denied';
    END IF;
    UPDATE platform.platformops_recovery_sets AS recovery
    SET state='failed',failure_code=p_failure_code,updated_at=v_now
    FROM platform.platformops_recovery_execution_attempts AS attempt
    WHERE recovery.recovery_set_id=p_recovery_set_id
      AND recovery.state IN ('holding','snapshotting','copying','verifying')
      AND attempt.attempt_id=p_attempt_id
      AND attempt.recovery_set_id=recovery.recovery_set_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active' AND attempt.lease_expires_at>v_now;
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_recovery_execution_attempts
    SET lifecycle_state='failed',failure_code=p_failure_code,completed_at=v_now
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_fail_recovery_execution_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_failure_code text) OWNER TO harpy_owner;

--
-- Name: platformops_fail_restore_execution_v1(uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_fail_restore_execution_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_failure_code text, p_fenced boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_failure_code !~ '^[a-z0-9_]{1,64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore failure transition denied';
    END IF;
    UPDATE platform.platformops_restore_operations AS restore
    SET state=CASE WHEN p_fenced THEN 'fenced' ELSE 'failed' END,
        updated_at=v_now
    FROM platform.platformops_restore_execution_attempts AS attempt
    WHERE restore.operation_id=p_operation_id
      AND restore.state IN (
          'plan_ready','draining','restoring','verifying','switched'
      )
      AND attempt.attempt_id=p_attempt_id
      AND attempt.operation_id=restore.operation_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active' AND attempt.lease_expires_at>v_now;
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET lifecycle_state='failed',failure_code=p_failure_code,
        heartbeat_at=v_now,lease_expires_at=v_now,completed_at=v_now
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


