--
-- Name: platformops_finish_recovery_set_delete_v1(uuid, boolean, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_finish_recovery_set_delete_v1(p_recovery_set_id uuid, p_succeeded boolean, p_updated_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE platform.platformops_recovery_sets
       SET state = CASE WHEN p_succeeded THEN 'deleted' ELSE 'protected' END,
           updated_at = p_updated_at
     WHERE recovery_set_id = p_recovery_set_id AND state = 'deleting'
    ;
    RETURN FOUND;
END;
$$;


