--
-- Name: platformops_trace_spans; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.platformops_trace_spans (
    id uuid NOT NULL,
    environment_id uuid NOT NULL,
    correlation_id text NOT NULL,
    span_id text NOT NULL,
    parent_span_id text,
    service_name text NOT NULL,
    operation text NOT NULL,
    span_kind text NOT NULL,
    method text NOT NULL,
    path text NOT NULL,
    status_code integer NOT NULL,
    started_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone NOT NULL,
    duration_ms numeric(18,3) NOT NULL,
    level text NOT NULL,
    message text,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT platformops_trace_spans_check CHECK ((ended_at >= started_at)),
    CONSTRAINT platformops_trace_spans_correlation_id_check CHECK ((((length(correlation_id) >= 1) AND (length(correlation_id) <= 64)) AND (correlation_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'::text))),
    CONSTRAINT platformops_trace_spans_duration_ms_check CHECK ((duration_ms >= (0)::numeric)),
    CONSTRAINT platformops_trace_spans_level_check CHECK ((level = ANY (ARRAY['debug'::text, 'info'::text, 'warn'::text, 'error'::text, 'fatal'::text]))),
    CONSTRAINT platformops_trace_spans_message_check CHECK (((message IS NULL) OR (length(message) <= 500))),
    CONSTRAINT platformops_trace_spans_method_check CHECK ((method = ANY (ARRAY['GET'::text, 'HEAD'::text, 'POST'::text, 'PUT'::text, 'PATCH'::text, 'DELETE'::text, 'OPTIONS'::text]))),
    CONSTRAINT platformops_trace_spans_operation_check CHECK (((length(operation) >= 1) AND (length(operation) <= 256))),
    CONSTRAINT platformops_trace_spans_parent_span_id_check CHECK (((parent_span_id IS NULL) OR (parent_span_id ~ '^[0-9a-f]{16,32}$'::text))),
    CONSTRAINT platformops_trace_spans_path_check CHECK ((((length(path) >= 1) AND (length(path) <= 256)) AND (path ~~ '/%'::text))),
    CONSTRAINT platformops_trace_spans_service_name_check CHECK (((length(service_name) >= 1) AND (length(service_name) <= 100))),
    CONSTRAINT platformops_trace_spans_span_id_check CHECK ((span_id ~ '^[0-9a-f]{16,32}$'::text)),
    CONSTRAINT platformops_trace_spans_span_kind_check CHECK ((span_kind = ANY (ARRAY['server'::text, 'client'::text, 'internal'::text, 'consumer'::text, 'producer'::text]))),
    CONSTRAINT platformops_trace_spans_status_code_check CHECK (((status_code >= 100) AND (status_code <= 599)))
);


