--
-- Name: platformops_guard_recovery_set_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_guard_recovery_set_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.recovery_set_id <> OLD.recovery_set_id
       OR NEW.operation_id <> OLD.operation_id
       OR NEW.environment_id <> OLD.environment_id
       OR NEW.deployment_mode <> OLD.deployment_mode
       OR NEW.portability <> OLD.portability
       OR NEW.sequence <> OLD.sequence
       OR NEW.primary_binding_id <> OLD.primary_binding_id
       OR NEW.tenant_set_sha256 <> OLD.tenant_set_sha256
       OR NEW.owner_binding_id <> OLD.owner_binding_id
       OR NEW.owner_binding_generation <> OLD.owner_binding_generation
       OR NEW.database_lineage_id <> OLD.database_lineage_id
       OR NEW.recovery_signing_generation <> OLD.recovery_signing_generation
       OR NEW.recovery_trust_bundle_sha256 <> OLD.recovery_trust_bundle_sha256
       OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'recovery set identity is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state <> NEW.state AND NOT (
        (OLD.state = 'requested' AND NEW.state IN ('holding','failed'))
        OR (OLD.state = 'holding' AND NEW.state IN ('snapshotting','failed'))
        OR (OLD.state = 'snapshotting' AND NEW.state IN ('copying','failed'))
        OR (OLD.state = 'copying' AND NEW.state IN ('verifying','failed'))
        OR (OLD.state = 'verifying' AND NEW.state IN ('protected','failed'))
        OR (OLD.state = 'protected' AND NEW.state = 'deleting')
        OR (OLD.state = 'deleting' AND NEW.state IN ('protected','deleted'))
    ) THEN
        RAISE EXCEPTION 'recovery set transition is invalid'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'protected' AND NEW.state <> 'deleting' AND (
        NEW.manifest_sha256 IS DISTINCT FROM OLD.manifest_sha256
        OR NEW.manifest_bytes IS DISTINCT FROM OLD.manifest_bytes
        OR NEW.database_system_id IS DISTINCT FROM OLD.database_system_id
        OR NEW.protected_at IS DISTINCT FROM OLD.protected_at
    ) THEN
        RAISE EXCEPTION 'protected recovery evidence is immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformops_guard_recovery_set_v1() OWNER TO harpy_owner;

--
-- Name: platformops_guard_recovery_set_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_guard_recovery_set_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.recovery_set_id<>OLD.recovery_set_id OR NEW.operation_id<>OLD.operation_id OR
       NEW.environment_id<>OLD.environment_id OR NEW.deployment_mode<>OLD.deployment_mode OR
       NEW.portability<>OLD.portability OR NEW.sequence<>OLD.sequence OR
       NEW.primary_binding_id<>OLD.primary_binding_id OR NEW.tenant_set_sha256<>OLD.tenant_set_sha256 OR
       NEW.owner_binding_id<>OLD.owner_binding_id OR
       NEW.owner_binding_generation<>OLD.owner_binding_generation OR
       NEW.database_lineage_id<>OLD.database_lineage_id OR
       NEW.recovery_signing_generation<>OLD.recovery_signing_generation OR
       NEW.recovery_trust_bundle_sha256<>OLD.recovery_trust_bundle_sha256 OR
       NEW.created_at<>OLD.created_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='recovery set identity is immutable';
    END IF;
    IF OLD.state<>NEW.state AND NOT (
        (OLD.state='requested' AND NEW.state IN ('holding','failed')) OR
        (OLD.state='holding' AND NEW.state IN ('snapshotting','failed')) OR
        (OLD.state='snapshotting' AND NEW.state IN ('copying','failed')) OR
        (OLD.state='copying' AND NEW.state IN ('verifying','failed')) OR
        (OLD.state='verifying' AND NEW.state IN ('protected','failed')) OR
        (OLD.state='protected' AND NEW.state IN ('stale','deleting')) OR
        (OLD.state='deleting' AND NEW.state IN ('protected','deleted'))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='recovery set transition is invalid';
    END IF;
    IF OLD.state='protected' AND NEW.state NOT IN ('stale','deleting') AND (
        NEW.manifest_sha256 IS DISTINCT FROM OLD.manifest_sha256 OR
        NEW.manifest_bytes IS DISTINCT FROM OLD.manifest_bytes OR
        NEW.database_system_id IS DISTINCT FROM OLD.database_system_id OR
        NEW.protected_at IS DISTINCT FROM OLD.protected_at) THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='protected recovery evidence is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformops_guard_recovery_set_v2() OWNER TO harpy_owner;

--
-- Name: platformops_guard_restore_operation_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_guard_restore_operation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.operation_id <> OLD.operation_id
       OR NEW.recovery_set_id <> OLD.recovery_set_id
       OR NEW.environment_id <> OLD.environment_id
       OR NEW.target_disposition <> OLD.target_disposition
       OR NEW.plan_sha256 <> OLD.plan_sha256
       OR NEW.plan_bytes <> OLD.plan_bytes
       OR NEW.safety_recovery_set_id IS DISTINCT FROM OLD.safety_recovery_set_id
       OR NEW.safety_recovery_set_sha256 IS DISTINCT FROM OLD.safety_recovery_set_sha256
       OR NEW.waiver_reason IS DISTINCT FROM OLD.waiver_reason
       OR NEW.probe_sha256 IS DISTINCT FROM OLD.probe_sha256
       OR NEW.destructive_confirmed <> OLD.destructive_confirmed
       OR NEW.seeded OR NEW.owner_changed OR NEW.tenant_replaced
       OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'restore operation identity is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state <> NEW.state AND NOT (
        (OLD.state = 'plan_ready' AND NEW.state IN ('draining','failed','fenced'))
        OR (OLD.state = 'draining' AND NEW.state IN ('restoring','failed','fenced'))
        OR (OLD.state = 'restoring' AND NEW.state IN ('verifying','failed','fenced'))
        OR (OLD.state = 'verifying' AND NEW.state IN ('switched','failed','fenced'))
        OR (OLD.state = 'switched' AND NEW.state = 'completed')
    ) THEN
        RAISE EXCEPTION 'restore operation transition is invalid'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.state = 'completed' THEN
        RAISE EXCEPTION 'completed restore is immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformops_guard_restore_operation_v1() OWNER TO harpy_owner;

--
-- Name: platformops_heartbeat_recovery_execution_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_heartbeat_recovery_execution_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery execution heartbeat denied';
    END IF;
    UPDATE platform.platformops_recovery_execution_attempts
    SET heartbeat_at=v_now,lease_expires_at=v_now+interval '2 minutes'
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND recovery_set_id=p_recovery_set_id
      AND lifecycle_state='active' AND lease_expires_at>v_now;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_heartbeat_recovery_execution_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid) OWNER TO harpy_owner;

--
-- Name: platformops_heartbeat_restore_execution_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_heartbeat_restore_execution_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore heartbeat denied';
    END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET heartbeat_at=v_now,lease_expires_at=v_now+interval '2 minutes'
    WHERE attempt_id=p_attempt_id AND operation_id=p_operation_id
      AND lease_token=p_lease_token
      AND lifecycle_state='active' AND lease_expires_at>v_now;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_heartbeat_restore_execution_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid) OWNER TO harpy_owner;

--
-- Name: platformops_import_recovery_snapshot_v1(text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_import_recovery_snapshot_v1(p_snapshot_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_snapshot_id !~ '^[0-9]+-[0-9A-F]+-[0-9]+$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery snapshot import denied';
    END IF;
    PERFORM pg_catalog.pg_import_snapshot(p_snapshot_id);
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platformops_import_recovery_snapshot_v1(p_snapshot_id text) OWNER TO harpy_owner;

--
-- Name: platformops_import_restore_receipt_v1(uuid, uuid, uuid, text, text, text, bytea, uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_import_restore_receipt_v1(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_plan_sha256 text, p_manifest_sha256 text, p_receipt_sha256 text, p_receipt_bytes bytea, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_component_inventory jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_receipt jsonb;
    v_existing platform.platformops_restore_receipt_imports%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_operation_id IS NULL OR p_recovery_set_id IS NULL
       OR p_environment_id IS NULL OR p_new_database_system_id IS NULL
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR p_receipt_sha256 !~ '^[0-9a-f]{64}$'
       OR p_object_merkle_sha256 !~ '^[0-9a-f]{64}$'
       OR p_locator_remap_sha256 !~ '^[0-9a-f]{64}$'
       OR p_safety_evidence_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(p_receipt_bytes) NOT BETWEEN 1 AND 2097152
       OR p_receipt_sha256<>pg_catalog.encode(
           pg_catalog.sha256(p_receipt_bytes),'hex'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt import denied';
    END IF;
    IF pg_catalog.jsonb_typeof(p_component_inventory)<>'object'
       OR pg_catalog.jsonb_object_length(p_component_inventory)<>5
       OR NOT p_component_inventory ?& ARRAY[
           'database_archive','documents_inventory','key_custody',
           'owner_anchor','protected_authority'
       ] OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_each(p_component_inventory) AS component
           WHERE pg_catalog.jsonb_typeof(component.value)<>'object'
              OR component.value->>'object_key' IS NULL
              OR pg_catalog.length(component.value->>'object_key') NOT BETWEEN 1 AND 1024
              OR component.value->>'object_version_id' IS NULL
              OR pg_catalog.length(component.value->>'object_version_id') NOT BETWEEN 1 AND 1024
              OR component.value->>'ciphertext_sha256' !~ '^[0-9a-f]{64}$'
              OR (component.value->>'ciphertext_bytes')::bigint<=0
       ) THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='restore component import is invalid';
    END IF;
    v_receipt := pg_catalog.convert_from(p_receipt_bytes,'UTF8')::jsonb;
    IF v_receipt->>'schema' IS DISTINCT FROM 'harpy-recovery-artifact.v1'
       OR v_receipt->>'purpose' IS DISTINCT FROM 'restore_receipt'
       OR v_receipt->>'environment_id' IS DISTINCT FROM p_environment_id::text
       OR v_receipt->>'operation_id' IS DISTINCT FROM p_operation_id::text
       OR v_receipt->>'artifact_id' IS DISTINCT FROM p_operation_id::text
       OR v_receipt->>'algorithm' IS DISTINCT FROM 'Ed25519'
       OR v_receipt->>'payload_sha256' !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(v_receipt->>'signature')<1
       OR (v_receipt->>'issued_at')::timestamptz>v_now
       OR (v_receipt->>'expires_at')::timestamptz<=v_now
       OR v_receipt#>>'{payload,schema}' IS DISTINCT FROM
          'restore-receipt-payload.v1'
       OR v_receipt#>>'{payload,recovery_set_id}' IS DISTINCT FROM
          p_recovery_set_id::text
       OR v_receipt#>>'{payload,manifest_sha256}' IS DISTINCT FROM
          p_manifest_sha256
       OR v_receipt#>>'{payload,identity,environment_id}' IS DISTINCT FROM
          p_environment_id::text
       OR v_receipt#>>'{payload,new_database_system_id}' IS DISTINCT FROM
          p_new_database_system_id::text
       OR v_receipt#>>'{payload,object_merkle_sha256}' IS DISTINCT FROM
          p_object_merkle_sha256
       OR v_receipt#>>'{payload,locator_remap_sha256}' IS DISTINCT FROM
          p_locator_remap_sha256
       OR v_receipt#>>'{payload,safety_evidence_sha256}' IS DISTINCT FROM
          p_safety_evidence_sha256
       OR (v_receipt#>>'{payload,seeded}')::boolean
       OR (v_receipt#>>'{payload,owner_changed}')::boolean
       OR (v_receipt#>>'{payload,tenant_replaced}')::boolean
       OR v_receipt#>>'{payload,switch_outcome}' IS DISTINCT FROM
          'switched_same_environment' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt evidence import denied';
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformops_restore_receipt_imports
    WHERE operation_id=p_operation_id FOR UPDATE;
    IF FOUND THEN
        RETURN (v_existing.recovery_set_id,v_existing.environment_id,
                v_existing.plan_sha256,v_existing.manifest_sha256,
                v_existing.receipt_sha256,v_existing.receipt_bytes,
                v_existing.new_database_system_id,
                v_existing.component_inventory)
            IS NOT DISTINCT FROM
               (p_recovery_set_id,p_environment_id,p_plan_sha256,
                p_manifest_sha256,p_receipt_sha256,p_receipt_bytes,
                p_new_database_system_id,p_component_inventory);
    END IF;
    INSERT INTO platform.platformops_restore_receipt_imports(
        operation_id,recovery_set_id,environment_id,plan_sha256,
        manifest_sha256,receipt_sha256,receipt_bytes,
        previous_database_system_id,new_database_system_id,
        object_merkle_sha256,locator_remap_sha256,
        safety_evidence_sha256,component_inventory,imported_at
    ) VALUES (
        p_operation_id,p_recovery_set_id,p_environment_id,p_plan_sha256,
        p_manifest_sha256,p_receipt_sha256,p_receipt_bytes,
        p_previous_database_system_id,p_new_database_system_id,
        p_object_merkle_sha256,p_locator_remap_sha256,
        p_safety_evidence_sha256,p_component_inventory,v_now
    );
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platformops_import_restore_receipt_v1(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_plan_sha256 text, p_manifest_sha256 text, p_receipt_sha256 text, p_receipt_bytes bytea, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_component_inventory jsonb) OWNER TO harpy_owner;

--
-- Name: platformops_import_restore_receipt_v2(uuid, uuid, uuid, text, text, text, bytea, uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_import_restore_receipt_v2(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_plan_sha256 text, p_manifest_sha256 text, p_receipt_sha256 text, p_receipt_bytes bytea, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_component_inventory jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_manifest_inventory jsonb;
    v_result boolean;
BEGIN
    SELECT pg_catalog.convert_from(manifest_bytes,'UTF8')::jsonb
           #> '{payload,components}'
    INTO v_manifest_inventory
    FROM platform.platformops_recovery_sets
    WHERE recovery_set_id=p_recovery_set_id
      AND environment_id=p_environment_id
      AND manifest_sha256=p_manifest_sha256
      AND state='protected';
    IF NOT FOUND OR v_manifest_inventory IS DISTINCT FROM p_component_inventory THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt component binding denied';
    END IF;
    SELECT platform.platformops_import_restore_receipt_v1(
        p_operation_id,p_recovery_set_id,p_environment_id,p_plan_sha256,
        p_manifest_sha256,p_receipt_sha256,p_receipt_bytes,
        p_previous_database_system_id,p_new_database_system_id,
        p_object_merkle_sha256,p_locator_remap_sha256,
        p_safety_evidence_sha256,p_component_inventory
    ) INTO v_result;
    RETURN v_result;
END;
$$;


ALTER FUNCTION platform.platformops_import_restore_receipt_v2(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_plan_sha256 text, p_manifest_sha256 text, p_receipt_sha256 text, p_receipt_bytes bytea, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_component_inventory jsonb) OWNER TO harpy_owner;

--
-- Name: platformops_import_restore_receipt_v3(uuid, uuid, uuid, text, text, text, bytea, uuid, uuid, text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_import_restore_receipt_v3(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_plan_sha256 text, p_manifest_sha256 text, p_receipt_sha256 text, p_receipt_bytes bytea, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_drain_ack_sha256 text, p_switch_ack_sha256 text, p_control_database_locator_sha256 text, p_scratch_database_locator_sha256 text, p_component_inventory jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_receipt jsonb;
    v_manifest_inventory jsonb;
    v_existing platform.platformops_restore_receipt_imports%ROWTYPE;
    v_lineage_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_operation_id IS NULL OR p_recovery_set_id IS NULL
       OR p_environment_id IS NULL OR p_previous_database_system_id IS NULL
       OR p_new_database_system_id IS NULL
       OR p_previous_database_system_id=p_new_database_system_id
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR p_receipt_sha256 !~ '^[0-9a-f]{64}$'
       OR p_object_merkle_sha256 !~ '^[0-9a-f]{64}$'
       OR p_locator_remap_sha256 !~ '^[0-9a-f]{64}$'
       OR p_safety_evidence_sha256 !~ '^[0-9a-f]{64}$'
       OR p_drain_ack_sha256 !~ '^[0-9a-f]{64}$'
       OR p_switch_ack_sha256 !~ '^[0-9a-f]{64}$'
       OR p_control_database_locator_sha256 !~ '^[0-9a-f]{64}$'
       OR p_scratch_database_locator_sha256 !~ '^[0-9a-f]{64}$'
       OR p_control_database_locator_sha256=
          p_scratch_database_locator_sha256
       OR pg_catalog.octet_length(p_receipt_bytes) NOT BETWEEN 1 AND 2097152
       OR p_receipt_sha256<>pg_catalog.encode(
           pg_catalog.sha256(p_receipt_bytes),'hex'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt import v3 denied';
    END IF;
    SELECT pg_catalog.convert_from(manifest_bytes,'UTF8')::jsonb
           #> '{payload,components}'
    INTO v_manifest_inventory
    FROM platform.platformops_recovery_sets
    WHERE recovery_set_id=p_recovery_set_id
      AND environment_id=p_environment_id
      AND manifest_sha256=p_manifest_sha256
      AND state='protected';
    IF NOT FOUND OR v_manifest_inventory IS DISTINCT FROM
       p_component_inventory THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt component import v3 denied';
    END IF;
    v_receipt := pg_catalog.convert_from(p_receipt_bytes,'UTF8')::jsonb;
    IF v_receipt->>'schema' IS DISTINCT FROM
          'harpy-recovery-artifact.v1'
       OR v_receipt->>'purpose' IS DISTINCT FROM 'restore_receipt'
       OR v_receipt->>'environment_id' IS DISTINCT FROM
          p_environment_id::text
       OR v_receipt->>'operation_id' IS DISTINCT FROM p_operation_id::text
       OR v_receipt->>'artifact_id' IS DISTINCT FROM p_operation_id::text
       OR v_receipt->>'algorithm' IS DISTINCT FROM 'Ed25519'
       OR v_receipt->>'payload_sha256' !~ '^[0-9a-f]{64}$'
       OR pg_catalog.octet_length(v_receipt->>'signature')<1
       OR (v_receipt->>'issued_at')::timestamptz>v_now
       OR (v_receipt->>'expires_at')::timestamptz<=v_now
       OR v_receipt#>>'{payload,schema}' IS DISTINCT FROM
          'restore-receipt-payload.v2'
       OR v_receipt#>>'{payload,operation_id}' IS DISTINCT FROM
          p_operation_id::text
       OR v_receipt#>>'{payload,recovery_set_id}' IS DISTINCT FROM
          p_recovery_set_id::text
       OR v_receipt#>>'{payload,plan_sha256}' IS DISTINCT FROM p_plan_sha256
       OR v_receipt#>>'{payload,manifest_sha256}' IS DISTINCT FROM
          p_manifest_sha256
       OR v_receipt#>>'{payload,identity,environment_id}' IS DISTINCT FROM
          p_environment_id::text
       OR v_receipt#>>'{payload,previous_database_system_id}' IS DISTINCT FROM
          p_previous_database_system_id::text
       OR v_receipt#>>'{payload,new_database_system_id}' IS DISTINCT FROM
          p_new_database_system_id::text
       OR v_receipt#>>'{payload,previous_database_locator_sha256}'
          IS DISTINCT FROM p_control_database_locator_sha256
       OR v_receipt#>>'{payload,new_database_locator_sha256}'
          IS DISTINCT FROM p_scratch_database_locator_sha256
       OR v_receipt#>>'{payload,drain_ack_sha256}' IS DISTINCT FROM
          p_drain_ack_sha256
       OR v_receipt#>>'{payload,switch_ack_sha256}' IS DISTINCT FROM
          p_switch_ack_sha256
       OR v_receipt#>>'{payload,object_merkle_sha256}' IS DISTINCT FROM
          p_object_merkle_sha256
       OR v_receipt#>>'{payload,locator_remap_sha256}' IS DISTINCT FROM
          p_locator_remap_sha256
       OR v_receipt#>>'{payload,safety_evidence_sha256}' IS DISTINCT FROM
          p_safety_evidence_sha256
       OR (v_receipt#>>'{payload,seeded}')::boolean
       OR (v_receipt#>>'{payload,owner_changed}')::boolean
       OR (v_receipt#>>'{payload,tenant_replaced}')::boolean
       OR v_receipt#>>'{payload,switch_outcome}' IS DISTINCT FROM
          'switched_same_environment' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore receipt import v3 evidence denied';
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformops_restore_receipt_imports
    WHERE operation_id=p_operation_id FOR UPDATE;
    IF FOUND THEN
        RETURN (v_existing.recovery_set_id,v_existing.environment_id,
                v_existing.plan_sha256,v_existing.manifest_sha256,
                v_existing.receipt_sha256,v_existing.receipt_bytes,
                v_existing.new_database_system_id,
                v_existing.switch_ack_sha256,
                v_existing.component_inventory)
            IS NOT DISTINCT FROM
               (p_recovery_set_id,p_environment_id,p_plan_sha256,
                p_manifest_sha256,p_receipt_sha256,p_receipt_bytes,
                p_new_database_system_id,p_switch_ack_sha256,
                p_component_inventory)
           AND EXISTS (
               SELECT 1 FROM platform.platformops_database_lineages
               WHERE environment_id=p_environment_id
                 AND current_database_system_id=p_new_database_system_id
           );
    END IF;
    INSERT INTO platform.platformops_restore_receipt_imports(
        operation_id,recovery_set_id,environment_id,plan_sha256,
        manifest_sha256,receipt_sha256,receipt_bytes,
        previous_database_system_id,new_database_system_id,
        object_merkle_sha256,locator_remap_sha256,safety_evidence_sha256,
        drain_ack_sha256,switch_ack_sha256,
        control_database_locator_sha256,scratch_database_locator_sha256,
        component_inventory,imported_at
    ) VALUES (
        p_operation_id,p_recovery_set_id,p_environment_id,p_plan_sha256,
        p_manifest_sha256,p_receipt_sha256,p_receipt_bytes,
        p_previous_database_system_id,p_new_database_system_id,
        p_object_merkle_sha256,p_locator_remap_sha256,p_safety_evidence_sha256,
        p_drain_ack_sha256,p_switch_ack_sha256,
        p_control_database_locator_sha256,p_scratch_database_locator_sha256,
        p_component_inventory,v_now
    );
    UPDATE platform.platformops_database_lineages
    SET current_database_system_id=p_new_database_system_id,
        generation=generation+1,updated_at=v_now
    WHERE environment_id=p_environment_id
      AND current_database_system_id=p_previous_database_system_id
    RETURNING generation INTO v_lineage_generation;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='restored database lineage import denied';
    END IF;
    INSERT INTO platform.platformops_database_lineage_events(
        operation_id,environment_id,previous_database_system_id,
        database_system_id,generation,event_kind,occurred_at
    ) VALUES (
        p_operation_id,p_environment_id,p_previous_database_system_id,
        p_new_database_system_id,v_lineage_generation,'restored',v_now
    );
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platformops_import_restore_receipt_v3(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_plan_sha256 text, p_manifest_sha256 text, p_receipt_sha256 text, p_receipt_bytes bytea, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_drain_ack_sha256 text, p_switch_ack_sha256 text, p_control_database_locator_sha256 text, p_scratch_database_locator_sha256 text, p_component_inventory jsonb) OWNER TO harpy_owner;

--
-- Name: platformops_initialize_database_lineage_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_initialize_database_lineage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_system_identifier text;
    v_database_system_id uuid;
BEGIN
    IF NEW.deployment_mode <> 'onpremise' THEN
        RETURN NEW;
    END IF;
    SELECT identity.database_system_identifier
      INTO v_system_identifier
      FROM platform.environment_identity AS identity
     WHERE identity.environment_id = NEW.environment_id;
    IF v_system_identifier IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'database lineage environment identity is missing';
    END IF;
    v_database_system_id := pg_catalog.gen_random_uuid();
    INSERT INTO platform.platformops_database_lineages(
        environment_id,lineage_id,current_database_system_id,
        database_system_identifier,generation,created_at,updated_at
    ) VALUES (
        NEW.environment_id,NEW.environment_id,v_database_system_id,
        v_system_identifier,1,NEW.created_at,NEW.created_at
    );
    INSERT INTO platform.platformops_database_lineage_events(
        operation_id,environment_id,previous_database_system_id,
        database_system_id,generation,event_kind,occurred_at
    ) VALUES (
        NEW.operation_id,NEW.environment_id,NULL,v_database_system_id,
        1,'initialized',NEW.created_at
    );
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformops_initialize_database_lineage_v1() OWNER TO harpy_owner;

--
-- Name: platformops_initialize_recovery_protection_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_initialize_recovery_protection_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.deployment_mode = 'onpremise' THEN
        INSERT INTO platform.platformops_recovery_protections(
            environment_id,state,generation,created_at,updated_at
        ) VALUES (NEW.environment_id,'unprotected',0,NEW.created_at,NEW.created_at)
        ON CONFLICT (environment_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.platformops_initialize_recovery_protection_v1() OWNER TO harpy_owner;

--
-- Name: platformops_installation_recovery_initialize_v1(uuid, uuid, uuid, name, text, bigint, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_installation_recovery_initialize_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_signing_generation bigint, p_trust_bundle_sha256 text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.platformops_installation_recovery_identities%ROWTYPE;
    v_state text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL OR p_schema_name IS NULL
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation recovery identity initialization denied';
    END IF;
    IF NOT platform.tenancy_activation_assert_v1(
        p_operation_id, p_tenant_id, p_schema_name
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'installation recovery identity activation conflicts';
    END IF;
    IF p_deployment_mode = 'onpremise' THEN
        IF p_signing_generation IS NULL OR p_signing_generation < 1
           OR p_trust_bundle_sha256 !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'on-premise recovery identity is invalid';
        END IF;
        v_state := 'active';
    ELSIF p_deployment_mode = 'saas' THEN
        IF p_signing_generation IS NOT NULL OR p_trust_bundle_sha256 IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'SaaS recovery identity must be not applicable';
        END IF;
        v_state := 'not_applicable';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'deployment mode is invalid';
    END IF;
    SELECT * INTO v_existing
    FROM platform.platformops_installation_recovery_identities AS identity
    WHERE identity.operation_id = p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_existing.deployment_mode IS DISTINCT FROM p_deployment_mode
           OR v_existing.identity_state IS DISTINCT FROM v_state
           OR v_existing.signing_generation IS DISTINCT FROM p_signing_generation
           OR v_existing.trust_bundle_sha256 IS DISTINCT FROM p_trust_bundle_sha256
           OR v_existing.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'installation recovery identity replay conflicts';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.platformops_installation_recovery_identities (
        operation_id, environment_id, tenant_id, deployment_mode,
        identity_state, signing_generation, trust_bundle_sha256,
        manifest_sha256, created_at
    ) VALUES (
        p_operation_id, p_environment_id, p_tenant_id, p_deployment_mode,
        v_state, p_signing_generation, p_trust_bundle_sha256,
        p_manifest_sha256, pg_catalog.statement_timestamp()
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.platformops_installation_recovery_initialize_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_signing_generation bigint, p_trust_bundle_sha256 text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_installation_recovery_initialize_v2(uuid, uuid, uuid, name, text, bigint, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_installation_recovery_initialize_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_signing_generation bigint, p_trust_bundle_sha256 text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_replayed boolean;
BEGIN
    IF NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id,
        'platformops.initialize_recovery_signing_identity',
        p_environment_id, p_tenant_id, p_schema_name,
        'environment_initialize'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation recovery capability required';
    END IF;
    v_replayed := platform.platformops_installation_recovery_initialize_v1(
        p_operation_id, p_environment_id, p_tenant_id, p_schema_name,
        p_deployment_mode, p_signing_generation, p_trust_bundle_sha256,
        p_manifest_sha256
    );
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id,
        'platformops.initialize_recovery_signing_identity'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'installation recovery capability consume failed';
    END IF;
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.platformops_installation_recovery_initialize_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_deployment_mode text, p_signing_generation bigint, p_trust_bundle_sha256 text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_list_alert_events_v1(uuid, text, text, integer, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_list_alert_events_v1(p_environment_id uuid, p_service_name text, p_status text, p_limit integer, p_offset integer) RETURNS TABLE(id uuid, environment_id uuid, alert_rule_id uuid, service_name text, previous_status text, current_status text, channels_used text[], message text, actor_id uuid, resolved_at timestamp with time zone, created_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 100 OR p_offset < 0 THEN
        RAISE EXCEPTION 'alert event query is invalid' USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT event.id, event.environment_id, event.alert_rule_id,
        event.service_name, event.previous_status, event.current_status,
        event.channels_used, event.message, event.actor_id, event.resolved_at,
        event.created_at, count(*) OVER ()
    FROM platform.platformops_alert_events AS event
    WHERE event.environment_id = p_environment_id
      AND (p_service_name = '' OR event.service_name = p_service_name)
      AND (p_status = '' OR event.current_status = p_status)
    ORDER BY event.created_at DESC, event.id
    LIMIT p_limit OFFSET p_offset;
END;
$$;


ALTER FUNCTION platform.platformops_list_alert_events_v1(p_environment_id uuid, p_service_name text, p_status text, p_limit integer, p_offset integer) OWNER TO harpy_owner;

--
-- Name: platformops_list_alert_rules_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_list_alert_rules_v1(p_environment_id uuid) RETURNS SETOF platform.platformops_alert_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT rule.* FROM platform.platformops_alert_rules AS rule
    WHERE rule.environment_id = p_environment_id
    ORDER BY rule.name, rule.id;
END;
$$;


ALTER FUNCTION platform.platformops_list_alert_rules_v1(p_environment_id uuid) OWNER TO harpy_owner;

