-- Name: platformops_list_recovery_sets_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_list_recovery_sets_v1(p_environment_id uuid) RETURNS TABLE(recovery_set_id uuid, operation_id uuid, environment_id uuid, sequence bigint, state text, manifest_sha256 text, legal_hold boolean, database_system_id uuid, protected_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT r.recovery_set_id, r.operation_id, r.environment_id,
           r.sequence, r.state, r.manifest_sha256, r.legal_hold,
           r.database_system_id, r.protected_at
      FROM platform.platformops_recovery_sets r
     WHERE r.environment_id = p_environment_id AND r.state <> 'deleted'
     ORDER BY r.sequence DESC, r.recovery_set_id DESC;
END;
$$;


