CREATE FUNCTION platform.platformops_list_retention_candidates_v1(p_environment_id uuid) RETURNS TABLE(recovery_set_id uuid, manifest_sha256 text, protected_at timestamp with time zone, legal_hold boolean)
    LANGUAGE plpgsql SECURITY DEFINER
