    AS $$
BEGIN
    RETURN QUERY
    SELECT r.recovery_set_id, r.manifest_sha256, r.protected_at, r.legal_hold
      FROM platform.platformops_recovery_sets r
     WHERE r.environment_id = p_environment_id AND r.state = 'protected'
