-- Name: platformops_mark_anchor_handoff_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_mark_anchor_handoff_v1(p_operation_id uuid, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE platform.platformops_recovery_control_operations
       SET state='handoff_ready',updated_at=p_occurred_at
     WHERE operation_id=p_operation_id
       AND operation_kind IN ('anchor_register','anchor_delete')
       AND state IN ('accepted','handoff_ready');
    RETURN FOUND;
END;
$$;


