CREATE FUNCTION platform.platformops_mark_recovery_set_deleting_v1(p_recovery_set_id uuid, p_expected_manifest_sha256 text, p_updated_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE platform.platformops_recovery_sets
       SET state = 'deleting', updated_at = p_updated_at
     WHERE recovery_set_id = p_recovery_set_id AND state = 'protected'
