--
-- Name: platformops_mark_restore_switched_v1(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_mark_restore_switched_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_object_merkle_sha256 !~ '^[0-9a-f]{64}$'
       OR p_locator_remap_sha256 !~ '^[0-9a-f]{64}$'
       OR p_safety_evidence_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore switch transition denied';
    END IF;
    UPDATE platform.platformops_restore_operations AS restore
    SET state='switched',updated_at=v_now
    FROM platform.platformops_restore_execution_attempts AS attempt
    WHERE restore.operation_id=p_operation_id AND restore.state='verifying'
      AND attempt.attempt_id=p_attempt_id
      AND attempt.operation_id=restore.operation_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active' AND attempt.lease_expires_at>v_now
      AND attempt.archive_readback_sha256 IS NOT NULL
      AND attempt.restored_database_system_id IS NOT NULL;
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET claimed_restore_state='switched',
        object_merkle_sha256=p_object_merkle_sha256,
        locator_remap_sha256=p_locator_remap_sha256,
        safety_evidence_sha256=p_safety_evidence_sha256,
        heartbeat_at=v_now,lease_expires_at=v_now+interval '2 minutes'
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_mark_restore_switched_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_mark_restore_switched_v2(uuid, uuid, uuid, text, text, text, text, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_mark_restore_switched_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_switch_ack_sha256 text, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_control_database_locator_sha256 text, p_scratch_database_locator_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_changed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR p_switch_ack_sha256 !~ '^[0-9a-f]{64}$'
       OR p_control_database_locator_sha256 !~ '^[0-9a-f]{64}$'
       OR p_scratch_database_locator_sha256 !~ '^[0-9a-f]{64}$'
       OR p_control_database_locator_sha256=
          p_scratch_database_locator_sha256
       OR p_previous_database_system_id IS NULL
       OR p_new_database_system_id IS NULL
       OR p_previous_database_system_id=p_new_database_system_id THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore switch authority binding denied';
    END IF;
    PERFORM 1
    FROM platform.platformops_restore_execution_attempts AS attempt
    JOIN platform.platformops_restore_operations AS restore
      ON restore.operation_id=attempt.operation_id
    JOIN platform.platformops_recovery_sets AS recovery
      ON recovery.recovery_set_id=restore.recovery_set_id
    WHERE attempt.attempt_id=p_attempt_id
      AND attempt.operation_id=p_operation_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active'
      AND attempt.claimed_restore_state='verifying'
      AND restore.state='verifying'
      AND recovery.database_system_id=p_previous_database_system_id
      AND attempt.restored_database_system_id=p_new_database_system_id
      AND attempt.control_database_locator_sha256=
          p_control_database_locator_sha256
      AND attempt.scratch_database_locator_sha256=
          p_scratch_database_locator_sha256
      AND attempt.switch_ack_sha256 IS NULL
    FOR UPDATE OF attempt,restore;
    IF NOT FOUND THEN
        RETURN EXISTS (
            SELECT 1
            FROM platform.platformops_restore_execution_attempts AS attempt
            JOIN platform.platformops_restore_operations AS restore
              ON restore.operation_id=attempt.operation_id
            WHERE attempt.attempt_id=p_attempt_id
              AND attempt.operation_id=p_operation_id
              AND attempt.lease_token=p_lease_token
              AND attempt.lifecycle_state='active'
              AND attempt.claimed_restore_state='switched'
              AND restore.state='switched'
              AND attempt.switch_ack_sha256=p_switch_ack_sha256
              AND attempt.restored_database_system_id=p_new_database_system_id
              AND attempt.control_database_locator_sha256=
                  p_control_database_locator_sha256
              AND attempt.scratch_database_locator_sha256=
                  p_scratch_database_locator_sha256
        );
    END IF;
    SELECT platform.platformops_mark_restore_switched_v1(
        p_operation_id,p_attempt_id,p_lease_token,
        p_object_merkle_sha256,p_locator_remap_sha256,
        p_safety_evidence_sha256
    ) INTO v_changed;
    IF NOT v_changed THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET switch_ack_sha256=p_switch_ack_sha256
    WHERE attempt_id=p_attempt_id AND operation_id=p_operation_id
      AND lease_token=p_lease_token
      AND lifecycle_state='active'
      AND claimed_restore_state='switched'
      AND switch_ack_sha256 IS NULL;
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_mark_restore_switched_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_object_merkle_sha256 text, p_locator_remap_sha256 text, p_safety_evidence_sha256 text, p_switch_ack_sha256 text, p_previous_database_system_id uuid, p_new_database_system_id uuid, p_control_database_locator_sha256 text, p_scratch_database_locator_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_prune_observability_v1(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_prune_observability_v1(p_environment_id uuid, p_before timestamp with time zone, p_limit integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE deleted_count bigint;
BEGIN
    IF p_limit NOT BETWEEN 1 AND 10000 OR
       p_before > pg_catalog.clock_timestamp() - interval '30 days' THEN
        RAISE EXCEPTION 'observability prune boundary is invalid' USING ERRCODE = '22023';
    END IF;
    WITH candidates AS (
        SELECT id FROM platform.platformops_trace_spans
        WHERE environment_id = p_environment_id AND started_at < p_before
        ORDER BY started_at, id LIMIT p_limit FOR UPDATE SKIP LOCKED
    ), removed AS (
        DELETE FROM platform.platformops_trace_spans AS span
        USING candidates WHERE span.id = candidates.id RETURNING span.id
    ) SELECT count(*) INTO deleted_count FROM removed;
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION platform.platformops_prune_observability_v1(p_environment_id uuid, p_before timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: platformops_publish_recovery_kit_v1(uuid, bytea, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_publish_recovery_kit_v1(p_operation_id uuid, p_artifact_bytes bytea, p_artifact_sha256 bytea, p_ack_verifier_sha256 bytea, p_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_operation_id IS NULL OR pg_catalog.octet_length(p_artifact_bytes)=0 OR
       pg_catalog.sha256(p_artifact_bytes) IS DISTINCT FROM p_artifact_sha256 OR
       pg_catalog.octet_length(p_ack_verifier_sha256)<>32 OR
       p_expires_at<=p_occurred_at THEN
        RETURN false;
    END IF;
    UPDATE platform.platformops_recovery_control_operations
       SET artifact_bytes=p_artifact_bytes,artifact_sha256=p_artifact_sha256,
           ack_verifier_sha256=p_ack_verifier_sha256,expires_at=p_expires_at,
           state='kit_ready',kit_claim_state='ready',updated_at=p_occurred_at
     WHERE operation_id=p_operation_id AND operation_kind IN ('enable','rotate')
       AND state IN ('accepted','handoff_ready') AND kit_claim_state='pending';
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_publish_recovery_kit_v1(p_operation_id uuid, p_artifact_bytes bytea, p_artifact_sha256 bytea, p_ack_verifier_sha256 bytea, p_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_record_anchor_operation_v1(uuid, uuid, uuid, text, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_record_anchor_operation_v1(p_operation_id uuid, p_environment_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_kind text, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_existing platform.platformops_recovery_control_operations%ROWTYPE;
BEGIN
    IF p_operation_id IS NULL OR p_environment_id IS NULL OR p_actor_user_id IS NULL OR
       p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       pg_catalog.octet_length(p_request_sha256)<>32 OR
       p_kind NOT IN ('anchor_register','anchor_delete') OR p_occurred_at IS NULL THEN
        RETURN false;
    END IF;
    SELECT * INTO v_existing FROM platform.platformops_recovery_control_operations
     WHERE operation_id=p_operation_id FOR SHARE;
    IF FOUND THEN
        RETURN v_existing.environment_id=p_environment_id AND
            v_existing.actor_user_id=p_actor_user_id AND
            v_existing.idempotency_key=p_idempotency_key AND
            v_existing.request_sha256=p_request_sha256 AND
            v_existing.operation_kind=p_kind;
    END IF;
    INSERT INTO platform.platformops_recovery_control_operations(
        operation_id,environment_id,operation_kind,actor_user_id,idempotency_key,
        request_sha256,state,kit_claim_state,created_at,updated_at
    ) VALUES (p_operation_id,p_environment_id,p_kind,p_actor_user_id,
        p_idempotency_key,p_request_sha256,'accepted','not_applicable',
        p_occurred_at,p_occurred_at);
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platformops_record_anchor_operation_v1(p_operation_id uuid, p_environment_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_kind text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_record_recovery_component_v1(uuid, text, text, text, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_record_recovery_component_v1(p_recovery_set_id uuid, p_component_kind text, p_object_key text, p_object_version_id text, p_ciphertext_sha256 text, p_ciphertext_bytes bigint, p_verified_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_existing platform.platformops_recovery_components%ROWTYPE;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM platform.platformops_recovery_sets
         WHERE recovery_set_id = p_recovery_set_id
           AND state IN ('copying','verifying')
    ) THEN
        RAISE EXCEPTION 'recovery set cannot accept components' USING ERRCODE = '55000';
    END IF;
    SELECT * INTO v_existing FROM platform.platformops_recovery_components
     WHERE recovery_set_id = p_recovery_set_id AND component_kind = p_component_kind;
    IF FOUND THEN
        IF v_existing.object_key <> p_object_key
           OR v_existing.object_version_id <> p_object_version_id
           OR v_existing.ciphertext_sha256 <> p_ciphertext_sha256
           OR v_existing.ciphertext_bytes <> p_ciphertext_bytes
           OR v_existing.verified_at <> p_verified_at THEN
            RAISE EXCEPTION 'recovery component conflicts' USING ERRCODE = '23505';
        END IF;
        RETURN;
    END IF;
    INSERT INTO platform.platformops_recovery_components(
        recovery_set_id, component_kind, object_key, object_version_id,
        ciphertext_sha256, ciphertext_bytes, verified_at
    ) VALUES (
        p_recovery_set_id, p_component_kind, p_object_key, p_object_version_id,
        p_ciphertext_sha256, p_ciphertext_bytes, p_verified_at
    );
END;
$$;


ALTER FUNCTION platform.platformops_record_recovery_component_v1(p_recovery_set_id uuid, p_component_kind text, p_object_key text, p_object_version_id text, p_ciphertext_sha256 text, p_ciphertext_bytes bigint, p_verified_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_record_recovery_component_v3(uuid, uuid, uuid, text, text, text, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_record_recovery_component_v3(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_component_kind text, p_object_key text, p_object_version_id text, p_ciphertext_sha256 text, p_ciphertext_bytes bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_attempt_state text;
    v_lease_expires_at timestamptz;
    v_recovery_state text;
    v_environment_id uuid;
    v_existing_key text;
    v_existing_version text;
    v_existing_sha256 text;
    v_existing_bytes bigint;
    v_expected_key text;
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-backup-executor'
       OR p_component_kind NOT IN (
           'database_archive','documents_inventory','key_custody',
           'owner_anchor','protected_authority'
       )
       OR p_object_version_id IS NULL
       OR pg_catalog.octet_length(p_object_version_id) NOT BETWEEN 1 AND 1024
       OR p_ciphertext_sha256 !~ '^[0-9a-f]{64}$'
       OR p_ciphertext_bytes < 1 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery component record denied';
    END IF;
    SELECT attempt.lifecycle_state,attempt.lease_expires_at
    INTO v_attempt_state,v_lease_expires_at
    FROM platform.platformops_recovery_execution_attempts AS attempt
    WHERE attempt.attempt_id=p_attempt_id
      AND attempt.recovery_set_id=p_recovery_set_id
      AND attempt.lease_token=p_lease_token
    FOR UPDATE;
    IF NOT FOUND THEN RETURN false; END IF;
    SELECT recovery.state,recovery.environment_id
    INTO v_recovery_state,v_environment_id
    FROM platform.platformops_recovery_sets AS recovery
    WHERE recovery.recovery_set_id=p_recovery_set_id
    FOR UPDATE;
    IF NOT FOUND OR v_attempt_state<>'active'
       OR v_lease_expires_at<=v_now
       OR v_recovery_state NOT IN ('copying','verifying') THEN
        RETURN false;
    END IF;
    v_expected_key := 'environments/' || v_environment_id::text ||
        '/recovery-sets/' || p_recovery_set_id::text ||
        '/components/' || p_component_kind || '.fcbackup1';
    IF p_object_key IS DISTINCT FROM v_expected_key THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery component key denied';
    END IF;
    SELECT object_key,object_version_id,ciphertext_sha256,ciphertext_bytes
    INTO v_existing_key,v_existing_version,v_existing_sha256,v_existing_bytes
    FROM platform.platformops_recovery_components
    WHERE recovery_set_id=p_recovery_set_id
      AND component_kind=p_component_kind;
    IF FOUND THEN
        IF (v_existing_key,v_existing_version,
            v_existing_sha256,v_existing_bytes)
           IS DISTINCT FROM
           (p_object_key,p_object_version_id,
            p_ciphertext_sha256,p_ciphertext_bytes) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='recovery component conflicts';
        END IF;
    ELSE
        INSERT INTO platform.platformops_recovery_components(
            recovery_set_id,component_kind,object_key,object_version_id,
            ciphertext_sha256,ciphertext_bytes,verified_at
        ) VALUES (
            p_recovery_set_id,p_component_kind,p_object_key,p_object_version_id,
            p_ciphertext_sha256,p_ciphertext_bytes,v_now
        );
    END IF;
    UPDATE platform.platformops_recovery_execution_attempts
    SET heartbeat_at=v_now,lease_expires_at=v_now+interval '2 minutes'
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_record_recovery_component_v3(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_component_kind text, p_object_key text, p_object_version_id text, p_ciphertext_sha256 text, p_ciphertext_bytes bigint) OWNER TO harpy_owner;

--
-- Name: platformops_record_recovery_components_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_record_recovery_components_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_components jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_kind text;
    v_value jsonb;
    v_changed boolean;
BEGIN
    IF pg_catalog.jsonb_typeof(p_components)<>'object'
       OR pg_catalog.jsonb_object_length(p_components)<>5
       OR NOT p_components ?& ARRAY[
           'database_archive','documents_inventory','key_custody',
           'owner_anchor','protected_authority'
       ] THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='recovery component batch denied';
    END IF;
    FOREACH v_kind IN ARRAY ARRAY[
        'database_archive','documents_inventory','key_custody',
        'owner_anchor','protected_authority'
    ] LOOP
        v_value := p_components->v_kind;
        IF pg_catalog.jsonb_typeof(v_value)<>'object'
           OR pg_catalog.jsonb_object_length(v_value)<>4
           OR (v_value->>'ciphertext_sha256') !~ '^[0-9a-f]{64}$'
           OR (v_value->>'ciphertext_bytes') !~ '^[1-9][0-9]*$' THEN
            RAISE EXCEPTION USING ERRCODE='42501',
                MESSAGE='recovery component batch denied';
        END IF;
        SELECT platform.platformops_record_recovery_component_v3(
            p_recovery_set_id,p_attempt_id,p_lease_token,v_kind,
            v_value->>'object_key',v_value->>'object_version_id',
            v_value->>'ciphertext_sha256',
            (v_value->>'ciphertext_bytes')::bigint
        ) INTO v_changed;
        IF NOT v_changed THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.platformops_record_recovery_components_v1(p_recovery_set_id uuid, p_attempt_id uuid, p_lease_token uuid, p_components jsonb) OWNER TO harpy_owner;

--
-- Name: platformops_record_signing_bundle_v1(uuid, bigint, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_record_signing_bundle_v1(p_environment_id uuid, p_generation bigint, p_bundle_sha256 text, p_bundle_bytes bytea, p_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.platformops_recovery_signing_bundles%ROWTYPE;
    v_latest bigint;
BEGIN
    IF p_generation <= 0
       OR p_bundle_sha256 !~ '^[0-9a-f]{64}$'
       OR octet_length(p_bundle_bytes) NOT BETWEEN 1 AND 1048576 THEN
        RAISE EXCEPTION 'invalid recovery signing bundle'
            USING ERRCODE = '23514';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('platformops:signing:' || p_environment_id::text, 0)
    );
    SELECT * INTO v_existing
    FROM platform.platformops_recovery_signing_bundles
    WHERE environment_id = p_environment_id AND generation = p_generation;
    IF FOUND THEN
        IF v_existing.bundle_sha256 <> p_bundle_sha256
           OR v_existing.bundle_bytes <> p_bundle_bytes
           OR v_existing.created_at <> p_created_at THEN
            RAISE EXCEPTION 'recovery signing generation conflicts'
                USING ERRCODE = '23505';
        END IF;
        RETURN;
    END IF;
    SELECT max(generation) INTO v_latest
    FROM platform.platformops_recovery_signing_bundles
    WHERE environment_id = p_environment_id;
    IF p_generation <> COALESCE(v_latest, 0) + 1 THEN
        RAISE EXCEPTION 'recovery signing generation is not monotonic'
            USING ERRCODE = '40001';
    END IF;
    INSERT INTO platform.platformops_recovery_signing_bundles(
        environment_id, generation, bundle_sha256, bundle_bytes, created_at
    ) VALUES (
        p_environment_id, p_generation, p_bundle_sha256, p_bundle_bytes, p_created_at
    );
END;
$_$;


ALTER FUNCTION platform.platformops_record_signing_bundle_v1(p_environment_id uuid, p_generation bigint, p_bundle_sha256 text, p_bundle_bytes bytea, p_created_at timestamp with time zone) OWNER TO harpy_owner;

