-- Name: platformops_record_trace_v1(uuid, uuid, text, text, text, text, text, text, text, text, integer, timestamp with time zone, timestamp with time zone, numeric, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_record_trace_v1(p_id uuid, p_environment_id uuid, p_correlation_id text, p_span_id text, p_parent_span_id text, p_service_name text, p_operation text, p_span_kind text, p_method text, p_path text, p_status_code integer, p_started_at timestamp with time zone, p_ended_at timestamp with time zone, p_duration_ms numeric, p_level text, p_message text, p_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    INSERT INTO platform.platformops_trace_spans(
        id, environment_id, correlation_id, span_id, parent_span_id,
        service_name, operation, span_kind, method, path, status_code,
        started_at, ended_at, duration_ms, level, message, created_at
    ) VALUES (
        p_id, p_environment_id, p_correlation_id, p_span_id, p_parent_span_id,
        p_service_name, p_operation, p_span_kind, p_method, p_path, p_status_code,
        p_started_at, p_ended_at, p_duration_ms, p_level, p_message, p_created_at
    ) ON CONFLICT (environment_id, span_id) DO NOTHING;
END;
$$;


