--
-- Name: platformops_request_recovery_control_v1(uuid, uuid, uuid, text, bytea, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_request_recovery_control_v1(p_operation_id uuid, p_environment_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_operation_kind text, p_claim_algorithm text, p_claim_public_key bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(operation_id uuid, state text, kit_claim_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_protection platform.platformops_recovery_protections%ROWTYPE;
    v_existing platform.platformops_recovery_control_operations%ROWTYPE;
    v_tenant_id uuid;
BEGIN
    IF p_operation_id IS NULL OR p_environment_id IS NULL OR p_actor_user_id IS NULL OR
       p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_operation_kind NOT IN ('enable','rotate','disable') OR p_occurred_at IS NULL OR
       (p_operation_kind IN ('enable','rotate') AND
        (p_claim_algorithm IS DISTINCT FROM
         'HPKE-v1-X25519-HKDF-SHA256-AES-256-GCM' OR
         pg_catalog.octet_length(p_claim_public_key) <> 32)) OR
       (p_operation_kind = 'disable' AND
        (p_claim_algorithm IS NOT NULL OR p_claim_public_key IS NOT NULL)) THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='recovery control request is invalid';
    END IF;
    SELECT * INTO v_existing
      FROM platform.platformops_recovery_control_operations AS operation
     WHERE operation.operation_id=p_operation_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id OR
           v_existing.actor_user_id IS DISTINCT FROM p_actor_user_id OR
           v_existing.idempotency_key IS DISTINCT FROM p_idempotency_key OR
           v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.operation_kind IS DISTINCT FROM p_operation_kind OR
           v_existing.claim_algorithm IS DISTINCT FROM p_claim_algorithm OR
           v_existing.claim_public_key IS DISTINCT FROM p_claim_public_key THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='recovery control replay conflicts';
        END IF;
        RETURN QUERY SELECT v_existing.operation_id,v_existing.state,
                            v_existing.kit_claim_state;
        RETURN;
    END IF;
    SELECT identity.tenant_id INTO v_tenant_id
      FROM platform.platformops_installation_recovery_identities AS identity
     WHERE identity.environment_id=p_environment_id
       AND identity.deployment_mode='onpremise' AND identity.identity_state='active'
     FOR SHARE;
    IF v_tenant_id IS NULL OR NOT platform.iam_platform_current_owner_v1(
        v_tenant_id,p_actor_user_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current owner is required';
    END IF;
    SELECT * INTO v_protection
      FROM platform.platformops_recovery_protections AS protection
     WHERE protection.environment_id=p_environment_id FOR UPDATE;
    IF NOT FOUND OR v_protection.current_operation_id IS NOT NULL OR
       (p_operation_kind='enable' AND v_protection.state<>'unprotected') OR
       (p_operation_kind IN ('rotate','disable') AND v_protection.state<>'protected') THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='recovery protection state conflicts';
    END IF;
    IF p_operation_kind='disable' AND EXISTS (
        SELECT 1 FROM platform.platformops_recovery_sets AS recovery_set
         WHERE recovery_set.environment_id=p_environment_id
           AND recovery_set.state IN ('requested','holding','snapshotting','copying',
                                      'verifying','protected','deleting')
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23000',MESSAGE='retained recovery set blocks disable';
    END IF;
    INSERT INTO platform.platformops_recovery_control_operations(
        operation_id,environment_id,operation_kind,actor_user_id,idempotency_key,
        request_sha256,claim_algorithm,claim_public_key,state,kit_claim_state,
        created_at,updated_at
    ) VALUES (
        p_operation_id,p_environment_id,p_operation_kind,p_actor_user_id,p_idempotency_key,
        p_request_sha256,p_claim_algorithm,p_claim_public_key,'accepted',
        CASE WHEN p_operation_kind='disable' THEN 'not_applicable' ELSE 'pending' END,
        p_occurred_at,p_occurred_at
    );
    UPDATE platform.platformops_recovery_protections
       SET current_operation_id=p_operation_id,
           state=CASE p_operation_kind WHEN 'rotate' THEN 'rotation_pending'
                 WHEN 'disable' THEN 'disable_pending' ELSE 'unprotected' END,
           updated_at=p_occurred_at
     WHERE environment_id=p_environment_id;
    RETURN QUERY SELECT p_operation_id,'accepted'::text,
        CASE WHEN p_operation_kind='disable' THEN 'not_applicable' ELSE 'pending' END;
END;
$_$;


ALTER FUNCTION platform.platformops_request_recovery_control_v1(p_operation_id uuid, p_environment_id uuid, p_actor_user_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_operation_kind text, p_claim_algorithm text, p_claim_public_key bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_request_recovery_set_v1(uuid, uuid, uuid, uuid, text, uuid, bigint, uuid, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_request_recovery_set_v1(p_recovery_set_id uuid, p_operation_id uuid, p_environment_id uuid, p_primary_binding_id uuid, p_tenant_set_sha256 text, p_owner_binding_id uuid, p_owner_binding_generation bigint, p_database_lineage_id uuid, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_created_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.platformops_recovery_sets%ROWTYPE;
    v_sequence bigint;
BEGIN
    IF p_tenant_set_sha256 !~ '^[0-9a-f]{64}$'
       OR p_recovery_trust_bundle_sha256 !~ '^[0-9a-f]{64}$'
       OR p_owner_binding_generation <= 0
       OR p_recovery_signing_generation <= 0 THEN
        RAISE EXCEPTION 'invalid recovery set request'
            USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.platformops_recovery_signing_bundles
        WHERE environment_id = p_environment_id
          AND generation = p_recovery_signing_generation
          AND bundle_sha256 = p_recovery_trust_bundle_sha256
    ) THEN
        RAISE EXCEPTION 'recovery signing bundle is missing'
            USING ERRCODE = 'P0002';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('platformops:recovery:' || p_environment_id::text, 0)
    );
    SELECT * INTO v_existing
    FROM platform.platformops_recovery_sets
    WHERE operation_id = p_operation_id OR recovery_set_id = p_recovery_set_id
    ORDER BY operation_id = p_operation_id DESC
    LIMIT 1;
    IF FOUND THEN
        IF v_existing.recovery_set_id <> p_recovery_set_id
           OR v_existing.operation_id <> p_operation_id
           OR v_existing.environment_id <> p_environment_id
           OR v_existing.primary_binding_id <> p_primary_binding_id
           OR v_existing.tenant_set_sha256 <> p_tenant_set_sha256
           OR v_existing.owner_binding_id <> p_owner_binding_id
           OR v_existing.owner_binding_generation <> p_owner_binding_generation
           OR v_existing.database_lineage_id <> p_database_lineage_id
           OR v_existing.recovery_signing_generation <> p_recovery_signing_generation
           OR v_existing.recovery_trust_bundle_sha256 <> p_recovery_trust_bundle_sha256 THEN
            RAISE EXCEPTION 'recovery set request conflicts'
                USING ERRCODE = '23505';
        END IF;
        RETURN v_existing.sequence;
    END IF;
    SELECT COALESCE(max(sequence), 0) + 1 INTO v_sequence
    FROM platform.platformops_recovery_sets
    WHERE environment_id = p_environment_id;
    INSERT INTO platform.platformops_recovery_sets(
        recovery_set_id, operation_id, environment_id, deployment_mode,
        portability, sequence, state, primary_binding_id, tenant_set_sha256,
        owner_binding_id, owner_binding_generation, database_lineage_id,
        recovery_signing_generation, recovery_trust_bundle_sha256,
        created_at, updated_at
    ) VALUES (
        p_recovery_set_id, p_operation_id, p_environment_id, 'onpremise',
        'same_environment', v_sequence, 'requested', p_primary_binding_id,
        p_tenant_set_sha256, p_owner_binding_id, p_owner_binding_generation,
        p_database_lineage_id, p_recovery_signing_generation,
        p_recovery_trust_bundle_sha256, p_created_at, p_created_at
    );
    RETURN v_sequence;
END;
$_$;


ALTER FUNCTION platform.platformops_request_recovery_set_v1(p_recovery_set_id uuid, p_operation_id uuid, p_environment_id uuid, p_primary_binding_id uuid, p_tenant_set_sha256 text, p_owner_binding_id uuid, p_owner_binding_generation bigint, p_database_lineage_id uuid, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_request_recovery_set_v2(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_request_recovery_set_v2(p_recovery_set_id uuid, p_operation_id uuid, p_environment_id uuid, p_created_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_existing platform.platformops_recovery_sets%ROWTYPE;
    v_primary_binding_id uuid;
    v_tenant_set_sha256 text;
    v_owner_binding_id uuid;
    v_owner_binding_generation bigint;
    v_database_lineage_id uuid;
    v_signing_generation bigint;
    v_trust_bundle_sha256 text;
    v_sequence bigint;
BEGIN
    IF p_recovery_set_id IS NULL OR p_operation_id IS NULL
       OR p_environment_id IS NULL OR p_created_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'invalid recovery set request';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'platformops:recovery:' || p_environment_id::text,0
        )
    );
    SELECT * INTO v_existing
      FROM platform.platformops_recovery_sets
     WHERE operation_id = p_operation_id
        OR recovery_set_id = p_recovery_set_id
     ORDER BY operation_id = p_operation_id DESC
     LIMIT 1;
    IF FOUND THEN
        IF v_existing.recovery_set_id <> p_recovery_set_id
           OR v_existing.operation_id <> p_operation_id
           OR v_existing.environment_id <> p_environment_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'recovery set request conflicts';
        END IF;
        RETURN v_existing.sequence;
    END IF;
    SELECT identity.primary_binding_id,identity.tenant_set_sha256,
           identity.owner_binding_id,identity.owner_binding_generation,
           identity.database_lineage_id
      INTO v_primary_binding_id,v_tenant_set_sha256,
           v_owner_binding_id,v_owner_binding_generation,
           v_database_lineage_id
      FROM platform.platformops_current_environment_identity_v1(
          p_environment_id
      ) AS identity;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'current on-premise recovery identity is unavailable';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.platformops_recovery_protections AS protection
         WHERE protection.environment_id=p_environment_id
           AND protection.state='protected' AND protection.active_kit_sha256 IS NOT NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='acknowledged recovery protection is required';
    END IF;
    SELECT bundle.generation,bundle.bundle_sha256
      INTO v_signing_generation,v_trust_bundle_sha256
      FROM platform.platformops_recovery_signing_bundles AS bundle
     WHERE bundle.environment_id = p_environment_id
     ORDER BY bundle.generation DESC
     LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'current recovery signing bundle is missing';
    END IF;
    SELECT COALESCE(max(recovery.sequence),0) + 1
      INTO v_sequence
      FROM platform.platformops_recovery_sets AS recovery
     WHERE recovery.environment_id = p_environment_id;
    INSERT INTO platform.platformops_recovery_sets(
        recovery_set_id,operation_id,environment_id,deployment_mode,
        portability,sequence,state,primary_binding_id,tenant_set_sha256,
        owner_binding_id,owner_binding_generation,database_lineage_id,
        recovery_signing_generation,recovery_trust_bundle_sha256,
        created_at,updated_at
    ) VALUES (
        p_recovery_set_id,p_operation_id,p_environment_id,'onpremise',
        'same_environment',v_sequence,'requested',v_primary_binding_id,
        v_tenant_set_sha256,v_owner_binding_id,v_owner_binding_generation,
        v_database_lineage_id,v_signing_generation,v_trust_bundle_sha256,
        p_created_at,p_created_at
    );
    RETURN v_sequence;
END;
$$;


ALTER FUNCTION platform.platformops_request_recovery_set_v2(p_recovery_set_id uuid, p_operation_id uuid, p_environment_id uuid, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_request_restore_v1(uuid, uuid, uuid, text, text, bytea, uuid, text, text, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_request_restore_v1(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_target_disposition text, p_plan_sha256 text, p_plan_bytes bytea, p_safety_recovery_set_id uuid, p_safety_recovery_set_sha256 text, p_waiver_reason text, p_probe_sha256 text, p_destructive_confirmed boolean, p_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_existing platform.platformops_restore_operations%ROWTYPE;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM platform.platformops_recovery_sets
         WHERE recovery_set_id = p_recovery_set_id
           AND environment_id = p_environment_id
           AND state = 'protected'
    ) THEN
        RAISE EXCEPTION 'protected same-environment recovery set is missing'
            USING ERRCODE = 'P0002';
    END IF;
    IF p_target_disposition = 'existing_readable' AND NOT EXISTS (
        SELECT 1 FROM platform.platformops_recovery_sets
         WHERE recovery_set_id = p_safety_recovery_set_id
           AND recovery_set_id <> p_recovery_set_id
           AND environment_id = p_environment_id
           AND state = 'protected'
           AND manifest_sha256 = p_safety_recovery_set_sha256
    ) THEN
        RAISE EXCEPTION 'readable restore requires protected safety set'
            USING ERRCODE = '55000';
    END IF;
    SELECT * INTO v_existing FROM platform.platformops_restore_operations
     WHERE operation_id = p_operation_id;
    IF FOUND THEN
        IF v_existing.recovery_set_id <> p_recovery_set_id
           OR v_existing.environment_id <> p_environment_id
           OR v_existing.target_disposition <> p_target_disposition
           OR v_existing.plan_sha256 <> p_plan_sha256
           OR v_existing.plan_bytes <> p_plan_bytes
           OR v_existing.safety_recovery_set_id IS DISTINCT FROM p_safety_recovery_set_id
           OR v_existing.safety_recovery_set_sha256 IS DISTINCT FROM p_safety_recovery_set_sha256
           OR v_existing.waiver_reason IS DISTINCT FROM p_waiver_reason
           OR v_existing.probe_sha256 IS DISTINCT FROM p_probe_sha256
           OR v_existing.destructive_confirmed <> p_destructive_confirmed
           OR v_existing.created_at <> p_created_at THEN
            RAISE EXCEPTION 'restore request conflicts' USING ERRCODE = '23505';
        END IF;
        RETURN;
    END IF;
    INSERT INTO platform.platformops_restore_operations(
        operation_id, recovery_set_id, environment_id, target_disposition,
        state, plan_sha256, plan_bytes, safety_recovery_set_id,
        safety_recovery_set_sha256, waiver_reason, probe_sha256,
        destructive_confirmed, created_at, updated_at
    ) VALUES (
        p_operation_id, p_recovery_set_id, p_environment_id, p_target_disposition,
        'plan_ready', p_plan_sha256, p_plan_bytes, p_safety_recovery_set_id,
        p_safety_recovery_set_sha256, p_waiver_reason, p_probe_sha256,
        p_destructive_confirmed, p_created_at, p_created_at
    );
END;
$$;


ALTER FUNCTION platform.platformops_request_restore_v1(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_target_disposition text, p_plan_sha256 text, p_plan_bytes bytea, p_safety_recovery_set_id uuid, p_safety_recovery_set_sha256 text, p_waiver_reason text, p_probe_sha256 text, p_destructive_confirmed boolean, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_request_restore_v2(uuid, uuid, uuid, text, text, bytea, uuid, text, text, text, boolean, timestamp with time zone, uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_request_restore_v2(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_target_disposition text, p_plan_sha256 text, p_plan_bytes bytea, p_safety_recovery_set_id uuid, p_safety_recovery_set_sha256 text, p_waiver_reason text, p_probe_sha256 text, p_destructive_confirmed boolean, p_created_at timestamp with time zone, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM platform.tenancy_tenant_bindings b
         WHERE b.environment_id = p_environment_id
           AND b.tenant_id = p_tenant_id
           AND platform.iam_platform_current_owner_v1(p_tenant_id,p_actor_user_id)
    ) THEN
        RAISE EXCEPTION 'current owner is required' USING ERRCODE = '42501';
    END IF;
    PERFORM platform.platformops_request_restore_v1(
        p_operation_id, p_recovery_set_id, p_environment_id,
        p_target_disposition, p_plan_sha256, p_plan_bytes,
        p_safety_recovery_set_id, p_safety_recovery_set_sha256,
        p_waiver_reason, p_probe_sha256, p_destructive_confirmed, p_created_at
    );
    UPDATE platform.platformops_restore_operations r
       SET requested_by_actor_id = p_actor_user_id,
           requested_by_session_id = p_session_id
     WHERE r.operation_id = p_operation_id
       AND (r.requested_by_actor_id IS NULL
            OR (r.requested_by_actor_id = p_actor_user_id
                AND r.requested_by_session_id = p_session_id));
    IF NOT FOUND THEN
        RAISE EXCEPTION 'restore requester conflicts' USING ERRCODE = '23505';
    END IF;
END;
$$;


ALTER FUNCTION platform.platformops_request_restore_v2(p_operation_id uuid, p_recovery_set_id uuid, p_environment_id uuid, p_target_disposition text, p_plan_sha256 text, p_plan_bytes bytea, p_safety_recovery_set_id uuid, p_safety_recovery_set_sha256 text, p_waiver_reason text, p_probe_sha256 text, p_destructive_confirmed boolean, p_created_at timestamp with time zone, p_tenant_id uuid, p_actor_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_restored_license_scope_mint_v1(uuid, uuid, uuid, text, uuid, uuid, text, text, bigint, text, bigint, text, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_restored_license_scope_mint_v1(p_operation_id uuid, p_environment_id uuid, p_restore_receipt_id uuid, p_restore_receipt_sha256 text, p_license_id uuid, p_licensee_organization_id uuid, p_delivery_kind text, p_issuer text, p_previous_sequence bigint, p_previous_sha256 text, p_next_sequence bigint, p_next_sha256 text, p_manifest_sha256 text, p_authority_revision bigint) RETURNS TABLE(operation_id uuid, environment_id uuid, restore_receipt_id uuid, restore_receipt_sha256 text, license_binding_id uuid, license_id uuid, licensee_organization_id uuid, delivery_kind text, issuer text, previous_sequence bigint, previous_sha256 text, next_sequence bigint, next_sha256 text, manifest_sha256 text, authority_revision bigint, lease_until timestamp with time zone, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_restore platform.platformops_restore_operations%ROWTYPE;
    v_grant platform.platformops_restored_license_grants%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR pg_catalog.current_setting('application_name', true)
            <> 'harpy-v2:core-operator-license-reconcile' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'restored license scope mint denied';
    END IF;
    IF pg_catalog.uuid_extract_version(p_operation_id) <> 7
       OR p_environment_id IS NULL OR p_restore_receipt_id IS NULL
       OR p_license_id IS NULL OR p_licensee_organization_id IS NULL
       OR p_restore_receipt_sha256 !~ '^[0-9a-f]{64}$'
       OR p_delivery_kind NOT IN ('connected','airgap','development')
       OR pg_catalog.octet_length(p_issuer) NOT BETWEEN 1 AND 256
       OR p_issuer <> pg_catalog.btrim(p_issuer) OR p_issuer ~ '[[:cntrl:]]'
       OR p_previous_sequence < 1 OR p_next_sequence <= p_previous_sequence
       OR p_previous_sha256 !~ '^[0-9a-f]{64}$'
       OR p_next_sha256 !~ '^[0-9a-f]{64}$'
       OR p_manifest_sha256 <>
          '982f8d8b6315f237e87a80904ceda1ed4ef54d32931907cda9be1db07a2f5d45'
       OR p_authority_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'restored license scope input is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.tenancy_deployment_policy AS policy
        JOIN platform.tenancy_tenant_bindings AS binding
          ON binding.environment_id = policy.environment_id
         AND binding.purpose = 'onpremise_primary'
        WHERE policy.singleton AND policy.deployment_mode = 'onpremise'
          AND policy.environment_id = p_environment_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'restored license scope requires onpremise primary';
    END IF;
    SELECT restore.* INTO v_restore
      FROM platform.platformops_restore_operations AS restore
     WHERE restore.operation_id = p_operation_id
     FOR SHARE;
    IF NOT FOUND OR v_restore.state <> 'completed'
       OR v_restore.environment_id IS DISTINCT FROM p_environment_id
       OR v_restore.receipt_sha256 IS DISTINCT FROM p_restore_receipt_sha256
       OR v_restore.receipt_bytes IS NULL
       OR pg_catalog.encode(pg_catalog.sha256(v_restore.receipt_bytes), 'hex')
            IS DISTINCT FROM p_restore_receipt_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'completed restore receipt binding is invalid';
    END IF;
    INSERT INTO platform.platformops_restored_license_grants (
        operation_id, environment_id, restore_receipt_id,
        restore_receipt_sha256, license_binding_id, license_id,
        licensee_organization_id, delivery_kind, issuer,
        previous_sequence, previous_sha256, next_sequence, next_sha256,
        manifest_sha256, authority_revision, lease_until, created_at, updated_at
    ) VALUES (
        p_operation_id, p_environment_id, p_restore_receipt_id,
        p_restore_receipt_sha256, pg_catalog.uuidv7(), p_license_id,
        p_licensee_organization_id, p_delivery_kind, p_issuer,
        p_previous_sequence, p_previous_sha256, p_next_sequence, p_next_sha256,
        p_manifest_sha256, p_authority_revision, v_now + interval '60 seconds',
        v_now, v_now
    ) ON CONFLICT ON CONSTRAINT platformops_restored_license_grants_pkey
      DO NOTHING;
    SELECT grant_row.* INTO v_grant
      FROM platform.platformops_restored_license_grants AS grant_row
     WHERE grant_row.operation_id = p_operation_id FOR UPDATE;
    IF v_grant.environment_id IS DISTINCT FROM p_environment_id
       OR v_grant.restore_receipt_id IS DISTINCT FROM p_restore_receipt_id
       OR v_grant.restore_receipt_sha256 IS DISTINCT FROM p_restore_receipt_sha256
       OR v_grant.license_id IS DISTINCT FROM p_license_id
       OR v_grant.licensee_organization_id IS DISTINCT FROM p_licensee_organization_id
       OR v_grant.delivery_kind IS DISTINCT FROM p_delivery_kind
       OR v_grant.issuer IS DISTINCT FROM p_issuer
       OR v_grant.previous_sequence IS DISTINCT FROM p_previous_sequence
       OR v_grant.previous_sha256 IS DISTINCT FROM p_previous_sha256
       OR v_grant.next_sequence IS DISTINCT FROM p_next_sequence
       OR v_grant.next_sha256 IS DISTINCT FROM p_next_sha256
       OR v_grant.manifest_sha256 IS DISTINCT FROM p_manifest_sha256
       OR v_grant.authority_revision IS DISTINCT FROM p_authority_revision THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'restored license scope input conflicts';
    END IF;
    IF v_grant.lease_until <= v_now THEN
        UPDATE platform.platformops_restored_license_grants AS grant_row
           SET lease_until = v_now + interval '60 seconds', updated_at = v_now
         WHERE grant_row.operation_id = p_operation_id
         RETURNING grant_row.* INTO v_grant;
    END IF;
    RETURN QUERY SELECT v_grant.operation_id, v_grant.environment_id,
        v_grant.restore_receipt_id, v_grant.restore_receipt_sha256,
        v_grant.license_binding_id, v_grant.license_id,
        v_grant.licensee_organization_id, v_grant.delivery_kind, v_grant.issuer,
        v_grant.previous_sequence, v_grant.previous_sha256,
        v_grant.next_sequence, v_grant.next_sha256, v_grant.manifest_sha256,
        v_grant.authority_revision, v_grant.lease_until, v_now;
END;
$_$;


ALTER FUNCTION platform.platformops_restored_license_scope_mint_v1(p_operation_id uuid, p_environment_id uuid, p_restore_receipt_id uuid, p_restore_receipt_sha256 text, p_license_id uuid, p_licensee_organization_id uuid, p_delivery_kind text, p_issuer text, p_previous_sequence bigint, p_previous_sha256 text, p_next_sequence bigint, p_next_sha256 text, p_manifest_sha256 text, p_authority_revision bigint) OWNER TO harpy_owner;

--
-- Name: platformops_seed_rehydrate_control_v1(text, bytea, text, bytea, text, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_seed_rehydrate_control_v1(p_trust_sha256 text, p_trust_bytes bytea, p_plan_sha256 text, p_plan_bytes bytea, p_manifest_sha256 text, p_manifest_bytes bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_trust jsonb;
    v_plan jsonb;
    v_manifest jsonb;
    v_component_key text;
    v_component_value jsonb;
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_trust_sha256<>pg_catalog.encode(pg_catalog.sha256(p_trust_bytes),'hex')
       OR p_plan_sha256<>pg_catalog.encode(pg_catalog.sha256(p_plan_bytes),'hex')
       OR p_manifest_sha256<>pg_catalog.encode(
            pg_catalog.sha256(p_manifest_bytes),'hex'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='rehydrate control seed denied';
    END IF;
    v_trust:=pg_catalog.convert_from(p_trust_bytes,'UTF8')::jsonb;
    v_plan:=pg_catalog.convert_from(p_plan_bytes,'UTF8')::jsonb;
    v_manifest:=pg_catalog.convert_from(p_manifest_bytes,'UTF8')::jsonb;
    IF v_trust->>'schema'<>'recovery-trust-bundle.v1'
       OR v_plan->>'schema'<>'harpy-recovery-artifact.v1'
       OR v_plan->>'purpose'<>'restore_plan'
       OR v_manifest->>'schema'<>'harpy-recovery-artifact.v1'
       OR v_manifest->>'purpose'<>'recovery_manifest'
       OR v_plan->>'environment_id'<>v_trust->>'environment_id'
       OR v_manifest->>'environment_id'<>v_trust->>'environment_id'
       OR v_plan#>>'{payload,identity,environment_id}'<>
          v_trust->>'environment_id'
       OR v_manifest#>>'{payload,identity,environment_id}'<>
          v_trust->>'environment_id'
       OR v_plan#>>'{payload,recovery_set_id}'<>
          v_manifest->>'artifact_id'
       OR v_plan#>>'{payload,manifest_sha256}'<>p_manifest_sha256
       OR v_manifest#>>'{payload,recovery_trust_bundle_sha256}'<>
          p_trust_sha256
       OR (v_manifest->>'key_generation')::bigint<>
          (v_trust->>'generation')::bigint
       OR (v_plan->>'key_generation')::bigint<>
          (v_trust->>'generation')::bigint
       OR v_manifest#>>'{payload,schema}'<>'recovery-set-manifest.v1'
       OR v_plan#>>'{payload,schema}'<>'restore-plan-payload.v1'
       OR v_manifest#>>'{payload,portability}'<>'same_environment'
       OR v_manifest#>>'{payload,identity,deployment_mode}'<>'onpremise'
       OR pg_catalog.jsonb_object_length(
            v_manifest#>'{payload,components}'
          )<>5 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='rehydrate artifacts differ';
    END IF;
    INSERT INTO platform.platformops_recovery_signing_bundles(
        environment_id,generation,bundle_sha256,bundle_bytes,created_at
    ) VALUES (
        (v_trust->>'environment_id')::uuid,
        (v_trust->>'generation')::bigint,p_trust_sha256,p_trust_bytes,
        (v_trust->>'generated_at')::timestamptz
    ) ON CONFLICT DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM platform.platformops_recovery_signing_bundles
        WHERE environment_id=(v_trust->>'environment_id')::uuid
          AND generation=(v_trust->>'generation')::bigint
          AND bundle_sha256=p_trust_sha256 AND bundle_bytes=p_trust_bytes
    ) THEN RAISE EXCEPTION USING ERRCODE='23505',
        MESSAGE='rehydrate trust conflicts'; END IF;
    INSERT INTO platform.platformops_recovery_sets(
        recovery_set_id,operation_id,environment_id,deployment_mode,
        portability,sequence,state,primary_binding_id,tenant_set_sha256,
        owner_binding_id,owner_binding_generation,database_lineage_id,
        database_system_id,recovery_signing_generation,
        recovery_trust_bundle_sha256,manifest_sha256,manifest_bytes,
        protected_at,created_at,updated_at
    ) VALUES (
        (v_manifest->>'artifact_id')::uuid,
        (v_manifest->>'operation_id')::uuid,
        (v_manifest->>'environment_id')::uuid,'onpremise','same_environment',
        (v_manifest->>'artifact_sequence')::bigint,'protected',
        (v_manifest#>>'{payload,identity,primary_binding_id}')::uuid,
        v_manifest#>>'{payload,identity,tenant_set_sha256}',
        (v_manifest#>>'{payload,identity,owner_binding_id}')::uuid,
        (v_manifest#>>'{payload,identity,owner_binding_generation}')::bigint,
        (v_manifest#>>'{payload,identity,database_lineage_id}')::uuid,
        (v_manifest#>>'{payload,database_system_id}')::uuid,
        (v_manifest->>'key_generation')::bigint,p_trust_sha256,
        p_manifest_sha256,p_manifest_bytes,
        (v_manifest#>>'{payload,created_at}')::timestamptz,
        (v_manifest#>>'{payload,created_at}')::timestamptz,v_now
    ) ON CONFLICT DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM platform.platformops_recovery_sets
        WHERE recovery_set_id=(v_manifest->>'artifact_id')::uuid
          AND environment_id=(v_manifest->>'environment_id')::uuid
          AND manifest_sha256=p_manifest_sha256
          AND manifest_bytes=p_manifest_bytes AND state='protected'
    ) THEN RAISE EXCEPTION USING ERRCODE='23505',
        MESSAGE='rehydrate recovery set conflicts'; END IF;
    FOR v_component_key,v_component_value IN
    SELECT component.key,component.value FROM pg_catalog.jsonb_each(
        v_manifest#>'{payload,components}'
    ) AS component LOOP
        IF v_component_key NOT IN (
            'database_archive','documents_inventory','key_custody',
            'owner_anchor','protected_authority'
        ) THEN RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='rehydrate component is invalid'; END IF;
        INSERT INTO platform.platformops_recovery_components(
            recovery_set_id,component_kind,object_key,object_version_id,
            ciphertext_sha256,ciphertext_bytes,verified_at
        ) VALUES (
            (v_manifest->>'artifact_id')::uuid,v_component_key,
            v_component_value->>'object_key',
            v_component_value->>'object_version_id',
            v_component_value->>'ciphertext_sha256',
            (v_component_value->>'ciphertext_bytes')::bigint,v_now
        ) ON CONFLICT DO NOTHING;
    END LOOP;
    IF (SELECT pg_catalog.count(*) FROM platform.platformops_recovery_components
        WHERE recovery_set_id=(v_manifest->>'artifact_id')::uuid)<>5 THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='rehydrate component inventory conflicts';
    END IF;
    INSERT INTO platform.platformops_restore_operations(
        operation_id,recovery_set_id,environment_id,target_disposition,
        state,plan_sha256,plan_bytes,safety_recovery_set_id,
        safety_recovery_set_sha256,waiver_reason,probe_sha256,
        destructive_confirmed,created_at,updated_at
    ) VALUES (
        (v_plan->>'operation_id')::uuid,
        (v_plan#>>'{payload,recovery_set_id}')::uuid,
        (v_plan->>'environment_id')::uuid,
        v_plan#>>'{payload,target_disposition}','plan_ready',
        p_plan_sha256,p_plan_bytes,
        NULLIF(v_plan#>>'{payload,safety_recovery_set_id}','')::uuid,
        NULLIF(v_plan#>>'{payload,safety_recovery_set_sha256}',''),
        NULLIF(v_plan#>>'{payload,waiver_reason}',''),
        NULLIF(v_plan#>>'{payload,probe_sha256}',''),
        (v_plan#>>'{payload,destructive_confirmed}')::boolean,
        (v_plan->>'issued_at')::timestamptz,v_now
    ) ON CONFLICT DO NOTHING;
    RETURN EXISTS (
        SELECT 1 FROM platform.platformops_restore_operations
        WHERE operation_id=(v_plan->>'operation_id')::uuid
          AND recovery_set_id=(v_manifest->>'artifact_id')::uuid
          AND plan_sha256=p_plan_sha256 AND plan_bytes=p_plan_bytes
          AND state IN ('plan_ready','draining','restoring','verifying','switched')
    );
END;
$$;


ALTER FUNCTION platform.platformops_seed_rehydrate_control_v1(p_trust_sha256 text, p_trust_bytes bytea, p_plan_sha256 text, p_plan_bytes bytea, p_manifest_sha256 text, p_manifest_bytes bytea) OWNER TO harpy_owner;

--
-- Name: platformops_stale_recovery_sets_for_authority_v1(uuid, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_stale_recovery_sets_for_authority_v1(p_environment_id uuid, p_authority_generation bigint, p_state_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
    IF p_environment_id IS NULL OR p_authority_generation<1 OR
       pg_catalog.octet_length(p_state_sha256)<>32 OR p_occurred_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='authority stale request is invalid';
    END IF;
    UPDATE platform.platformops_recovery_sets
       SET state='stale',failure_code='protected_authority_advanced',updated_at=p_occurred_at
     WHERE environment_id=p_environment_id AND state='protected';
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION platform.platformops_stale_recovery_sets_for_authority_v1(p_environment_id uuid, p_authority_generation bigint, p_state_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

