--
-- Name: platformops_start_restore_apply_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_start_restore_apply_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_drain_ack_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_drain_ack_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore apply transition denied';
    END IF;
    UPDATE platform.platformops_restore_operations AS restore
    SET state='restoring',updated_at=v_now
    FROM platform.platformops_restore_execution_attempts AS attempt
    WHERE restore.operation_id=p_operation_id AND restore.state='draining'
      AND attempt.attempt_id=p_attempt_id
      AND attempt.operation_id=restore.operation_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active' AND attempt.lease_expires_at>v_now
      AND (attempt.drain_ack_sha256 IS NULL
           OR attempt.drain_ack_sha256=p_drain_ack_sha256);
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET claimed_restore_state='restoring',
        drain_ack_sha256=p_drain_ack_sha256,heartbeat_at=v_now,
        lease_expires_at=v_now+interval '2 minutes'
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_start_restore_apply_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_drain_ack_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_start_restore_apply_v2(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_start_restore_apply_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_drain_ack_sha256 text, p_control_database_locator_sha256 text, p_scratch_database_locator_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_changed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR p_drain_ack_sha256 !~ '^[0-9a-f]{64}$'
       OR p_control_database_locator_sha256 !~ '^[0-9a-f]{64}$'
       OR p_scratch_database_locator_sha256 !~ '^[0-9a-f]{64}$'
       OR p_control_database_locator_sha256=
          p_scratch_database_locator_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore database locator binding denied';
    END IF;
    SELECT platform.platformops_start_restore_apply_v1(
        p_operation_id,p_attempt_id,p_lease_token,p_drain_ack_sha256
    ) INTO v_changed;
    IF v_changed THEN
        UPDATE platform.platformops_restore_execution_attempts
        SET control_database_locator_sha256=
                p_control_database_locator_sha256,
            scratch_database_locator_sha256=
                p_scratch_database_locator_sha256
        WHERE attempt_id=p_attempt_id AND operation_id=p_operation_id
          AND lease_token=p_lease_token
          AND lifecycle_state='active'
          AND drain_ack_sha256=p_drain_ack_sha256
          AND control_database_locator_sha256 IS NULL
          AND scratch_database_locator_sha256 IS NULL;
        RETURN FOUND;
    END IF;
    RETURN EXISTS (
        SELECT 1
        FROM platform.platformops_restore_execution_attempts AS attempt
        JOIN platform.platformops_restore_operations AS restore
          ON restore.operation_id=attempt.operation_id
        WHERE attempt.attempt_id=p_attempt_id
          AND attempt.operation_id=p_operation_id
          AND attempt.lease_token=p_lease_token
          AND attempt.lifecycle_state='active'
          AND attempt.claimed_restore_state='restoring'
          AND restore.state='restoring'
          AND attempt.drain_ack_sha256=p_drain_ack_sha256
          AND attempt.control_database_locator_sha256=
              p_control_database_locator_sha256
          AND attempt.scratch_database_locator_sha256=
              p_scratch_database_locator_sha256
    );
END;
$_$;


ALTER FUNCTION platform.platformops_start_restore_apply_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_drain_ack_sha256 text, p_control_database_locator_sha256 text, p_scratch_database_locator_sha256 text) OWNER TO harpy_owner;

--
-- Name: platformops_start_restore_drain_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_start_restore_drain_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore drain transition denied';
    END IF;
    UPDATE platform.platformops_restore_operations AS restore
    SET state='draining',updated_at=v_now
    FROM platform.platformops_restore_execution_attempts AS attempt
    WHERE restore.operation_id=p_operation_id AND restore.state='plan_ready'
      AND attempt.attempt_id=p_attempt_id
      AND attempt.operation_id=restore.operation_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active' AND attempt.lease_expires_at>v_now;
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET claimed_restore_state='draining',heartbeat_at=v_now,
        lease_expires_at=v_now+interval '2 minutes'
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.platformops_start_restore_drain_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid) OWNER TO harpy_owner;

--
-- Name: platformops_start_restore_verify_v1(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_start_restore_verify_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_archive_readback_sha256 text, p_new_database_system_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR pg_catalog.current_setting('application_name')
          IS DISTINCT FROM 'harpy-v2:core-database-restore'
       OR p_archive_readback_sha256 !~ '^[0-9a-f]{64}$'
       OR p_new_database_system_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='restore verify transition denied';
    END IF;
    UPDATE platform.platformops_restore_operations AS restore
    SET state='verifying',updated_at=v_now
    FROM platform.platformops_restore_execution_attempts AS attempt
    WHERE restore.operation_id=p_operation_id AND restore.state='restoring'
      AND attempt.attempt_id=p_attempt_id
      AND attempt.operation_id=restore.operation_id
      AND attempt.lease_token=p_lease_token
      AND attempt.lifecycle_state='active' AND attempt.lease_expires_at>v_now
      AND attempt.drain_ack_sha256 IS NOT NULL
      AND (attempt.archive_readback_sha256 IS NULL
           OR (attempt.archive_readback_sha256=p_archive_readback_sha256
               AND attempt.restored_database_system_id=p_new_database_system_id));
    IF NOT FOUND THEN RETURN false; END IF;
    UPDATE platform.platformops_restore_execution_attempts
    SET claimed_restore_state='verifying',
        archive_readback_sha256=p_archive_readback_sha256,
        restored_database_system_id=p_new_database_system_id,
        heartbeat_at=v_now,lease_expires_at=v_now+interval '2 minutes'
    WHERE attempt_id=p_attempt_id AND lease_token=p_lease_token
      AND lifecycle_state='active';
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.platformops_start_restore_verify_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_token uuid, p_archive_readback_sha256 text, p_new_database_system_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_test_alert_rule_v1(uuid, uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_test_alert_rule_v1(p_event_id uuid, p_rule_id uuid, p_environment_id uuid, p_actor_id uuid, p_message text, p_now timestamp with time zone) RETURNS SETOF platform.platformops_alert_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE selected platform.platformops_alert_rules%ROWTYPE;
BEGIN
    SELECT * INTO selected FROM platform.platformops_alert_rules
    WHERE id = p_rule_id AND environment_id = p_environment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'alert rule was not found' USING ERRCODE = 'P0002'; END IF;
    INSERT INTO platform.platformops_alert_events(
        id, environment_id, alert_rule_id, service_name, previous_status,
        current_status, channels_used, message, actor_id, created_at
    ) VALUES (
        p_event_id, p_environment_id, p_rule_id,
        coalesce(selected.service_name, 'core-api'), 'healthy', 'unhealthy',
        '{}'::text[], p_message, p_actor_id, p_now
    );
    RETURN QUERY SELECT * FROM platform.platformops_alert_events WHERE id = p_event_id;
END;
$$;


ALTER FUNCTION platform.platformops_test_alert_rule_v1(p_event_id uuid, p_rule_id uuid, p_environment_id uuid, p_actor_id uuid, p_message text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: platformops_trace_stats_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_trace_stats_v1(p_environment_id uuid) RETURNS TABLE(total_traces bigint, total_spans bigint, error_rate numeric, average_duration_ms numeric, spans_by_service jsonb, spans_by_level jsonb, traces_last_24h bigint, traces_last_hour bigint, slowest_endpoints jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    WITH source AS (
        SELECT span.* FROM platform.platformops_trace_spans AS span
        WHERE span.environment_id = p_environment_id
          AND span.started_at >= pg_catalog.statement_timestamp() - interval '31 days'
    ), totals AS (
        SELECT count(DISTINCT correlation_id)::bigint AS traces,
            count(*)::bigint AS spans,
            coalesce(avg(duration_ms), 0)::numeric AS average_duration,
            coalesce(count(*) FILTER (WHERE status_code >= 500 OR level IN ('error','fatal'))::numeric
                / nullif(count(*), 0), 0)::numeric AS failures,
            count(DISTINCT correlation_id) FILTER (
                WHERE started_at >= pg_catalog.statement_timestamp() - interval '24 hours')::bigint AS last_day,
            count(DISTINCT correlation_id) FILTER (
                WHERE started_at >= pg_catalog.statement_timestamp() - interval '1 hour')::bigint AS last_hour
        FROM source
    ), services AS (
        SELECT service_name, count(*)::bigint AS amount FROM source GROUP BY service_name
    ), levels AS (
        SELECT level, count(*)::bigint AS amount FROM source GROUP BY level
    ), endpoints AS (
        SELECT path, method, avg(duration_ms)::numeric AS average_duration,
            count(*)::bigint AS calls,
            count(*) FILTER (WHERE status_code >= 500 OR level IN ('error','fatal'))::bigint AS errors
        FROM source GROUP BY path, method ORDER BY average_duration DESC, path, method LIMIT 10
    )
    SELECT totals.traces, totals.spans, totals.failures, totals.average_duration,
        coalesce((SELECT jsonb_object_agg(service_name, amount ORDER BY service_name) FROM services), '{}'::jsonb),
        coalesce((SELECT jsonb_object_agg(level, amount ORDER BY level) FROM levels), '{}'::jsonb),
        totals.last_day, totals.last_hour,
        coalesce((SELECT jsonb_agg(jsonb_build_object(
            'path', path, 'method', method, 'avg_duration_ms', average_duration,
            'call_count', calls, 'error_count', errors
        ) ORDER BY average_duration DESC, path, method) FROM endpoints), '[]'::jsonb)
    FROM totals;
END;
$$;


ALTER FUNCTION platform.platformops_trace_stats_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: platformops_update_alert_rule_v1(uuid, uuid, text, text, boolean, text, text, integer, jsonb, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.platformops_update_alert_rule_v1(p_id uuid, p_environment_id uuid, p_name text, p_description text, p_enabled boolean, p_service_name text, p_condition text, p_cooldown_minutes integer, p_channels jsonb, p_now timestamp with time zone) RETURNS SETOF platform.platformops_alert_rules
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    UPDATE platform.platformops_alert_rules SET
        name = btrim(p_name), description = p_description, enabled = p_enabled,
        service_name = nullif(btrim(p_service_name), ''), condition = p_condition,
        cooldown_minutes = p_cooldown_minutes, channels = p_channels,
        revision = revision + 1, updated_at = p_now
    WHERE id = p_id AND environment_id = p_environment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'alert rule was not found' USING ERRCODE = 'P0002'; END IF;
    RETURN QUERY SELECT * FROM platform.platformops_alert_rules WHERE id = p_id;
END;
$$;


ALTER FUNCTION platform.platformops_update_alert_rule_v1(p_id uuid, p_environment_id uuid, p_name text, p_description text, p_enabled boolean, p_service_name text, p_condition text, p_cooldown_minutes integer, p_channels jsonb, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_adoption_page_receipts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.support_adoption_page_receipts (
    run_id uuid NOT NULL,
    page_number bigint NOT NULL,
    cursor_before uuid,
    cursor_after uuid NOT NULL,
    row_count integer NOT NULL,
    request_sha256 bytea NOT NULL,
    source_page_sha256 bytea NOT NULL,
    target_page_sha256 bytea NOT NULL,
    state text NOT NULL,
    applied_at timestamp(6) with time zone NOT NULL,
    advanced_at timestamp(6) with time zone,
    CONSTRAINT support_adoption_page_receipts_check CHECK ((((state = 'applied'::text) AND (advanced_at IS NULL)) OR ((state = 'advanced'::text) AND (advanced_at IS NOT NULL)))),
    CONSTRAINT support_adoption_page_receipts_page_number_check CHECK ((page_number > 0)),
    CONSTRAINT support_adoption_page_receipts_request_sha256_check CHECK ((octet_length(request_sha256) = 32)),
    CONSTRAINT support_adoption_page_receipts_row_count_check CHECK (((row_count >= 1) AND (row_count <= 100))),
    CONSTRAINT support_adoption_page_receipts_source_page_sha256_check CHECK ((octet_length(source_page_sha256) = 32)),
    CONSTRAINT support_adoption_page_receipts_state_check CHECK ((state = ANY (ARRAY['applied'::text, 'advanced'::text]))),
    CONSTRAINT support_adoption_page_receipts_target_page_sha256_check CHECK ((octet_length(target_page_sha256) = 32))
);


ALTER TABLE platform.support_adoption_page_receipts OWNER TO harpy_owner;

--
-- Name: support_adoption_page_document_v1(platform.support_adoption_page_receipts); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_adoption_page_document_v1(p_page platform.support_adoption_page_receipts) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'run_id', p_page.run_id,
        'page_number', p_page.page_number,
        'cursor_before', p_page.cursor_before,
        'cursor_after', p_page.cursor_after,
        'row_count', p_page.row_count,
        'source_page_sha256', pg_catalog.encode(p_page.source_page_sha256,'hex'),
        'target_page_sha256', pg_catalog.encode(p_page.target_page_sha256,'hex'),
        'advanced', p_page.state = 'advanced'
    )
$$;


ALTER FUNCTION platform.support_adoption_page_document_v1(p_page platform.support_adoption_page_receipts) OWNER TO harpy_owner;

--
-- Name: support_adoption_runs; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.support_adoption_runs (
    run_id uuid NOT NULL,
    source_kind text NOT NULL,
    source_tenant_id uuid,
    source_schema text NOT NULL,
    cursor_id uuid,
    copied_count bigint DEFAULT 0 NOT NULL,
    source_sha256 bytea,
    target_sha256 bytea,
    status text NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    operation_id uuid NOT NULL,
    source_relation text NOT NULL,
    source_relation_oid oid NOT NULL,
    source_locator_sha256 bytea NOT NULL,
    source_manifest_sha256 bytea NOT NULL,
    transform_sha256 bytea NOT NULL,
    snapshot_id text NOT NULL,
    tenant_slug text DEFAULT ''::text NOT NULL,
    tenant_name text DEFAULT ''::text NOT NULL,
    expected_count bigint NOT NULL,
    expected_source_sha256 bytea NOT NULL,
    next_page bigint DEFAULT 1 NOT NULL,
    lease_owner uuid,
    lease_claim_revision bigint,
    lease_generation bigint DEFAULT 0 NOT NULL,
    lease_expires_at timestamp(6) with time zone,
    reconciled_at timestamp(6) with time zone,
    completed_at timestamp(6) with time zone,
    CONSTRAINT support_adoption_runs_copied_count_check CHECK ((copied_count >= 0)),
    CONSTRAINT support_adoption_runs_hash_check CHECK (((octet_length(source_locator_sha256) = 32) AND (octet_length(source_manifest_sha256) = 32) AND (octet_length(transform_sha256) = 32) AND (octet_length(expected_source_sha256) = 32))),
    CONSTRAINT support_adoption_runs_lease_check CHECK ((((lease_owner IS NULL) = (lease_expires_at IS NULL)) AND ((lease_owner IS NULL) = (lease_claim_revision IS NULL)) AND ((lease_claim_revision IS NULL) OR (lease_claim_revision > 0)))),
    CONSTRAINT support_adoption_runs_progress_check CHECK (((expected_count >= 0) AND (copied_count <= expected_count) AND (next_page > 0) AND (lease_generation >= 0) AND ((octet_length(snapshot_id) >= 16) AND (octet_length(snapshot_id) <= 200)))),
    CONSTRAINT support_adoption_runs_relation_check CHECK ((((octet_length(source_relation) >= 1) AND (octet_length(source_relation) <= 63)) AND ((source_relation_oid)::bigint > 0) AND (source_schema ~ '^[a-z][a-z0-9_]{0,62}$'::text))),
    CONSTRAINT support_adoption_runs_revision_check CHECK ((revision > 0)),
    CONSTRAINT support_adoption_runs_run_id_check CHECK ((uuid_extract_version(run_id) = 7)),
    CONSTRAINT support_adoption_runs_scope_check CHECK ((((source_kind = 'contact_global'::text) AND (source_tenant_id IS NULL) AND (source_schema = 'public'::text) AND (source_relation = 'contact_messages'::text) AND (tenant_slug = ''::text) AND (tenant_name = ''::text)) OR ((source_kind = 'bug_tenant'::text) AND (source_tenant_id IS NOT NULL) AND (source_schema <> ALL (ARRAY['public'::text, 'platform'::text, 'pg_catalog'::text, 'information_schema'::text])) AND (source_schema !~ '^pg_'::text) AND (source_relation = 'bug_reports'::text) AND ((octet_length(tenant_slug) >= 1) AND (octet_length(tenant_slug) <= 100)) AND ((octet_length(tenant_name) >= 1) AND (octet_length(tenant_name) <= 200))))),
    CONSTRAINT support_adoption_runs_source_kind_check CHECK ((source_kind = ANY (ARRAY['contact_global'::text, 'bug_tenant'::text]))),
    CONSTRAINT support_adoption_runs_source_schema_check CHECK (((octet_length(source_schema) >= 1) AND (octet_length(source_schema) <= 128))),
    CONSTRAINT support_adoption_runs_source_sha256_check CHECK (((source_sha256 IS NULL) OR (octet_length(source_sha256) = 32))),
    CONSTRAINT support_adoption_runs_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'applying'::text, 'reconciling'::text, 'completed'::text, 'fenced'::text]))),
    CONSTRAINT support_adoption_runs_target_sha256_check CHECK (((target_sha256 IS NULL) OR (octet_length(target_sha256) = 32)))
);


ALTER TABLE platform.support_adoption_runs OWNER TO harpy_owner;

--
-- Name: support_adoption_run_document_v1(platform.support_adoption_runs); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_adoption_run_document_v1(p_run platform.support_adoption_runs) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT pg_catalog.jsonb_build_object(
        'operation_id', p_run.operation_id,
        'run_id', p_run.run_id,
        'source_kind', p_run.source_kind,
        'source_tenant_id', p_run.source_tenant_id,
        'source_schema', p_run.source_schema,
        'source_relation', p_run.source_relation,
        'source_relation_oid', p_run.source_relation_oid::bigint,
        'tenant_slug', p_run.tenant_slug,
        'tenant_name', p_run.tenant_name,
        'snapshot_id', p_run.snapshot_id,
        'source_locator_sha256', pg_catalog.encode(p_run.source_locator_sha256,'hex'),
        'source_manifest_sha256', pg_catalog.encode(p_run.source_manifest_sha256,'hex'),
        'transform_sha256', pg_catalog.encode(p_run.transform_sha256,'hex'),
        'expected_count', p_run.expected_count,
        'copied_count', p_run.copied_count,
        'cursor_id', p_run.cursor_id,
        'next_page', p_run.next_page,
        'expected_source_sha256', pg_catalog.encode(p_run.expected_source_sha256,'hex'),
        'source_sha256', pg_catalog.encode(p_run.source_sha256,'hex'),
        'target_sha256', pg_catalog.encode(p_run.target_sha256,'hex'),
        'status', p_run.status,
        'revision', p_run.revision,
        'lease_owner', p_run.lease_owner,
        'lease_generation', p_run.lease_generation,
        'lease_expires_at', p_run.lease_expires_at,
        'created_at', p_run.created_at,
        'updated_at', p_run.updated_at
    )
$$;


ALTER FUNCTION platform.support_adoption_run_document_v1(p_run platform.support_adoption_runs) OWNER TO harpy_owner;

--
-- Name: support_adoption_target_drift_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_adoption_target_drift_v1(p_run_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM platform.support_adoption_mappings AS mapping
        WHERE mapping.run_id=p_run_id
          AND mapping.target_sha256 IS DISTINCT FROM pg_catalog.sha256(
              pg_catalog.convert_to((
                  CASE mapping.source_kind
                  WHEN 'contact_global' THEN
                      platform.support_contact_adoption_document_v1(mapping.target_id)
                  WHEN 'bug_tenant' THEN
                      platform.support_bug_adoption_document_v1(mapping.target_id)
                  END
              )::text,'UTF8')
          )
    )
$$;


ALTER FUNCTION platform.support_adoption_target_drift_v1(p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: support_advance_adoption_v1(uuid, uuid, uuid, bigint, bigint, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_advance_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_source_page_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.support_adoption_runs%ROWTYPE;
    v_page platform.support_adoption_page_receipts%ROWTYPE;
    v_source_root bytea;
    v_target_root bytea;
BEGIN
    PERFORM platform.support_require_adopter_v1();
    IF p_page_number < 1 OR pg_catalog.octet_length(p_source_page_sha256) <> 32
       OR p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support adoption advance';
    END IF;
    SELECT run.* INTO v_run FROM platform.support_adoption_runs AS run
    WHERE run.operation_id=p_operation_id AND run.run_id=p_run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6514', MESSAGE='support adoption run not found';
    END IF;
    SELECT page.* INTO v_page FROM platform.support_adoption_page_receipts AS page
    WHERE page.run_id=p_run_id AND page.page_number=p_page_number FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6514', MESSAGE='support adoption page not found';
    END IF;
    IF v_page.cursor_before IS DISTINCT FROM p_cursor_before
       OR v_page.source_page_sha256 <> p_source_page_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption advance drift';
    END IF;
    IF v_page.state='advanced' THEN
        IF v_run.next_page <> p_page_number+1 OR v_run.cursor_id <> v_page.cursor_after THEN
            RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption checkpoint drift';
        END IF;
        RETURN platform.support_adoption_run_document_v1(v_run);
    END IF;
    IF v_run.status <> 'applying' OR v_run.next_page <> p_page_number
       OR v_run.cursor_id IS DISTINCT FROM p_cursor_before
       OR v_run.copied_count+v_page.row_count > v_run.expected_count THEN
        RAISE EXCEPTION USING ERRCODE='P6511', MESSAGE='support adoption advance state mismatch';
    END IF;
    IF v_run.lease_owner <> p_lease_owner
       OR v_run.lease_generation <> p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='P6513', MESSAGE='support adoption lease mismatch';
    END IF;

    v_source_root := pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.encode(v_run.source_sha256,'hex') ||
        pg_catalog.encode(v_page.source_page_sha256,'hex'),'UTF8'));
    v_target_root := pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.encode(v_run.target_sha256,'hex') ||
        pg_catalog.encode(v_page.target_page_sha256,'hex'),'UTF8'));
    UPDATE platform.support_adoption_page_receipts AS page
    SET state='advanced',advanced_at=p_observed_at
    WHERE page.run_id=p_run_id AND page.page_number=p_page_number
    RETURNING * INTO v_page;
    UPDATE platform.support_adoption_runs AS run SET
        cursor_id=v_page.cursor_after,copied_count=run.copied_count+v_page.row_count,
        source_sha256=v_source_root,target_sha256=v_target_root,
        next_page=run.next_page+1,revision=run.revision+1,
        lease_expires_at=p_observed_at+interval '5 minutes',updated_at=p_observed_at
    WHERE run.run_id=p_run_id RETURNING * INTO v_run;
    RETURN platform.support_adoption_run_document_v1(v_run);
END;
$$;


ALTER FUNCTION platform.support_advance_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_source_page_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_apply_bug_adoption_page_v1(uuid, uuid, uuid, bigint, bigint, uuid, jsonb, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_apply_bug_adoption_page_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_rows jsonb, p_source_page_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run platform.support_adoption_runs%ROWTYPE;
    v_page platform.support_adoption_page_receipts%ROWTYPE;
    v_item jsonb;
    v_target jsonb;
    v_source_id uuid;
    v_target_id uuid;
    v_previous uuid := p_cursor_before;
    v_source_hex text := '';
    v_target_hex text := '';
    v_source_sha bytea;
    v_target_sha bytea;
    v_request_sha bytea;
    v_count integer;
BEGIN
    PERFORM platform.support_require_adopter_v1();
    IF p_page_number < 1 OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.octet_length(p_source_page_sha256) <> 32
       OR p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support bug adoption page';
    END IF;
    v_count := pg_catalog.jsonb_array_length(p_rows);
    IF v_count < 1 OR v_count > 100 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='support adoption page is outside budget';
    END IF;
    v_request_sha := pg_catalog.sha256(pg_catalog.convert_to(p_rows::text,'UTF8'));

    SELECT run.* INTO v_run FROM platform.support_adoption_runs AS run
    WHERE run.operation_id=p_operation_id AND run.run_id=p_run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6514', MESSAGE='support adoption run not found';
    END IF;
    IF v_run.source_kind <> 'bug_tenant' THEN
        RAISE EXCEPTION USING ERRCODE='P6511', MESSAGE='support adoption source mismatch';
    END IF;
    IF v_run.lease_owner <> p_lease_owner
       OR v_run.lease_generation <> p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='P6513', MESSAGE='support adoption lease mismatch';
    END IF;

    SELECT page.* INTO v_page FROM platform.support_adoption_page_receipts AS page
    WHERE page.run_id=p_run_id AND page.page_number=p_page_number;
    IF FOUND THEN
        IF v_page.cursor_before IS DISTINCT FROM p_cursor_before
           OR v_page.row_count <> v_count OR v_page.request_sha256 <> v_request_sha
           OR v_page.source_page_sha256 <> p_source_page_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption page drift';
        END IF;
        RETURN platform.support_adoption_page_document_v1(v_page);
    END IF;

    IF v_run.status <> 'applying'
       OR v_run.next_page <> p_page_number
       OR v_run.cursor_id IS DISTINCT FROM p_cursor_before THEN
        RAISE EXCEPTION USING ERRCODE='P6511', MESSAGE='support adoption page state mismatch';
    END IF;

    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(p_rows)
    LOOP
        IF pg_catalog.jsonb_typeof(v_item) <> 'object'
           OR NOT (v_item ?& ARRAY['source_id','source_sha256','target'])
           OR (v_item - ARRAY['source_id','source_sha256','target']) <> '{}'::jsonb
           OR (v_item->>'source_sha256') !~ '^[0-9a-f]{64}$'
           OR pg_catalog.jsonb_typeof(v_item->'target') <> 'object' THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support bug adoption record';
        END IF;
        v_source_id := (v_item->>'source_id')::uuid;
        IF v_source_id='00000000-0000-0000-0000-000000000000'
           OR (v_previous IS NOT NULL AND v_source_id <= v_previous) THEN
            RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support source order drift';
        END IF;
        v_target := v_item->'target';
        IF NOT (v_target ?& ARRAY['reporter_id','reporter_name','reporter_email',
            'title','description','category','severity','priority','page_url','user_agent',
            'browser_info','console_errors','network_info','screenshots','steps_to_reproduce',
            'status','resolution','admin_notes','resolved_at','closed_at','created_at','updated_at'])
           OR (v_target - ARRAY['reporter_id','reporter_name','reporter_email',
            'title','description','category','severity','priority','page_url','user_agent',
            'browser_info','console_errors','network_info','screenshots','steps_to_reproduce',
            'status','resolution','admin_notes','resolved_at','closed_at','created_at','updated_at']
           ) <> '{}'::jsonb THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support bug target';
        END IF;

        v_target_id := pg_catalog.uuidv7();
        INSERT INTO platform.support_bug_reports (
            id,tenant_id,tenant_slug,tenant_name,reporter_id,reporter_name,reporter_email,
            title,description,category,severity,priority,page_url,user_agent,browser_info,
            console_errors,network_info,legacy_screenshot_refs,steps_to_reproduce,status,
            resolution,admin_notes,resolved_at,closed_at,revision,created_at,updated_at
        ) VALUES (
            v_target_id,v_run.source_tenant_id,v_run.tenant_slug,v_run.tenant_name,
            (v_target->>'reporter_id')::uuid,v_target->>'reporter_name',
            v_target->>'reporter_email',v_target->>'title',v_target->>'description',
            v_target->>'category',v_target->>'severity',v_target->>'priority',
            v_target->>'page_url',v_target->>'user_agent',v_target->'browser_info',
            v_target->'console_errors',v_target->'network_info',v_target->'screenshots',
            v_target->>'steps_to_reproduce',v_target->>'status',v_target->>'resolution',
            v_target->>'admin_notes',(v_target->>'resolved_at')::timestamp with time zone,
            (v_target->>'closed_at')::timestamp with time zone,1,
            (v_target->>'created_at')::timestamp with time zone,
            (v_target->>'updated_at')::timestamp with time zone
        );
        v_source_sha := pg_catalog.decode(v_item->>'source_sha256','hex');
        v_target_sha := pg_catalog.sha256(pg_catalog.convert_to(
            platform.support_bug_adoption_document_v1(v_target_id)::text,'UTF8'));
        INSERT INTO platform.support_adoption_mappings (
            run_id,source_kind,source_tenant_id,source_id,target_id,source_sha256,
            target_sha256,page_number,applied_at
        ) VALUES (
            p_run_id,'bug_tenant',v_run.source_tenant_id,v_source_id,v_target_id,
            v_source_sha,v_target_sha,p_page_number,p_observed_at
        );
        v_source_hex := v_source_hex || pg_catalog.encode(v_source_sha,'hex');
        v_target_hex := v_target_hex || pg_catalog.encode(v_target_sha,'hex');
        v_previous := v_source_id;
    END LOOP;

    v_source_sha := pg_catalog.sha256(pg_catalog.convert_to(v_source_hex,'UTF8'));
    v_target_sha := pg_catalog.sha256(pg_catalog.convert_to(v_target_hex,'UTF8'));
    IF v_source_sha <> p_source_page_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support source page checksum drift';
    END IF;
    INSERT INTO platform.support_adoption_page_receipts (
        run_id,page_number,cursor_before,cursor_after,row_count,request_sha256,
        source_page_sha256,target_page_sha256,state,applied_at
    ) VALUES (
        p_run_id,p_page_number,p_cursor_before,v_previous,v_count,v_request_sha,
        v_source_sha,v_target_sha,'applied',p_observed_at
    ) RETURNING * INTO v_page;
    RETURN platform.support_adoption_page_document_v1(v_page);
END;
$_$;


ALTER FUNCTION platform.support_apply_bug_adoption_page_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_rows jsonb, p_source_page_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_apply_contact_adoption_page_v1(uuid, uuid, uuid, bigint, bigint, uuid, jsonb, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_apply_contact_adoption_page_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_rows jsonb, p_source_page_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run platform.support_adoption_runs%ROWTYPE;
    v_page platform.support_adoption_page_receipts%ROWTYPE;
    v_item jsonb;
    v_target jsonb;
    v_source_id uuid;
    v_target_id uuid;
    v_previous uuid := p_cursor_before;
    v_source_hex text := '';
    v_target_hex text := '';
    v_source_sha bytea;
    v_target_sha bytea;
    v_request_sha bytea;
    v_count integer;
BEGIN
    PERFORM platform.support_require_adopter_v1();
    IF p_page_number < 1 OR pg_catalog.jsonb_typeof(p_rows) <> 'array'
       OR pg_catalog.octet_length(p_source_page_sha256) <> 32
       OR p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support contact adoption page';
    END IF;
    v_count := pg_catalog.jsonb_array_length(p_rows);
    IF v_count < 1 OR v_count > 100 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='support adoption page is outside budget';
    END IF;
    v_request_sha := pg_catalog.sha256(pg_catalog.convert_to(p_rows::text,'UTF8'));

    SELECT run.* INTO v_run FROM platform.support_adoption_runs AS run
    WHERE run.operation_id=p_operation_id AND run.run_id=p_run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6514', MESSAGE='support adoption run not found';
    END IF;
    IF v_run.source_kind <> 'contact_global' THEN
        RAISE EXCEPTION USING ERRCODE='P6511', MESSAGE='support adoption source mismatch';
    END IF;
    IF v_run.lease_owner <> p_lease_owner
       OR v_run.lease_generation <> p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='P6513', MESSAGE='support adoption lease mismatch';
    END IF;

    SELECT page.* INTO v_page FROM platform.support_adoption_page_receipts AS page
    WHERE page.run_id=p_run_id AND page.page_number=p_page_number;
    IF FOUND THEN
        IF v_page.cursor_before IS DISTINCT FROM p_cursor_before
           OR v_page.row_count <> v_count OR v_page.request_sha256 <> v_request_sha
           OR v_page.source_page_sha256 <> p_source_page_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption page drift';
        END IF;
        RETURN platform.support_adoption_page_document_v1(v_page);
    END IF;

    IF v_run.status <> 'applying'
       OR v_run.next_page <> p_page_number
       OR v_run.cursor_id IS DISTINCT FROM p_cursor_before THEN
        RAISE EXCEPTION USING ERRCODE='P6511', MESSAGE='support adoption page state mismatch';
    END IF;

    FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(p_rows)
    LOOP
        IF pg_catalog.jsonb_typeof(v_item) <> 'object'
           OR NOT (v_item ?& ARRAY['source_id','source_sha256','target'])
           OR (v_item - ARRAY['source_id','source_sha256','target']) <> '{}'::jsonb
           OR (v_item->>'source_sha256') !~ '^[0-9a-f]{64}$'
           OR pg_catalog.jsonb_typeof(v_item->'target') <> 'object' THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support contact adoption record';
        END IF;
        v_source_id := (v_item->>'source_id')::uuid;
        IF v_source_id='00000000-0000-0000-0000-000000000000'
           OR (v_previous IS NOT NULL AND v_source_id <= v_previous) THEN
            RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support source order drift';
        END IF;
        v_target := v_item->'target';
        IF NOT (v_target ?& ARRAY['name','email','company','phone','employee_count',
            'message','contact_type','status','source','notes','replied_at','replied_by',
            'created_at','updated_at'])
           OR (v_target - ARRAY['name','email','company','phone','employee_count',
            'message','contact_type','status','source','notes','replied_at','replied_by',
            'created_at','updated_at']) <> '{}'::jsonb THEN
            RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support contact target';
        END IF;

        v_target_id := pg_catalog.uuidv7();
        INSERT INTO platform.support_contact_messages (
            id,name,email,company,phone,employee_count,message,contact_type,status,
            source,notes,replied_at,replied_by,revision,created_at,updated_at
        ) VALUES (
            v_target_id,v_target->>'name',v_target->>'email',v_target->>'company',
            v_target->>'phone',v_target->>'employee_count',v_target->>'message',
            v_target->>'contact_type',v_target->>'status',v_target->>'source',
            v_target->>'notes',(v_target->>'replied_at')::timestamp with time zone,
            (v_target->>'replied_by')::uuid,1,
            (v_target->>'created_at')::timestamp with time zone,
            (v_target->>'updated_at')::timestamp with time zone
        );
        v_source_sha := pg_catalog.decode(v_item->>'source_sha256','hex');
        v_target_sha := pg_catalog.sha256(pg_catalog.convert_to(
