--
-- Name: support_bug_stats_v1(uuid, bigint, bigint, boolean, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_bug_stats_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_platform_scope boolean, p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_stats jsonb;
BEGIN
    IF p_actor_id IS NULL OR p_authorization_version < 1 OR p_authority_clock < 1 OR
       p_platform_scope IS NULL OR (NOT p_platform_scope AND p_tenant_id IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6501', MESSAGE = 'support bug stats invalid';
    END IF;
    WITH visible AS (
        SELECT report.* FROM platform.support_bug_reports AS report
        WHERE p_platform_scope OR report.tenant_id = p_tenant_id
    ), categories AS (
        SELECT COALESCE(pg_catalog.jsonb_object_agg(value.category, value.amount), '{}'::jsonb) AS document
        FROM (SELECT visible.category, pg_catalog.count(*) AS amount FROM visible GROUP BY visible.category) AS value
    ), severities AS (
        SELECT COALESCE(pg_catalog.jsonb_object_agg(value.severity, value.amount), '{}'::jsonb) AS document
        FROM (SELECT visible.severity, pg_catalog.count(*) AS amount FROM visible GROUP BY visible.severity) AS value
    )
    SELECT pg_catalog.jsonb_build_object(
        'total', pg_catalog.count(*),
        'open', pg_catalog.count(*) FILTER (WHERE visible.status = 'open'),
        'in_progress', pg_catalog.count(*) FILTER (WHERE visible.status = 'in_progress'),
        'resolved', pg_catalog.count(*) FILTER (WHERE visible.status = 'resolved'),
        'closed', pg_catalog.count(*) FILTER (WHERE visible.status = 'closed'),
        'critical_open', pg_catalog.count(*) FILTER (WHERE visible.status = 'open' AND visible.severity = 'critical'),
        'by_category', (SELECT categories.document FROM categories),
        'by_severity', (SELECT severities.document FROM severities)
    ) INTO v_stats FROM visible;
    RETURN v_stats;
END;
$$;


ALTER FUNCTION platform.support_bug_stats_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_platform_scope boolean, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: support_claim_adoption_v1(uuid, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_claim_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_expected_revision bigint, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.support_adoption_runs%ROWTYPE;
BEGIN
    PERFORM platform.support_require_adopter_v1();
    IF p_lease_owner IS NULL OR p_lease_owner='00000000-0000-0000-0000-000000000000'
       OR p_expected_revision < 1 OR p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support adoption claim';
    END IF;
    SELECT run.* INTO v_run FROM platform.support_adoption_runs AS run
    WHERE run.operation_id=p_operation_id AND run.run_id=p_run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6514', MESSAGE='support adoption run not found';
    END IF;
    IF v_run.status='completed' THEN
        IF v_run.lease_owner <> p_lease_owner THEN
            RAISE EXCEPTION USING ERRCODE='P6513', MESSAGE='support adoption lease mismatch';
        END IF;
        RETURN platform.support_adoption_run_document_v1(v_run);
    END IF;
    IF v_run.status='fenced' THEN
        RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption run is fenced';
    END IF;
    IF v_run.revision = p_expected_revision + 1
       AND v_run.lease_claim_revision = p_expected_revision
       AND v_run.lease_owner = p_lease_owner AND v_run.lease_expires_at > p_observed_at THEN
        RETURN platform.support_adoption_run_document_v1(v_run);
    END IF;
    IF v_run.revision <> p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE='P6511', MESSAGE='support adoption revision mismatch';
    END IF;
    IF v_run.lease_owner IS NOT NULL AND v_run.lease_owner <> p_lease_owner
       AND v_run.lease_expires_at > p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='P6513', MESSAGE='support adoption lease held';
    END IF;
    UPDATE platform.support_adoption_runs AS run SET
        status=CASE WHEN run.status='planned' THEN 'applying' ELSE run.status END,
        lease_owner=p_lease_owner, lease_claim_revision=p_expected_revision,
        lease_generation=run.lease_generation+1,
        lease_expires_at=p_observed_at+interval '5 minutes',
        revision=run.revision+1, updated_at=p_observed_at
    WHERE run.run_id=p_run_id RETURNING * INTO v_run;
    RETURN platform.support_adoption_run_document_v1(v_run);
END;
$$;


ALTER FUNCTION platform.support_claim_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_expected_revision bigint, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_complete_adoption_v1(uuid, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_complete_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.support_adoption_runs%ROWTYPE;
BEGIN
    PERFORM platform.support_require_adopter_v1();
    IF p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support adoption completion';
    END IF;
    SELECT run.* INTO v_run FROM platform.support_adoption_runs AS run
    WHERE run.operation_id=p_operation_id AND run.run_id=p_run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6514', MESSAGE='support adoption run not found';
    END IF;
    IF v_run.lease_owner <> p_lease_owner OR v_run.lease_generation <> p_lease_generation THEN
        RAISE EXCEPTION USING ERRCODE='P6513', MESSAGE='support adoption lease mismatch';
    END IF;
    IF v_run.status='completed' THEN
        RETURN platform.support_adoption_run_document_v1(v_run);
    END IF;
    IF v_run.status <> 'reconciling' OR v_run.reconciled_at IS NULL
       OR v_run.lease_expires_at <= p_observed_at
       OR v_run.copied_count <> v_run.expected_count
       OR v_run.source_sha256 <> v_run.expected_source_sha256
       OR platform.support_adoption_target_drift_v1(p_run_id) THEN
        RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption completion drift';
    END IF;
    UPDATE platform.support_adoption_runs AS run SET
        status='completed',completed_at=p_observed_at,lease_expires_at=p_observed_at,
        revision=run.revision+1,updated_at=p_observed_at
    WHERE run.run_id=p_run_id RETURNING * INTO v_run;
    RETURN platform.support_adoption_run_document_v1(v_run);
END;
$$;


ALTER FUNCTION platform.support_complete_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

