--
-- Name: support_list_bugs_v1(uuid, bigint, bigint, boolean, uuid, uuid, text, text, text, integer, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_list_bugs_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_platform_scope boolean, p_tenant_id uuid, p_reporter_id uuid, p_status text, p_severity text, p_category text, p_page integer, p_page_size integer) RETURNS TABLE(items jsonb, total bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_actor_id IS NULL OR p_authorization_version < 1 OR p_authority_clock < 1 OR
       p_platform_scope IS NULL OR (NOT p_platform_scope AND p_tenant_id IS NULL) OR
       (p_platform_scope AND p_reporter_id IS NOT NULL) OR
       (p_status IS NOT NULL AND p_status NOT IN ('open','in_progress','resolved','closed','wont_fix','duplicate')) OR
       (p_severity IS NOT NULL AND p_severity NOT IN ('critical','high','medium','low')) OR
       (p_category IS NOT NULL AND p_category NOT IN ('bug','feature_request','performance','ui_issue','data_issue','other')) OR
       p_page NOT BETWEEN 1 AND 5001 OR p_page_size NOT BETWEEN 1 AND 100 OR
       (p_page - 1) * p_page_size > 5000 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6501', MESSAGE = 'support bug list invalid';
    END IF;
    RETURN QUERY
    WITH filtered AS MATERIALIZED (
        SELECT report.* FROM platform.support_bug_reports AS report
        WHERE ((p_platform_scope AND (p_tenant_id IS NULL OR report.tenant_id = p_tenant_id))
            OR (NOT p_platform_scope AND report.tenant_id = p_tenant_id))
          AND (p_reporter_id IS NULL OR report.reporter_id = p_reporter_id)
          AND (p_status IS NULL OR report.status = p_status)
          AND (p_severity IS NULL OR report.severity = p_severity)
          AND (p_category IS NULL OR report.category = p_category)
    ), page_rows AS (
        SELECT filtered.* FROM filtered
        ORDER BY filtered.created_at DESC, filtered.id DESC
        OFFSET ((p_page - 1) * p_page_size) LIMIT p_page_size
    )
    SELECT COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(row_value)
        ORDER BY row_value.created_at DESC, row_value.id DESC) FROM page_rows AS row_value),
        '[]'::jsonb), (SELECT pg_catalog.count(*) FROM filtered);
END;
$$;


ALTER FUNCTION platform.support_list_bugs_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_platform_scope boolean, p_tenant_id uuid, p_reporter_id uuid, p_status text, p_severity text, p_category text, p_page integer, p_page_size integer) OWNER TO harpy_owner;

--
-- Name: support_list_contacts_v1(uuid, bigint, bigint, text, text, integer, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_list_contacts_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_status text, p_contact_type text, p_page integer, p_page_size integer) RETURNS TABLE(items jsonb, total bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_actor_id IS NULL OR p_authorization_version < 1 OR p_authority_clock < 1 OR
       (p_status IS NOT NULL AND p_status NOT IN ('new','read','replied','archived')) OR
       (p_contact_type IS NOT NULL AND p_contact_type NOT IN ('general','demo_request','pricing_inquiry','technical_question','partnership','enterprise_plan','on_premise')) OR
       p_page NOT BETWEEN 1 AND 5001 OR p_page_size NOT BETWEEN 1 AND 100 OR
       (p_page - 1) * p_page_size > 5000 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6501', MESSAGE = 'support contact list invalid';
    END IF;
    RETURN QUERY
    WITH filtered AS MATERIALIZED (
        SELECT message.* FROM platform.support_contact_messages AS message
        WHERE (p_status IS NULL OR message.status = p_status)
          AND (p_contact_type IS NULL OR message.contact_type = p_contact_type)
    ), page_rows AS (
        SELECT filtered.* FROM filtered
        ORDER BY filtered.created_at DESC, filtered.id DESC
        OFFSET ((p_page - 1) * p_page_size) LIMIT p_page_size
    )
    SELECT COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(row_value)
        ORDER BY row_value.created_at DESC, row_value.id DESC) FROM page_rows AS row_value),
        '[]'::jsonb), (SELECT pg_catalog.count(*) FROM filtered);
END;
$$;


ALTER FUNCTION platform.support_list_contacts_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_status text, p_contact_type text, p_page integer, p_page_size integer) OWNER TO harpy_owner;

--
-- Name: support_reconcile_adoption_v1(uuid, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_reconcile_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.support_adoption_runs%ROWTYPE;
    v_mapping_count bigint;
    v_page_count bigint;
BEGIN
    PERFORM platform.support_require_adopter_v1();
    IF p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support adoption reconcile';
    END IF;
    SELECT run.* INTO v_run FROM platform.support_adoption_runs AS run
    WHERE run.operation_id=p_operation_id AND run.run_id=p_run_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6514', MESSAGE='support adoption run not found';
    END IF;
    IF v_run.lease_owner <> p_lease_owner
       OR v_run.lease_generation <> p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='P6513', MESSAGE='support adoption lease mismatch';
    END IF;
    IF v_run.status NOT IN ('applying','reconciling') THEN
        RAISE EXCEPTION USING ERRCODE='P6511', MESSAGE='support adoption reconcile state mismatch';
    END IF;
    SELECT pg_catalog.count(*) INTO v_mapping_count
    FROM platform.support_adoption_mappings AS mapping WHERE mapping.run_id=p_run_id;
    SELECT COALESCE(pg_catalog.sum(page.row_count),0::bigint) INTO v_page_count
    FROM platform.support_adoption_page_receipts AS page
    WHERE page.run_id=p_run_id AND page.state='advanced';
    IF v_mapping_count <> v_run.copied_count OR v_page_count <> v_run.copied_count
       OR v_run.copied_count <> v_run.expected_count
       OR v_run.source_sha256 <> v_run.expected_source_sha256
       OR EXISTS (SELECT 1 FROM platform.support_adoption_page_receipts AS page
                  WHERE page.run_id=p_run_id AND page.state<>'advanced')
       OR platform.support_adoption_target_drift_v1(p_run_id) THEN
        RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption reconciliation drift';
    END IF;
    IF v_run.status='reconciling' THEN
        RETURN platform.support_adoption_run_document_v1(v_run);
    END IF;
    UPDATE platform.support_adoption_runs AS run SET
        status='reconciling',reconciled_at=p_observed_at,
        revision=run.revision+1,lease_expires_at=p_observed_at+interval '5 minutes',
        updated_at=p_observed_at
    WHERE run.run_id=p_run_id RETURNING * INTO v_run;
    RETURN platform.support_adoption_run_document_v1(v_run);
END;
$$;


ALTER FUNCTION platform.support_reconcile_adoption_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_require_adopter_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_require_adopter_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF session_user <> 'harpy_adopter' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='support adopter authority required';
    END IF;
END;
$$;


ALTER FUNCTION platform.support_require_adopter_v1() OWNER TO harpy_owner;

--
-- Name: support_start_adoption_v1(uuid, uuid, text, uuid, text, text, oid, text, text, bytea, bytea, bytea, text, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_start_adoption_v1(p_operation_id uuid, p_run_id uuid, p_source_kind text, p_source_tenant_id uuid, p_source_schema text, p_source_relation text, p_source_relation_oid oid, p_tenant_slug text, p_tenant_name text, p_source_locator_sha256 bytea, p_source_manifest_sha256 bytea, p_transform_sha256 bytea, p_snapshot_id text, p_expected_count bigint, p_expected_source_sha256 bytea, p_observed_at timestamp with time zone) RETURNS TABLE(run_document jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.support_adoption_runs%ROWTYPE;
BEGIN
    PERFORM platform.support_require_adopter_v1();
    IF p_operation_id IS NULL OR p_operation_id = '00000000-0000-0000-0000-000000000000'
       OR p_run_id IS NULL OR pg_catalog.uuid_extract_version(p_run_id) <> 7
       OR p_expected_count < 0 OR p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at
       OR pg_catalog.octet_length(p_source_locator_sha256) <> 32
       OR pg_catalog.octet_length(p_source_manifest_sha256) <> 32
       OR pg_catalog.octet_length(p_transform_sha256) <> 32
       OR pg_catalog.octet_length(p_expected_source_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid support adoption plan';
    END IF;
    SELECT run.* INTO v_run FROM platform.support_adoption_runs AS run
    WHERE run.operation_id=p_operation_id;
    IF FOUND THEN
        IF v_run.run_id <> p_run_id OR v_run.source_kind <> p_source_kind
           OR v_run.source_tenant_id IS DISTINCT FROM p_source_tenant_id
           OR v_run.source_schema <> p_source_schema
           OR v_run.source_relation <> p_source_relation
           OR v_run.source_relation_oid <> p_source_relation_oid
           OR v_run.tenant_slug <> p_tenant_slug OR v_run.tenant_name <> p_tenant_name
           OR v_run.source_locator_sha256 <> p_source_locator_sha256
           OR v_run.source_manifest_sha256 <> p_source_manifest_sha256
           OR v_run.transform_sha256 <> p_transform_sha256
           OR v_run.snapshot_id <> p_snapshot_id
           OR v_run.expected_count <> p_expected_count
           OR v_run.expected_source_sha256 <> p_expected_source_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support adoption plan drift';
        END IF;
        RETURN QUERY SELECT platform.support_adoption_run_document_v1(v_run), true;
        RETURN;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_catalog.pg_class AS relation
        JOIN pg_catalog.pg_namespace AS namespace ON namespace.oid=relation.relnamespace
        WHERE relation.oid=p_source_relation_oid
          AND namespace.nspname=p_source_schema
          AND relation.relname=p_source_relation
          AND relation.relkind IN ('r','p')
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6512', MESSAGE='support source locator drift';
    END IF;

    INSERT INTO platform.support_adoption_runs (
        run_id,operation_id,source_kind,source_tenant_id,source_schema,source_relation,
        source_relation_oid,tenant_slug,tenant_name,source_locator_sha256,
        source_manifest_sha256,transform_sha256,snapshot_id,expected_count,
        expected_source_sha256,copied_count,source_sha256,target_sha256,status,
        revision,next_page,lease_generation,created_at,updated_at
    ) VALUES (
        p_run_id,p_operation_id,p_source_kind,p_source_tenant_id,p_source_schema,
        p_source_relation,p_source_relation_oid,p_tenant_slug,p_tenant_name,
        p_source_locator_sha256,p_source_manifest_sha256,p_transform_sha256,
        p_snapshot_id,p_expected_count,p_expected_source_sha256,0,
        pg_catalog.sha256(''::bytea),pg_catalog.sha256(''::bytea),'planned',
        1,1,0,p_observed_at,p_observed_at
    ) RETURNING * INTO v_run;
    RETURN QUERY SELECT platform.support_adoption_run_document_v1(v_run), false;
END;
$$;


ALTER FUNCTION platform.support_start_adoption_v1(p_operation_id uuid, p_run_id uuid, p_source_kind text, p_source_tenant_id uuid, p_source_schema text, p_source_relation text, p_source_relation_oid oid, p_tenant_slug text, p_tenant_name text, p_source_locator_sha256 bytea, p_source_manifest_sha256 bytea, p_transform_sha256 bytea, p_snapshot_id text, p_expected_count bigint, p_expected_source_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_submit_contact_v1(uuid, text, text, text, text, text, text, text, text, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_submit_contact_v1(p_id uuid, p_name text, p_email text, p_company text, p_phone text, p_employee_count text, p_message text, p_contact_type text, p_source text, p_rate_key_sha256 bytea, p_idempotency_key text, p_request_sha256 bytea, p_observed_at timestamp with time zone) RETURNS TABLE(response_document jsonb, replayed boolean, admitted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_partition text;
    v_receipt platform.support_command_receipts%ROWTYPE;
    v_message platform.support_contact_messages%ROWTYPE;
    v_count integer;
    v_bucket timestamp(6) with time zone;
    v_document jsonb;
BEGIN
    IF p_id IS NULL OR pg_catalog.uuid_extract_version(p_id) IS DISTINCT FROM 7 OR
       p_name IS NULL OR p_name <> pg_catalog.btrim(p_name) OR pg_catalog.octet_length(p_name) NOT BETWEEN 1 AND 200 OR
       p_email IS NULL OR p_email <> pg_catalog.lower(pg_catalog.btrim(p_email)) OR pg_catalog.octet_length(p_email) NOT BETWEEN 3 AND 255 OR
       p_company IS NULL OR p_company <> pg_catalog.btrim(p_company) OR pg_catalog.octet_length(p_company) > 200 OR
       p_phone IS NULL OR p_phone <> pg_catalog.btrim(p_phone) OR pg_catalog.octet_length(p_phone) > 50 OR
       p_employee_count IS NULL OR p_employee_count NOT IN ('','1-10','11-50','51-200','201-500','500+') OR
       p_message IS NULL OR p_message <> pg_catalog.btrim(p_message) OR pg_catalog.octet_length(p_message) NOT BETWEEN 1 AND 2000 OR
       p_contact_type IS NULL OR p_contact_type NOT IN ('general','demo_request','pricing_inquiry','technical_question','partnership','enterprise_plan','on_premise') OR
       p_source IS NULL OR p_source <> pg_catalog.btrim(p_source) OR pg_catalog.octet_length(p_source) > 50 OR
       p_rate_key_sha256 IS NULL OR pg_catalog.octet_length(p_rate_key_sha256) <> 32 OR
       p_idempotency_key IS NULL OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 16 AND 200 OR
       p_request_sha256 IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) OR
       pg_catalog.date_trunc('microseconds', p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P6501', MESSAGE = 'support contact command invalid';
    END IF;

    v_partition := 'contact:' || pg_catalog.encode(p_rate_key_sha256, 'hex');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'support.contact.create:' || v_partition || ':' || p_idempotency_key, 0));
    SELECT receipt.* INTO v_receipt
    FROM platform.support_command_receipts AS receipt
    WHERE receipt.operation = 'support.contact.create'
      AND receipt.principal_partition = v_partition
      AND receipt.idempotency_key = p_idempotency_key;
    IF FOUND THEN
        IF v_receipt.request_sha256 <> p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6502', MESSAGE = 'support idempotency mismatch';
        END IF;
        RETURN QUERY SELECT v_receipt.response_document, true, true;
        RETURN;
    END IF;

    v_bucket := pg_catalog.date_bin('15 minutes'::interval, p_observed_at,
        '2000-01-01 00:00:00+00'::timestamp with time zone);
    INSERT INTO platform.support_public_rate_leases AS lease(
        rate_key_sha256, bucket_start, request_count, updated_at)
    VALUES (p_rate_key_sha256, v_bucket, 1, p_observed_at)
    ON CONFLICT (rate_key_sha256, bucket_start) DO UPDATE
    SET request_count = lease.request_count + 1, updated_at = EXCLUDED.updated_at
    RETURNING request_count INTO v_count;
    IF v_count > 5 THEN
        RETURN QUERY SELECT NULL::jsonb, false, false;
        RETURN;
    END IF;

    INSERT INTO platform.support_contact_messages(
        id, name, email, company, phone, employee_count, message, contact_type,
        status, source, revision, created_at, updated_at)
    VALUES (p_id, p_name, p_email, p_company, p_phone, p_employee_count, p_message,
        p_contact_type, 'new', p_source, 1, p_observed_at, p_observed_at)
    RETURNING * INTO v_message;
    v_document := pg_catalog.to_jsonb(v_message);
    INSERT INTO platform.support_command_receipts(
        receipt_id, operation, principal_partition, idempotency_key,
        request_sha256, result_id, result_revision, response_document, created_at)
    VALUES (pg_catalog.uuidv7(), 'support.contact.create', v_partition,
        p_idempotency_key, p_request_sha256, p_id, 1, v_document, p_observed_at);
    RETURN QUERY SELECT v_document, false, true;
END;
$$;


ALTER FUNCTION platform.support_submit_contact_v1(p_id uuid, p_name text, p_email text, p_company text, p_phone text, p_employee_count text, p_message text, p_contact_type text, p_source text, p_rate_key_sha256 bytea, p_idempotency_key text, p_request_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_update_bug_v1(uuid, bigint, bigint, boolean, uuid, uuid, boolean, text, boolean, text, boolean, text, boolean, text, bigint, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_update_bug_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_platform_scope boolean, p_tenant_id uuid, p_id uuid, p_has_status boolean, p_status text, p_has_priority boolean, p_priority text, p_has_resolution boolean, p_resolution text, p_has_admin_notes boolean, p_admin_notes text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_observed_at timestamp with time zone) RETURNS TABLE(response_document jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation text;
    v_partition text;
    v_receipt platform.support_command_receipts%ROWTYPE;
    v_report platform.support_bug_reports%ROWTYPE;
    v_document jsonb;
BEGIN
    IF p_actor_id IS NULL OR p_authorization_version < 1 OR p_authority_clock < 1 OR
       p_platform_scope IS NULL OR p_tenant_id IS NULL OR p_id IS NULL OR
       (NOT p_has_status AND NOT p_has_priority AND NOT p_has_resolution AND NOT p_has_admin_notes) OR
       (p_has_status AND (p_status IS NULL OR p_status NOT IN ('open','in_progress','resolved','closed','wont_fix','duplicate'))) OR
       (NOT p_has_status AND p_status IS NOT NULL) OR
       (p_has_priority AND (p_priority IS NULL OR p_priority NOT IN ('urgent','high','normal','low'))) OR
       (NOT p_has_priority AND p_priority IS NOT NULL) OR
       (p_has_resolution AND (p_resolution IS NULL OR pg_catalog.octet_length(p_resolution) > 8000)) OR
       (NOT p_has_resolution AND p_resolution IS NOT NULL) OR
       (p_has_admin_notes AND (p_admin_notes IS NULL OR pg_catalog.octet_length(p_admin_notes) > 8000)) OR
       (NOT p_has_admin_notes AND p_admin_notes IS NOT NULL) OR
       p_expected_revision < 1 OR
       p_idempotency_key IS NULL OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 16 AND 200 OR
       p_request_sha256 IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) OR
       pg_catalog.date_trunc('microseconds', p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P6501', MESSAGE = 'support bug update invalid';
    END IF;
    v_operation := CASE WHEN p_platform_scope
        THEN 'support.bug.platform.update' ELSE 'support.bug.tenant.update' END;
    v_partition := 'actor:' || p_actor_id::text;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        v_operation || ':' || v_partition || ':' || p_idempotency_key, 0));
    SELECT receipt.* INTO v_receipt FROM platform.support_command_receipts AS receipt
    WHERE receipt.operation = v_operation
      AND receipt.principal_partition = v_partition
      AND receipt.idempotency_key = p_idempotency_key;
    IF FOUND THEN
        IF v_receipt.request_sha256 <> p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6502', MESSAGE = 'support idempotency mismatch';
        END IF;
        RETURN QUERY SELECT v_receipt.response_document, true;
        RETURN;
    END IF;
    SELECT report.* INTO v_report FROM platform.support_bug_reports AS report
    WHERE report.id = p_id AND report.tenant_id = p_tenant_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6504', MESSAGE = 'support bug missing';
    END IF;
    IF v_report.revision <> p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = 'P6503', MESSAGE = 'support revision stale';
    END IF;
    UPDATE platform.support_bug_reports AS report
    SET status = CASE WHEN p_has_status THEN p_status ELSE report.status END,
        priority = CASE WHEN p_has_priority THEN p_priority ELSE report.priority END,
        resolution = CASE WHEN p_has_resolution THEN p_resolution ELSE report.resolution END,
        admin_notes = CASE WHEN p_has_admin_notes THEN p_admin_notes ELSE report.admin_notes END,
        resolved_at = CASE WHEN p_has_status AND p_status = 'resolved' THEN p_observed_at ELSE report.resolved_at END,
        closed_at = CASE WHEN p_has_status AND p_status = 'closed' THEN p_observed_at ELSE report.closed_at END,
        revision = report.revision + 1, updated_at = p_observed_at
    WHERE report.id = p_id AND report.tenant_id = p_tenant_id
    RETURNING * INTO v_report;
    v_document := pg_catalog.to_jsonb(v_report);
    INSERT INTO platform.support_command_receipts(
        receipt_id, operation, principal_partition, idempotency_key,
        request_sha256, result_id, result_revision, response_document, created_at)
    VALUES (pg_catalog.uuidv7(), v_operation, v_partition, p_idempotency_key,
        p_request_sha256, p_id, v_report.revision, v_document, p_observed_at);
    RETURN QUERY SELECT v_document, false;
END;
$$;


ALTER FUNCTION platform.support_update_bug_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_platform_scope boolean, p_tenant_id uuid, p_id uuid, p_has_status boolean, p_status text, p_has_priority boolean, p_priority text, p_has_resolution boolean, p_resolution text, p_has_admin_notes boolean, p_admin_notes text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: support_update_contact_v1(uuid, bigint, bigint, uuid, boolean, text, boolean, text, bigint, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.support_update_contact_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_id uuid, p_has_status boolean, p_status text, p_has_notes boolean, p_notes text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_observed_at timestamp with time zone) RETURNS TABLE(response_document jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_partition text;
    v_receipt platform.support_command_receipts%ROWTYPE;
    v_message platform.support_contact_messages%ROWTYPE;
    v_document jsonb;
BEGIN
    IF p_actor_id IS NULL OR p_authorization_version < 1 OR p_authority_clock < 1 OR
       p_id IS NULL OR (NOT p_has_status AND NOT p_has_notes) OR
       (p_has_status AND (p_status IS NULL OR p_status NOT IN ('new','read','replied','archived'))) OR
       (NOT p_has_status AND p_status IS NOT NULL) OR
       (p_has_notes AND (p_notes IS NULL OR pg_catalog.octet_length(p_notes) > 8000)) OR
       (NOT p_has_notes AND p_notes IS NOT NULL) OR p_expected_revision < 1 OR
       p_idempotency_key IS NULL OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 16 AND 200 OR
       p_request_sha256 IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) OR
       pg_catalog.date_trunc('microseconds', p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P6501', MESSAGE = 'support contact update invalid';
    END IF;
    v_partition := 'actor:' || p_actor_id::text;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'support.contact.update:' || v_partition || ':' || p_idempotency_key, 0));
    SELECT receipt.* INTO v_receipt FROM platform.support_command_receipts AS receipt
    WHERE receipt.operation = 'support.contact.update'
      AND receipt.principal_partition = v_partition
      AND receipt.idempotency_key = p_idempotency_key;
    IF FOUND THEN
        IF v_receipt.request_sha256 <> p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6502', MESSAGE = 'support idempotency mismatch';
        END IF;
        RETURN QUERY SELECT v_receipt.response_document, true;
        RETURN;
    END IF;
    SELECT message.* INTO v_message FROM platform.support_contact_messages AS message
    WHERE message.id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6504', MESSAGE = 'support contact missing';
    END IF;
    IF v_message.revision <> p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = 'P6503', MESSAGE = 'support revision stale';
    END IF;
    UPDATE platform.support_contact_messages AS message
    SET status = CASE WHEN p_has_status THEN p_status ELSE message.status END,
        notes = CASE WHEN p_has_notes THEN p_notes ELSE message.notes END,
        replied_at = CASE WHEN p_has_status AND p_status = 'replied' THEN p_observed_at ELSE message.replied_at END,
        replied_by = CASE WHEN p_has_status AND p_status = 'replied' THEN p_actor_id ELSE message.replied_by END,
        revision = message.revision + 1, updated_at = p_observed_at
    WHERE message.id = p_id RETURNING * INTO v_message;
    v_document := pg_catalog.to_jsonb(v_message);
    INSERT INTO platform.support_command_receipts(
        receipt_id, operation, principal_partition, idempotency_key,
        request_sha256, result_id, result_revision, response_document, created_at)
    VALUES (pg_catalog.uuidv7(), 'support.contact.update', v_partition,
        p_idempotency_key, p_request_sha256, p_id, v_message.revision,
        v_document, p_observed_at);
    RETURN QUERY SELECT v_document, false;
END;
$$;


ALTER FUNCTION platform.support_update_contact_v1(p_actor_id uuid, p_authorization_version bigint, p_authority_clock bigint, p_id uuid, p_has_status boolean, p_status text, p_has_notes boolean, p_notes text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_assert_v1(uuid, uuid, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_assert_v1(p_operation_id uuid, p_tenant_id uuid, p_schema_name name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_kind text;
    v_tenant_id uuid;
    v_schema_name text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_schema_name IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation assertion denied';
    END IF;
    SELECT operation.state, operation.operation_kind,
           operation.tenant_id, operation.schema_name
    INTO v_state, v_kind, v_tenant_id, v_schema_name
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_state IS DISTINCT FROM 'finalizing'
       OR v_kind IS DISTINCT FROM 'environment_initialize'
       OR v_tenant_id IS DISTINCT FROM p_tenant_id
       OR v_schema_name IS DISTINCT FROM p_schema_name THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation assertion conflicts';
    END IF;
    PERFORM 1
    FROM platform.tenants AS tenant
    WHERE tenant.id = p_tenant_id
      AND tenant.schema_name = p_schema_name
      AND tenant.status = 'ACTIVE'
      AND tenant.deleted_at IS NULL
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation target is not active';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.tenancy_activation_assert_v1(p_operation_id uuid, p_tenant_id uuid, p_schema_name name) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_assert_v2(uuid, uuid, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_assert_v2(p_operation_id uuid, p_tenant_id uuid, p_schema_name name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_kind text;
    v_mode text;
    v_tenant_id uuid;
    v_schema_name text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_schema_name IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation assertion denied';
    END IF;
    SELECT operation.state, operation.operation_kind,
           operation.deployment_mode, operation.tenant_id,
           operation.schema_name
    INTO v_state, v_kind, v_mode, v_tenant_id, v_schema_name
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_state IS DISTINCT FROM 'finalizing'
       OR v_kind NOT IN (
           'environment_initialize', 'saas_customer_tenant_provision'
       )
       OR (v_kind = 'saas_customer_tenant_provision'
           AND v_mode IS DISTINCT FROM 'saas')
       OR v_tenant_id IS DISTINCT FROM p_tenant_id
       OR v_schema_name IS DISTINCT FROM p_schema_name THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation assertion conflicts';
    END IF;
    PERFORM 1
    FROM platform.tenants AS tenant
    WHERE tenant.id = p_tenant_id
      AND tenant.schema_name = p_schema_name
      AND tenant.status = 'ACTIVE'
      AND tenant.deleted_at IS NULL
    FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation target is not active';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION platform.tenancy_activation_assert_v2(p_operation_id uuid, p_tenant_id uuid, p_schema_name name) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_capability_commit_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_capability_commit_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM platform.tenancy_activation_command_capabilities AS capability
        WHERE capability.backend_pid = NEW.backend_pid
          AND capability.transaction_id = NEW.transaction_id
          AND capability.operation_id = NEW.operation_id
          AND capability.command_key = NEW.command_key
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'tenancy activation command capability was not consumed';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.tenancy_activation_capability_commit_guard_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_activation_command_consume_v1(uuid, text, uuid, uuid, text, text, text, text, uuid, bigint, text, timestamp with time zone, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_command_consume_v1(p_operation_id uuid, p_command_key text, p_environment_id uuid, p_tenant_id uuid, p_operation_kind text, p_deployment_mode text, p_binding_purpose text, p_manifest_sha256 text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_consumed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RETURN false;
    END IF;
    DELETE FROM platform.tenancy_activation_command_capabilities AS capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id()
      AND capability.operation_id = p_operation_id
      AND capability.command_key = p_command_key
      AND capability.environment_id = p_environment_id
      AND capability.tenant_id = p_tenant_id
      AND capability.operation_kind = p_operation_kind
      AND capability.deployment_mode = p_deployment_mode
      AND capability.binding_purpose = p_binding_purpose
      AND capability.manifest_sha256 = p_manifest_sha256
      AND capability.offering_version_id = p_offering_version_id
      AND capability.offering_revision = p_offering_revision
      AND capability.offering_sha256 = p_offering_sha256
      AND capability.offering_effective_at = p_offering_effective_at
      AND capability.offering_source_sequence
            IS NOT DISTINCT FROM p_offering_source_sequence
      AND capability.offering_source_sha256
            IS NOT DISTINCT FROM p_offering_source_sha256
    RETURNING true INTO v_consumed;
    RETURN coalesce(v_consumed, false);
END;
$$;


ALTER FUNCTION platform.tenancy_activation_command_consume_v1(p_operation_id uuid, p_command_key text, p_environment_id uuid, p_tenant_id uuid, p_operation_kind text, p_deployment_mode text, p_binding_purpose text, p_manifest_sha256 text, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_cutover_initialize_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_cutover_initialize_v1(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant cutover activation denied';
    END IF;
    PERFORM platform.cutover_initialize_tenant_v1(
        p_operation_id, p_tenant_id, p_owner_user_id, p_manifest_sha256
    );
END;
$$;


ALTER FUNCTION platform.tenancy_activation_cutover_initialize_v1(p_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_initialize_v1(uuid, uuid, uuid, text, text, uuid, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_initialize_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_existing platform.tenancy_activation_facts%ROWTYPE;
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation initialization denied';
    END IF;
    IF p_tenant_name IS NULL OR pg_catalog.char_length(p_tenant_name) NOT BETWEEN 1 AND 255
       OR p_tenant_name IS DISTINCT FROM pg_catalog.btrim(p_tenant_name)
       OR p_tenant_slug IS NULL OR pg_catalog.char_length(p_tenant_slug) NOT BETWEEN 1 AND 100
       OR p_tenant_slug IS DISTINCT FROM pg_catalog.lower(p_tenant_slug)
       OR p_schema_name !~ '^[a-z][a-z0-9_]*$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant activation input is invalid';
    END IF;
    SELECT * INTO v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_operation.state IS DISTINCT FROM 'finalizing'
       OR v_operation.environment_id IS DISTINCT FROM p_environment_id
       OR v_operation.tenant_id IS DISTINCT FROM p_tenant_id
       OR v_operation.first_user_id IS DISTINCT FROM p_owner_user_id
       OR v_operation.schema_name IS DISTINCT FROM p_schema_name
       OR v_operation.binding_purpose IS DISTINCT FROM p_binding_purpose
       OR v_operation.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation plan conflict';
    END IF;
    SELECT * INTO v_existing
    FROM platform.tenancy_activation_facts AS fact
    WHERE fact.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_existing.owner_user_id IS DISTINCT FROM p_owner_user_id
           OR v_existing.binding_purpose IS DISTINCT FROM p_binding_purpose
           OR v_existing.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'tenant activation replay conflict';
        END IF;
        RETURN true;
    END IF;
    INSERT INTO platform.tenants (
        id, name, slug, status, settings, owner_id, schema_name,
        created_at, updated_at, deleted_at
    ) VALUES (
        p_tenant_id, p_tenant_name, p_tenant_slug, 'ACTIVE', '{}'::jsonb,
        p_owner_user_id, p_schema_name, v_now, v_now, NULL
    );
    INSERT INTO platform.tenancy_tenant_bindings (
        environment_id, tenant_id, purpose, created_at
    ) VALUES (p_environment_id, p_tenant_id, p_binding_purpose, v_now);
    PERFORM platform.tenancy_activation_cutover_initialize_v1(
        p_operation_id, p_tenant_id, p_owner_user_id, p_manifest_sha256
    );
    INSERT INTO platform.tenancy_activation_audits (
        operation_id, environment_id, tenant_id, actor_id,
        event_type, manifest_sha256, recorded_at
    ) VALUES (
        p_operation_id, p_environment_id, p_tenant_id, p_owner_user_id,
        'installation.activated', p_manifest_sha256, v_now
    );
    INSERT INTO platform.tenancy_activation_facts (
        operation_id, environment_id, tenant_id, owner_user_id,
        binding_purpose, manifest_sha256, activated_at
    ) VALUES (
        p_operation_id, p_environment_id, p_tenant_id, p_owner_user_id,
        p_binding_purpose, p_manifest_sha256, v_now
    );
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.tenancy_activation_initialize_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_initialize_v2(uuid, uuid, uuid, text, text, uuid, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_initialize_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_replayed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation initialization v2 denied';
    END IF;
    SELECT platform.tenancy_activation_initialize_v1(
        p_operation_id, p_environment_id, p_tenant_id,
        p_tenant_name, p_tenant_slug, p_owner_user_id,
        p_schema_name, p_binding_purpose, p_manifest_sha256
    ) INTO v_replayed;
    PERFORM platform.cutover_initialize_tenant_v2(
        p_operation_id, p_tenant_id, p_owner_user_id, p_manifest_sha256
    );
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.tenancy_activation_initialize_v2(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_initialize_v3(uuid, uuid, uuid, text, text, uuid, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_initialize_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_replayed boolean;
    v_authority_id uuid;
    v_created_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation initialization v3 denied';
    END IF;
    SELECT platform.tenancy_activation_initialize_v2(
        p_operation_id, p_environment_id, p_tenant_id,
        p_tenant_name, p_tenant_slug, p_owner_user_id,
        p_schema_name, p_binding_purpose, p_manifest_sha256
    ) INTO v_replayed;
    SELECT tenant.created_at INTO STRICT v_created_at
    FROM platform.tenants AS tenant
    WHERE tenant.id = p_tenant_id
      AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL');
    v_authority_id := pg_catalog.overlay(
        p_operation_id::text, '7', 15, 1
    )::uuid;
    PERFORM platform.analytics_register_tenant_authority_v1(
        v_authority_id, p_tenant_id, 1, 1, v_created_at
    );
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.tenancy_activation_initialize_v3(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_initialize_v4(uuid, uuid, uuid, text, text, uuid, text, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_initialize_v4(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text, p_operation_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_existing platform.tenancy_activation_facts%ROWTYPE;
    v_application text;
    v_now timestamptz;
    v_created_at timestamptz;
    v_authority_id uuid;
    v_replayed boolean;
BEGIN
    v_application := pg_catalog.current_setting('application_name', true);
    v_now := pg_catalog.statement_timestamp();
    v_replayed := false;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR NOT (
           (p_operation_kind = 'environment_initialize'
            AND v_application = 'harpy-v2:core-operator-initialize')
           OR (p_operation_kind = 'saas_customer_tenant_provision'
               AND v_application = 'harpy-v2:core-worker')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation initialization v4 denied';
    END IF;
    IF p_tenant_name IS NULL
       OR pg_catalog.char_length(p_tenant_name) NOT BETWEEN 1 AND 255
       OR p_tenant_name IS DISTINCT FROM pg_catalog.btrim(p_tenant_name)
       OR p_tenant_slug IS NULL
       OR pg_catalog.char_length(p_tenant_slug) NOT BETWEEN 1 AND 100
       OR p_tenant_slug IS DISTINCT FROM pg_catalog.lower(p_tenant_slug)
       OR p_schema_name !~ '^[a-z][a-z0-9_]*$'
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant activation input is invalid';
    END IF;
    SELECT * INTO v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_operation.state IS DISTINCT FROM 'finalizing'
       OR v_operation.operation_kind IS DISTINCT FROM p_operation_kind
       OR v_operation.environment_id IS DISTINCT FROM p_environment_id
       OR v_operation.tenant_id IS DISTINCT FROM p_tenant_id
       OR v_operation.first_user_id IS DISTINCT FROM p_owner_user_id
       OR v_operation.schema_name::text IS DISTINCT FROM p_schema_name
       OR v_operation.binding_purpose IS DISTINCT FROM p_binding_purpose
       OR v_operation.manifest_sha256 IS DISTINCT FROM p_manifest_sha256
       OR NOT (
           (v_operation.operation_kind = 'environment_initialize'
            AND ((v_operation.deployment_mode = 'onpremise'
                  AND v_operation.binding_purpose = 'onpremise_primary')
                 OR (v_operation.deployment_mode = 'saas'
                     AND v_operation.binding_purpose = 'saas_control')))
           OR (v_operation.operation_kind = 'saas_customer_tenant_provision'
               AND v_operation.deployment_mode = 'saas'
               AND v_operation.binding_purpose = 'saas_customer')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation plan conflict';
    END IF;
    IF p_operation_kind = 'environment_initialize' THEN
        RETURN platform.tenancy_activation_initialize_v3(
            p_operation_id, p_environment_id, p_tenant_id,
            p_tenant_name, p_tenant_slug, p_owner_user_id,
            p_schema_name, p_binding_purpose, p_manifest_sha256
        );
    END IF;
    SELECT * INTO v_existing
    FROM platform.tenancy_activation_facts AS fact
    WHERE fact.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_existing.owner_user_id IS DISTINCT FROM p_owner_user_id
           OR v_existing.binding_purpose IS DISTINCT FROM p_binding_purpose
           OR v_existing.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'tenant activation replay conflict';
        END IF;
        v_replayed := true;
    ELSE
        INSERT INTO platform.tenants (
            id, name, slug, status, settings, owner_id, schema_name,
            created_at, updated_at, deleted_at
        ) VALUES (
            p_tenant_id, p_tenant_name, p_tenant_slug, 'ACTIVE', '{}'::jsonb,
            p_owner_user_id, p_schema_name, v_now, v_now, NULL
        );
        INSERT INTO platform.tenancy_tenant_bindings (
            environment_id, tenant_id, purpose, created_at
        ) VALUES (p_environment_id, p_tenant_id, p_binding_purpose, v_now);
        INSERT INTO platform.tenancy_activation_audits (
            operation_id, environment_id, tenant_id, actor_id,
            event_type, manifest_sha256, recorded_at
        ) VALUES (
            p_operation_id, p_environment_id, p_tenant_id, p_owner_user_id,
            'installation.activated', p_manifest_sha256, v_now
        );
        INSERT INTO platform.tenancy_activation_facts (
            operation_id, environment_id, tenant_id, owner_user_id,
            binding_purpose, manifest_sha256, activated_at
        ) VALUES (
            p_operation_id, p_environment_id, p_tenant_id, p_owner_user_id,
            p_binding_purpose, p_manifest_sha256, v_now
        );
    END IF;
    PERFORM platform.cutover_initialize_tenant_v3(
        p_operation_id, p_tenant_id, p_owner_user_id,
        p_manifest_sha256, p_operation_kind
    );
    SELECT tenant.created_at INTO STRICT v_created_at
    FROM platform.tenants AS tenant
    WHERE tenant.id = p_tenant_id
      AND tenant.deleted_at IS NULL
      AND tenant.status IN ('ACTIVE', 'TRIAL');
    v_authority_id := pg_catalog.overlay(
        p_operation_id::text, '7', 15, 1
    )::uuid;
    PERFORM platform.analytics_register_tenant_authority_v1(
        v_authority_id, p_tenant_id, 1, 1, v_created_at
    );
    RETURN v_replayed;
END;
$_$;


ALTER FUNCTION platform.tenancy_activation_initialize_v4(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text, p_operation_kind text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_initialize_v5(uuid, uuid, uuid, text, text, uuid, text, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_initialize_v5(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text, p_operation_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_replayed boolean;
BEGIN
    IF NOT platform.tenancy_activation_step_assert_v1(
        p_operation_id, 'tenancy.activate_tenant'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation step capability required';
    END IF;
    v_replayed := platform.tenancy_activation_initialize_v4(
        p_operation_id, p_environment_id, p_tenant_id, p_tenant_name,
        p_tenant_slug, p_owner_user_id, p_schema_name, p_binding_purpose,
        p_manifest_sha256, p_operation_kind
    );
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id, 'tenancy.activate_tenant'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation step capability consume failed';
    END IF;
    RETURN v_replayed;
END;
$$;


ALTER FUNCTION platform.tenancy_activation_initialize_v5(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_name text, p_tenant_slug text, p_owner_user_id uuid, p_schema_name text, p_binding_purpose text, p_manifest_sha256 text, p_operation_kind text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_step_assert_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_step_assert_v1(p_operation_id uuid, p_command_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN SESSION_USER = 'harpy_v2_runtime'
       AND CURRENT_USER = 'harpy_owner'
       AND EXISTS (
            SELECT 1
            FROM platform.tenancy_activation_step_capabilities AS capability
            JOIN platform.tenancy_onboarding_operations AS operation
              ON operation.operation_id = capability.operation_id
            JOIN platform.tenancy_onboarding_leases AS lease
              ON lease.operation_id = operation.operation_id
            WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
              AND capability.transaction_id = pg_catalog.pg_current_xact_id()
              AND capability.operation_id = p_operation_id
              AND capability.command_key = p_command_key
              AND operation.state = 'finalizing'
              AND operation.environment_id = capability.environment_id
              AND operation.tenant_id = capability.tenant_id
              AND operation.schema_name = capability.schema_name
              AND operation.operation_kind = capability.operation_kind
              AND operation.deployment_mode = capability.deployment_mode
              AND operation.binding_purpose = capability.binding_purpose
              AND operation.manifest_sha256 = capability.manifest_sha256
              AND operation.step_plan_sha256 = capability.step_plan_sha256
              AND lease.lease_until > pg_catalog.statement_timestamp()
       );
END;
$$;


ALTER FUNCTION platform.tenancy_activation_step_assert_v1(p_operation_id uuid, p_command_key text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_step_commit_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_step_commit_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM platform.tenancy_activation_step_capabilities AS capability
        WHERE capability.backend_pid = NEW.backend_pid
          AND capability.transaction_id = NEW.transaction_id
          AND capability.operation_id = NEW.operation_id
          AND capability.command_key = NEW.command_key
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'tenancy activation step capability was not consumed';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.tenancy_activation_step_commit_guard_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_activation_step_consume_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_step_consume_v1(p_operation_id uuid, p_command_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_consumed boolean;
BEGIN
    IF NOT platform.tenancy_activation_step_assert_v1(
        p_operation_id, p_command_key
    ) THEN
        RETURN false;
    END IF;
    DELETE FROM platform.tenancy_activation_step_capabilities AS capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id()
      AND capability.operation_id = p_operation_id
      AND capability.command_key = p_command_key
    RETURNING true INTO v_consumed;
    RETURN COALESCE(v_consumed, false);
END;
$$;


ALTER FUNCTION platform.tenancy_activation_step_consume_v1(p_operation_id uuid, p_command_key text) OWNER TO harpy_owner;

--
-- Name: tenancy_activation_step_context_assert_v1(uuid, text, uuid, uuid, name, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_activation_step_context_assert_v1(p_operation_id uuid, p_command_key text, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_operation_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN platform.tenancy_activation_step_assert_v1(
        p_operation_id, p_command_key
    ) AND EXISTS (
        SELECT 1
        FROM platform.tenancy_activation_step_capabilities AS capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id()
          AND capability.operation_id = p_operation_id
          AND capability.command_key = p_command_key
          AND capability.environment_id = p_environment_id
          AND capability.tenant_id = p_tenant_id
          AND capability.schema_name = p_schema_name
          AND capability.operation_kind = p_operation_kind
    );
END;
$$;


ALTER FUNCTION platform.tenancy_activation_step_context_assert_v1(p_operation_id uuid, p_command_key text, p_environment_id uuid, p_tenant_id uuid, p_schema_name name, p_operation_kind text) OWNER TO harpy_owner;

--
-- Name: tenancy_assert_saas_customer_offboard_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_assert_saas_customer_offboard_v1(p_environment_id uuid, p_tenant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN platform.tenancy_assert_saas_customer_target_v1(
        p_environment_id,
        p_tenant_id
    );
END;
$$;


ALTER FUNCTION platform.tenancy_assert_saas_customer_offboard_v1(p_environment_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_assert_saas_customer_target_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_assert_saas_customer_target_v1(p_environment_id uuid, p_tenant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
        OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
        OR p_environment_id IS NULL OR p_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'SaaS customer target query denied';
    END IF;
    PERFORM 1
    FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id = policy.environment_id
    WHERE policy.environment_id = p_environment_id
      AND policy.deployment_mode = 'saas'
      AND binding.tenant_id = p_tenant_id
      AND binding.purpose = 'saas_customer';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'SaaS customer target is required';
    END IF;
    RETURN p_tenant_id;
END;
$$;


ALTER FUNCTION platform.tenancy_assert_saas_customer_target_v1(p_environment_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_authority_reconcile_current_v1(uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_authority_reconcile_current_v1(p_operation_id uuid, p_manifest_sha256 text) RETURNS TABLE(billing_global_reconciled integer, billing_global_remaining integer, billing_tenant_reconciled integer, billing_tenant_remaining integer, analytics_reconciled integer, analytics_remaining integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_deleted integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenancy authority reconciliation is denied';
    END IF;
    SELECT * INTO v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR SHARE;
    IF NOT FOUND
       OR v_operation.operation_kind IS DISTINCT FROM 'environment_initialize'
       OR v_operation.state IS DISTINCT FROM 'succeeded'
       OR v_operation.manifest_sha256 IS DISTINCT FROM p_manifest_sha256
       OR NOT EXISTS (
            SELECT 1
            FROM platform.tenancy_activation_facts AS fact
            JOIN platform.tenancy_tenant_bindings AS binding
              ON binding.environment_id = fact.environment_id
             AND binding.tenant_id = fact.tenant_id
             AND binding.purpose = fact.binding_purpose
            JOIN platform.tenants AS tenant ON tenant.id = fact.tenant_id
            WHERE fact.operation_id = v_operation.operation_id
              AND fact.environment_id = v_operation.environment_id
              AND fact.tenant_id = v_operation.tenant_id
              AND fact.owner_user_id = v_operation.first_user_id
              AND fact.binding_purpose = v_operation.binding_purpose
              AND fact.manifest_sha256 = v_operation.manifest_sha256
              AND tenant.deleted_at IS NULL
              AND tenant.status IN ('ACTIVE', 'TRIAL')
       )
       OR NOT EXISTS (
            SELECT 1 FROM platform.tenancy_onboarding_receipts AS receipt
            WHERE receipt.operation_id = v_operation.operation_id
              AND receipt.receipt_kind = 'activation_completed'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'completed environment initialization is required';
    END IF;
    INSERT INTO platform.tenancy_authority_reconcile_scopes (
        backend_pid, transaction_id, operation_id, environment_id,
        manifest_sha256, step_plan_sha256, owner_key, created_at
    )
    SELECT pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
           v_operation.operation_id, v_operation.environment_id,
           v_operation.manifest_sha256, v_operation.step_plan_sha256,
           owner_key, pg_catalog.transaction_timestamp()
    FROM (VALUES ('billing'), ('analytics')) AS owners(owner_key);

    SELECT reconciled_count, remaining_count
    INTO billing_global_reconciled, billing_global_remaining
    FROM platform.billing_reconcile_current_global_authority_v2();
    SELECT reconciled_count, remaining_count
    INTO billing_tenant_reconciled, billing_tenant_remaining
    FROM platform.billing_reconcile_current_tenant_authorities_v2();
    SELECT reconciled_count, remaining_count
    INTO analytics_reconciled, analytics_remaining
    FROM platform.analytics_reconcile_current_tenant_authorities_v2();

    DELETE FROM platform.tenancy_authority_reconcile_scopes AS scope
    WHERE scope.backend_pid = pg_catalog.pg_backend_pid()
      AND scope.transaction_id = pg_catalog.pg_current_xact_id()
      AND scope.operation_id = v_operation.operation_id;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    IF v_deleted IS DISTINCT FROM 2 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'tenancy authority reconcile scope cleanup failed';
    END IF;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.tenancy_authority_reconcile_current_v1(p_operation_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_authority_reconcile_scope_assert_v1(text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_authority_reconcile_scope_assert_v1(p_owner_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN SESSION_USER = 'harpy_v2_runtime'
       AND CURRENT_USER = 'harpy_owner'
       AND p_owner_key IN ('billing', 'analytics')
       AND EXISTS (
            SELECT 1
            FROM platform.tenancy_authority_reconcile_scopes AS scope
            WHERE scope.backend_pid = pg_catalog.pg_backend_pid()
              AND scope.transaction_id = pg_catalog.pg_current_xact_id()
              AND scope.owner_key = p_owner_key
       );
END;
$$;


ALTER FUNCTION platform.tenancy_authority_reconcile_scope_assert_v1(p_owner_key text) OWNER TO harpy_owner;

--
-- Name: tenancy_authority_scope_commit_guard_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_authority_scope_commit_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM platform.tenancy_authority_reconcile_scopes AS scope
        WHERE scope.backend_pid = NEW.backend_pid
          AND scope.transaction_id = NEW.transaction_id
          AND scope.operation_id = NEW.operation_id
          AND scope.owner_key = NEW.owner_key
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'tenancy authority reconcile scope was not cleared';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION platform.tenancy_authority_scope_commit_guard_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_accept_v1(uuid, uuid, uuid, uuid, text, bigint, text, bytea, uuid, uuid, uuid, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_accept_v1(p_environment_id uuid, p_control_tenant_id uuid, p_actor_id uuid, p_target_tenant_id uuid, p_kind text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_retention_receipt_id uuid, p_backup_receipt_id uuid, p_contributor_receipt_id uuid, p_evidence_sha256 bytea, p_proof_verified_at timestamp with time zone, p_now timestamp with time zone) RETURNS TABLE(outcome text, operation_id uuid, control_tenant_id uuid, target_tenant_id uuid, kind text, state text, result_revision bigint, replay boolean, created_at timestamp with time zone, updated_at timestamp with time zone, completed_at timestamp with time zone, failure_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.tenancy_customer_lifecycle_operations%ROWTYPE;
    v_tenant platform.tenants%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_environment_id IS NULL OR p_control_tenant_id IS NULL OR
       p_actor_id IS NULL OR p_target_tenant_id IS NULL OR
       p_target_tenant_id=p_control_tenant_id OR
       p_kind NOT IN ('offboard','purge') OR p_expected_revision < 1 OR
       p_idempotency_key IS NULL OR
       p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       p_request_sha256 IS NULL OR pg_catalog.length(p_request_sha256)<>32 OR
       p_now IS NULL OR pg_catalog.abs(EXTRACT(EPOCH FROM
           (pg_catalog.transaction_timestamp()-p_now))) > 300 OR
       (p_kind='offboard' AND (p_retention_receipt_id IS NOT NULL OR
           p_backup_receipt_id IS NOT NULL OR p_contributor_receipt_id IS NOT NULL OR
           p_evidence_sha256 IS NOT NULL OR p_proof_verified_at IS NOT NULL)) OR
       (p_kind='purge' AND (p_retention_receipt_id IS NULL OR
           p_backup_receipt_id IS NULL OR p_contributor_receipt_id IS NULL OR
           p_evidence_sha256 IS NULL OR pg_catalog.length(p_evidence_sha256)<>32 OR
           p_proof_verified_at IS NULL OR p_proof_verified_at>p_now OR
           p_now-p_proof_verified_at>INTERVAL '24 hours')) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Customer tenant lifecycle operation invalid';
    END IF;
    PERFORM 1 FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS control_binding
      ON control_binding.environment_id=policy.environment_id AND
         control_binding.tenant_id=p_control_tenant_id AND
         control_binding.purpose='saas_control'
    WHERE policy.singleton AND policy.environment_id=p_environment_id AND
          policy.deployment_mode='saas';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='SaaS control tenant boundary is required';
    END IF;
    SELECT operation.* INTO v_existing
    FROM platform.tenancy_customer_lifecycle_operations AS operation
    WHERE operation.control_tenant_id=p_control_tenant_id AND
          operation.idempotency_key=p_idempotency_key;
    IF FOUND THEN
        IF v_existing.request_sha256<>p_request_sha256 OR
           v_existing.kind<>p_kind OR
           v_existing.target_tenant_id<>p_target_tenant_id OR
           v_existing.expected_revision<>p_expected_revision OR
           v_existing.requested_by_actor_id<>p_actor_id THEN
            RETURN QUERY SELECT 'idempotency_conflict',NULL::uuid,NULL::uuid,
                NULL::uuid,NULL::text,NULL::text,NULL::bigint,NULL::boolean,
                NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::text;
        ELSE
            RETURN QUERY SELECT 'replay',v_existing.operation_id,
                v_existing.control_tenant_id,v_existing.target_tenant_id,
                v_existing.kind,v_existing.state,v_existing.result_revision,true,
                v_existing.created_at,v_existing.updated_at,
                v_existing.completed_at,v_existing.failure_code;
        END IF;
        RETURN;
    END IF;
    SELECT tenant.* INTO v_tenant
    FROM platform.tenancy_tenant_bindings AS binding
    JOIN platform.tenants AS tenant ON tenant.id=binding.tenant_id
    WHERE binding.environment_id=p_environment_id AND
          binding.tenant_id=p_target_tenant_id AND binding.purpose='saas_customer'
    FOR UPDATE OF tenant;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'not_found',NULL::uuid,NULL::uuid,NULL::uuid,
            NULL::text,NULL::text,NULL::bigint,NULL::boolean,NULL::timestamptz,
            NULL::timestamptz,NULL::timestamptz,NULL::text;
        RETURN;
    END IF;
    IF v_tenant.lifecycle_revision<>p_expected_revision THEN
        RETURN QUERY SELECT 'revision_conflict',NULL::uuid,NULL::uuid,NULL::uuid,
            NULL::text,NULL::text,NULL::bigint,NULL::boolean,NULL::timestamptz,
            NULL::timestamptz,NULL::timestamptz,NULL::text;
        RETURN;
    END IF;
    IF (p_kind='offboard' AND (v_tenant.deleted_at IS NOT NULL OR
            v_tenant.offboarded_at IS NOT NULL OR v_tenant.purged_at IS NOT NULL)) OR
       (p_kind='purge' AND (v_tenant.deleted_at IS NULL OR
            v_tenant.offboarded_at IS NULL OR v_tenant.purged_at IS NOT NULL)) THEN
        RETURN QUERY SELECT 'state_conflict',NULL::uuid,NULL::uuid,NULL::uuid,
            NULL::text,NULL::text,NULL::bigint,NULL::boolean,NULL::timestamptz,
            NULL::timestamptz,NULL::timestamptz,NULL::text;
        RETURN;
    END IF;
    INSERT INTO platform.tenancy_customer_lifecycle_operations(
        environment_id,control_tenant_id,target_tenant_id,kind,state,
        idempotency_key,request_sha256,expected_revision,result_revision,
        requested_by_actor_id,retention_receipt_id,backup_receipt_id,
        contributor_receipt_id,evidence_sha256,proof_verified_at,
        created_at,updated_at
    ) VALUES (p_environment_id,p_control_tenant_id,p_target_tenant_id,p_kind,
        'REQUESTED',p_idempotency_key,p_request_sha256,p_expected_revision,
        p_expected_revision,p_actor_id,p_retention_receipt_id,p_backup_receipt_id,
        p_contributor_receipt_id,p_evidence_sha256,p_proof_verified_at,p_now,p_now)
    RETURNING * INTO v_existing;
    RETURN QUERY SELECT 'accepted',v_existing.operation_id,
        v_existing.control_tenant_id,v_existing.target_tenant_id,
        v_existing.kind,v_existing.state,v_existing.result_revision,false,
        v_existing.created_at,v_existing.updated_at,
        v_existing.completed_at,v_existing.failure_code;
END;
$_$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_accept_v1(p_environment_id uuid, p_control_tenant_id uuid, p_actor_id uuid, p_target_tenant_id uuid, p_kind text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_retention_receipt_id uuid, p_backup_receipt_id uuid, p_contributor_receipt_id uuid, p_evidence_sha256 bytea, p_proof_verified_at timestamp with time zone, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_claim_v1(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_claim_v1(p_worker_id uuid, p_now timestamp with time zone, p_lease_seconds integer) RETURNS TABLE(operation_id uuid, control_tenant_id uuid, target_tenant_id uuid, kind text, state text, result_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, completed_at timestamp with time zone, failure_code text, schema_name text, retention_receipt_id uuid, backup_receipt_id uuid, contributor_receipt_id uuid, evidence_sha256 bytea, proof_verified_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_worker_id IS NULL OR
       p_now IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 600 OR
       pg_catalog.abs(EXTRACT(EPOCH FROM
           (pg_catalog.transaction_timestamp()-p_now))) > 300 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Customer tenant lifecycle claim denied';
    END IF;
    SELECT operation.operation_id INTO v_operation_id
    FROM platform.tenancy_customer_lifecycle_operations AS operation
    WHERE operation.state='REQUESTED' OR
          (operation.state='RUNNING' AND operation.leased_until<p_now)
    ORDER BY operation.created_at,operation.operation_id
    FOR UPDATE SKIP LOCKED LIMIT 1;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    UPDATE platform.tenancy_customer_lifecycle_operations AS operation SET
        state='RUNNING',worker_id=p_worker_id,
        leased_until=p_now+pg_catalog.make_interval(secs=>p_lease_seconds),
        attempt_count=operation.attempt_count+1,updated_at=p_now,
        failure_code=NULL,completed_at=NULL
    WHERE operation.operation_id=v_operation_id;
    RETURN QUERY SELECT operation.operation_id,operation.control_tenant_id,
        operation.target_tenant_id,operation.kind,operation.state,
        operation.result_revision,operation.created_at,operation.updated_at,
        operation.completed_at,operation.failure_code,tenant.schema_name::text,
        operation.retention_receipt_id,operation.backup_receipt_id,
        operation.contributor_receipt_id,operation.evidence_sha256,
        operation.proof_verified_at
    FROM platform.tenancy_customer_lifecycle_operations AS operation
    JOIN platform.tenants AS tenant ON tenant.id=operation.target_tenant_id
    WHERE operation.operation_id=v_operation_id;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_claim_v1(p_worker_id uuid, p_now timestamp with time zone, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_complete_offboard_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_complete_offboard_v1(p_operation_id uuid, p_worker_id uuid, p_now timestamp with time zone) RETURNS TABLE(operation_id uuid, control_tenant_id uuid, target_tenant_id uuid, kind text, state text, result_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, completed_at timestamp with time zone, failure_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.tenancy_customer_lifecycle_operations%ROWTYPE;
    v_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_operation_id IS NULL OR p_worker_id IS NULL OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Customer tenant offboard completion denied';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.tenancy_customer_lifecycle_operations AS operation
    WHERE operation.operation_id=p_operation_id FOR UPDATE;
    IF NOT FOUND OR v_operation.kind<>'offboard' OR
       v_operation.worker_id IS DISTINCT FROM p_worker_id OR
       v_operation.state NOT IN ('RUNNING','SUCCEEDED') THEN
        RETURN;
    END IF;
    IF v_operation.state='SUCCEEDED' THEN
        RETURN QUERY SELECT v_operation.operation_id,v_operation.control_tenant_id,
            v_operation.target_tenant_id,v_operation.kind,v_operation.state,
            v_operation.result_revision,v_operation.created_at,v_operation.updated_at,
            v_operation.completed_at,v_operation.failure_code;
        RETURN;
    END IF;
    IF v_operation.leased_until<p_now THEN
        RETURN;
    END IF;
    UPDATE platform.tenants AS tenant SET status='SUSPENDED',deleted_at=p_now,
        offboarded_at=p_now,lifecycle_revision=tenant.lifecycle_revision+1,
        updated_at=p_now
    WHERE tenant.id=v_operation.target_tenant_id AND tenant.deleted_at IS NULL AND
          tenant.offboarded_at IS NULL AND tenant.purged_at IS NULL AND
          tenant.lifecycle_revision=v_operation.expected_revision
    RETURNING tenant.lifecycle_revision INTO v_revision;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    UPDATE platform.tenancy_customer_lifecycle_operations AS operation SET
        state='SUCCEEDED',result_revision=v_revision,updated_at=p_now,
        completed_at=p_now,failure_code=NULL
    WHERE operation.operation_id=p_operation_id RETURNING operation.* INTO v_operation;
    RETURN QUERY SELECT v_operation.operation_id,v_operation.control_tenant_id,
        v_operation.target_tenant_id,v_operation.kind,v_operation.state,
        v_operation.result_revision,v_operation.created_at,v_operation.updated_at,
        v_operation.completed_at,v_operation.failure_code;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_complete_offboard_v1(p_operation_id uuid, p_worker_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_complete_purge_v1(uuid, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_complete_purge_v1(p_operation_id uuid, p_worker_id uuid, p_executor_receipt_id uuid, p_executor_receipt_sha256 bytea, p_now timestamp with time zone) RETURNS TABLE(operation_id uuid, control_tenant_id uuid, target_tenant_id uuid, kind text, state text, result_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, completed_at timestamp with time zone, failure_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.tenancy_customer_lifecycle_operations%ROWTYPE;
    v_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_operation_id IS NULL OR p_worker_id IS NULL OR
       p_executor_receipt_id IS NULL OR p_executor_receipt_sha256 IS NULL OR
       pg_catalog.length(p_executor_receipt_sha256)<>32 OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Customer tenant purge completion denied';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.tenancy_customer_lifecycle_operations AS operation
    WHERE operation.operation_id=p_operation_id FOR UPDATE;
    IF NOT FOUND OR v_operation.kind<>'purge' OR
       v_operation.worker_id IS DISTINCT FROM p_worker_id OR
       v_operation.state NOT IN ('RUNNING','SUCCEEDED') THEN
        RETURN;
    END IF;
    IF v_operation.state='SUCCEEDED' THEN
        IF v_operation.executor_receipt_id IS DISTINCT FROM p_executor_receipt_id OR
           v_operation.executor_receipt_sha256<>p_executor_receipt_sha256 THEN
            RETURN;
        END IF;
        RETURN QUERY SELECT v_operation.operation_id,v_operation.control_tenant_id,
            v_operation.target_tenant_id,v_operation.kind,v_operation.state,
            v_operation.result_revision,v_operation.created_at,v_operation.updated_at,
            v_operation.completed_at,v_operation.failure_code;
        RETURN;
    END IF;
    IF v_operation.leased_until<p_now OR v_operation.proof_verified_at IS NULL OR
       p_now-v_operation.proof_verified_at>INTERVAL '24 hours' THEN
        RETURN;
    END IF;
    UPDATE platform.tenants AS tenant SET purged_at=p_now,
        lifecycle_revision=tenant.lifecycle_revision+1,updated_at=p_now
    WHERE tenant.id=v_operation.target_tenant_id AND tenant.deleted_at IS NOT NULL AND
          tenant.offboarded_at IS NOT NULL AND tenant.purged_at IS NULL AND
          tenant.lifecycle_revision=v_operation.expected_revision
    RETURNING tenant.lifecycle_revision INTO v_revision;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    UPDATE platform.tenancy_customer_lifecycle_operations AS operation SET
        state='SUCCEEDED',result_revision=v_revision,updated_at=p_now,
        completed_at=p_now,executor_receipt_id=p_executor_receipt_id,
        executor_receipt_sha256=p_executor_receipt_sha256,failure_code=NULL
    WHERE operation.operation_id=p_operation_id RETURNING operation.* INTO v_operation;
    RETURN QUERY SELECT v_operation.operation_id,v_operation.control_tenant_id,
        v_operation.target_tenant_id,v_operation.kind,v_operation.state,
        v_operation.result_revision,v_operation.created_at,v_operation.updated_at,
        v_operation.completed_at,v_operation.failure_code;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_complete_purge_v1(p_operation_id uuid, p_worker_id uuid, p_executor_receipt_id uuid, p_executor_receipt_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_fail_v1(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_fail_v1(p_operation_id uuid, p_worker_id uuid, p_failure_code text, p_now timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_operation_id IS NULL OR p_worker_id IS NULL OR p_failure_code IS NULL OR
       p_failure_code !~ '^[A-Z0-9_]{3,64}$' OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Customer tenant lifecycle failure record denied';
    END IF;
    UPDATE platform.tenancy_customer_lifecycle_operations AS operation SET
        state=CASE WHEN p_failure_code='PURGE_EXECUTION_FAILED'
                   THEN 'UNKNOWN' ELSE 'FAILED' END,
        failure_code=p_failure_code,updated_at=p_now,completed_at=p_now
    WHERE operation.operation_id=p_operation_id AND operation.state='RUNNING' AND
          operation.worker_id=p_worker_id AND operation.leased_until>=p_now;
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_fail_v1(p_operation_id uuid, p_worker_id uuid, p_failure_code text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_get_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_get_v1(p_environment_id uuid, p_target_tenant_id uuid) RETURNS TABLE(id uuid, name text, slug text, status text, lifecycle_revision bigint, settings_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, offboarded_at timestamp with time zone, purged_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_environment_id IS NULL OR p_target_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Customer tenant lifecycle read denied';
    END IF;
    RETURN QUERY
    SELECT tenant.id,tenant.name::text,tenant.slug::text,tenant.status::text,
           tenant.lifecycle_revision,tenant.settings_revision,
           tenant.created_at,tenant.updated_at,
           tenant.offboarded_at,tenant.purged_at
    FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id=policy.environment_id AND
         binding.purpose='saas_customer' AND
         binding.tenant_id=p_target_tenant_id
    JOIN platform.tenants AS tenant ON tenant.id=binding.tenant_id
    WHERE policy.singleton AND policy.environment_id=p_environment_id AND
          policy.deployment_mode='saas';
END;
$$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_get_v1(p_environment_id uuid, p_target_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_list_v1(uuid, integer, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_list_v1(p_environment_id uuid, p_limit integer, p_after uuid) RETURNS TABLE(document jsonb, next_cursor uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_environment_id IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Customer tenant lifecycle list denied';
    END IF;
    PERFORM 1 FROM platform.tenancy_deployment_policy AS policy
    WHERE policy.singleton AND policy.environment_id=p_environment_id AND
          policy.deployment_mode='saas';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='SaaS deployment policy is required';
    END IF;
    RETURN QUERY
    WITH candidate AS (
        SELECT tenant.id,tenant.name::text,tenant.slug::text,tenant.status::text,
               tenant.lifecycle_revision,tenant.settings_revision,
               tenant.created_at,tenant.updated_at,
               tenant.offboarded_at,tenant.purged_at
        FROM platform.tenancy_tenant_bindings AS binding
        JOIN platform.tenants AS tenant ON tenant.id=binding.tenant_id
        WHERE binding.environment_id=p_environment_id AND
              binding.purpose='saas_customer' AND
              (p_after IS NULL OR tenant.id > p_after)
        ORDER BY tenant.id
        LIMIT p_limit+1
    ), page AS (
        SELECT * FROM candidate ORDER BY id LIMIT p_limit
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'id',page.id,'name',page.name,'slug',page.slug,
               'status',page.status,'revision',page.lifecycle_revision,
               'settings_revision',page.settings_revision,
               'created_at',page.created_at,'updated_at',page.updated_at,
               'offboarded_at',page.offboarded_at,'purged_at',page.purged_at
           ) ORDER BY page.id),'[]'::jsonb),
           CASE WHEN (SELECT pg_catalog.count(*) FROM candidate)>p_limit
                THEN (SELECT cursor_page.id FROM page AS cursor_page
                      ORDER BY cursor_page.id DESC LIMIT 1)
                ELSE NULL::uuid END
    FROM page;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_list_v1(p_environment_id uuid, p_limit integer, p_after uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_mutate_v1(uuid, uuid, uuid, uuid, text, text, bigint, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_mutate_v1(p_environment_id uuid, p_control_tenant_id uuid, p_actor_id uuid, p_target_tenant_id uuid, p_kind text, p_name text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_now timestamp with time zone) RETURNS TABLE(outcome text, replay boolean, id uuid, name text, slug text, status text, lifecycle_revision bigint, settings_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, offboarded_at timestamp with time zone, purged_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_tenant platform.tenants%ROWTYPE;
    v_digest bytea;
    v_kind text;
    v_expected bigint;
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_environment_id IS NULL OR p_control_tenant_id IS NULL OR
       p_actor_id IS NULL OR p_target_tenant_id IS NULL OR
       p_target_tenant_id=p_control_tenant_id OR
       p_kind NOT IN ('update','suspend','reactivate') OR
       p_expected_revision < 1 OR p_idempotency_key IS NULL OR
       p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       p_request_sha256 IS NULL OR pg_catalog.length(p_request_sha256)<>32 OR
       p_now IS NULL OR
       pg_catalog.abs(EXTRACT(EPOCH FROM
           (pg_catalog.transaction_timestamp()-p_now))) > 300 OR
       (p_kind='update' AND (p_name IS NULL OR p_name<>pg_catalog.btrim(p_name) OR
           pg_catalog.char_length(p_name) NOT BETWEEN 1 AND 255)) OR
       (p_kind<>'update' AND p_name IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Customer tenant lifecycle mutation invalid';
    END IF;
    PERFORM 1 FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS control_binding
      ON control_binding.environment_id=policy.environment_id AND
         control_binding.tenant_id=p_control_tenant_id AND
         control_binding.purpose='saas_control'
    WHERE policy.singleton AND policy.environment_id=p_environment_id AND
          policy.deployment_mode='saas';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='SaaS control tenant boundary is required';
    END IF;
    SELECT receipt.request_sha256,receipt.kind,receipt.expected_revision,
           receipt.result_document
      INTO v_digest,v_kind,v_expected,v_document
    FROM platform.tenancy_customer_lifecycle_receipts AS receipt
    WHERE receipt.tenant_id=p_target_tenant_id AND
          receipt.idempotency_key=p_idempotency_key;
    IF FOUND THEN
        IF v_digest<>p_request_sha256 OR v_kind<>p_kind OR
           v_expected<>p_expected_revision THEN
            RETURN QUERY SELECT 'idempotency_conflict',false,NULL::uuid,
                NULL::text,NULL::text,NULL::text,NULL::bigint,NULL::bigint,
                NULL::timestamptz,NULL::timestamptz,NULL::timestamptz,NULL::timestamptz;
        ELSE
            RETURN QUERY SELECT 'replay',true,(v_document->>'id')::uuid,
                v_document->>'name',v_document->>'slug',v_document->>'status',
                (v_document->>'revision')::bigint,
                (v_document->>'settings_revision')::bigint,
                (v_document->>'created_at')::timestamptz,
                (v_document->>'updated_at')::timestamptz,
                (v_document->>'offboarded_at')::timestamptz,
                (v_document->>'purged_at')::timestamptz;
        END IF;
        RETURN;
    END IF;
    SELECT tenant.* INTO v_tenant
    FROM platform.tenancy_tenant_bindings AS binding
    JOIN platform.tenants AS tenant ON tenant.id=binding.tenant_id
    WHERE binding.environment_id=p_environment_id AND
          binding.tenant_id=p_target_tenant_id AND binding.purpose='saas_customer'
    FOR UPDATE OF tenant;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 'not_found',false,NULL::uuid,NULL::text,NULL::text,
            NULL::text,NULL::bigint,NULL::bigint,NULL::timestamptz,
            NULL::timestamptz,NULL::timestamptz,NULL::timestamptz;
        RETURN;
    END IF;
    IF v_tenant.lifecycle_revision<>p_expected_revision THEN
        RETURN QUERY SELECT 'revision_conflict',false,NULL::uuid,NULL::text,
            NULL::text,NULL::text,NULL::bigint,NULL::bigint,NULL::timestamptz,
            NULL::timestamptz,NULL::timestamptz,NULL::timestamptz;
        RETURN;
    END IF;
    IF v_tenant.deleted_at IS NOT NULL OR v_tenant.purged_at IS NOT NULL OR
       (p_kind='suspend' AND v_tenant.status NOT IN ('ACTIVE','TRIAL')) OR
       (p_kind='reactivate' AND v_tenant.status<>'SUSPENDED') THEN
        RETURN QUERY SELECT 'state_conflict',false,NULL::uuid,NULL::text,
            NULL::text,NULL::text,NULL::bigint,NULL::bigint,NULL::timestamptz,
            NULL::timestamptz,NULL::timestamptz,NULL::timestamptz;
        RETURN;
    END IF;
    UPDATE platform.tenants AS tenant SET
        name=CASE WHEN p_kind='update' THEN p_name ELSE tenant.name END,
        status=CASE p_kind WHEN 'suspend' THEN 'SUSPENDED'
                           WHEN 'reactivate' THEN 'ACTIVE' ELSE tenant.status END,
        lifecycle_revision=tenant.lifecycle_revision+1,
        settings_revision=tenant.settings_revision+
            CASE WHEN p_kind='update' THEN 1 ELSE 0 END,
        updated_at=p_now
    WHERE tenant.id=p_target_tenant_id RETURNING tenant.* INTO v_tenant;
    v_document:=pg_catalog.jsonb_build_object(
        'id',v_tenant.id,'name',v_tenant.name,'slug',v_tenant.slug,
        'status',v_tenant.status,'revision',v_tenant.lifecycle_revision,
        'settings_revision',v_tenant.settings_revision,
        'created_at',v_tenant.created_at,'updated_at',v_tenant.updated_at,
        'offboarded_at',v_tenant.offboarded_at,'purged_at',v_tenant.purged_at);
    INSERT INTO platform.tenancy_customer_lifecycle_receipts(
        tenant_id,control_tenant_id,actor_id,kind,idempotency_key,request_sha256,
        expected_revision,result_revision,result_document,created_at
    ) VALUES (p_target_tenant_id,p_control_tenant_id,p_actor_id,p_kind,
        p_idempotency_key,p_request_sha256,p_expected_revision,
        v_tenant.lifecycle_revision,v_document,p_now);
    RETURN QUERY SELECT 'applied',false,v_tenant.id,v_tenant.name::text,
        v_tenant.slug::text,v_tenant.status::text,v_tenant.lifecycle_revision,
        v_tenant.settings_revision,v_tenant.created_at,v_tenant.updated_at,
        v_tenant.offboarded_at,v_tenant.purged_at;
END;
$_$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_mutate_v1(p_environment_id uuid, p_control_tenant_id uuid, p_actor_id uuid, p_target_tenant_id uuid, p_kind text, p_name text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_lifecycle_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_lifecycle_read_v1(p_control_tenant_id uuid, p_operation_id uuid) RETURNS TABLE(operation_id uuid, control_tenant_id uuid, target_tenant_id uuid, kind text, state text, result_revision bigint, replay boolean, created_at timestamp with time zone, updated_at timestamp with time zone, completed_at timestamp with time zone, failure_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_control_tenant_id IS NULL OR p_operation_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Customer tenant lifecycle operation read denied';
    END IF;
    RETURN QUERY SELECT operation.operation_id,operation.control_tenant_id,
        operation.target_tenant_id,operation.kind,operation.state,
        operation.result_revision,false,operation.created_at,operation.updated_at,
        operation.completed_at,operation.failure_code
    FROM platform.tenancy_customer_lifecycle_operations AS operation
    WHERE operation.operation_id=p_operation_id AND
          operation.control_tenant_id=p_control_tenant_id;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_lifecycle_read_v1(p_control_tenant_id uuid, p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_provision_accept_v1(uuid, uuid, text, text, text, text, text, text, uuid, name, text, uuid, uuid, uuid, uuid, uuid, bigint, text, timestamp with time zone, bigint, text, bigint, text, uuid, text, uuid, bigint, text, text, text, timestamp with time zone, uuid, uuid, text, text, text, text, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_provision_accept_v1(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_idempotency_key text, p_request_sha256 text, p_manifest_sha256 text, p_step_plan_sha256 text, p_deployment_mode text, p_tenant_id uuid, p_schema_name name, p_binding_purpose text, p_first_user_id uuid, p_root_organization_id uuid, p_protected_admin_binding_id uuid, p_instance_owner_binding_id uuid, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_registry_binding_id uuid, p_authority_scope_kind text, p_authority_scope_id uuid, p_authority_generation bigint, p_authority_previous_head_sha256 text, p_authority_state_sha256 text, p_authority_proposal_sha256 text, p_created_at timestamp with time zone, p_control_tenant_id uuid, p_requested_by_subject_id uuid, p_customer_name text, p_tenant_slug text, p_first_admin_display_name text, p_first_admin_email text, p_job_id uuid) RETURNS TABLE(operation_id uuid, tenant_id uuid, requested_by_subject_id uuid, state text, setup_delivery_state text, failure_code text, failure_retryable boolean, correlation_id text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_ready platform.tenancy_tenant_migration_executor_readiness%ROWTYPE;
    v_request platform.tenancy_customer_provisioning_requests%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_operation_kind <> 'saas_customer_tenant_provision'
       OR p_deployment_mode <> 'saas' OR p_binding_purpose <> 'saas_customer'
       OR p_instance_owner_binding_id IS NOT NULL
       OR p_requested_by_subject_id IS NULL OR p_control_tenant_id IS NULL
       OR p_job_id IS NULL OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='customer provisioning acceptance is invalid';
    END IF;
    PERFORM 1
    FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id=policy.environment_id
     AND binding.purpose='saas_control'
    JOIN platform.tenants AS tenant ON tenant.id=binding.tenant_id
    WHERE policy.environment_id=p_environment_id
      AND policy.deployment_mode='saas'
      AND binding.tenant_id=p_control_tenant_id
      AND tenant.status='ACTIVE' AND tenant.deleted_at IS NULL
    FOR SHARE OF policy,binding,tenant;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='active SaaS control tenant is required';
    END IF;
    SELECT ready.* INTO v_ready
    FROM platform.tenancy_tenant_migration_executor_readiness AS ready
    WHERE ready.environment_id=p_environment_id
      AND ready.deployment_mode='saas' AND ready.state='active'
      AND ready.ready_until > pg_catalog.clock_timestamp()
    ORDER BY ready.ready_until DESC,ready.release_id DESC
    LIMIT 1 FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='tenant migration executor is not claim ready';
    END IF;
    PERFORM 1 FROM platform.tenancy_onboarding_accept_v1(
        p_operation_id,p_environment_id,p_operation_kind,p_idempotency_key,
        p_request_sha256,p_manifest_sha256,p_step_plan_sha256,p_deployment_mode,
        p_tenant_id,p_schema_name,p_binding_purpose,p_first_user_id,
        p_root_organization_id,p_protected_admin_binding_id,
        p_instance_owner_binding_id,p_offering_version_id,p_offering_revision,
        p_offering_sha256,p_offering_effective_at,p_offering_source_sequence,
        p_offering_source_sha256,p_recovery_signing_generation,
        p_recovery_trust_bundle_sha256,p_registry_binding_id,
        p_authority_scope_kind,p_authority_scope_id,p_authority_generation,
        p_authority_previous_head_sha256,p_authority_state_sha256,
        p_authority_proposal_sha256,p_created_at
    );
    INSERT INTO platform.tenancy_customer_provisioning_requests (
        operation_id,control_tenant_id,requested_by_subject_id,customer_name,
        tenant_slug,first_admin_display_name,first_admin_email,
        request_sha256,created_at
    ) VALUES (
        p_operation_id,p_control_tenant_id,p_requested_by_subject_id,p_customer_name,
        p_tenant_slug,p_first_admin_display_name,p_first_admin_email,
        p_request_sha256,p_created_at
    ) ON CONFLICT (operation_id) DO NOTHING;
    SELECT request.* INTO STRICT v_request
    FROM platform.tenancy_customer_provisioning_requests AS request
    WHERE request.operation_id=p_operation_id FOR SHARE;
    IF v_request.control_tenant_id IS DISTINCT FROM p_control_tenant_id
       OR v_request.requested_by_subject_id IS DISTINCT FROM p_requested_by_subject_id
       OR v_request.customer_name IS DISTINCT FROM p_customer_name
       OR v_request.tenant_slug IS DISTINCT FROM p_tenant_slug
       OR v_request.first_admin_display_name IS DISTINCT FROM p_first_admin_display_name
       OR v_request.first_admin_email IS DISTINCT FROM p_first_admin_email
       OR v_request.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='customer provisioning idempotency conflicts';
    END IF;
    INSERT INTO platform.tenancy_customer_provisioning_outcomes (
        operation_id,setup_delivery_state,revision,updated_at
    ) VALUES (p_operation_id,'pending',1,p_created_at)
    ON CONFLICT (operation_id) DO NOTHING;
    PERFORM 1 FROM platform.tenancy_tenant_migration_enqueue_v1(
        p_job_id,p_operation_id,v_ready.release_id,v_ready.runtime_generation,
        v_ready.database_generation,v_ready.migration_manifest_sha256
    );
    RETURN QUERY SELECT operation.operation_id,operation.tenant_id,
        request.requested_by_subject_id,operation.state,outcome.setup_delivery_state,
        outcome.failure_code,outcome.failure_retryable,outcome.correlation_id::text,
        operation.created_at,operation.updated_at
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.tenancy_customer_provisioning_requests AS request
      ON request.operation_id=operation.operation_id
    JOIN platform.tenancy_customer_provisioning_outcomes AS outcome
      ON outcome.operation_id=operation.operation_id
    WHERE operation.operation_id=p_operation_id;
END;
$_$;


ALTER FUNCTION platform.tenancy_customer_provision_accept_v1(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_idempotency_key text, p_request_sha256 text, p_manifest_sha256 text, p_step_plan_sha256 text, p_deployment_mode text, p_tenant_id uuid, p_schema_name name, p_binding_purpose text, p_first_user_id uuid, p_root_organization_id uuid, p_protected_admin_binding_id uuid, p_instance_owner_binding_id uuid, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_registry_binding_id uuid, p_authority_scope_kind text, p_authority_scope_id uuid, p_authority_generation bigint, p_authority_previous_head_sha256 text, p_authority_state_sha256 text, p_authority_proposal_sha256 text, p_created_at timestamp with time zone, p_control_tenant_id uuid, p_requested_by_subject_id uuid, p_customer_name text, p_tenant_slug text, p_first_admin_display_name text, p_first_admin_email text, p_job_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_provision_claim_v1(uuid, text, text, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_provision_claim_v1(p_attempt_id uuid, p_lease_owner text, p_lease_token_sha256 text, p_lease_seconds integer) RETURNS TABLE(operation_id uuid, environment_id uuid, operation_kind text, idempotency_key text, request_sha256 text, manifest_sha256 text, step_plan_sha256 text, deployment_mode text, tenant_id uuid, schema_name text, binding_purpose text, first_user_id uuid, root_organization_id uuid, protected_admin_binding_id uuid, instance_owner_binding_id uuid, offering_version_id uuid, offering_revision bigint, offering_sha256 text, offering_effective_at timestamp with time zone, offering_source_sequence bigint, offering_source_sha256 text, recovery_signing_generation bigint, recovery_trust_bundle_sha256 text, registry_binding_id uuid, authority_scope_kind text, authority_scope_id uuid, authority_generation bigint, authority_previous_head_sha256 text, authority_state_sha256 text, authority_proposal_sha256 text, created_at timestamp with time zone, customer_name text, tenant_slug text, first_admin_display_name text, first_admin_email text, state text, revision bigint, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_original_state text;
    v_revision bigint;
    v_lease_until timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_attempt_id IS NULL OR pg_catalog.octet_length(p_lease_owner) NOT BETWEEN 1 AND 128
       OR p_lease_token_sha256 !~ '^[0-9a-f]{64}$'
       OR p_lease_seconds NOT BETWEEN 1 AND 300 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer provisioning worker claim is denied';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    LEFT JOIN platform.tenancy_onboarding_leases AS lease
      ON lease.operation_id=operation.operation_id
    WHERE operation.operation_kind='saas_customer_tenant_provision'
      AND operation.deployment_mode='saas'
      AND operation.state IN (
          'migration_ready','authority_pending','authority_acknowledged'
      )
      AND (lease.operation_id IS NULL
           OR lease.lease_until <= pg_catalog.statement_timestamp())
    ORDER BY operation.created_at,operation.operation_id
    LIMIT 1 FOR UPDATE OF operation SKIP LOCKED;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    v_original_state:=v_operation.state;
    SELECT claimed.revision,claimed.lease_until
    INTO STRICT v_revision,v_lease_until
    FROM platform.tenancy_onboarding_claim_v2(
        v_operation.operation_id,p_attempt_id,p_lease_owner,
        p_lease_token_sha256,v_operation.revision,p_lease_seconds
    ) AS claimed;
    IF v_original_state='migration_ready' THEN
        UPDATE platform.tenancy_onboarding_operations AS operation
        SET state='authority_pending',revision=v_revision+1,
            updated_at=pg_catalog.statement_timestamp()
        WHERE operation.operation_id=v_operation.operation_id
          AND operation.state='migration_ready' AND operation.revision=v_revision;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='customer authority transition conflicts';
        END IF;
        v_revision:=v_revision+1;
        UPDATE platform.tenancy_onboarding_leases AS lease
        SET revision=v_revision,heartbeat_at=pg_catalog.statement_timestamp()
        WHERE lease.operation_id=v_operation.operation_id
          AND lease.attempt_id=p_attempt_id;
    END IF;
    RETURN QUERY
    SELECT operation.operation_id,operation.environment_id,
        operation.operation_kind,operation.idempotency_key,
        operation.request_sha256,operation.manifest_sha256,
        operation.step_plan_sha256,operation.deployment_mode,
        operation.tenant_id,operation.schema_name::text,
        operation.binding_purpose,operation.first_user_id,
        operation.root_organization_id,operation.protected_admin_binding_id,
        operation.instance_owner_binding_id,operation.offering_version_id,
        operation.offering_revision,operation.offering_sha256,
        operation.offering_effective_at,operation.offering_source_sequence,
        operation.offering_source_sha256,operation.recovery_signing_generation,
        operation.recovery_trust_bundle_sha256,operation.registry_binding_id,
        operation.authority_scope_kind,operation.authority_scope_id,
        operation.authority_generation,operation.authority_previous_head_sha256,
        operation.authority_state_sha256,operation.authority_proposal_sha256,
        operation.created_at,request.customer_name,request.tenant_slug,
        request.first_admin_display_name,request.first_admin_email,
        operation.state,operation.revision,v_lease_until
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.tenancy_customer_provisioning_requests AS request
      ON request.operation_id=operation.operation_id
    WHERE operation.operation_id=v_operation.operation_id;
END;
$_$;


ALTER FUNCTION platform.tenancy_customer_provision_claim_v1(p_attempt_id uuid, p_lease_owner text, p_lease_token_sha256 text, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_provision_read_v1(uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_provision_read_v1(p_operation_id uuid, p_requested_by_subject_id uuid) RETURNS TABLE(operation_id uuid, tenant_id uuid, requested_by_subject_id uuid, state text, setup_delivery_state text, failure_code text, failure_retryable boolean, correlation_id text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_operation_id IS NULL OR p_requested_by_subject_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='customer provisioning read is invalid';
    END IF;
    PERFORM 1 FROM platform.tenancy_deployment_policy AS policy
    WHERE policy.deployment_mode='saas' FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer provisioning mode is denied';
    END IF;
    RETURN QUERY SELECT operation.operation_id,operation.tenant_id,
        request.requested_by_subject_id,operation.state,outcome.setup_delivery_state,
        outcome.failure_code,outcome.failure_retryable,outcome.correlation_id::text,
        operation.created_at,operation.updated_at
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.tenancy_customer_provisioning_requests AS request
      ON request.operation_id=operation.operation_id
    JOIN platform.tenancy_customer_provisioning_outcomes AS outcome
      ON outcome.operation_id=operation.operation_id
    WHERE operation.operation_id=p_operation_id
      AND operation.operation_kind='saas_customer_tenant_provision'
      AND request.requested_by_subject_id=p_requested_by_subject_id;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_provision_read_v1(p_operation_id uuid, p_requested_by_subject_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_setup_accepted_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_setup_accepted_v1(p_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_current text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_artifact_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer setup acceptance denied';
    END IF;
    SELECT outcome.setup_delivery_state INTO v_current
    FROM platform.tenancy_customer_provisioning_outcomes AS outcome
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id=outcome.operation_id
    WHERE operation.operation_id=p_operation_id
      AND operation.tenant_id=p_tenant_id
      AND operation.operation_kind='saas_customer_tenant_provision'
      AND operation.deployment_mode='saas' AND operation.state='succeeded'
      AND outcome.setup_artifact_id=p_artifact_id
    FOR UPDATE OF outcome;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup acceptance conflicts';
    END IF;
    IF v_current='accepted' THEN
        RETURN true;
    END IF;
    IF v_current<>'delivered' THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup must be delivered before acceptance';
    END IF;
    UPDATE platform.tenancy_customer_provisioning_outcomes
    SET setup_delivery_state='accepted',revision=revision+1,
        updated_at=pg_catalog.statement_timestamp()
    WHERE operation_id=p_operation_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_setup_accepted_v1(p_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_setup_artifact_bind_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_setup_artifact_bind_v1(p_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_existing uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_artifact_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer setup artifact binding denied';
    END IF;
    PERFORM 1
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.tenancy_customer_provisioning_requests AS request
      ON request.operation_id=operation.operation_id
    WHERE operation.operation_id=p_operation_id
      AND operation.tenant_id=p_tenant_id
      AND operation.operation_kind='saas_customer_tenant_provision'
      AND operation.deployment_mode='saas'
      AND operation.state='finalizing'
    FOR UPDATE OF operation;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup artifact activation conflicts';
    END IF;
    SELECT outcome.setup_artifact_id INTO v_existing
    FROM platform.tenancy_customer_provisioning_outcomes AS outcome
    WHERE outcome.operation_id=p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_existing IS NOT NULL
       AND v_existing IS DISTINCT FROM p_artifact_id THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='customer setup artifact replay conflicts';
    END IF;
    IF v_existing IS NOT NULL THEN
        RETURN true;
    END IF;
    UPDATE platform.tenancy_customer_provisioning_outcomes
    SET setup_artifact_id=p_artifact_id,revision=revision+1,
        updated_at=pg_catalog.statement_timestamp()
    WHERE operation_id=p_operation_id
      AND setup_delivery_state='pending';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup delivery state conflicts';
    END IF;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_setup_artifact_bind_v1(p_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_setup_delivery_outcome_v1(uuid, uuid, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_setup_delivery_outcome_v1(p_tenant_id uuid, p_artifact_id uuid, p_outcome text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_current text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-worker'
       OR p_tenant_id IS NULL OR p_artifact_id IS NULL
       OR p_outcome NOT IN ('delivered','permanent_failure','outcome_unknown') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer setup delivery outcome denied';
    END IF;
    SELECT outcome.setup_delivery_state INTO v_current
    FROM platform.tenancy_customer_provisioning_outcomes AS outcome
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id=outcome.operation_id
    WHERE operation.tenant_id=p_tenant_id
      AND operation.operation_kind='saas_customer_tenant_provision'
      AND operation.deployment_mode='saas'
      AND outcome.setup_artifact_id=p_artifact_id
    FOR UPDATE OF outcome;
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    IF v_current=p_outcome THEN
        RETURN true;
    END IF;
    IF v_current NOT IN ('pending','reissued') THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup delivery outcome conflicts';
    END IF;
    UPDATE platform.tenancy_customer_provisioning_outcomes
    SET setup_delivery_state=p_outcome,revision=revision+1,
        updated_at=pg_catalog.statement_timestamp()
    WHERE setup_artifact_id=p_artifact_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_setup_delivery_outcome_v1(p_tenant_id uuid, p_artifact_id uuid, p_outcome text) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_setup_reissue_assert_v1(uuid, uuid, uuid, uuid, name); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_setup_reissue_assert_v1(p_operation_id uuid, p_reissue_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid, p_schema_name name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer setup reissue assertion denied';
    END IF;
    RETURN EXISTS (
        SELECT 1
        FROM platform.tenancy_customer_provisioning_outcomes AS outcome
        JOIN platform.tenancy_onboarding_operations AS operation
          ON operation.operation_id=outcome.operation_id
        WHERE operation.operation_id=p_operation_id
          AND operation.tenant_id=p_tenant_id
          AND operation.operation_kind='saas_customer_tenant_provision'
          AND operation.deployment_mode='saas' AND operation.state='succeeded'
          AND operation.schema_name=p_schema_name
          AND outcome.setup_delivery_state='reissued'
          AND outcome.setup_artifact_id=p_artifact_id
          AND outcome.setup_reissue_operation_id=p_reissue_operation_id
    );
END;
$$;


ALTER FUNCTION platform.tenancy_customer_setup_reissue_assert_v1(p_operation_id uuid, p_reissue_operation_id uuid, p_tenant_id uuid, p_artifact_id uuid, p_schema_name name) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_setup_reissue_target_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_setup_reissue_target_v1(p_tenant_id uuid) RETURNS TABLE(operation_id uuid, tenant_id uuid, requested_by_subject_id uuid, state text, setup_delivery_state text, failure_code text, failure_retryable boolean, correlation_id text, created_at timestamp with time zone, updated_at timestamp with time zone, setup_reissue_operation_id uuid, schema_name name, first_user_id uuid, first_admin_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api'
       OR p_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer setup reissue target denied';
    END IF;
    RETURN QUERY
    SELECT operation.operation_id,operation.tenant_id,
        request.requested_by_subject_id,operation.state,
        outcome.setup_delivery_state,outcome.failure_code,
        outcome.failure_retryable,outcome.correlation_id::text,
        operation.created_at,operation.updated_at,
        outcome.setup_reissue_operation_id,operation.schema_name,
        operation.first_user_id,request.first_admin_email
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.tenancy_customer_provisioning_requests AS request
      ON request.operation_id=operation.operation_id
    JOIN platform.tenancy_customer_provisioning_outcomes AS outcome
      ON outcome.operation_id=operation.operation_id
    WHERE operation.tenant_id=p_tenant_id
      AND operation.operation_kind='saas_customer_tenant_provision'
      AND operation.deployment_mode='saas' AND operation.state='succeeded'
      AND outcome.setup_delivery_state IN (
          'permanent_failure','outcome_unknown','reissued'
      );
END;
$$;


ALTER FUNCTION platform.tenancy_customer_setup_reissue_target_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_customer_setup_reissue_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_customer_setup_reissue_v1(p_operation_id uuid, p_reissue_operation_id uuid, p_tenant_id uuid, p_old_artifact_id uuid, p_new_artifact_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_outcome platform.tenancy_customer_provisioning_outcomes%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api'
       OR p_operation_id IS NULL OR p_reissue_operation_id IS NULL
       OR p_tenant_id IS NULL OR p_old_artifact_id IS NULL
       OR p_new_artifact_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='customer setup reissue denied';
    END IF;
    SELECT outcome.* INTO v_outcome
    FROM platform.tenancy_customer_provisioning_outcomes AS outcome
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id=outcome.operation_id
    WHERE operation.operation_id=p_operation_id
      AND operation.tenant_id=p_tenant_id
      AND operation.operation_kind='saas_customer_tenant_provision'
      AND operation.deployment_mode='saas' AND operation.state='succeeded'
    FOR UPDATE OF outcome;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup reissue target conflicts';
    END IF;
    IF v_outcome.setup_delivery_state='reissued'
       AND v_outcome.setup_artifact_id=p_new_artifact_id
       AND v_outcome.setup_reissue_operation_id=p_reissue_operation_id THEN
        RETURN true;
    END IF;
    IF p_old_artifact_id=p_new_artifact_id THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup reissue artifact conflicts';
    END IF;
    IF v_outcome.setup_delivery_state NOT IN (
        'permanent_failure','outcome_unknown'
    ) OR v_outcome.setup_artifact_id IS DISTINCT FROM p_old_artifact_id THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='customer setup reissue state conflicts';
    END IF;
    UPDATE platform.tenancy_customer_provisioning_outcomes
    SET setup_delivery_state='reissued',setup_artifact_id=p_new_artifact_id,
        setup_reissue_operation_id=p_reissue_operation_id,
        revision=revision+1,updated_at=pg_catalog.statement_timestamp()
    WHERE operation_id=p_operation_id;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.tenancy_customer_setup_reissue_v1(p_operation_id uuid, p_reissue_operation_id uuid, p_tenant_id uuid, p_old_artifact_id uuid, p_new_artifact_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_get_deployment_policy_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_get_deployment_policy_v1() RETURNS TABLE(environment_id uuid, deployment_mode text, maximum_customer_tenants bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
        OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501',
            MESSAGE = 'Tenancy deployment policy query denied';
    END IF;
    RETURN QUERY
    SELECT policy.environment_id,
           policy.deployment_mode,
           policy.maximum_customer_tenants,
           policy.created_at
    FROM platform.tenancy_deployment_policy AS policy
    WHERE policy.singleton
    FOR SHARE;
END;
$$;


ALTER FUNCTION platform.tenancy_get_deployment_policy_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_get_primary_tenant_target_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_get_primary_tenant_target_v1() RETURNS TABLE(environment_id uuid, deployment_mode text, tenant_id uuid, purpose text, slug text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
        OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Primary tenant target query denied';
    END IF;
    RETURN QUERY
    SELECT policy.environment_id,
           policy.deployment_mode,
           binding.tenant_id,
           binding.purpose,
           tenant.slug::text
    FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id = policy.environment_id
     AND binding.purpose = CASE policy.deployment_mode
         WHEN 'onpremise' THEN 'onpremise_primary'
         WHEN 'saas' THEN 'saas_control'
     END
    JOIN platform.tenants AS tenant ON tenant.id = binding.tenant_id
    WHERE policy.singleton
    FOR SHARE OF policy, binding, tenant;
END;
$$;


ALTER FUNCTION platform.tenancy_get_primary_tenant_target_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_get_primary_tenant_target_v2(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_get_primary_tenant_target_v2() RETURNS TABLE(environment_id uuid, deployment_mode text, tenant_id uuid, purpose text, slug text, schema_name name, tenant_set_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
        OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Primary tenant target query denied';
    END IF;
    RETURN QUERY
    WITH tenant_set AS (
        SELECT policy.environment_id,
               pg_catalog.sha256(pg_catalog.convert_to(
                   'tenant-set.v1' || COALESCE(pg_catalog.string_agg(
                       '|' || binding.tenant_id::text || '|' ||
                       tenant.schema_name::text,
                       '' ORDER BY binding.tenant_id::text
                   ), ''),
                   'UTF8'
               )) AS digest
        FROM platform.tenancy_deployment_policy AS policy
        JOIN platform.tenancy_tenant_bindings AS binding
          ON binding.environment_id = policy.environment_id
        JOIN platform.tenants AS tenant ON tenant.id = binding.tenant_id
        WHERE policy.singleton
        GROUP BY policy.environment_id
    )
    SELECT policy.environment_id,
           policy.deployment_mode,
           binding.tenant_id,
           binding.purpose,
           tenant.slug::text,
           tenant.schema_name,
           tenant_set.digest
    FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id = policy.environment_id
     AND binding.purpose = CASE policy.deployment_mode
         WHEN 'onpremise' THEN 'onpremise_primary'
         WHEN 'saas' THEN 'saas_control'
     END
    JOIN platform.tenants AS tenant ON tenant.id = binding.tenant_id
    JOIN tenant_set ON tenant_set.environment_id = policy.environment_id
    WHERE policy.singleton
    FOR SHARE OF policy, binding, tenant;
END;
$$;


ALTER FUNCTION platform.tenancy_get_primary_tenant_target_v2() OWNER TO harpy_owner;

--
-- Name: tenancy_get_recovery_target_v1(text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_get_recovery_target_v1(p_purpose text) RETURNS TABLE(environment_id uuid, deployment_mode text, tenant_id uuid, tenant_slug text, schema_name name, tenant_set_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NOT (
        SESSION_USER = 'harpy_backup' AND p_purpose = 'backup'
        OR SESSION_USER = 'harpy_restore' AND p_purpose = 'restore'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenancy recovery target denied';
    END IF;
    RETURN QUERY
    WITH tenant_set AS (
        SELECT policy.environment_id,
               pg_catalog.sha256(pg_catalog.convert_to(
                   'tenant-set.v1' || COALESCE(pg_catalog.string_agg(
                       '|' || binding.tenant_id::text || '|' ||
                       tenant.schema_name,
                       '' ORDER BY binding.tenant_id::text
                   ), ''),
                   'UTF8'
               )) AS digest
        FROM platform.tenancy_deployment_policy AS policy
        JOIN platform.tenancy_tenant_bindings AS binding
          ON binding.environment_id = policy.environment_id
        JOIN platform.tenants AS tenant ON tenant.id = binding.tenant_id
        WHERE policy.singleton AND policy.deployment_mode = 'onpremise'
          AND binding.purpose = 'onpremise_primary'
          AND tenant.status = 'ACTIVE' AND tenant.deleted_at IS NULL
        GROUP BY policy.environment_id
    )
    SELECT policy.environment_id, policy.deployment_mode,
           binding.tenant_id, tenant.slug::text, tenant.schema_name::name,
           tenant_set.digest
    FROM platform.tenancy_deployment_policy AS policy
    JOIN platform.tenancy_tenant_bindings AS binding
      ON binding.environment_id = policy.environment_id
     AND binding.purpose = 'onpremise_primary'
    JOIN platform.tenants AS tenant ON tenant.id = binding.tenant_id
    JOIN tenant_set ON tenant_set.environment_id = policy.environment_id
    WHERE policy.singleton AND policy.deployment_mode = 'onpremise'
      AND tenant.status = 'ACTIVE' AND tenant.deleted_at IS NULL;
END;
$$;


ALTER FUNCTION platform.tenancy_get_recovery_target_v1(p_purpose text) OWNER TO harpy_owner;

--
-- Name: tenancy_guard_customer_lifecycle_operation_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_guard_customer_lifecycle_operation_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' OR OLD.state IN ('SUCCEEDED','FAILED','UNKNOWN') OR
       NEW.operation_id IS DISTINCT FROM OLD.operation_id OR
       NEW.environment_id IS DISTINCT FROM OLD.environment_id OR
       NEW.control_tenant_id IS DISTINCT FROM OLD.control_tenant_id OR
       NEW.target_tenant_id IS DISTINCT FROM OLD.target_tenant_id OR
       NEW.kind IS DISTINCT FROM OLD.kind OR
       NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key OR
       NEW.request_sha256 IS DISTINCT FROM OLD.request_sha256 OR
       NEW.expected_revision IS DISTINCT FROM OLD.expected_revision OR
       NEW.requested_by_actor_id IS DISTINCT FROM OLD.requested_by_actor_id OR
       NEW.retention_receipt_id IS DISTINCT FROM OLD.retention_receipt_id OR
       NEW.backup_receipt_id IS DISTINCT FROM OLD.backup_receipt_id OR
       NEW.contributor_receipt_id IS DISTINCT FROM OLD.contributor_receipt_id OR
       NEW.evidence_sha256 IS DISTINCT FROM OLD.evidence_sha256 OR
       NEW.proof_verified_at IS DISTINCT FROM OLD.proof_verified_at OR
       NEW.created_at IS DISTINCT FROM OLD.created_at OR
       (OLD.state='REQUESTED' AND NEW.state<>'RUNNING') OR
       (OLD.state='RUNNING' AND NEW.state NOT IN
           ('RUNNING','SUCCEEDED','FAILED','UNKNOWN')) OR
       NEW.attempt_count<OLD.attempt_count THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Customer tenant lifecycle operation mutation denied';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.tenancy_guard_customer_lifecycle_operation_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_guard_onboarding_operation_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_guard_onboarding_operation_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'onboarding operation delete is forbidden';
    END IF;
    IF ROW(NEW.operation_id, NEW.environment_id, NEW.operation_kind,
        NEW.idempotency_key, NEW.request_sha256, NEW.manifest_sha256,
        NEW.step_plan_sha256, NEW.deployment_mode, NEW.tenant_id,
        NEW.schema_name, NEW.binding_purpose, NEW.first_user_id,
        NEW.root_organization_id, NEW.protected_admin_binding_id,
        NEW.instance_owner_binding_id, NEW.offering_version_id,
        NEW.offering_revision, NEW.offering_sha256, NEW.offering_effective_at,
        NEW.offering_source_sequence, NEW.offering_source_sha256,
        NEW.recovery_signing_generation, NEW.recovery_trust_bundle_sha256,
        NEW.registry_binding_id, NEW.authority_scope_kind, NEW.authority_scope_id,
        NEW.authority_generation, NEW.authority_previous_head_sha256,
        NEW.authority_state_sha256, NEW.authority_proposal_sha256, NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.operation_id, OLD.environment_id, OLD.operation_kind,
        OLD.idempotency_key, OLD.request_sha256, OLD.manifest_sha256,
        OLD.step_plan_sha256, OLD.deployment_mode, OLD.tenant_id,
        OLD.schema_name, OLD.binding_purpose, OLD.first_user_id,
        OLD.root_organization_id, OLD.protected_admin_binding_id,
        OLD.instance_owner_binding_id, OLD.offering_version_id,
        OLD.offering_revision, OLD.offering_sha256, OLD.offering_effective_at,
        OLD.offering_source_sequence, OLD.offering_source_sha256,
        OLD.recovery_signing_generation, OLD.recovery_trust_bundle_sha256,
        OLD.registry_binding_id, OLD.authority_scope_kind, OLD.authority_scope_id,
        OLD.authority_generation, OLD.authority_previous_head_sha256,
        OLD.authority_state_sha256, OLD.authority_proposal_sha256, OLD.created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'onboarding plan is immutable';
    END IF;
    IF NEW.revision <> OLD.revision + 1 OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'onboarding revision transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.tenancy_guard_onboarding_operation_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_guard_tenant_binding_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_guard_tenant_binding_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    policy_mode text;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'harpy:v2:tenancy-binding:' || NEW.environment_id::text,
            0
        )
    );
    SELECT policy.deployment_mode
    INTO policy_mode
    FROM platform.tenancy_deployment_policy AS policy
    WHERE policy.environment_id = NEW.environment_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'Persisted tenancy deployment policy is required';
    END IF;

    IF policy_mode = 'onpremise' THEN
        IF NEW.purpose IS DISTINCT FROM 'onpremise_primary' THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'On-premise binding purpose is invalid';
        END IF;
        IF EXISTS (
            SELECT 1 FROM platform.tenancy_tenant_bindings AS binding
            WHERE binding.environment_id = NEW.environment_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'On-premise tenant capacity is exhausted';
        END IF;
    ELSIF policy_mode = 'saas' THEN
        IF NEW.purpose = 'saas_control' AND EXISTS (
            SELECT 1 FROM platform.tenancy_tenant_bindings AS binding
            WHERE binding.environment_id = NEW.environment_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'SaaS control binding already exists';
        ELSIF NEW.purpose = 'saas_customer' AND NOT EXISTS (
            SELECT 1 FROM platform.tenancy_tenant_bindings AS binding
            WHERE binding.environment_id = NEW.environment_id
              AND binding.purpose = 'saas_control'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'SaaS control binding is required before customers';
        ELSIF NEW.purpose NOT IN ('saas_control', 'saas_customer') THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'SaaS binding purpose is invalid';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.tenancy_guard_tenant_binding_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_guard_tenant_migration_attempt_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_guard_tenant_migration_attempt_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' OR ROW(
        NEW.job_id, NEW.attempt, NEW.migration_run_id,
        NEW.profile_instance_id, NEW.lease_id, NEW.leased_at
    ) IS DISTINCT FROM ROW(
        OLD.job_id, OLD.attempt, OLD.migration_run_id,
        OLD.profile_instance_id, OLD.lease_id, OLD.leased_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration attempt identity is immutable';
    END IF;
    IF NOT (
        OLD.state = 'running' AND NEW.state = 'running'
            AND NEW.heartbeat_at > OLD.heartbeat_at
            AND NEW.lease_until > OLD.lease_until
        OR OLD.state = 'running' AND NEW.state IN (
            'succeeded', 'failed', 'reconcile_required', 'cleanup_required'
        ) AND NEW.finished_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration attempt transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.tenancy_guard_tenant_migration_attempt_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_guard_tenant_migration_job_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_guard_tenant_migration_job_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_release_changed boolean;
    v_rollforward boolean := false;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF TG_OP = 'DELETE' OR ROW(
        NEW.job_id, NEW.operation_id, NEW.origin, NEW.environment_id,
        NEW.deployment_mode, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.job_id, OLD.operation_id, OLD.origin, OLD.environment_id,
        OLD.deployment_mode, OLD.created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration job identity is immutable';
    END IF;

    v_release_changed := ROW(
        NEW.release_id, NEW.runtime_generation, NEW.database_generation,
        NEW.migration_manifest_sha256
    ) IS DISTINCT FROM ROW(
        OLD.release_id, OLD.runtime_generation, OLD.database_generation,
        OLD.migration_manifest_sha256
    );
    IF v_release_changed THEN
        v_rollforward :=
            SESSION_USER = 'harpy_migrator'
            AND CURRENT_USER = 'harpy_owner'
            AND OLD.state IN ('pending', 'failed', 'running')
            AND NEW.state = 'running'
            AND NEW.current_attempt = OLD.current_attempt + 1
            AND NEW.error_code IS NULL AND NEW.completed_at IS NULL
            AND EXISTS (
                SELECT 1
                FROM platform.tenancy_tenant_migration_executor_readiness AS ready
                WHERE ready.release_id = NEW.release_id
                  AND ready.environment_id = NEW.environment_id
                  AND ready.deployment_mode = NEW.deployment_mode
                  AND ready.runtime_generation = NEW.runtime_generation
                  AND ready.database_generation = NEW.database_generation
                  AND ready.migration_manifest_sha256 =
                      NEW.migration_manifest_sha256
                  AND ready.state = 'active' AND ready.ready_until > v_now
            )
            AND (
                OLD.state <> 'running' OR EXISTS (
                    SELECT 1
                    FROM platform.tenancy_tenant_migration_attempts AS attempt
                    WHERE attempt.job_id = OLD.job_id
                      AND attempt.attempt = OLD.current_attempt
                      AND attempt.state = 'failed'
                      AND attempt.error_code = 'lease_expired'
                )
            )
            AND (
                SELECT pg_catalog.count(*)
                FROM platform.tenancy_tenant_migration_attempts AS attempt
                JOIN platform.tenancy_tenant_migration_executor_readiness AS ready
                  ON ready.profile_instance_id = attempt.profile_instance_id
                WHERE attempt.job_id = OLD.job_id
                  AND ready.release_id = NEW.release_id
                  AND ready.runtime_generation = NEW.runtime_generation
                  AND ready.database_generation = NEW.database_generation
                  AND ready.migration_manifest_sha256 =
                      NEW.migration_manifest_sha256
            ) < 8;
        IF NOT v_rollforward THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'tenant migration job release identity is immutable';
        END IF;
    END IF;

    IF NEW.updated_at <= OLD.updated_at OR NOT (
        OLD.state = 'pending' AND NEW.state IN ('running', 'fenced')
        OR OLD.state = 'running' AND NEW.state = 'running'
            AND NEW.current_attempt = OLD.current_attempt + 1
        OR OLD.state = 'running' AND NEW.state IN (
            'succeeded', 'failed', 'reconcile_required', 'cleanup_required'
        )
        OR OLD.state = 'failed' AND NEW.state IN ('running', 'fenced')
        OR OLD.state IN ('reconcile_required', 'cleanup_required')
            AND NEW.state = 'fenced'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration job transition is invalid';
    END IF;
    IF NEW.state = 'running' AND NEW.current_attempt <> OLD.current_attempt + 1
       OR NEW.state <> 'running' AND
          NEW.current_attempt <> OLD.current_attempt THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration attempt transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.tenancy_guard_tenant_migration_job_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_guard_tenant_migration_readiness_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_guard_tenant_migration_readiness_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' OR ROW(
        NEW.profile_instance_id, NEW.release_id, NEW.environment_id,
        NEW.deployment_mode, NEW.runtime_generation, NEW.database_generation,
        NEW.migration_manifest_sha256, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.profile_instance_id, OLD.release_id, OLD.environment_id,
        OLD.deployment_mode, OLD.runtime_generation, OLD.database_generation,
        OLD.migration_manifest_sha256, OLD.created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration readiness identity is immutable';
    END IF;
    IF NOT (
        OLD.state = 'active' AND NEW.state = 'active'
            AND NEW.heartbeat_at > OLD.heartbeat_at
            AND NEW.ready_until > OLD.ready_until
        OR OLD.state = 'active' AND NEW.state = 'retired'
            AND NEW.retired_at IS NOT NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration readiness transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.tenancy_guard_tenant_migration_readiness_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_guard_tenant_registry(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_guard_tenant_registry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.id IS DISTINCT FROM OLD.id
            OR NEW.slug IS DISTINCT FROM OLD.slug
            OR NEW.schema_name IS DISTINCT FROM OLD.schema_name
            OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
            RAISE EXCEPTION USING
                ERRCODE = '55000',
                MESSAGE = 'tenant id, slug, schema name, and creation time are immutable';
        END IF;
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING
        ERRCODE = '55000',
        MESSAGE = 'tenant registry hard delete is forbidden';
END;
$$;


ALTER FUNCTION platform.tenancy_guard_tenant_registry() OWNER TO harpy_owner;

--
-- Name: tenancy_initialize_deployment_policy_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_initialize_deployment_policy_v1(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_deployment_mode text) RETURNS TABLE(operation_id uuid, environment_id uuid, deployment_mode text, maximum_customer_tenants bigint, created_at timestamp with time zone, database_now timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    initialization platform.tenancy_deployment_policy_initializations%ROWTYPE;
    policy platform.tenancy_deployment_policy%ROWTYPE;
    capacity bigint;
    now_at timestamptz := pg_catalog.statement_timestamp();
    policy_preexisted boolean := false;
BEGIN
    capacity := CASE p_deployment_mode WHEN 'onpremise' THEN 0 ELSE NULL END;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_operation_kind IS DISTINCT FROM 'environment_initialize'
       OR p_deployment_mode NOT IN ('onpremise', 'saas') THEN
        RAISE EXCEPTION USING
            ERRCODE = '42501', MESSAGE = 'deployment policy initialization denied';
    END IF;
    PERFORM 1 FROM platform.environment_identity AS identity
    WHERE identity.environment_id = p_environment_id
    FOR NO KEY UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            ERRCODE = 'P0002', MESSAGE = 'environment identity is missing';
    END IF;
    SELECT * INTO initialization
    FROM platform.tenancy_deployment_policy_initializations AS candidate
    WHERE candidate.environment_id = p_environment_id
    FOR UPDATE;
    IF FOUND THEN
        IF initialization.operation_id IS DISTINCT FROM p_operation_id
           OR initialization.operation_kind IS DISTINCT FROM p_operation_kind
           OR initialization.deployment_mode IS DISTINCT FROM p_deployment_mode
           OR initialization.maximum_customer_tenants IS DISTINCT FROM capacity THEN
            RAISE EXCEPTION USING
                ERRCODE = '23505', MESSAGE = 'deployment policy initialization conflicts';
        END IF;
        SELECT * INTO policy
        FROM platform.tenancy_deployment_policy AS existing
        WHERE existing.environment_id = p_environment_id
        FOR UPDATE;
        IF NOT FOUND OR policy.deployment_mode IS DISTINCT FROM p_deployment_mode
           OR policy.maximum_customer_tenants IS DISTINCT FROM capacity THEN
            RAISE EXCEPTION USING
                ERRCODE = '23505', MESSAGE = 'deployment policy state conflicts';
        END IF;
        RETURN QUERY SELECT initialization.operation_id, policy.environment_id,
            policy.deployment_mode, policy.maximum_customer_tenants,
            policy.created_at, now_at, true;
        RETURN;
    END IF;
    SELECT * INTO policy
    FROM platform.tenancy_deployment_policy AS existing
    WHERE existing.singleton
    FOR UPDATE;
    IF FOUND THEN
        policy_preexisted := true;
        IF policy.environment_id IS DISTINCT FROM p_environment_id
           OR policy.deployment_mode IS DISTINCT FROM p_deployment_mode
           OR policy.maximum_customer_tenants IS DISTINCT FROM capacity THEN
            RAISE EXCEPTION USING
                ERRCODE = '23505', MESSAGE = 'deployment policy state conflicts';
        END IF;
    ELSE
        INSERT INTO platform.tenancy_deployment_policy (
            environment_id, deployment_mode, maximum_customer_tenants, created_at
        ) VALUES (p_environment_id, p_deployment_mode, capacity, now_at)
        RETURNING * INTO policy;
    END IF;
    INSERT INTO platform.tenancy_deployment_policy_initializations (
        operation_id, environment_id, operation_kind, deployment_mode,
        maximum_customer_tenants, created_at
    ) VALUES (p_operation_id, p_environment_id, p_operation_kind,
        p_deployment_mode, capacity, now_at);
    RETURN QUERY SELECT p_operation_id, policy.environment_id,
        policy.deployment_mode, policy.maximum_customer_tenants,
        policy.created_at, now_at, policy_preexisted;
END;
$$;


ALTER FUNCTION platform.tenancy_initialize_deployment_policy_v1(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_deployment_mode text) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_ack_v1(uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_ack_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint, p_adapter_id text, p_claim_token_sha256 text) RETURNS TABLE(operation_id uuid, tenant_id uuid, first_owner_user_id uuid, current_attempt_id uuid, current_credential_id uuid, current_credential_version bigint, delivery_state text, delivery_revision bigint, database_now timestamp with time zone, claim_adapter_id text, claim_lease_until timestamp with time zone, acknowledged_at timestamp with time zone, secret_deleted_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery ack denied';
    END IF;
    IF p_expected_revision < 1 OR p_attempt_id IS NULL
       OR octet_length(p_adapter_id) NOT BETWEEN 1 AND 128
       OR p_claim_token_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='installation delivery ack invalid';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR delivery.current_attempt_id<>p_attempt_id
       OR delivery.claim_adapter_id<>p_adapter_id
       OR delivery.claim_token_sha256<>p_claim_token_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='installation delivery ack unavailable';
    END IF;
    IF delivery.state='acknowledged' AND delivery.revision=p_expected_revision+1 THEN
        NULL;
    ELSIF delivery.state='claimed' AND delivery.revision=p_expected_revision
       AND delivery.claim_lease_until>now_at THEN
        UPDATE platform.tenancy_installation_credential_deliveries AS target
        SET state='acknowledged',acknowledged_at=now_at,
            revision=target.revision+1,updated_at=now_at
        WHERE target.operation_id=p_operation_id
        RETURNING * INTO delivery;
        UPDATE platform.tenancy_installation_credential_delivery_attempts AS attempt
        SET state='acknowledged',acknowledged_at=now_at
        WHERE attempt.attempt_id=p_attempt_id AND attempt.operation_id=p_operation_id
          AND attempt.state='claimed';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery attempt changed';
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery ack changed';
    END IF;
    RETURN QUERY SELECT delivery.operation_id,delivery.tenant_id,
        delivery.first_owner_user_id,delivery.current_attempt_id,
        delivery.current_credential_id,delivery.current_credential_version,
        delivery.state,delivery.revision,now_at,delivery.claim_adapter_id,
        delivery.claim_lease_until,delivery.acknowledged_at,
        delivery.secret_deleted_at,delivery.completed_at;
END;
$_$;


ALTER FUNCTION platform.tenancy_installation_delivery_ack_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint, p_adapter_id text, p_claim_token_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_attempts_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_attempts_v1(p_operation_id uuid) RETURNS TABLE(attempt_id uuid, credential_id uuid, credential_version bigint, attempt_state text, cause text, superseded_by_attempt_id uuid, created_at timestamp with time zone, claimed_at timestamp with time zone, acknowledged_at timestamp with time zone, superseded_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery attempts denied';
    END IF;
    RETURN QUERY SELECT attempt.attempt_id,attempt.credential_id,attempt.credential_version,
        attempt.state,attempt.cause,attempt.superseded_by_attempt_id,
        attempt.created_at,attempt.claimed_at,attempt.acknowledged_at,
        attempt.superseded_at,attempt.completed_at
    FROM platform.tenancy_installation_credential_delivery_attempts AS attempt
    WHERE attempt.operation_id=p_operation_id
    ORDER BY attempt.credential_version;
END;
$$;


ALTER FUNCTION platform.tenancy_installation_delivery_attempts_v1(p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_claim_v1(uuid, uuid, bigint, text, text, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_claim_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint, p_adapter_id text, p_claim_token_sha256 text, p_lease_seconds integer) RETURNS TABLE(operation_id uuid, tenant_id uuid, first_owner_user_id uuid, current_attempt_id uuid, current_credential_id uuid, current_credential_version bigint, delivery_state text, delivery_revision bigint, database_now timestamp with time zone, claim_adapter_id text, claim_lease_until timestamp with time zone, acknowledged_at timestamp with time zone, secret_deleted_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery claim denied';
    END IF;
    IF p_expected_revision < 1 OR p_attempt_id IS NULL
       OR octet_length(p_adapter_id) NOT BETWEEN 1 AND 128
       OR p_claim_token_sha256 !~ '^[0-9a-f]{64}$'
       OR p_lease_seconds NOT BETWEEN 10 AND 300 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='installation delivery claim invalid';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR delivery.current_attempt_id <> p_attempt_id THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='installation delivery unavailable';
    END IF;
    IF delivery.state='claimed' AND delivery.revision=p_expected_revision+1
       AND delivery.claim_adapter_id=p_adapter_id
       AND delivery.claim_token_sha256=p_claim_token_sha256
       AND delivery.claim_lease_until>now_at THEN
        NULL;
    ELSIF delivery.state='ready_to_display' AND delivery.revision=p_expected_revision THEN
        UPDATE platform.tenancy_installation_credential_deliveries AS target
        SET state='claimed',claim_adapter_id=p_adapter_id,
            claim_token_sha256=p_claim_token_sha256,
            claim_lease_until=now_at+pg_catalog.make_interval(secs=>p_lease_seconds),
            claimed_at=now_at,revision=target.revision+1,updated_at=now_at
        WHERE target.operation_id=p_operation_id
        RETURNING * INTO delivery;
        UPDATE platform.tenancy_installation_credential_delivery_attempts AS attempt
        SET state='claimed',claimed_at=now_at
        WHERE attempt.attempt_id=p_attempt_id AND attempt.operation_id=p_operation_id
          AND attempt.state='ready_to_display';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery attempt changed';
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery claim changed';
    END IF;
    RETURN QUERY SELECT delivery.operation_id,delivery.tenant_id,
        delivery.first_owner_user_id,delivery.current_attempt_id,
        delivery.current_credential_id,delivery.current_credential_version,
        delivery.state,delivery.revision,now_at,delivery.claim_adapter_id,
        delivery.claim_lease_until,delivery.acknowledged_at,
        delivery.secret_deleted_at,delivery.completed_at;
END;
$_$;


ALTER FUNCTION platform.tenancy_installation_delivery_claim_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint, p_adapter_id text, p_claim_token_sha256 text, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_complete_v1(uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_complete_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint) RETURNS TABLE(delivery_state text, delivery_revision bigint, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery complete denied';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id AND candidate.current_attempt_id=p_attempt_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='installation delivery unavailable';
    END IF;
    IF delivery.state='completed' AND delivery.revision=p_expected_revision+1 THEN
        NULL;
    ELSIF delivery.state='secret_deleted' AND delivery.revision=p_expected_revision THEN
        UPDATE platform.tenancy_installation_credential_deliveries AS target
        SET state='completed',completed_at=now_at,
            revision=target.revision+1,updated_at=now_at
        WHERE target.operation_id=p_operation_id
        RETURNING * INTO delivery;
        UPDATE platform.tenancy_installation_credential_delivery_attempts AS attempt
        SET state='completed',completed_at=now_at
        WHERE attempt.attempt_id=p_attempt_id AND attempt.operation_id=p_operation_id
          AND attempt.state='acknowledged';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery attempt changed';
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation completion state changed';
    END IF;
    RETURN QUERY SELECT delivery.state,delivery.revision,now_at;
END;
$$;


ALTER FUNCTION platform.tenancy_installation_delivery_complete_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_read_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_read_v1(p_operation_id uuid) RETURNS TABLE(operation_id uuid, tenant_id uuid, first_owner_user_id uuid, current_attempt_id uuid, current_credential_id uuid, current_credential_version bigint, delivery_state text, delivery_revision bigint, database_now timestamp with time zone, claim_adapter_id text, claim_lease_until timestamp with time zone, acknowledged_at timestamp with time zone, secret_deleted_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery read denied';
    END IF;
    RETURN QUERY SELECT delivery.operation_id,delivery.tenant_id,delivery.first_owner_user_id,
        delivery.current_attempt_id,delivery.current_credential_id,
        delivery.current_credential_version,delivery.state,delivery.revision,
        pg_catalog.statement_timestamp(),delivery.claim_adapter_id,
        delivery.claim_lease_until,delivery.acknowledged_at,
        delivery.secret_deleted_at,delivery.completed_at
    FROM platform.tenancy_installation_credential_deliveries AS delivery
    WHERE delivery.operation_id=p_operation_id;
END;
$$;


ALTER FUNCTION platform.tenancy_installation_delivery_read_v1(p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_record_v1(uuid, uuid, uuid, bigint, uuid, uuid, bigint, bigint, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_record_v1(p_operation_id uuid, p_current_attempt_id uuid, p_current_credential_id uuid, p_current_credential_version bigint, p_next_attempt_id uuid, p_next_credential_id uuid, p_next_credential_version bigint, p_expected_revision bigint, p_recovery_token_sha256 text, p_delivery_manifest_sha256 text, p_cause text) RETURNS TABLE(delivery_state text, delivery_revision bigint, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery record denied';
    END IF;
    IF p_expected_revision<1 OR p_cause NOT IN ('claim_lease_expired','outcome_unknown')
       OR p_delivery_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR p_recovery_token_sha256 !~ '^[0-9a-f]{64}$'
       OR p_next_credential_version<>p_current_credential_version+1 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='installation delivery record invalid';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR delivery.state<>'outcome_unknown'
       OR delivery.revision<>p_expected_revision
       OR delivery.current_attempt_id<>p_current_attempt_id
       OR delivery.current_credential_id<>p_current_credential_id
       OR delivery.current_credential_version<>p_current_credential_version
       OR delivery.recovery_attempt_id<>p_next_attempt_id
       OR delivery.recovery_credential_id<>p_next_credential_id
       OR delivery.recovery_credential_version<>p_next_credential_version
       OR delivery.recovery_token_sha256<>p_recovery_token_sha256
       OR delivery.recovery_lease_until<=now_at OR delivery.recovery_cause<>p_cause
       OR delivery.delivery_manifest_sha256<>p_delivery_manifest_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation recovery binding changed';
    END IF;
    UPDATE platform.tenancy_installation_credential_delivery_attempts AS previous
    SET state='superseded',superseded_by_attempt_id=p_next_attempt_id,
        superseded_at=now_at
    WHERE previous.attempt_id=p_current_attempt_id
      AND previous.operation_id=p_operation_id
      AND previous.state='outcome_unknown' AND previous.cause=p_cause;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation recovery attempt changed';
    END IF;
    INSERT INTO platform.tenancy_installation_credential_delivery_attempts(
        attempt_id,operation_id,credential_id,credential_version,state,created_at)
    VALUES (p_next_attempt_id,p_operation_id,p_next_credential_id,
        p_next_credential_version,'ready_to_display',now_at);
    UPDATE platform.tenancy_installation_credential_deliveries AS target
    SET current_attempt_id=p_next_attempt_id,current_credential_id=p_next_credential_id,
        current_credential_version=p_next_credential_version,state='ready_to_display',
        claim_adapter_id=NULL,claim_token_sha256=NULL,claim_lease_until=NULL,
        claimed_at=NULL,acknowledged_at=NULL,secret_deleted_at=NULL,completed_at=NULL,
        recovery_attempt_id=NULL,recovery_credential_id=NULL,
        recovery_credential_version=NULL,recovery_token_sha256=NULL,
        recovery_lease_until=NULL,recovery_cause=NULL,
        revision=target.revision+1,updated_at=now_at
    WHERE target.operation_id=p_operation_id
    RETURNING * INTO delivery;
    RETURN QUERY SELECT delivery.state,delivery.revision,now_at;
END;
$_$;


ALTER FUNCTION platform.tenancy_installation_delivery_record_v1(p_operation_id uuid, p_current_attempt_id uuid, p_current_credential_id uuid, p_current_credential_version bigint, p_next_attempt_id uuid, p_next_credential_id uuid, p_next_credential_version bigint, p_expected_revision bigint, p_recovery_token_sha256 text, p_delivery_manifest_sha256 text, p_cause text) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_recover_v1(uuid, uuid, uuid, bigint, uuid, uuid, bigint, bigint, text, text, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_recover_v1(p_operation_id uuid, p_current_attempt_id uuid, p_current_credential_id uuid, p_current_credential_version bigint, p_next_attempt_id uuid, p_next_credential_id uuid, p_next_credential_version bigint, p_expected_revision bigint, p_recovery_token_sha256 text, p_delivery_manifest_sha256 text, p_lease_seconds integer) RETURNS TABLE(operation_id uuid, tenant_id uuid, first_owner_user_id uuid, current_credential_id uuid, current_credential_version bigint, next_credential_id uuid, next_credential_version bigint, current_attempt_id uuid, next_attempt_id uuid, recovery_cause text, delivery_manifest_sha256 text, delivery_revision bigint, database_now timestamp with time zone, recovery_lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    attempt platform.tenancy_installation_credential_delivery_attempts%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery recovery denied';
    END IF;
    IF p_expected_revision<1 OR p_next_attempt_id IS NULL OR p_next_credential_id IS NULL
       OR p_next_attempt_id=p_current_attempt_id OR p_next_credential_id=p_current_credential_id
       OR p_next_credential_version<>p_current_credential_version+1
       OR p_recovery_token_sha256 !~ '^[0-9a-f]{64}$'
       OR p_delivery_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR p_lease_seconds NOT BETWEEN 10 AND 300 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='installation delivery recovery invalid';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id
    FOR UPDATE;
    SELECT * INTO attempt
    FROM platform.tenancy_installation_credential_delivery_attempts AS candidate
    WHERE candidate.operation_id=p_operation_id AND candidate.attempt_id=p_current_attempt_id
    FOR UPDATE;
    IF delivery.operation_id IS NULL OR attempt.attempt_id IS NULL
       OR delivery.state<>'outcome_unknown' OR attempt.state<>'outcome_unknown'
       OR delivery.current_attempt_id<>p_current_attempt_id
       OR delivery.current_credential_id<>p_current_credential_id
       OR delivery.current_credential_version<>p_current_credential_version
       OR delivery.delivery_manifest_sha256<>p_delivery_manifest_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='installation delivery recovery unavailable';
    END IF;
    IF delivery.revision=p_expected_revision+1
       AND delivery.recovery_attempt_id=p_next_attempt_id
       AND delivery.recovery_credential_id=p_next_credential_id
       AND delivery.recovery_credential_version=p_next_credential_version
       AND delivery.recovery_token_sha256=p_recovery_token_sha256
       AND delivery.recovery_lease_until>now_at THEN
        NULL;
    ELSIF delivery.revision=p_expected_revision
       AND (delivery.recovery_lease_until IS NULL OR delivery.recovery_lease_until<=now_at) THEN
        UPDATE platform.tenancy_installation_credential_deliveries AS target
        SET recovery_attempt_id=p_next_attempt_id,
            recovery_credential_id=p_next_credential_id,
            recovery_credential_version=p_next_credential_version,
            recovery_token_sha256=p_recovery_token_sha256,
            recovery_lease_until=now_at+pg_catalog.make_interval(secs=>p_lease_seconds),
            recovery_cause=attempt.cause,revision=target.revision+1,updated_at=now_at
        WHERE target.operation_id=p_operation_id
        RETURNING * INTO delivery;
    ELSE
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation recovery lease changed';
    END IF;
    RETURN QUERY SELECT delivery.operation_id,delivery.tenant_id,
        delivery.first_owner_user_id,delivery.current_credential_id,
        delivery.current_credential_version,delivery.recovery_credential_id,
        delivery.recovery_credential_version,delivery.current_attempt_id,
        delivery.recovery_attempt_id,delivery.recovery_cause,
        delivery.delivery_manifest_sha256,delivery.revision,now_at,
        delivery.recovery_lease_until;
END;
$_$;


ALTER FUNCTION platform.tenancy_installation_delivery_recover_v1(p_operation_id uuid, p_current_attempt_id uuid, p_current_credential_id uuid, p_current_credential_version bigint, p_next_attempt_id uuid, p_next_credential_id uuid, p_next_credential_version bigint, p_expected_revision bigint, p_recovery_token_sha256 text, p_delivery_manifest_sha256 text, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_secret_deleted_v1(uuid, uuid, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_secret_deleted_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint) RETURNS TABLE(delivery_state text, delivery_revision bigint, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation secret cleanup denied';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id AND candidate.current_attempt_id=p_attempt_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='installation delivery unavailable';
    END IF;
    IF delivery.state='secret_deleted' AND delivery.revision=p_expected_revision+1 THEN
        NULL;
    ELSIF delivery.state='acknowledged' AND delivery.revision=p_expected_revision THEN
        UPDATE platform.tenancy_installation_credential_deliveries AS target
        SET state='secret_deleted',secret_deleted_at=now_at,
            revision=target.revision+1,updated_at=now_at
        WHERE target.operation_id=p_operation_id
        RETURNING * INTO delivery;
    ELSE
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation cleanup state changed';
    END IF;
    RETURN QUERY SELECT delivery.state,delivery.revision,now_at;
END;
$$;


ALTER FUNCTION platform.tenancy_installation_delivery_secret_deleted_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_stage_v1(uuid, uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_stage_v1(p_operation_id uuid, p_attempt_id uuid, p_credential_id uuid, p_credential_version bigint, p_installation_manifest_sha256 text, p_delivery_manifest_sha256 text) RETURNS TABLE(operation_id uuid, tenant_id uuid, first_owner_user_id uuid, current_attempt_id uuid, current_credential_id uuid, current_credential_version bigint, delivery_state text, delivery_revision bigint, database_now timestamp with time zone, claim_adapter_id text, claim_lease_until timestamp with time zone, acknowledged_at timestamp with time zone, secret_deleted_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    onboarding platform.tenancy_onboarding_operations%ROWTYPE;
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery stage denied';
    END IF;
    IF p_attempt_id IS NULL OR p_credential_id IS NULL OR p_credential_version <> 1
       OR p_installation_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR p_delivery_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='installation delivery stage invalid';
    END IF;
    SELECT * INTO onboarding
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id=p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR onboarding.operation_kind <> 'environment_initialize'
       OR onboarding.state <> 'succeeded'
       OR onboarding.manifest_sha256 <> p_installation_manifest_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='installation delivery is not ready';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id
    FOR UPDATE;
    IF FOUND THEN
        IF delivery.tenant_id <> onboarding.tenant_id
           OR delivery.first_owner_user_id <> onboarding.first_user_id
           OR delivery.current_attempt_id <> p_attempt_id
           OR delivery.current_credential_id <> p_credential_id
           OR delivery.current_credential_version <> p_credential_version
           OR delivery.installation_manifest_sha256 <> p_installation_manifest_sha256
           OR delivery.delivery_manifest_sha256 <> p_delivery_manifest_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery replay changed';
        END IF;
    ELSE
        INSERT INTO platform.tenancy_installation_credential_deliveries(
            operation_id,tenant_id,first_owner_user_id,installation_manifest_sha256,
            delivery_manifest_sha256,current_attempt_id,current_credential_id,
            current_credential_version,state,revision,created_at,updated_at)
        VALUES (p_operation_id,onboarding.tenant_id,onboarding.first_user_id,
            p_installation_manifest_sha256,p_delivery_manifest_sha256,p_attempt_id,
            p_credential_id,p_credential_version,'ready_to_display',1,now_at,now_at)
        RETURNING * INTO delivery;
        INSERT INTO platform.tenancy_installation_credential_delivery_attempts(
            attempt_id,operation_id,credential_id,credential_version,state,created_at)
        VALUES (p_attempt_id,p_operation_id,p_credential_id,p_credential_version,
            'ready_to_display',now_at);
    END IF;
    RETURN QUERY SELECT delivery.operation_id,delivery.tenant_id,
        delivery.first_owner_user_id,delivery.current_attempt_id,
        delivery.current_credential_id,delivery.current_credential_version,
        delivery.state,delivery.revision,now_at,delivery.claim_adapter_id,
        delivery.claim_lease_until,delivery.acknowledged_at,
        delivery.secret_deleted_at,delivery.completed_at;
END;
$_$;


ALTER FUNCTION platform.tenancy_installation_delivery_stage_v1(p_operation_id uuid, p_attempt_id uuid, p_credential_id uuid, p_credential_version bigint, p_installation_manifest_sha256 text, p_delivery_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_installation_delivery_unknown_v1(uuid, uuid, bigint, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_installation_delivery_unknown_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint, p_adapter_id text, p_claim_token_sha256 text, p_cause text) RETURNS TABLE(delivery_state text, delivery_revision bigint, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    delivery platform.tenancy_installation_credential_deliveries%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='installation delivery unknown denied';
    END IF;
    IF p_expected_revision<1 OR p_cause NOT IN ('claim_lease_expired','outcome_unknown')
       OR octet_length(p_adapter_id) NOT BETWEEN 1 AND 128
       OR p_claim_token_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='installation delivery unknown invalid';
    END IF;
    SELECT * INTO delivery
    FROM platform.tenancy_installation_credential_deliveries AS candidate
    WHERE candidate.operation_id=p_operation_id AND candidate.current_attempt_id=p_attempt_id
    FOR UPDATE;
    IF NOT FOUND OR delivery.claim_adapter_id<>p_adapter_id
       OR delivery.claim_token_sha256<>p_claim_token_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='installation delivery unavailable';
    END IF;
    IF delivery.state='outcome_unknown' AND delivery.revision=p_expected_revision+1 THEN
        NULL;
    ELSIF delivery.state='claimed' AND delivery.revision=p_expected_revision
       AND (p_cause='outcome_unknown' OR delivery.claim_lease_until<=now_at) THEN
        UPDATE platform.tenancy_installation_credential_deliveries AS target
        SET state='outcome_unknown',revision=target.revision+1,updated_at=now_at
        WHERE target.operation_id=p_operation_id
        RETURNING * INTO delivery;
        UPDATE platform.tenancy_installation_credential_delivery_attempts AS attempt
        SET state='outcome_unknown',cause=p_cause
        WHERE attempt.attempt_id=p_attempt_id AND attempt.operation_id=p_operation_id
          AND attempt.state='claimed';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery attempt changed';
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='installation delivery unknown changed';
    END IF;
    RETURN QUERY SELECT delivery.state,delivery.revision,now_at;
END;
$_$;


ALTER FUNCTION platform.tenancy_installation_delivery_unknown_v1(p_operation_id uuid, p_attempt_id uuid, p_expected_revision bigint, p_adapter_id text, p_claim_token_sha256 text, p_cause text) OWNER TO harpy_owner;

--
-- Name: tenancy_list_saas_customer_tenants_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_list_saas_customer_tenants_v1(p_environment_id uuid) RETURNS TABLE(tenant_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
        OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
        OR p_environment_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'SaaS customer list query denied';
    END IF;
    PERFORM 1
    FROM platform.tenancy_deployment_policy AS policy
    WHERE policy.environment_id = p_environment_id
      AND policy.deployment_mode = 'saas';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'SaaS deployment policy is required';
    END IF;
    RETURN QUERY
    SELECT binding.tenant_id
    FROM platform.tenancy_tenant_bindings AS binding
    WHERE binding.environment_id = p_environment_id
      AND binding.purpose = 'saas_customer'
    ORDER BY binding.tenant_id;
END;
$$;


ALTER FUNCTION platform.tenancy_list_saas_customer_tenants_v1(p_environment_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_accept_v1(uuid, uuid, text, text, text, text, text, text, uuid, name, text, uuid, uuid, uuid, uuid, uuid, bigint, text, timestamp with time zone, bigint, text, bigint, text, uuid, text, uuid, bigint, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_accept_v1(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_idempotency_key text, p_request_sha256 text, p_manifest_sha256 text, p_step_plan_sha256 text, p_deployment_mode text, p_tenant_id uuid, p_schema_name name, p_binding_purpose text, p_first_user_id uuid, p_root_organization_id uuid, p_protected_admin_binding_id uuid, p_instance_owner_binding_id uuid, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_registry_binding_id uuid, p_authority_scope_kind text, p_authority_scope_id uuid, p_authority_generation bigint, p_authority_previous_head_sha256 text, p_authority_state_sha256 text, p_authority_proposal_sha256 text, p_created_at timestamp with time zone) RETURNS TABLE(operation_id uuid, state text, revision bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    existing platform.tenancy_onboarding_operations%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'onboarding accept denied';
    END IF;
    PERFORM 1 FROM platform.tenancy_deployment_policy AS policy
    WHERE policy.environment_id = p_environment_id
      AND policy.deployment_mode = p_deployment_mode
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'deployment policy mismatch';
    END IF;
    SELECT * INTO existing
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.environment_id = p_environment_id
      AND operation.operation_kind = p_operation_kind
      AND operation.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF existing.operation_id IS DISTINCT FROM p_operation_id
           OR existing.request_sha256 IS DISTINCT FROM p_request_sha256
           OR existing.manifest_sha256 IS DISTINCT FROM p_manifest_sha256
           OR existing.step_plan_sha256 IS DISTINCT FROM p_step_plan_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'onboarding idempotency conflict';
        END IF;
        RETURN QUERY SELECT existing.operation_id, existing.state,
            existing.revision, existing.updated_at;
        RETURN;
    END IF;
    INSERT INTO platform.tenancy_onboarding_operations (
        operation_id, environment_id, operation_kind, idempotency_key,
        request_sha256, manifest_sha256, step_plan_sha256, deployment_mode,
        tenant_id, schema_name, binding_purpose, first_user_id,
        root_organization_id, protected_admin_binding_id, instance_owner_binding_id,
        offering_version_id, offering_revision, offering_sha256,
        offering_effective_at, offering_source_sequence, offering_source_sha256,
        recovery_signing_generation, recovery_trust_bundle_sha256,
        registry_binding_id, authority_scope_kind, authority_scope_id,
        authority_generation, authority_previous_head_sha256,
        authority_state_sha256, authority_proposal_sha256, created_at, updated_at
    ) VALUES (
        p_operation_id, p_environment_id, p_operation_kind, p_idempotency_key,
        p_request_sha256, p_manifest_sha256, p_step_plan_sha256, p_deployment_mode,
        p_tenant_id, p_schema_name, p_binding_purpose, p_first_user_id,
        p_root_organization_id, p_protected_admin_binding_id, p_instance_owner_binding_id,
        p_offering_version_id, p_offering_revision, p_offering_sha256,
        p_offering_effective_at, p_offering_source_sequence, p_offering_source_sha256,
        p_recovery_signing_generation, p_recovery_trust_bundle_sha256,
        p_registry_binding_id, p_authority_scope_kind, p_authority_scope_id,
        p_authority_generation, p_authority_previous_head_sha256,
        p_authority_state_sha256, p_authority_proposal_sha256, p_created_at, p_created_at
    );
    INSERT INTO platform.tenancy_onboarding_steps (operation_id, step_ordinal, command_key)
    VALUES
        (p_operation_id, 1, 'tenancy.activate_tenant'),
        (p_operation_id, 2, 'iam.initialize_tenant_identity'),
        (p_operation_id, 3, 'billing.assign_tenant_base_offering'),
        (p_operation_id, 4, 'billing.open_tenant_usage'),
        (p_operation_id, 5, 'systemresources.initialize_tenant_baseline'),
        (p_operation_id, 6, 'platformops.initialize_recovery_signing_identity');
    IF p_operation_kind = 'environment_initialize' THEN
        INSERT INTO platform.tenancy_onboarding_steps (operation_id, step_ordinal, command_key)
        VALUES (p_operation_id, 7, 'platformauthority.bind_owner'),
               (p_operation_id, 8, 'platformauthority.pin_protected_authority_head'),
               (p_operation_id, 9, 'activation.complete');
    ELSE
        INSERT INTO platform.tenancy_onboarding_steps (operation_id, step_ordinal, command_key)
        VALUES (p_operation_id, 7, 'platformauthority.pin_protected_authority_head'),
               (p_operation_id, 8, 'activation.complete');
    END IF;
    RETURN QUERY SELECT p_operation_id, 'accepted'::text, 1::bigint, p_created_at;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_accept_v1(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_idempotency_key text, p_request_sha256 text, p_manifest_sha256 text, p_step_plan_sha256 text, p_deployment_mode text, p_tenant_id uuid, p_schema_name name, p_binding_purpose text, p_first_user_id uuid, p_root_organization_id uuid, p_protected_admin_binding_id uuid, p_instance_owner_binding_id uuid, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_registry_binding_id uuid, p_authority_scope_kind text, p_authority_scope_id uuid, p_authority_generation bigint, p_authority_previous_head_sha256 text, p_authority_state_sha256 text, p_authority_proposal_sha256 text, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_accept_v2(uuid, uuid, text, text, text, text, text, text, uuid, name, text, uuid, uuid, uuid, uuid, uuid, bigint, text, timestamp with time zone, bigint, text, bigint, text, uuid, text, uuid, bigint, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_accept_v2(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_idempotency_key text, p_request_sha256 text, p_manifest_sha256 text, p_step_plan_sha256 text, p_deployment_mode text, p_tenant_id uuid, p_schema_name name, p_binding_purpose text, p_first_user_id uuid, p_root_organization_id uuid, p_protected_admin_binding_id uuid, p_instance_owner_binding_id uuid, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_registry_binding_id uuid, p_authority_scope_kind text, p_authority_scope_id uuid, p_authority_generation bigint, p_authority_previous_head_sha256 text, p_authority_state_sha256 text, p_authority_proposal_sha256 text, p_created_at timestamp with time zone) RETURNS TABLE(operation_id uuid, state text, revision bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_existing platform.tenancy_onboarding_operations%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'onboarding accept denied';
    END IF;
    PERFORM 1
    FROM platform.tenancy_deployment_policy AS policy
    WHERE policy.environment_id = p_environment_id
      AND policy.deployment_mode = p_deployment_mode
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'deployment policy mismatch';
    END IF;
    SELECT * INTO v_existing
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.environment_id = p_environment_id
      AND operation.operation_kind = p_operation_kind
      AND operation.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.operation_id IS DISTINCT FROM p_operation_id
           OR v_existing.request_sha256 IS DISTINCT FROM p_request_sha256
           OR v_existing.manifest_sha256 IS DISTINCT FROM p_manifest_sha256
           OR v_existing.step_plan_sha256
                IS DISTINCT FROM p_step_plan_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'onboarding idempotency conflict';
        END IF;
        RETURN QUERY SELECT v_existing.operation_id, v_existing.state,
            v_existing.revision, v_existing.updated_at;
        RETURN;
    END IF;
    INSERT INTO platform.tenancy_onboarding_operations (
        operation_id, environment_id, operation_kind, idempotency_key,
        request_sha256, manifest_sha256, step_plan_sha256, deployment_mode,
        tenant_id, schema_name, binding_purpose, first_user_id,
        root_organization_id, protected_admin_binding_id,
        instance_owner_binding_id, offering_version_id, offering_revision,
        offering_sha256, offering_effective_at, offering_source_sequence,
        offering_source_sha256, recovery_signing_generation,
        recovery_trust_bundle_sha256, registry_binding_id,
        authority_scope_kind, authority_scope_id, authority_generation,
        authority_previous_head_sha256, authority_state_sha256,
        authority_proposal_sha256, created_at, updated_at
    ) VALUES (
        p_operation_id, p_environment_id, p_operation_kind,
        p_idempotency_key, p_request_sha256, p_manifest_sha256,
        p_step_plan_sha256, p_deployment_mode, p_tenant_id, p_schema_name,
        p_binding_purpose, p_first_user_id, p_root_organization_id,
        p_protected_admin_binding_id, p_instance_owner_binding_id,
        p_offering_version_id, p_offering_revision, p_offering_sha256,
        p_offering_effective_at, p_offering_source_sequence,
        p_offering_source_sha256, p_recovery_signing_generation,
        p_recovery_trust_bundle_sha256, p_registry_binding_id,
        p_authority_scope_kind, p_authority_scope_id,
        p_authority_generation, p_authority_previous_head_sha256,
        p_authority_state_sha256, p_authority_proposal_sha256,
        p_created_at, p_created_at
    );
    IF p_operation_kind = 'environment_initialize' THEN
        INSERT INTO platform.tenancy_onboarding_steps (
            operation_id, step_ordinal, command_key
        ) VALUES
            (p_operation_id, 1, 'tenancy.activate_tenant'),
            (p_operation_id, 2, 'iam.initialize_tenant_identity'),
            (p_operation_id, 3, 'billing.assign_tenant_base_offering'),
            (p_operation_id, 4, 'billing.open_tenant_usage'),
            (p_operation_id, 5, 'systemresources.initialize_tenant_baseline'),
            (p_operation_id, 6, 'platformops.initialize_recovery_signing_identity'),
            (p_operation_id, 7, 'platformauthority.bind_owner'),
            (p_operation_id, 8, 'platformauthority.pin_protected_authority_head'),
            (p_operation_id, 9, 'activation.complete');
    ELSE
        INSERT INTO platform.tenancy_onboarding_steps (
            operation_id, step_ordinal, command_key
        ) VALUES
            (p_operation_id, 1, 'tenancy.activate_tenant'),
            (p_operation_id, 2, 'iam.initialize_tenant_identity'),
            (p_operation_id, 3, 'billing.assign_tenant_base_offering'),
            (p_operation_id, 4, 'billing.open_tenant_usage'),
            (p_operation_id, 5, 'systemresources.initialize_tenant_baseline'),
            (p_operation_id, 6, 'platformauthority.pin_protected_authority_head'),
            (p_operation_id, 7, 'activation.complete');
    END IF;
    RETURN QUERY SELECT p_operation_id, 'accepted'::text,
        1::bigint, p_created_at;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_accept_v2(p_operation_id uuid, p_environment_id uuid, p_operation_kind text, p_idempotency_key text, p_request_sha256 text, p_manifest_sha256 text, p_step_plan_sha256 text, p_deployment_mode text, p_tenant_id uuid, p_schema_name name, p_binding_purpose text, p_first_user_id uuid, p_root_organization_id uuid, p_protected_admin_binding_id uuid, p_instance_owner_binding_id uuid, p_offering_version_id uuid, p_offering_revision bigint, p_offering_sha256 text, p_offering_effective_at timestamp with time zone, p_offering_source_sequence bigint, p_offering_source_sha256 text, p_recovery_signing_generation bigint, p_recovery_trust_bundle_sha256 text, p_registry_binding_id uuid, p_authority_scope_kind text, p_authority_scope_id uuid, p_authority_generation bigint, p_authority_previous_head_sha256 text, p_authority_state_sha256 text, p_authority_proposal_sha256 text, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_activate_v1(uuid, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_activate_v1(p_operation_id uuid, p_lease_token_sha256 text, p_expected_revision bigint) RETURNS TABLE(operation_id uuid, tenant_id uuid, operation_kind text, step_plan_sha256 text, migration_receipt_id uuid, migration_receipt_sha256 text, authority_ack_sha256 text, revision bigint, database_now timestamp with time zone, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    operation platform.tenancy_onboarding_operations%ROWTYPE;
    lease platform.tenancy_onboarding_leases%ROWTYPE;
    migration_receipt platform.tenancy_onboarding_receipts%ROWTYPE;
    ack_sha256 text;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'tenant activation claim denied';
    END IF;
    SELECT * INTO operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR operation.revision <> p_expected_revision
       OR NOT (operation.deployment_mode = 'onpremise' AND operation.state = 'migration_ready'
           OR operation.deployment_mode = 'saas' AND operation.state = 'authority_acknowledged') THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'tenant activation state conflict';
    END IF;
    SELECT * INTO lease
    FROM platform.tenancy_onboarding_leases AS current_lease
    WHERE current_lease.operation_id = p_operation_id
      AND current_lease.lease_token_sha256 = p_lease_token_sha256
      AND current_lease.lease_until > now_at
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'active activation lease required';
    END IF;
    SELECT * INTO migration_receipt
    FROM platform.tenancy_onboarding_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id
      AND receipt.receipt_kind = 'migration_completed';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'migration completion receipt required';
    END IF;
    SELECT ack.ack_sha256 INTO ack_sha256
    FROM platform.tenancy_onboarding_authority_acks AS ack
    WHERE ack.operation_id = p_operation_id;
    IF operation.deployment_mode = 'saas' AND ack_sha256 IS NULL
       OR operation.deployment_mode = 'onpremise' AND ack_sha256 IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'authority acknowledgement state mismatch';
    END IF;
    UPDATE platform.tenancy_onboarding_operations
    SET state = 'finalizing', revision = operation.revision + 1, updated_at = now_at
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id;
    UPDATE platform.tenancy_onboarding_leases
    SET revision = operation.revision + 1, heartbeat_at = now_at
    WHERE tenancy_onboarding_leases.operation_id = p_operation_id;
    RETURN QUERY SELECT operation.operation_id, operation.tenant_id,
        operation.operation_kind, operation.step_plan_sha256,
        migration_receipt.receipt_id, migration_receipt.receipt_sha256,
        ack_sha256, operation.revision + 1, now_at, lease.lease_until;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_activate_v1(p_operation_id uuid, p_lease_token_sha256 text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_activate_v2(uuid, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_activate_v2(p_operation_id uuid, p_lease_token_sha256 text, p_expected_revision bigint) RETURNS TABLE(operation_id uuid, tenant_id uuid, operation_kind text, step_plan_sha256 text, migration_receipt_id uuid, migration_receipt_sha256 text, authority_ack_sha256 text, revision bigint, database_now timestamp with time zone, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_claim_operation_id uuid;
    v_claim_tenant_id uuid;
    v_claim_operation_kind text;
    v_claim_step_plan_sha256 text;
    v_claim_migration_receipt_id uuid;
    v_claim_migration_receipt_sha256 text;
    v_claim_authority_ack_sha256 text;
    v_claim_revision bigint;
    v_claim_database_now timestamptz;
    v_claim_lease_until timestamptz;
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation capability mint denied';
    END IF;
    SELECT claim.operation_id, claim.tenant_id, claim.operation_kind,
           claim.step_plan_sha256, claim.migration_receipt_id,
           claim.migration_receipt_sha256, claim.authority_ack_sha256,
           claim.revision, claim.database_now, claim.lease_until
    INTO STRICT v_claim_operation_id, v_claim_tenant_id,
        v_claim_operation_kind, v_claim_step_plan_sha256,
        v_claim_migration_receipt_id, v_claim_migration_receipt_sha256,
        v_claim_authority_ack_sha256, v_claim_revision,
        v_claim_database_now, v_claim_lease_until
    FROM platform.tenancy_onboarding_activate_v1(
        p_operation_id, p_lease_token_sha256, p_expected_revision
    ) AS claim;
    SELECT * INTO STRICT v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF v_operation.state IS DISTINCT FROM 'finalizing'
       OR v_operation.revision IS DISTINCT FROM v_claim_revision
       OR v_operation.tenant_id IS DISTINCT FROM v_claim_tenant_id
       OR v_operation.operation_kind IS DISTINCT FROM v_claim_operation_kind
       OR v_operation.step_plan_sha256
            IS DISTINCT FROM v_claim_step_plan_sha256
       OR NOT EXISTS (
           SELECT 1
           FROM platform.tenancy_onboarding_steps AS step
           WHERE step.operation_id = v_operation.operation_id
             AND step.command_key = 'billing.assign_tenant_base_offering'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation capability plan conflict';
    END IF;
    INSERT INTO platform.tenancy_activation_command_capabilities (
        backend_pid, transaction_id, operation_id, command_key,
        environment_id, tenant_id, operation_kind, deployment_mode,
        binding_purpose, manifest_sha256, step_plan_sha256,
        offering_version_id, offering_revision, offering_sha256,
        offering_effective_at, offering_source_sequence,
        offering_source_sha256, created_at
    ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
        v_operation.operation_id, 'billing.assign_tenant_base_offering',
        v_operation.environment_id, v_operation.tenant_id,
        v_operation.operation_kind, v_operation.deployment_mode,
        v_operation.binding_purpose, v_operation.manifest_sha256,
        v_operation.step_plan_sha256, v_operation.offering_version_id,
        v_operation.offering_revision, v_operation.offering_sha256,
        v_operation.offering_effective_at,
        v_operation.offering_source_sequence,
        v_operation.offering_source_sha256,
        pg_catalog.transaction_timestamp()
    );
    RETURN QUERY SELECT
        v_claim_operation_id, v_claim_tenant_id, v_claim_operation_kind,
        v_claim_step_plan_sha256, v_claim_migration_receipt_id,
        v_claim_migration_receipt_sha256, v_claim_authority_ack_sha256,
        v_claim_revision, v_claim_database_now, v_claim_lease_until;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_activate_v2(p_operation_id uuid, p_lease_token_sha256 text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_activate_v3(uuid, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_activate_v3(p_operation_id uuid, p_lease_token_sha256 text, p_expected_revision bigint) RETURNS TABLE(operation_id uuid, tenant_id uuid, operation_kind text, step_plan_sha256 text, migration_receipt_id uuid, migration_receipt_sha256 text, authority_ack_sha256 text, revision bigint, database_now timestamp with time zone, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_claim_operation_id uuid;
    v_claim_tenant_id uuid;
    v_claim_operation_kind text;
    v_claim_step_plan_sha256 text;
    v_claim_migration_receipt_id uuid;
    v_claim_migration_receipt_sha256 text;
    v_claim_authority_ack_sha256 text;
    v_claim_revision bigint;
    v_claim_database_now timestamptz;
    v_claim_lease_until timestamptz;
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
BEGIN
    SELECT claim.operation_id, claim.tenant_id, claim.operation_kind,
        claim.step_plan_sha256, claim.migration_receipt_id,
        claim.migration_receipt_sha256, claim.authority_ack_sha256,
        claim.revision, claim.database_now, claim.lease_until
    INTO STRICT v_claim_operation_id, v_claim_tenant_id,
        v_claim_operation_kind, v_claim_step_plan_sha256,
        v_claim_migration_receipt_id, v_claim_migration_receipt_sha256,
        v_claim_authority_ack_sha256, v_claim_revision,
        v_claim_database_now, v_claim_lease_until
    FROM platform.tenancy_onboarding_activate_v2(
        p_operation_id, p_lease_token_sha256, p_expected_revision
    ) AS claim;
    SELECT * INTO STRICT v_operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF v_operation.state IS DISTINCT FROM 'finalizing'
       OR v_operation.revision IS DISTINCT FROM v_claim_revision
       OR v_operation.step_plan_sha256
            IS DISTINCT FROM v_claim_step_plan_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation step plan conflict';
    END IF;
    IF EXISTS (
        SELECT required.command_key
        FROM (
            VALUES
                ('tenancy.activate_tenant', false),
                ('iam.initialize_tenant_identity', false),
                ('billing.assign_tenant_base_offering', false),
                ('billing.open_tenant_usage', false),
                ('systemresources.initialize_tenant_baseline', false),
                ('platformops.initialize_recovery_signing_identity', true),
                ('platformauthority.bind_owner', true),
                ('platformauthority.pin_protected_authority_head', false),
                ('activation.complete', false)
        ) AS required(command_key, environment_only)
        WHERE (NOT required.environment_only
               OR v_operation.operation_kind = 'environment_initialize')
          AND NOT EXISTS (
              SELECT 1
              FROM platform.tenancy_onboarding_steps AS persisted
              WHERE persisted.operation_id = v_operation.operation_id
                AND persisted.command_key = required.command_key
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant activation command manifest conflict';
    END IF;
    INSERT INTO platform.tenancy_activation_step_capabilities (
        backend_pid, transaction_id, operation_id, command_key,
        environment_id, tenant_id, schema_name, operation_kind,
        deployment_mode, binding_purpose, manifest_sha256,
        step_plan_sha256, created_at
    )
    SELECT pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
        v_operation.operation_id, command.command_key,
        v_operation.environment_id, v_operation.tenant_id,
        v_operation.schema_name, v_operation.operation_kind,
        v_operation.deployment_mode, v_operation.binding_purpose,
        v_operation.manifest_sha256, v_operation.step_plan_sha256,
        pg_catalog.transaction_timestamp()
    FROM (
        VALUES
            ('tenancy.activate_tenant', false),
            ('iam.initialize_tenant_identity', false),
            ('billing.open_tenant_usage', false),
            ('systemresources.initialize_tenant_baseline', false),
            ('platformops.initialize_recovery_signing_identity', true),
            ('platformauthority.bind_owner', true),
            ('platformauthority.pin_protected_authority_head', false),
            ('activation.complete', false)
    ) AS command(command_key, environment_only)
    WHERE NOT command.environment_only
       OR v_operation.operation_kind = 'environment_initialize';
    RETURN QUERY SELECT v_claim_operation_id, v_claim_tenant_id,
        v_claim_operation_kind, v_claim_step_plan_sha256,
        v_claim_migration_receipt_id, v_claim_migration_receipt_sha256,
        v_claim_authority_ack_sha256, v_claim_revision,
        v_claim_database_now, v_claim_lease_until;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_activate_v3(p_operation_id uuid, p_lease_token_sha256 text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_authority_ack_v1(uuid, uuid, text, uuid, bigint, text, text, text, text, bigint, timestamp with time zone, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_authority_ack_v1(p_operation_id uuid, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_registry_sequence bigint, p_verified_at timestamp with time zone, p_expected_revision bigint) RETURNS TABLE(operation_id uuid, state text, revision bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    operation platform.tenancy_onboarding_operations%ROWTYPE;
    existing platform.tenancy_onboarding_authority_acks%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_verified_at > now_at THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'authority acknowledgement denied';
    END IF;
    SELECT * INTO operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR operation.deployment_mode <> 'saas' THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'SaaS onboarding operation required';
    END IF;
    SELECT * INTO existing
    FROM platform.tenancy_onboarding_authority_acks AS ack
    WHERE ack.operation_id = p_operation_id;
    IF FOUND THEN
        IF existing.registry_binding_id IS DISTINCT FROM p_registry_binding_id
           OR existing.scope_kind IS DISTINCT FROM p_scope_kind
           OR existing.scope_id IS DISTINCT FROM p_scope_id
           OR existing.generation IS DISTINCT FROM p_generation
           OR existing.previous_head_sha256 IS DISTINCT FROM p_previous_head_sha256
           OR existing.state_sha256 IS DISTINCT FROM p_state_sha256
           OR existing.proposal_sha256 IS DISTINCT FROM p_proposal_sha256
           OR existing.ack_sha256 IS DISTINCT FROM p_ack_sha256
           OR existing.registry_sequence IS DISTINCT FROM p_registry_sequence THEN
            RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'authority acknowledgement CAS conflict';
        END IF;
        RETURN QUERY SELECT operation.operation_id, operation.state,
            operation.revision, operation.updated_at;
        RETURN;
    END IF;
    IF operation.revision <> p_expected_revision OR operation.state <> 'authority_pending'
       OR operation.registry_binding_id IS DISTINCT FROM p_registry_binding_id
       OR operation.authority_scope_kind IS DISTINCT FROM p_scope_kind
       OR operation.authority_scope_id IS DISTINCT FROM p_scope_id
       OR operation.authority_generation IS DISTINCT FROM p_generation
       OR operation.authority_previous_head_sha256 IS DISTINCT FROM p_previous_head_sha256
       OR operation.authority_state_sha256 IS DISTINCT FROM p_state_sha256
       OR operation.authority_proposal_sha256 IS DISTINCT FROM p_proposal_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'authority plan CAS conflict';
    END IF;
    PERFORM 1 FROM platform.tenancy_onboarding_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id
      AND receipt.receipt_kind = 'migration_completed';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'migration receipt required';
    END IF;
    INSERT INTO platform.tenancy_onboarding_authority_acks (
        operation_id, registry_binding_id, scope_kind, scope_id, generation,
        previous_head_sha256, state_sha256, proposal_sha256, ack_sha256,
        registry_sequence, verified_at
    ) VALUES (p_operation_id, p_registry_binding_id, p_scope_kind, p_scope_id,
        p_generation, p_previous_head_sha256, p_state_sha256, p_proposal_sha256,
        p_ack_sha256, p_registry_sequence, p_verified_at);
    UPDATE platform.tenancy_onboarding_operations
    SET state = 'authority_acknowledged', revision = operation.revision + 1,
        updated_at = now_at
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id;
    RETURN QUERY SELECT p_operation_id, 'authority_acknowledged'::text,
        operation.revision + 1, now_at;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_authority_ack_v1(p_operation_id uuid, p_registry_binding_id uuid, p_scope_kind text, p_scope_id uuid, p_generation bigint, p_previous_head_sha256 text, p_state_sha256 text, p_proposal_sha256 text, p_ack_sha256 text, p_registry_sequence bigint, p_verified_at timestamp with time zone, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_claim_v1(uuid, uuid, text, text, bigint, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_claim_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_owner text, p_lease_token_sha256 text, p_expected_revision bigint, p_lease_seconds integer) RETURNS TABLE(operation_id uuid, attempt_id uuid, attempt_number bigint, revision bigint, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    operation platform.tenancy_onboarding_operations%ROWTYPE;
    lease platform.tenancy_onboarding_leases%ROWTYPE;
    next_attempt bigint;
    now_at timestamptz := pg_catalog.statement_timestamp();
    expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_lease_seconds < 1 OR p_lease_seconds > 300 THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'onboarding claim denied';
    END IF;
    SELECT * INTO operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR operation.revision <> p_expected_revision
       OR operation.state IN ('succeeded', 'fenced') THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'onboarding claim revision conflict';
    END IF;
    SELECT * INTO lease
    FROM platform.tenancy_onboarding_leases AS current_lease
    WHERE current_lease.operation_id = p_operation_id
    FOR UPDATE;
    IF FOUND AND lease.lease_until > now_at THEN
        IF lease.attempt_id = p_attempt_id
           AND lease.lease_token_sha256 = p_lease_token_sha256
           AND lease.lease_owner = p_lease_owner THEN
            SELECT attempt.attempt_number INTO next_attempt
            FROM platform.tenancy_onboarding_attempts AS attempt
            WHERE attempt.attempt_id = lease.attempt_id;
            RETURN QUERY SELECT p_operation_id, p_attempt_id, next_attempt,
                operation.revision, lease.lease_until;
            RETURN;
        END IF;
        RAISE EXCEPTION USING ERRCODE = '55P03', MESSAGE = 'onboarding lease is held';
    END IF;
    IF FOUND THEN
        UPDATE platform.tenancy_onboarding_attempts
        SET outcome = 'expired', finished_at = now_at
        WHERE attempt_id = lease.attempt_id AND outcome = 'active';
        DELETE FROM platform.tenancy_onboarding_leases
        WHERE operation_id = p_operation_id;
    END IF;
    SELECT COALESCE(MAX(attempt.attempt_number), 0) + 1 INTO next_attempt
    FROM platform.tenancy_onboarding_attempts AS attempt
    WHERE attempt.operation_id = p_operation_id;
    expires_at := now_at + pg_catalog.make_interval(secs => p_lease_seconds);
    INSERT INTO platform.tenancy_onboarding_attempts (
        attempt_id, operation_id, attempt_number, outcome, started_at
    ) VALUES (p_attempt_id, p_operation_id, next_attempt, 'active', now_at);
    INSERT INTO platform.tenancy_onboarding_leases (
        operation_id, attempt_id, lease_owner, lease_token_sha256,
        lease_until, heartbeat_at, revision
    ) VALUES (p_operation_id, p_attempt_id, p_lease_owner,
        p_lease_token_sha256, expires_at, now_at, operation.revision + 1);
    UPDATE platform.tenancy_onboarding_operations
    SET state = 'migrating', revision = operation.revision + 1, updated_at = now_at
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id;
    RETURN QUERY SELECT p_operation_id, p_attempt_id, next_attempt,
        operation.revision + 1, expires_at;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_claim_v1(p_operation_id uuid, p_attempt_id uuid, p_lease_owner text, p_lease_token_sha256 text, p_expected_revision bigint, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_claim_v2(uuid, uuid, text, text, bigint, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_claim_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_owner text, p_lease_token_sha256 text, p_expected_revision bigint, p_lease_seconds integer) RETURNS TABLE(operation_id uuid, attempt_id uuid, attempt_number bigint, revision bigint, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    operation platform.tenancy_onboarding_operations%ROWTYPE;
    lease platform.tenancy_onboarding_leases%ROWTYPE;
    next_attempt bigint;
    next_state text;
    now_at timestamptz := pg_catalog.statement_timestamp();
    expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_lease_seconds < 1 OR p_lease_seconds > 300 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'onboarding claim denied';
    END IF;
    SELECT * INTO operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR operation.revision <> p_expected_revision
       OR operation.state NOT IN ('accepted', 'migrating', 'migration_ready',
            'authority_pending', 'authority_acknowledged') THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'onboarding claim revision conflict';
    END IF;
    SELECT * INTO lease
    FROM platform.tenancy_onboarding_leases AS current_lease
    WHERE current_lease.operation_id = p_operation_id
    FOR UPDATE;
    IF FOUND AND lease.lease_until > now_at THEN
        IF lease.attempt_id = p_attempt_id
           AND lease.lease_token_sha256 = p_lease_token_sha256
           AND lease.lease_owner = p_lease_owner THEN
            expires_at := now_at + pg_catalog.make_interval(secs => p_lease_seconds);
            UPDATE platform.tenancy_onboarding_leases
            SET lease_until = expires_at, heartbeat_at = now_at,
                revision = operation.revision
            WHERE tenancy_onboarding_leases.operation_id = p_operation_id;
            SELECT attempt.attempt_number INTO next_attempt
            FROM platform.tenancy_onboarding_attempts AS attempt
            WHERE attempt.attempt_id = lease.attempt_id;
            RETURN QUERY SELECT p_operation_id, p_attempt_id, next_attempt,
                operation.revision, expires_at;
            RETURN;
        END IF;
        RAISE EXCEPTION USING ERRCODE = '55P03',
            MESSAGE = 'onboarding lease is held';
    END IF;
    IF FOUND THEN
        UPDATE platform.tenancy_onboarding_attempts AS expired_attempt
        SET outcome = 'expired', finished_at = now_at
        WHERE expired_attempt.attempt_id = lease.attempt_id
          AND expired_attempt.outcome = 'active';
        DELETE FROM platform.tenancy_onboarding_leases
        WHERE tenancy_onboarding_leases.operation_id = p_operation_id;
    END IF;
    SELECT COALESCE(MAX(attempt.attempt_number), 0) + 1 INTO next_attempt
    FROM platform.tenancy_onboarding_attempts AS attempt
    WHERE attempt.operation_id = p_operation_id;
    expires_at := now_at + pg_catalog.make_interval(secs => p_lease_seconds);
    INSERT INTO platform.tenancy_onboarding_attempts (
        attempt_id, operation_id, attempt_number, outcome, started_at
    ) VALUES (p_attempt_id, p_operation_id, next_attempt, 'active', now_at);
    INSERT INTO platform.tenancy_onboarding_leases (
        operation_id, attempt_id, lease_owner, lease_token_sha256,
        lease_until, heartbeat_at, revision
    ) VALUES (p_operation_id, p_attempt_id, p_lease_owner,
        p_lease_token_sha256, expires_at, now_at, operation.revision + 1);
    next_state := CASE operation.state WHEN 'accepted' THEN 'migrating'
        ELSE operation.state END;
    UPDATE platform.tenancy_onboarding_operations
    SET state = next_state, revision = operation.revision + 1, updated_at = now_at
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id;
    RETURN QUERY SELECT p_operation_id, p_attempt_id, next_attempt,
        operation.revision + 1, expires_at;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_claim_v2(p_operation_id uuid, p_attempt_id uuid, p_lease_owner text, p_lease_token_sha256 text, p_expected_revision bigint, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_complete_v1(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_complete_v1(p_operation_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text, p_expected_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    operation platform.tenancy_onboarding_operations%ROWTYPE;
    lease platform.tenancy_onboarding_leases%ROWTYPE;
    existing platform.tenancy_onboarding_receipts%ROWTYPE;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'tenant activation completion denied';
    END IF;
    SELECT * INTO operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'onboarding operation missing';
    END IF;
    SELECT * INTO existing
    FROM platform.tenancy_onboarding_receipts AS receipt
    WHERE receipt.receipt_id = p_receipt_id;
    IF FOUND THEN
        IF operation.state <> 'succeeded'
           OR existing.operation_id IS DISTINCT FROM p_operation_id
           OR existing.receipt_kind <> 'activation_completed'
           OR existing.receipt_sha256 IS DISTINCT FROM p_receipt_sha256
           OR existing.evidence_sha256 IS DISTINCT FROM p_evidence_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'activation completion replay conflict';
        END IF;
        RETURN;
    END IF;
    IF operation.state <> 'finalizing' OR operation.revision <> p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'activation completion revision conflict';
    END IF;
    SELECT * INTO lease
    FROM platform.tenancy_onboarding_leases AS current_lease
    WHERE current_lease.operation_id = p_operation_id
      AND current_lease.lease_until > now_at
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'active activation lease required';
    END IF;
    INSERT INTO platform.tenancy_onboarding_receipts (
        receipt_id, operation_id, attempt_id, receipt_kind,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (p_receipt_id, p_operation_id, lease.attempt_id,
        'activation_completed', p_receipt_sha256, p_evidence_sha256, now_at);
    UPDATE platform.tenancy_onboarding_attempts
    SET outcome = 'completed', finished_at = now_at
    WHERE attempt_id = lease.attempt_id AND outcome = 'active';
    DELETE FROM platform.tenancy_onboarding_leases WHERE operation_id = p_operation_id;
    UPDATE platform.tenancy_onboarding_operations
    SET state = 'succeeded', revision = operation.revision + 1, updated_at = now_at
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_complete_v1(p_operation_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_complete_v2(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_complete_v2(p_operation_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text, p_expected_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_artifact_id uuid;
BEGIN
    SELECT * INTO v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR NOT platform.tenancy_activation_step_assert_v1(
        p_operation_id, 'activation.complete'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation completion capability required';
    END IF;
    IF v_operation.operation_kind = 'environment_initialize'
       AND v_operation.deployment_mode = 'onpremise' THEN
        IF v_operation.authority_generation IS DISTINCT FROM 0
           OR v_operation.authority_scope_kind IS DISTINCT FROM 'environment'
           OR NOT platform.tenancy_activation_step_consume_v1(
               p_operation_id,
               'platformauthority.pin_protected_authority_head'
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '42501',
                MESSAGE = 'on-premise authority no-op capability required';
        END IF;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.tenancy_activation_step_capabilities AS capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id()
          AND capability.operation_id = p_operation_id
          AND capability.command_key <> 'activation.complete'
    ) OR EXISTS (
        SELECT 1
        FROM platform.tenancy_activation_command_capabilities AS capability
        WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
          AND capability.transaction_id = pg_catalog.pg_current_xact_id()
          AND capability.operation_id = p_operation_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'tenant activation has incomplete command capabilities';
    END IF;
    IF NOT platform.platform_async_installation_activation_evidence_assert_v1(
        p_operation_id, NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'installation activation event evidence is unavailable';
    END IF;
    IF v_operation.operation_kind = 'saas_customer_tenant_provision' THEN
        SELECT outcome.setup_artifact_id INTO v_artifact_id
        FROM platform.tenancy_customer_provisioning_outcomes AS outcome
        WHERE outcome.operation_id = p_operation_id;
        IF v_artifact_id IS NULL OR NOT
            platform.platform_async_installation_activation_evidence_assert_v1(
                p_operation_id, v_artifact_id
            )
        THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'initial admin delivery evidence is unavailable';
        END IF;
    END IF;
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id, 'activation.complete'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'tenant activation completion capability consume failed';
    END IF;
    PERFORM platform.tenancy_onboarding_complete_v1(
        p_operation_id, p_receipt_id, p_receipt_sha256,
        p_evidence_sha256, p_expected_revision
    );
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_complete_v2(p_operation_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_reconcile_v1(uuid, uuid, text, text, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_reconcile_v1(p_operation_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text, p_expected_revision bigint) RETURNS TABLE(operation_id uuid, state text, revision bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    operation platform.tenancy_onboarding_operations%ROWTYPE;
    existing platform.tenancy_onboarding_receipts%ROWTYPE;
    current_lease platform.tenancy_onboarding_leases%ROWTYPE;
    latest_attempt_id uuid;
    next_state text;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'onboarding reconcile denied';
    END IF;
    SELECT * INTO operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'onboarding operation missing';
    END IF;
    SELECT * INTO existing
    FROM platform.tenancy_onboarding_receipts AS receipt
    WHERE receipt.receipt_id = p_receipt_id;
    IF FOUND THEN
        IF existing.operation_id IS DISTINCT FROM p_operation_id
           OR existing.receipt_kind <> 'ambiguous_reconciled'
           OR existing.receipt_sha256 IS DISTINCT FROM p_receipt_sha256
           OR existing.evidence_sha256 IS DISTINCT FROM p_evidence_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'reconcile receipt replay conflict';
        END IF;
        RETURN QUERY SELECT operation.operation_id, operation.state,
            operation.revision, operation.updated_at;
        RETURN;
    END IF;
    IF operation.revision <> p_expected_revision OR operation.state = 'fenced' THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'onboarding reconcile revision conflict';
    END IF;
    SELECT * INTO current_lease
    FROM platform.tenancy_onboarding_leases AS lease
    WHERE lease.operation_id = p_operation_id
    FOR UPDATE;
    IF FOUND AND current_lease.lease_until <= now_at THEN
        UPDATE platform.tenancy_onboarding_attempts
        SET outcome = 'ambiguous', finished_at = now_at
        WHERE attempt_id = current_lease.attempt_id AND outcome = 'active';
        DELETE FROM platform.tenancy_onboarding_leases AS expired_lease
        WHERE expired_lease.operation_id = p_operation_id;
    ELSIF FOUND AND current_lease.lease_until > now_at THEN
        RAISE EXCEPTION USING ERRCODE = '55P03', MESSAGE = 'active lease cannot be reconciled';
    END IF;
    SELECT attempt.attempt_id INTO latest_attempt_id
    FROM platform.tenancy_onboarding_attempts AS attempt
    WHERE attempt.operation_id = p_operation_id
    ORDER BY attempt.attempt_number DESC LIMIT 1;
    IF latest_attempt_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'onboarding attempt required';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.tenancy_onboarding_receipts AS receipt
        WHERE receipt.operation_id = p_operation_id
          AND receipt.receipt_kind = 'activation_completed') THEN
        next_state := 'succeeded';
    ELSIF EXISTS (SELECT 1 FROM platform.tenancy_onboarding_authority_acks AS ack
        WHERE ack.operation_id = p_operation_id) THEN
        next_state := 'authority_acknowledged';
    ELSIF EXISTS (SELECT 1 FROM platform.tenancy_onboarding_receipts AS receipt
        WHERE receipt.operation_id = p_operation_id
          AND receipt.receipt_kind = 'migration_completed') THEN
        next_state := CASE operation.deployment_mode
            WHEN 'saas' THEN 'authority_pending' ELSE 'migration_ready' END;
    ELSE
        next_state := 'accepted';
    END IF;
    INSERT INTO platform.tenancy_onboarding_receipts (
        receipt_id, operation_id, attempt_id, receipt_kind,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (p_receipt_id, p_operation_id, latest_attempt_id,
        'ambiguous_reconciled', p_receipt_sha256, p_evidence_sha256, now_at);
    UPDATE platform.tenancy_onboarding_operations
    SET state = next_state, revision = operation.revision + 1, updated_at = now_at
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id;
    RETURN QUERY SELECT p_operation_id, next_state, operation.revision + 1, now_at;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_reconcile_v1(p_operation_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: tenancy_onboarding_record_v1(uuid, uuid, uuid, text, text, text, timestamp with time zone, bigint); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_onboarding_record_v1(p_receipt_id uuid, p_operation_id uuid, p_attempt_id uuid, p_receipt_kind text, p_receipt_sha256 text, p_evidence_sha256 text, p_occurred_at timestamp with time zone, p_expected_revision bigint) RETURNS TABLE(operation_id uuid, state text, revision bigint, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    operation platform.tenancy_onboarding_operations%ROWTYPE;
    existing platform.tenancy_onboarding_receipts%ROWTYPE;
    next_state text;
    now_at timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_receipt_kind NOT IN ('migration_claim_ready', 'migration_completed', 'failure')
       OR p_occurred_at > now_at THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'onboarding receipt denied';
    END IF;
    SELECT * INTO operation
    FROM platform.tenancy_onboarding_operations AS candidate
    WHERE candidate.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'onboarding operation missing';
    END IF;
    SELECT * INTO existing
    FROM platform.tenancy_onboarding_receipts AS receipt
    WHERE receipt.receipt_id = p_receipt_id;
    IF FOUND THEN
        IF existing.operation_id IS DISTINCT FROM p_operation_id
           OR existing.attempt_id IS DISTINCT FROM p_attempt_id
           OR existing.receipt_kind IS DISTINCT FROM p_receipt_kind
           OR existing.receipt_sha256 IS DISTINCT FROM p_receipt_sha256
           OR existing.evidence_sha256 IS DISTINCT FROM p_evidence_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'onboarding receipt replay conflict';
        END IF;
        RETURN QUERY SELECT operation.operation_id, operation.state,
            operation.revision, operation.updated_at;
        RETURN;
    END IF;
    IF operation.revision <> p_expected_revision OR operation.state <> 'migrating' THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'onboarding receipt revision conflict';
    END IF;
    PERFORM 1 FROM platform.tenancy_onboarding_leases AS lease
    WHERE lease.operation_id = p_operation_id AND lease.attempt_id = p_attempt_id
      AND lease.lease_until > now_at
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'active onboarding lease required';
    END IF;
    INSERT INTO platform.tenancy_onboarding_receipts (
        receipt_id, operation_id, attempt_id, receipt_kind,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (p_receipt_id, p_operation_id, p_attempt_id, p_receipt_kind,
        p_receipt_sha256, p_evidence_sha256, p_occurred_at);
    next_state := CASE p_receipt_kind
        WHEN 'migration_completed' THEN CASE operation.deployment_mode
            WHEN 'saas' THEN 'authority_pending' ELSE 'migration_ready' END
        WHEN 'failure' THEN 'failed'
        ELSE 'migrating'
    END;
    UPDATE platform.tenancy_onboarding_operations
    SET state = next_state, revision = operation.revision + 1, updated_at = now_at
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id;
    IF p_receipt_kind = 'failure' THEN
        UPDATE platform.tenancy_onboarding_attempts
        SET outcome = 'failed', finished_at = now_at
        WHERE attempt_id = p_attempt_id AND outcome = 'active';
        DELETE FROM platform.tenancy_onboarding_leases WHERE operation_id = p_operation_id;
    END IF;
    RETURN QUERY SELECT p_operation_id, next_state, operation.revision + 1, now_at;
END;
$$;


ALTER FUNCTION platform.tenancy_onboarding_record_v1(p_receipt_id uuid, p_operation_id uuid, p_attempt_id uuid, p_receipt_kind text, p_receipt_sha256 text, p_evidence_sha256 text, p_occurred_at timestamp with time zone, p_expected_revision bigint) OWNER TO harpy_owner;

