--
-- Name: tenancy_settings_read_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_settings_read_v1(p_tenant_id uuid) RETURNS TABLE(id uuid, name text, slug text, status text, settings_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Tenant settings read denied';
    END IF;
    RETURN QUERY SELECT tenant.id, tenant.name::text, tenant.slug::text,
        tenant.status::text, tenant.settings_revision, tenant.created_at,
        tenant.updated_at
    FROM platform.tenants AS tenant
    WHERE tenant.id=p_tenant_id AND tenant.deleted_at IS NULL;
END;
$$;


ALTER FUNCTION platform.tenancy_settings_read_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_settings_update_v1(uuid, text, bigint, text, bytea); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_settings_update_v1(p_tenant_id uuid, p_name text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea) RETURNS TABLE(result_revision bigint, replay boolean, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_current bigint;
    v_digest bytea;
    v_expected bigint;
    v_result bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_tenant_id IS NULL OR
       p_expected_revision < 1 OR p_request_sha256 IS NULL OR
       pg_catalog.length(p_request_sha256) <> 32 OR p_idempotency_key IS NULL OR
       p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR
       (p_name IS NOT NULL AND (p_name <> pg_catalog.btrim(p_name) OR
        pg_catalog.char_length(p_name) NOT BETWEEN 1 AND 255)) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Tenant settings update invalid';
    END IF;
    SELECT receipt.request_sha256, receipt.expected_revision, receipt.result_revision
      INTO v_digest, v_expected, v_result
    FROM platform.tenancy_settings_operation_receipts AS receipt
    WHERE receipt.tenant_id=p_tenant_id AND receipt.idempotency_key=p_idempotency_key;
    IF FOUND THEN
        RETURN QUERY SELECT v_result,
            v_digest=p_request_sha256 AND v_expected=p_expected_revision,
            CASE WHEN v_digest=p_request_sha256 AND v_expected=p_expected_revision
                 THEN 'replay' ELSE 'idempotency_conflict' END;
        RETURN;
    END IF;
    SELECT tenant.settings_revision INTO v_current
    FROM platform.tenants AS tenant
    WHERE tenant.id=p_tenant_id AND tenant.deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT 0::bigint, false, 'not_found'::text;
        RETURN;
    END IF;
    SELECT receipt.request_sha256, receipt.expected_revision, receipt.result_revision
      INTO v_digest, v_expected, v_result
    FROM platform.tenancy_settings_operation_receipts AS receipt
    WHERE receipt.tenant_id=p_tenant_id AND receipt.idempotency_key=p_idempotency_key;
    IF FOUND THEN
        RETURN QUERY SELECT v_result,
            v_digest=p_request_sha256 AND v_expected=p_expected_revision,
            CASE WHEN v_digest=p_request_sha256 AND v_expected=p_expected_revision
                 THEN 'replay' ELSE 'idempotency_conflict' END;
        RETURN;
    END IF;
    IF v_current <> p_expected_revision THEN
        RETURN QUERY SELECT v_current, false, 'revision_conflict'::text;
        RETURN;
    END IF;
    UPDATE platform.tenants AS tenant SET name=COALESCE(p_name,tenant.name),
        settings_revision=tenant.settings_revision+1,
        updated_at=pg_catalog.transaction_timestamp()
    WHERE tenant.id=p_tenant_id RETURNING tenant.settings_revision INTO v_result;
    INSERT INTO platform.tenancy_settings_operation_receipts(
        tenant_id,idempotency_key,request_sha256,expected_revision,
        result_revision,created_at
    ) VALUES (p_tenant_id,p_idempotency_key,p_request_sha256,
        p_expected_revision,v_result,pg_catalog.transaction_timestamp());
    RETURN QUERY SELECT v_result, false, 'applied'::text;
END;
$_$;


ALTER FUNCTION platform.tenancy_settings_update_v1(p_tenant_id uuid, p_name text, p_expected_revision bigint, p_idempotency_key text, p_request_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_claim_v1(uuid, uuid, uuid, uuid, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_claim_v1(p_profile_instance_id uuid, p_lease_id uuid, p_migration_run_id uuid, p_expiry_receipt_id uuid, p_lease_seconds integer) RETURNS TABLE(job_id uuid, operation_id uuid, tenant_id uuid, schema_name text, step_plan_sha256 text, origin text, attempt integer, migration_run_id uuid, previous_run_id uuid, lease_id uuid, profile_instance_id uuid, release_id uuid, environment_id uuid, deployment_mode text, runtime_generation bigint, database_generation bigint, migration_manifest_sha256 text, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_ready platform.tenancy_tenant_migration_executor_readiness%ROWTYPE;
    v_job platform.tenancy_tenant_migration_jobs%ROWTYPE;
    v_previous_run_id uuid;
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_attempt integer;
    v_digest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='tenant migration claim authority is denied';
    END IF;
    IF p_profile_instance_id IS NULL OR p_lease_id IS NULL OR
       p_migration_run_id IS NULL OR p_expiry_receipt_id IS NULL OR
       p_lease_seconds NOT BETWEEN 30 AND 300 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='tenant migration claim request is invalid';
    END IF;

    SELECT ready.* INTO v_ready
    FROM platform.tenancy_tenant_migration_executor_readiness AS ready
    JOIN platform.release_generations AS release_row
      ON release_row.environment_id=ready.environment_id
     AND release_row.release_id=ready.release_id
     AND release_row.runtime_generation=ready.runtime_generation
     AND release_row.database_generation=ready.database_generation
     AND release_row.migration_manifest_sha256=ready.migration_manifest_sha256
    JOIN platform.schema_contracts AS contract
      ON contract.component='core' AND contract.status='ready'
     AND contract.verified_run_id=release_row.migration_run_id
    WHERE ready.profile_instance_id=p_profile_instance_id
      AND ready.state='active' AND ready.ready_until>v_now
    FOR SHARE OF ready,release_row,contract;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='tenant migration executor is not claim ready';
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.tenancy_deployment_policy AS policy
        WHERE policy.environment_id IS DISTINCT FROM v_ready.environment_id
           OR policy.deployment_mode IS DISTINCT FROM v_ready.deployment_mode
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='tenant migration deployment policy conflicts';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.tenancy_deployment_policy) THEN
        RETURN;
    END IF;

    UPDATE platform.tenancy_tenant_migration_jobs AS exhausted
    SET state='fenced',error_code='attempt_limit_exhausted',
        completed_at=v_now,updated_at=v_now
    WHERE exhausted.state='failed'
      AND exhausted.release_id=v_ready.release_id
      AND exhausted.environment_id=v_ready.environment_id
      AND exhausted.runtime_generation=v_ready.runtime_generation
      AND exhausted.database_generation=v_ready.database_generation
      AND exhausted.migration_manifest_sha256=v_ready.migration_manifest_sha256
      AND (
          SELECT pg_catalog.count(*)
          FROM platform.tenancy_tenant_migration_attempts AS attempt_row
          JOIN platform.tenancy_tenant_migration_executor_readiness AS profile
            ON profile.profile_instance_id=attempt_row.profile_instance_id
          WHERE attempt_row.job_id=exhausted.job_id
            AND profile.release_id=v_ready.release_id
            AND profile.runtime_generation=v_ready.runtime_generation
            AND profile.database_generation=v_ready.database_generation
            AND profile.migration_manifest_sha256=
                v_ready.migration_manifest_sha256
      )>=8;

    SELECT candidate.* INTO v_job
    FROM platform.tenancy_tenant_migration_jobs AS candidate
    WHERE (candidate.state IN ('pending','failed') OR (
        candidate.state='running' AND EXISTS (
            SELECT 1 FROM platform.tenancy_tenant_migration_attempts AS prior
            WHERE prior.job_id=candidate.job_id
              AND prior.attempt=candidate.current_attempt
              AND prior.state='running' AND prior.lease_until<=v_now
        )
    ))
      AND candidate.environment_id=v_ready.environment_id
      AND candidate.deployment_mode=v_ready.deployment_mode
      AND (
        ROW(candidate.release_id,candidate.runtime_generation,
            candidate.database_generation,candidate.migration_manifest_sha256)
        IS DISTINCT FROM ROW(v_ready.release_id,v_ready.runtime_generation,
            v_ready.database_generation,v_ready.migration_manifest_sha256)
        OR (
          SELECT pg_catalog.count(*)
          FROM platform.tenancy_tenant_migration_attempts AS attempt_row
          JOIN platform.tenancy_tenant_migration_executor_readiness AS profile
            ON profile.profile_instance_id=attempt_row.profile_instance_id
          WHERE attempt_row.job_id=candidate.job_id
            AND profile.release_id=v_ready.release_id
            AND profile.runtime_generation=v_ready.runtime_generation
            AND profile.database_generation=v_ready.database_generation
            AND profile.migration_manifest_sha256=
                v_ready.migration_manifest_sha256
        )<8
      )
    ORDER BY candidate.created_at,candidate.job_id
    FOR UPDATE SKIP LOCKED LIMIT 1;
    IF NOT FOUND THEN RETURN; END IF;

    IF v_job.state='running' THEN
        SELECT prior.migration_run_id INTO v_previous_run_id
        FROM platform.tenancy_tenant_migration_attempts AS prior
        WHERE prior.job_id=v_job.job_id AND prior.attempt=v_job.current_attempt
        FOR UPDATE;
        UPDATE platform.tenancy_tenant_migration_attempts
        SET state='failed',finished_at=v_now,error_code='lease_expired'
        WHERE tenancy_tenant_migration_attempts.job_id=v_job.job_id
          AND tenancy_tenant_migration_attempts.attempt=v_job.current_attempt;
        v_digest:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            v_job.job_id::text||':'||v_job.current_attempt::text||
            ':lease_expired','UTF8')),'hex');
        INSERT INTO platform.tenancy_tenant_migration_receipts (
            receipt_id,job_id,attempt,receipt_kind,migration_run_id,
            receipt_sha256,evidence_sha256,occurred_at
        ) VALUES (
            p_expiry_receipt_id,v_job.job_id,v_job.current_attempt,
            'failure',v_previous_run_id,v_digest,v_digest,v_now
        ) ON CONFLICT ON CONSTRAINT
            tenancy_tenant_migration_receipt_attempt_kind_uq DO NOTHING;
    END IF;

    v_attempt:=v_job.current_attempt+1;
    UPDATE platform.tenancy_tenant_migration_jobs
    SET release_id=v_ready.release_id,
        runtime_generation=v_ready.runtime_generation,
        database_generation=v_ready.database_generation,
        migration_manifest_sha256=v_ready.migration_manifest_sha256,
        state='running',current_attempt=v_attempt,error_code=NULL,
        completed_at=NULL,updated_at=v_now
    WHERE tenancy_tenant_migration_jobs.job_id=v_job.job_id;
    INSERT INTO platform.tenancy_tenant_migration_attempts (
        job_id,attempt,migration_run_id,profile_instance_id,lease_id,
        state,leased_at,heartbeat_at,lease_until
    ) VALUES (
        v_job.job_id,v_attempt,p_migration_run_id,p_profile_instance_id,
        p_lease_id,'running',v_now,v_now,
        v_now+pg_catalog.make_interval(secs=>p_lease_seconds)
    );

    RETURN QUERY SELECT
        v_job.job_id,v_job.operation_id,operation.tenant_id,
        operation.schema_name::text,operation.step_plan_sha256,
        v_job.origin,v_attempt,p_migration_run_id,v_previous_run_id,
        p_lease_id,p_profile_instance_id,v_ready.release_id,
        v_ready.environment_id,v_ready.deployment_mode,
        v_ready.runtime_generation,v_ready.database_generation,
        v_ready.migration_manifest_sha256,
        v_now+pg_catalog.make_interval(secs=>p_lease_seconds)
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id=v_job.operation_id;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_claim_v1(p_profile_instance_id uuid, p_lease_id uuid, p_migration_run_id uuid, p_expiry_receipt_id uuid, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_complete_v1(uuid, integer, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_complete_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) RETURNS TABLE(catalog_sha256 text, requirement_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.tenancy_tenant_migration_jobs%ROWTYPE;
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_run_id uuid;
    v_origin text;
    v_verified boolean;
    v_catalog_sha256 text;
    v_requirement_count integer;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_receipt_id IS NULL OR p_receipt_sha256 !~ '^[0-9a-f]{64}$' OR
       p_evidence_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration completion receipt is invalid';
    END IF;
    SELECT job.* INTO v_job
    FROM platform.tenancy_tenant_migration_jobs AS job
    WHERE job.job_id = p_job_id
    FOR UPDATE;
    IF NOT FOUND OR v_job.state <> 'running' OR
       v_job.current_attempt <> p_attempt THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration completion state is invalid';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = v_job.operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_operation.state <> 'migrating' OR EXISTS (
           SELECT 1 FROM platform.tenants WHERE id = v_operation.tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration completion state is invalid';
    END IF;

    SELECT attempt_row.migration_run_id
    INTO v_run_id
    FROM platform.tenancy_tenant_migration_attempts AS attempt_row
    WHERE attempt_row.job_id = p_job_id AND attempt_row.attempt = p_attempt
      AND attempt_row.profile_instance_id = p_profile_instance_id
      AND attempt_row.lease_id = p_lease_id
      AND attempt_row.state = 'running'
      AND attempt_row.lease_until > v_now
    FOR UPDATE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM platform.tenancy_tenant_migration_receipts AS receipt
        WHERE receipt.job_id = p_job_id
          AND receipt.receipt_kind = 'schema_created'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration completion lease is invalid';
    END IF;

    SELECT run.database_origin INTO v_origin
    FROM platform.migration_runs AS run
    WHERE run.run_id = v_run_id AND run.release_id = v_job.release_id
      AND run.environment_id = v_job.environment_id
      AND run.command = 'tenant_migration_executor'
      AND run.state = 'succeeded'
      AND run.migration_manifest_sha256 = v_job.migration_manifest_sha256;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration run is not complete';
    END IF;

    SELECT verification.verified, verification.catalog_sha256,
           verification.requirement_count
    INTO v_verified, v_catalog_sha256, v_requirement_count
    FROM platform.platform_migrator_verify_new_tenant_v1(
        v_job.release_id, v_job.environment_id, v_origin,
        v_operation.tenant_id, v_job.migration_manifest_sha256
    ) AS verification;
    IF NOT v_verified THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration checkpoints are incomplete';
    END IF;

    INSERT INTO platform.tenancy_tenant_migration_receipts (
        receipt_id, job_id, attempt, receipt_kind, migration_run_id,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (
        p_receipt_id, p_job_id, p_attempt, 'migration_completed', v_run_id,
        p_receipt_sha256, p_evidence_sha256, v_now
    );
    UPDATE platform.tenancy_tenant_migration_attempts
    SET state = 'succeeded', finished_at = v_now
    WHERE job_id = p_job_id AND attempt = p_attempt;
    UPDATE platform.tenancy_tenant_migration_jobs
    SET state = 'succeeded', completed_at = v_now, updated_at = v_now
    WHERE job_id = p_job_id;
    UPDATE platform.tenancy_onboarding_operations
    SET state = 'migration_ready', revision = revision + 1, updated_at = v_now
    WHERE operation_id = v_job.operation_id AND state = 'migrating';

    RETURN QUERY SELECT v_catalog_sha256, v_requirement_count;
END;
$_$;


ALTER FUNCTION platform.tenancy_tenant_migration_complete_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_complete_v2(uuid, integer, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_complete_v2(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) RETURNS TABLE(catalog_sha256 text, requirement_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.tenancy_tenant_migration_jobs%ROWTYPE;
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_run_id uuid;
    v_origin text;
    v_verified boolean;
    v_catalog_sha256 text;
    v_requirement_count integer;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_receipt_id IS NULL OR p_receipt_sha256 !~ '^[0-9a-f]{64}$' OR
       p_evidence_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration completion receipt is invalid';
    END IF;
    SELECT job.* INTO v_job
    FROM platform.tenancy_tenant_migration_jobs AS job
    WHERE job.job_id = p_job_id
    FOR UPDATE;
    IF NOT FOUND OR v_job.state <> 'running' OR
       v_job.current_attempt <> p_attempt THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration completion state is invalid';
    END IF;
    SELECT operation.* INTO v_operation
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = v_job.operation_id
    FOR SHARE;
    IF NOT FOUND OR v_operation.state <> 'migrating' OR EXISTS (
           SELECT 1 FROM platform.tenants WHERE id = v_operation.tenant_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration completion state is invalid';
    END IF;
    SELECT attempt_row.migration_run_id INTO v_run_id
    FROM platform.tenancy_tenant_migration_attempts AS attempt_row
    WHERE attempt_row.job_id = p_job_id AND attempt_row.attempt = p_attempt
      AND attempt_row.profile_instance_id = p_profile_instance_id
      AND attempt_row.lease_id = p_lease_id
      AND attempt_row.state = 'running'
      AND attempt_row.lease_until > v_now
    FOR UPDATE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM platform.tenancy_tenant_migration_receipts AS receipt
        WHERE receipt.job_id = p_job_id
          AND receipt.receipt_kind = 'schema_created'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration completion lease is invalid';
    END IF;
    SELECT run.database_origin INTO v_origin
    FROM platform.migration_runs AS run
    WHERE run.run_id = v_run_id AND run.release_id = v_job.release_id
      AND run.environment_id = v_job.environment_id
      AND run.command = 'tenant_migration_executor'
      AND run.state = 'succeeded'
      AND run.migration_manifest_sha256 = v_job.migration_manifest_sha256;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration run is not complete';
    END IF;
    SELECT verification.verified, verification.catalog_sha256,
           verification.requirement_count
    INTO v_verified, v_catalog_sha256, v_requirement_count
    FROM platform.platform_migrator_verify_new_tenant_v1(
        v_job.release_id, v_job.environment_id, v_origin,
        v_operation.tenant_id, v_job.migration_manifest_sha256
    ) AS verification;
    IF NOT v_verified THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration checkpoints are incomplete';
    END IF;
    INSERT INTO platform.tenancy_tenant_migration_receipts (
        receipt_id, job_id, attempt, receipt_kind, migration_run_id,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (
        p_receipt_id, p_job_id, p_attempt, 'migration_completed', v_run_id,
        p_receipt_sha256, p_evidence_sha256, v_now
    );
    UPDATE platform.tenancy_tenant_migration_attempts
    SET state = 'succeeded', finished_at = v_now
    WHERE job_id = p_job_id AND attempt = p_attempt;
    UPDATE platform.tenancy_tenant_migration_jobs
    SET state = 'succeeded', completed_at = v_now, updated_at = v_now
    WHERE job_id = p_job_id;
    RETURN QUERY SELECT v_catalog_sha256, v_requirement_count;
END;
$_$;


ALTER FUNCTION platform.tenancy_tenant_migration_complete_v2(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_complete_v3(uuid, integer, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_complete_v3(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) RETURNS TABLE(catalog_sha256 text, requirement_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_catalog_sha256 text;
    v_requirement_count integer;
    v_operation_id uuid;
    v_leased_at timestamptz;
    v_attempt_number bigint;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_migrator'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='tenant migration completion authority is denied';
    END IF;
    SELECT completed.catalog_sha256,completed.requirement_count
    INTO v_catalog_sha256,v_requirement_count
    FROM platform.tenancy_tenant_migration_complete_v2(
        p_job_id,p_attempt,p_profile_instance_id,p_lease_id,p_receipt_id,
        p_receipt_sha256,p_evidence_sha256
    ) AS completed;
    SELECT job.operation_id INTO STRICT v_operation_id
    FROM platform.tenancy_tenant_migration_jobs AS job
    WHERE job.job_id=p_job_id AND job.state='succeeded'
    FOR SHARE;
    SELECT attempt.leased_at INTO STRICT v_leased_at
    FROM platform.tenancy_tenant_migration_attempts AS attempt
    WHERE attempt.job_id=p_job_id AND attempt.attempt=p_attempt
      AND attempt.profile_instance_id=p_profile_instance_id
      AND attempt.lease_id=p_lease_id AND attempt.state='succeeded';
    SELECT COALESCE(MAX(attempt.attempt_number),0)+1 INTO v_attempt_number
    FROM platform.tenancy_onboarding_attempts AS attempt
    WHERE attempt.operation_id=v_operation_id;
    INSERT INTO platform.tenancy_onboarding_attempts (
        attempt_id,operation_id,attempt_number,outcome,started_at,finished_at
    ) VALUES (
        p_lease_id,v_operation_id,v_attempt_number,'completed',v_leased_at,v_now
    );
    INSERT INTO platform.tenancy_onboarding_receipts (
        receipt_id,operation_id,attempt_id,receipt_kind,
        receipt_sha256,evidence_sha256,occurred_at
    ) VALUES (
        p_receipt_id,v_operation_id,p_lease_id,'migration_completed',
        p_receipt_sha256,p_evidence_sha256,v_now
    );
    UPDATE platform.tenancy_onboarding_operations AS operation
    SET state=CASE
            WHEN operation.operation_kind='environment_initialize'
             AND operation.deployment_mode='saas' THEN 'authority_pending'
            ELSE 'migration_ready'
        END,
        revision=operation.revision+1,updated_at=v_now
    WHERE operation.operation_id=v_operation_id
      AND operation.operation_kind IN (
          'environment_initialize','saas_customer_tenant_provision'
      )
      AND operation.state='migrating';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='tenant migration onboarding transition is invalid';
    END IF;
    RETURN QUERY SELECT v_catalog_sha256,v_requirement_count;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_complete_v3(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_enqueue_v1(uuid, uuid, uuid, bigint, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_enqueue_v1(p_job_id uuid, p_operation_id uuid, p_release_id uuid, p_runtime_generation bigint, p_database_generation bigint, p_migration_manifest_sha256 text) RETURNS TABLE(job_id uuid, operation_id uuid, state text, tenant_id uuid, schema_name text, step_plan_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_operation platform.tenancy_onboarding_operations%ROWTYPE;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_job_id IS NULL OR p_operation_id IS NULL OR p_release_id IS NULL OR
       p_runtime_generation < 1 OR p_database_generation < 1 OR
       p_migration_manifest_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration enqueue request is invalid';
    END IF;

    SELECT * INTO v_operation
    FROM platform.tenancy_onboarding_operations
    WHERE tenancy_onboarding_operations.operation_id = p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_operation.state NOT IN ('accepted', 'migrating') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'onboarding operation cannot enqueue migration';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM platform.tenancy_tenant_migration_executor_readiness AS ready
        WHERE ready.release_id = p_release_id
          AND ready.environment_id = v_operation.environment_id
          AND ready.deployment_mode = v_operation.deployment_mode
          AND ready.runtime_generation = p_runtime_generation
          AND ready.database_generation = p_database_generation
          AND ready.migration_manifest_sha256 =
              p_migration_manifest_sha256
          AND ready.state = 'active'
          AND ready.ready_until > v_now
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration executor is not claim ready';
    END IF;

    INSERT INTO platform.tenancy_tenant_migration_jobs (
        job_id, operation_id, release_id, environment_id, deployment_mode,
        runtime_generation, database_generation, migration_manifest_sha256,
        state, created_at, updated_at
    ) VALUES (
        p_job_id, p_operation_id, p_release_id, v_operation.environment_id,
        v_operation.deployment_mode, p_runtime_generation,
        p_database_generation, p_migration_manifest_sha256,
        'pending', v_now, v_now
    ) ON CONFLICT ON CONSTRAINT
        tenancy_tenant_migration_jobs_operation_id_key DO NOTHING;

    IF v_operation.state = 'accepted' THEN
        UPDATE platform.tenancy_onboarding_operations AS operation_row
        SET state = 'migrating', revision = operation_row.revision + 1,
            updated_at = v_now
        WHERE operation_row.operation_id = p_operation_id
          AND operation_row.state = 'accepted';
    END IF;

    RETURN QUERY
    SELECT job.job_id, job.operation_id, job.state,
           operation.tenant_id, operation.schema_name::text,
           operation.step_plan_sha256
    FROM platform.tenancy_tenant_migration_jobs AS job
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id = job.operation_id
    WHERE job.operation_id = p_operation_id
      AND job.release_id = p_release_id
      AND job.runtime_generation = p_runtime_generation
      AND job.database_generation = p_database_generation
      AND job.migration_manifest_sha256 = p_migration_manifest_sha256;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration enqueue replay differs';
    END IF;
END;
$_$;


ALTER FUNCTION platform.tenancy_tenant_migration_enqueue_v1(p_job_id uuid, p_operation_id uuid, p_release_id uuid, p_runtime_generation bigint, p_database_generation bigint, p_migration_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_fail_v1(uuid, integer, uuid, uuid, text, text, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_fail_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_outcome text, p_error_code text, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run_id uuid;
    v_receipt_kind text;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_outcome NOT IN ('failed', 'reconcile_required', 'cleanup_required') OR
       p_error_code !~ '^[a-z][a-z0-9_]{2,63}$' OR p_receipt_id IS NULL OR
       p_receipt_sha256 !~ '^[0-9a-f]{64}$' OR
       p_evidence_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration failure receipt is invalid';
    END IF;
    SELECT attempt_row.migration_run_id INTO v_run_id
    FROM platform.tenancy_tenant_migration_jobs AS job
    JOIN platform.tenancy_tenant_migration_attempts AS attempt_row
      ON attempt_row.job_id = job.job_id
     AND attempt_row.attempt = job.current_attempt
    WHERE job.job_id = p_job_id AND job.state = 'running'
      AND job.current_attempt = p_attempt
      AND attempt_row.profile_instance_id = p_profile_instance_id
      AND attempt_row.lease_id = p_lease_id
      AND attempt_row.state = 'running'
    FOR UPDATE OF job, attempt_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration failure lease is stale';
    END IF;

    v_receipt_kind := CASE p_outcome
        WHEN 'failed' THEN 'failure'
        ELSE p_outcome
    END;
    INSERT INTO platform.tenancy_tenant_migration_receipts (
        receipt_id, job_id, attempt, receipt_kind, migration_run_id,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (
        p_receipt_id, p_job_id, p_attempt, v_receipt_kind, v_run_id,
        p_receipt_sha256, p_evidence_sha256, v_now
    );
    UPDATE platform.tenancy_tenant_migration_attempts
    SET state = p_outcome, finished_at = v_now, error_code = p_error_code
    WHERE job_id = p_job_id AND attempt = p_attempt;
    UPDATE platform.tenancy_tenant_migration_jobs
    SET state = p_outcome, error_code = p_error_code,
        completed_at = v_now, updated_at = v_now
    WHERE job_id = p_job_id;
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.tenancy_tenant_migration_fail_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_outcome text, p_error_code text, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_get_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_get_v1(p_operation_id uuid) RETURNS TABLE(job_id uuid, operation_id uuid, state text, tenant_id uuid, schema_name text, step_plan_sha256 text, release_id uuid, runtime_generation bigint, database_generation bigint, migration_manifest_sha256 text, error_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT job.job_id, job.operation_id, job.state,
           operation.tenant_id, operation.schema_name::text,
           operation.step_plan_sha256, job.release_id,
           job.runtime_generation, job.database_generation,
           job.migration_manifest_sha256, job.error_code
    FROM platform.tenancy_tenant_migration_jobs AS job
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id = job.operation_id
    WHERE job.operation_id = p_operation_id;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_get_v1(p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_get_v2(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_get_v2(p_operation_id uuid) RETURNS TABLE(job_id uuid, operation_id uuid, state text, tenant_id uuid, schema_name text, step_plan_sha256 text, release_id uuid, runtime_generation bigint, database_generation bigint, migration_manifest_sha256 text, error_code text, completion_receipt_id uuid, completion_receipt_sha256 text, completion_evidence_sha256 text, completed_at timestamp with time zone, created_at timestamp with time zone, database_now timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT job.job_id, job.operation_id, job.state,
           operation.tenant_id, operation.schema_name::text,
           operation.step_plan_sha256, job.release_id,
           job.runtime_generation, job.database_generation,
           job.migration_manifest_sha256, job.error_code,
           receipt.receipt_id, receipt.receipt_sha256,
           receipt.evidence_sha256,
           CASE WHEN job.state = 'succeeded' THEN job.completed_at END,
           job.created_at,
           pg_catalog.clock_timestamp()
    FROM platform.tenancy_tenant_migration_jobs AS job
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id = job.operation_id
    LEFT JOIN platform.tenancy_tenant_migration_receipts AS receipt
      ON receipt.job_id = job.job_id
     AND receipt.receipt_kind = 'migration_completed'
    WHERE job.operation_id = p_operation_id;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_get_v2(p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_heartbeat_v1(uuid, integer, uuid, uuid, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_heartbeat_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_lease_seconds integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_lease_until timestamptz;
BEGIN
    IF p_job_id IS NULL OR p_attempt NOT BETWEEN 1 AND 8 OR
       p_profile_instance_id IS NULL OR p_lease_id IS NULL OR
       p_lease_seconds NOT BETWEEN 30 AND 300 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration lease heartbeat is invalid';
    END IF;

    UPDATE platform.tenancy_tenant_migration_attempts AS attempt_row
    SET heartbeat_at = v_now,
        lease_until = v_now + pg_catalog.make_interval(secs => p_lease_seconds)
    FROM platform.tenancy_tenant_migration_jobs AS job,
         platform.tenancy_tenant_migration_executor_readiness AS ready
    WHERE attempt_row.job_id = p_job_id
      AND attempt_row.attempt = p_attempt
      AND attempt_row.profile_instance_id = p_profile_instance_id
      AND attempt_row.lease_id = p_lease_id
      AND attempt_row.state = 'running'
      AND attempt_row.lease_until > v_now
      AND job.job_id = attempt_row.job_id
      AND job.state = 'running'
      AND job.current_attempt = attempt_row.attempt
      AND ready.profile_instance_id = p_profile_instance_id
      AND ready.state = 'active'
      AND ready.ready_until > v_now
      AND ready.release_id = job.release_id
      AND ready.environment_id = job.environment_id
      AND ready.runtime_generation = job.runtime_generation
      AND ready.database_generation = job.database_generation
      AND ready.migration_manifest_sha256 = job.migration_manifest_sha256
    RETURNING attempt_row.lease_until INTO v_lease_until;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration lease is stale';
    END IF;
    RETURN v_lease_until;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_heartbeat_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_lease_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_offline_cleanup_record_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_offline_cleanup_record_v1(p_job_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_job platform.tenancy_tenant_migration_jobs%ROWTYPE;
    v_schema_name text;
    v_tenant_id uuid;
    v_run_id uuid;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_job_id IS NULL OR p_receipt_id IS NULL OR
       p_receipt_sha256 !~ '^[0-9a-f]{64}$' OR
       p_evidence_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'offline cleanup receipt is invalid';
    END IF;
    SELECT job.* INTO v_job
    FROM platform.tenancy_tenant_migration_jobs AS job
    WHERE job.job_id = p_job_id
    FOR UPDATE;
    IF NOT FOUND OR v_job.state <> 'cleanup_required' OR EXISTS (
        SELECT 1
        FROM platform.tenancy_tenant_migration_executor_readiness AS ready
        WHERE ready.environment_id = v_job.environment_id
          AND ready.release_id = v_job.release_id
          AND ready.state = 'active' AND ready.ready_until > v_now
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'offline cleanup requires stopped executor';
    END IF;
    SELECT operation.schema_name::text, operation.tenant_id,
           attempt_row.migration_run_id
    INTO v_schema_name, v_tenant_id, v_run_id
    FROM platform.tenancy_onboarding_operations AS operation
    JOIN platform.tenancy_tenant_migration_attempts AS attempt_row
      ON attempt_row.job_id = v_job.job_id
     AND attempt_row.attempt = v_job.current_attempt
    WHERE operation.operation_id = v_job.operation_id;
    IF pg_catalog.to_regnamespace(v_schema_name) IS NOT NULL OR EXISTS (
        SELECT 1 FROM platform.tenants WHERE id = v_tenant_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'offline cleanup has not removed orphan schema';
    END IF;
    INSERT INTO platform.tenancy_tenant_migration_receipts (
        receipt_id, job_id, attempt, receipt_kind, migration_run_id,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (
        p_receipt_id, v_job.job_id, v_job.current_attempt,
        'offline_cleanup_completed', v_run_id,
        p_receipt_sha256, p_evidence_sha256, v_now
    );
    UPDATE platform.tenancy_tenant_migration_jobs
    SET state = 'fenced', error_code = 'offline_cleanup_completed',
        updated_at = v_now
    WHERE job_id = v_job.job_id;
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.tenancy_tenant_migration_offline_cleanup_record_v1(p_job_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_ready_current_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_ready_current_v1() RETURNS TABLE(release_id uuid, environment_id uuid, deployment_mode text, runtime_generation bigint, database_generation bigint, migration_manifest_sha256 text, ready_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT ready.release_id, ready.environment_id, ready.deployment_mode,
           ready.runtime_generation, ready.database_generation,
           ready.migration_manifest_sha256, ready.ready_until
    FROM platform.tenancy_tenant_migration_executor_readiness AS ready
    JOIN platform.tenancy_deployment_policy AS policy
      ON policy.environment_id = ready.environment_id
     AND policy.deployment_mode = ready.deployment_mode
    JOIN platform.release_generations AS release_row
      ON release_row.environment_id = ready.environment_id
     AND release_row.release_id = ready.release_id
     AND release_row.runtime_generation = ready.runtime_generation
     AND release_row.database_generation = ready.database_generation
     AND release_row.migration_manifest_sha256 =
         ready.migration_manifest_sha256
    JOIN platform.schema_contracts AS contract
      ON contract.component = 'core' AND contract.status = 'ready'
     AND contract.verified_run_id = release_row.migration_run_id
    WHERE ready.state = 'active'
      AND ready.ready_until > pg_catalog.clock_timestamp()
    ORDER BY ready.ready_until DESC, ready.profile_instance_id
    LIMIT 1;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_ready_current_v1() OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_ready_heartbeat_v1(uuid, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_ready_heartbeat_v1(p_profile_instance_id uuid, p_ttl_seconds integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_ready_until timestamptz;
BEGIN
    IF p_profile_instance_id IS NULL OR p_ttl_seconds NOT BETWEEN 15 AND 120 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration heartbeat request is invalid';
    END IF;

    UPDATE platform.tenancy_tenant_migration_executor_readiness AS ready
    SET heartbeat_at = v_now,
        ready_until = v_now + pg_catalog.make_interval(secs => p_ttl_seconds)
    FROM platform.release_generations AS release_row,
         platform.schema_contracts AS contract
    WHERE ready.profile_instance_id = p_profile_instance_id
      AND ready.state = 'active'
      AND ready.ready_until > v_now
      AND release_row.environment_id = ready.environment_id
      AND release_row.release_id = ready.release_id
      AND release_row.runtime_generation = ready.runtime_generation
      AND release_row.database_generation = ready.database_generation
      AND release_row.migration_manifest_sha256 =
          ready.migration_manifest_sha256
      AND contract.component = 'core'
      AND contract.status = 'ready'
      AND contract.verified_run_id = release_row.migration_run_id
      AND contract.database_generation = ready.database_generation
      AND contract.migration_manifest_sha256 =
          ready.migration_manifest_sha256
      AND NOT EXISTS (
          SELECT 1
          FROM platform.tenancy_deployment_policy AS policy
          WHERE policy.environment_id IS DISTINCT FROM ready.environment_id
             OR policy.deployment_mode IS DISTINCT FROM ready.deployment_mode
      )
    RETURNING ready.ready_until INTO v_ready_until;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration readiness is stale';
    END IF;
    RETURN v_ready_until;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_ready_heartbeat_v1(p_profile_instance_id uuid, p_ttl_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_ready_register_v1(uuid, uuid, text, bigint, text, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_ready_register_v1(p_profile_instance_id uuid, p_release_id uuid, p_deployment_mode text, p_runtime_generation bigint, p_migration_manifest_sha256 text, p_ttl_seconds integer) RETURNS TABLE(profile_instance_id uuid, release_id uuid, environment_id uuid, deployment_mode text, runtime_generation bigint, database_generation bigint, migration_manifest_sha256 text, ready_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_environment_id uuid;
    v_database_generation bigint;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_profile_instance_id IS NULL OR p_release_id IS NULL OR
       p_deployment_mode NOT IN ('onpremise', 'saas') OR
       p_runtime_generation < 1 OR
       p_migration_manifest_sha256 !~ '^[0-9a-f]{64}$' OR
       p_ttl_seconds NOT BETWEEN 15 AND 120 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration readiness request is invalid';
    END IF;

    SELECT release_row.environment_id, release_row.database_generation
    INTO v_environment_id, v_database_generation
    FROM platform.release_generations AS release_row
    JOIN platform.environment_identity AS identity
      ON identity.environment_id = release_row.environment_id
    JOIN platform.schema_contracts AS contract
      ON contract.component = 'core'
     AND contract.verified_run_id = release_row.migration_run_id
     AND contract.status = 'ready'
     AND contract.database_generation = release_row.database_generation
     AND contract.migration_manifest_sha256 =
         release_row.migration_manifest_sha256
    WHERE release_row.release_id = p_release_id
      AND release_row.runtime_generation = p_runtime_generation
      AND release_row.migration_manifest_sha256 =
          p_migration_manifest_sha256
    FOR SHARE OF release_row, contract;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration release is not current';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM platform.tenancy_deployment_policy AS policy
        WHERE policy.environment_id IS DISTINCT FROM v_environment_id
           OR policy.deployment_mode IS DISTINCT FROM p_deployment_mode
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration deployment policy conflicts';
    END IF;

    INSERT INTO platform.tenancy_tenant_migration_executor_readiness (
        profile_instance_id, release_id, environment_id, deployment_mode,
        runtime_generation, database_generation, migration_manifest_sha256,
        state, ready_until, heartbeat_at, created_at
    ) VALUES (
        p_profile_instance_id, p_release_id, v_environment_id,
        p_deployment_mode, p_runtime_generation, v_database_generation,
        p_migration_manifest_sha256, 'active',
        v_now + pg_catalog.make_interval(secs => p_ttl_seconds), v_now, v_now
    )
    ON CONFLICT ON CONSTRAINT
        tenancy_tenant_migration_executor_readiness_pkey DO UPDATE SET
        heartbeat_at = EXCLUDED.heartbeat_at,
        ready_until = EXCLUDED.ready_until
    WHERE tenancy_tenant_migration_executor_readiness.state = 'active'
      AND tenancy_tenant_migration_executor_readiness.release_id =
          EXCLUDED.release_id
      AND tenancy_tenant_migration_executor_readiness.environment_id =
          EXCLUDED.environment_id
      AND tenancy_tenant_migration_executor_readiness.deployment_mode =
          EXCLUDED.deployment_mode
      AND tenancy_tenant_migration_executor_readiness.runtime_generation =
          EXCLUDED.runtime_generation
      AND tenancy_tenant_migration_executor_readiness.database_generation =
          EXCLUDED.database_generation
      AND tenancy_tenant_migration_executor_readiness.migration_manifest_sha256 =
          EXCLUDED.migration_manifest_sha256;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'tenant migration profile instance cannot be reused';
    END IF;

    RETURN QUERY
    SELECT ready.profile_instance_id, ready.release_id, ready.environment_id,
           ready.deployment_mode, ready.runtime_generation,
           ready.database_generation, ready.migration_manifest_sha256,
           ready.ready_until
    FROM platform.tenancy_tenant_migration_executor_readiness AS ready
    WHERE ready.profile_instance_id = p_profile_instance_id;
END;
$_$;


ALTER FUNCTION platform.tenancy_tenant_migration_ready_register_v1(p_profile_instance_id uuid, p_release_id uuid, p_deployment_mode text, p_runtime_generation bigint, p_migration_manifest_sha256 text, p_ttl_seconds integer) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_ready_retire_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_ready_retire_v1(p_profile_instance_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    UPDATE platform.tenancy_tenant_migration_executor_readiness
    SET state = 'retired', retired_at = v_now
    WHERE profile_instance_id = p_profile_instance_id AND state = 'active';
    RETURN FOUND;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_ready_retire_v1(p_profile_instance_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_schema_inspect_v1(uuid, integer, uuid, uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_schema_inspect_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid) RETURNS TABLE(tenant_id uuid, schema_name text, namespace_exists boolean, schema_receipt_exists boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    RETURN QUERY
    SELECT operation.tenant_id, operation.schema_name::text,
           pg_catalog.to_regnamespace(operation.schema_name::text) IS NOT NULL,
           EXISTS (
               SELECT 1
               FROM platform.tenancy_tenant_migration_receipts AS receipt
               WHERE receipt.job_id = job.job_id
                 AND receipt.receipt_kind = 'schema_created'
           )
    FROM platform.tenancy_tenant_migration_jobs AS job
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id = job.operation_id
    JOIN platform.tenancy_tenant_migration_attempts AS attempt_row
      ON attempt_row.job_id = job.job_id
     AND attempt_row.attempt = job.current_attempt
    WHERE job.job_id = p_job_id AND job.state = 'running'
      AND job.current_attempt = p_attempt
      AND attempt_row.profile_instance_id = p_profile_instance_id
      AND attempt_row.lease_id = p_lease_id
      AND attempt_row.state = 'running'
      AND attempt_row.lease_until > v_now
      AND NOT EXISTS (
          SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = operation.tenant_id
      );
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration schema lease is invalid';
    END IF;
END;
$$;


ALTER FUNCTION platform.tenancy_tenant_migration_schema_inspect_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid) OWNER TO harpy_owner;

--
-- Name: tenancy_tenant_migration_schema_record_v1(uuid, integer, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_tenant_migration_schema_record_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_run_id uuid;
    v_schema_name text;
    v_tenant_id uuid;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF p_receipt_id IS NULL OR p_receipt_sha256 !~ '^[0-9a-f]{64}$' OR
       p_evidence_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'tenant migration schema receipt is invalid';
    END IF;
    SELECT attempt_row.migration_run_id, operation.schema_name::text,
           operation.tenant_id
    INTO v_run_id, v_schema_name, v_tenant_id
    FROM platform.tenancy_tenant_migration_jobs AS job
    JOIN platform.tenancy_onboarding_operations AS operation
      ON operation.operation_id = job.operation_id
    JOIN platform.tenancy_tenant_migration_attempts AS attempt_row
      ON attempt_row.job_id = job.job_id
     AND attempt_row.attempt = job.current_attempt
    WHERE job.job_id = p_job_id AND job.state = 'running'
      AND job.current_attempt = p_attempt
      AND attempt_row.profile_instance_id = p_profile_instance_id
      AND attempt_row.lease_id = p_lease_id
      AND attempt_row.state = 'running'
      AND attempt_row.lease_until > v_now
    FOR UPDATE OF job, attempt_row;
    IF NOT FOUND OR pg_catalog.to_regnamespace(v_schema_name) IS NULL OR
       EXISTS (SELECT 1 FROM platform.tenants WHERE id = v_tenant_id) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'tenant migration schema evidence is invalid';
    END IF;
    INSERT INTO platform.tenancy_tenant_migration_receipts (
        receipt_id, job_id, attempt, receipt_kind, migration_run_id,
        receipt_sha256, evidence_sha256, occurred_at
    ) VALUES (
        p_receipt_id, p_job_id, p_attempt, 'schema_created', v_run_id,
        p_receipt_sha256, p_evidence_sha256, v_now
    );
    RETURN true;
END;
$_$;


ALTER FUNCTION platform.tenancy_tenant_migration_schema_record_v1(p_job_id uuid, p_attempt integer, p_profile_instance_id uuid, p_lease_id uuid, p_receipt_id uuid, p_receipt_sha256 text, p_evidence_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_v1_adopt_environment_v1(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_v1_adopt_environment_v1(p_operation_id uuid, p_environment_id uuid, p_deployment_mode text, p_primary_tenant_id uuid, p_inventory_sha256 text, p_plan_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_existing platform.tenancy_v1_adoption_receipts%ROWTYPE;
    v_tenant_count integer;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            !~ '^harpy-cutover/[0-9a-f-]{36}$'
       OR p_operation_id IS NULL OR p_environment_id IS NULL
       OR p_primary_tenant_id IS NULL
       OR p_deployment_mode NOT IN ('onpremise','saas')
       OR p_inventory_sha256 !~ '^[0-9a-f]{64}$'
       OR p_plan_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 tenancy adoption denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('v1-tenancy-adopt|'||p_environment_id::text,0));
    SELECT * INTO v_existing FROM platform.tenancy_v1_adoption_receipts
    WHERE environment_id=p_environment_id FOR SHARE;
    IF FOUND THEN
        IF v_existing.operation_id IS DISTINCT FROM p_operation_id
           OR v_existing.deployment_mode IS DISTINCT FROM p_deployment_mode
           OR v_existing.primary_tenant_id IS DISTINCT FROM p_primary_tenant_id
           OR v_existing.inventory_sha256 IS DISTINCT FROM pg_catalog.decode(p_inventory_sha256,'hex')
           OR v_existing.plan_sha256 IS DISTINCT FROM pg_catalog.decode(p_plan_sha256,'hex') THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='V1 tenancy adoption replay conflicts';
        END IF;
        RETURN true;
    END IF;
    SELECT pg_catalog.count(*)::integer INTO v_tenant_count
    FROM platform.tenants AS tenant WHERE tenant.deleted_at IS NULL;
    IF (p_deployment_mode='onpremise' AND (v_tenant_count<>1 OR NOT EXISTS (
            SELECT 1 FROM platform.tenants AS tenant
            WHERE tenant.id=p_primary_tenant_id AND tenant.deleted_at IS NULL)))
       OR (p_deployment_mode='saas' AND (v_tenant_count<1 OR NOT EXISTS (
            SELECT 1 FROM platform.tenants AS tenant
            WHERE tenant.id=p_primary_tenant_id AND tenant.deleted_at IS NULL))) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 tenant inventory is ambiguous';
    END IF;
    IF EXISTS (SELECT 1 FROM platform.tenancy_deployment_policy)
       OR EXISTS (SELECT 1 FROM platform.tenancy_tenant_bindings) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 tenancy authority already exists without adoption receipt';
    END IF;
    INSERT INTO platform.tenancy_deployment_policy(
        environment_id,deployment_mode,maximum_customer_tenants,created_at
    ) VALUES (p_environment_id,p_deployment_mode,
        CASE WHEN p_deployment_mode='onpremise' THEN 0 ELSE NULL END,v_now);
    INSERT INTO platform.tenancy_tenant_bindings(
        environment_id,tenant_id,purpose,created_at
    ) VALUES (p_environment_id,p_primary_tenant_id,
        CASE WHEN p_deployment_mode='onpremise'
            THEN 'onpremise_primary' ELSE 'saas_control' END,v_now);
    IF p_deployment_mode='saas' THEN
        INSERT INTO platform.tenancy_tenant_bindings(
            environment_id,tenant_id,purpose,created_at
        ) SELECT p_environment_id,tenant.id,'saas_customer',v_now
          FROM platform.tenants AS tenant
         WHERE tenant.deleted_at IS NULL AND tenant.id<>p_primary_tenant_id
         ORDER BY tenant.id;
    END IF;
    INSERT INTO platform.tenancy_v1_adoption_receipts(
        operation_id,environment_id,deployment_mode,primary_tenant_id,
        adopted_tenant_count,inventory_sha256,plan_sha256,adopted_at,recorded_by
    ) VALUES (p_operation_id,p_environment_id,p_deployment_mode,p_primary_tenant_id,
        v_tenant_count,pg_catalog.decode(p_inventory_sha256,'hex'),
        pg_catalog.decode(p_plan_sha256,'hex'),v_now,SESSION_USER);
    RETURN false;
END;
$_$;


ALTER FUNCTION platform.tenancy_v1_adopt_environment_v1(p_operation_id uuid, p_environment_id uuid, p_deployment_mode text, p_primary_tenant_id uuid, p_inventory_sha256 text, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_v1_environment_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_v1_environment_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract text;
    v_oid oid;
    v_signature text;
    v_replayed boolean;
    v_count bigint;
    v_key_sha text;
    v_state_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_batch_bytes IS DISTINCT FROM pg_catalog.octet_length(p_change_batch_bytes)
       OR p_batch_bytes NOT BETWEEN 1 AND 8388608
       OR pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes),'hex')
            IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 tenancy environment composite denied';
    END IF;
    v_batch := pg_catalog.convert_from(p_change_batch_bytes,'UTF8')::jsonb;
    IF (v_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id
       OR (v_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id
       OR v_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind
       OR (v_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id
       OR (v_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal
       OR v_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key
       OR v_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state
       OR v_batch->'last_key' IS DISTINCT FROM p_last_key
       OR v_batch#>>'{source_position,snapshot_name}' IS DISTINCT FROM p_snapshot_name
       OR (v_batch#>>'{source_position,snapshot_lsn}')::pg_lsn IS DISTINCT FROM p_snapshot_lsn
       OR (v_batch#>>'{source_position,received_lsn}')::pg_lsn IS DISTINCT FROM p_received_lsn
       OR (v_batch#>>'{source_position,commit_lsn}')::pg_lsn IS DISTINCT FROM p_commit_lsn
       OR (v_batch#>>'{source_position,final_lsn}')::pg_lsn IS DISTINCT FROM p_final_lsn
       OR (v_batch#>>'{source_position,source_xid}')::xid8 IS DISTINCT FROM p_source_xid
       OR (v_batch#>>'{source_position,batch_ordinal}')::integer IS DISTINCT FROM p_batch_ordinal THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 tenancy environment batch evidence differs';
    END IF;
    SELECT prepared.procedure_contract_id,prepared.procedure_oid,
        prepared.procedure_signature,prepared.already_applied,
        prepared.applied_count,prepared.key_state_sha256,prepared.state_sha256
      INTO STRICT v_contract,v_oid,v_signature,v_replayed,
        v_count,v_key_sha,v_state_sha
      FROM platform.cutover_prepare_batch_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
        p_checkpoint_key,p_batch_ordinal,p_commit_lsn,p_source_xid,
        p_batch_sha256,p_lease_manifest_sha256) AS prepared;
    IF v_contract IS DISTINCT FROM 'tenancy.v1_environment_adoption.v1'
       OR v_oid IS DISTINCT FROM
            'platform.tenancy_v1_environment_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid
       OR v_signature IS DISTINCT FROM
            'platform.tenancy_v1_environment_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 tenancy environment procedure binding differs';
    END IF;
    IF v_replayed THEN
        RETURN QUERY SELECT v_count,v_key_sha,v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count,result.key_state_sha256,result.state_sha256
      INTO STRICT v_count,v_key_sha,v_state_sha
      FROM platform.tenancy_v1_environment_apply_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
        p_checkpoint_key,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
        p_source_xid,p_batch_ordinal,v_batch,p_batch_sha256) AS result;
    IF v_count<0 OR v_key_sha !~ '^[0-9a-f]{64}$'
       OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='V1 tenancy environment result is invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id,p_run_id,p_relation_ordinal,p_checkpoint_key,p_snapshot_name,
        p_snapshot_lsn,p_received_lsn,p_commit_lsn,p_final_lsn,p_source_xid,
        p_batch_ordinal,p_checkpoint_state,p_last_key,p_batch_sha256,p_batch_bytes,
        v_count,v_key_sha,v_state_sha);
    RETURN QUERY SELECT v_count,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION platform.tenancy_v1_environment_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_v1_environment_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_v1_environment_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_after jsonb;
    v_plan jsonb;
    v_plan_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name',true)
            IS DISTINCT FROM 'harpy-cutover/'||p_run_id::text
       OR p_scope_kind IS DISTINCT FROM 'global' OR p_scope_id IS NULL
       OR p_operation_id IS NULL OR p_run_id IS NULL
       OR p_relation_ordinal<1 OR p_checkpoint_key=''
       OR p_snapshot_lsn>p_commit_lsn OR p_received_lsn<p_commit_lsn
       OR p_batch_ordinal NOT BETWEEN 1 AND 2147483
       OR p_batch_sha256 !~ '^[0-9a-f]{64}$'
       OR pg_catalog.jsonb_typeof(p_change_batch->'changes')<>'array'
       OR pg_catalog.jsonb_array_length(p_change_batch->'changes')<>1 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='V1 tenancy environment apply denied';
    END IF;
    v_after := p_change_batch#>'{changes,0,after}';
    IF p_change_batch#>>'{changes,0,kind}' IS DISTINCT FROM 'insert'
       OR p_change_batch#>'{changes,0,before}' IS DISTINCT FROM 'null'::jsonb
       OR pg_catalog.jsonb_typeof(v_after)<>'object'
       OR (SELECT pg_catalog.array_agg(key ORDER BY key)
             FROM pg_catalog.jsonb_object_keys(v_after) AS key)
          IS DISTINCT FROM ARRAY['authority_ids','contract_version','inventory',
              'operation_id','plan']::text[]
       OR v_after->>'contract_version' IS DISTINCT FROM
            'platform-v1-environment-adoption.v1'
       OR (v_after->>'operation_id')::uuid IS DISTINCT FROM p_operation_id THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='V1 tenancy environment document differs';
    END IF;
    v_plan := v_after->'plan';
    v_plan_sha := v_plan->>'plan_sha256';
    PERFORM 1 FROM platform.platform_cutover_v1_adoption_plans AS recorded
     WHERE recorded.operation_id=p_operation_id
       AND recorded.environment_id=p_scope_id AND recorded.decision='ready'
       AND recorded.deployment_mode=v_plan->>'mode'
       AND recorded.primary_tenant_id=(v_plan->>'primary_tenant_id')::uuid
       AND recorded.inventory_sha256=v_plan->>'inventory_sha256'
       AND recorded.plan_sha256=v_plan_sha
       AND recorded.plan_document=v_plan FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 tenancy environment plan is not recorded';
    END IF;
    PERFORM platform.tenancy_v1_adopt_environment_v1(
        p_operation_id,p_scope_id,v_plan->>'mode',
        (v_plan->>'primary_tenant_id')::uuid,
        v_plan->>'inventory_sha256',v_plan_sha);
    applied_count := 1;
    key_state_sha256 := v_plan_sha;
    state_sha256 := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'tenancy:'||v_plan_sha,'UTF8')),'hex');
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.tenancy_v1_environment_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: tenancy_v1_settings_fence_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.tenancy_v1_settings_fence_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR NEW.id IS DISTINCT FROM OLD.id OR
       NEW.slug IS DISTINCT FROM OLD.slug OR
       NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='V1 tenant settings identity mutation denied';
    END IF;
    UPDATE platform.tenants AS tenant SET
        name=NEW.name, status=NEW.status, settings=NEW.settings,
        owner_id=NEW.owner_id, updated_at=NEW.updated_at,
        deleted_at=NEW.deleted_at,
        settings_revision=tenant.settings_revision+
            CASE WHEN NEW.name IS DISTINCT FROM OLD.name OR
                      NEW.settings IS DISTINCT FROM OLD.settings
                 THEN 1 ELSE 0 END
    WHERE tenant.id=OLD.id;
    RETURN NEW;
END;
$$;


ALTER FUNCTION platform.tenancy_v1_settings_fence_v1() OWNER TO harpy_owner;

--
-- Name: usage_active_users_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_active_users_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_result jsonb;
    v_expected text;
BEGIN
    v_expected := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.active_users'
        ELSE 'usage.platform.active_users' END;
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage time is invalid';
    END IF;
    SELECT pg_catalog.jsonb_build_object(
        'dau', pg_catalog.count(DISTINCT facts.actor_id) FILTER (
            WHERE facts.occurred_at >= pg_catalog.date_trunc('day', p_now, 'UTC')),
        'wau', pg_catalog.count(DISTINCT facts.actor_id) FILTER (
            WHERE facts.occurred_at >= p_now - interval '7 days'),
        'mau', pg_catalog.count(DISTINCT facts.actor_id) FILTER (
            WHERE facts.occurred_at >= p_now - interval '1 month'),
        'concurrent_users', pg_catalog.count(DISTINCT facts.actor_id) FILTER (
            WHERE facts.occurred_at >= p_now - interval '5 minutes'),
        'total_requests_today', pg_catalog.count(*) FILTER (
            WHERE facts.occurred_at >= pg_catalog.date_trunc('day', p_now, 'UTC'))
    ) INTO v_result
    FROM platform.usage_request_facts AS facts
    WHERE facts.environment_id = p_environment_id
      AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
      AND facts.occurred_at <= p_now;
    RETURN v_result;
END;
$$;


ALTER FUNCTION platform.usage_active_users_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_adoption_advance_v1(uuid, uuid, uuid, bigint, bigint, uuid, uuid, bytea, bytea, oid, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_adoption_advance_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_cursor_after uuid, p_source_page_sha256 bytea, p_target_page_sha256 bytea, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_run platform.usage_adoption_runs%ROWTYPE; v_receipt platform.usage_adoption_page_receipts%ROWTYPE;
BEGIN
    SELECT * INTO v_run FROM platform.usage_adoption_runs AS runs
    WHERE runs.operation_id = p_operation_id AND runs.run_id = p_run_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P6904', MESSAGE = 'usage adoption missing'; END IF;
    IF v_run.source_relation_oid IS DISTINCT FROM p_source_relation_oid
       OR v_run.source_count IS DISTINCT FROM p_source_count
       OR v_run.source_root_sha256 IS DISTINCT FROM p_source_root_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6906', MESSAGE = 'usage adoption source drifted';
    END IF;
    SELECT * INTO v_receipt FROM platform.usage_adoption_page_receipts AS receipts
    WHERE receipts.run_id = p_run_id AND receipts.page_number = p_page_number FOR UPDATE;
    IF NOT FOUND OR v_receipt.cursor_before IS DISTINCT FROM p_cursor_before
       OR v_receipt.cursor_after IS DISTINCT FROM p_cursor_after
       OR v_receipt.source_page_sha256 IS DISTINCT FROM p_source_page_sha256
       OR v_receipt.target_page_sha256 IS DISTINCT FROM p_target_page_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption advance conflicts';
    END IF;
    IF v_receipt.state = 'advanced' AND v_run.next_page = p_page_number + 1
       AND v_run.cursor_id = p_cursor_after THEN
        RETURN platform.usage_adoption_run_document_v1(p_run_id);
    END IF;
    IF v_receipt.state <> 'applied' OR v_run.status <> 'applying'
       OR v_run.lease_owner IS DISTINCT FROM p_lease_owner
       OR v_run.lease_generation IS DISTINCT FROM p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at OR v_run.next_page <> p_page_number
       OR v_run.cursor_id IS DISTINCT FROM p_cursor_before THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption lease conflicts';
    END IF;
    UPDATE platform.usage_adoption_page_receipts SET state = 'advanced', advanced_at = p_observed_at
    WHERE run_id = p_run_id AND page_number = p_page_number;
    UPDATE platform.usage_adoption_runs SET next_page = next_page + 1,
        cursor_id = p_cursor_after, copied_count = copied_count + v_receipt.row_count,
        revision = revision + 1, updated_at = p_observed_at,
        lease_expires_at = p_observed_at + interval '30 seconds' WHERE run_id = p_run_id;
    RETURN platform.usage_adoption_run_document_v1(p_run_id);
END;
$$;


ALTER FUNCTION platform.usage_adoption_advance_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_cursor_after uuid, p_source_page_sha256 bytea, p_target_page_sha256 bytea, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_adoption_apply_page_v1(uuid, uuid, uuid, bigint, bigint, uuid, uuid, jsonb, bytea, bytea, oid, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_adoption_apply_page_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_cursor_after uuid, p_records jsonb, p_source_page_sha256 bytea, p_target_page_sha256 bytea, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_run platform.usage_adoption_runs%ROWTYPE;
    v_receipt platform.usage_adoption_page_receipts%ROWTYPE;
    v_mapping platform.usage_adoption_mappings%ROWTYPE;
    v_record jsonb;
    v_fact_id uuid;
    v_replayed boolean;
    v_source_id uuid;
    v_target_id uuid;
    v_source_sha bytea;
    v_target_sha bytea;
BEGIN
    SELECT * INTO v_run FROM platform.usage_adoption_runs AS runs
    WHERE runs.operation_id = p_operation_id AND runs.run_id = p_run_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P6904', MESSAGE = 'usage adoption missing'; END IF;
    IF v_run.source_relation_oid IS DISTINCT FROM p_source_relation_oid
       OR v_run.source_count IS DISTINCT FROM p_source_count
       OR v_run.source_root_sha256 IS DISTINCT FROM p_source_root_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6906', MESSAGE = 'usage adoption source drifted';
    END IF;
    IF v_run.status <> 'applying' OR v_run.lease_owner IS DISTINCT FROM p_lease_owner
       OR v_run.lease_generation IS DISTINCT FROM p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at OR v_run.next_page <> p_page_number
       OR v_run.cursor_id IS DISTINCT FROM p_cursor_before OR p_cursor_after IS NULL
       OR p_records IS NULL OR pg_catalog.jsonb_typeof(p_records) <> 'array'
       OR pg_catalog.jsonb_array_length(p_records) NOT BETWEEN 1 AND 100
       OR pg_catalog.octet_length(p_source_page_sha256) <> 32
       OR pg_catalog.octet_length(p_target_page_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption page conflicts';
    END IF;
    SELECT * INTO v_receipt FROM platform.usage_adoption_page_receipts AS receipts
    WHERE receipts.run_id = p_run_id AND receipts.page_number = p_page_number;
    IF FOUND THEN
        IF v_receipt.cursor_before IS DISTINCT FROM p_cursor_before
           OR v_receipt.cursor_after IS DISTINCT FROM p_cursor_after
           OR v_receipt.row_count <> pg_catalog.jsonb_array_length(p_records)
           OR v_receipt.source_page_sha256 IS DISTINCT FROM p_source_page_sha256
           OR v_receipt.target_page_sha256 IS DISTINCT FROM p_target_page_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption receipt conflicts';
        END IF;
        RETURN pg_catalog.to_jsonb(v_receipt);
    END IF;
    FOR v_record IN SELECT value FROM pg_catalog.jsonb_array_elements(p_records) AS rows(value) LOOP
        IF pg_catalog.jsonb_typeof(v_record) <> 'object'
           OR (v_record - ARRAY['source_id','target_id','environment_id','tenant_id','actor_id',
              'source_identity','source_sha256','fact_digest','method','route_pattern','status_code',
              'duration_micros','occurred_at']::text[]) <> '{}'::jsonb THEN
            RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage adoption record is invalid';
        END IF;
        v_source_id := (v_record->>'source_id')::uuid;
        v_target_id := (v_record->>'target_id')::uuid;
        v_source_sha := pg_catalog.decode(v_record->>'source_sha256', 'hex');
        v_target_sha := pg_catalog.decode(v_record->>'fact_digest', 'hex');
        SELECT recorded.fact_id, recorded.replayed INTO v_fact_id, v_replayed
        FROM platform.usage_record_fact_v1(v_target_id,
            (v_record->>'environment_id')::uuid, (v_record->>'tenant_id')::uuid,
            (v_record->>'actor_id')::uuid,
            pg_catalog.decode(v_record->>'source_identity', 'hex'), v_target_sha,
            v_record->>'method', v_record->>'route_pattern',
            (v_record->>'status_code')::integer, (v_record->>'duration_micros')::bigint,
            (v_record->>'occurred_at')::timestamptz) AS recorded;
        IF v_fact_id IS DISTINCT FROM v_target_id OR pg_catalog.octet_length(v_source_sha) <> 32 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption mapping conflicts';
        END IF;
        INSERT INTO platform.usage_adoption_mappings AS target (
            run_id, source_id, target_id, source_sha256, target_sha256, page_number, applied_at
        ) VALUES (p_run_id, v_source_id, v_target_id, v_source_sha,
            v_target_sha, p_page_number, p_observed_at)
        ON CONFLICT (run_id, source_id) DO NOTHING;
        SELECT * INTO v_mapping FROM platform.usage_adoption_mappings AS mappings
        WHERE mappings.run_id = p_run_id AND mappings.source_id = v_source_id;
        IF v_mapping.target_id IS DISTINCT FROM v_target_id
           OR v_mapping.source_sha256 IS DISTINCT FROM v_source_sha
           OR v_mapping.target_sha256 IS DISTINCT FROM v_target_sha
           OR v_mapping.page_number IS DISTINCT FROM p_page_number THEN
            RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption mapping drifted';
        END IF;
    END LOOP;
    INSERT INTO platform.usage_adoption_page_receipts (
        run_id, page_number, cursor_before, cursor_after, row_count,
        source_page_sha256, target_page_sha256, state, applied_at
    ) VALUES (p_run_id, p_page_number, p_cursor_before, p_cursor_after,
        pg_catalog.jsonb_array_length(p_records), p_source_page_sha256,
        p_target_page_sha256, 'applied', p_observed_at)
    RETURNING * INTO v_receipt;
    RETURN pg_catalog.to_jsonb(v_receipt);
END;
$$;


ALTER FUNCTION platform.usage_adoption_apply_page_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_page_number bigint, p_cursor_before uuid, p_cursor_after uuid, p_records jsonb, p_source_page_sha256 bytea, p_target_page_sha256 bytea, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_adoption_claim_v1(uuid, uuid, uuid, bigint, oid, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_adoption_claim_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_expected_revision bigint, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_run platform.usage_adoption_runs%ROWTYPE;
BEGIN
    SELECT * INTO v_run FROM platform.usage_adoption_runs AS runs
    WHERE runs.operation_id = p_operation_id AND runs.run_id = p_run_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P6904', MESSAGE = 'usage adoption missing'; END IF;
    IF v_run.source_relation_oid IS DISTINCT FROM p_source_relation_oid
       OR v_run.source_count IS DISTINCT FROM p_source_count
       OR v_run.source_root_sha256 IS DISTINCT FROM p_source_root_sha256 THEN
        UPDATE platform.usage_adoption_runs SET status = 'fenced', lease_owner = NULL,
            lease_expires_at = NULL, revision = revision + 1, updated_at = p_observed_at
        WHERE run_id = p_run_id;
        RETURN platform.usage_adoption_run_document_v1(p_run_id);
    END IF;
    IF v_run.status IN ('completed','fenced') THEN
        RETURN platform.usage_adoption_run_document_v1(p_run_id);
    END IF;
    IF p_lease_owner IS NULL OR p_expected_revision <> v_run.revision OR p_observed_at IS NULL
       OR (v_run.lease_owner IS NOT NULL AND v_run.lease_owner <> p_lease_owner
           AND v_run.lease_expires_at > p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption lease conflicts';
    END IF;
    UPDATE platform.usage_adoption_runs SET status = 'applying', lease_owner = p_lease_owner,
        lease_generation = lease_generation + 1, lease_expires_at = p_observed_at + interval '30 seconds',
        revision = revision + 1, updated_at = p_observed_at WHERE run_id = p_run_id;
    RETURN platform.usage_adoption_run_document_v1(p_run_id);
END;
$$;


ALTER FUNCTION platform.usage_adoption_claim_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_expected_revision bigint, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_adoption_complete_v1(uuid, uuid, uuid, bigint, oid, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_adoption_complete_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_run platform.usage_adoption_runs%ROWTYPE;
BEGIN
    SELECT * INTO v_run FROM platform.usage_adoption_runs AS runs
    WHERE runs.operation_id = p_operation_id AND runs.run_id = p_run_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P6904', MESSAGE = 'usage adoption missing'; END IF;
    IF v_run.status = 'completed' THEN RETURN platform.usage_adoption_run_document_v1(p_run_id); END IF;
    IF v_run.source_relation_oid IS DISTINCT FROM p_source_relation_oid
       OR v_run.source_count IS DISTINCT FROM p_source_count
       OR v_run.source_root_sha256 IS DISTINCT FROM p_source_root_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6906', MESSAGE = 'usage adoption source drifted';
    END IF;
    IF v_run.status <> 'reconciling' OR v_run.lease_owner IS DISTINCT FROM p_lease_owner
       OR v_run.lease_generation IS DISTINCT FROM p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption completion conflicts';
    END IF;
    UPDATE platform.usage_adoption_runs SET status = 'completed', completed_at = p_observed_at,
        lease_owner = NULL, lease_expires_at = NULL, revision = revision + 1,
        updated_at = p_observed_at WHERE run_id = p_run_id;
    RETURN platform.usage_adoption_run_document_v1(p_run_id);
END;
$$;


ALTER FUNCTION platform.usage_adoption_complete_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_adoption_reconcile_v1(uuid, uuid, uuid, bigint, oid, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_adoption_reconcile_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_run platform.usage_adoption_runs%ROWTYPE; v_mapping_count bigint;
BEGIN
    SELECT * INTO v_run FROM platform.usage_adoption_runs AS runs
    WHERE runs.operation_id = p_operation_id AND runs.run_id = p_run_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P6904', MESSAGE = 'usage adoption missing'; END IF;
    IF v_run.source_relation_oid IS DISTINCT FROM p_source_relation_oid
       OR v_run.source_count IS DISTINCT FROM p_source_count
       OR v_run.source_root_sha256 IS DISTINCT FROM p_source_root_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6906', MESSAGE = 'usage adoption source drifted';
    END IF;
    SELECT pg_catalog.count(*) INTO v_mapping_count FROM platform.usage_adoption_mappings AS mappings
    WHERE mappings.run_id = p_run_id;
    IF v_run.status <> 'applying' OR v_run.lease_owner IS DISTINCT FROM p_lease_owner
       OR v_run.lease_generation IS DISTINCT FROM p_lease_generation
       OR v_run.lease_expires_at <= p_observed_at OR v_run.copied_count <> p_source_count
       OR v_mapping_count <> p_source_count THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption reconcile conflicts';
    END IF;
    UPDATE platform.usage_adoption_runs SET status = 'reconciling', revision = revision + 1,
        updated_at = p_observed_at, lease_expires_at = p_observed_at + interval '30 seconds'
    WHERE run_id = p_run_id;
    RETURN platform.usage_adoption_run_document_v1(p_run_id);
END;
$$;


ALTER FUNCTION platform.usage_adoption_reconcile_v1(p_operation_id uuid, p_run_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_adoption_run_document_v1(uuid); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_adoption_run_document_v1(p_run_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
SELECT pg_catalog.jsonb_build_object(
    'run_id', runs.run_id, 'operation_id', runs.operation_id,
    'source_kind', runs.source_kind, 'source_schema', runs.source_schema,
    'source_relation', runs.source_relation,
    'source_relation_oid', runs.source_relation_oid::bigint,
    'source_count', runs.source_count,
    'source_root_sha256', pg_catalog.encode(runs.source_root_sha256, 'hex'),
    'snapshot_id', runs.snapshot_id,
    'transform_sha256', pg_catalog.encode(runs.transform_sha256, 'hex'),
    'next_page', runs.next_page, 'cursor_id', runs.cursor_id,
    'copied_count', runs.copied_count, 'status', runs.status,
    'lease_owner', runs.lease_owner, 'lease_generation', runs.lease_generation,
    'lease_expires_at', runs.lease_expires_at, 'revision', runs.revision,
    'completed_at', runs.completed_at)
FROM platform.usage_adoption_runs AS runs WHERE runs.run_id = p_run_id
$$;


ALTER FUNCTION platform.usage_adoption_run_document_v1(p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: usage_adoption_start_v1(uuid, uuid, text, text, text, oid, bigint, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_adoption_start_v1(p_operation_id uuid, p_run_id uuid, p_source_kind text, p_source_schema text, p_source_relation text, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_snapshot_id text, p_transform_sha256 bytea, p_observed_at timestamp with time zone) RETURNS TABLE(document jsonb, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_existing platform.usage_adoption_runs%ROWTYPE;
BEGIN
    IF p_operation_id IS NULL OR p_run_id IS NULL
       OR pg_catalog.uuid_extract_version(p_run_id) <> 7
       OR p_source_kind NOT IN ('zero','legacy_trace_logs')
       OR p_source_schema !~ '^[a-z][a-z0-9_]{0,62}$'
       OR p_source_relation !~ '^[a-z][a-z0-9_]{0,62}$'
       OR p_source_count < 0 OR pg_catalog.octet_length(p_source_root_sha256) <> 32
       OR pg_catalog.octet_length(p_transform_sha256) <> 32
       OR pg_catalog.octet_length(p_snapshot_id) NOT BETWEEN 16 AND 200
       OR p_observed_at IS NULL
       OR (p_source_kind = 'zero' AND (p_source_relation_oid <> 0 OR p_source_count <> 0))
       OR (p_source_kind = 'legacy_trace_logs' AND p_source_relation_oid::bigint < 1) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage adoption start is invalid';
    END IF;
    INSERT INTO platform.usage_adoption_runs AS target (
        run_id, operation_id, source_kind, source_schema, source_relation,
        source_relation_oid, source_count, source_root_sha256, snapshot_id,
        transform_sha256, status, created_at, updated_at
    ) VALUES (p_run_id, p_operation_id, p_source_kind, p_source_schema,
        p_source_relation, p_source_relation_oid, p_source_count, p_source_root_sha256,
        p_snapshot_id, p_transform_sha256, 'planned', p_observed_at, p_observed_at)
    ON CONFLICT (operation_id) DO NOTHING;
    SELECT * INTO v_existing FROM platform.usage_adoption_runs AS runs
    WHERE runs.operation_id = p_operation_id;
    IF v_existing.run_id IS DISTINCT FROM p_run_id
       OR v_existing.source_kind IS DISTINCT FROM p_source_kind
       OR v_existing.source_schema IS DISTINCT FROM p_source_schema
       OR v_existing.source_relation IS DISTINCT FROM p_source_relation
       OR v_existing.source_relation_oid IS DISTINCT FROM p_source_relation_oid
       OR v_existing.source_count IS DISTINCT FROM p_source_count
       OR v_existing.source_root_sha256 IS DISTINCT FROM p_source_root_sha256
       OR v_existing.snapshot_id IS DISTINCT FROM p_snapshot_id
       OR v_existing.transform_sha256 IS DISTINCT FROM p_transform_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage adoption start conflicts';
    END IF;
    document := platform.usage_adoption_run_document_v1(v_existing.run_id);
    replayed := v_existing.created_at IS DISTINCT FROM p_observed_at;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION platform.usage_adoption_start_v1(p_operation_id uuid, p_run_id uuid, p_source_kind text, p_source_schema text, p_source_relation text, p_source_relation_oid oid, p_source_count bigint, p_source_root_sha256 bytea, p_snapshot_id text, p_transform_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_assert_read_access_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_assert_read_access_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_expected_operation text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_tenant boolean;
    v_platform boolean;
BEGIN
    IF p_actor_id IS NULL OR p_subject_tenant_id IS NULL OR p_environment_id IS NULL
       OR p_token_version < 1 OR p_authorization_version < 1 OR p_authority_clock < 1
       OR p_operation IS DISTINCT FROM p_expected_operation
       OR p_operation !~ '^[a-z][a-z0-9_.]{0,127}$' THEN
        RAISE EXCEPTION USING ERRCODE = 'P6903', MESSAGE = 'usage read access denied';
    END IF;
    v_tenant := p_scope = 'tenant' AND p_target_tenant_id = p_subject_tenant_id
        AND p_permission = 'analytics.usage.read' AND NOT p_control_primary
        AND ((p_mode = 'onpremise' AND p_purpose = 'onpremise_primary')
            OR (p_mode = 'saas' AND p_purpose = 'saas_customer'));
    v_platform := p_scope = 'platform' AND p_target_tenant_id IS NULL
        AND p_permission = 'platform.analytics.usage.read' AND p_control_primary
        AND p_mode = 'saas' AND p_purpose = 'saas_control';
    IF NOT v_tenant AND NOT v_platform THEN
        RAISE EXCEPTION USING ERRCODE = 'P6903', MESSAGE = 'usage read scope denied';
    END IF;
END;
$_$;


ALTER FUNCTION platform.usage_assert_read_access_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_expected_operation text) OWNER TO harpy_owner;

--
-- Name: usage_features_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_features_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_result jsonb;
    v_expected text;
BEGIN
    v_expected := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.features'
        ELSE 'usage.platform.features' END;
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_start IS NULL OR p_end IS NULL OR p_start >= p_end
       OR p_end - p_start > interval '31 days' OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage features query is invalid';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('route_pattern', ranked.route_pattern,
            'method', ranked.method, 'request_count', ranked.request_count,
            'unique_users', ranked.unique_users,
            'average_millis', ranked.average_millis,
            'error_count', ranked.error_count,
            'error_rate', ranked.error_count::numeric * 100.0 / ranked.request_count)
        ORDER BY ranked.request_count DESC, ranked.route_pattern, ranked.method
    ), '[]'::jsonb) INTO v_result
    FROM (
        SELECT facts.route_pattern, facts.method,
            pg_catalog.count(*) AS request_count,
            pg_catalog.count(DISTINCT facts.actor_id) AS unique_users,
            pg_catalog.avg(facts.duration_micros)::numeric / 1000.0 AS average_millis,
            pg_catalog.count(*) FILTER (WHERE facts.status_code >= 400) AS error_count
        FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id
          AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
          AND facts.occurred_at >= p_start AND facts.occurred_at < p_end
        GROUP BY facts.route_pattern, facts.method
        ORDER BY request_count DESC, facts.route_pattern, facts.method
        LIMIT p_limit
    ) AS ranked;
    RETURN v_result;
END;
$$;


ALTER FUNCTION platform.usage_features_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: usage_heatmap_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_heatmap_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_result jsonb; v_expected text;
BEGIN
    v_expected := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.heatmap'
        ELSE 'usage.platform.heatmap' END;
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_start IS NULL OR p_end IS NULL OR p_start >= p_end
       OR p_end - p_start > interval '31 days' THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage heatmap query is invalid';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('day', cells.day, 'hour', cells.hour, 'count', cells.count)
        ORDER BY cells.day, cells.hour), '[]'::jsonb) INTO v_result
    FROM (
        SELECT pg_catalog.date_part('dow', facts.occurred_at AT TIME ZONE 'UTC')::integer AS day,
            pg_catalog.date_part('hour', facts.occurred_at AT TIME ZONE 'UTC')::integer AS hour,
            pg_catalog.count(*) AS count
        FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id
          AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
          AND facts.occurred_at >= p_start AND facts.occurred_at < p_end
        GROUP BY 1, 2 ORDER BY 1, 2
    ) AS cells;
    RETURN v_result;
END;
$$;


ALTER FUNCTION platform.usage_heatmap_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_legal_hold_place_v1(uuid, uuid, uuid, text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_legal_hold_place_v1(p_hold_id uuid, p_environment_id uuid, p_tenant_id uuid, p_reason_code text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE v_existing platform.usage_legal_holds%ROWTYPE;
BEGIN
    IF p_hold_id IS NULL OR pg_catalog.uuid_extract_version(p_hold_id) <> 7
       OR p_environment_id IS NULL OR p_reason_code !~ '^[a-z][a-z0-9_.-]{0,63}$'
       OR p_starts_at IS NULL OR p_observed_at IS NULL
       OR (p_ends_at IS NOT NULL AND p_ends_at < p_starts_at) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage legal hold is invalid';
    END IF;
    INSERT INTO platform.usage_legal_holds AS target (
        hold_id, environment_id, tenant_id, reason_code, starts_at, ends_at, created_at
    ) VALUES (p_hold_id, p_environment_id, p_tenant_id, p_reason_code,
        p_starts_at, p_ends_at, p_observed_at)
    ON CONFLICT (hold_id) DO NOTHING;
    SELECT * INTO v_existing FROM platform.usage_legal_holds AS holds
    WHERE holds.hold_id = p_hold_id;
    IF v_existing.environment_id IS DISTINCT FROM p_environment_id
       OR v_existing.tenant_id IS DISTINCT FROM p_tenant_id
       OR v_existing.reason_code IS DISTINCT FROM p_reason_code
       OR v_existing.starts_at IS DISTINCT FROM p_starts_at
       OR v_existing.ends_at IS DISTINCT FROM p_ends_at THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage legal hold conflicts';
    END IF;
    RETURN v_existing.created_at = p_observed_at;
END;
$_$;


ALTER FUNCTION platform.usage_legal_hold_place_v1(p_hold_id uuid, p_environment_id uuid, p_tenant_id uuid, p_reason_code text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_legal_hold_release_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_legal_hold_release_v1(p_hold_id uuid, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_hold_id IS NULL OR p_observed_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage legal hold release is invalid';
    END IF;
    UPDATE platform.usage_legal_holds AS holds SET released_at = p_observed_at
    WHERE holds.hold_id = p_hold_id AND holds.released_at IS NULL;
    IF FOUND THEN RETURN true; END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.usage_legal_holds AS holds
        WHERE holds.hold_id = p_hold_id) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6904', MESSAGE = 'usage legal hold not found';
    END IF;
    RETURN false;
END;
$$;


ALTER FUNCTION platform.usage_legal_hold_release_v1(p_hold_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_overview_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_overview_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_active jsonb;
    v_features jsonb;
    v_users jsonb;
    v_trend jsonb;
    v_recent jsonb;
    v_expected text;
    v_prefix text;
BEGIN
    v_prefix := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.' ELSE 'usage.platform.' END;
    v_expected := v_prefix || 'overview';
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_start IS NULL OR p_end IS NULL OR p_now IS NULL OR p_start >= p_end
       OR p_end - p_start > interval '31 days' THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage overview query is invalid';
    END IF;
    v_active := platform.usage_active_users_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission,
        v_prefix || 'active_users', p_now);
    v_features := platform.usage_features_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission,
        v_prefix || 'features', p_start, p_end, 5);
    v_users := platform.usage_top_users_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission,
        v_prefix || 'top_users', p_start, p_end, 5);
    v_trend := platform.usage_trend_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission,
        v_prefix || 'trend', p_start, p_end, 'hour');
    SELECT COALESCE(pg_catalog.jsonb_agg(last_points.value
        ORDER BY last_points.ordinality), '[]'::jsonb) INTO v_recent
    FROM (
        SELECT points.value, points.ordinality
        FROM pg_catalog.jsonb_array_elements(v_trend) WITH ORDINALITY AS points(value, ordinality)
        ORDER BY points.ordinality DESC LIMIT 24
    ) AS last_points;
    RETURN pg_catalog.jsonb_build_object('active_users', v_active,
        'top_features', v_features, 'top_users', v_users, 'recent_trend', v_recent);
END;
$$;


ALTER FUNCTION platform.usage_overview_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_record_fact_v1(uuid, uuid, uuid, uuid, bytea, bytea, text, text, integer, bigint, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_record_fact_v1(p_fact_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_source_identity bytea, p_fact_digest bytea, p_method text, p_route_pattern text, p_status_code integer, p_duration_micros bigint, p_occurred_at timestamp with time zone) RETURNS TABLE(fact_id uuid, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_fact_id uuid;
    v_digest bytea;
BEGIN
    IF p_fact_id IS NULL OR pg_catalog.uuid_extract_version(p_fact_id) <> 7
       OR p_environment_id IS NULL OR p_tenant_id IS NULL OR p_actor_id IS NULL
       OR pg_catalog.octet_length(p_source_identity) <> 32
       OR pg_catalog.octet_length(p_fact_digest) <> 32
       OR p_source_identity = pg_catalog.decode(pg_catalog.repeat('00', 32), 'hex')
       OR p_fact_digest = pg_catalog.decode(pg_catalog.repeat('00', 32), 'hex')
       OR p_method NOT IN ('GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS')
       OR pg_catalog.octet_length(p_route_pattern) NOT BETWEEN 1 AND 256
       OR pg_catalog.left(p_route_pattern, 1) <> '/'
       OR pg_catalog.strpos(p_route_pattern, '?') > 0
       OR pg_catalog.strpos(p_route_pattern, '#') > 0
       OR p_route_pattern ~ E'[\r\n]' OR p_status_code NOT BETWEEN 100 AND 599
       OR p_duration_micros NOT BETWEEN 0 AND 86400000000 OR p_occurred_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage fact is invalid';
    END IF;
    INSERT INTO platform.usage_request_facts AS target (
        fact_id, environment_id, tenant_id, actor_id, source_identity, fact_digest,
        method, route_pattern, status_code, duration_micros, occurred_at, created_at
    ) VALUES (
        p_fact_id, p_environment_id, p_tenant_id, p_actor_id, p_source_identity,
        p_fact_digest, p_method, p_route_pattern, p_status_code, p_duration_micros,
        p_occurred_at, pg_catalog.clock_timestamp()
    ) ON CONFLICT (environment_id, source_identity) DO NOTHING
    RETURNING target.fact_id INTO v_fact_id;
    IF v_fact_id IS NOT NULL THEN
        fact_id := v_fact_id;
        replayed := false;
        RETURN NEXT;
        RETURN;
    END IF;
    SELECT stored.fact_id, stored.fact_digest INTO v_fact_id, v_digest
    FROM platform.usage_request_facts AS stored
    WHERE stored.environment_id = p_environment_id
      AND stored.source_identity = p_source_identity;
    IF v_fact_id IS NULL OR v_digest IS DISTINCT FROM p_fact_digest THEN
        RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage source identity conflict';
    END IF;
    fact_id := v_fact_id;
    replayed := true;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION platform.usage_record_fact_v1(p_fact_id uuid, p_environment_id uuid, p_tenant_id uuid, p_actor_id uuid, p_source_identity bytea, p_fact_digest bytea, p_method text, p_route_pattern text, p_status_code integer, p_duration_micros bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_request_fact_immutable_v1(); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_request_fact_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE'
       AND pg_catalog.current_setting('harpy.usage_retention', true) = 'usage_retention_v1' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'P6903', MESSAGE = 'usage facts are immutable';
END;
$$;


ALTER FUNCTION platform.usage_request_fact_immutable_v1() OWNER TO harpy_owner;

--
-- Name: usage_retention_prune_v1(uuid, uuid, timestamp with time zone, integer, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_retention_prune_v1(p_receipt_id uuid, p_environment_id uuid, p_delete_before timestamp with time zone, p_batch_limit integer, p_observed_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_existing platform.usage_retention_receipts%ROWTYPE; v_deleted integer;
BEGIN
    IF p_receipt_id IS NULL OR pg_catalog.uuid_extract_version(p_receipt_id) <> 7
       OR p_environment_id IS NULL OR p_observed_at IS NULL
       OR p_batch_limit NOT BETWEEN 1 AND 10000 OR p_delete_before IS NULL
       OR p_delete_before > p_observed_at - interval '31 days' THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage retention request is invalid';
    END IF;
    SELECT * INTO v_existing FROM platform.usage_retention_receipts AS receipts
    WHERE receipts.receipt_id = p_receipt_id;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.delete_before IS DISTINCT FROM p_delete_before
           OR v_existing.batch_limit IS DISTINCT FROM p_batch_limit THEN
            RAISE EXCEPTION USING ERRCODE = 'P6902', MESSAGE = 'usage retention receipt conflicts';
        END IF;
        RETURN v_existing.deleted_count;
    END IF;
    PERFORM pg_catalog.set_config('harpy.usage_retention', 'usage_retention_v1', true);
    WITH candidates AS (
        SELECT facts.fact_id FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id AND facts.occurred_at < p_delete_before
          AND NOT EXISTS (SELECT 1 FROM platform.usage_legal_holds AS holds
              WHERE holds.environment_id = facts.environment_id AND holds.released_at IS NULL
                AND (holds.tenant_id IS NULL OR holds.tenant_id = facts.tenant_id)
                AND holds.starts_at <= p_observed_at
                AND (holds.ends_at IS NULL OR holds.ends_at >= p_observed_at))
        ORDER BY facts.occurred_at, facts.fact_id LIMIT p_batch_limit FOR UPDATE SKIP LOCKED
    ) DELETE FROM platform.usage_request_facts AS facts
      USING candidates WHERE facts.fact_id = candidates.fact_id;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;
    INSERT INTO platform.usage_retention_receipts (
        receipt_id, environment_id, delete_before, batch_limit, deleted_count, observed_at
    ) VALUES (p_receipt_id, p_environment_id, p_delete_before,
        p_batch_limit, v_deleted, p_observed_at);
    RETURN v_deleted;
END;
$$;


ALTER FUNCTION platform.usage_retention_prune_v1(p_receipt_id uuid, p_environment_id uuid, p_delete_before timestamp with time zone, p_batch_limit integer, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_top_users_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_top_users_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_result jsonb;
    v_expected text;
BEGIN
    v_expected := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.top_users'
        ELSE 'usage.platform.top_users' END;
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_start IS NULL OR p_end IS NULL OR p_start >= p_end
       OR p_end - p_start > interval '31 days' OR p_limit NOT BETWEEN 1 AND 50 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage top users query is invalid';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
            'subject_id', ranked.subject_id,
            'request_count', ranked.request_count,
            'unique_routes', ranked.unique_routes,
            'last_active', ranked.last_active
        ) ORDER BY ranked.request_count DESC, ranked.last_active DESC, ranked.subject_id
    ), '[]'::jsonb) INTO v_result
    FROM (
        SELECT CASE WHEN p_scope = 'tenant' THEN facts.actor_id::text ELSE
            pg_catalog.encode(pg_catalog.sha256(
                pg_catalog.uuid_send(facts.environment_id)
                || pg_catalog.uuid_send(facts.tenant_id)
                || pg_catalog.uuid_send(facts.actor_id)), 'hex') END AS subject_id,
            pg_catalog.count(*) AS request_count,
            pg_catalog.count(DISTINCT (facts.route_pattern, facts.method)) AS unique_routes,
            pg_catalog.max(facts.occurred_at) AS last_active
        FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id
          AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
          AND facts.occurred_at >= p_start AND facts.occurred_at < p_end
        GROUP BY 1
        ORDER BY request_count DESC, last_active DESC, subject_id
        LIMIT p_limit
    ) AS ranked;
    RETURN v_result;
END;
$$;


ALTER FUNCTION platform.usage_top_users_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: usage_trend_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_trend_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_granularity text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_result jsonb; v_expected text;
BEGIN
    v_expected := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.trend'
        ELSE 'usage.platform.trend' END;
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_start IS NULL OR p_end IS NULL OR p_start >= p_end
       OR p_end - p_start > interval '31 days'
       OR p_granularity NOT IN ('hour','day','week') THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage trend query is invalid';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('bucket', points.bucket, 'requests', points.requests,
            'unique_users', points.unique_users) ORDER BY points.bucket), '[]'::jsonb)
    INTO v_result
    FROM (
        SELECT pg_catalog.date_trunc(p_granularity, facts.occurred_at, 'UTC') AS bucket,
            pg_catalog.count(*) AS requests,
            pg_catalog.count(DISTINCT facts.actor_id) AS unique_users
        FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id
          AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
          AND facts.occurred_at >= p_start AND facts.occurred_at < p_end
        GROUP BY 1 ORDER BY 1
    ) AS points;
    RETURN v_result;
END;
$$;


ALTER FUNCTION platform.usage_trend_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_start timestamp with time zone, p_end timestamp with time zone, p_granularity text) OWNER TO harpy_owner;

--
-- Name: usage_user_summary_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_user_summary_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_subject text, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_total bigint;
    v_unique bigint;
    v_last timestamptz;
    v_routes jsonb;
    v_daily jsonb;
    v_expected text;
BEGIN
    v_expected := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.user_summary'
        ELSE 'usage.platform.user_summary' END;
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_start IS NULL OR p_end IS NULL OR p_start >= p_end
       OR p_end - p_start > interval '31 days'
       OR (p_scope = 'tenant' AND p_subject !~
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
       OR (p_scope = 'platform' AND p_subject !~ '^[0-9a-f]{64}$') THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage subject query is invalid';
    END IF;
    SELECT pg_catalog.count(*),
        pg_catalog.count(DISTINCT (facts.route_pattern, facts.method)),
        pg_catalog.max(facts.occurred_at)
    INTO v_total, v_unique, v_last
    FROM platform.usage_request_facts AS facts
    WHERE facts.environment_id = p_environment_id
      AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
      AND facts.occurred_at >= p_start AND facts.occurred_at < p_end
      AND ((p_scope = 'tenant' AND facts.actor_id = p_subject::uuid)
        OR (p_scope = 'platform' AND pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.uuid_send(facts.environment_id)
            || pg_catalog.uuid_send(facts.tenant_id)
            || pg_catalog.uuid_send(facts.actor_id)), 'hex') = p_subject));
    IF v_total = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6904', MESSAGE = 'usage subject not found';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('route_pattern', ranked.route_pattern,
            'method', ranked.method, 'request_count', ranked.request_count,
            'average_millis', ranked.average_millis)
        ORDER BY ranked.request_count DESC, ranked.route_pattern, ranked.method
    ), '[]'::jsonb) INTO v_routes
    FROM (
        SELECT facts.route_pattern, facts.method, pg_catalog.count(*) AS request_count,
            pg_catalog.avg(facts.duration_micros)::numeric / 1000.0 AS average_millis
        FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id
          AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
          AND facts.occurred_at >= p_start AND facts.occurred_at < p_end
          AND ((p_scope = 'tenant' AND facts.actor_id = p_subject::uuid)
            OR (p_scope = 'platform' AND pg_catalog.encode(pg_catalog.sha256(
                pg_catalog.uuid_send(facts.environment_id) || pg_catalog.uuid_send(facts.tenant_id)
                || pg_catalog.uuid_send(facts.actor_id)), 'hex') = p_subject))
        GROUP BY facts.route_pattern, facts.method
        ORDER BY request_count DESC, facts.route_pattern, facts.method LIMIT 10
    ) AS ranked;
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('date', daily.day, 'request_count', daily.request_count)
        ORDER BY daily.day), '[]'::jsonb) INTO v_daily
    FROM (
        SELECT pg_catalog.to_char(pg_catalog.date_trunc('day', facts.occurred_at, 'UTC'),
            'YYYY-MM-DD') AS day, pg_catalog.count(*) AS request_count
        FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id
          AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
          AND facts.occurred_at >= p_start AND facts.occurred_at < p_end
          AND ((p_scope = 'tenant' AND facts.actor_id = p_subject::uuid)
            OR (p_scope = 'platform' AND pg_catalog.encode(pg_catalog.sha256(
                pg_catalog.uuid_send(facts.environment_id) || pg_catalog.uuid_send(facts.tenant_id)
                || pg_catalog.uuid_send(facts.actor_id)), 'hex') = p_subject))
        GROUP BY 1 ORDER BY 1
    ) AS daily;
    RETURN pg_catalog.jsonb_build_object('subject_id', p_subject, 'last_active', v_last,
        'total_requests', v_total, 'unique_routes', v_unique,
        'top_routes', v_routes, 'daily_breakdown', v_daily);
END;
$_$;


ALTER FUNCTION platform.usage_user_summary_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_subject text, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: usage_user_timeline_v1(uuid, uuid, uuid, uuid, bigint, bigint, bigint, text, text, text, boolean, text, text, text, integer, integer); Type: FUNCTION; Schema: platform; Owner: harpy_owner
--

CREATE FUNCTION platform.usage_user_timeline_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_subject text, p_page integer, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_total bigint;
    v_items jsonb;
    v_expected text;
BEGIN
    v_expected := CASE WHEN p_scope = 'tenant' THEN 'usage.tenant.user_timeline'
        ELSE 'usage.platform.user_timeline' END;
    PERFORM platform.usage_assert_read_access_v1(
        p_actor_id, p_subject_tenant_id, p_target_tenant_id, p_environment_id,
        p_token_version, p_authorization_version, p_authority_clock, p_scope,
        p_mode, p_purpose, p_control_primary, p_permission, p_operation, v_expected);
    IF p_page NOT BETWEEN 1 AND 1000 OR p_limit NOT BETWEEN 1 AND 100
       OR (p_scope = 'tenant' AND p_subject !~
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
       OR (p_scope = 'platform' AND p_subject !~ '^[0-9a-f]{64}$') THEN
        RAISE EXCEPTION USING ERRCODE = 'P6901', MESSAGE = 'usage timeline query is invalid';
    END IF;
    SELECT pg_catalog.count(*) INTO v_total
    FROM platform.usage_request_facts AS facts
    WHERE facts.environment_id = p_environment_id
      AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
      AND ((p_scope = 'tenant' AND facts.actor_id = p_subject::uuid)
        OR (p_scope = 'platform' AND pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.uuid_send(facts.environment_id) || pg_catalog.uuid_send(facts.tenant_id)
            || pg_catalog.uuid_send(facts.actor_id)), 'hex') = p_subject));
    SELECT COALESCE(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('id', page.fact_id::text,
            'route_pattern', page.route_pattern, 'method', page.method,
            'status_code', page.status_code,
            'duration_millis', page.duration_micros::numeric / 1000.0,
            'occurred_at', page.occurred_at)
        ORDER BY page.occurred_at DESC, page.fact_id DESC
    ), '[]'::jsonb) INTO v_items
    FROM (
        SELECT facts.fact_id, facts.route_pattern, facts.method, facts.status_code,
            facts.duration_micros, facts.occurred_at
        FROM platform.usage_request_facts AS facts
        WHERE facts.environment_id = p_environment_id
          AND (p_scope = 'platform' OR facts.tenant_id = p_target_tenant_id)
          AND ((p_scope = 'tenant' AND facts.actor_id = p_subject::uuid)
            OR (p_scope = 'platform' AND pg_catalog.encode(pg_catalog.sha256(
                pg_catalog.uuid_send(facts.environment_id) || pg_catalog.uuid_send(facts.tenant_id)
                || pg_catalog.uuid_send(facts.actor_id)), 'hex') = p_subject))
        ORDER BY facts.occurred_at DESC, facts.fact_id DESC
        OFFSET (p_page - 1) * p_limit LIMIT p_limit
    ) AS page;
    RETURN pg_catalog.jsonb_build_object('items', v_items, 'total', v_total,
        'page', p_page, 'limit', p_limit,
        'total_pages', ((v_total + p_limit - 1) / p_limit)::integer);
END;
$_$;


ALTER FUNCTION platform.usage_user_timeline_v1(p_actor_id uuid, p_subject_tenant_id uuid, p_target_tenant_id uuid, p_environment_id uuid, p_token_version bigint, p_authorization_version bigint, p_authority_clock bigint, p_scope text, p_mode text, p_purpose text, p_control_primary boolean, p_permission text, p_operation text, p_subject text, p_page integer, p_limit integer) OWNER TO harpy_owner;

--
-- Name: authority_adoption_inventory; Type: TABLE; Schema: cutover_authority; Owner: harpy_owner
--

CREATE TABLE cutover_authority.authority_adoption_inventory (
    catalog_generation integer NOT NULL,
    operation_id uuid NOT NULL,
    receipt_id uuid NOT NULL,
    receipt_sha256 text NOT NULL,
    receipt_document bytea NOT NULL,
    operation_sha256 text NOT NULL,
    release_id uuid NOT NULL,
    environment_id uuid NOT NULL,
    database_origin text NOT NULL,
    system_identifier numeric(20,0) NOT NULL,
    database_oid oid NOT NULL,
    catalog_contract_sha256 text NOT NULL,
    catalog_instance_sha256 text NOT NULL,
    dependency_contract_sha256 text CONSTRAINT authority_adoption_inventor_dependency_contract_sha256_not_null NOT NULL,
    dependency_instance_sha256 text CONSTRAINT authority_adoption_inventor_dependency_instance_sha256_not_null NOT NULL,
    object_count integer NOT NULL,
    dependency_count integer NOT NULL,
    adopted_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT authority_adoption_inventory_catalog_contract_sha256_check CHECK ((catalog_contract_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT authority_adoption_inventory_catalog_generation_check CHECK ((catalog_generation > 0)),
    CONSTRAINT authority_adoption_inventory_catalog_instance_sha256_check CHECK ((catalog_instance_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT authority_adoption_inventory_check CHECK ((receipt_sha256 = encode(sha256(receipt_document), 'hex'::text))),
    CONSTRAINT authority_adoption_inventory_database_origin_check CHECK ((database_origin = ANY (ARRAY['fresh'::text, 'v1_adopted'::text]))),
    CONSTRAINT authority_adoption_inventory_dependency_contract_sha256_check CHECK ((dependency_contract_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT authority_adoption_inventory_dependency_count_check CHECK ((dependency_count = 19)),
    CONSTRAINT authority_adoption_inventory_dependency_instance_sha256_check CHECK ((dependency_instance_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT authority_adoption_inventory_object_count_check CHECK (((object_count >= 18) AND (object_count <= 256))),
    CONSTRAINT authority_adoption_inventory_operation_sha256_check CHECK ((operation_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT authority_adoption_inventory_receipt_document_check CHECK (((octet_length(receipt_document) >= 2) AND (octet_length(receipt_document) <= 16777216))),
    CONSTRAINT authority_adoption_inventory_receipt_sha256_check CHECK ((receipt_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT authority_adoption_inventory_system_identifier_check CHECK ((system_identifier > (0)::numeric))
);


