    CONSTRAINT finalization_authorizations_check2 CHECK ((seal_receipt_sha256 = encode(sha256(seal_receipt_document), 'hex'::text))),
    CONSTRAINT finalization_authorizations_check3 CHECK ((cleanup_receipt_sha256 = encode(sha256(cleanup_receipt_document), 'hex'::text))),
    CONSTRAINT finalization_authorizations_check4 CHECK ((authority_receipt_sha256 = encode(sha256(authority_receipt_document), 'hex'::text))),
    CONSTRAINT finalization_authorizations_check5 CHECK ((terminal_evidence_sha256 = encode(sha256(terminal_evidence_document), 'hex'::text))),
    CONSTRAINT finalization_authorizations_cleanup_receipt_document_check CHECK (((octet_length(cleanup_receipt_document) >= 2) AND (octet_length(cleanup_receipt_document) <= 65536))),
    CONSTRAINT finalization_authorizations_finalization_state_sha256_check CHECK ((finalization_state_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT finalization_authorizations_finalizer_lease_document_check CHECK (((octet_length(finalizer_lease_document) >= 2) AND (octet_length(finalizer_lease_document) <= 65536))),
    CONSTRAINT finalization_authorizations_seal_receipt_document_check CHECK (((octet_length(seal_receipt_document) >= 2) AND (octet_length(seal_receipt_document) <= 65536))),
    CONSTRAINT finalization_authorizations_terminal_evidence_document_check CHECK (((octet_length(terminal_evidence_document) >= 2) AND (octet_length(terminal_evidence_document) <= 16777216))),
    CONSTRAINT finalization_authorizations_terminal_evidence_sha256_check CHECK ((terminal_evidence_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT finalization_authorizations_terminal_state_check CHECK ((terminal_state = ANY (ARRAY['completed'::text, 'failed'::text, 'cancelled'::text])))
);


ALTER TABLE cutover_authority.finalization_authorizations OWNER TO harpy_owner;

--
-- Name: finalization_receipts; Type: TABLE; Schema: cutover_authority; Owner: harpy_owner
--

CREATE TABLE cutover_authority.finalization_receipts (
    operation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    finalizer_lease_id uuid NOT NULL,
    finalizer_lease_sha256 text NOT NULL,
    finalizer_lease_document bytea NOT NULL,
    adoption_lease_sha256 text NOT NULL,
    adoption_lease_document bytea NOT NULL,
    seal_receipt_sha256 text NOT NULL,
    seal_receipt_document bytea NOT NULL,
    cleanup_receipt_sha256 text NOT NULL,
    cleanup_receipt_document bytea NOT NULL,
    authority_receipt_sha256 text NOT NULL,
    authority_receipt_document bytea NOT NULL,
    terminal_state text NOT NULL,
    terminal_evidence_sha256 text NOT NULL,
    terminal_evidence_document bytea NOT NULL,
    finalization_state_sha256 text NOT NULL,
    tenant_requirement_catalog_sha256 text,
    tenant_requirement_catalog_document bytea,
    tenant_requirement_count integer,
    tenant_target_count integer,
    finalized_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    finalized_by text DEFAULT SESSION_USER NOT NULL,
    CONSTRAINT finalization_receipts_adoption_lease_document_check CHECK (((octet_length(adoption_lease_document) >= 2) AND (octet_length(adoption_lease_document) <= 16777216))),
    CONSTRAINT finalization_receipts_authority_receipt_document_check CHECK (((octet_length(authority_receipt_document) >= 2) AND (octet_length(authority_receipt_document) <= 16777216))),
    CONSTRAINT finalization_receipts_check CHECK ((finalizer_lease_sha256 = encode(sha256(finalizer_lease_document), 'hex'::text))),
    CONSTRAINT finalization_receipts_check1 CHECK ((adoption_lease_sha256 = encode(sha256(adoption_lease_document), 'hex'::text))),
    CONSTRAINT finalization_receipts_check2 CHECK ((seal_receipt_sha256 = encode(sha256(seal_receipt_document), 'hex'::text))),
    CONSTRAINT finalization_receipts_check3 CHECK ((cleanup_receipt_sha256 = encode(sha256(cleanup_receipt_document), 'hex'::text))),
    CONSTRAINT finalization_receipts_check4 CHECK ((authority_receipt_sha256 = encode(sha256(authority_receipt_document), 'hex'::text))),
    CONSTRAINT finalization_receipts_check5 CHECK ((terminal_evidence_sha256 = encode(sha256(terminal_evidence_document), 'hex'::text))),
    CONSTRAINT finalization_receipts_check6 CHECK ((((terminal_state = 'completed'::text) AND (tenant_requirement_catalog_sha256 IS NOT NULL) AND (tenant_requirement_catalog_sha256 ~ '^[0-9a-f]{64}$'::text) AND (tenant_requirement_catalog_document IS NOT NULL) AND (tenant_requirement_count IS NOT NULL) AND ((tenant_requirement_count >= 1) AND (tenant_requirement_count <= 10000)) AND (tenant_target_count IS NOT NULL) AND ((tenant_target_count >= 0) AND (tenant_target_count <= 10000))) OR ((terminal_state = ANY (ARRAY['failed'::text, 'cancelled'::text])) AND (tenant_requirement_catalog_sha256 IS NULL) AND (tenant_requirement_catalog_document IS NULL) AND (tenant_requirement_count IS NULL) AND (tenant_target_count IS NULL)))),
    CONSTRAINT finalization_receipts_check7 CHECK (((tenant_requirement_catalog_sha256 IS NULL) OR (tenant_requirement_catalog_sha256 = encode(sha256(tenant_requirement_catalog_document), 'hex'::text)))),
    CONSTRAINT finalization_receipts_cleanup_receipt_document_check CHECK (((octet_length(cleanup_receipt_document) >= 2) AND (octet_length(cleanup_receipt_document) <= 65536))),
    CONSTRAINT finalization_receipts_finalization_state_sha256_check CHECK ((finalization_state_sha256 ~ '^[0-9a-f]{64}$'::text)),
