    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    domain text NOT NULL,
    group_id text NOT NULL,
    source_generation bigint NOT NULL,
    target_generation bigint NOT NULL,
    source_group_generation bigint NOT NULL,
    target_group_generation bigint NOT NULL,
    inventory_contract_version text NOT NULL,
    inventory_revision integer NOT NULL,
    inventory_sha256 text NOT NULL,
    component_manifest_sha256 text NOT NULL,
    expected_enqueue_fences smallint NOT NULL,
    expected_scheduler_fences smallint NOT NULL,
    expected_consumer_fences smallint NOT NULL,
    item_count bigint NOT NULL,
    state text NOT NULL,
    captured_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    accepted_at timestamp with time zone,
    acceptance_sha256 text,
    CONSTRAINT async_v1_adoption_runs_acceptance_sha256_check CHECK ((acceptance_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT async_v1_adoption_runs_check CHECK ((target_generation = (source_generation + 1))),
    CONSTRAINT async_v1_adoption_runs_check1 CHECK ((target_group_generation = (source_group_generation + 1))),
    CONSTRAINT async_v1_adoption_runs_component_manifest_sha256_check CHECK ((component_manifest_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT async_v1_adoption_runs_domain_check CHECK ((domain ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT async_v1_adoption_runs_expected_consumer_fences_check CHECK (((expected_consumer_fences >= 1) AND (expected_consumer_fences <= 64))),
    CONSTRAINT async_v1_adoption_runs_expected_enqueue_fences_check CHECK (((expected_enqueue_fences >= 1) AND (expected_enqueue_fences <= 64))),
    CONSTRAINT async_v1_adoption_runs_expected_scheduler_fences_check CHECK (((expected_scheduler_fences >= 1) AND (expected_scheduler_fences <= 64))),
    CONSTRAINT async_v1_adoption_runs_group_id_check CHECK ((group_id ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT async_v1_adoption_runs_inventory_contract_version_check CHECK ((inventory_contract_version = 'async-adoption-inventory.v1'::text)),
    CONSTRAINT async_v1_adoption_runs_inventory_revision_check CHECK ((inventory_revision = 1)),
    CONSTRAINT async_v1_adoption_runs_inventory_sha256_check CHECK ((inventory_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT async_v1_adoption_runs_item_count_check CHECK (((item_count >= 0) AND (item_count <= 100000))),
    CONSTRAINT async_v1_adoption_runs_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT async_v1_adoption_runs_source_generation_check CHECK ((source_generation > 0)),
    CONSTRAINT async_v1_adoption_runs_source_group_generation_check CHECK ((source_group_generation > 0)),
    CONSTRAINT async_v1_adoption_runs_state_check CHECK ((state = ANY (ARRAY['inventory'::text, 'disposing'::text, 'accepted'::text]))),
    CONSTRAINT async_v1_runs_terminal_check CHECK ((((state = ANY (ARRAY['inventory'::text, 'disposing'::text])) AND (accepted_at IS NULL) AND (acceptance_sha256 IS NULL)) OR ((state = 'accepted'::text) AND (accepted_at IS NOT NULL) AND (acceptance_sha256 IS NOT NULL)))),
    CONSTRAINT async_v1_runs_time_check CHECK (((captured_at <= created_at) AND ((accepted_at IS NULL) OR (created_at <= accepted_at))))
);


