    expected_discount_count smallint NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone,
    presentation_metadata jsonb NOT NULL,
    presentation_sha256 bytea NOT NULL,
    publication_state text NOT NULL,
    publication_operation_id uuid NOT NULL,
    published_at timestamp with time zone NOT NULL,
    presentation_name text NOT NULL,
    presentation_description text NOT NULL,
    presentation_banner_text text NOT NULL,
    auto_apply boolean NOT NULL,
    available boolean NOT NULL,
    superseded_version_id uuid,
    CONSTRAINT billing_campaign_versions_interval_check CHECK (((ends_at IS NULL) OR (starts_at < ends_at))),
    CONSTRAINT billing_campaign_versions_policy_check CHECK (((id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (publication_operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (version > 0) AND ((expected_discount_count >= 0) AND (expected_discount_count <= 256)) AND (publication_state = 'published'::text))),
    CONSTRAINT billing_campaign_versions_presentation_v2_check CHECK ((((octet_length(presentation_name) >= 1) AND (octet_length(presentation_name) <= 128)) AND (btrim(presentation_name) = presentation_name) AND (octet_length(presentation_description) <= 4096) AND (octet_length(presentation_banner_text) <= 512) AND (presentation_metadata = jsonb_build_object('name', presentation_name, 'description', presentation_description, 'banner_text', presentation_banner_text, 'auto_apply', auto_apply)) AND (octet_length(presentation_sha256) = 32) AND (presentation_sha256 = sha256(convert_to((presentation_metadata)::text, 'UTF8'::name)))))
);


ALTER TABLE platform.billing_campaign_versions OWNER TO harpy_owner;

--
-- Name: billing_campaigns; Type: TABLE; Schema: platform; Owner: harpy_owner
