    revision bigint NOT NULL,
    legacy_created_by uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    CONSTRAINT billing_campaigns_key_check CHECK ((campaign_key ~ '^[a-z][a-z0-9._-]{0,126}[a-z0-9]$'::text)),
    CONSTRAINT billing_campaigns_lifecycle_check CHECK ((((lifecycle = 'active'::text) AND (retired_at IS NULL)) OR ((lifecycle = 'retired'::text) AND (retired_at IS NOT NULL)))),
    CONSTRAINT billing_campaigns_shape_check CHECK (((id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (revision > 0) AND ((retired_at IS NULL) OR (retired_at >= created_at))))
);


ALTER TABLE platform.billing_campaigns OWNER TO harpy_owner;

--
-- Name: billing_campaign_query_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_campaign_query_v1 WITH (security_barrier='true') AS
 WITH current_authority AS (
         SELECT authority_1.authority_id
           FROM (((platform.billing_global_authorities authority_1
             JOIN platform.environment_identity identity ON ((identity.environment_id = authority_1.scope_id)))
             JOIN platform.cutover_groups group_row ON (((group_row.scope_kind = authority_1.scope_kind) AND (group_row.scope_id = authority_1.scope_id) AND (group_row.group_id = authority_1.authority_group_id) AND (group_row.generation = authority_1.authority_group_generation))))
             JOIN platform.domain_cutovers domain_row ON (((domain_row.scope_kind = authority_1.scope_kind) AND (domain_row.scope_id = authority_1.scope_id) AND (domain_row.domain = authority_1.authority_domain) AND (domain_row.generation = authority_1.authority_domain_generation))))
          WHERE ((authority_1.scope_kind = 'global'::text) AND (authority_1.authority_group_id = 'billing'::text) AND (authority_1.authority_domain = 'billing'::text) AND (group_row.writer = 'v2'::text) AND (group_row.state = 'v2'::text) AND (domain_row.writer = 'v2'::text) AND (domain_row.state = 'v2'::text))
        )
 SELECT version_row.id,
    root.id AS campaign_id,
    root.campaign_key,
    root.campaign_key AS campaign_key_folded,
    root.revision,
    root.lifecycle,
    version_row.version,
    "normalize"((version_row.presentation_metadata ->> 'name'::text), 'NFC'::text) AS name,
    "normalize"((version_row.presentation_metadata ->> 'banner_text'::text), 'NFC'::text) AS banner_text,
    version_row.priority,
    version_row.expected_discount_count,
    version_row.starts_at,
    version_row.ends_at,
    version_row.publication_state,
    version_row.published_at
   FROM ((current_authority authority
     JOIN platform.billing_campaigns root ON ((root.authority_id = authority.authority_id)))
     JOIN platform.billing_campaign_versions version_row ON (((version_row.authority_id = authority.authority_id) AND (version_row.campaign_id = root.id))))
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW platform.billing_campaign_query_v1 OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_mappings; Type: TABLE; Schema: platform; Owner: harpy_owner
