    created_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_v1_adoption_mappings_digest_check CHECK ((octet_length(record_sha256) = 32)),
    CONSTRAINT billing_v1_adoption_mappings_key_check CHECK ((((octet_length(source_key) >= 1) AND (octet_length(source_key) <= 512)) AND (target_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT billing_v1_adoption_mappings_kind_check CHECK ((record_kind = ANY (ARRAY['offering'::text, 'campaign'::text, 'discount'::text, 'provider_account'::text, 'base_assignment'::text, 'subscription'::text, 'redemption'::text, 'usage_opening'::text, 'gauge_opening'::text, 'legacy_event'::text])))
);


ALTER TABLE platform.billing_v1_adoption_mappings OWNER TO harpy_owner;

--
-- Name: billing_v1_adoption_runs; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_v1_adoption_runs (
    operation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    authority_id uuid NOT NULL,
    cutover_lease_id uuid NOT NULL,
    cutover_evidence_generation bigint NOT NULL,
    cutover_lease_sha256 bytea NOT NULL,
    cutover_batch_sha256 bytea NOT NULL,
    cutover_session_seal_receipt_id uuid CONSTRAINT billing_v1_adoption_runs_cutover_session_seal_receipt__not_null NOT NULL,
    cutover_session_seal_sha256 bytea NOT NULL,
    cutover_envelope_sha256 bytea NOT NULL,
    contract_version text NOT NULL,
    plan_sha256 bytea NOT NULL,
    source_sha256 bytea NOT NULL,
    plan_bytes bytea NOT NULL,
    plan_document jsonb NOT NULL,
    state text NOT NULL,
    eligible boolean NOT NULL,
    issue_count integer NOT NULL,
    snapshot_at timestamp with time zone NOT NULL,
    source_timezone text NOT NULL,
    applied_count bigint,
    baseline_sha256 bytea,
    target_sha256 bytea,
    money_difference bigint,
    period_difference bigint,
    coupon_difference bigint,
    usage_difference bigint,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    applied_at timestamp with time zone,
    verified_at timestamp with time zone,
    rehearsed_at timestamp with time zone,
    CONSTRAINT billing_v1_adoption_runs_contract_check CHECK (((contract_version = 'harpy/billing-v1-adoption-plan/v1'::text) AND (source_timezone = 'UTC'::text))),
    CONSTRAINT billing_v1_adoption_runs_cutover_identity_check CHECK (((cutover_lease_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (cutover_session_seal_receipt_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (cutover_evidence_generation > 0))),
    CONSTRAINT billing_v1_adoption_runs_digest_check CHECK (((octet_length(plan_sha256) = 32) AND (octet_length(source_sha256) = 32) AND (octet_length(cutover_lease_sha256) = 32) AND (octet_length(cutover_batch_sha256) = 32) AND (octet_length(cutover_session_seal_sha256) = 32) AND (octet_length(cutover_envelope_sha256) = 32) AND ((baseline_sha256 IS NULL) OR (octet_length(baseline_sha256) = 32)) AND ((target_sha256 IS NULL) OR (octet_length(target_sha256) = 32)))),
    CONSTRAINT billing_v1_adoption_runs_document_check CHECK ((((octet_length(plan_bytes) >= 2) AND (octet_length(plan_bytes) <= 67108864)) AND (jsonb_typeof(plan_document) = 'object'::text) AND (plan_document <> '{}'::jsonb))),
    CONSTRAINT billing_v1_adoption_runs_issue_check CHECK (((issue_count >= 0) AND (eligible = (issue_count = 0)) AND (eligible OR (state = 'blocked'::text)))),
    CONSTRAINT billing_v1_adoption_runs_metric_check CHECK ((((applied_count IS NULL) OR (applied_count >= 0)) AND ((money_difference IS NULL) OR (money_difference >= 0)) AND ((period_difference IS NULL) OR (period_difference >= 0)) AND ((coupon_difference IS NULL) OR (coupon_difference >= 0)) AND ((usage_difference IS NULL) OR (usage_difference >= 0)))),
    CONSTRAINT billing_v1_adoption_runs_scope_check CHECK ((((scope_kind = 'global'::text) AND (scope_id <> '00000000-0000-0000-0000-000000000000'::uuid)) OR ((scope_kind = 'tenant'::text) AND (scope_id <> '00000000-0000-0000-0000-000000000000'::uuid)))),
    CONSTRAINT billing_v1_adoption_runs_state_check CHECK ((state = ANY (ARRAY['blocked'::text, 'planned'::text, 'applied'::text, 'verified'::text, 'rollback_rehearsed'::text]))),
    CONSTRAINT billing_v1_adoption_runs_time_check CHECK (((updated_at >= created_at) AND ((applied_at IS NULL) OR ((applied_at >= created_at) AND (applied_at <= updated_at))) AND ((verified_at IS NULL) OR ((verified_at >= created_at) AND (verified_at <= updated_at))) AND ((rehearsed_at IS NULL) OR ((rehearsed_at >= created_at) AND (rehearsed_at <= updated_at)))))
);


ALTER TABLE platform.billing_v1_adoption_runs OWNER TO harpy_owner;

--
-- Name: billing_legacy_identity_alias_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_legacy_identity_alias_v1 WITH (security_barrier='true') AS
 WITH ranked_runs AS (
         SELECT run_1.operation_id,
            run_1.run_id,
            run_1.authority_id,
            run_1.scope_kind,
            run_1.scope_id,
            row_number() OVER (PARTITION BY run_1.authority_id ORDER BY run_1.applied_at DESC NULLS LAST, run_1.updated_at DESC, run_1.operation_id DESC, run_1.run_id DESC) AS "position"
           FROM platform.billing_v1_adoption_runs run_1
          WHERE ((run_1.state = ANY (ARRAY['applied'::text, 'verified'::text, 'rollback_rehearsed'::text])) AND run_1.eligible)
        )
 SELECT run.authority_id,
    run.scope_kind,
    run.scope_id,
    mapping.record_kind,
    (mapping.source_key)::uuid AS legacy_id,
    mapping.target_id AS canonical_id
   FROM (ranked_runs run
     JOIN platform.billing_v1_adoption_mappings mapping ON (((mapping.operation_id = run.operation_id) AND (mapping.run_id = run.run_id) AND (mapping.authority_id = run.authority_id) AND (mapping.scope_kind = run.scope_kind) AND (mapping.scope_id = run.scope_id))))
  WHERE ((run."position" = 1) AND (mapping.record_kind = ANY (ARRAY['offering'::text, 'discount'::text, 'campaign'::text, 'subscription'::text])) AND (NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW platform.billing_legacy_identity_alias_v1 OWNER TO harpy_owner;

--
-- Name: billing_promotion_campaign_read_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_promotion_campaign_read_v1 WITH (security_barrier='true') AS
 SELECT root.authority_id,
    root.id AS campaign_id,
    root.campaign_key,
    root.revision,
    root.lifecycle,
    root.created_at,
    GREATEST(root.created_at, version_row.published_at, COALESCE(root.retired_at, root.created_at)) AS updated_at,
    version_row.id AS version_id,
    version_row.version,
    version_row.presentation_name AS name,
    version_row.presentation_description AS description,
    version_row.presentation_banner_text AS banner_text,
    version_row.auto_apply,
    version_row.available,
    version_row.priority,
    version_row.starts_at,
    version_row.ends_at
   FROM (platform.billing_campaigns root
     JOIN LATERAL ( SELECT candidate.id,
            candidate.authority_id,
            candidate.campaign_id,
            candidate.version,
            candidate.priority,
            candidate.expected_discount_count,
            candidate.starts_at,
            candidate.ends_at,
            candidate.presentation_metadata,
            candidate.presentation_sha256,
            candidate.publication_state,
            candidate.publication_operation_id,
            candidate.published_at,
            candidate.presentation_name,
            candidate.presentation_description,
            candidate.presentation_banner_text,
            candidate.auto_apply,
            candidate.available,
            candidate.superseded_version_id
           FROM platform.billing_campaign_versions candidate
          WHERE ((candidate.authority_id = root.authority_id) AND (candidate.campaign_id = root.id) AND (NOT (EXISTS ( SELECT 1
                   FROM platform.billing_campaign_versions successor
                  WHERE ((successor.authority_id = candidate.authority_id) AND (successor.superseded_version_id = candidate.id))))))
          ORDER BY candidate.version DESC, candidate.id
         LIMIT 1) version_row ON (true))
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW platform.billing_promotion_campaign_read_v1 OWNER TO harpy_owner;

--
-- Name: billing_promotion_campaign_read_v2; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_promotion_campaign_read_v2 WITH (security_barrier='true') AS
 SELECT base.authority_id,
    base.campaign_id,
    base.campaign_key,
    base.revision,
    base.lifecycle,
    base.created_at,
    base.updated_at,
    base.version_id,
    base.version,
    base.name,
    base.description,
    base.banner_text,
    base.auto_apply,
    base.available,
    base.priority,
    base.starts_at,
    base.ends_at,
    COALESCE(identity.legacy_id, base.campaign_id) AS legacy_id,
    root.legacy_created_by AS created_by
   FROM ((platform.billing_promotion_campaign_read_v1 base
     JOIN platform.billing_campaigns root ON (((root.authority_id = base.authority_id) AND (root.id = base.campaign_id))))
     LEFT JOIN platform.billing_legacy_identity_alias_v1 identity ON (((identity.authority_id = base.authority_id) AND (identity.record_kind = 'campaign'::text) AND (identity.canonical_id = base.campaign_id))));


ALTER VIEW platform.billing_promotion_campaign_read_v2 OWNER TO harpy_owner;

--
-- Name: billing_catalog_campaign_snapshot_read_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_catalog_campaign_snapshot_read_v1 WITH (security_barrier='true') AS
 SELECT campaign.authority_id,
    campaign.campaign_id,
    campaign.campaign_key,
    campaign.revision,
    campaign.lifecycle,
    campaign.created_at,
    campaign.updated_at,
    campaign.version_id,
    campaign.version,
    campaign.name,
    campaign.description,
    campaign.banner_text,
    campaign.auto_apply,
    campaign.available,
    campaign.priority,
    campaign.starts_at,
    campaign.ends_at,
    campaign.legacy_id,
    campaign.created_by,
    version_row.publication_state
   FROM (platform.billing_promotion_campaign_read_v2 campaign
     JOIN platform.billing_campaign_versions version_row ON (((version_row.authority_id = campaign.authority_id) AND (version_row.id = campaign.version_id))))
  WHERE (campaign.authority_id = platform.billing_resolve_current_global_authority_v1('billing'::text));


ALTER VIEW platform.billing_catalog_campaign_snapshot_read_v1 OWNER TO harpy_owner;

