    unit text NOT NULL COLLATE pg_catalog."C",
    source_contract text NOT NULL COLLATE pg_catalog."C",
    canonical_sha256 bytea NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_entitlement_definitions_key_check CHECK (((entitlement_key ~ '^[a-z](?:[a-z0-9_.]{0,126}[a-z0-9])?$'::text) AND (owner_module ~ '^[a-z][a-z0-9_]{0,62}[a-z0-9]$'::text) AND (source_contract = ANY (ARRAY['ADR-0082'::text, 'ADR-0120'::text])) AND (registry_version > 0) AND (octet_length(canonical_sha256) = 32))),
    CONSTRAINT billing_entitlement_definitions_type_check CHECK ((((value_type = 'boolean'::text) AND (meter_kind IS NULL) AND (reset_policy IS NULL) AND (enforcement IS NULL) AND (NOT unlimited_allowed) AND (unit = 'enabled'::text)) OR ((value_type = 'integer'::text) AND (meter_kind = ANY (ARRAY['counter'::text, 'gauge'::text])) AND (reset_policy = ANY (ARRAY['billing_period'::text, 'calendar_month_utc'::text, 'never'::text])) AND (enforcement = ANY (ARRAY['hard'::text, 'soft'::text])) AND (unit = ANY (ARRAY['byte'::text, 'count'::text])) AND ((meter_kind <> 'gauge'::text) OR (reset_policy = 'never'::text)))))
);


ALTER TABLE platform.billing_entitlement_definitions OWNER TO harpy_owner;

