    CONSTRAINT billing_offering_versions_id_check CHECK ((id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT billing_offering_versions_interval_check CHECK (((effective_end IS NULL) OR (effective_start < effective_end))),
    CONSTRAINT billing_offering_versions_policy_check CHECK (((publication_operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (version > 0) AND ((trial_days >= 0) AND (trial_days <= 3650)) AND ((grace_days >= 0) AND (grace_days <= 3650)) AND ((expected_price_count >= 1) AND (expected_price_count <= 16)) AND ((expected_grant_count >= 0) AND (expected_grant_count <= 256)) AND (publication_state = 'published'::text))),
    CONSTRAINT billing_offering_versions_presentation_check CHECK (((jsonb_typeof(presentation_metadata) = 'object'::text) AND (octet_length(presentation_sha256) = 32) AND (presentation_sha256 = sha256(convert_to((presentation_metadata)::text, 'UTF8'::name)))))
);


ALTER TABLE platform.billing_offering_versions OWNER TO harpy_owner;

--
-- Name: billing_offerings; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_offerings (
