    currency character(3) NOT NULL COLLATE pg_catalog."C",
    currency_registry_version bigint NOT NULL,
    currency_eligible boolean NOT NULL,
    effective_start timestamp with time zone NOT NULL,
    effective_end timestamp with time zone,
    money_policy_version text NOT NULL,
    published_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_price_versions_interval_check CHECK (((effective_end IS NULL) OR (effective_start < effective_end))),
    CONSTRAINT billing_price_versions_shape_check CHECK (((id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (cadence = ANY (ARRAY['one_time'::text, 'monthly'::text, 'yearly'::text])) AND ((minor_units >= 0) AND (minor_units <= '9000000000000000'::bigint)) AND currency_eligible AND (currency_registry_version > 0) AND (money_policy_version = 'fc_money_v1'::text)))
);


