--
-- Name: billing_catalog_offering_snapshot_read_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_catalog_offering_snapshot_read_v1 WITH (security_barrier='true') AS
 SELECT offering_id AS id,
    offering_key,
    revision,
    lifecycle,
    id AS version_id,
    version,
    publication_state,
    is_public,
    available,
    name,
    description,
    sort_order,
    highlight_label,
    color,
    billing_interval,
    is_base,
    trial_days,
    grace_days,
    expected_price_count,
    expected_grant_count,
    effective_start,
    effective_end,
    created_at,
    updated_at,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', price.id, 'cadence', price.cadence, 'minor_units', price.minor_units, 'currency', btrim((price.currency)::text), 'currency_registry_version', price.currency_registry_version) ORDER BY price.cadence, price.currency, price.id) AS jsonb_agg
           FROM platform.billing_price_versions price
          WHERE (price.offering_version_id = source.id)), '[]'::jsonb) AS prices,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('key', definition.entitlement_key, 'kind', grant_row.value_type, 'boolean', grant_row.boolean_value, 'integer', grant_row.integer_value, 'unlimited', grant_row.unlimited) ORDER BY definition.entitlement_key, definition.id) AS jsonb_agg
           FROM (platform.billing_offering_entitlements grant_row
             JOIN platform.billing_entitlement_definitions definition ON (((definition.authority_id = grant_row.authority_id) AND (definition.id = grant_row.entitlement_definition_id))))
          WHERE (grant_row.offering_version_id = source.id)), '[]'::jsonb) AS entitlements
   FROM platform.billing_offering_query_v2 source;


ALTER VIEW platform.billing_catalog_offering_snapshot_read_v1 OWNER TO harpy_owner;

--
-- Name: billing_catalog_operations; Type: TABLE; Schema: platform; Owner: harpy_owner
