CREATE TABLE platform.billing_catalog_operations (
    operation_id uuid NOT NULL,
    authority_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    idempotency_key text NOT NULL COLLATE pg_catalog."C",
    request_sha256 bytea NOT NULL,
    aggregate_kind text NOT NULL,
    aggregate_id uuid NOT NULL,
    operation_kind text NOT NULL,
    result_version_id uuid,
    result_revision bigint NOT NULL,
    result_version bigint,
    result_lifecycle text NOT NULL,
    reason text,
    occurred_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_catalog_operations_result_check CHECK ((((operation_kind = ANY (ARRAY['create'::text, 'create_version'::text])) AND (result_version_id IS NOT NULL) AND (result_version > 0) AND (result_lifecycle = 'active'::text) AND (reason IS NULL)) OR ((operation_kind = 'retire'::text) AND (result_version_id IS NULL) AND (result_version IS NULL) AND (result_lifecycle = 'retired'::text) AND ((octet_length(reason) >= 1) AND (octet_length(reason) <= 512))))),
    CONSTRAINT billing_catalog_operations_shape_check CHECK (((operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (actor_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (aggregate_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND ((octet_length(idempotency_key) >= 1) AND (octet_length(idempotency_key) <= 128)) AND (btrim(idempotency_key) = idempotency_key) AND (octet_length(request_sha256) = 32) AND (aggregate_kind = ANY (ARRAY['offering'::text, 'discount'::text, 'campaign'::text])) AND (operation_kind = ANY (ARRAY['create'::text, 'create_version'::text, 'retire'::text])) AND (result_revision > 0) AND (result_lifecycle = ANY (ARRAY['active'::text, 'retired'::text]))))
);


ALTER TABLE platform.billing_catalog_operations OWNER TO harpy_owner;

