CREATE TABLE platform.billing_discount_versions (
    id uuid NOT NULL,
    authority_id uuid NOT NULL,
    discount_id uuid NOT NULL,
    version bigint NOT NULL,
    discount_kind text NOT NULL,
    fixed_minor_units bigint,
    currency character(3) COLLATE pg_catalog."C",
    currency_registry_version bigint,
    currency_eligible boolean,
    basis_points integer,
    duration text NOT NULL,
    repeating_cycles bigint,
    priority integer NOT NULL,
    global_use_limit bigint,
    per_tenant_use_limit bigint,
    all_offerings boolean NOT NULL,
    expected_offering_count smallint NOT NULL,
    publication_operation_id uuid NOT NULL,
    valid_start timestamp with time zone NOT NULL,
    valid_end timestamp with time zone,
    published_at timestamp with time zone NOT NULL,
    presentation_name text NOT NULL,
    presentation_description text NOT NULL,
    available boolean NOT NULL,
    CONSTRAINT billing_discount_versions_amount_check CHECK ((((discount_kind = 'fixed'::text) AND ((fixed_minor_units >= 1) AND (fixed_minor_units <= '9000000000000000'::bigint)) AND (currency IS NOT NULL) AND (currency_registry_version > 0) AND currency_eligible AND (basis_points IS NULL)) OR ((discount_kind = 'basis_point'::text) AND ((basis_points >= 1) AND (basis_points <= 10000)) AND (fixed_minor_units IS NULL) AND (currency IS NULL) AND (currency_registry_version IS NULL) AND (currency_eligible IS NULL)))),
    CONSTRAINT billing_discount_versions_duration_check CHECK ((((duration = 'once'::text) AND (repeating_cycles IS NULL)) OR ((duration = 'repeating'::text) AND (repeating_cycles > 0)) OR ((duration = 'forever'::text) AND (repeating_cycles IS NULL)))),
    CONSTRAINT billing_discount_versions_policy_check CHECK (((publication_operation_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (version > 0) AND (priority >= 0) AND ((global_use_limit IS NULL) OR (global_use_limit > 0)) AND ((per_tenant_use_limit IS NULL) OR (per_tenant_use_limit > 0)) AND ((all_offerings AND (expected_offering_count = 0)) OR ((NOT all_offerings) AND ((expected_offering_count >= 1) AND (expected_offering_count <= 256)))) AND ((valid_end IS NULL) OR (valid_start < valid_end)))),
    CONSTRAINT billing_discount_versions_presentation_v2_check CHECK ((((octet_length(presentation_name) >= 1) AND (octet_length(presentation_name) <= 100)) AND (btrim(presentation_name) = presentation_name) AND (octet_length(presentation_description) <= 4096)))
);


