    CONSTRAINT billing_discount_redemptions_duration_check CHECK ((((applied_duration = 'once'::text) AND (applied_repeating_cycles IS NULL)) OR ((applied_duration = 'repeating'::text) AND (applied_repeating_cycles > 0)) OR ((applied_duration = 'forever'::text) AND (applied_repeating_cycles IS NULL)))),
    CONSTRAINT billing_discount_redemptions_time_check CHECK (((applied_priority >= 0) AND (octet_length(policy_sha256) = 32) AND ((relationship_ended_at IS NULL) OR (relationship_ended_at >= redeemed_at))))
);


