    CONSTRAINT billing_entitlement_decisions_reason_check CHECK (((reason = ANY (ARRAY['allowed'::text, 'base_grant'::text, 'subscription_grant'::text, 'override_grant'::text, 'missing_grant'::text, 'hard_limit'::text, 'soft_limit'::text, 'dependency_not_ready'::text])) AND (correlation_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'::text) AND (retain_until > decided_at)))
);


