    result_revision bigint NOT NULL,
    invoice_total_minor_units bigint CONSTRAINT billing_invoice_finalization_invoice_total_minor_units_not_null NOT NULL,
    settled_minor_units bigint NOT NULL,
    amount_due_minor_units bigint NOT NULL,
    credit_balance_minor_units bigint CONSTRAINT billing_invoice_finalizatio_credit_balance_minor_units_not_null NOT NULL,
    currency character(3) NOT NULL COLLATE pg_catalog."C",
    currency_registry_version bigint CONSTRAINT billing_invoice_finalization_currency_registry_version_not_null NOT NULL,
    policy_sha256 bytea NOT NULL,
    finalized_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_invoice_finalizations_shape_check CHECK (((expected_revision > 0) AND (result_revision = (expected_revision + 1)) AND (abs(invoice_total_minor_units) <= '9000000000000000'::bigint) AND ((settled_minor_units >= 0) AND (settled_minor_units <= '9000000000000000'::bigint)) AND ((amount_due_minor_units >= 0) AND (amount_due_minor_units <= '9000000000000000'::bigint)) AND ((credit_balance_minor_units >= 0) AND (credit_balance_minor_units <= '9000000000000000'::bigint)) AND ((amount_due_minor_units)::numeric = GREATEST((0)::numeric, ((invoice_total_minor_units)::numeric - (settled_minor_units)::numeric))) AND ((credit_balance_minor_units)::numeric = GREATEST((0)::numeric, ((settled_minor_units)::numeric - (invoice_total_minor_units)::numeric))) AND (octet_length(policy_sha256) = 32)))
);


