    tax_minor_units bigint NOT NULL,
    debit_adjustment_minor_units bigint NOT NULL,
    credit_adjustment_minor_units bigint NOT NULL,
    line_total_minor_units bigint NOT NULL,
    currency character(3) NOT NULL COLLATE pg_catalog."C",
    currency_registry_version bigint NOT NULL,
    allocation_rank integer NOT NULL,
    money_policy_version text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_invoice_lines_amount_check CHECK ((((gross_minor_units >= 0) AND (gross_minor_units <= '9000000000000000'::bigint)) AND ((discount_minor_units >= 0) AND (discount_minor_units <= gross_minor_units)) AND ((tax_minor_units >= 0) AND (tax_minor_units <= '9000000000000000'::bigint)) AND ((debit_adjustment_minor_units >= 0) AND (debit_adjustment_minor_units <= '9000000000000000'::bigint)) AND ((credit_adjustment_minor_units >= 0) AND (credit_adjustment_minor_units <= '9000000000000000'::bigint)) AND (abs(line_total_minor_units) <= '9000000000000000'::bigint))),
    CONSTRAINT billing_invoice_lines_shape_check CHECK (((line_sequence > 0) AND (allocation_rank > 0) AND (line_kind = ANY (ARRAY['item'::text, 'tax'::text, 'discount'::text, 'adjustment'::text, 'credit'::text])) AND ((octet_length(description) >= 1) AND (octet_length(description) <= 2048)) AND (quantity > 0) AND (unit_minor_units >= 0) AND (money_policy_version = 'fc_money_v1'::text))),
    CONSTRAINT billing_invoice_lines_total_check CHECK ((((gross_minor_units)::numeric = ((unit_minor_units)::numeric * (quantity)::numeric)) AND ((line_total_minor_units)::numeric = (((((gross_minor_units)::numeric - (discount_minor_units)::numeric) + (tax_minor_units)::numeric) + (debit_adjustment_minor_units)::numeric) - (credit_adjustment_minor_units)::numeric))))
);


