--
-- Name: billing_invoices; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_invoices (
    id uuid NOT NULL,
    authority_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    invoice_number text NOT NULL COLLATE pg_catalog."C",
    state text NOT NULL,
    currency character(3) NOT NULL COLLATE pg_catalog."C",
    currency_registry_version bigint NOT NULL,
    currency_eligible boolean NOT NULL,
    gross_minor_units bigint NOT NULL,
    discount_minor_units bigint NOT NULL,
    tax_minor_units bigint NOT NULL,
    debit_adjustment_minor_units bigint NOT NULL,
    credit_adjustment_minor_units bigint NOT NULL,
    invoice_total_minor_units bigint NOT NULL,
    settled_minor_units bigint NOT NULL,
    amount_due_minor_units bigint NOT NULL,
    credit_balance_minor_units bigint NOT NULL,
    money_policy_version text NOT NULL,
    policy_sha256 bytea NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    finalized_at timestamp with time zone,
    revision bigint NOT NULL,
    CONSTRAINT billing_invoices_money_check CHECK ((currency_eligible AND (money_policy_version = 'fc_money_v1'::text) AND (octet_length(policy_sha256) = 32) AND ((gross_minor_units >= 0) AND (gross_minor_units <= '9000000000000000'::bigint)) AND ((discount_minor_units >= 0) AND (discount_minor_units <= gross_minor_units)) AND ((tax_minor_units >= 0) AND (tax_minor_units <= '9000000000000000'::bigint)) AND ((debit_adjustment_minor_units >= 0) AND (debit_adjustment_minor_units <= '9000000000000000'::bigint)) AND ((credit_adjustment_minor_units >= 0) AND (credit_adjustment_minor_units <= '9000000000000000'::bigint)) AND (abs(invoice_total_minor_units) <= '9000000000000000'::bigint) AND ((settled_minor_units >= 0) AND (settled_minor_units <= '9000000000000000'::bigint)) AND ((amount_due_minor_units >= 0) AND (amount_due_minor_units <= '9000000000000000'::bigint)) AND ((credit_balance_minor_units >= 0) AND (credit_balance_minor_units <= '9000000000000000'::bigint)))),
    CONSTRAINT billing_invoices_state_check CHECK ((((state = 'draft'::text) AND (finalized_at IS NULL)) OR ((state = 'finalized'::text) AND (finalized_at IS NOT NULL)))),
    CONSTRAINT billing_invoices_time_check CHECK (((period_start < period_end) AND (updated_at >= created_at) AND ((finalized_at IS NULL) OR (finalized_at >= created_at)) AND (revision > 0))),
    CONSTRAINT billing_invoices_total_check CHECK ((((invoice_total_minor_units)::numeric = (((((gross_minor_units)::numeric - (discount_minor_units)::numeric) + (tax_minor_units)::numeric) + (debit_adjustment_minor_units)::numeric) - (credit_adjustment_minor_units)::numeric)) AND ((amount_due_minor_units)::numeric = GREATEST((0)::numeric, ((invoice_total_minor_units)::numeric - (settled_minor_units)::numeric))) AND ((credit_balance_minor_units)::numeric = GREATEST((0)::numeric, ((settled_minor_units)::numeric - (invoice_total_minor_units)::numeric)))))
);


ALTER TABLE platform.billing_invoices OWNER TO harpy_owner;

--
-- Name: billing_legal_holds; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_legal_holds (
    id uuid NOT NULL,
    authority_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    state text NOT NULL,
    placed_by uuid NOT NULL,
    place_operation_id uuid NOT NULL,
    place_idempotency_key text NOT NULL COLLATE pg_catalog."C",
    place_request_sha256 bytea NOT NULL,
    reason text NOT NULL,
    ticket_reference text NOT NULL COLLATE pg_catalog."C",
    placed_at timestamp with time zone NOT NULL,
    released_by uuid,
    release_operation_id uuid,
    release_idempotency_key text COLLATE pg_catalog."C",
    release_request_sha256 bytea,
    release_reason text,
    released_at timestamp with time zone,
    revision bigint NOT NULL,
    CONSTRAINT billing_legal_holds_shape_check CHECK ((((octet_length(place_idempotency_key) >= 1) AND (octet_length(place_idempotency_key) <= 128)) AND (octet_length(place_request_sha256) = 32) AND ((octet_length(reason) >= 1) AND (octet_length(reason) <= 2048)) AND ((octet_length(ticket_reference) >= 1) AND (octet_length(ticket_reference) <= 256)) AND ((release_idempotency_key IS NULL) OR ((octet_length(release_idempotency_key) >= 1) AND (octet_length(release_idempotency_key) <= 128))))),
    CONSTRAINT billing_legal_holds_state_check CHECK ((((state = 'active'::text) AND (revision = 1) AND (released_by IS NULL) AND (release_operation_id IS NULL) AND (release_idempotency_key IS NULL) AND (release_request_sha256 IS NULL) AND (release_reason IS NULL) AND (released_at IS NULL)) OR ((state = 'released'::text) AND (revision = 2) AND (released_by IS NOT NULL) AND (release_operation_id IS NOT NULL) AND (release_idempotency_key IS NOT NULL) AND (octet_length(release_request_sha256) = 32) AND ((octet_length(release_reason) >= 1) AND (octet_length(release_reason) <= 2048)) AND (released_at >= placed_at))))
);


