    effective_at timestamp with time zone NOT NULL,
    manifest_sha256 text NOT NULL COLLATE pg_catalog."C",
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_license_offering_shape_check CHECK (((uuid_extract_version(operation_id) = 7) AND (uuid_extract_version(offering_version_id) = 7) AND (delivery_kind = ANY (ARRAY['connected'::text, 'airgap'::text, 'development'::text])) AND (snapshot_sequence > 0) AND (revision > 0) AND (snapshot_sha256 ~ '^[0-9a-f]{64}$'::text) AND (offering_sha256 ~ '^[0-9a-f]{64}$'::text) AND (manifest_sha256 ~ '^[0-9a-f]{64}$'::text) AND ((octet_length(offering_document) >= 2) AND (octet_length(offering_document) <= 65536)) AND (offering_sha256 = encode(sha256(offering_document), 'hex'::text))))
);


