--
-- Name: billing_license_refresh_attempts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_license_refresh_attempts (
    operation_id uuid NOT NULL,
    attempt integer NOT NULL,
    lease_token uuid NOT NULL,
    state text NOT NULL,
    claimed_at timestamp with time zone NOT NULL,
    lease_until timestamp with time zone NOT NULL,
    finished_at timestamp with time zone,
    failure_kind text,
    CONSTRAINT billing_license_refresh_attempt_shape_check CHECK (((attempt > 0) AND (claimed_at < lease_until) AND (state = ANY (ARRAY['running'::text, 'source_failed'::text, 'verification_failed'::text, 'lease_expired'::text, 'succeeded'::text, 'noop'::text, 'sequence_conflict'::text, 'sequence_rollback'::text])))),
    CONSTRAINT billing_license_refresh_attempt_state_check CHECK ((((state = 'running'::text) AND (finished_at IS NULL) AND (failure_kind IS NULL)) OR ((state = 'source_failed'::text) AND (finished_at IS NOT NULL) AND (failure_kind = 'source_unavailable'::text)) OR ((state = 'verification_failed'::text) AND (finished_at IS NOT NULL) AND (failure_kind = 'verification_failed'::text)) OR ((state = 'lease_expired'::text) AND (finished_at IS NOT NULL) AND (failure_kind = 'lease_expired'::text)) OR ((state = 'sequence_conflict'::text) AND (finished_at IS NOT NULL) AND (failure_kind = 'sequence_conflict'::text)) OR ((state = 'sequence_rollback'::text) AND (finished_at IS NOT NULL) AND (failure_kind = 'sequence_rollback'::text)) OR ((state = ANY (ARRAY['succeeded'::text, 'noop'::text])) AND (finished_at IS NOT NULL) AND (failure_kind IS NULL))))
);


ALTER TABLE platform.billing_license_refresh_attempts OWNER TO harpy_owner;

--
-- Name: billing_license_refresh_operations; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_license_refresh_operations (
    operation_id uuid NOT NULL,
    license_id uuid NOT NULL,
    licensee_organization_id uuid CONSTRAINT billing_license_refresh_opera_licensee_organization_id_not_null NOT NULL,
    environment_id uuid NOT NULL,
    delivery_kind text NOT NULL,
    nonce bytea NOT NULL,
    component_versions jsonb NOT NULL,
    state text NOT NULL,
    current_attempt integer DEFAULT 0 NOT NULL,
    lease_token uuid,
    lease_until timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT billing_license_refresh_operation_shape_check CHECK (((uuid_extract_version(operation_id) = 7) AND (license_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (licensee_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (delivery_kind = ANY (ARRAY['connected'::text, 'airgap'::text, 'development'::text])) AND (octet_length(nonce) = 32) AND (jsonb_typeof(component_versions) = 'array'::text) AND ((jsonb_array_length(component_versions) >= 1) AND (jsonb_array_length(component_versions) <= 64)) AND (state = ANY (ARRAY['pending'::text, 'running'::text, 'succeeded'::text, 'fenced'::text])) AND (current_attempt >= 0) AND (created_at <= updated_at))),
    CONSTRAINT billing_license_refresh_operation_state_check CHECK ((((state = 'running'::text) AND (lease_token IS NOT NULL) AND (lease_until IS NOT NULL) AND (completed_at IS NULL)) OR ((state = 'pending'::text) AND (lease_token IS NULL) AND (lease_until IS NULL) AND (completed_at IS NULL)) OR ((state = ANY (ARRAY['succeeded'::text, 'fenced'::text])) AND (lease_token IS NULL) AND (lease_until IS NULL) AND (completed_at IS NOT NULL))))
);


