    revision bigint NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_license_refresh_target_shape CHECK (((license_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (environment_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (licensee_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (delivery_kind = ANY (ARRAY['connected'::text, 'airgap'::text, 'development'::text])) AND (observed_sequence > 0) AND (observed_sha256 ~ '^[0-9a-f]{64}$'::text) AND (uuid_extract_version(operation_id) = 7) AND (revision > 0) AND isfinite(next_attempt_at) AND isfinite(updated_at) AND ((lease_until IS NULL) OR (isfinite(lease_until) AND (lease_until > updated_at)))))
);


