    expected_revision bigint NOT NULL,
    authority_revision bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_license_restore_shape_check CHECK (((uuid_extract_version(operation_id) = 7) AND (restore_receipt_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (license_binding_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (restore_receipt_sha256 ~ '^[0-9a-f]{64}$'::text) AND (previous_sequence > 0) AND (accepted_sequence > previous_sequence) AND (previous_sha256 ~ '^[0-9a-f]{64}$'::text) AND (accepted_sha256 ~ '^[0-9a-f]{64}$'::text) AND (expected_revision > 0) AND (authority_revision = (expected_revision + 1))))
);


