    CONSTRAINT billing_license_projection_value_check CHECK ((((value_type = 'boolean'::text) AND (boolean_value IS NOT NULL) AND (integer_value IS NULL) AND (NOT unlimited)) OR ((value_type = 'integer'::text) AND (boolean_value IS NULL) AND ((unlimited AND (integer_value IS NULL)) OR ((NOT unlimited) AND (integer_value >= 0))))))
);


