--
-- Name: billing_license_snapshots; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_license_snapshots (
    snapshot_id uuid DEFAULT gen_random_uuid() NOT NULL,
    license_id uuid NOT NULL,
    licensee_organization_id uuid NOT NULL,
    environment_id uuid NOT NULL,
    delivery_kind text NOT NULL,
    issuer text NOT NULL COLLATE pg_catalog."C",
    key_id text NOT NULL COLLATE pg_catalog."C",
    sequence bigint NOT NULL,
    payload_sha256 text NOT NULL COLLATE pg_catalog."C",
    status text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    not_before timestamp with time zone NOT NULL,
    refresh_after timestamp with time zone NOT NULL,
    grant_valid_until timestamp with time zone NOT NULL,
    grace_until timestamp with time zone NOT NULL,
    commercial_expires_at timestamp with time zone NOT NULL,
    release_channel text NOT NULL COLLATE pg_catalog."C",
    features jsonb NOT NULL,
    limits jsonb NOT NULL,
    canonical_payload bytea NOT NULL,
    signed_document bytea NOT NULL,
    accepted_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_license_snapshot_shape_check CHECK (((license_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (licensee_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (delivery_kind = ANY (ARRAY['connected'::text, 'airgap'::text, 'development'::text])) AND ((octet_length(issuer) >= 1) AND (octet_length(issuer) <= 256)) AND (issuer = btrim(issuer)) AND (issuer !~ '[[:cntrl:]]'::text) AND (key_id ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text) AND (sequence > 0) AND (payload_sha256 ~ '^[0-9a-f]{64}$'::text) AND (status = ANY (ARRAY['active'::text, 'suspended'::text, 'revoked'::text, 'expired'::text])) AND (release_channel ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text) AND (jsonb_typeof(features) = 'object'::text) AND (jsonb_typeof(limits) = 'object'::text) AND ((octet_length(canonical_payload) >= 2) AND (octet_length(canonical_payload) <= 65536)) AND ((octet_length(signed_document) >= 2) AND (octet_length(signed_document) <= 65536)) AND (payload_sha256 = encode(sha256(canonical_payload), 'hex'::text)))),
    CONSTRAINT billing_license_snapshot_time_check CHECK (((issued_at <= refresh_after) AND (not_before <= grant_valid_until) AND (grant_valid_until <= grace_until) AND (not_before <= commercial_expires_at)))
);


