    CONSTRAINT billing_meter_periods_policy_check CHECK ((((meter_kind = 'counter'::text) AND (reset_policy = ANY (ARRAY['billing_period'::text, 'calendar_month_utc'::text, 'never'::text]))) OR ((meter_kind = 'gauge'::text) AND (reset_policy = 'never'::text))))
);


