--
-- Name: billing_metered_resource_receipts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_metered_resource_receipts (
    operation_id uuid NOT NULL,
    authority_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    resource_kind text NOT NULL COLLATE pg_catalog."C",
    mutation_kind text NOT NULL COLLATE pg_catalog."C",
    owner_fact_id uuid NOT NULL,
    idempotency_key text NOT NULL COLLATE pg_catalog."C",
    request_sha256 bytea NOT NULL,
    feature_enabled boolean NOT NULL,
    allowed boolean NOT NULL,
    gauge_delta bigint NOT NULL,
    current_amount bigint NOT NULL,
    limit_amount bigint NOT NULL,
    unlimited boolean NOT NULL,
    usage_decision_id uuid,
    usage_entry_id uuid,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_metered_resource_receipts_identity_check CHECK (((uuid_extract_version(operation_id) = 7) AND (uuid_extract_version(owner_fact_id) = 7) AND (resource_kind = ANY (ARRAY['api_endpoint'::text, 'analytics_dashboard'::text])) AND (mutation_kind = ANY (ARRAY['create'::text, 'update'::text, 'publish'::text, 'revalidate'::text, 'delete'::text, 'restore'::text])) AND (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::text) AND (octet_length(request_sha256) = 32) AND (current_amount >= 0) AND (limit_amount >= 0) AND ((NOT unlimited) OR (limit_amount = 0)) AND isfinite(recorded_at))),
    CONSTRAINT billing_metered_resource_receipts_outcome_check CHECK ((((mutation_kind = ANY (ARRAY['update'::text, 'publish'::text, 'revalidate'::text])) AND (allowed = feature_enabled) AND (gauge_delta = 0) AND (current_amount = 0) AND (limit_amount = 0) AND (NOT unlimited)) OR ((mutation_kind = ANY (ARRAY['create'::text, 'restore'::text])) AND (allowed = (feature_enabled AND (unlimited OR (current_amount < limit_amount)))) AND (gauge_delta =
CASE
    WHEN allowed THEN 1
    ELSE 0
END)) OR ((mutation_kind = 'delete'::text) AND allowed AND (NOT feature_enabled) AND (gauge_delta = ANY (ARRAY[('-1'::integer)::bigint, (0)::bigint]))))),
    CONSTRAINT billing_metered_resource_receipts_usage_check CHECK ((((gauge_delta <> 0) AND (usage_decision_id IS NOT NULL) AND (usage_entry_id IS NOT NULL)) OR ((mutation_kind = ANY (ARRAY['create'::text, 'restore'::text])) AND feature_enabled AND (NOT allowed) AND (gauge_delta = 0) AND (usage_decision_id IS NOT NULL) AND (usage_entry_id IS NULL)) OR ((gauge_delta = 0) AND (NOT ((mutation_kind = ANY (ARRAY['create'::text, 'restore'::text])) AND feature_enabled AND (NOT allowed))) AND (usage_decision_id IS NULL) AND (usage_entry_id IS NULL))))
);


ALTER TABLE platform.billing_metered_resource_receipts OWNER TO harpy_owner;

--
-- Name: billing_metered_resource_reconcile_receipts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

