    request_sha256 bytea CONSTRAINT billing_metered_resource_reconcile_rece_request_sha256_not_null NOT NULL,
    evidence_sha256 bytea CONSTRAINT billing_metered_resource_reconcile_rec_evidence_sha256_not_null NOT NULL,
    evidence_exists boolean CONSTRAINT billing_metered_resource_reconcile_rec_evidence_exists_not_null NOT NULL,
    evidence_active boolean CONSTRAINT billing_metered_resource_reconcile_rec_evidence_active_not_null NOT NULL,
    included_in_opening boolean CONSTRAINT billing_metered_resource_reconcile_included_in_opening_not_null NOT NULL,
    changed boolean NOT NULL,
