    measured_at timestamp with time zone CONSTRAINT billing_metered_resource_reconcile_receipt_measured_at_not_null NOT NULL,
    recorded_at timestamp with time zone CONSTRAINT billing_metered_resource_reconcile_receipt_recorded_at_not_null NOT NULL,
    CONSTRAINT billing_metered_resource_reconcile_shape_check CHECK (((uuid_extract_version(operation_id) = 7) AND (uuid_extract_version(owner_fact_id) = 7) AND (resource_kind = ANY (ARRAY['api_endpoint'::text, 'analytics_dashboard'::text])) AND (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'::text) AND (octet_length(request_sha256) = 32) AND (octet_length(evidence_sha256) = 32) AND (evidence_exists OR (NOT evidence_active)) AND ((NOT included_in_opening) OR (evidence_exists AND evidence_active)) AND ((gauge_delta >= '-1'::integer) AND (gauge_delta <= 1)) AND (changed OR (gauge_delta = 0)) AND (current_amount >= 0) AND (limit_amount >= 0) AND ((NOT unlimited) OR (limit_amount = 0)) AND ((gauge_delta <> 0) OR ((current_amount = 0) AND (limit_amount = 0) AND (NOT unlimited))) AND isfinite(measured_at) AND isfinite(recorded_at) AND (((gauge_delta = 0) AND (usage_decision_id IS NULL) AND (usage_entry_id IS NULL)) OR ((gauge_delta <> 0) AND (usage_decision_id IS NOT NULL) AND (usage_entry_id IS NOT NULL)))))
);


ALTER TABLE platform.billing_metered_resource_reconcile_receipts OWNER TO harpy_owner;

--
-- Name: billing_metered_resources; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_metered_resources (
    authority_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    resource_kind text NOT NULL COLLATE pg_catalog."C",
    owner_fact_id uuid NOT NULL,
    counted_state text NOT NULL COLLATE pg_catalog."C",
    origin_kind text NOT NULL COLLATE pg_catalog."C",
    opening_evidence_sha256 bytea,
    opening_measured_at timestamp with time zone,
    last_operation_id uuid NOT NULL,
    revision bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_metered_resources_shape_check CHECK (((uuid_extract_version(owner_fact_id) = 7) AND (uuid_extract_version(last_operation_id) = 7) AND (resource_kind = ANY (ARRAY['api_endpoint'::text, 'analytics_dashboard'::text])) AND (counted_state = ANY (ARRAY['active'::text, 'released'::text])) AND (origin_kind = ANY (ARRAY['runtime'::text, 'adopted'::text])) AND (revision > 0) AND isfinite(created_at) AND isfinite(updated_at) AND (updated_at >= created_at) AND (((origin_kind = 'runtime'::text) AND (opening_evidence_sha256 IS NULL) AND (opening_measured_at IS NULL)) OR ((origin_kind = 'adopted'::text) AND (octet_length(opening_evidence_sha256) = 32) AND isfinite(opening_measured_at)))))
);


ALTER TABLE platform.billing_metered_resources OWNER TO harpy_owner;

--
-- Name: billing_offering_query_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_offering_query_v1 WITH (security_barrier='true') AS
 WITH current_authority AS (
         SELECT authority_1.authority_id
           FROM (((platform.billing_global_authorities authority_1
             JOIN platform.environment_identity identity ON ((identity.environment_id = authority_1.scope_id)))
             JOIN platform.cutover_groups group_row ON (((group_row.scope_kind = authority_1.scope_kind) AND (group_row.scope_id = authority_1.scope_id) AND (group_row.group_id = authority_1.authority_group_id) AND (group_row.generation = authority_1.authority_group_generation))))
             JOIN platform.domain_cutovers domain_row ON (((domain_row.scope_kind = authority_1.scope_kind) AND (domain_row.scope_id = authority_1.scope_id) AND (domain_row.domain = authority_1.authority_domain) AND (domain_row.generation = authority_1.authority_domain_generation))))
          WHERE ((authority_1.scope_kind = 'global'::text) AND (authority_1.authority_group_id = 'billing'::text) AND (authority_1.authority_domain = 'billing'::text) AND (group_row.writer = 'v2'::text) AND (group_row.state = 'v2'::text) AND (domain_row.writer = 'v2'::text) AND (domain_row.state = 'v2'::text))
        )
 SELECT version_row.id,
    root.id AS offering_id,
    root.offering_key,
    root.offering_key AS offering_key_folded,
    "normalize"((version_row.presentation_metadata ->> 'name'::text), 'NFC'::text) AS name,
    root.revision,
    root.lifecycle,
    version_row.version,
    version_row.is_base,
    version_row.is_public,
    version_row.trial_days,
    version_row.grace_days,
    version_row.expected_price_count,
    version_row.expected_grant_count,
    version_row.effective_start,
    version_row.effective_end,
    version_row.publication_state,
    version_row.published_at
   FROM ((current_authority authority
     JOIN platform.billing_offerings root ON ((root.authority_id = authority.authority_id)))
     JOIN platform.billing_offering_versions version_row ON (((version_row.authority_id = authority.authority_id) AND (version_row.offering_id = root.id))))
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW platform.billing_offering_query_v1 OWNER TO harpy_owner;

--
-- Name: billing_platform_license_refresh_requests; Type: TABLE; Schema: platform; Owner: harpy_owner
