    request_sha256 text CONSTRAINT billing_platform_license_refresh_reques_request_sha256_not_null NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_platform_license_refresh_request_shape CHECK (((uuid_extract_version(operation_id) = 7) AND (uuid_extract_version(environment_id) = 7) AND (license_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (actor_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$'::text) AND (request_sha256 ~ '^[0-9a-f]{64}$'::text) AND isfinite(created_at)))
);


