--
-- Name: billing_promotion_discount_read_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_promotion_discount_read_v1 WITH (security_barrier='true') AS
 SELECT root.authority_id,
    root.id AS discount_id,
    root.normalized_code AS code,
    root.revision,
    root.lifecycle,
    root.created_at,
    GREATEST(root.created_at, version_row.published_at, COALESCE(root.revoked_at, root.created_at)) AS updated_at,
    version_row.id AS version_id,
    version_row.version,
    version_row.presentation_name AS name,
    version_row.presentation_description AS description,
    version_row.available,
    version_row.discount_kind,
    version_row.fixed_minor_units,
    (version_row.currency)::text AS currency,
    version_row.currency_registry_version,
    version_row.basis_points,
    version_row.duration,
    version_row.repeating_cycles,
    version_row.priority,
    version_row.all_offerings,
    version_row.valid_start,
    version_row.valid_end,
    version_row.global_use_limit,
    version_row.per_tenant_use_limit,
    COALESCE(( SELECT count(*) AS count
           FROM (platform.billing_discount_redemptions redemption
             JOIN platform.billing_discount_versions redeemed_version ON ((redeemed_version.id = redemption.discount_version_id)))
          WHERE (redeemed_version.discount_id = root.id)), (0)::bigint) AS used_count,
    COALESCE(( SELECT array_agg(binding.offering_version_id ORDER BY binding.offering_version_id) AS array_agg
           FROM platform.billing_discount_offerings binding
          WHERE ((binding.authority_id = root.authority_id) AND (binding.discount_version_id = version_row.id))), ARRAY[]::uuid[]) AS offering_version_ids,
    COALESCE(( SELECT array_agg(offering.id ORDER BY offering.id) AS array_agg
           FROM ((platform.billing_discount_offerings binding
             JOIN platform.billing_offering_versions offering_version ON (((offering_version.authority_id = binding.authority_id) AND (offering_version.id = binding.offering_version_id))))
             JOIN platform.billing_offerings offering ON (((offering.authority_id = offering_version.authority_id) AND (offering.id = offering_version.offering_id))))
          WHERE ((binding.authority_id = root.authority_id) AND (binding.discount_version_id = version_row.id))), ARRAY[]::uuid[]) AS offering_ids,
    COALESCE(( SELECT array_agg(campaign_version.campaign_id ORDER BY campaign_version.campaign_id) AS array_agg
           FROM (platform.billing_campaign_discounts binding
             JOIN platform.billing_campaign_versions campaign_version ON (((campaign_version.authority_id = binding.authority_id) AND (campaign_version.id = binding.campaign_version_id))))
          WHERE ((binding.authority_id = root.authority_id) AND (binding.discount_version_id = version_row.id) AND (NOT (EXISTS ( SELECT 1
                   FROM platform.billing_campaign_versions successor
                  WHERE ((successor.authority_id = campaign_version.authority_id) AND (successor.superseded_version_id = campaign_version.id))))))), ARRAY[]::uuid[]) AS campaign_ids
   FROM (platform.billing_discounts root
     JOIN LATERAL ( SELECT candidate.id,
            candidate.authority_id,
            candidate.discount_id,
            candidate.version,
            candidate.discount_kind,
            candidate.fixed_minor_units,
            candidate.currency,
            candidate.currency_registry_version,
            candidate.currency_eligible,
            candidate.basis_points,
            candidate.duration,
            candidate.repeating_cycles,
            candidate.priority,
            candidate.global_use_limit,
            candidate.per_tenant_use_limit,
            candidate.all_offerings,
            candidate.expected_offering_count,
            candidate.publication_operation_id,
            candidate.valid_start,
            candidate.valid_end,
            candidate.published_at,
            candidate.presentation_name,
            candidate.presentation_description,
            candidate.available
           FROM platform.billing_discount_versions candidate
          WHERE ((candidate.authority_id = root.authority_id) AND (candidate.discount_id = root.id))
          ORDER BY candidate.version DESC, candidate.id
         LIMIT 1) version_row ON (true))
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW platform.billing_promotion_discount_read_v1 OWNER TO harpy_owner;

--
-- Name: billing_promotion_discount_read_v2; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_promotion_discount_read_v2 WITH (security_barrier='true') AS
 SELECT base.authority_id,
    base.discount_id,
    base.code,
    base.revision,
    base.lifecycle,
    base.created_at,
    base.updated_at,
    base.version_id,
    base.version,
    base.name,
    base.description,
    base.available,
    base.discount_kind,
    base.fixed_minor_units,
    base.currency,
    base.currency_registry_version,
    base.basis_points,
    base.duration,
    base.repeating_cycles,
    base.priority,
    base.all_offerings,
    base.valid_start,
    base.valid_end,
    base.global_use_limit,
    base.per_tenant_use_limit,
    base.used_count,
    base.offering_version_ids,
    base.offering_ids,
    base.campaign_ids,
    COALESCE(identity.legacy_id, base.discount_id) AS legacy_id,
    ARRAY( SELECT COALESCE(offering_identity.legacy_id, selected.offering_id) AS "coalesce"
           FROM (unnest(base.offering_ids) selected(offering_id)
             LEFT JOIN platform.billing_legacy_identity_alias_v1 offering_identity ON (((offering_identity.authority_id = base.authority_id) AND (offering_identity.record_kind = 'offering'::text) AND (offering_identity.canonical_id = selected.offering_id))))
          ORDER BY COALESCE(offering_identity.legacy_id, selected.offering_id)) AS legacy_offering_ids,
    ARRAY( SELECT COALESCE(campaign_identity.legacy_id, selected.campaign_id) AS "coalesce"
           FROM (unnest(base.campaign_ids) selected(campaign_id)
             LEFT JOIN platform.billing_legacy_identity_alias_v1 campaign_identity ON (((campaign_identity.authority_id = base.authority_id) AND (campaign_identity.record_kind = 'campaign'::text) AND (campaign_identity.canonical_id = selected.campaign_id))))
          ORDER BY COALESCE(campaign_identity.legacy_id, selected.campaign_id)) AS legacy_campaign_ids,
    root.legacy_created_by AS created_by
   FROM ((platform.billing_promotion_discount_read_v1 base
     JOIN platform.billing_discounts root ON (((root.authority_id = base.authority_id) AND (root.id = base.discount_id))))
     LEFT JOIN platform.billing_legacy_identity_alias_v1 identity ON (((identity.authority_id = base.authority_id) AND (identity.record_kind = 'discount'::text) AND (identity.canonical_id = base.discount_id))));


ALTER VIEW platform.billing_promotion_discount_read_v2 OWNER TO harpy_owner;

--
-- Name: billing_provider_accounts; Type: TABLE; Schema: platform; Owner: harpy_owner
