    lifecycle text NOT NULL,
    supports_checkout boolean NOT NULL,
    supports_webhooks boolean NOT NULL,
    supports_proration boolean NOT NULL,
    supports_refunds boolean NOT NULL,
    created_at timestamp with time zone NOT NULL,
    disabled_at timestamp with time zone,
    revision bigint NOT NULL,
    CONSTRAINT billing_provider_accounts_key_check CHECK (((provider_key ~ '^[a-z][a-z0-9._-]{0,62}$'::text) AND (provider_account_key ~ '^[a-zA-Z0-9][a-zA-Z0-9._:-]{0,254}$'::text))),
    CONSTRAINT billing_provider_accounts_lifecycle_check CHECK ((((lifecycle = 'active'::text) AND (disabled_at IS NULL)) OR ((lifecycle = 'disabled'::text) AND (disabled_at IS NOT NULL)))),
    CONSTRAINT billing_provider_accounts_manual_check CHECK (((provider_key <> 'manual'::text) OR ((NOT supports_checkout) AND (NOT supports_webhooks) AND (NOT supports_proration) AND (NOT supports_refunds)))),
    CONSTRAINT billing_provider_accounts_revision_check CHECK ((revision > 0)),
    CONSTRAINT billing_provider_accounts_time_check CHECK (((disabled_at IS NULL) OR (disabled_at >= created_at)))
);


ALTER TABLE platform.billing_provider_accounts OWNER TO harpy_owner;

--
-- Name: billing_provider_commands; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_provider_commands (
    id uuid NOT NULL,
    authority_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    provider_account_id uuid NOT NULL,
    provider_object_mapping_id uuid,
    subscription_id uuid,
    command_kind text NOT NULL,
    effect_key text NOT NULL COLLATE pg_catalog."C",
    request_sha256 bytea NOT NULL,
    state text NOT NULL,
    provider_receipt_reference text COLLATE pg_catalog."C",
    last_error_code text COLLATE pg_catalog."C",
    attempts integer NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    revision bigint NOT NULL,
    actor_id uuid,
    active_job_id uuid,
    finalizer_job_id uuid,
    CONSTRAINT billing_provider_commands_attempt_check CHECK ((((attempts >= 0) AND (attempts <= 25)) AND (revision > 0) AND ((completed_at IS NULL) OR (completed_at >= requested_at)))),
    CONSTRAINT billing_provider_commands_kind_check CHECK (((command_kind = ANY (ARRAY['checkout'::text, 'change'::text, 'cancel'::text, 'refund'::text, 'reconcile'::text])) AND ((octet_length(effect_key) >= 1) AND (octet_length(effect_key) <= 256)) AND (octet_length(request_sha256) = 32))),
    CONSTRAINT billing_provider_commands_receipt_check CHECK ((((state = 'succeeded'::text) AND (provider_receipt_reference IS NOT NULL) AND (last_error_code IS NULL)) OR (state <> 'succeeded'::text))),
    CONSTRAINT billing_provider_commands_route_check CHECK ((((actor_id IS NULL) AND (active_job_id IS NULL) AND (finalizer_job_id IS NULL)) OR ((actor_id IS NOT NULL) AND (actor_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (uuid_extract_version(active_job_id) = 7) AND (uuid_extract_version(finalizer_job_id) = 7) AND (active_job_id <> finalizer_job_id)))),
    CONSTRAINT billing_provider_commands_state_check CHECK ((((state = ANY (ARRAY['queued'::text, 'running'::text])) AND (completed_at IS NULL)) OR ((state = ANY (ARRAY['succeeded'::text, 'failed'::text, 'reconcile_required'::text])) AND (completed_at IS NOT NULL))))
);


ALTER TABLE platform.billing_provider_commands OWNER TO harpy_owner;

--
-- Name: billing_provider_events; Type: TABLE; Schema: platform; Owner: harpy_owner
