    normalized_sha256 bytea NOT NULL,
    CONSTRAINT billing_provider_events_integrity_check CHECK (((normalized_at >= occurred_at) AND ((octet_length(canonical_fact) >= 1) AND (octet_length(canonical_fact) <= 65536)) AND (octet_length(normalized_sha256) = 32) AND (normalized_sha256 = sha256(canonical_fact)))),
    CONSTRAINT billing_provider_events_ordering_check CHECK ((((ordering_mode = 'contiguous'::text) AND (ordering_sequence > 0) AND (ordering_previous = (ordering_sequence - 1))) OR ((ordering_mode = 'requires_reconciliation'::text) AND (ordering_sequence = 0) AND (ordering_previous = 0)))),
    CONSTRAINT billing_provider_events_schema_check CHECK (((normalized_schema ~ '^[a-z][a-z0-9_.]{2,127}$'::text) AND (normalized_version > 0)))
);


ALTER TABLE platform.billing_provider_events OWNER TO harpy_owner;

