    CONSTRAINT billing_provider_objects_id_check CHECK ((((octet_length(provider_object_id) >= 1) AND (octet_length(provider_object_id) <= 512)) AND (revision > 0) AND ((retired_at IS NULL) OR (retired_at >= created_at)))),
    CONSTRAINT billing_provider_objects_kind_check CHECK ((((object_kind = 'customer'::text) AND (subscription_id IS NULL) AND (invoice_id IS NULL)) OR ((object_kind = 'subscription'::text) AND (subscription_id IS NOT NULL)) OR ((object_kind = ANY (ARRAY['invoice'::text, 'payment'::text])) AND (invoice_id IS NOT NULL))))
);


ALTER TABLE platform.billing_provider_objects OWNER TO harpy_owner;

