    authority_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    subscription_revision bigint NOT NULL,
    offering_version_id uuid NOT NULL,
    price_version_id uuid NOT NULL,
    price_source_sha256 bytea NOT NULL,
    state text NOT NULL COLLATE pg_catalog."C",
    cadence text NOT NULL COLLATE pg_catalog."C",
    currency character(3) NOT NULL COLLATE pg_catalog."C",
    currency_registry_version bigint NOT NULL,
    source_minor_units bigint NOT NULL,
    monthly_minor_units bigint NOT NULL,
    annual_minor_units bigint NOT NULL,
    refreshed_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_revenue_projection_shape_check CHECK (((id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (subscription_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (subscription_revision > 0) AND (octet_length(price_source_sha256) = 32) AND (state = ANY (ARRAY['active'::text, 'past_due'::text])) AND (cadence = ANY (ARRAY['monthly'::text, 'yearly'::text])) AND (currency ~ '^[A-Z]{3}$'::text) AND (currency_registry_version > 0) AND ((source_minor_units >= 0) AND (source_minor_units <= '9000000000000000'::bigint)) AND (monthly_minor_units >= 0) AND (annual_minor_units >= 0)))
);


ALTER TABLE platform.billing_revenue_projection OWNER TO harpy_owner;

--
-- Name: billing_revenue_rebuilds; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_revenue_rebuilds (
    id uuid NOT NULL,
    authority_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    authority_group_generation bigint NOT NULL,
    billing_generation bigint NOT NULL,
    source_count bigint NOT NULL,
    projected_count bigint NOT NULL,
    source_revision_ceiling bigint NOT NULL,
    before_sha256 bytea NOT NULL,
    source_sha256 bytea NOT NULL,
    after_sha256 bytea NOT NULL,
    rebuilt_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_revenue_rebuilds_shape_check CHECK (((id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (actor_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (authority_group_generation > 0) AND (billing_generation > 0) AND (source_count >= 0) AND (projected_count = source_count) AND (source_revision_ceiling >= 0) AND (octet_length(before_sha256) = 32) AND (octet_length(source_sha256) = 32) AND (octet_length(after_sha256) = 32) AND (source_sha256 = after_sha256)))
);


