    CONSTRAINT billing_subscription_changes_revision_check CHECK (((revision > 0) AND (effective_at >= created_at) AND ((resolved_at IS NULL) OR (resolved_at >= created_at)))),
    CONSTRAINT billing_subscription_changes_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'provider'::text, 'v1_adopted'::text]))),
    CONSTRAINT billing_subscription_changes_state_check CHECK ((((state = 'scheduled'::text) AND (resolved_at IS NULL)) OR ((state = ANY (ARRAY['applied'::text, 'cancelled'::text])) AND (resolved_at IS NOT NULL))))
);


