    authority_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    source_operation_id uuid NOT NULL,
    source_kind text NOT NULL,
    operation_kind text NOT NULL COLLATE pg_catalog."C",
    request_sha256 bytea NOT NULL,
    result_sha256 bytea NOT NULL,
    expected_revision bigint NOT NULL,
    result_revision bigint NOT NULL,
    result_state text NOT NULL,
    completed_at timestamp with time zone NOT NULL,
    result_provider_account_id uuid CONSTRAINT billing_subscription_operat_result_provider_account_id_not_null NOT NULL,
    result_offering_version_id uuid CONSTRAINT billing_subscription_operat_result_offering_version_id_not_null NOT NULL,
    result_price_version_id uuid CONSTRAINT billing_subscription_operation_result_price_version_id_not_null NOT NULL,
    result_currency character(3) NOT NULL COLLATE pg_catalog."C",
    result_period_start timestamp with time zone,
    result_period_end timestamp with time zone,
    result_trial_ends_at timestamp with time zone,
    result_grace_ends_at timestamp with time zone,
    result_cancel_at_period_end boolean CONSTRAINT billing_subscription_operat_result_cancel_at_period_en_not_null NOT NULL,
    result_cancel_at timestamp with time zone,
    result_updated_at timestamp with time zone NOT NULL,
    CONSTRAINT billing_subscription_operations_result_check CHECK (((octet_length(request_sha256) = 32) AND (octet_length(result_sha256) = 32) AND (expected_revision >= 0) AND (result_revision = (expected_revision + 1)) AND (result_state = ANY (ARRAY['pending'::text, 'trialing'::text, 'active'::text, 'past_due'::text, 'paused'::text, 'cancelled'::text, 'expired'::text])))),
    CONSTRAINT billing_subscription_operations_snapshot_check CHECK ((((result_period_start IS NULL) AND (result_period_end IS NULL)) OR ((result_period_start IS NOT NULL) AND (result_period_end IS NOT NULL) AND (result_period_start < result_period_end)))),
    CONSTRAINT billing_subscription_operations_source_check CHECK (((source_kind = ANY (ARRAY['actor'::text, 'provider'::text, 'job'::text, 'v1_adopted'::text])) AND (operation_kind ~ '^[a-z][a-z0-9._]{2,127}$'::text))),
    CONSTRAINT billing_subscription_operations_window_check CHECK ((((result_state <> 'trialing'::text) OR ((result_trial_ends_at IS NOT NULL) AND (result_trial_ends_at = result_period_end))) AND ((result_state <> 'past_due'::text) OR (result_grace_ends_at IS NOT NULL)) AND (result_cancel_at_period_end = (result_cancel_at IS NOT NULL)) AND ((result_cancel_at IS NULL) OR (result_cancel_at = result_period_end)) AND (result_updated_at <= completed_at)))
);


