);


ALTER TABLE platform.billing_v1_event_archive OWNER TO harpy_owner;

--
-- Name: billing_v1_event_report_query_v1; Type: VIEW; Schema: platform; Owner: harpy_owner
--

CREATE VIEW platform.billing_v1_event_report_query_v1 WITH (security_barrier='true') AS
 WITH current_global AS (
         SELECT authority.authority_id
           FROM (((platform.billing_global_authorities authority
             JOIN platform.environment_identity identity ON ((identity.environment_id = authority.scope_id)))
             JOIN platform.cutover_groups group_row ON (((group_row.scope_kind = authority.scope_kind) AND (group_row.scope_id = authority.scope_id) AND (group_row.group_id = authority.authority_group_id) AND (group_row.generation = authority.authority_group_generation))))
             JOIN platform.domain_cutovers domain_row ON (((domain_row.scope_kind = authority.scope_kind) AND (domain_row.scope_id = authority.scope_id) AND (domain_row.domain = authority.authority_domain) AND (domain_row.generation = authority.authority_domain_generation))))
          WHERE ((authority.scope_kind = 'global'::text) AND (authority.authority_group_id = 'billing'::text) AND (authority.authority_domain = 'billing'::text) AND (group_row.writer = 'v2'::text) AND (group_row.state = 'v2'::text) AND (domain_row.writer = 'v2'::text) AND (domain_row.state = 'v2'::text))
        ), current_tenants AS (
         SELECT authority.authority_id,
            authority.tenant_id
           FROM (((platform.billing_tenant_authorities authority
             JOIN platform.tenants tenant ON ((tenant.id = authority.tenant_id)))
             JOIN platform.cutover_groups group_row ON (((group_row.scope_kind = authority.scope_kind) AND (group_row.scope_id = authority.scope_id) AND (group_row.group_id = authority.authority_group_id) AND (group_row.generation = authority.authority_group_generation))))
             JOIN platform.domain_cutovers billing_row ON (((billing_row.scope_kind = authority.scope_kind) AND (billing_row.scope_id = authority.scope_id) AND (billing_row.domain = authority.billing_domain) AND (billing_row.generation = authority.billing_generation))))
          WHERE ((group_row.writer = 'v2'::text) AND (group_row.state = 'v2'::text) AND (billing_row.writer = 'v2'::text) AND (billing_row.state = 'v2'::text))
        )
 SELECT archive.source_event_id AS id,
    archive.tenant_id,
    archive.source_subscription_id AS subscription_id,
    archive.event_type,
    archive.amount_cents,
    archive.currency,
    archive.description,
    archive.metadata,
    archive.created_at
   FROM (current_tenants authority
     JOIN platform.billing_v1_event_archive archive ON (((archive.authority_id = authority.authority_id) AND (archive.tenant_id = authority.tenant_id))))
UNION ALL
 SELECT audit.id,
    audit.tenant_id,
    COALESCE(alias.legacy_id, audit.subscription_id) AS subscription_id,
        CASE
            WHEN ((audit.kind = 'cancellation_scheduled'::text) OR (audit.reason = 'cancellation'::text)) THEN 'subscription_cancelled'::text
            WHEN (audit.kind = 'cancellation_resumed'::text) THEN 'subscription_resumed'::text
            WHEN (audit.kind = 'trial_claimed'::text) THEN 'trial_started'::text
            WHEN ((audit.kind = 'manual_change_scheduled'::text) OR (audit.reason = 'manual_change'::text)) THEN 'plan_changed'::text
            WHEN (audit.reason = 'trial_end'::text) THEN 'trial_ended'::text
            WHEN (subscription.state = 'expired'::text) THEN 'subscription_expired'::text
            WHEN (subscription.state = 'cancelled'::text) THEN 'subscription_cancelled'::text
            ELSE 'subscription_renewed'::text
        END AS event_type,
    (0)::bigint AS amount_cents,
    btrim((price.currency)::text) AS currency,
    audit.reason AS description,
    jsonb_build_object('source_kind', audit.source_kind, 'before_revision', audit.before_revision, 'after_revision', audit.after_revision, 'source_operation_id', audit.source_operation_id) AS metadata,
    audit.occurred_at AS created_at
   FROM (((((current_global global_authority
     JOIN current_tenants authority ON (true))
     JOIN platform.billing_subscription_audit audit ON (((audit.authority_id = authority.authority_id) AND (audit.tenant_id = authority.tenant_id))))
     JOIN platform.billing_subscriptions subscription ON (((subscription.id = audit.subscription_id) AND (subscription.tenant_id = audit.tenant_id))))
     JOIN platform.billing_price_versions price ON (((price.authority_id = global_authority.authority_id) AND (price.id = subscription.price_version_id))))
     LEFT JOIN platform.billing_legacy_identity_alias_v1 alias ON (((alias.authority_id = authority.authority_id) AND (alias.scope_kind = 'tenant'::text) AND (alias.scope_id = audit.tenant_id) AND (alias.record_kind = 'subscription'::text) AND (alias.canonical_id = audit.subscription_id))))
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW platform.billing_v1_event_report_query_v1 OWNER TO harpy_owner;

--
-- Name: billing_webhook_receipts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.billing_webhook_receipts (
    id uuid NOT NULL,
    authority_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    provider_account_id uuid NOT NULL,
    provider_object_mapping_id uuid NOT NULL,
    provider_event_id text NOT NULL COLLATE pg_catalog."C",
    body_sha256 bytea NOT NULL,
    authentication_digest bytea NOT NULL,
    verification_revision integer NOT NULL,
    event_occurred_at timestamp with time zone NOT NULL,
    signature_issued_at timestamp with time zone NOT NULL,
    algorithm text COLLATE pg_catalog."C",
    nonce bytea,
    encrypted_body bytea,
    wrapped_dek bytea,
    key_id text NOT NULL COLLATE pg_catalog."C",
    verified_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone NOT NULL,
    processor_state text NOT NULL,
