    CONSTRAINT billing_webhook_receipts_time_check CHECK (((event_occurred_at <= received_at) AND (signature_issued_at <= received_at) AND (verified_at <= received_at) AND (raw_body_expires_at > received_at) AND (retain_until >= raw_body_expires_at) AND (revision > 0)))
);


