    CONSTRAINT cutover_operations_database_check CHECK (((source_system_identifier > (0)::numeric) AND (source_system_identifier = target_system_identifier) AND ((source_database_oid >= 1) AND (source_database_oid <= '4294967295'::bigint)) AND (source_database_oid = target_database_oid))),
    CONSTRAINT cutover_operations_digest_check CHECK (((lease_manifest_sha256 ~ '^[0-9a-f]{64}$'::text) AND (plan_sha256 ~ '^[0-9a-f]{64}$'::text) AND (transform_manifest_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT cutover_operations_generation_check CHECK (((cutover_generation > 0) AND (lease_generation > 0))),
