    CONSTRAINT cutover_operations_scope_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT cutover_operations_slot_check CHECK (((slot_name ~ '^[a-z][a-z0-9_]{0,62}$'::text) AND (slot_name <> publication_name))),
    CONSTRAINT cutover_operations_state_check CHECK ((state = ANY (ARRAY['planned'::text, 'copying'::text, 'shadow'::text, 'quiescing'::text, 'blocked'::text, 'completed'::text, 'failed'::text, 'cancelled'::text]))),
