    CONSTRAINT cutover_transition_events_approval_check CHECK (((event_kind <> 'approval'::text) OR ((request_event_id IS NOT NULL) AND (approved_by = actor_id) AND (requested_by <> actor_id)))),
    CONSTRAINT cutover_transition_events_domain_check CHECK (((domain IS NULL) OR (domain = ANY (ARRAY['analytics'::text, 'billing'::text, 'catalog'::text, 'documents'::text, 'iam'::text, 'notifications'::text, 'system_resource_layout'::text, 'tenancy'::text, 'work'::text, 'workflow'::text])))),
    CONSTRAINT cutover_transition_events_generation_check CHECK (((previous_generation > 0) AND (new_generation >= previous_generation))),
