    CONSTRAINT cutover_transition_events_kind_check CHECK ((event_kind = ANY (ARRAY['request'::text, 'approval'::text, 'fence'::text, 'quiesce'::text, 'switch'::text, 'rollback'::text, 'blocked'::text, 'closure'::text]))),
    CONSTRAINT cutover_transition_events_new_writer_check CHECK ((((new_state = ANY (ARRAY['v1'::text, 'shadow'::text])) AND (new_writer = 'v1'::text)) OR ((new_state = 'v2'::text) AND (new_writer = 'v2'::text)) OR ((new_state = ANY (ARRAY['quiescing'::text, 'fenced'::text])) AND (new_writer = 'none'::text)))),
