    CONSTRAINT cutover_transition_events_reference_check CHECK (((octet_length(change_reference) >= 1) AND (octet_length(change_reference) <= 256))),
    CONSTRAINT cutover_transition_events_request_check CHECK (((event_kind <> 'request'::text) OR (request_event_id IS NULL))),
    CONSTRAINT cutover_transition_events_scope_check CHECK ((scope_kind = ANY (ARRAY['global'::text, 'tenant'::text]))),
    CONSTRAINT cutover_transition_events_state_check CHECK (((previous_state = ANY (ARRAY['v1'::text, 'shadow'::text, 'quiescing'::text, 'v2'::text, 'fenced'::text])) AND (new_state = ANY (ARRAY['v1'::text, 'shadow'::text, 'quiescing'::text, 'v2'::text, 'fenced'::text])))),
    CONSTRAINT cutover_transition_events_target_check CHECK ((((target_kind = 'group'::text) AND (domain IS NULL)) OR ((target_kind = 'domain'::text) AND (domain IS NOT NULL))))
);


