    CONSTRAINT iam_recovery_anchor_state_evidence_ck CHECK ((((state = 'pending'::text) AND (authority_generation IS NULL) AND (protected_state_sha256 IS NULL) AND (authority_ack_sha256 IS NULL) AND (deleted_at IS NULL)) OR ((state = ANY (ARRAY['active'::text, 'stale'::text])) AND (authority_generation IS NOT NULL) AND (protected_state_sha256 IS NOT NULL) AND (authority_ack_sha256 IS NOT NULL) AND (deleted_at IS NULL)) OR ((state = 'deleted'::text) AND (authority_generation IS NOT NULL) AND (protected_state_sha256 IS NOT NULL) AND (authority_ack_sha256 IS NOT NULL) AND (deleted_at IS NOT NULL)))),
