    CONSTRAINT iam_recovery_anchors_attestation_type_check CHECK (((octet_length(attestation_type) >= 1) AND (octet_length(attestation_type) <= 64))),
    CONSTRAINT iam_recovery_anchors_authority_ack_sha256_check CHECK (((authority_ack_sha256 IS NULL) OR (octet_length(authority_ack_sha256) = 32))),
    CONSTRAINT iam_recovery_anchors_authority_generation_check CHECK ((authority_generation > 0)),
    CONSTRAINT iam_recovery_anchors_backup_eligible_check CHECK ((backup_eligible = false)),
    CONSTRAINT iam_recovery_anchors_backup_state_check CHECK ((backup_state = false)),
    CONSTRAINT iam_recovery_anchors_check CHECK ((updated_at >= created_at)),
    CONSTRAINT iam_recovery_anchors_counter_policy_check CHECK ((counter_policy = 'adr0062'::text)),
    CONSTRAINT iam_recovery_anchors_credential_id_check CHECK (((octet_length(credential_id) >= 1) AND (octet_length(credential_id) <= 1024))),
    CONSTRAINT iam_recovery_anchors_generation_check CHECK ((generation > 0)),
    CONSTRAINT iam_recovery_anchors_protected_state_sha256_check CHECK (((protected_state_sha256 IS NULL) OR (octet_length(protected_state_sha256) = 32))),
    CONSTRAINT iam_recovery_anchors_public_key_cose_check CHECK (((octet_length(public_key_cose) >= 1) AND (octet_length(public_key_cose) <= 4096))),
    CONSTRAINT iam_recovery_anchors_revision_check CHECK ((revision > 0)),
    CONSTRAINT iam_recovery_anchors_rp_id_check CHECK (((octet_length(rp_id) >= 1) AND (octet_length(rp_id) <= 253))),
    CONSTRAINT iam_recovery_anchors_sign_count_check CHECK ((sign_count >= 0)),
    CONSTRAINT iam_recovery_anchors_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'active'::text, 'stale'::text, 'deleted'::text]))),
