    environment_id uuid NOT NULL,
    restore_receipt_id uuid NOT NULL,
    restore_receipt_sha256 text CONSTRAINT platformops_restored_license_gr_restore_receipt_sha256_not_null NOT NULL,
    license_binding_id uuid NOT NULL,
    license_id uuid NOT NULL,
    licensee_organization_id uuid CONSTRAINT platformops_restored_license__licensee_organization_id_not_null NOT NULL,
    delivery_kind text NOT NULL,
    issuer text NOT NULL,
    previous_sequence bigint NOT NULL,
    previous_sha256 text NOT NULL,
    next_sequence bigint NOT NULL,
    next_sha256 text NOT NULL,
    manifest_sha256 text NOT NULL,
    authority_revision bigint NOT NULL,
    lease_until timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT platformops_restored_license_shape CHECK (((uuid_extract_version(operation_id) = 7) AND (uuid_extract_version(license_binding_id) = 7) AND (environment_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (restore_receipt_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (license_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (licensee_organization_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (restore_receipt_sha256 ~ '^[0-9a-f]{64}$'::text) AND (delivery_kind = ANY (ARRAY['connected'::text, 'airgap'::text, 'development'::text])) AND ((octet_length(issuer) >= 1) AND (octet_length(issuer) <= 256)) AND (issuer = btrim(issuer)) AND (issuer !~ '[[:cntrl:]]'::text) AND (previous_sequence > 0) AND (next_sequence > previous_sequence) AND (previous_sha256 ~ '^[0-9a-f]{64}$'::text) AND (next_sha256 ~ '^[0-9a-f]{64}$'::text) AND (manifest_sha256 ~ '^[0-9a-f]{64}$'::text) AND (authority_revision > 0) AND isfinite(lease_until) AND (created_at <= updated_at) AND (updated_at < lease_until)))
);


