    next_executor text NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    error_code text,
    created_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    checkpoint_record_id uuid,
    processed_rows bigint DEFAULT 0 NOT NULL,
    canonical_step_bytes bytea,
    checkpoint_canonical_bytes bigint,
    checkpoint_page_sha256 text,
    CONSTRAINT schema_job_steps_attempt_check CHECK ((attempt >= 0)),
    CONSTRAINT schema_job_steps_canonical_bytes_check CHECK (((canonical_step_bytes IS NULL) OR (((octet_length(canonical_step_bytes) >= 2) AND (octet_length(canonical_step_bytes) <= 1048576)) AND pg_input_is_valid(convert_from(canonical_step_bytes, 'UTF8'::name), 'jsonb'::text) AND (encode(sha256(canonical_step_bytes), 'hex'::text) = step_sha256)))),
    CONSTRAINT schema_job_steps_error_code_check CHECK ((error_code ~ '^[a-z][a-z0-9_]{2,63}$'::text)),
    CONSTRAINT schema_job_steps_executor_kind_check CHECK ((((executor_kind = 'forms_runtime'::text) AND (operation_id = ANY (ARRAY['activate_generation'::text, 'disable_old_writer'::text, 'enable_dual_write'::text, 'retain_generation'::text]))) OR ((executor_kind = 'migrator'::text) AND (operation_id = ANY (ARRAY['add_constraint'::text, 'add_field_column'::text, 'add_relation_table'::text, 'backfill_field_batch'::text, 'cleanup_invalid_index'::text, 'create_form_table'::text, 'create_index'::text, 'create_index_concurrently'::text, 'drop_constraint'::text, 'drop_field_column'::text, 'drop_form_table'::text, 'drop_index'::text, 'drop_index_concurrently'::text, 'drop_relation_table'::text, 'set_field_not_null'::text, 'validate_constraint'::text, 'verify_storage'::text]))))),
    CONSTRAINT schema_job_steps_generation_check CHECK ((generation > 0)),
    CONSTRAINT schema_job_steps_operation_check CHECK ((operation_id = ANY (ARRAY['activate_generation'::text, 'add_constraint'::text, 'add_field_column'::text, 'add_relation_table'::text, 'backfill_field_batch'::text, 'cleanup_invalid_index'::text, 'create_form_table'::text, 'create_index'::text, 'create_index_concurrently'::text, 'disable_old_writer'::text, 'drop_constraint'::text, 'drop_field_column'::text, 'drop_form_table'::text, 'drop_index'::text, 'drop_index_concurrently'::text, 'drop_relation_table'::text, 'enable_dual_write'::text, 'retain_generation'::text, 'set_field_not_null'::text, 'validate_constraint'::text, 'verify_storage'::text]))),
    CONSTRAINT schema_job_steps_ordinal_check CHECK (((ordinal >= 0) AND (ordinal <= 4095))),
    CONSTRAINT schema_job_steps_page_evidence_check CHECK ((((checkpoint_canonical_bytes IS NULL) AND (checkpoint_page_sha256 IS NULL)) OR ((operation_id = 'backfill_field_batch'::text) AND ((checkpoint_canonical_bytes >= 1) AND (checkpoint_canonical_bytes <= 8388608)) AND (checkpoint_page_sha256 ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT schema_job_steps_payload_check CHECK (((jsonb_typeof(identifier_mapping) = 'object'::text) AND (identifier_mapping <> '{}'::jsonb) AND ((octet_length((identifier_mapping)::text) >= 2) AND (octet_length((identifier_mapping)::text) <= 65536)) AND (jsonb_typeof(arguments) = 'object'::text) AND ((octet_length((arguments)::text) >= 2) AND (octet_length((arguments)::text) <= 262144)) AND (((identifier_mapping)::text || (arguments)::text) !~* '"(sql|raw_sql|function_body|routine_body|client_identifier)"[[:space:]]*:'::text))),
    CONSTRAINT schema_job_steps_plan_sha256_check CHECK ((plan_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schema_job_steps_progress_check CHECK ((((operation_id = 'backfill_field_batch'::text) AND (((processed_rows = 0) AND (checkpoint_record_id IS NULL)) OR ((processed_rows > 0) AND (checkpoint_record_id IS NOT NULL)))) OR ((operation_id <> 'backfill_field_batch'::text) AND (processed_rows = 0) AND (checkpoint_record_id IS NULL)))),
    CONSTRAINT schema_job_steps_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'running'::text, 'retryable'::text, 'lease_expired'::text, 'succeeded'::text, 'failed'::text, 'blocked'::text, 'skipped'::text, 'cancelled'::text]))),
    CONSTRAINT schema_job_steps_state_shape_check CHECK ((((state = 'pending'::text) AND (attempt = 0) AND (next_executor = executor_kind) AND (started_at IS NULL) AND (finished_at IS NULL) AND (error_code IS NULL)) OR ((state = 'running'::text) AND (attempt > 0) AND (next_executor = executor_kind) AND (started_at IS NOT NULL) AND (finished_at IS NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['retryable'::text, 'lease_expired'::text])) AND (attempt > 0) AND (next_executor = executor_kind) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL)) OR ((state = ANY (ARRAY['succeeded'::text, 'skipped'::text])) AND (attempt > 0) AND (next_executor = 'none'::text) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::text, 'blocked'::text, 'cancelled'::text])) AND (attempt > 0) AND (next_executor = 'none'::text) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL)))),
    CONSTRAINT schema_job_steps_step_sha256_check CHECK ((step_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schema_job_steps_time_check CHECK (((created_at <= updated_at) AND ((started_at IS NULL) OR (created_at <= started_at)) AND ((finished_at IS NULL) OR (started_at <= finished_at)) AND ((finished_at IS NULL) OR (finished_at <= updated_at)))),
    CONSTRAINT schema_job_steps_transaction_class_check CHECK ((((operation_id = ANY (ARRAY['cleanup_invalid_index'::text, 'create_index_concurrently'::text, 'drop_index_concurrently'::text])) AND (transaction_class = 'concurrent_index'::text)) OR ((operation_id <> ALL (ARRAY['cleanup_invalid_index'::text, 'create_index_concurrently'::text, 'drop_index_concurrently'::text])) AND (transaction_class = 'transactional'::text))))
);


