    compiler_version text NOT NULL,
    plan_contract_version text NOT NULL,
    canonical_plan jsonb NOT NULL,
    plan_sha256 text NOT NULL,
    step_count integer NOT NULL,
    next_step_ordinal integer DEFAULT 0 NOT NULL,
    generation bigint DEFAULT 1 NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    next_executor text DEFAULT 'migrator'::text NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone NOT NULL,
    lease_id uuid,
    lease_owner_id uuid,
    leased_at timestamp with time zone,
    lease_heartbeat_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    last_lease_expired_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    finished_at timestamp with time zone,
    failure_code text,
    canonical_plan_bytes bytea,
    submission_authority_id uuid,
    submission_authority_group_id text,
    submission_group_generation bigint,
    submission_billing_generation bigint,
    submission_forms_generation bigint,
    CONSTRAINT schema_jobs_attempt_check CHECK ((attempt >= 0)),
    CONSTRAINT schema_jobs_canonical_bytes_check CHECK (((canonical_plan_bytes IS NULL) OR (((octet_length(canonical_plan_bytes) >= 2) AND (octet_length(canonical_plan_bytes) <= 1048576)) AND pg_input_is_valid(convert_from(canonical_plan_bytes, 'UTF8'::name), 'jsonb'::text) AND ((convert_from(canonical_plan_bytes, 'UTF8'::name))::jsonb = canonical_plan) AND (encode(sha256(canonical_plan_bytes), 'hex'::text) = plan_sha256)))),
    CONSTRAINT schema_jobs_compiler_version_check CHECK ((compiler_version ~ '^[0-9]+\.[0-9]+\.[0-9]+$'::text)),
    CONSTRAINT schema_jobs_executor_check CHECK ((((state = 'queued'::text) AND (next_executor = 'migrator'::text)) OR ((state = 'awaiting_runtime'::text) AND (next_executor = 'forms_runtime'::text)) OR ((state = ANY (ARRAY['leased'::text, 'running'::text, 'lease_expired'::text])) AND (next_executor = ANY (ARRAY['migrator'::text, 'forms_runtime'::text]))) OR ((state = ANY (ARRAY['succeeded'::text, 'failed'::text, 'cancelled'::text])) AND (next_executor = 'none'::text)))),
    CONSTRAINT schema_jobs_failure_code_check CHECK ((failure_code ~ '^[a-z][a-z0-9_]{2,63}$'::text)),
    CONSTRAINT schema_jobs_generation_check CHECK ((generation > 0)),
    CONSTRAINT schema_jobs_lease_check CHECK ((((state = ANY (ARRAY['leased'::text, 'running'::text])) AND (lease_id IS NOT NULL) AND (lease_owner_id IS NOT NULL) AND (leased_at IS NOT NULL) AND (lease_heartbeat_at IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (leased_at <= lease_heartbeat_at) AND (lease_heartbeat_at <= updated_at) AND (updated_at < lease_expires_at)) OR ((state = 'lease_expired'::text) AND (lease_id IS NOT NULL) AND (lease_owner_id IS NOT NULL) AND (leased_at IS NOT NULL) AND (lease_heartbeat_at IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (last_lease_expired_at IS NOT NULL) AND (leased_at <= lease_heartbeat_at) AND (lease_expires_at <= last_lease_expired_at) AND (last_lease_expired_at <= updated_at)) OR ((state <> ALL (ARRAY['leased'::text, 'running'::text, 'lease_expired'::text])) AND (lease_id IS NULL) AND (lease_owner_id IS NULL) AND (leased_at IS NULL) AND (lease_heartbeat_at IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT schema_jobs_outcome_check CHECK ((((state = ANY (ARRAY['queued'::text, 'leased'::text, 'running'::text, 'awaiting_runtime'::text])) AND (finished_at IS NULL) AND (failure_code IS NULL)) OR ((state = 'lease_expired'::text) AND (finished_at IS NULL) AND (failure_code = 'lease_expired'::text)) OR ((state = 'succeeded'::text) AND (finished_at IS NOT NULL) AND (failure_code IS NULL)) OR ((state = ANY (ARRAY['failed'::text, 'cancelled'::text])) AND (finished_at IS NOT NULL) AND (failure_code IS NOT NULL)))),
    CONSTRAINT schema_jobs_owner_check CHECK ((owner ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT schema_jobs_plan_contract_version_check CHECK ((plan_contract_version = ANY (ARRAY['forms-schema-plan.v1'::text, 'forms-schema-plan.v2'::text]))),
    CONSTRAINT schema_jobs_plan_sha256_check CHECK ((plan_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT schema_jobs_plan_shape_check CHECK (((jsonb_typeof(canonical_plan) = 'object'::text) AND ((octet_length((canonical_plan)::text) >= 2) AND (octet_length((canonical_plan)::text) <= 1048576)) AND ((canonical_plan)::text !~* '"(sql|raw_sql|function_body|routine_body|client_identifier)"[[:space:]]*:'::text))),
    CONSTRAINT schema_jobs_resource_kind_check CHECK ((resource_kind = ANY (ARRAY['form_storage'::text, 'form_purge'::text]))),
    CONSTRAINT schema_jobs_resource_revision_check CHECK ((resource_revision > 0)),
    CONSTRAINT schema_jobs_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'leased'::text, 'running'::text, 'lease_expired'::text, 'awaiting_runtime'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT schema_jobs_step_count_check CHECK (((step_count >= 1) AND (step_count <= 4096))),
    CONSTRAINT schema_jobs_step_pointer_check CHECK ((((next_step_ordinal >= 0) AND (next_step_ordinal <= step_count)) AND (((state = 'succeeded'::text) AND (next_step_ordinal = step_count)) OR ((state <> 'succeeded'::text) AND (next_step_ordinal < step_count))))),
    CONSTRAINT schema_jobs_submission_authority_v2_check CHECK ((((plan_contract_version = 'forms-schema-plan.v1'::text) AND (submission_authority_id IS NULL) AND (submission_authority_group_id IS NULL) AND (submission_group_generation IS NULL) AND (submission_billing_generation IS NULL) AND (submission_forms_generation IS NULL)) OR ((plan_contract_version = 'forms-schema-plan.v2'::text) AND (compiler_version = '2.0.0'::text) AND (canonical_plan_bytes IS NOT NULL) AND (NOT (uuid_extract_version(submission_authority_id) IS DISTINCT FROM 7)) AND (submission_authority_group_id = 'billing'::text) AND ((submission_group_generation >= 1) AND (submission_group_generation <= '9007199254740991'::bigint)) AND ((submission_billing_generation >= 1) AND (submission_billing_generation <= '9007199254740991'::bigint)) AND ((submission_forms_generation >= 1) AND (submission_forms_generation <= '9007199254740991'::bigint))))),
    CONSTRAINT schema_jobs_time_check CHECK (((created_at <= updated_at) AND (created_at <= available_at) AND ((last_lease_expired_at IS NULL) OR (last_lease_expired_at <= updated_at)) AND ((finished_at IS NULL) OR (updated_at <= finished_at))))
);


