-- Name: tenant_migration_checkpoints; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.tenant_migration_checkpoints (
    tenant_id uuid NOT NULL,
    owner text NOT NULL,
    logical_version bigint NOT NULL,
    database_origin text NOT NULL,
    selected_path text NOT NULL,
    selected_sha256 text NOT NULL,
    run_id uuid NOT NULL,
    state text NOT NULL,
    attempt integer NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    error_code text,
    updated_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    CONSTRAINT tenant_migration_checkpoints_attempt_check CHECK ((attempt > 0)),
    CONSTRAINT tenant_migration_checkpoints_check CHECK ((((state = 'pending'::text) AND (started_at IS NULL) AND (finished_at IS NULL) AND (error_code IS NULL)) OR ((state = 'running'::text) AND (started_at IS NOT NULL) AND (finished_at IS NULL) AND (error_code IS NULL)) OR ((state = 'succeeded'::text) AND (started_at IS NOT NULL) AND (finished_at IS NOT NULL) AND (error_code IS NULL)) OR ((state = ANY (ARRAY['failed'::text, 'fenced'::text])) AND (finished_at IS NOT NULL) AND (error_code IS NOT NULL)))),
    CONSTRAINT tenant_migration_checkpoints_database_origin_check CHECK ((database_origin = ANY (ARRAY['fresh'::text, 'v1_adopted'::text]))),
    CONSTRAINT tenant_migration_checkpoints_error_code_check CHECK ((error_code ~ '^[a-z][a-z0-9_]{2,63}$'::text)),
    CONSTRAINT tenant_migration_checkpoints_logical_version_check CHECK (((logical_version >= '20000101000000'::bigint) AND (logical_version <= '99991231235959'::bigint))),
    CONSTRAINT tenant_migration_checkpoints_owner_check CHECK ((owner ~ '^[a-z][a-z0-9_-]{0,63}$'::text)),
    CONSTRAINT tenant_migration_checkpoints_selected_path_check CHECK ((selected_path ~ '^[a-z0-9][a-z0-9_./-]*\.sql$'::text)),
    CONSTRAINT tenant_migration_checkpoints_selected_path_check1 CHECK (((POSITION(('..'::text) IN (selected_path)) = 0) AND (POSITION(('//'::text) IN (selected_path)) = 0))),
    CONSTRAINT tenant_migration_checkpoints_selected_sha256_check CHECK ((selected_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tenant_migration_checkpoints_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'fenced'::text])))
);


ALTER TABLE platform.tenant_migration_checkpoints OWNER TO harpy_owner;

--
-- Name: tenant_migration_requirement_catalogs; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.tenant_migration_requirement_catalogs (
    migration_run_id uuid NOT NULL,
    contract_version text NOT NULL,
    release_id uuid NOT NULL,
    environment_id uuid NOT NULL,
    database_origin text NOT NULL,
    migration_manifest_sha256 text CONSTRAINT tenant_migration_requirement_migration_manifest_sha256_not_null NOT NULL,
    catalog_sha256 text NOT NULL,
    requirement_count integer CONSTRAINT tenant_migration_requirement_catalog_requirement_count_not_null NOT NULL,
    target_count integer NOT NULL,
    canonical_document bytea CONSTRAINT tenant_migration_requirement_catalo_canonical_document_not_null NOT NULL,
    recorded_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    CONSTRAINT tenant_migration_requirement_ca_migration_manifest_sha256_check CHECK ((migration_manifest_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tenant_migration_requirement_catalogs_canonical_document_check CHECK (((octet_length(canonical_document) >= 2) AND (octet_length(canonical_document) <= 16777216))),
    CONSTRAINT tenant_migration_requirement_catalogs_catalog_sha256_check CHECK ((catalog_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tenant_migration_requirement_catalogs_contract_version_check CHECK ((contract_version = 'tenant-migration-requirement-catalog.v2'::text)),
    CONSTRAINT tenant_migration_requirement_catalogs_database_origin_check CHECK ((database_origin = ANY (ARRAY['fresh'::text, 'v1_adopted'::text]))),
    CONSTRAINT tenant_migration_requirement_catalogs_requirement_count_check CHECK (((requirement_count >= 1) AND (requirement_count <= 10000))),
    CONSTRAINT tenant_migration_requirement_catalogs_target_count_check CHECK (((target_count >= 0) AND (target_count <= 10000))),
    CONSTRAINT tenant_requirement_catalogs_document_digest_check CHECK ((catalog_sha256 = encode(sha256(canonical_document), 'hex'::text)))
);


ALTER TABLE platform.tenant_migration_requirement_catalogs OWNER TO harpy_owner;

