    CONSTRAINT tenant_migration_requirements_logical_version_check CHECK (((logical_version >= '20000101000000'::bigint) AND (logical_version <= '99991231235959'::bigint))),
    CONSTRAINT tenant_migration_requirements_ordinal_check CHECK (((ordinal >= 1) AND (ordinal <= 10000))),
    CONSTRAINT tenant_migration_requirements_owner_check CHECK ((owner ~ '^[a-z][a-z0-9_]{0,63}$'::text)),
    CONSTRAINT tenant_migration_requirements_selected_path_check CHECK (((selected_path ~ '^[a-z0-9][a-z0-9_./-]*\.sql$'::text) AND (octet_length(selected_path) <= 512))),
    CONSTRAINT tenant_migration_requirements_selected_path_check1 CHECK (((POSITION(('..'::text) IN (selected_path)) = 0) AND (POSITION(('//'::text) IN (selected_path)) = 0))),
    CONSTRAINT tenant_migration_requirements_selected_sha256_check CHECK ((selected_sha256 ~ '^[0-9a-f]{64}$'::text))
);


