--
-- Name: tenant_migration_supersessions; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.tenant_migration_supersessions (
    owner text NOT NULL,
    scope text NOT NULL,
    logical_version bigint NOT NULL,
    database_origin text NOT NULL,
    superseded_path text NOT NULL,
    superseded_sha256 text NOT NULL,
    current_path text NOT NULL,
    current_sha256 text NOT NULL,
    registered_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    supersession_distance smallint DEFAULT 1 NOT NULL,
    CONSTRAINT tenant_migration_supersessions_current_sha256_check CHECK ((current_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tenant_migration_supersessions_database_origin_check CHECK ((database_origin = ANY (ARRAY['fresh'::text, 'v1_adopted'::text]))),
    CONSTRAINT tenant_migration_supersessions_distance_check CHECK (((supersession_distance = ANY (ARRAY[1, 2, 3])) AND (POSITION(((('/'::text || database_origin) || '/'::text)) IN (superseded_path)) > 0) AND (POSITION(((('/'::text || database_origin) || '/'::text)) IN (current_path)) > 0) AND (((supersession_distance = 1) AND (((POSITION(('/supersessions/'::text) IN (superseded_path)) = 0) AND (POSITION(((('/supersessions/'::text || database_origin) || '/'::text)) IN (current_path)) > 0) AND (POSITION(('/supersessions/v2/'::text) IN (current_path)) = 0) AND (POSITION(('/supersessions/v3/'::text) IN (current_path)) = 0)) OR ((POSITION(((('/supersessions/'::text || database_origin) || '/'::text)) IN (superseded_path)) > 0) AND (POSITION(('/supersessions/v2/'::text) IN (superseded_path)) = 0) AND (POSITION(('/supersessions/v3/'::text) IN (superseded_path)) = 0) AND (POSITION(('/supersessions/v2/'::text) IN (current_path)) > 0)) OR ((POSITION(('/supersessions/v2/'::text) IN (superseded_path)) > 0) AND (POSITION(('/supersessions/v3/'::text) IN (current_path)) > 0)))) OR ((supersession_distance = 2) AND (((POSITION(('/supersessions/'::text) IN (superseded_path)) = 0) AND (POSITION(('/supersessions/v2/'::text) IN (current_path)) > 0)) OR ((POSITION(((('/supersessions/'::text || database_origin) || '/'::text)) IN (superseded_path)) > 0) AND (POSITION(('/supersessions/v2/'::text) IN (superseded_path)) = 0) AND (POSITION(('/supersessions/v3/'::text) IN (current_path)) > 0)))) OR ((supersession_distance = 3) AND (POSITION(('/supersessions/'::text) IN (superseded_path)) = 0) AND (POSITION(('/supersessions/v3/'::text) IN (current_path)) > 0))))),
    CONSTRAINT tenant_migration_supersessions_logical_version_check CHECK (((logical_version >= '20000101000000'::bigint) AND (logical_version <= '99991231235959'::bigint))),
    CONSTRAINT tenant_migration_supersessions_owner_check CHECK ((owner ~ '^[a-z][a-z0-9_-]{0,63}$'::text)),
    CONSTRAINT tenant_migration_supersessions_paths_check CHECK (((superseded_path ~ '^[a-z0-9][a-z0-9_./-]*\.sql$'::text) AND (current_path ~ '^[a-z0-9][a-z0-9_./-]*\.sql$'::text) AND (POSITION(('..'::text) IN (superseded_path)) = 0) AND (POSITION(('//'::text) IN (superseded_path)) = 0) AND (POSITION(('..'::text) IN (current_path)) = 0) AND (POSITION(('//'::text) IN (current_path)) = 0) AND (superseded_path <> current_path) AND (superseded_sha256 <> current_sha256))),
    CONSTRAINT tenant_migration_supersessions_scope_check CHECK ((scope = 'tenant'::text)),
    CONSTRAINT tenant_migration_supersessions_superseded_sha256_check CHECK ((superseded_sha256 ~ '^[0-9a-f]{64}$'::text))
);


ALTER TABLE platform.tenant_migration_supersessions OWNER TO harpy_owner;

