CREATE TABLE platform.usage_adoption_page_receipts (
    run_id uuid NOT NULL,
    page_number bigint NOT NULL,
    cursor_before uuid,
    cursor_after uuid NOT NULL,
    row_count integer NOT NULL,
    source_page_sha256 bytea NOT NULL,
    target_page_sha256 bytea NOT NULL,
    state text NOT NULL,
    applied_at timestamp(6) with time zone NOT NULL,
    advanced_at timestamp(6) with time zone,
    CONSTRAINT usage_adoption_page_receipts_check CHECK ((((state = 'applied'::text) AND (advanced_at IS NULL)) OR ((state = 'advanced'::text) AND (advanced_at IS NOT NULL)))),
    CONSTRAINT usage_adoption_page_receipts_page_number_check CHECK ((page_number > 0)),
    CONSTRAINT usage_adoption_page_receipts_row_count_check CHECK (((row_count >= 1) AND (row_count <= 100))),
    CONSTRAINT usage_adoption_page_receipts_source_page_sha256_check CHECK ((octet_length(source_page_sha256) = 32)),
    CONSTRAINT usage_adoption_page_receipts_state_check CHECK ((state = ANY (ARRAY['applied'::text, 'advanced'::text]))),
    CONSTRAINT usage_adoption_page_receipts_target_page_sha256_check CHECK ((octet_length(target_page_sha256) = 32))
);


ALTER TABLE platform.usage_adoption_page_receipts OWNER TO harpy_owner;

--
-- Name: usage_adoption_runs; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.usage_adoption_runs (
    run_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    source_kind text NOT NULL,
    source_schema text NOT NULL,
    source_relation text NOT NULL,
    source_relation_oid oid NOT NULL,
    source_count bigint NOT NULL,
    source_root_sha256 bytea NOT NULL,
    snapshot_id text NOT NULL,
    transform_sha256 bytea NOT NULL,
    next_page bigint DEFAULT 1 NOT NULL,
    cursor_id uuid,
    copied_count bigint DEFAULT 0 NOT NULL,
    status text NOT NULL,
    lease_owner uuid,
    lease_generation bigint DEFAULT 0 NOT NULL,
    lease_expires_at timestamp(6) with time zone,
    revision bigint DEFAULT 1 NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    completed_at timestamp(6) with time zone,
    CONSTRAINT usage_adoption_runs_check CHECK ((((source_kind = 'zero'::text) AND (source_relation_oid = (0)::oid) AND (source_count = 0)) OR ((source_kind = 'legacy_trace_logs'::text) AND ((source_relation_oid)::bigint > 0)))),
    CONSTRAINT usage_adoption_runs_check1 CHECK (((lease_owner IS NULL) = (lease_expires_at IS NULL))),
    CONSTRAINT usage_adoption_runs_check2 CHECK ((copied_count <= source_count)),
    CONSTRAINT usage_adoption_runs_check3 CHECK (((status = 'completed'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT usage_adoption_runs_copied_count_check CHECK ((copied_count >= 0)),
    CONSTRAINT usage_adoption_runs_lease_generation_check CHECK ((lease_generation >= 0)),
    CONSTRAINT usage_adoption_runs_next_page_check CHECK ((next_page > 0)),
    CONSTRAINT usage_adoption_runs_revision_check CHECK ((revision > 0)),
    CONSTRAINT usage_adoption_runs_run_id_check CHECK ((uuid_extract_version(run_id) = 7)),
    CONSTRAINT usage_adoption_runs_snapshot_id_check CHECK (((octet_length(snapshot_id) >= 16) AND (octet_length(snapshot_id) <= 200))),
    CONSTRAINT usage_adoption_runs_source_count_check CHECK ((source_count >= 0)),
    CONSTRAINT usage_adoption_runs_source_kind_check CHECK ((source_kind = ANY (ARRAY['zero'::text, 'legacy_trace_logs'::text]))),
    CONSTRAINT usage_adoption_runs_source_relation_check CHECK ((source_relation ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT usage_adoption_runs_source_root_sha256_check CHECK ((octet_length(source_root_sha256) = 32)),
    CONSTRAINT usage_adoption_runs_source_schema_check CHECK ((source_schema ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT usage_adoption_runs_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'applying'::text, 'reconciling'::text, 'completed'::text, 'fenced'::text]))),
    CONSTRAINT usage_adoption_runs_transform_sha256_check CHECK ((octet_length(transform_sha256) = 32))
);


ALTER TABLE platform.usage_adoption_runs OWNER TO harpy_owner;

