    CONSTRAINT usage_legal_holds_check1 CHECK (((released_at IS NULL) OR (released_at >= starts_at))),
    CONSTRAINT usage_legal_holds_hold_id_check CHECK ((uuid_extract_version(hold_id) = 7)),
    CONSTRAINT usage_legal_holds_reason_code_check CHECK ((reason_code ~ '^[a-z][a-z0-9_.-]{0,63}$'::text))
);


