--
-- Name: usage_request_facts; Type: TABLE; Schema: platform; Owner: harpy_owner
--

CREATE TABLE platform.usage_request_facts (
    fact_id uuid NOT NULL,
    environment_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    source_identity bytea NOT NULL,
    fact_digest bytea NOT NULL,
    method text NOT NULL,
    route_pattern text NOT NULL,
    status_code integer NOT NULL,
    duration_micros bigint NOT NULL,
    occurred_at timestamp(6) with time zone NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    CONSTRAINT usage_request_facts_duration_micros_check CHECK (((duration_micros >= 0) AND (duration_micros <= '86400000000'::bigint))),
    CONSTRAINT usage_request_facts_fact_digest_check CHECK ((octet_length(fact_digest) = 32)),
    CONSTRAINT usage_request_facts_fact_id_check CHECK ((uuid_extract_version(fact_id) = 7)),
    CONSTRAINT usage_request_facts_method_check CHECK ((method = ANY (ARRAY['GET'::text, 'HEAD'::text, 'POST'::text, 'PUT'::text, 'PATCH'::text, 'DELETE'::text, 'OPTIONS'::text]))),
    CONSTRAINT usage_request_facts_route_pattern_check CHECK ((((octet_length(route_pattern) >= 1) AND (octet_length(route_pattern) <= 256)) AND ("left"(route_pattern, 1) = '/'::text) AND (strpos(route_pattern, '?'::text) = 0) AND (strpos(route_pattern, '#'::text) = 0) AND (route_pattern !~ '[
]'::text))),
    CONSTRAINT usage_request_facts_source_identity_check CHECK ((octet_length(source_identity) = 32)),
    CONSTRAINT usage_request_facts_status_code_check CHECK (((status_code >= 100) AND (status_code <= 599)))
);


ALTER TABLE platform.usage_request_facts OWNER TO harpy_owner;

